    public static function activate() {
        self::create_page_if_missing('Login', '[cmn_login]');
        self::create_page_if_missing('Portal', '[cmn_portal]');
        self::create_page_if_missing('CoverMeNow ONE', '[cmn_portal]');
        self::create_page_if_missing('School Registration', '[cmn_register_school]');
        self::create_page_if_missing('Candidate Registration', '[cmn_register_candidate]');
        self::create_page_if_missing('Request Received', '[cmn_request_received]');
        self::create_page_if_missing('CoverMeNow ONE for Schools', '[cmn_school_landing]');
        self::create_page_if_missing('CoverMeNow ONE for Candidates', '[cmn_candidate_landing]');
        self::create_page_if_missing('School Dashboard', '[cmn_school_dashboard]');
        self::create_page_if_missing('Candidate Dashboard', '[cmn_candidate_dashboard]');
        self::create_page_if_missing('Available Tomorrow', '[cmn_available_wall]');
        self::run_schema_migrations((int) get_option('cmn_schema_version', 0));
        if (!wp_next_scheduled(self::MONTHLY_INVOICE_CRON_HOOK)) {
            $tz = wp_timezone();
            $reference = new DateTimeImmutable('now', $tz);
            $candidate = $reference->modify('first day of this month')->setTime(2, 0, 0);
            if ($reference >= $candidate) {
                $candidate = $candidate->modify('first day of next month')->setTime(2, 0, 0);
            }
            wp_schedule_single_event((int) $candidate->getTimestamp(), self::MONTHLY_INVOICE_CRON_HOOK);
        }
        if (!wp_next_scheduled(self::INVOICE_OVERDUE_REMINDER_CRON_HOOK)) {
            $tz = wp_timezone();
            $reference = new DateTimeImmutable('now', $tz);
            $candidate = $reference->setTime(8, 0, 0);
            if ($reference >= $candidate) {
                $candidate = $candidate->modify('+1 day')->setTime(8, 0, 0);
            }
            wp_schedule_single_event((int) $candidate->getTimestamp(), self::INVOICE_OVERDUE_REMINDER_CRON_HOOK);
        }
        if (!wp_next_scheduled(self::CANDIDATE_REWARDS_ANNUAL_RESET_CRON_HOOK)) {
            $tz = wp_timezone();
            $reference = new DateTimeImmutable('now', $tz);
            $candidate = $reference->setDate((int) $reference->format('Y'), 9, 1)->setTime(2, 0, 0);
            if ($reference >= $candidate) {
                $candidate = $candidate->modify('+1 year')->setDate((int) $candidate->format('Y'), 9, 1)->setTime(2, 0, 0);
            }
            wp_schedule_single_event((int) $candidate->getTimestamp(), self::CANDIDATE_REWARDS_ANNUAL_RESET_CRON_HOOK);
        }
        if (!wp_next_scheduled(self::CANDIDATE_REWARDS_ACADEMIC_YEAR_ROLLOVER_CRON_HOOK)) {
            $tz = wp_timezone();
            $reference = new DateTimeImmutable('now', $tz);
            $candidate = $reference->setTime(2, 0, 0);
            if ($reference >= $candidate) {
                $candidate = $candidate->modify('+1 day')->setTime(2, 0, 0);
            }
            wp_schedule_event((int) $candidate->getTimestamp(), 'daily', self::CANDIDATE_REWARDS_ACADEMIC_YEAR_ROLLOVER_CRON_HOOK);
        }
        if (!wp_next_scheduled(self::CANDIDATE_REWARDS_PAYROLL_ADDON_CRON_HOOK)) {
            $tz = wp_timezone();
            $reference = new DateTimeImmutable('now', $tz);
            $candidate = $reference->modify('next monday')->setTime(2, 30, 0);
            if ($reference->format('N') === '1' && $reference < $reference->setTime(2, 30, 0)) {
                $candidate = $reference->setTime(2, 30, 0);
            }
            wp_schedule_single_event((int) $candidate->getTimestamp(), self::CANDIDATE_REWARDS_PAYROLL_ADDON_CRON_HOOK);
        }
        if (!wp_next_scheduled(self::PAYROLL_PERIOD_AUTO_LOCK_CRON_HOOK)) {
            $tz = wp_timezone();
            $reference = new DateTimeImmutable('now', $tz);
            $candidate = $reference->modify('next thursday')->setTime(17, 0, 0);
            if ($reference->format('N') === '4' && $reference < $reference->setTime(17, 0, 0)) {
                $candidate = $reference->setTime(17, 0, 0);
            }
            wp_schedule_single_event((int) $candidate->getTimestamp(), self::PAYROLL_PERIOD_AUTO_LOCK_CRON_HOOK);
        }
        if (!wp_next_scheduled(self::SCHOOL_PARTNER_CONFIRMATION_EMAIL_CRON_HOOK)) {
            $tz = wp_timezone();
            $reference = new DateTimeImmutable('now', $tz);
            $candidate = $reference->setTime(7, 0, 0);
            if ($reference >= $candidate) {
                $candidate = $candidate->modify('+1 day')->setTime(7, 0, 0);
            }
            wp_schedule_event((int) $candidate->getTimestamp(), 'daily', self::SCHOOL_PARTNER_CONFIRMATION_EMAIL_CRON_HOOK);
        }
        if (!wp_next_scheduled(self::SCHOOL_PARTNER_CONFIRMATION_REMINDER_CRON_HOOK)) {
            $tz = wp_timezone();
            $reference = new DateTimeImmutable('now', $tz);
            $candidate = $reference->setTime(7, 30, 0);
            if ($reference >= $candidate) {
                $candidate = $candidate->modify('+1 day')->setTime(7, 30, 0);
            }
            wp_schedule_event((int) $candidate->getTimestamp(), 'daily', self::SCHOOL_PARTNER_CONFIRMATION_REMINDER_CRON_HOOK);
        }
    }

    private static function create_page_if_missing($title, $shortcode) {
        $existing = cmn_get_page_by_title($title);
        if ($existing) {
            return;
        }
        wp_insert_post([
            'post_type' => 'page',
            'post_title' => $title,
            'post_status' => 'publish',
            'post_content' => $shortcode,
        ]);
    }

    public function ensure_required_pages() {
        $portal_route_changed = $this->ensure_portal_page_route();
        $covermenow_one_route_changed = $this->ensure_covermenow_one_portal_page_route();
        $registration_routes_changed = $this->ensure_registration_pages_routes();
        self::create_page_if_missing('Login', '[cmn_login]');
        self::create_page_if_missing('School Registration', '[cmn_register_school]');
        self::create_page_if_missing('Candidate Registration', '[cmn_register_candidate]');
        self::create_page_if_missing('Request Received', '[cmn_request_received]');
        self::create_page_if_missing('CoverMeNow ONE for Schools', '[cmn_school_landing]');
        self::create_page_if_missing('CoverMeNow ONE for Candidates', '[cmn_candidate_landing]');
        if ($portal_route_changed || $covermenow_one_route_changed || $registration_routes_changed) {
            flush_rewrite_rules(false);
        }
    }

    private function ensure_registration_pages_routes() {
        $school_changed = $this->ensure_named_shortcode_page_route(
            'school-registration',
            'School Registration',
            '[cmn_register_school]',
            'cmn_register_school'
        );
        $candidate_changed = $this->ensure_named_shortcode_page_route(
            'candidate-registration',
            'Candidate Registration',
            '[cmn_register_candidate]',
            'cmn_register_candidate'
        );
        $request_received_changed = $this->ensure_named_shortcode_page_route(
            'request-received',
            'Request Received',
            '[cmn_request_received]',
            'cmn_request_received'
        );
        return $school_changed || $candidate_changed || $request_received_changed;
    }

    private function ensure_named_shortcode_page_route($slug, $title, $shortcode, $shortcode_tag) {
        $slug = sanitize_title((string) $slug);
        $title = sanitize_text_field((string) $title);
        $shortcode = (string) $shortcode;
        $shortcode_tag = sanitize_key((string) $shortcode_tag);
        if ($slug === '' || $title === '' || $shortcode === '' || $shortcode_tag === '') {
            return false;
        }

        $by_path = get_page_by_path($slug, OBJECT, 'page');
        if ($by_path instanceof WP_Post) {
            $updates = ['ID' => (int) $by_path->ID];
            $changed = false;
            if ($by_path->post_status !== 'publish') {
                $updates['post_status'] = 'publish';
                $changed = true;
            }
            if (!has_shortcode((string) $by_path->post_content, $shortcode_tag)) {
                $updates['post_content'] = $shortcode;
                $changed = true;
            }
            if ($changed) {
                wp_update_post($updates);
            }
            return $changed;
        }

        $by_title = cmn_get_page_by_title($title, OBJECT, 'page');
        if ($by_title instanceof WP_Post) {
            $updates = ['ID' => (int) $by_title->ID];
            $changed = false;
            if ($by_title->post_status !== 'publish') {
                $updates['post_status'] = 'publish';
                $changed = true;
            }
            if ($by_title->post_name !== $slug && !get_page_by_path($slug, OBJECT, 'page')) {
                $unique_slug = wp_unique_post_slug($slug, (int) $by_title->ID, (string) $by_title->post_status, 'page', (int) $by_title->post_parent);
                if ($unique_slug === $slug) {
                    $updates['post_name'] = $slug;
                    $changed = true;
                }
            }
            if (!has_shortcode((string) $by_title->post_content, $shortcode_tag)) {
                $updates['post_content'] = $shortcode;
                $changed = true;
            }
            if ($changed) {
                wp_update_post($updates);
            }
            return $changed;
        }

        $inserted = wp_insert_post([
            'post_type' => 'page',
            'post_title' => $title,
            'post_name' => $slug,
            'post_status' => 'publish',
            'post_content' => $shortcode,
        ], true);
        return !is_wp_error($inserted) && (int) $inserted > 0;
    }

