    private function find_portal_page() {
        static $cached = null;
        if ($cached !== null) {
            return $cached ?: null;
        }

        $by_path = get_page_by_path('covermenow-one', OBJECT, 'page');
        if ($by_path instanceof WP_Post) {
            $cached = $by_path;
            return $by_path;
        }

        $by_title = cmn_get_page_by_title('CoverMeNow ONE', OBJECT, 'page');
        if ($by_title instanceof WP_Post) {
            $cached = $by_title;
            return $by_title;
        }

        $by_path = get_page_by_path('portal', OBJECT, 'page');
        if ($by_path instanceof WP_Post) {
            $cached = $by_path;
            return $by_path;
        }

        $by_title = cmn_get_page_by_title('Portal', OBJECT, 'page');
        if ($by_title instanceof WP_Post) {
            $cached = $by_title;
            return $by_title;
        }

        global $wpdb;
        $like = '%' . $wpdb->esc_like('[cmn_portal') . '%';
        $page_id = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT ID
             FROM {$wpdb->posts}
             WHERE post_type = 'page'
               AND post_status NOT IN ('trash', 'auto-draft')
               AND post_content LIKE %s
             ORDER BY ID ASC
             LIMIT 1",
            $like
        ));
        if ($page_id > 0) {
            $by_shortcode = get_post($page_id);
            if ($by_shortcode instanceof WP_Post) {
                $cached = $by_shortcode;
                return $by_shortcode;
            }
        }

        $cached = false;
        return null;
    }

