    public function initialize_release_version_option() {
        $current = trim((string) get_option('cmn_release_version', ''));
        if (!$this->is_valid_release_version($current)) {
            $legacy = trim((string) get_option('cmn_portal_release_version', ''));
            if ($this->is_valid_release_version($legacy)) {
                $current = $legacy;
            } else {
                $current = '0.0.1';
            }
            update_option('cmn_release_version', $current, false);

            if ((string) get_option('cmn_release_version_standardized_notice', '') !== '1') {
                update_option('cmn_release_version_standardized_notice', '1', false);
            }
        } else {
            $normalized_current = $this->normalize_release_version_value($current);
            if ($normalized_current !== '' && $normalized_current !== $current) {
                $current = $normalized_current;
                update_option('cmn_release_version', $current, false);
            }
        }

        $synced_version = $this->maybe_sync_release_version_with_deploy($current);
        if ($synced_version !== $current) {
            update_option('cmn_release_version', $synced_version, false);
        }
    }

    private function is_valid_release_version($version) {
        return is_string($version) && (bool) preg_match('/^\d+\.\d+\.\d+$/', trim($version));
    }

    private function normalize_release_version_value($version) {
        if (!preg_match('/^(\d+)\.(\d+)\.(\d+)$/', trim((string) $version), $matches)) {
            return '';
        }
        $major = (int) $matches[1];
        $minor = (int) $matches[2];
        $patch = (int) $matches[3];

        if ($patch >= 100) {
            $minor += intdiv($patch, 100);
            $patch = $patch % 100;
        }
        if ($minor >= 100) {
            $major += intdiv($minor, 100);
            $minor = $minor % 100;
        }

        return $major . '.' . $minor . '.' . $patch;
    }

    private function increment_release_patch_version($version) {
        $normalized = $this->normalize_release_version_value($version);
        if ($normalized === '' || !preg_match('/^(\d+)\.(\d+)\.(\d+)$/', $normalized, $matches)) {
            return '0.0.1';
        }
        $major = (int) $matches[1];
        $minor = (int) $matches[2];
        $patch = (int) $matches[3] + 1;
        if ($patch >= 100) {
            $minor += intdiv($patch, 100);
            $patch = $patch % 100;
        }
        if ($minor >= 100) {
            $major += intdiv($minor, 100);
            $minor = $minor % 100;
        }
        return $major . '.' . $minor . '.' . $patch;
    }

    private function build_release_signature() {
        $parts = ['plugin=' . self::VERSION];
        $this->append_release_signature_parts(__DIR__, $parts);
        return sha1(implode('|', $parts));
    }

    private function append_release_signature_parts($path, &$parts) {
        $path = (string) $path;
        $parts[] = $path . ':exists=' . (file_exists($path) ? '1' : '0');
        if (!file_exists($path)) {
            return;
        }
        if (is_file($path)) {
            $parts[] = $path . ':m=' . (int) @filemtime($path) . ':s=' . (int) @filesize($path);
            return;
        }
        if (!is_dir($path)) {
            return;
        }

        $parts[] = $path . ':dir_m=' . (int) @filemtime($path);
        $entries = @scandir($path);
        if (!is_array($entries)) {
            return;
        }
        sort($entries, SORT_STRING);
        foreach ($entries as $entry) {
            if ($entry === '.' || $entry === '..') {
                continue;
            }
            if ($entry === '.git') {
                continue;
            }
            $this->append_release_signature_parts($path . '/' . $entry, $parts);
        }
    }

    private function maybe_sync_release_version_with_deploy($current_version) {
        $current_signature = $this->build_release_signature();
        $saved_signature = trim((string) get_option('cmn_release_signature', ''));
        if ($saved_signature === '') {
            update_option('cmn_release_signature', $current_signature, false);
            return $current_version;
        }
        if ($saved_signature === $current_signature) {
            return $current_version;
        }

        update_option('cmn_release_signature', $current_signature, false);

        if ($this->is_valid_release_version($current_version)) {
            return $this->increment_release_patch_version($current_version);
        }
        $legacy_version = trim((string) get_option('cmn_portal_release_version', ''));
        if ($this->is_valid_release_version($legacy_version)) {
            return $this->increment_release_patch_version($legacy_version);
        }
        return '0.0.1';
    }

    public function get_release_version() {
        $this->initialize_release_version_option();
        $version = trim((string) get_option('cmn_release_version', ''));
        if (!$this->is_valid_release_version($version)) {
            $version = '0.0.1';
            update_option('cmn_release_version', $version, false);
        } else {
            $normalized = $this->normalize_release_version_value($version);
            if ($normalized !== '' && $normalized !== $version) {
                $version = $normalized;
                update_option('cmn_release_version', $version, false);
            }
        }
        return $version;
    }

    public function set_release_version($v) {
        if (!is_user_logged_in() || !$this->is_admin_user()) {
            return;
        }
        $v = trim((string) $v);
        if (!$this->is_valid_release_version($v)) {
            return;
        }
        $normalized = $this->normalize_release_version_value($v);
        if ($normalized === '') {
            return;
        }
        update_option('cmn_release_version', $normalized, false);
    }

    public function render_release_version_standardized_admin_notice() {
        if (!is_admin() || !is_user_logged_in() || !$this->is_admin_user()) {
            return;
        }
        if ((string) get_option('cmn_release_version_standardized_notice', '') !== '1') {
            return;
        }
        echo '<div class="notice notice-success is-dismissible"><p>Portal version source standardized to Release Version.</p></div>';
        update_option('cmn_release_version_standardized_notice', '0', false);
    }

    private function render_portal_branding() {
        $version = $this->get_release_version();
        ob_start();
        ?>
        <div class="cmn-brand-block">
            <div class="cmn-brand-title">CoverMeNow <span class="cmn-topbar-accent">ONE</span></div>
            <div class="cmn-brand-version">V<?php echo esc_html($version); ?></div>
        </div>
        <?php
        return ob_get_clean();
    }

    public function migrate_candidate_statuses_to_approved() {
        if (get_option('cmn_candidate_status_migrated_v1') === '1') {
            return;
        }
        $candidate_ids = get_posts([
            'post_type' => 'cmn_candidate',
            'posts_per_page' => -1,
            'fields' => 'ids',
        ]);
        foreach ((array) $candidate_ids as $candidate_id) {
            $current = strtolower((string) get_post_meta((int) $candidate_id, 'cmn_status', true));
            if ($current === '' || $current === 'pending') {
                update_post_meta((int) $candidate_id, 'cmn_status', 'approved');
            }
            $user_id = (int) get_post_meta((int) $candidate_id, 'cmn_user_id', true);
            if ($user_id) {
                $user = get_user_by('id', $user_id);
                if ($user) {
                    $roles = (array) $user->roles;
                    if (in_array('cmn_candidate_pending', $roles, true) || !in_array('cmn_candidate', $roles, true)) {
                        $user_obj = new WP_User($user_id);
                        $user_obj->set_role('cmn_candidate');
                    }
                }
            }
        }
        update_option('cmn_candidate_status_migrated_v1', '1', false);
    }

    public function migrate_registration_profile_meta_backfill() {
        if ((string) get_option('cmn_profile_meta_backfill_v1', '') === '1') {
            return;
        }
        $candidate_ids = get_posts([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish', 'pending', 'draft', 'private'],
            'fields' => 'ids',
            'posts_per_page' => 1200,
        ]);
        foreach ((array) $candidate_ids as $candidate_id) {
            $candidate_id = (int) $candidate_id;
            if ($candidate_id < 1) {
                continue;
            }
            $driving = trim((string) get_post_meta($candidate_id, 'cmn_driving_licence', true));
            $car_owner = trim((string) get_post_meta($candidate_id, 'cmn_car_owner', true));
            if ($driving === '') {
                $legacy = $this->normalize_yes_no_value((string) get_post_meta($candidate_id, 'cmn_drives', true));
                if ($legacy !== '') {
                    update_post_meta($candidate_id, 'cmn_driving_licence', $legacy);
                }
            }
            if ($car_owner === '') {
                $legacy = $this->normalize_yes_no_value((string) get_post_meta($candidate_id, 'cmn_has_car', true));
                if ($legacy !== '') {
                    update_post_meta($candidate_id, 'cmn_car_owner', $legacy);
                }
            }
        }
        update_option('cmn_profile_meta_backfill_v1', '1', false);
    }

    public function maybe_backfill_candidate_referral_codes() {
        if ((string) get_option('cmn_referral_codes_backfilled_v1', '') === '1') {
            return;
        }
        $users = get_users([
            'fields' => ['ID'],
            'number' => 10000,
            'role__in' => ['cmn_candidate', 'cmn_candidate_pending', 'candidate'],
        ]);
        foreach ((array) $users as $user_row) {
            $user_id = (int) (is_object($user_row) ? ($user_row->ID ?? 0) : (is_array($user_row) ? ($user_row['ID'] ?? 0) : 0));
            if ($user_id > 0) {
                $this->ensure_candidate_referral_code($user_id);
            }
        }
        update_option('cmn_referral_codes_backfilled_v1', '1', false);
    }

