    private static function get_wp_database_name() {
        global $wpdb;
        if (isset($wpdb->dbname) && is_string($wpdb->dbname) && $wpdb->dbname !== '') {
            return $wpdb->dbname;
        }
        return defined('DB_NAME') ? (string) DB_NAME : '';
    }

    private static function quote_sql_identifier($identifier) {
        return '`' . str_replace('`', '``', (string) $identifier) . '`';
    }

    private static function maybe_add_missing_column($table_name, $column_name, $column_ddl) {
        global $wpdb;
        $db_name = self::get_wp_database_name();
        if ($db_name === '' || !is_string($table_name) || $table_name === '' || !is_string($column_name) || $column_name === '') {
            return;
        }
        $exists = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM INFORMATION_SCHEMA.COLUMNS
             WHERE TABLE_SCHEMA = %s
               AND TABLE_NAME = %s
               AND COLUMN_NAME = %s",
            $db_name,
            $table_name,
            $column_name
        ));
        if ($exists > 0) {
            return;
        }
        $table_sql = self::quote_sql_identifier($table_name);
        $column_sql = self::quote_sql_identifier($column_name);
        $wpdb->query("ALTER TABLE {$table_sql} ADD COLUMN {$column_sql} {$column_ddl}");
    }

    private static function maybe_add_missing_index($table_name, $index_name, $index_ddl) {
        global $wpdb;
        $db_name = self::get_wp_database_name();
        if ($db_name === '' || !is_string($table_name) || $table_name === '' || !is_string($index_name) || $index_name === '') {
            return;
        }
        $exists = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM INFORMATION_SCHEMA.STATISTICS
             WHERE TABLE_SCHEMA = %s
               AND TABLE_NAME = %s
               AND INDEX_NAME = %s",
            $db_name,
            $table_name,
            $index_name
        ));
        if ($exists > 0) {
            return;
        }
        $table_sql = self::quote_sql_identifier($table_name);
        $wpdb->query("ALTER TABLE {$table_sql} ADD {$index_ddl}");
    }

    private static function ensure_pay_approvals_training_unique_index($table_name) {
        global $wpdb;
        $db_name = self::get_wp_database_name();
        if ($db_name === '' || !is_string($table_name) || $table_name === '') {
            return;
        }
        if (!self::table_has_column($table_name, 'is_training')) {
            return;
        }

        $index_name = 'candidate_booking_day_date';
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT COLUMN_NAME
             FROM INFORMATION_SCHEMA.STATISTICS
             WHERE TABLE_SCHEMA = %s
               AND TABLE_NAME = %s
               AND INDEX_NAME = %s
             ORDER BY SEQ_IN_INDEX ASC",
            $db_name,
            $table_name,
            $index_name
        ), ARRAY_A);

        $expected_columns = ['candidate_user_id', 'booking_id', 'booking_day_date', 'is_training'];
        $current_columns = [];
        foreach ((array) $rows as $row) {
            $column = sanitize_key((string) ($row['COLUMN_NAME'] ?? ''));
            if ($column !== '') {
                $current_columns[] = $column;
            }
        }
        if ($current_columns === $expected_columns) {
            return;
        }

        $table_sql = self::quote_sql_identifier($table_name);
        if (!empty($current_columns)) {
            $index_sql = self::quote_sql_identifier($index_name);
            $wpdb->query("ALTER TABLE {$table_sql} DROP INDEX {$index_sql}");
        }
        $wpdb->query(
            "ALTER TABLE {$table_sql} ADD UNIQUE KEY candidate_booking_day_date (candidate_user_id, booking_id, booking_day_date, is_training)"
        );
    }

    private static function table_has_column($table_name, $column_name) {
        global $wpdb;
        $db_name = self::get_wp_database_name();
        if ($db_name === '' || !is_string($table_name) || $table_name === '' || !is_string($column_name) || $column_name === '') {
            return false;
        }

        $exists = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM INFORMATION_SCHEMA.COLUMNS
             WHERE TABLE_SCHEMA = %s
               AND TABLE_NAME = %s
               AND COLUMN_NAME = %s",
            $db_name,
            $table_name,
            $column_name
        ));
        return $exists > 0;
    }

    private static function maybe_drop_column($table_name, $column_name) {
        global $wpdb;
        if (!self::table_has_column($table_name, $column_name)) {
            return;
        }

        $table_sql = self::quote_sql_identifier($table_name);
        $column_sql = self::quote_sql_identifier($column_name);
        $wpdb->query("ALTER TABLE {$table_sql} DROP COLUMN {$column_sql}");
    }

    private static function build_academic_year_label_from_start_year($start_year) {
        $start_year = (int) $start_year;
        $end_short = ($start_year + 1) % 100;
        return sprintf('%04d/%02d', $start_year, $end_short);
    }

    private static function parse_academic_year_start_year_from_label($academic_year_label) {
        $academic_year_label = trim((string) $academic_year_label);
        if (!preg_match('/^(\d{4})\/(\d{2})$/', $academic_year_label, $matches)) {
            return 0;
        }
        return (int) $matches[1];
    }

    private static function get_academic_year_bounds_for_datetime(DateTimeInterface $reference_date) {
        $month = (int) $reference_date->format('n');
        $year = (int) $reference_date->format('Y');

        // Sep -> Jul cycle. August is treated as off-season for the previous academic year.
        if ($month >= 9) {
            $start_year = $year;
        } else {
            $start_year = $year - 1;
        }
        if ($month === 8) {
            $start_year = $year - 1;
        }

        $end_year = $start_year + 1;

        return [
            'start_year' => $start_year,
            'end_year' => $end_year,
            'starts_on' => sprintf('%04d-09-01', $start_year),
            'ends_on' => sprintf('%04d-07-31', $end_year),
            'is_off_season' => $month === 8,
        ];
    }

    private static function ensure_rewards_config_year_row($academic_year_label) {
        global $wpdb;
        $table = self::get_rewards_config_years_table_name();
        $start_year = self::parse_academic_year_start_year_from_label($academic_year_label);
        if ($start_year < 2000) {
            return [];
        }
        $normalized_label = self::build_academic_year_label_from_start_year($start_year);
        $existing = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE academic_year_label = %s LIMIT 1",
            $normalized_label
        ), ARRAY_A);
        if (is_array($existing) && !empty($existing)) {
            $existing['__cmn_created'] = false;
            return $existing;
        }

        $now = current_time('mysql');
        $inserted = $wpdb->insert($table, [
            'academic_year_label' => $normalized_label,
            'starts_on' => sprintf('%04d-09-01', $start_year),
            'ends_on' => sprintf('%04d-07-31', ($start_year + 1)),
            'bronze_threshold' => 30,
            'silver_threshold' => 60,
            'gold_threshold' => 90,
            'elite_threshold' => 120,
            'bronze_multiplier' => 1.10,
            'silver_multiplier' => 1.20,
            'gold_multiplier' => 1.30,
            'elite_multiplier' => 1.50,
            'elite_recurring_block' => 30,
            'elite_recurring_multiplier' => 1.50,
            'created_at' => $now,
            'updated_at' => $now,
        ], [
            '%s',
            '%s',
            '%s',
            '%d',
            '%d',
            '%d',
            '%d',
            '%f',
            '%f',
            '%f',
            '%f',
            '%d',
            '%f',
            '%s',
            '%s',
        ]);
        $created = ($inserted !== false);

        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE academic_year_label = %s LIMIT 1",
            $normalized_label
        ), ARRAY_A);
        if (!is_array($row)) {
            return [];
        }
        $row['__cmn_created'] = $created;
        return $row;
    }

    private static function seed_rewards_config_year_defaults() {
        $timezone = function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC');
        $now = new DateTimeImmutable('now', $timezone);
        $bounds = self::get_academic_year_bounds_for_datetime($now);
        $labels_to_ensure = [
            self::build_academic_year_label_from_start_year((int) ($bounds['start_year'] ?? ((int) $now->format('Y') - 1))) => true,
        ];

        if (!empty($bounds['is_off_season'])) {
            $labels_to_ensure[self::build_academic_year_label_from_start_year((int) $now->format('Y'))] = true;
        }

        foreach (array_keys($labels_to_ensure) as $academic_year_label) {
            self::ensure_rewards_config_year_row($academic_year_label);
        }
    }

    private static function detect_wpdb_format($value) {
        if (is_int($value) || is_bool($value)) {
            return '%d';
        }
        if (is_float($value)) {
            return '%f';
        }
        return '%s';
    }

    private static function seed_singleton_config_defaults($table_name, $defaults) {
        global $wpdb;
        $defaults = is_array($defaults) ? $defaults : [];
        if (!is_string($table_name) || $table_name === '') {
            return [];
        }

        $ids = $wpdb->get_col("SELECT id FROM {$table_name} ORDER BY id ASC");
        $now = current_time('mysql');
        if (!is_array($ids) || count($ids) < 1) {
            $insert_data = $defaults;
            $insert_data['created_at'] = $now;
            $insert_data['updated_at'] = $now;
            $insert_format = [];
            foreach ($insert_data as $value) {
                $insert_format[] = self::detect_wpdb_format($value);
            }
            $wpdb->insert($table_name, $insert_data, $insert_format);
        } else {
            $keep_id = (int) $ids[0];
            if (count($ids) > 1) {
                $delete_ids = array_map('intval', array_slice($ids, 1));
                if (!empty($delete_ids)) {
                    $wpdb->query("DELETE FROM {$table_name} WHERE id IN (" . implode(',', $delete_ids) . ")");
                }
            }
            $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table_name} WHERE id = %d LIMIT 1", $keep_id), ARRAY_A);
            $update_data = [];
            if (is_array($row)) {
                foreach ($defaults as $key => $value) {
                    if (!array_key_exists($key, $row) || $row[$key] === null || $row[$key] === '') {
                        $update_data[$key] = $value;
                    }
                }
            } else {
                $update_data = $defaults;
            }
            $update_data['updated_at'] = $now;
            if (!empty($update_data)) {
                $update_format = [];
                foreach ($update_data as $value) {
                    $update_format[] = self::detect_wpdb_format($value);
                }
                $wpdb->update($table_name, $update_data, ['id' => $keep_id], $update_format, ['%d']);
            }
        }

        $final_row = $wpdb->get_row("SELECT * FROM {$table_name} ORDER BY id ASC LIMIT 1", ARRAY_A);
        return is_array($final_row) ? $final_row : [];
    }

    private static function seed_default_rate_rule_if_missing() {
        global $wpdb;
        $table = $wpdb->prefix . 'cmn_rate_rules';
        $existing = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE status = 'active'");
        if ($existing > 0) {
            return;
        }
        $wpdb->insert($table, [
            'role_key' => 'default',
            'region_key' => 'default',
            'min_margin_amount' => 25.00,
            'min_margin_percent' => 20.00,
            'min_school_rate' => 120.00,
            'max_school_rate' => 450.00,
            'min_candidate_pay' => 95.00,
            'max_candidate_pay' => 380.00,
            'effective_from' => current_time('mysql'),
            'status' => 'active',
            'created_by' => 0,
            'created_at' => current_time('mysql'),
        ], ['%s', '%s', '%f', '%f', '%f', '%f', '%f', '%f', '%s', '%s', '%d', '%s']);
    }

    private static function migrate_school_index() {
        global $wpdb;
        $school_index = $wpdb->prefix . 'cmn_school_index';
        $schools = get_posts([
            'post_type' => 'cmn_school',
            'posts_per_page' => -1,
            'fields' => 'ids',
        ]);
        if (!$schools) {
            return;
        }
        foreach ($schools as $post_id) {
            $school_id = get_post_meta($post_id, 'cmn_school_id', true);
            if (!$school_id) {
                $school_id = self::generate_school_id_static();
                update_post_meta($post_id, 'cmn_school_id', $school_id);
            }
            $name = get_the_title($post_id);
            $email = get_post_meta($post_id, 'cmn_email', true);
            $domain = '';
            if ($email) {
                $parts = explode('@', strtolower(trim($email)));
                $domain = strtolower(trim(end($parts)));
                if ($domain) {
                    update_post_meta($post_id, 'cmn_school_email_domain', $domain);
                }
            }
            $wpdb->replace($school_index, [
                'school_id' => strtoupper(trim($school_id)),
                'post_id' => (int) $post_id,
                'name' => $name,
                'school_email' => $email,
                'school_email_domain' => $domain ?: null,
                'updated_at' => current_time('mysql'),
            ], ['%s', '%d', '%s', '%s', '%s', '%s']);
        }
    }

    private static function migrate_contact_links() {
        global $wpdb;
        $contact_school = $wpdb->prefix . 'cmn_contact_school';
        $contacts = get_posts([
            'post_type' => 'cmn_contact',
            'posts_per_page' => -1,
            'fields' => 'ids',
        ]);
        if (!$contacts) {
            return;
        }
        foreach ($contacts as $contact_id) {
            $legacy_school_post = (int) get_post_meta($contact_id, 'cmn_contact_school_id', true);
            if (!$legacy_school_post) {
                continue;
            }
            $school_code = get_post_meta($legacy_school_post, 'cmn_school_id', true);
            $school_domain = get_post_meta($legacy_school_post, 'cmn_school_email_domain', true);
            if (!$school_code) {
                continue;
            }
            $wpdb->replace($contact_school, [
                'school_id' => strtoupper(trim($school_code)),
                'school_email_domain' => $school_domain ?: null,
                'contact_id' => (int) $contact_id,
                'is_primary' => 1,
                'created_at' => current_time('mysql'),
            ], ['%s', '%s', '%d', '%d', '%s']);
        }
    }

    public function record_user_login($user_login, $user) {
        if (!$user instanceof WP_User) {
            return;
        }
        $now = time();
        update_user_meta($user->ID, 'cmn_last_login', $now);
        update_user_meta($user->ID, 'cmn_last_seen', $now);
        if ($this->is_staff_user_id((int) $user->ID)) {
            if (get_user_meta((int) $user->ID, 'cmn_available_online', true) === '') {
                update_user_meta((int) $user->ID, 'cmn_available_online', '1');
            }
            if (get_user_meta((int) $user->ID, 'cmn_on_annual_leave', true) === '') {
                update_user_meta((int) $user->ID, 'cmn_on_annual_leave', '0');
            }
        }
    }

    public function filter_deprecated_function_trigger_error($trigger, $function, $replacement, $version) {
        $function = (string) $function;
        if ($function === 'get_page_by_title') {
            return false;
        }
        return $trigger;
    }

