    public function add_portal_body_class($classes) {
        $portal_view = '';
        if (isset($_GET['view'])) {
            $portal_view = sanitize_key((string) wp_unslash($_GET['view']));
        }
        $is_register_portal_view = $this->is_portal_page()
            && !is_user_logged_in()
            && in_array($portal_view, ['register-school', 'register-candidate'], true);
        $is_register_surface = $this->is_registration_page() || $is_register_portal_view;

        if ($this->is_portal_page()) {
            $classes[] = 'cmn-portal-page';
        }
        if ($this->is_portal_page() && !is_user_logged_in()) {
            $view = isset($_GET['view']) ? sanitize_text_field((string) wp_unslash($_GET['view'])) : '';
            if (in_array($view, ['forgot-password', 'reset-password', 'set-password', 'candidate-verify'], true)) {
                $classes[] = 'cmn-portal-auth';
                $classes[] = 'cmn-portal-bg';
            }
        }
        if ($is_register_surface) {
            $classes[] = 'cmn-portal-bg';
            $classes[] = 'cmn-register-view';
        }
        if ($this->is_login_page() || ($this->is_portal_page() && !is_user_logged_in()) || $is_register_surface) {
            $classes[] = 'cmn-portal-scroll';
        }
        if ($this->is_portal_page() && is_user_logged_in()) {
            $classes[] = 'cmn-theme-' . $this->get_user_theme_scheme(get_current_user_id());
        }
        return $classes;
    }

    private function is_portal_page() {
        if (!is_singular()) {
            return false;
        }
        $post = get_post();
        if (!$post) {
            return false;
        }
        $content = $post->post_content;
        return has_shortcode($content, 'cmn_login')
            || has_shortcode($content, 'cmn_portal')
            || has_shortcode($content, 'cmn_register_school')
            || has_shortcode($content, 'cmn_register_candidate')
            || has_shortcode($content, 'cmn_school_landing')
            || has_shortcode($content, 'cmn_candidate_landing')
            || has_shortcode($content, 'cmn_school_dashboard')
            || has_shortcode($content, 'cmn_candidate_dashboard');
    }

    private function is_registration_page() {
        if (!is_singular()) {
            return false;
        }
        $post = get_post();
        if (!$post) {
            return false;
        }
        $content = $post->post_content;
        return has_shortcode($content, 'cmn_register_school')
            || has_shortcode($content, 'cmn_register_candidate');
    }

    private function is_login_page() {
        if (!is_singular()) {
            return false;
        }
        $post = get_post();
        if (!$post) {
            return false;
        }
        $content = $post->post_content;
        return has_shortcode($content, 'cmn_login');
    }

    private function can_preview_dashboards() {
        $user = wp_get_current_user();
        if (!$user || !$user->exists()) {
            return false;
        }
        $email = strtolower($user->user_email);
        return $email === 'jay.norton@covermenow.co.uk' || current_user_can('manage_options');
    }

    public function register_cron_schedules($schedules) {
        if (!isset($schedules['cmn_five_minutes'])) {
            $schedules['cmn_five_minutes'] = [
                'interval' => 300,
                'display' => 'Every 5 Minutes',
            ];
        }
        if (!isset($schedules['cmn_hourly'])) {
            $schedules['cmn_hourly'] = [
                'interval' => 3600,
                'display' => 'Every Hour',
            ];
        }
        return $schedules;
    }

    public function schedule_booking_expiry() {
        if (!wp_next_scheduled('cmn_expire_bookings')) {
            wp_schedule_event(time() + 300, 'cmn_five_minutes', 'cmn_expire_bookings');
        }
        $last_feedback_scan = (int) get_transient('cmn_feedback_scan_ts');
        $now_ts = (int) current_time('timestamp');
        if ($last_feedback_scan < 1 || ($now_ts - $last_feedback_scan) >= 300) {
            $this->maybe_request_feedback_for_past_bookings();
            set_transient('cmn_feedback_scan_ts', $now_ts, 300);
        }
        $last_support_feedback_expiry_scan = (int) get_transient('cmn_support_feedback_request_expiry_scan_ts');
        if ($last_support_feedback_expiry_scan < 1 || ($now_ts - $last_support_feedback_expiry_scan) >= 300) {
            $this->maybe_expire_support_feedback_requests();
            set_transient('cmn_support_feedback_request_expiry_scan_ts', $now_ts, 300);
        }
    }

    public function schedule_compliance_reminders() {
        if (!wp_next_scheduled('cmn_compliance_reminders')) {
            wp_schedule_event(time() + 900, 'cmn_hourly', 'cmn_compliance_reminders');
        }
    }

    public function schedule_availability_nudges() {
        if (!wp_next_scheduled('cmn_availability_nudges')) {
            wp_schedule_event(time() + 1200, 'cmn_hourly', 'cmn_availability_nudges');
        }
    }

    public function maybe_run_compliance_reminders_fallback() {
        if (wp_doing_ajax()) {
            return;
        }
        if (!$this->is_portal_page()) {
            return;
        }
        $last_run = (int) get_option('cmn_compliance_reminder_last_run_ts', 0);
        $now = time();
        if (($now - $last_run) < 3600) {
            return;
        }
        if (!defined('DISABLE_WP_CRON') || !DISABLE_WP_CRON) {
            return;
        }
        $this->run_compliance_reminders();
    }

    public function maybe_run_availability_nudges_fallback() {
        if (wp_doing_ajax()) {
            return;
        }
        if (!$this->is_portal_page()) {
            return;
        }
        if (!defined('DISABLE_WP_CRON') || !DISABLE_WP_CRON) {
            return;
        }
        $tz = wp_timezone();
        $now = new DateTime('now', $tz);
        $hour = (int) $now->format('G');
        if ($hour !== 18 && $hour !== 19) {
            return;
        }
        $slot_key = $now->format('Y-m-d-H');
        $last_slot = (string) get_option('cmn_availability_nudge_last_slot', '');
        if ($last_slot === $slot_key) {
            return;
        }
        $target_day = (int) (clone $now)->modify('+1 day')->format('N');
        if ($target_day < 1 || $target_day > 5) {
            return;
        }
        $this->run_availability_nudges();
    }

    public function maybe_run_marketing_automation_fallback() {
        if (wp_doing_ajax()) {
            return;
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing(get_current_user_id())) {
            return;
        }
        if (!$this->is_portal_page()) {
            return;
        }
        if (!defined('DISABLE_WP_CRON') || !DISABLE_WP_CRON) {
            return;
        }

        $now = time();
        $last_queue = (int) get_option('cmn_marketing_queue_last_run_ts', 0);
        if (($now - $last_queue) >= 300) {
            $this->process_marketing_queue_batch(0, 30);
            update_option('cmn_marketing_queue_last_run_ts', $now, false);
        }

        $last_poll = (int) get_option('cmn_marketing_poll_last_run_ts', 0);
        if (($now - $last_poll) >= 600) {
            $this->poll_marketing_replies_imap(40);
            update_option('cmn_marketing_poll_last_run_ts', $now, false);
        }
    }

