    private function get_next_candidate_rewards_annual_reset_timestamp($reference_ts = 0) {
        $reference_ts = (int) $reference_ts;
        if ($reference_ts < 1) {
            $reference_ts = (int) (function_exists('cmn_now') ? cmn_now()->getTimestamp() : current_time('timestamp'));
        }
        $tz = wp_timezone();
        $reference = (new DateTimeImmutable('@' . max(1, $reference_ts)))->setTimezone($tz);
        $candidate = $reference->setDate((int) $reference->format('Y'), 9, 1)->setTime(2, 0, 0);
        if ($reference >= $candidate) {
            $candidate = $candidate->modify('+1 year')->setDate((int) $candidate->format('Y'), 9, 1)->setTime(2, 0, 0);
        }
        return (int) $candidate->getTimestamp();
    }

    private function get_next_candidate_rewards_academic_year_rollover_timestamp($reference_ts = 0) {
        $reference_ts = (int) $reference_ts;
        if ($reference_ts < 1) {
            $reference_ts = (int) (function_exists('cmn_now') ? cmn_now()->getTimestamp() : current_time('timestamp'));
        }
        $tz = wp_timezone();
        $reference = (new DateTimeImmutable('@' . max(1, $reference_ts)))->setTimezone($tz);
        $candidate = $reference->setTime(2, 0, 0);
        if ($reference >= $candidate) {
            $candidate = $candidate->modify('+1 day')->setTime(2, 0, 0);
        }
        return (int) $candidate->getTimestamp();
    }

    private function get_next_candidate_rewards_payroll_addon_timestamp($reference_ts = 0) {
        $reference_ts = (int) $reference_ts;
        if ($reference_ts < 1) {
            $reference_ts = (int) (function_exists('cmn_now') ? cmn_now()->getTimestamp() : current_time('timestamp'));
        }
        $tz = wp_timezone();
        $reference = (new DateTimeImmutable('@' . max(1, $reference_ts)))->setTimezone($tz);
        $candidate = $reference->modify('next monday')->setTime(2, 30, 0);
        if ($reference->format('N') === '1') {
            $today_target = $reference->setTime(2, 30, 0);
            if ($reference < $today_target) {
                $candidate = $today_target;
            }
        }
        return (int) $candidate->getTimestamp();
    }

