    private function get_candidate_rewards_reset_period_labels($reference_date = 'now') {
        $to_label = (string) $this->get_academic_year_label($reference_date);
        if (preg_match('/^(\d{4})-(\d{4})$/', $to_label, $m) !== 1) {
            return [
                'from' => '',
                'to' => '',
            ];
        }
        $start_year = (int) $m[1];
        $from_label = sprintf('%04d-%04d', ($start_year - 1), $start_year);
        return [
            'from' => $from_label,
            'to' => $to_label,
        ];
    }

