    public function ensure_rewards_academic_year_configs() {
        static $ran = false;
        if ($ran) {
            return;
        }
        $ran = true;

        $this->run_candidate_rewards_academic_year_rollover_job('init', 0);
    }

    /*
     * Prompt 4 acceptance checks:
     * 1) On Sep 1, current rewards academic year resolves to that Sep 1 -> Jul 31 label.
     * 2) On Aug 15, current resolves to the year that ended Jul 31; next config exists for upcoming Sep 1.
     * 3) Running this job repeatedly does not create duplicate academic_year_label rows.
     */
    private function run_candidate_rewards_academic_year_rollover_job($trigger = 'cron', $actor_user_id = 0, DateTimeInterface $reference_datetime = null) {
        $lock_key = self::CANDIDATE_REWARDS_ACADEMIC_YEAR_ROLLOVER_LOCK_KEY;
        if (get_transient($lock_key)) {
            return [
                'ok' => false,
                'message' => 'Rewards academic year rollover is already in progress.',
            ];
        }
        set_transient($lock_key, 1, self::CANDIDATE_REWARDS_ACADEMIC_YEAR_ROLLOVER_LOCK_TTL);

        try {
            $reference = $this->normalize_rewards_reference_datetime($reference_datetime);
            $year_context = $this->get_rewards_current_and_next_year_contexts_for_datetime($reference);
            $created_labels = [];

            foreach (['current', 'next'] as $slot) {
                $target = $year_context[$slot] ?? [];
                $label = (string) ($target['label'] ?? '');
                if ($label === '') {
                    continue;
                }
                $result = $this->ensure_rewards_year_config_with_audit($label, [
                    'actor_user_id' => (int) $actor_user_id,
                    'trigger' => (string) $trigger,
                ]);
                if (!empty($result['created'])) {
                    $created_labels[] = $label;
                }
            }

            $archived_labels = $this->archive_rewards_config_years_before_date((string) $reference->format('Y-m-d'));
            if ($trigger === 'cron' && function_exists('cmn_audit_log_event')) {
                cmn_audit_log_event([
                    'module' => 'rewards',
                    'entity_type' => 'system',
                    'entity_id' => 0,
                    'event_type' => 'academic_year_rollover_checked',
                    'actor_user_id' => (int) $actor_user_id,
                    'metadata' => [
                        'trigger' => (string) $trigger,
                        'reference_date' => (string) $reference->format('Y-m-d'),
                        'timezone' => wp_timezone_string(),
                        'current_label' => (string) ($year_context['current']['label'] ?? ''),
                        'current_start' => (string) ($year_context['current']['start'] ?? ''),
                        'current_end' => (string) ($year_context['current']['end'] ?? ''),
                        'next_label' => (string) ($year_context['next']['label'] ?? ''),
                        'next_start' => (string) ($year_context['next']['start'] ?? ''),
                        'next_end' => (string) ($year_context['next']['end'] ?? ''),
                        'is_off_season' => !empty($year_context['current']['is_off_season']),
                        'created_labels' => array_values(array_unique($created_labels)),
                        'archived_labels' => array_values(array_unique($archived_labels)),
                    ],
                ]);
            }

            return [
                'ok' => true,
                'created_labels' => array_values(array_unique($created_labels)),
                'archived_labels' => array_values(array_unique($archived_labels)),
                'current' => $year_context['current'],
                'next' => $year_context['next'],
            ];
        } finally {
            delete_transient($lock_key);
        }
    }

    private function normalize_rewards_reference_datetime(DateTimeInterface $reference_datetime = null) {
        $tz = wp_timezone();
        if ($reference_datetime instanceof DateTimeImmutable) {
            return $reference_datetime->setTimezone($tz);
        }
        if ($reference_datetime instanceof DateTimeInterface) {
            $source_timezone = $reference_datetime->getTimezone();
            if (!$source_timezone instanceof DateTimeZone) {
                $source_timezone = $tz;
            }
            return (new DateTimeImmutable($reference_datetime->format('Y-m-d H:i:s'), $source_timezone))
                ->setTimezone($tz);
        }
        return function_exists('cmn_now')
            ? cmn_now()->setTimezone($tz)
            : new DateTimeImmutable('now', $tz);
    }

    private function get_rewards_current_and_next_year_contexts_for_datetime(DateTimeInterface $reference_datetime) {
        $reference = $this->normalize_rewards_reference_datetime($reference_datetime);
        $current_context = $this->get_rewards_academic_year_context_for_datetime($reference);
        $calendar_year = (int) $reference->format('Y');
        $calendar_month = (int) $reference->format('n');

        $next_start_year = $calendar_month < 9 ? $calendar_year : ($calendar_year + 1);
        $next_start = new DateTimeImmutable(sprintf('%04d-09-01 00:00:00', $next_start_year), wp_timezone());
        $next_context = $this->get_rewards_academic_year_context_for_datetime($next_start);

        return [
            'current' => $current_context,
            'next' => $next_context,
        ];
    }

    private function get_rewards_academic_year_context_for_datetime(DateTimeInterface $reference_datetime) {
        $reference = $this->normalize_rewards_reference_datetime($reference_datetime);
        $bounds = self::get_academic_year_bounds_for_datetime($reference);
        $start_year = (int) ($bounds['start_year'] ?? 0);
        $end_year = (int) ($bounds['end_year'] ?? ($start_year + 1));

        return [
            'label' => self::build_academic_year_label_from_start_year($start_year),
            'start' => sprintf('%04d-09-01', $start_year),
            'end' => sprintf('%04d-07-31', $end_year),
            'start_year' => $start_year,
            'end_year' => $end_year,
            'is_off_season' => !empty($bounds['is_off_season']),
        ];
    }

    private function ensure_rewards_year_config_with_audit($academic_year_label, array $options = []) {
        $academic_year_label = trim((string) $academic_year_label);
        $start_year = self::parse_academic_year_start_year_from_label($academic_year_label);
        if ($start_year < 2000) {
            return [
                'created' => false,
                'row' => [],
            ];
        }
        $normalized_label = self::build_academic_year_label_from_start_year($start_year);

        global $wpdb;
        $table = $this->get_rewards_config_years_table();
        $existing = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE academic_year_label = %s LIMIT 1",
            $normalized_label
        ), ARRAY_A);
        if (is_array($existing) && !empty($existing)) {
            return [
                'created' => false,
                'row' => $existing,
            ];
        }

        $row = self::ensure_rewards_config_year_row($normalized_label);
        $created = !empty($row['__cmn_created']);
        if (!empty($row)) {
            if ($created) {
                $actor_user_id = (int) ($options['actor_user_id'] ?? 0);
                $trigger = sanitize_key((string) ($options['trigger'] ?? 'system'));
                if ($trigger === '') {
                    $trigger = 'system';
                }
                if (function_exists('cmn_audit_log_event')) {
                    cmn_audit_log_event([
                        'module' => 'rewards',
                        'entity_type' => 'system',
                        'entity_id' => 0,
                        'event_type' => 'academic_year_config_created',
                        'actor_user_id' => $actor_user_id,
                        'metadata' => [
                            'label' => (string) ($row['academic_year_label'] ?? $normalized_label),
                            'start' => (string) ($row['starts_on'] ?? ''),
                            'end' => (string) ($row['ends_on'] ?? ''),
                            'trigger' => $trigger,
                        ],
                    ]);
                }
            }
        }
        if (isset($row['__cmn_created'])) {
            unset($row['__cmn_created']);
        }

        return [
            'created' => $created,
            'row' => is_array($row) ? $row : [],
        ];
    }

    private function archive_rewards_config_years_before_date($reference_date_ymd) {
        $reference_date_ymd = trim((string) $reference_date_ymd);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $reference_date_ymd)) {
            return [];
        }

        global $wpdb;
        $table = $this->get_rewards_config_years_table();
        $to_archive = $wpdb->get_results($wpdb->prepare(
            "SELECT id, academic_year_label
             FROM {$table}
             WHERE is_archived = 0
               AND ends_on < %s",
            $reference_date_ymd
        ), ARRAY_A);
        if (!is_array($to_archive) || empty($to_archive)) {
            return [];
        }

        $ids = [];
        $labels = [];
        foreach ($to_archive as $row) {
            $id = (int) ($row['id'] ?? 0);
            if ($id > 0) {
                $ids[] = $id;
                $labels[] = (string) ($row['academic_year_label'] ?? '');
            }
        }
        $ids = array_values(array_unique($ids));
        $labels = array_values(array_unique(array_filter($labels, static function ($value) {
            return is_string($value) && $value !== '';
        })));
        if (empty($ids)) {
            return [];
        }

        $quoted_ids = implode(',', array_map('intval', $ids));
        $now_mysql = current_time('mysql');
        $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET is_archived = 1,
                 updated_at = %s
             WHERE id IN ({$quoted_ids})",
            $now_mysql
        ));

        return $labels;
    }

    public function maybe_run_automation_runner_fallback() {
        if (wp_doing_ajax()) {
            return;
        }
        if (!$this->is_portal_page()) {
            return;
        }
        if (!defined('DISABLE_WP_CRON') || !DISABLE_WP_CRON) {
            return;
        }
        $last_run = (int) get_option('cmn_automation_runner_last_run_ts', 0);
        if ((time() - $last_run) < HOUR_IN_SECONDS) {
            return;
        }
        $this->run_automation_runner();
    }

    public function run_automation_runner() {
        if (get_transient('cmn_automation_runner_lock')) {
            return [
                'ok' => false,
                'message' => 'Automation runner is already in progress.',
            ];
        }
        set_transient('cmn_automation_runner_lock', 1, 600);
        $result = [
            'ok' => false,
            'message' => 'Automation runner did not execute.',
        ];
        try {
            $summary = $this->get_automation_engine()->run_scheduled_no_activity([
                'batch_size' => 80,
                'max_entities' => 800,
            ]);
            update_option('cmn_automation_runner_last_run_ts', time(), false);
            update_option('cmn_automation_runner_last_result', wp_json_encode($summary), false);
            $result = [
                'ok' => true,
                'summary' => $summary,
            ];
        } catch (Throwable $e) {
            $result = [
                'ok' => false,
                'message' => 'Automation runner failed: ' . $e->getMessage(),
            ];
        } finally {
            delete_transient('cmn_automation_runner_lock');
        }
        return $result;
    }

    private function get_automation_runner_token() {
        if (defined('CMN_AUTOMATION_CRON_TOKEN')) {
            $token = trim((string) CMN_AUTOMATION_CRON_TOKEN);
            if ($token !== '') {
                return $token;
            }
        }
        $token = trim((string) get_option('cmn_automation_runner_token', ''));
        if ($token === '') {
            $token = wp_generate_password(48, false, false);
            update_option('cmn_automation_runner_token', $token, false);
        }
        return $token;
    }

    public function handle_automation_runner_endpoint() {
        if (!isset($_GET['cmn_run_automation'])) {
            return;
        }
        $run_flag = trim((string) wp_unslash($_GET['cmn_run_automation']));
        if (!in_array($run_flag, ['1', 'true', 'yes'], true)) {
            return;
        }

        $provided = trim((string) ($_REQUEST['token'] ?? $_REQUEST['cmn_runner_token'] ?? ''));
        $expected = $this->get_automation_runner_token();
        $as_json = strtolower(trim((string) ($_REQUEST['format'] ?? 'json'))) === 'json';
        if ($provided === '' || !hash_equals($expected, $provided)) {
            status_header(403);
            if ($as_json) {
                wp_send_json_error(['message' => 'Invalid automation runner token.'], 403);
            }
            header('Content-Type: text/plain; charset=utf-8');
            echo 'Invalid automation runner token.';
            exit;
        }

        $run = $this->run_automation_runner();
        if ($as_json) {
            if (!empty($run['ok'])) {
                wp_send_json_success([
                    'ok' => true,
                    'at' => gmdate('c'),
                    'result' => $run,
                ]);
            }
            wp_send_json_error([
                'ok' => false,
                'at' => gmdate('c'),
                'result' => $run,
            ], 500);
        }

        header('Content-Type: text/plain; charset=utf-8');
        if (!empty($run['ok'])) {
            echo "ok\n";
            echo 'at=' . gmdate('c') . "\n";
            $summary = is_array($run['summary'] ?? null) ? $run['summary'] : [];
            echo 'rules_processed=' . (int) ($summary['rules_processed'] ?? 0) . "\n";
            echo 'entities_checked=' . (int) ($summary['entities_checked'] ?? 0) . "\n";
            echo 'success=' . (int) ($summary['success'] ?? 0) . "\n";
            echo 'skipped=' . (int) ($summary['skipped'] ?? 0) . "\n";
            echo 'failed=' . (int) ($summary['failed'] ?? 0) . "\n";
            exit;
        }
        status_header(500);
        echo 'error=' . (string) ($run['message'] ?? 'Automation runner failed.') . "\n";
        exit;
    }

    public function handle_set_release_version_endpoint() {
        if (!isset($_GET['cmn_set_release_version'])) {
            return;
        }
        $flag = trim((string) wp_unslash($_GET['cmn_set_release_version']));
        if (!in_array($flag, ['1', 'true', 'yes'], true)) {
            return;
        }
        $provided = trim((string) wp_unslash($_GET['token'] ?? $_REQUEST['token'] ?? ''));
        $expected = $this->get_automation_runner_token();
        if ($provided === '' || !hash_equals($expected, $provided)) {
            status_header(403);
            wp_send_json([
                'ok' => false,
                'error' => 'Invalid token.',
            ], 403);
        }
        $version = trim((string) wp_unslash($_GET['v'] ?? $_REQUEST['v'] ?? ''));
        if (!preg_match('/^\d+\.\d+\.\d+$/', $version)) {
            wp_send_json([
                'ok' => false,
                'error' => 'Invalid version. Use digits only (e.g. 0.0.18).',
            ], 400);
        }
        $version = $this->normalize_release_version_value($version);
        if ($version === '') {
            wp_send_json([
                'ok' => false,
                'error' => 'Invalid version. Use digits only (e.g. 0.0.18).',
            ], 400);
        }
        update_option('cmn_release_version', $version, false);
        wp_send_json([
            'ok' => true,
            'version' => $version,
        ], 200);
    }

    public function handle_automation_realtime($trigger_event, $entity_context = [], $options = []) {
        $trigger_event = sanitize_key((string) $trigger_event);
        if ($trigger_event === '') {
            return;
        }
        if (!is_array($entity_context)) {
            $entity_context = [];
        }
        $depth = (int) ($entity_context['automation_meta']['depth'] ?? 0);
        if ($depth > self::AUTOMATION_MAX_RECURSION_DEPTH) {
            return;
        }
        if (!is_array($options)) {
            $options = [];
        }
        $this->get_automation_engine()->run_event($trigger_event, $entity_context, $options);
    }

    private function trigger_automation_event($trigger_event, $entity_type, $entity_id, $extra = [], $options = []) {
        $trigger_event = sanitize_key((string) $trigger_event);
        if ($trigger_event === '') {
            return;
        }
        if (!is_array($extra)) {
            $extra = [];
        }
        if (!is_array($options)) {
            $options = [];
        }
        $context = $this->build_automation_context($entity_type, $entity_id, $trigger_event, $extra);
        if (!$context) {
            return;
        }
        do_action('cmn_automation_realtime', $trigger_event, $context, $options);
    }

    public function build_automation_context($entity_type, $entity_id, $trigger_event = '', $extra = []) {
        $entity_type = sanitize_key((string) $entity_type);
        $entity_id = (int) $entity_id;
        $trigger_event = sanitize_key((string) $trigger_event);
        if (!is_array($extra)) {
            $extra = [];
        }

        $context = [
            'trigger_event' => $trigger_event,
            'entity_type' => $entity_type,
            'entity_id' => $entity_id,
            'event_time' => current_time('mysql'),
            'automation_meta' => [
                'depth' => max(0, (int) ($extra['automation_meta']['depth'] ?? 0)),
                'source' => sanitize_key((string) ($extra['automation_meta']['source'] ?? 'realtime')),
            ],
        ];

        if ($entity_type === 'candidate' && $entity_id > 0) {
            $context = array_merge($context, $this->get_automation_candidate_context($entity_id));
        } elseif (($entity_type === 'school' || $entity_type === 'lead') && $entity_id > 0) {
            $school_context = $this->get_automation_school_context($entity_id);
            if ($entity_type === 'lead') {
                $school_context['entity_type'] = 'lead';
            }
            $context = array_merge($context, $school_context);
        } elseif ($entity_type === 'booking' && $entity_id > 0) {
            $context = array_merge($context, $this->get_automation_booking_context($entity_id));
        } elseif ($entity_type === 'support_ticket' && $entity_id > 0) {
            $context = array_merge($context, $this->get_automation_support_ticket_context($entity_id));
        }

        foreach ($extra as $key => $value) {
            if ($key === 'automation_meta' && is_array($value)) {
                $context['automation_meta'] = array_merge($context['automation_meta'], $value);
                continue;
            }
            $context[$key] = $value;
        }

        return $context;
    }

    private function get_automation_candidate_context($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return [];
        }
        $candidate_name = (string) get_the_title($candidate_id);
        $candidate_email = sanitize_email((string) get_post_meta($candidate_id, 'cmn_email', true));
        $candidate_user_id = (int) get_post_meta($candidate_id, 'cmn_user_id', true);
        if ($candidate_user_id < 1 && $candidate_email !== '') {
            $candidate_user = get_user_by('email', $candidate_email);
            $candidate_user_id = $candidate_user ? (int) $candidate_user->ID : 0;
        }
        $last_booking_days = $this->get_automation_last_booking_days('candidate', $candidate_id);
        $last_activity_days = $this->get_automation_last_activity_days('candidate', $candidate_id);
        return [
            'entity_type' => 'candidate',
            'entity_id' => $candidate_id,
            'candidate_id' => $candidate_id,
            'candidate_name' => $candidate_name,
            'first_name' => $this->get_automation_first_name($candidate_name),
            'candidate_email' => $candidate_email,
            'candidate_user_id' => $candidate_user_id,
            'location' => (string) get_post_meta($candidate_id, 'cmn_location', true),
            'status' => (string) get_post_meta($candidate_id, 'cmn_status', true),
            'compliance_status' => (string) get_post_meta($candidate_id, 'cmn_status', true),
            'last_booking_days' => $last_booking_days,
            'last_activity_days' => $last_activity_days,
            'no_activity_days' => $this->get_automation_no_activity_days($last_booking_days, $last_activity_days),
        ];
    }

    private function get_automation_school_context($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [];
        }
        $school_email = sanitize_email((string) get_post_meta($school_id, 'cmn_email', true));
        $school_domain = strtolower(trim((string) get_post_meta($school_id, 'cmn_school_email_domain', true)));
        if ($school_domain === '') {
            $school_domain = $this->get_email_domain($school_email);
        }
        $school_user_id = 0;
        if ($school_email !== '') {
            $school_user = get_user_by('email', $school_email);
            if ($school_user) {
                $school_user_id = (int) $school_user->ID;
            }
        }
        $last_booking_days = $this->get_automation_last_booking_days('school', $school_id);
        $last_activity_days = $this->get_automation_last_activity_days('school', $school_id);
        return [
            'entity_type' => 'school',
            'entity_id' => $school_id,
            'school_id' => $school_id,
            'school_name' => (string) get_the_title($school_id),
            'first_name' => $this->get_automation_first_name((string) get_the_title($school_id)),
            'school_email' => $school_email,
            'school_domain' => $school_domain,
            'school_user_id' => $school_user_id,
            'location' => (string) get_post_meta($school_id, 'cmn_location', true),
            'status' => (string) get_post_meta($school_id, 'cmn_status', true),
            'pipeline_stage' => (string) get_post_meta($school_id, 'cmn_pipeline_stage', true),
            'account_manager_user_id' => (int) get_post_meta($school_id, 'cmn_account_manager_user', true),
            'last_booking_days' => $last_booking_days,
            'last_activity_days' => $last_activity_days,
            'no_activity_days' => $this->get_automation_no_activity_days($last_booking_days, $last_activity_days),
        ];
    }

    private function get_automation_booking_context($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking') {
            return [];
        }
        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        $context = [
            'entity_type' => 'booking',
            'entity_id' => $booking_id,
            'booking_id' => $booking_id,
            'booking_status' => (string) get_post_meta($booking_id, 'cmn_status', true),
            'booking_date' => (string) get_post_meta($booking_id, 'cmn_start_date', true),
            'location' => (string) get_post_meta($booking_id, 'cmn_location', true),
            'role' => (string) get_post_meta($booking_id, 'cmn_role', true),
            'candidate_id' => $candidate_id,
            'school_id' => $school_id,
        ];
        if ((string) $context['booking_date'] === '') {
            $context['booking_date'] = (string) get_post_meta($booking_id, 'cmn_date', true);
        }
        if ($candidate_id > 0) {
            $context = array_merge($context, $this->get_automation_candidate_context($candidate_id));
            $context['entity_type'] = 'booking';
            $context['entity_id'] = $booking_id;
            $context['candidate_id'] = $candidate_id;
        }
        if ($school_id > 0) {
            $school_ctx = $this->get_automation_school_context($school_id);
            $context['school_name'] = (string) ($school_ctx['school_name'] ?? '');
            $context['school_email'] = (string) ($school_ctx['school_email'] ?? '');
            $context['school_domain'] = (string) ($school_ctx['school_domain'] ?? '');
            $context['school_user_id'] = (int) ($school_ctx['school_user_id'] ?? 0);
            $context['account_manager_user_id'] = (int) ($school_ctx['account_manager_user_id'] ?? 0);
            if ((string) ($context['location'] ?? '') === '' && !empty($school_ctx['location'])) {
                $context['location'] = (string) $school_ctx['location'];
            }
        }
        return $context;
    }

    private function get_automation_support_ticket_context($ticket_id) {
        global $wpdb;
        $ticket_id = (int) $ticket_id;
        if ($ticket_id < 1) {
            return [];
        }
        $table = $this->get_support_ticket_table();
        $ticket = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $ticket_id), ARRAY_A);
        if (!$ticket) {
            return [];
        }
        $owner_user_id = (int) ($ticket['created_by_user_id'] ?? 0);
        $owner = $owner_user_id > 0 ? get_user_by('id', $owner_user_id) : null;
        return [
            'entity_type' => 'support_ticket',
            'entity_id' => $ticket_id,
            'ticket_id' => $ticket_id,
            'ticket_ref' => (string) ($ticket['ticket_ref'] ?? ''),
            'status' => (string) ($ticket['status'] ?? ''),
            'category' => (string) ($ticket['category'] ?? ''),
            'subject' => (string) ($ticket['subject'] ?? ''),
            'first_name' => $owner ? $this->get_automation_first_name((string) $owner->display_name) : '',
            'owner_user_id' => $owner_user_id,
            'owner_email' => $owner ? (string) $owner->user_email : '',
        ];
    }

    private function get_automation_last_booking_days($entity_type, $entity_id) {
        global $wpdb;
        $entity_type = sanitize_key((string) $entity_type);
        $entity_id = (int) $entity_id;
        if ($entity_id < 1) {
            return null;
        }
        $meta_key = $entity_type === 'school' ? 'cmn_school_id' : 'cmn_candidate_id';
        $date_sql = "SELECT COALESCE(NULLIF(start_date.meta_value, ''), NULLIF(day_date.meta_value, '')) AS booking_date
            FROM {$wpdb->posts} p
            INNER JOIN {$wpdb->postmeta} link_meta ON link_meta.post_id = p.ID AND link_meta.meta_key = %s AND link_meta.meta_value = %d
            LEFT JOIN {$wpdb->postmeta} start_date ON start_date.post_id = p.ID AND start_date.meta_key = 'cmn_start_date'
            LEFT JOIN {$wpdb->postmeta} day_date ON day_date.post_id = p.ID AND day_date.meta_key = 'cmn_date'
            LEFT JOIN {$wpdb->postmeta} status_meta ON status_meta.post_id = p.ID AND status_meta.meta_key = 'cmn_status'
            WHERE p.post_type = 'cmn_booking'
              AND p.post_status IN ('publish', 'private')
              AND COALESCE(status_meta.meta_value, '') NOT IN ('declined', 'expired')
            ORDER BY booking_date DESC
            LIMIT 1";
        $booking_date = (string) $wpdb->get_var($wpdb->prepare($date_sql, $meta_key, $entity_id));
        if ($booking_date === '') {
            return null;
        }
        $ts = strtotime($booking_date . ' 00:00:00');
        if ($ts === false) {
            return null;
        }
        return max(0, (int) floor((current_time('timestamp') - $ts) / DAY_IN_SECONDS));
    }

    private function get_automation_last_activity_days($entity_type, $entity_id) {
        global $wpdb;
        $entity_type = sanitize_key((string) $entity_type);
        $entity_id = (int) $entity_id;
        if ($entity_id < 1) {
            return null;
        }
        $activity_type = '';
        $entity_ref = '';
        if ($entity_type === 'candidate') {
            $activity_type = 'contact';
            $entity_ref = (string) $entity_id;
        } elseif ($entity_type === 'school') {
            $activity_type = 'school';
            $domain = (string) get_post_meta($entity_id, 'cmn_school_email_domain', true);
            if ($domain === '') {
                $domain = $this->get_email_domain((string) get_post_meta($entity_id, 'cmn_email', true));
            }
            $entity_ref = strtolower(trim($domain));
        }
        if ($activity_type === '' || $entity_ref === '') {
            return null;
        }
        $table = $this->get_activity_table();
        $created_at = (string) $wpdb->get_var($wpdb->prepare(
            "SELECT MAX(created_at) FROM {$table} WHERE entity_type = %s AND entity_ref = %s",
            $activity_type,
            $entity_ref
        ));
        if ($created_at === '') {
            return null;
        }
        $ts = strtotime($created_at);
        if ($ts === false) {
            return null;
        }
        return max(0, (int) floor((current_time('timestamp') - $ts) / DAY_IN_SECONDS));
    }

    private function get_automation_no_activity_days($last_booking_days, $last_activity_days) {
        $vals = [];
        if (is_numeric($last_booking_days)) {
            $vals[] = (int) $last_booking_days;
        }
        if (is_numeric($last_activity_days)) {
            $vals[] = (int) $last_activity_days;
        }
        if (!$vals) {
            return 9999;
        }
        return min($vals);
    }

    private function get_automation_first_name($name) {
        $name = trim((string) $name);
        if ($name === '') {
            return '';
        }
        $parts = preg_split('/\s+/', $name);
        return $parts ? (string) $parts[0] : $name;
    }

    private function resolve_school_id_for_user($user_id = 0) {
        $user_id = $user_id ?: get_current_user_id();
        if (!$user_id) {
            return 0;
        }
        $mapped = get_user_meta($user_id, 'cmn_school_id', true);
        if ($mapped) {
            $school_id = (int) $mapped;
            if ($school_id > 0 && $this->is_school_user($user_id)) {
                $state_result = $this->ensure_school_partner_state_for_user((int) $user_id);
                if (is_wp_error($state_result) && defined('WP_DEBUG') && WP_DEBUG) {
                    error_log('CMN school partner state ensure failed (resolve mapped): ' . $state_result->get_error_message());
                }
            }
            return $school_id;
        }
        $user = get_user_by('id', $user_id);
        if (!$user) {
            return 0;
        }
        $school = get_posts([
            'post_type' => 'cmn_school',
            'posts_per_page' => 1,
            'meta_query' => [
                [
                    'key' => 'cmn_email',
                    'value' => $user->user_email,
                ],
            ],
        ]);
        if ($school) {
            $school_id = (int) $school[0]->ID;
            if ($school_id > 0 && $this->is_school_user($user_id)) {
                update_user_meta($user_id, 'cmn_school_id', $school_id);
                $state_result = $this->ensure_school_partner_state_for_user((int) $user_id);
                if (is_wp_error($state_result) && defined('WP_DEBUG') && WP_DEBUG) {
                    error_log('CMN school partner state ensure failed (resolve by email): ' . $state_result->get_error_message());
                }
            }
            return $school_id;
        }
        return 0;
    }

    private function get_candidate_id_for_user($user_id = 0) {
        $user_id = $user_id ?: get_current_user_id();
        if (!$user_id) {
            return 0;
        }
        $candidate_by_user = get_posts([
            'post_type' => 'cmn_candidate',
            'posts_per_page' => 1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_user_id',
                    'value' => (int) $user_id,
                    'compare' => '=',
                    'type' => 'NUMERIC',
                ],
            ],
            'orderby' => 'date',
            'order' => 'DESC',
        ]);
        if ($candidate_by_user) {
            return (int) $candidate_by_user[0];
        }
        $user = get_user_by('id', $user_id);
        if (!$user || !$user->user_email) {
            return 0;
        }
        $candidate = get_posts([
            'post_type' => 'cmn_candidate',
            'posts_per_page' => 1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_email',
                    'value' => $user->user_email,
                ],
            ],
        ]);
        if ($candidate) {
            return (int) $candidate[0];
        }
        return 0;
    }

    private function get_candidate_user_id($candidate_id) {
        if (!$candidate_id) {
            return 0;
        }
        $user_id = (int) get_post_meta($candidate_id, 'cmn_user_id', true);
        if ($user_id) {
            return $user_id;
        }
        $email = get_post_meta($candidate_id, 'cmn_email', true);
        if ($email) {
            $user = get_user_by('email', $email);
            if ($user) {
                return (int) $user->ID;
            }
        }
        return 0;
    }

    private function get_account_manager($school_id) {
        $name = get_post_meta($school_id, 'cmn_account_manager_name', true);
        $email = get_post_meta($school_id, 'cmn_account_manager_email', true);
        if (!$email) {
            $email = get_option('admin_email');
        }
        if (!$name) {
            $name = 'CoverMeNow ONE';
        }
        return [
            'name' => $name,
            'email' => $email,
        ];
    }

    private function count_school_leads_for_navigation($include_needs_attention = true) {
        $lead_meta_query = [
            [
                'key' => 'cmn_status',
                'value' => 'lead',
            ],
        ];
        if ($include_needs_attention) {
            $lead_meta_query = [
                'relation' => 'OR',
                [
                    'key' => 'cmn_status',
                    'value' => 'lead',
                ],
                [
                    'key' => 'cmn_status',
                    'value' => 'needs_attention',
                ],
            ];
        }
        $query = new WP_Query([
            'post_type' => 'cmn_school',
            'post_status' => $this->get_school_list_post_statuses(),
            'posts_per_page' => 1,
            'fields' => 'ids',
            'no_found_rows' => false,
            'meta_query' => [$lead_meta_query],
        ]);
        return (int) $query->found_posts;
    }

    private function count_school_status_for_navigation($status) {
        $status = sanitize_key((string) $status);
        if ($status === '') {
            return 0;
        }
        $query = new WP_Query([
            'post_type' => 'cmn_school',
            'post_status' => $this->get_school_list_post_statuses(),
            'posts_per_page' => 1,
            'fields' => 'ids',
            'no_found_rows' => false,
            'meta_query' => [
                [
                    'key' => 'cmn_status',
                    'value' => $status,
                ],
            ],
        ]);
        return (int) $query->found_posts;
    }

    private function get_school_primary_contact_summary($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return [
                'name' => '',
                'phone' => '',
                'email' => '',
            ];
        }
        $name = trim((string) get_post_meta($school_id, 'cmn_primary_contact_name', true));
        if ($name === '') {
            $name = trim((string) get_post_meta($school_id, 'cmn_contact_name', true));
        }
        $phone = trim((string) get_post_meta($school_id, 'cmn_primary_contact_phone', true));
        if ($phone === '') {
            $phone = trim((string) get_post_meta($school_id, 'cmn_contact_phone', true));
        }
        $email = sanitize_email((string) get_post_meta($school_id, 'cmn_primary_contact_email', true));
        if ($email === '') {
            $email = sanitize_email((string) get_post_meta($school_id, 'cmn_contact_email', true));
        }
        return [
            'name' => $name,
            'phone' => $phone,
            'email' => $email,
        ];
    }

    private function get_school_account_manager_summary($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return [
                'name' => '',
                'email' => '',
            ];
        }
        $manager_user_id = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
        if ($manager_user_id < 1) {
            $manager_user_id = (int) get_post_meta($school_id, 'cmn_account_manager_user_id', true);
        }
        if ($manager_user_id > 0) {
            $manager_user = get_user_by('id', $manager_user_id);
            if ($manager_user) {
                return [
                    'name' => trim((string) $manager_user->display_name),
                    'email' => sanitize_email((string) $manager_user->user_email),
                ];
            }
        }
        $name = trim((string) get_post_meta($school_id, 'cmn_account_manager', true));
        if ($name === '') {
            $name = trim((string) get_post_meta($school_id, 'cmn_account_manager_name', true));
        }
        $email = sanitize_email((string) get_post_meta($school_id, 'cmn_account_manager_email', true));
        return [
            'name' => $name,
            'email' => $email,
        ];
    }

    private function get_school_last_activity_summary($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return [
                'label' => '-',
                'detail' => '',
            ];
        }
        $modified = trim((string) get_post_field('post_modified', $school_id));
        if ($modified === '' || $modified === '0000-00-00 00:00:00') {
            $modified = trim((string) get_post_field('post_date', $school_id));
        }
        $activity_ts = $modified !== '' ? strtotime($modified) : 0;
        if ($activity_ts < 1) {
            return [
                'label' => '-',
                'detail' => '',
            ];
        }
        return [
            'label' => human_time_diff($activity_ts, current_time('timestamp')) . ' ago',
            'detail' => date_i18n('M j, Y g:ia', $activity_ts),
        ];
    }

    public function get_automation_console_url($tab = 'rules', $extra_query = []) {
        $tab = sanitize_key((string) $tab);
        if ($tab === '') {
            $tab = 'rules';
        }
        $url = add_query_arg([
            'view' => 'automation',
            'cmn_automation_tab' => $tab,
        ], $this->get_portal_base_url());
        if (!is_array($extra_query) || !$extra_query) {
            return $url;
        }
        $query = [];
        foreach ($extra_query as $key => $value) {
            $key = sanitize_key((string) $key);
            if ($key === '') {
                continue;
            }
            if ($value === null) {
                $query[$key] = false;
                continue;
            }
            if (is_bool($value)) {
                $query[$key] = $value ? '1' : '0';
                continue;
            }
            if (is_scalar($value)) {
                $query[$key] = sanitize_text_field((string) $value);
            }
        }
        if ($query) {
            $url = add_query_arg($query, $url);
        }
        return $url;
    }

    private function get_staff_nav_group_whitelist() {
        return ['schools', 'candidates', 'bookings', 'commercial', 'support', 'intelligence', 'automation', 'system'];
    }

    private function build_staff_nav_order_from_groups($groups) {
        $groups = is_array($groups) ? $groups : [];
        $order = [
            'groups' => [],
            'items' => [],
        ];
        foreach ($groups as $group_key => $group_config) {
            $group_key = sanitize_key((string) $group_key);
            if ($group_key === '') {
                continue;
            }
            $items = isset($group_config['items']) && is_array($group_config['items']) ? $group_config['items'] : [];
            if (!$items) {
                continue;
            }
            $order['groups'][] = $group_key;
            $order['items'][$group_key] = [];
            foreach ($items as $item_config) {
                $item_key = sanitize_key((string) ($item_config['key'] ?? ''));
                if ($item_key === '') {
                    continue;
                }
                $order['items'][$group_key][] = $item_key;
            }
        }
        return $order;
    }

    private function normalize_staff_nav_order_payload($raw_order, $groups) {
        $defaults = $this->build_staff_nav_order_from_groups($groups);
        if (!is_array($raw_order)) {
            return $defaults;
        }

        $normalized_groups = [];
        $seen_groups = [];
        $requested_groups = isset($raw_order['groups']) && is_array($raw_order['groups']) ? $raw_order['groups'] : [];
        foreach ($requested_groups as $group_key) {
            $group_key = sanitize_key((string) $group_key);
            if ($group_key === '' || !in_array($group_key, $defaults['groups'], true) || isset($seen_groups[$group_key])) {
                continue;
            }
            $normalized_groups[] = $group_key;
            $seen_groups[$group_key] = true;
        }
        foreach ($defaults['groups'] as $group_key) {
            if (!isset($seen_groups[$group_key])) {
                $normalized_groups[] = $group_key;
                $seen_groups[$group_key] = true;
            }
        }

        $normalized_items = [];
        $raw_items = isset($raw_order['items']) && is_array($raw_order['items']) ? $raw_order['items'] : [];
        foreach ($normalized_groups as $group_key) {
            $allowed_items = isset($defaults['items'][$group_key]) && is_array($defaults['items'][$group_key]) ? $defaults['items'][$group_key] : [];
            $requested_items = isset($raw_items[$group_key]) && is_array($raw_items[$group_key]) ? $raw_items[$group_key] : [];
            $seen_items = [];
            $normalized_items[$group_key] = [];
            foreach ($requested_items as $item_key) {
                $item_key = sanitize_key((string) $item_key);
                if ($item_key === '' || !in_array($item_key, $allowed_items, true) || isset($seen_items[$item_key])) {
                    continue;
                }
                $normalized_items[$group_key][] = $item_key;
                $seen_items[$item_key] = true;
            }
            foreach ($allowed_items as $item_key) {
                if (!isset($seen_items[$item_key])) {
                    $normalized_items[$group_key][] = $item_key;
                }
            }
        }

        return [
            'groups' => $normalized_groups,
            'items' => $normalized_items,
        ];
    }

    private function apply_staff_nav_order_to_groups($groups, $raw_order) {
        $groups = is_array($groups) ? $groups : [];
        if (!$groups) {
            return [];
        }
        $order = $this->normalize_staff_nav_order_payload($raw_order, $groups);
        $group_lookup = $groups;
        $ordered_groups = [];

        foreach ((array) $order['groups'] as $group_key) {
            if (!isset($group_lookup[$group_key])) {
                continue;
            }
            $group_config = $group_lookup[$group_key];
            $item_order = isset($order['items'][$group_key]) && is_array($order['items'][$group_key]) ? $order['items'][$group_key] : [];
            $items = isset($group_config['items']) && is_array($group_config['items']) ? $group_config['items'] : [];
            if ($items) {
                $item_lookup = [];
                $item_without_key = [];
                foreach ($items as $item_config) {
                    $item_key = sanitize_key((string) ($item_config['key'] ?? ''));
                    if ($item_key === '') {
                        $item_without_key[] = $item_config;
                        continue;
                    }
                    $item_lookup[$item_key] = $item_config;
                }
                $ordered_items = [];
                foreach ($item_order as $item_key) {
                    if (isset($item_lookup[$item_key])) {
                        $ordered_items[] = $item_lookup[$item_key];
                        unset($item_lookup[$item_key]);
                    }
                }
                foreach ($item_lookup as $item_config) {
                    $ordered_items[] = $item_config;
                }
                foreach ($item_without_key as $item_config) {
                    $ordered_items[] = $item_config;
                }
                $group_config['items'] = $ordered_items;
            }
            $ordered_groups[$group_key] = $group_config;
        }

        foreach ($group_lookup as $group_key => $group_config) {
            if (!isset($ordered_groups[$group_key])) {
                $ordered_groups[$group_key] = $group_config;
            }
        }

        return $ordered_groups;
    }

