    private function get_assigned_candidates($school_id) {
        $assigned = get_post_meta($school_id, 'cmn_assigned_candidates', true);
        if (is_array($assigned)) {
            return array_map('intval', $assigned);
        }
        if (is_string($assigned) && $assigned !== '') {
            $decoded = json_decode($assigned, true);
            if (is_array($decoded)) {
                return array_map('intval', $decoded);
            }
        }
        return [];
    }

    private function get_candidate_rate($candidate_id, $school_id = 0) {
        $default_rate = get_post_meta($candidate_id, 'cmn_default_rate', true);
        if ($default_rate === '') {
            $default_rate = 100;
        }
        $rate = (float) $default_rate;
        if ($school_id) {
            $rates = get_post_meta($school_id, 'cmn_candidate_rates', true);
            if (is_array($rates) && isset($rates[$candidate_id]) && $rates[$candidate_id] !== '') {
                $rate = (float) $rates[$candidate_id];
            }
        }
        return $rate;
    }

    private function get_portal_base_url() {
        $portal_page = $this->find_portal_page();
        if ($portal_page instanceof WP_Post) {
            $permalink = get_permalink($portal_page);
            if (is_string($permalink) && $permalink !== '') {
                return $permalink;
            }
        }
        return home_url('/portal/');
    }

    public function get_admin_recipient_email() {
        if (defined('CMN_ADMIN_RECIPIENT_EMAIL')) {
            $raw = CMN_ADMIN_RECIPIENT_EMAIL;
            if (is_string($raw) || is_numeric($raw)) {
                $normalized = sanitize_email((string) $raw);
                if ($normalized !== '') {
                    return $normalized;
                }
            }
        }
        $stored = sanitize_email((string) get_option('cmn_admin_recipient_email', ''));
        if ($stored !== '') {
            return $stored;
        }
        return 'admin@covermenow.co.uk';
    }

    public function notify_staff_admins($type, $title, $message, $link_url = '', $context = []) {
        $type = sanitize_key((string) $type);
        $title = sanitize_text_field((string) $title);
        $message = sanitize_text_field((string) $message);
        $link_url = esc_url_raw((string) $link_url);
        $context = is_array($context) ? $context : [];
        $inserted = 0;
        foreach ($this->get_staff_admin_users_for_cv_notifications() as $notify_user_id) {
            $insert_id = $this->add_notification((int) $notify_user_id, $type, $title, $message, $link_url, $context);
            if ($insert_id > 0) {
                $inserted++;
            }
        }
        return $inserted;
    }

    private function count_recent_candidate_registrations($hours = 24) {
        $hours = max(1, (int) $hours);
        $after = gmdate('Y-m-d H:i:s', time() - ($hours * HOUR_IN_SECONDS));
        $query = new WP_Query([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish', 'pending', 'draft', 'private'],
            'posts_per_page' => 1,
            'fields' => 'ids',
            'date_query' => [
                [
                    'after' => $after,
                    'inclusive' => true,
                ],
            ],
            'no_found_rows' => false,
        ]);
        return (int) $query->found_posts;
    }

    private function get_cv_converter_base_url() {
        // Use plugin-hosted static bundle path to avoid webroot routing differences.
        $plugin_bundle_url = plugin_dir_url(__FILE__) . 'cv/dist/';

        // Allow dev override only on local/test hosts.
        $home_host = strtolower((string) wp_parse_url(home_url('/'), PHP_URL_HOST));
        $is_local_host = ($home_host === 'localhost' || $home_host === '127.0.0.1' || (bool) preg_match('/\.(local|test|invalid)$/', $home_host));
        if ($is_local_host && defined('CMN_CV_CONVERTER_DEV_URL')) {
            $dev_url = trim((string) CMN_CV_CONVERTER_DEV_URL);
            if ($dev_url !== '' && preg_match('#^https?://#i', $dev_url)) {
                return esc_url_raw($dev_url);
            }
        }

        return esc_url_raw($plugin_bundle_url);
    }
    private function get_cv_converter_api_base_path() {
        $portal_api_base = (string) wp_parse_url($this->get_portal_base_url(), PHP_URL_PATH);
        $portal_api_base = trim($portal_api_base);
        if ($portal_api_base === '') {
            $portal_api_base = '/portal';
        }
        $portal_api_base = '/' . ltrim($portal_api_base, '/');
        $portal_api_base = rtrim($portal_api_base, '/');
        if ($portal_api_base === '') {
            $portal_api_base = '/portal';
        }
        return $portal_api_base;
    }

    private function send_cv_converter_api_json($payload, $status_code = 200) {
        status_header((int) $status_code);
        nocache_headers();
        header('Content-Type: application/json; charset=utf-8');
        echo wp_json_encode($payload);
        exit;
    }

    private function get_cv_converter_api_route() {
        $path = wp_parse_url((string) ($_SERVER['REQUEST_URI'] ?? ''), PHP_URL_PATH);
        $path = strtolower(trim((string) $path));
        if ($path === '') {
            return '';
        }
        $path = rtrim($path, '/');
        if (substr($path, -12) === '/api/convert') {
            return 'convert';
        }
        if (substr($path, -11) === '/api/export') {
            return 'export';
        }
        return '';
    }

    public function handle_cv_converter_api_endpoints() {
        $route = $this->get_cv_converter_api_route();
        if ($route === '') {
            return;
        }

        try {
            if (strtoupper((string) ($_SERVER['REQUEST_METHOD'] ?? 'GET')) !== 'POST') {
                $this->send_cv_converter_api_json([
                    'ok' => false,
                    'error' => 'Method not allowed.',
                ], 405);
            }
            if (!is_user_logged_in()) {
                $this->send_cv_converter_api_json([
                    'ok' => false,
                    'error' => 'Unauthorized.',
                ], 403);
            }
            $user_id = (int) get_current_user_id();
            if (!$this->user_can_manage_cv_converter($user_id)) {
                $this->send_cv_converter_api_json([
                    'ok' => false,
                    'error' => 'Unauthorized.',
                ], 403);
            }

            if ($route === 'convert') {
                if (empty($_FILES['cv']) || !is_array($_FILES['cv'])) {
                    $this->send_cv_converter_api_json([
                        'ok' => false,
                        'error' => 'CV upload is required.',
                    ], 400);
                }
                $cv_file = $_FILES['cv'];
                if (!empty($cv_file['error'])) {
                    $this->send_cv_converter_api_json([
                        'ok' => false,
                        'error' => 'Upload failed: ' . sanitize_text_field((string) $cv_file['error']),
                    ], 400);
                }
                $tmp_path = (string) ($cv_file['tmp_name'] ?? '');
                if ($tmp_path === '' || !file_exists($tmp_path)) {
                    $this->send_cv_converter_api_json([
                        'ok' => false,
                        'error' => 'Uploaded file not found.',
                    ], 400);
                }

                $candidate_id = isset($_REQUEST['candidate_id']) ? (int) $_REQUEST['candidate_id'] : 0;
                $portal_token = sanitize_text_field((string) ($_REQUEST['portal_token'] ?? ''));
                if ($candidate_id > 0) {
                    if (get_post_type($candidate_id) !== 'cmn_candidate') {
                        $this->send_cv_converter_api_json([
                            'ok' => false,
                            'error' => 'Candidate not found.',
                        ], 404);
                    }
                    if (!$this->user_can_view_candidate($candidate_id, $user_id)) {
                        $this->send_cv_converter_api_json([
                            'ok' => false,
                            'error' => 'Access restricted for this candidate.',
                        ], 403);
                    }
                    if ($portal_token !== '') {
                        $token_check = $this->validate_cv_converter_token($portal_token, $candidate_id, $user_id);
                        if (is_wp_error($token_check)) {
                            $this->send_cv_converter_api_json([
                                'ok' => false,
                                'error' => (string) $token_check->get_error_message(),
                            ], 403);
                        }
                    }
                }

                $parse_result = $this->parse_cv_converter_upload_text(
                    $tmp_path,
                    (string) ($cv_file['name'] ?? 'candidate_cv'),
                    (string) ($cv_file['type'] ?? '')
                );
                $raw_text = trim((string) ($parse_result['text'] ?? ''));
                $warnings = (array) ($parse_result['warnings'] ?? []);

                $candidate_name = $candidate_id > 0 ? trim((string) get_the_title($candidate_id)) : '';
                if ($candidate_name === '') {
                    $candidate_name = preg_replace('/\.[a-z0-9]+$/i', '', sanitize_file_name((string) ($cv_file['name'] ?? 'Candidate CV')));
                    $candidate_name = ucwords(str_replace(['-', '_'], ' ', (string) $candidate_name));
                }
                if ($candidate_name === '') {
                    $candidate_name = 'Candidate';
                }

                $candidate_title = 'Education Professional';
                $candidate_location = '';
                if ($candidate_id > 0) {
                    $candidate_location = sanitize_text_field((string) get_post_meta($candidate_id, 'cmn_location', true));
                }

                $logo_data_uri = '';
                if (!empty($_FILES['logo']) && is_array($_FILES['logo']) && empty($_FILES['logo']['error'])) {
                    $logo_tmp_path = (string) ($_FILES['logo']['tmp_name'] ?? '');
                    if ($logo_tmp_path !== '' && file_exists($logo_tmp_path)) {
                        $logo_mime = strtolower(trim((string) ($_FILES['logo']['type'] ?? '')));
                        if (!preg_match('#^image/(png|jpe?g|gif|webp|svg\+xml)$#', $logo_mime)) {
                            $logo_mime = 'image/png';
                        }
                        $logo_bytes = (string) @file_get_contents($logo_tmp_path);
                        if ($logo_bytes !== '') {
                            $logo_data_uri = 'data:' . $logo_mime . ';base64,' . base64_encode($logo_bytes);
                        }
                    }
                }

                $render_payload = $this->build_cv_converter_render_payload(
                    $raw_text,
                    $candidate_name,
                    $candidate_title,
                    $candidate_location,
                    $logo_data_uri
                );

                $candidate_name = (string) ($render_payload['candidate_name'] ?? $candidate_name);
                $candidate_title = (string) ($render_payload['candidate_title'] ?? $candidate_title);
                $candidate_location = (string) ($render_payload['location'] ?? $candidate_location);

                if ($raw_text === '') {
                    $warnings[] = 'Could not extract text from this file. Use the editor to complete the formatted CV.';
                }
                foreach ((array) ($render_payload['warnings'] ?? []) as $extra_warning) {
                    $extra_warning = sanitize_text_field((string) $extra_warning);
                    if ($extra_warning !== '' && !in_array($extra_warning, $warnings, true)) {
                        $warnings[] = $extra_warning;
                    }
                }

                $html_content = $this->build_cv_converter_html_template($render_payload);

                $overall_confidence = isset($render_payload['overall_confidence']) ? (float) $render_payload['overall_confidence'] : ($raw_text !== '' ? 0.65 : 0.25);
                if ($overall_confidence < 0) {
                    $overall_confidence = 0;
                }
                if ($overall_confidence > 1) {
                    $overall_confidence = 1;
                }
                $confidence_label = $overall_confidence >= 0.75 ? 'high' : ($overall_confidence >= 0.45 ? 'medium' : 'low');

                $this->send_cv_converter_api_json([
                    'ok' => true,
                    'candidate_name' => $candidate_name,
                    'candidate_title' => $candidate_title,
                    'candidate_location' => $candidate_location,
                    'confidence' => $confidence_label,
                    'overall_confidence' => $overall_confidence,
                    'warnings' => $warnings,
                    'html_content' => $html_content,
                    'pdf_download_url' => '',
                    'html_download_url' => '',
                ], 200);
            }

            $raw_json = file_get_contents('php://input');
            $payload = json_decode((string) $raw_json, true);
            if (!is_array($payload)) {
                $this->send_cv_converter_api_json([
                    'ok' => false,
                    'error' => 'Invalid export payload.',
                ], 400);
            }
            $html_content = (string) ($payload['html_content'] ?? '');
            if (trim($html_content) === '') {
                $this->send_cv_converter_api_json([
                    'ok' => false,
                    'error' => 'Nothing to export.',
                ], 400);
            }
            $base_name = sanitize_file_name((string) ($payload['base_name'] ?? 'CANDIDATE_CMN_CV'));
            if ($base_name === '') {
                $base_name = 'CANDIDATE_CMN_CV';
            }
            $portal_mode = !empty($payload['portal_mode']);

            $plain_text = trim((string) wp_strip_all_tags($html_content));
            if ($plain_text === '') {
                $plain_text = 'CoverMeNow CV export';
            }
            $pdf_binary = $this->generate_cv_converter_pdf_binary($base_name, $plain_text);
            $pdf_filename = $base_name . '.pdf';
            $html_filename = $base_name . '.html';
            $pdf_base64 = base64_encode($pdf_binary);
            $html_base64 = base64_encode($html_content);

            if ($portal_mode) {
                $this->send_cv_converter_api_json([
                    'ok' => true,
                    'pdf_base64' => $pdf_base64,
                    'html_base64' => $html_base64,
                    'pdf_filename' => $pdf_filename,
                    'html_filename' => $html_filename,
                ], 200);
            }

            $this->send_cv_converter_api_json([
                'ok' => true,
                'pdf_download_url' => 'data:application/pdf;base64,' . $pdf_base64,
                'html_download_url' => 'data:text/html;base64,' . $html_base64,
                'pdf_filename' => $pdf_filename,
                'html_filename' => $html_filename,
            ], 200);
        } catch (Throwable $e) {
            error_log('[CMN_CV_CONVERTER_API] ' . $e->getMessage());
            $this->send_cv_converter_api_json([
                'ok' => false,
                'error' => 'Converter service error.',
            ], 500);
        }
    }

    private function parse_cv_converter_upload_text($file_path, $original_name = '', $mime_type = '') {
        $file_path = (string) $file_path;
        $original_name = (string) $original_name;
        $mime_type = strtolower(trim((string) $mime_type));
        $ext = strtolower((string) pathinfo($original_name, PATHINFO_EXTENSION));
        $warnings = [];
        $text = '';

        if ($ext === '') {
            if (strpos($mime_type, 'pdf') !== false) {
                $ext = 'pdf';
            } elseif (strpos($mime_type, 'wordprocessingml') !== false || strpos($mime_type, 'msword') !== false) {
                $ext = 'docx';
            } elseif (strpos($mime_type, 'text') !== false) {
                $ext = 'txt';
            }
        }

        if ($ext === 'txt') {
            $text = (string) file_get_contents($file_path);
        } elseif ($ext === 'docx') {
            $text = $this->extract_cv_converter_docx_text($file_path);
        } elseif ($ext === 'pdf') {
            $text = $this->extract_cv_converter_pdf_text($file_path);
            if (trim($text) === '') {
                $warnings[] = 'PDF text extraction was limited for this file.';
            }
        } else {
            $warnings[] = 'Unsupported file type detected. Please use PDF, DOCX, or TXT.';
        }

        $text = preg_replace("/\r\n?/", "\n", (string) $text);
        $text = preg_replace('/[ \t]+/', ' ', (string) $text);
        $text = preg_replace("/\n{3,}/", "\n\n", (string) $text);
        $text = trim((string) $text);

        return [
            'text' => $text,
            'warnings' => $warnings,
        ];
    }

    private function extract_cv_converter_docx_text($file_path) {
        if (!class_exists('ZipArchive')) {
            return '';
        }
        $zip = new ZipArchive();
        if ($zip->open($file_path) !== true) {
            return '';
        }
        $xml = (string) $zip->getFromName('word/document.xml');
        $zip->close();
        if ($xml === '') {
            return '';
        }
        $xml = str_replace(['</w:p>', '</w:tr>', '</w:br>'], "\n", $xml);
        $xml = preg_replace('/<[^>]+>/', '', $xml);
        return html_entity_decode((string) $xml, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    }

    private function extract_cv_converter_pdf_text($file_path) {
        $text = '';
        $command = '';
        if (function_exists('shell_exec')) {
            $command = trim((string) @shell_exec('command -v pdftotext 2>/dev/null'));
        }
        if ($command !== '') {
            $tmp_out = wp_tempnam('cmn_cv_text_');
            if ($tmp_out) {
                @shell_exec(escapeshellarg($command) . ' -layout ' . escapeshellarg($file_path) . ' ' . escapeshellarg($tmp_out) . ' 2>/dev/null');
                if (file_exists($tmp_out)) {
                    $text = (string) file_get_contents($tmp_out);
                    @unlink($tmp_out);
                }
            }
        }
        if (trim($text) !== '') {
            return $text;
        }

        $raw = (string) @file_get_contents($file_path);
        if ($raw === '') {
            return '';
        }
        $matches = [];
        preg_match_all('/\(([^\(\)]{2,300})\)/', $raw, $matches);
        if (empty($matches[1])) {
            return '';
        }
        $lines = array_map(static function ($line) {
            $line = str_replace(['\\n', '\\r', '\\t'], ' ', (string) $line);
            $line = str_replace(['\\(', '\\)'], ['(', ')'], (string) $line);
            return trim((string) $line);
        }, (array) $matches[1]);
        $lines = array_values(array_filter($lines, static function ($line) {
            $len = function_exists('mb_strlen') ? mb_strlen((string) $line) : strlen((string) $line);
            return $len > 2;
        }));
        return implode("\n", $lines);
    }

    private function build_cv_converter_render_payload($raw_text, $candidate_name, $candidate_title = '', $location = '', $logo_data_uri = '') {
        $raw_text = trim((string) $raw_text);
        $candidate_name = sanitize_text_field((string) $candidate_name);
        $candidate_title = sanitize_text_field((string) $candidate_title);
        $location = sanitize_text_field((string) $location);
        $logo_data_uri = trim((string) $logo_data_uri);
        $warnings = [];

        $normalized_lines = $this->cv_converter_normalize_lines($raw_text);
        $sections = $this->cv_converter_split_sections($normalized_lines);
        $header_identity = $this->cv_converter_extract_header_identity((array) ($sections['header'] ?? []));

        $extracted_name = sanitize_text_field((string) ($header_identity['name'] ?? ''));
        $extracted_title = sanitize_text_field((string) ($header_identity['title'] ?? ''));
        if ($candidate_name === '' || strtolower($candidate_name) === 'candidate') {
            if ($extracted_name !== '') {
                $candidate_name = $extracted_name;
            }
        }
        if ($candidate_name === '') {
            $candidate_name = 'Candidate';
        }

        $generic_titles = ['education professional', 'candidate title', 'candidate'];
        if ($candidate_title === '' || in_array(strtolower($candidate_title), $generic_titles, true)) {
            if ($extracted_title !== '') {
                $candidate_title = $extracted_title;
            }
        }
        if ($candidate_title === '') {
            $candidate_title = 'Education Professional';
        }

        $extracted_location = $this->cv_converter_extract_location($normalized_lines);
        if ($location === '' && $extracted_location !== '') {
            $location = $extracted_location;
        }
        if ($location === '') {
            $location = 'Location';
        }

        $profile_text = $this->cv_converter_extract_profile_text($sections, $raw_text, $candidate_name);
        if ($profile_text === '') {
            $profile_text = 'PULLED FROM THEIR PERSONAL SUMMARY';
        }

        $strength_patterns = [
            'Communication' => '\\bcommunicat(?:e|ion|ing|or)\\b|active listening|clear (?:written|verbal)',
            'Rapport Building' => '\\brapport\\b|build(?:ing)? positive relationships?|strong relationships? with (?:pupils|students|children|parents|families)|trusted adult',
            'Classroom Management' => '\\bclassroom management\\b|manage(?:d|s|ing)? (?:a )?classroom',
            'Behaviour Management' => '\\bbehavio[u]?r management\\b|positive behavio[u]?r support|de[- ]escalat(?:e|ion|ing)|restorative practice',
            'Pupil Engagement' => '\\b(?:pupil|student|learner) engagement\\b|engag(?:e|ed|ing) learners?|increas(?:e|ed|ing) participation',
            'Safeguarding Awareness' => '\\bsafeguard(?:ing)?\\b|child protection|(?:pupil|student) welfare',
            'Inclusion and SEN Awareness' => '\\binclusive (?:practice|teaching|classrooms?)\\b|\\b(?:sen|send)\\b|special educational needs',
            'Differentiation' => '\\bdifferentiat(?:e|ed|ion|ing)\\b|adapt(?:ed|ing)? lessons?',
            'Assessment and Progress Tracking' => '\\bassessment\\b|progress tracking|monitor(?:ing|ed) progress|marking\\b',
            'Lesson Planning' => '\\blesson planning?\\b|scheme of work',
            'Pastoral Care' => '\\bpastoral\\b|wellbeing support|emotional support',
            'Parent Partnership' => '\\bparent(?:al)? (?:communication|engagement|liaison|partnership)\\b|famil(?:y|ies) liaison',
            'Patience' => '\\bpatient|patience\\b',
            'Empathy' => '\\bempath(?:y|etic)\\b',
            'Adaptability' => '\\badapt(?:ability|able|ing)\\b',
            'Organisation' => '\\borganis(?:ation|ed|ing|e)|organiz(?:ation|ed|ing|e)\\b',
            'Teamwork' => '\\bteam(?:work)?|collaborat(?:e|ion|ive)\\b',
            'Leadership' => '\\blead(?:er|ership|ing)\\b',
            'Reliability' => '\\breliable|dependable\\b',
            'Problem Solving' => '\\bproblem[- ]solv(?:e|ing)\\b',
            'Resilience' => '\\bresilien(?:ce|t)\\b',
            'Creativity' => '\\bcreativ(?:e|ity)\\b|innovative',
        ];
        $skill_patterns = [
            'Safeguarding' => '\\bsafeguard(?:ing)?|child protection\\b',
            'Classroom Management' => '\\bclassroom management\\b',
            'Behaviour Management' => '\\bbehavio[u]?r management\\b',
            'SEN/SEND Support' => '\\b(?:sen|send)\\b|special educational needs',
            'Lesson Planning' => '\\blesson planning?\\b',
            'Curriculum Delivery' => '\\bcurriculum\\b',
            'Phonics' => '\\bphonics?\\b',
            'Differentiation' => '\\bdifferentiat(?:e|ion|ing)\\b',
            'Assessment and Progress Tracking' => '\\b(assessment|progress tracking|marking)\\b',
            'Pastoral Support' => '\\bpastoral\\b',
            'Parent Communication' => '\\bparent(?:al)? (?:communication|engagement|liaison)\\b',
            'One-to-one Learner Support' => '\\bone[- ]to[- ]one\\b',
            'Child Development' => '\\bchild(?:ren)? development\\b',
            'Sales' => '\\bsales\\b',
            'Account Management' => '\\baccount management|account manager\\b',
            'Business Development' => '\\bbusiness development\\b',
            'Customer Relations' => '\\bcustomer relations?\\b',
            'Team Leadership' => '\\bteam leadership\\b',
        ];
        $subject_patterns = [
            'Mathematics' => '\\b(maths?|mathematics|numeracy)\\b',
            'English' => '\\benglish\\b',
            'Science' => '\\bscience\\b',
            'Biology' => '\\bbiology\\b',
            'Chemistry' => '\\bchemistry\\b',
            'Physics' => '\\bphysics\\b',
            'History' => '\\bhistory\\b',
            'Geography' => '\\bgeography\\b',
            'Computer Science' => '\\b(computer science|ict|computing)\\b',
            'Art' => '\\bart\\b',
            'Music' => '\\bmusic\\b',
            'PE' => '\\b(pe|physical education|sport)\\b',
            'Religious Education' => '\\b(religious education|re)\\b',
            'French' => '\\bfrench\\b',
            'Spanish' => '\\bspanish\\b',
            'German' => '\\bgerman\\b',
        ];
        $child_skill_patterns = [
            'Safeguarding' => '\\bsafeguard(?:ing)?|child protection\\b',
            'Classroom Management' => '\\bclassroom management\\b',
            'Behaviour Management' => '\\bbehavio[u]?r management\\b',
            'SEN/SEND Support' => '\\b(?:sen|send)\\b|special educational needs\\b',
            'Lesson Planning' => '\\blesson planning?\\b',
            'Curriculum Delivery' => '\\bcurriculum\\b',
            'Phonics' => '\\bphonics?\\b',
            'Differentiation' => '\\bdifferentiat(?:e|ion|ing)\\b',
            'Assessment and Progress Tracking' => '\\b(assessment|progress tracking|marking)\\b',
            'Pastoral Support' => '\\bpastoral\\b',
            'Parent Communication' => '\\b(parent(?:al)? (?:communication|engagement|liaison))\\b',
            'One-to-one Learner Support' => '\\bone[- ]to[- ]one\\b',
        ];

        $strengths_section = $this->cv_converter_extract_list_items((array) ($sections['strengths'] ?? []));
        $skills_section = $this->cv_converter_extract_list_items((array) ($sections['skills'] ?? []));
        $key_info_section = $this->cv_converter_extract_list_items((array) ($sections['key_info'] ?? []));

        $context_chunks = [$profile_text];
        foreach (['work_experience', 'skills', 'key_info', 'header'] as $section_key) {
            if (!empty($sections[$section_key])) {
                $context_chunks[] = implode(' ', (array) $sections[$section_key]);
            }
        }
        $strength_context = trim((string) implode(' ', $context_chunks));

        $strengths_ranked = $this->cv_converter_extract_pattern_labels_ranked($strength_context, $strength_patterns);
        $strengths_clause = $this->cv_converter_extract_statement_clause_items($profile_text, 'strengths', $strength_patterns);
        $strengths = $this->cv_converter_merge_unique(array_merge($strengths_ranked, $strengths_clause, $strengths_section), 10);
        if (empty($strengths)) {
            $strengths = [
                'Communication',
                'Teamwork',
                'Leadership',
                'Organisation',
                'Creativity',
            ];
        }

        $skills_ranked = $this->cv_converter_extract_pattern_labels_ranked($strength_context, $skill_patterns);
        $skills_clause = $this->cv_converter_extract_statement_clause_items($profile_text, 'skills', $skill_patterns);
        $skills = $this->cv_converter_merge_unique(array_merge($skills_ranked, $skills_clause, $skills_section), 10);
        if (empty($skills)) {
            $skills = [
                'Classroom Support',
                'Behaviour Management',
                'Safeguarding Awareness',
                'Lesson Delivery Support',
                'Parent Communication',
            ];
        }

        $key_info = $this->cv_converter_build_key_info($raw_text, $profile_text, $key_info_section, $subject_patterns, $child_skill_patterns);
        if (empty($key_info)) {
            $key_info = [
                'Flexible and reliable support across key stages.',
                'Strong classroom behaviour and safeguarding awareness.',
                'Confident building positive relationships with pupils and staff.',
            ];
        }

        $work_lines = (array) ($sections['work_experience'] ?? []);
        $experience = $this->cv_converter_extract_experience_entries($work_lines);
        if (empty($experience)) {
            $experience = $this->cv_converter_extract_experience_entries($normalized_lines);
        }
        if (!empty($experience)) {
            $sanitized_experience = [];
            foreach ($experience as $entry) {
                if (!is_array($entry)) {
                    continue;
                }
                $company = sanitize_text_field((string) ($entry['company'] ?? ''));
                $role = sanitize_text_field((string) ($entry['role'] ?? ''));
                $date_range = sanitize_text_field((string) ($entry['date_range'] ?? ''));
                $bullets = [];
                foreach ((array) ($entry['bullets'] ?? []) as $bullet) {
                    $bullet = sanitize_text_field((string) $bullet);
                    if ($bullet === '') {
                        continue;
                    }
                    $bullets[] = $bullet;
                    if (count($bullets) >= 30) {
                        break;
                    }
                }
                if ($company === '' && $role !== '') {
                    $company = $role;
                    $role = '';
                }
                if ($role === '' && !empty($bullets)) {
                    $role = 'Overview';
                }
                if ($company === '' && empty($bullets) && $date_range === '') {
                    continue;
                }
                $sanitized_experience[] = [
                    'company' => $company !== '' ? $company : 'Previous School',
                    'role' => $role,
                    'date_range' => $date_range,
                    'bullets' => $bullets,
                ];
                if (count($sanitized_experience) >= 12) {
                    break;
                }
            }
            $experience = $sanitized_experience;
        }
        if (empty($experience)) {
            $experience = [
                [
                    'company' => 'Previous School',
                    'date_range' => 'Recent',
                    'role' => 'Role title',
                    'bullets' => [
                        'Delivered day-to-day classroom support across mixed year groups and subjects.',
                        'Followed school safeguarding and behaviour policies while maintaining a calm learning environment.',
                        'Built positive relationships with pupils, teachers, and support staff to ensure continuity.',
                    ],
                ],
            ];
            $warnings[] = 'Could not extract enough structured experience from the uploaded file.';
        }

        $education = $this->cv_converter_extract_education_entries((array) ($sections['education'] ?? []));
        if (empty($education)) {
            $education_candidate_lines = array_values(array_filter($normalized_lines, static function ($line) {
                return preg_match('/\\b(gcse|a[- ]level|bachelor|master|degree|college|university|certificate|diploma|nvq|pgce|qts)\\b/i', (string) $line);
            }));
            $education = $this->cv_converter_extract_education_entries($education_candidate_lines);
        }
        if (!empty($education)) {
            $sanitized_education = [];
            foreach ($education as $entry) {
                if (!is_array($entry)) {
                    continue;
                }
                $qualification = sanitize_text_field((string) ($entry['qualification'] ?? ''));
                $institution = sanitize_text_field((string) ($entry['institution'] ?? ''));
                $date_range = sanitize_text_field((string) ($entry['date_range'] ?? ''));
                if ($qualification === '' && $institution === '' && $date_range === '') {
                    continue;
                }
                $sanitized_education[] = [
                    'qualification' => $qualification !== '' ? $qualification : 'Education & Training',
                    'institution' => $institution,
                    'date_range' => $date_range,
                ];
                if (count($sanitized_education) >= 6) {
                    break;
                }
            }
            $education = $sanitized_education;
        }
        if (empty($education)) {
            $education = [
                [
                    'qualification' => 'Education & Training',
                    'date_range' => 'Details on request',
                    'institution' => 'Please update with highest relevant qualification',
                ],
            ];
        }

        // Contact details stay fixed for AM details in the CMN template.
        $contact_phone = '07438 766-542';
        $contact_email = 'jay.norton@covermenow.co.uk';

        $confidence_seed = [
            'candidate_name' => $candidate_name,
            'candidate_title' => in_array(strtolower($candidate_title), $generic_titles, true) ? '' : $candidate_title,
            'location' => strtolower($location) === 'location' ? '' : $location,
            'profile_text' => $profile_text === 'PULLED FROM THEIR PERSONAL SUMMARY' ? '' : $profile_text,
            'key_info' => $key_info,
            'strengths' => $strengths,
            'skills' => $skills,
            'phone' => $contact_phone,
            'email' => $contact_email,
            'experience' => $experience,
            'education' => $education,
        ];
        $confidence_data = $this->cv_converter_estimate_payload_confidence($confidence_seed);
        $overall_confidence = (float) ($confidence_data['overall'] ?? 0.25);
        $field_confidence = (array) ($confidence_data['field_confidence'] ?? []);
        foreach ($field_confidence as $field => $score) {
            $score = (float) $score;
            if ($score < 0.6) {
                $warnings[] = 'Low confidence for ' . str_replace('_', ' ', (string) $field);
            }
        }
        if (empty($work_lines) && !empty($experience)) {
            $warnings[] = 'Work experience was inferred from unstructured CV text.';
        }
        $warnings = array_values(array_unique(array_filter(array_map(static function ($warning) {
            return sanitize_text_field((string) $warning);
        }, $warnings), static function ($warning) {
            return $warning !== '';
        })));

        return [
            'candidate_name' => $candidate_name,
            'candidate_title' => $candidate_title,
            'location' => $location,
            'profile_text' => $profile_text,
            'key_info' => $key_info,
            'strengths' => $strengths,
            'skills' => $skills,
            'experience' => $experience,
            'education' => $education,
            'phone' => $contact_phone,
            'email' => $contact_email,
            'footer_cta_text' => 'Get in touch to discuss your next opportunity.',
            'primary_red' => '#D1001C',
            'overall_confidence' => $overall_confidence,
            'warnings' => $warnings,
            'logo_data_uri' => $logo_data_uri !== '' ? $logo_data_uri : $this->get_cv_converter_default_logo_data_uri(),
        ];
    }

    private function cv_converter_strlen($value) {
        return function_exists('mb_strlen') ? mb_strlen((string) $value) : strlen((string) $value);
    }

    private function cv_converter_normalize_lines($text) {
        $text = preg_replace("/\r\n?/", "\n", (string) $text);
        $raw_lines = preg_split('/\n+/', (string) $text) ?: [];
        $lines = [];
        foreach ($raw_lines as $raw_line) {
            $line = trim((string) preg_replace('/\s+/', ' ', str_replace("\t", ' ', (string) $raw_line)));
            if ($line === '') {
                continue;
            }
            $lines[] = $line;
        }
        return $lines;
    }

    private function cv_converter_section_aliases() {
        return [
            'profile' => ['PROFILE', 'SUMMARY', 'ABOUT', 'ABOUT ME', 'PERSONAL PROFILE', 'PERSONAL STATEMENT', 'PROFESSIONAL SUMMARY'],
            'work_experience' => ['WORK EXPERIENCE', 'EXPERIENCE', 'EMPLOYMENT HISTORY', 'CAREER HISTORY', 'PROFESSIONAL EXPERIENCE'],
            'education' => ['EDUCATION', 'QUALIFICATIONS', 'ACADEMIC BACKGROUND'],
            'key_info' => ['KEY INFO', 'KEY INFORMATION', 'INFO'],
            'strengths' => ['STRENGTHS', 'CORE STRENGTHS', 'KEY STRENGTHS'],
            'skills' => ['SKILLS', 'CORE SKILLS', 'TECHNICAL SKILLS', 'SKILLSET'],
            'contact' => ['CONTACT', 'CONTACT DETAILS', 'CONTACT INFORMATION'],
        ];
    }

    private function cv_converter_normalize_heading($line) {
        $line = strtoupper((string) $line);
        $line = preg_replace('/[^A-Z ]+/', ' ', (string) $line);
        $line = preg_replace('/\s+/', ' ', (string) $line);
        return trim((string) $line);
    }

    private function cv_converter_detect_section($line, $aliases = []) {
        $heading = $this->cv_converter_normalize_heading($line);
        if ($heading === '') {
            return '';
        }
        foreach ((array) $aliases as $section => $section_aliases) {
            foreach ((array) $section_aliases as $alias) {
                $alias = strtoupper(trim((string) $alias));
                if ($alias === '') {
                    continue;
                }
                if ($heading === $alias) {
                    return (string) $section;
                }
                if (strpos($heading, $alias . ' ') === 0) {
                    return (string) $section;
                }
            }
        }
        return '';
    }

    private function cv_converter_split_sections($lines) {
        $aliases = $this->cv_converter_section_aliases();
        $sections = ['header' => []];
        $current = 'header';
        foreach ((array) $lines as $line) {
            $detected = $this->cv_converter_detect_section($line, $aliases);
            if ($detected !== '') {
                $current = $detected;
                if (!isset($sections[$current])) {
                    $sections[$current] = [];
                }
                continue;
            }
            if (!isset($sections[$current])) {
                $sections[$current] = [];
            }
            $sections[$current][] = (string) $line;
        }
        return $sections;
    }

    private function cv_converter_extract_date_range($line) {
        if (preg_match('/((?:[A-Za-z]{3,9}\s+\d{4}|\d{4})\s*(?:-|-|-|to)\s*(?:present|current|[A-Za-z]{3,9}\s+\d{4}|\d{4}))/i', (string) $line, $match)) {
            return trim((string) ($match[1] ?? ''));
        }
        return '';
    }

    private function cv_converter_first_name_only($full_name) {
        preg_match_all("/[A-Za-z][A-Za-z'-]*/", (string) $full_name, $tokens);
        $tokens = (array) ($tokens[0] ?? []);
        $honorifics = ['mr', 'mrs', 'ms', 'miss', 'dr', 'prof', 'sir'];
        foreach ($tokens as $token) {
            if (!in_array(strtolower((string) $token), $honorifics, true)) {
                return sanitize_text_field((string) $token);
            }
        }
        return sanitize_text_field((string) ($tokens[0] ?? trim((string) $full_name)));
    }

    private function cv_converter_extract_header_identity($header_lines) {
        $header_lines = array_slice((array) $header_lines, 0, 6);
        $filtered = [];
        foreach ($header_lines as $line) {
            $line = trim((string) $line);
            if ($line === '') {
                continue;
            }
            if (preg_match('/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/', $line)) {
                continue;
            }
            if (preg_match('/(?:(?:\+?\d{1,3}[\s.-]?)?(?:\(\d{2,4}\)[\s.-]?)?\d[\d\s().-]{7,}\d)/', $line)) {
                continue;
            }
            if ($this->cv_converter_extract_date_range($line) !== '') {
                continue;
            }
            $filtered[] = $line;
        }
        $name = '';
        $title = '';
        if (!empty($filtered)) {
            $name = $this->cv_converter_first_name_only((string) $filtered[0]);
        }
        foreach (array_slice($filtered, 1) as $line) {
            if ($this->cv_converter_strlen($line) > 90) {
                continue;
            }
            if (preg_match('/[@\d]/', (string) $line)) {
                continue;
            }
            $word_count = count(array_filter(preg_split('/\s+/', (string) $line) ?: []));
            if ($word_count > 0 && $word_count <= 10) {
                $title = sanitize_text_field((string) $line);
                break;
            }
        }
        return [
            'name' => $name,
            'title' => $title,
        ];
    }

    private function cv_converter_extract_location($lines) {
        foreach ((array) $lines as $line) {
            $line = trim((string) $line);
            if ($line === '') {
                continue;
            }
            if (preg_match('/\b(location|based in)\b/i', $line)) {
                $value = $line;
                if (strpos($line, ':') !== false) {
                    $parts = explode(':', $line, 2);
                    $value = (string) ($parts[1] ?? '');
                }
                $value = preg_replace('/^(location|based in)\s*/i', '', (string) $value);
                $value = trim((string) preg_replace('/\s+/', ' ', (string) $value), " \t\n\r\0\x0B,.-");
                if ($value !== '' && $this->cv_converter_strlen($value) <= 90) {
                    return sanitize_text_field((string) $value);
                }
            }
        }
        foreach ((array) $lines as $line) {
            $line = trim((string) $line);
            if ($line === '') {
                continue;
            }
            if (strpos($line, '@') === false && !preg_match('/(?:(?:\+?\d{1,3}[\s.-]?)?(?:\(\d{2,4}\)[\s.-]?)?\d[\d\s().-]{7,}\d)/', $line)) {
                continue;
            }
            $candidate = preg_replace('/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/', ' ', $line);
            $candidate = preg_replace('/(?:(?:\+?\d{1,3}[\s.-]?)?(?:\(\d{2,4}\)[\s.-]?)?\d[\d\s().-]{7,}\d)/', ' ', (string) $candidate);
            $candidate = preg_replace('/^(title|location|based in)\s*:\s*/i', '', (string) $candidate);
            $candidate = trim((string) preg_replace('/\s+/', ' ', (string) $candidate), " \t\n\r\0\x0B,.-");
            if ($candidate !== '' && $this->cv_converter_strlen($candidate) <= 90) {
                return sanitize_text_field((string) $candidate);
            }
        }
        foreach ((array) $lines as $line) {
            if (strpos((string) $line, '@') !== false) {
                continue;
            }
            if (preg_match('/\b(uk|england|scotland|wales|london|hampshire|surrey|fareham|portsmouth|southampton|manchester|birmingham|liverpool|leeds|bristol)\b/i', (string) $line)) {
                $cleaned = sanitize_text_field((string) $line);
                if ($cleaned !== '' && $this->cv_converter_strlen($cleaned) <= 90) {
                    return $cleaned;
                }
            }
        }
        return '';
    }

    private function cv_converter_extract_profile_text($sections, $raw_text, $candidate_name = '') {
        $profile_text = '';
        $profile_lines = (array) ($sections['profile'] ?? []);
        if (!empty($profile_lines)) {
            $profile_text = implode(' ', $profile_lines);
        } else {
            $header_lines = (array) ($sections['header'] ?? []);
            if (count($header_lines) > 2) {
                $profile_text = implode(' ', array_slice($header_lines, 2, 4));
            }
        }
        if (trim((string) $profile_text) === '' && trim((string) $raw_text) !== '') {
            $source = (string) $raw_text;
            $source = preg_replace('/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/', ' ', (string) $source);
            $source = preg_replace('/(?:(?:\+?\d{1,3}[\s.-]?)?(?:\(\d{2,4}\)[\s.-]?)?\d[\d\s().-]{7,}\d)/', ' ', (string) $source);
            $source = preg_replace('/\s+/', ' ', (string) $source);
            $sentences = preg_split('/(?<=[\.\!\?])\s+/', trim((string) $source)) ?: [];
            foreach ($sentences as $sentence) {
                $sentence = trim((string) $sentence);
                if ($sentence === '') {
                    continue;
                }
                $len = $this->cv_converter_strlen($sentence);
                if ($len < 40 || $len > 420) {
                    continue;
                }
                if (preg_match('/\b(curriculum vitae|cv|profile|contact details|mobile|phone|email)\b/i', $sentence)) {
                    continue;
                }
                $profile_text = $sentence;
                break;
            }
        }
        $profile_text = preg_replace('/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/', ' ', (string) $profile_text);
        $profile_text = preg_replace('/(?:(?:\+?\d{1,3}[\s.-]?)?(?:\(\d{2,4}\)[\s.-]?)?\d[\d\s().-]{7,}\d)/', ' ', (string) $profile_text);
        $profile_text = trim((string) preg_replace('/\s+/', ' ', (string) $profile_text));
        if ($candidate_name !== '') {
            $profile_text = preg_replace('/\b' . preg_quote((string) $candidate_name, '/') . '\b/i', '', (string) $profile_text);
            $profile_text = trim((string) preg_replace('/\s+/', ' ', (string) $profile_text));
        }
        return sanitize_text_field((string) $profile_text);
    }

    private function cv_converter_strip_bullet_prefix($line) {
        $line = (string) $line;
        $line = preg_replace('/^(?:[-*****]|\d+[.)])\s+/u', '', (string) $line);
        return trim((string) $line, " \t\n\r\0\x0B-****");
    }

    private function cv_converter_extract_list_items($lines) {
        $items = [];
        foreach ((array) $lines as $line) {
            $line = trim((string) $line);
            if ($line === '') {
                continue;
            }
            $cleaned = $this->cv_converter_strip_bullet_prefix($line);
            if ($cleaned === '') {
                continue;
            }
            if (preg_match('/^(?:[-*****]|\d+[.)])\s+/u', (string) $line)) {
                $items[] = $cleaned;
                continue;
            }
            if (substr_count($cleaned, ',') >= 2) {
                foreach (explode(',', $cleaned) as $part) {
                    $part = trim((string) $part);
                    if ($part !== '') {
                        $items[] = $part;
                    }
                }
                continue;
            }
            $items[] = $cleaned;
        }
        return $this->cv_converter_merge_unique($items);
    }

    private function cv_converter_merge_unique($items, $max_items = 0) {
        $seen = [];
        $merged = [];
        foreach ((array) $items as $item) {
            $item = trim((string) preg_replace('/\s+/', ' ', (string) $item));
            if ($item === '') {
                continue;
            }
            $key = strtolower($item);
            if (isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;
            $merged[] = $item;
            if ((int) $max_items > 0 && count($merged) >= (int) $max_items) {
                break;
            }
        }
        return $merged;
    }

    private function cv_converter_extract_pattern_labels($text, $patterns) {
        $labels = [];
        $text = (string) $text;
        foreach ((array) $patterns as $label => $pattern) {
            $pattern = (string) $pattern;
            if ($pattern === '') {
                continue;
            }
            if (@preg_match('/' . $pattern . '/i', $text)) {
                $labels[] = (string) $label;
            }
        }
        return $labels;
    }

    private function cv_converter_extract_pattern_labels_ranked($text, $patterns) {
        $scored = [];
        $text = (string) $text;
        $index = 0;
        foreach ((array) $patterns as $label => $pattern) {
            $pattern = (string) $pattern;
            if ($pattern === '') {
                $index++;
                continue;
            }
            $count = 0;
            if (@preg_match_all('/' . $pattern . '/i', $text, $matches)) {
                $count = count((array) ($matches[0] ?? []));
            }
            if ($count > 0) {
                $scored[] = [
                    'label' => (string) $label,
                    'count' => $count,
                    'index' => $index,
                ];
            }
            $index++;
        }
        usort($scored, static function ($a, $b) {
            $count_compare = (int) ($b['count'] ?? 0) <=> (int) ($a['count'] ?? 0);
            if ($count_compare !== 0) {
                return $count_compare;
            }
            return (int) ($a['index'] ?? 0) <=> (int) ($b['index'] ?? 0);
        });
        $labels = [];
        foreach ($scored as $row) {
            $labels[] = (string) ($row['label'] ?? '');
        }
        return $labels;
    }

    private function cv_converter_extract_statement_clause_items($profile_text, $mode, $pattern_map) {
        $profile_text = trim((string) $profile_text);
        if ($profile_text === '') {
            return [];
        }
        $mode = strtolower((string) $mode);
        if ($mode === 'skills') {
            $clause_patterns = [
                '/(?:skilled in|experienced in|experience in|proficient in|strong in|competent in)\s+([^.;]+)/i',
            ];
        } else {
            $clause_patterns = [
                '/(?:strengths include|known for|noted for|recognised for|recognized for|strong in|demonstrated in|proven in)\s+([^.;]+)/i',
            ];
        }
        $items = [];
        foreach ($clause_patterns as $regex) {
            if (!preg_match_all($regex, $profile_text, $matches)) {
                continue;
            }
            foreach ((array) ($matches[1] ?? []) as $clause) {
                $parts = preg_split('/,|\/|\band\b|\bor\b|\bwith\b|\bplus\b|\bas well as\b|\bincluding\b/i', (string) $clause) ?: [];
                foreach ($parts as $part) {
                    $part = trim((string) preg_replace('/\s+/', ' ', (string) $part), " .:-");
                    if ($part === '' || $this->cv_converter_strlen($part) < 3) {
                        continue;
                    }
                    $mapped = $this->cv_converter_extract_pattern_labels($part, (array) $pattern_map);
                    if (!empty($mapped)) {
                        $items[] = (string) $mapped[0];
                        continue;
                    }
                    if ($mode === 'strengths') {
                        $token_count = count(array_filter(preg_split('/\s+/', (string) $part) ?: []));
                        if ($token_count < 2) {
                            continue;
                        }
                    }
                    $items[] = ucwords(strtolower((string) $part));
                }
            }
        }
        return $this->cv_converter_merge_unique($items);
    }

    private function cv_converter_extract_dbs_line($text) {
        $text = strtolower((string) $text);
        $has_enhanced = (bool) preg_match('/\benhanced\s+dbs\b/', $text);
        $has_update_service = (bool) preg_match('/\bupdate\s+service\b/', $text);
        $pending = (bool) preg_match('/\b(dbs\s+pending|dbs\s+applied|awaiting\s+dbs)\b/', $text);
        $no_dbs = (bool) preg_match('/\b(no\s+dbs|without\s+dbs|does\s+not\s+have\s+dbs)\b/', $text);
        if ($has_enhanced && $has_update_service) {
            return 'Enhanced DBS on Update Service';
        }
        if ($pending) {
            return 'DBS pending';
        }
        if ($no_dbs) {
            return 'No DBS';
        }
        if ($has_enhanced) {
            return 'Enhanced DBS';
        }
        return '';
    }

    private function cv_converter_build_key_info($full_text, $profile_text, $existing_key_info, $subject_patterns, $child_skill_patterns) {
        $derived = [];
        $dbs_line = $this->cv_converter_extract_dbs_line($full_text);
        if ($dbs_line !== '') {
            $derived[] = $dbs_line;
        }
        $subjects = $this->cv_converter_extract_pattern_labels((string) $full_text, (array) $subject_patterns);
        if (!empty($subjects)) {
            $derived[] = 'Subjects: ' . implode(', ', array_slice($subjects, 0, 8));
        }
        $child_skills_source = trim((string) $profile_text) !== '' ? ((string) $profile_text . ' ' . (string) $full_text) : (string) $full_text;
        $child_skills = $this->cv_converter_extract_pattern_labels($child_skills_source, (array) $child_skill_patterns);
        if (!empty($child_skills)) {
            $derived[] = 'Child-focused skills: ' . implode(', ', array_slice($child_skills, 0, 8));
        }
        return $this->cv_converter_merge_unique(array_merge($derived, (array) $existing_key_info), 10);
    }

    private function cv_converter_looks_like_experience_start($line, $date_range) {
        if (trim((string) $date_range) !== '') {
            if ($this->cv_converter_is_date_only_line($line)) {
                return false;
            }
            return true;
        }
        if (strpos((string) $line, '|') !== false) {
            $parts = array_values(array_filter(array_map('trim', explode('|', (string) $line)), static function ($part) {
                return $part !== '';
            }));
            if (count($parts) >= 2) {
                return true;
            }
        }
        return false;
    }

    private function cv_converter_is_date_only_line($line) {
        $line = trim((string) $line);
        if ($line === '') {
            return false;
        }
        $line = trim((string) preg_replace('/^[\s\|\-–—]+|[\s\|\-–—]+$/u', '', (string) $line));
        if ($line === '') {
            return false;
        }
        return preg_match('/^(?:[A-Za-z]{3,9}\s+\d{4}|\d{4})\s*(?:-|-|-|to)\s*(?:present|current|[A-Za-z]{3,9}\s+\d{4}|\d{4})$/i', (string) $line) === 1;
    }

    private function cv_converter_line_looks_sentence_like($line) {
        $line = trim((string) $line);
        if ($line === '') {
            return false;
        }
        $word_count = count(array_filter(preg_split('/\s+/', (string) $line) ?: []));
        if ($word_count >= 14) {
            return true;
        }
        if (preg_match('/[.!?]$/', (string) $line)) {
            return true;
        }
        if (substr_count((string) $line, ',') >= 2 && $word_count >= 8) {
            return true;
        }
        return false;
    }

    private function cv_converter_line_looks_like_role($line) {
        $line = trim((string) $this->cv_converter_strip_bullet_prefix((string) $line));
        if ($line === '' || $this->cv_converter_line_looks_sentence_like($line)) {
            return false;
        }
        if (strpos((string) $line, '@') !== false) {
            return false;
        }
        $word_count = count(array_filter(preg_split('/\s+/', (string) $line) ?: []));
        if ($word_count < 1 || $word_count > 10) {
            return false;
        }
        if (preg_match('/\b(teacher|assistant|manager|consultant|coordinator|supervisor|officer|specialist|administrator|analyst|director|tutor|lecturer|head|lead|advisor|mentor|executive|recruiter|support|instructor|educator|trainer)\b/i', (string) $line)) {
            return true;
        }
        if (preg_match('/\b(school|academy|trust|college|university|ltd|limited|plc|llp|group|services|solutions|connect|centre|center|agency|company|organisation|organization|council)\b/i', (string) $line)) {
            return false;
        }
        $tokens = array_values(array_filter(preg_split('/\s+/', (string) $line) ?: []));
        $title_like = 0;
        foreach ($tokens as $token) {
            $first = substr((string) $token, 0, 1);
            if ($first !== '' && ctype_alpha($first) && strtoupper($first) === $first) {
                $title_like++;
            }
        }
        return $title_like >= min(3, max(2, $word_count - 1));
    }

    private function cv_converter_line_looks_like_company($line) {
        $line = trim((string) $this->cv_converter_strip_bullet_prefix((string) $line));
        if ($line === '' || $this->cv_converter_line_looks_sentence_like($line)) {
            return false;
        }
        if (strpos((string) $line, '@') !== false) {
            return false;
        }
        $word_count = count(array_filter(preg_split('/\s+/', (string) $line) ?: []));
        if ($word_count < 1 || $word_count > 12) {
            return false;
        }
        if (preg_match('/\b(school|academy|trust|college|university|ltd|limited|plc|llp|group|services|solutions|connect|centre|center|agency|company|organisation|organization|council)\b/i', (string) $line)) {
            return true;
        }
        return strtoupper((string) $line) === (string) $line && $word_count <= 6;
    }

    private function cv_converter_parse_experience_header($line, $date_range) {
        $line = (string) $line;
        $date_range = trim((string) $date_range);
        $working = $line;
        if ($date_range !== '') {
            $working = trim((string) str_replace($date_range, '', $working));
        }
        $working = trim((string) preg_replace('/^[\s\|\---]+|[\s\|\---]+$/u', '', (string) $working));
        if (strpos($working, '|') !== false) {
            $parts = array_values(array_filter(array_map('trim', explode('|', $working)), static function ($part) {
                return $part !== '';
            }));
            if (count($parts) >= 2) {
                return [
                    'company' => sanitize_text_field((string) $parts[0]),
                    'role' => sanitize_text_field((string) $parts[1]),
                    'date_range' => sanitize_text_field((string) $date_range),
                ];
            }
        }
        if (preg_match('/\s+at\s+/i', $working)) {
            $pieces = preg_split('/\s+at\s+/i', $working, 2) ?: [];
            if (count($pieces) === 2) {
                return [
                    'company' => sanitize_text_field((string) ($pieces[1] ?? '')),
                    'role' => sanitize_text_field((string) ($pieces[0] ?? '')),
                    'date_range' => sanitize_text_field((string) $date_range),
                ];
            }
        }
        return [
            'company' => sanitize_text_field((string) $working),
            'role' => '',
            'date_range' => sanitize_text_field((string) $date_range),
        ];
    }

    private function cv_converter_entry_has_content($entry) {
        if (!is_array($entry)) {
            return false;
        }
        return (
            trim((string) ($entry['company'] ?? '')) !== ''
            || trim((string) ($entry['role'] ?? '')) !== ''
            || trim((string) ($entry['date_range'] ?? '')) !== ''
            || !empty($entry['bullets'])
        );
    }

    private function cv_converter_finalize_experience_entry($entry) {
        if (!is_array($entry)) {
            return [
                'company' => '',
                'role' => '',
                'date_range' => '',
                'bullets' => [],
            ];
        }
        $bullets = [];
        foreach ((array) ($entry['bullets'] ?? []) as $bullet) {
            $bullet = sanitize_text_field((string) $bullet);
            if ($bullet === '') {
                continue;
            }
            $bullets[] = $bullet;
        }
        $company = sanitize_text_field((string) ($entry['company'] ?? ''));
        $role = sanitize_text_field((string) ($entry['role'] ?? ''));
        $date_range = sanitize_text_field((string) ($entry['date_range'] ?? ''));
        if ($company === '' && $role !== '') {
            $company = $role;
            $role = '';
        }
        if ($role === '' && !empty($bullets)) {
            $role = 'Overview';
        }
        return [
            'company' => $company,
            'role' => $role,
            'date_range' => $date_range,
            'bullets' => $bullets,
        ];
    }

    private function cv_converter_extract_experience_entries($lines) {
        $lines = (array) $lines;
        if (empty($lines)) {
            return [];
        }
        $normalized_lines = [];
        foreach ($lines as $raw_line) {
            $line = trim((string) $raw_line);
            if ($line === '') {
                continue;
            }
            $normalized_lines[] = $line;
        }
        if (empty($normalized_lines)) {
            return [];
        }

        $entries = [];
        $current = null;
        $line_count = count($normalized_lines);
        for ($i = 0; $i < $line_count; $i++) {
            $line = (string) $normalized_lines[$i];
            $next_line = ($i + 1 < $line_count) ? (string) $normalized_lines[$i + 1] : '';
            $date_range = $this->cv_converter_extract_date_range($line);

            // If bullets already exist, treat the next short header-like line as a new role.
            if (
                is_array($current)
                && !empty($current['bullets'])
                && !preg_match('/^(?:[-*****]|\d+[.)])\s+/u', (string) $line)
                && !$this->cv_converter_line_looks_sentence_like($line)
                && (
                    $this->cv_converter_line_looks_like_role($line)
                    || $this->cv_converter_line_looks_like_company($line)
                    || $this->cv_converter_extract_date_range($next_line) !== ''
                )
            ) {
                if ($this->cv_converter_entry_has_content($current)) {
                    $entries[] = $this->cv_converter_finalize_experience_entry((array) $current);
                }
                $current = null;
            }

            if ($this->cv_converter_looks_like_experience_start($line, $date_range)) {
                if (
                    is_array($current)
                    && $date_range !== ''
                    && $this->cv_converter_is_date_only_line($line)
                    && trim((string) ($current['date_range'] ?? '')) === ''
                    && (
                        trim((string) ($current['company'] ?? '')) !== ''
                        || trim((string) ($current['role'] ?? '')) !== ''
                    )
                ) {
                    $current['date_range'] = sanitize_text_field((string) $date_range);
                    continue;
                }
                if ($this->cv_converter_entry_has_content($current)) {
                    $entries[] = $this->cv_converter_finalize_experience_entry((array) $current);
                }
                $current = $this->cv_converter_parse_experience_header($line, $date_range);
                $current['bullets'] = [];
                continue;
            }
            if ($current === null) {
                $current = [
                    'company' => $this->cv_converter_line_looks_like_role($line) ? '' : sanitize_text_field((string) $line),
                    'role' => $this->cv_converter_line_looks_like_role($line) ? sanitize_text_field((string) $line) : '',
                    'date_range' => '',
                    'bullets' => [],
                ];
                continue;
            }
            if (preg_match('/^(?:[-*****]|\d+[.)])\s+/u', $line)) {
                $current['bullets'][] = $this->cv_converter_strip_bullet_prefix($line);
                continue;
            }
            if ((string) ($current['date_range'] ?? '') === '' && $date_range !== '') {
                $current['date_range'] = sanitize_text_field((string) $date_range);
                $remainder = trim((string) str_replace((string) $date_range, '', (string) $line));
                $remainder = trim((string) preg_replace('/^[\s\|\-–—]+|[\s\|\-–—]+$/u', '', (string) $remainder));
                if ($remainder !== '') {
                    if ((string) ($current['role'] ?? '') === '' && $this->cv_converter_line_looks_like_role($remainder)) {
                        $current['role'] = sanitize_text_field((string) $remainder);
                    } elseif ((string) ($current['company'] ?? '') === '' && $this->cv_converter_line_looks_like_company($remainder)) {
                        $current['company'] = sanitize_text_field((string) $remainder);
                    } else {
                        $current['bullets'][] = $this->cv_converter_strip_bullet_prefix($remainder);
                    }
                }
                continue;
            }
            if ((string) ($current['role'] ?? '') === '' && $this->cv_converter_line_looks_like_role($line)) {
                $current['role'] = sanitize_text_field((string) $line);
                continue;
            }
            if ((string) ($current['company'] ?? '') === '' && $this->cv_converter_line_looks_like_company($line)) {
                $current['company'] = sanitize_text_field((string) $line);
                continue;
            }
            $word_count = count(array_filter(preg_split('/\s+/', (string) $line) ?: []));
            if (
                (string) ($current['role'] ?? '') === ''
                && $word_count > 0
                && $word_count <= 8
                && strpos((string) $line, '@') === false
                && !$this->cv_converter_line_looks_sentence_like($line)
            ) {
                $current['role'] = sanitize_text_field((string) $line);
                continue;
            }
            if ((string) ($current['company'] ?? '') === '') {
                $current['company'] = sanitize_text_field((string) $line);
                continue;
            }
            $current['bullets'][] = $this->cv_converter_strip_bullet_prefix($line);
        }
        if ($this->cv_converter_entry_has_content($current)) {
            $entries[] = $this->cv_converter_finalize_experience_entry((array) $current);
        }
        $entries = array_values(array_filter($entries, static function ($entry) {
            if (!is_array($entry)) {
                return false;
            }
            return trim((string) ($entry['company'] ?? '')) !== '' || !empty($entry['bullets']);
        }));
        return $entries;
    }

    private function cv_converter_extract_education_entries($lines) {
        $lines = (array) $lines;
        if (empty($lines)) {
            return [];
        }
        $entries = [];
        $current = [
            'qualification' => '',
            'institution' => '',
            'date_range' => '',
        ];
        foreach ($lines as $raw_line) {
            $line = trim((string) $raw_line);
            if ($line === '') {
                continue;
            }
            $date_range = $this->cv_converter_extract_date_range($line);
            if ($date_range !== '' && ((string) $current['qualification'] !== '' || (string) $current['institution'] !== '')) {
                $current['date_range'] = sanitize_text_field((string) $date_range);
                $entries[] = $current;
                $current = [
                    'qualification' => '',
                    'institution' => '',
                    'date_range' => '',
                ];
                continue;
            }
            if ((string) $current['qualification'] === '') {
                $current['qualification'] = sanitize_text_field((string) $this->cv_converter_strip_bullet_prefix($line));
                continue;
            }
            if ((string) $current['institution'] === '') {
                $current['institution'] = sanitize_text_field((string) $this->cv_converter_strip_bullet_prefix($line));
                continue;
            }
            if ((string) $current['date_range'] === '' && $date_range !== '') {
                $current['date_range'] = sanitize_text_field((string) $date_range);
                continue;
            }
        }
        if ((string) $current['qualification'] !== '' || (string) $current['institution'] !== '' || (string) $current['date_range'] !== '') {
            $entries[] = $current;
        }
        $entries = array_values(array_filter($entries, static function ($entry) {
            if (!is_array($entry)) {
                return false;
            }
            return trim((string) ($entry['qualification'] ?? '')) !== '' || trim((string) ($entry['institution'] ?? '')) !== '';
        }));
        return $entries;
    }

    private function cv_converter_value_confidence($value) {
        return trim((string) $value) !== '' ? 0.85 : 0.25;
    }

    private function cv_converter_list_confidence($items) {
        $count = count((array) $items);
        if ($count < 1) {
            return 0.25;
        }
        if ($count >= 4) {
            return 0.9;
        }
        return 0.7;
    }

    private function cv_converter_estimate_payload_confidence($payload) {
        $payload = is_array($payload) ? $payload : [];
        $profile_words = preg_split('/\s+/', trim((string) ($payload['profile_text'] ?? ''))) ?: [];
        $profile_word_count = count(array_filter($profile_words, static function ($token) {
            return $token !== '';
        }));
        $field_confidence = [
            'candidate_name' => $this->cv_converter_value_confidence($payload['candidate_name'] ?? ''),
            'candidate_title' => $this->cv_converter_value_confidence($payload['candidate_title'] ?? ''),
            'location' => $this->cv_converter_value_confidence($payload['location'] ?? ''),
            'profile_text' => $profile_word_count >= 20 ? 0.8 : $this->cv_converter_value_confidence($payload['profile_text'] ?? ''),
            'key_info' => $this->cv_converter_list_confidence($payload['key_info'] ?? []),
            'strengths' => $this->cv_converter_list_confidence($payload['strengths'] ?? []),
            'skills' => $this->cv_converter_list_confidence($payload['skills'] ?? []),
            'phone' => $this->cv_converter_value_confidence($payload['phone'] ?? ''),
            'email' => $this->cv_converter_value_confidence($payload['email'] ?? ''),
            'experience' => !empty($payload['experience']) ? 0.85 : 0.25,
            'education' => !empty($payload['education']) ? 0.8 : 0.25,
        ];
        $overall = 0.0;
        if (!empty($field_confidence)) {
            $overall = array_sum($field_confidence) / count($field_confidence);
        }
        return [
            'field_confidence' => $field_confidence,
            'overall' => $overall,
        ];
    }
    private function get_cv_converter_default_logo_data_uri() {
        static $cached = null;
        if (is_string($cached)) {
            return $cached;
        }

        $logo_candidates = [
            plugin_dir_path(__FILE__) . 'logo.png',
            dirname(plugin_dir_path(__FILE__)) . '/logo.png',
            plugin_dir_path(__FILE__) . '73fa2b5c-e425-4854-a404-96824acab169.png',
            dirname(plugin_dir_path(__FILE__)) . '/73fa2b5c-e425-4854-a404-96824acab169.png',
            plugin_dir_path(__FILE__) . 'portal-logo.png',
            plugin_dir_path(__FILE__) . 'rightlogo.png',
        ];

        foreach ($logo_candidates as $logo_path) {
            if (!is_string($logo_path) || $logo_path === '' || !file_exists($logo_path)) {
                continue;
            }
            $ext = strtolower((string) pathinfo($logo_path, PATHINFO_EXTENSION));
            $mime = 'image/png';
            if ($ext === 'jpg' || $ext === 'jpeg') {
                $mime = 'image/jpeg';
            } elseif ($ext === 'svg') {
                $mime = 'image/svg+xml';
            }
            $bytes = (string) @file_get_contents($logo_path);
            if ($bytes === '') {
                continue;
            }
            $cached = 'data:' . $mime . ';base64,' . base64_encode($bytes);
            return $cached;
        }

        $cached = '';
        return $cached;
    }

