    private function generate_cv_converter_pdf_binary($title, $plain_text) {
        $title = trim((string) $title);
        if ($title === '') {
            $title = 'CoverMeNow CV';
        }
        $text = preg_replace('/\s+/', ' ', (string) $plain_text);
        $text = trim((string) $text);
        if ($text === '') {
            $text = 'CoverMeNow CV export';
        }
        $lines = preg_split('/(?<=[\.\!\?])\s+/', $text) ?: [];
        $lines = array_values(array_filter(array_map('trim', $lines), static function ($line) {
            return $line !== '';
        }));
        if (!$lines) {
            $lines = [$text];
        }
        $lines = array_slice($lines, 0, 36);
        $escaped_lines = array_map(static function ($line) {
            $line = function_exists('mb_substr') ? mb_substr((string) $line, 0, 110) : substr((string) $line, 0, 110);
            $line = str_replace(['\\', '(', ')'], ['\\\\', '\\(', '\\)'], $line);
            return $line;
        }, $lines);

        $stream_lines = [];
        $stream_lines[] = 'BT';
        $stream_lines[] = '/F1 12 Tf';
        $stream_lines[] = '50 790 Td';
        foreach ($escaped_lines as $idx => $line) {
            if ($idx > 0) {
                $stream_lines[] = 'T*';
            }
            $stream_lines[] = '(' . $line . ') Tj';
        }
        $stream_lines[] = 'ET';
        $stream = implode("\n", $stream_lines) . "\n";

        $objects = [];
        $objects[] = "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n";
        $objects[] = "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n";
        $objects[] = "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>\nendobj\n";
        $objects[] = "4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n";
        $objects[] = "5 0 obj\n<< /Length " . strlen($stream) . " >>\nstream\n" . $stream . "endstream\nendobj\n";

        $pdf = "%PDF-1.4\n";
        $offsets = [0];
        foreach ($objects as $object) {
            $offsets[] = strlen($pdf);
            $pdf .= $object;
        }
        $xref_offset = strlen($pdf);
        $pdf .= "xref\n0 " . (count($objects) + 1) . "\n";
        $pdf .= "0000000000 65535 f \n";
        for ($i = 1; $i <= count($objects); $i++) {
            $pdf .= sprintf("%010d 00000 n \n", (int) $offsets[$i]);
        }
        $pdf .= "trailer\n<< /Size " . (count($objects) + 1) . " /Root 1 0 R >>\nstartxref\n" . $xref_offset . "\n%%EOF";
        return $pdf;
    }

    private function user_can_manage_cv_converter($user_id = 0) {
        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        if (!$user_id) {
            return false;
        }
        return $this->is_admin_user($user_id)
            || $this->is_staff_role($user_id)
            || $this->is_account_manager_user($user_id);
    }

    private function get_staff_admin_users_for_cv_notifications() {
        $users = get_users([
            'role__in' => ['administrator', 'cmn_admin', 'cmn_staff', 'cmn_account_manager'],
            'fields' => ['ID'],
        ]);
        $ids = [];
        foreach ((array) $users as $user) {
            if (!is_object($user) || !isset($user->ID)) {
                continue;
            }
            $ids[] = (int) $user->ID;
        }
        return array_values(array_unique(array_filter($ids)));
    }

    private function maybe_notify_staff_about_school_request($school_id, $registration_ref = '') {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return 0;
        }
        $registration_ref = sanitize_text_field((string) $registration_ref);
        if ($registration_ref === '') {
            $registration_ref = sanitize_text_field((string) get_post_meta($school_id, 'cmn_registration_ref', true));
        }
        $requested_at = (string) get_post_meta($school_id, 'cmn_registration_requested_at', true);
        $dedupe_key = $registration_ref !== '' ? ('ref:' . $registration_ref) : ('requested_at:' . $requested_at);
        $last_notified = (string) get_post_meta($school_id, 'cmn_access_request_last_notified_key', true);
        if ($dedupe_key !== '' && $last_notified === $dedupe_key) {
            return 0;
        }

        $school_label = trim((string) get_the_title($school_id));
        if ($school_label === '') {
            $school_label = 'School #' . $school_id;
        }
        $pending_school_requests_url = add_query_arg([
            'view' => 'school-requests',
            'status' => 'all',
        ], $this->get_portal_base_url());
        $message = $school_label . ' submitted a new school registration request.';
        if ($registration_ref !== '') {
            $message .= ' Ref: ' . $registration_ref . '.';
        }

        $inserted = 0;
        foreach ($this->get_staff_admin_users_for_cv_notifications() as $notify_user_id) {
            $insert_id = $this->add_notification(
                (int) $notify_user_id,
                'school_request_submitted',
                'New school registration request',
                $message,
                $pending_school_requests_url
            );
            if ($insert_id > 0) {
                $inserted++;
            }
        }

        if ($inserted > 0 && $dedupe_key !== '') {
            update_post_meta($school_id, 'cmn_access_request_last_notified_key', $dedupe_key);
        }
        return $inserted;
    }

    private function user_can_access_marketing($user_id = 0) {
        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        if ($user_id < 1) {
            return false;
        }
        return $this->is_admin_user($user_id) || $this->is_staff_role($user_id) || $this->is_account_manager_user($user_id);
    }

