    private function get_marketing_template_by_id($template_id) {
        $template_id = (int) $template_id;
        if ($template_id < 1) {
            return null;
        }
        global $wpdb;
        $table = $this->get_marketing_templates_table();
        $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $template_id), ARRAY_A);
