    private function get_marketing_templates($limit = 100) {
        global $wpdb;
        $limit = max(1, min(300, (int) $limit));
        $table = $this->get_marketing_templates_table();
        $rows = (array) $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} ORDER BY updated_at DESC, id DESC LIMIT %d",
            $limit
        ), ARRAY_A);
        $out = [];
        foreach ($rows as $row) {
            $out[] = [
                'id' => (int) ($row['id'] ?? 0),
                'name' => sanitize_text_field((string) ($row['name'] ?? '')),
                'subject_template' => (string) ($row['subject_template'] ?? ''),
                'body_template_html' => (string) ($row['body_template_html'] ?? ''),
                'body_template_text' => (string) ($row['body_template_text'] ?? ''),
                'updated_at' => (string) ($row['updated_at'] ?? ''),
            ];
        }
        return $out;
    }

    private function get_marketing_settings() {
        return [
            'max_per_hour' => max(1, (int) get_option('cmn_marketing_max_per_hour', 200)),
            'sending_paused' => (int) get_option('cmn_marketing_sending_paused', 0) === 1 ? 1 : 0,
        ];
    }

    private function is_marketing_email_unsubscribed($email) {
        $email = strtolower(trim(sanitize_email((string) $email)));
        if ($email === '') {
            return false;
        }
        global $wpdb;
        $table = $this->get_marketing_unsubscribes_table();
        $count = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE email = %s", $email));
        if ($count > 0) {
            return true;
        }
        return false;
    }

    private function add_marketing_unsubscribe($email, $entity_type = '', $entity_id = 0, $reason = '') {
        $email = strtolower(trim(sanitize_email((string) $email)));
        if ($email === '') {
            return false;
        }
        global $wpdb;
        $table = $this->get_marketing_unsubscribes_table();
        $wpdb->replace($table, [
            'email' => $email,
            'entity_type' => sanitize_key((string) $entity_type),
            'entity_id' => (int) $entity_id > 0 ? (int) $entity_id : null,
            'unsubscribed_at' => current_time('mysql'),
            'reason' => sanitize_textarea_field((string) $reason),
        ], ['%s', '%s', '%d', '%s', '%s']);
        return true;
    }

    private function get_marketing_recent_sent_count_last_hour() {
        global $wpdb;
        $table = $this->get_marketing_sends_table();
        return (int) $wpdb->get_var(
            "SELECT COUNT(*) FROM {$table}
             WHERE status = 'sent'
               AND sent_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 1 HOUR)"
        );
    }

    private function can_process_marketing_send_batch(&$reason = '') {
        $settings = $this->get_marketing_settings();
        if (!empty($settings['sending_paused'])) {
            $reason = 'Sending paused by admin.';
            return false;
        }
        $sent_last_hour = $this->get_marketing_recent_sent_count_last_hour();
        if ($sent_last_hour >= (int) $settings['max_per_hour']) {
            $reason = 'Hourly safety limit reached.';
            return false;
        }
        return true;
    }

    private function get_marketing_overview_metrics() {
        $cache_key = 'cmn_marketing_overview_metrics';
        $cached = get_transient($cache_key);
        if (is_array($cached)) {
            return $cached;
        }
        global $wpdb;
        $sends = $this->get_marketing_sends_table();
        $campaigns = $this->get_marketing_campaigns_table();
        $unsubs = $this->get_marketing_unsubscribes_table();
        $emails_sent_7d = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$sends} WHERE status = 'sent' AND created_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 7 DAY)");
        $emails_failed_7d = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$sends} WHERE status = 'failed' AND created_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 7 DAY)");
        $unsubs_30d = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$unsubs} WHERE unsubscribed_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 30 DAY)");
        $top_templates = (array) $wpdb->get_results(
            "SELECT c.template_id, COUNT(*) AS total_count
             FROM {$sends} s
             INNER JOIN {$campaigns} c ON c.id = s.campaign_id
             WHERE s.created_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 30 DAY)
               AND c.template_id IS NOT NULL
             GROUP BY c.template_id
             ORDER BY total_count DESC
             LIMIT 5",
            ARRAY_A
        );
        $recent_campaigns = (array) $wpdb->get_results(
            "SELECT c.id, c.name, c.status,
                    SUM(CASE WHEN s.status = 'sent' THEN 1 ELSE 0 END) AS sent_count,
                    SUM(CASE WHEN s.status = 'failed' THEN 1 ELSE 0 END) AS failed_count,
                    SUM(CASE WHEN s.status LIKE 'skipped%' THEN 1 ELSE 0 END) AS skipped_count
             FROM {$campaigns} c
             LEFT JOIN {$sends} s ON s.campaign_id = c.id
             GROUP BY c.id
             ORDER BY c.created_at DESC
             LIMIT 10",
            ARRAY_A
        );
        $payload = [
            'emails_sent_7d' => $emails_sent_7d,
            'emails_failed_7d' => $emails_failed_7d,
            'unsubscribes_30d' => $unsubs_30d,
            'top_templates' => $top_templates,
            'recent_campaigns' => $recent_campaigns,
        ];
        set_transient($cache_key, $payload, 10 * MINUTE_IN_SECONDS);
        return $payload;
    }

    private function get_marketing_send_log_rows($limit = 100) {
        global $wpdb;
        $limit = max(1, min(500, (int) $limit));
        $sql = "SELECT s.*, c.name AS campaign_name, t.name AS template_name
                FROM {$this->get_marketing_sends_table()} s
                LEFT JOIN {$this->get_marketing_campaigns_table()} c ON c.id = s.campaign_id
                LEFT JOIN {$this->get_marketing_templates_table()} t ON t.id = c.template_id
                ORDER BY s.id DESC
                LIMIT %d";
        return (array) $wpdb->get_results($wpdb->prepare($sql, $limit), ARRAY_A);
    }

    private function get_marketing_unsubscribe_rows($limit = 100) {
        global $wpdb;
        $limit = max(1, min(500, (int) $limit));
        $sql = "SELECT * FROM {$this->get_marketing_unsubscribes_table()} ORDER BY unsubscribed_at DESC, id DESC LIMIT %d";
        return (array) $wpdb->get_results($wpdb->prepare($sql, $limit), ARRAY_A);
    }

    private function refresh_marketing_list_members($list_id, $selected_school_ids = null, $user_id = 0) {
        $list_id = (int) $list_id;
        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        if ($list_id < 1 || $user_id < 1) {
            return 0;
        }
        global $wpdb;
        $list = $this->get_marketing_list_by_id($list_id);
        if (!$list) {
            return 0;
        }
        $members_table = $this->get_marketing_members_table();
        $type = strtolower((string) ($list['type'] ?? 'dynamic'));
        $criteria = [];
        if (!empty($list['criteria_json'])) {
            $decoded = json_decode((string) $list['criteria_json'], true);
            if (is_array($decoded)) {
                $criteria = $decoded;
            }
        }
        if ($type === 'static') {
            $school_ids = is_array($selected_school_ids) ? array_values(array_unique(array_map('intval', $selected_school_ids))) : [];
        } else {
            $rows = $this->get_marketing_school_rows($criteria, $user_id);
            $school_ids = array_values(array_unique(array_map(function ($row) {
                return (int) ($row['school_id'] ?? 0);
            }, $rows)));
        }

        $wpdb->delete($members_table, ['list_id' => $list_id], ['%d']);
        $count = 0;
        foreach ($school_ids as $school_id) {
            if ($school_id < 1) {
                continue;
            }
            $inserted = $wpdb->insert($members_table, [
                'list_id' => $list_id,
                'school_id' => $school_id,
                'added_at' => current_time('mysql'),
                'added_by_user_id' => $user_id,
                'source' => $type === 'static' ? 'manual' : 'criteria',
            ], ['%d', '%d', '%s', '%d', '%s']);
            if ($inserted) {
                $count++;
            }
        }
        return $count;
    }

    private function get_marketing_lists_with_counts($user_id = 0) {
        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        global $wpdb;
        $lists_table = $this->get_marketing_lists_table();
        $members_table = $this->get_marketing_members_table();
        $rows = (array) $wpdb->get_results(
            "SELECT l.*, COUNT(m.id) AS member_count
             FROM {$lists_table} l
             LEFT JOIN {$members_table} m ON m.list_id = l.id
             GROUP BY l.id
             ORDER BY l.updated_at DESC, l.id DESC",
            ARRAY_A
        );
        $out = [];
        foreach ($rows as $row) {
            $created_by = (int) ($row['created_by_user_id'] ?? 0);
            if ($this->is_account_manager_user($user_id) && !$this->is_admin_user($user_id) && !$this->is_staff_role($user_id) && $created_by !== $user_id) {
                continue;
            }
            $out[] = [
                'id' => (int) ($row['id'] ?? 0),
                'name' => sanitize_text_field((string) ($row['name'] ?? '')),
                'type' => sanitize_key((string) ($row['type'] ?? 'dynamic')),
                'member_count' => (int) ($row['member_count'] ?? 0),
                'updated_at' => (string) ($row['updated_at'] ?? ''),
                'criteria_json' => (string) ($row['criteria_json'] ?? ''),
            ];
        }
        return $out;
    }

    private function get_marketing_list_school_ids($list_id) {
        $list_id = (int) $list_id;
        if ($list_id < 1) {
            return [];
        }
        global $wpdb;
        $members_table = $this->get_marketing_members_table();
        $rows = (array) $wpdb->get_col($wpdb->prepare(
            "SELECT school_id FROM {$members_table} WHERE list_id = %d ORDER BY id ASC",
            $list_id
        ));
        return array_values(array_filter(array_unique(array_map('intval', $rows))));
    }

    private function user_can_manage_marketing_list($user_id, $list_row) {
        $user_id = (int) $user_id;
        if ($user_id < 1 || !is_array($list_row) || !$list_row) {
            return false;
        }
        if (!$this->user_can_access_marketing($user_id)) {
            return false;
        }
        if ($this->is_admin_user($user_id) || $this->is_staff_role($user_id)) {
            return true;
        }
        $created_by = (int) ($list_row['created_by_user_id'] ?? 0);
        return $created_by > 0 && $created_by === $user_id;
    }

    private function get_marketing_campaigns_for_user($user_id = 0, $limit = 100) {
        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        global $wpdb;
        $table = $this->get_marketing_campaigns_table();
        $limit = max(1, min(500, (int) $limit));
        $rows = (array) $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} ORDER BY created_at DESC, id DESC LIMIT %d",
            $limit
        ), ARRAY_A);
        $out = [];
        foreach ($rows as $row) {
            $created_by = (int) ($row['created_by_user_id'] ?? 0);
            if ($this->is_account_manager_user($user_id) && !$this->is_admin_user($user_id) && !$this->is_staff_role($user_id) && $created_by !== $user_id) {
                continue;
            }
            $out[] = [
                'id' => (int) ($row['id'] ?? 0),
                'name' => sanitize_text_field((string) ($row['name'] ?? '')),
                'status' => sanitize_key((string) ($row['status'] ?? 'draft')),
                'subject' => sanitize_text_field((string) ($row['subject'] ?? '')),
                'throttle_per_minute' => (int) ($row['throttle_per_minute'] ?? 30),
                'created_at' => (string) ($row['created_at'] ?? ''),
            ];
        }
        return $out;
    }

    private function get_marketing_merge_map($entity_type, $entity_id = 0, $extra = []) {
        if (is_numeric($entity_type)) {
            $extra = is_array($entity_id) ? $entity_id : $extra;
            $entity_id = (int) $entity_type;
            $entity_type = 'school';
        }
        $entity_type = sanitize_key((string) $entity_type);
        $entity_id = (int) $entity_id;
        if (!in_array($entity_type, ['school', 'contact'], true)) {
            $entity_type = 'school';
        }
        $school_id = 0;
        $contact_id = 0;
        if ($entity_type === 'school') {
            $school_id = $entity_id;
        } else {
            $contact_id = $entity_id;
            $linked = $this->get_contact_school_links($contact_id);
            if (!empty($linked[0]['school_email_domain'])) {
                $school_id = (int) $this->get_school_post_id_by_domain((string) $linked[0]['school_email_domain']);
            }
        }
        $school_name = $school_id > 0 ? (string) get_the_title($school_id) : '';
        $school_location = $school_id > 0 ? (string) get_post_meta($school_id, 'cmn_location', true) : '';
        $school_town = $school_id > 0 ? (string) get_post_meta($school_id, 'cmn_town', true) : '';
        if ($school_town === '') {
            $school_town = $school_location;
        }
        $school_email = $school_id > 0 ? sanitize_email((string) get_post_meta($school_id, 'cmn_email', true)) : '';
        $contact_name = '';
        $contact_role = '';
        $contact_email = '';
        if ($contact_id > 0) {
            $contact_name = (string) get_the_title($contact_id);
            $contact_role = (string) get_post_meta($contact_id, 'cmn_contact_role', true);
            $contact_email = sanitize_email((string) get_post_meta($contact_id, 'cmn_contact_email', true));
        } elseif ($school_id > 0) {
            $contact_name = (string) get_post_meta($school_id, 'cmn_primary_contact_name', true);
            if ($contact_name === '') {
                $contact_name = (string) get_post_meta($school_id, 'cmn_contact1', true);
            }
            $contact_email = $school_email;
        }
        $email = $contact_email !== '' ? $contact_email : $school_email;
        $unsubscribe_link = '';
        if ($email !== '') {
            $token = $this->create_marketing_unsubscribe_token($email, $entity_type, $entity_id);
            $unsubscribe_link = add_query_arg([
                'cmn_unsub' => '1',
                'token' => $token,
            ], home_url('/'));
        }
        return [
            'school_name' => $school_name,
            'school_location' => $school_location,
            'school_town' => $school_town,
            'contact_name' => $contact_name,
            'contact_role' => $contact_role,
            'email' => $email,
            'portal_link' => $this->get_portal_base_url(),
            'unsubscribe_link' => $unsubscribe_link,
            'company_name' => 'CoverMeNow',
            'location' => $school_location,
            'postcode' => $school_id > 0 ? (string) get_post_meta($school_id, 'cmn_postcode', true) : '',
            'distance' => (string) ($extra['distance'] ?? ''),
            'last_contacted_date' => (string) ($extra['last_contacted_date'] ?? ''),
        ];
    }

    private function render_marketing_template_text($template, $entity_type = 'school', $entity_id = 0, $extra = []) {
        if (is_numeric($entity_type)) {
            $extra = is_array($entity_id) ? $entity_id : $extra;
            $entity_id = (int) $entity_type;
            $entity_type = 'school';
        }
        $template = (string) $template;
        if ($template === '') {
            return '';
        }
        $map = $this->get_marketing_merge_map($entity_type, (int) $entity_id, is_array($extra) ? $extra : []);
        $template = preg_replace_callback('/\{\{\s*([a-zA-Z0-9_]+)(?:\|([^}]*))?\s*\}\}/', function ($matches) use ($map) {
            $key = sanitize_key((string) ($matches[1] ?? ''));
            $fallback = isset($matches[2]) ? (string) $matches[2] : '';
            $val = isset($map[$key]) ? trim((string) $map[$key]) : '';
            if ($val === '') {
                $val = trim($fallback);
            }
            return $val;
        }, $template);
        return preg_replace("/\n{3,}/", "\n\n", $template);
    }

    private function extract_marketing_tags($template) {
        $template = (string) $template;
        if ($template === '') {
            return [];
        }
        preg_match_all('/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}|\{\s*([a-zA-Z0-9_]+)\s*\}/', $template, $matches, PREG_SET_ORDER);
        $tags = [];
        foreach ((array) $matches as $match) {
            $tag = !empty($match[1]) ? (string) $match[1] : (!empty($match[2]) ? (string) $match[2] : '');
            $tag = sanitize_key($tag);
            if ($tag !== '') {
                $tags[$tag] = true;
            }
        }
        return array_keys($tags);
    }

    private function get_marketing_missing_tag_counts($entity_type, $entity_id = 0, $templates = [], $extra = []) {
        if (is_numeric($entity_type)) {
            $extra = is_array($templates) ? $templates : [];
            $templates = is_array($entity_id) ? $entity_id : [];
            $entity_id = (int) $entity_type;
            $entity_type = 'school';
        }
        $map = $this->get_marketing_merge_map($entity_type, (int) $entity_id, is_array($extra) ? $extra : []);
        $counts = [];
        foreach ((array) $templates as $template) {
            foreach ($this->extract_marketing_tags((string) $template) as $tag) {
                $value = isset($map[$tag]) ? trim((string) $map[$tag]) : '';
                if ($value === '') {
                    if (!isset($counts[$tag])) {
                        $counts[$tag] = 0;
                    }
                    $counts[$tag]++;
                }
            }
        }
        ksort($counts);
        return $counts;
    }

    private function process_marketing_queue_batch($campaign_id = 0, $limit = 30) {
        global $wpdb;
        $campaign_id = (int) $campaign_id;
        $limit = max(1, min(50, (int) $limit));
        $sends_table = $this->get_marketing_sends_table();
        $campaigns_table = $this->get_marketing_campaigns_table();

        $query = "SELECT s.* FROM {$sends_table} s LEFT JOIN {$campaigns_table} c ON c.id = s.campaign_id WHERE s.status = 'queued' AND (c.id IS NULL OR c.status <> 'paused')";
        $params = [];
        if ($campaign_id > 0) {
            $query .= " AND s.campaign_id = %d";
            $params[] = $campaign_id;
        }
        $query .= " ORDER BY s.id ASC LIMIT %d";
        $params[] = $limit;

        $rows = (array) $wpdb->get_results($wpdb->prepare($query, ...$params), ARRAY_A);
        $processed = 0;
        $sent = 0;
        $failed = 0;
        $skipped = 0;
        $stop_reason = '';
        $guard_ok = $this->can_process_marketing_send_batch($stop_reason);
        if (!$guard_ok) {
            return [
                'processed' => 0,
                'sent' => 0,
                'failed' => 0,
                'skipped' => 0,
                'stopped_reason' => $stop_reason,
            ];
        }
        foreach ($rows as $row) {
            $reason = '';
            if (!$this->can_process_marketing_send_batch($reason)) {
                $stop_reason = $reason;
                break;
            }
            $processed++;
            $send_id = (int) ($row['id'] ?? 0);
            $campaign = $this->get_marketing_campaign_by_id((int) ($row['campaign_id'] ?? 0));
            $entity_type = sanitize_key((string) ($row['entity_type'] ?? 'school'));
            $entity_id = (int) ($row['entity_id'] ?? 0);
            $school_id = (int) ($row['school_id'] ?? 0);
            if ($entity_id < 1 && $school_id > 0) {
                $entity_type = 'school';
                $entity_id = $school_id;
            }
            $to_email = sanitize_email((string) ($row['to_email'] ?? ''));
            if (!$campaign || $entity_id < 1 || $to_email === '') {
                $wpdb->update($sends_table, [
                    'status' => $to_email === '' ? 'skipped_no_email' : 'failed',
                    'failure_reason' => 'Invalid campaign or recipient data.',
                    'error_message' => 'Invalid campaign or recipient data.',
                ], ['id' => $send_id], ['%s', '%s', '%s'], ['%d']);
                if ($to_email === '') {
                    $skipped++;
                } else {
                    $failed++;
                }
                continue;
            }
            if ($this->is_marketing_email_unsubscribed($to_email)) {
                $wpdb->update($sends_table, [
                    'status' => 'skipped_unsubscribed',
                    'failure_reason' => 'Recipient unsubscribed.',
                    'error_message' => 'Recipient unsubscribed.',
                    'sent_at' => current_time('mysql'),
                ], ['id' => $send_id], ['%s', '%s', '%s', '%s'], ['%d']);
                $skipped++;
                continue;
            }

            $subject = $this->render_marketing_template_text((string) ($campaign['subject'] ?? ''), $entity_type, $entity_id);
            $html_body = $this->render_marketing_template_text((string) ($campaign['html_body'] ?? ''), $entity_type, $entity_id);
            $text_body = $this->render_marketing_template_text((string) ($campaign['text_body'] ?? ''), $entity_type, $entity_id);
            if ($text_body === '') {
                $text_body = wp_strip_all_tags($html_body);
            }
            $thread_key = (string) ($row['thread_key'] ?? '');
            $headers = [
                'Content-Type: text/html; charset=UTF-8',
                'X-CMN-Thread-Key: ' . $thread_key,
                'X-CMN-Campaign-ID: ' . (int) ($campaign['id'] ?? 0),
            ];
            if (!empty($campaign['reply_to_email'])) {
                $headers[] = 'Reply-To: ' . sanitize_email((string) $campaign['reply_to_email']);
            }
            $mail_body = nl2br(esc_html($text_body));
            if ($html_body !== '') {
                $mail_body = wp_kses_post($html_body);
            }
            $body_hash = sha1((string) $mail_body);

            $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
            $GLOBALS['cmn_school_mail_log_type'] = 'marketing_campaign';
            $result = $this->send_school_email($to_email, $subject, $mail_body, $headers, []);
            if ($previous_log_type !== null) {
                $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
            } else {
                unset($GLOBALS['cmn_school_mail_log_type']);
            }
            if ($result) {
                $sent++;
                $wpdb->update($sends_table, [
                    'status' => 'sent',
                    'sent_at' => current_time('mysql'),
                    'subject_rendered' => $subject,
                    'body_rendered_hash' => $body_hash,
                    'error_message' => null,
                    'failure_reason' => null,
                ], ['id' => $send_id], ['%s', '%s', '%s', '%s', '%s'], ['%d']);
                $this->insert_activity_row([
                    'entity_type' => $entity_type === 'contact' ? 'contact' : 'school',
                    'entity_ref' => (string) $entity_id,
                    'activity_type' => 'email',
                    'subject' => 'Marketing email',
                    'notes' => 'Marketing email: ' . (string) ($campaign['name'] ?? ('Campaign #' . (int) ($campaign['id'] ?? 0))) . ' - sent - ' . current_time('mysql') . ' (campaign_id=' . (int) ($campaign['id'] ?? 0) . ', send_id=' . $send_id . ')',
                    'created_by' => (int) ($campaign['created_by_user_id'] ?? get_current_user_id()),
                ]);
            } else {
                $failed++;
                $wpdb->update($sends_table, [
                    'status' => 'failed',
                    'subject_rendered' => $subject,
                    'body_rendered_hash' => $body_hash,
                    'error_message' => 'wp_mail returned false.',
                    'failure_reason' => 'wp_mail returned false.',
                ], ['id' => $send_id], ['%s', '%s', '%s', '%s'], ['%d']);
            }
            sleep(2);
        }

        if ($campaign_id > 0) {
            $queued = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(1) FROM {$sends_table} WHERE campaign_id = %d AND status = 'queued'",
                $campaign_id
            ));
            $wpdb->update($campaigns_table, [
                'status' => $queued > 0 ? 'sending' : 'sent',
                'send_finished_at' => $queued > 0 ? null : current_time('mysql'),
            ], ['id' => $campaign_id], ['%s', '%s'], ['%d']);
        }

        return [
            'processed' => $processed,
            'sent' => $sent,
            'failed' => $failed,
            'skipped' => $skipped,
            'stopped_reason' => $stop_reason,
        ];
    }

    private function get_marketing_queue_snapshot($limit = 60) {
        global $wpdb;
        $limit = max(1, min(300, (int) $limit));
        $sends_table = $this->get_marketing_sends_table();
        $campaigns_table = $this->get_marketing_campaigns_table();
        $rows = (array) $wpdb->get_results($wpdb->prepare(
            "SELECT s.*, c.name AS campaign_name
             FROM {$sends_table} s
             LEFT JOIN {$campaigns_table} c ON c.id = s.campaign_id
             ORDER BY s.id DESC
             LIMIT %d",
            $limit
        ), ARRAY_A);
        $out_rows = [];
        foreach ($rows as $row) {
            $school_id = (int) ($row['school_id'] ?? 0);
            $out_rows[] = [
                'id' => (int) ($row['id'] ?? 0),
                'campaign_id' => (int) ($row['campaign_id'] ?? 0),
                'campaign_name' => sanitize_text_field((string) ($row['campaign_name'] ?? '')),
                'school_id' => $school_id,
                'school_name' => $school_id > 0 ? (string) get_the_title($school_id) : '',
                'to_email' => sanitize_email((string) ($row['to_email'] ?? '')),
                'status' => sanitize_key((string) ($row['status'] ?? 'queued')),
                'sent_at' => (string) ($row['sent_at'] ?? ''),
                'failure_reason' => sanitize_text_field((string) ($row['failure_reason'] ?? '')),
            ];
        }
        $queued = (int) $wpdb->get_var("SELECT COUNT(1) FROM {$sends_table} WHERE status = 'queued'");
        $sent = (int) $wpdb->get_var("SELECT COUNT(1) FROM {$sends_table} WHERE status = 'sent'");
        $failed = (int) $wpdb->get_var("SELECT COUNT(1) FROM {$sends_table} WHERE status = 'failed'");
        return [
            'queued' => $queued,
            'sent' => $sent,
            'failed' => $failed,
            'rows' => $out_rows,
        ];
    }

    private function get_marketing_replies_payload($user_id = 0, $limit = 120) {
        global $wpdb;
        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        $limit = max(1, min(300, (int) $limit));
        $inbound_table = $this->get_marketing_inbound_table();
        $scoped_school_ids = $this->get_marketing_scoped_school_ids($user_id);
        $is_global_scope = $this->is_admin_user($user_id) || $this->is_staff_role($user_id);

        if (!$is_global_scope && !$scoped_school_ids) {
            return [
                'rows' => [],
                'counts' => [
                    'total' => 0,
                    'matched' => 0,
                    'unmatched' => 0,
                ],
            ];
        }

        $rows = [];
        if ($is_global_scope) {
            $rows = (array) $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$inbound_table} ORDER BY received_at DESC, id DESC LIMIT %d",
                $limit
            ), ARRAY_A);
        } else {
            $placeholders = implode(',', array_fill(0, count($scoped_school_ids), '%d'));
            $params = array_merge($scoped_school_ids, [$limit]);
            $rows = (array) $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$inbound_table} WHERE school_id IN ({$placeholders}) ORDER BY received_at DESC, id DESC LIMIT %d",
                ...$params
            ), ARRAY_A);
        }

        $out_rows = [];
        $matched = 0;
        foreach ($rows as $row) {
            $school_id = (int) ($row['school_id'] ?? 0);
            if ($school_id > 0) {
                $matched++;
            }
            $received_raw = (string) ($row['received_at'] ?? '');
            $received_ts = $received_raw !== '' ? strtotime($received_raw) : false;
            $out_rows[] = [
                'id' => (int) ($row['id'] ?? 0),
                'school_id' => $school_id,
                'school_name' => $school_id > 0 ? sanitize_text_field((string) get_the_title($school_id)) : 'Unmatched',
                'campaign_id' => (int) ($row['campaign_id'] ?? 0),
                'from_email' => sanitize_email((string) ($row['from_email'] ?? '')),
                'subject' => sanitize_text_field((string) ($row['subject'] ?? '')),
                'snippet' => sanitize_textarea_field((string) ($row['snippet'] ?? '')),
                'received_at' => $received_raw,
                'received_at_label' => $received_ts ? date_i18n('M j, Y g:ia', $received_ts) : '',
                'message_id' => sanitize_text_field((string) ($row['message_id'] ?? '')),
            ];
        }

        $total = count($out_rows);
        return [
            'rows' => $out_rows,
            'counts' => [
                'total' => $total,
                'matched' => $matched,
                'unmatched' => max(0, $total - $matched),
            ],
        ];
    }


    private function decode_inbound_email_body_text($raw_body) {
        $body = (string) $raw_body;
        if ($body === '') {
            return '';
        }
        if (function_exists('quoted_printable_decode')) {
            $decoded = quoted_printable_decode($body);
            if (is_string($decoded) && $decoded !== '') {
                $body = $decoded;
            }
        }
        $body = html_entity_decode($body, ENT_QUOTES, 'UTF-8');
        $body = str_replace(["\r\n", "\r"], "\n", $body);
        return trim((string) $body);
    }

    private function extract_school_request_reference_from_text($text) {
        $text = strtoupper(trim((string) $text));
        if ($text === '') {
            return '';
        }
        $patterns = [
            '/\bREFERENCE\s*[:#]?\s*([A-Z0-9]{6,24})\b/i',
            '/\bREF\s*[:#]?\s*([A-Z0-9]{6,24})\b/i',
            '/\[\s*([A-Z0-9]{6,24})\s*\]/',
        ];
        foreach ($patterns as $pattern) {
            if (preg_match($pattern, $text, $m)) {
                $ref = sanitize_text_field((string) ($m[1] ?? ''));
                if ($ref !== '') {
                    return strtoupper($ref);
                }
            }
        }
        return '';
    }

    private function get_school_request_post_statuses() {
        return ['publish', 'draft', 'pending', 'private'];
    }

    private function find_school_request_school_id_by_registration_ref($registration_ref) {
        $registration_ref = strtoupper(trim(sanitize_text_field((string) $registration_ref)));
        if ($registration_ref === '') {
            return 0;
        }
        $rows = get_posts([
            'post_type' => 'cmn_school',
            'post_status' => $this->get_school_request_post_statuses(),
            'posts_per_page' => 1,
            'orderby' => 'date',
            'order' => 'DESC',
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_registration_ref',
                    'value' => $registration_ref,
                    'compare' => '=',
                ],
            ],
        ]);
        return !empty($rows) ? (int) $rows[0] : 0;
    }

    private function find_school_request_school_id_by_email($email) {
        $email = sanitize_email((string) $email);
        if ($email === '' || !is_email($email)) {
            return 0;
        }
        $rows = get_posts([
            'post_type' => 'cmn_school',
            'post_status' => $this->get_school_request_post_statuses(),
            'posts_per_page' => 5,
            'orderby' => 'date',
            'order' => 'DESC',
            'fields' => 'ids',
            'meta_query' => [
                'relation' => 'OR',
                [
                    'key' => 'cmn_email',
                    'value' => $email,
                    'compare' => '=',
                ],
                [
                    'key' => 'cmn_primary_contact_email',
                    'value' => $email,
                    'compare' => '=',
                ],
                [
                    'key' => 'cmn_contact1_email',
                    'value' => $email,
                    'compare' => '=',
                ],
            ],
        ]);
        if (!$rows) {
            return 0;
        }
        if (count($rows) === 1) {
            return (int) $rows[0];
        }
        foreach ((array) $rows as $school_id) {
            if ($this->get_school_access_request_status((int) $school_id) === 'more_info_needed') {
                return (int) $school_id;
            }
        }
        return (int) $rows[0];
    }

    private function find_school_request_school_id_by_domain($domain) {
        $domain = strtolower(trim((string) $domain));
        if ($domain === '') {
            return 0;
        }
        $rows = get_posts([
            'post_type' => 'cmn_school',
            'post_status' => $this->get_school_request_post_statuses(),
            'posts_per_page' => 6,
            'orderby' => 'date',
            'order' => 'DESC',
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_school_email_domain',
                    'value' => $domain,
                    'compare' => '=',
                ],
            ],
        ]);
        if (!$rows) {
            return 0;
        }
        if (count($rows) === 1) {
            return (int) $rows[0];
        }
        $more_info_matches = [];
        foreach ((array) $rows as $school_id) {
            if ($this->get_school_access_request_status((int) $school_id) === 'more_info_needed') {
                $more_info_matches[] = (int) $school_id;
            }
        }
        if (count($more_info_matches) === 1) {
            return (int) $more_info_matches[0];
        }
        return 0;
    }

    private function resolve_school_request_school_id_from_inbound($from_email, $subject_raw = '', $body_text = '', $fallback_school_id = 0) {
        $fallback_school_id = (int) $fallback_school_id;

        $ref = $this->extract_school_request_reference_from_text((string) $subject_raw);
        if ($ref === '') {
            $ref = $this->extract_school_request_reference_from_text((string) $body_text);
        }
        if ($ref !== '') {
            $by_ref = $this->find_school_request_school_id_by_registration_ref($ref);
            if ($by_ref > 0) {
                return $by_ref;
            }
        }

        $by_email = $this->find_school_request_school_id_by_email((string) $from_email);
        if ($by_email > 0) {
            return $by_email;
        }

        $domain = $this->get_email_domain((string) $from_email);
        if ($domain !== '') {
            $by_domain = $this->find_school_request_school_id_by_domain($domain);
            if ($by_domain > 0) {
                return $by_domain;
            }
        }

        if ($fallback_school_id > 0 && get_post_type($fallback_school_id) === 'cmn_school') {
            return $fallback_school_id;
        }

        return 0;
    }

    private function extract_school_request_reply_excerpt($body_text, $fallback = '') {
        $body_text = str_replace(["\r\n", "\r"], "\n", (string) $body_text);
        $lines = preg_split('/\n+/', $body_text);
        $reply_lines = [];
        $stop_patterns = [
            '/^\s*>/',
            '/^\s*On .+ wrote:\s*$/i',
            '/^\s*From:\s*/i',
            '/^\s*Sent:\s*/i',
            '/^\s*Subject:\s*/i',
            '/^-{2,}\s*Original Message\s*-{2,}/i',
        ];

        foreach ((array) $lines as $line) {
            $line = trim((string) wp_strip_all_tags((string) $line));
            if ($line === '') {
                continue;
            }
            $is_stop = false;
            foreach ($stop_patterns as $pattern) {
                if (preg_match($pattern, $line)) {
                    $is_stop = true;
                    break;
                }
            }
            if ($is_stop) {
                if (!empty($reply_lines)) {
                    break;
                }
                continue;
            }
            $reply_lines[] = $line;
            if (count($reply_lines) >= 12) {
                break;
            }
        }

        $excerpt = trim(implode(' ', $reply_lines));
        if ($excerpt === '') {
            $excerpt = trim((string) $fallback);
        }
        $excerpt = trim((string) preg_replace('/\s+/', ' ', (string) $excerpt));
        if (strlen($excerpt) > 480) {
            $excerpt = substr($excerpt, 0, 477) . '...';
        }
        return sanitize_textarea_field($excerpt);
    }

    private function record_school_request_inbound_reply($school_id, $from_email, $subject_raw, $body_text, $snippet, $received_at, $message_id = '') {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return false;
        }

        $status = $this->get_school_access_request_status($school_id);
        if ($status !== 'more_info_needed') {
            return false;
        }

        $from_email = sanitize_email((string) $from_email);
        $subject = sanitize_text_field((string) $subject_raw);
        $message_id = sanitize_text_field((string) $message_id);
        $received_at = sanitize_text_field((string) $received_at);
        if ($received_at === '') {
            $received_at = current_time('mysql');
        }

        $reply_excerpt = $this->extract_school_request_reply_excerpt((string) $body_text, (string) $snippet);
        if ($reply_excerpt === '' && $subject !== '') {
            $reply_excerpt = $subject;
        }
        if ($reply_excerpt === '') {
            return false;
        }

        update_post_meta($school_id, 'cmn_access_request_latest_school_reply', $reply_excerpt);
        update_post_meta($school_id, 'cmn_access_request_latest_school_reply_subject', $subject);
        update_post_meta($school_id, 'cmn_access_request_latest_school_reply_from', $from_email);
        update_post_meta($school_id, 'cmn_access_request_latest_school_reply_at', $received_at);

        $registration_ref = sanitize_text_field((string) get_post_meta($school_id, 'cmn_registration_ref', true));
        $school_name = trim((string) get_the_title($school_id));
        if ($school_name === '') {
            $school_name = 'School #' . $school_id;
        }

        $this->insert_audit('school_request_school_reply_received', 'school', $school_id, [
            'school_id' => $school_id,
            'ref' => $registration_ref,
            'from_email' => $from_email,
            'subject' => $subject,
            'reply_excerpt' => $reply_excerpt,
            'received_at' => $received_at,
            'message_id' => $message_id,
            'status' => 'more_info_needed',
        ], 0);

        $portal_link = add_query_arg(['view' => 'schools', 'school_id' => $school_id], $this->get_portal_base_url());
        $message_text = $school_name . ' replied with additional information.';
        if ($reply_excerpt !== '') {
            $message_text .= ' ' . $reply_excerpt;
        }
        if (strlen($message_text) > 240) {
            $message_text = substr($message_text, 0, 237) . '...';
        }

        $recipient_ids = [];
        $manager_user_id = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
        if ($manager_user_id < 1) {
            $manager_user_id = (int) get_post_meta($school_id, 'cmn_account_manager_user_id', true);
        }
        if ($manager_user_id > 0) {
            $recipient_ids[$manager_user_id] = true;
        }
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            $admin_id = (int) $admin_id;
            if ($admin_id > 0) {
                $recipient_ids[$admin_id] = true;
            }
        }

        foreach (array_keys($recipient_ids) as $notify_user_id) {
            $this->add_notification(
                (int) $notify_user_id,
                'school_request_reply_received',
                'School replied to application',
                $message_text,
                $portal_link
            );
        }

        return true;
    }

    private function poll_marketing_replies_imap($limit = 40) {
        $limit = max(1, min(200, (int) $limit));
        if (!function_exists('imap_open') || !function_exists('imap_search')) {
            return [
                'ok' => false,
                'message' => 'IMAP extension is not available on this server.',
                'processed' => 0,
                'matched' => 0,
                'inserted' => 0,
                'last_uid' => (int) get_option('cmn_marketing_imap_last_uid', 0),
            ];
        }

        $config = $this->get_marketing_imap_config();
        if (empty($config['host']) || empty($config['username']) || empty($config['password'])) {
            return [
                'ok' => false,
                'message' => 'IMAP credentials are not configured.',
                'processed' => 0,
                'matched' => 0,
                'inserted' => 0,
                'last_uid' => (int) get_option('cmn_marketing_imap_last_uid', 0),
            ];
        }

        $flags = '/imap';
        if ($config['encryption'] === 'ssl') {
            $flags .= '/ssl';
        } elseif ($config['encryption'] === 'tls') {
            $flags .= '/tls';
        } else {
            $flags .= '/notls';
        }
        $mailbox = '{' . $config['host'] . ':' . (int) $config['port'] . $flags . '/novalidate-cert}' . $config['mailbox'];
        $open_flags = defined('OP_READONLY') ? OP_READONLY : 0;
        $inbox = @imap_open($mailbox, (string) $config['username'], (string) $config['password'], $open_flags);
        if (!$inbox) {
            $err = function_exists('imap_last_error') ? (string) imap_last_error() : '';
            return [
                'ok' => false,
                'message' => $err !== '' ? $err : 'Unable to connect to inbox.',
                'processed' => 0,
                'matched' => 0,
                'inserted' => 0,
                'last_uid' => (int) get_option('cmn_marketing_imap_last_uid', 0),
            ];
        }

        global $wpdb;
        $sends_table = $this->get_marketing_sends_table();
        $inbound_table = $this->get_marketing_inbound_table();
        $last_uid = (int) get_option('cmn_marketing_imap_last_uid', 0);
        $search_flags = defined('SE_UID') ? SE_UID : 1;
        $uids = @imap_search($inbox, 'ALL', $search_flags);
        if (!$uids) {
            @imap_close($inbox);
            return [
                'ok' => true,
                'message' => 'No inbound messages found.',
                'processed' => 0,
                'matched' => 0,
                'inserted' => 0,
                'last_uid' => $last_uid,
            ];
        }
        sort($uids, SORT_NUMERIC);
        $new_uids = [];
        foreach ((array) $uids as $uid) {
            $uid = (int) $uid;
            if ($uid > $last_uid) {
                $new_uids[] = $uid;
            }
        }
        if (!$new_uids) {
            @imap_close($inbox);
            return [
                'ok' => true,
                'message' => 'No new replies since last poll.',
                'processed' => 0,
                'matched' => 0,
                'inserted' => 0,
                'last_uid' => $last_uid,
            ];
        }
        if (count($new_uids) > $limit) {
            $new_uids = array_slice($new_uids, -$limit);
        }

        $processed = 0;
        $matched = 0;
        $inserted = 0;
        $school_request_replies = 0;
        $ft_uid = defined('FT_UID') ? FT_UID : 1;
        $ft_peek = defined('FT_PEEK') ? FT_PEEK : 2;

        foreach ($new_uids as $uid) {
            $uid = (int) $uid;
            if ($uid < 1) {
                continue;
            }
            $processed++;
            $overview_rows = @imap_fetch_overview($inbox, (string) $uid, $ft_uid);
            $overview = (is_array($overview_rows) && !empty($overview_rows[0])) ? $overview_rows[0] : null;
            $from_raw = $overview && isset($overview->from) ? (string) $overview->from : '';
            $subject_raw = $overview && isset($overview->subject) ? (string) $overview->subject : '';
            $message_id_raw = $overview && isset($overview->message_id) ? (string) $overview->message_id : '';
            $date_raw = $overview && isset($overview->date) ? (string) $overview->date : '';
            $header_text = (string) @imap_fetchheader($inbox, (string) $uid, $ft_uid);
            $body_raw = (string) @imap_fetchbody($inbox, (string) $uid, '1', $ft_uid | $ft_peek);
            if ($body_raw === '') {
                $body_raw = (string) @imap_body($inbox, (string) $uid, $ft_uid | $ft_peek);
            }
            $body_text = $this->decode_inbound_email_body_text($body_raw);
            $snippet_source = $body_text !== '' ? $body_text : (string) $subject_raw;
            $snippet = trim((string) preg_replace('/\s+/', ' ', (string) wp_strip_all_tags($snippet_source)));
            if ($snippet === '') {
                $snippet = trim((string) preg_replace('/\s+/', ' ', (string) wp_strip_all_tags($subject_raw)));
            }
            if (strlen($snippet) > 240) {
                $snippet = substr($snippet, 0, 240) . '...';
            }

            $thread_key = '';
            if ($header_text !== '' && preg_match('/^X-CMN-Thread-Key:\s*([A-Za-z0-9_\-]+)/mi', $header_text, $m)) {
                $thread_key = sanitize_text_field((string) $m[1]);
            }
            $in_reply_to = '';
            if ($header_text !== '' && preg_match('/^In-Reply-To:\s*<?([^>\r\n]+)>?/mi', $header_text, $m)) {
                $in_reply_to = sanitize_text_field((string) $m[1]);
            }

            $from_email = '';
            if ($from_raw !== '' && preg_match('/<([^>]+)>/', $from_raw, $m)) {
                $from_email = sanitize_email((string) $m[1]);
            }
            if ($from_email === '') {
                $from_email = sanitize_email(trim($from_raw));
            }
            if ($from_email === '') {
                continue;
            }

            $message_id = trim((string) $message_id_raw);
            $message_id = trim($message_id, '<>');
            $message_id = sanitize_text_field($message_id);
            if ($message_id === '') {
                $message_id = 'uid_' . $uid . '_' . substr(md5($from_email . '|' . $subject_raw . '|' . $date_raw), 0, 16);
            }
            $exists = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$inbound_table} WHERE message_id = %s LIMIT 1",
                $message_id
            ));
            if ($exists > 0) {
                if ($uid > $last_uid) {
                    $last_uid = $uid;
                }
                continue;
            }

            $matched_send = null;
            if ($thread_key !== '') {
                $matched_send = $wpdb->get_row($wpdb->prepare(
                    "SELECT * FROM {$sends_table} WHERE thread_key = %s ORDER BY id DESC LIMIT 1",
                    $thread_key
                ), ARRAY_A);
            }
            if (!$matched_send && $in_reply_to !== '') {
                $matched_send = $wpdb->get_row($wpdb->prepare(
                    "SELECT * FROM {$sends_table} WHERE message_id = %s ORDER BY id DESC LIMIT 1",
                    $in_reply_to
                ), ARRAY_A);
            }
            if (!$matched_send) {
                $matched_send = $wpdb->get_row($wpdb->prepare(
                    "SELECT * FROM {$sends_table} WHERE to_email = %s AND status IN ('sent','replied','failed') ORDER BY sent_at DESC, id DESC LIMIT 1",
                    $from_email
                ), ARRAY_A);
            }

            $school_id = 0;
            $campaign_id = 0;
            if ($matched_send) {
                $school_id = (int) ($matched_send['school_id'] ?? 0);
                $campaign_id = (int) ($matched_send['campaign_id'] ?? 0);
            }
            if ($school_id < 1) {
                $school_id = $this->find_marketing_school_id_by_email($from_email);
            }

            $resolved_school_request_id = $this->resolve_school_request_school_id_from_inbound(
                $from_email,
                (string) $subject_raw,
                (string) $body_text,
                $school_id
            );
            if ($resolved_school_request_id > 0) {
                $school_id = (int) $resolved_school_request_id;
            }

            $received_at = current_time('mysql');
            if ($date_raw !== '') {
                $date_ts = strtotime($date_raw);
                if ($date_ts !== false) {
                    $received_at = gmdate('Y-m-d H:i:s', $date_ts + (get_option('gmt_offset') * HOUR_IN_SECONDS));
                }
            }

            $wpdb->insert($inbound_table, [
                'school_id' => $school_id ?: null,
                'campaign_id' => $campaign_id ?: null,
                'message_id' => $message_id,
                'in_reply_to' => $in_reply_to,
                'from_email' => $from_email,
                'subject' => sanitize_text_field((string) $subject_raw),
                'snippet' => sanitize_textarea_field($snippet),
                'received_at' => $received_at,
            ], ['%d', '%d', '%s', '%s', '%s', '%s', '%s', '%s']);
            if ((int) $wpdb->insert_id > 0) {
                $inserted++;
            }

            $school_reply_recorded = $this->record_school_request_inbound_reply(
                $school_id,
                $from_email,
                (string) $subject_raw,
                (string) $body_text,
                $snippet,
                $received_at,
                $message_id
            );
            if ($school_reply_recorded) {
                $school_request_replies++;
            }

            if ($matched_send && !empty($matched_send['id'])) {
                $matched++;
                $send_id = (int) $matched_send['id'];
                $current_status = sanitize_key((string) ($matched_send['status'] ?? 'sent'));
                if ($current_status !== 'replied') {
                    $wpdb->update($sends_table, [
                        'status' => 'replied',
                        'replied_at' => current_time('mysql'),
                    ], ['id' => $send_id], ['%s', '%s'], ['%d']);
                }
                if ($school_id > 0) {
                    $this->insert_activity_row([
                        'entity_type' => 'school',
                        'entity_ref' => (string) $school_id,
                        'activity_type' => 'email',
                        'subject' => 'Marketing reply received',
                        'notes' => sanitize_text_field((string) $subject_raw),
                        'created_by' => 0,
                    ]);
                    $manager_user_id = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
                    $marketing_link = add_query_arg(['view' => 'marketing'], $this->get_portal_base_url());
                    if ($manager_user_id > 0) {
                        $this->add_notification(
                            $manager_user_id,
                            'marketing_reply',
                            'Marketing reply received',
                            get_the_title($school_id) . ' replied to campaign outreach.',
                            $marketing_link
                        );
                    } else {
                        foreach ($this->get_admin_users_for_support() as $admin_notify_user_id) {
                            $this->add_notification(
                                (int) $admin_notify_user_id,
                                'marketing_reply',
                                'Marketing reply received',
                                get_the_title($school_id) . ' replied to campaign outreach.',
                                $marketing_link
                            );
                        }
                    }
                }
            }

            if ($uid > $last_uid) {
                $last_uid = $uid;
            }
        }

        update_option('cmn_marketing_imap_last_uid', $last_uid, false);
        @imap_close($inbox);

        return [
            'ok' => true,
            'message' => 'Inbound poll completed.',
            'processed' => $processed,
            'matched' => $matched,
            'inserted' => $inserted,
            'school_request_replies' => $school_request_replies,
            'last_uid' => $last_uid,
        ];
    }

    private function add_candidate_cv_reconversion_notification($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if (!$candidate_id) {
            return;
        }
        $candidate_name = (string) get_the_title($candidate_id);
        $portal_link = add_query_arg([
            'view' => 'cv_converter',
            'candidate_id' => $candidate_id,
        ], $this->get_portal_base_url());
        foreach ($this->get_staff_admin_users_for_cv_notifications() as $user_id) {
            $this->add_notification(
                (int) $user_id,
                'candidate_cv_reconversion_required',
                'Candidate updated CV - reconversion required.',
                $candidate_name !== '' ? ($candidate_name . ' requires CV reconversion.') : 'Candidate requires CV reconversion.',
                $portal_link
            );
        }
    }

    private function add_candidate_cv_audit_entry($candidate_id, $subject, $notes = '', $created_by = 0) {
        $candidate_id = (int) $candidate_id;
        if (!$candidate_id) {
            return 0;
        }
        return $this->insert_activity_row([
            'entity_type' => 'contact',
            'entity_ref' => (string) $candidate_id,
            'activity_type' => 'note',
            'subject' => sanitize_text_field((string) $subject),
            'notes' => sanitize_textarea_field((string) $notes),
            'created_by' => $created_by ? (int) $created_by : get_current_user_id(),
        ]);
    }

    private function get_candidate_cv_original_attachment_id($candidate_id, $candidate_user_id = 0) {
        $candidate_id = (int) $candidate_id;
        if (!$candidate_id) {
            return 0;
        }
        $attachment_id = (int) get_post_meta($candidate_id, 'cmn_cv_original_attachment_id', true);
        if ($attachment_id > 0) {
            return $attachment_id;
        }
        if (!$candidate_user_id) {
            $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        }
        if ($candidate_user_id > 0) {
            $cv_status = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, 'cv');
            $attachment_id = (int) ($cv_status['attachment_id'] ?? 0);
            if ($attachment_id > 0) {
                update_post_meta($candidate_id, 'cmn_cv_original_attachment_id', $attachment_id);
                $uploaded_at = (string) ($cv_status['uploaded_at'] ?? '');
                if ($uploaded_at !== '') {
                    update_post_meta($candidate_id, 'cmn_cv_original_uploaded_at', $uploaded_at);
                }
            }
        }
        return $attachment_id;
    }

    private function get_candidate_cv_formatted_attachment_id($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if (!$candidate_id) {
            return 0;
        }
        if ((string) get_post_meta($candidate_id, 'cmn_cv_formatted_outdated', true) === '1') {
            return 0;
        }
        $attachment_id = (int) get_post_meta($candidate_id, 'cmn_cv_formatted_attachment_id', true);
        if ($attachment_id < 1) {
            return 0;
        }
        if (get_post_type($attachment_id) !== 'attachment') {
            return 0;
        }
        return $attachment_id;
    }

    private function get_candidate_cv_formatted_status($candidate_id) {
        $candidate_id = (int) $candidate_id;
        $attachment_id = $this->get_candidate_cv_formatted_attachment_id($candidate_id);
        $generated_at = (string) get_post_meta($candidate_id, 'cmn_cv_formatted_generated_at', true);
        $generated_by = (int) get_post_meta($candidate_id, 'cmn_cv_formatted_generated_by', true);
        $version = (string) get_post_meta($candidate_id, 'cmn_cv_formatted_version', true);
        $generated_by_name = '';
        if ($generated_by > 0) {
            $user = get_user_by('id', $generated_by);
            if ($user instanceof WP_User) {
                $generated_by_name = (string) $user->display_name;
            }
        }
        $filename = '';
        $filesize_label = '';
        if ($attachment_id > 0) {
            $file = get_attached_file($attachment_id);
            if ($file) {
                $filename = basename($file);
                $size = @filesize($file);
                if ($size !== false && (int) $size > 0) {
                    $filesize_label = size_format((int) $size);
                }
            }
        }
        return [
            'available' => $attachment_id > 0,
            'attachment_id' => $attachment_id,
            'filename' => $filename,
            'filesize_label' => $filesize_label,
            'generated_at' => $generated_at,
            'generated_at_label' => $generated_at !== '' ? date_i18n('M j, Y g:ia', strtotime($generated_at)) : '',
            'generated_by' => $generated_by,
            'generated_by_name' => $generated_by_name,
            'version' => $version,
            'outdated' => (string) get_post_meta($candidate_id, 'cmn_cv_formatted_outdated', true) === '1',
        ];
    }

    private function mark_candidate_formatted_cv_outdated($candidate_id, $notify = true) {
        $candidate_id = (int) $candidate_id;
        if (!$candidate_id) {
            return false;
        }
        $has_formatted = (int) get_post_meta($candidate_id, 'cmn_cv_formatted_attachment_id', true) > 0;
        if (!$has_formatted) {
            return false;
        }
        update_post_meta($candidate_id, 'cmn_cv_formatted_outdated', '1');
        if ($notify) {
            $this->add_candidate_cv_reconversion_notification($candidate_id);
        }
        return true;
    }

    private function get_cv_converter_token_transient_key($token) {
        $token = trim((string) $token);
        if ($token === '') {
            return '';
        }
        return 'cmn_cv_converter_' . substr(hash('sha256', $token), 0, 40);
    }

    private function cv_converter_base64url_encode($value) {
        $encoded = base64_encode((string) $value);
        $encoded = str_replace(['+', '/', '='], ['-', '_', ''], (string) $encoded);
        return (string) $encoded;
    }

    private function cv_converter_base64url_decode($value) {
        $value = str_replace(['-', '_'], ['+', '/'], (string) $value);
        $pad = strlen($value) % 4;
        if ($pad > 0) {
            $value .= str_repeat('=', 4 - $pad);
        }
        $decoded = base64_decode($value, true);
        return is_string($decoded) ? $decoded : '';
    }

    private function get_cv_converter_hmac_secret() {
        $secret = '';
        if (function_exists('wp_salt')) {
            $secret = (string) wp_salt('cmn_cv_converter');
            if ($secret === '') {
                $secret = (string) wp_salt('auth');
            }
        }
        if ($secret === '' && defined('AUTH_KEY')) {
            $secret = (string) AUTH_KEY;
        }
        if ($secret === '') {
            $secret = (string) NONCE_KEY;
        }
        if ($secret === '') {
            $secret = 'cmn_cv_converter_secret_fallback';
        }
        return hash('sha256', $secret . '|cmn-cv-converter-v2');
    }

    private function create_cv_converter_token($candidate_id, $staff_user_id, $ttl = 1800) {
        $candidate_id = (int) $candidate_id;
        $staff_user_id = (int) $staff_user_id;
        $ttl = max(60, (int) $ttl);
        if ($candidate_id < 1 || $staff_user_id < 1) {
            return '';
        }
        $now = time();
        $payload = [
            'candidate_id' => $candidate_id,
            'staff_user_id' => $staff_user_id,
            'iat' => $now,
            'exp' => $now + $ttl,
        ];
        $payload_json = wp_json_encode($payload);
        if (!is_string($payload_json) || $payload_json === '') {
            return '';
        }
        $payload_encoded = $this->cv_converter_base64url_encode($payload_json);
        $signature = hash_hmac('sha256', $payload_encoded, $this->get_cv_converter_hmac_secret(), true);
        return $payload_encoded . '.' . $this->cv_converter_base64url_encode($signature);
    }

    private function validate_cv_converter_hmac_token($token) {
        $token = trim((string) $token);
        if ($token === '' || strpos($token, '.') === false) {
            return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
        }
        $parts = explode('.', $token, 2);
        $payload_encoded = (string) ($parts[0] ?? '');
        $signature_encoded = (string) ($parts[1] ?? '');
        if ($payload_encoded === '' || $signature_encoded === '') {
            return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
        }
        $expected_signature_encoded = $this->cv_converter_base64url_encode(
            hash_hmac('sha256', $payload_encoded, $this->get_cv_converter_hmac_secret(), true)
        );
        if (!hash_equals($expected_signature_encoded, $signature_encoded)) {
            return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
        }
        $payload_json = $this->cv_converter_base64url_decode($payload_encoded);
        if ($payload_json === '') {
            return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
        }
        $payload = json_decode($payload_json, true);
        if (!is_array($payload)) {
            return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
        }
        $candidate_id = (int) ($payload['candidate_id'] ?? 0);
        $staff_user_id = (int) ($payload['staff_user_id'] ?? 0);
        $exp = (int) ($payload['exp'] ?? 0);
        if ($candidate_id < 1 || $staff_user_id < 1 || $exp < 1) {
            return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
        }
        if (time() > $exp) {
            return new WP_Error('cmn_expired_cv_token', 'CV converter token expired. Please reopen converter.');
        }
        return [
            'candidate_id' => $candidate_id,
            'staff_user_id' => $staff_user_id,
            'created_at' => (int) ($payload['iat'] ?? 0),
            'exp' => $exp,
            'token_type' => 'hmac',
        ];
    }

    private function validate_cv_converter_token($token, $candidate_id, $staff_user_id) {
        $candidate_id = (int) $candidate_id;
        $staff_user_id = (int) $staff_user_id;
        $token = trim((string) $token);
        if ($candidate_id < 1 || $staff_user_id < 1 || $token === '') {
            return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
        }

        if (strpos($token, '.') !== false) {
            $payload = $this->validate_cv_converter_hmac_token($token);
            if (is_wp_error($payload)) {
                return $payload;
            }
            if ((int) ($payload['candidate_id'] ?? 0) !== $candidate_id || (int) ($payload['staff_user_id'] ?? 0) !== $staff_user_id) {
                return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
            }
            return $payload;
        }

        // Backwards compatibility for legacy transient tokens.
        $key = $this->get_cv_converter_token_transient_key($token);
        if ($key === '') {
            return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
        }
        $payload = get_transient($key);
        if (!is_array($payload)) {
            return new WP_Error('cmn_expired_cv_token', 'CV converter token expired. Please reopen converter.');
        }
        if ((int) ($payload['candidate_id'] ?? 0) !== $candidate_id || (int) ($payload['staff_user_id'] ?? 0) !== $staff_user_id) {
            return new WP_Error('cmn_invalid_cv_token', 'Invalid CV converter token.');
        }
        return $payload;
    }
    private function get_current_url() {
        $scheme = is_ssl() ? 'https://' : 'http://';
        $host = $_SERVER['HTTP_HOST'] ?? '';
        $uri = $_SERVER['REQUEST_URI'] ?? '';
        return $scheme . $host . $uri;
    }

    private function get_portal_login_url() {
        return add_query_arg(['view' => 'login'], $this->get_portal_base_url());
    }

    private function get_portal_forgot_url() {
        return add_query_arg(['view' => 'forgot-password'], $this->get_portal_base_url());
    }

    private function get_portal_reset_url($login, $key) {
        return add_query_arg([
            'view' => 'set-password',
            'login' => rawurlencode($login),
            'key' => rawurlencode($key),
        ], $this->get_portal_base_url());
    }

    private function get_portal_logout_url($redirect_to = '') {
        $logout_url = add_query_arg([
            'view' => 'logout',
            'candidate' => false,
            'school' => false,
            'cmn_tab' => false,
        ], $this->get_portal_base_url());

        $redirect_to = is_string($redirect_to) ? trim($redirect_to) : '';
        if ($redirect_to !== '') {
            $validated_redirect = wp_validate_redirect($redirect_to, '');
            if ($validated_redirect !== '') {
                $logout_url = add_query_arg(['redirect_to' => $validated_redirect], $logout_url);
            }
        }

        return $logout_url;
    }

    private function portal_safe_redirect($url) {
        $default = $this->get_portal_base_url();
        $target = wp_validate_redirect((string) $url, $default);
        if (!headers_sent()) {
            wp_safe_redirect($target);
            exit;
        }
        $escaped_target = esc_url($target);
        echo '<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=' . $escaped_target . '"></head><body>';
        echo '<p>Redirecting... <a href="' . $escaped_target . '">Continue</a></p>';
        echo '<script>window.location.href=' . wp_json_encode($target) . ';</script>';
        echo '</body></html>';
        exit;
    }

    private function get_candidate_verify_url($user_id, $token, $login = '', $key = '') {
        $args = [
            'view' => 'candidate-verify',
            'uid' => (int) $user_id,
            'token' => rawurlencode($token),
        ];
        if ($login !== '' && $key !== '') {
            $args['login'] = rawurlencode($login);
            $args['key'] = rawurlencode($key);
        }
        return add_query_arg($args, $this->get_portal_base_url());
    }

    public function handle_login_redirect($redirect_to, $requested_redirect_to, $user) {
        if (!$user || is_wp_error($user)) {
            return $redirect_to;
        }
        $user_id = isset($user->ID) ? (int) $user->ID : 0;
        if (!$user_id) {
            return $redirect_to;
        }
        $portal_base = $this->get_portal_base_url();
        $requested_redirect_to = is_string($requested_redirect_to) ? trim($requested_redirect_to) : '';
        if ($requested_redirect_to !== '' && $this->is_admin_user($user_id)) {
            $requested_valid = wp_validate_redirect($requested_redirect_to, '');
            if ($requested_valid !== '') {
                $requested_path = (string) wp_parse_url($requested_valid, PHP_URL_PATH);
                $requested_query = (string) wp_parse_url($requested_valid, PHP_URL_QUERY);
                $requested_args = [];
                if ($requested_query !== '') {
                    parse_str($requested_query, $requested_args);
                }
                $request_admin_flag = isset($requested_args['cmn_admin']) && (string) $requested_args['cmn_admin'] === '1';
                if (strpos($requested_path, '/wp-admin') === 0 || $request_admin_flag) {
                    return $requested_valid;
                }
            }
        }
        if ($this->is_admin_user($user_id) || $this->is_staff_role($user_id) || $this->is_account_manager_user($user_id)) {
            return add_query_arg(['view' => 'dashboard'], $portal_base);
        }
        if ($this->is_candidate_user($user_id)) {
            return add_query_arg(['view' => 'candidate-dashboard'], $portal_base);
        }
        if ($this->is_school_user($user_id)) {
            return add_query_arg(['view' => 'school-dashboard'], $portal_base);
        }
        return $portal_base;
    }

    public function handle_logout_redirect($redirect_to, $requested_redirect_to, $user) {
        return $this->get_portal_base_url();
    }

    public function block_wp_admin_for_non_admins() {
        if (!is_user_logged_in()) {
            return;
        }
        if (defined('DOING_AJAX') && DOING_AJAX) {
            return;
        }
        if (defined('DOING_CRON') && DOING_CRON) {
            return;
        }
        if ($this->is_admin_user()) {
            return;
        }
        if (is_admin()) {
            global $pagenow;
            if (is_string($pagenow) && $pagenow === 'admin-post.php') {
                // Allow secured form handlers (nonce/capability checked in each handler).
                return;
            }
            $page = sanitize_key((string) ($_GET['page'] ?? ''));
            if ($page === 'cmn-automation' && $this->can_manage_automation(get_current_user_id())) {
                return;
            }
            $action = sanitize_key((string) ($_REQUEST['action'] ?? ''));
            if ($action !== '' && in_array($action, ['cmn_save_automation_rule', 'cmn_toggle_automation_rule', 'cmn_export_automation_logs', 'cmn_run_automation_smoke_test'], true) && $this->can_manage_automation(get_current_user_id())) {
                return;
            }
            wp_redirect($this->get_portal_base_url());
            exit;
        }
    }

    public function redirect_legacy_portal_paths() {
        if (is_admin()) {
            return;
        }
        $path = wp_parse_url($_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH);
        if (!$path) {
            return;
        }
        $normalized_path = strtolower(rtrim((string) $path, '/'));
        if ($normalized_path === '/cv-converter' || strpos($normalized_path, '/cv-converter/') === 0) {
            $staff_access = is_user_logged_in() && $this->user_can_manage_cv_converter(get_current_user_id());
            if (!$staff_access) {
                $login_url = add_query_arg([
                    'view' => 'login',
                    'redirect_to' => rawurlencode(add_query_arg(['view' => 'cv_converter'], $this->get_portal_base_url())),
                ], $this->get_portal_base_url());
                wp_safe_redirect($login_url);
                exit;
            }
        }
        $legacy_paths = [
            '/covermenowone-one',
        ];
        $query = wp_parse_url($_SERVER['REQUEST_URI'] ?? '', PHP_URL_QUERY);
        $query_args = [];
        if (is_string($query) && $query !== '') {
            parse_str($query, $query_args);
        }
        $legacy_converter_paths = [
            '/cv_formatter',
            '/cv-formatter',
            '/cv_formatter/index.php',
            '/cv_formatter/app',
        ];
        $is_legacy_portal = in_array($normalized_path, $legacy_paths, true);
        $is_legacy_converter = in_array($normalized_path, $legacy_converter_paths, true);
        $is_converter_flag = isset($query_args['converter']) && (string) $query_args['converter'] === '1';
        $is_converter_root = ($normalized_path === '/cv-converter');
        $is_converter_runtime = !empty($query_args['candidate_id']) || !empty($query_args['portal_token']);
        $is_converter_request = $is_legacy_converter || $is_converter_flag || ($is_converter_root && !$is_converter_runtime);
        if (!$is_legacy_portal && !$is_converter_request) {
            return;
        }
        if ($is_legacy_portal && !$is_converter_request) {
            $portal_target = $this->get_portal_base_url();
            if (!is_string($portal_target) || $portal_target === '') {
                return;
            }
            $safe_query_args = [];
            foreach ((array) $query_args as $arg_key => $arg_value) {
                $safe_key = sanitize_key((string) $arg_key);
                if ($safe_key === '' || is_array($arg_value)) {
                    continue;
                }
                $safe_query_args[$safe_key] = sanitize_text_field((string) $arg_value);
            }
            if (!empty($safe_query_args)) {
                $portal_target = add_query_arg($safe_query_args, $portal_target);
            }
            wp_safe_redirect($portal_target, 301);
            exit;
        }
        $target_args = [];
        if (!empty($query_args['candidate_id'])) {
            $target_args['candidate_id'] = (int) $query_args['candidate_id'];
        }
        if (!empty($query_args['s'])) {
            $target_args['s'] = sanitize_text_field((string) $query_args['s']);
        }
        $target_args['view'] = 'cv_converter';
        $target = add_query_arg($target_args, $this->get_portal_base_url());
        wp_safe_redirect($target, 301);
        exit;
    }

    public function handle_portal_route_fallback() {
        if (is_admin()) {
            return;
        }
        $training_console_requested = isset($_GET['cmn_training_console']) && (string) sanitize_text_field((string) wp_unslash($_GET['cmn_training_console'])) === '1';
        if ($training_console_requested) {
            $portal_page = $this->find_portal_page();
            if ($portal_page instanceof WP_Post) {
                if ((int) get_queried_object_id() === (int) $portal_page->ID) {
                    return;
                }
                $query_args = [];
                foreach ((array) $_GET as $arg_key => $arg_value) {
                    $safe_key = sanitize_key((string) $arg_key);
                    if ($safe_key === '') {
                        continue;
                    }
                    if (is_array($arg_value)) {
                        continue;
                    }
                    $query_args[$safe_key] = sanitize_text_field((string) wp_unslash($arg_value));
                }
                $query_args['cmn_training_console'] = 1;
                $target = add_query_arg($query_args, get_permalink($portal_page));
                if (is_string($target) && $target !== '') {
                    wp_safe_redirect($target, 302);
                    exit;
                }
            }
        }
        $path = (string) wp_parse_url($_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH);
        $normalized_path = strtolower(rtrim($path, '/'));
        if ($normalized_path !== '/portal') {
            return;
        }
        $portal_page = $this->find_portal_page();
        if (!$portal_page instanceof WP_Post) {
            return;
        }
        if ((int) get_queried_object_id() === (int) $portal_page->ID) {
            return;
        }
        $target = get_permalink($portal_page);
        if (!is_string($target) || $target === '') {
            return;
        }
        $target_args = [];
        foreach ((array) $_GET as $arg_key => $arg_value) {
            $safe_key = sanitize_key((string) $arg_key);
            if ($safe_key === '' || is_array($arg_value)) {
                continue;
            }
            $target_args[$safe_key] = sanitize_text_field((string) wp_unslash($arg_value));
        }
        if (!empty($target_args)) {
            $target = add_query_arg($target_args, $target);
        }
        wp_safe_redirect($target, 301);
        exit;
    }

    public function handle_marketing_unsubscribe() {
        if (is_admin()) {
            return;
        }
        if (!isset($_GET['cmn_unsub']) || (string) $_GET['cmn_unsub'] !== '1') {
            return;
        }
        $token = isset($_GET['token']) ? sanitize_text_field((string) $_GET['token']) : '';
        $decoded = $this->decode_marketing_unsubscribe_token($token);
        if (!$decoded) {
            status_header(403);
            wp_die('Invalid unsubscribe link.', 'Unsubscribe', ['response' => 403]);
        }
        $email = (string) ($decoded['email'] ?? '');
        $entity_type = (string) ($decoded['entity_type'] ?? '');
        $entity_id = (int) ($decoded['entity_id'] ?? 0);
        $this->add_marketing_unsubscribe($email, $entity_type, $entity_id, 'Clicked unsubscribe link');
        if ($entity_type === 'school' && $entity_id > 0) {
            update_post_meta($entity_id, 'cmn_marketing_unsubscribed', '1');
        }
        if ($entity_type === 'contact' && $entity_id > 0) {
            update_post_meta($entity_id, 'cmn_marketing_unsubscribed', '1');
        }
        $message = 'You have been unsubscribed from marketing emails.';
        echo '<!doctype html><html><head><meta charset="utf-8"><title>Unsubscribed</title><style>body{font-family:Arial,sans-serif;background:#111;color:#fff;padding:24px}.card{max-width:640px;margin:40px auto;background:#1b1b1b;border:1px solid #333;border-radius:10px;padding:24px}h1{margin:0 0 8px;color:#e43d30}p{margin:0;color:#ddd}</style></head><body><div class="card"><h1>CoverMeNow ONE</h1><p>' . esc_html($message) . '</p></div></body></html>';
        exit;
    }

    public function redirect_wp_login_for_portal_users() {
        $action = isset($_REQUEST['action']) ? sanitize_text_field($_REQUEST['action']) : 'login';
        $is_admin_override = isset($_GET['cmn_admin']) && $_GET['cmn_admin'] === '1';
        if ($action === 'logout') {
            if ($is_admin_override) {
                return;
            }
            wp_safe_redirect($this->get_portal_logout_url());
            exit;
        }
        if (is_user_logged_in() && $this->is_admin_user()) {
            return;
        }
        if ($is_admin_override) {
            return;
        }
        $redirect_to_raw = isset($_REQUEST['redirect_to']) ? wp_unslash((string) $_REQUEST['redirect_to']) : '';
        if ($redirect_to_raw !== '') {
            $redirect_to = wp_validate_redirect($redirect_to_raw, '');
            if ($redirect_to !== '') {
                $redirect_path = (string) wp_parse_url($redirect_to, PHP_URL_PATH);
                if (strpos($redirect_path, '/wp-admin') === 0) {
                    // Allow core wp-admin login flow (including host-generated admin links).
                    return;
                }
                $redirect_query = (string) wp_parse_url($redirect_to, PHP_URL_QUERY);
                $redirect_args = [];
                if ($redirect_query !== '') {
                    parse_str($redirect_query, $redirect_args);
                }
                if (isset($redirect_args['cmn_admin']) && (string) $redirect_args['cmn_admin'] === '1') {
                    return;
                }
            }
        }
        if (in_array($action, ['rp', 'resetpass'], true)) {
            $key = sanitize_text_field($_REQUEST['key'] ?? '');
            $login = sanitize_text_field($_REQUEST['login'] ?? '');
            if ($key && $login) {
                wp_redirect($this->get_portal_reset_url($login, $key));
                exit;
            }
        }
        if ($action === 'lostpassword') {
            wp_redirect($this->get_portal_forgot_url());
            exit;
        }
        wp_redirect($this->get_portal_login_url());
        exit;
    }

    public function configure_candidate_upload_runtime_limits() {
        if (defined('WP_CLI') && WP_CLI) {
            return;
        }
        @ini_set('upload_max_filesize', '32M');
        @ini_set('post_max_size', '64M');
        @ini_set('memory_limit', '256M');
        @ini_set('max_execution_time', '120');
        @ini_set('max_input_time', '120');
    }

    private function get_candidate_doc_target_limit_bytes() {
        return 20 * 1024 * 1024;
    }

    public function filter_candidate_upload_size_limit($size) {
        $target = $this->get_candidate_doc_target_limit_bytes();
        if ($size < $target) {
            return $target;
        }
        return $size;
    }

    private function get_candidate_doc_allowed_mimes($doc_type = '') {
        $common = [
            'pdf' => 'application/pdf',
            'jpg' => 'image/jpeg',
            'jpeg' => 'image/jpeg',
            'png' => 'image/png',
        ];
        if ($doc_type === 'cv' || $doc_type === '') {
            $common['doc'] = 'application/msword';
            $common['docx'] = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
        }
        return $common;
    }

    public function prefilter_candidate_doc_upload($file) {
        if (!defined('DOING_AJAX') || !DOING_AJAX) {
            return $file;
        }
        $action = isset($_REQUEST['action']) ? sanitize_key((string) $_REQUEST['action']) : '';
        if ($action !== 'cmn_candidate_upload_doc') {
            return $file;
        }

        $doc_type = sanitize_key((string) ($_REQUEST['doc_type'] ?? ''));
        $allowed = $this->get_candidate_doc_allowed_mimes($doc_type);
        $extension = strtolower((string) pathinfo((string) ($file['name'] ?? ''), PATHINFO_EXTENSION));
        if (!$extension || !isset($allowed[$extension])) {
            $file['error'] = 'File type not allowed. Upload PDF, JPG, JPEG, PNG' . ($doc_type === 'cv' ? ', DOC or DOCX.' : '.');
            return $file;
        }

        $effective_limit = (int) wp_max_upload_size();
        $target_limit = (int) $this->get_candidate_doc_target_limit_bytes();
        $requested_max = max(1, min($target_limit, $effective_limit > 0 ? $effective_limit : $target_limit));
        $size = isset($file['size']) ? (int) $file['size'] : 0;
        if ($size > $requested_max) {
            $msg = 'File is too large. Maximum supported upload is ' . size_format($requested_max) . '.';
            if ($effective_limit > 0 && $effective_limit < $target_limit) {
                $msg .= ' Hosting limits are currently too low. Please ask support to raise upload_max_filesize/post_max_size.';
            }
            $file['error'] = $msg;
            return $file;
        }

        return $file;
    }

    private function get_candidate_doc_host_limit_warning() {
        $effective_limit = (int) wp_max_upload_size();
        $target_limit = (int) $this->get_candidate_doc_target_limit_bytes();
        if ($effective_limit >= $target_limit) {
            return '';
        }
        return 'Hosting upload limits are too low for candidate documents. Current limit: '
            . size_format(max(1, $effective_limit))
            . '. Recommended minimum: '
            . size_format($target_limit)
            . '. Increase PHP upload_max_filesize and post_max_size in hosting settings.';
    }

    public function maybe_hide_admin_bar($show) {
        if (!is_user_logged_in()) {
            return $show;
        }
        $user = wp_get_current_user();
        if (!$user || !$user->ID) {
            return $show;
        }
        if ($this->is_admin_user((int) $user->ID)) {
            return $show;
        }
        return false;
    }

