    private function normalize_staff_lounge_thread_type($thread_type = '') {
        $thread_type = sanitize_key((string) $thread_type);
        if (in_array($thread_type, ['staff_lounge', 'stafflounge', 'internal_chat', 'internal', 'messages', 'chat'], true)) {
            return 'staff_lounge';
        }
        return $thread_type !== '' ? $thread_type : 'staff_lounge';
    }

    private function get_staff_lounge_messages($thread_type = 'staff_lounge', $limit = 120) {
        global $wpdb;
        $table = $this->get_staff_lounge_table();
        $thread_type = $this->normalize_staff_lounge_thread_type($thread_type);
        $limit = max(20, min(200, (int) $limit));
        $rows = (array) $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE thread_type = %s ORDER BY created_at DESC, id DESC LIMIT %d",
            $thread_type,
            $limit
        ), ARRAY_A);
        if (!$rows) {
            return [];
        }
        $rows = array_reverse($rows);
        $output = [];
        foreach ($rows as $row) {
            $sender_user_id = (int) ($row['sender_user_id'] ?? 0);
            $sender_name = 'Staff';
            $sender_role = 'staff';
            if ($sender_user_id > 0) {
                $u = get_user_by('id', $sender_user_id);
                if ($u) {
                    $sender_name = trim((string) ($u->display_name ?: $u->user_login));
                    if ($this->is_admin_user($sender_user_id)) {
                        $sender_role = 'admin';
                    } elseif ($this->is_account_manager_user($sender_user_id)) {
                        $sender_role = 'account_manager';
                    } elseif ($this->is_staff_role($sender_user_id)) {
                        $sender_role = 'staff';
                    }
                }
            }
            $output[] = [
                'id' => (int) ($row['id'] ?? 0),
                'thread_type' => $thread_type,
                'sender_user_id' => $sender_user_id,
                'sender_name' => $sender_name,
                'sender_role' => $sender_role,
                'message' => (string) ($row['message'] ?? ''),
                'created_at' => !empty($row['created_at']) ? date_i18n('M j, Y g:ia', strtotime((string) $row['created_at'])) : '',
            ];
        }
        return $output;
    }

    private function add_staff_lounge_message($sender_user_id, $message, $thread_type = 'staff_lounge') {
        global $wpdb;
        $table = $this->get_staff_lounge_table();
        $sender_user_id = (int) $sender_user_id;
        $thread_type = $this->normalize_staff_lounge_thread_type($thread_type);
        $message = trim(wp_strip_all_tags((string) $message));
        if ($sender_user_id < 1 || $message === '') {
            return 0;
        }
        $wpdb->insert($table, [
            'thread_type' => $thread_type,
            'sender_user_id' => $sender_user_id,
            'message' => $message,
            'created_at' => current_time('mysql'),
        ], ['%s', '%d', '%s', '%s']);
        return (int) $wpdb->insert_id;
    }

    private function get_support_ticket_columns() {
        static $columns = null;
        if (is_array($columns)) {
            return $columns;
        }
        global $wpdb;
        $table = $this->get_support_ticket_table();
        $rows = $wpdb->get_results("SHOW COLUMNS FROM {$table}", ARRAY_A);
        $columns = [];
        if (is_array($rows)) {
            foreach ($rows as $row) {
                if (!empty($row['Field'])) {
                    $columns[] = (string) $row['Field'];
                }
            }
        }
        return $columns;
    }

    private function support_ticket_has_column($column) {
        $column = (string) $column;
        if ($column === '') {
            return false;
        }
        return in_array($column, $this->get_support_ticket_columns(), true);
    }

    private function get_support_owner_user_id($ticket) {
        if (!is_array($ticket)) {
            return 0;
        }
        if (isset($ticket['created_by_user_id']) && (int) $ticket['created_by_user_id'] > 0) {
            return (int) $ticket['created_by_user_id'];
        }
        if (isset($ticket['user_id']) && (int) $ticket['user_id'] > 0) {
            return (int) $ticket['user_id'];
        }
        return 0;
    }

    private function normalize_support_status($status) {
        $status = sanitize_key((string) $status);
        if (in_array($status, ['closed', 'resolved', 'done'], true)) {
            return 'closed';
        }
        if (in_array($status, ['new'], true)) {
            return 'new';
        }
        if (in_array($status, ['awaiting_admin', 'awaiting_user', 'reopened', 'reply', 'open'], true)) {
            return 'open';
        }
        if ($status === '') {
            return 'open';
        }
        return 'open';
    }

    private function normalize_support_ticket_for_view($ticket, $is_staff_view = false) {
        $normalized = $this->normalize_support_status($ticket['status'] ?? '');
        if (!$is_staff_view && $normalized === 'new') {
            $normalized = 'open';
        }
        if ($normalized !== 'closed' && $is_staff_view && !empty($ticket['is_new_for_admin'])) {
            $normalized = 'new';
        }
        $ticket['status'] = $normalized;
        return $ticket;
    }

    private function normalize_payroll_support_ticket_status($status) {
        $status = sanitize_key((string) $status);
        if (in_array($status, ['closed'], true)) {
            return 'closed';
        }
        if (in_array($status, ['resolved', 'done'], true)) {
            return 'resolved';
        }
        if (in_array($status, ['pending', 'awaiting_user', 'awaiting_admin'], true)) {
            return 'pending';
        }
        if (in_array($status, ['new', 'open', 'reopened', 'reply'], true)) {
            return 'open';
        }
        return 'open';
    }

    private function is_payroll_support_ticket_row($ticket) {
        if (!is_array($ticket)) {
            return false;
        }
        $category = strtolower(trim((string) ($ticket['category'] ?? '')));
        $queue_key = strtolower(trim((string) ($ticket['queue_key'] ?? '')));
        return ($category === 'payroll' || $queue_key === 'payroll');
    }

    private function get_staff_payroll_ticket_period_filter_options($max_periods = 9) {
        $max_periods = max(1, min(20, (int) $max_periods));
        $options = [];
        $seen = [];
        $period = function_exists('cmn_payroll_get_current_period')
            ? (array) cmn_payroll_get_current_period()
            : (array) $this->get_payroll_current_period();

        for ($index = 0; $index < $max_periods; $index++) {
            $period_start = $this->normalize_invoice_date((string) ($period['period_start'] ?? ''));
            $period_end = $this->normalize_invoice_date((string) ($period['period_end'] ?? ''));
            if ($period_start === '' || $period_end === '') {
                break;
            }

            $period_id = sanitize_text_field((string) ($period['period_id'] ?? ''));
            if ($period_id === '') {
                $period_id = $this->get_payroll_period_id($period_start, $period_end);
            }
            if ($period_id === '' || isset($seen[$period_id])) {
                break;
            }
            $seen[$period_id] = true;

            $label = sanitize_text_field((string) ($period['label'] ?? ''));
            if ($label === '') {
                $label = $this->get_staff_payroll_period_label_from_id($period_id);
            }

            $options[] = [
                'period_id' => $period_id,
                'label' => $label,
                'period_start' => $period_start,
                'period_end' => $period_end,
            ];

            $period = function_exists('cmn_payroll_get_period_for_date')
                ? (array) cmn_payroll_get_period_for_date($period_start . ' -1 day')
                : (array) $this->get_payroll_period_for_date($period_start . ' -1 day');
        }

        return $options;
    }

    private function get_staff_payroll_ticket_filters_from_request($actor_user_id = 0, $source = null) {
        $source = is_array($source) ? $source : $_GET;
        $actor_user_id = max(0, (int) $actor_user_id);

        $status_raw = isset($source['cmn_payroll_ticket_status'])
            ? $source['cmn_payroll_ticket_status']
            : ($source['status'] ?? 'open');
        $status = sanitize_key((string) wp_unslash($status_raw));
        if (!in_array($status, ['open', 'pending', 'resolved', 'closed'], true)) {
            $status = 'open';
        }

        $issue_type_map = $this->get_candidate_payroll_query_issue_type_map();
        $allowed_issue_types = array_merge(['any'], array_keys($issue_type_map));
        $issue_raw = isset($source['cmn_payroll_ticket_issue_type'])
            ? $source['cmn_payroll_ticket_issue_type']
            : ($source['issue_type'] ?? 'any');
        $issue_type = sanitize_key((string) wp_unslash($issue_raw));
        if (!in_array($issue_type, $allowed_issue_types, true)) {
            $issue_type = 'any';
        }

        $period_raw = isset($source['cmn_payroll_ticket_period_id'])
            ? $source['cmn_payroll_ticket_period_id']
            : ($source['period_id'] ?? 'any');
        $period_id = sanitize_text_field((string) wp_unslash($period_raw));
        if ($period_id === '') {
            $period_id = 'any';
        }

        $assignee_raw = isset($source['cmn_payroll_ticket_assignee'])
            ? $source['cmn_payroll_ticket_assignee']
            : ($source['assignee'] ?? 'any');
        $assignee = sanitize_key((string) wp_unslash($assignee_raw));
        if (!in_array($assignee, ['me', 'unassigned', 'any'], true)) {
            $assignee = 'any';
        }

        return [
            'status' => $status,
            'issue_type' => $issue_type,
            'period_id' => $period_id,
            'assignee' => $assignee,
            'actor_user_id' => $actor_user_id,
        ];
    }

    private function get_staff_payroll_ticket_filter_query_args($filters = []) {
        $filters = is_array($filters) ? $filters : [];
        return [
            'cmn_payroll_ticket_status' => sanitize_key((string) ($filters['status'] ?? 'open')),
            'cmn_payroll_ticket_issue_type' => sanitize_key((string) ($filters['issue_type'] ?? 'any')),
            'cmn_payroll_ticket_period_id' => sanitize_text_field((string) ($filters['period_id'] ?? 'any')),
            'cmn_payroll_ticket_assignee' => sanitize_key((string) ($filters['assignee'] ?? 'any')),
        ];
    }

    private function get_staff_payroll_assignee_label($assignee_user_id, $actor_user_id = 0) {
        $assignee_user_id = max(0, (int) $assignee_user_id);
        $actor_user_id = max(0, (int) $actor_user_id);
        if ($assignee_user_id < 1) {
            return 'Unassigned';
        }
        if ($actor_user_id > 0 && $assignee_user_id === $actor_user_id) {
            return 'Me';
        }
        $user = get_user_by('id', $assignee_user_id);
        if (!$user instanceof WP_User) {
            return 'User #' . $assignee_user_id;
        }
        $label = trim((string) ($user->display_name ?: $user->user_login));
        if ($label === '') {
            $label = 'User #' . $assignee_user_id;
        }
        return $label;
    }

    private function get_staff_payroll_support_ticket_rows($filters = [], $limit = 120) {
        $filters = $this->get_staff_payroll_ticket_filters_from_request(
            (int) ($filters['actor_user_id'] ?? 0),
            is_array($filters) ? $filters : []
        );
        $limit = max(1, min(400, (int) $limit));

        global $wpdb;
        $ticket_table = $this->get_support_ticket_table();
        if (!$this->candidate_rewards_table_exists($ticket_table)) {
            return [];
        }
        $meta_table = $this->get_support_payroll_query_table();
        $meta_exists = $this->candidate_rewards_table_exists($meta_table);
        $has_queue_key = $this->support_ticket_has_column('queue_key');
        $has_assignee = $this->support_ticket_has_column('assigned_to_user_id');

        $select_fields = [
            't.id',
            't.ticket_ref',
            't.subject',
            't.status',
            't.category',
            't.created_by_user_id',
            't.created_at',
            't.updated_at',
            $has_queue_key ? 't.queue_key' : "'' AS queue_key",
            $has_assignee ? 't.assigned_to_user_id' : 'NULL AS assigned_to_user_id',
        ];
        if ($meta_exists) {
            $select_fields[] = 'pq.candidate_user_id AS meta_candidate_user_id';
            $select_fields[] = 'pq.period_id AS meta_period_id';
            $select_fields[] = 'pq.period_start AS meta_period_start';
            $select_fields[] = 'pq.period_end AS meta_period_end';
            $select_fields[] = 'pq.issue_type AS meta_issue_type';
            $select_fields[] = 'pq.payout_run_id AS meta_payout_run_id';
        } else {
            $select_fields[] = 'NULL AS meta_candidate_user_id';
            $select_fields[] = "'' AS meta_period_id";
            $select_fields[] = "'' AS meta_period_start";
            $select_fields[] = "'' AS meta_period_end";
            $select_fields[] = "'' AS meta_issue_type";
            $select_fields[] = 'NULL AS meta_payout_run_id';
        }

        $where_sql = "WHERE LOWER(COALESCE(t.category, '')) = 'payroll'";
        if ($has_queue_key) {
            $where_sql = "WHERE (LOWER(COALESCE(t.category, '')) = 'payroll' OR LOWER(COALESCE(t.queue_key, '')) = 'payroll')";
        }
        $join_sql = $meta_exists ? "LEFT JOIN {$meta_table} pq ON pq.ticket_id = t.id" : '';
        $sql = "SELECT " . implode(', ', $select_fields) . "
                FROM {$ticket_table} t
                {$join_sql}
                {$where_sql}
                ORDER BY t.created_at DESC, t.id DESC
                LIMIT {$limit}";

        $rows = (array) $wpdb->get_results($sql, ARRAY_A);
        if (!is_array($rows) || !$rows) {
            return [];
        }

        $issue_type_map = $this->get_candidate_payroll_query_issue_type_map();
        $actor_user_id = max(0, (int) ($filters['actor_user_id'] ?? 0));
        $status_filter = sanitize_key((string) ($filters['status'] ?? 'open'));
        $issue_filter = sanitize_key((string) ($filters['issue_type'] ?? 'any'));
        $period_filter = sanitize_text_field((string) ($filters['period_id'] ?? 'any'));
        $assignee_filter = sanitize_key((string) ($filters['assignee'] ?? 'any'));

        $out = [];
        foreach ($rows as $row) {
            if (!$this->is_payroll_support_ticket_row($row)) {
                continue;
            }

            $normalized_status = $this->normalize_payroll_support_ticket_status((string) ($row['status'] ?? 'open'));
            if ($status_filter !== '' && $normalized_status !== $status_filter) {
                continue;
            }

            $issue_type = $this->normalize_candidate_payroll_query_issue_type((string) ($row['meta_issue_type'] ?? 'other'));
            if ($issue_filter !== 'any' && $issue_filter !== $issue_type) {
                continue;
            }

            $period_id = sanitize_text_field((string) ($row['meta_period_id'] ?? ''));
            if ($period_filter !== 'any' && $period_filter !== $period_id) {
                continue;
            }

            $assignee_user_id = max(0, (int) ($row['assigned_to_user_id'] ?? 0));
            if ($assignee_filter === 'me' && ($actor_user_id < 1 || $assignee_user_id !== $actor_user_id)) {
                continue;
            }
            if ($assignee_filter === 'unassigned' && $assignee_user_id > 0) {
                continue;
            }

            $candidate_user_id = max(0, (int) ($row['meta_candidate_user_id'] ?? 0));
            if ($candidate_user_id < 1) {
                $candidate_user_id = max(0, (int) ($row['created_by_user_id'] ?? 0));
            }
            $candidate_label = $candidate_user_id > 0
                ? $this->get_payroll_candidate_label($candidate_user_id)
                : 'Unknown candidate';

            $period_start = $this->normalize_invoice_date((string) ($row['meta_period_start'] ?? ''));
            $period_end = $this->normalize_invoice_date((string) ($row['meta_period_end'] ?? ''));
            $period_label = '—';
            if ($period_start !== '' && $period_end !== '') {
                $period_label = 'Fri ' . date_i18n('j M Y', strtotime($period_start)) . ' -> Thu ' . date_i18n('j M Y', strtotime($period_end));
            } elseif ($period_id !== '') {
                $period_label = $this->get_staff_payroll_period_label_from_id($period_id);
            }

            $created_at = $this->normalize_invoice_datetime((string) ($row['created_at'] ?? ''));
            $created_label = $created_at !== '' ? mysql2date('j M Y g:ia', $created_at, false) : '—';
            $issue_type_label = sanitize_text_field((string) ($issue_type_map[$issue_type] ?? 'Other'));
            $assignee_label = $this->get_staff_payroll_assignee_label($assignee_user_id, $actor_user_id);

            $status_label = ucfirst($normalized_status);
            $status_chip_class = 'is-warning';
            if ($normalized_status === 'pending') {
                $status_chip_class = 'is-pending';
            } elseif ($normalized_status === 'resolved') {
                $status_chip_class = 'is-approved';
            } elseif ($normalized_status === 'closed') {
                $status_chip_class = 'is-muted';
            }

            $ticket_id = (int) ($row['id'] ?? 0);
            $ticket_ref = sanitize_text_field((string) ($row['ticket_ref'] ?? ''));
            $out[] = [
                'ticket_id' => $ticket_id,
                'ticket_ref' => $ticket_ref,
                'candidate_user_id' => $candidate_user_id,
                'candidate_label' => $candidate_label,
                'period_id' => $period_id,
                'period_label' => $period_label,
                'issue_type' => $issue_type,
                'issue_type_label' => $issue_type_label,
                'status' => $normalized_status,
                'status_label' => $status_label,
                'status_chip_class' => $status_chip_class,
                'created_at' => $created_at,
                'created_label' => $created_label,
                'assignee_user_id' => $assignee_user_id,
                'assignee_label' => $assignee_label,
                'payout_run_id' => max(0, (int) ($row['meta_payout_run_id'] ?? 0)),
                'open_url' => add_query_arg([
                    'view' => 'support',
                    'ticket_id' => $ticket_id,
                    'support_filter' => 'open',
                ], $this->get_portal_base_url()),
            ];
        }

        return $out;
    }

    private function get_candidate_approved_shift_count_for_period($candidate_user_id, $period_id) {
        $candidate_user_id = max(0, (int) $candidate_user_id);
        $period_id = sanitize_text_field((string) $period_id);
        if ($candidate_user_id < 1 || $period_id === '') {
            return 0;
        }

        global $wpdb;
        $table = $this->get_candidate_pay_approvals_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return 0;
        }
        $has_dispute_flag = self::table_has_column($table, 'dispute_flag');
        $dispute_sql = $has_dispute_flag ? "AND COALESCE(dispute_flag, 0) = 0" : '';
        $count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(1)
             FROM {$table}
             WHERE candidate_user_id = %d
               AND period_id = %s
               AND approval_status = %s
               {$dispute_sql}",
            $candidate_user_id,
            $period_id,
            'approved'
        ));
        return max(0, $count);
    }

    private function get_candidate_applied_adjustment_summary_for_period($candidate_user_id, $period_id) {
        $candidate_user_id = max(0, (int) $candidate_user_id);
        $period_id = sanitize_text_field((string) $period_id);
        if ($candidate_user_id < 1 || $period_id === '') {
            return ['count' => 0, 'total' => 0.00];
        }

        global $wpdb;
        $table = $this->get_payroll_adjustments_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return ['count' => 0, 'total' => 0.00];
        }

        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT COUNT(1) AS adjustment_count, COALESCE(SUM(adjustment_amount), 0) AS adjustment_total
             FROM {$table}
             WHERE candidate_user_id = %d
               AND applied_in_period_id = %s
               AND adjustment_status = %s",
            $candidate_user_id,
            $period_id,
            'applied'
        ), ARRAY_A);
        if (!is_array($row)) {
            return ['count' => 0, 'total' => 0.00];
        }

        return [
            'count' => max(0, (int) ($row['adjustment_count'] ?? 0)),
            'total' => round((float) ($row['adjustment_total'] ?? 0), 2),
        ];
    }

    private function build_staff_payroll_ticket_context($ticket, $payroll_query_meta = []) {
        if (!is_array($ticket) || !$ticket || !$this->is_payroll_support_ticket_row($ticket)) {
            return [];
        }
        $ticket_id = max(0, (int) ($ticket['id'] ?? 0));
        if ($ticket_id < 1) {
            return [];
        }

        $payroll_query_meta = is_array($payroll_query_meta) ? $payroll_query_meta : [];
        if (!$payroll_query_meta) {
            $payroll_query_meta = $this->get_support_payroll_query_metadata_by_ticket($ticket_id);
        }
        $period_id = sanitize_text_field((string) ($payroll_query_meta['period_id'] ?? ''));
        $period_start = $this->normalize_invoice_date((string) ($payroll_query_meta['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($payroll_query_meta['period_end'] ?? ''));
        $issue_type = $this->normalize_candidate_payroll_query_issue_type((string) ($payroll_query_meta['issue_type'] ?? 'other'));
        $issue_type_map = $this->get_candidate_payroll_query_issue_type_map();

        $candidate_user_id = max(0, (int) ($payroll_query_meta['candidate_user_id'] ?? 0));
        if ($candidate_user_id < 1) {
            $candidate_user_id = (int) $this->get_support_owner_user_id($ticket);
        }
        $candidate_label = $candidate_user_id > 0
            ? $this->get_payroll_candidate_label($candidate_user_id)
            : 'Unknown candidate';

        $period_label = '—';
        if ($period_start !== '' && $period_end !== '') {
            $period_label = 'Fri ' . date_i18n('j M Y', strtotime($period_start)) . ' -> Thu ' . date_i18n('j M Y', strtotime($period_end));
        } elseif ($period_id !== '') {
            $period_label = $this->get_staff_payroll_period_label_from_id($period_id);
        }

        $payout_item = [];
        if ($candidate_user_id > 0 && $period_id !== '') {
            $payout_item = $this->get_candidate_payout_run_item_for_period($candidate_user_id, $period_id);
        }

        $bank_status_key = sanitize_key((string) ($payout_item['bank_status'] ?? ''));
        if (!in_array($bank_status_key, ['complete', 'missing'], true)) {
            $bank_status_key = ($candidate_user_id > 0 && $this->is_candidate_bank_complete_for_payroll($candidate_user_id)) ? 'complete' : 'missing';
        }
        $bank_status_label = $bank_status_key === 'complete' ? 'Complete' : 'Missing';

        $shifts_count = max(0, (int) ($payout_item['shifts_count'] ?? 0));
        if ($shifts_count < 1 && $candidate_user_id > 0 && $period_id !== '') {
            $shifts_count = $this->get_candidate_approved_shift_count_for_period($candidate_user_id, $period_id);
        }

        $gross_amount = round((float) ($payout_item['gross_amount'] ?? 0), 2);
        $payout_item_status = sanitize_key((string) ($payout_item['payout_item_status'] ?? ''));
        if (!in_array($payout_item_status, ['ready', 'hold'], true)) {
            $ack_complete = $candidate_user_id > 0 ? $this->is_candidate_self_employed_ack_complete_for_payroll($candidate_user_id) : false;
            $payout_item_status = ($bank_status_key === 'complete' && $ack_complete) ? 'ready' : 'hold';
        }

        $adjustments_total = round((float) ($payout_item['adjustments_total'] ?? 0), 2);
        $adjustment_summary = $this->get_candidate_applied_adjustment_summary_for_period($candidate_user_id, $period_id);
        $adjustment_count = max(0, (int) ($adjustment_summary['count'] ?? 0));
        if ($adjustment_count > 0) {
            $adjustments_total = round((float) ($adjustment_summary['total'] ?? $adjustments_total), 2);
        }

        return [
            'ticket_id' => $ticket_id,
            'candidate_user_id' => $candidate_user_id,
            'candidate_label' => $candidate_label,
            'period_id' => $period_id,
            'period_label' => $period_label,
            'issue_type' => $issue_type,
            'issue_type_label' => sanitize_text_field((string) ($issue_type_map[$issue_type] ?? 'Other')),
            'bank_status' => $bank_status_key,
            'bank_status_label' => $bank_status_label,
            'shifts_count' => $shifts_count,
            'gross_amount' => $gross_amount,
            'payout_item_status' => $payout_item_status,
            'payout_item_status_label' => $payout_item_status === 'ready' ? 'Ready' : 'Hold',
            'adjustments_total' => $adjustments_total,
            'adjustments_count' => $adjustment_count,
            'payout_run_id' => max(0, (int) ($payout_item['payout_run_id'] ?? ($payroll_query_meta['payout_run_id'] ?? 0))),
        ];
    }

    private function log_payroll_ticket_status_changed_event($ticket_id, $from_status, $to_status, $actor_user_id = 0) {
        $ticket_id = max(0, (int) $ticket_id);
        if ($ticket_id < 1 || !function_exists('cmn_audit_log_event')) {
            return;
        }
        $from_status = $this->normalize_payroll_support_ticket_status($from_status);
        $to_status = $this->normalize_payroll_support_ticket_status($to_status);
        $actor_user_id = max(0, (int) $actor_user_id);

        cmn_audit_log_event([
            'module' => 'support',
            'entity_type' => 'ticket',
            'entity_id' => $ticket_id,
            'event_type' => 'payroll_ticket_status_changed',
            'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
            'metadata' => [
                'ticket_id' => $ticket_id,
                'from_status' => $from_status,
                'to_status' => $to_status,
                'actor_user_id' => $actor_user_id,
            ],
        ]);
    }

    private function log_payroll_ticket_assigned_event($ticket_id, $from_assignee_user_id, $to_assignee_user_id, $actor_user_id = 0, $from_status = '', $to_status = '') {
        $ticket_id = max(0, (int) $ticket_id);
        if ($ticket_id < 1 || !function_exists('cmn_audit_log_event')) {
            return;
        }
        $from_assignee_user_id = max(0, (int) $from_assignee_user_id);
        $to_assignee_user_id = max(0, (int) $to_assignee_user_id);
        if ($from_assignee_user_id === $to_assignee_user_id) {
            return;
        }
        $actor_user_id = max(0, (int) $actor_user_id);
        $from_status = $this->normalize_payroll_support_ticket_status($from_status);
        $to_status = $this->normalize_payroll_support_ticket_status($to_status !== '' ? $to_status : $from_status);

        cmn_audit_log_event([
            'module' => 'support',
            'entity_type' => 'ticket',
            'entity_id' => $ticket_id,
            'event_type' => 'payroll_ticket_assigned',
            'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
            'metadata' => [
                'ticket_id' => $ticket_id,
                'from_status' => $from_status,
                'to_status' => $to_status,
                'actor_user_id' => $actor_user_id,
                'from_assigned_to' => $from_assignee_user_id,
                'to_assigned_to' => $to_assignee_user_id,
            ],
        ]);
    }

    private function get_support_message_attachments($message_row) {
        $ids = [];
        if (!empty($message_row['attachment_ids'])) {
            $raw = json_decode((string) $message_row['attachment_ids'], true);
            if (is_array($raw)) {
                foreach ($raw as $id) {
                    $id = (int) $id;
                    if ($id > 0) {
                        $ids[] = $id;
                    }
                }
            }
        }
        $attachments = [];
        foreach ($ids as $id) {
            $url = wp_get_attachment_url($id);
            if (!$url) {
                continue;
            }
            $path = get_attached_file($id);
            $attachments[] = [
                'id' => $id,
                'filename' => $path ? basename($path) : ('Attachment #' . $id),
                'url' => esc_url_raw($url),
            ];
        }
        return $attachments;
    }

    private function handle_support_attachments_upload($field_name = 'attachments') {
        $results = [
            'ids' => [],
            'errors' => [],
        ];
        if (empty($_FILES[$field_name]) || !is_array($_FILES[$field_name])) {
            return $results;
        }
        $files = $_FILES[$field_name];
        $names = isset($files['name']) && is_array($files['name']) ? $files['name'] : [$files['name']];
        $types = isset($files['type']) && is_array($files['type']) ? $files['type'] : [$files['type']];
        $tmp_names = isset($files['tmp_name']) && is_array($files['tmp_name']) ? $files['tmp_name'] : [$files['tmp_name']];
        $errors = isset($files['error']) && is_array($files['error']) ? $files['error'] : [$files['error']];
        $sizes = isset($files['size']) && is_array($files['size']) ? $files['size'] : [$files['size']];

        $allowed = [
            'pdf' => 'application/pdf',
            'doc' => 'application/msword',
            'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'jpg' => 'image/jpeg',
            'jpeg' => 'image/jpeg',
            'png' => 'image/png',
            'webp' => 'image/webp',
            'txt' => 'text/plain',
        ];

        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';

        for ($i = 0; $i < count($names); $i++) {
            $name = (string) ($names[$i] ?? '');
            $tmp = (string) ($tmp_names[$i] ?? '');
            $error = (int) ($errors[$i] ?? UPLOAD_ERR_NO_FILE);
            $size = (int) ($sizes[$i] ?? 0);
            if ($error === UPLOAD_ERR_NO_FILE || $name === '' || $tmp === '') {
                continue;
            }
            if ($error !== UPLOAD_ERR_OK) {
                $results['errors'][] = $name . ': upload error.';
                continue;
            }
            if ($size > 10 * 1024 * 1024) {
                $results['errors'][] = $name . ': file is over 10MB.';
                continue;
            }
            $ext = strtolower((string) pathinfo($name, PATHINFO_EXTENSION));
            if (!isset($allowed[$ext])) {
                $results['errors'][] = $name . ': invalid file type.';
                continue;
            }
            $single = [
                'name' => $name,
                'type' => (string) ($types[$i] ?? ''),
                'tmp_name' => $tmp,
                'error' => $error,
                'size' => $size,
            ];
            $uploaded = wp_handle_upload($single, [
                'test_form' => false,
                'mimes' => $allowed,
            ]);
            if (!empty($uploaded['error'])) {
                $results['errors'][] = $name . ': ' . sanitize_text_field((string) $uploaded['error']);
                continue;
            }
            $attachment_id = wp_insert_attachment([
                'post_mime_type' => $uploaded['type'] ?? '',
                'post_title' => sanitize_file_name(pathinfo($name, PATHINFO_FILENAME)),
                'post_status' => 'inherit',
                'guid' => $uploaded['url'] ?? '',
            ], $uploaded['file'] ?? '');
            if (is_wp_error($attachment_id) || !$attachment_id) {
                $results['errors'][] = $name . ': failed to save.';
                continue;
            }
            $meta = wp_generate_attachment_metadata($attachment_id, $uploaded['file']);
            if (!is_wp_error($meta)) {
                wp_update_attachment_metadata($attachment_id, $meta);
            }
            $results['ids'][] = (int) $attachment_id;
        }
        return $results;
    }

    private function get_support_feedback($ticket_id, $user_id = 0) {
        global $wpdb;
        $table = $this->get_support_feedback_table();
        $ticket_id = (int) $ticket_id;
        if (!$ticket_id) {
            return null;
        }
        if ($user_id) {
            return $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM {$table} WHERE ticket_id = %d AND user_id = %d",
                $ticket_id,
                (int) $user_id
            ), ARRAY_A);
        }
        return $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE ticket_id = %d ORDER BY created_at DESC LIMIT 1",
            $ticket_id
        ), ARRAY_A);
    }

    private function build_support_transcript_text($ticket, $messages) {
        $lines = [];
        $lines[] = 'CoverMeNow ONE Support Transcript';
        $lines[] = 'Ticket Ref: ' . ($ticket['ticket_ref'] ?? '');
        $lines[] = 'Status: ' . ucfirst($this->normalize_support_status($ticket['status'] ?? 'open'));
        $lines[] = 'Created: ' . ($ticket['created_at'] ?? '');
        $lines[] = 'Updated: ' . ($ticket['updated_at'] ?? '');
        if (!empty($ticket['closed_at'])) {
            $lines[] = 'Closed: ' . $ticket['closed_at'];
        }
        $lines[] = '';
        foreach ($messages as $msg) {
            $sender = $msg['sender_name'] ?? 'Support';
            $date = $msg['created_at'] ?? '';
            $lines[] = '[' . $date . '] ' . $sender . ': ' . ($msg['message'] ?? '');
            if (!empty($msg['attachments']) && is_array($msg['attachments'])) {
                foreach ($msg['attachments'] as $attachment) {
                    $lines[] = '  - Attachment: ' . ($attachment['filename'] ?? 'file') . ' (' . ($attachment['url'] ?? '') . ')';
                }
            }
        }
        return implode("\n", $lines);
    }

    private function generate_support_ticket_ref() {
        global $wpdb;
        $table = $this->get_support_ticket_table();
        $feedback_table = $this->get_support_feedback_table();
        $max_id = (int) $wpdb->get_var("SELECT MAX(id) FROM {$table}");
        $next = $max_id + 1;
        do {
            $ref = 'CMN-SUP-' . str_pad((string) $next, 6, '0', STR_PAD_LEFT);
            $exists = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$table} WHERE ticket_ref = %s",
                $ref
            ));
            $next++;
        } while ($exists > 0);
        return $ref;
    }

    private function normalize_livechat_guest_type($guest_type) {
        $guest_type = sanitize_key((string) $guest_type);
        if (!in_array($guest_type, ['school', 'candidate', 'other'], true)) {
            return 'other';
        }
        return $guest_type;
    }

    private function normalize_livechat_thread_status($status) {
        $status = sanitize_key((string) $status);
        if (!in_array($status, ['open', 'closed', 'expired'], true)) {
            return 'open';
        }
        return $status;
    }

    private function build_livechat_thread_token() {
        try {
            return bin2hex(random_bytes(24));
        } catch (Throwable $e) {
            return wp_generate_password(48, false, false);
        }
    }

    private function hash_livechat_thread_token($thread_token) {
        $thread_token = trim((string) $thread_token);
        if ($thread_token === '') {
            return '';
        }
        return hash_hmac('sha256', $thread_token, (string) wp_salt('auth'));
    }

    private function get_livechat_thread_by_ticket_id($ticket_id) {
        $ticket_id = max(0, (int) $ticket_id);
        if ($ticket_id < 1) {
            return [];
        }
        global $wpdb;
        $table = $this->get_livechat_threads_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE ticket_id = %d
             LIMIT 1",
            $ticket_id
        ), ARRAY_A);
        if (!is_array($row) || !$row) {
            return [];
        }
        return [
            'id' => max(0, (int) ($row['id'] ?? 0)),
            'ticket_id' => max(0, (int) ($row['ticket_id'] ?? 0)),
            'source_key' => sanitize_key((string) ($row['source_key'] ?? 'website_live_chat')),
            'guest_name' => sanitize_text_field((string) ($row['guest_name'] ?? '')),
            'guest_email' => sanitize_email((string) ($row['guest_email'] ?? '')),
            'guest_type' => $this->normalize_livechat_guest_type((string) ($row['guest_type'] ?? 'other')),
            'linked_user_id' => max(0, (int) ($row['linked_user_id'] ?? 0)),
            'status' => $this->normalize_livechat_thread_status((string) ($row['status'] ?? 'open')),
            'last_message_id' => max(0, (int) ($row['last_message_id'] ?? 0)),
            'last_ip' => sanitize_text_field((string) ($row['last_ip'] ?? '')),
            'created_at' => $this->normalize_invoice_datetime((string) ($row['created_at'] ?? '')),
            'updated_at' => $this->normalize_invoice_datetime((string) ($row['updated_at'] ?? '')),
            'expires_at' => $this->normalize_invoice_datetime((string) ($row['expires_at'] ?? '')),
        ];
    }

    private function get_livechat_thread_by_token($thread_token) {
        $token_hash = $this->hash_livechat_thread_token($thread_token);
        if ($token_hash === '') {
            return [];
        }
        global $wpdb;
        $table = $this->get_livechat_threads_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE thread_token_hash = %s
             LIMIT 1",
            $token_hash
        ), ARRAY_A);
        if (!is_array($row) || !$row) {
            return [];
        }
        $thread = $this->get_livechat_thread_by_ticket_id((int) ($row['ticket_id'] ?? 0));
        if (!$thread) {
            return [];
        }

        $expires_at = $this->normalize_invoice_datetime((string) ($thread['expires_at'] ?? ''));
        if ($expires_at !== '' && strtotime($expires_at) !== false && strtotime($expires_at) < current_time('timestamp')) {
            $this->update_livechat_thread_status((int) ($thread['id'] ?? 0), 'expired');
            $thread['status'] = 'expired';
        }
        return $thread;
    }

    private function update_livechat_thread_status($thread_id, $status = 'open') {
        $thread_id = max(0, (int) $thread_id);
        if ($thread_id < 1) {
            return;
        }
        global $wpdb;
        $table = $this->get_livechat_threads_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return;
        }
        $wpdb->update(
            $table,
            [
                'status' => $this->normalize_livechat_thread_status($status),
                'updated_at' => current_time('mysql'),
            ],
            ['id' => $thread_id],
            ['%s', '%s'],
            ['%d']
        );
    }

    private function update_livechat_thread_activity($thread_id, $last_message_id = 0, $ip_address = '') {
        $thread_id = max(0, (int) $thread_id);
        if ($thread_id < 1) {
            return;
        }
        global $wpdb;
        $table = $this->get_livechat_threads_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return;
        }
        $update_data = [
            'updated_at' => current_time('mysql'),
        ];
        $update_format = ['%s'];
        $last_message_id = max(0, (int) $last_message_id);
        if ($last_message_id > 0) {
            $update_data['last_message_id'] = $last_message_id;
            $update_format[] = '%d';
        }
        $ip_address = substr(sanitize_text_field((string) $ip_address), 0, 64);
        if ($ip_address !== '') {
            $update_data['last_ip'] = $ip_address;
            $update_format[] = '%s';
        }
        $wpdb->update(
            $table,
            $update_data,
            ['id' => $thread_id],
            $update_format,
            ['%d']
        );
    }

    private function get_livechat_source_map_for_tickets($ticket_ids = []) {
        $ticket_ids = array_values(array_unique(array_filter(array_map('intval', (array) $ticket_ids))));
        if (!$ticket_ids) {
            return [];
        }
        global $wpdb;
        $table = $this->get_livechat_threads_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }

        $placeholders = implode(', ', array_fill(0, count($ticket_ids), '%d'));
        $rows = (array) $wpdb->get_results(
            $wpdb->prepare(
                "SELECT ticket_id, source_key, guest_name, guest_email, guest_type, linked_user_id, status
                 FROM {$table}
                 WHERE ticket_id IN ({$placeholders})",
                $ticket_ids
            ),
            ARRAY_A
        );
        if (!is_array($rows) || !$rows) {
            return [];
        }

        $map = [];
        foreach ($rows as $row) {
            $ticket_id = max(0, (int) ($row['ticket_id'] ?? 0));
            if ($ticket_id < 1) {
                continue;
            }
            $source_key = sanitize_key((string) ($row['source_key'] ?? 'website_live_chat'));
            $map[$ticket_id] = [
                'source_key' => $source_key,
                'source_label' => $source_key === 'website_live_chat' ? 'Website Live Chat' : ucfirst(str_replace('_', ' ', $source_key)),
                'guest_name' => sanitize_text_field((string) ($row['guest_name'] ?? '')),
                'guest_email' => sanitize_email((string) ($row['guest_email'] ?? '')),
                'guest_type' => $this->normalize_livechat_guest_type((string) ($row['guest_type'] ?? 'other')),
                'linked_user_id' => max(0, (int) ($row['linked_user_id'] ?? 0)),
                'status' => $this->normalize_livechat_thread_status((string) ($row['status'] ?? 'open')),
            ];
        }
        return $map;
    }

    private function get_livechat_rate_limit_key($scope, $identifier) {
        $scope = sanitize_key((string) $scope);
        $identifier = strtolower(trim((string) $identifier));
        if ($scope === '' || $identifier === '') {
            return '';
        }
        return 'cmn_livechat_rl_' . $scope . '_' . md5($identifier);
    }

    private function is_livechat_rate_limited($scope, $identifier, $max_events = 10, $window_seconds = 3600) {
        $max_events = max(1, (int) $max_events);
        $window_seconds = max(60, (int) $window_seconds);
        $key = $this->get_livechat_rate_limit_key($scope, $identifier);
        if ($key === '') {
            return false;
        }
        $now = time();
        $hits = get_transient($key);
        $hits = is_array($hits) ? $hits : [];
        $fresh = [];
        foreach ($hits as $hit_ts) {
            $hit_ts = (int) $hit_ts;
            if ($hit_ts > 0 && ($now - $hit_ts) < $window_seconds) {
                $fresh[] = $hit_ts;
            }
        }
        if (count($fresh) >= $max_events) {
            set_transient($key, $fresh, $window_seconds);
            return true;
        }
        $fresh[] = $now;
        set_transient($key, $fresh, $window_seconds);
        return false;
    }

    private function get_livechat_messages_since($ticket_id, $last_message_id = 0, $limit = 120) {
        $ticket_id = max(0, (int) $ticket_id);
        $last_message_id = max(0, (int) $last_message_id);
        $limit = max(1, min(250, (int) $limit));
        if ($ticket_id < 1) {
            return [];
        }
        global $wpdb;
        $table = $this->get_support_message_table();
        $rows = (array) $wpdb->get_results($wpdb->prepare(
            "SELECT id, sender_user_id, sender_type, message, created_at
             FROM {$table}
             WHERE ticket_id = %d
               AND id > %d
             ORDER BY id ASC
             LIMIT %d",
            $ticket_id,
            $last_message_id,
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function format_livechat_message_row($row, $thread = []) {
        $row = is_array($row) ? $row : [];
        $thread = is_array($thread) ? $thread : [];
        $sender_type_raw = sanitize_key((string) ($row['sender_type'] ?? 'user'));
        $sender_type = $sender_type_raw === 'admin' ? 'support' : 'visitor';
        $sender_name = $sender_type === 'support'
            ? 'Support'
            : sanitize_text_field((string) ($thread['guest_name'] ?? 'You'));
        if ($sender_name === '') {
            $sender_name = $sender_type === 'support' ? 'Support' : 'You';
        }
        $created_at = $this->normalize_invoice_datetime((string) ($row['created_at'] ?? ''));
        $created_label = $created_at !== '' && strtotime($created_at) !== false
            ? date_i18n('j M Y g:ia', strtotime($created_at))
            : '';
        return [
            'id' => max(0, (int) ($row['id'] ?? 0)),
            'sender_type' => $sender_type,
            'sender_name' => $sender_name,
            'message' => (string) ($row['message'] ?? ''),
            'created_at' => $created_at,
            'created_at_label' => $created_label,
        ];
    }

    private function build_livechat_messages_payload($thread, $last_message_id = 0, $limit = 120) {
        $thread = is_array($thread) ? $thread : [];
        $ticket_id = max(0, (int) ($thread['ticket_id'] ?? 0));
        if ($ticket_id < 1) {
            return [];
        }
        $rows = $this->get_livechat_messages_since($ticket_id, $last_message_id, $limit);
        $messages = [];
        foreach ($rows as $row) {
            $messages[] = $this->format_livechat_message_row($row, $thread);
        }
        return $messages;
    }

    private function get_livechat_feedback_record($ticket_id, $thread = []) {
        $ticket_id = max(0, (int) $ticket_id);
        if ($ticket_id < 1) {
            return null;
        }

        global $wpdb;
        $table = $this->get_support_feedback_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return null;
        }

        $thread = is_array($thread) ? $thread : [];
        $linked_user_id = max(0, (int) ($thread['linked_user_id'] ?? 0));
        $row = null;
        if ($linked_user_id > 0) {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT support_rating, response_time_rating, issue_resolved, overall_satisfaction, comments, created_at
                 FROM {$table}
                 WHERE ticket_id = %d
                   AND user_id = %d
                 LIMIT 1",
                $ticket_id,
                $linked_user_id
            ), ARRAY_A);
        } else {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT support_rating, response_time_rating, issue_resolved, overall_satisfaction, comments, created_at
                 FROM {$table}
                 WHERE ticket_id = %d
                   AND user_id = 0
                 LIMIT 1",
                $ticket_id
            ), ARRAY_A);
        }

        if (!is_array($row) || !$row) {
            return null;
        }

        return [
            'support_rating' => max(1, min(5, (int) ($row['support_rating'] ?? 0))),
            'response_time_rating' => max(1, min(5, (int) ($row['response_time_rating'] ?? 0))),
            'issue_resolved' => !empty($row['issue_resolved']) ? 1 : 0,
            'overall_satisfaction' => max(1, min(5, (int) ($row['overall_satisfaction'] ?? 0))),
            'comments' => sanitize_textarea_field((string) ($row['comments'] ?? '')),
            'created_at' => $this->normalize_invoice_datetime((string) ($row['created_at'] ?? '')),
        ];
    }

    /*
     * Acceptance checks:
     * - Live Chat button appears only on /contact (contact page gating).
     * - Guest can start/send/poll without being logged in.
     * - Website live chat creates support ticket and appears in staff Support list.
     * - Staff replies are returned through live chat polling.
     * - Rate limiting blocks spam for start/send.
     * - Invalid or expired token returns authorization failure.
     */
    public function handle_livechat_start() {
        if (!check_ajax_referer('cmn_livechat_public', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }

        $name = sanitize_text_field((string) ($_POST['name'] ?? ''));
        $email = sanitize_email((string) ($_POST['email'] ?? ''));
        $guest_type = $this->normalize_livechat_guest_type((string) ($_POST['user_type'] ?? 'other'));
        $message = sanitize_textarea_field((string) ($_POST['message'] ?? ''));
        $name = trim($name);
        $message = trim($message);
        if ($message === '') {
            wp_send_json_error(['message' => 'Please enter a message.'], 400);
        }
        if ((function_exists('mb_strlen') ? mb_strlen($message) : strlen($message)) > 1500) {
            wp_send_json_error(['message' => 'Message must be 1500 characters or fewer.'], 400);
        }

        $ip_address = $this->get_request_ip_address();
        if ($this->is_livechat_rate_limited('start_ip', $ip_address, 6, 3600)) {
            wp_send_json_error(['message' => 'Too many chat requests. Please try again shortly.'], 429);
        }

        $linked_user_id = 0;
        $role_type = 'guest';
        $linked_user = null;
        if (is_user_logged_in()) {
            $current_user_id = (int) get_current_user_id();
            if ($current_user_id > 0 && ($this->is_candidate_user($current_user_id) || $this->is_school_user($current_user_id) || $this->is_staff_user($current_user_id))) {
                $linked_user_id = $current_user_id;
                $role_type = $this->get_support_user_role_type($current_user_id);
                $linked_user = get_user_by('id', $current_user_id);
                if ($this->is_candidate_user($current_user_id)) {
                    $guest_type = 'candidate';
                } elseif ($this->is_school_user($current_user_id)) {
                    $guest_type = 'school';
                } else {
                    $guest_type = 'other';
                }
            }
        }

        if ($linked_user instanceof WP_User) {
            $linked_name = trim((string) $linked_user->display_name);
            if ($linked_name === '') {
                $linked_name = trim((string) get_user_meta($linked_user_id, 'first_name', true) . ' ' . (string) get_user_meta($linked_user_id, 'last_name', true));
            }
            if ($linked_name === '') {
                $linked_name = (string) $linked_user->user_login;
            }
            $linked_email = sanitize_email((string) $linked_user->user_email);
            if ($linked_name !== '') {
                $name = sanitize_text_field($linked_name);
            }
            if ($linked_email !== '') {
                $email = $linked_email;
            }
        }
        if ($name === '' || strlen($name) < 2 || strlen($name) > 120) {
            wp_send_json_error(['message' => 'Please enter your full name.'], 400);
        }
        if ($email === '' || !is_email($email)) {
            wp_send_json_error(['message' => 'Please enter a valid email address.'], 400);
        }
        if ($this->is_livechat_rate_limited('start_email', strtolower($email), 4, 3600)) {
            wp_send_json_error(['message' => 'Too many chat requests for this email. Please try again shortly.'], 429);
        }

        global $wpdb;
        $ticket_table = $this->get_support_ticket_table();
        $message_table = $this->get_support_message_table();
        $livechat_table = $this->get_livechat_threads_table();
        self::migrate_schema_v71_livechat_support_threads();

        $ticket_ref = $this->generate_support_ticket_ref();
        $guest_type_label = $guest_type === 'school' ? 'School' : ($guest_type === 'candidate' ? 'Candidate' : 'Other');
        $subject = 'Website Live Chat - ' . $name . ' (' . $guest_type_label . ')';
        $now = current_time('mysql');
        $ticket_inserted = $wpdb->insert($ticket_table, [
            'ticket_ref' => $ticket_ref,
            'created_by_user_id' => $linked_user_id,
            'user_role_type' => $role_type,
            'subject' => $subject,
            'category' => 'General Enquiry',
            'queue_key' => 'general',
            'assigned_to_user_id' => null,
            'priority' => 'normal',
            'status' => 'open',
            'is_new_for_admin' => 1,
            'created_at' => $now,
            'updated_at' => $now,
            'closed_at' => null,
        ], ['%s', '%d', '%s', '%s', '%s', '%s', '%d', '%s', '%s', '%d', '%s', '%s', '%s']);
        if (!$ticket_inserted) {
            wp_send_json_error(['message' => 'Unable to start chat.'], 500);
        }
        $ticket_id = (int) $wpdb->insert_id;

        $message_inserted = $wpdb->insert($message_table, [
            'ticket_id' => $ticket_id,
            'sender_user_id' => $linked_user_id > 0 ? $linked_user_id : null,
            'sender_type' => 'user',
            'message' => $message,
            'attachment_ids' => null,
            'created_at' => $now,
        ], ['%d', '%d', '%s', '%s', '%s', '%s']);
        if (!$message_inserted) {
            wp_send_json_error(['message' => 'Unable to start chat.'], 500);
        }
        $message_id = (int) $wpdb->insert_id;

        $thread_token = $this->build_livechat_thread_token();
        $thread_hash = $this->hash_livechat_thread_token($thread_token);
        $expires_at = date('Y-m-d H:i:s', strtotime('+30 days', current_time('timestamp')));
        $thread_inserted = $wpdb->insert($livechat_table, [
            'ticket_id' => $ticket_id,
            'thread_token_hash' => $thread_hash,
            'source_key' => 'website_live_chat',
            'guest_name' => $name,
            'guest_email' => $email,
            'guest_type' => $guest_type,
            'linked_user_id' => $linked_user_id > 0 ? $linked_user_id : null,
            'status' => 'open',
            'last_message_id' => $message_id,
            'last_ip' => $ip_address !== '' ? $ip_address : null,
            'expires_at' => $expires_at,
            'created_at' => $now,
            'updated_at' => $now,
        ], ['%d', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%d', '%s', '%s', '%s', '%s']);
        if (!$thread_inserted) {
            wp_send_json_error(['message' => 'Unable to start chat.'], 500);
        }

        $this->notify_admins_support($ticket_id, $ticket_ref, $subject, $message);

        $contact_url = home_url('/contact');
        $confirmation_subject = 'We\'ve received your message - ' . $ticket_ref;
        $confirmation_body = implode("\n", [
            'Hi ' . $name . ',',
            '',
            'We have received your live chat message.',
            'Reference: ' . $ticket_ref,
            '',
            'You can return to the Contact page to view replies in the live chat widget:',
            $contact_url,
        ]);
        $this->send_support_email($email, $confirmation_subject, $confirmation_body, [
            'type' => 'livechat_started',
            'template_key' => 'website_livechat_received',
            'recipient_role' => 'system',
            'module' => 'support',
            'related_entity_type' => 'support_ticket',
            'related_entity_id' => $ticket_id,
            'metadata' => [
                'source' => 'website_live_chat',
                'guest_type' => $guest_type,
            ],
        ]);

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'support',
                'entity_type' => 'ticket',
                'entity_id' => $ticket_id,
                'event_type' => 'livechat_started',
                'actor_user_id' => $linked_user_id > 0 ? $linked_user_id : null,
                'metadata' => [
                    'ticket_id' => $ticket_id,
                    'guest_email' => $email,
                    'source' => 'website_live_chat',
                ],
            ]);
        }

        wp_send_json_success([
            'thread_token' => $thread_token,
            'ticket_id' => $ticket_id,
            'ticket_ref' => $ticket_ref,
            'status' => 'open',
            'feedback_submitted' => 0,
            'feedback' => null,
            'messages' => [
                $this->format_livechat_message_row([
                    'id' => $message_id,
                    'sender_type' => 'user',
                    'message' => $message,
                    'created_at' => $now,
                ], [
                    'guest_name' => $name,
                ]),
            ],
        ]);
    }

    public function handle_livechat_send() {
        if (!check_ajax_referer('cmn_livechat_public', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }

        $thread_token = sanitize_text_field((string) ($_POST['thread_token'] ?? ''));
        $message = sanitize_textarea_field((string) ($_POST['message'] ?? ''));
        $message = trim($message);
        if ($thread_token === '' || $message === '') {
            wp_send_json_error(['message' => 'Message is required.'], 400);
        }
        if ((function_exists('mb_strlen') ? mb_strlen($message) : strlen($message)) > 1500) {
            wp_send_json_error(['message' => 'Message must be 1500 characters or fewer.'], 400);
        }

        $ip_address = $this->get_request_ip_address();
        if ($this->is_livechat_rate_limited('send_ip', $ip_address, 60, 3600)) {
            wp_send_json_error(['message' => 'Rate limit reached. Please wait and try again.'], 429);
        }
        if ($this->is_livechat_rate_limited('send_token', $thread_token, 40, 3600)) {
            wp_send_json_error(['message' => 'Rate limit reached. Please wait and try again.'], 429);
        }

        $thread = $this->get_livechat_thread_by_token($thread_token);
        if (!$thread) {
            wp_send_json_error(['message' => 'Not authorized.'], 403);
        }
        if ($this->normalize_livechat_thread_status((string) ($thread['status'] ?? 'open')) !== 'open') {
            wp_send_json_error(['message' => 'This chat is closed.'], 403);
        }

        $ticket_id = max(0, (int) ($thread['ticket_id'] ?? 0));
        $ticket = $this->get_support_ticket($ticket_id);
        if (!$ticket) {
            wp_send_json_error(['message' => 'Chat not found.'], 404);
        }
        if ($this->normalize_support_status((string) ($ticket['status'] ?? 'open')) === 'closed') {
            $this->update_livechat_thread_status((int) ($thread['id'] ?? 0), 'closed');
            wp_send_json_error(['message' => 'This chat is closed.'], 403);
        }

        global $wpdb;
        $message_table = $this->get_support_message_table();
        $ticket_table = $this->get_support_ticket_table();
        $now = current_time('mysql');
        $sender_user_id = max(0, (int) ($thread['linked_user_id'] ?? 0));
        $inserted = $wpdb->insert($message_table, [
            'ticket_id' => $ticket_id,
            'sender_user_id' => $sender_user_id > 0 ? $sender_user_id : null,
            'sender_type' => 'user',
            'message' => $message,
            'attachment_ids' => null,
            'created_at' => $now,
        ], ['%d', '%d', '%s', '%s', '%s', '%s']);
        if (!$inserted) {
            wp_send_json_error(['message' => 'Unable to send message.'], 500);
        }
        $message_id = (int) $wpdb->insert_id;
        $wpdb->update($ticket_table, [
            'status' => 'open',
            'is_new_for_admin' => 1,
            'updated_at' => $now,
            'closed_at' => null,
        ], ['id' => $ticket_id], ['%s', '%d', '%s', '%s'], ['%d']);
        $this->update_livechat_thread_activity((int) ($thread['id'] ?? 0), $message_id, $ip_address);

        $ticket_ref = sanitize_text_field((string) ($ticket['ticket_ref'] ?? ''));
        $this->notify_admins_support_reply($ticket_id, $ticket_ref, $message, $sender_user_id);

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'support',
                'entity_type' => 'ticket',
                'entity_id' => $ticket_id,
                'event_type' => 'livechat_message_sent',
                'actor_user_id' => $sender_user_id > 0 ? $sender_user_id : null,
                'metadata' => [
                    'ticket_id' => $ticket_id,
                    'source' => 'website_live_chat',
                ],
            ]);
        }

        $last_message_id = max(0, (int) ($_POST['last_message_id'] ?? 0));
        $messages = $this->build_livechat_messages_payload($thread, $last_message_id, 120);
        wp_send_json_success([
            'ticket_id' => $ticket_id,
            'ticket_ref' => $ticket_ref,
            'status' => 'open',
            'messages' => $messages,
            'last_message_id' => $messages ? max(array_map(function ($msg) { return (int) ($msg['id'] ?? 0); }, $messages)) : $last_message_id,
        ]);
    }

    public function handle_livechat_poll() {
        if (!check_ajax_referer('cmn_livechat_public', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }

        $thread_token = sanitize_text_field((string) ($_POST['thread_token'] ?? ''));
        if ($thread_token === '') {
            wp_send_json_error(['message' => 'Not authorized.'], 403);
        }

        $thread = $this->get_livechat_thread_by_token($thread_token);
        if (!$thread) {
            wp_send_json_error(['message' => 'Not authorized.'], 403);
        }

        $ticket_id = max(0, (int) ($thread['ticket_id'] ?? 0));
        $ticket = $this->get_support_ticket($ticket_id);
        if (!$ticket) {
            wp_send_json_error(['message' => 'Chat not found.'], 404);
        }

        $ticket_status = $this->normalize_support_status((string) ($ticket['status'] ?? 'open'));
        if ($ticket_status === 'closed' && $this->normalize_livechat_thread_status((string) ($thread['status'] ?? 'open')) !== 'expired') {
            $this->update_livechat_thread_status((int) ($thread['id'] ?? 0), 'closed');
            $thread['status'] = 'closed';
        }

        $last_message_id = max(0, (int) ($_POST['last_message_id'] ?? 0));
        $messages = $this->build_livechat_messages_payload($thread, $last_message_id, 120);
        $feedback = $this->get_livechat_feedback_record($ticket_id, $thread);
        $resolved_last = $last_message_id;
        if ($messages) {
            $resolved_last = max(array_map(function ($msg) {
                return max(0, (int) ($msg['id'] ?? 0));
            }, $messages));
        }
        $this->update_livechat_thread_activity((int) ($thread['id'] ?? 0), 0, $this->get_request_ip_address());

        wp_send_json_success([
            'ticket_id' => $ticket_id,
            'ticket_ref' => sanitize_text_field((string) ($ticket['ticket_ref'] ?? '')),
            'ticket_status' => $ticket_status,
            'thread_status' => $this->normalize_livechat_thread_status((string) ($thread['status'] ?? 'open')),
            'messages' => $messages,
            'last_message_id' => $resolved_last,
            'feedback_submitted' => $feedback ? 1 : 0,
            'feedback' => $feedback ?: null,
            'guest_name' => sanitize_text_field((string) ($thread['guest_name'] ?? '')),
            'guest_email' => sanitize_email((string) ($thread['guest_email'] ?? '')),
            'source' => sanitize_key((string) ($thread['source_key'] ?? 'website_live_chat')),
        ]);
    }

    public function handle_livechat_feedback_submit() {
        if (!check_ajax_referer('cmn_livechat_public', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }

        $thread_token = sanitize_text_field((string) ($_POST['thread_token'] ?? ''));
        if ($thread_token === '') {
            wp_send_json_error(['message' => 'Not authorized.'], 403);
        }

        $thread = $this->get_livechat_thread_by_token($thread_token);
        if (!$thread) {
            wp_send_json_error(['message' => 'Not authorized.'], 403);
        }

        $ticket_id = max(0, (int) ($thread['ticket_id'] ?? 0));
        $ticket = $this->get_support_ticket($ticket_id);
        if (!$ticket) {
            wp_send_json_error(['message' => 'Chat not found.'], 404);
        }
        if ($this->normalize_support_status((string) ($ticket['status'] ?? 'open')) !== 'closed') {
            wp_send_json_error(['message' => 'Feedback is available after support closes the chat.'], 400);
        }

        $support_rating = max(1, min(5, (int) ($_POST['support_rating'] ?? 0)));
        $response_time_rating = max(1, min(5, (int) ($_POST['response_time_rating'] ?? 0)));
        $overall_satisfaction = max(1, min(5, (int) ($_POST['overall_satisfaction'] ?? 0)));
        $issue_resolved_raw = isset($_POST['issue_resolved']) ? (string) $_POST['issue_resolved'] : '';
        $issue_resolved = ($issue_resolved_raw === '1' || strtolower(trim($issue_resolved_raw)) === 'yes') ? 1 : 0;
        $comments = trim(sanitize_textarea_field((string) ($_POST['comments'] ?? '')));
        if ($support_rating < 1 || $response_time_rating < 1 || $overall_satisfaction < 1 || ($issue_resolved_raw !== '0' && $issue_resolved_raw !== '1' && strtolower(trim($issue_resolved_raw)) !== 'yes' && strtolower(trim($issue_resolved_raw)) !== 'no')) {
            wp_send_json_error(['message' => 'Please complete all required feedback fields.'], 400);
        }
        if ((function_exists('mb_strlen') ? mb_strlen($comments) : strlen($comments)) > 1000) {
            wp_send_json_error(['message' => 'Comments must be 1000 characters or fewer.'], 400);
        }

        global $wpdb;
        $table = $this->get_support_feedback_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            wp_send_json_error(['message' => 'Feedback service is unavailable.'], 500);
        }

        $feedback_user_id = max(0, (int) ($thread['linked_user_id'] ?? 0));
        $now = current_time('mysql');
        $saved = $wpdb->replace($table, [
            'ticket_id' => $ticket_id,
            'user_id' => $feedback_user_id,
            'support_rating' => $support_rating,
            'response_time_rating' => $response_time_rating,
            'issue_resolved' => $issue_resolved,
            'overall_satisfaction' => $overall_satisfaction,
            'comments' => $comments,
            'created_at' => $now,
        ], ['%d', '%d', '%d', '%d', '%d', '%d', '%s', '%s']);
        if (!$saved) {
            wp_send_json_error(['message' => 'Unable to submit feedback right now.'], 500);
        }

        $ticket_ref = sanitize_text_field((string) ($ticket['ticket_ref'] ?? ''));
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            $admin_id = (int) $admin_id;
            if ($admin_id < 1) {
                continue;
            }
            $admin_link = $this->get_support_link_for_user($admin_id, $ticket_id, $ticket_ref);
            $this->add_notification(
                $admin_id,
                'support_feedback',
                'Support feedback',
                ($ticket_ref !== '' ? $ticket_ref : ('Ticket #' . $ticket_id)) . ' live chat feedback submitted.',
                $admin_link
            );
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'support',
                'entity_type' => 'ticket',
                'entity_id' => $ticket_id,
                'event_type' => 'livechat_feedback_submitted',
                'actor_user_id' => $feedback_user_id > 0 ? $feedback_user_id : null,
                'metadata' => [
                    'ticket_id' => $ticket_id,
                    'source' => 'website_live_chat',
                ],
            ]);
        }

        wp_send_json_success([
            'message' => 'Feedback submitted. Thank you.',
            'feedback_submitted' => 1,
            'feedback' => $this->get_livechat_feedback_record($ticket_id, $thread),
        ]);
    }

    private function get_support_user_role_type($user_id) {
        if ($this->is_candidate_user($user_id)) {
            return 'candidate';
        }
        if ($this->is_school_user($user_id)) {
            return 'school';
        }
        return 'staff';
    }

    private function can_access_support_ticket($ticket, $user_id = 0) {
        if (!$ticket) {
            return false;
        }
        $user_id = $user_id ?: get_current_user_id();
        if ($this->is_staff_user($user_id)) {
            return true;
        }
        if ((int) $this->get_support_owner_user_id($ticket) !== (int) $user_id) {
            return false;
        }
        $expected_role = $this->get_support_user_role_type($user_id);
        $ticket_role = sanitize_key((string) ($ticket['user_role_type'] ?? ''));
        if ($ticket_role === '') {
            return true;
        }
        return $ticket_role === $expected_role;
    }

    private function get_support_ticket($ticket_id) {
        global $wpdb;
        $table = $this->get_support_ticket_table();
        return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $ticket_id), ARRAY_A);
    }

    private function get_support_ticket_by_ref($ticket_ref) {
        $ticket_ref = sanitize_text_field((string) $ticket_ref);
        if ($ticket_ref === '') {
            return null;
        }
        global $wpdb;
        $table = $this->get_support_ticket_table();
        return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE ticket_ref = %s", $ticket_ref), ARRAY_A);
    }

    private function resolve_support_requested_ticket($ticket_id = 0, $ticket_ref = '') {
        $ticket = null;
        $ticket_id = (int) $ticket_id;
        $ticket_ref = sanitize_text_field((string) $ticket_ref);
        if ($ticket_id > 0) {
            $ticket = $this->get_support_ticket($ticket_id);
        } elseif ($ticket_ref !== '') {
            $ticket = $this->get_support_ticket_by_ref($ticket_ref);
        }
        return $ticket ?: null;
    }

    private function map_support_filter_for_status($normalized_status) {
        $normalized_status = $this->normalize_support_status($normalized_status);
        if ($normalized_status === 'new') {
            return 'new';
        }
        if ($normalized_status === 'closed') {
            return 'closed';
        }
        return 'open';
    }

    private function support_ticket_matches_filter($ticket, $filter) {
        $filter = sanitize_key((string) $filter);
        $normalized = $this->normalize_support_ticket_for_view($ticket, $this->is_staff_user());
        $status = $normalized['status'] ?? 'open';
        if ($filter === 'all') {
            return true;
        }
        if ($filter === 'active' || $filter === '' || $filter === 'new_open') {
            return in_array($status, ['new', 'open'], true);
        }
        if ($filter === 'new') {
            return $status === 'new';
        }
        if ($filter === 'open') {
            return $status === 'open';
        }
        if ($filter === 'closed') {
            return $status === 'closed';
        }
        if ($filter === 'needs_feedback') {
            return $this->support_ticket_requires_feedback($normalized);
        }
        return true;
    }

    private function normalize_support_feedback_request_status($status) {
        $status = sanitize_key((string) $status);
        if (!in_array($status, ['none', 'requested', 'expired', 'completed', 'dismissed'], true)) {
            return 'none';
        }
        return $status;
    }

    private function get_support_feedback_request_expiry_ts($ticket) {
        if (!is_array($ticket)) {
            return 0;
        }
        $raw = trim((string) ($ticket['feedback_request_expires_at'] ?? ''));
        if ($raw === '') {
            return 0;
        }
        $timestamp = strtotime($raw);
        if ($timestamp === false) {
            return 0;
        }
        return (int) $timestamp;
    }

    private function is_support_feedback_request_active($ticket) {
        if (!is_array($ticket)) {
            return false;
        }
        $status = $this->normalize_support_feedback_request_status((string) ($ticket['feedback_request_status'] ?? 'none'));
        if ($status !== 'requested') {
            return false;
        }
        $expires_ts = $this->get_support_feedback_request_expiry_ts($ticket);
        if ($expires_ts < 1) {
            return true;
        }
        return $expires_ts > (int) current_time('timestamp');
    }

    private function support_ticket_can_request_feedback($ticket) {
        if (!is_array($ticket)) {
            return false;
        }
        $status = $this->normalize_support_status((string) ($ticket['status'] ?? 'open'));
        if ($status !== 'closed') {
            return false;
        }
        $feedback_count = isset($ticket['feedback_count']) ? (int) $ticket['feedback_count'] : 0;
        if ($feedback_count > 0) {
            return false;
        }
        if (!$this->support_ticket_has_column('feedback_request_status')) {
            return true;
        }
        return !$this->is_support_feedback_request_active($ticket);
    }

    private function maybe_expire_support_feedback_requests($batch_limit = 250) {
        if (
            !$this->support_ticket_has_column('feedback_request_status')
            || !$this->support_ticket_has_column('feedback_requested_at')
            || !$this->support_ticket_has_column('feedback_request_expires_at')
        ) {
            return 0;
        }
        global $wpdb;
        $ticket_table = $this->get_support_ticket_table();
        $feedback_table = $this->get_support_feedback_table();
        $batch_limit = max(1, min(1000, (int) $batch_limit));
        $now_mysql = current_time('mysql');
        $updated = (int) $wpdb->query($wpdb->prepare(
            "UPDATE {$ticket_table} t
             LEFT JOIN {$feedback_table} sf ON sf.ticket_id = t.id
             SET t.feedback_request_status = 'expired',
                 t.feedback_requested_at = NULL,
                 t.feedback_request_expires_at = NULL,
                 t.updated_at = %s
             WHERE t.feedback_request_status = 'requested'
               AND t.feedback_request_expires_at IS NOT NULL
               AND t.feedback_request_expires_at <= %s
               AND sf.id IS NULL
             LIMIT %d",
            $now_mysql,
            $now_mysql,
            $batch_limit
        ));
        if ($updated > 0) {
            $this->add_audit_log(
                'support_feedback_request_expired_cleanup',
                'support_ticket',
                'bulk',
                ['expired_count' => $updated],
                0
            );
        }
        return max(0, $updated);
    }

    private function support_ticket_requires_feedback($ticket) {
        if (!is_array($ticket)) {
            return false;
        }
        $status = $this->normalize_support_status((string) ($ticket['status'] ?? 'open'));
        if ($status !== 'closed') {
            return false;
        }
        $feedback_count = isset($ticket['feedback_count']) ? (int) $ticket['feedback_count'] : 0;
        if ($feedback_count > 0) {
            return false;
        }
        $channel_key = sanitize_key((string) ($ticket['channel_key'] ?? ''));
        $linked_user_id = max(0, (int) ($ticket['linked_user_id'] ?? 0));
        if ($channel_key === 'website_live_chat' && $linked_user_id < 1) {
            return false;
        }
        if (!$this->support_ticket_has_column('feedback_request_status')) {
            return true;
        }
        return $this->is_support_feedback_request_active($ticket);
    }

    private function insert_support_system_message_once($ticket_id, $message, $sender_user_id = 0, $sender_type = 'admin') {
        global $wpdb;
        $ticket_id = (int) $ticket_id;
        $message = trim((string) $message);
        if (!$ticket_id || $message === '') {
            return;
        }
        $table = $this->get_support_message_table();
        $last = $wpdb->get_row($wpdb->prepare(
            "SELECT sender_type, message, created_at FROM {$table} WHERE ticket_id = %d ORDER BY id DESC LIMIT 1",
            $ticket_id
        ), ARRAY_A);
        if ($last) {
            $same_sender = sanitize_key((string) ($last['sender_type'] ?? '')) === sanitize_key($sender_type);
            $same_message = trim((string) ($last['message'] ?? '')) === $message;
            $within_window = false;
            if (!empty($last['created_at'])) {
                $within_window = (time() - strtotime((string) $last['created_at'])) <= 30;
            }
            if ($same_sender && $same_message && $within_window) {
                return;
            }
        }
        $wpdb->insert($table, [
            'ticket_id' => $ticket_id,
            'sender_user_id' => (int) $sender_user_id,
            'sender_type' => sanitize_key($sender_type),
            'message' => $message,
            'attachment_ids' => null,
            'created_at' => current_time('mysql'),
        ], ['%d', '%d', '%s', '%s', '%s', '%s']);
    }

    private function get_support_ticket_messages($ticket_id) {
        global $wpdb;
        $table = $this->get_support_message_table();
        return $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE ticket_id = %d ORDER BY created_at ASC",
            $ticket_id
        ), ARRAY_A);
    }

    private function get_admin_users_for_support() {
        $admins = get_users([
            'role__in' => ['administrator', 'cmn_admin'],
            'fields' => ['ID'],
        ]);
        return array_map(function ($user) {
            return (int) $user->ID;
        }, $admins);
    }

    private function notify_admins_support($ticket_id, $ticket_ref, $subject, $latest_message = '') {
        $ticket_id = (int) $ticket_id;
        $ticket_ref = sanitize_text_field((string) $ticket_ref);
        $subject = sanitize_text_field((string) $subject);
        $latest_message = (string) $latest_message;
        $message_preview = $this->build_payroll_ticket_message_preview($latest_message, 220);
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            $portal_link = $this->get_support_link_for_user($admin_id, $ticket_id, $ticket_ref);
            $this->add_notification($admin_id, 'support_new_ticket', 'New support ticket', "{$ticket_ref} - {$subject}", $portal_link);
            $email_subject = 'New support ticket: ' . $ticket_ref;
            $email_body = implode("\n", [
                'A new support ticket has been created.',
                '',
                'Reference: ' . $ticket_ref,
                'Subject: ' . $subject,
                'Message preview: ' . $message_preview,
                'Open in portal: ' . $portal_link,
            ]);
            $this->send_support_email_to_user((int) $admin_id, $email_subject, $email_body, 'support_new_ticket_admin', [
                'ticket_id' => $ticket_id,
            ]);
        }
    }

    private function notify_admins_support_reply($ticket_id, $ticket_ref, $latest_message = '', $actor_user_id = 0) {
        $ticket_id = (int) $ticket_id;
        $ticket_ref = sanitize_text_field((string) $ticket_ref);
        $actor_user_id = (int) $actor_user_id;
        $latest_message = (string) $latest_message;
        $message_preview = $this->build_payroll_ticket_message_preview($latest_message, 220);
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            $admin_id = (int) $admin_id;
            if ($admin_id < 1) {
                continue;
            }
            if ($actor_user_id > 0 && $admin_id === $actor_user_id) {
                continue;
            }
            $portal_link = $this->get_support_link_for_user($admin_id, $ticket_id, $ticket_ref);
            $this->add_notification($admin_id, 'support_reply', 'Support ticket reply', "{$ticket_ref} updated.", $portal_link);
            $email_subject = 'Support ticket updated: ' . $ticket_ref;
            $email_body = implode("\n", [
                'A support ticket has a new update.',
                '',
                'Reference: ' . $ticket_ref,
                'Message preview: ' . $message_preview,
                'Open in portal: ' . $portal_link,
            ]);
            $this->send_support_email_to_user($admin_id, $email_subject, $email_body, 'support_ticket_reply_admin', [
                'ticket_id' => $ticket_id,
            ]);
        }
    }

    private function get_support_link_for_user($user_id, $ticket_id, $ticket_ref = '') {
        $ticket_value = (int) $ticket_id;
        if ($ticket_value < 1 && $ticket_ref !== '') {
            $ticket = $this->get_support_ticket_by_ref($ticket_ref);
            if ($ticket) {
                $ticket_value = (int) $ticket['id'];
            }
        }
        if ($ticket_value < 1) {
            return $this->get_portal_base_url();
        }
        if ($this->is_candidate_user($user_id)) {
            return add_query_arg([
                'candidate' => 'support',
                'ticket_id' => $ticket_value,
            ], $this->get_portal_base_url());
        }
        if ($this->is_school_user($user_id)) {
            return add_query_arg([
                'school' => 'support',
                'ticket_id' => $ticket_value,
            ], $this->get_portal_base_url());
        }
        return add_query_arg([
            'view' => 'support',
            'hub' => '1',
            'ticket_id' => $ticket_value,
        ], $this->get_portal_base_url());
    }

    private function get_support_feedback_link_for_user($user_id, $ticket_id, $ticket_ref = '') {
        $link = $this->get_support_link_for_user($user_id, $ticket_id, $ticket_ref);
        return add_query_arg([
            'support_filter' => 'needs_feedback',
            'support_feedback' => '1',
        ], $link);
    }

    private function get_support_primary_admin_user_id() {
        $admin_ids = $this->get_admin_users_for_support();
        foreach ($admin_ids as $admin_id) {
            $admin_id = (int) $admin_id;
            if ($admin_id > 0 && $this->is_admin_user($admin_id)) {
                return $admin_id;
            }
        }

        $fallback = get_users([
            'role__in' => ['administrator', 'cmn_admin'],
            'number' => 1,
            'fields' => ['ID'],
            'orderby' => 'ID',
            'order' => 'ASC',
        ]);
        if (is_array($fallback) && !empty($fallback[0]) && !empty($fallback[0]->ID)) {
            return (int) $fallback[0]->ID;
        }
        return 0;
    }

    private function get_configured_payroll_duty_user_id() {
        $config = (array) $this->finance_get_config();
        $duty_user_id = max(0, (int) ($config['payroll_duty_user_id'] ?? 0));
        if ($duty_user_id > 0 && $this->is_staff_user($duty_user_id)) {
            return $duty_user_id;
        }
        return 0;
    }

    private function resolve_payroll_ticket_assignee_user_id() {
        $duty_user_id = $this->get_configured_payroll_duty_user_id();
        if ($duty_user_id > 0) {
            return $duty_user_id;
        }
        return $this->get_support_primary_admin_user_id();
    }

    private function resolve_payroll_ticket_notification_email() {
        $config = (array) $this->finance_get_config();
        $configured_keys = [
            'payroll_notification_email',
            'payroll_support_email',
            'payroll_email',
        ];
        foreach ($configured_keys as $key) {
            $candidate = sanitize_email((string) ($config[$key] ?? ''));
            if ($candidate !== '' && is_email($candidate)) {
                return $candidate;
            }
        }

        foreach (['CMN_PAYROLL_SUPPORT_EMAIL', 'CMN_PAYROLL_NOTIFICATION_EMAIL'] as $constant_name) {
            if (defined($constant_name)) {
                $candidate = sanitize_email((string) constant($constant_name));
                if ($candidate !== '' && is_email($candidate)) {
                    return $candidate;
                }
            }
        }

        $fallback = sanitize_email((string) get_option('admin_email'));
        if ($fallback !== '' && is_email($fallback)) {
            return $fallback;
        }
        return '';
    }

    private function build_payroll_ticket_message_preview($message, $max_chars = 200) {
        $max_chars = max(40, (int) $max_chars);
        $message = trim(preg_replace('/\s+/', ' ', (string) wp_strip_all_tags((string) $message)));
        if ($message === '') {
            return 'No message provided.';
        }

        $message = preg_replace('/\b\d{2}-\d{2}-\d{2}\b/', '[redacted]', $message);
        $message = preg_replace('/\b[A-Z]{2}\d{2}[A-Z0-9]{10,30}\b/i', '[redacted]', $message);
        $message = preg_replace('/\b\d{6}\b/', '[redacted]', $message);
        $message = preg_replace('/\b\d{8}\b/', '[redacted]', $message);
        if (!is_string($message)) {
            $message = '';
        }
        $message = trim($message);
        if ($message === '') {
            return 'Message redacted.';
        }

        if (function_exists('mb_strlen') && function_exists('mb_substr')) {
            if (mb_strlen($message) > $max_chars) {
                return (string) mb_substr($message, 0, $max_chars) . '...';
            }
            return $message;
        }

        if (strlen($message) > $max_chars) {
            return (string) substr($message, 0, $max_chars) . '...';
        }
        return $message;
    }

    private function count_open_payroll_support_tickets() {
        global $wpdb;
        $table = $this->get_support_ticket_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return 0;
        }

        $has_queue_key = $this->support_ticket_has_column('queue_key');
        $where_sql = "WHERE (LOWER(COALESCE(category, '')) = 'payroll')";
        if ($has_queue_key) {
            $where_sql = "WHERE (LOWER(COALESCE(category, '')) = 'payroll' OR LOWER(COALESCE(queue_key, '')) = 'payroll')";
        }

        $rows = $wpdb->get_results(
            "SELECT status
             FROM {$table}
             {$where_sql}",
            ARRAY_A
        );
        if (!is_array($rows)) {
            return 0;
        }

        $count = 0;
        foreach ($rows as $row) {
            $status = $this->normalize_support_status((string) ($row['status'] ?? 'open'));
            if ($status !== 'closed') {
                $count++;
            }
        }
        return max(0, $count);
    }

    /*
     * Prompt 34 acceptance tests:
     * 1) Payroll-category tickets route to payroll queue key and default assignee.
     * 2) Internal payroll notification email is sent with safe preview content only.
     * 3) Audit event payroll_ticket_routed records assigned_to and notification status.
     */
    private function route_payroll_support_ticket($ticket_id, $context = []) {
        $ticket_id = (int) $ticket_id;
        $context = is_array($context) ? $context : [];
        if ($ticket_id < 1) {
            return ['routed' => false, 'assigned_to' => 0, 'notification_sent' => false];
        }

        self::migrate_schema_v61_support_payroll_routing();
        $ticket = $this->get_support_ticket($ticket_id);
        if (!is_array($ticket) || !$ticket) {
            return ['routed' => false, 'assigned_to' => 0, 'notification_sent' => false];
        }

        $category = strtolower(trim((string) ($ticket['category'] ?? '')));
        if ($category !== 'payroll') {
            return ['routed' => false, 'assigned_to' => 0, 'notification_sent' => false];
        }

        $existing_assignee_user_id = max(0, (int) ($ticket['assigned_to_user_id'] ?? 0));
        $current_status_for_audit = $this->normalize_payroll_support_ticket_status((string) ($ticket['status'] ?? 'open'));
        $actor_user_id = max(0, (int) ($context['actor_user_id'] ?? 0));
        $assignee_user_id = $this->resolve_payroll_ticket_assignee_user_id();
        $priority_value = 'normal';

        global $wpdb;
        $table = $this->get_support_ticket_table();
        $update_data = [];
        $update_format = [];

        if ($this->support_ticket_has_column('queue_key')) {
            $update_data['queue_key'] = 'payroll';
            $update_format[] = '%s';
        }
        if ($this->support_ticket_has_column('assigned_to_user_id')) {
            $update_data['assigned_to_user_id'] = $assignee_user_id > 0 ? $assignee_user_id : null;
            $update_format[] = '%d';
        }
        if ($this->support_ticket_has_column('priority')) {
            $update_data['priority'] = $priority_value;
            $update_format[] = '%s';
        }
        if ($update_data) {
            $update_data['updated_at'] = current_time('mysql');
            $update_format[] = '%s';
            $wpdb->update(
                $table,
                $update_data,
                ['id' => $ticket_id],
                $update_format,
                ['%d']
            );
        }

        $this->log_payroll_ticket_assigned_event(
            $ticket_id,
            $existing_assignee_user_id,
            $assignee_user_id,
            $actor_user_id,
            $current_status_for_audit,
            $current_status_for_audit
        );

        $payroll_meta = $this->get_support_payroll_query_metadata_by_ticket($ticket_id);
        $period_id = sanitize_text_field((string) ($context['period_id'] ?? ($payroll_meta['period_id'] ?? '')));
        if ($period_id === '') {
            $period_id = 'unknown-period';
        }

        $period_label = sanitize_text_field((string) ($context['period_label'] ?? ''));
        if ($period_label === '') {
            $period_start = $this->normalize_invoice_date((string) ($payroll_meta['period_start'] ?? ''));
            $period_end = $this->normalize_invoice_date((string) ($payroll_meta['period_end'] ?? ''));
            if ($period_start !== '' && $period_end !== '') {
                $period_label = 'Fri ' . date_i18n('j M Y', strtotime($period_start)) . ' -> Thu ' . date_i18n('j M Y', strtotime($period_end));
            } else {
                $period_label = $period_id;
            }
        }

        $issue_type_label = sanitize_text_field((string) ($context['issue_type_label'] ?? ''));
        if ($issue_type_label === '') {
            $issue_type_label = sanitize_text_field((string) ($payroll_meta['issue_type_label'] ?? 'Other'));
        }

        $owner_user_id = max(0, (int) ($payroll_meta['candidate_user_id'] ?? 0));
        if ($owner_user_id < 1) {
            $owner_user_id = (int) $this->get_support_owner_user_id($ticket);
        }
        $owner_user = $owner_user_id > 0 ? get_user_by('id', $owner_user_id) : null;
        $candidate_name = $owner_user instanceof WP_User
            ? sanitize_text_field((string) ($owner_user->display_name ?: $owner_user->user_login))
            : 'Unknown candidate';

        $message_preview_source = (string) ($context['message_preview_source'] ?? '');
        if ($message_preview_source === '') {
            $messages = $this->get_support_ticket_messages($ticket_id);
            if (is_array($messages) && !empty($messages[0]['message'])) {
                $message_preview_source = (string) $messages[0]['message'];
            }
        }
        $message_preview = $this->build_payroll_ticket_message_preview($message_preview_source, 200);

        $recipient_email = $this->resolve_payroll_ticket_notification_email();
        $notification_sent = false;
        if ($recipient_email !== '') {
            $staff_link_user_id = $assignee_user_id > 0 ? $assignee_user_id : $this->get_support_primary_admin_user_id();
            $staff_link = $this->get_support_link_for_user($staff_link_user_id, $ticket_id, (string) ($ticket['ticket_ref'] ?? ''));
            $email_subject = 'New Payroll Ticket — ' . $ticket_id . ' — ' . $period_id;
            $email_body = implode("\n", [
                'A new payroll support ticket has been routed.',
                '',
                'Ticket ID: ' . $ticket_id,
                'Staff link: ' . $staff_link,
                'Candidate: ' . $candidate_name . ' (user_id: ' . $owner_user_id . ')',
                'Period: ' . $period_label,
                'Issue type: ' . $issue_type_label,
                'Message preview: ' . $message_preview,
            ]);
            $notification_sent = (bool) $this->send_support_email($recipient_email, $email_subject, $email_body, [
                'type' => 'support_payroll_ticket_routed',
                'template_key' => 'support_payroll_ticket_routed',
                'recipient_role' => 'admin',
                'module' => 'support',
                'related_entity_type' => 'support_ticket',
                'related_entity_id' => $ticket_id,
            ]);
        }

        if ($assignee_user_id > 0 && $this->is_staff_user($assignee_user_id)) {
            $assignee_link = $this->get_support_link_for_user($assignee_user_id, $ticket_id, (string) ($ticket['ticket_ref'] ?? ''));
            $assignee_title = 'Payroll ticket assigned';
            $assignee_message = 'Ticket #' . $ticket_id . ' routed to payroll queue.';
            $this->add_notification($assignee_user_id, 'support_payroll_ticket', $assignee_title, $assignee_message, $assignee_link);
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'support',
                'entity_type' => 'ticket',
                'entity_id' => $ticket_id,
                'event_type' => 'payroll_ticket_routed',
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'ticket_id' => $ticket_id,
                    'assigned_to' => $assignee_user_id,
                    'notification_sent' => (bool) $notification_sent,
                ],
            ]);
        }

        return [
            'routed' => true,
            'assigned_to' => $assignee_user_id,
            'notification_sent' => (bool) $notification_sent,
        ];
    }

    private function get_candidate_payroll_query_issue_type_map() {
        return [
            'missing_shift' => 'Missing shift',
            'incorrect_rate' => 'Incorrect rate',
            'hold_bank_issue' => 'Hold / bank issue',
            'dispute_no_show_attendance' => 'Dispute no-show / attendance',
            'other' => 'Other',
        ];
    }

    private function normalize_candidate_payroll_query_issue_type($issue_type) {
        $issue_type = sanitize_key((string) $issue_type);
        $allowed = $this->get_candidate_payroll_query_issue_type_map();
        if (!isset($allowed[$issue_type])) {
            return 'other';
        }
        return $issue_type;
    }

    private function get_candidate_payroll_query_period_options($max_periods = 5) {
        $max_periods = max(1, min(12, (int) $max_periods));
        $periods = [];
        $seen = [];

        $current = function_exists('cmn_payroll_get_current_period')
            ? (array) cmn_payroll_get_current_period()
            : (array) $this->get_payroll_current_period();

        for ($index = 0; $index < $max_periods; $index++) {
            $period_start = $this->normalize_invoice_date((string) ($current['period_start'] ?? ''));
            $period_end = $this->normalize_invoice_date((string) ($current['period_end'] ?? ''));
            if ($period_start === '' || $period_end === '') {
                break;
            }
            $period_id = sanitize_text_field((string) ($current['period_id'] ?? ''));
            if ($period_id === '') {
                $period_id = $this->get_payroll_period_id($period_start, $period_end);
            }
            if ($period_id === '' || isset($seen[$period_id])) {
                break;
            }
            $seen[$period_id] = true;

            $label = sanitize_text_field((string) ($current['label'] ?? ''));
            if ($label === '') {
                $label = 'Fri ' . date_i18n('j M', strtotime($period_start)) . ' - Thu ' . date_i18n('j M', strtotime($period_end));
            }

            $periods[] = [
                'period_id' => $period_id,
                'period_start' => $period_start,
                'period_end' => $period_end,
                'pay_date' => $this->normalize_invoice_date((string) ($current['pay_date'] ?? '')),
                'label' => $label,
            ];

            $reference = $period_start . ' -1 day';
            $current = function_exists('cmn_payroll_get_period_for_date')
                ? (array) cmn_payroll_get_period_for_date($reference)
                : (array) $this->get_payroll_period_for_date($reference);
        }

        return $periods;
    }

    private function get_candidate_payroll_query_booking_day_options($candidate_user_id, $period_id) {
        $candidate_user_id = (int) $candidate_user_id;
        $period_id = sanitize_text_field((string) $period_id);
        if ($candidate_user_id < 1 || $period_id === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_pay_approvals_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }

        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT id, booking_id, booking_day_date, approval_status, approved_method
             FROM {$table}
             WHERE candidate_user_id = %d
               AND period_id = %s
             ORDER BY booking_day_date ASC, id ASC",
            $candidate_user_id,
            $period_id
        ), ARRAY_A);
        if (!is_array($rows) || !$rows) {
            return [];
        }

        $booking_ids = array_values(array_unique(array_filter(array_map('intval', array_column($rows, 'booking_id')))));
        $rate_rows_map = $this->get_booking_rate_rows_map($booking_ids);
        $items = [];
        $seen = [];

        foreach ($rows as $row) {
            $booking_id = max(0, (int) ($row['booking_id'] ?? 0));
            $booking_day_date = $this->normalize_invoice_date((string) ($row['booking_day_date'] ?? ''));
            if ($booking_id < 1 || $booking_day_date === '') {
                continue;
            }

            $value = $booking_id . '|' . $booking_day_date;
            if (isset($seen[$value])) {
                continue;
            }
            $seen[$value] = true;

            $approval_status = sanitize_key((string) ($row['approval_status'] ?? 'approved'));
            $approved_method = sanitize_key((string) ($row['approved_method'] ?? 'school_confirmed'));
            $status_label = $approval_status === 'approved'
                ? $this->get_remittance_approval_status_label($approved_method)
                : ucfirst(str_replace('_', ' ', $approval_status));

            $rate_row = (isset($rate_rows_map[$booking_id]) && is_array($rate_rows_map[$booking_id]))
                ? (array) $rate_rows_map[$booking_id]
                : [];
            $school_label = $this->get_remittance_school_label_for_booking($booking_id);
            $role_label = $this->get_remittance_role_label_for_booking($booking_id, $rate_row);
            $date_label = date_i18n('D j M Y', strtotime($booking_day_date));

            $items[] = [
                'value' => $value,
                'booking_id' => $booking_id,
                'booking_day_date' => $booking_day_date,
                'label' => trim($date_label . ' - ' . $school_label . ' - ' . $role_label . ' (' . $status_label . ')'),
                'status' => $approval_status,
            ];
        }

        return $items;
    }

    private function get_candidate_payroll_query_rate_limit_key($candidate_user_id) {
        return 'cmn_candidate_payroll_query_rate_' . max(1, (int) $candidate_user_id);
    }

    private function get_candidate_payroll_query_recent_submission_timestamps($candidate_user_id, $window_seconds = DAY_IN_SECONDS) {
        $candidate_user_id = (int) $candidate_user_id;
        $window_seconds = max(60, (int) $window_seconds);
        if ($candidate_user_id < 1) {
            return [];
        }

        $raw = get_transient($this->get_candidate_payroll_query_rate_limit_key($candidate_user_id));
        $timestamps = is_array($raw) ? $raw : [];
        $now = time();
        $valid = [];
        foreach ($timestamps as $timestamp) {
            $timestamp = (int) $timestamp;
            if ($timestamp > 0 && ($now - $timestamp) < $window_seconds) {
                $valid[] = $timestamp;
            }
        }
        return $valid;
    }

    private function assert_candidate_payroll_query_rate_limit($candidate_user_id, $max_submissions = 2, $window_seconds = DAY_IN_SECONDS) {
        $candidate_user_id = (int) $candidate_user_id;
        $max_submissions = max(1, (int) $max_submissions);
        $recent = $this->get_candidate_payroll_query_recent_submission_timestamps($candidate_user_id, $window_seconds);
        if (count($recent) >= $max_submissions) {
            return new WP_Error(
                'cmn_payroll_query_rate_limited',
                'Rate limit reached. You can submit up to 2 payroll queries per 24 hours.',
                ['status' => 429]
            );
        }
        return true;
    }

    private function record_candidate_payroll_query_submission($candidate_user_id, $window_seconds = DAY_IN_SECONDS) {
        $candidate_user_id = (int) $candidate_user_id;
        $window_seconds = max(60, (int) $window_seconds);
        if ($candidate_user_id < 1) {
            return;
        }
        $recent = $this->get_candidate_payroll_query_recent_submission_timestamps($candidate_user_id, $window_seconds);
        $recent[] = time();
        set_transient($this->get_candidate_payroll_query_rate_limit_key($candidate_user_id), $recent, $window_seconds);
    }

    private function normalize_support_payroll_query_booking_refs($booking_refs = []) {
        $booking_refs = is_array($booking_refs) ? $booking_refs : [];
        $normalized = [];
        foreach ($booking_refs as $booking_ref) {
            if (!is_array($booking_ref)) {
                continue;
            }
            $booking_id = max(0, (int) ($booking_ref['booking_id'] ?? 0));
            $booking_day_date = $this->normalize_invoice_date((string) ($booking_ref['booking_day_date'] ?? ''));
            if ($booking_id < 1 || $booking_day_date === '') {
                continue;
            }
            $normalized[] = [
                'booking_id' => $booking_id,
                'booking_day_date' => $booking_day_date,
            ];
        }
        return array_values($normalized);
    }

    private function upsert_support_payroll_query_metadata($ticket_id, $candidate_user_id, $period, $issue_type, $booking_refs = [], $payout_run_id = 0) {
        $ticket_id = (int) $ticket_id;
        $candidate_user_id = (int) $candidate_user_id;
        $period = is_array($period) ? $period : [];
        $issue_type = $this->normalize_candidate_payroll_query_issue_type($issue_type);
        $payout_run_id = max(0, (int) $payout_run_id);
        if ($ticket_id < 1 || $candidate_user_id < 1) {
            return new WP_Error('cmn_payroll_query_meta_invalid', 'Payroll query metadata context is invalid.');
        }

        $period_id = sanitize_text_field((string) ($period['period_id'] ?? ''));
        $period_start = $this->normalize_invoice_date((string) ($period['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($period['period_end'] ?? ''));
        $pay_date = $this->normalize_invoice_date((string) ($period['pay_date'] ?? ''));
        if ($period_id === '' || $period_start === '' || $period_end === '') {
            return new WP_Error('cmn_payroll_query_meta_period_invalid', 'Payroll period metadata is invalid.');
        }

        $booking_refs = $this->normalize_support_payroll_query_booking_refs($booking_refs);
        $booking_refs_json = $booking_refs ? wp_json_encode($booking_refs) : null;
        if ($booking_refs_json !== null && !is_string($booking_refs_json)) {
            $booking_refs_json = null;
        }

        global $wpdb;
        $table = $this->get_support_payroll_query_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return new WP_Error('cmn_payroll_query_meta_table_missing', 'Payroll query metadata table is unavailable.');
        }

        $now = current_time('mysql');
        $existing_id = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id
             FROM {$table}
             WHERE ticket_id = %d
             LIMIT 1",
            $ticket_id
        ));

        if ($existing_id > 0) {
            $updated = $wpdb->update(
                $table,
                [
                    'candidate_user_id' => $candidate_user_id,
                    'period_id' => $period_id,
                    'period_start' => $period_start,
                    'period_end' => $period_end,
                    'pay_date' => $pay_date !== '' ? $pay_date : null,
                    'issue_type' => $issue_type,
                    'booking_refs_json' => $booking_refs_json,
                    'payout_run_id' => $payout_run_id > 0 ? $payout_run_id : null,
                    'updated_at' => $now,
                ],
                ['id' => $existing_id],
                ['%d', '%s', '%s', '%s', '%s', '%s', '%s', '%d', '%s'],
                ['%d']
            );
            if ($updated === false) {
                return new WP_Error('cmn_payroll_query_meta_update_failed', 'Unable to update payroll query metadata.');
            }
            return true;
        }

        $inserted = $wpdb->insert(
            $table,
            [
                'ticket_id' => $ticket_id,
                'candidate_user_id' => $candidate_user_id,
                'period_id' => $period_id,
                'period_start' => $period_start,
                'period_end' => $period_end,
                'pay_date' => $pay_date !== '' ? $pay_date : null,
                'issue_type' => $issue_type,
                'booking_refs_json' => $booking_refs_json,
                'payout_run_id' => $payout_run_id > 0 ? $payout_run_id : null,
                'created_at' => $now,
                'updated_at' => $now,
            ],
            ['%d', '%d', '%s', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%s']
        );
        if ($inserted === false) {
            return new WP_Error('cmn_payroll_query_meta_insert_failed', 'Unable to save payroll query metadata.');
        }
        return true;
    }

    private function get_support_payroll_query_metadata_by_ticket($ticket_id) {
        $ticket_id = (int) $ticket_id;
        if ($ticket_id < 1) {
            return [];
        }

        global $wpdb;
        $table = $this->get_support_payroll_query_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }

        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE ticket_id = %d
             LIMIT 1",
            $ticket_id
        ), ARRAY_A);
        if (!is_array($row)) {
            return [];
        }

        $booking_refs = [];
        $raw_booking_refs = (string) ($row['booking_refs_json'] ?? '');
        if ($raw_booking_refs !== '') {
            $decoded = json_decode($raw_booking_refs, true);
            if (is_array($decoded)) {
                $booking_refs = $this->normalize_support_payroll_query_booking_refs($decoded);
            }
        }

        $issue_type = $this->normalize_candidate_payroll_query_issue_type((string) ($row['issue_type'] ?? 'other'));
        $issue_type_map = $this->get_candidate_payroll_query_issue_type_map();

        return [
            'ticket_id' => (int) ($row['ticket_id'] ?? 0),
            'candidate_user_id' => (int) ($row['candidate_user_id'] ?? 0),
            'period_id' => sanitize_text_field((string) ($row['period_id'] ?? '')),
            'period_start' => $this->normalize_invoice_date((string) ($row['period_start'] ?? '')),
            'period_end' => $this->normalize_invoice_date((string) ($row['period_end'] ?? '')),
            'pay_date' => $this->normalize_invoice_date((string) ($row['pay_date'] ?? '')),
            'issue_type' => $issue_type,
            'issue_type_label' => (string) ($issue_type_map[$issue_type] ?? 'Other'),
            'booking_refs' => $booking_refs,
            'payout_run_id' => max(0, (int) ($row['payout_run_id'] ?? 0)),
            'created_at' => $this->normalize_invoice_datetime((string) ($row['created_at'] ?? '')),
            'updated_at' => $this->normalize_invoice_datetime((string) ($row['updated_at'] ?? '')),
        ];
    }

    private function extract_ticket_ref_from_text($text) {
        $text = (string) $text;
        if (preg_match('/CMN-SUP-\d{6}/i', $text, $matches)) {
            return strtoupper($matches[0]);
        }
        return '';
    }

    private function resolve_support_notification_link($item, $user_id, $fallback = '') {
        $type = sanitize_key((string) ($item['type'] ?? ''));
        if (!in_array($type, ['support_reply', 'support_new', 'support_new_ticket', 'support_ticket_closed', 'support_ticket_reopened', 'support_feedback'], true)) {
            return $fallback;
        }
        if (!empty($item['link_url']) && strpos((string) $item['link_url'], 'ticket_id=') !== false) {
            return $item['link_url'];
        }
        $ticket_ref = $this->extract_ticket_ref_from_text(($item['message'] ?? '') . ' ' . ($item['title'] ?? ''));
        $ticket_id = 0;
        if ($ticket_ref !== '') {
            $ticket = $this->get_support_ticket_by_ref($ticket_ref);
            if ($ticket) {
                $ticket_id = (int) $ticket['id'];
            }
        }
        return $this->get_support_link_for_user($user_id, $ticket_id, $ticket_ref);
    }

    private function send_support_email_to_user($user_id, $subject, $message, $log_type = 'support_update', $context = []) {
        $user = get_user_by('id', $user_id);
        if (!$user) {
            return false;
        }
        $user_id = (int) $user_id;
        $context = is_array($context) ? $context : [];
        $recipient_role = 'system';
        if ($this->is_candidate_user($user_id)) {
            $recipient_role = 'candidate';
            if (!$this->can_send_candidate_email_for_context($user->user_email, [
                'type' => $log_type,
                'user_id' => $user_id,
            ])) {
                $this->log_email($user->user_email, (string) $subject, ['type' => $log_type], 'skipped', 'Candidate email preference disabled');
                return true;
            }
        } elseif ($this->is_school_user($user_id)) {
            $recipient_role = 'school';
        } elseif ($this->is_admin_user($user_id)) {
            $recipient_role = 'admin';
        } elseif ($this->is_staff_role($user_id) || $this->is_account_manager_user($user_id)) {
            $recipient_role = 'staff';
        }

        $related_entity_type = sanitize_key((string) ($context['related_entity_type'] ?? 'support_ticket'));
        $related_entity_id = max(0, (int) ($context['related_entity_id'] ?? ($context['ticket_id'] ?? 0)));
        return $this->send_support_email($user->user_email, $subject, $message, [
            'type' => sanitize_key((string) $log_type),
            'template_key' => sanitize_key((string) ($context['template_key'] ?? $log_type)),
            'recipient_role' => $recipient_role,
            'recipient_user_id' => $user_id,
            'module' => 'support',
            'related_entity_type' => $related_entity_type !== '' ? $related_entity_type : 'support_ticket',
            'related_entity_id' => $related_entity_id,
        ]);
    }

    private function can_manage_staff_users($user_id = 0) {
        $user = $user_id ? get_user_by('id', $user_id) : wp_get_current_user();
        if (!$user || !$user->ID) {
            return false;
        }
        if ($this->is_super_admin_user()) {
            return true;
        }
        return in_array('cmn_admin', (array) $user->roles, true);
    }

    private function get_candidate_ids_with_deletion_request() {
        $user_ids = get_users([
            'fields' => 'ID',
            'meta_key' => 'cmn_deletion_requested',
            'meta_value' => '1',
        ]);
        if (!$user_ids) {
            return [];
        }
        $candidate_posts = get_posts([
            'post_type' => 'cmn_candidate',
            'posts_per_page' => -1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_user_id',
                    'value' => array_map('intval', (array) $user_ids),
                    'compare' => 'IN',
                    'type' => 'NUMERIC',
                ],
            ],
        ]);
        return array_map('intval', (array) $candidate_posts);
    }

    private function is_super_admin_user_id($user_id) {
        if (!$user_id) {
            return false;
        }
        $user = get_user_by('id', $user_id);
        if (!$user || !$user->ID) {
            return false;
        }
        return strtolower($user->user_email) === 'jaynorton17@gmail.com';
    }

    private function generate_unique_username($seed) {
        $base = sanitize_user($seed, true);
        if ($base === '') {
            $base = 'staff';
        }
        $username = $base;
        $suffix = 2;
        while (username_exists($username)) {
            $username = $base . '-' . $suffix;
            $suffix++;
        }
        return $username;
    }

    private function build_password_reset_link($user) {
        if (!$user instanceof WP_User) {
            return '';
        }
        $key = get_password_reset_key($user);
        if (is_wp_error($key)) {
            return '';
        }
        return $this->get_portal_reset_url($user->user_login, $key);
    }

    private function send_staff_welcome_email($user, $plain_password = '') {
        if (!$user instanceof WP_User) {
            return false;
        }
        $login_url = $this->get_portal_base_url();
        $reset_link = $this->build_password_reset_link($user);
        $subject = 'Your CoverMeNow ONE Staff Login';
        $message = "Welcome to CoverMeNow ONE.\n\nUsername: {$user->user_login}\nLogin: {$login_url}\n\nSet your password here:\n{$reset_link}\n\nIf you need any help, reply to this email.";
        $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
        $GLOBALS['cmn_school_mail_log_type'] = 'staff_welcome';
        $sent = $this->send_school_email($user->user_email, $subject, $message);
        if ($previous_log_type !== null) {
            $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
        } else {
            unset($GLOBALS['cmn_school_mail_log_type']);
        }
        return $sent;
    }

    private function send_staff_reset_email($user) {
        if (!$user instanceof WP_User) {
            return false;
        }
        $reset_link = $this->build_password_reset_link($user);
        if ($reset_link === '') {
            return false;
        }
        $subject = 'Reset your CoverMeNow ONE password';
        $message = "Use the link below to reset your password:\n{$reset_link}\n\nIf you did not request this, please ignore this email.";
        $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
        $GLOBALS['cmn_school_mail_log_type'] = 'staff_reset';
        $sent = $this->send_school_email($user->user_email, $subject, $message);
        if ($previous_log_type !== null) {
            $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
        } else {
            unset($GLOBALS['cmn_school_mail_log_type']);
        }
        return $sent;
    }

