    public function get_system_fix_log($limit = 100, $filters = []) {
        global $wpdb;
        $table = $this->get_system_fix_log_table();
        $limit = max(1, min(500, (int) $limit));
        $where = ['1=1'];
        $params = [];
        $issue_key = sanitize_key((string) ($filters['issue_key'] ?? ''));
        $performed_by = (int) ($filters['performed_by'] ?? 0);
        $date_from = sanitize_text_field((string) ($filters['date_from'] ?? ''));
        $date_to = sanitize_text_field((string) ($filters['date_to'] ?? ''));
        if ($issue_key !== '') {
            $where[] = 'issue_key = %s';
            $params[] = $issue_key;
        }
        if ($performed_by > 0) {
            $where[] = 'performed_by = %d';
            $params[] = $performed_by;
        }
        if ($date_from !== '') {
            $where[] = 'performed_at >= %s';
            $params[] = $date_from . ' 00:00:00';
        }
        if ($date_to !== '') {
            $where[] = 'performed_at <= %s';
            $params[] = $date_to . ' 23:59:59';
        }
        $where_sql = implode(' AND ', $where);
        $params[] = $limit;
        $sql = "SELECT id, issue_key, entity_type, entity_id, action_json, performed_by, performed_at, before_json, after_json
                FROM {$table}
                WHERE {$where_sql}
                ORDER BY id DESC
                LIMIT %d";
        $rows = $wpdb->get_results($wpdb->prepare($sql, $params), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    public function insert_system_fix_log($issue_key, $entity_type, $entity_id, $action_array = [], $before_array = [], $after_array = []) {
        global $wpdb;
        $table = $this->get_system_fix_log_table();
        $issue_key = substr(sanitize_key((string) $issue_key), 0, 64);
        $entity_type = substr(sanitize_key((string) $entity_type), 0, 32);
        $entity_id = (int) $entity_id;
        $action = is_array($action_array) ? $action_array : [];
        $before = is_array($before_array) ? $before_array : [];
        $after = is_array($after_array) ? $after_array : [];
        $ok = $wpdb->insert($table, [
            'issue_key' => $issue_key !== '' ? $issue_key : 'unknown_issue',
            'entity_type' => $entity_type !== '' ? $entity_type : 'system',
            'entity_id' => $entity_id > 0 ? $entity_id : null,
            'action_json' => wp_json_encode($action),
            'performed_by' => get_current_user_id() ?: null,
            'performed_at' => current_time('mysql'),
            'before_json' => wp_json_encode($before),
            'after_json' => wp_json_encode($after),
        ], ['%s', '%s', '%d', '%s', '%d', '%s', '%s', '%s']);
        if ($ok === false) {
            return 0;
        }
        return (int) $wpdb->insert_id;
    }

    private function get_request_ip_address() {
        $candidates = [
            $_SERVER['HTTP_CF_CONNECTING_IP'] ?? '',
            $_SERVER['HTTP_X_FORWARDED_FOR'] ?? '',
            $_SERVER['REMOTE_ADDR'] ?? '',
        ];
        foreach ($candidates as $raw) {
            $raw = trim((string) $raw);
            if ($raw === '') {
                continue;
            }
            if (strpos($raw, ',') !== false) {
                $parts = array_map('trim', explode(',', $raw));
                $raw = (string) ($parts[0] ?? '');
            }
            if ($raw !== '') {
                return substr($raw, 0, 64);
            }
        }
        return '';
    }

    private function add_audit_log($action_type, $reference_type = '', $reference_id = '', $details = [], $user_id = 0) {
        global $wpdb;
        $table = $this->get_audit_log_table();
        if ($table === '') {
            return 0;
        }
        $user_id = $user_id ? (int) $user_id : (int) get_current_user_id();
        $details_json = '';
        if (is_array($details) && !empty($details)) {
            $details_json = wp_json_encode($details);
        } elseif (is_string($details) && $details !== '') {
            $details_json = $details;
        }
        $wpdb->insert($table, [
            'user_id' => $user_id ?: null,
            'action_type' => sanitize_key((string) $action_type),
            'reference_type' => sanitize_key((string) $reference_type),
            'reference_id' => sanitize_text_field((string) $reference_id),
            'details_json' => $details_json,
            'ip_address' => $this->get_request_ip_address(),
            'created_at' => current_time('mysql'),
        ], ['%d', '%s', '%s', '%s', '%s', '%s', '%s']);
        return (int) $wpdb->insert_id;
    }

    private function insert_audit($action_type, $reference_type, $reference_id, $details = [], $user_id = 0) {
        return $this->add_audit_log($action_type, $reference_type, $reference_id, $details, $user_id);
    }

