            ];
        }
        return $items;
    }

    private function detect_system_health_orphan_contacts($limit_items = 100) {
        global $wpdb;
        $limit_items = max(1, min(500, (int) $limit_items));
        $contact_school_table = $this->get_contact_school_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT p.ID AS contact_id,
                    COALESCE(email.meta_value, '') AS contact_email,
                    COALESCE(legacy.meta_value, '') AS legacy_school_id
             FROM {$wpdb->posts} p
             LEFT JOIN {$wpdb->postmeta} email ON email.post_id = p.ID AND email.meta_key = 'cmn_contact_email'
             LEFT JOIN {$wpdb->postmeta} legacy ON legacy.post_id = p.ID AND legacy.meta_key = 'cmn_contact_school_id'
             LEFT JOIN {$contact_school_table} cs ON cs.contact_id = p.ID
             WHERE p.post_type = %s
               AND p.post_status NOT IN ('trash', 'auto-draft')
               AND cs.id IS NULL
               AND (legacy.meta_value IS NULL OR TRIM(legacy.meta_value) = '' OR legacy.meta_value = '0')
             ORDER BY p.ID DESC
             LIMIT %d",
            'cmn_contact',
            $limit_items
        ), ARRAY_A);
        $items = [];
        foreach ((array) $rows as $row) {
            $contact_id = (int) ($row['contact_id'] ?? 0);
            if ($contact_id < 1) {
                continue;
            }
            $domain = $this->extract_email_domain((string) ($row['contact_email'] ?? ''));
            $matching_school_ids = [];
            if ($domain !== '') {
                $matching_school_ids = get_posts([
                    'post_type' => 'cmn_school',
                    'post_status' => ['publish', 'pending', 'draft', 'future', 'private'],
                    'fields' => 'ids',
                    'posts_per_page' => 5,
                    'meta_query' => [[
                        'key' => 'cmn_school_email_domain',
                        'value' => $domain,
                        'compare' => '=',
                    ]],
                ]);
                $matching_school_ids = array_values(array_filter(array_map('intval', (array) $matching_school_ids)));
            }
            if (!empty($matching_school_ids)) {
                continue;
            }
            $items[] = [
                'entity_id' => $contact_id,
                'contact_email_domain' => $domain,
            ];
        }
        return $items;
    }

    private function detect_system_health_candidate_missing_profile_fields($limit_items = 100) {
        global $wpdb;
        $limit_items = max(1, min(500, (int) $limit_items));
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT p.ID AS candidate_id,
                    COALESCE(driving.meta_value, '') AS driving_licence,
                    COALESCE(car.meta_value, '') AS car_owner,
                    COALESCE(email.meta_value, '') AS candidate_email,
                    COALESCE(phone.meta_value, '') AS candidate_phone,
                    COALESCE(location.meta_value, '') AS candidate_location,
                    COALESCE(user_link.meta_value, '') AS candidate_user_id,
                    COALESCE(drives.meta_value, '') AS legacy_drives,
                    COALESCE(has_car.meta_value, '') AS legacy_has_car
             FROM {$wpdb->posts} p
             LEFT JOIN {$wpdb->postmeta} driving ON driving.post_id = p.ID AND driving.meta_key = 'cmn_driving_licence'
             LEFT JOIN {$wpdb->postmeta} car ON car.post_id = p.ID AND car.meta_key = 'cmn_car_owner'
             LEFT JOIN {$wpdb->postmeta} email ON email.post_id = p.ID AND email.meta_key = 'cmn_email'
             LEFT JOIN {$wpdb->postmeta} phone ON phone.post_id = p.ID AND phone.meta_key = 'cmn_phone'
             LEFT JOIN {$wpdb->postmeta} location ON location.post_id = p.ID AND location.meta_key = 'cmn_location'
             LEFT JOIN {$wpdb->postmeta} user_link ON user_link.post_id = p.ID AND user_link.meta_key = 'cmn_user_id'
             LEFT JOIN {$wpdb->postmeta} drives ON drives.post_id = p.ID AND drives.meta_key = 'cmn_drives'
             LEFT JOIN {$wpdb->postmeta} has_car ON has_car.post_id = p.ID AND has_car.meta_key = 'cmn_has_car'
             WHERE p.post_type = %s
               AND p.post_status NOT IN ('trash', 'auto-draft')
               AND (TRIM(COALESCE(driving.meta_value, '')) = '' OR TRIM(COALESCE(car.meta_value, '')) = '')
             ORDER BY p.ID DESC
             LIMIT %d",
            'cmn_candidate',
            $limit_items
        ), ARRAY_A);
        $items = [];
        foreach ((array) $rows as $row) {
            $candidate_id = (int) ($row['candidate_id'] ?? 0);
            if ($candidate_id < 1) {
                continue;
            }
            $registration_exists = trim((string) ($row['candidate_email'] ?? '')) !== ''
                || trim((string) ($row['candidate_phone'] ?? '')) !== ''
                || trim((string) ($row['candidate_location'] ?? '')) !== ''
                || (int) ($row['candidate_user_id'] ?? 0) > 0
                || trim((string) ($row['legacy_drives'] ?? '')) !== ''
                || trim((string) ($row['legacy_has_car'] ?? '')) !== '';
            if (!$registration_exists) {
                continue;
            }
            $items[] = [
                'entity_id' => $candidate_id,
                'missing_driving_licence' => trim((string) ($row['driving_licence'] ?? '')) === '' ? 1 : 0,
                'missing_car_owner' => trim((string) ($row['car_owner'] ?? '')) === '' ? 1 : 0,
                'legacy_drives' => sanitize_key((string) ($row['legacy_drives'] ?? '')),
                'legacy_has_car' => sanitize_key((string) ($row['legacy_has_car'] ?? '')),
            ];
        }
        return $items;
    }

    private function detect_system_health_duplicate_school_domains($limit_items = 100) {
        global $wpdb;
        $limit_items = max(1, min(500, (int) $limit_items));
        $rows = $wpdb->get_results(
            "SELECT LOWER(TRIM(pm.meta_value)) AS school_domain,
                    COUNT(*) AS total_count,
                    GROUP_CONCAT(pm.post_id ORDER BY pm.post_id ASC) AS school_ids
             FROM {$wpdb->postmeta} pm
             INNER JOIN {$wpdb->posts} p ON p.ID = pm.post_id
             WHERE p.post_type = 'cmn_school'
               AND p.post_status NOT IN ('trash', 'auto-draft')
               AND pm.meta_key = 'cmn_school_email_domain'
               AND TRIM(pm.meta_value) <> ''
             GROUP BY LOWER(TRIM(pm.meta_value))
             HAVING COUNT(*) > 1
             ORDER BY total_count DESC
             LIMIT " . (int) $limit_items,
            ARRAY_A
        );
        $items = [];
        foreach ((array) $rows as $row) {
            $school_ids = array_values(array_filter(array_map('intval', explode(',', (string) ($row['school_ids'] ?? '')))));
            $items[] = [
                'domain' => (string) ($row['school_domain'] ?? ''),
                'entity_id' => !empty($school_ids) ? (int) $school_ids[0] : 0,
                'school_ids' => $school_ids,
                'count' => (int) ($row['total_count'] ?? 0),
            ];
        }
        return $items;
    }

    public function run_system_health_scan($limit_items = 100) {
        $limit_items = max(1, min(500, (int) $limit_items));
        $out = [
            'orphan_contacts' => [
                'count' => 0,
                'severity' => 'MED',
                'items' => [],
            ],
            'schools_missing_domain' => [
                'count' => 0,
                'severity' => 'MED',
                'items' => [],
            ],
            'bookings_missing_rate_row' => [
                'count' => 0,
                'severity' => 'HIGH',
                'items' => [],
            ],
            'booking_rate_row_missing_status' => [
                'count' => 0,
                'severity' => 'HIGH',
                'items' => [],
            ],
            'candidate_missing_profile_fields' => [
                'count' => 0,
                'severity' => 'LOW',
                'items' => [],
            ],
            'duplicate_school_domains' => [
                'count' => 0,
                'severity' => 'WARN',
                'items' => [],
            ],
        ];
        $out['orphan_contacts']['items'] = $this->detect_system_health_orphan_contacts($limit_items);
        $out['schools_missing_domain']['items'] = $this->detect_system_health_schools_missing_domain($limit_items);
        $out['bookings_missing_rate_row']['items'] = $this->detect_system_health_bookings_missing_rate_row($limit_items);
        $out['booking_rate_row_missing_status']['items'] = $this->detect_system_health_booking_rate_row_missing_status($limit_items);
        $out['candidate_missing_profile_fields']['items'] = $this->detect_system_health_candidate_missing_profile_fields($limit_items);
        $out['duplicate_school_domains']['items'] = $this->detect_system_health_duplicate_school_domains($limit_items);
        foreach ($out as $key => $item) {
            $out[$key]['count'] = count((array) ($item['items'] ?? []));
        }
        return $out;
    }

    private function normalize_yes_no_value($value) {
        $value = sanitize_key((string) $value);
        if (in_array($value, ['yes', '1', 'true'], true)) {
            return 'yes';
        }
        if (in_array($value, ['no', '0', 'false'], true)) {
            return 'no';
        }
        return '';
    }

    private function apply_system_health_fix_schools_missing_domain($items) {
        $result = ['fixed_count' => 0, 'skipped_count' => 0, 'errors' => []];
        foreach ((array) $items as $item) {
            $school_id = (int) ($item['entity_id'] ?? 0);
            if ($school_id < 1) {
                $result['skipped_count']++;
                continue;
            }
            $current = strtolower(trim((string) get_post_meta($school_id, 'cmn_school_email_domain', true)));
            if ($current !== '') {
                $result['skipped_count']++;
                continue;
            }
            $domain = strtolower(trim((string) ($item['computed_domain'] ?? '')));
            if ($domain === '') {
                $result['skipped_count']++;
                continue;
            }
            update_post_meta($school_id, 'cmn_school_email_domain', $domain);
            $this->insert_system_fix_log(
                'schools_missing_domain',
                'school',
                $school_id,
                [
                    'status' => 'success',
                    'summary' => 'Filled missing school domain from existing school email.',
                ],
                ['cmn_school_email_domain' => $current],
                ['cmn_school_email_domain' => $domain]
            );
            $result['fixed_count']++;
        }
        return $result;
    }

    private function apply_system_health_fix_bookings_missing_rate_row($items) {
        $result = ['fixed_count' => 0, 'skipped_count' => 0, 'errors' => []];
        foreach ((array) $items as $item) {
            $booking_id = (int) ($item['entity_id'] ?? 0);
            if ($booking_id < 1) {
                $result['skipped_count']++;
                continue;
            }
            try {
                $existing_row = $this->get_booking_rate_row($booking_id);
                if (!empty($existing_row)) {
                    $result['skipped_count']++;
                    continue;
                }
                $request_id = (int) get_post_meta($booking_id, 'cmn_request_id', true);
                $request = $request_id > 0 ? (array) $this->get_candidate_request_by_id($request_id) : [];
                $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
                $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
                $context = $this->resolve_rate_context($candidate_id, $school_id, $request, $booking_id);
                $school_rate = (float) get_post_meta($booking_id, 'cmn_school_charge_rate', true);
                $candidate_pay = (float) get_post_meta($booking_id, 'cmn_candidate_pay_rate', true);
                if ($school_rate <= 0 && !empty($request['school_charge_rate'])) {
                    $school_rate = (float) $request['school_charge_rate'];
                }
                if ($candidate_pay <= 0 && !empty($request['candidate_pay_rate'])) {
                    $candidate_pay = (float) $request['candidate_pay_rate'];
                }
                if ($school_rate <= 0 || $candidate_pay <= 0) {
                    $result['skipped_count']++;
                    $result['errors'][] = "Booking #{$booking_id} skipped: missing rate values.";
                    continue;
                }
                $this->upsert_booking_rates(
                    $booking_id,
                    $request_id,
                    (string) ($context['role_key'] ?? 'default'),
                    (string) ($context['region_key'] ?? 'default'),
                    $school_rate,
                    $candidate_pay,
                    0,
                    'System Health safe fix: create booking rate row'
                );
                $after = $this->get_booking_rate_row($booking_id);
                $this->insert_system_fix_log(
                    'bookings_missing_rate_row',
                    'booking',
                    $booking_id,
                    [
                        'status' => 'success',
                        'summary' => 'Created missing booking rate row via guardrail evaluator.',
                    ],
                    ['rate_row_exists' => 0],
                    [
                        'rate_row_exists' => !empty($after) ? 1 : 0,
                        'guardrail_status' => (string) ($after['guardrail_status'] ?? ''),
                    ]
                );
                $result['fixed_count']++;
            } catch (Throwable $e) {
                $result['errors'][] = "Booking #{$booking_id} error: " . $e->getMessage();
            }
        }
        return $result;
    }

    private function apply_system_health_fix_booking_rate_row_missing_status($items) {
        $result = ['fixed_count' => 0, 'skipped_count' => 0, 'errors' => []];
        foreach ((array) $items as $item) {
            $booking_id = (int) ($item['entity_id'] ?? 0);
            if ($booking_id < 1) {
                $result['skipped_count']++;
                continue;
            }
            try {
                $before = $this->get_booking_rate_row($booking_id);
                if (empty($before)) {
                    $result['skipped_count']++;
                    continue;
                }
                $request_id = !empty($before['request_id']) ? (int) $before['request_id'] : (int) get_post_meta($booking_id, 'cmn_request_id', true);
                $request = $request_id > 0 ? (array) $this->get_candidate_request_by_id($request_id) : [];
                $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
                $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
                $context = $this->resolve_rate_context($candidate_id, $school_id, $request, $booking_id);
                $school_rate = isset($before['school_charge_rate']) ? (float) $before['school_charge_rate'] : 0.0;
                $candidate_pay = isset($before['candidate_pay_rate']) ? (float) $before['candidate_pay_rate'] : 0.0;
                if ($school_rate <= 0 || $candidate_pay <= 0) {
                    $result['skipped_count']++;
                    $result['errors'][] = "Booking #{$booking_id} skipped: cannot recompute status without rates.";
                    continue;
                }
                $this->upsert_booking_rates(
                    $booking_id,
                    $request_id,
                    (string) ($before['role_key'] ?? ($context['role_key'] ?? 'default')),
                    (string) ($before['region_key'] ?? ($context['region_key'] ?? 'default')),
                    $school_rate,
                    $candidate_pay,
                    !empty($before['override_flag']) ? 1 : 0,
                    !empty($before['override_reason']) ? (string) $before['override_reason'] : 'System Health safe fix: recompute guardrail status'
                );
                $after = $this->get_booking_rate_row($booking_id);
                $this->insert_system_fix_log(
                    'booking_rate_row_missing_status',
                    'booking',
                    $booking_id,
                    [
                        'status' => 'success',
                        'summary' => 'Recomputed missing guardrail status on booking rate row.',
                    ],
                    [
                        'guardrail_status' => (string) ($before['guardrail_status'] ?? ''),
                    ],
                    [
                        'guardrail_status' => (string) ($after['guardrail_status'] ?? ''),
                    ]
                );
                $result['fixed_count']++;
            } catch (Throwable $e) {
                $result['errors'][] = "Booking #{$booking_id} error: " . $e->getMessage();
            }
        }
        return $result;
    }

    private function apply_system_health_fix_orphan_contacts($items) {
        $result = ['fixed_count' => 0, 'skipped_count' => 0, 'errors' => []];
        foreach ((array) $items as $item) {
            $contact_id = (int) ($item['entity_id'] ?? 0);
            if ($contact_id < 1) {
                $result['skipped_count']++;
                continue;
            }
            try {
                $domain = strtolower(trim((string) ($item['contact_email_domain'] ?? '')));
                if ($domain === '') {
                    $result['skipped_count']++;
                    continue;
                }
                $matches = get_posts([
                    'post_type' => 'cmn_school',
                    'post_status' => ['publish', 'pending', 'draft', 'future', 'private'],
                    'fields' => 'ids',
                    'posts_per_page' => 3,
                    'meta_query' => [[
                        'key' => 'cmn_school_email_domain',
                        'value' => $domain,
                        'compare' => '=',
                    ]],
                ]);
                $matches = array_values(array_filter(array_map('intval', (array) $matches)));
                if (count($matches) !== 1) {
                    $result['skipped_count']++;
                    continue;
                }
                $school_post_id = (int) $matches[0];
                $legacy_before = (int) get_post_meta($contact_id, 'cmn_contact_school_id', true);
                $this->link_contact_to_school($contact_id, $domain, true);
                update_post_meta($contact_id, 'cmn_contact_school_id', $school_post_id);
                $this->insert_system_fix_log(
                    'orphan_contacts',
                    'contact',
                    $contact_id,
                    [
                        'status' => 'success',
                        'summary' => 'Linked orphan contact to school using exact email domain match.',
                    ],
                    [
                        'cmn_contact_school_id' => $legacy_before,
                        'domain' => $domain,
                    ],
                    [
                        'cmn_contact_school_id' => $school_post_id,
                        'domain' => $domain,
                    ]
                );
                $result['fixed_count']++;
            } catch (Throwable $e) {
                $result['errors'][] = "Contact #{$contact_id} error: " . $e->getMessage();
            }
        }
        return $result;
    }

    private function apply_system_health_fix_candidate_missing_profile_fields($items) {
        $result = ['fixed_count' => 0, 'skipped_count' => 0, 'errors' => []];
        foreach ((array) $items as $item) {
            $candidate_id = (int) ($item['entity_id'] ?? 0);
            if ($candidate_id < 1) {
                $result['skipped_count']++;
                continue;
            }
            try {
                $before_driving = strtolower(trim((string) get_post_meta($candidate_id, 'cmn_driving_licence', true)));
                $before_car = strtolower(trim((string) get_post_meta($candidate_id, 'cmn_car_owner', true)));
                $legacy_drives = $this->normalize_yes_no_value((string) ($item['legacy_drives'] ?? get_post_meta($candidate_id, 'cmn_drives', true)));
                $legacy_has_car = $this->normalize_yes_no_value((string) ($item['legacy_has_car'] ?? get_post_meta($candidate_id, 'cmn_has_car', true)));
                $changed = false;
                if ($before_driving === '' && $legacy_drives !== '') {
                    update_post_meta($candidate_id, 'cmn_driving_licence', $legacy_drives);
                    $before_driving = $legacy_drives;
                    $changed = true;
                }
                if ($before_car === '' && $legacy_has_car !== '') {
                    update_post_meta($candidate_id, 'cmn_car_owner', $legacy_has_car);
                    $before_car = $legacy_has_car;
                    $changed = true;
                }
                if (!$changed) {
                    $result['skipped_count']++;
                    continue;
                }
                $this->insert_system_fix_log(
                    'candidate_missing_profile_fields',
                    'candidate',
                    $candidate_id,
                    [
                        'status' => 'success',
                        'summary' => 'Copied legacy registration driving/car values into candidate profile fields.',
                    ],
                    [],
                    [
                        'cmn_driving_licence' => $before_driving,
                        'cmn_car_owner' => $before_car,
                    ]
                );
                $result['fixed_count']++;
            } catch (Throwable $e) {
                $result['errors'][] = "Candidate #{$candidate_id} error: " . $e->getMessage();
            }
        }
        return $result;
    }

    private function apply_system_health_safe_issue($issue_type) {
        $issue_type = sanitize_key((string) $issue_type);
        switch ($issue_type) {
            case 'schools_missing_domain':
                return $this->apply_system_health_fix_schools_missing_domain($this->detect_system_health_schools_missing_domain(100));
            case 'bookings_missing_rate_row':
                return $this->apply_system_health_fix_bookings_missing_rate_row($this->detect_system_health_bookings_missing_rate_row(100));
            case 'booking_rate_row_missing_status':
                return $this->apply_system_health_fix_booking_rate_row_missing_status($this->detect_system_health_booking_rate_row_missing_status(100));
            case 'orphan_contacts':
                return $this->apply_system_health_fix_orphan_contacts($this->detect_system_health_orphan_contacts(100));
            case 'candidate_missing_profile_fields':
                return $this->apply_system_health_fix_candidate_missing_profile_fields($this->detect_system_health_candidate_missing_profile_fields(100));
        }
        return ['fixed_count' => 0, 'skipped_count' => 0, 'errors' => ['Unsupported issue type.']];
    }

    private function get_system_health_last_apply_all_result() {
        $raw = get_option('cmn_system_health_last_apply_all_result', '');
        if (is_array($raw)) {
            return $raw;
        }
        if (!is_string($raw) || $raw === '') {
            return [];
        }
        $decoded = json_decode($raw, true);
        return is_array($decoded) ? $decoded : [];
    }

    public function handle_system_health_apply_all_safe_fixes() {
        if (!check_ajax_referer('cmn_system_health', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_admin_user()) {
            wp_send_json_error(['message' => 'Admin only.'], 403);
        }
        $user_id = get_current_user_id();
        $lock_key = 'cmn_system_health_apply_all_lock_' . $user_id;
        if (get_transient($lock_key)) {
            wp_send_json_error(['message' => 'Please wait before running all safe fixes again.'], 429);
        }
        set_transient($lock_key, 1, 60);

        $order = [
            'schools_missing_domain',
            'bookings_missing_rate_row',
            'booking_rate_row_missing_status',
            'orphan_contacts',
            'candidate_missing_profile_fields',
        ];
        $totals_by_issue = [];
        $total_fixed = 0;
        $total_skipped = 0;
        $total_errors = 0;
        foreach ($order as $issue_type) {
            try {
                $result = $this->apply_system_health_safe_issue($issue_type);
            } catch (Throwable $e) {
                $result = [
                    'fixed_count' => 0,
                    'skipped_count' => 0,
                    'errors' => [$e->getMessage()],
                ];
            }
            $fixed = (int) ($result['fixed_count'] ?? 0);
            $skipped = (int) ($result['skipped_count'] ?? 0);
            $errors = array_values(array_filter(array_map('strval', (array) ($result['errors'] ?? []))));
            $totals_by_issue[$issue_type] = [
                'fixed_count' => $fixed,
                'skipped_count' => $skipped,
                'errors' => $errors,
            ];
            $total_fixed += $fixed;
            $total_skipped += $skipped;
            $total_errors += count($errors);
        }

        $summary = [
            'performed_at' => current_time('mysql'),
            'performed_by' => $user_id,
            'totals_by_issue' => $totals_by_issue,
            'total_fixed' => $total_fixed,
            'total_skipped' => $total_skipped,
            'total_errors' => $total_errors,
        ];
        update_option('cmn_system_health_last_apply_all_result', wp_json_encode($summary), false);

        wp_send_json_success([
            'message' => 'Safe fixes completed.',
            'result' => $summary,
        ]);
    }

