    public function render_candidate_verify_shortcode() {
        $user_id = isset($_GET['uid']) ? intval($_GET['uid']) : 0;
        $token = isset($_GET['token']) ? sanitize_text_field(wp_unslash($_GET['token'])) : '';
        $login = sanitize_text_field($_GET['login'] ?? '');
        $key = sanitize_text_field($_GET['key'] ?? '');
        $verification = ['success' => false, 'message' => 'This verification link is invalid or has expired.'];
        if ($user_id && $token !== '') {
            $verification = $this->verify_candidate_email_token($user_id, $token);
        }
        $set_password_url = '';
        if ($user_id) {
            $user = get_user_by('id', $user_id);
            if ($user instanceof WP_User) {
                $key_for_user = get_password_reset_key($user);
                if (!is_wp_error($key_for_user)) {
                    $set_password_url = $this->get_portal_reset_url($user->user_login, $key_for_user);
                }
            }
        }
        if ($login && $key) {
            $set_password_url = add_query_arg([
                'view' => 'candidate-verify',
                'uid' => $user_id,
                'token' => rawurlencode($token),
                'login' => rawurlencode($login),
                'key' => rawurlencode($key),
            ], $this->get_portal_base_url());
        }
        ob_start();
        ?>
        <section class="cmn-portal cmn-portal-auth">
            <div class="cmn-panel-card cmn-auth-card">
                <div class="cmn-auth-heading">
                    <span class="cmn-auth-brand">CoverMeNow <span>ONE</span></span>
                    <h2>Candidate Verification</h2>
                </div>
                <div class="<?php echo $verification['success'] ? 'cmn-register-success' : 'cmn-register-error'; ?>">
                    <?php echo esc_html($verification['message']); ?>
                </div>
                <?php if (!$verification['success']) : ?>
                    <a class="cmn-primary cmn-button-link" href="<?php echo esc_url($this->get_portal_forgot_url()); ?>">Resend verification email</a>
                <?php endif; ?>
                <?php if ($verification['success'] && $set_password_url && !$login && !$key) : ?>
                    <a class="cmn-primary cmn-button-link" href="<?php echo esc_url($set_password_url); ?>">Set password</a>
                <?php endif; ?>
                <?php if ($login && $key) : ?>
                    <?php
                    $checked_user = check_password_reset_key($key, $login);
                    $is_valid = !is_wp_error($checked_user);
                    ?>
                    <?php if (!$is_valid) : ?>
                        <div class="cmn-register-error">This password link is invalid or has expired.</div>
                        <a class="cmn-ghost cmn-button-link" href="<?php echo esc_url($this->get_portal_forgot_url()); ?>">Request a new link</a>
                    <?php else : ?>
                        <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-form">
                            <?php wp_nonce_field('cmn_portal_reset_password', 'cmn_portal_reset_password_nonce'); ?>
                            <input type="hidden" name="action" value="cmn_portal_reset_password">
                            <input type="hidden" name="login" value="<?php echo esc_attr($login); ?>">
                            <input type="hidden" name="key" value="<?php echo esc_attr($key); ?>">
                            <label>New password
                                <input type="password" name="pass1" required>
                            </label>
                            <label>Confirm password
                                <input type="password" name="pass2" required>
                            </label>
                            <p class="cmn-muted-small">Password must be at least 10 characters.</p>
                            <button class="cmn-primary" type="submit">Save password</button>
                        </form>
                    <?php endif; ?>
                <?php endif; ?>
                <a class="cmn-ghost cmn-button-link" href="<?php echo esc_url($this->get_portal_base_url()); ?>">Back to portal</a>
            </div>
        </section>
        <?php
        return ob_get_clean();
    }

    public function render_portal_shortcode() {
        $preview = isset($_GET['as']) ? sanitize_text_field($_GET['as']) : '';
        if ($preview && $this->can_preview_dashboards()) {
            if ($preview === 'candidate') {
                return $this->render_candidate_dashboard_shortcode();
            }
            if ($preview === 'school') {
                return $this->render_school_dashboard_shortcode();
            }
        }

        $view = isset($_GET['view']) ? sanitize_text_field($_GET['view']) : '';
        if ($view === 'logout') {
            if (is_user_logged_in()) {
                wp_logout();
            }
            $_GET['view'] = 'login';
            unset($_GET['candidate'], $_GET['school'], $_GET['cmn_tab']);
            return $this->render_login_shortcode(true);
        }
        $cmn_tab = isset($_GET['cmn_tab']) ? sanitize_key((string) wp_unslash($_GET['cmn_tab'])) : '';
        $training_console = isset($_GET['cmn_training_console']) ? sanitize_key((string) wp_unslash($_GET['cmn_training_console'])) : '';
        if ($training_console === '1') {
            if (!is_user_logged_in()) {
                return $this->render_login_shortcode(true);
            }
            return $this->render_training_console_tab();
        }
        if ($view === 'register-school') {
            return $this->render_register_school_shortcode();
        }
        if ($view === 'register-candidate') {
            return $this->render_register_candidate_shortcode();
        }
        if ($view === 'candidate-verify') {
            return $this->render_candidate_verify_shortcode();
        }
        if ($view === 'candidate-settings') {
            if (!is_user_logged_in()) {
                return $this->render_login_shortcode(true);
            }
            if (!$this->is_candidate_user()) {
                return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>This section is available to candidates only.</p></div></section>';
            }
            $_GET['candidate'] = 'settings';
            return $this->render_candidate_dashboard_shortcode();
        }
        if (in_array($view, ['candidate-finance', 'candidate_finance'], true)) {
            if (!is_user_logged_in()) {
                return $this->render_login_shortcode(true);
            }
            if (!$this->is_candidate_user()) {
                return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>This section is available to candidates only.</p></div></section>';
            }
            if (function_exists('cmn_require_ability')) {
                $ability_check = cmn_require_ability('finance.view_self', ['candidate_user_id' => (int) get_current_user_id()]);
                if (is_wp_error($ability_check)) {
                    return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access denied</h3><p>You do not have permission to access this page.</p></div></section>';
                }
            }
            $_GET['candidate'] = 'candidate_finance';
            $_GET['cmn_tab'] = 'candidate_finance';
            return $this->render_candidate_dashboard_shortcode();
        }
        if (in_array($view, ['candidate-rewards', 'candidate_rewards', 'candidate-rewards-admin', 'candidate_rewards_admin'], true)) {
            if (!is_user_logged_in()) {
                return $this->render_login_shortcode(true);
            }
            if ($this->is_admin_user() || $this->is_staff_role()) {
                return $this->render_staff_candidate_rewards_shortcode();
            }
            if (!$this->is_candidate_user() && !$this->can_preview_dashboards()) {
                return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>This section is available to candidates and staff/admin only.</p></div></section>';
            }
            $_GET['candidate'] = 'rewards';
            return $this->render_candidate_dashboard_shortcode();
        }
        if (!is_user_logged_in()) {
            $ticket_id = isset($_GET['ticket_id']) ? (int) $_GET['ticket_id'] : 0;
            if ($ticket_id > 0 && (($view === 'support') || (isset($_GET['candidate']) && $_GET['candidate'] === 'support') || (isset($_GET['school']) && $_GET['school'] === 'support'))) {
                $_GET['view'] = 'login';
                $_GET['redirect_to'] = esc_url_raw($this->get_current_url());
                return $this->render_login_shortcode(true);
            }
            if ($view === 'login') {
                return $this->render_login_shortcode(true);
            }
            if ($view === 'forgot-password') {
                return $this->render_portal_forgot_password_shortcode();
            }
            if ($view === 'candidate-verify') {
                return $this->render_candidate_verify_shortcode();
            }
            if ($view === 'reset-password' || $view === 'set-password') {
                return $this->render_portal_reset_password_shortcode();
            }
            return $this->render_login_shortcode(true);
        }
        if ($cmn_tab === 'candidate_finance') {
            $current_user_id = (int) get_current_user_id();
            if (!$this->is_candidate_user($current_user_id)) {
                return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access denied</h3><p>You do not have permission to access this page.</p></div></section>';
            }
            if (function_exists('cmn_require_ability')) {
                $ability_check = cmn_require_ability('finance.view_self', ['candidate_user_id' => $current_user_id]);
                if (is_wp_error($ability_check)) {
                    return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access denied</h3><p>You do not have permission to access this page.</p></div></section>';
                }
            }
            $_GET['candidate'] = 'candidate_finance';
            return $this->render_candidate_dashboard_shortcode();
        }
        if ($cmn_tab === 'staff_payroll') {
            $current_user_id = (int) get_current_user_id();
            $is_staff_or_admin = $this->is_admin_user($current_user_id) || $this->is_staff_role($current_user_id);
            if (!$is_staff_or_admin) {
                return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access denied</h3><p>You do not have permission to access this page.</p></div></section>';
            }
            if (function_exists('cmn_require_ability')) {
                $ability_check = cmn_require_ability('payroll.view_any', ['actor_user_id' => $current_user_id]);
                if (is_wp_error($ability_check)) {
                    return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access denied</h3><p>You do not have permission to access this page.</p></div></section>';
                }
            }
            return $this->render_staff_payroll_tab();
        }
        $this->touch_staff_presence();
        if ($view === 'clients') {
            $_GET['cmn_status'] = 'client';
            return $this->render_staff_schools_shortcode();
        }
        if ($view === 'leads') {
            $_GET['cmn_status'] = 'lead';
            return $this->render_staff_schools_shortcode();
        }
        if ($view === 'schools') {
            return $this->render_staff_schools_shortcode();
        }
        if ($view === 'candidates') {
            return $this->render_staff_candidates_shortcode();
        }
        if ($view === 'compliance-review' || $view === 'compliance_review') {
            $_GET['cmn_doc_review'] = 'pending';
            return $this->render_staff_candidates_shortcode();
        }
        if ($view === 'cv-converter' || $view === 'cv_converter') {
            return $this->render_cmn_cv_converter_view();
        }
        if ($view === 'cv_converter_app') {
            return $this->render_cmn_cv_converter_app_view();
        }
        if ($view === 'marketing') {
            return $this->render_staff_marketing_shortcode();
        }
        if ($view === 'requests') {
            return $this->render_staff_requests_shortcode();
        }
        if ($view === 'school-requests' || $view === 'school_requests') {
            return $this->render_staff_school_requests_shortcode();
        }
        if ($view === 'automation') {
            return $this->render_staff_automation_console_shortcode();
        }
        if ($view === 'rate-guardrails' || $view === 'rate_guardrails') {
            return $this->render_staff_rate_guardrails_shortcode();
        }
        if ($view === 'war-room' || $view === 'war_room') {
            return $this->render_staff_war_room_shortcode();
        }
        if ($view === 'broadcast') {
            return $this->render_staff_broadcast_shortcode();
        }
        if ($view === 'audit') {
            return $this->render_staff_audit_shortcode();
        }
        if ($view === 'bookings') {
            return $this->render_staff_bookings_shortcode();
        }
        if ($view === 'analytics') {
            return $this->render_staff_analytics_shortcode();
        }
        if ($view === 'system-health' || $view === 'system_health') {
            return $this->render_staff_system_health_shortcode();
        }
        if ($view === 'data-integrity' || $view === 'data_integrity') {
            return $this->render_staff_data_integrity_auditor_shortcode();
        }
        if ($view === 'contacts') {
            return $this->render_staff_contacts_shortcode();
        }
        if ($view === 'settings') {
            return $this->render_staff_settings_shortcode();
        }
        if ($view === 'email-centre' || $view === 'email_centre') {
            return $this->render_staff_email_centre_shortcode();
        }
        if ($view === 'finance-overview' || $view === 'finance_overview') {
            return $this->render_staff_finance_overview_shortcode();
        }
        if ($view === 'partner-credit-ledger' || $view === 'partner_credit_ledger') {
            return $this->render_staff_partner_credit_ledger_shortcode();
        }
        if ($view === 'school-partner-admin' || $view === 'school_partner_admin') {
            return $this->render_staff_school_partner_admin_shortcode();
        }
        if ($view === 'invoicing') {
            return $this->render_staff_invoicing_shortcode();
        }
        if ($view === 'partner-programme' || $view === 'partner_programme') {
            return $this->render_staff_partner_programme_shortcode();
        }
        if ($view === 'support') {
            if ($this->is_candidate_user()) {
                $_GET['candidate'] = 'support';
                return $this->render_candidate_dashboard_shortcode();
            }
            if ($this->is_school_user()) {
                $_GET['school'] = 'support';
                return $this->render_school_dashboard_shortcode();
            }
            return $this->render_staff_support_shortcode();
        }
        if ($view === 'feedback-insights' || $view === 'feedback_insights') {
            return $this->render_staff_feedback_insights_shortcode();
        }
        if (in_array($view, ['staff-lounge', 'staff_lounge', 'chat', 'internal-chat', 'messages'], true)) {
            if (!$this->is_staff_user()) {
                return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>Staff Lounge is available to staff, account managers, and admins only.</p></div></section>';
            }
            return $this->render_staff_lounge_shortcode();
        }
        if ($view === 'staff') {
            return $this->render_staff_staff_shortcode();
        }

        $user = wp_get_current_user();
        if (in_array('cmn_admin', (array) $user->roles, true)
            || in_array('cmn_staff', (array) $user->roles, true)
            || in_array('cmn_account_manager', (array) $user->roles, true)
            || in_array('administrator', (array) $user->roles, true)) {
            return $this->render_staff_dashboard_shortcode();
        }
        if (in_array('cmn_school_manager', (array) $user->roles, true) || in_array('cmn_school_staff', (array) $user->roles, true)) {
            return $this->render_school_dashboard_shortcode();
        }
        if (in_array('cmn_candidate', (array) $user->roles, true)) {
            return $this->render_candidate_dashboard_shortcode();
        }
        if (in_array('cmn_candidate_pending', (array) $user->roles, true)) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Email verification required</h3><p>Please verify your email address to access your profile. Check your inbox for the verification link.</p></div></section>';
        }

        return $this->render_staff_dashboard_shortcode();
    }

    public function render_staff_automation_console_shortcode() {
        $user_id = (int) get_current_user_id();
        if (!$this->is_staff_user($user_id) || !$this->can_manage_automation($user_id)) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access denied</h3><p>You do not have permission to access this page.</p></div></section>';
        }

        $tab = sanitize_key((string) ($_GET['cmn_automation_tab'] ?? 'rules'));
        $tab_to_active = [
            'rules' => 'automation_rule_builder',
            'performance' => 'automation_rule_performance',
            'trigger_logs' => 'automation_trigger_logs',
            'failed_actions' => 'automation_failed_actions',
            'scheduled_actions' => 'automation_scheduled_actions',
            'broadcast_logic' => 'automation_broadcast_logic',
        ];
        if (!isset($tab_to_active[$tab])) {
            $tab = 'rules';
        }
        $_GET['cmn_automation_tab'] = $tab;

        ob_start();
        $this->render_automation_page();
        $inner_html = ob_get_clean();
        return $this->render_staff_shell($tab_to_active[$tab], $inner_html);
    }

    public function render_staff_dashboard_shortcode() {
        global $wpdb;

        $open_support_count = $this->count_open_support_tickets();
        $new_requests_count = $this->count_new_booking_requests_for_dashboard();
        $new_school_requests_count = $this->count_pending_school_requests();
        $pending_docs_count = count($this->get_candidates_awaiting_document_review(600));
        $new_candidate_regs_count = $this->count_recent_candidate_registrations(24);
        $bookings_at_risk_count = $this->count_bookings_at_risk_low_margin();
        $todays_bookings_count = $this->count_bookings_today();
        $alert_missing_dbs = $this->count_missing_dbs();
        $alert_missing_id = $this->count_missing_id();
        $alert_availability = 0;
        $feedback_overview = $this->get_booking_feedback_analytics('all', 30);
        $alert_low_feedback = (int) ($feedback_overview['totals']['low_count'] ?? 0);
        $portal_url = $this->get_portal_base_url();
        $user_id = get_current_user_id();
        $can_broadcast = $this->is_admin_user($user_id);
        $can_manage_automation = $this->can_manage_automation($user_id);
        $automation_counts = ['active_rules' => 0, 'runs_today' => 0, 'failures_today' => 0];
        if ($can_manage_automation) {
            $automation_counts = (array) $this->get_automation_engine()->get_overview_counts();
        }
        $automation_failures = (int) ($automation_counts['failures_today'] ?? 0);
        $automation_console_url = $can_manage_automation
            ? $this->get_automation_console_url('rules')
            : add_query_arg(['view' => 'system_health'], $portal_url);

        $active_schools_count = $this->count_by_status('cmn_school', 'client');
        if ($active_schools_count < 1) {
            $active_schools_count = $this->count_total_posts('cmn_school');
        }
        $active_candidates_count = $this->count_total_posts('cmn_candidate');

        $open_bookings_count = $this->count_bookings_by_status('open');
        if ($open_bookings_count < 1) {
            $open_bookings_count = $this->count_bookings_by_status('requested') + $this->count_bookings_by_status('pending');
        }
        if ($open_bookings_count < 1) {
            $open_bookings_count = $new_requests_count;
        }

        $week_reference = function_exists('cmn_now')
            ? cmn_now()->setTimezone(wp_timezone())
            : new DateTimeImmutable('now', wp_timezone());
        $week_start = $week_reference->modify('monday this week')->setTime(0, 0, 0);
        $week_end = $week_start->modify('+6 days')->setTime(23, 59, 59);
        $week_label = date_i18n('M j', $week_start->getTimestamp()) . ' - ' . date_i18n('M j', $week_end->getTimestamp());

        $week_revenue = 0.0;
        $invoices_table = $this->get_invoices_table();
        if ($this->candidate_rewards_table_exists($invoices_table)) {
            $week_revenue = (float) $wpdb->get_var($wpdb->prepare(
                "SELECT COALESCE(SUM(total), 0)
                 FROM {$invoices_table}
                 WHERE status <> %s
                   AND period_start <= %s
                   AND period_end >= %s",
                'void',
                $week_end->format('Y-m-d'),
                $week_start->format('Y-m-d')
            ));
        }
        $week_revenue = round(max(0, $week_revenue), 2);

        $audit_events_today = 0;
        $audit_table = $this->get_audit_log_table();
        if ($this->candidate_rewards_table_exists($audit_table)) {
            $audit_events_today = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$audit_table} WHERE DATE(created_at) = %s",
                current_time('Y-m-d')
            ));
        }

        $escalations_count = $bookings_at_risk_count + $alert_low_feedback;
        $format_money = static function ($value) {
            return 'GBP ' . number_format((float) $value, 2);
        };

        $business_health_cards = [
            [
                'label' => "Today's bookings",
                'value' => number_format((int) $todays_bookings_count),
                'subtext' => 'Confirmed and pending for today.',
                'url' => add_query_arg(['view' => 'bookings'], $portal_url),
            ],
            [
                'label' => "This week's revenue",
                'value' => $format_money($week_revenue),
                'subtext' => 'Invoice total in week ' . $week_label . '.',
                'url' => add_query_arg(['view' => 'finance-overview'], $portal_url),
            ],
            [
                'label' => 'Active schools',
                'value' => number_format((int) $active_schools_count),
                'subtext' => 'Client schools active in the network.',
                'url' => add_query_arg(['view' => 'schools', 'cmn_bucket' => 'clients', 'cmn_status' => 'client'], $portal_url),
            ],
            [
                'label' => 'Active candidates',
                'value' => number_format((int) $active_candidates_count),
                'subtext' => 'Candidate profiles currently in pool.',
                'url' => add_query_arg(['view' => 'candidates'], $portal_url),
            ],
            [
                'label' => 'Open bookings',
                'value' => number_format((int) $open_bookings_count),
                'subtext' => 'Requests currently awaiting closure.',
                'url' => add_query_arg(['view' => 'requests', 'cmn_status' => 'requested'], $portal_url),
            ],
        ];

        $risk_cards = [
            [
                'label' => 'Missing DBS',
                'count' => (int) $alert_missing_dbs,
                'detail' => 'Candidates missing DBS verification.',
                'severity' => $alert_missing_dbs > 20 ? 'high' : ($alert_missing_dbs > 0 ? 'medium' : 'low'),
                'url' => add_query_arg(['view' => 'compliance-review'], $portal_url),
            ],
            [
                'label' => 'Missing ID',
                'count' => (int) $alert_missing_id,
                'detail' => 'Candidates missing valid photo ID.',
                'severity' => $alert_missing_id > 20 ? 'high' : ($alert_missing_id > 0 ? 'medium' : 'low'),
                'url' => add_query_arg(['view' => 'compliance-review'], $portal_url),
            ],
            [
                'label' => 'Cancelled availability',
                'count' => (int) $alert_availability,
                'detail' => 'Availability withdrawals to review.',
                'severity' => $alert_availability > 0 ? 'medium' : 'low',
                'url' => add_query_arg(['view' => 'requests', 'cmn_status' => 'cancelled'], $portal_url),
            ],
            [
                'label' => 'Bookings at risk',
                'count' => (int) $bookings_at_risk_count,
                'detail' => 'Low margin bookings requiring action.',
                'severity' => $bookings_at_risk_count > 0 ? 'high' : 'low',
                'url' => add_query_arg(['view' => 'rate-guardrails', 'cmn_risk_only' => 1], $portal_url),
            ],
            [
                'label' => 'Failed automations',
                'count' => (int) $automation_failures,
                'detail' => $can_manage_automation ? 'Automation failures detected today.' : 'Automation console access restricted.',
                'severity' => $automation_failures > 0 ? 'high' : ($can_manage_automation ? 'low' : 'medium'),
                'url' => $automation_console_url,
            ],
        ];

        $growth_cards = [
            [
                'label' => 'Emergency broadcasts',
                'value' => $can_broadcast ? 'Ready' : 'Admin',
                'detail' => $can_broadcast ? 'Send urgent updates in one action.' : 'Admin access required to broadcast.',
                'url' => $can_broadcast ? add_query_arg(['view' => 'broadcast'], $portal_url) : add_query_arg(['view' => 'support'], $portal_url),
                'urgency' => 'urgent',
            ],
            [
                'label' => 'Marketing campaigns',
                'value' => 'Open',
                'detail' => 'Create and launch outbound campaigns.',
                'url' => add_query_arg(['view' => 'marketing', 'marketing_tab' => 'campaigns'], $portal_url),
                'urgency' => 'neutral',
            ],
            [
                'label' => 'Saved lists',
                'value' => 'Open',
                'detail' => 'Manage reusable marketing audiences.',
                'url' => add_query_arg(['view' => 'marketing', 'marketing_tab' => 'lists'], $portal_url),
                'urgency' => 'neutral',
            ],
            [
                'label' => 'Referral activity',
                'value' => number_format((int) $new_school_requests_count),
                'detail' => 'New school requests in current pipeline.',
                'url' => add_query_arg(['view' => 'school-requests', 'status' => 'all'], $portal_url),
                'urgency' => 'neutral',
            ],
            [
                'label' => 'Automation rules running today',
                'value' => number_format((int) ($automation_counts['runs_today'] ?? 0)),
                'detail' => $can_manage_automation ? 'Rule executions recorded today.' : 'Automation overview restricted by role.',
                'url' => $automation_console_url,
                'urgency' => 'neutral',
            ],
        ];

        $system_cards = [
            [
                'label' => 'Failed actions',
                'count' => (int) $automation_failures,
                'detail' => 'Automation actions failed today.',
                'status' => $automation_failures > 0 ? 'red' : 'green',
                'url' => $automation_console_url,
            ],
            [
                'label' => 'Audit logs',
                'count' => (int) $audit_events_today,
                'detail' => 'Audit events captured today.',
                'status' => $audit_events_today > 0 ? 'green' : 'amber',
                'url' => add_query_arg(['view' => 'audit'], $portal_url),
            ],
            [
                'label' => 'Automation health',
                'count' => (int) ($automation_counts['active_rules'] ?? 0),
                'detail' => $can_manage_automation ? 'Active rules currently enabled.' : 'Automation visibility restricted.',
                'status' => $automation_failures > 0 ? 'red' : ((int) ($automation_counts['active_rules'] ?? 0) > 0 ? 'green' : 'amber'),
                'url' => $automation_console_url,
            ],
            [
                'label' => 'Support tickets open',
                'count' => (int) $open_support_count,
                'detail' => 'Open tickets across support queues.',
                'status' => $open_support_count > 24 ? 'red' : ($open_support_count > 10 ? 'amber' : 'green'),
                'url' => add_query_arg(['view' => 'support', 'support_filter' => 'open'], $portal_url),
            ],
            [
                'label' => 'Escalations',
                'count' => (int) $escalations_count,
                'detail' => 'Bookings at risk and low feedback alerts.',
                'status' => $escalations_count > 10 ? 'red' : ($escalations_count > 0 ? 'amber' : 'green'),
                'url' => add_query_arg(['view' => 'feedback-insights', 'cmn_feedback_filter' => 'at_risk_candidates'], $portal_url),
            ],
        ];

        $action_queue_items = [
            [
                'label' => 'New school requests',
                'count' => (int) $new_school_requests_count,
                'url' => add_query_arg(['view' => 'school-requests', 'status' => 'pending'], $portal_url),
                'action' => 'Review requests',
            ],
            [
                'label' => 'Documents pending review',
                'count' => (int) $pending_docs_count,
                'url' => add_query_arg(['view' => 'compliance-review'], $portal_url),
                'action' => 'Review documents',
            ],
            [
                'label' => 'New registrations (24h)',
                'count' => (int) $new_candidate_regs_count,
                'url' => add_query_arg(['view' => 'candidates'], $portal_url),
                'action' => 'View candidates',
            ],
            [
                'label' => 'Automation failures today',
                'count' => (int) $automation_failures,
                'url' => $automation_console_url,
                'action' => 'Open automation logs',
            ],
        ];

        ob_start();
        ?>
        <header class="cmn-school-header cmn-dashboard-header">
            <div class="cmn-header-row">
                <div>
                    <h2>Dashboard</h2>
                    <p>Operational control centre with live health, risk, growth, and system performance signals.</p>
                </div>
            </div>
        </header>
        <div class="cmn-exec-dashboard">
            <section class="cmn-exec-band">
                <div class="cmn-exec-band-head">
                    <div>
                        <h3>Action Queue</h3>
                        <p>Items that require attention today.</p>
                    </div>
                </div>
                <div class="cmn-exec-alert-grid">
                    <?php foreach ($action_queue_items as $queue_item) : ?>
                        <?php $queue_count = (int) ($queue_item['count'] ?? 0); ?>
                        <a class="cmn-exec-alert-card<?php echo $queue_count > 0 ? ' has-issue' : ' is-clear'; ?>" href="<?php echo esc_url((string) $queue_item['url']); ?>">
                            <div class="cmn-exec-alert-head">
                                <span class="cmn-exec-alert-label"><?php echo esc_html((string) $queue_item['label']); ?></span>
                                <span class="cmn-exec-alert-count"><?php echo esc_html(number_format($queue_count)); ?></span>
                            </div>
                            <p><?php echo esc_html((string) $queue_item['action']); ?></p>
                        </a>
                    <?php endforeach; ?>
                </div>
            </section>
            <section class="cmn-exec-band">
                <div class="cmn-exec-band-head">
                    <div>
                        <h3>Business Health</h3>
                        <p>Top-line view of live delivery and commercial activity.</p>
                    </div>
                </div>
                <div class="cmn-exec-kpi-grid">
                    <?php foreach ($business_health_cards as $card_index => $card) : ?>
                        <?php
                        $metric_tier_class = ((int) $card_index < 2) ? ' is-primary-heartbeat' : ' is-capacity-signal';
                        ?>
                        <a class="cmn-exec-kpi-card<?php echo esc_attr($metric_tier_class); ?>" href="<?php echo esc_url((string) $card['url']); ?>">
                            <span class="cmn-exec-kpi-label"><?php echo esc_html((string) $card['label']); ?></span>
                            <strong class="cmn-exec-kpi-value"><?php echo esc_html((string) $card['value']); ?></strong>
                            <span class="cmn-exec-kpi-subtext"><?php echo esc_html((string) $card['subtext']); ?></span>
