            <section class="cmn-exec-band">
                <div class="cmn-exec-band-head">
                    <div>
                        <h3>Risk &amp; Compliance</h3>
                        <p>Actionable alerts with severity signalling and direct drill-down links.</p>
                    </div>
                </div>
                <div class="cmn-exec-alert-grid">
                    <?php foreach ($risk_cards as $risk_card) : ?>
                        <?php
                        $risk_count = (int) ($risk_card['count'] ?? 0);
                        $risk_state_class = $risk_count > 0 ? ' has-issue' : ' is-clear';
                        ?>
                        <a class="cmn-exec-alert-card is-<?php echo esc_attr((string) $risk_card['severity']); ?><?php echo esc_attr($risk_state_class); ?>" href="<?php echo esc_url((string) $risk_card['url']); ?>">
                            <div class="cmn-exec-alert-head">
                                <span class="cmn-exec-alert-label"><?php echo esc_html((string) $risk_card['label']); ?></span>
                                <span class="cmn-exec-alert-count"><?php echo esc_html(number_format($risk_count)); ?></span>
                            </div>
                            <p><?php echo esc_html((string) $risk_card['detail']); ?></p>
                        </a>
                    <?php endforeach; ?>
                </div>
            </section>

            <section class="cmn-exec-band">
                <div class="cmn-exec-band-head">
                    <div>
                        <h3>Growth &amp; Outreach</h3>
                        <p>Forward delivery pipeline and engagement momentum.</p>
                    </div>
                </div>
                <div class="cmn-exec-activity-grid">
                    <?php foreach ($growth_cards as $growth_card) : ?>
                        <?php
                        $growth_urgency_class = (string) ($growth_card['urgency'] ?? 'neutral') === 'urgent'
                            ? ' is-urgent'
                            : ' is-neutral';
                        ?>
                        <a class="cmn-exec-activity-card<?php echo esc_attr($growth_urgency_class); ?>" href="<?php echo esc_url((string) $growth_card['url']); ?>">
                            <span class="cmn-exec-activity-label"><?php echo esc_html((string) $growth_card['label']); ?></span>
                            <strong class="cmn-exec-activity-value"><?php echo esc_html((string) $growth_card['value']); ?></strong>
                            <span class="cmn-exec-activity-subtext"><?php echo esc_html((string) $growth_card['detail']); ?></span>
                        </a>
                    <?php endforeach; ?>
                </div>
            </section>

            <section class="cmn-exec-band">
                <div class="cmn-exec-band-head">
                    <div>
                        <h3>System &amp; Performance</h3>
                        <p>Runtime stability, queue pressure, and audit visibility at a glance.</p>
                    </div>
                </div>
                <div class="cmn-exec-system-grid">
                    <?php foreach ($system_cards as $system_card) : ?>
                        <a class="cmn-exec-system-card" href="<?php echo esc_url((string) $system_card['url']); ?>">
                            <span class="cmn-exec-status-dot is-<?php echo esc_attr((string) $system_card['status']); ?>" aria-hidden="true"></span>
                            <div class="cmn-exec-system-body">
                                <span class="cmn-exec-system-label"><?php echo esc_html((string) $system_card['label']); ?></span>
                                <span class="cmn-exec-system-subtext"><?php echo esc_html((string) $system_card['detail']); ?></span>
                            </div>
                            <strong class="cmn-exec-system-count"><?php echo esc_html(number_format((int) $system_card['count'])); ?></strong>
                        </a>
                    <?php endforeach; ?>
                </div>
            </section>
        </div>
        <?php
        $inner = ob_get_clean();
        return $this->render_staff_shell('dashboard', $inner);
    }

    public function render_staff_schools_shortcode() {
        if (!is_user_logged_in()) {
            return $this->render_login_shortcode();
        }
        if (!$this->is_staff_user()) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>This section is available to admin staff only.</p></div></section>';
        }
        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        $school_identifier = isset($_GET['school_id']) ? sanitize_text_field($_GET['school_id']) : '';
        $requested_pid = isset($_GET['pid']) ? (int) $_GET['pid'] : 0;
        $request_bucket = isset($_GET['cmn_bucket']) ? sanitize_key((string) $_GET['cmn_bucket']) : '';
        $current_user_id = (int) get_current_user_id();
        if ($school_identifier !== '' || $requested_pid > 0) {
            error_log('[CMN_SCHOOL_VIEW] start school_id=' . $school_identifier . ' t=0');
            $req_id = 'SCHVIEW-' . wp_generate_uuid4();
            $request_started_at = microtime(true);
            $render_stage = 'request_received';
            $render_ref = '';
            $resolved_school_post_id = 0;
            $fallback_profile_html = '';
            $self = $this;
            $this->current_school_view_req_id = $req_id;
            error_log('[CMN_SCHOOL_VIEW] ' . wp_json_encode([
                'stage' => 'handler_start',
                'requested_school_id' => $school_identifier,
                'requested_pid' => $requested_pid,
                'current_user_id' => $current_user_id,
                'current_user_role' => $this->get_current_user_role(),
            ]));

            register_shutdown_function(function () use (&$render_stage, &$render_ref, $req_id, $school_identifier, &$resolved_school_post_id, $self) {
                $error = error_get_last();
                if (!$error || !in_array((int) ($error['type'] ?? 0), [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR], true)) {
                    return;
                }
                $render_ref = $render_ref !== '' ? $render_ref : ('CMN-ERR-SCHVIEW-' . gmdate('YmdHis') . '-' . substr(wp_generate_uuid4(), 0, 8));
                $payload = [
                    'req_id' => $req_id,
                    'reference' => $render_ref,
                    'stage' => (string) $render_stage,
                    'school_identifier' => (string) $school_identifier,
                    'resolved_school_post_id' => (int) $resolved_school_post_id,
                    'error_type' => (int) ($error['type'] ?? 0),
                    'error_message' => (string) ($error['message'] ?? ''),
                    'error_file' => (string) ($error['file'] ?? ''),
                    'error_line' => (int) ($error['line'] ?? 0),
                ];
                error_log('[CMN_SCHOOL_VIEW_CRASH] ' . wp_json_encode($payload));
                while (ob_get_level() > 0) {
                    ob_end_clean();
                }
                $fallback = '';
                try {
                    if ($resolved_school_post_id > 0) {
                        $fallback = (string) $self->build_school_view_fallback_profile($resolved_school_post_id, []);
                    }
                } catch (Throwable $e) {
                    $fallback = '';
                }
                echo '<section class="cmn-portal">' . $fallback . $self->build_school_view_error_card(
                    $render_ref,
                    'A system error stopped this profile from loading.',
                    $school_identifier,
                    $resolved_school_post_id
                ) . '</section>';
            });

            try {
                $this->log_school_view_event($req_id, 'request_received', [
                    'requested_school_identifier' => $school_identifier,
                    'requested_pid' => $requested_pid,
                    'cmn_bucket' => $request_bucket,
                    'current_user_id' => $current_user_id,
                    'current_user_role' => $this->get_current_user_role(),
                    'caps' => [
                        'is_admin' => $this->is_admin_user($current_user_id) ? 1 : 0,
                        'is_staff' => $this->is_staff_role($current_user_id) ? 1 : 0,
                        'is_account_manager' => $this->is_account_manager_user($current_user_id) ? 1 : 0,
                    ],
                ], $request_started_at);

                $resolve_started_at = microtime(true);
                $render_stage = 'resolve_by_pid';
                $resolved_school_post_id_candidate = (int) $this->resolve_school_identifier($school_identifier, $requested_pid);
                $resolved_by_pid = ($requested_pid > 0 && $resolved_school_post_id_candidate === (int) $requested_pid)
                    ? $resolved_school_post_id_candidate
                    : 0;
                $resolved_by_school_id = $resolved_by_pid > 0 ? 0 : $resolved_school_post_id_candidate;
                $this->log_school_view_event($req_id, 'resolve_by_pid', [
                    'requested_pid' => $requested_pid,
                    'resolved_post_id' => $resolved_by_pid,
                ], $resolve_started_at);
                $render_stage = 'resolve_by_school_id';
                $this->log_school_view_event($req_id, 'resolve_by_school_id', [
                    'requested_school_identifier' => $school_identifier,
                    'resolved_post_id' => $resolved_by_school_id,
                ], $resolve_started_at);

                $school_post_id = $resolved_by_pid ?: $resolved_by_school_id;
                $resolved_school_post_id = (int) $school_post_id;
                if (!$school_post_id) {
                    $render_stage = 'resolve_failed';
                    return $this->render_staff_shell('all_schools', $this->build_school_not_resolved_card(
                        $school_identifier,
                        $requested_pid,
                        $portal_url
                    ));
                }

                $render_stage = 'permission_check';
                $permission_granted = $this->user_can_access_school($school_post_id, $current_user_id);
                $school_record = get_post($school_post_id);
                $school_meta_snapshot = [
                    'cmn_status' => (string) get_post_meta($school_post_id, 'cmn_status', true),
                    'access_request_status' => (string) $this->get_school_access_request_status($school_post_id),
                    'cmn_account_manager_user' => (int) get_post_meta($school_post_id, 'cmn_account_manager_user', true),
                    'cmn_account_manager_user_id' => (int) get_post_meta($school_post_id, 'cmn_account_manager_user_id', true),
                    'cmn_school_id' => (string) get_post_meta($school_post_id, 'cmn_school_id', true),
                    'cmn_location' => (string) get_post_meta($school_post_id, 'cmn_location', true),
                    'cmn_postcode' => (string) get_post_meta($school_post_id, 'cmn_postcode', true),
                    'cmn_town' => (string) get_post_meta($school_post_id, 'cmn_town', true),
                    'cmn_address_line1' => (string) get_post_meta($school_post_id, 'cmn_address_line1', true),
                    'cmn_account_manager' => (string) get_post_meta($school_post_id, 'cmn_account_manager', true),
                ];
                $missing_fields = $this->get_school_profile_missing_fields($school_post_id);
                $fallback_profile_html = (string) $this->build_school_view_fallback_profile($school_post_id, $missing_fields);
                $this->log_school_view_event($req_id, 'meta_presence_check', [
                    'resolved_school_post_id' => (int) $school_post_id,
                    'school_record_found' => $school_record instanceof WP_Post ? 1 : 0,
                    'school_record_type' => $school_record instanceof WP_Post ? (string) $school_record->post_type : '',
                    'permission_granted' => $permission_granted ? 1 : 0,
                    'missing_fields' => $missing_fields,
                    'school_meta' => $school_meta_snapshot,
                    'meta_presence' => [
                        'status' => $school_meta_snapshot['cmn_status'] !== '' ? 1 : 0,
                        'postcode' => $school_meta_snapshot['cmn_postcode'] !== '' ? 1 : 0,
                        'town' => $school_meta_snapshot['cmn_town'] !== '' ? 1 : 0,
                        'address_line1' => $school_meta_snapshot['cmn_address_line1'] !== '' ? 1 : 0,
                        'account_manager' => $school_meta_snapshot['cmn_account_manager'] !== '' ? 1 : 0,
                    ],
                ], $request_started_at);

                if (!$permission_granted) {
                    $this->log_school_view_event($req_id, 'permission_denied', [
                        'resolved_school_post_id' => (int) $school_post_id,
                        'current_user_id' => $current_user_id,
                    ], $request_started_at);
                    return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>You do not have access to this school.</p></div></section>';
                }

                $bucket_for_profile = $request_bucket;
                $status_for_profile = isset($_GET['cmn_status']) ? sanitize_key((string) $_GET['cmn_status']) : '';
                $active_profile_nav = ($bucket_for_profile === 'sales' || $status_for_profile === 'lead' || $status_for_profile === 'needs_attention') ? 'schools_leads' : 'all_schools';

                $render_stage = 'render_start';
                $this->log_school_view_event($req_id, 'render_start', [
                    'resolved_school_post_id' => (int) $school_post_id,
                    'template' => 'render_frontend_school_profile',
                ], $request_started_at);

                ob_start();
                try {
                    error_log('[CMN_SCHOOL_VIEW] before_render_profile school_id=' . $school_identifier);
                    $profile_html = (string) $this->render_frontend_school_profile($school_post_id);
                    error_log('[CMN_SCHOOL_VIEW] after_render_profile school_id=' . $school_identifier);
                    $buffered = ob_get_clean();
                    $profile_html = trim($buffered . $profile_html);
                    if ($profile_html === '') {
                        $render_ref = 'CMN-ERR-SCHVIEW-' . gmdate('YmdHis') . '-' . substr(wp_generate_uuid4(), 0, 8);
                        $render_stage = 'render_empty';
                        $this->log_school_view_crash($req_id, $render_ref, [
                            'resolved_school_post_id' => (int) $school_post_id,
                            'school_identifier' => $school_identifier,
                            'reason' => 'Profile render returned empty output.',
                        ]);
                        return $this->render_staff_shell($active_profile_nav, $fallback_profile_html . $this->build_school_view_error_card(
                            $render_ref,
                            'Profile render returned empty output.',
                            $school_identifier,
                            $school_post_id
                        ));
                    }
                    $render_stage = 'render_shell';
                    $this->log_school_view_event($req_id, 'render_shell', [
                        'resolved_school_post_id' => (int) $school_post_id,
                        'template' => 'render_frontend_school_profile',
                    ], $request_started_at);
                    $shell_html = (string) $this->render_staff_shell($active_profile_nav, $profile_html);
                    if (trim($shell_html) === '') {
                        $render_ref = 'CMN-ERR-SCHVIEW-' . gmdate('YmdHis') . '-' . substr(wp_generate_uuid4(), 0, 8);
                        $render_stage = 'shell_empty';
                        $this->log_school_view_crash($req_id, $render_ref, [
                            'resolved_school_post_id' => (int) $school_post_id,
                            'school_identifier' => $school_identifier,
                            'reason' => 'Shell render returned empty output.',
                        ]);
                        return '<section class="cmn-portal">' . $fallback_profile_html . $this->build_school_view_error_card(
                            $render_ref,
                            'Shell render returned empty output.',
                            $school_identifier,
                            $school_post_id
                        ) . '</section>';
                    }
                    $render_stage = 'render_success';
                    $this->log_school_view_event($req_id, 'render_success', [
                        'resolved_school_post_id' => (int) $school_post_id,
                        'template' => 'render_frontend_school_profile',
                    ], $request_started_at);
                    return $shell_html;
                } catch (Throwable $e) {
                    if (ob_get_level() > 0) {
                        ob_end_clean();
                    }
                    $render_ref = 'CMN-ERR-SCHVIEW-' . gmdate('YmdHis') . '-' . substr(wp_generate_uuid4(), 0, 8);
                    $render_stage = 'render_exception';
                    $this->log_school_view_crash($req_id, $render_ref, [
                        'resolved_school_post_id' => (int) $school_post_id,
                        'school_identifier' => $school_identifier,
                        'error' => $e->getMessage(),
                        'trace' => $e->getTraceAsString(),
                    ]);
                    return $this->render_staff_shell($active_profile_nav, $fallback_profile_html . $this->build_school_view_error_card(
                        $render_ref,
                        'An unexpected error occurred while rendering this profile.',
                        $school_identifier,
                        $school_post_id
                    ));
                }
            } finally {
                $this->current_school_view_req_id = '';
            }
        }
        $view = isset($_GET['view']) ? sanitize_text_field($_GET['view']) : 'schools';
        $status = isset($_GET['cmn_status']) ? sanitize_text_field($_GET['cmn_status']) : '';
        $search = isset($_GET['q']) ? sanitize_text_field($_GET['q']) : '';
        if ($search === '' && isset($_GET['s'])) {
            $search = sanitize_text_field($_GET['s']);
        }
        $bucket = isset($_GET['cmn_bucket']) ? sanitize_key((string) $_GET['cmn_bucket']) : '';
        if (!in_array($bucket, ['sales', 'clients'], true)) {
            $bucket = '';
        }
        $stage = isset($_GET['cmn_stage']) ? sanitize_text_field($_GET['cmn_stage']) : '';
        $manager_id = isset($_GET['cmn_manager']) ? intval($_GET['cmn_manager']) : 0;
        $location_filter = isset($_GET['cmn_location']) ? sanitize_text_field($_GET['cmn_location']) : '';
        $lead_group_filter = isset($_GET['cmn_lead_group']) ? $this->sanitize_lead_group_slug((string) $_GET['cmn_lead_group']) : '';
        $last_activity_filter = isset($_GET['cmn_last_activity']) ? sanitize_key((string) $_GET['cmn_last_activity']) : '';
        if (!in_array($last_activity_filter, ['', 'inactive_30'], true)) {
            $last_activity_filter = '';
        }
        if ($status === '') {
            if ($view === 'clients') {
                $status = 'client';
            } elseif ($view === 'leads') {
                $status = 'lead';
            }
        }
        if ($bucket === 'clients') {
            $status = 'client';
        } elseif ($bucket === 'sales') {
            $status = 'lead';
        }
        if ($status === '') {
            $status = 'lead';
        }
        if ($status === 'all') {
            $status = 'all';
        }
        $import_message = isset($_GET['cmn_imported']) ? sanitize_text_field($_GET['cmn_imported']) : '';
        $import_note = isset($_GET['cmn_import_msg']) ? sanitize_text_field(wp_unslash($_GET['cmn_import_msg'])) : '';
        $import_token = isset($_GET['cmn_import_token']) ? sanitize_text_field($_GET['cmn_import_token']) : '';
        $import_data = $import_token ? get_transient('cmn_import_' . $import_token) : null;
        if ($import_data && (int) ($import_data['user_id'] ?? 0) !== get_current_user_id()) {
            $import_data = null;
            $import_token = '';
        }
        $import_job_id = isset($_GET['cmn_import_job']) ? sanitize_key((string) $_GET['cmn_import_job']) : '';
        $import_job_data = $import_job_id !== '' ? $this->get_school_import_job($import_job_id) : null;
        if ($import_job_data && (int) ($import_job_data['user_id'] ?? 0) !== get_current_user_id()) {
            $import_job_data = null;
            $import_job_id = '';
        }
        $import_headers = $import_data['headers'] ?? [];
        $import_preview_rows = (array) ($import_data['preview_rows'] ?? []);
        $import_total_rows = max(0, (int) ($import_data['total_rows'] ?? 0));
        $panel = isset($_GET['cmn_panel']) ? sanitize_key((string) $_GET['cmn_panel']) : '';
        $bulk_active = ($import_data || $import_job_data || $panel === 'bulk') ? ' is-active' : '';
        $add_active = $panel === 'add' ? ' is-active' : '';

        $school_list_post_statuses = $this->get_school_list_post_statuses();
        /*
         * Eligibility contract: Sales/Clients -> Schools list
         * - Entity source: cmn_school posts (internal CRM records), including non-public internal post statuses.
         * - Sales list inclusion: cmn_status = 'lead'.
         * - Clients list inclusion: cmn_status = 'client'.
         * - Additional filters: pipeline stage, account manager, location, and search criteria.
         */
        $args = [
            'post_type' => 'cmn_school',
            'post_status' => $school_list_post_statuses,
            'posts_per_page' => 200,
        ];
        $assigned_school_ids = [];
        if ($this->is_account_manager_user($current_user_id) && !$this->is_admin_user($current_user_id) && !$this->is_staff_role($current_user_id)) {
            $assigned_school_ids = $this->get_assigned_school_ids_for_account_manager($current_user_id);
            if (!$assigned_school_ids) {
                $assigned_school_ids = [0];
            }
            $args['post__in'] = $assigned_school_ids;
        }
        $meta_query = [];
        if ($status !== '' && $status !== 'all') {
            $meta_query[] = [
                'key' => 'cmn_status',
                'value' => $status,
            ];
        }
        if ($stage !== '') {
            $meta_query[] = [
                'key' => 'cmn_pipeline_stage',
                'value' => $stage,
            ];
        }
        if ($location_filter !== '') {
            $meta_query[] = [
                'key' => 'cmn_location',
                'value' => $location_filter,
                'compare' => 'LIKE',
            ];
        }
        if ($manager_id) {
            $manager = get_user_by('id', $manager_id);
            $manager_query = [
                'relation' => 'OR',
                [
                    'key' => 'cmn_account_manager_user',
                    'value' => (string) $manager_id,
                ],
            ];
            if ($manager) {
                $manager_query[] = [
                    'key' => 'cmn_account_manager',
                    'value' => $manager->display_name,
                    'compare' => 'LIKE',
                ];
                $manager_query[] = [
                    'key' => 'cmn_account_manager_name',
                    'value' => $manager->display_name,
                    'compare' => 'LIKE',
                ];
                $manager_query[] = [
                    'key' => 'cmn_account_manager_email',
                    'value' => $manager->user_email,
                    'compare' => 'LIKE',
                ];
            }
            $meta_query[] = $manager_query;
        }
        if ($lead_group_filter !== '') {
            $meta_query[] = [
                'key' => 'cmn_lead_groups_csv',
                'value' => '|' . $lead_group_filter . '|',
                'compare' => 'LIKE',
            ];
        }
        if ($meta_query) {
            $args['meta_query'] = $meta_query;
        }
        if ($last_activity_filter === 'inactive_30') {
            $args['date_query'] = [
                [
                    'column' => 'post_modified',
                    'before' => wp_date('Y-m-d H:i:s', current_time('timestamp') - (30 * DAY_IN_SECONDS)),
                    'inclusive' => true,
                ],
            ];
        }
        if ($search !== '') {
            global $wpdb;
            $status_placeholders = implode(',', array_fill(0, count($school_list_post_statuses), '%s'));
            $meta_keys = [
                'cmn_school_id',
                'cmn_location',
                'cmn_town',
                'cmn_city',
                'cmn_county',
                'cmn_postcode',
                'cmn_email',
                'cmn_school_email',
                'cmn_school_email_domain',
                'cmn_domain',
                'cmn_phone',
                'cmn_primary_contact_name',
                'cmn_primary_contact_email',
                'cmn_primary_contact_phone',
                'cmn_status',
                'cmn_pipeline_stage',
                'cmn_account_manager',
                'cmn_account_manager_name',
                'cmn_account_manager_username',
                'cmn_account_manager_email',
                'cmn_cover_manager',
                'cmn_cover_manager_name',
                'cmn_cover_manager_email',
                'cmn_email_name',
                'cmn_contact_name',
                'cmn_contact_email',
                'cmn_contact_phone',
                'cmn_contact_role',
            ];
            $placeholders = implode(',', array_fill(0, count($meta_keys), '%s'));
            $search_tokens = preg_split('/\s+/', strtolower(trim((string) $search))) ?: [];
            $search_tokens = array_values(array_unique(array_filter($search_tokens, static function ($token) {
                return trim((string) $token) !== '';
            })));
            if (!$search_tokens) {
                $search_tokens = [strtolower(trim((string) $search))];
            }
            $matched_ids = null;
            foreach ($search_tokens as $search_token) {
                $like = '%' . $wpdb->esc_like((string) $search_token) . '%';
                $sql = "SELECT DISTINCT p.ID
                    FROM {$wpdb->posts} p
                    LEFT JOIN {$wpdb->postmeta} pm ON pm.post_id = p.ID
                    WHERE p.post_type = 'cmn_school'
                      AND p.post_status IN ({$status_placeholders})
                      AND (p.post_title LIKE %s OR (pm.meta_key IN ({$placeholders}) AND pm.meta_value LIKE %s))";
                $params = array_merge($school_list_post_statuses, [$like], $meta_keys, [$like]);
                $token_ids = array_map('intval', (array) $wpdb->get_col($wpdb->prepare($sql, $params)));
                if ($matched_ids === null) {
                    $matched_ids = $token_ids;
                } else {
                    $matched_ids = array_values(array_intersect($matched_ids, $token_ids));
                }
                if (!$matched_ids) {
                    break;
                }
            }
            if (!$matched_ids) {
                $matched_ids = [0];
            }
            if (!empty($args['post__in'])) {
                $matched_ids = array_values(array_intersect($args['post__in'], $matched_ids));
                if (!$matched_ids) {
                    $matched_ids = [0];
                }
            }
            $args['post__in'] = $matched_ids;
        }
        $query = new WP_Query($args);
        $view_param = 'schools';
        $redirect_url = add_query_arg(array_filter([
            'view' => $view_param,
            'cmn_status' => $status ?: null,
            'cmn_stage' => $stage ?: null,
            'cmn_manager' => $manager_id ?: null,
            'cmn_location' => $location_filter ?: null,
            'cmn_lead_group' => $lead_group_filter ?: null,
            'cmn_last_activity' => $last_activity_filter ?: null,
            'q' => $search ?: null,
            'cmn_bucket' => $bucket ?: null,
        ]), $portal_url);
        $manager_users = $this->get_account_manager_users();
        $visible_lead_groups = $this->get_visible_lead_groups_for_user((int) $current_user_id);
        $active_nav = 'all_schools';
        if ($status === 'needs_attention') {
            $active_nav = 'schools_needs_attention';
        } elseif ($status === 'lead' || $bucket === 'sales' || $view === 'leads') {
            $active_nav = 'schools_leads';
        } elseif ($status === 'client' || $bucket === 'clients') {
            $active_nav = 'active_clients';
        } elseif (in_array($status, ['rejected', 'archived'], true)) {
