        $filter_label = $filter_count ? 'Filters (' . $filter_count . ')' : 'Filters';
        $base_url = add_query_arg(array_filter(['view' => $view_param, 'cmn_bucket' => $bucket ?: null]), $portal_url);
        $panel_base_query = array_filter([
