        return $this->render_staff_shell('requests', $inner);
    }

    private function get_school_access_request_source($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return '';
        }
        return sanitize_key((string) get_post_meta($school_id, 'cmn_access_request_source', true));
    }

    private function is_explicit_school_access_request_source($source) {
        $source = sanitize_key((string) $source);
        if ($source === '') {
            return false;
        }
        return in_array($source, [
            'public_form',
            'token_form',
            'reapply_form',
            'reapply_admin',
            'staff_manual',
            'staff_quick_actions',
            'staff_request_review',
        ], true);
    }

    private function set_school_access_request_source($school_id, $source) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return;
        }
        $source = sanitize_key((string) $source);
        if ($source === '') {
            delete_post_meta($school_id, 'cmn_access_request_source');
            return;
        }
        update_post_meta($school_id, 'cmn_access_request_source', $source);
    }

    private function is_import_origin_school($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return false;
        }
        $import_markers = [
            'cmn_import_batch_id',
            'cmn_import_source_row',
            'cmn_import_issues',
            'cmn_bulk_import_key',
        ];
        foreach ($import_markers as $meta_key) {
            $value = get_post_meta($school_id, $meta_key, true);
            if (is_array($value)) {
                if (!empty($value)) {
                    return true;
                }
                continue;
            }
            if (trim((string) $value) !== '') {
                return true;
            }
        }
        return false;
    }

    private function clear_school_access_request_state($school_id, $clear_source = true) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return;
        }
        delete_post_meta($school_id, 'cmn_access_request_status');
        delete_post_meta($school_id, 'cmn_access_request_processed_at');
        delete_post_meta($school_id, 'cmn_access_request_processed_by');
        delete_post_meta($school_id, 'cmn_access_request_processed_ref');
        delete_post_meta($school_id, 'cmn_access_request_reject_reason');
        delete_post_meta($school_id, 'cmn_access_request_more_info_note');
        delete_post_meta($school_id, 'cmn_access_request_manual_started_at');
        if ($clear_source) {
            $this->set_school_access_request_source($school_id, '');
        }
        if (sanitize_key((string) get_post_meta($school_id, 'cmn_account_lifecycle', true)) === 'pending') {
            delete_post_meta($school_id, 'cmn_account_lifecycle');
        }
    }

    private function apply_school_rejected_lifecycle_state($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [
                'ok' => false,
                'reason' => 'invalid_school',
            ];
        }
        $current_status = sanitize_key((string) get_post_meta($school_id, 'cmn_status', true));
        if ($current_status === 'client') {
            return [
                'ok' => true,
                'skipped_client' => true,
                'status' => 'client',
            ];
        }
        $target_status = ($current_status === 'archived') ? 'archived' : 'rejected';
        update_post_meta($school_id, 'cmn_status', $target_status);
        if ($target_status === 'archived') {
            update_post_meta($school_id, 'cmn_account_lifecycle', 'archived');
        } else {
            $current_lifecycle = sanitize_key((string) get_post_meta($school_id, 'cmn_account_lifecycle', true));
            if ($current_lifecycle !== 'client' && $current_lifecycle !== 'archived') {
                update_post_meta($school_id, 'cmn_account_lifecycle', 'rejected');
            }
        }
        return [
            'ok' => true,
            'skipped_client' => false,
            'status' => $target_status,
        ];
    }

    private function assert_imported_school_not_application_without_submission($school_id, $context = '') {
        $school_id = (int) $school_id;
        if ($school_id < 1 || !$this->is_import_origin_school($school_id)) {
            return;
        }
        $status = sanitize_key((string) get_post_meta($school_id, 'cmn_access_request_status', true));
        if (!in_array($status, ['pending', 'approved', 'more_info_needed', 'rejected'], true)) {
            return;
        }
        $requested_at = trim((string) get_post_meta($school_id, 'cmn_registration_requested_at', true));
        $registration_ref = trim((string) get_post_meta($school_id, 'cmn_registration_ref', true));
        $manual_started_at = trim((string) get_post_meta($school_id, 'cmn_access_request_manual_started_at', true));
        if ($requested_at !== '' || $registration_ref !== '' || $manual_started_at !== '') {
            return;
        }
        $previous_status = $status;
        $this->clear_school_access_request_state($school_id, true);
        $current_status = sanitize_key((string) get_post_meta($school_id, 'cmn_status', true));
        if ($current_status === '' || $current_status === 'pending') {
            update_post_meta($school_id, 'cmn_status', 'lead');
        }
        $this->insert_audit('school_request_state_repaired', 'school', $school_id, [
            'reason' => 'imported_record_without_submission',
            'previous_request_status' => $previous_status,
            'context' => sanitize_key((string) $context),
        ], (int) get_current_user_id());
        error_log('[CMN_SCHOOL_REQUEST_GUARD] repaired imported school pending state | school_id=' . $school_id . ' | context=' . sanitize_key((string) $context));
    }

    private function repair_imported_school_application_states($limit = 500) {
        $limit = max(1, min(1200, (int) $limit));
        $query = new WP_Query([
            'post_type' => 'cmn_school',
            'post_status' => ['publish', 'draft', 'pending', 'private'],
            'posts_per_page' => $limit,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_access_request_status',
                    'compare' => 'EXISTS',
                ],
            ],
            'no_found_rows' => true,
        ]);
        $fixed = 0;
        foreach ((array) $query->posts as $school_id) {
            $school_id = (int) $school_id;
            if ($school_id < 1 || !$this->is_import_origin_school($school_id)) {
                continue;
            }
            $status = sanitize_key((string) get_post_meta($school_id, 'cmn_access_request_status', true));
            if (!in_array($status, ['pending', 'approved', 'more_info_needed', 'rejected'], true)) {
                continue;
            }
            $requested_at = trim((string) get_post_meta($school_id, 'cmn_registration_requested_at', true));
            $registration_ref = trim((string) get_post_meta($school_id, 'cmn_registration_ref', true));
            $manual_started_at = trim((string) get_post_meta($school_id, 'cmn_access_request_manual_started_at', true));
            if ($requested_at !== '' || $registration_ref !== '' || $manual_started_at !== '') {
                continue;
            }
            $this->clear_school_access_request_state($school_id, true);
            $current_status = sanitize_key((string) get_post_meta($school_id, 'cmn_status', true));
            if ($current_status === '' || $current_status === 'pending') {
                update_post_meta($school_id, 'cmn_status', 'lead');
            }
            $this->insert_audit('school_request_state_repaired', 'school', $school_id, [
                'reason' => 'imported_record_without_submission',
                'previous_request_status' => $status,
                'request_submitted_at' => $requested_at,
                'registration_ref' => $registration_ref,
            ], 0);
            $fixed++;
        }
        return $fixed;
    }

    private function maybe_repair_imported_school_application_states() {
        $current_user_id = (int) get_current_user_id();
        if ($current_user_id < 1 || !$this->is_staff_user($current_user_id)) {
            return;
        }
        $lock_key = 'cmn_repair_imported_school_apps_lock';
        if (get_transient($lock_key)) {
            return;
        }
        $last_run = (int) get_option('cmn_repair_imported_school_apps_last', 0);
        if ($last_run > 0 && (time() - $last_run) < 300) {
            return;
        }
        set_transient($lock_key, '1', 60);
        $fixed = $this->repair_imported_school_application_states(600);
        update_option('cmn_repair_imported_school_apps_last', time(), false);
        delete_transient($lock_key);
        if ($fixed > 0) {
            error_log('[CMN_SCHOOL_REQUEST_GUARD] repaired imported school application states: ' . (int) $fixed);
        }
    }

    private function get_school_access_request_status($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return '';
        }
        $status = sanitize_key((string) get_post_meta($school_id, 'cmn_access_request_status', true));
        $requested_at = trim((string) get_post_meta($school_id, 'cmn_registration_requested_at', true));
        $registration_ref = trim((string) get_post_meta($school_id, 'cmn_registration_ref', true));
        $processed_at = trim((string) get_post_meta($school_id, 'cmn_access_request_processed_at', true));
        $processed_ref = sanitize_text_field((string) get_post_meta($school_id, 'cmn_access_request_processed_ref', true));
        $manual_started_at = trim((string) get_post_meta($school_id, 'cmn_access_request_manual_started_at', true));
        $request_source = $this->get_school_access_request_source($school_id);
        $has_request_markers = ($requested_at !== '' || $registration_ref !== '');
        $has_manual_start_marker = ($manual_started_at !== '');
        $has_explicit_source = $this->is_explicit_school_access_request_source($request_source);
        $is_import_origin = $this->is_import_origin_school($school_id);
        $manual_pending_sources = ['staff_manual', 'staff_quick_actions', 'staff_request_review', 'reapply_admin'];

        if ($is_import_origin && !$has_request_markers && !$has_manual_start_marker) {
            // Imported leads must never appear in Applications unless explicitly submitted or manually started.
            if ($status !== '' || $has_explicit_source) {
                $this->clear_school_access_request_state($school_id, true);
            }
            return '';
        }

        if (in_array($status, ['pending', 'approved', 'rejected', 'more_info_needed'], true)) {
            $allow_manual_pending = in_array($request_source, $manual_pending_sources, true) && $has_manual_start_marker;
            if ($status === 'pending' && !$has_request_markers && !$allow_manual_pending) {
                $this->clear_school_access_request_state($school_id, true);
                return '';
            }
            if (in_array($status, ['approved', 'rejected', 'more_info_needed'], true) && !$has_request_markers && !$allow_manual_pending) {
                $this->clear_school_access_request_state($school_id, true);
                return '';
            }
            if (in_array($status, ['approved', 'rejected', 'more_info_needed'], true) && $has_request_markers) {
                if ($registration_ref !== '' && $processed_ref !== '' && $processed_ref !== $registration_ref) {
                    update_post_meta($school_id, 'cmn_access_request_status', 'pending');
                    delete_post_meta($school_id, 'cmn_access_request_processed_at');
                    delete_post_meta($school_id, 'cmn_access_request_processed_by');
                    delete_post_meta($school_id, 'cmn_access_request_processed_ref');
                    delete_post_meta($school_id, 'cmn_access_request_reject_reason');
                    delete_post_meta($school_id, 'cmn_access_request_more_info_note');
                    return 'pending';
                }
                if ($registration_ref !== '' && $processed_ref === '' && $processed_at !== '') {
                    // Backfill legacy records so they are stable and do not regress to pending.
                    update_post_meta($school_id, 'cmn_access_request_processed_ref', $registration_ref);
                }
            }
            return $status;
        }

        $allow_manual_pending = in_array($request_source, $manual_pending_sources, true) && $has_manual_start_marker;
        if ($has_request_markers || ($has_explicit_source && $allow_manual_pending)) {
            update_post_meta($school_id, 'cmn_access_request_status', 'pending');
            return 'pending';
        }
        return '';
    }

    private function get_school_requests_queue($status_filter = 'pending', $search = '', $limit = 250) {
        $status_filter = sanitize_key((string) $status_filter);
        if (!in_array($status_filter, ['pending', 'approved', 'more_info_needed', 'rejected', 'all'], true)) {
            $status_filter = 'all';
        }
        $search = strtolower(trim((string) $search));
        $limit = max(1, min(500, (int) $limit));
        $query = new WP_Query([
            'post_type' => 'cmn_school',
            'post_status' => ['publish', 'draft', 'pending', 'private'],
            'posts_per_page' => $limit,
            'fields' => 'ids',
            'meta_query' => [
                'relation' => 'OR',
                [
                    'key' => 'cmn_registration_requested_at',
                    'compare' => 'EXISTS',
                ],
                [
                    'key' => 'cmn_registration_ref',
                    'compare' => 'EXISTS',
                ],
                [
                    'key' => 'cmn_access_request_status',
                    'compare' => 'EXISTS',
                ],
                [
                    'key' => 'cmn_access_request_source',
                    'compare' => 'EXISTS',
                ],
            ],
            'orderby' => 'date',
            'order' => 'DESC',
            'no_found_rows' => true,
        ]);
        $rows = [];
        foreach ((array) $query->posts as $school_id) {
            $school_id = (int) $school_id;
            if ($school_id < 1) {
                continue;
            }
            $status = $this->get_school_access_request_status($school_id);
            if ($status === '') {
                continue;
            }
            if ($status_filter !== 'all' && $status !== $status_filter) {
                continue;
            }
            $ref = (string) get_post_meta($school_id, 'cmn_registration_ref', true);
            $email = (string) get_post_meta($school_id, 'cmn_email', true);
            $domain = (string) get_post_meta($school_id, 'cmn_school_email_domain', true);
            $location = (string) get_post_meta($school_id, 'cmn_location', true);
            $requested_at = (string) get_post_meta($school_id, 'cmn_registration_requested_at', true);
            $post_date = (string) get_post_field('post_date', $school_id);
            $title = (string) get_the_title($school_id);
            if ($search !== '') {
                $haystack = strtolower(implode(' ', [$ref, $email, $domain, $location, $title]));
                if (strpos($haystack, $search) === false) {
                    continue;
                }
            }
            $rows[] = [
                'school_id' => $school_id,
                'ref' => $ref,
                'name' => $title !== '' ? $title : ('School #' . $school_id),
                'email' => $email,
                'domain' => $domain,
                'location' => $location,
                'requested_at' => $requested_at,
                'post_date' => $post_date,
                'status' => $status,
                'processed_at' => (string) get_post_meta($school_id, 'cmn_access_request_processed_at', true),
                'processed_by' => (int) get_post_meta($school_id, 'cmn_access_request_processed_by', true),
                'reject_reason' => (string) get_post_meta($school_id, 'cmn_access_request_reject_reason', true),
                'more_info_note' => (string) get_post_meta($school_id, 'cmn_access_request_more_info_note', true),
                'latest_school_reply' => (string) get_post_meta($school_id, 'cmn_access_request_latest_school_reply', true),
                'latest_school_reply_at' => (string) get_post_meta($school_id, 'cmn_access_request_latest_school_reply_at', true),
            ];
        }
        usort($rows, static function ($a, $b) {
            $a_source = !empty($a['requested_at']) ? (string) $a['requested_at'] : (string) ($a['post_date'] ?? '');
            $b_source = !empty($b['requested_at']) ? (string) $b['requested_at'] : (string) ($b['post_date'] ?? '');
            $a_time = $a_source !== '' ? strtotime($a_source) : 0;
            $b_time = $b_source !== '' ? strtotime($b_source) : 0;
            if ($a_time === $b_time) {
                return (int) ($b['school_id'] ?? 0) <=> (int) ($a['school_id'] ?? 0);
            }
            return $b_time <=> $a_time;
        });
        return $rows;
    }

    private function decode_json_payload($payload, $fallback = []) {
        if (is_array($payload)) {
            return $payload;
        }
        if (!is_string($payload) || trim($payload) === '') {
            return is_array($fallback) ? $fallback : [];
        }
        $decoded = json_decode($payload, true);
        return is_array($decoded) ? $decoded : (is_array($fallback) ? $fallback : []);
    }

    private function get_school_request_timeline($school_id, $limit = 25) {
        global $wpdb;
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [];
        }
        $table = $this->get_audit_log_table();
        $limit = max(5, min(100, (int) $limit));
        $audit_rows = (array) $wpdb->get_results($wpdb->prepare(
            "SELECT id, user_id, action_type, details_json, created_at
             FROM {$table}
             WHERE reference_type = %s AND reference_id = %s
             ORDER BY id DESC
             LIMIT %d",
            'school',
            (string) $school_id,
            $limit
        ), ARRAY_A);
        if (!$audit_rows) {
            return [];
        }

        $allowed_actions = [
            'school_request_submitted',
            'school_request_assignment_updated',
            'school_request_more_info_needed',
            'school_request_approved',
            'school_request_rejected',
            'school_request_school_reply_received',
            'school_request_staff_message_posted',
            'school_request_thread_reopened',
            'school_request_thread_status_changed',
        ];
        $timeline = [];
        foreach ($audit_rows as $row) {
            $action = sanitize_key((string) ($row['action_type'] ?? ''));
            if (!in_array($action, $allowed_actions, true)) {
                continue;
            }
            $details = $this->decode_json_payload((string) ($row['details_json'] ?? ''), []);
            $user_id = (int) ($row['user_id'] ?? 0);
            $user = $user_id > 0 ? get_user_by('id', $user_id) : null;
            $actor_name = ($user && !empty($user->display_name)) ? (string) $user->display_name : 'System';
            $note_text = '';
            $title = 'Application updated';
            $status_class = 'is-muted';

            if ($action === 'school_request_submitted') {
                $title = 'Application submitted';
                $status_class = 'is-info';
            } elseif ($action === 'school_request_assignment_updated') {
                $status_class = 'is-info';
                $assignment_result = is_array($details['assignment_result'] ?? null) ? $details['assignment_result'] : [];
                $manager_id = isset($assignment_result['manager_id']) ? (int) $assignment_result['manager_id'] : 0;
                if ($manager_id > 0) {
                    $manager_user = get_user_by('id', $manager_id);
                    $manager_name = ($manager_user && !empty($manager_user->display_name)) ? (string) $manager_user->display_name : ('User #' . $manager_id);
                    $title = 'Assigned to account manager';
                    $note_text = $manager_name;
                } else {
                    $title = 'Account manager unassigned';
                }
            } elseif ($action === 'school_request_more_info_needed') {
                $title = 'More info needed';
                $status_class = 'is-warning';
                $note_text = sanitize_textarea_field((string) ($details['note'] ?? ''));
            } elseif ($action === 'school_request_approved') {
                $title = 'Application approved';
                $status_class = 'is-verified';
            } elseif ($action === 'school_request_rejected') {
                $title = 'Application declined';
                $status_class = 'is-declined';
                $note_text = sanitize_textarea_field((string) ($details['note'] ?? ($details['reason'] ?? '')));
            } elseif ($action === 'school_request_school_reply_received') {
                $title = 'School replied with requested information';
                $status_class = 'is-info';
                $reply_subject = sanitize_text_field((string) ($details['subject'] ?? ''));
                $reply_excerpt = sanitize_textarea_field((string) ($details['reply_excerpt'] ?? ($details['note'] ?? '')));
                $note_text = $reply_subject !== '' ? ($reply_subject . ($reply_excerpt !== '' ? (' - ' . $reply_excerpt) : '')) : $reply_excerpt;
            } elseif ($action === 'school_request_staff_message_posted') {
                $title = 'Staff sent a chat update';
                $status_class = 'is-info';
                $note_text = sanitize_textarea_field((string) ($details['message_excerpt'] ?? ''));
            } elseif ($action === 'school_request_thread_reopened') {
                $title = 'Chat reopened';
                $status_class = 'is-warning';
                $note_text = 'Reopened by school reply.';
            } elseif ($action === 'school_request_thread_status_changed') {
                $new_status = sanitize_key((string) ($details['status'] ?? ''));
                $title = $new_status === 'closed' ? 'Chat closed' : 'Chat opened';
                $status_class = $new_status === 'closed' ? 'is-warning' : 'is-verified';
            }

            $timeline[] = [
                'id' => (int) ($row['id'] ?? 0),
                'title' => $title,
                'note' => $note_text,
                'status_class' => $status_class,
                'created_at' => (string) ($row['created_at'] ?? ''),
                'actor_name' => $actor_name,
            ];
        }

        return array_reverse($timeline);
    }

    private function count_pending_school_requests() {
        $this->maybe_repair_imported_school_application_states();
        $rows = $this->get_school_requests_queue('pending', '', 500);
        $user_id = (int) get_current_user_id();
        if ($this->is_restricted_account_manager($user_id)) {
            $manageable_school_ids = $this->get_manageable_school_ids_for_user($user_id);
            if (!$manageable_school_ids) {
                return 0;
            }
            $rows = array_values(array_filter($rows, function ($row) use ($manageable_school_ids) {
                return in_array((int) ($row['school_id'] ?? 0), $manageable_school_ids, true);
            }));
        }
        return count($rows);
    }

    public function render_staff_school_requests_shortcode() {
        if (!is_user_logged_in()) {
            return $this->render_login_shortcode();
        }
        if (!$this->is_staff_user()) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>This section is available to staff only.</p></div></section>';
        }
        $this->maybe_repair_imported_school_application_states();
        $status_filter = sanitize_key((string) ($_GET['status'] ?? 'pending'));
        if (!in_array($status_filter, ['pending', 'approved', 'more_info_needed', 'rejected', 'all'], true)) {
            $status_filter = 'pending';
        }
        $search = sanitize_text_field((string) ($_GET['q'] ?? ''));
        $message = sanitize_text_field((string) wp_unslash($_GET['cmn_school_request_msg'] ?? ''));
        $portal_url = $this->get_portal_base_url();
        $request_id = (int) ($_GET['request_id'] ?? 0);
        if ($request_id > 0) {
            try {
                return $this->render_staff_school_request_detail_view($request_id, $portal_url, $message);
            } catch (\Throwable $e) {
                error_log('CMN school request detail render failed for request_id=' . $request_id . ': ' . $e->getMessage());
                $fallback = '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Application failed to load</h3><p>We hit a render error for this application. Please return to queue and try again, or contact support.</p><p><strong>Error:</strong> ' . esc_html((string) $e->getMessage()) . '</p><p><a class="cmn-ghost cmn-btn-mini cmn-button-link" href="' . esc_url(add_query_arg(['view' => 'school-requests'], $portal_url)) . '">Back to queue</a></p></div></section>';
                return $this->render_staff_shell('school_requests', $fallback);
            }
        }
        $rows = $this->get_school_requests_queue($status_filter, $search, 300);
        $current_user_id = (int) get_current_user_id();
        if ($this->is_restricted_account_manager($current_user_id)) {
            $manageable_school_ids = $this->get_manageable_school_ids_for_user($current_user_id);
            if ($manageable_school_ids) {
                $rows = array_values(array_filter($rows, function ($row) use ($manageable_school_ids) {
                    return in_array((int) ($row['school_id'] ?? 0), $manageable_school_ids, true);
                }));
            } else {
                $rows = [];
            }
        }
        $can_update_assignment = $this->is_admin_user($current_user_id);
        $account_managers = $can_update_assignment ? $this->get_account_manager_users() : [];
        $recent_cutoff = time() - (7 * DAY_IN_SECONDS);
        foreach ($rows as $row) {
            if ((string) ($row['status'] ?? '') !== 'pending') {
                continue;
            }
            $requested_at = (string) ($row['requested_at'] ?? '');
            $requested_ts = $requested_at !== '' ? strtotime($requested_at) : 0;
            if ($requested_ts > 0 && $requested_ts < $recent_cutoff) {
                continue;
            }
            $this->maybe_notify_staff_about_school_request(
                (int) ($row['school_id'] ?? 0),
                (string) ($row['ref'] ?? '')
            );
        }
        $current_url = add_query_arg([
            'view' => 'school-requests',
            'status' => $status_filter,
            'q' => $search,
        ], $portal_url);

        ob_start();
        ?>
        <header class="cmn-school-header">
            <div class="cmn-header-row">
                <div>
                    <h2>School Requests</h2>
                    <p>Review and process new school access requests.</p>
                </div>
            </div>
        </header>
        <?php if ($message !== '') : ?>
            <div class="cmn-panel-card"><strong><?php echo esc_html($message); ?></strong></div>
        <?php endif; ?>
        <form method="get" class="cmn-filters">
            <input type="hidden" name="view" value="school-requests">
            <select name="status">
                <option value="pending"<?php echo $status_filter === 'pending' ? ' selected' : ''; ?>>Pending</option>
                <option value="approved"<?php echo $status_filter === 'approved' ? ' selected' : ''; ?>>Approved</option>
                <option value="more_info_needed"<?php echo $status_filter === 'more_info_needed' ? ' selected' : ''; ?>>More Info Needed</option>
                <option value="rejected"<?php echo $status_filter === 'rejected' ? ' selected' : ''; ?>>Rejected</option>
                <option value="all"<?php echo $status_filter === 'all' ? ' selected' : ''; ?>>All</option>
            </select>
            <input type="search" name="q" value="<?php echo esc_attr($search); ?>" placeholder="Search school, email, domain, ref">
            <button class="cmn-ghost" type="submit">Filter</button>
            <a class="cmn-ghost" href="<?php echo esc_url(add_query_arg(['view' => 'school-requests'], $portal_url)); ?>">Clear</a>
        </form>
        <table class="cmn-approval-table cmn-request-table">
            <thead>
                <tr>
                    <th>Ref</th>
                    <th>School Name</th>
                    <th>Email</th>
                    <th>Domain</th>
                    <th>Location</th>
                    <th>Requested at</th>
                    <th>Status</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                <?php if ($rows) : ?>
                    <?php foreach ($rows as $row) : ?>
                        <?php
                        $status = (string) ($row['status'] ?? 'pending');
                        if ($status === 'approved') {
                            $status_class = 'is-verified';
                            $status_label = 'Approved';
                        } elseif ($status === 'rejected') {
                            $status_class = 'is-declined';
                            $status_label = 'Declined';
                        } elseif ($status === 'more_info_needed') {
                            $status_class = 'is-warning';
                            $status_label = 'More Info Needed';
                        } else {
                            $status_class = 'is-pending';
                            $status_label = 'Pending';
                        }
                        $school_id = (int) ($row['school_id'] ?? 0);
                        $ref_value = (string) ($row['ref'] ?? '');
                        $assigned_manager_id = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
                        if ($assigned_manager_id < 1) {
                            $assigned_manager_id = (int) get_post_meta($school_id, 'cmn_account_manager_user_id', true);
                        }
                        $assigned_manager_name = '';
                        if ($assigned_manager_id > 0) {
                            $assigned_manager_user = get_user_by('id', $assigned_manager_id);
                            if ($assigned_manager_user && !empty($assigned_manager_user->display_name)) {
                                $assigned_manager_name = (string) $assigned_manager_user->display_name;
                            }
                        }
                        ?>
                        <tr>
                            <td><?php echo esc_html($ref_value !== '' ? $ref_value : '-'); ?></td>
                            <td><?php echo esc_html((string) ($row['name'] ?? 'School')); ?></td>
                            <td><?php echo esc_html((string) ($row['email'] ?? '')); ?></td>
                            <td><?php echo esc_html((string) ($row['domain'] ?? '')); ?></td>
                            <td><?php echo esc_html((string) ($row['location'] ?? '')); ?></td>
                            <td><?php echo esc_html(!empty($row['requested_at']) ? date_i18n('M j, Y g:ia', strtotime((string) $row['requested_at'])) : '-'); ?></td>
                            <td>
                                <span class="cmn-status-chip <?php echo esc_attr($status_class); ?>"><?php echo esc_html($status_label); ?></span>
                                <?php if ($status === 'rejected' && !empty($row['reject_reason'])) : ?>
                                    <div class="cmn-table-meta"><?php echo esc_html((string) $row['reject_reason']); ?></div>
                                <?php endif; ?>
                                <?php if ($status === 'more_info_needed' && !empty($row['more_info_note'])) : ?>
                                    <div class="cmn-table-meta"><?php echo esc_html((string) $row['more_info_note']); ?></div>
                                <?php endif; ?>
                                <?php if ($status === 'more_info_needed' && !empty($row['latest_school_reply'])) : ?>
                                    <div class="cmn-table-meta"><strong>School reply:</strong> <?php echo esc_html((string) $row['latest_school_reply']); ?></div>
                                <?php endif; ?>
                            </td>
                            <td>
                                <a class="cmn-primary cmn-btn-mini cmn-button-link" href="<?php echo esc_url(add_query_arg(['view' => 'school-requests', 'request_id' => $school_id], $portal_url)); ?>">Open Application</a>
                                <a class="cmn-ghost cmn-btn-mini" href="<?php echo esc_url(add_query_arg(['view' => 'schools', 'school_id' => $school_id], $portal_url)); ?>">View</a>
                                <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-request-panel cmn-school-request-form" data-school-request-form="1" data-school-name="<?php echo esc_attr((string) ($row['name'] ?? 'School')); ?>">
                                    <?php wp_nonce_field('cmn_process_school_request_' . $school_id, 'cmn_process_school_request_nonce'); ?>
                                    <input type="hidden" name="action" value="cmn_process_school_request">
                                    <input type="hidden" name="school_id" value="<?php echo esc_attr((string) $school_id); ?>">
                                    <input type="hidden" name="cmn_redirect" value="<?php echo esc_attr($current_url); ?>">
                                    <input type="hidden" name="cmn_convert_to_client" value="0" class="cmn-convert-client-flag">
                                    <label class="cmn-school-request-convert" data-school-request-convert hidden>
                                        <input type="checkbox" data-school-request-convert-input checked>
                                        <span class="cmn-school-request-convert-title">Convert approved school to Client</span>
                                        <small>Creates school login and sends set-password email immediately.</small>
                                    </label>
                                    <label>Decision
                                        <select name="cmn_request_decision" data-school-request-decision>
                                            <option value="assign_only" selected>Assign only (no decision yet)</option>
                                            <option value="approved">Approve</option>
                                            <option value="more_info_needed">More info needed</option>
                                            <option value="rejected">Decline</option>
                                        </select>
                                    </label>
                                    <?php if ($can_update_assignment) : ?>
                                    <label>Assign account manager
                                        <select name="cmn_account_manager_user">
                                            <option value="__keep__" selected>Keep current</option>
                                            <option value="0">Unassigned</option>
                                            <?php foreach ($account_managers as $manager) : ?>
                                                <option value="<?php echo esc_attr((string) $manager->ID); ?>">
                                                    <?php echo esc_html($manager->display_name . ' (' . $manager->user_email . ')'); ?>
                                                </option>
                                            <?php endforeach; ?>
                                        </select>
                                    </label>
                                    <?php else : ?>
                                        <input type="hidden" name="cmn_account_manager_user" value="__keep__">
                                        <p class="cmn-muted">Assigned account manager: <?php echo esc_html($assigned_manager_name !== '' ? $assigned_manager_name : 'Unassigned'); ?></p>
                                        <p class="cmn-muted">Only admin can change assignment.</p>
                                    <?php endif; ?>
                                    <label class="cmn-school-request-note" data-school-request-note hidden>Note
                                        <textarea name="cmn_request_note" rows="2" data-school-request-note-input placeholder="Add details for the school"></textarea>
                                    </label>
                                    <button class="cmn-ghost cmn-btn-mini" type="submit">Save</button>
                                </form>
                            </td>
                        </tr>
                    <?php endforeach; ?>
                <?php else : ?>
                    <tr><td colspan="8">No school requests found for this filter.</td></tr>
                <?php endif; ?>
            </tbody>
        </table>
        <?php
        $inner = ob_get_clean();
        return $this->render_staff_shell('school_requests', $inner);
    }

    private function get_rate_guardrail_rows($only_risk = false, $limit = 150) {
        global $wpdb;
        $table = $this->get_booking_rates_table();
        $limit = max(1, (int) $limit);
        $where = '';
        if ($only_risk) {
            $where = "WHERE guardrail_status IN ('LOW','NEGATIVE')";
        }
        return (array) $wpdb->get_results(
            "SELECT * FROM {$table} {$where} ORDER BY updated_at DESC, id DESC LIMIT {$limit}",
            ARRAY_A
        );
    }

    private function count_bookings_at_risk_low_margin() {
        global $wpdb;
        $table = $this->get_booking_rates_table();
        $count = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE guardrail_status IN ('LOW','NEGATIVE')");
        return $count > 0 ? $count : 0;
    }

