    public function handle_export_data_integrity_csv() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized', 403);
        }
        $entity_type = sanitize_key((string) ($_GET['entity_type'] ?? 'candidate'));
        if (!in_array($entity_type, ['candidate', 'school'], true)) {
            $entity_type = 'candidate';
        }
        $nonce = (string) ($_GET['cmn_nonce'] ?? '');
        if (!wp_verify_nonce($nonce, 'cmn_export_data_integrity_csv_' . $entity_type)) {
            wp_die('Invalid request', 403);
        }
        $rows = $this->get_data_integrity_audit_rows($entity_type, 1000);
        nocache_headers();
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=cmn-data-integrity-' . $entity_type . '.csv');
        $out = fopen('php://output', 'w');
        fputcsv($out, ['entity_type', 'entity_id', 'name', 'missing_count', 'missing_fields', 'captured_not_displayed', 'displayed_not_captured']);
        foreach ((array) $rows as $row) {
            fputcsv($out, [
                $entity_type,
                (int) ($row['entity_id'] ?? 0),
                (string) ($row['name'] ?? ''),
                (int) ($row['missing_count'] ?? 0),
                implode('; ', (array) ($row['missing_fields'] ?? [])),
                implode('; ', (array) ($row['captured_not_displayed'] ?? [])),
                implode('; ', (array) ($row['displayed_not_captured'] ?? [])),
            ]);
        }
        fclose($out);
        exit;
    }

    public function handle_export_finance_invoices_csv() {
        if (!is_user_logged_in() || !$this->can_access_finance_reporting(get_current_user_id())) {
            wp_die('Unauthorized', 403);
        }
        $nonce = sanitize_text_field(wp_unslash((string) ($_REQUEST['cmn_nonce'] ?? '')));
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_export_finance_invoices_csv')) {
            wp_die('Invalid request', 403);
        }

        $month_filter = $this->normalize_finance_month_filter(wp_unslash((string) ($_REQUEST['cmn_finance_month'] ?? current_time('Y-m'))));
        $paid_filter = $this->normalize_finance_paid_filter(wp_unslash((string) ($_REQUEST['cmn_finance_paid'] ?? 'all')));
        $date_from = $this->normalize_invoice_date(wp_unslash((string) ($_REQUEST['cmn_finance_from'] ?? '')));
        $date_to = $this->normalize_invoice_date(wp_unslash((string) ($_REQUEST['cmn_finance_to'] ?? '')));
        if ($date_from !== '' && $date_to !== '' && strtotime($date_to) < strtotime($date_from)) {
            $tmp = $date_from;
            $date_from = $date_to;
            $date_to = $tmp;
        }
        $range = $this->get_finance_report_date_range($month_filter, $date_from, $date_to);
        $range_from = (string) ($range['from'] ?? '');
        $range_to = (string) ($range['to'] ?? '');
        if ($range_from === '' || $range_to === '') {
            wp_die('Invalid date range', 400);
        }

        $filename_range = preg_replace('/[^0-9]/', '', $range_from) . '-' . preg_replace('/[^0-9]/', '', $range_to);
        $filename = sprintf('cmn-finance-invoices-%s-%s.csv', $filename_range, gmdate('Ymd-His'));

        nocache_headers();
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=' . $filename);

        $out = fopen('php://output', 'w');
        fputcsv($out, ['invoice_number', 'school_name', 'period_start', 'period_end', 'subtotal', 'partner_credit', 'total', 'status']);

        global $wpdb;
        $invoices_table = $this->get_invoices_table();
        $adjustments_table = $this->get_invoice_adjustments_table();
        $posts_table = $wpdb->posts;
        $chunk_size = 250;
        $last_id = 0;

        while (true) {
            $where = [
                'i.id > %d',
                'i.period_start <= %s',
                'i.period_end >= %s',
            ];
            $params = [
                $last_id,
                $range_to,
                $range_from,
            ];
            $this->append_finance_paid_filter_sql($paid_filter, $where, $params, 'i.status', true);
            $where_sql = implode(' AND ', $where);
            $params[] = $chunk_size;
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT
                    i.id,
                    i.invoice_number,
                    i.school_id,
                    p.post_title AS school_name,
                    i.period_start,
                    i.period_end,
                    i.subtotal,
                    i.total,
                    i.status
                 FROM {$invoices_table} i
                 LEFT JOIN {$posts_table} p ON p.ID = i.school_id
                 WHERE {$where_sql}
                 ORDER BY i.id ASC
                 LIMIT %d",
                ...$params
            ), ARRAY_A);
            if (!is_array($rows) || !$rows) {
                break;
            }

            $invoice_ids = array_values(array_filter(array_map('intval', wp_list_pluck($rows, 'id'))));
            $partner_credit_map = [];
            if ($invoice_ids) {
                $placeholders = implode(',', array_fill(0, count($invoice_ids), '%d'));
                $credit_rows = $wpdb->get_results($wpdb->prepare(
                    "SELECT invoice_id, ROUND(COALESCE(ABS(SUM(amount)), 0), 2) AS partner_credit
                     FROM {$adjustments_table}
                     WHERE type = %s
                       AND invoice_id IN ({$placeholders})
                     GROUP BY invoice_id",
                    ...array_merge(['partner_credit'], $invoice_ids)
                ), ARRAY_A);
                if (is_array($credit_rows)) {
                    foreach ($credit_rows as $credit_row) {
                        $partner_credit_map[(int) ($credit_row['invoice_id'] ?? 0)] = round((float) ($credit_row['partner_credit'] ?? 0), 2);
                    }
                }
            }

            foreach ($rows as $row) {
                $invoice_id = (int) ($row['id'] ?? 0);
                $school_id = (int) ($row['school_id'] ?? 0);
                $school_name = $this->get_invoice_school_display_name($school_id, (string) ($row['school_name'] ?? ''));
                $partner_credit = round((float) ($partner_credit_map[$invoice_id] ?? 0), 2);
                fputcsv($out, [
                    (string) ($row['invoice_number'] ?? ('INV-' . $invoice_id)),
                    $school_name,
                    (string) ($row['period_start'] ?? ''),
                    (string) ($row['period_end'] ?? ''),
                    number_format((float) ($row['subtotal'] ?? 0), 2, '.', ''),
                    number_format($partner_credit, 2, '.', ''),
                    number_format((float) ($row['total'] ?? 0), 2, '.', ''),
                    $this->normalize_invoice_status((string) ($row['status'] ?? 'draft')),
                ]);
            }

            $last_row = end($rows);
            $last_id = max($last_id, (int) ($last_row['id'] ?? $last_id));
            unset($last_row);
            if (count($rows) < $chunk_size) {
                break;
            }
            if (function_exists('flush')) {
                flush();
            }
        }

        fclose($out);
        exit;
    }

    public function handle_export_partner_programme_summary_csv() {
        if (!is_user_logged_in() || !$this->can_access_finance_reporting(get_current_user_id())) {
            wp_die('Unauthorized', 403);
        }
        $nonce = sanitize_text_field(wp_unslash((string) ($_REQUEST['cmn_nonce'] ?? '')));
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_export_partner_programme_summary_csv')) {
            wp_die('Invalid request', 403);
        }

        $filename = 'cmn-partner-programme-summary-' . gmdate('Ymd-His') . '.csv';
        nocache_headers();
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=' . $filename);
        $out = fopen('php://output', 'w');
        fputcsv($out, ['school_name', 'tier', 'discount_percent', 'lifetime_credits', 'lifetime_savings', 'academic_year_savings']);

        global $wpdb;
        $posts_table = $wpdb->posts;
        $partner_table = $this->get_school_partner_table();
        $chunk_size = 250;
        $last_id = 0;

        while (true) {
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT
                    p.ID AS school_id,
                    p.post_title AS school_name,
                    COALESCE(sp.tier, %s) AS tier,
                    COALESCE(sp.discount_percent, 0) AS discount_percent,
                    COALESCE(sp.lifetime_credits, 0) AS lifetime_credits,
                    COALESCE(sp.lifetime_savings, 0) AS lifetime_savings,
                    COALESCE(sp.academic_year_savings, 0) AS academic_year_savings
                 FROM {$posts_table} p
                 LEFT JOIN {$partner_table} sp ON sp.school_id = p.ID
                 WHERE p.post_type = %s
                   AND p.post_status IN ('publish', 'private', 'draft', 'pending', 'future')
                   AND p.ID > %d
                 ORDER BY p.ID ASC
                 LIMIT %d",
                'standard',
                'cmn_school',
                $last_id,
                $chunk_size
            ), ARRAY_A);
            if (!is_array($rows) || !$rows) {
                break;
            }

            foreach ($rows as $row) {
                $school_id = (int) ($row['school_id'] ?? 0);
                $school_name = $this->get_invoice_school_display_name($school_id, (string) ($row['school_name'] ?? ''));
                $tier = $this->normalize_school_partner_tier((string) ($row['tier'] ?? 'standard'));
                fputcsv($out, [
                    $school_name,
                    $tier,
                    number_format((float) ($row['discount_percent'] ?? 0), 2, '.', ''),
                    (int) ($row['lifetime_credits'] ?? 0),
                    number_format((float) ($row['lifetime_savings'] ?? 0), 2, '.', ''),
                    number_format((float) ($row['academic_year_savings'] ?? 0), 2, '.', ''),
                ]);
            }

            $last_row = end($rows);
            $last_id = max($last_id, (int) ($last_row['school_id'] ?? $last_id));
            unset($last_row);
            if (count($rows) < $chunk_size) {
                break;
            }
            if (function_exists('flush')) {
                flush();
            }
        }

        fclose($out);
        exit;
    }

