    private function get_school_display_name_for_school_user_id($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return '—';
        }
        $school_id = (int) $this->resolve_school_id_for_user($school_user_id);
        if ($school_id > 0) {
            $title = trim((string) get_the_title($school_id));
            if ($title !== '') {
                return $title;
            }
        }
        $user = get_user_by('id', $school_user_id);
        if ($user instanceof WP_User) {
            $display = trim((string) $user->display_name);
            if ($display !== '') {
                return $display;
            }
            $email = trim((string) $user->user_email);
            if ($email !== '') {
                return $email;
            }
        }
        return 'School User #' . $school_user_id;
    }

    private function get_school_partner_credit_type_label($credit_type) {
        $credit_type = $this->normalize_school_partner_credit_type($credit_type);
        $labels = [
            'tier_discount' => 'Tier Discount',
            'manual_adjustment' => 'Manual Adjustment',
        ];
        return (string) ($labels[$credit_type] ?? 'Unknown');
    }

    private function get_school_partner_credit_status_label($credit_status) {
        $credit_status = $this->normalize_school_partner_credit_status($credit_status);
        $labels = [
            'pending' => 'Pending',
            'applied' => 'Applied',
            'voided' => 'Voided',
        ];
        return (string) ($labels[$credit_status] ?? 'Unknown');
    }

    /*
     * Prompt 19 acceptance checks:
     * 1) Admin/staff read-only ledger view lists table entries from cmn_school_partner_credits.
     * 2) Output columns: School, Booking ID, Date, Credit Amount (£), Credit Type, Status, Created At.
     * 3) No invoice totals or booking totals are modified from this view.
     */
    public function render_staff_partner_credit_ledger_shortcode() {
        if (!is_user_logged_in()) {
            return $this->render_login_shortcode();
        }
        $user_id = (int) get_current_user_id();
        if (!$this->can_access_finance_reporting($user_id)) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>Partner Credit Ledger is available to staff/admin only.</p></div></section>';
        }

        $portal_url = $this->get_portal_base_url();
        $status_filter = $this->normalize_school_partner_credit_status((string) wp_unslash($_GET['cmn_credit_status'] ?? ''));
        $school_user_filter = max(0, (int) ($_GET['cmn_credit_school_user'] ?? 0));
        $current_page = max(1, (int) ($_GET['cmn_credit_page'] ?? 1));

        $payload = $this->get_school_partner_credit_ledger_rows([
            'page' => $current_page,
            'per_page' => 50,
            'school_user_id' => $school_user_filter,
            'credit_status' => $status_filter,
        ]);
        $rows = (array) ($payload['rows'] ?? []);
        $total_rows = (int) ($payload['total_rows'] ?? 0);
        $total_pages = (int) ($payload['total_pages'] ?? 1);
        $current_page = (int) ($payload['page'] ?? $current_page);

        $base_url = add_query_arg(['view' => 'partner-credit-ledger'], $portal_url);
        $build_url = function ($overrides = []) use ($base_url, $status_filter, $school_user_filter, $current_page) {
            $args = [
                'cmn_credit_status' => $status_filter !== '' ? $status_filter : 'all',
            ];
            if ($school_user_filter > 0) {
                $args['cmn_credit_school_user'] = $school_user_filter;
            }
            if ($current_page > 1) {
                $args['cmn_credit_page'] = $current_page;
            }
            foreach ((array) $overrides as $key => $value) {
                if ($value === null) {
                    unset($args[$key]);
                    continue;
                }
                $args[$key] = $value;
            }
            return add_query_arg($args, $base_url);
        };

        ob_start();
        ?>
        <header class="cmn-school-header">
            <h2>Partner Credit Ledger</h2>
            <p>Read-only ledger of pending/applied/voided partner credits.</p>
        </header>
        <div class="cmn-dashboard-card" style="margin-bottom:16px;">
            <form method="get" action="<?php echo esc_url($portal_url); ?>" class="cmn-inline cmn-finance-filter-form">
                <input type="hidden" name="view" value="partner-credit-ledger">
                <label style="display:flex;flex-direction:column;gap:4px;">
                    <span>Status</span>
                    <select name="cmn_credit_status">
                        <option value="all"<?php selected($status_filter, ''); ?>>All</option>
                        <option value="pending"<?php selected($status_filter, 'pending'); ?>>Pending</option>
                        <option value="applied"<?php selected($status_filter, 'applied'); ?>>Applied</option>
                        <option value="voided"<?php selected($status_filter, 'voided'); ?>>Voided</option>
                    </select>
                </label>
                <label style="display:flex;flex-direction:column;gap:4px;">
                    <span>School User ID (optional)</span>
                    <input type="number" min="1" step="1" name="cmn_credit_school_user" value="<?php echo $school_user_filter > 0 ? esc_attr((string) $school_user_filter) : ''; ?>" placeholder="e.g. 245">
                </label>
                <button class="cmn-primary" type="submit">Apply</button>
                <a class="cmn-ghost" href="<?php echo esc_url(add_query_arg(['view' => 'partner-credit-ledger'], $portal_url)); ?>">Clear</a>
            </form>
        </div>
        <div class="cmn-dashboard-card">
            <h3>Ledger Entries</h3>
            <p class="cmn-muted"><?php echo esc_html(number_format((float) $total_rows, 0)); ?> row(s)</p>
            <?php if (!$rows) : ?>
                <div class="cmn-empty">No credit ledger entries yet.</div>
            <?php else : ?>
                <table class="cmn-approval-table">
                    <thead>
                        <tr>
                            <th>School</th>
                            <th>Booking ID</th>
                            <th>Date</th>
                            <th>Credit Amount (&pound;)</th>
                            <th>Credit Type</th>
                            <th>Status</th>
                            <th>Created At</th>
                        </tr>
                    </thead>
                    <tbody>
                        <?php foreach ($rows as $row) : ?>
                            <?php
                            $row_school_user_id = (int) ($row['school_user_id'] ?? 0);
                            $row_school_name = $this->get_school_display_name_for_school_user_id($row_school_user_id);
                            $row_booking_id = isset($row['booking_id']) && (int) $row['booking_id'] > 0 ? (int) $row['booking_id'] : 0;
                            $row_date = (string) ($row['booking_day_date'] ?? '');
                            $row_amount = round((float) ($row['credit_amount'] ?? 0), 2);
                            $row_created = (string) ($row['created_at'] ?? '');
                            $row_created_label = $row_created !== '' ? date_i18n('j M Y g:ia', strtotime($row_created)) : '—';
                            ?>
                            <tr>
                                <td><?php echo esc_html($row_school_name); ?></td>
                                <td><?php echo $row_booking_id > 0 ? esc_html((string) $row_booking_id) : '—'; ?></td>
                                <td><?php echo esc_html($row_date !== '' ? $row_date : '—'); ?></td>
                                <td><?php echo esc_html(number_format($row_amount, 2)); ?></td>
                                <td><?php echo esc_html($this->get_school_partner_credit_type_label((string) ($row['credit_type'] ?? ''))); ?></td>
                                <td><?php echo esc_html($this->get_school_partner_credit_status_label((string) ($row['credit_status'] ?? ''))); ?></td>
                                <td><?php echo esc_html($row_created_label); ?></td>
                            </tr>
                        <?php endforeach; ?>
                    </tbody>
                </table>
            <?php endif; ?>
            <?php if ($total_pages > 1) : ?>
                <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;">
                    <?php $prev_page = max(1, $current_page - 1); ?>
                    <?php $next_page = min($total_pages, $current_page + 1); ?>
                    <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_credit_page' => $prev_page])); ?>">Prev</a>
                    <?php for ($page_num = 1; $page_num <= $total_pages; $page_num++) : ?>
                        <a class="cmn-ghost<?php echo $page_num === $current_page ? ' is-active' : ''; ?>" href="<?php echo esc_url($build_url(['cmn_credit_page' => $page_num])); ?>"><?php echo esc_html((string) $page_num); ?></a>
                    <?php endfor; ?>
                    <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_credit_page' => $next_page])); ?>">Next</a>
                </div>
            <?php endif; ?>
        </div>
        <?php
        return $this->render_staff_shell('partner_credit_ledger', ob_get_clean());
    }

    private function get_school_partner_staff_manual_day_delta_limit() {
        $limit = (int) apply_filters(
            'cmn_school_partner_staff_manual_day_delta_limit',
            self::SCHOOL_PARTNER_STAFF_MAX_MANUAL_DAY_DELTA
        );
        return max(1, min(500, $limit));
    }

    private function get_school_partner_admin_action_throttle_seconds($action_key = '') {
        $seconds = (int) apply_filters(
            'cmn_school_partner_admin_action_throttle_seconds',
            self::SCHOOL_PARTNER_ADMIN_ACTION_THROTTLE_SECONDS,
            sanitize_key((string) $action_key)
        );
        return max(1, min(60, $seconds));
    }

    private function enforce_school_partner_admin_action_throttle($actor_user_id, $action_key = '') {
        $actor_user_id = (int) $actor_user_id;
        if ($actor_user_id < 1) {
            return new WP_Error('cmn_school_partner_admin_actor_required', 'Not authorised', ['status' => 403]);
        }
        $action_key = sanitize_key((string) $action_key);
        if ($action_key === '') {
            $action_key = 'generic';
        }
        $ttl = $this->get_school_partner_admin_action_throttle_seconds($action_key);
        $transient_key = 'cmn_sp_admin_throttle_' . $actor_user_id . '_' . substr(hash('sha256', $action_key), 0, 20);
        if (get_transient($transient_key) !== false) {
            return new WP_Error('cmn_school_partner_admin_throttled', 'Please wait a few seconds before trying again.', ['status' => 429]);
        }
        set_transient($transient_key, 1, $ttl);
        return true;
    }

    private function get_school_partner_overdue_confirmation_count($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return 0;
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return 0;
        }

        $count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM {$table}
             WHERE school_user_id = %d
               AND status = %s
               AND overdue_flag = 1",
            $school_user_id,
            'pending'
        ));
        return max(0, $count);
    }

    private function get_school_partner_admin_state_payload($school_user_id, $refresh = true, $actor_user_id = 0) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }

        $actor_user_id = (int) $actor_user_id;
        $state = $refresh
            ? $this->school_partner_refresh_confirmed_days($school_user_id, $actor_user_id > 0 ? $actor_user_id : null)
            : $this->ensure_school_partner_state_for_user($school_user_id);
        if (is_wp_error($state)) {
            return $state;
        }
        $state = is_array($state) ? $state : [];

        $base_confirmed_days = max(0, (int) ($state['confirmed_completed_days'] ?? 0));
        $manual_days_adjustment = (int) ($state['manual_days_adjustment'] ?? 0);
        $effective_confirmed_days = max(0, $base_confirmed_days + $manual_days_adjustment);

        return [
            'state' => $state,
            'base_confirmed_days' => $base_confirmed_days,
            'manual_days_adjustment' => $manual_days_adjustment,
            'effective_confirmed_days' => $effective_confirmed_days,
            'overdue_confirmations' => $this->get_school_partner_overdue_confirmation_count($school_user_id),
        ];
    }

    private function get_school_partner_admin_audit_state($payload) {
        $payload = is_array($payload) ? $payload : [];
        $state = is_array($payload['state'] ?? null) ? (array) $payload['state'] : [];
        return [
            'current_tier' => $this->normalize_school_partner_lifetime_tier((string) ($state['current_tier'] ?? 'standard')),
            'discount_pct' => round((float) ($state['discount_pct'] ?? 0), 2),
            'base_confirmed_days' => max(0, (int) ($payload['base_confirmed_days'] ?? 0)),
            'manual_days_adjustment' => (int) ($payload['manual_days_adjustment'] ?? 0),
            'effective_confirmed_days' => max(0, (int) ($payload['effective_confirmed_days'] ?? 0)),
            'estimated_savings_total' => round((float) ($state['estimated_savings_total'] ?? 0), 2),
            'last_tier_change_at' => (string) ($state['last_tier_change_at'] ?? ''),
            'overdue_confirmations' => max(0, (int) ($payload['overdue_confirmations'] ?? 0)),
        ];
    }

    private function get_school_partner_admin_search_results($search = '', $limit = 50) {
        $search = sanitize_text_field((string) $search);
        $limit = max(1, min(200, (int) $limit));
        $args = [
            'role__in' => ['cmn_school_manager', 'cmn_school_staff'],
            'number' => $limit,
            'orderby' => 'display_name',
            'order' => 'ASC',
            'fields' => ['ID', 'display_name', 'user_email', 'user_login'],
        ];

        if ($search !== '') {
            if (ctype_digit($search)) {
                $args['include'] = [(int) $search];
                $args['number'] = 1;
                $args['orderby'] = 'include';
            } else {
                $needle = str_replace(['*', '?'], '', $search);
                $args['search'] = '*' . $needle . '*';
                $args['search_columns'] = ['display_name', 'user_email', 'user_login'];
            }
        }

        $users = get_users($args);
        if (!is_array($users)) {
            $users = [];
        }

        $rows = [];
        foreach ($users as $user) {
            if (!$user instanceof WP_User) {
                continue;
            }
            $school_user_id = (int) ($user->ID ?? 0);
            if ($school_user_id < 1 || !$this->is_school_user($school_user_id)) {
                continue;
            }
            $state_result = $this->ensure_school_partner_state_for_user($school_user_id);
            $state_row = is_wp_error($state_result) ? [] : (is_array($state_result) ? $state_result : []);
            $base_confirmed_days = max(0, (int) ($state_row['confirmed_completed_days'] ?? 0));
            $manual_days_adjustment = (int) ($state_row['manual_days_adjustment'] ?? 0);
            $rows[] = [
                'school_user_id' => $school_user_id,
                'display_name' => (string) ($user->display_name ?: $user->user_login),
                'user_email' => (string) ($user->user_email ?? ''),
                'school_name' => $this->get_school_display_name_for_school_user_id($school_user_id),
                'current_tier' => $this->normalize_school_partner_lifetime_tier((string) ($state_row['current_tier'] ?? 'standard')),
                'discount_pct' => round((float) ($state_row['discount_pct'] ?? 0), 2),
                'base_confirmed_days' => $base_confirmed_days,
                'manual_days_adjustment' => $manual_days_adjustment,
                'effective_confirmed_days' => max(0, $base_confirmed_days + $manual_days_adjustment),
            ];
        }
        return $rows;
    }

    private function log_school_partner_admin_action_event($school_user_id, $event_type, $actor_user_id, $reason, $previous = [], $new = [], $metadata = []) {
        $school_user_id = (int) $school_user_id;
        $actor_user_id = (int) $actor_user_id;
        $event_type = sanitize_key((string) $event_type);
        if ($school_user_id < 1 || $event_type === '' || !function_exists('cmn_audit_log_event')) {
            return;
        }

        $metadata = is_array($metadata) ? $metadata : [];
        $metadata = array_merge([
            'reason' => sanitize_textarea_field((string) $reason),
            'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
            'previous' => is_array($previous) ? $previous : [],
            'new' => is_array($new) ? $new : [],
        ], $metadata);

        cmn_audit_log_event([
            'module' => 'school_partner',
            'entity_type' => 'school',
            'entity_id' => $school_user_id,
            'event_type' => $event_type,
            'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
            'metadata' => $metadata,
        ]);
    }

    private function school_partner_admin_apply_effective_tier_if_needed($school_user_id, $actor_user_id = 0) {
        $school_user_id = (int) $school_user_id;
        $actor_user_id = (int) $actor_user_id;
        $payload = $this->get_school_partner_admin_state_payload($school_user_id, false, $actor_user_id);
        if (is_wp_error($payload)) {
            return $payload;
        }

        $state = (array) ($payload['state'] ?? []);
        $current_tier = $this->normalize_school_partner_lifetime_tier((string) ($state['current_tier'] ?? 'standard'));
        $current_rank = $this->get_school_partner_lifetime_tier_rank($current_tier);
        $config_row = (array) $this->get_school_partner_config_row();
        $effective_confirmed_days = max(0, (int) ($payload['effective_confirmed_days'] ?? 0));
        $target_tier = $this->normalize_school_partner_lifetime_tier($this->school_partner_compute_tier($effective_confirmed_days, $config_row));
        $target_rank = $this->get_school_partner_lifetime_tier_rank($target_tier);

        $effective_tier = $target_rank > $current_rank ? $target_tier : $current_tier;
        $new_discount = $this->get_school_partner_discount_pct_for_tier($effective_tier, $config_row);
        $previous_discount = round((float) ($state['discount_pct'] ?? 0.00), 2);

        $updates = [];
        $formats = [];
        $now = current_time('mysql');
        $tier_changed = false;

        if ($effective_tier !== $current_tier) {
            $tier_changed = true;
            $updates['current_tier'] = $effective_tier;
            $formats[] = '%s';
            $updates['last_tier_change_at'] = $now;
            $formats[] = '%s';
        }
        if (abs($new_discount - $previous_discount) >= 0.0001) {
            $updates['discount_pct'] = $new_discount;
            $formats[] = '%f';
        }

        if (!empty($updates)) {
            $updates['updated_at'] = $now;
            $formats[] = '%s';
            global $wpdb;
            $table = $this->get_school_partner_state_table();
            $updated = $wpdb->update(
                $table,
                $updates,
                ['school_user_id' => $school_user_id],
                $formats,
                ['%d']
            );
            if ($updated === false) {
                return new WP_Error('cmn_school_partner_admin_apply_tier_failed', 'Unable to update school partner tier.');
            }
        }

        $updated_payload = $this->get_school_partner_admin_state_payload($school_user_id, false, $actor_user_id);
        if (is_wp_error($updated_payload)) {
            return $updated_payload;
        }

        if ($tier_changed && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'school',
                'entity_id' => $school_user_id,
                'event_type' => 'tier_change',
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'from' => $current_tier,
                    'to' => $effective_tier,
                    'confirmed_days' => max(0, (int) ($payload['base_confirmed_days'] ?? 0)),
                    'manual_days_adjustment' => (int) ($payload['manual_days_adjustment'] ?? 0),
                    'effective_confirmed_days' => $effective_confirmed_days,
                    'discount_pct' => $new_discount,
                    'source' => 'school_partner_admin_effective_days',
                ],
            ]);
        }

        return $updated_payload;
    }

    private function school_partner_admin_recalculate_days($school_user_id, $reason, $actor_user_id = 0) {
        $school_user_id = (int) $school_user_id;
        $actor_user_id = (int) $actor_user_id;
        $reason = sanitize_textarea_field((string) $reason);
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }
        if ($reason === '') {
            return new WP_Error('cmn_school_partner_reason_required', 'A reason is required.');
        }

        $before_payload = $this->get_school_partner_admin_state_payload($school_user_id, false, $actor_user_id);
        if (is_wp_error($before_payload)) {
            return $before_payload;
        }

        $refresh = $this->school_partner_refresh_confirmed_days($school_user_id, $actor_user_id > 0 ? $actor_user_id : null);
        if (is_wp_error($refresh)) {
            return $refresh;
        }

        $apply = $this->school_partner_apply_tier_if_needed($school_user_id, $actor_user_id > 0 ? $actor_user_id : null);
        if (is_wp_error($apply)) {
            return $apply;
        }

        $effective_apply = $this->school_partner_admin_apply_effective_tier_if_needed($school_user_id, $actor_user_id);
        if (is_wp_error($effective_apply)) {
            return $effective_apply;
        }

        $after_payload = $this->get_school_partner_admin_state_payload($school_user_id, false, $actor_user_id);
        if (is_wp_error($after_payload)) {
            return $after_payload;
        }

        $this->log_school_partner_admin_action_event(
            $school_user_id,
            'admin_recalc_days',
            $actor_user_id,
            $reason,
            $this->get_school_partner_admin_audit_state($before_payload),
            $this->get_school_partner_admin_audit_state($after_payload),
            [
                'used_apply_function' => 'cmn_school_partner_apply_tier_if_needed',
            ]
        );

        return [
            'before' => $before_payload,
            'after' => $after_payload,
        ];
    }

    private function school_partner_admin_set_tier($school_user_id, $target_tier, $reason, $actor_user_id = 0) {
        $school_user_id = (int) $school_user_id;
        $actor_user_id = (int) $actor_user_id;
        $target_tier = $this->normalize_school_partner_lifetime_tier($target_tier);
        $reason = sanitize_textarea_field((string) $reason);
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }
        if ($reason === '') {
            return new WP_Error('cmn_school_partner_reason_required', 'A reason is required.');
        }

        $is_admin = $this->is_admin_user($actor_user_id);
        if (!$is_admin && !$this->is_staff_role($actor_user_id)) {
            return new WP_Error('cmn_school_partner_not_authorized', 'Not authorised', ['status' => 403]);
        }

        $before_payload = $this->get_school_partner_admin_state_payload($school_user_id, false, $actor_user_id);
        if (is_wp_error($before_payload)) {
            return $before_payload;
        }
        $before_state = (array) ($before_payload['state'] ?? []);
        $current_tier = $this->normalize_school_partner_lifetime_tier((string) ($before_state['current_tier'] ?? 'standard'));
        $current_rank = $this->get_school_partner_lifetime_tier_rank($current_tier);
        $target_rank = $this->get_school_partner_lifetime_tier_rank($target_tier);
        if (!$is_admin && $target_rank < $current_rank) {
            return new WP_Error('cmn_school_partner_staff_cannot_downgrade', 'Staff can only upgrade tier.');
        }

        $config_row = (array) $this->get_school_partner_config_row();
        $new_discount = $this->get_school_partner_discount_pct_for_tier($target_tier, $config_row);
        $now = current_time('mysql');

        $updates = [
            'current_tier' => $target_tier,
            'discount_pct' => $new_discount,
            'last_tier_change_at' => $now,
            'updated_at' => $now,
        ];
        global $wpdb;
        $table = $this->get_school_partner_state_table();
        $updated = $wpdb->update(
            $table,
            $updates,
            ['school_user_id' => $school_user_id],
            ['%s', '%f', '%s', '%s'],
            ['%d']
        );
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_admin_set_tier_failed', 'Unable to set tier.');
        }

        $after_payload = $this->get_school_partner_admin_state_payload($school_user_id, false, $actor_user_id);
        if (is_wp_error($after_payload)) {
            return $after_payload;
        }

        $this->log_school_partner_admin_action_event(
            $school_user_id,
            'admin_set_tier',
            $actor_user_id,
            $reason,
            $this->get_school_partner_admin_audit_state($before_payload),
            $this->get_school_partner_admin_audit_state($after_payload),
            [
                'target_tier' => $target_tier,
                'downgrade' => $target_rank < $current_rank ? 1 : 0,
            ]
        );

        return [
            'before' => $before_payload,
            'after' => $after_payload,
        ];
    }

    private function school_partner_admin_adjust_manual_days($school_user_id, $delta, $reason, $actor_user_id = 0) {
        $school_user_id = (int) $school_user_id;
        $delta = (int) $delta;
        $actor_user_id = (int) $actor_user_id;
        $reason = sanitize_textarea_field((string) $reason);
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }
        if ($delta === 0) {
            return new WP_Error('cmn_school_partner_invalid_delta', 'Delta must be non-zero.');
        }
        if ($reason === '') {
            return new WP_Error('cmn_school_partner_reason_required', 'A reason is required.');
        }

        $is_admin = $this->is_admin_user($actor_user_id);
        if (!$is_admin && !$this->is_staff_role($actor_user_id)) {
            return new WP_Error('cmn_school_partner_not_authorized', 'Not authorised', ['status' => 403]);
        }
        $staff_limit = $this->get_school_partner_staff_manual_day_delta_limit();
        if (!$is_admin && abs($delta) > $staff_limit) {
            return new WP_Error(
                'cmn_school_partner_delta_limit_exceeded',
                sprintf('Staff may adjust by at most %d days per action.', $staff_limit)
            );
        }

        $before_payload = $this->get_school_partner_admin_state_payload($school_user_id, true, $actor_user_id);
        if (is_wp_error($before_payload)) {
            return $before_payload;
        }
        $before_state = (array) ($before_payload['state'] ?? []);
        $previous_adjustment = (int) ($before_state['manual_days_adjustment'] ?? 0);
        $new_adjustment = $previous_adjustment + $delta;
        $now = current_time('mysql');

        global $wpdb;
        $table = $this->get_school_partner_state_table();
        $updated = $wpdb->update(
            $table,
            [
                'manual_days_adjustment' => $new_adjustment,
                'manual_days_adjustment_reason' => $reason,
                'manual_days_adjustment_updated_at' => $now,
                'updated_at' => $now,
            ],
            ['school_user_id' => $school_user_id],
            ['%d', '%s', '%s', '%s'],
            ['%d']
        );
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_adjust_days_failed', 'Unable to update manual day adjustment.');
        }

        $effective_apply = $this->school_partner_admin_apply_effective_tier_if_needed($school_user_id, $actor_user_id);
        if (is_wp_error($effective_apply)) {
            return $effective_apply;
        }
        $after_payload = $this->get_school_partner_admin_state_payload($school_user_id, false, $actor_user_id);
        if (is_wp_error($after_payload)) {
            return $after_payload;
        }

        $this->log_school_partner_admin_action_event(
            $school_user_id,
            'admin_adjust_days',
            $actor_user_id,
            $reason,
            $this->get_school_partner_admin_audit_state($before_payload),
            $this->get_school_partner_admin_audit_state($after_payload),
            [
                'delta' => $delta,
                'staff_limit' => $staff_limit,
            ]
        );

        return [
            'before' => $before_payload,
            'after' => $after_payload,
        ];
    }

    private function school_partner_admin_create_manual_credit_entry($school_user_id, $credit_amount, $reference, $reason, $actor_user_id = 0, $booking_id = 0, $booking_day_date = '') {
        $school_user_id = (int) $school_user_id;
        $credit_amount = round((float) $credit_amount, 2);
        $reference = sanitize_text_field((string) $reference);
        $reason = sanitize_textarea_field((string) $reason);
        $actor_user_id = (int) $actor_user_id;
        $booking_id = max(0, (int) $booking_id);
        $booking_day_date = $this->normalize_invoice_date((string) $booking_day_date);

        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }
        if ($credit_amount <= 0) {
            return new WP_Error('cmn_school_partner_invalid_credit_amount', 'Amount must be greater than zero.');
        }
        if ($reference === '' || $reason === '') {
            return new WP_Error('cmn_school_partner_reference_reason_required', 'Reference and reason are required.');
        }

        $created = $this->insert_partner_credit_entry([
            'school_user_id' => $school_user_id,
            'booking_id' => $booking_id > 0 ? $booking_id : null,
            'booking_day_date' => $booking_day_date !== '' ? $booking_day_date : null,
            'credit_amount' => $credit_amount,
            'credit_type' => 'manual_adjustment',
            'reference' => $reference,
        ]);
        if (is_wp_error($created)) {
            return $created;
        }
        $created = is_array($created) ? $created : [];

        $this->log_school_partner_admin_action_event(
            $school_user_id,
            'admin_credit_created',
            $actor_user_id,
            $reason,
            [],
            [
                'credit_id' => (int) ($created['id'] ?? 0),
                'credit_status' => (string) ($created['credit_status'] ?? 'pending'),
                'credit_amount' => round((float) ($created['credit_amount'] ?? $credit_amount), 2),
            ],
            [
                'credit_id' => (int) ($created['id'] ?? 0),
                'booking_id' => (int) ($created['booking_id'] ?? $booking_id),
                'booking_day_date' => (string) ($created['booking_day_date'] ?? $booking_day_date),
                'credit_type' => 'manual_adjustment',
                'reference' => $reference,
            ]
        );

        return $created;
    }

    private function school_partner_admin_void_credit_entry($school_user_id, $credit_id, $reason, $actor_user_id = 0) {
        $school_user_id = (int) $school_user_id;
        $credit_id = (int) $credit_id;
        $actor_user_id = (int) $actor_user_id;
        $reason = sanitize_textarea_field((string) $reason);
        if ($school_user_id < 1 || $credit_id < 1) {
            return new WP_Error('cmn_school_partner_credit_invalid', 'School and credit entry are required.');
        }
        if ($reason === '') {
            return new WP_Error('cmn_school_partner_reason_required', 'A reason is required.');
        }

        global $wpdb;
        $table = $this->get_school_partner_credits_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT id, school_user_id, booking_id, booking_day_date, credit_type, reference, credit_amount, credit_status, related_invoice_id, created_at, updated_at
             FROM {$table}
             WHERE id = %d
             LIMIT 1",
            $credit_id
        ), ARRAY_A);
        if (!is_array($row) || empty($row)) {
            return new WP_Error('cmn_school_partner_credit_not_found', 'Credit entry not found.');
        }
        $row_school_user_id = (int) ($row['school_user_id'] ?? 0);
        if ($row_school_user_id !== $school_user_id) {
            return new WP_Error('cmn_school_partner_credit_mismatch', 'Credit entry does not belong to selected school.');
        }
        $current_status = $this->normalize_school_partner_credit_status((string) ($row['credit_status'] ?? 'pending'));
        if ($current_status !== 'pending') {
            return new WP_Error('cmn_school_partner_credit_not_pending', 'Only pending credits can be voided.');
        }

        $now = current_time('mysql');
        $updated = $wpdb->update(
            $table,
            [
                'credit_status' => 'voided',
                'updated_at' => $now,
            ],
            ['id' => $credit_id],
            ['%s', '%s'],
            ['%d']
        );
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_credit_void_failed', 'Unable to void credit entry.');
        }

        $updated_row = $wpdb->get_row($wpdb->prepare(
            "SELECT id, school_user_id, booking_id, booking_day_date, credit_type, reference, credit_amount, credit_status, related_invoice_id, created_at, updated_at
             FROM {$table}
             WHERE id = %d
             LIMIT 1",
            $credit_id
        ), ARRAY_A);
        $updated_row = is_array($updated_row) ? $updated_row : [];

        $this->log_school_partner_admin_action_event(
            $school_user_id,
            'admin_credit_voided',
            $actor_user_id,
            $reason,
            [
                'credit_id' => $credit_id,
                'credit_status' => $current_status,
                'credit_amount' => round((float) ($row['credit_amount'] ?? 0), 2),
            ],
            [
                'credit_id' => $credit_id,
                'credit_status' => (string) ($updated_row['credit_status'] ?? 'voided'),
                'credit_amount' => round((float) ($updated_row['credit_amount'] ?? ($row['credit_amount'] ?? 0)), 2),
            ],
            [
                'credit_id' => $credit_id,
                'reference' => (string) ($row['reference'] ?? ''),
            ]
        );

        return $updated_row;
    }

    private function authorize_school_partner_admin_action($nonce_action, $nonce_field, $school_user_id = 0) {
        if (!is_user_logged_in()) {
            return new WP_Error('cmn_auth_required', 'Not authorised', ['status' => 401]);
        }

        $nonce_check = function_exists('cmn_require_nonce')
            ? cmn_require_nonce($nonce_action, $nonce_field)
            : null;
        if (is_wp_error($nonce_check)) {
            return $nonce_check;
        }
        if (!function_exists('cmn_require_nonce')) {
            $nonce = isset($_REQUEST[$nonce_field]) ? sanitize_text_field((string) wp_unslash($_REQUEST[$nonce_field])) : '';
            if ($nonce === '' || !wp_verify_nonce($nonce, $nonce_action)) {
                return new WP_Error('cmn_invalid_nonce', 'Invalid request.', ['status' => 403]);
            }
        }

        $actor_user_id = (int) get_current_user_id();
        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('school_partner.mutate_any', [
                'entity_type' => 'school',
                'school_user_id' => max(0, (int) $school_user_id),
            ]);
            if (is_wp_error($ability_check)) {
                return $ability_check;
            }
        } elseif (!$this->can_access_finance_reporting($actor_user_id)) {
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }

        return $actor_user_id;
    }

    private function redirect_school_partner_admin_action($return_url, $school_user_id, $message, $message_type = 'success', $search = '') {
        $return_url = $this->get_school_partner_admin_portal_return_url($return_url);
        $school_user_id = max(0, (int) $school_user_id);
        $message_type = sanitize_key((string) $message_type);
        if (!in_array($message_type, ['success', 'error', 'warning'], true)) {
            $message_type = 'success';
        }
        $search = sanitize_text_field((string) $search);
        $args = [
            'cmn_sp_admin_msg' => rawurlencode(sanitize_text_field((string) $message)),
            'cmn_sp_admin_msg_type' => $message_type,
        ];
        if ($school_user_id > 0) {
            $args['cmn_sp_admin_school_user'] = $school_user_id;
        }
        if ($search !== '') {
            $args['cmn_sp_admin_search'] = $search;
        }
        wp_safe_redirect(add_query_arg($args, $return_url));
        exit;
    }

    /*
     * Prompt 20 acceptance checks:
     * 1) Staff/admin can search school users by name/email/user_id and view school partner state.
     * 2) Manual actions require reason + nonce + capability and are rate-limited.
     * 3) Staff cannot downgrade tier and is limited to +/- configured day adjustment.
     * 4) Manual credits can be created and pending credits can be voided with audit events.
     */
    public function render_staff_school_partner_admin_shortcode() {
        if (!is_user_logged_in()) {
            return $this->render_login_shortcode();
        }
        $user_id = (int) get_current_user_id();
        if (!$this->can_access_finance_reporting($user_id)) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>School Partner Admin is available to staff/admin only.</p></div></section>';
        }
        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('school_partner.mutate_any', ['entity_type' => 'school']);
            if (is_wp_error($ability_check)) {
                return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>Not authorised.</p></div></section>';
            }
        }

        $portal_url = $this->get_portal_base_url();
        $base_url = add_query_arg(['view' => 'school-partner-admin'], $portal_url);
        $search_filter = isset($_GET['cmn_sp_admin_search'])
            ? sanitize_text_field(wp_unslash((string) $_GET['cmn_sp_admin_search']))
            : '';
        $selected_school_user_id = max(0, (int) ($_GET['cmn_sp_admin_school_user'] ?? 0));
        $message = isset($_GET['cmn_sp_admin_msg'])
            ? sanitize_text_field(rawurldecode((string) wp_unslash((string) $_GET['cmn_sp_admin_msg'])))
            : '';
        $message_type = isset($_GET['cmn_sp_admin_msg_type'])
            ? sanitize_key(wp_unslash((string) $_GET['cmn_sp_admin_msg_type']))
            : 'success';
        if (!in_array($message_type, ['success', 'error', 'warning'], true)) {
            $message_type = 'success';
        }

        $rows = $this->get_school_partner_admin_search_results($search_filter, 75);
        $row_ids = [];
        foreach ($rows as $row) {
            $row_ids[] = (int) ($row['school_user_id'] ?? 0);
        }
        if ($selected_school_user_id > 0 && !in_array($selected_school_user_id, $row_ids, true) && $this->is_school_user($selected_school_user_id)) {
            $selected_user = get_user_by('id', $selected_school_user_id);
            if ($selected_user instanceof WP_User) {
                $state_result = $this->ensure_school_partner_state_for_user($selected_school_user_id);
                $state_row = is_wp_error($state_result) ? [] : (is_array($state_result) ? $state_result : []);
                $base_confirmed_days = max(0, (int) ($state_row['confirmed_completed_days'] ?? 0));
                $manual_days_adjustment = (int) ($state_row['manual_days_adjustment'] ?? 0);
                $rows[] = [
                    'school_user_id' => $selected_school_user_id,
                    'display_name' => (string) ($selected_user->display_name ?: $selected_user->user_login),
                    'user_email' => (string) ($selected_user->user_email ?? ''),
                    'school_name' => $this->get_school_display_name_for_school_user_id($selected_school_user_id),
                    'current_tier' => $this->normalize_school_partner_lifetime_tier((string) ($state_row['current_tier'] ?? 'standard')),
                    'discount_pct' => round((float) ($state_row['discount_pct'] ?? 0), 2),
                    'base_confirmed_days' => $base_confirmed_days,
                    'manual_days_adjustment' => $manual_days_adjustment,
                    'effective_confirmed_days' => max(0, $base_confirmed_days + $manual_days_adjustment),
                ];
            }
        }

        $selected_payload = null;
        $selected_error = '';
        $selected_ledger_rows = [];
        if ($selected_school_user_id > 0) {
            if (!$this->is_school_user($selected_school_user_id)) {
                $selected_error = 'School user not found.';
            } else {
                $selected_payload_result = $this->get_school_partner_admin_state_payload($selected_school_user_id, true, $user_id);
                if (is_wp_error($selected_payload_result)) {
                    $selected_error = $selected_payload_result->get_error_message();
                } else {
                    $selected_payload = $selected_payload_result;
                    $ledger_payload = $this->get_school_partner_credit_ledger_rows([
                        'page' => 1,
                        'per_page' => 50,
                        'school_user_id' => $selected_school_user_id,
                    ]);
                    $selected_ledger_rows = (array) ($ledger_payload['rows'] ?? []);
                }
            }
        }

        $build_url = function ($overrides = []) use ($base_url, $search_filter, $selected_school_user_id) {
            $args = [];
            if ($search_filter !== '') {
                $args['cmn_sp_admin_search'] = $search_filter;
            }
            if ($selected_school_user_id > 0) {
                $args['cmn_sp_admin_school_user'] = $selected_school_user_id;
            }
            foreach ((array) $overrides as $key => $value) {
                if ($value === null || $value === '') {
                    unset($args[$key]);
                    continue;
                }
                $args[$key] = $value;
            }
            return add_query_arg($args, $base_url);
        };

        $return_url = $build_url(['cmn_sp_admin_school_user' => $selected_school_user_id > 0 ? $selected_school_user_id : null]);
        $is_admin = $this->is_admin_user($user_id);
