    public function render_school_partner_admin_admin_page() {
        if (!is_user_logged_in() || !$this->can_access_finance_reporting(get_current_user_id())) {
            wp_die('Not authorised.');
        }

        $portal_url = add_query_arg(['view' => 'school-partner-admin'], $this->get_portal_base_url());
        echo '<div class="wrap">';
        echo '<h1>School Partner Admin</h1>';
        echo '<p>Manage school partner overrides and manual credit entries inside the portal workspace.</p>';
        echo '<p><a class="button button-primary" href="' . esc_url($portal_url) . '">Open School Partner Admin</a></p>';
        echo '</div>';
    }

    public function render_partner_credit_ledger_admin_page() {
        if (!is_user_logged_in() || !$this->can_access_finance_reporting(get_current_user_id())) {
            wp_die('Not authorised.');
        }

        $status_filter = $this->normalize_school_partner_credit_status((string) wp_unslash($_GET['cmn_credit_status'] ?? ''));
        $school_user_filter = max(0, (int) ($_GET['cmn_credit_school_user'] ?? 0));
        $current_page = max(1, (int) ($_GET['cmn_credit_page'] ?? 1));
        $payload = $this->get_school_partner_credit_ledger_rows([
            'page' => $current_page,
            'per_page' => 50,
            'school_user_id' => $school_user_filter,
            'credit_status' => $status_filter,
        ]);
        $rows = (array) ($payload['rows'] ?? []);
        $total_rows = (int) ($payload['total_rows'] ?? 0);
        $total_pages = (int) ($payload['total_pages'] ?? 1);
        $current_page = (int) ($payload['page'] ?? $current_page);

        $base_url = admin_url('admin.php?page=cmn-partner-credit-ledger');
        $build_url = function ($overrides = []) use ($base_url, $status_filter, $school_user_filter, $current_page) {
            $args = [
                'cmn_credit_status' => $status_filter !== '' ? $status_filter : 'all',
            ];
            if ($school_user_filter > 0) {
                $args['cmn_credit_school_user'] = $school_user_filter;
            }
            if ($current_page > 1) {
                $args['cmn_credit_page'] = $current_page;
            }
            foreach ((array) $overrides as $key => $value) {
                if ($value === null) {
                    unset($args[$key]);
                    continue;
                }
                $args[$key] = $value;
            }
            return add_query_arg($args, $base_url);
        };

        echo '<div class="wrap">';
        echo '<h1>Partner Credit Ledger</h1>';
        echo '<p>Read-only placeholder ledger for partner credits pending future invoice application.</p>';
        echo '<form method="get" style="display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;margin-bottom:16px;">';
        echo '<input type="hidden" name="page" value="cmn-partner-credit-ledger">';
        echo '<label>Status<br><select name="cmn_credit_status">';
        echo '<option value="all"' . selected($status_filter, '', false) . '>All</option>';
        echo '<option value="pending"' . selected($status_filter, 'pending', false) . '>Pending</option>';
        echo '<option value="applied"' . selected($status_filter, 'applied', false) . '>Applied</option>';
        echo '<option value="voided"' . selected($status_filter, 'voided', false) . '>Voided</option>';
        echo '</select></label>';
        echo '<label>School User ID<br><input type="number" min="1" step="1" name="cmn_credit_school_user" value="' . esc_attr($school_user_filter > 0 ? (string) $school_user_filter : '') . '"></label>';
        echo '<p><button class="button button-primary" type="submit">Apply</button> ';
        echo '<a class="button" href="' . esc_url($base_url) . '">Clear</a></p>';
        echo '</form>';

        echo '<p><strong>' . esc_html(number_format((float) $total_rows, 0)) . '</strong> row(s)</p>';
        if (!$rows) {
            echo '<p>No credit ledger entries yet.</p>';
        } else {
            echo '<table class="widefat striped">';
            echo '<thead><tr>';
            echo '<th>School</th>';
            echo '<th>Booking ID</th>';
            echo '<th>Date</th>';
            echo '<th>Credit Amount (&pound;)</th>';
            echo '<th>Credit Type</th>';
            echo '<th>Status</th>';
            echo '<th>Created At</th>';
            echo '</tr></thead><tbody>';
            foreach ($rows as $row) {
                $row_school_user_id = (int) ($row['school_user_id'] ?? 0);
                $row_school_name = $this->get_school_display_name_for_school_user_id($row_school_user_id);
                $row_booking_id = isset($row['booking_id']) && (int) $row['booking_id'] > 0 ? (int) $row['booking_id'] : 0;
                $row_date = (string) ($row['booking_day_date'] ?? '');
                $row_amount = round((float) ($row['credit_amount'] ?? 0), 2);
                $row_created = (string) ($row['created_at'] ?? '');
                $row_created_label = $row_created !== '' ? date_i18n('j M Y g:ia', strtotime($row_created)) : '—';
                echo '<tr>';
                echo '<td>' . esc_html($row_school_name) . '</td>';
                echo '<td>' . ($row_booking_id > 0 ? esc_html((string) $row_booking_id) : '—') . '</td>';
                echo '<td>' . esc_html($row_date !== '' ? $row_date : '—') . '</td>';
                echo '<td>' . esc_html(number_format($row_amount, 2)) . '</td>';
                echo '<td>' . esc_html($this->get_school_partner_credit_type_label((string) ($row['credit_type'] ?? ''))) . '</td>';
                echo '<td>' . esc_html($this->get_school_partner_credit_status_label((string) ($row['credit_status'] ?? ''))) . '</td>';
                echo '<td>' . esc_html($row_created_label) . '</td>';
                echo '</tr>';
            }
            echo '</tbody></table>';
        }

        if ($total_pages > 1) {
            echo '<p style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap;">';
            $prev_page = max(1, $current_page - 1);
            $next_page = min($total_pages, $current_page + 1);
            echo '<a class="button" href="' . esc_url($build_url(['cmn_credit_page' => $prev_page])) . '">Prev</a>';
            for ($page_num = 1; $page_num <= $total_pages; $page_num++) {
                $class = 'button' . ($page_num === $current_page ? ' button-primary' : '');
                echo '<a class="' . esc_attr($class) . '" href="' . esc_url($build_url(['cmn_credit_page' => $page_num])) . '">' . esc_html((string) $page_num) . '</a>';
            }
            echo '<a class="button" href="' . esc_url($build_url(['cmn_credit_page' => $next_page])) . '">Next</a>';
            echo '</p>';
        }

        echo '</div>';
    }

    public function render_staff_invoicing_shortcode() {
        if (!is_user_logged_in()) {
            return $this->render_login_shortcode();
        }
        if (!$this->is_staff_user()) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>This section is available to staff only.</p></div></section>';
        }
        $portal_url = $this->get_portal_base_url();
        $base_url = add_query_arg(['view' => 'invoicing'], $portal_url);
        $status_raw = isset($_GET['cmn_invoice_status']) ? sanitize_key(wp_unslash((string) $_GET['cmn_invoice_status'])) : '';
        if ($status_raw === 'all') {
            $status_raw = '';
        }
        $status_filter = in_array($status_raw, $this->get_allowed_invoice_statuses(), true) ? $status_raw : '';
        $month_filter = isset($_GET['cmn_invoice_month'])
            ? sanitize_text_field(wp_unslash((string) $_GET['cmn_invoice_month']))
            : current_time('Y-m');
        if (!preg_match('/^\d{4}-\d{2}$/', $month_filter)) {
            $month_filter = current_time('Y-m');
        }
        $school_filter = isset($_GET['cmn_invoice_school'])
            ? sanitize_text_field(wp_unslash((string) $_GET['cmn_invoice_school']))
            : '';
        $current_page = max(1, (int) ($_GET['cmn_invoice_page'] ?? 1));
        $selected_invoice_id = max(0, (int) ($_GET['cmn_invoice_id'] ?? 0));
        $message_raw = '';
        if (isset($_GET['cmn_invoice_msg'])) {
            $message_raw = (string) wp_unslash((string) $_GET['cmn_invoice_msg']);
        } elseif (isset($_GET['cmn_invoice_generation_msg'])) {
            $message_raw = (string) wp_unslash((string) $_GET['cmn_invoice_generation_msg']);
        } elseif (isset($_GET['cmn_candidate_rewards_reset_msg'])) {
            $message_raw = (string) wp_unslash((string) $_GET['cmn_candidate_rewards_reset_msg']);
        } elseif (isset($_GET['cmn_rewards_payroll_msg'])) {
            $message_raw = (string) wp_unslash((string) $_GET['cmn_rewards_payroll_msg']);
        }
        $message = sanitize_text_field(rawurldecode($message_raw));

        $list_payload = $this->get_invoice_list_results([
            'status' => $status_filter,
            'month' => $month_filter,
            'school' => $school_filter,
            'page' => $current_page,
            'per_page' => 20,
        ]);
        $invoice_rows = (array) ($list_payload['rows'] ?? []);
        $total_rows = (int) ($list_payload['total_rows'] ?? 0);
        $total_pages = (int) ($list_payload['total_pages'] ?? 1);
        $current_page = (int) ($list_payload['page'] ?? $current_page);

        $school_filter_options = $this->get_invoice_school_filter_options(160);
        $current_user_id = (int) get_current_user_id();
        $selected_invoice = [];
        $invoice_items = [];
        $invoice_adjustments = [];
        $invoice_payments = [];
        $invoice_audit_entries = [];
        $invoice_audit_user_map = [];
        $invoice_payment_user_map = [];
        $invoice_email_latest_log = [];
        $invoice_email_last_sent_log = [];
        $invoice_view_error = '';
        $selected_school_name = '';
        if ($selected_invoice_id > 0) {
            $selected_invoice = $this->get_invoice_by_id($selected_invoice_id);
            if (!$selected_invoice) {
                $invoice_view_error = 'Invoice not found.';
            } else {
                $invoice_items = $this->get_invoice_items((int) $selected_invoice_id);
                $invoice_adjustments = $this->get_invoice_adjustments((int) $selected_invoice_id);
                $invoice_payments = $this->get_invoice_payments((int) $selected_invoice_id, 200);
                $invoice_audit_entries = $this->get_invoice_audit_entries((int) $selected_invoice_id, 20);
                $audit_user_ids = [];
                foreach ((array) $invoice_audit_entries as $audit_row) {
                    $audit_user_id = (int) ($audit_row['user_id'] ?? 0);
                    if ($audit_user_id > 0) {
                        $audit_user_ids[] = $audit_user_id;
                    }
                }
                $payment_user_ids = [];
                foreach ((array) $invoice_payments as $payment_row) {
                    $payment_user_id = (int) ($payment_row['recorded_by_user_id'] ?? 0);
                    if ($payment_user_id > 0) {
                        $payment_user_ids[] = $payment_user_id;
                    }
                }
                $user_ids = array_values(array_unique(array_merge($audit_user_ids, $payment_user_ids)));
                if (!empty($user_ids)) {
                    $audit_users = get_users([
                        'include' => $user_ids,
                        'fields' => ['ID', 'display_name', 'user_login'],
                    ]);
                    foreach ((array) $audit_users as $audit_user) {
                        $audit_user_id = (int) ($audit_user->ID ?? 0);
                        if ($audit_user_id < 1) {
                            continue;
                        }
                        $label = trim((string) ($audit_user->display_name ?? ''));
                        if ($label === '') {
                            $label = trim((string) ($audit_user->user_login ?? ''));
                        }
                        $resolved_label = $label !== '' ? $label : ('User #' . $audit_user_id);
                        $invoice_audit_user_map[$audit_user_id] = $resolved_label;
                        $invoice_payment_user_map[$audit_user_id] = $resolved_label;
                    }
                }
                $selected_school_name = $this->get_invoice_school_display_name((int) ($selected_invoice['school_id'] ?? 0));
                $invoice_email_latest_log = $this->get_latest_invoice_email_log_entry((int) $selected_invoice_id);
                $invoice_email_last_sent_log = $this->get_latest_invoice_email_log_entry((int) $selected_invoice_id, 'sent');
            }
        }
        $status_transitions = !empty($selected_invoice)
            ? $this->get_invoice_allowed_status_transitions((string) ($selected_invoice['status'] ?? 'draft'), $current_user_id)
            : [];
        $selected_status = !empty($selected_invoice) ? $this->normalize_invoice_status((string) ($selected_invoice['status'] ?? 'draft')) : '';
        $selected_invoice_locked = $selected_status !== '' ? $this->is_invoice_content_locked($selected_status) : false;
        $selected_invoice_lock_message = $selected_status !== '' ? $this->get_invoice_lock_message($selected_status) : '';
        $can_add_adjustment = !empty($selected_invoice)
            && !$selected_invoice_locked
            && ($this->is_admin_user($current_user_id) || $this->is_staff_role($current_user_id));
        $selected_invoice_total = !empty($selected_invoice) ? round((float) ($selected_invoice['total'] ?? 0), 2) : 0.00;
        $selected_invoice_amount_paid = !empty($selected_invoice) ? round(max(0, (float) ($selected_invoice['amount_paid'] ?? 0)), 2) : 0.00;
        if (!empty($invoice_payments)) {
            $payment_sum = 0.0;
            foreach ((array) $invoice_payments as $payment_row) {
                $payment_sum += (float) ($payment_row['amount'] ?? 0);
            }
            $selected_invoice_amount_paid = round(max(0, $payment_sum), 2);
        }
        $selected_invoice_amount_due = !empty($selected_invoice)
            ? round(max(0, $selected_invoice_total - $selected_invoice_amount_paid), 2)
            : 0.00;
        $payment_method_options = [];
        foreach ($this->get_allowed_invoice_payment_methods() as $method_key) {
            $payment_method_options[$method_key] = $this->get_invoice_payment_method_label($method_key);
        }
        $can_record_payment = !empty($selected_invoice)
            && ($this->is_admin_user($current_user_id) || $this->is_staff_role($current_user_id))
            && $selected_status !== 'void'
            && ($selected_status !== 'paid' || $this->is_admin_user($current_user_id));
        $record_payment_block_reason = '';
        if (!empty($selected_invoice) && $selected_status === 'void') {
            $record_payment_block_reason = 'Payments cannot be recorded for void invoices.';
        } elseif (!empty($selected_invoice) && $selected_status === 'paid' && !$this->is_admin_user($current_user_id)) {
            $record_payment_block_reason = 'Invoice is already paid. Additional payment entries are Admin-only.';
        }
        $record_payment_default_amount = $selected_invoice_amount_due > 0 ? $selected_invoice_amount_due : $selected_invoice_total;
        if ($record_payment_default_amount <= 0) {
            $record_payment_default_amount = 0.01;
        }
        $record_payment_default_paid_at = current_time('Y-m-d\TH:i');
        $month_label = date_i18n('F Y', strtotime($month_filter . '-01'));
        $generator_month = $month_filter;
        $scheduled_bounds = $this->get_previous_invoice_month_bounds();
        $scheduled_month_key = is_array($scheduled_bounds) ? (string) ($scheduled_bounds['month_key'] ?? '') : '';
        if (!preg_match('/^\d{4}-\d{2}$/', $scheduled_month_key)) {
            $scheduled_month_key = current_time('Y-m');
        }
        $scheduled_month_label = date_i18n('F Y', strtotime($scheduled_month_key . '-01'));
        $candidate_rewards_reset_period = $this->get_candidate_rewards_reset_period_labels('now');
        $candidate_rewards_reset_to = (string) ($candidate_rewards_reset_period['to'] ?? '');
        if (!preg_match('/^\d{4}-\d{4}$/', $candidate_rewards_reset_to)) {
            $candidate_rewards_reset_to = (string) $this->get_academic_year_label('now');
        }
        $payroll_week_raw = isset($_GET['cmn_payroll_week_start'])
            ? sanitize_text_field(wp_unslash((string) $_GET['cmn_payroll_week_start']))
            : '';
        $payroll_week_start = $this->get_payroll_week_start($payroll_week_raw !== '' ? $payroll_week_raw : 'now');
        $payroll_week_end = $this->get_payroll_week_end_from_start($payroll_week_start);
        $payroll_week_label = $payroll_week_start;
        if ($payroll_week_start !== '' && $payroll_week_end !== '') {
            $payroll_week_label = sprintf(
                '%s - %s',
                date_i18n('j M Y', strtotime($payroll_week_start)),
                date_i18n('j M Y', strtotime($payroll_week_end))
            );
        }

        $build_url = function ($overrides = []) use ($base_url, $status_filter, $month_filter, $school_filter, $current_page, $selected_invoice_id) {
            $args = [
                'cmn_invoice_status' => $status_filter !== '' ? $status_filter : 'all',
                'cmn_invoice_month' => $month_filter,
            ];
            if ($school_filter !== '') {
                $args['cmn_invoice_school'] = $school_filter;
            }
            if ($current_page > 1) {
                $args['cmn_invoice_page'] = $current_page;
            }
            if ($selected_invoice_id > 0) {
                $args['cmn_invoice_id'] = $selected_invoice_id;
            }
            foreach ((array) $overrides as $key => $value) {
                if ($value === null) {
                    unset($args[$key]);
                    continue;
                }
                $args[$key] = $value;
            }
            return add_query_arg($args, $base_url);
        };

        ob_start();
        ?>
        <header class="cmn-school-header">
            <h2>Invoicing</h2>
            <p>Accounts receivable for schools: list, review, adjust, and progress invoice status.</p>
        </header>
        <?php if ($message !== '') : ?>
            <div class="cmn-dashboard-card" style="margin-bottom:12px;">
                <p class="cmn-muted"><?php echo esc_html($message); ?></p>
            </div>
        <?php endif; ?>
        <div class="cmn-dashboard-card" style="margin-bottom:16px;">
            <form method="get" action="<?php echo esc_url($portal_url); ?>" class="cmn-inline" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;">
                <input type="hidden" name="view" value="invoicing">
                <label style="display:flex;flex-direction:column;gap:4px;">
                    <span>Status</span>
                    <select name="cmn_invoice_status">
                        <option value="all"<?php selected($status_filter, ''); ?>>All statuses</option>
                        <option value="draft"<?php selected($status_filter, 'draft'); ?>>Draft</option>
                        <option value="issued"<?php selected($status_filter, 'issued'); ?>>Issued</option>
                        <option value="sent"<?php selected($status_filter, 'sent'); ?>>Sent</option>
                        <option value="paid"<?php selected($status_filter, 'paid'); ?>>Paid</option>
                        <option value="void"<?php selected($status_filter, 'void'); ?>>Void</option>
                    </select>
                </label>
                <label style="display:flex;flex-direction:column;gap:4px;">
                    <span>Month</span>
                    <input type="month" name="cmn_invoice_month" value="<?php echo esc_attr($month_filter); ?>">
                </label>
                <label style="display:flex;flex-direction:column;gap:4px;min-width:260px;">
                    <span>School (search/select)</span>
                    <input type="text" name="cmn_invoice_school" value="<?php echo esc_attr($school_filter); ?>" list="cmn-invoice-schools" placeholder="School name or ID">
                    <datalist id="cmn-invoice-schools">
                        <?php foreach ((array) $school_filter_options as $opt) : ?>
                            <option value="<?php echo esc_attr((string) ($opt['school_name'] ?? '')); ?>"></option>
                            <option value="<?php echo esc_attr((string) ($opt['school_id'] ?? 0)); ?>"></option>
                        <?php endforeach; ?>
                    </datalist>
                </label>
                <button class="cmn-primary" type="submit">Filter</button>
                <a class="cmn-ghost" href="<?php echo esc_url(add_query_arg(['view' => 'invoicing'], $portal_url)); ?>">Clear</a>
            </form>
        </div>
        <div class="cmn-dashboard-card" style="margin-bottom:16px;">
            <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-inline" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;">
                <?php wp_nonce_field('cmn_generate_monthly_invoices', 'cmn_generate_monthly_invoices_nonce'); ?>
                <input type="hidden" name="action" value="cmn_generate_monthly_invoices">
                <label style="display:flex;flex-direction:column;gap:4px;">
                    <span>Generate month</span>
                    <input type="month" name="cmn_invoice_month" value="<?php echo esc_attr($generator_month); ?>" required>
                </label>
                <button class="cmn-primary" type="submit">Run Monthly Generator</button>
            </form>
            <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-inline" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-top:10px;">
                <?php wp_nonce_field('cmn_run_monthly_invoice_job_now', 'cmn_run_monthly_invoice_job_now_nonce'); ?>
                <input type="hidden" name="action" value="cmn_run_monthly_invoice_job_now">
                <button class="cmn-ghost" type="submit">Run monthly invoice job now (previous month: <?php echo esc_html($scheduled_month_label); ?>)</button>
            </form>
            <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-inline" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-top:10px;">
                <?php wp_nonce_field('cmn_run_candidate_rewards_reset_now', 'cmn_run_candidate_rewards_reset_now_nonce'); ?>
                <input type="hidden" name="action" value="cmn_run_candidate_rewards_reset_now">
                <button class="cmn-ghost" type="submit">Run candidate rewards annual reset now (academic year: <?php echo esc_html($candidate_rewards_reset_to); ?>)</button>
            </form>
            <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-inline" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-top:10px;">
                <?php wp_nonce_field('cmn_run_rewards_payroll_addon_processor', 'cmn_run_rewards_payroll_addon_processor_nonce'); ?>
                <input type="hidden" name="action" value="cmn_run_rewards_payroll_addon_processor">
                <input type="hidden" name="cmn_return_url" value="<?php echo esc_attr((string) $build_url([])); ?>">
                <label style="display:flex;flex-direction:column;gap:4px;">
                    <span>Rewards payroll add-on week</span>
                    <input type="date" name="cmn_payroll_week_start" value="<?php echo esc_attr($payroll_week_start); ?>" required>
                </label>
                <button class="cmn-ghost" type="submit">Run rewards payroll add-on processor (week: <?php echo esc_html($payroll_week_label); ?>)</button>
            </form>
            <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-inline" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-top:10px;">
                <?php wp_nonce_field('cmn_mark_rewards_addons_processed', 'cmn_mark_rewards_addons_processed_nonce'); ?>
                <input type="hidden" name="action" value="cmn_mark_rewards_addons_processed">
                <input type="hidden" name="cmn_return_url" value="<?php echo esc_attr((string) $build_url([])); ?>">
                <label style="display:flex;flex-direction:column;gap:4px;">
                    <span>Mark processed week</span>
                    <input type="date" name="cmn_payroll_week_start" value="<?php echo esc_attr($payroll_week_start); ?>" required>
                </label>
                <button class="cmn-ghost" type="submit">Mark rewards add-ons processed (week: <?php echo esc_html($payroll_week_label); ?>)</button>
            </form>
        </div>
        <div class="cmn-portal-grid" style="align-items:start;">
            <div class="cmn-dashboard-card">
                <h3>Invoices - <?php echo esc_html($month_label); ?></h3>
                <p class="cmn-muted"><?php echo esc_html((string) $total_rows); ?> invoice(s) found.</p>
                <?php if (!$invoice_rows) : ?>
                    <div class="cmn-empty">No invoices match the current filters.</div>
                <?php else : ?>
                    <table class="cmn-approval-table">
                        <thead>
                            <tr>
                                <th>Invoice</th>
                                <th>School</th>
                                <th>Period</th>
                                <th>Status</th>
                                <th>Subtotal</th>
                                <th>Adjustments</th>
                                <th>Total (GBP)</th>
                                <th>Created</th>
                            </tr>
                        </thead>
                        <tbody>
                            <?php foreach ((array) $invoice_rows as $invoice_row) : ?>
                                <?php
                                $invoice_id = (int) ($invoice_row['id'] ?? 0);
                                $school_name = $this->get_invoice_school_display_name(
                                    (int) ($invoice_row['school_id'] ?? 0),
                                    (string) ($invoice_row['school_name'] ?? '')
                                );
                                $status = (string) ($invoice_row['status'] ?? 'draft');
                                $row_link = $build_url([
                                    'cmn_invoice_id' => $invoice_id,
                                    'cmn_invoice_page' => $current_page,
                                ]);
                                $created_at = (string) ($invoice_row['created_at'] ?? '');
                                $created_label = $created_at !== '' ? date_i18n('M j, Y', strtotime($created_at)) : '-';
                                ?>
                                <tr>
                                    <td><a href="<?php echo esc_url($row_link); ?>"><?php echo esc_html((string) ($invoice_row['invoice_number'] ?? ('INV-' . $invoice_id))); ?></a></td>
                                    <td><?php echo esc_html($school_name); ?></td>
                                    <td><?php echo esc_html((string) ($invoice_row['period_start'] ?? '') . ' -> ' . (string) ($invoice_row['period_end'] ?? '')); ?></td>
                                    <td><span class="cmn-status-chip <?php echo esc_attr($this->get_invoice_status_chip_class($status)); ?>"><?php echo esc_html($this->get_invoice_status_label($status)); ?></span></td>
                                    <td><?php echo esc_html(number_format((float) ($invoice_row['subtotal'] ?? 0), 2)); ?></td>
                                    <td><?php echo esc_html(number_format((float) ($invoice_row['adjustments_total'] ?? 0), 2)); ?></td>
                                    <td><?php echo esc_html(number_format((float) ($invoice_row['total'] ?? 0), 2)); ?></td>
                                    <td><?php echo esc_html($created_label); ?></td>
                                </tr>
                            <?php endforeach; ?>
                        </tbody>
                    </table>
                <?php endif; ?>
                <?php if ($total_pages > 1) : ?>
                    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;">
                        <?php
                        $prev_page = max(1, $current_page - 1);
                        $next_page = min($total_pages, $current_page + 1);
                        ?>
                        <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_invoice_page' => $prev_page, 'cmn_invoice_id' => null])); ?>">Prev</a>
                        <?php for ($p = 1; $p <= $total_pages; $p++) : ?>
                            <a class="cmn-ghost<?php echo $p === $current_page ? ' is-active' : ''; ?>" href="<?php echo esc_url($build_url(['cmn_invoice_page' => $p, 'cmn_invoice_id' => null])); ?>"><?php echo esc_html((string) $p); ?></a>
                        <?php endfor; ?>
                        <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_invoice_page' => $next_page, 'cmn_invoice_id' => null])); ?>">Next</a>
                    </div>
                <?php endif; ?>
            </div>
            <div class="cmn-dashboard-card">
                <h3>Invoice detail</h3>
                <?php if ($invoice_view_error !== '') : ?>
                    <div class="cmn-empty"><?php echo esc_html($invoice_view_error); ?></div>
                <?php elseif (!$selected_invoice) : ?>
                    <div class="cmn-empty">Select an invoice from the list to view details.</div>
                <?php else : ?>
                    <?php
