    private function get_staff_candidate_rewards_conduct_chip_class($status) {
        $status = $this->normalize_candidate_rewards_conduct_status((string) $status);
        if ($status === 'yellow') {
            return 'is-pending';
        }
        if ($status === 'red' || $status === 'terminated') {
            return 'is-declined';
        }
        return 'is-verified';
    }

    private function get_staff_candidate_rewards_timeline_event_types() {
        return [
            'shift_completed',
            'no_show_confirmed',
            'no_show_reversed',
            'penalty_applied',
            'penalty_reversed',
            'probation_shift_completed',
            'probation_reset',
            'rewards_reinstated',
            'rewards_reinstated_override',
            'tier_updated',
            'bonus_triggered',
            'cycle_reset',
            'bonus_included_in_payroll',
            'bonus_paid',
            'review_required',
            'candidate_terminated',
            'termination_reversed',
            'recalculated',
        ];
    }

    private function get_staff_candidate_rewards_event_meta_snippet($meta_raw, $max_length = 220) {
        $meta = $this->decode_candidate_rewards_event_meta($meta_raw);
        if (!$meta) {
            return '—';
        }
        $json = wp_json_encode($meta, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        if (!is_string($json) || $json === '') {
            return '—';
        }
        $max_length = max(80, (int) $max_length);
        if (strlen($json) > $max_length) {
            return substr($json, 0, $max_length) . '...';
        }
        return $json;
    }

    private function get_staff_candidate_rewards_year_options($candidate_id) {
        $candidate_id = (int) $candidate_id;
        $current_year = $this->normalize_candidate_rewards_academic_year_label('', current_time('Y-m-d'));
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return [$current_year];
        }

        global $wpdb;
        $table = $this->get_candidate_rewards_table();
        $rows = $wpdb->get_col($wpdb->prepare(
            "SELECT academic_year
             FROM {$table}
             WHERE candidate_id = %d
             ORDER BY academic_year DESC",
            $candidate_id
        ));
        $years = [];
        foreach ((array) $rows as $academic_year) {
            $normalized = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, current_time('Y-m-d'));
            if ($normalized !== '') {
                $years[] = $normalized;
            }
        }
        if (!in_array($current_year, $years, true)) {
            $years[] = $current_year;
        }
        $years = array_values(array_unique($years));
        rsort($years, SORT_STRING);
        return $years ?: [$current_year];
    }

    private function get_staff_candidate_rewards_list_results($filters = []) {
        $filters = is_array($filters) ? $filters : [];
        $academic_year = $this->normalize_candidate_rewards_academic_year_label(
            (string) ($filters['academic_year'] ?? ''),
            current_time('Y-m-d')
        );
        $search_filter = sanitize_text_field((string) ($filters['search'] ?? ''));
        $page = max(1, (int) ($filters['page'] ?? 1));
        $per_page = max(10, min(100, (int) ($filters['per_page'] ?? 25)));
        $offset = ($page - 1) * $per_page;

        global $wpdb;
        $posts_table = $wpdb->posts;
        $postmeta_table = $wpdb->postmeta;
        $rewards_table = $this->get_candidate_rewards_table();
        $payouts_table = $this->get_candidate_reward_payouts_table();

        $where = [
            'p.post_type = %s',
            "p.post_status IN ('publish','private','draft','pending','future')",
        ];
        $params = ['cmn_candidate'];
        if ($search_filter !== '') {
            $search_like = '%' . $wpdb->esc_like($search_filter) . '%';
            if (ctype_digit($search_filter)) {
                $where[] = '(p.ID = %d OR p.post_title LIKE %s OR COALESCE(em.email, \'\') LIKE %s OR CAST(COALESCE(uid.user_id_meta, \'0\') AS UNSIGNED) = %d)';
                $params[] = (int) $search_filter;
                $params[] = $search_like;
                $params[] = $search_like;
                $params[] = (int) $search_filter;
            } else {
                $where[] = '(p.post_title LIKE %s OR COALESCE(em.email, \'\') LIKE %s)';
                $params[] = $search_like;
                $params[] = $search_like;
            }
        }
        $where_sql = implode(' AND ', $where);

        $count_sql = "SELECT COUNT(*)
                      FROM {$posts_table} p
                      LEFT JOIN (
                          SELECT pm.post_id, MAX(pm.meta_value) AS email
                          FROM {$postmeta_table} pm
                          WHERE pm.meta_key = 'cmn_email'
                          GROUP BY pm.post_id
                      ) em ON em.post_id = p.ID
                      LEFT JOIN (
                          SELECT pm.post_id, MAX(pm.meta_value) AS user_id_meta
                          FROM {$postmeta_table} pm
                          WHERE pm.meta_key = 'cmn_user_id'
                          GROUP BY pm.post_id
                      ) uid ON uid.post_id = p.ID
                      WHERE {$where_sql}";
        $count_query = $wpdb->prepare($count_sql, ...$params);
        $total_rows = (int) $wpdb->get_var($count_query);

        $list_sql = "SELECT
                        p.ID AS candidate_id,
                        p.post_title AS candidate_name,
                        COALESCE(em.email, '') AS candidate_email,
                        CAST(COALESCE(uid.user_id_meta, '0') AS UNSIGNED) AS candidate_user_id,
                        COALESCE(cr.conduct_status, 'clear') AS conduct_status,
                        COALESCE(cr.tier, 'standard') AS tier,
                        COALESCE(cr.multiplier, 0) AS multiplier,
                        COALESCE(cr.shift_cycle_count, 0) AS shift_cycle_count,
                        COALESCE(cr.academic_year_shift_total, 0) AS academic_year_shift_total,
                        COALESCE(cr.no_show_count, 0) AS no_show_count,
                        COALESCE(cr.rewards_paused, 0) AS rewards_paused,
                        COALESCE(lp.status, '') AS last_payout_status,
                        lp.payroll_week_start AS last_payout_week_start,
                        lp.created_at AS last_payout_created_at
                    FROM {$posts_table} p
                    LEFT JOIN (
                        SELECT pm.post_id, MAX(pm.meta_value) AS email
                        FROM {$postmeta_table} pm
                        WHERE pm.meta_key = 'cmn_email'
                        GROUP BY pm.post_id
                    ) em ON em.post_id = p.ID
                    LEFT JOIN (
                        SELECT pm.post_id, MAX(pm.meta_value) AS user_id_meta
                        FROM {$postmeta_table} pm
                        WHERE pm.meta_key = 'cmn_user_id'
                        GROUP BY pm.post_id
                    ) uid ON uid.post_id = p.ID
                    LEFT JOIN {$rewards_table} cr
                        ON cr.candidate_id = p.ID
                       AND cr.academic_year = %s
                    LEFT JOIN (
                        SELECT pr.candidate_id, pr.status, pr.payroll_week_start, pr.created_at
                        FROM {$payouts_table} pr
                        INNER JOIN (
                            SELECT candidate_id, MAX(id) AS max_id
                            FROM {$payouts_table}
                            GROUP BY candidate_id
                        ) latest ON latest.max_id = pr.id
                    ) lp ON lp.candidate_id = p.ID
                    WHERE {$where_sql}
                    ORDER BY p.post_title ASC, p.ID DESC
                    LIMIT %d OFFSET %d";
        $list_params = array_merge([$academic_year], $params, [$per_page, $offset]);
        $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
        if (!is_array($rows)) {
            $rows = [];
        }
        foreach ($rows as &$row) {
            $tier = $this->normalize_candidate_rewards_tier((string) ($row['tier'] ?? 'standard'));
            $multiplier = round((float) ($row['multiplier'] ?? 0), 2);
            if ($multiplier <= 0) {
                $multiplier = $this->get_candidate_rewards_multiplier_for_tier($tier);
            }
            $row['tier'] = $tier;
            $row['multiplier'] = $multiplier;
            $row['candidate_user_id'] = max(0, (int) ($row['candidate_user_id'] ?? 0));
            $row['conduct_status'] = $this->normalize_candidate_rewards_conduct_status((string) ($row['conduct_status'] ?? 'clear'));
            $row['shift_cycle_count'] = (int) ($row['shift_cycle_count'] ?? 0);
            $row['academic_year_shift_total'] = max(0, (int) ($row['academic_year_shift_total'] ?? 0));
            $row['no_show_count'] = max(0, (int) ($row['no_show_count'] ?? 0));
            $row['rewards_paused'] = !empty($row['rewards_paused']) ? 1 : 0;
            $last_payout_status = sanitize_key((string) ($row['last_payout_status'] ?? ''));
            if ($last_payout_status !== '') {
                $last_payout_status = $this->normalize_candidate_rewards_payout_status($last_payout_status);
            }
            $row['last_payout_status'] = $last_payout_status;
            $row['last_payout_week_start'] = $this->normalize_invoice_date((string) ($row['last_payout_week_start'] ?? ''));
            $row['last_payout_created_at'] = sanitize_text_field((string) ($row['last_payout_created_at'] ?? ''));
        }
        unset($row);

        $total_pages = (int) max(1, ceil($total_rows / max(1, $per_page)));
        if ($page > $total_pages && $total_pages > 0) {
            $page = $total_pages;
            $offset = ($page - 1) * $per_page;
            $list_params = array_merge([$academic_year], $params, [$per_page, $offset]);
            $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
            if (!is_array($rows)) {
                $rows = [];
            }
        }

        return [
            'rows' => $rows,
            'total_rows' => $total_rows,
            'page' => $page,
            'per_page' => $per_page,
            'total_pages' => $total_pages,
            'academic_year' => $academic_year,
            'search_filter' => $search_filter,
        ];
    }

    private function get_staff_candidate_rewards_timeline_results($candidate_id, $academic_year, $page = 1, $per_page = 30) {
        $candidate_id = (int) $candidate_id;
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, current_time('Y-m-d'));
        $page = max(1, (int) $page);
        $per_page = max(10, min(100, (int) $per_page));
        $offset = ($page - 1) * $per_page;
        $types = (array) $this->get_staff_candidate_rewards_timeline_event_types();
        if ($candidate_id < 1 || !$types) {
            return [
                'rows' => [],
                'total_rows' => 0,
                'page' => 1,
                'per_page' => $per_page,
                'total_pages' => 1,
                'academic_year' => $academic_year,
            ];
        }

        $bounds = $this->get_candidate_rewards_academic_year_bounds($academic_year);
        $start_date = (string) ($bounds['start_date'] ?? '');
        $end_date = (string) ($bounds['end_date'] ?? '');
        if ($start_date === '' || $end_date === '') {
            return [
                'rows' => [],
                'total_rows' => 0,
                'page' => 1,
                'per_page' => $per_page,
                'total_pages' => 1,
                'academic_year' => $academic_year,
            ];
        }

        global $wpdb;
        $events_table = $this->get_candidate_rewards_events_table();
        $type_placeholders = implode(',', array_fill(0, count($types), '%s'));

        $count_sql = "SELECT COUNT(*)
                      FROM {$events_table}
                      WHERE candidate_id = %d
                        AND shift_date >= %s
                        AND shift_date <= %s
                        AND event_type IN ({$type_placeholders})";
        $count_params = array_merge([$candidate_id, $start_date, $end_date], $types);
        $total_rows = (int) $wpdb->get_var($wpdb->prepare($count_sql, ...$count_params));

        $list_sql = "SELECT
                        id,
                        candidate_id,
                        booking_id,
                        shift_date,
                        event_type,
                        delta_cycle,
                        delta_year_total,
                        meta,
                        created_by_user_id,
                        created_at
                     FROM {$events_table}
                     WHERE candidate_id = %d
                       AND shift_date >= %s
                       AND shift_date <= %s
                       AND event_type IN ({$type_placeholders})
                     ORDER BY shift_date DESC, id DESC
                     LIMIT %d OFFSET %d";
        $list_params = array_merge([$candidate_id, $start_date, $end_date], $types, [$per_page, $offset]);
        $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
        if (!is_array($rows)) {
            $rows = [];
        }
        foreach ($rows as &$row) {
            $event_type = sanitize_key((string) ($row['event_type'] ?? ''));
            $row['event_type'] = $event_type;
            $row['event_label'] = $this->get_candidate_rewards_event_label($event_type);
            $row['summary'] = $this->build_candidate_rewards_event_summary($row);
            $row['booking_id'] = max(0, (int) ($row['booking_id'] ?? 0));
            $row['shift_date'] = $this->normalize_invoice_date((string) ($row['shift_date'] ?? ''));
            $row['created_by_user_id'] = max(0, (int) ($row['created_by_user_id'] ?? 0));
            $row['created_at'] = sanitize_text_field((string) ($row['created_at'] ?? ''));
            $row['meta_snippet'] = $this->get_staff_candidate_rewards_event_meta_snippet((string) ($row['meta'] ?? ''));
        }
        unset($row);

        $total_pages = (int) max(1, ceil($total_rows / max(1, $per_page)));
        if ($page > $total_pages && $total_pages > 0) {
            $page = $total_pages;
            $offset = ($page - 1) * $per_page;
            $list_params = array_merge([$candidate_id, $start_date, $end_date], $types, [$per_page, $offset]);
            $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
            if (!is_array($rows)) {
                $rows = [];
            }
        }

        return [
            'rows' => $rows,
            'total_rows' => $total_rows,
            'page' => $page,
            'per_page' => $per_page,
            'total_pages' => $total_pages,
            'academic_year' => $academic_year,
            'start_date' => $start_date,
            'end_date' => $end_date,
        ];
    }

    private function get_staff_candidate_rewards_payout_rows($candidate_id, $academic_year, $limit = 10) {
        $candidate_id = (int) $candidate_id;
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, current_time('Y-m-d'));
        $limit = max(1, min(50, (int) $limit));
        if ($candidate_id < 1) {
            return [];
        }
        $rows = $this->get_candidate_reward_payouts($candidate_id, $academic_year, $limit);
        if (!$rows) {
            return [];
        }
        foreach ($rows as &$row) {
            $row['bonus_amount'] = round((float) ($row['bonus_amount'] ?? 0), 2);
            $row['multiplier_applied'] = round((float) ($row['multiplier_applied'] ?? 1.00), 2);
            $row['status'] = $this->normalize_candidate_rewards_payout_status((string) ($row['status'] ?? 'queued'));
            $row['status_label'] = ucfirst((string) ($row['status'] ?? 'queued'));
            $row['payroll_week_start'] = $this->normalize_invoice_date((string) ($row['payroll_week_start'] ?? ''));
            $row['created_at'] = sanitize_text_field((string) ($row['created_at'] ?? ''));
        }
        unset($row);
        return $rows;
    }

    private function get_staff_candidate_rewards_shift_adjust_limit($user_id = 0) {
        $user_id = max(0, (int) $user_id);
        $default_limit = 10;
        $resolved_limit = (int) apply_filters('cmn_rewards_staff_shift_adjustment_limit', $default_limit, $user_id);
        if ($resolved_limit < 1) {
            $resolved_limit = $default_limit;
        }
        return $resolved_limit;
    }

    private function resolve_staff_candidate_rewards_row_status(array $row = []) {
        $status = sanitize_key((string) ($row['status'] ?? ''));
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($row['conduct_status'] ?? 'clear'));
        $is_paused = !empty($row['rewards_paused']) && (int) ($row['rewards_paused'] ?? 0) === 1;
        if ($status === 'terminated' || $conduct_status === 'terminated') {
            return 'terminated';
        }
        if ($status === 'rewards_suspended' || $is_paused) {
            return 'rewards_suspended';
        }
        return 'active';
    }

    private function get_staff_candidate_rewards_status_label($status) {
        $status = sanitize_key((string) $status);
        if ($status === 'rewards_suspended') {
            return 'Suspended';
        }
        if ($status === 'terminated') {
            return 'Terminated';
        }
        return 'Active';
    }

    private function resolve_staff_candidate_rewards_candidate_user_id($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Candidate not found.');
        }
        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            return new WP_Error('cmn_candidate_rewards_missing_candidate_user', 'Candidate does not have an attached user account.');
        }
        $user = get_user_by('id', $candidate_user_id);
        if (!$user instanceof WP_User) {
            return new WP_Error('cmn_candidate_rewards_missing_candidate_user', 'Candidate user account not found.');
        }
        return $candidate_user_id;
    }

    private function assert_staff_candidate_rewards_mutation_capability(array $context = []) {
        if (!is_user_logged_in()) {
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }
        $user_id = (int) get_current_user_id();
        if (function_exists('cmn_require_ability')) {
            $check = cmn_require_ability('rewards.mutate_any', $context);
            if (is_wp_error($check)) {
                return $check;
            }
        } elseif (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }
        return [
            'user_id' => $user_id,
            'is_admin' => $this->is_admin_user($user_id),
        ];
    }

    private function get_staff_candidate_rewards_bonus_and_ticket_summary($candidate_user_id, $academic_year) {
        $candidate_user_id = max(0, (int) $candidate_user_id);
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, current_time('Y-m-d'));
        $portal_label = $this->normalize_rewards_config_year_label($academic_year, current_time('Y-m-d'));
        if ($portal_label === '') {
            $portal_label = $this->normalize_rewards_config_year_label('', current_time('Y-m-d'));
        }
        $summary = [
            'academic_year_label' => $portal_label,
            'last_bonus_amount' => 0.00,
            'last_bonus_awarded_at' => '',
            'last_bonus_awarded_at_label' => 'Not yet awarded',
            'referral_tickets' => 0,
        ];
        if ($candidate_user_id < 1 || $portal_label === '') {
            return $summary;
        }

        $awards_table = $this->get_candidate_bonus_awards_table();
        if ($this->candidate_rewards_table_exists($awards_table)) {
            global $wpdb;
            $award_row = $wpdb->get_row($wpdb->prepare(
                "SELECT bonus_amount, awarded_at
                 FROM {$awards_table}
                 WHERE candidate_user_id = %d
                   AND academic_year_label = %s
                 ORDER BY block_index DESC, awarded_at DESC
                 LIMIT 1",
                $candidate_user_id,
                $portal_label
            ), ARRAY_A);
            if (is_array($award_row) && $award_row) {
                $summary['last_bonus_amount'] = round((float) ($award_row['bonus_amount'] ?? 0), 2);
                $summary['last_bonus_awarded_at'] = $this->normalize_invoice_datetime((string) ($award_row['awarded_at'] ?? ''));
                if ($summary['last_bonus_awarded_at'] !== '' && strtotime((string) $summary['last_bonus_awarded_at']) !== false) {
                    $summary['last_bonus_awarded_at_label'] = date_i18n('j M Y', strtotime((string) $summary['last_bonus_awarded_at']));
                }
            }
        }

        if (function_exists('cmn_referrals_get_ticket_count')) {
            $summary['referral_tickets'] = max(0, (int) cmn_referrals_get_ticket_count($candidate_user_id, $portal_label));
        } else {
            $tickets_table = $this->get_candidate_referral_tickets_table();
            if ($this->candidate_rewards_table_exists($tickets_table)) {
                global $wpdb;
                $summary['referral_tickets'] = max(0, (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*)
                     FROM {$tickets_table}
                     WHERE candidate_user_id = %d
                       AND academic_year_label = %s",
                    $candidate_user_id,
                    $portal_label
                )));
            }
        }

        return $summary;
    }

    private function log_staff_candidate_rewards_override_audit($event_type, $candidate_user_id, $actor_user_id, array $metadata = []) {
        $event_type = sanitize_key((string) $event_type);
        $candidate_user_id = max(0, (int) $candidate_user_id);
        $actor_user_id = max(0, (int) $actor_user_id);
        if ($event_type === '' || $candidate_user_id < 1 || !function_exists('cmn_audit_log_event')) {
            return;
        }

        cmn_audit_log_event([
            'module' => 'rewards',
            'entity_type' => 'candidate',
            'entity_id' => $candidate_user_id,
            'event_type' => $event_type,
            'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
            'metadata' => is_array($metadata) ? $metadata : [],
        ]);
    }

    private function redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $message, $message_type = 'success') {
        $candidate_id = max(0, (int) $candidate_id);
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, current_time('Y-m-d'));
        $return_url = $this->get_candidate_rewards_staff_portal_return_url((string) $return_url);
        $message = sanitize_text_field((string) $message);
        $message_type = sanitize_key((string) $message_type);
        if (!in_array($message_type, ['success', 'error', 'warning'], true)) {
            $message_type = 'success';
        }

        $redirect = add_query_arg([
            'cmn_rewards_candidate_id' => $candidate_id > 0 ? $candidate_id : null,
            'cmn_rewards_year' => $academic_year !== '' ? $academic_year : null,
            'cmn_rewards_msg' => rawurlencode($message),
            'cmn_rewards_msg_type' => $message_type,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    private function run_staff_candidate_rewards_recalculation($candidate_id, $academic_year, $reason = '', $actor_user_id = 0, $source = 'staff_console_recalculate') {
        $candidate_id = (int) $candidate_id;
        $actor_user_id = (int) ($actor_user_id ?: get_current_user_id());
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, current_time('Y-m-d'));
        $reason = sanitize_textarea_field((string) $reason);
        $source = sanitize_key((string) $source);
        if ($source === '') {
            $source = 'staff_console_recalculate';
        }
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Candidate not found.');
        }

        $before = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($before)) {
            return $before;
        }
        $before = is_array($before) ? $before : [];

        $resolved = $this->cmn_candidate_rewards_resolve_tier((int) ($before['academic_year_shift_total'] ?? 0));
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($before['conduct_status'] ?? 'clear'));
        $rewards_paused = in_array($conduct_status, ['yellow', 'red', 'terminated'], true) ? 1 : 0;
        $probation_count = max(0, (int) ($before['probation_consecutive_shifts'] ?? 0));
        if ($conduct_status === 'clear' || $conduct_status === 'terminated') {
            $probation_count = 0;
        }
        if ($probation_count > 10) {
            $probation_count = 10;
        }

        $after = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'tier' => (string) ($resolved['tier'] ?? 'standard'),
            'multiplier' => (float) ($resolved['multiplier'] ?? 1.00),
            'rewards_paused' => $rewards_paused,
            'probation_consecutive_shifts' => $probation_count,
        ]);
        if (is_wp_error($after)) {
            return $after;
        }
        $after = is_array($after) ? $after : [];

        $event_insert = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => 0,
            'shift_date' => current_time('Y-m-d'),
            'event_type' => 'recalculated',
            'delta_cycle' => 0,
            'delta_year_total' => 0,
            'meta' => [
                'reason' => $reason,
                'source' => $source,
                'academic_year' => $academic_year,
                'before' => [
                    'tier' => (string) ($before['tier'] ?? 'standard'),
                    'multiplier' => round((float) ($before['multiplier'] ?? 1.00), 2),
                    'conduct_status' => (string) ($before['conduct_status'] ?? 'clear'),
                    'rewards_paused' => !empty($before['rewards_paused']) ? 1 : 0,
                    'probation_consecutive_shifts' => max(0, (int) ($before['probation_consecutive_shifts'] ?? 0)),
                ],
                'after' => [
                    'tier' => (string) ($after['tier'] ?? 'standard'),
                    'multiplier' => round((float) ($after['multiplier'] ?? 1.00), 2),
                    'conduct_status' => (string) ($after['conduct_status'] ?? 'clear'),
                    'rewards_paused' => !empty($after['rewards_paused']) ? 1 : 0,
                    'probation_consecutive_shifts' => max(0, (int) ($after['probation_consecutive_shifts'] ?? 0)),
                ],
            ],
            'created_by_user_id' => $actor_user_id,
        ]);
        if (is_wp_error($event_insert)) {
            return $event_insert;
        }

        $this->add_audit_log('candidate_rewards_staff_recalculated', 'candidate', (string) $candidate_id, [
            'academic_year' => $academic_year,
            'reason' => $reason,
            'source' => $source,
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
        ], $actor_user_id);

        return [
            'candidate_id' => $candidate_id,
            'academic_year' => $academic_year,
            'before' => $before,
            'after' => $after,
            'event' => $event_insert,
        ];
    }

    private function flag_staff_candidate_rewards_for_review($candidate_id, $academic_year, $reason = '', $actor_user_id = 0, $source = 'staff_console_flag_review') {
        $candidate_id = (int) $candidate_id;
        $actor_user_id = (int) ($actor_user_id ?: get_current_user_id());
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, current_time('Y-m-d'));
        $reason = sanitize_textarea_field((string) $reason);
        $source = sanitize_key((string) $source);
        if ($source === '') {
            $source = 'staff_console_flag_review';
        }
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Candidate not found.');
        }

        $before = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($before)) {
            return $before;
        }
        $before = is_array($before) ? $before : [];
        $previous_status = $this->normalize_candidate_rewards_conduct_status((string) ($before['conduct_status'] ?? 'clear'));
        if ($previous_status === 'terminated') {
            return new WP_Error('cmn_candidate_rewards_terminated', 'Candidate is already terminated.');
        }

        $probation_count = max(0, (int) ($before['probation_consecutive_shifts'] ?? 0));
        if (!in_array($previous_status, ['yellow', 'red'], true)) {
            $probation_count = 0;
        }
        if ($probation_count > 10) {
            $probation_count = 10;
        }

        $after = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'conduct_status' => 'red',
            'rewards_paused' => 1,
            'review_required' => 1,
            'probation_consecutive_shifts' => $probation_count,
        ]);
        if (is_wp_error($after)) {
            return $after;
        }
        $after = is_array($after) ? $after : [];

        $event_insert = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => 0,
            'shift_date' => current_time('Y-m-d'),
            'event_type' => 'review_required',
            'delta_cycle' => 0,
            'delta_year_total' => 0,
            'meta' => [
                'reason' => $reason,
                'source' => $source,
                'academic_year' => $academic_year,
                'previous_status' => $previous_status,
            ],
            'created_by_user_id' => $actor_user_id,
        ]);
        if (is_wp_error($event_insert)) {
            return $event_insert;
        }

        $this->add_audit_log('candidate_rewards_staff_review_flagged', 'candidate', (string) $candidate_id, [
            'academic_year' => $academic_year,
            'reason' => $reason,
            'source' => $source,
            'previous_status' => $previous_status,
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
        ], $actor_user_id);

        return [
            'candidate_id' => $candidate_id,
            'academic_year' => $academic_year,
            'before' => $before,
            'after' => $after,
            'event' => $event_insert,
        ];
    }

    private function terminate_staff_candidate_rewards($candidate_id, $academic_year, $reason = '', $actor_user_id = 0, $source = 'staff_console_terminate') {
        $candidate_id = (int) $candidate_id;
        $actor_user_id = (int) ($actor_user_id ?: get_current_user_id());
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, current_time('Y-m-d'));
        $reason = sanitize_textarea_field((string) $reason);
        $source = sanitize_key((string) $source);
        if ($source === '') {
            $source = 'staff_console_terminate';
        }
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Candidate not found.');
        }

        $before = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($before)) {
            return $before;
        }
        $before = is_array($before) ? $before : [];

        $after = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'conduct_status' => 'terminated',
            'rewards_paused' => 1,
            'review_required' => 1,
            'probation_consecutive_shifts' => 0,
        ]);
        if (is_wp_error($after)) {
            return $after;
        }
        $after = is_array($after) ? $after : [];

        $access_result = $this->disable_candidate_portal_access_for_rewards($candidate_id, [
            'actor_user_id' => $actor_user_id,
            'reason' => $reason !== '' ? $reason : 'Terminated by staff action from Candidate Rewards panel.',
        ]);
        $event_insert = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => 0,
            'shift_date' => current_time('Y-m-d'),
            'event_type' => 'candidate_terminated',
            'delta_cycle' => 0,
            'delta_year_total' => 0,
            'meta' => [
                'reason' => $reason,
                'source' => $source,
                'academic_year' => $academic_year,
                'access_disabled' => !empty($access_result['disabled']) ? 1 : 0,
                'disabled_user_id' => (int) ($access_result['user_id'] ?? 0),
                'disable_message' => sanitize_text_field((string) ($access_result['message'] ?? '')),
            ],
            'created_by_user_id' => $actor_user_id,
        ]);
        if (is_wp_error($event_insert)) {
            return $event_insert;
        }

        $this->add_audit_log('candidate_rewards_staff_terminated', 'candidate', (string) $candidate_id, [
            'academic_year' => $academic_year,
            'reason' => $reason,
            'source' => $source,
            'access_disabled' => !empty($access_result['disabled']) ? 1 : 0,
            'disabled_user_id' => (int) ($access_result['user_id'] ?? 0),
            'disable_message' => sanitize_text_field((string) ($access_result['message'] ?? '')),
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
        ], $actor_user_id);

        return [
            'candidate_id' => $candidate_id,
            'academic_year' => $academic_year,
            'before' => $before,
            'after' => $after,
            'event' => $event_insert,
            'access_result' => $access_result,
        ];
    }

    public function render_staff_candidate_rewards_shortcode() {
        if (!is_user_logged_in()) {
            return $this->render_login_shortcode();
        }
        $user_id = (int) get_current_user_id();
        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('rewards.mutate_any', ['entity_type' => 'candidate']);
            if (is_wp_error($ability_check)) {
                return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>Not authorised.</p></div></section>';
            }
        } elseif (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>This section is available to staff/admin only.</p></div></section>';
        }
        $can_override_no_show = $this->can_manage_candidate_rewards_no_show_overrides($user_id);

        $portal_url = $this->get_portal_base_url();
        $base_url = add_query_arg(['view' => 'candidate-rewards'], $portal_url);
        $search_filter = isset($_GET['cmn_rewards_search'])
            ? sanitize_text_field(wp_unslash((string) $_GET['cmn_rewards_search']))
            : '';
        $current_page = max(1, (int) ($_GET['cmn_rewards_page'] ?? 1));
        $selected_candidate_id = max(0, (int) ($_GET['cmn_rewards_candidate_id'] ?? 0));
        $event_page = max(1, (int) ($_GET['cmn_rewards_event_page'] ?? 1));
        $current_academic_year = $this->normalize_candidate_rewards_academic_year_label('', current_time('Y-m-d'));
        $selected_year_raw = isset($_GET['cmn_rewards_year'])
            ? sanitize_text_field(wp_unslash((string) $_GET['cmn_rewards_year']))
            : '';
        $selected_year = $selected_year_raw !== ''
            ? $this->normalize_candidate_rewards_academic_year_label($selected_year_raw, current_time('Y-m-d'))
            : $current_academic_year;
        $message = isset($_GET['cmn_rewards_msg'])
            ? sanitize_text_field(rawurldecode((string) wp_unslash((string) $_GET['cmn_rewards_msg'])))
            : '';
        $message_type = isset($_GET['cmn_rewards_msg_type'])
            ? sanitize_key(wp_unslash((string) $_GET['cmn_rewards_msg_type']))
            : 'success';
        if (!in_array($message_type, ['success', 'error', 'warning'], true)) {
            $message_type = 'success';
        }

        $list_payload = $this->get_staff_candidate_rewards_list_results([
            'academic_year' => $current_academic_year,
            'search' => $search_filter,
            'page' => $current_page,
            'per_page' => 25,
        ]);
        $rows = (array) ($list_payload['rows'] ?? []);
        $total_rows = (int) ($list_payload['total_rows'] ?? 0);
        $total_pages = (int) ($list_payload['total_pages'] ?? 1);
        $current_page = (int) ($list_payload['page'] ?? $current_page);
        $search_filter = (string) ($list_payload['search_filter'] ?? $search_filter);
        $current_academic_year = (string) ($list_payload['academic_year'] ?? $current_academic_year);

        $build_url = function ($overrides = []) use ($base_url, $search_filter, $current_page, $selected_candidate_id, $selected_year, $event_page) {
            $args = [];
            if ($search_filter !== '') {
                $args['cmn_rewards_search'] = $search_filter;
            }
            if ($current_page > 1) {
                $args['cmn_rewards_page'] = $current_page;
            }
            if ($selected_candidate_id > 0) {
                $args['cmn_rewards_candidate_id'] = $selected_candidate_id;
            }
            if ($selected_year !== '') {
                $args['cmn_rewards_year'] = $selected_year;
            }
            if ($event_page > 1) {
                $args['cmn_rewards_event_page'] = $event_page;
            }
            foreach ((array) $overrides as $key => $value) {
                if ($value === null) {
                    unset($args[$key]);
                } else {
                    $args[$key] = $value;
                }
            }
            return add_query_arg($args, $base_url);
        };

        $selected_candidate = null;
        $selected_candidate_email = '';
        $selected_candidate_user_id = 0;
        $selected_candidate_error = '';
        $year_options = [];
        $selected_rewards_row = [];
        $selected_rewards_stats = [];
        $selected_bonus_ticket_summary = [];
        $timeline_payload = [
            'rows' => [],
            'total_rows' => 0,
            'page' => 1,
            'per_page' => 30,
            'total_pages' => 1,
            'academic_year' => $selected_year,
        ];
        $timeline_actor_map = [];
        $payout_rows = [];

        if ($selected_candidate_id > 0) {
            $selected_candidate = get_post($selected_candidate_id);
            if (!$selected_candidate || $selected_candidate->post_type !== 'cmn_candidate') {
                $selected_candidate_error = 'Candidate not found.';
                $selected_candidate = null;
            } else {
                $selected_candidate_email = sanitize_text_field((string) get_post_meta($selected_candidate_id, 'cmn_email', true));
                $selected_candidate_user_id = max(0, (int) get_post_meta($selected_candidate_id, 'cmn_user_id', true));
                if ($selected_candidate_user_id < 1) {
                    $selected_candidate_user_id = max(0, (int) $this->get_candidate_user_id($selected_candidate_id));
                }
                $year_options = $this->get_staff_candidate_rewards_year_options($selected_candidate_id);
                if (!in_array($selected_year, $year_options, true)) {
                    $year_options[] = $selected_year;
                    $year_options = array_values(array_unique($year_options));
                    rsort($year_options, SORT_STRING);
                }
                $existing_row = $this->get_candidate_rewards_record($selected_candidate_id, $selected_year);
                $selected_row_result = $this->get_or_create_candidate_rewards($selected_candidate_id, $selected_year);
                if (is_wp_error($selected_row_result)) {
                    $selected_candidate_error = $selected_row_result->get_error_message();
                } else {
                    $selected_rewards_row = (array) $selected_row_result;
                    if (empty($existing_row)) {
                        $auto_event = $this->insert_candidate_rewards_event([
                            'candidate_id' => $selected_candidate_id,
                            'booking_id' => 0,
                            'shift_date' => current_time('Y-m-d'),
                            'event_type' => 'recalculated',
                            'delta_cycle' => 0,
                            'delta_year_total' => 0,
                            'meta' => [
                                'reason' => 'Initial rewards row created from staff console.',
                                'source' => 'staff_console_row_autocreate',
                                'academic_year' => $selected_year,
                            ],
                            'created_by_user_id' => $user_id,
                        ]);
                        if (!is_wp_error($auto_event)) {
                            $this->add_audit_log('candidate_rewards_staff_row_auto_created', 'candidate', (string) $selected_candidate_id, [
                                'academic_year' => $selected_year,
                                'event_id' => (int) ($auto_event['event_id'] ?? 0),
                            ], $user_id);
                        }
                    }

                    $year_bounds = $this->get_candidate_rewards_academic_year_bounds($selected_year);
                    $reference_date = (string) ($year_bounds['start_date'] ?? '');
                    if ($reference_date === '') {
                        $reference_date = current_time('Y-m-d');
                    }
                    $stats_result = $this->get_candidate_rewards_stats_payload($selected_candidate_id, [
                        'reference_date' => $reference_date,
                        'include_events' => false,
                        'payout_limit' => 5,
                    ]);
                    if (is_wp_error($stats_result)) {
                        $selected_candidate_error = $stats_result->get_error_message();
                    } else {
                        $selected_rewards_stats = (array) $stats_result;
                        $timeline_payload = $this->get_staff_candidate_rewards_timeline_results(
                            $selected_candidate_id,
                            $selected_year,
                            $event_page,
                            30
                        );
                        $timeline_rows = (array) ($timeline_payload['rows'] ?? []);
                        $actor_ids = [];
                        foreach ($timeline_rows as $timeline_row) {
                            $actor_id = (int) ($timeline_row['created_by_user_id'] ?? 0);
                            if ($actor_id > 0) {
                                $actor_ids[] = $actor_id;
                            }
                        }
                        $actor_ids = array_values(array_unique($actor_ids));
                        if ($actor_ids) {
                            $actor_users = get_users([
                                'include' => $actor_ids,
                                'fields' => ['ID', 'display_name', 'user_login'],
                            ]);
                            foreach ((array) $actor_users as $actor_user) {
                                $actor_uid = (int) ($actor_user->ID ?? 0);
                                if ($actor_uid > 0) {
                                    $timeline_actor_map[$actor_uid] = (string) ($actor_user->display_name ?: $actor_user->user_login);
                                }
                            }
                        }
                        $payout_rows = $this->get_staff_candidate_rewards_payout_rows($selected_candidate_id, $selected_year, 10);
                        if ($selected_candidate_user_id > 0) {
                            $selected_bonus_ticket_summary = $this->get_staff_candidate_rewards_bonus_and_ticket_summary($selected_candidate_user_id, $selected_year);
                        }
                    }
                }
            }
        }
        if (!$year_options && $selected_year !== '') {
            $year_options = [$selected_year];
        }

        ob_start();
        ?>
        <header class="cmn-school-header">
            <h2>Candidate Rewards</h2>
            <p>Internal oversight panel for CMN Rewards conduct, cycle progress, and payout audit trails.</p>
        </header>
        <?php if ($message !== '') : ?>
            <div class="cmn-dashboard-card" style="margin-bottom:12px;">
                <p class="<?php echo $message_type === 'error' ? 'cmn-register-error' : ($message_type === 'warning' ? 'cmn-register-warning' : 'cmn-register-success'); ?>"><?php echo esc_html($message); ?></p>
            </div>
        <?php endif; ?>

        <div class="cmn-dashboard-card" style="margin-bottom:16px;">
            <form method="get" action="<?php echo esc_url($portal_url); ?>" class="cmn-inline" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;">
                <input type="hidden" name="view" value="candidate-rewards">
                <label style="display:flex;flex-direction:column;gap:4px;min-width:280px;">
                    <span>Candidate search</span>
                    <input type="text" name="cmn_rewards_search" value="<?php echo esc_attr($search_filter); ?>" placeholder="Search by name, email, or candidate ID">
                </label>
                <button class="cmn-primary" type="submit">Search</button>
                <a class="cmn-ghost" href="<?php echo esc_url(add_query_arg(['view' => 'candidate-rewards'], $portal_url)); ?>">Clear</a>
            </form>
        </div>

        <div class="cmn-dashboard-card" style="margin-bottom:16px;">
            <h3>Candidate Rewards Overview</h3>
            <p class="cmn-muted">Academic year context: <?php echo esc_html($current_academic_year); ?> • <?php echo esc_html((string) $total_rows); ?> candidate(s) found.</p>
            <?php if (!$rows) : ?>
                <div class="cmn-empty">No candidates matched your search.</div>
            <?php else : ?>
                <table class="cmn-approval-table">
                    <thead>
                        <tr>
                            <th>Candidate</th>
                            <th>User ID</th>
                            <th>Conduct</th>
                            <th>Tier / Multiplier</th>
                            <th>Cycle count</th>
                            <th>Year shifts</th>
                            <th>No-shows</th>
                            <th>Rewards status</th>
                            <th>Last payout</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        <?php foreach ((array) $rows as $row) : ?>
                            <?php
                            $row_candidate_id = (int) ($row['candidate_id'] ?? 0);
                            $row_tier = $this->normalize_candidate_rewards_tier((string) ($row['tier'] ?? 'standard'));
                            $row_multiplier = round((float) ($row['multiplier'] ?? 1.00), 2);
                            if ($row_multiplier <= 0) {
                                $row_multiplier = $this->get_candidate_rewards_multiplier_for_tier($row_tier);
                            }
                            $row_multiplier_label = rtrim(rtrim(number_format($row_multiplier, 2, '.', ''), '0'), '.');
                            if ($row_multiplier_label === '') {
                                $row_multiplier_label = '1';
                            }
                            $row_conduct = $this->normalize_candidate_rewards_conduct_status((string) ($row['conduct_status'] ?? 'clear'));
                            $row_conduct_label = $this->get_candidate_rewards_conduct_status_label($row_conduct);
                            $row_conduct_class = $this->get_staff_candidate_rewards_conduct_chip_class($row_conduct);
                            $row_status = $this->resolve_staff_candidate_rewards_row_status((array) $row);
                            $row_status_label = $this->get_staff_candidate_rewards_status_label($row_status);
                            $row_payout_status = sanitize_key((string) ($row['last_payout_status'] ?? ''));
                            $row_payout_status_label = $row_payout_status !== '' ? ucfirst($row_payout_status) : '—';
                            $row_payout_date_label = '—';
                            $row_week_start = $this->normalize_invoice_date((string) ($row['last_payout_week_start'] ?? ''));
                            if ($row_week_start !== '' && strtotime($row_week_start) !== false) {
                                $row_payout_date_label = date_i18n('M j, Y', strtotime($row_week_start));
                            } else {
                                $row_created = sanitize_text_field((string) ($row['last_payout_created_at'] ?? ''));
                                if ($row_created !== '' && strtotime($row_created) !== false) {
                                    $row_payout_date_label = date_i18n('M j, Y', strtotime($row_created));
                                }
                            }
                            $row_link = $build_url([
                                'cmn_rewards_candidate_id' => $row_candidate_id,
                                'cmn_rewards_year' => $selected_year,
                                'cmn_rewards_event_page' => null,
                            ]);
                            ?>
                            <tr>
                                <td>
                                    <strong><?php echo esc_html((string) ($row['candidate_name'] ?? ('Candidate #' . $row_candidate_id))); ?></strong><br>
                                    <span class="cmn-muted"><?php echo esc_html((string) ($row['candidate_email'] ?? '')); ?></span><br>
                                    <span class="cmn-muted">ID #<?php echo esc_html((string) $row_candidate_id); ?></span>
                                </td>
                                <td><?php echo esc_html((string) max(0, (int) ($row['candidate_user_id'] ?? 0))); ?></td>
                                <td><span class="cmn-status-chip <?php echo esc_attr($row_conduct_class); ?>"><?php echo esc_html($row_conduct_label); ?></span></td>
                                <td><?php echo esc_html($this->get_candidate_rewards_tier_label($row_tier)); ?> • <?php echo esc_html($row_multiplier_label); ?>x</td>
                                <td><?php echo esc_html((string) ((int) ($row['shift_cycle_count'] ?? 0))); ?></td>
                                <td><?php echo esc_html((string) number_format((int) ($row['academic_year_shift_total'] ?? 0))); ?></td>
                                <td><?php echo esc_html((string) number_format((int) ($row['no_show_count'] ?? 0))); ?></td>
                                <td><?php echo esc_html($row_status_label); ?></td>
                                <td><?php echo esc_html($row_payout_status_label); ?> / <?php echo esc_html($row_payout_date_label); ?></td>
                                <td><a class="cmn-ghost cmn-btn-mini" href="<?php echo esc_url($row_link); ?>">Open</a></td>
                            </tr>
                        <?php endforeach; ?>
                    </tbody>
                </table>
            <?php endif; ?>

            <?php if ($total_pages > 1) : ?>
                <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;">
                    <?php
                    $prev_page = max(1, $current_page - 1);
                    $next_page = min($total_pages, $current_page + 1);
                    ?>
                    <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_rewards_page' => $prev_page])); ?>">Prev</a>
                    <?php for ($p = 1; $p <= $total_pages; $p++) : ?>
                        <a class="cmn-ghost<?php echo $p === $current_page ? ' is-active' : ''; ?>" href="<?php echo esc_url($build_url(['cmn_rewards_page' => $p])); ?>"><?php echo esc_html((string) $p); ?></a>
                    <?php endfor; ?>
                    <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_rewards_page' => $next_page])); ?>">Next</a>
                </div>
            <?php endif; ?>
        </div>

        <?php if ($selected_candidate_id > 0) : ?>
            <div class="cmn-dashboard-card" style="margin-bottom:16px;">
                <h3>Candidate Detail</h3>
                <?php if ($selected_candidate_error !== '') : ?>
                    <div class="cmn-empty"><?php echo esc_html($selected_candidate_error); ?></div>
                <?php else : ?>
                    <?php
                    $candidate_name = $selected_candidate ? (string) $selected_candidate->post_title : ('Candidate #' . $selected_candidate_id);
                    $tier = $this->normalize_candidate_rewards_tier((string) ($selected_rewards_stats['tier'] ?? ($selected_rewards_row['tier'] ?? 'standard')));
                    $tier_label = $this->get_candidate_rewards_tier_label($tier);
                    $multiplier = round((float) ($selected_rewards_stats['multiplier'] ?? ($selected_rewards_row['multiplier'] ?? 1.00)), 2);
                    if ($multiplier <= 0) {
                        $multiplier = $this->get_candidate_rewards_multiplier_for_tier($tier);
                    }
                    $multiplier_label = rtrim(rtrim(number_format($multiplier, 2, '.', ''), '0'), '.');
                    if ($multiplier_label === '') {
                        $multiplier_label = '1';
                    }
                    $academic_year_shift_total = max(0, (int) ($selected_rewards_stats['academic_year_shift_total'] ?? ($selected_rewards_row['academic_year_shift_total'] ?? 0)));
                    $shift_cycle_count = (int) ($selected_rewards_stats['shift_cycle_count'] ?? ($selected_rewards_row['shift_cycle_count'] ?? 0));
                    $no_show_count = max(0, (int) ($selected_rewards_stats['no_show_count'] ?? ($selected_rewards_row['no_show_count'] ?? 0)));
