                            <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_rewards_event_page' => $timeline_prev])); ?>">Prev events</a>
                            <?php for ($ep = 1; $ep <= $timeline_total_pages; $ep++) : ?>
                                <a class="cmn-ghost<?php echo $ep === $timeline_page ? ' is-active' : ''; ?>" href="<?php echo esc_url($build_url(['cmn_rewards_event_page' => $ep])); ?>"><?php echo esc_html((string) $ep); ?></a>
                            <?php endfor; ?>
                            <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_rewards_event_page' => $timeline_next])); ?>">Next events</a>
                        </div>
                    <?php endif; ?>
                </div>

                <div class="cmn-dashboard-card" style="margin-bottom:16px;">
                    <h3>Payout History</h3>
                    <?php if (!$payout_rows) : ?>
                        <div class="cmn-empty">No payouts recorded for this academic year.</div>
                    <?php else : ?>
                        <table class="cmn-approval-table">
                            <thead>
                                <tr>
                                    <th>Bonus amount</th>
                                    <th>Multiplier</th>
                                    <th>Status</th>
                                    <th>Payroll week start</th>
                                    <th>Created at</th>
                                </tr>
                            </thead>
                            <tbody>
                                <?php foreach ($payout_rows as $payout_row) : ?>
                                    <?php
                                    $bonus_amount = round((float) ($payout_row['bonus_amount'] ?? 0), 2);
                                    $payout_multiplier = round((float) ($payout_row['multiplier_applied'] ?? 1.00), 2);
                                    $payout_multiplier_label = rtrim(rtrim(number_format($payout_multiplier, 2, '.', ''), '0'), '.');
                                    if ($payout_multiplier_label === '') {
                                        $payout_multiplier_label = '1';
                                    }
                                    $payout_status = sanitize_key((string) ($payout_row['status'] ?? 'queued'));
                                    $payout_status_label = ucfirst($payout_status);
                                    $payroll_week_start = $this->normalize_invoice_date((string) ($payout_row['payroll_week_start'] ?? ''));
                                    $payroll_week_start_label = $payroll_week_start !== '' && strtotime($payroll_week_start) !== false
                                        ? date_i18n('M j, Y', strtotime($payroll_week_start))
                                        : '—';
                                    $created_at = sanitize_text_field((string) ($payout_row['created_at'] ?? ''));
                                    ?>
                                    <tr>
                                        <td><?php echo esc_html('GBP ' . number_format($bonus_amount, 2)); ?></td>
                                        <td><?php echo esc_html($payout_multiplier_label); ?>x</td>
                                        <td><span class="cmn-status-chip"><?php echo esc_html($payout_status_label); ?></span></td>
                                        <td><?php echo esc_html($payroll_week_start_label); ?></td>
                                        <td><?php echo esc_html($created_at !== '' ? $created_at : '—'); ?></td>
                                    </tr>
                                <?php endforeach; ?>
                            </tbody>
                        </table>
                    <?php endif; ?>
                </div>
            <?php endif; ?>
        <?php endif; ?>
        <?php
        $inner = ob_get_clean();
        return $this->render_staff_shell('candidate_rewards', $inner);
    }

    public function render_staff_partner_programme_shortcode() {
        if (!is_user_logged_in()) {
            return $this->render_login_shortcode();
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            return '<section class="cmn-portal"><div class="cmn-panel-card"><h3>Access restricted</h3><p>This section is available to staff/admin only.</p></div></section>';
        }

        $portal_url = $this->get_portal_base_url();
        $base_url = add_query_arg(['view' => 'partner-programme'], $portal_url);
        $tier_raw = isset($_GET['cmn_partner_tier']) ? sanitize_key(wp_unslash((string) $_GET['cmn_partner_tier'])) : '';
        if ($tier_raw === 'all') {
            $tier_raw = '';
        }
        $allowed_tiers = array_keys((array) $this->get_school_partner_tier_definitions());
        $tier_filter = ($tier_raw !== '' && in_array($tier_raw, $allowed_tiers, true)) ? $tier_raw : '';
        $search_filter = isset($_GET['cmn_partner_search'])
            ? sanitize_text_field(wp_unslash((string) $_GET['cmn_partner_search']))
            : '';
        $sort_filter = isset($_GET['cmn_partner_sort'])
            ? sanitize_key(wp_unslash((string) $_GET['cmn_partner_sort']))
            : 'credits';
        if (!in_array($sort_filter, ['credits', 'savings', 'tier', 'activity', 'name'], true)) {
            $sort_filter = 'credits';
        }
        $current_page = max(1, (int) ($_GET['cmn_partner_page'] ?? 1));
        $selected_school_id = max(0, (int) ($_GET['cmn_partner_school_id'] ?? 0));
        $message = isset($_GET['cmn_partner_msg'])
            ? sanitize_text_field(rawurldecode((string) wp_unslash((string) $_GET['cmn_partner_msg'])))
            : '';
        $message_type = isset($_GET['cmn_partner_msg_type'])
            ? sanitize_key(wp_unslash((string) $_GET['cmn_partner_msg_type']))
            : 'success';
        if (!in_array($message_type, ['success', 'error', 'warning'], true)) {
            $message_type = 'success';
        }

        $list_payload = $this->get_staff_partner_programme_list_results([
            'tier' => $tier_filter,
            'search' => $search_filter,
            'sort' => $sort_filter,
            'page' => $current_page,
            'per_page' => 25,
        ]);
        $rows = (array) ($list_payload['rows'] ?? []);
        $total_rows = (int) ($list_payload['total_rows'] ?? 0);
        $total_pages = (int) ($list_payload['total_pages'] ?? 1);
        $current_page = (int) ($list_payload['page'] ?? $current_page);
        $tier_filter = (string) ($list_payload['tier_filter'] ?? $tier_filter);
        $search_filter = (string) ($list_payload['search_filter'] ?? $search_filter);
        $sort_filter = (string) ($list_payload['sort_filter'] ?? $sort_filter);

        $build_url = function ($overrides = []) use ($base_url, $tier_filter, $search_filter, $sort_filter, $current_page, $selected_school_id) {
            $args = [
                'cmn_partner_tier' => $tier_filter !== '' ? $tier_filter : 'all',
                'cmn_partner_sort' => $sort_filter,
            ];
            if ($search_filter !== '') {
                $args['cmn_partner_search'] = $search_filter;
            }
            if ($current_page > 1) {
                $args['cmn_partner_page'] = $current_page;
            }
            if ($selected_school_id > 0) {
                $args['cmn_partner_school_id'] = $selected_school_id;
            }
            foreach ((array) $overrides as $key => $value) {
                if ($value === null) {
                    unset($args[$key]);
                    continue;
                }
                $args[$key] = $value;
            }
            return add_query_arg($args, $base_url);
        };

        $selected_school = null;
        $selected_partner_stats = [];
        $selected_partner_progress = [];
        $selected_partner_error = '';
        $selected_partner_adjustments = [];
        $selected_partner_events = [];
        $selected_partner_audit_rows = [];
        if ($selected_school_id > 0) {
            $selected_school = get_post($selected_school_id);
            if (!$selected_school || $selected_school->post_type !== 'cmn_school') {
                $selected_partner_error = 'School not found.';
                $selected_school = null;
            } else {
                $partner_row = $this->get_or_create_school_partner($selected_school_id);
                if (is_wp_error($partner_row)) {
                    $selected_partner_error = $partner_row->get_error_message();
                } else {
                    $selected_partner_stats_result = $this->get_school_partner_programme_stats($selected_school_id, [
                        'refresh' => true,
                        'reference_date' => current_time('Y-m-d'),
                        'source' => 'staff_partner_programme_detail',
                    ]);
                    if (is_wp_error($selected_partner_stats_result)) {
                        $selected_partner_error = $selected_partner_stats_result->get_error_message();
                    } else {
                        $selected_partner_stats = (array) $selected_partner_stats_result;
                        $selected_partner_progress = $this->get_school_partner_progress_snapshot((int) ($selected_partner_stats['lifetime_credits'] ?? 0));
                        $selected_partner_adjustments = $this->get_school_partner_credit_adjustments_rows($selected_school_id, 10);
                        $selected_partner_events = $this->get_school_partner_event_rows($selected_school_id, 20);
                        $selected_partner_audit_rows = $this->get_school_partner_audit_rows($selected_school_id, 20);
                    }
                }
            }
        }

        $audit_user_ids = [];
        foreach ((array) $selected_partner_audit_rows as $audit_row) {
            $audit_user_id = (int) ($audit_row['user_id'] ?? 0);
            if ($audit_user_id > 0) {
                $audit_user_ids[] = $audit_user_id;
            }
        }
        $audit_user_ids = array_values(array_unique($audit_user_ids));
        $audit_user_map = [];
        if ($audit_user_ids) {
            $audit_users = get_users([
                'include' => $audit_user_ids,
                'fields' => ['ID', 'display_name', 'user_login'],
            ]);
            foreach ((array) $audit_users as $audit_user) {
                $uid = (int) ($audit_user->ID ?? 0);
                if ($uid > 0) {
                    $audit_user_map[$uid] = (string) ($audit_user->display_name ?: $audit_user->user_login);
                }
            }
        }
        $format_money = function ($value) {
            return 'GBP ' . number_format((float) $value, 2);
        };
        $is_admin_user = $this->is_admin_user($user_id);

        ob_start();
        ?>
        <header class="cmn-school-header">
            <h2>CMN Partner Programme</h2>
            <p>Internal overview of partner tiers, lifetime credits, discounts and invoice-linked savings.</p>
        </header>
        <?php if ($message !== '') : ?>
            <div class="cmn-dashboard-card" style="margin-bottom:12px;">
                <p class="<?php echo $message_type === 'error' ? 'cmn-register-error' : ($message_type === 'warning' ? 'cmn-register-warning' : 'cmn-register-success'); ?>"><?php echo esc_html($message); ?></p>
            </div>
        <?php endif; ?>
        <div class="cmn-dashboard-card" style="margin-bottom:16px;">
            <form method="get" action="<?php echo esc_url($portal_url); ?>" class="cmn-inline cmn-partner-admin-toolbar" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;">
                <input type="hidden" name="view" value="partner-programme">
                <label style="display:flex;flex-direction:column;gap:4px;">
                    <span>Tier</span>
                    <select name="cmn_partner_tier">
                        <option value="all"<?php selected($tier_filter, ''); ?>>All tiers</option>
                        <?php foreach ((array) $allowed_tiers as $tier_key) : ?>
                            <option value="<?php echo esc_attr($tier_key); ?>"<?php selected($tier_filter, $tier_key); ?>><?php echo esc_html($this->get_school_partner_tier_label($tier_key)); ?></option>
                        <?php endforeach; ?>
                    </select>
                </label>
                <label style="display:flex;flex-direction:column;gap:4px;min-width:240px;">
                    <span>School search</span>
                    <input type="text" name="cmn_partner_search" value="<?php echo esc_attr($search_filter); ?>" placeholder="School name or ID">
                </label>
                <label style="display:flex;flex-direction:column;gap:4px;">
                    <span>Sort by</span>
                    <select name="cmn_partner_sort">
                        <option value="credits"<?php selected($sort_filter, 'credits'); ?>>Credits</option>
                        <option value="savings"<?php selected($sort_filter, 'savings'); ?>>Savings</option>
                        <option value="tier"<?php selected($sort_filter, 'tier'); ?>>Tier</option>
                        <option value="activity"<?php selected($sort_filter, 'activity'); ?>>Latest activity</option>
                        <option value="name"<?php selected($sort_filter, 'name'); ?>>School name</option>
                    </select>
                </label>
                <button class="cmn-primary" type="submit">Filter</button>
                <a class="cmn-ghost" href="<?php echo esc_url(add_query_arg(['view' => 'partner-programme'], $portal_url)); ?>">Clear</a>
            </form>
        </div>
        <div class="cmn-portal-grid" style="align-items:start;">
            <div class="cmn-dashboard-card">
                <h3>Schools in Partner Programme</h3>
                <p class="cmn-muted"><?php echo esc_html((string) $total_rows); ?> school(s) found.</p>
                <?php if (!$rows) : ?>
                    <div class="cmn-empty">No schools found for current filters.</div>
                <?php else : ?>
                    <table class="cmn-approval-table">
                        <thead>
                            <tr>
                                <th>School</th>
                                <th>Tier</th>
                                <th>Discount</th>
                                <th>Lifetime Credits</th>
                                <th>Lifetime Savings</th>
                                <th>Academic Year Savings</th>
                                <th>Last Invoice</th>
                                <th>Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            <?php foreach ((array) $rows as $row) : ?>
                                <?php
                                $row_school_id = (int) ($row['school_id'] ?? 0);
                                $row_tier = sanitize_key((string) ($row['tier'] ?? 'standard'));
                                $row_tier_label = $this->get_school_partner_tier_label($row_tier);
                                $row_link = $build_url([
                                    'cmn_partner_school_id' => $row_school_id,
                                    'cmn_partner_page' => $current_page,
                                ]);
                                $row_last_invoice = (string) ($row['last_invoice_date'] ?? '');
                                $row_last_invoice_label = $row_last_invoice !== '' ? date_i18n('M j, Y', strtotime($row_last_invoice)) : '—';
                                ?>
                                <tr>
                                    <td><?php echo esc_html((string) ($row['school_name'] ?? ('School #' . $row_school_id))); ?></td>
                                    <td><span class="cmn-status-chip cmn-partner-tier-chip is-<?php echo esc_attr($row_tier); ?>"><?php echo esc_html($row_tier_label); ?></span></td>
                                    <td><?php echo esc_html(rtrim(rtrim(number_format((float) ($row['discount_percent'] ?? 0), 2, '.', ''), '0'), '.')); ?>%</td>
                                    <td><?php echo esc_html(number_format((float) ($row['lifetime_credits'] ?? 0), 0)); ?></td>
                                    <td><?php echo esc_html($format_money((float) ($row['lifetime_savings'] ?? 0))); ?></td>
                                    <td><?php echo esc_html($format_money((float) ($row['academic_year_savings'] ?? 0))); ?></td>
                                    <td><?php echo esc_html($row_last_invoice_label); ?></td>
                                    <td><a class="cmn-ghost cmn-btn-mini" href="<?php echo esc_url($row_link); ?>">View</a></td>
                                </tr>
                            <?php endforeach; ?>
                        </tbody>
                    </table>
                <?php endif; ?>
                <?php if ($total_pages > 1) : ?>
                    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;">
                        <?php
                        $prev_page = max(1, $current_page - 1);
                        $next_page = min($total_pages, $current_page + 1);
                        ?>
                        <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_partner_page' => $prev_page, 'cmn_partner_school_id' => null])); ?>">Prev</a>
                        <?php for ($p = 1; $p <= $total_pages; $p++) : ?>
                            <a class="cmn-ghost<?php echo $p === $current_page ? ' is-active' : ''; ?>" href="<?php echo esc_url($build_url(['cmn_partner_page' => $p, 'cmn_partner_school_id' => null])); ?>"><?php echo esc_html((string) $p); ?></a>
                        <?php endfor; ?>
                        <a class="cmn-ghost" href="<?php echo esc_url($build_url(['cmn_partner_page' => $next_page, 'cmn_partner_school_id' => null])); ?>">Next</a>
                    </div>
                <?php endif; ?>
            </div>

            <div class="cmn-dashboard-card">
                <h3>School Partner Detail</h3>
                <?php if ($selected_school_id < 1) : ?>
                    <div class="cmn-empty">Select a school from the list to view partner details.</div>
                <?php elseif ($selected_partner_error !== '') : ?>
                    <div class="cmn-empty"><?php echo esc_html($selected_partner_error); ?></div>
                <?php else : ?>
                    <?php
                    $school_name = $selected_school ? (string) $selected_school->post_title : ('School #' . $selected_school_id);
                    $tier_key = sanitize_key((string) ($selected_partner_stats['tier'] ?? 'standard'));
                    $tier_label = $this->get_school_partner_tier_label($tier_key);
                    $detail_return_url = $build_url(['cmn_partner_school_id' => $selected_school_id]);
                    $projection_status = sanitize_key((string) ($selected_partner_stats['projection_status'] ?? 'insufficient_data'));
                    ?>
                    <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-bottom:12px;">
                        <div><strong>School</strong><br><?php echo esc_html($school_name); ?></div>
                        <div><strong>Tier</strong><br><span class="cmn-status-chip cmn-partner-tier-chip is-<?php echo esc_attr($tier_key); ?>"><?php echo esc_html($tier_label); ?></span></div>
                        <div><strong>Discount</strong><br><?php echo esc_html(rtrim(rtrim(number_format((float) ($selected_partner_stats['discount_percent'] ?? 0), 2, '.', ''), '0'), '.')); ?>%</div>
                        <div><strong>Lifetime credits</strong><br><?php echo esc_html(number_format((float) ($selected_partner_stats['lifetime_credits'] ?? 0), 0)); ?></div>
                        <div><strong>Total saved</strong><br><?php echo esc_html($format_money((float) ($selected_partner_stats['lifetime_savings'] ?? 0))); ?></div>
                        <div><strong>Saved this academic year</strong><br><?php echo esc_html($format_money((float) ($selected_partner_stats['academic_year_savings'] ?? 0))); ?></div>
                        <div><strong>Projected academic-year savings</strong><br>
                            <?php if ($projection_status === 'ok') : ?>
                                <?php echo esc_html($format_money((float) ($selected_partner_stats['projected_academic_year_savings'] ?? 0))); ?>
                            <?php else : ?>
                                Projection available after 2 months of activity
                            <?php endif; ?>
                        </div>
                        <div><strong>Academic year</strong><br><?php echo esc_html((string) ($selected_partner_stats['academic_year_label'] ?? '')); ?></div>
                    </div>

                    <div class="cmn-muted" style="margin-bottom:12px;">
                        <?php if (!empty($selected_partner_progress['is_top_tier'])) : ?>
                            Top tier achieved.
                        <?php else : ?>
                            <?php echo esc_html((string) ((int) ($selected_partner_progress['credits_remaining'] ?? 0))); ?> credits to reach <?php echo esc_html((string) ($selected_partner_progress['next_tier_label'] ?? 'next')); ?> tier.
                        <?php endif; ?>
                    </div>

                    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">
                        <a class="cmn-ghost cmn-btn-mini" href="<?php echo esc_url(add_query_arg(['view' => 'schools', 'school_id' => $selected_school_id], $portal_url)); ?>">Open school record</a>
                        <a class="cmn-ghost cmn-btn-mini" href="<?php echo esc_url(add_query_arg(['view' => 'invoicing', 'cmn_invoice_school' => $selected_school_id], $portal_url)); ?>">Open invoice history</a>
                        <a class="cmn-ghost cmn-btn-mini" href="<?php echo esc_url(add_query_arg(['as' => 'school', 'school' => 'partner-programme', 'school_id' => $selected_school_id], $portal_url)); ?>">Open school partner dashboard</a>
                    </div>

                    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;">
                        <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-inline">
                            <?php wp_nonce_field('cmn_partner_programme_recalculate', 'cmn_partner_programme_recalculate_nonce'); ?>
                            <input type="hidden" name="action" value="cmn_partner_programme_recalculate">
                            <input type="hidden" name="school_id" value="<?php echo esc_attr((string) $selected_school_id); ?>">
                            <input type="hidden" name="cmn_return_url" value="<?php echo esc_attr((string) $detail_return_url); ?>">
                            <button class="cmn-primary" type="submit">Recalculate tier + savings</button>
                        </form>
                    </div>

                    <?php if ($is_admin_user) : ?>
                        <h4>Admin override: adjust credits</h4>
                        <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-inline" style="display:grid;grid-template-columns:160px minmax(0,1fr) auto;gap:8px;align-items:end;margin-bottom:14px;">
                            <?php wp_nonce_field('cmn_partner_programme_adjust_credits', 'cmn_partner_programme_adjust_credits_nonce'); ?>
                            <input type="hidden" name="action" value="cmn_partner_programme_adjust_credits">
                            <input type="hidden" name="school_id" value="<?php echo esc_attr((string) $selected_school_id); ?>">
                            <input type="hidden" name="cmn_return_url" value="<?php echo esc_attr((string) $detail_return_url); ?>">
                            <label style="display:flex;flex-direction:column;gap:4px;">
                                <span>Delta</span>
                                <input type="number" name="delta" step="1" required placeholder="+10 or -5">
