                            <label style="display:flex;flex-direction:column;gap:4px;">
                                <span>Reason</span>
                                <input type="text" name="reason" maxlength="255" required>
                            </label>
                            <button class="cmn-ghost" type="submit">Apply</button>
                        </form>
                    <?php endif; ?>

                    <h4>Recent partner credit notes</h4>
                    <?php if (!$selected_partner_adjustments) : ?>
                        <div class="cmn-empty">No partner credit notes found.</div>
                    <?php else : ?>
                        <table class="cmn-approval-table" style="margin-bottom:14px;">
                            <thead>
                                <tr>
                                    <th>When</th>
                                    <th>Invoice</th>
                                    <th>Period</th>
                                    <th>Amount</th>
                                    <th>Label</th>
                                </tr>
                            </thead>
                            <tbody>
                                <?php foreach ((array) $selected_partner_adjustments as $adj) : ?>
