                                        <td><?php echo esc_html((string) ($event_row['created_at'] ?? '')); ?></td>
                                        <td><?php echo esc_html((string) ($event_row['event_type'] ?? '')); ?></td>
                                        <td>#<?php echo esc_html((string) ((int) ($event_row['booking_id'] ?? 0))); ?></td>
                                        <td><?php echo esc_html((string) ($event_row['shift_date'] ?? '')); ?></td>
                                        <td><?php echo esc_html((string) ((int) ($event_row['delta'] ?? 0))); ?></td>
                                    </tr>
                                <?php endforeach; ?>
                            </tbody>
                        </table>
                    <?php endif; ?>

                    <h4>Override audit</h4>
                    <?php if (!$selected_partner_audit_rows) : ?>
                        <div class="cmn-empty">No partner override audit events recorded.</div>
                    <?php else : ?>
                        <table class="cmn-approval-table">
                            <thead>
                                <tr>
                                    <th>When</th>
                                    <th>User</th>
                                    <th>Action</th>
                                    <th>Reason / Details</th>
                                </tr>
                            </thead>
                            <tbody>
                                <?php foreach ((array) $selected_partner_audit_rows as $audit_row) : ?>
                                    <?php
                                    $audit_user_id = (int) ($audit_row['user_id'] ?? 0);
                                    $audit_user_label = $audit_user_id > 0 ? ((string) ($audit_user_map[$audit_user_id] ?? ('User #' . $audit_user_id))) : 'System';
                                    $details_text = '';
                                    if (!empty($audit_row['details_json'])) {
                                        $decoded = json_decode((string) $audit_row['details_json'], true);
                                        if (is_array($decoded)) {
                                            if (!empty($decoded['reason'])) {
                                                $details_text = (string) $decoded['reason'];
                                            } else {
                                                $details_text = wp_json_encode($decoded);
                                            }
                                        } else {
                                            $details_text = (string) $audit_row['details_json'];
                                        }
                                    }
                                    ?>
                                    <tr>
                                        <td><?php echo esc_html((string) ($audit_row['created_at'] ?? '')); ?></td>
                                        <td><?php echo esc_html($audit_user_label); ?></td>
                                        <td><?php echo esc_html((string) ($audit_row['action_type'] ?? '')); ?></td>
                                        <td><?php echo esc_html($details_text !== '' ? $details_text : '—'); ?></td>
                                    </tr>
                                <?php endforeach; ?>
                            </tbody>
                        </table>
                    <?php endif; ?>
                <?php endif; ?>
            </div>
        </div>
        <?php
        $inner = ob_get_clean();
        return $this->render_staff_shell('partner_programme', $inner);
    }

    private function invoice_job_log_table_exists() {
        global $wpdb;
        $table = $this->get_invoice_job_log_table();
        if ($table === '') {
            return false;
        }
        $found = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
        return $found === $table;
    }

    private function normalize_invoice_job_status($status) {
        $status = sanitize_key((string) $status);
        if (!in_array($status, ['success', 'partial', 'failed', 'skipped'], true)) {
            return 'failed';
        }
        return $status;
    }

    private function sanitize_invoice_job_error_message($message) {
        $message = trim((string) $message);
        if ($message === '') {
            return '';
        }
        $message = sanitize_textarea_field($message);
        if (strlen($message) > 60000) {
            $message = substr($message, 0, 60000);
        }
        return $message;
    }

    private function insert_invoice_job_log_row($payload = []) {
        if (!$this->invoice_job_log_table_exists()) {
            return 0;
        }
        $payload = is_array($payload) ? $payload : [];
        global $wpdb;
        $table = $this->get_invoice_job_log_table();
        $started_at = trim((string) ($payload['started_at'] ?? current_time('mysql')));
        if ($started_at === '' || !preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/', $started_at)) {
            $started_at = current_time('mysql');
        }
        $finished_at = trim((string) ($payload['finished_at'] ?? ''));
        if ($finished_at !== '' && !preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/', $finished_at)) {
            $finished_at = '';
        }
        $row = [
            'job_name' => sanitize_key((string) ($payload['job_name'] ?? 'monthly_invoice_generation')),
            'run_for_year' => max(0, (int) ($payload['run_for_year'] ?? 0)),
            'run_for_month' => max(0, min(12, (int) ($payload['run_for_month'] ?? 0))),
            'started_at' => $started_at,
            'finished_at' => $finished_at,
            'status' => $this->normalize_invoice_job_status((string) ($payload['status'] ?? 'failed')),
            'schools_processed' => max(0, (int) ($payload['schools_processed'] ?? 0)),
            'invoices_created' => max(0, (int) ($payload['invoices_created'] ?? 0)),
            'invoices_updated' => max(0, (int) ($payload['invoices_updated'] ?? 0)),
            'warnings_count' => max(0, (int) ($payload['warnings_count'] ?? 0)),
            'error_message' => $this->sanitize_invoice_job_error_message((string) ($payload['error_message'] ?? '')),
        ];
        if ($row['finished_at'] === '') {
            $row['finished_at'] = null;
        }
        if ($row['error_message'] === '') {
            $row['error_message'] = null;
        }
        $ok = $wpdb->insert($table, $row, ['%s', '%d', '%d', '%s', '%s', '%s', '%d', '%d', '%d', '%d', '%s']);
        if ($ok === false) {
            return 0;
        }
        return (int) $wpdb->insert_id;
    }

    private function update_invoice_job_log_row($log_id, $payload = []) {
        $log_id = (int) $log_id;
        if ($log_id < 1 || !$this->invoice_job_log_table_exists()) {
            return false;
        }
        $payload = is_array($payload) ? $payload : [];
        $data = [];
        $formats = [];
        if (array_key_exists('finished_at', $payload)) {
            $finished_at = trim((string) $payload['finished_at']);
            if ($finished_at !== '' && !preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/', $finished_at)) {
                $finished_at = '';
            }
            $data['finished_at'] = $finished_at !== '' ? $finished_at : null;
            $formats[] = '%s';
        }
        if (array_key_exists('status', $payload)) {
            $data['status'] = $this->normalize_invoice_job_status((string) $payload['status']);
            $formats[] = '%s';
        }
        if (array_key_exists('schools_processed', $payload)) {
            $data['schools_processed'] = max(0, (int) $payload['schools_processed']);
            $formats[] = '%d';
        }
        if (array_key_exists('invoices_created', $payload)) {
            $data['invoices_created'] = max(0, (int) $payload['invoices_created']);
            $formats[] = '%d';
        }
        if (array_key_exists('invoices_updated', $payload)) {
            $data['invoices_updated'] = max(0, (int) $payload['invoices_updated']);
            $formats[] = '%d';
        }
        if (array_key_exists('warnings_count', $payload)) {
            $data['warnings_count'] = max(0, (int) $payload['warnings_count']);
            $formats[] = '%d';
        }
        if (array_key_exists('error_message', $payload)) {
            $error_message = $this->sanitize_invoice_job_error_message((string) $payload['error_message']);
            $data['error_message'] = $error_message !== '' ? $error_message : null;
            $formats[] = '%s';
        }
        if (!$data) {
            return false;
        }
        global $wpdb;
        $table = $this->get_invoice_job_log_table();
        $updated = $wpdb->update($table, $data, ['id' => $log_id], $formats, ['%d']);
        return $updated !== false;
    }

