    private function build_invoice_job_warning_message($generation_result) {
        $generation_result = is_array($generation_result) ? $generation_result : [];
        $warnings_total = max(0, (int) ($generation_result['warnings_count'] ?? 0));
        if ($warnings_total < 1) {
            return '';
        }
        $samples = [];
        $school_results = is_array($generation_result['school_results'] ?? null) ? (array) $generation_result['school_results'] : [];
        foreach ($school_results as $school_result) {
            if (!is_array($school_result)) {
                continue;
            }
            $school_id = (int) ($school_result['school_id'] ?? 0);
            $warnings = is_array($school_result['warnings'] ?? null) ? (array) $school_result['warnings'] : [];
            foreach ($warnings as $warning_row) {
                if (!is_array($warning_row)) {
                    continue;
                }
                $samples[] = [
                    'school_id' => $school_id > 0 ? $school_id : (int) ($warning_row['school_id'] ?? 0),
                    'code' => sanitize_key((string) ($warning_row['code'] ?? 'warning')),
                    'invoice_id' => (int) ($warning_row['invoice_id'] ?? 0),
                    'booking_id' => (int) ($warning_row['booking_id'] ?? 0),
                    'shift_date' => $this->normalize_invoice_date((string) ($warning_row['shift_date'] ?? '')),
                ];
                if (count($samples) >= 30) {
                    break 2;
                }
            }
        }

        $payload = [
            'message' => 'Non-fatal warnings were raised. See invoice_generation_warning audit entries for full details.',
            'warnings_count' => $warnings_total,
            'samples' => $samples,
        ];
        $encoded = wp_json_encode($payload);
        if (!is_string($encoded) || $encoded === '') {
            $encoded = 'Non-fatal warnings were raised during monthly invoice generation.';
        }
        return $this->sanitize_invoice_job_error_message($encoded);
    }

    private function run_monthly_invoice_generation_job($trigger = 'cron', $actor_user_id = 0) {
        $actor_user_id = (int) $actor_user_id;
        $trigger = sanitize_key((string) $trigger);
        if ($trigger === '') {
            $trigger = 'cron';
        }
        $bounds = $this->get_previous_invoice_month_bounds();
        if (!$bounds) {
            return new WP_Error('cmn_invoice_monthly_job_invalid_period', 'Unable to determine previous month bounds.');
        }
        $year = (int) ($bounds['year'] ?? 0);
        $month = (int) ($bounds['month'] ?? 0);
        $month_key = (string) ($bounds['month_key'] ?? '');
        $job_name = 'monthly_invoice_generation';
        $started_at = current_time('mysql');
        $lock_key = self::MONTHLY_INVOICE_LOCK_KEY;

        if (get_transient($lock_key)) {
            $lock_message = 'Skipped due to lock: monthly invoice generation is already in progress.';
            $this->insert_invoice_job_log_row([
                'job_name' => $job_name,
                'run_for_year' => $year,
                'run_for_month' => $month,
                'started_at' => $started_at,
                'finished_at' => current_time('mysql'),
                'status' => 'skipped',
                'schools_processed' => 0,
                'invoices_created' => 0,
                'invoices_updated' => 0,
                'warnings_count' => 0,
                'error_message' => $lock_message,
            ]);
            $this->add_audit_log('invoice_monthly_job_skipped_lock', 'invoice_period', $month_key, [
                'trigger' => $trigger,
                'message' => $lock_message,
            ], $actor_user_id);
            return [
                'status' => 'skipped',
                'trigger' => $trigger,
                'year' => $year,
                'month' => $month,
                'month_key' => $month_key,
                'schools_processed' => 0,
                'invoices_created' => 0,
                'invoices_updated' => 0,
                'warnings_count' => 0,
                'error_message' => $lock_message,
            ];
        }

        $lock_token = function_exists('wp_generate_uuid4') ? (string) wp_generate_uuid4() : uniqid('cmn-invoice-job-', true);
        set_transient($lock_key, $lock_token, self::MONTHLY_INVOICE_LOCK_TTL);

        $log_id = $this->insert_invoice_job_log_row([
            'job_name' => $job_name,
            'run_for_year' => $year,
            'run_for_month' => $month,
            'started_at' => $started_at,
            'status' => 'partial',
        ]);

        $status = 'failed';
        $schools_processed = 0;
        $invoices_created = 0;
        $invoices_updated = 0;
        $warnings_count = 0;
        $error_message = '';
        $generation_result = null;
        try {
            $generation_result = $this->generate_invoices_for_month($year, $month, [
                'actor_user_id' => $actor_user_id,
                'permission_validated' => true,
            ]);
            if (is_wp_error($generation_result)) {
                $status = 'failed';
                $error_message = $generation_result->get_error_message();
            } else {
                $schools_processed = max(0, (int) ($generation_result['schools_total'] ?? 0));
                $invoices_created = max(0, (int) ($generation_result['invoices_created'] ?? 0));
                $invoices_touched = max(0, (int) ($generation_result['invoices_touched'] ?? 0));
                $invoices_updated = max(0, $invoices_touched - $invoices_created);
                $warnings_count = max(0, (int) ($generation_result['warnings_count'] ?? 0));
                $status = $warnings_count > 0 ? 'partial' : 'success';
                if ($warnings_count > 0) {
                    $error_message = $this->build_invoice_job_warning_message($generation_result);
                }
            }
        } catch (Throwable $e) {
            $status = 'failed';
            $error_message = 'Unhandled error: ' . $e->getMessage();
        }

        $finished_at = current_time('mysql');
        $log_payload = [
            'finished_at' => $finished_at,
            'status' => $status,
            'schools_processed' => $schools_processed,
            'invoices_created' => $invoices_created,
            'invoices_updated' => $invoices_updated,
            'warnings_count' => $warnings_count,
            'error_message' => $error_message,
        ];
        if ($log_id > 0) {
            $this->update_invoice_job_log_row($log_id, $log_payload);
        } else {
            $this->insert_invoice_job_log_row(array_merge($log_payload, [
                'job_name' => $job_name,
                'run_for_year' => $year,
                'run_for_month' => $month,
                'started_at' => $started_at,
            ]));
        }

        delete_transient($lock_key);
        $this->schedule_monthly_invoice_generation();

        $this->add_audit_log('invoice_monthly_job_run', 'invoice_period', $month_key, [
            'trigger' => $trigger,
            'status' => $status,
            'schools_processed' => $schools_processed,
            'invoices_created' => $invoices_created,
            'invoices_updated' => $invoices_updated,
            'warnings_count' => $warnings_count,
            'error_message' => $error_message,
            'log_id' => $log_id,
        ], $actor_user_id);

        return [
            'status' => $status,
            'trigger' => $trigger,
            'year' => $year,
            'month' => $month,
            'month_key' => $month_key,
            'schools_processed' => $schools_processed,
            'invoices_created' => $invoices_created,
            'invoices_updated' => $invoices_updated,
            'warnings_count' => $warnings_count,
            'error_message' => $error_message,
            'log_id' => $log_id,
            'generation_result' => is_array($generation_result) ? $generation_result : [],
        ];
    }

    private function run_invoice_overdue_reminder_job($trigger = 'cron', $actor_user_id = 0) {
        $actor_user_id = (int) $actor_user_id;
        $trigger = sanitize_key((string) $trigger);
        if ($trigger === '') {
            $trigger = 'cron';
        }
        $required_methods = [
            'get_overdue_invoices_for_reminders',
            'get_invoice_due_reminder_stage_for_invoice',
            'get_invoice_reminder_log_entry',
            'has_invoice_sent_reminder_on_date',
            'get_invoice_overdue_days',
            'insert_invoice_reminder_log_entry',
            'get_school_invoice_reminders_opt_out',
            'build_invoice_reminder_email_subject',
            'build_invoice_reminder_email_bodies',
        ];
        foreach ($required_methods as $required_method) {
            if (!method_exists($this, $required_method)) {
                return [
                    'status' => 'skipped',
                    'trigger' => $trigger,
                    'date' => current_time('Y-m-d'),
                    'invoices_scanned' => 0,
                    'reminders_sent' => 0,
                    'reminders_failed' => 0,
                    'reminders_skipped' => 0,
                    'error_message' => 'Overdue reminder job is not fully configured (missing method: ' . $required_method . ').',
                ];
            }
        }
        $today = current_time('Y-m-d');
        $lock_key = self::INVOICE_OVERDUE_REMINDER_LOCK_KEY;
        if (get_transient($lock_key)) {
            return [
                'status' => 'skipped',
                'trigger' => $trigger,
                'date' => $today,
                'invoices_scanned' => 0,
                'reminders_sent' => 0,
                'reminders_failed' => 0,
                'reminders_skipped' => 0,
                'error_message' => 'Skipped due to lock: overdue reminder job is already in progress.',
            ];
        }
        $lock_token = function_exists('wp_generate_uuid4') ? (string) wp_generate_uuid4() : uniqid('cmn-invoice-reminder-', true);
        set_transient($lock_key, $lock_token, self::INVOICE_OVERDUE_REMINDER_LOCK_TTL);

        $summary = [
            'status' => 'success',
            'trigger' => $trigger,
            'date' => $today,
            'invoices_scanned' => 0,
            'reminders_sent' => 0,
            'reminders_failed' => 0,
            'reminders_skipped' => 0,
            'error_message' => '',
        ];

        try {
            $invoice_rows = $this->get_overdue_invoices_for_reminders(500, $today);
            $summary['invoices_scanned'] = count($invoice_rows);
            foreach ($invoice_rows as $invoice_row) {
                $invoice_id = (int) ($invoice_row['id'] ?? 0);
                $school_id = (int) ($invoice_row['school_id'] ?? 0);
                if ($invoice_id < 1 || $school_id < 1) {
                    continue;
                }

                $stage = $this->get_invoice_due_reminder_stage_for_invoice($invoice_row, $today);
                if ($stage < 1) {
                    continue;
                }
                if ($this->get_invoice_reminder_log_entry($invoice_id, $stage)) {
                    continue;
                }
                if ($this->has_invoice_sent_reminder_on_date($invoice_id, $today)) {
                    $summary['reminders_skipped']++;
                    continue;
                }

                $days_overdue = $this->get_invoice_overdue_days($invoice_row, $today);
                if ($days_overdue < 1) {
                    continue;
                }
                if (!empty($invoice_row['reminders_disabled'])) {
                    $this->insert_invoice_reminder_log_entry([
                        'invoice_id' => $invoice_id,
                        'school_id' => $school_id,
                        'stage' => $stage,
                        'to_email' => '',
                        'sent_by_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                        'status' => 'skipped',
                        'error_message' => 'Invoice-level reminders are disabled.',
                    ]);
                    $summary['reminders_skipped']++;
                    continue;
                }
                if ($this->get_school_invoice_reminders_opt_out($school_id)) {
                    $this->insert_invoice_reminder_log_entry([
                        'invoice_id' => $invoice_id,
                        'school_id' => $school_id,
                        'stage' => $stage,
                        'to_email' => '',
                        'sent_by_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                        'status' => 'skipped',
                        'error_message' => 'School has opted out of invoice reminders.',
                    ]);
                    $summary['reminders_skipped']++;
                    continue;
                }

                $recipient = $this->get_invoice_email_primary_recipient($invoice_row);
                $to_email = sanitize_email((string) ($recipient['email'] ?? ''));
                if ($to_email === '') {
                    $this->insert_invoice_reminder_log_entry([
                        'invoice_id' => $invoice_id,
                        'school_id' => $school_id,
                        'stage' => $stage,
                        'to_email' => '',
                        'sent_by_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                        'status' => 'skipped',
                        'error_message' => 'Recipient email missing (invoice_email and billing_email empty).',
                    ]);
                    $this->add_audit_log('invoice_reminder_skipped_missing_recipient', 'invoice', (string) $invoice_id, [
                        'school_id' => $school_id,
                        'stage' => $stage,
                    ], $actor_user_id);
                    $summary['reminders_skipped']++;
                    continue;
                }

                $school_name = $this->get_invoice_school_display_name(
                    $school_id,
                    (string) ($invoice_row['school_name'] ?? '')
                );
                $subject = $this->build_invoice_reminder_email_subject($invoice_row, $stage);
                $bodies = $this->build_invoice_reminder_email_bodies($invoice_row, $school_name, $stage);
                $html_body = (string) ($bodies['html'] ?? '');
                $plain_body = (string) ($bodies['plain'] ?? '');
                $headers = [
                    'Message-ID: ' . $this->build_invoice_email_message_id($invoice_id),
                ];
                $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
                $GLOBALS['cmn_school_mail_log_type'] = 'invoice_overdue_reminder';
                $send_result = $this->send_school_email_with_alt_body(
                    $to_email,
                    $subject,
                    $html_body,
                    $plain_body,
                    $headers,
                    []
                );
                if ($previous_log_type !== null) {
                    $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
                } else {
                    unset($GLOBALS['cmn_school_mail_log_type']);
                }

                $send_result = is_array($send_result) ? $send_result : [];
                $sent = !empty($send_result['sent']);
                $mail_error = sanitize_textarea_field((string) ($send_result['error_message'] ?? ''));
                if (!$sent) {
                    if ($mail_error === '') {
                        $mail_error = 'Reminder send failed.';
                    }
                    $this->insert_invoice_reminder_log_entry([
                        'invoice_id' => $invoice_id,
                        'school_id' => $school_id,
                        'stage' => $stage,
                        'to_email' => $to_email,
                        'sent_by_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                        'status' => 'failed',
                        'error_message' => $mail_error,
                    ]);
                    $this->add_audit_log('invoice_reminder_failed', 'invoice', (string) $invoice_id, [
                        'school_id' => $school_id,
                        'stage' => $stage,
                        'to_email' => $to_email,
                        'error' => $mail_error,
                    ], $actor_user_id);
                    $summary['reminders_failed']++;
                    continue;
                }

                $now_mysql = current_time('mysql');
                $this->insert_invoice_reminder_log_entry([
                    'invoice_id' => $invoice_id,
                    'school_id' => $school_id,
                    'stage' => $stage,
                    'to_email' => $to_email,
                    'sent_by_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                    'sent_at' => $now_mysql,
                    'status' => 'sent',
                    'error_message' => '',
                ]);
                global $wpdb;
                $invoices_table = $this->get_invoices_table();
                $wpdb->query($wpdb->prepare(
                    "UPDATE {$invoices_table}
                     SET last_reminder_sent_at = %s,
                         updated_at = %s
                     WHERE id = %d",
                    $now_mysql,
                    $now_mysql,
                    $invoice_id
                ));

                $note = sprintf(
                    'Reminder stage %d sent to %s (%d day(s) overdue).',
                    $stage,
                    $to_email,
                    $days_overdue
                );
                $this->log_invoice_audit_event($invoice_id, 'reminder_sent', [
                    'invoice' => $invoice_row,
                    'school_id' => $school_id,
                    'from_status' => (string) ($invoice_row['status'] ?? ''),
                    'to_status' => (string) ($invoice_row['status'] ?? ''),
                    'user_id' => $actor_user_id,
                    'note' => $note,
                ]);
                $this->add_audit_log('invoice_overdue_reminder_sent', 'invoice', (string) $invoice_id, [
                    'school_id' => $school_id,
                    'stage' => $stage,
                    'to_email' => $to_email,
                    'days_overdue' => $days_overdue,
                ], $actor_user_id);
                $summary['reminders_sent']++;
            }
        } catch (Throwable $e) {
            $summary['status'] = 'failed';
            $summary['error_message'] = 'Unhandled error: ' . $e->getMessage();
        }

        delete_transient($lock_key);
        $this->schedule_invoice_overdue_reminders();

        if ($summary['status'] !== 'failed') {
            if ($summary['reminders_failed'] > 0) {
                $summary['status'] = 'partial';
            } else {
                $summary['status'] = 'success';
            }
        }

        $this->add_audit_log('invoice_overdue_reminder_job_run', 'invoice_reminders', $today, [
            'trigger' => $trigger,
            'status' => $summary['status'],
            'date' => $today,
            'invoices_scanned' => (int) $summary['invoices_scanned'],
            'reminders_sent' => (int) $summary['reminders_sent'],
            'reminders_failed' => (int) $summary['reminders_failed'],
            'reminders_skipped' => (int) $summary['reminders_skipped'],
            'error_message' => (string) ($summary['error_message'] ?? ''),
        ], $actor_user_id);

        return $summary;
    }

    private function get_active_candidate_ids_for_rewards_reset() {
        $candidate_ids = (array) get_posts([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish'],
            'fields' => 'ids',
            'posts_per_page' => -1,
            'orderby' => 'ID',
            'order' => 'ASC',
        ]);
        if (!$candidate_ids) {
            return [];
        }
        $active_ids = [];
        foreach ($candidate_ids as $candidate_id) {
            $candidate_id = (int) $candidate_id;
            if ($candidate_id < 1) {
                continue;
            }
            $status = sanitize_key((string) get_post_meta($candidate_id, 'cmn_status', true));
            if (in_array($status, ['rejected', 'declined', 'deleted', 'inactive', 'terminated'], true)) {
                continue;
            }
            $active_ids[] = $candidate_id;
        }
        return array_values(array_unique($active_ids));
    }

    private function run_candidate_rewards_annual_reset_job($trigger = 'cron', $actor_user_id = 0, $reference_date = 'now') {
        $actor_user_id = (int) $actor_user_id;
        $trigger = sanitize_key((string) $trigger);
        if ($trigger === '') {
            $trigger = 'cron';
        }

        $period = $this->get_candidate_rewards_reset_period_labels($reference_date);
        $academic_year_from = (string) ($period['from'] ?? '');
        $academic_year_to = (string) ($period['to'] ?? '');
        if (!preg_match('/^\d{4}-\d{4}$/', $academic_year_from) || !preg_match('/^\d{4}-\d{4}$/', $academic_year_to)) {
            return new WP_Error('cmn_candidate_rewards_reset_invalid_period', 'Unable to determine academic year reset period.');
        }

        $job_name = 'candidate_rewards_year_reset';
        $started_at = current_time('mysql');
        $lock_key = self::CANDIDATE_REWARDS_ANNUAL_RESET_LOCK_KEY;
        if (get_transient($lock_key)) {
            $lock_message = 'Skipped due to lock: candidate rewards annual reset is already in progress.';
            $this->insert_candidate_rewards_job_log_row([
                'job_name' => $job_name,
                'academic_year_from' => $academic_year_from,
                'academic_year_to' => $academic_year_to,
                'started_at' => $started_at,
                'finished_at' => current_time('mysql'),
                'status' => 'skipped',
                'candidates_processed' => 0,
                'candidates_created' => 0,
                'warnings_count' => 0,
                'error_message' => $lock_message,
            ]);
            $this->add_audit_log('candidate_rewards_year_reset_skipped_lock', 'candidate_rewards_year', $academic_year_to, [
                'trigger' => $trigger,
                'academic_year_from' => $academic_year_from,
                'message' => $lock_message,
            ], $actor_user_id);
            return [
                'status' => 'skipped',
                'trigger' => $trigger,
                'academic_year_from' => $academic_year_from,
                'academic_year_to' => $academic_year_to,
                'candidates_processed' => 0,
                'candidates_created' => 0,
                'warnings_count' => 0,
                'error_message' => $lock_message,
            ];
        }

        $lock_token = function_exists('wp_generate_uuid4') ? (string) wp_generate_uuid4() : uniqid('cmn-rewards-reset-', true);
        set_transient($lock_key, $lock_token, self::CANDIDATE_REWARDS_ANNUAL_RESET_LOCK_TTL);

        $log_id = $this->insert_candidate_rewards_job_log_row([
            'job_name' => $job_name,
            'academic_year_from' => $academic_year_from,
            'academic_year_to' => $academic_year_to,
            'started_at' => $started_at,
            'status' => 'partial',
        ]);

        $status = 'failed';
        $candidates_processed = 0;
        $candidates_created = 0;
        $warnings_count = 0;
        $error_message = '';
        $warning_samples = [];
        try {
            $candidate_ids = $this->get_active_candidate_ids_for_rewards_reset();
            $candidates_processed = count($candidate_ids);
            foreach ($candidate_ids as $candidate_id) {
                $candidate_id = (int) $candidate_id;
                if ($candidate_id < 1) {
                    continue;
                }
                $existing_target = $this->get_candidate_rewards_record($candidate_id, $academic_year_to);
                if (!empty($existing_target)) {
                    continue;
                }
                $created_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year_to);
                if (is_wp_error($created_row)) {
                    $warnings_count++;
                    if (count($warning_samples) < 50) {
                        $warning_samples[] = [
                            'candidate_id' => $candidate_id,
                            'code' => sanitize_key((string) $created_row->get_error_code()),
                            'message' => sanitize_text_field($created_row->get_error_message()),
                        ];
                    }
                    continue;
                }
                $candidates_created++;
            }
            $status = $warnings_count > 0 ? 'partial' : 'success';
            if ($warnings_count > 0) {
                $warning_payload = [
                    'message' => 'Some candidate rewards rows could not be created.',
                    'warnings_count' => $warnings_count,
                    'samples' => $warning_samples,
                ];
                $encoded = wp_json_encode($warning_payload);
                if (is_string($encoded) && $encoded !== '') {
                    $error_message = $encoded;
                } else {
                    $error_message = 'Some candidate rewards rows could not be created.';
                }
            }
        } catch (Throwable $e) {
            $status = 'failed';
            $error_message = 'Unhandled error: ' . $e->getMessage();
        }

        $error_message = $this->sanitize_candidate_rewards_job_error_message($error_message);
        $finished_at = current_time('mysql');
        $log_payload = [
            'finished_at' => $finished_at,
            'status' => $status,
            'candidates_processed' => $candidates_processed,
            'candidates_created' => $candidates_created,
            'warnings_count' => $warnings_count,
            'error_message' => $error_message,
        ];
        if ($log_id > 0) {
            $this->update_candidate_rewards_job_log_row($log_id, $log_payload);
        } else {
            $this->insert_candidate_rewards_job_log_row(array_merge($log_payload, [
                'job_name' => $job_name,
                'academic_year_from' => $academic_year_from,
                'academic_year_to' => $academic_year_to,
                'started_at' => $started_at,
            ]));
        }

        delete_transient($lock_key);
        $this->schedule_candidate_rewards_annual_reset();

        $this->add_audit_log('candidate_rewards_year_reset_run', 'candidate_rewards_year', $academic_year_to, [
            'trigger' => $trigger,
            'status' => $status,
            'academic_year_from' => $academic_year_from,
            'candidates_processed' => $candidates_processed,
            'candidates_created' => $candidates_created,
            'warnings_count' => $warnings_count,
            'error_message' => $error_message,
            'log_id' => $log_id,
        ], $actor_user_id);

        return [
            'status' => $status,
            'trigger' => $trigger,
            'academic_year_from' => $academic_year_from,
            'academic_year_to' => $academic_year_to,
            'candidates_processed' => $candidates_processed,
            'candidates_created' => $candidates_created,
            'warnings_count' => $warnings_count,
            'error_message' => $error_message,
            'log_id' => $log_id,
        ];
    }

    public function handle_run_monthly_invoice_job_now() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_run_monthly_invoice_job_now_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_run_monthly_invoice_job_now_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_run_monthly_invoice_job_now')) {
            wp_die('Invalid request', 403);
        }

        $result = $this->run_monthly_invoice_generation_job('manual', $user_id);
        $bounds = $this->get_previous_invoice_month_bounds();
        $month_key = is_array($bounds) ? (string) ($bounds['month_key'] ?? current_time('Y-m')) : current_time('Y-m');
        $month_label = preg_match('/^\d{4}-\d{2}$/', $month_key) ? date_i18n('F Y', strtotime($month_key . '-01')) : $month_key;

        if (is_wp_error($result)) {
            $message = 'Monthly invoice job failed: ' . $result->get_error_message();
        } else {
            $status = (string) ($result['status'] ?? 'failed');
            if ($status === 'success') {
                $message = sprintf(
                    'Monthly invoice job complete for %s: %d school(s), %d invoice(s) created, %d invoice(s) updated.',
                    $month_label,
                    (int) ($result['schools_processed'] ?? 0),
                    (int) ($result['invoices_created'] ?? 0),
                    (int) ($result['invoices_updated'] ?? 0)
                );
            } elseif ($status === 'partial') {
                $message = sprintf(
                    'Monthly invoice job completed with warnings for %s: %d school(s), %d invoice(s) created, %d updated, %d warning(s).',
                    $month_label,
                    (int) ($result['schools_processed'] ?? 0),
                    (int) ($result['invoices_created'] ?? 0),
                    (int) ($result['invoices_updated'] ?? 0),
                    (int) ($result['warnings_count'] ?? 0)
                );
            } elseif ($status === 'skipped') {
                $message = 'Monthly invoice job skipped because another run is in progress.';
            } else {
                $fallback_error = trim((string) ($result['error_message'] ?? ''));
                $message = $fallback_error !== ''
                    ? ('Monthly invoice job failed: ' . $fallback_error)
                    : 'Monthly invoice job failed.';
            }
            if (!empty($result['month_key'])) {
                $month_key = (string) $result['month_key'];
            }
        }

        $redirect = add_query_arg([
            'view' => 'invoicing',
            'cmn_invoice_month' => $month_key,
            'cmn_invoice_generation_msg' => $message,
        ], $this->get_portal_base_url());
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_run_invoice_overdue_reminder_job_now() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_run_invoice_overdue_reminder_job_now_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_run_invoice_overdue_reminder_job_now_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_run_invoice_overdue_reminder_job_now')) {
            wp_die('Invalid request', 403);
        }
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_invoice_portal_return_url($return_url_raw);

        $result = $this->run_invoice_overdue_reminder_job('manual', $user_id);
        $status = (string) ($result['status'] ?? 'failed');
        if ($status === 'success') {
            $message = sprintf(
                'Overdue reminder job complete: %d invoice(s) scanned, %d sent, %d skipped.',
                (int) ($result['invoices_scanned'] ?? 0),
                (int) ($result['reminders_sent'] ?? 0),
                (int) ($result['reminders_skipped'] ?? 0)
            );
        } elseif ($status === 'partial') {
            $message = sprintf(
                'Overdue reminder job completed with failures: %d scanned, %d sent, %d failed, %d skipped.',
                (int) ($result['invoices_scanned'] ?? 0),
                (int) ($result['reminders_sent'] ?? 0),
                (int) ($result['reminders_failed'] ?? 0),
                (int) ($result['reminders_skipped'] ?? 0)
            );
        } elseif ($status === 'skipped') {
            $message = 'Overdue reminder job skipped because another run is in progress.';
        } else {
            $fallback_error = sanitize_text_field((string) ($result['error_message'] ?? ''));
            $message = $fallback_error !== '' ? ('Overdue reminder job failed: ' . $fallback_error) : 'Overdue reminder job failed.';
        }

        $redirect = add_query_arg([
            'cmn_invoice_reminder_job_msg' => rawurlencode($message),
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_update_invoice_school_reminder_opt_out() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $school_id = max(0, (int) ($_POST['school_id'] ?? 0));
        $invoice_id = max(0, (int) ($_POST['invoice_id'] ?? 0));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_invoice_portal_return_url($return_url_raw);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            $redirect = add_query_arg([
                'cmn_invoice_msg' => 'School not found.',
                'cmn_invoice_id' => $invoice_id > 0 ? $invoice_id : null,
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }
        $nonce = isset($_POST['cmn_invoice_school_reminder_opt_out_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_invoice_school_reminder_opt_out_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_invoice_school_reminder_opt_out_' . $school_id)) {
            wp_die('Invalid request', 403);
        }

        $opt_out = !empty($_POST['cmn_invoice_reminders_opt_out']) ? 1 : 0;
        update_post_meta($school_id, 'cmn_invoice_reminders_opt_out', (string) $opt_out);

        $this->add_audit_log('invoice_school_reminder_opt_out_updated', 'school', (string) $school_id, [
            'school_id' => $school_id,
            'invoice_id' => $invoice_id,
            'opt_out' => $opt_out,
        ], $user_id);
        $message = $opt_out
            ? 'Invoice reminders are now opted out for this school.'
            : 'Invoice reminders are now enabled for this school.';
        $redirect = add_query_arg([
            'cmn_invoice_msg' => rawurlencode($message),
            'cmn_invoice_id' => $invoice_id > 0 ? $invoice_id : null,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_run_candidate_rewards_reset_now() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_run_candidate_rewards_reset_now_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_run_candidate_rewards_reset_now_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_run_candidate_rewards_reset_now')) {
            wp_die('Invalid request', 403);
        }

        $result = $this->run_candidate_rewards_annual_reset_job('manual', $user_id, 'now');
        if (is_wp_error($result)) {
            $message = 'Candidate rewards annual reset failed: ' . $result->get_error_message();
        } else {
            $status = (string) ($result['status'] ?? 'failed');
            if ($status === 'success') {
                $message = sprintf(
                    'Candidate rewards reset complete (%s): %d active candidate(s), %d new row(s) created.',
                    (string) ($result['academic_year_to'] ?? ''),
                    (int) ($result['candidates_processed'] ?? 0),
                    (int) ($result['candidates_created'] ?? 0)
                );
            } elseif ($status === 'partial') {
                $message = sprintf(
                    'Candidate rewards reset completed with warnings (%s): %d active candidate(s), %d new row(s), %d warning(s).',
                    (string) ($result['academic_year_to'] ?? ''),
                    (int) ($result['candidates_processed'] ?? 0),
                    (int) ($result['candidates_created'] ?? 0),
                    (int) ($result['warnings_count'] ?? 0)
                );
            } elseif ($status === 'skipped') {
                $message = 'Candidate rewards annual reset skipped because another run is in progress.';
            } else {
                $fallback_error = trim((string) ($result['error_message'] ?? ''));
                $message = $fallback_error !== ''
                    ? ('Candidate rewards annual reset failed: ' . $fallback_error)
                    : 'Candidate rewards annual reset failed.';
            }
        }

        $redirect = add_query_arg([
            'view' => 'invoicing',
            'cmn_candidate_rewards_reset_msg' => rawurlencode($message),
        ], $this->get_portal_base_url());
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_run_rewards_payroll_addon_processor() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_run_rewards_payroll_addon_processor_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_run_rewards_payroll_addon_processor_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_run_rewards_payroll_addon_processor')) {
            wp_die('Invalid request', 403);
        }

        $week_input = isset($_POST['cmn_payroll_week_start'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_payroll_week_start']))
            : '';
        $week_start = $this->get_payroll_week_start($week_input !== '' ? $week_input : 'now');
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_invoice_portal_return_url($return_url_raw);

        $result = $this->process_candidate_rewards_payouts_for_week($week_start, [
            'trigger' => 'manual',
            'actor_user_id' => $user_id,
        ]);
        if (is_wp_error($result)) {
            $message = 'Rewards payroll add-on processor failed: ' . $result->get_error_message();
        } else {
            $status = (string) ($result['status'] ?? 'failed');
            if ($status === 'success') {
                $message = sprintf(
                    'Rewards payroll add-on processor complete for week %s: %d payout(s) reviewed, %d add-on(s) included, %d duplicate(s), %d warning(s).',
                    (string) ($result['week_start'] ?? $week_start),
                    (int) ($result['processed'] ?? 0),
                    (int) ($result['included'] ?? 0),
                    (int) ($result['duplicates'] ?? 0),
                    (int) ($result['warnings'] ?? 0)
                );
            } elseif ($status === 'partial') {
                $message = sprintf(
                    'Rewards payroll add-on processor completed with warnings for week %s: %d payout(s) reviewed, %d included, %d duplicate(s), %d warning(s).',
                    (string) ($result['week_start'] ?? $week_start),
                    (int) ($result['processed'] ?? 0),
                    (int) ($result['included'] ?? 0),
                    (int) ($result['duplicates'] ?? 0),
                    (int) ($result['warnings'] ?? 0)
                );
            } elseif ($status === 'skipped') {
                $message = 'Rewards payroll add-on processor skipped because another run is in progress.';
            } else {
                $fallback_error = trim((string) ($result['message'] ?? ''));
                $message = $fallback_error !== ''
                    ? ('Rewards payroll add-on processor failed: ' . $fallback_error)
                    : 'Rewards payroll add-on processor failed.';
            }
            $week_start = (string) ($result['week_start'] ?? $week_start);
        }

        $redirect = add_query_arg([
            'cmn_rewards_payroll_msg' => rawurlencode($message),
            'cmn_payroll_week_start' => $week_start,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

