    public function handle_generate_monthly_invoices() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_generate_monthly_invoices_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_generate_monthly_invoices_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_generate_monthly_invoices')) {
            wp_die('Invalid request', 403);
        }

        $month_value = isset($_POST['cmn_invoice_month'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_invoice_month']))
            : current_time('Y-m');
        if (!preg_match('/^\d{4}-\d{2}$/', $month_value)) {
            $month_value = current_time('Y-m');
        }
        $year = (int) substr($month_value, 0, 4);
        $month = (int) substr($month_value, 5, 2);
        $result = $this->generate_invoices_for_month($year, $month, [
            'actor_user_id' => $user_id,
        ]);
        if (is_wp_error($result)) {
            $message = 'Invoice generation failed: ' . $result->get_error_message();
        } else {
            $schools_total = (int) ($result['schools_total'] ?? 0);
            $created_count = (int) ($result['invoices_created'] ?? 0);
            $items_added = (int) ($result['items_added'] ?? 0);
            $warnings_count = (int) ($result['warnings_count'] ?? 0);
            $message = sprintf(
                'Invoice generation complete: %d school(s), %d invoice(s) created, %d item(s) added, %d warning(s).',
                $schools_total,
                $created_count,
                $items_added,
                $warnings_count
            );
            $month_value = (string) ($result['month_key'] ?? $month_value);
        }
        $redirect = add_query_arg([
            'view' => 'invoicing',
            'cmn_invoice_month' => $month_value,
            'cmn_invoice_generation_msg' => $message,
        ], $this->get_portal_base_url());
        wp_safe_redirect($redirect);
        exit;
    }

    private function get_invoice_portal_return_url($raw_url = '') {
        $default_url = add_query_arg(['view' => 'invoicing'], $this->get_portal_base_url());
        $raw_url = is_string($raw_url) ? trim($raw_url) : '';
        if ($raw_url === '') {
            return $default_url;
        }
        $candidate = esc_url_raw($raw_url);
        if ($candidate === '') {
            return $default_url;
        }
        return wp_validate_redirect($candidate, $default_url);
    }

