    public function handle_invoice_change_status() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_invoice_change_status_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_invoice_change_status_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_invoice_change_status')) {
            wp_die('Invalid request', 403);
        }
        $invoice_id = (int) ($_POST['invoice_id'] ?? 0);
        $target_status = sanitize_key((string) ($_POST['target_status'] ?? ''));
        $status_note = sanitize_textarea_field((string) ($_POST['status_note'] ?? ''));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_invoice_portal_return_url($return_url_raw);

        $result = $this->set_invoice_status($invoice_id, $target_status, $user_id, $status_note);
        if (is_wp_error($result)) {
            $message = 'Status update failed: ' . $result->get_error_message();
        } else {
            $invoice_id = (int) ($result['id'] ?? $invoice_id);
            $message = 'Invoice marked ' . $this->get_invoice_status_label($target_status) . '.';
        }
        $redirect_args = [
            'cmn_invoice_msg' => $message,
        ];
        if ($invoice_id > 0) {
            $redirect_args['cmn_invoice_id'] = $invoice_id;
        }
        $redirect = add_query_arg($redirect_args, $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_invoice_add_adjustment() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_invoice_add_adjustment_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_invoice_add_adjustment_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_invoice_add_adjustment')) {
            wp_die('Invalid request', 403);
        }

        $invoice_id = (int) ($_POST['invoice_id'] ?? 0);
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_invoice_portal_return_url($return_url_raw);
        $invoice = $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            $redirect = add_query_arg(['cmn_invoice_msg' => 'Invoice not found.'], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $invoice_status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        if ($this->is_invoice_content_locked($invoice_status)) {
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => $this->get_invoice_lock_message($invoice_status),
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $type = sanitize_key((string) ($_POST['adjustment_type'] ?? ''));
        if (!in_array($type, ['manual_credit', 'fee'], true)) {
            $type = 'manual_credit';
        }
        $label = sanitize_text_field((string) ($_POST['adjustment_label'] ?? ''));
        $reason = sanitize_textarea_field((string) ($_POST['adjustment_reason'] ?? ''));
        $amount = round((float) ($_POST['adjustment_amount'] ?? 0), 2);
        if ($label === '' || $reason === '' || $amount <= 0) {
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => 'Label, reason, and amount are required.',
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $result = $this->add_invoice_adjustment([
            'invoice_id' => $invoice_id,
            'type' => $type,
            'label' => $label,
            'amount' => $amount,
            'created_by_user_id' => $user_id,
            'reason' => $reason,
        ], [
            'skip_permission_check' => true,
            'actor_user_id' => $user_id,
        ]);

        if (is_wp_error($result)) {
            $message = 'Adjustment failed: ' . $result->get_error_message();
        } else {
            $final_amount = (float) ($result['amount'] ?? 0);
            $this->add_audit_log('invoice_manual_adjustment_added', 'invoice', (string) $invoice_id, [
                'type' => $type,
                'label' => $label,
                'amount' => $final_amount,
            ], $user_id);
            $message = 'Adjustment added successfully.';
        }

        $redirect = add_query_arg([
            'cmn_invoice_id' => $invoice_id,
            'cmn_invoice_msg' => $message,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_invoice_record_payment() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }

        $invoice_id = max(0, (int) ($_POST['invoice_id'] ?? 0));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_invoice_portal_return_url($return_url_raw);
        if ($invoice_id < 1) {
            $redirect = add_query_arg(['cmn_invoice_msg' => 'Invalid invoice.'], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }
        $nonce = isset($_POST['cmn_invoice_record_payment_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_invoice_record_payment_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_invoice_record_payment_' . $invoice_id)) {
            wp_die('Invalid request', 403);
        }

        $invoice = $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => 'Invoice not found.',
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $status_before = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        $is_admin = $this->is_admin_user($user_id);
        if ($status_before === 'void') {
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => 'Cannot record payment on a void invoice.',
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        if ($status_before === 'paid' && !$is_admin) {
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => 'Invoice is already paid. Only Admin can add corrective payment entries.',
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $payment_amount = round((float) ($_POST['payment_amount'] ?? 0), 2);
        $payment_paid_at_input = isset($_POST['payment_paid_at']) ? wp_unslash((string) $_POST['payment_paid_at']) : '';
        $payment_method = sanitize_key((string) ($_POST['payment_method'] ?? 'other'));
        $payment_reference = sanitize_text_field((string) ($_POST['payment_reference'] ?? ''));
        $payment_note = sanitize_textarea_field((string) ($_POST['payment_note'] ?? ''));
        if ($payment_amount <= 0) {
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => 'Payment amount must be greater than zero.',
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $payment_record = $this->insert_invoice_payment_record([
            'invoice_id' => $invoice_id,
            'amount' => $payment_amount,
            'currency' => (string) ($invoice['currency'] ?? 'GBP'),
            'paid_at' => $payment_paid_at_input,
            'payment_method' => $payment_method,
            'payment_reference' => $payment_reference,
            'note' => $payment_note,
            'recorded_by_user_id' => $user_id,
        ], [
            'allow_paid_invoice' => $is_admin && $status_before === 'paid',
        ]);
        if (is_wp_error($payment_record)) {
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => 'Payment recording failed: ' . $payment_record->get_error_message(),
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }
        $payment_record = is_array($payment_record) ? $payment_record : [];

        $summary = $this->recalculate_invoice_payment_totals($invoice_id);
        if (is_wp_error($summary)) {
            $this->add_audit_log('invoice_payment_totals_refresh_failed', 'invoice', (string) $invoice_id, [
                'payment_id' => (int) ($payment_record['payment_id'] ?? 0),
                'error' => $summary->get_error_message(),
            ], $user_id);
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => 'Payment recorded but totals refresh failed: ' . $summary->get_error_message(),
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }
        $summary = is_array($summary) ? $summary : [];

        $status_result = $this->reconcile_invoice_status_after_payment(
            $invoice_id,
            $user_id,
            (string) ($summary['latest_paid_at'] ?? (string) ($payment_record['paid_at'] ?? ''))
        );
        $status_warning = '';
        if (is_wp_error($status_result)) {
            $status_warning = $status_result->get_error_message();
            $invoice_after = $this->get_invoice_by_id($invoice_id);
            if (!$invoice_after) {
                $invoice_after = $invoice;
            }
            $status_after = $this->normalize_invoice_status((string) ($invoice_after['status'] ?? $status_before));
        } else {
            $status_result = is_array($status_result) ? $status_result : [];
            $invoice_after = is_array($status_result['invoice'] ?? null) ? (array) $status_result['invoice'] : $this->get_invoice_by_id($invoice_id);
            if (!$invoice_after) {
                $invoice_after = $invoice;
            }
            $status_after = sanitize_key((string) ($status_result['to_status'] ?? $this->normalize_invoice_status((string) ($invoice_after['status'] ?? $status_before))));
        }

        $method_label = $this->get_invoice_payment_method_label((string) ($payment_record['payment_method'] ?? $payment_method));
        $paid_at_label = sanitize_text_field((string) ($payment_record['paid_at'] ?? ''));
        $audit_note = sprintf(
            'Payment recorded: GBP %s via %s, ref %s, paid_at %s',
            number_format((float) ($payment_record['amount'] ?? $payment_amount), 2),
            $method_label,
            sanitize_text_field((string) ($payment_record['payment_reference'] ?? $payment_reference)),
            $paid_at_label !== '' ? $paid_at_label : current_time('mysql')
        );
        if ($status_before === 'paid' && $is_admin) {
            $audit_note .= ' (additional payment entered on paid invoice)';
            $this->add_audit_log('invoice_payment_recorded_on_paid_invoice', 'invoice', (string) $invoice_id, [
                'amount' => round((float) ($payment_record['amount'] ?? $payment_amount), 2),
                'reference' => sanitize_text_field((string) ($payment_record['payment_reference'] ?? $payment_reference)),
                'method' => sanitize_key((string) ($payment_record['payment_method'] ?? $payment_method)),
            ], $user_id);
        }
        if ($payment_note !== '') {
            $audit_note .= '; note: ' . $payment_note;
        }
        if ($status_warning !== '') {
            $audit_note .= '; status warning: ' . $status_warning;
        }

        $this->log_invoice_audit_event($invoice_id, 'payment_recorded', [
            'invoice' => $invoice_after,
            'school_id' => (int) ($invoice_after['school_id'] ?? ($invoice['school_id'] ?? 0)),
            'from_status' => $status_before,
            'to_status' => $status_after,
            'amount_delta' => round((float) ($payment_record['amount'] ?? $payment_amount), 2),
            'user_id' => $user_id,
            'note' => $audit_note,
        ]);
        $this->add_audit_log('invoice_payment_recorded', 'invoice', (string) $invoice_id, [
            'school_id' => (int) ($invoice_after['school_id'] ?? ($invoice['school_id'] ?? 0)),
            'payment_id' => (int) ($payment_record['payment_id'] ?? 0),
            'amount' => round((float) ($payment_record['amount'] ?? $payment_amount), 2),
            'currency' => sanitize_text_field((string) ($payment_record['currency'] ?? ($invoice['currency'] ?? 'GBP'))),
            'paid_at' => $paid_at_label,
            'method' => sanitize_key((string) ($payment_record['payment_method'] ?? $payment_method)),
            'reference' => sanitize_text_field((string) ($payment_record['payment_reference'] ?? $payment_reference)),
            'amount_paid' => round((float) ($summary['amount_paid'] ?? 0), 2),
            'amount_due' => round((float) ($summary['amount_due'] ?? 0), 2),
            'status_before' => $status_before,
            'status_after' => $status_after,
            'status_warning' => $status_warning,
        ], $user_id);

        $message = sprintf(
            'Payment recorded: GBP %s. Amount paid: GBP %s. Amount due: GBP %s.',
            number_format((float) ($payment_record['amount'] ?? $payment_amount), 2),
            number_format((float) ($summary['amount_paid'] ?? 0), 2),
            number_format((float) ($summary['amount_due'] ?? 0), 2)
        );
        if ($status_before === 'paid' && $is_admin) {
            $message .= ' Additional payment was recorded on an already paid invoice.';
        }
        if ($status_warning !== '') {
            $message .= ' Status update warning: ' . $status_warning;
        }

        $redirect = add_query_arg([
            'cmn_invoice_id' => $invoice_id,
            'cmn_invoice_msg' => $message,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_invoice_send_email() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $invoice_id = max(0, (int) ($_POST['invoice_id'] ?? 0));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_invoice_portal_return_url($return_url_raw);
        if ($invoice_id < 1) {
            $redirect = add_query_arg(['cmn_invoice_msg' => 'Invalid invoice.'], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }
        $nonce = isset($_POST['cmn_invoice_send_email_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_invoice_send_email_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_invoice_send_email_' . $invoice_id)) {
            wp_die('Invalid request', 403);
        }

        $mode = sanitize_key((string) ($_POST['send_mode'] ?? 'send'));
        if (!in_array($mode, ['send', 'resend'], true)) {
            $mode = 'send';
        }
        $resend_confirmed = !empty($_POST['cmn_invoice_resend_confirm']);
        $resend_reason = sanitize_textarea_field((string) ($_POST['cmn_invoice_resend_reason'] ?? ''));

        $invoice = $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => 'Invoice not found.',
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }
        $status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        $school_id = (int) ($invoice['school_id'] ?? 0);
        $subject = $this->build_invoice_email_subject($invoice);
        if ($status === 'void') {
            $message = 'Void invoices cannot be emailed.';
            $this->insert_invoice_email_log_entry([
                'invoice_id' => $invoice_id,
                'school_id' => $school_id,
                'to_email' => '',
                'subject' => $subject,
                'sent_by_user_id' => $user_id,
                'status' => 'failed',
                'error_message' => $message,
                'note' => 'Email dispatch blocked for void invoice.',
            ]);
            $this->log_invoice_audit_event($invoice_id, 'email_failed', [
                'invoice' => $invoice,
                'school_id' => $school_id,
                'from_status' => $status,
                'to_status' => $status,
                'user_id' => $user_id,
                'note' => $message,
            ]);
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => $message,
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        if ($mode === 'send' && $status === 'sent') {
            $message = 'Invoice already marked sent. Use Resend Invoice with confirmation.';
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => $message,
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        if ($mode === 'resend') {
            $prior_sent_log = $this->get_latest_invoice_email_log_entry($invoice_id, 'sent');
            $has_prior_send = !empty($prior_sent_log)
                || !empty($invoice['sent_at'])
                || in_array($status, ['sent', 'paid'], true);
            if (!$has_prior_send) {
                $message = 'Resend is available only after an invoice has been sent once.';
                $redirect = add_query_arg([
                    'cmn_invoice_id' => $invoice_id,
                    'cmn_invoice_msg' => $message,
                ], $return_url);
                wp_safe_redirect($redirect);
                exit;
            }
            if (!$resend_confirmed || $resend_reason === '') {
                $message = 'Resend requires confirmation and a reason.';
                $redirect = add_query_arg([
                    'cmn_invoice_id' => $invoice_id,
                    'cmn_invoice_msg' => $message,
                ], $return_url);
                wp_safe_redirect($redirect);
                exit;
            }
        } else {
            $recent_sent = $this->get_recent_invoice_sent_log_entry($invoice_id, 24);
            if ($recent_sent) {
                $recent_time = sanitize_text_field((string) ($recent_sent['sent_at'] ?? ''));
                $recent_recipient = sanitize_email((string) ($recent_sent['to_email'] ?? ''));
                $message = 'Invoice already sent recently. Use "Resend" with confirmation.';
                $note = $message;
                if ($recent_time !== '') {
                    $note .= ' Last sent at ' . $recent_time . '.';
                }
                if ($recent_recipient !== '') {
                    $note .= ' Recipient: ' . $recent_recipient . '.';
                }
                $this->log_invoice_audit_event($invoice_id, 'email_send_blocked', [
                    'invoice' => $invoice,
                    'school_id' => $school_id,
                    'from_status' => $status,
                    'to_status' => $status,
                    'user_id' => $user_id,
                    'note' => $note,
                ]);
                $redirect = add_query_arg([
                    'cmn_invoice_id' => $invoice_id,
                    'cmn_invoice_msg' => $message,
                ], $return_url);
                wp_safe_redirect($redirect);
                exit;
            }
        }

        $recipient = $this->get_invoice_email_primary_recipient($invoice);
        $to_email = sanitize_email((string) ($recipient['email'] ?? ''));
        if ($to_email === '') {
            $message = 'Invoice email cannot be sent because both invoice email and billing email are blank.';
            $warning_note = 'Email blocked: invoice_email and billing_email were blank.';
            $this->insert_invoice_email_log_entry([
                'invoice_id' => $invoice_id,
                'school_id' => $school_id,
                'to_email' => '',
                'subject' => $subject,
                'sent_by_user_id' => $user_id,
                'status' => 'failed',
                'error_message' => $message,
                'note' => $warning_note,
            ]);
            $this->log_invoice_audit_event($invoice_id, 'email_failed', [
                'invoice' => $invoice,
                'school_id' => $school_id,
                'from_status' => $status,
                'to_status' => $status,
                'user_id' => $user_id,
                'note' => $warning_note,
            ]);
            $this->add_audit_log('invoice_email_send_blocked', 'invoice', (string) $invoice_id, [
                'school_id' => $school_id,
                'reason' => 'missing_recipient',
            ], $user_id);
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => $message,
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $document = $this->get_invoice_pdf_document($invoice, [
            'force_regenerate' => false,
        ]);
        if (is_wp_error($document)) {
            $error_message = 'Invoice PDF generation failed: ' . $document->get_error_message();
            $this->insert_invoice_email_log_entry([
                'invoice_id' => $invoice_id,
                'school_id' => $school_id,
                'to_email' => $to_email,
                'subject' => $subject,
                'sent_by_user_id' => $user_id,
                'status' => 'failed',
                'error_message' => $error_message,
                'note' => 'Email not sent because PDF generation failed.',
            ]);
            $this->log_invoice_audit_event($invoice_id, 'email_failed', [
                'invoice' => $invoice,
                'school_id' => $school_id,
                'from_status' => $status,
                'to_status' => $status,
                'user_id' => $user_id,
                'note' => $error_message,
            ]);
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => $error_message,
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }
        $document = is_array($document) ? $document : [];
        $attachment = $this->create_invoice_email_attachment_file($invoice, $document);
        if (is_wp_error($attachment)) {
            $error_message = 'Invoice PDF attachment failed: ' . $attachment->get_error_message();
            $this->insert_invoice_email_log_entry([
                'invoice_id' => $invoice_id,
                'school_id' => $school_id,
                'to_email' => $to_email,
                'subject' => $subject,
                'sent_by_user_id' => $user_id,
                'status' => 'failed',
                'error_message' => $error_message,
            ]);
            $this->log_invoice_audit_event($invoice_id, 'email_failed', [
                'invoice' => $invoice,
                'school_id' => $school_id,
                'from_status' => $status,
                'to_status' => $status,
                'user_id' => $user_id,
                'note' => $error_message,
            ]);
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => $error_message,
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }
        $attachment = is_array($attachment) ? $attachment : [];
        $attachment_path = (string) ($attachment['path'] ?? '');
        $cleanup_dir = (string) ($attachment['cleanup_dir'] ?? '');

        $school_name = $this->get_invoice_school_display_name(
            (int) ($invoice['school_id'] ?? 0),
            (string) ($invoice['school_name'] ?? '')
        );
        $bodies = $this->build_invoice_email_bodies($invoice, $school_name);
        $html_body = (string) ($bodies['html'] ?? '');
        $plain_body = (string) ($bodies['plain'] ?? '');
        $message_id = $this->build_invoice_email_message_id($invoice_id);
        $headers = [
            'Message-ID: ' . $message_id,
        ];
        if ($this->should_cc_invoice_sender()) {
            $user = get_user_by('id', $user_id);
            if ($user instanceof WP_User) {
                $sender_email = sanitize_email((string) ($user->user_email ?? ''));
                if ($sender_email !== '') {
                    $headers[] = 'Cc: ' . $sender_email;
                }
            }
        }

        $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
        $GLOBALS['cmn_school_mail_log_type'] = 'invoice_dispatch';
        $send_result = $this->send_school_email_with_alt_body(
            $to_email,
            $subject,
            $html_body,
            $plain_body,
            $headers,
            [$attachment_path]
        );
        if ($previous_log_type !== null) {
            $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
        } else {
            unset($GLOBALS['cmn_school_mail_log_type']);
        }
        $this->cleanup_invoice_email_attachment_file($attachment_path, $cleanup_dir);

        $send_result = is_array($send_result) ? $send_result : [];
        $sent = !empty($send_result['sent']);
        $mail_error = sanitize_textarea_field((string) ($send_result['error_message'] ?? ''));
        if (!$sent) {
            if ($mail_error === '') {
                $mail_error = 'wp_mail returned false.';
            }
            $this->insert_invoice_email_log_entry([
                'invoice_id' => $invoice_id,
                'school_id' => $school_id,
                'to_email' => $to_email,
                'subject' => $subject,
                'sent_by_user_id' => $user_id,
                'message_id' => $message_id,
                'status' => 'failed',
                'error_message' => $mail_error,
                'note' => $mode === 'resend' ? ('Resend reason: ' . $resend_reason) : '',
            ]);
            $this->log_invoice_audit_event($invoice_id, 'email_failed', [
                'invoice' => $invoice,
                'school_id' => $school_id,
                'from_status' => $status,
                'to_status' => $status,
                'user_id' => $user_id,
                'note' => 'Email to ' . $to_email . ' failed: ' . $mail_error,
            ]);
            $this->add_audit_log('invoice_email_failed', 'invoice', (string) $invoice_id, [
                'school_id' => $school_id,
                'to_email' => $to_email,
                'mode' => $mode,
                'error' => $mail_error,
            ], $user_id);
            $redirect = add_query_arg([
                'cmn_invoice_id' => $invoice_id,
                'cmn_invoice_msg' => 'Invoice email failed: ' . $mail_error,
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $status_transition = [
            'from_status' => $status,
            'to_status' => $status,
        ];
        $status_warning = '';
        if (in_array($status, ['draft', 'issued'], true)) {
            $transition_result = $this->transition_invoice_status_after_email_send($invoice, $user_id, $to_email);
            if (is_wp_error($transition_result)) {
                $status_warning = $transition_result->get_error_message();
            } else {
                $status_transition['from_status'] = (string) ($transition_result['from_status'] ?? $status);
                $status_transition['to_status'] = (string) ($transition_result['to_status'] ?? $status);
                $invoice = is_array($transition_result['invoice'] ?? null) ? (array) $transition_result['invoice'] : $invoice;
            }
        }

        $email_note = 'Invoice emailed to ' . $to_email . '.';
        if ($mode === 'resend') {
            $email_note .= ' Resend reason: ' . $resend_reason . '.';
        }
        if ($status_warning !== '') {
            $email_note .= ' Status transition warning: ' . $status_warning . '.';
        }
        $this->insert_invoice_email_log_entry([
            'invoice_id' => $invoice_id,
            'school_id' => $school_id,
            'to_email' => $to_email,
            'subject' => $subject,
            'sent_by_user_id' => $user_id,
            'message_id' => $message_id,
            'status' => 'sent',
            'note' => $mode === 'resend' ? ('Resend reason: ' . $resend_reason) : '',
        ]);
        $this->log_invoice_audit_event($invoice_id, 'email_sent', [
            'invoice' => $invoice,
            'school_id' => $school_id,
            'from_status' => $status_transition['from_status'],
            'to_status' => $status_transition['to_status'],
            'user_id' => $user_id,
            'note' => $email_note,
        ]);
        $this->add_audit_log('invoice_email_sent', 'invoice', (string) $invoice_id, [
            'school_id' => $school_id,
            'to_email' => $to_email,
            'mode' => $mode,
            'message_id' => $message_id,
            'from_status' => $status_transition['from_status'],
            'to_status' => $status_transition['to_status'],
            'status_warning' => $status_warning,
            'resend_reason' => $mode === 'resend' ? $resend_reason : '',
        ], $user_id);

        $message = 'Invoice email sent to ' . $to_email . '.';
        if ($mode === 'resend') {
            $message = 'Invoice email resent to ' . $to_email . '.';
        }
        if ($status_warning !== '') {
            $message .= ' Status update warning: ' . $status_warning;
        }
        $redirect = add_query_arg([
            'cmn_invoice_id' => $invoice_id,
            'cmn_invoice_msg' => $message,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_download_invoice_pdf() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        $invoice_id = max(0, (int) ($_REQUEST['invoice_id'] ?? 0));
        if ($invoice_id < 1) {
            wp_die('Invoice not found.', 404);
        }
        $nonce = isset($_REQUEST['cmn_invoice_pdf_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_REQUEST['cmn_invoice_pdf_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_download_invoice_pdf_' . $invoice_id)) {
            wp_die('Invalid request', 403);
        }

        $invoice = $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            wp_die('Invoice not found.', 404);
        }
        if (!$this->can_user_access_invoice_pdf($invoice, $user_id)) {
            wp_die('Unauthorized', 403);
        }

        $document = $this->get_invoice_pdf_document($invoice, [
            'force_regenerate' => !empty($_REQUEST['cmn_invoice_pdf_refresh']),
        ]);
        if (is_wp_error($document)) {
            wp_die('Unable to generate invoice PDF: ' . esc_html($document->get_error_message()), 500);
        }
        $document = is_array($document) ? $document : [];
        $download_name = (string) ($document['download_name'] ?? $this->get_invoice_pdf_download_filename($invoice));
        $binary = (string) ($document['binary'] ?? '');
        $file_path = (string) ($document['file_path'] ?? '');
        $use_file = $file_path !== '' && is_readable($file_path);
        $content_length = 0;
        if ($use_file) {
            $content_length = max(0, (int) @filesize($file_path));
        } elseif ($binary !== '') {
            $content_length = strlen($binary);
        } else {
            wp_die('Invoice PDF was empty.', 500);
        }

        $audit_note = 'Invoice PDF generated for download.';
        $this->log_invoice_audit_event($invoice_id, 'invoice_pdf_generated', [
            'invoice' => $invoice,
            'school_id' => (int) ($invoice['school_id'] ?? 0),
            'user_id' => $user_id,
            'note' => $audit_note,
        ]);
        $this->add_audit_log('invoice_pdf_generated', 'invoice', (string) $invoice_id, [
            'school_id' => (int) ($invoice['school_id'] ?? 0),
            'cached_file' => $use_file ? 1 : 0,
            'download_name' => $download_name,
            'size' => $content_length,
        ], $user_id);

        if (!headers_sent()) {
            nocache_headers();
            header('Content-Type: application/pdf');
            header('X-Content-Type-Options: nosniff');
            header('Content-Disposition: attachment; filename="' . str_replace('"', '', $download_name) . '"');
            if ($content_length > 0) {
                header('Content-Length: ' . $content_length);
            }
        }
        if ($use_file) {
            $fh = @fopen($file_path, 'rb');
            if ($fh) {
                while (!feof($fh)) {
                    $chunk = fread($fh, 8192);
                    if ($chunk === false) {
                        break;
                    }
                    echo $chunk;
                }
                fclose($fh);
                exit;
            }
        }
        echo $binary;
        exit;
    }

    public function handle_partner_programme_recalculate() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_partner_programme_recalculate_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_partner_programme_recalculate_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_partner_programme_recalculate')) {
            wp_die('Invalid request', 403);
        }

        $school_id = max(0, (int) ($_POST['school_id'] ?? 0));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_partner_programme_portal_return_url($return_url_raw);

        $result = $this->recalculate_school_partner_profile_for_staff($school_id, $user_id, 'staff_partner_manual_recalculate');
        if (is_wp_error($result)) {
            $message = 'Recalculation failed: ' . $result->get_error_message();
            $msg_type = 'error';
        } else {
            $message = 'Partner tier and savings recalculated successfully.';
            $msg_type = 'success';
        }
        $redirect = add_query_arg([
            'cmn_partner_school_id' => $school_id > 0 ? $school_id : null,
            'cmn_partner_msg' => rawurlencode($message),
            'cmn_partner_msg_type' => $msg_type,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_partner_programme_adjust_credits() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_partner_programme_adjust_credits_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_partner_programme_adjust_credits_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_partner_programme_adjust_credits')) {
            wp_die('Invalid request', 403);
        }

        $school_id = max(0, (int) ($_POST['school_id'] ?? 0));
        $delta = (int) ($_POST['delta'] ?? 0);
        $reason = sanitize_textarea_field((string) ($_POST['reason'] ?? ''));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_partner_programme_portal_return_url($return_url_raw);

        if ($reason === '' || $delta === 0) {
            $redirect = add_query_arg([
                'cmn_partner_school_id' => $school_id > 0 ? $school_id : null,
                'cmn_partner_msg' => rawurlencode('Delta and reason are required.'),
                'cmn_partner_msg_type' => 'error',
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $result = $this->apply_school_partner_admin_credit_delta($school_id, $delta, $reason, $user_id);
        if (is_wp_error($result)) {
            $message = 'Credit adjustment failed: ' . $result->get_error_message();
            $msg_type = 'error';
        } else {
            $message = 'Partner credits adjusted successfully.';
            $msg_type = 'success';
        }
        $redirect = add_query_arg([
            'cmn_partner_school_id' => $school_id > 0 ? $school_id : null,
            'cmn_partner_msg' => rawurlencode($message),
            'cmn_partner_msg_type' => $msg_type,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

