    public function handle_staff_candidate_rewards_recalculate() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_staff_candidate_rewards_recalculate_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_staff_candidate_rewards_recalculate_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_staff_candidate_rewards_recalculate')) {
            wp_die('Invalid request', 403);
        }

        $candidate_id = max(0, (int) ($_POST['candidate_id'] ?? 0));
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) ($_POST['academic_year'] ?? ''), current_time('Y-m-d'));
        $reason = sanitize_textarea_field((string) ($_POST['reason'] ?? ''));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_candidate_rewards_staff_portal_return_url($return_url_raw);

        if ($candidate_id < 1 || $reason === '') {
            $redirect = add_query_arg([
                'cmn_rewards_candidate_id' => $candidate_id > 0 ? $candidate_id : null,
                'cmn_rewards_year' => $academic_year,
                'cmn_rewards_msg' => rawurlencode('Candidate and reason are required.'),
                'cmn_rewards_msg_type' => 'error',
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $result = $this->run_staff_candidate_rewards_recalculation(
            $candidate_id,
            $academic_year,
            $reason,
            $user_id,
            'staff_console_recalculate'
        );
        if (is_wp_error($result)) {
            $message = 'Recalculation failed: ' . $result->get_error_message();
            $msg_type = 'error';
        } else {
            $message = 'Candidate rewards state recalculated.';
            $msg_type = 'success';
        }

        $redirect = add_query_arg([
            'cmn_rewards_candidate_id' => $candidate_id,
            'cmn_rewards_year' => $academic_year,
            'cmn_rewards_msg' => rawurlencode($message),
            'cmn_rewards_msg_type' => $msg_type,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

