        );
        if (is_wp_error($result)) {
            $message = 'Termination failed: ' . $result->get_error_message();
            $msg_type = 'error';
        } else {
            $access_result = is_array($result['access_result'] ?? null) ? (array) $result['access_result'] : [];
            if (!empty($access_result['disabled'])) {
                $message = 'Candidate terminated and portal access disabled.';
            } else {
                $message = 'Candidate terminated. Portal disable requires follow-up.';
            }
            $msg_type = 'success';
