        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_staff_candidate_rewards_reverse_no_show() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->can_manage_candidate_rewards_no_show_overrides($user_id)) {
            wp_die('Unauthorized', 403);
        }
        $nonce = isset($_POST['cmn_staff_candidate_rewards_reverse_no_show_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_staff_candidate_rewards_reverse_no_show_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_staff_candidate_rewards_reverse_no_show')) {
            wp_die('Invalid request', 403);
        }

        $candidate_id = max(0, (int) ($_POST['candidate_id'] ?? 0));
        $booking_id = max(0, (int) ($_POST['booking_id'] ?? 0));
        $shift_date = $this->normalize_invoice_date((string) ($_POST['shift_date'] ?? ''));
        $reversal_reason = sanitize_textarea_field((string) ($_POST['reason'] ?? ''));
        $confirm_checked = !empty($_POST['cmn_override_confirm']) ? 1 : 0;
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_candidate_rewards_staff_portal_return_url($return_url_raw);

        $academic_year = $shift_date !== ''
            ? $this->normalize_candidate_rewards_academic_year_label('', $shift_date)
            : $this->normalize_candidate_rewards_academic_year_label('', current_time('Y-m-d'));
        if ($candidate_id < 1 || $booking_id < 1 || $shift_date === '' || $reversal_reason === '' || !$confirm_checked) {
            $redirect = add_query_arg([
                'cmn_rewards_candidate_id' => $candidate_id > 0 ? $candidate_id : null,
                'cmn_rewards_year' => $academic_year,
                'cmn_rewards_msg' => rawurlencode('Candidate, booking, shift date, reason, and confirmation are required.'),
                'cmn_rewards_msg_type' => 'error',
            ], $return_url);
            wp_safe_redirect($redirect);
            exit;
        }

        $result = $this->reverse_candidate_no_show_penalty_for_override(
            $candidate_id,
            $booking_id,
            $shift_date,
            $reversal_reason,
            $user_id,
            [
                'source' => 'staff_console_no_show_override',
            ]
        );
        if (is_wp_error($result)) {
            $message = 'No-show reversal failed: ' . $result->get_error_message();
            $msg_type = 'error';
        } else {
            $message = 'No-show reversed successfully.';
            if (!empty($result['finance_manual_review_required'])) {
                $message .= ' Finance review is required before any payout changes.';
            }
            $msg_type = 'success';
        }

        $redirect = add_query_arg([
            'cmn_rewards_candidate_id' => $candidate_id,
            'cmn_rewards_year' => $academic_year,
            'cmn_rewards_msg' => rawurlencode($message),
            'cmn_rewards_msg_type' => $msg_type,
        ], $return_url);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_staff_candidate_rewards_adjust_shifts() {
        $candidate_id = max(0, (int) ($_POST['candidate_id'] ?? 0));
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) ($_POST['academic_year'] ?? ''), current_time('Y-m-d'));
        $delta = (int) ($_POST['delta'] ?? 0);
        $reason = sanitize_textarea_field((string) ($_POST['reason'] ?? ''));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_candidate_rewards_staff_portal_return_url($return_url_raw);

        if (!is_user_logged_in()) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Not authorised.', 'error');
        }
        $nonce = isset($_POST['cmn_staff_candidate_rewards_adjust_shifts_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_staff_candidate_rewards_adjust_shifts_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_staff_candidate_rewards_adjust_shifts')) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Invalid request.', 'error');
        }
        if ($candidate_id < 1 || $delta === 0 || $reason === '') {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Candidate, non-zero delta, and reason are required.', 'error');
        }

        $capability = $this->assert_staff_candidate_rewards_mutation_capability([
            'candidate_id' => $candidate_id,
            'academic_year' => $academic_year,
            'action' => 'adjust_shifts',
        ]);
        if (is_wp_error($capability)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $capability->get_error_message(), 'error');
        }

        $actor_user_id = (int) ($capability['user_id'] ?? 0);
        $is_admin = !empty($capability['is_admin']);
        if (!$is_admin) {
            $limit = $this->get_staff_candidate_rewards_shift_adjust_limit($actor_user_id);
            if (abs($delta) > $limit) {
                $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, sprintf('Staff adjustments are limited to +/- %d shifts per action.', $limit), 'error');
            }
        }

        $candidate_user_id = $this->resolve_staff_candidate_rewards_candidate_user_id($candidate_id);
        if (is_wp_error($candidate_user_id)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $candidate_user_id->get_error_message(), 'error');
        }
        $candidate_user_id = (int) $candidate_user_id;

        $before = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($before)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $before->get_error_message(), 'error');
        }
        $before = is_array($before) ? $before : [];
        $before_cycle_count = max(0, (int) ($before['shift_cycle_count'] ?? 0));
        $before_year_total = max(0, (int) ($before['academic_year_shift_total'] ?? 0));

        $after_cycle_count = max(0, $before_cycle_count + $delta);
        $after_year_total = max(0, $before_year_total + $delta);

        $updated = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'shift_cycle_count' => $after_cycle_count,
            'academic_year_shift_total' => $after_year_total,
        ]);
        if (is_wp_error($updated)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Shift adjustment failed: ' . $updated->get_error_message(), 'error');
        }

        $tier_sync = $this->rewards_apply_tier_if_needed($candidate_user_id, $academic_year, $actor_user_id);
        if (is_wp_error($tier_sync)) {
            $this->add_audit_log('candidate_rewards_staff_shift_adjust_tier_sync_failed', 'candidate', (string) $candidate_id, [
                'academic_year' => $academic_year,
                'candidate_user_id' => $candidate_user_id,
                'message' => $tier_sync->get_error_message(),
            ], $actor_user_id);
            $after = is_array($updated) ? $updated : [];
        } else {
            $after = is_array($tier_sync['row'] ?? null) ? (array) $tier_sync['row'] : (is_array($updated) ? $updated : []);
        }
        $after = is_array($after) ? $after : [];

        $this->log_staff_candidate_rewards_override_audit('admin_shift_adjust', $candidate_user_id, $actor_user_id, [
            'candidate_id' => $candidate_id,
            'candidate_user_id' => $candidate_user_id,
            'academic_year' => $academic_year,
            'delta' => $delta,
            'reason' => $reason,
            'actor_user_id' => $actor_user_id,
            'previous' => [
                'shift_cycle_count' => $before_cycle_count,
                'academic_year_shift_total' => $before_year_total,
                'tier' => $this->normalize_candidate_rewards_tier((string) ($before['tier'] ?? 'standard')),
                'multiplier' => round((float) ($before['multiplier'] ?? 1.00), 2),
                'status' => $this->resolve_staff_candidate_rewards_row_status($before),
            ],
            'new' => [
                'shift_cycle_count' => max(0, (int) ($after['shift_cycle_count'] ?? $after_cycle_count)),
                'academic_year_shift_total' => max(0, (int) ($after['academic_year_shift_total'] ?? $after_year_total)),
                'tier' => $this->normalize_candidate_rewards_tier((string) ($after['tier'] ?? ($before['tier'] ?? 'standard'))),
                'multiplier' => round((float) ($after['multiplier'] ?? ($before['multiplier'] ?? 1.00)), 2),
                'status' => $this->resolve_staff_candidate_rewards_row_status($after),
            ],
        ]);

        $this->redirect_staff_candidate_rewards_action(
            $return_url,
            $candidate_id,
            $academic_year,
            sprintf(
                'Shift count adjusted by %d. Year shifts now %d.',
                $delta,
                max(0, (int) ($after['academic_year_shift_total'] ?? $after_year_total))
            ),
            'success'
        );
    }

    public function handle_staff_candidate_rewards_set_tier() {
        $candidate_id = max(0, (int) ($_POST['candidate_id'] ?? 0));
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) ($_POST['academic_year'] ?? ''), current_time('Y-m-d'));
        $target_tier_raw = sanitize_key((string) ($_POST['tier'] ?? ''));
        $target_tier = $this->normalize_candidate_rewards_tier($target_tier_raw);
        $reason = sanitize_textarea_field((string) ($_POST['reason'] ?? ''));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_candidate_rewards_staff_portal_return_url($return_url_raw);

        if (!is_user_logged_in()) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Not authorised.', 'error');
        }
        $nonce = isset($_POST['cmn_staff_candidate_rewards_set_tier_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_staff_candidate_rewards_set_tier_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_staff_candidate_rewards_set_tier')) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Invalid request.', 'error');
        }
        if ($candidate_id < 1 || $reason === '') {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Candidate and reason are required.', 'error');
        }
        if (!in_array($target_tier_raw, $this->get_candidate_rewards_tier_order(), true)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Invalid tier selection.', 'error');
        }

        $capability = $this->assert_staff_candidate_rewards_mutation_capability([
            'candidate_id' => $candidate_id,
            'academic_year' => $academic_year,
            'action' => 'set_tier',
        ]);
        if (is_wp_error($capability)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $capability->get_error_message(), 'error');
        }
        $actor_user_id = (int) ($capability['user_id'] ?? 0);
        $is_admin = !empty($capability['is_admin']);

        $candidate_user_id = $this->resolve_staff_candidate_rewards_candidate_user_id($candidate_id);
        if (is_wp_error($candidate_user_id)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $candidate_user_id->get_error_message(), 'error');
        }
        $candidate_user_id = (int) $candidate_user_id;

        $before = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($before)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $before->get_error_message(), 'error');
        }
        $before = is_array($before) ? $before : [];
        $before_tier = $this->normalize_candidate_rewards_tier((string) ($before['tier'] ?? 'standard'));
        $before_rank = $this->get_candidate_rewards_tier_rank($before_tier);
        $target_rank = $this->get_candidate_rewards_tier_rank($target_tier);

        if (!$is_admin && $target_rank < $before_rank) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Tier downgrades are admin-only.', 'error');
        }

        if ($target_tier === $before_tier) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Tier is already set to that value.', 'warning');
        }

        $config_row = $this->get_rewards_config_row_for_academic_year($academic_year, current_time('Y-m-d'));
        $multiplier_map = $this->get_candidate_rewards_tier_multiplier_map(is_array($config_row) ? $config_row : []);
        $target_multiplier = round((float) ($multiplier_map[$target_tier] ?? $this->get_candidate_rewards_multiplier_for_tier($target_tier)), 2);
        if ($target_multiplier <= 0) {
            $target_multiplier = $this->get_candidate_rewards_multiplier_for_tier($target_tier);
        }

        $updated = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'tier' => $target_tier,
            'multiplier' => $target_multiplier,
            'last_tier_change_at' => current_time('mysql'),
        ]);
        if (is_wp_error($updated)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Tier override failed: ' . $updated->get_error_message(), 'error');
        }
        $after = is_array($updated) ? $updated : [];

        $this->log_staff_candidate_rewards_override_audit('admin_set_tier', $candidate_user_id, $actor_user_id, [
            'candidate_id' => $candidate_id,
            'candidate_user_id' => $candidate_user_id,
            'academic_year' => $academic_year,
            'reason' => $reason,
            'actor_user_id' => $actor_user_id,
            'previous' => [
                'tier' => $before_tier,
                'multiplier' => round((float) ($before['multiplier'] ?? 1.00), 2),
                'status' => $this->resolve_staff_candidate_rewards_row_status($before),
            ],
            'new' => [
                'tier' => $this->normalize_candidate_rewards_tier((string) ($after['tier'] ?? $target_tier)),
                'multiplier' => round((float) ($after['multiplier'] ?? $target_multiplier), 2),
                'status' => $this->resolve_staff_candidate_rewards_row_status($after),
            ],
        ]);

        $this->redirect_staff_candidate_rewards_action(
            $return_url,
            $candidate_id,
            $academic_year,
            sprintf('Tier set to %s.', $this->get_candidate_rewards_tier_label($target_tier)),
            'success'
        );
    }

