            'candidate_id' => $candidate_id,
            'candidate_user_id' => $candidate_user_id,
            'academic_year' => $academic_year,
            'reason' => $reason,
            'actor_user_id' => $actor_user_id,
            'previous' => [
                'status' => $before_status,
                'rewards_paused' => !empty($before['rewards_paused']) ? 1 : 0,
                'review_required' => !empty($before['review_required']) ? 1 : 0,
                'conduct_status' => $this->normalize_candidate_rewards_conduct_status((string) ($before['conduct_status'] ?? 'clear')),
            ],
            'new' => [
                'status' => $this->resolve_staff_candidate_rewards_row_status($after),
                'rewards_paused' => !empty($after['rewards_paused']) ? 1 : 0,
                'review_required' => !empty($after['review_required']) ? 1 : 0,
                'conduct_status' => $this->normalize_candidate_rewards_conduct_status((string) ($after['conduct_status'] ?? 'clear')),
            ],
        ]);

        $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Rewards suspended for this candidate.', 'success');
    }

    public function handle_staff_candidate_rewards_reinstate() {
        $candidate_id = max(0, (int) ($_POST['candidate_id'] ?? 0));
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) ($_POST['academic_year'] ?? ''), current_time('Y-m-d'));
        $reason = sanitize_textarea_field((string) ($_POST['reason'] ?? ''));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_candidate_rewards_staff_portal_return_url($return_url_raw);

        if (!is_user_logged_in()) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Not authorised.', 'error');
        }
        $nonce = isset($_POST['cmn_staff_candidate_rewards_reinstate_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_staff_candidate_rewards_reinstate_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_staff_candidate_rewards_reinstate')) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Invalid request.', 'error');
        }
        if ($candidate_id < 1 || $reason === '') {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Candidate and reason are required.', 'error');
        }

        $capability = $this->assert_staff_candidate_rewards_mutation_capability([
            'candidate_id' => $candidate_id,
            'academic_year' => $academic_year,
            'action' => 'reinstate',
        ]);
        if (is_wp_error($capability)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $capability->get_error_message(), 'error');
        }
        $actor_user_id = (int) ($capability['user_id'] ?? 0);
        $is_admin = !empty($capability['is_admin']);

        $candidate_user_id = $this->resolve_staff_candidate_rewards_candidate_user_id($candidate_id);
        if (is_wp_error($candidate_user_id)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $candidate_user_id->get_error_message(), 'error');
        }
        $candidate_user_id = (int) $candidate_user_id;

        $before = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($before)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $before->get_error_message(), 'error');
        }
        $before = is_array($before) ? $before : [];
        $before_status = $this->resolve_staff_candidate_rewards_row_status($before);
        if ($before_status === 'terminated' && !$is_admin) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Only admin can reinstate a terminated candidate.', 'error');
        }

        $before_conduct = $this->normalize_candidate_rewards_conduct_status((string) ($before['conduct_status'] ?? 'clear'));
        $before_no_shows = max(0, (int) ($before['no_show_count'] ?? 0));
        $target_conduct = $before_conduct;
        if ($before_conduct === 'terminated') {
            $target_conduct = $this->resolve_conduct_status_from_no_show_count($before_no_shows);
            if ($target_conduct === 'terminated') {
                $target_conduct = 'red';
            }
        }

        $updated = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'rewards_paused' => 0,
            'review_required' => 0,
            'conduct_status' => $target_conduct,
        ]);
        if (is_wp_error($updated)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Reinstatement failed: ' . $updated->get_error_message(), 'error');
        }
        $after = is_array($updated) ? $updated : [];

        $this->log_staff_candidate_rewards_override_audit('admin_reinstate', $candidate_user_id, $actor_user_id, [
            'candidate_id' => $candidate_id,
            'candidate_user_id' => $candidate_user_id,
            'academic_year' => $academic_year,
            'reason' => $reason,
            'actor_user_id' => $actor_user_id,
            'previous' => [
                'status' => $before_status,
                'rewards_paused' => !empty($before['rewards_paused']) ? 1 : 0,
                'review_required' => !empty($before['review_required']) ? 1 : 0,
                'conduct_status' => $before_conduct,
                'no_show_count' => $before_no_shows,
            ],
            'new' => [
                'status' => $this->resolve_staff_candidate_rewards_row_status($after),
                'rewards_paused' => !empty($after['rewards_paused']) ? 1 : 0,
                'review_required' => !empty($after['review_required']) ? 1 : 0,
                'conduct_status' => $this->normalize_candidate_rewards_conduct_status((string) ($after['conduct_status'] ?? $target_conduct)),
                'no_show_count' => max(0, (int) ($after['no_show_count'] ?? $before_no_shows)),
            ],
        ]);

        $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Rewards reinstated for this candidate.', 'success');
    }

    public function handle_staff_candidate_rewards_mark_no_show() {
        $candidate_id = max(0, (int) ($_POST['candidate_id'] ?? 0));
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) ($_POST['academic_year'] ?? ''), current_time('Y-m-d'));
        $booking_id = max(0, (int) ($_POST['booking_id'] ?? 0));
        $reason = sanitize_textarea_field((string) ($_POST['reason'] ?? ''));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_candidate_rewards_staff_portal_return_url($return_url_raw);

        if (!is_user_logged_in()) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Not authorised.', 'error');
        }
        $nonce = isset($_POST['cmn_staff_candidate_rewards_mark_no_show_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_staff_candidate_rewards_mark_no_show_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_staff_candidate_rewards_mark_no_show')) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Invalid request.', 'error');
        }
        if ($candidate_id < 1 || $booking_id < 1 || $reason === '') {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Candidate, booking, and reason are required.', 'error');
        }

        $capability = $this->assert_staff_candidate_rewards_mutation_capability([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'academic_year' => $academic_year,
            'action' => 'mark_no_show',
        ]);
        if (is_wp_error($capability)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $capability->get_error_message(), 'error');
        }
        $actor_user_id = (int) ($capability['user_id'] ?? 0);

        $candidate_user_id = $this->resolve_staff_candidate_rewards_candidate_user_id($candidate_id);
        if (is_wp_error($candidate_user_id)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $candidate_user_id->get_error_message(), 'error');
        }
        $candidate_user_id = (int) $candidate_user_id;

        $shift_date = $this->resolve_no_show_shift_date_for_booking($booking_id);
        $effective_year = $shift_date !== ''
            ? $this->normalize_candidate_rewards_academic_year_label('', $shift_date)
            : $academic_year;
        $before = $this->get_or_create_candidate_rewards($candidate_id, $effective_year);
        if (is_wp_error($before)) {
            $before = [];
        }
        $before = is_array($before) ? $before : [];

        $result = $this->conduct_record_no_show($candidate_user_id, $booking_id, $reason, $actor_user_id);
        if (is_wp_error($result)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $effective_year, 'No-show record failed: ' . $result->get_error_message(), 'error');
        }
        $result = is_array($result) ? $result : [];
        $resolved_shift_date = $this->normalize_invoice_date((string) ($result['shift_date'] ?? $shift_date));
        $effective_year = $resolved_shift_date !== ''
            ? $this->normalize_candidate_rewards_academic_year_label('', $resolved_shift_date)
            : $effective_year;

        $after = $this->get_or_create_candidate_rewards($candidate_id, $effective_year);
        if (is_wp_error($after)) {
            $after = [];
        }
        $after = is_array($after) ? $after : [];

        $this->log_staff_candidate_rewards_override_audit('admin_mark_no_show', $candidate_user_id, $actor_user_id, [
            'candidate_id' => $candidate_id,
            'candidate_user_id' => $candidate_user_id,
            'academic_year' => $effective_year,
            'booking_id' => $booking_id,
            'reason' => $reason,
            'actor_user_id' => $actor_user_id,
            'shift_date' => $resolved_shift_date,
            'result' => [
                'conduct_event_id' => (int) ($result['conduct_event_id'] ?? 0),
                'decision_status' => sanitize_key((string) ($result['conduct_status'] ?? '')),
                'terminated' => !empty($result['terminated']) ? 1 : 0,
            ],
            'previous' => [
                'no_show_count' => max(0, (int) ($before['no_show_count'] ?? 0)),
                'conduct_status' => $this->normalize_candidate_rewards_conduct_status((string) ($before['conduct_status'] ?? 'clear')),
                'status' => $this->resolve_staff_candidate_rewards_row_status($before),
                'academic_year_shift_total' => max(0, (int) ($before['academic_year_shift_total'] ?? 0)),
            ],
            'new' => [
                'no_show_count' => max(0, (int) ($after['no_show_count'] ?? 0)),
                'conduct_status' => $this->normalize_candidate_rewards_conduct_status((string) ($after['conduct_status'] ?? 'clear')),
                'status' => $this->resolve_staff_candidate_rewards_row_status($after),
                'academic_year_shift_total' => max(0, (int) ($after['academic_year_shift_total'] ?? 0)),
            ],
        ]);

        $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $effective_year, 'No-show recorded successfully.', 'success');
    }

    public function handle_staff_candidate_rewards_resolve_appeal() {
        $candidate_id = max(0, (int) ($_POST['candidate_id'] ?? 0));
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) ($_POST['academic_year'] ?? ''), current_time('Y-m-d'));
        $booking_id = max(0, (int) ($_POST['booking_id'] ?? 0));
        $decision = sanitize_key((string) ($_POST['decision'] ?? ''));
        $reason = sanitize_textarea_field((string) ($_POST['reason'] ?? ''));
        $return_url_raw = isset($_POST['cmn_return_url']) ? wp_unslash((string) $_POST['cmn_return_url']) : '';
        $return_url = $this->get_candidate_rewards_staff_portal_return_url($return_url_raw);

        if (!is_user_logged_in()) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Not authorised.', 'error');
        }
        $nonce = isset($_POST['cmn_staff_candidate_rewards_resolve_appeal_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_staff_candidate_rewards_resolve_appeal_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_staff_candidate_rewards_resolve_appeal')) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Invalid request.', 'error');
        }
        if ($candidate_id < 1 || $booking_id < 1 || $reason === '') {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Candidate, booking, decision, and reason are required.', 'error');
        }
        if ($decision === 'approve') {
            $decision = 'approved';
        } elseif ($decision === 'reject') {
            $decision = 'rejected';
        }
        if (!in_array($decision, ['approved', 'rejected'], true)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, 'Invalid appeal decision.', 'error');
        }

        $capability = $this->assert_staff_candidate_rewards_mutation_capability([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'academic_year' => $academic_year,
            'action' => 'resolve_appeal',
        ]);
        if (is_wp_error($capability)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $capability->get_error_message(), 'error');
        }
        $actor_user_id = (int) ($capability['user_id'] ?? 0);

        $candidate_user_id = $this->resolve_staff_candidate_rewards_candidate_user_id($candidate_id);
        if (is_wp_error($candidate_user_id)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $academic_year, $candidate_user_id->get_error_message(), 'error');
        }
        $candidate_user_id = (int) $candidate_user_id;

        $shift_date = $this->resolve_no_show_shift_date_for_booking($booking_id);
        $effective_year = $shift_date !== ''
            ? $this->normalize_candidate_rewards_academic_year_label('', $shift_date)
            : $academic_year;
        $before = $this->get_or_create_candidate_rewards($candidate_id, $effective_year);
        if (is_wp_error($before)) {
            $before = [];
        }
        $before = is_array($before) ? $before : [];

        $result = $this->conduct_resolve_appeal($candidate_user_id, $booking_id, $decision, $reason, $actor_user_id);
        if (is_wp_error($result)) {
            $this->redirect_staff_candidate_rewards_action($return_url, $candidate_id, $effective_year, 'Appeal resolution failed: ' . $result->get_error_message(), 'error');
        }
        $result = is_array($result) ? $result : [];
        $resolved_shift_date = $this->normalize_invoice_date((string) ($result['shift_date'] ?? $shift_date));
        $effective_year = $resolved_shift_date !== ''
            ? $this->normalize_candidate_rewards_academic_year_label('', $resolved_shift_date)
            : $effective_year;
        $after = $this->get_or_create_candidate_rewards($candidate_id, $effective_year);
        if (is_wp_error($after)) {
            $after = [];
        }
        $after = is_array($after) ? $after : [];

        $this->log_staff_candidate_rewards_override_audit('admin_resolve_appeal', $candidate_user_id, $actor_user_id, [
            'candidate_id' => $candidate_id,
            'candidate_user_id' => $candidate_user_id,
            'academic_year' => $effective_year,
            'booking_id' => $booking_id,
            'decision' => $decision,
            'reason' => $reason,
            'actor_user_id' => $actor_user_id,
            'shift_date' => $resolved_shift_date,
            'result' => [
                'appeal_event_id' => (int) ($result['appeal_event_id'] ?? 0),
                'reversed_no_show_event_id' => (int) ($result['reversed_no_show_event_id'] ?? 0),
                'resolved_decision' => sanitize_key((string) ($result['decision'] ?? $decision)),
            ],
            'previous' => [
                'no_show_count' => max(0, (int) ($before['no_show_count'] ?? 0)),
                'conduct_status' => $this->normalize_candidate_rewards_conduct_status((string) ($before['conduct_status'] ?? 'clear')),
                'status' => $this->resolve_staff_candidate_rewards_row_status($before),
                'academic_year_shift_total' => max(0, (int) ($before['academic_year_shift_total'] ?? 0)),
            ],
            'new' => [
                'no_show_count' => max(0, (int) ($after['no_show_count'] ?? 0)),
                'conduct_status' => $this->normalize_candidate_rewards_conduct_status((string) ($after['conduct_status'] ?? 'clear')),
                'status' => $this->resolve_staff_candidate_rewards_row_status($after),
                'academic_year_shift_total' => max(0, (int) ($after['academic_year_shift_total'] ?? 0)),
            ],
        ]);

        $decision_label = $decision === 'approved' ? 'approved' : 'rejected';
        $this->redirect_staff_candidate_rewards_action(
            $return_url,
            $candidate_id,
            $effective_year,
            sprintf('Appeal %s successfully.', $decision_label),
            'success'
        );
    }

