    public function handle_save_admin_recipient_email() {
        if (!$this->is_admin_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_save_admin_recipient_email_nonce']) || !wp_verify_nonce($_POST['cmn_save_admin_recipient_email_nonce'], 'cmn_save_admin_recipient_email')) {
            wp_die('Invalid request');
        }
        $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? $this->get_portal_base_url()));
        $email = sanitize_email((string) ($_POST['cmn_admin_recipient_email'] ?? ''));
        if ($email === '' || !is_email($email)) {
            wp_safe_redirect(add_query_arg([
                'view' => 'settings',
                'cmn_admin_recipient_status' => 'error',
                'cmn_admin_recipient_msg' => rawurlencode('Please enter a valid email address.'),
            ], $redirect));
            exit;
        }
        update_option('cmn_admin_recipient_email', $email, false);
        wp_safe_redirect(add_query_arg([
            'view' => 'settings',
            'cmn_admin_recipient_status' => 'success',
            'cmn_admin_recipient_msg' => rawurlencode('Admin recipient updated.'),
        ], $redirect));
        exit;
    }

    public function handle_save_staff_availability_settings() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized', 403);
        }
        if (
            !isset($_POST['cmn_save_staff_availability_settings_nonce']) ||
            !wp_verify_nonce((string) $_POST['cmn_save_staff_availability_settings_nonce'], 'cmn_save_staff_availability_settings')
        ) {
            wp_die('Invalid request', 403);
        }

        $user_id = (int) get_current_user_id();
        $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? ''));
        if ($redirect === '') {
            $redirect = add_query_arg(['view' => 'settings'], $this->get_portal_base_url());
        }

        $available_online = isset($_POST['cmn_available_online']) ? 1 : 0;
        $on_annual_leave = isset($_POST['cmn_on_annual_leave']) ? 1 : 0;
        $cover_user_id = (int) ($_POST['cmn_cover_user_id'] ?? 0);
        $allowed_cover_ids = array_map(function ($user) {
            return (int) ($user->ID ?? 0);
        }, $this->get_cover_delegate_users($user_id));
        if ($cover_user_id > 0 && !in_array($cover_user_id, $allowed_cover_ids, true)) {
            $cover_user_id = 0;
        }

        update_user_meta($user_id, 'cmn_available_online', $available_online ? '1' : '0');
        update_user_meta($user_id, 'cmn_on_annual_leave', $on_annual_leave ? '1' : '0');
        if ($cover_user_id > 0) {
            update_user_meta($user_id, 'cmn_cover_user_id', $cover_user_id);
        } else {
            delete_user_meta($user_id, 'cmn_cover_user_id');
        }
        $this->touch_staff_presence($user_id, true);

        $status = 'success';
        $message = 'Availability settings saved.';
        $is_unavailable = ($available_online !== 1 || $on_annual_leave === 1);
        if ($is_unavailable && $cover_user_id < 1) {
            $status = 'warning';
            $message = 'Saved. Select a cover delegate so school requests are covered while you are unavailable.';
        } elseif ($is_unavailable && $cover_user_id > 0) {
            $owner_user = get_user_by('id', $user_id);
            $cover_user = get_user_by('id', $cover_user_id);
            $owner_name = ($owner_user && !empty($owner_user->display_name)) ? (string) $owner_user->display_name : ('User #' . $user_id);
            $cover_name = ($cover_user && !empty($cover_user->display_name)) ? (string) $cover_user->display_name : ('User #' . $cover_user_id);
            $reason_parts = [];
            if ($on_annual_leave === 1) {
                $reason_parts[] = 'annual leave';
            }
            if ($available_online !== 1) {
                $reason_parts[] = 'offline';
            }
            $reason_label = $reason_parts ? implode(' + ', $reason_parts) : 'unavailable';
            $requests_url = add_query_arg(['view' => 'school-requests'], $this->get_portal_base_url());
            $cover_msg = $owner_name . ' marked themselves as ' . $reason_label . ' and assigned you as cover for school requests.';
            $this->add_notification($cover_user_id, 'school_request_cover_delegate', 'School request cover assigned', $cover_msg, $requests_url);
            foreach ($this->get_admin_users_for_support() as $admin_id) {
                $admin_id = (int) $admin_id;
                if ($admin_id < 1 || $admin_id === $cover_user_id || $admin_id === $user_id) {
                    continue;
                }
                $admin_msg = $owner_name . ' is ' . $reason_label . '. Cover delegate: ' . $cover_name . '.';
                $this->add_notification($admin_id, 'school_request_cover_delegate_admin', 'School request cover updated', $admin_msg, $requests_url);
            }
            $message = 'Saved and cover notifications sent.';
        }

        wp_safe_redirect(add_query_arg([
            'cmn_staff_presence_status' => $status,
            'cmn_staff_presence_msg' => rawurlencode($message),
        ], $redirect));
        exit;
    }

    public function handle_save_release_version() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized', 403);
        }
        if (
            !isset($_POST['cmn_save_release_version_nonce']) ||
            !wp_verify_nonce((string) $_POST['cmn_save_release_version_nonce'], 'cmn_save_release_version')
        ) {
            wp_die('Invalid request', 403);
        }
        $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? ''));
        if ($redirect === '') {
            $redirect = add_query_arg(['view' => 'settings'], $this->get_portal_base_url());
        }
        if (!$this->is_admin_user()) {
            wp_safe_redirect(add_query_arg([
                'cmn_release_version_status' => 'error',
                'cmn_release_version_msg' => rawurlencode('Only admins can change the release version.'),
            ], $redirect));
            exit;
        }
        $raw = trim((string) wp_unslash($_POST['cmn_release_version'] ?? ''));
        if (!preg_match('/^\d+\.\d+\.\d+$/', $raw)) {
            wp_safe_redirect(add_query_arg([
                'cmn_release_version_status' => 'error',
                'cmn_release_version_msg' => rawurlencode('Enter digits only (e.g. 0.0.3).'),
            ], $redirect));
            exit;
        }
        $this->set_release_version($raw);
        wp_safe_redirect(add_query_arg([
            'cmn_release_version_status' => 'success',
            'cmn_release_version_msg' => rawurlencode('Release version saved.'),
            'cmn_release_version_warn' => rawurlencode('Saved. Remember to create git tag: v' . $raw),
        ], $redirect));
        exit;
    }

    public function handle_save_converter_settings() {
        if (!is_user_logged_in() || !$this->is_admin_user()) {
            wp_die('Unauthorized', 403);
        }
        if (
            !isset($_POST['cmn_save_converter_settings_nonce']) ||
            !wp_verify_nonce((string) $_POST['cmn_save_converter_settings_nonce'], 'cmn_save_converter_settings')
        ) {
            wp_die('Invalid request', 403);
        }
        $raw = trim((string) wp_unslash($_POST['cmn_cv_converter_url'] ?? ''));
        $value = '';
        if ($raw !== '') {
            if (!preg_match('#^https?://#i', $raw)) {
                $raw = home_url('/' . ltrim($raw, '/'));
            }
            $value = esc_url_raw($raw);
        }
        if ($value !== '') {
            $normalized_value = strtolower($value);
            $is_portal_converter_app = strpos($normalized_value, 'view=cv_converter_app') !== false;
            $value_host = strtolower((string) wp_parse_url($value, PHP_URL_HOST));
            $home_host = strtolower((string) wp_parse_url(home_url('/'), PHP_URL_HOST));
            $value_path = strtolower((string) wp_parse_url($value, PHP_URL_PATH));
            $same_host = ($value_host === '' || $value_host === $home_host);
            $legacy_converter_path = $same_host && ($value_path === '/cv-converter' || strpos($value_path, '/cv-converter/') === 0);
            if (
                strpos($normalized_value, 'view=cv-converter') !== false
                || (strpos($normalized_value, 'view=cv_converter') !== false && !$is_portal_converter_app)
                || (strpos($normalized_value, '/portal') !== false && !$is_portal_converter_app)
                || strpos($normalized_value, 'covermenow-one') !== false
                || strpos($normalized_value, 'covermenowone-one') !== false
                || $legacy_converter_path
            ) {
                $value = '';
                $raw = '';
            }
        }
        if ($value === '') {
            delete_option('cmn_cv_converter_url');
            $msg = 'Converter URL reset to default (portal CV Converter app route).';
        } else {
            if (strpos($value, '?') === false) {
                $value = trailingslashit($value);
            }
            update_option('cmn_cv_converter_url', $value, false);
            $msg = 'Converter URL saved.';
        }
        $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? ''));
        if ($redirect === '') {
            $redirect = add_query_arg(['view' => 'settings'], $this->get_portal_base_url());
        }
        wp_safe_redirect(add_query_arg(['cmn_converter_msg' => rawurlencode($msg)], $redirect));
        exit;
    }

    public function handle_regenerate_marketing_runner_token() {
        if (!is_user_logged_in() || !$this->is_admin_user()) {
            wp_die('Unauthorized', 403);
        }
        if (
            !isset($_POST['cmn_regen_marketing_runner_nonce']) ||
            !wp_verify_nonce((string) $_POST['cmn_regen_marketing_runner_nonce'], 'cmn_regen_marketing_runner')
        ) {
            wp_die('Invalid request', 403);
        }
        $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? ''));
        if ($redirect === '') {
            $redirect = add_query_arg(['view' => 'settings'], $this->get_portal_base_url());
        }
        if (defined('CMN_MARKETING_RUNNER_TOKEN') && trim((string) CMN_MARKETING_RUNNER_TOKEN) !== '') {
            wp_safe_redirect(add_query_arg(['cmn_marketing_runner_msg' => rawurlencode('Runner token is managed by CMN_MARKETING_RUNNER_TOKEN constant.')], $redirect));
            exit;
        }
        $token = wp_generate_password(48, false, false);
        update_option('cmn_marketing_runner_token', $token, false);
        wp_safe_redirect(add_query_arg(['cmn_marketing_runner_msg' => rawurlencode('Marketing runner token regenerated.')], $redirect));
        exit;
    }

    public function handle_marketing_runner() {
        $provided = trim((string) ($_REQUEST['cmn_runner_token'] ?? ($_REQUEST['token'] ?? '')));
        $expected = $this->get_marketing_runner_token();
        $as_json = strtolower(trim((string) ($_REQUEST['format'] ?? 'json'))) === 'json';
        if ($provided === '' || !hash_equals($expected, $provided)) {
            status_header(403);
            if ($as_json) {
                wp_send_json_error(['message' => 'Invalid runner token.'], 403);
            }
            header('Content-Type: text/plain; charset=utf-8');
            echo 'Invalid runner token.';
            exit;
        }
        $queue_limit = max(1, min(300, (int) ($_REQUEST['queue_limit'] ?? 30)));
        $poll_limit = max(1, min(200, (int) ($_REQUEST['poll_limit'] ?? 40)));
        $campaign_id = max(0, (int) ($_REQUEST['campaign_id'] ?? 0));

        $queue_result = $this->process_marketing_queue_batch($campaign_id, $queue_limit);
        $poll_result = $this->poll_marketing_replies_imap($poll_limit);
        $now = time();
        update_option('cmn_marketing_queue_last_run_ts', $now, false);
        update_option('cmn_marketing_poll_last_run_ts', $now, false);

        $payload = [
            'ok' => true,
            'at' => gmdate('c'),
            'queue' => $queue_result,
            'replies' => $poll_result,
        ];
        if ($as_json) {
            wp_send_json_success($payload);
        }
        header('Content-Type: text/plain; charset=utf-8');
        echo "ok\n";
        echo 'at=' . $payload['at'] . "\n";
        echo 'queue_processed=' . (int) ($queue_result['processed'] ?? 0) . "\n";
        echo 'queue_sent=' . (int) ($queue_result['sent'] ?? 0) . "\n";
        echo 'queue_failed=' . (int) ($queue_result['failed'] ?? 0) . "\n";
        echo 'replies_processed=' . (int) ($poll_result['processed'] ?? 0) . "\n";
        echo 'replies_matched=' . (int) ($poll_result['matched'] ?? 0) . "\n";
        echo 'school_request_replies=' . (int) ($poll_result['school_request_replies'] ?? 0) . "\n";
        echo 'last_uid=' . (int) ($poll_result['last_uid'] ?? 0) . "\n";
        exit;
    }

    private function render_frontend_school_profile($school_id) {
        $school = get_post($school_id);
        error_log('[CMN_SCHOOL_VIEW] profile_start school_id=' . (int) $school_id);
        if (!$school || $school->post_type !== 'cmn_school') {
            error_log('[CMN_SCHOOL_VIEW] profile_no_school school_id=' . (int) $school_id);
            return '<div class="cmn-panel-card"><p>School not found.</p></div>';
        }
        error_log('[CMN_SCHOOL_VIEW] profile_school_resolved school_id=' . (int) $school_id);
        $t0 = microtime(true);
        $render_started_at = $t0;
        $requested_identifier = isset($_GET['school_id']) ? sanitize_text_field((string) $_GET['school_id']) : '';
        $resolved_cmn_school_id = (string) get_post_meta($school_id, 'cmn_school_id', true);
        try {
            error_log('[CMN_SCHOOL_VIEW] ' . wp_json_encode([
                'stage' => 'start',
                'requested_school_id' => $requested_identifier,
                'resolved_post_id' => (int) $school_id,
                'resolved_cmn_school_id' => $resolved_cmn_school_id,
                'elapsed_ms' => 0,
            ]));

            $meta = function ($key) use ($school_id) {
                return get_post_meta($school_id, $key, true);
            };
            $display = function ($value) {
                $value = trim((string) $value);
                return $value !== '' ? $value : '—';
            };
            $portal_page = cmn_get_page_by_title('Portal');
            $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
            $school_code = $meta('cmn_school_id');
            if ($school_code === '') {
                // Avoid writes during render; fall back to post ID.
                $school_code = (string) $school_id;
            }
            $redirect_url = add_query_arg(['view' => 'schools', 'school_id' => $school_code], $portal_url);
            $school_email = (string) $meta('cmn_email');
            $school_domain = $this->get_email_domain($school_email);
            if ($school_domain === '') {
                $school_domain = $meta('cmn_school_email_domain');
            }
            $missing_profile_fields = $this->get_school_profile_missing_fields($school_id);
            $school_postcode = trim((string) $meta('cmn_postcode'));
            $school_coords = $this->get_geo_coordinates_for_post($school_id);
            $status_raw = trim((string) $meta('cmn_status'));
            $status_display = $status_raw !== '' ? $status_raw : 'pending';

            error_log('[CMN_SCHOOL_VIEW] ' . wp_json_encode([
                'stage' => 'meta_loaded',
                'school_post_id' => (int) $school_id,
                'domain_present' => $school_domain !== '' ? 1 : 0,
                'postcode_present' => $school_postcode !== '' ? 1 : 0,
                'town_present' => trim((string) $meta('cmn_town')) !== '' ? 1 : 0,
                'coords_present' => $school_coords ? 1 : 0,
                'elapsed_ms' => (int) round((microtime(true) - $render_started_at) * 1000),
            ]));

            $this->log_school_debug('school_profile_render_start', [
                'school_post_id' => (int) $school_id,
                'school_id_meta' => (string) $meta('cmn_school_id'),
                'school_email' => $school_email,
                'school_domain' => (string) $school_domain,
                'missing_fields' => $missing_profile_fields,
            ]);
            $request_status = $this->get_school_access_request_status($school_id);
            $request_status_label = 'Not requested';
            $request_status_class = 'is-muted';
            if ($request_status === 'approved') {
                $request_status_label = 'Approved';
                $request_status_class = 'is-verified';
            } elseif ($request_status === 'rejected') {
                $request_status_label = 'Declined';
                $request_status_class = 'is-declined';
            } elseif ($request_status === 'more_info_needed') {
                $request_status_label = 'More Info Needed';
                $request_status_class = 'is-warning';
            } elseif ($request_status === 'pending') {
                $request_status_label = 'Pending';
                $request_status_class = 'is-pending';
            }
            $request_note = '';
            if ($request_status === 'rejected') {
                $request_note = (string) get_post_meta($school_id, 'cmn_access_request_reject_reason', true);
            } elseif ($request_status === 'more_info_needed') {
                $request_note = (string) get_post_meta($school_id, 'cmn_access_request_more_info_note', true);
            }
            $latest_school_reply = (string) get_post_meta($school_id, 'cmn_access_request_latest_school_reply', true);
            $latest_school_reply_at = (string) get_post_meta($school_id, 'cmn_access_request_latest_school_reply_at', true);
            $assigned_manager_id = (int) $meta('cmn_account_manager_user');
            if ($assigned_manager_id < 1) {
                $assigned_manager_id = (int) $meta('cmn_account_manager_user_id');
            }
            $assigned_manager_name = trim((string) $meta('cmn_account_manager'));
            if ($assigned_manager_name === '' && $assigned_manager_id > 0) {
                $assigned_manager_user = get_user_by('id', $assigned_manager_id);
                if ($assigned_manager_user && !empty($assigned_manager_user->display_name)) {
                    $assigned_manager_name = (string) $assigned_manager_user->display_name;
                }
            }
            $current_user_id = (int) get_current_user_id();
            $can_update_assignment = $this->is_admin_user($current_user_id);
            $account_managers = $can_update_assignment ? $this->get_account_manager_users() : [];
            $contacts = [];
            $open_tasks = [];
            $activities = [];
            $request_timeline = [];
            $domain_valid = ($school_domain !== '' && $this->is_school_registration_domain($school_domain));
            $critical_meta_missing = (!$domain_valid || ($school_postcode === '' && !$school_coords));
            if (!$critical_meta_missing) {
                try {
                    $contacts = $this->get_school_contacts_by_domain($school_domain);
                    $open_tasks = $this->get_school_tasks($school_domain, 5);
                    $activities = $this->get_school_activities($school_domain, 20);
                } catch (Throwable $e) {
                    $this->log_school_debug('school_profile_related_data_failed', [
                        'school_post_id' => (int) $school_id,
                        'school_domain' => (string) $school_domain,
                        'error' => $e->getMessage(),
                        'trace' => $e->getTraceAsString(),
                    ]);
                }
                try {
                    $request_timeline = $this->get_school_request_timeline($school_id, 30);
                } catch (Throwable $e) {
                    $this->log_school_debug('school_profile_timeline_failed', [
                        'school_post_id' => (int) $school_id,
                        'error' => $e->getMessage(),
                        'trace' => $e->getTraceAsString(),
                    ]);
                }
            }
            $feedback_summary = $this->get_feedback_summary_for_entity('school', (int) $school_id);
            $convert_msg = isset($_GET['cmn_convert_msg']) ? sanitize_text_field(wp_unslash($_GET['cmn_convert_msg'])) : '';
            $request_msg = isset($_GET['cmn_school_request_msg']) ? sanitize_text_field(wp_unslash($_GET['cmn_school_request_msg'])) : '';
            $allowed_profile_tabs = ['overview', 'contacts', 'activity', 'bookings', 'commercial', 'marketing', 'documents', 'settings'];
            $active_profile_tab = isset($_GET['cmn_school_tab']) ? sanitize_key((string) $_GET['cmn_school_tab']) : 'overview';
            if (!in_array($active_profile_tab, $allowed_profile_tabs, true)) {
                $active_profile_tab = 'overview';
            }
            $tab_base_query = array_filter([
                'view' => 'schools',
                'school_id' => $school_code ?: null,
                'pid' => $school_id,
                'cmn_status' => isset($_GET['cmn_status']) ? sanitize_key((string) $_GET['cmn_status']) : '',
                'cmn_bucket' => isset($_GET['cmn_bucket']) ? sanitize_key((string) $_GET['cmn_bucket']) : '',
                'cmn_stage' => isset($_GET['cmn_stage']) ? sanitize_key((string) $_GET['cmn_stage']) : '',
                'cmn_manager' => isset($_GET['cmn_manager']) ? (int) $_GET['cmn_manager'] : 0,
                'cmn_location' => isset($_GET['cmn_location']) ? sanitize_text_field((string) $_GET['cmn_location']) : '',
                'cmn_lead_group' => isset($_GET['cmn_lead_group']) ? $this->sanitize_lead_group_slug((string) $_GET['cmn_lead_group']) : '',
                'cmn_last_activity' => isset($_GET['cmn_last_activity']) ? sanitize_key((string) $_GET['cmn_last_activity']) : '',
                'q' => isset($_GET['q']) ? sanitize_text_field((string) $_GET['q']) : '',
            ]);
            $build_tab_url = function ($tab_key) use ($portal_url, $tab_base_query) {
                return add_query_arg(array_merge($tab_base_query, ['cmn_school_tab' => $tab_key]), $portal_url);
            };
            $profile_issues = [];
            if ($missing_profile_fields) {
                $profile_issues[] = 'Missing fields: ' . implode(', ', array_slice(array_values($missing_profile_fields), 0, 3)) . (count($missing_profile_fields) > 3 ? ' +' . (count($missing_profile_fields) - 3) . ' more' : '');
            }
            if ($school_postcode === '') {
                $profile_issues[] = 'Postcode missing';
            }
            if (!$school_coords) {
                $profile_issues[] = 'Location not verified';
            }
            if (!$domain_valid) {
                $profile_issues[] = 'School domain missing';
            }
            if ($critical_meta_missing && !$profile_issues) {
                $profile_issues[] = 'Profile data incomplete';
            }
            $booking_counts = $this->get_school_profile_booking_counts($school_id);
            $recent_bookings = $this->get_school_profile_recent_bookings($school_id, 8);
            $activity_quick_counts = [
                'open_tasks' => (int) count($open_tasks),
                'timeline' => (int) count($activities),
                'contacts' => (int) count($contacts),
            ];

            error_log('[CMN_SCHOOL_VIEW] ' . wp_json_encode([
                'stage' => 'panels_start',
                'school_post_id' => (int) $school_id,
                'critical_meta_missing' => $critical_meta_missing ? 1 : 0,
                'elapsed_ms' => (int) round((microtime(true) - $render_started_at) * 1000),
            ]));

            ob_start();
            $watchdog_limit = 1.5;
            $watchdog = function ($label) use ($t0, $school_id) {
                if ((microtime(true) - $t0) > 1.5) {
                    error_log('[CMN_SCHOOL_VIEW] watchdog_skip stage=' . $label . ' school_id=' . (int) $school_id);
                    echo '<div class="cmn-panel-card"><h3>Safe mode: heavy panels skipped</h3><p>This profile loaded in safe mode.</p></div>';
                    return true;
                }
                return false;
            };
        ?>
        <header class="cmn-school-header cmn-school-profile-header">
            <div class="cmn-school-profile-header-main">
                <h2><?php echo esc_html($school->post_title); ?></h2>
                <p>School profile</p>
            </div>
            <div class="cmn-school-profile-status">
                <span class="cmn-status-chip <?php echo esc_attr($request_status_class); ?>"><?php echo esc_html($request_status_label); ?></span>
                <span class="cmn-pill cmn-pill--status"><?php echo esc_html(ucfirst($status_display)); ?></span>
            </div>
        </header>
        <?php if ($watchdog('after_header')) { return ob_get_clean(); } ?>
        <nav class="cmn-school-profile-tabs" aria-label="School profile sections">
            <?php
            $profile_tabs = [
                'overview' => 'Overview',
                'contacts' => 'Contacts',
                'activity' => 'Activity',
                'bookings' => 'Bookings',
                'commercial' => 'Commercial',
                'marketing' => 'Marketing',
                'documents' => 'Documents',
                'settings' => 'Settings',
            ];
            foreach ($profile_tabs as $tab_key => $tab_label) :
                ?>
                <a class="cmn-school-profile-tab<?php echo $active_profile_tab === $tab_key ? ' is-active' : ''; ?>" href="<?php echo esc_url($build_tab_url($tab_key)); ?>">
                    <?php echo esc_html($tab_label); ?>
                </a>
            <?php endforeach; ?>
        </nav>
        <?php if ($profile_issues) : ?>
            <section class="cmn-panel-card cmn-school-profile-issues-strip">
                <div class="cmn-school-profile-issues-strip-head">
                    <strong>Needs attention</strong>
                    <a class="cmn-ghost cmn-btn-mini" href="#cmn-school-details">Fix profile</a>
                </div>
                <div class="cmn-school-profile-issues-strip-list">
                    <?php foreach ($profile_issues as $issue_text) : ?>
                        <span class="cmn-pill cmn-pill--pending"><?php echo esc_html($issue_text); ?></span>
                    <?php endforeach; ?>
                </div>
            </section>
        <?php endif; ?>
        <?php if ($convert_msg) : ?>
            <div class="cmn-panel-card"><strong><?php echo esc_html($convert_msg); ?></strong></div>
        <?php endif; ?>
        <?php if ($request_msg) : ?>
            <div class="cmn-panel-card"><strong><?php echo esc_html($request_msg); ?></strong></div>
        <?php endif; ?>
        <section class="cmn-panel-card cmn-panel-card-wide cmn-school-tab-panel cmn-school-tab-panel--overview<?php echo $active_profile_tab === 'overview' ? '' : ' cmn-school-tab-panel-hidden'; ?>">
            <?php if ($watchdog('panel_timeline')) { return ob_get_clean(); } ?>
            <?php error_log('[CMN_SCHOOL_VIEW] panel_start timeline school_id=' . (int) $school_id); ?>
            <h3>Application Timeline</h3>
            <?php if ($critical_meta_missing) : ?>
                <p class="cmn-muted">Timeline hidden until domain + postcode are saved.</p>
            <?php elseif ($request_timeline) : ?>
                <ul class="cmn-activity-list">
                    <?php foreach ($request_timeline as $timeline_item) : ?>
                        <?php
                        $timeline_time = (string) ($timeline_item['created_at'] ?? '');
                        $timeline_actor = (string) ($timeline_item['actor_name'] ?? 'System');
                        ?>
                        <li>
                            <div>
                                <strong><?php echo esc_html((string) ($timeline_item['title'] ?? 'Application updated')); ?></strong>
                                <?php if (!empty($timeline_item['note'])) : ?>
                                    <div class="cmn-muted"><?php echo esc_html((string) $timeline_item['note']); ?></div>
                                <?php endif; ?>
                            </div>
                            <div class="cmn-muted">
                                <span class="cmn-status-chip <?php echo esc_attr((string) ($timeline_item['status_class'] ?? 'is-muted')); ?>"><?php echo esc_html($timeline_actor); ?></span>
                                <?php if ($timeline_time !== '') : ?>
                                    <span><?php echo esc_html(date_i18n('M j, Y g:ia', strtotime($timeline_time))); ?></span>
                                <?php endif; ?>
                            </div>
                        </li>
                    <?php endforeach; ?>
                </ul>
            <?php else : ?>
                <p class="cmn-muted">No application timeline entries yet.</p>
            <?php endif; ?>
            <?php error_log('[CMN_SCHOOL_VIEW] panel_end timeline school_id=' . (int) $school_id); ?>
        </section>
        <?php if ($watchdog('before_profile_grid')) { return ob_get_clean(); } ?>
