    private function get_school_profile_recent_bookings($school_id, $limit = 8) {
        $school_id = (int) $school_id;
        $limit = max(1, min(20, (int) $limit));
        if ($school_id < 1) {
            return [];
        }
        $query = new WP_Query([
            'post_type' => 'cmn_booking',
            'post_status' => ['publish', 'private', 'pending', 'draft', 'future'],
            'posts_per_page' => $limit,
            'orderby' => 'date',
            'order' => 'DESC',
            'meta_query' => [
                [
                    'key' => 'cmn_school_id',
                    'value' => (string) $school_id,
                ],
            ],
            'no_found_rows' => true,
        ]);
        $rows = [];
        while ($query->have_posts()) {
            $query->the_post();
            $booking_id = (int) get_the_ID();
            $status_key = sanitize_key((string) get_post_meta($booking_id, 'cmn_status', true));
            $status_label = $status_key !== '' ? ucwords(str_replace('_', ' ', $status_key)) : 'Unknown';
            $candidate_name = '';
            $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
            if ($candidate_id > 0) {
                $candidate_name = get_the_title($candidate_id);
            }
            $date_raw = trim((string) get_post_meta($booking_id, 'cmn_date', true));
            $date_label = $date_raw !== '' && strtotime($date_raw) ? date_i18n('M j, Y', strtotime($date_raw)) : '';
            $rows[] = [
                'id' => $booking_id,
                'title' => get_the_title(),
                'status_key' => $status_key,
                'status_label' => $status_label,
                'candidate' => $candidate_name,
                'date_label' => $date_label,
            ];
        }
        wp_reset_postdata();
        return $rows;
    }

    private function get_school_profile_booking_counts($school_id) {
        $school_id = (int) $school_id;
        $counts = [
            'total' => 0,
            'requested' => 0,
            'accepted' => 0,
            'completed' => 0,
        ];
        if ($school_id < 1) {
            return $counts;
        }
        global $wpdb;
        $posts_table = $wpdb->posts;
        $meta_table = $wpdb->postmeta;
        $rows = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT LOWER(TRIM(COALESCE(status_meta.meta_value, ''))) AS booking_status, COUNT(DISTINCT p.ID) AS total
                 FROM {$posts_table} p
                 INNER JOIN {$meta_table} school_meta
                         ON school_meta.post_id = p.ID
                        AND school_meta.meta_key = 'cmn_school_id'
                        AND school_meta.meta_value = %s
                 LEFT JOIN {$meta_table} status_meta
                        ON status_meta.post_id = p.ID
                       AND status_meta.meta_key = 'cmn_status'
                 WHERE p.post_type = 'cmn_booking'
                   AND p.post_status IN ('publish', 'private', 'pending', 'draft', 'future')
                 GROUP BY booking_status",
                (string) $school_id
            ),
            ARRAY_A
        );
        foreach ((array) $rows as $row) {
            $status_key = sanitize_key((string) ($row['booking_status'] ?? ''));
            $total = max(0, (int) ($row['total'] ?? 0));
            $counts['total'] += $total;
            if (in_array($status_key, ['requested', 'candidate_invited', 'pending'], true)) {
                $counts['requested'] += $total;
            } elseif (in_array($status_key, ['accepted', 'candidate_accepted'], true)) {
                $counts['accepted'] += $total;
            } elseif (in_array($status_key, ['completed', 'complete', 'finished'], true)) {
                $counts['completed'] += $total;
            }
        }
        return $counts;
    }

    private function render_frontend_candidate_profile($candidate_id) {
        $candidate = get_post($candidate_id);
        if (!$candidate || $candidate->post_type !== 'cmn_candidate') {
            return '<div class="cmn-panel-card"><p>Candidate not found.</p></div>';
        }
        $meta = function ($key) use ($candidate_id) {
            return get_post_meta($candidate_id, $key, true);
        };
        $feedback_summary = $this->get_feedback_summary_for_entity('candidate', (int) $candidate_id);
        ob_start();
        ?>
        <header class="cmn-school-header">
            <h2><?php echo esc_html($candidate->post_title); ?></h2>
            <p>Candidate profile</p>
        </header>
            <div class="cmn-profile-grid">
                <div class="cmn-panel-card">
                    <h3>Details</h3>
                    <div class="cmn-meta-grid">
                        <?php if ((string) get_post_meta($candidate_id, 'cmn_feedback_risk', true) === 'urgent') : ?>
                            <div><strong>Tag:</strong> Feedback Risk</div>
                        <?php endif; ?>
                        <div><strong>Status:</strong> <?php echo esc_html($meta('cmn_status')); ?></div>
                        <div><strong>Location:</strong> <?php echo esc_html($meta('cmn_location')); ?></div>
                        <div><strong>Phone:</strong> <?php echo esc_html($meta('cmn_phone')); ?></div>
                        <div><strong>Email:</strong> <?php echo esc_html($meta('cmn_email')); ?></div>
                    </div>
                </div>
                <div class="cmn-panel-card">
                    <h3>Documents</h3>
                    <div class="cmn-meta-grid">
                        <div><strong>CV:</strong> <?php echo $meta('cmn_cv_file') ? 'Uploaded' : 'Not uploaded'; ?></div>
                        <div><strong>DBS:</strong> <?php echo $meta('cmn_dbs_file') ? 'Uploaded' : 'Not uploaded'; ?></div>
                    </div>
                </div>
                <div class="cmn-panel-card">
                    <h3>Feedback Summary</h3>
                    <div class="cmn-meta-grid">
                        <div><strong>Average Rating:</strong> <?php echo esc_html(number_format((float) ($feedback_summary['avg_overall'] ?? 0), 2)); ?>/5</div>
                        <div><strong>Reliability Rating:</strong> <?php echo esc_html(number_format((float) ($feedback_summary['avg_reliability'] ?? 0), 2)); ?>/5</div>
                        <div><strong>Total Feedback Count:</strong> <?php echo esc_html((string) ((int) ($feedback_summary['feedback_count'] ?? 0))); ?></div>
                        <div><strong>Trend:</strong> <?php echo esc_html((string) ($feedback_summary['trend_label'] ?? '->')); ?></div>
                    </div>
                </div>
            </div>
            <a class="cmn-ghost" href="<?php echo esc_url(add_query_arg(['view' => 'candidates'], home_url('/portal'))); ?>">Back to Candidates</a>
        <?php
        return ob_get_clean();
    }

