    public function migrate_bank_details_plain_to_encrypted() {
        global $wpdb;
        $table = $this->get_candidate_bank_details_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return true;
        }

        self::migrate_schema_v54_candidate_bank_details_encryption();

        $legacy_sort_exists = self::table_has_column($table, 'sort_code');
        $legacy_account_exists = self::table_has_column($table, 'account_number');
        if (!$legacy_sort_exists && !$legacy_account_exists) {
            update_option('cmn_bank_details_plain_migration_complete_v1', '1', false);
            return true;
        }

        $legacy_fields = ['id'];
        $legacy_where = [];
        if ($legacy_sort_exists) {
            $legacy_fields[] = 'sort_code';
            $legacy_where[] = "COALESCE(sort_code, '') <> ''";
        }
        if ($legacy_account_exists) {
            $legacy_fields[] = 'account_number';
            $legacy_where[] = "COALESCE(account_number, '') <> ''";
        }
        if (!$legacy_where) {
            update_option('cmn_bank_details_plain_migration_complete_v1', '1', false);
            return true;
        }

        $rows_with_plain = (array) $wpdb->get_results(
            "SELECT " . implode(', ', $legacy_fields) . "
             FROM {$table}
             WHERE " . implode(' OR ', $legacy_where),
            ARRAY_A
        );
        if (!$rows_with_plain) {
            self::maybe_drop_column($table, 'sort_code');
            self::maybe_drop_column($table, 'account_number');
            update_option('cmn_bank_details_plain_migration_complete_v1', '1', false);
            return true;
        }

        $encryption_key = function_exists('cmn_get_bank_encryption_key')
            ? cmn_get_bank_encryption_key()
            : new WP_Error('cmn_bank_key_missing', 'Encryption key is missing.');
        if (is_wp_error($encryption_key)) {
            return $encryption_key;
        }

        $pending_count = 0;
        foreach ($rows_with_plain as $row) {
            $row_id = (int) ($row['id'] ?? 0);
            if ($row_id < 1) {
                continue;
            }

            $sort_digits = preg_replace('/\D+/', '', (string) ($row['sort_code'] ?? ''));
            $account_digits = preg_replace('/\D+/', '', (string) ($row['account_number'] ?? ''));
            if (!is_string($sort_digits) || !is_string($account_digits) || strlen($sort_digits) !== 6 || strlen($account_digits) !== 8) {
                $pending_count++;
                continue;
            }

            $sort_code_enc = function_exists('cmn_encrypt_secret') ? cmn_encrypt_secret($sort_digits) : new WP_Error('cmn_bank_encrypt_missing', 'Encryption helper missing.');
            if (is_wp_error($sort_code_enc)) {
                return $sort_code_enc;
            }
            $account_number_enc = function_exists('cmn_encrypt_secret') ? cmn_encrypt_secret($account_digits) : new WP_Error('cmn_bank_encrypt_missing', 'Encryption helper missing.');
            if (is_wp_error($account_number_enc)) {
                return $account_number_enc;
            }

            $masked_sort_code = $this->format_candidate_sort_code($sort_digits);
            $sort_last2 = substr($sort_digits, -2);
            $account_last4 = substr($account_digits, -4);
            if ($masked_sort_code === '' || $sort_last2 === '' || $account_last4 === '') {
                $pending_count++;
                continue;
            }

            $now = current_time('mysql');
            $update_data = [
                'sort_code_enc' => $sort_code_enc,
                'account_number_enc' => $account_number_enc,
                'sort_code_last2' => $sort_last2,
                'sort_code_masked' => $masked_sort_code,
                'account_number_last4' => $account_last4,
                'enc_version' => 1,
                'updated_at' => $now,
            ];
            $update_format = ['%s', '%s', '%s', '%s', '%s', '%d', '%s'];
            if ($legacy_sort_exists) {
                $update_data['sort_code'] = '';
                $update_format[] = '%s';
            }
            if ($legacy_account_exists) {
                $update_data['account_number'] = '';
                $update_format[] = '%s';
            }

            $updated = $wpdb->update($table, $update_data, ['id' => $row_id], $update_format, ['%d']);
            if ($updated === false) {
                return new WP_Error('cmn_bank_plain_migration_failed', 'Unable to migrate bank details to encrypted storage.');
            }
        }

        $remaining_plain = (int) $wpdb->get_var(
            "SELECT COUNT(*)
             FROM {$table}
             WHERE " . implode(' OR ', $legacy_where)
        );
        if ($remaining_plain <= 0 && $pending_count <= 0) {
            self::maybe_drop_column($table, 'sort_code');
            self::maybe_drop_column($table, 'account_number');
            update_option('cmn_bank_details_plain_migration_complete_v1', '1', false);
        } else {
            delete_option('cmn_bank_details_plain_migration_complete_v1');
        }

        return true;
    }

