    /*
     * Prompt 13 acceptance checks:
     * 1) School at 19 confirmed days stays standard.
     * 2) School at 20 confirmed days upgrades to bronze with 2.00 discount.
     * 3) Re-running apply_tier_if_needed is idempotent and logs on tier change only.
     * 4) Lifetime state never resets annually (state row keyed only by school_user_id).
     */
    public function ensure_school_partner_state_for_user($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }

        $user = get_user_by('id', $school_user_id);
        if (!$user instanceof WP_User) {
            return new WP_Error('cmn_school_partner_user_not_found', 'School user does not exist.');
        }
        if (!$this->is_school_user($school_user_id)) {
            return new WP_Error('cmn_school_partner_not_school_role', 'User is not a school account.');
        }

        global $wpdb;
        $table = $this->get_school_partner_state_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return new WP_Error('cmn_school_partner_state_table_missing', 'School partner state table does not exist.');
        }

        $existing = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE school_user_id = %d
             LIMIT 1",
            $school_user_id
        ), ARRAY_A);
        if (is_array($existing) && !empty($existing)) {
            return $existing;
        }

        $now = current_time('mysql');
        $inserted = $wpdb->insert($table, [
            'school_user_id' => $school_user_id,
            'current_tier' => 'standard',
            'confirmed_completed_days' => 0,
            'manual_days_adjustment' => 0,
            'manual_days_adjustment_reason' => null,
            'manual_days_adjustment_updated_at' => null,
            'discount_pct' => 0.00,
            'estimated_savings_total' => 0.00,
            'estimated_savings_updated_at' => null,
            'joined_at' => $now,
            'last_tier_change_at' => null,
            'updated_at' => $now,
        ], ['%d', '%s', '%d', '%d', '%s', '%s', '%f', '%f', '%s', '%s', '%s', '%s']);

        if ($inserted === false) {
            $existing_after_insert = $wpdb->get_row($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE school_user_id = %d
                 LIMIT 1",
                $school_user_id
            ), ARRAY_A);
            if (is_array($existing_after_insert) && !empty($existing_after_insert)) {
                return $existing_after_insert;
            }
            return new WP_Error('cmn_school_partner_state_insert_failed', 'Unable to initialise school partner state.');
        }

        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE school_user_id = %d
             LIMIT 1",
            $school_user_id
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function normalize_school_partner_lifetime_tier($tier) {
        $tier = sanitize_key((string) $tier);
        if (!in_array($tier, ['standard', 'bronze', 'silver', 'gold', 'elite'], true)) {
            return 'standard';
        }
        return $tier;
    }

    private function get_school_partner_lifetime_tier_rank($tier) {
        $tier = $this->normalize_school_partner_lifetime_tier($tier);
        $map = [
            'standard' => 0,
            'bronze' => 1,
            'silver' => 2,
            'gold' => 3,
            'elite' => 4,
        ];
        return (int) ($map[$tier] ?? 0);
    }

    private function get_school_partner_discount_pct_for_tier($tier, $config_row) {
        $tier = $this->normalize_school_partner_lifetime_tier($tier);
        $config_row = is_array($config_row) ? $config_row : [];
        $discount_map = [
            'standard' => 0.00,
            'bronze' => round((float) ($config_row['bronze_discount_pct'] ?? 2.00), 2),
            'silver' => round((float) ($config_row['silver_discount_pct'] ?? 4.00), 2),
            'gold' => round((float) ($config_row['gold_discount_pct'] ?? 6.00), 2),
            'elite' => round((float) ($config_row['elite_discount_pct'] ?? 8.00), 2),
        ];
        return round(max(0, (float) ($discount_map[$tier] ?? 0.00)), 2);
    }

    public function school_partner_compute_tier($confirmed_days, $config_row) {
        $confirmed_days = max(0, (int) $confirmed_days);
        $config_row = is_array($config_row) ? $config_row : [];

        $thresholds = [
            'bronze' => max(0, (int) ($config_row['bronze_threshold'] ?? 20)),
            'silver' => max(0, (int) ($config_row['silver_threshold'] ?? 50)),
            'gold' => max(0, (int) ($config_row['gold_threshold'] ?? 100)),
            'elite' => max(0, (int) ($config_row['elite_threshold'] ?? 200)),
        ];
        $thresholds['silver'] = max($thresholds['bronze'], $thresholds['silver']);
        $thresholds['gold'] = max($thresholds['silver'], $thresholds['gold']);
        $thresholds['elite'] = max($thresholds['gold'], $thresholds['elite']);

        if ($confirmed_days >= $thresholds['elite']) {
            return 'elite';
        }
        if ($confirmed_days >= $thresholds['gold']) {
            return 'gold';
        }
        if ($confirmed_days >= $thresholds['silver']) {
            return 'silver';
        }
        if ($confirmed_days >= $thresholds['bronze']) {
            return 'bronze';
        }
        return 'standard';
    }

    private function get_school_partner_config_row() {
        global $wpdb;
        $table = $this->get_school_partner_config_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists === $table) {
            $row = $wpdb->get_row("SELECT * FROM {$table} ORDER BY id ASC LIMIT 1", ARRAY_A);
            if (is_array($row) && !empty($row)) {
                return $row;
            }
        }
        return (array) $this->school_partner_get_config();
    }

    private function get_school_partner_average_daily_saving_estimate($config_row = []) {
        $config_row = is_array($config_row) ? $config_row : [];
        $average = (float) ($config_row['average_daily_saving_estimate'] ?? 25.00);
        if (!is_finite($average)) {
            $average = 25.00;
        }
        return round(max(0, $average), 2);
    }

    /*
     * Prompt 17 acceptance checks:
     * 1) confirmed_completed_days is refreshed from confirmation rows with status confirmed/auto_confirmed only.
     * 2) Refresh writes confirmed_days_recalculated audit event when count changes.
     * 3) estimated_savings_total is recomputed and estimated_savings_updated audit event is written on change.
     * 4) Re-running refresh with no data change is idempotent (no duplicate state mutations).
     */
    public function school_partner_refresh_confirmed_days($school_user_id, $actor_user_id = null) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }

        $actor_user_id = $actor_user_id === null ? (int) get_current_user_id() : (int) $actor_user_id;
        $state = $this->ensure_school_partner_state_for_user($school_user_id);
        if (is_wp_error($state)) {
            return $state;
        }

        $confirmed_days = max(0, (int) $this->school_partner_get_confirmed_completed_days($school_user_id));
        $previous_days = max(0, (int) ($state['confirmed_completed_days'] ?? 0));
        $config_row = (array) $this->get_school_partner_config_row();
        $average_daily_saving = $this->get_school_partner_average_daily_saving_estimate($config_row);
        $estimated_savings_total = round($confirmed_days * $average_daily_saving, 2);
        $previous_savings_total = round((float) ($state['estimated_savings_total'] ?? 0.00), 2);

        $updates = [];
        $formats = [];
        $confirmed_days_changed = ($confirmed_days !== $previous_days);
        $savings_changed = (abs($estimated_savings_total - $previous_savings_total) >= 0.0001);
        $now = current_time('mysql');

        if ($confirmed_days_changed) {
            $updates['confirmed_completed_days'] = $confirmed_days;
            $formats[] = '%d';
        }
        if ($savings_changed) {
            $updates['estimated_savings_total'] = $estimated_savings_total;
            $formats[] = '%f';
            $updates['estimated_savings_updated_at'] = $now;
            $formats[] = '%s';
        }

        if (!empty($updates)) {
            $updates['updated_at'] = $now;
            $formats[] = '%s';
            global $wpdb;
            $table = $this->get_school_partner_state_table();
            $updated = $wpdb->update(
                $table,
                $updates,
                ['school_user_id' => $school_user_id],
                $formats,
                ['%d']
            );
            if ($updated === false) {
                return new WP_Error('cmn_school_partner_refresh_failed', 'Unable to refresh confirmed day totals.');
            }
        }

        if ($confirmed_days_changed && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'school',
                'entity_id' => $school_user_id,
                'event_type' => 'confirmed_days_recalculated',
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'old' => $previous_days,
                    'new' => $confirmed_days,
                    'counted_statuses' => ['confirmed', 'auto_confirmed'],
                ],
            ]);
        }

        if ($savings_changed && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'school',
                'entity_id' => $school_user_id,
                'event_type' => 'estimated_savings_updated',
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'old' => $previous_savings_total,
                    'new' => $estimated_savings_total,
                    'confirmed_days' => $confirmed_days,
                    'average_daily_saving_estimate' => $average_daily_saving,
                ],
            ]);
        }

        global $wpdb;
        $table = $this->get_school_partner_state_table();
        $updated_state = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE school_user_id = %d
             LIMIT 1",
            $school_user_id
        ), ARRAY_A);
        return is_array($updated_state) ? $updated_state : (is_array($state) ? $state : []);
    }

    public function school_partner_apply_tier_if_needed($school_user_id, $actor_user_id = null) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }

        $actor_user_id = $actor_user_id === null ? (int) get_current_user_id() : (int) $actor_user_id;
        $state = $this->school_partner_refresh_confirmed_days($school_user_id, $actor_user_id);
        if (is_wp_error($state)) {
            return $state;
        }

        $config_row = (array) $this->get_school_partner_config_row();
        $confirmed_days = max(0, (int) ($state['confirmed_completed_days'] ?? 0));
        $current_tier = $this->normalize_school_partner_lifetime_tier((string) ($state['current_tier'] ?? 'standard'));
        $target_tier = $this->school_partner_compute_tier($confirmed_days, $config_row);
        $target_tier = $this->normalize_school_partner_lifetime_tier($target_tier);

        $current_rank = $this->get_school_partner_lifetime_tier_rank($current_tier);
        $target_rank = $this->get_school_partner_lifetime_tier_rank($target_tier);
        $effective_tier = $target_rank > $current_rank ? $target_tier : $current_tier;
        $new_discount = $this->get_school_partner_discount_pct_for_tier($effective_tier, $config_row);
        $previous_discount = round((float) ($state['discount_pct'] ?? 0.00), 2);
        $now = current_time('mysql');

        global $wpdb;
        $table = $this->get_school_partner_state_table();
        $updates = [];
        $formats = [];
        $tier_changed = false;

        if ($effective_tier !== $current_tier) {
            $tier_changed = true;
            $updates['current_tier'] = $effective_tier;
            $formats[] = '%s';
            $updates['last_tier_change_at'] = $now;
            $formats[] = '%s';
        }
        if (abs($previous_discount - $new_discount) >= 0.0001) {
            $updates['discount_pct'] = $new_discount;
            $formats[] = '%f';
        }
        if (!empty($updates)) {
            $updates['updated_at'] = $now;
            $formats[] = '%s';
            $updated_rows = $wpdb->update(
                $table,
                $updates,
                ['school_user_id' => $school_user_id],
                $formats,
                ['%d']
            );
            if ($updated_rows === false) {
                return new WP_Error('cmn_school_partner_state_update_failed', 'Unable to update school partner state.');
            }
        }

        $updated_state = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE school_user_id = %d
             LIMIT 1",
            $school_user_id
        ), ARRAY_A);
        $state = is_array($updated_state) ? $updated_state : (is_array($state) ? $state : []);

        if ($tier_changed && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'school',
                'entity_id' => $school_user_id,
                'event_type' => 'tier_change',
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'from' => $current_tier,
                    'to' => $effective_tier,
                    'confirmed_days' => $confirmed_days,
                    'discount_pct' => $new_discount,
                ],
            ]);
        }

        return $state;
    }

    private function get_school_partner_dashboard_tier_label($tier) {
        $tier = $this->normalize_school_partner_lifetime_tier($tier);
        $labels = [
            'standard' => 'Standard',
            'bronze' => 'Bronze',
            'silver' => 'Silver',
            'gold' => 'Gold',
            'elite' => 'Elite+',
        ];
        return (string) ($labels[$tier] ?? $labels['standard']);
    }

    private function get_school_partner_dashboard_thresholds($config_row) {
        $config_row = is_array($config_row) ? $config_row : [];
        $bronze = max(0, (int) ($config_row['bronze_threshold'] ?? 20));
        $silver = max($bronze, (int) ($config_row['silver_threshold'] ?? 50));
        $gold = max($silver, (int) ($config_row['gold_threshold'] ?? 100));
        $elite = max($gold, (int) ($config_row['elite_threshold'] ?? 200));
        return [
            'bronze' => $bronze,
            'silver' => $silver,
            'gold' => $gold,
            'elite' => $elite,
        ];
    }

    /*
     * Prompt 18 acceptance checks:
     * 1) Correct tier and progress values are returned from cmn_school_partner_state-derived fields.
     * 2) Elite+ returns no next threshold.
     * 3) Overdue confirmation notice flag is true when pending overdue rows exist.
     * 4) Function returns stable, presentation-safe fields (no raw table output).
     */
    public function get_school_partner_dashboard_data($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }
        if (!$this->is_school_user($school_user_id)) {
            return new WP_Error('cmn_school_partner_not_school_role', 'Not authorised', ['status' => 403]);
        }

        $actor_user_id = (int) get_current_user_id();
        $state = $this->school_partner_refresh_confirmed_days($school_user_id, $actor_user_id > 0 ? $actor_user_id : null);
        if (is_wp_error($state)) {
            return $state;
        }

        $config_row = (array) $this->school_partner_get_config();
        $thresholds = $this->get_school_partner_dashboard_thresholds($config_row);
        $tier_key = $this->normalize_school_partner_lifetime_tier((string) ($state['current_tier'] ?? 'standard'));
        $confirmed_days = max(0, (int) ($state['confirmed_completed_days'] ?? 0));
        $discount_percent = round(max(0, (float) ($state['discount_pct'] ?? $this->get_school_partner_discount_pct_for_tier($tier_key, $config_row))), 2);
        $estimated_savings_total = round(max(0, (float) ($state['estimated_savings_total'] ?? 0)), 2);
        $estimated_savings_updated_at = (string) ($state['estimated_savings_updated_at'] ?? '');

        $next_tier_map = [
            'standard' => 'bronze',
            'bronze' => 'silver',
            'silver' => 'gold',
            'gold' => 'elite',
            'elite' => '',
        ];
        $next_tier_key = (string) ($next_tier_map[$tier_key] ?? '');
        $next_threshold = $next_tier_key !== '' ? (int) ($thresholds[$next_tier_key] ?? 0) : null;

        $current_floor = 0;
        if ($tier_key === 'bronze') {
            $current_floor = $thresholds['bronze'];
        } elseif ($tier_key === 'silver') {
            $current_floor = $thresholds['silver'];
        } elseif ($tier_key === 'gold') {
            $current_floor = $thresholds['gold'];
        } elseif ($tier_key === 'elite') {
            $current_floor = $thresholds['elite'];
        }

        $progress_percent = 100.0;
        if (is_int($next_threshold) && $next_threshold > $current_floor) {
            $progress_percent = (($confirmed_days - $current_floor) / max(1, $next_threshold - $current_floor)) * 100;
        }
        $progress_percent = round(max(0.0, min(100.0, (float) $progress_percent)), 2);

        $has_overdue_confirmations = false;
        global $wpdb;
        $confirmations_table = $this->get_booking_completion_confirmations_table();
        $confirmations_table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $confirmations_table));
        if ($confirmations_table_exists === $confirmations_table) {
            $overdue_count = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*)
                 FROM {$confirmations_table}
                 WHERE school_user_id = %d
                   AND status = %s
                   AND overdue_flag = 1",
                $school_user_id,
                'pending'
            ));
            $has_overdue_confirmations = $overdue_count > 0;
        }

        return [
            'current_tier' => $this->get_school_partner_dashboard_tier_label($tier_key),
            'current_tier_key' => $tier_key,
            'discount_percent' => $discount_percent,
            'confirmed_completed_days' => $confirmed_days,
            'next_threshold' => $next_threshold,
            'next_tier_label' => $next_tier_key !== '' ? $this->get_school_partner_dashboard_tier_label($next_tier_key) : '',
            'progress_percent' => $progress_percent,
            'estimated_savings_total' => $estimated_savings_total,
            'estimated_savings_updated_at' => $estimated_savings_updated_at,
            'has_overdue_confirmations' => $has_overdue_confirmations,
            'tier_breakdown' => [
                [
                    'tier_key' => 'bronze',
                    'tier_label' => 'Bronze',
                    'required_confirmed_days' => $thresholds['bronze'],
                    'discount_percent' => round(max(0, (float) ($config_row['bronze_discount_pct'] ?? 2.00)), 2),
                ],
                [
                    'tier_key' => 'silver',
                    'tier_label' => 'Silver',
                    'required_confirmed_days' => $thresholds['silver'],
                    'discount_percent' => round(max(0, (float) ($config_row['silver_discount_pct'] ?? 4.00)), 2),
                ],
                [
                    'tier_key' => 'gold',
                    'tier_label' => 'Gold',
                    'required_confirmed_days' => $thresholds['gold'],
                    'discount_percent' => round(max(0, (float) ($config_row['gold_discount_pct'] ?? 6.00)), 2),
                ],
                [
                    'tier_key' => 'elite',
                    'tier_label' => 'Elite+',
                    'required_confirmed_days' => $thresholds['elite'],
                    'discount_percent' => round(max(0, (float) ($config_row['elite_discount_pct'] ?? 8.00)), 2),
                ],
            ],
        ];
    }

    private function get_school_partner_credit_allowed_types() {
        return ['tier_discount', 'manual_adjustment'];
    }

    private function normalize_school_partner_credit_type($credit_type) {
        $credit_type = sanitize_key((string) $credit_type);
        if (!in_array($credit_type, $this->get_school_partner_credit_allowed_types(), true)) {
            return '';
        }
        return $credit_type;
    }

    private function get_school_partner_credit_allowed_statuses() {
        return ['pending', 'applied', 'voided'];
    }

    private function normalize_school_partner_credit_status($credit_status) {
        $credit_status = sanitize_key((string) $credit_status);
        if (!in_array($credit_status, $this->get_school_partner_credit_allowed_statuses(), true)) {
            return '';
        }
        return $credit_status;
    }

    private function get_school_partner_credit_school_charge_rate($booking_id, $booking_day_date = '') {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return 0.0;
        }

        $booking_day_date = $this->normalize_invoice_date((string) $booking_day_date);
        if ($booking_day_date !== '') {
            $shift_dates = $this->get_rewards_booking_shift_dates($booking_id);
            if (!empty($shift_dates) && !in_array($booking_day_date, $shift_dates, true)) {
                return 0.0;
            }
        }

        // Source of truth: cmn_booking_rates (per-booking persisted school_charge_rate).
        $rate_row = $this->get_booking_rate_row($booking_id);
        $school_charge_rate = round(max(0, (float) ($rate_row['school_charge_rate'] ?? 0)), 2);
        if ($school_charge_rate > 0) {
            return $school_charge_rate;
        }

        // Backward-compatible fallback to booking post meta when rates row is missing.
        $meta_rate = round(max(0, (float) get_post_meta($booking_id, 'cmn_school_charge_rate', true)), 2);
        return $meta_rate > 0 ? $meta_rate : 0.0;
    }

    /*
     * Prompt 19 acceptance checks:
     * 1) Calculation uses cmn_school_partner_state discount_pct.
     * 2) Calculation uses persisted booking school charge rate source.
     * 3) Returns structured credit_amount/discount_percent/school_charge_rate payload.
     */
    public function calculate_partner_credit_for_booking_day($school_user_id, $booking_id, $booking_day_date) {
        $school_user_id = (int) $school_user_id;
        $booking_id = (int) $booking_id;
        $booking_day_date = $this->normalize_invoice_date((string) $booking_day_date);
        if ($school_user_id < 1 || $booking_id < 1 || $booking_day_date === '') {
            return new WP_Error('cmn_partner_credit_invalid_input', 'School user, booking, and booking day are required.');
        }
        if (get_post_type($booking_id) !== 'cmn_booking') {
            return new WP_Error('cmn_partner_credit_booking_not_found', 'Booking not found.');
        }
        if (!$this->is_school_user($school_user_id)) {
            return new WP_Error('cmn_partner_credit_not_school_user', 'School user is invalid.');
        }

        $booking_school_user_id = (int) $this->get_booking_school_user_id($booking_id);
        if ($booking_school_user_id > 0 && $booking_school_user_id !== $school_user_id) {
            return new WP_Error('cmn_partner_credit_booking_school_mismatch', 'Booking does not belong to the provided school user.');
        }

        $state = $this->ensure_school_partner_state_for_user($school_user_id);
        if (is_wp_error($state)) {
            return $state;
        }

        $school_charge_rate = $this->get_school_partner_credit_school_charge_rate($booking_id, $booking_day_date);
        if ($school_charge_rate <= 0) {
            return new WP_Error('cmn_partner_credit_missing_rate', 'School charge rate is missing for the booking day.');
        }

        $discount_percent = round(max(0, (float) ($state['discount_pct'] ?? 0)), 2);
        $credit_amount = round($school_charge_rate * ($discount_percent / 100), 2);

        return [
            'credit_amount' => $credit_amount,
            'discount_percent' => $discount_percent,
            'school_charge_rate' => $school_charge_rate,
        ];
    }

    /*
     * Prompt 19 acceptance checks:
     * 1) Insert function writes pending ledger rows with created_at/updated_at.
     * 2) Allowed credit_type values are enforced.
     * 3) Audit event credit_entry_created is written with required metadata.
     */
    public function insert_partner_credit_entry($args) {
        $args = is_array($args) ? $args : [];
        $school_user_id = (int) ($args['school_user_id'] ?? 0);
        $booking_id = isset($args['booking_id']) && (int) $args['booking_id'] > 0 ? (int) $args['booking_id'] : null;
        $booking_day_date = $this->normalize_invoice_date((string) ($args['booking_day_date'] ?? ''));
        $credit_amount = round((float) ($args['credit_amount'] ?? 0), 2);
        $credit_type = $this->normalize_school_partner_credit_type((string) ($args['credit_type'] ?? ''));
        $reference = substr(sanitize_text_field((string) ($args['reference'] ?? '')), 0, 100);
        $actor_user_id = (int) ($args['actor_user_id'] ?? get_current_user_id());

        if ($school_user_id < 1 || !$this->is_school_user($school_user_id)) {
            return new WP_Error('cmn_partner_credit_invalid_school_user', 'School user is required.');
        }
        if ($credit_type === '') {
            return new WP_Error('cmn_partner_credit_invalid_type', 'Credit type is invalid.');
        }
        if ($credit_amount == 0.0) {
            return new WP_Error('cmn_partner_credit_invalid_amount', 'Credit amount must be non-zero.');
        }
        if ($booking_id !== null && get_post_type($booking_id) !== 'cmn_booking') {
            return new WP_Error('cmn_partner_credit_booking_not_found', 'Booking not found.');
        }
        if ($booking_id !== null) {
            $booking_school_user_id = (int) $this->get_booking_school_user_id((int) $booking_id);
            if ($booking_school_user_id > 0 && $booking_school_user_id !== $school_user_id) {
                return new WP_Error('cmn_partner_credit_booking_school_mismatch', 'Booking does not belong to the provided school user.');
            }
        }
        if ($booking_day_date === '') {
            $booking_day_date = null;
        }

        global $wpdb;
        $table = $this->get_school_partner_credits_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return new WP_Error('cmn_partner_credit_table_missing', 'Partner credit ledger table does not exist.');
        }

        $now = current_time('mysql');
        $insert_data = [
            'school_user_id' => $school_user_id,
            'credit_type' => $credit_type,
            'credit_amount' => $credit_amount,
            'credit_status' => 'pending',
            'created_at' => $now,
            'updated_at' => $now,
        ];
        $insert_formats = ['%d', '%s', '%f', '%s', '%s', '%s'];
        if ($booking_id !== null) {
            $insert_data['booking_id'] = $booking_id;
            $insert_formats[] = '%d';
        }
        if ($booking_day_date !== null) {
            $insert_data['booking_day_date'] = $booking_day_date;
            $insert_formats[] = '%s';
        }
        if ($reference !== '') {
            $insert_data['reference'] = $reference;
            $insert_formats[] = '%s';
        }

        $inserted = $wpdb->insert($table, $insert_data, $insert_formats);

        if ($inserted === false) {
            return new WP_Error('cmn_partner_credit_insert_failed', 'Unable to create partner credit ledger entry.', [
                'db_error' => $wpdb->last_error,
            ]);
        }

        $entry_id = (int) $wpdb->insert_id;
        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'school',
                'entity_id' => $school_user_id,
                'event_type' => 'credit_entry_created',
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'entry_id' => $entry_id,
                    'booking_id' => $booking_id,
                    'booking_day_date' => $booking_day_date,
                    'credit_amount' => $credit_amount,
                    'credit_type' => $credit_type,
                    'reference' => $reference,
                    'credit_status' => 'pending',
                ],
            ]);
        }

        return [
            'id' => $entry_id,
            'school_user_id' => $school_user_id,
            'booking_id' => $booking_id,
            'booking_day_date' => $booking_day_date,
            'credit_amount' => $credit_amount,
            'credit_type' => $credit_type,
            'credit_status' => 'pending',
            'reference' => $reference,
            'created_at' => $now,
            'updated_at' => $now,
        ];
    }

    private function get_school_partner_credit_ledger_rows($options = []) {
        $options = is_array($options) ? $options : [];
        $page = max(1, (int) ($options['page'] ?? 1));
        $per_page = max(1, min(200, (int) ($options['per_page'] ?? 50)));
        $offset = ($page - 1) * $per_page;
        $school_user_id = isset($options['school_user_id']) && (int) $options['school_user_id'] > 0 ? (int) $options['school_user_id'] : 0;
        $credit_status = $this->normalize_school_partner_credit_status((string) ($options['credit_status'] ?? ''));

        global $wpdb;
        $table = $this->get_school_partner_credits_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [
                'rows' => [],
                'total_rows' => 0,
                'page' => 1,
                'per_page' => $per_page,
                'total_pages' => 1,
            ];
        }

        $where = ['1=1'];
        $params = [];
        if ($school_user_id > 0) {
            $where[] = 'school_user_id = %d';
            $params[] = $school_user_id;
        }
        if ($credit_status !== '') {
            $where[] = 'credit_status = %s';
            $params[] = $credit_status;
        }

        $where_sql = implode(' AND ', $where);
        $count_sql = "SELECT COUNT(*) FROM {$table} WHERE {$where_sql}";
        $count_query = !empty($params) ? $wpdb->prepare($count_sql, ...$params) : $count_sql;
        $total_rows = (int) $wpdb->get_var($count_query);

        $list_sql = "SELECT id, school_user_id, booking_id, booking_day_date, credit_type, reference, credit_amount, credit_status, related_invoice_id, created_at, updated_at
                     FROM {$table}
                     WHERE {$where_sql}
                     ORDER BY created_at DESC, id DESC
                     LIMIT %d OFFSET %d";
        $list_params = array_merge($params, [$per_page, $offset]);
        $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
        if (!is_array($rows)) {
            $rows = [];
        }

        $total_pages = (int) max(1, ceil($total_rows / max(1, $per_page)));
        if ($page > $total_pages && $total_pages > 0) {
            $page = $total_pages;
            $offset = ($page - 1) * $per_page;
            $list_params = array_merge($params, [$per_page, $offset]);
            $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
            if (!is_array($rows)) {
                $rows = [];
            }
        }

        return [
            'rows' => $rows,
            'total_rows' => $total_rows,
            'page' => $page,
            'per_page' => $per_page,
            'total_pages' => $total_pages,
        ];
    }

    private function normalize_booking_completion_confirmation_status($status) {
        $status = sanitize_key((string) $status);
        if (!in_array($status, ['pending', 'confirmed', 'disputed', 'auto_confirmed'], true)) {
            return 'pending';
        }
        return $status;
    }

    private function resolve_booking_confirmation_school_user_id($booking_id, $preferred_school_user_id = 0) {
        $booking_id = (int) $booking_id;
        $preferred_school_user_id = (int) $preferred_school_user_id;

        if ($preferred_school_user_id > 0 && $this->is_school_user($preferred_school_user_id)) {
            return $preferred_school_user_id;
        }

        $booking_school_user_id = (int) $this->get_booking_school_user_id($booking_id);
        if ($booking_school_user_id > 0 && $this->is_school_user($booking_school_user_id)) {
            return $booking_school_user_id;
        }

        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        if ($school_id > 0) {
            $school_user_ids = (array) $this->get_school_user_ids_for_school_request($school_id);
            foreach ($school_user_ids as $school_user_id) {
                $school_user_id = (int) $school_user_id;
                if ($school_user_id > 0 && $this->is_school_user($school_user_id)) {
                    return $school_user_id;
                }
            }
        }

        return 0;
    }

    /*
     * Prompt 14 acceptance checks:
     * 1) Creating a 5-day booking writes 5 pending rows for the booking's school user.
     * 2) Re-running population does not duplicate rows due INSERT IGNORE + unique key.
     */
    public function ensure_booking_completion_confirmations_for_booking($booking_id, $school_user_id = 0) {
        $booking_id = (int) $booking_id;
        $school_user_id = $this->resolve_booking_confirmation_school_user_id($booking_id, (int) $school_user_id);
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking') {
            return new WP_Error('cmn_school_partner_confirmation_invalid_booking', 'Booking not found.');
        }
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_confirmation_missing_school_user', 'School user is required for booking confirmations.');
        }

        $shift_dates = $this->get_rewards_booking_shift_dates($booking_id);
        if (!$shift_dates) {
            return [
                'booking_id' => $booking_id,
                'school_user_id' => $school_user_id,
                'processed' => 0,
                'inserted' => 0,
                'duplicates' => 0,
                'errors' => 0,
            ];
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return new WP_Error('cmn_school_partner_confirmation_table_missing', 'Booking completion confirmations table does not exist.');
        }

        $summary = [
            'booking_id' => $booking_id,
            'school_user_id' => $school_user_id,
            'processed' => 0,
            'inserted' => 0,
            'duplicates' => 0,
            'errors' => 0,
        ];
        foreach ((array) $shift_dates as $shift_date) {
            $shift_date = $this->normalize_invoice_date((string) $shift_date);
            if ($shift_date === '') {
                continue;
            }
            $summary['processed']++;
            $now = current_time('mysql');
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT IGNORE INTO {$table}
                (booking_id, school_user_id, booking_day_date, status, created_at, updated_at)
                VALUES
                (%d, %d, %s, %s, %s, %s)",
                $booking_id,
                $school_user_id,
                $shift_date,
                'pending',
                $now,
                $now
            ));
            if ($inserted === false) {
                $summary['errors']++;
                continue;
            }
            if ((int) $inserted > 0) {
                $summary['inserted']++;
            } else {
                $summary['duplicates']++;
            }
        }

        return $summary;
    }

    private function get_booking_completion_confirmation_row($school_user_id, $booking_id, $booking_day_date) {
        $school_user_id = (int) $school_user_id;
        $booking_id = (int) $booking_id;
        $booking_day_date = $this->normalize_invoice_date((string) $booking_day_date);
        if ($school_user_id < 1 || $booking_id < 1 || $booking_day_date === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE school_user_id = %d
               AND booking_id = %d
               AND booking_day_date = %s
             LIMIT 1",
            $school_user_id,
            $booking_id,
            $booking_day_date
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function enforce_school_partner_confirmation_permission($school_user_id, $booking_id, $school_id, $actor_user_id) {
        $school_user_id = (int) $school_user_id;
        $booking_id = (int) $booking_id;
        $school_id = (int) $school_id;
        $actor_user_id = max(0, (int) $actor_user_id);
        if ($actor_user_id < 1) {
            return true;
        }

        $ability = $actor_user_id === $school_user_id ? 'school_partner.mutate_self' : 'school_partner.mutate_any';
        $context = [
            'school_user_id' => $school_user_id,
            'school_id' => $school_id,
            'booking_id' => $booking_id,
        ];

        $current_user_id = (int) get_current_user_id();
        if ($current_user_id > 0 && $current_user_id === $actor_user_id && function_exists('cmn_require_ability')) {
            $permission = cmn_require_ability($ability, $context);
            if (is_wp_error($permission)) {
                return $permission;
            }
            return true;
        }

        if (function_exists('cmn_can') && !cmn_can($actor_user_id, $ability, $context)) {
            if (function_exists('cmn_log_permission_denied_event')) {
                $resolved_role = function_exists('cmn_role_from_user') ? (string) cmn_role_from_user($actor_user_id) : 'unknown';
                cmn_log_permission_denied_event($actor_user_id, $ability, $context, $resolved_role);
            }
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }
        return true;
    }

    private function sync_school_partner_confirmed_days_to_state($school_user_id, $actor_user_id = null) {
        $school_user_id = (int) $school_user_id;
        $actor_user_id = $actor_user_id === null ? (int) get_current_user_id() : (int) $actor_user_id;
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }

        return $this->school_partner_apply_tier_if_needed($school_user_id, $actor_user_id);
    }

    /*
     * Prompt 14 acceptance checks:
     * 1) Confirming a day updates status to confirmed and writes school_partner audit event.
     * 2) Confirm request for another school's booking is blocked.
     * 3) Re-running confirm is idempotent and does not duplicate status writes.
     */
    public function school_confirm_booking_day_completed($school_user_id, $booking_id, $date, $actor_user_id = null, $method = 'portal') {
        $school_user_id = (int) $school_user_id;
        $booking_id = (int) $booking_id;
        $booking_day_date = $this->normalize_invoice_date((string) $date);
        $actor_user_id = $actor_user_id === null ? (int) get_current_user_id() : (int) $actor_user_id;
        $method = sanitize_key((string) $method);
        if (!in_array($method, ['portal', 'email_link'], true)) {
            return new WP_Error('cmn_school_partner_confirmation_invalid_method', 'Invalid confirmation method.');
        }
        if ($school_user_id < 1 || !$this->is_school_user($school_user_id)) {
            return new WP_Error('cmn_school_partner_confirmation_invalid_school_user', 'School user is required.');
        }
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking' || $booking_day_date === '') {
            return new WP_Error('cmn_school_partner_confirmation_invalid_input', 'Booking and booking date are required.');
        }

        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return new WP_Error('cmn_school_partner_confirmation_invalid_school', 'Booking school not found.');
        }
        if (!$this->user_can_access_school($school_id, $school_user_id)) {
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }

        $permission = $this->enforce_school_partner_confirmation_permission($school_user_id, $booking_id, $school_id, $actor_user_id);
        if (is_wp_error($permission)) {
            return $permission;
        }

        $seed_result = $this->ensure_booking_completion_confirmations_for_booking($booking_id, $school_user_id);
        if (is_wp_error($seed_result)) {
            return $seed_result;
        }

        $row = $this->get_booking_completion_confirmation_row($school_user_id, $booking_id, $booking_day_date);
        if (!$row) {
            return new WP_Error('cmn_school_partner_confirmation_not_found', 'Booking day is not available for confirmation.');
        }

        $current_status = $this->normalize_booking_completion_confirmation_status((string) ($row['status'] ?? 'pending'));
        if (in_array($current_status, ['confirmed', 'auto_confirmed'], true)) {
            $tier_state = $this->sync_school_partner_confirmed_days_to_state($school_user_id, $actor_user_id);
            return [
                'booking_id' => $booking_id,
                'school_user_id' => $school_user_id,
                'booking_day_date' => $booking_day_date,
                'status' => 'confirmed',
                'already_confirmed' => true,
                'state' => is_wp_error($tier_state) ? [] : (array) $tier_state,
            ];
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $now = current_time('mysql');
        $updated = $wpdb->update(
            $table,
            [
                'status' => 'confirmed',
                'confirmed_at' => $now,
                'confirmation_token_hash' => null,
                'token_expires_at' => null,
                'overdue_flag' => 0,
                'updated_at' => $now,
            ],
            ['id' => (int) ($row['id'] ?? 0)],
            ['%s', '%s', '%s', '%s', '%d', '%s'],
            ['%d']
        );
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_confirmation_update_failed', 'Unable to confirm booking day.');
        }

        if ((int) $updated > 0 && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'booking',
                'entity_id' => $booking_id,
                'event_type' => 'booking_day_confirmed',
                'event_ref' => $booking_id . ':' . $booking_day_date,
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'school_user_id' => $school_user_id,
                    'date' => $booking_day_date,
                    'method' => $method,
                ],
            ]);
        }

        $tier_state = $this->sync_school_partner_confirmed_days_to_state($school_user_id, $actor_user_id);
        if (is_wp_error($tier_state)) {
            return $tier_state;
        }

        return [
            'booking_id' => $booking_id,
            'school_user_id' => $school_user_id,
            'booking_day_date' => $booking_day_date,
            'status' => 'confirmed',
            'already_confirmed' => false,
            'state' => (array) $tier_state,
        ];
    }

