    public function school_dispute_booking_day($school_user_id, $booking_id, $date, $reason, $actor_user_id = null) {
        $school_user_id = (int) $school_user_id;
        $booking_id = (int) $booking_id;
        $booking_day_date = $this->normalize_invoice_date((string) $date);
        $reason = sanitize_textarea_field((string) $reason);
        if (strlen($reason) > 2000) {
            $reason = substr($reason, 0, 2000);
        }
        $actor_user_id = $actor_user_id === null ? (int) get_current_user_id() : (int) $actor_user_id;

        if ($school_user_id < 1 || !$this->is_school_user($school_user_id)) {
            return new WP_Error('cmn_school_partner_dispute_invalid_school_user', 'School user is required.');
        }
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking' || $booking_day_date === '') {
            return new WP_Error('cmn_school_partner_dispute_invalid_input', 'Booking and booking date are required.');
        }
        if ($reason === '') {
            return new WP_Error('cmn_school_partner_dispute_reason_required', 'A dispute reason is required.');
        }

        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return new WP_Error('cmn_school_partner_dispute_invalid_school', 'Booking school not found.');
        }
        if (!$this->user_can_access_school($school_id, $school_user_id)) {
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }

        $permission = $this->enforce_school_partner_confirmation_permission($school_user_id, $booking_id, $school_id, $actor_user_id);
        if (is_wp_error($permission)) {
            return $permission;
        }

        $seed_result = $this->ensure_booking_completion_confirmations_for_booking($booking_id, $school_user_id);
        if (is_wp_error($seed_result)) {
            return $seed_result;
        }

        $row = $this->get_booking_completion_confirmation_row($school_user_id, $booking_id, $booking_day_date);
        if (!$row) {
            return new WP_Error('cmn_school_partner_dispute_not_found', 'Booking day is not available for dispute.');
        }

        $current_status = $this->normalize_booking_completion_confirmation_status((string) ($row['status'] ?? 'pending'));
        if ($current_status === 'disputed') {
            $tier_state = $this->sync_school_partner_confirmed_days_to_state($school_user_id, $actor_user_id);
            return [
                'booking_id' => $booking_id,
                'school_user_id' => $school_user_id,
                'booking_day_date' => $booking_day_date,
                'status' => 'disputed',
                'already_disputed' => true,
                'state' => is_wp_error($tier_state) ? [] : (array) $tier_state,
            ];
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $now = current_time('mysql');
        $updated = $wpdb->update(
            $table,
            [
                'status' => 'disputed',
                'disputed_at' => $now,
                'overdue_flag' => 0,
                'updated_at' => $now,
            ],
            ['id' => (int) ($row['id'] ?? 0)],
            ['%s', '%s', '%d', '%s'],
            ['%d']
        );
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_dispute_update_failed', 'Unable to dispute booking day.');
        }

        if ((int) $updated > 0 && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'booking',
                'entity_id' => $booking_id,
                'event_type' => 'booking_day_disputed',
                'event_ref' => $booking_id . ':' . $booking_day_date,
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'school_user_id' => $school_user_id,
                    'date' => $booking_day_date,
                    'reason' => $reason,
                ],
            ]);
        }

        $tier_state = $this->sync_school_partner_confirmed_days_to_state($school_user_id, $actor_user_id);
        if (is_wp_error($tier_state)) {
            return $tier_state;
        }

        return [
            'booking_id' => $booking_id,
            'school_user_id' => $school_user_id,
            'booking_day_date' => $booking_day_date,
            'status' => 'disputed',
            'already_disputed' => false,
            'state' => (array) $tier_state,
        ];
    }

    public function school_partner_get_confirmed_completed_days($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return 0;
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            $state = $this->ensure_school_partner_state_for_user($school_user_id);
            if (is_wp_error($state)) {
                return 0;
            }
            return max(0, (int) ($state['confirmed_completed_days'] ?? 0));
        }

        $count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM {$table}
             WHERE school_user_id = %d
               AND status IN ('confirmed', 'auto_confirmed')",
            $school_user_id
        ));
        return max(0, $count);
    }

    public function school_partner_get_pending_confirmations($school_user_id, $limit = 50) {
        $school_user_id = (int) $school_user_id;
        $limit = max(1, min(500, (int) $limit));
        if ($school_user_id < 1) {
            return [];
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT id, booking_id, school_user_id, booking_day_date, status, confirmed_at, disputed_at, auto_confirmed_at, token_expires_at, last_reminded_at, reminder_stage, overdue_flag, created_at, updated_at
             FROM {$table}
             WHERE school_user_id = %d
               AND status = %s
             ORDER BY booking_day_date ASC, id ASC
             LIMIT %d",
            $school_user_id,
            'pending',
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function get_school_partner_confirmation_request_ip() {
        $ip = '';
        if (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
            $parts = explode(',', (string) $_SERVER['HTTP_X_FORWARDED_FOR']);
            $ip = trim((string) ($parts[0] ?? ''));
        } elseif (!empty($_SERVER['REMOTE_ADDR'])) {
            $ip = trim((string) $_SERVER['REMOTE_ADDR']);
        }

        if ($ip === '') {
            return '';
        }
        return filter_var($ip, FILTER_VALIDATE_IP) ? $ip : '';
    }

    private function enforce_school_partner_confirmation_rate_limit() {
        $ip = $this->get_school_partner_confirmation_request_ip();
        $seed = $ip !== '' ? $ip : 'unknown';
        $key = 'cmn_bk_confirm_rl_' . substr(hash('sha256', $seed), 0, 32);
        $attempts = (int) get_transient($key);
        $attempts++;
        set_transient($key, $attempts, self::SCHOOL_PARTNER_CONFIRMATION_RATE_LIMIT_WINDOW);
        if ($attempts > self::SCHOOL_PARTNER_CONFIRMATION_RATE_LIMIT_MAX_ATTEMPTS) {
            return new WP_Error('cmn_school_partner_confirmation_rate_limited', 'Too many requests.');
        }
        return true;
    }

    private function get_school_partner_confirmation_generic_error_message() {
        return 'This confirmation link is invalid or expired. Please log into the portal to confirm your booking.';
    }

    private function render_school_partner_confirmation_result_page($is_success, $message = '', $status_code = 200) {
        $is_success = (bool) $is_success;
        $status_code = $is_success ? 200 : max(400, min(599, (int) $status_code));
        status_header($status_code);
        nocache_headers();

        $title = $is_success ? 'Thanks - booking confirmed.' : 'Unable to confirm booking.';
        $subtitle = $is_success
            ? 'You\'re one step closer to your next discount bracket.'
            : ($message !== '' ? (string) $message : $this->get_school_partner_confirmation_generic_error_message());
        $button_label = $is_success ? 'Open portal' : 'Log into portal';
        $portal_url = esc_url(add_query_arg(['view' => 'login'], $this->get_portal_base_url()));

        echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'
            . esc_html($title)
            . '</title><style>body{margin:0;background:#070b14;color:#f3f4f7;font-family:Segoe UI,Roboto,Arial,sans-serif}main{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px}.card{width:100%;max-width:560px;background:rgba(15,22,36,.92);border:1px solid rgba(255,255,255,.08);border-radius:16px;padding:28px;box-shadow:0 22px 40px rgba(0,0,0,.35)}h1{margin:0 0 10px;font-size:30px;line-height:1.2;color:#fff}p{margin:0 0 20px;font-size:17px;line-height:1.5;color:#c8cfde}.btn{display:inline-block;background:#d7263d;color:#fff;text-decoration:none;font-weight:700;padding:12px 18px;border-radius:10px}small{display:block;margin-top:14px;color:#93a0b9}</style></head><body><main><section class="card"><h1>'
            . esc_html($title)
            . '</h1><p>'
            . esc_html($subtitle)
            . '</p><a class="btn" href="'
            . $portal_url
            . '">'
            . esc_html($button_label)
            . '</a><small>CoverMeNow ONE</small></section></main></body></html>';
        exit;
    }

    private function get_booking_completion_confirmation_row_for_school($school_id, $booking_id, $booking_day_date) {
        $school_id = (int) $school_id;
        $booking_id = (int) $booking_id;
        $booking_day_date = $this->normalize_invoice_date((string) $booking_day_date);
        if ($school_id < 1 || $booking_id < 1 || $booking_day_date === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE booking_id = %d
               AND booking_day_date = %s
             ORDER BY id ASC",
            $booking_id,
            $booking_day_date
        ), ARRAY_A);
        if (!is_array($rows) || empty($rows)) {
            return [];
        }

        foreach ($rows as $row) {
            $row_school_user_id = (int) ($row['school_user_id'] ?? 0);
            if ($row_school_user_id < 1) {
                continue;
            }
            if (!$this->is_school_user($row_school_user_id)) {
                continue;
            }
            $resolved_school_id = (int) $this->resolve_school_id_for_user($row_school_user_id);
            if ($resolved_school_id !== $school_id) {
                continue;
            }
            return is_array($row) ? $row : [];
        }

        return [];
    }

    private function is_school_partner_confirmation_token_expired($token_expires_at, DateTimeImmutable $reference = null) {
        $token_expires_at = trim((string) $token_expires_at);
        if ($token_expires_at === '') {
            return true;
        }

        $tz = wp_timezone();
        if (!$reference instanceof DateTimeImmutable) {
            $reference = function_exists('cmn_now')
                ? cmn_now()->setTimezone($tz)
                : new DateTimeImmutable('now', $tz);
        } else {
            $reference = $reference->setTimezone($tz);
        }

        try {
            $expires_at = new DateTimeImmutable($token_expires_at, $tz);
        } catch (Throwable $e) {
            return true;
        }
        return $reference > $expires_at;
    }

    private function build_school_partner_booking_confirmation_url($booking_id, $school_id, $booking_day_date, $token) {
        $booking_id = (int) $booking_id;
        $school_id = (int) $school_id;
        $booking_day_date = $this->normalize_invoice_date((string) $booking_day_date);
        $token = trim((string) $token);
        if ($booking_id < 1 || $school_id < 1 || $booking_day_date === '' || $token === '') {
            return '';
        }
        return add_query_arg([
            'action' => 'cmn_confirm_booking_day',
            'booking_id' => $booking_id,
            'date' => $booking_day_date,
            'school_id' => $school_id,
            'token' => $token,
        ], admin_url('admin-post.php'));
    }

    private function generate_school_partner_confirmation_token() {
        try {
            return bin2hex(random_bytes(32));
        } catch (Throwable $e) {
            $entropy = wp_generate_password(128, true, true) . ':' . microtime(true) . ':' . wp_rand();
            return hash('sha256', $entropy);
        }
    }

    private function issue_school_partner_confirmation_token_for_row($confirmation_id) {
        $confirmation_id = (int) $confirmation_id;
        if ($confirmation_id < 1) {
            return new WP_Error('cmn_school_partner_confirmation_missing_row', 'Confirmation row is required.');
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $token = $this->generate_school_partner_confirmation_token();
        if ($token === '') {
            return new WP_Error('cmn_school_partner_confirmation_token_failed', 'Unable to generate confirmation token.');
        }
        $token_hash_hex = hash('sha256', $token);
        $tz = wp_timezone();
        $now = function_exists('cmn_now')
            ? cmn_now()->setTimezone($tz)
            : new DateTimeImmutable('now', $tz);
        $expires_at = $now->modify('+' . self::SCHOOL_PARTNER_CONFIRMATION_TOKEN_TTL_DAYS . ' days')->format('Y-m-d H:i:s');
        $now_mysql = $now->format('Y-m-d H:i:s');

        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET confirmation_token_hash = UNHEX(%s),
                 token_expires_at = %s,
                 updated_at = %s
             WHERE id = %d
               AND status = %s",
            $token_hash_hex,
            $expires_at,
            $now_mysql,
            $confirmation_id,
            'pending'
        ));
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_confirmation_token_store_failed', 'Unable to store confirmation token.');
        }
        if ((int) $updated < 1) {
            return new WP_Error('cmn_school_partner_confirmation_token_stale', 'Confirmation row is no longer pending.');
        }

        return [
            'token' => $token,
            'expires_at' => $expires_at,
        ];
    }

    private function get_school_partner_confirmation_email_rows($limit = 100) {
        $limit = max(1, min(500, (int) $limit));
        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }

        $tz = wp_timezone();
        $now = function_exists('cmn_now')
            ? cmn_now()->setTimezone($tz)
            : new DateTimeImmutable('now', $tz);
        $yesterday = $now->modify('-1 day')->format('Y-m-d');
        $now_mysql = $now->format('Y-m-d H:i:s');

        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT id, booking_id, school_user_id, booking_day_date, status, token_expires_at, created_at, updated_at
             FROM {$table}
             WHERE status = %s
               AND booking_day_date <= %s
               AND (
                   confirmation_token_hash IS NULL
                   OR OCTET_LENGTH(confirmation_token_hash) = 0
                   OR token_expires_at IS NULL
                   OR token_expires_at <= %s
               )
             ORDER BY booking_day_date ASC, id ASC
             LIMIT %d",
            'pending',
            $yesterday,
            $now_mysql,
            $limit
        ), ARRAY_A);

        return is_array($rows) ? $rows : [];
    }

    private function send_school_partner_confirmation_email_for_row(array $row, array $context = []) {
        $confirmation_id = (int) ($row['id'] ?? 0);
        $booking_id = (int) ($row['booking_id'] ?? 0);
        $school_user_id = (int) ($row['school_user_id'] ?? 0);
        $booking_day_date = $this->normalize_invoice_date((string) ($row['booking_day_date'] ?? ''));

        if ($confirmation_id < 1 || $booking_id < 1 || $school_user_id < 1 || $booking_day_date === '') {
            return [
                'status' => 'skipped',
                'reason' => 'Invalid confirmation row payload.',
            ];
        }
        if (get_post_type($booking_id) !== 'cmn_booking') {
            return [
                'status' => 'skipped',
                'reason' => 'Booking no longer exists.',
            ];
        }

        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [
                'status' => 'skipped',
                'reason' => 'School mapping missing for booking.',
            ];
        }
        $resolved_school_id = (int) $this->resolve_school_id_for_user($school_user_id);
        if ($resolved_school_id < 1 || $resolved_school_id !== $school_id) {
            return [
                'status' => 'skipped',
                'reason' => 'School user does not match booking school.',
            ];
        }

        $school_user = get_user_by('id', $school_user_id);
        $to_email = $school_user instanceof WP_User ? sanitize_email((string) $school_user->user_email) : '';
        if ($to_email === '') {
            $to_email = $this->get_school_primary_contact_email($school_id);
        }
        if ($to_email === '') {
            return [
                'status' => 'failed',
                'reason' => 'School email is unavailable.',
            ];
        }

        $token_result = $this->issue_school_partner_confirmation_token_for_row($confirmation_id);
        if (is_wp_error($token_result)) {
            return [
                'status' => 'failed',
                'reason' => $token_result->get_error_message(),
            ];
        }

        $token = (string) ($token_result['token'] ?? '');
        $confirm_url = $this->build_school_partner_booking_confirmation_url($booking_id, $school_id, $booking_day_date, $token);
        if ($confirm_url === '') {
            global $wpdb;
            $table = $this->get_booking_completion_confirmations_table();
            $wpdb->update(
                $table,
                [
                    'confirmation_token_hash' => null,
                    'token_expires_at' => null,
                    'updated_at' => current_time('mysql'),
                ],
                ['id' => $confirmation_id],
                ['%s', '%s', '%s'],
                ['%d']
            );
            return [
                'status' => 'failed',
                'reason' => 'Confirmation URL could not be generated.',
            ];
        }

        $school_name = trim((string) get_the_title($school_id));
        if ($school_name === '') {
            $school_name = 'School team';
        }
        $candidate_name = '';
        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($candidate_id > 0 && get_post_type($candidate_id) === 'cmn_candidate') {
            $candidate_name = trim((string) get_the_title($candidate_id));
        }

        $booking_date_display = $booking_day_date;
        $booking_date_ts = strtotime($booking_day_date . ' 00:00:00');
        if ($booking_date_ts !== false) {
            if (function_exists('wp_date')) {
                $booking_date_display = wp_date('l j F Y', $booking_date_ts, wp_timezone());
            } else {
                $booking_date_display = date_i18n('l j F Y', $booking_date_ts);
            }
        }

        $subject = "Confirm yesterday's cover booking";
        $candidate_html = $candidate_name !== ''
            ? '<p style="margin:0 0 12px;color:#c7cedf;"><strong>Candidate:</strong> ' . esc_html($candidate_name) . '</p>'
            : '';
        $candidate_text = $candidate_name !== '' ? "Candidate: {$candidate_name}\n" : '';
        $html_body = ''
            . '<p style="margin:0 0 14px;color:#f4f6fb;">Hello ' . esc_html($school_name) . ',</p>'
            . '<p style="margin:0 0 12px;color:#c7cedf;">Please confirm yesterday\'s cover booking.</p>'
            . '<p style="margin:0 0 12px;color:#c7cedf;"><strong>Booking date:</strong> ' . esc_html($booking_date_display) . '</p>'
            . $candidate_html
            . '<p style="margin:18px 0;"><a href="' . esc_url($confirm_url) . '" style="display:inline-block;padding:12px 18px;border-radius:10px;background:#d7263d;color:#ffffff;text-decoration:none;font-weight:700;">Confirm booking day</a></p>'
            . '<p style="margin:0;color:#c7cedf;">Confirming helps keep records accurate and moves you closer to your partner discount.</p>';
        $plain_body = "Hello {$school_name},\n\n"
            . "Please confirm yesterday's cover booking.\n"
            . "Booking date: {$booking_date_display}\n"
            . $candidate_text
            . "\nConfirm booking day:\n{$confirm_url}\n\n"
            . "Confirming helps keep records accurate and moves you closer to your partner discount.";

        $previous_log_type_exists = array_key_exists('cmn_school_mail_log_type', $GLOBALS);
        $previous_log_type = $previous_log_type_exists ? (string) $GLOBALS['cmn_school_mail_log_type'] : '';
        $GLOBALS['cmn_school_mail_log_type'] = 'school_partner_confirmation_email';
        $send_result = $this->send_school_email_with_alt_body($to_email, $subject, $html_body, $plain_body, [
            'From: CoverMeNow ONE <school@covermenow.co.uk>',
            'Reply-To: school@covermenow.co.uk',
        ], []);
        if ($previous_log_type_exists) {
            $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
        } else {
            unset($GLOBALS['cmn_school_mail_log_type']);
        }

        $sent = !empty($send_result['sent']);
        if (!$sent) {
            global $wpdb;
            $table = $this->get_booking_completion_confirmations_table();
            $wpdb->update(
                $table,
                [
                    'confirmation_token_hash' => null,
                    'token_expires_at' => null,
                    'updated_at' => current_time('mysql'),
                ],
                ['id' => $confirmation_id],
                ['%s', '%s', '%s'],
                ['%d']
            );
            return [
                'status' => 'failed',
                'reason' => (string) ($send_result['error_message'] ?? 'Unable to send confirmation email.'),
            ];
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'school',
                'entity_id' => $school_user_id,
                'event_type' => 'confirmation_email_sent',
                'event_ref' => $booking_id . ':' . $booking_day_date,
                'actor_user_id' => !empty($context['actor_user_id']) ? (int) $context['actor_user_id'] : null,
                'metadata' => [
                    'booking_id' => $booking_id,
                    'date' => $booking_day_date,
                ],
            ]);
        }

        return [
            'status' => 'sent',
        ];
    }

    /*
     * Prompt 15 acceptance checks:
     * 1) Pending rows from yesterday or earlier receive tokenized email confirmations.
     * 2) Re-running the cron is idempotent because pending rows with active tokens are skipped until expiry.
     * 3) Failed sends reset token fields so retries can happen on the next run.
     */
    private function run_school_partner_confirmation_email_job($trigger = 'cron', $actor_user_id = 0) {
        $lock_key = self::SCHOOL_PARTNER_CONFIRMATION_EMAIL_LOCK_KEY;
        if (get_transient($lock_key)) {
            return [
                'ok' => false,
                'message' => 'School partner confirmation email job is already running.',
            ];
        }
        set_transient($lock_key, 1, self::SCHOOL_PARTNER_CONFIRMATION_EMAIL_LOCK_TTL);

        try {
            $summary = [
                'ok' => true,
                'trigger' => (string) $trigger,
                'processed' => 0,
                'sent' => 0,
                'skipped' => 0,
                'failed' => 0,
            ];
            $batch_limit = 100;
            $safety_batches = 0;

            do {
                $rows = $this->get_school_partner_confirmation_email_rows($batch_limit);
                if (!$rows) {
                    break;
                }
                foreach ($rows as $row) {
                    $summary['processed']++;
                    $dispatch = $this->send_school_partner_confirmation_email_for_row((array) $row, [
                        'trigger' => (string) $trigger,
                        'actor_user_id' => (int) $actor_user_id,
                    ]);
                    $status = sanitize_key((string) ($dispatch['status'] ?? 'failed'));
                    if ($status === 'sent') {
                        $summary['sent']++;
                    } elseif ($status === 'skipped') {
                        $summary['skipped']++;
                    } else {
                        $summary['failed']++;
                    }
                }
                $safety_batches++;
                if ($safety_batches >= 25) {
                    break;
                }
            } while (count($rows) === $batch_limit);

            return $summary;
        } finally {
            delete_transient($lock_key);
        }
    }

    private function normalize_school_partner_confirmation_reminder_stage($stage) {
        $stage = (int) $stage;
        if ($stage < 0) {
            return 0;
        }
        if ($stage > 3) {
            return 3;
        }
        return $stage;
    }

    private function get_school_partner_confirmation_age_days($booking_day_date, DateTimeImmutable $reference = null) {
        $booking_day_date = $this->normalize_invoice_date((string) $booking_day_date);
        if ($booking_day_date === '') {
            return 0;
        }
        $tz = wp_timezone();
        if (!$reference instanceof DateTimeImmutable) {
            $reference = function_exists('cmn_now')
                ? cmn_now()->setTimezone($tz)
                : new DateTimeImmutable('now', $tz);
        } else {
            $reference = $reference->setTimezone($tz);
        }
        try {
            $day = new DateTimeImmutable($booking_day_date . ' 00:00:00', $tz);
        } catch (Throwable $e) {
            return 0;
        }
        $reference_day = $reference->setTime(0, 0, 0);
        if ($reference_day < $day) {
            return 0;
        }
        $interval = $day->diff($reference_day);
        return max(0, (int) ($interval->days ?? 0));
    }

    private function determine_school_partner_confirmation_reminder_stage($age_days, $current_stage) {
        $age_days = max(0, (int) $age_days);
        $current_stage = $this->normalize_school_partner_confirmation_reminder_stage($current_stage);
        if ($age_days >= 7 && $current_stage < 3) {
            return 3;
        }
        if ($age_days >= 3 && $current_stage < 2) {
            return 2;
        }
        if ($age_days >= 1 && $current_stage < 1) {
            return 1;
        }
        return 0;
    }

    private function get_school_partner_confirmation_reminder_rows($limit = 100) {
        $limit = max(1, min(500, (int) $limit));
        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }

        $tz = wp_timezone();
        $now = function_exists('cmn_now')
            ? cmn_now()->setTimezone($tz)
            : new DateTimeImmutable('now', $tz);
        $yesterday = $now->modify('-1 day')->format('Y-m-d');
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT id, booking_id, school_user_id, booking_day_date, status, token_expires_at, reminder_stage, last_reminded_at, overdue_flag
             FROM {$table}
             WHERE status = %s
               AND booking_day_date <= %s
               AND COALESCE(reminder_stage, 0) < 3
             ORDER BY booking_day_date ASC, id ASC
             LIMIT %d",
            'pending',
            $yesterday,
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function get_school_partner_confirmation_reminder_subject($stage) {
        $stage = $this->normalize_school_partner_confirmation_reminder_stage($stage);
        if ($stage === 1) {
            return "Quick confirmation: yesterday's booking";
        }
        if ($stage === 2) {
            return 'Reminder: please confirm completed booking';
        }
        return 'Final reminder: confirm booking to keep records accurate';
    }

    private function get_school_partner_confirmation_reminder_token_for_row($confirmation_id, $token_expires_at = '') {
        // Raw tokens are not persisted by design, so reminder emails rotate to a fresh single-use token.
        return $this->issue_school_partner_confirmation_token_for_row($confirmation_id);
    }

    private function send_school_partner_confirmation_reminder_for_row(array $row, $stage, array $context = []) {
        $stage = $this->normalize_school_partner_confirmation_reminder_stage($stage);
        if ($stage < 1) {
            return [
                'status' => 'skipped',
                'reason' => 'Reminder stage not due.',
            ];
        }

        $confirmation_id = (int) ($row['id'] ?? 0);
        $booking_id = (int) ($row['booking_id'] ?? 0);
        $school_user_id = (int) ($row['school_user_id'] ?? 0);
        $booking_day_date = $this->normalize_invoice_date((string) ($row['booking_day_date'] ?? ''));
        if ($confirmation_id < 1 || $booking_id < 1 || $school_user_id < 1 || $booking_day_date === '') {
            return [
                'status' => 'skipped',
                'reason' => 'Invalid reminder payload.',
            ];
        }
        if (get_post_type($booking_id) !== 'cmn_booking') {
            return [
                'status' => 'skipped',
                'reason' => 'Booking no longer exists.',
            ];
        }

        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [
                'status' => 'skipped',
                'reason' => 'Booking school missing.',
            ];
        }
        $resolved_school_id = (int) $this->resolve_school_id_for_user($school_user_id);
        if ($resolved_school_id < 1 || $resolved_school_id !== $school_id) {
            return [
                'status' => 'skipped',
                'reason' => 'School user mapping mismatch.',
            ];
        }

        $school_user = get_user_by('id', $school_user_id);
        $to_email = $school_user instanceof WP_User ? sanitize_email((string) $school_user->user_email) : '';
        if ($to_email === '') {
            $to_email = $this->get_school_primary_contact_email($school_id);
        }
        if ($to_email === '') {
            return [
                'status' => 'failed',
                'reason' => 'School recipient email missing.',
            ];
        }

        $token_result = $this->get_school_partner_confirmation_reminder_token_for_row($confirmation_id, (string) ($row['token_expires_at'] ?? ''));
        if (is_wp_error($token_result)) {
            return [
                'status' => 'failed',
                'reason' => $token_result->get_error_message(),
            ];
        }
        $token = (string) ($token_result['token'] ?? '');
        $confirm_url = $this->build_school_partner_booking_confirmation_url($booking_id, $school_id, $booking_day_date, $token);
        if ($confirm_url === '') {
            return [
                'status' => 'failed',
                'reason' => 'Unable to build reminder confirmation URL.',
            ];
        }

        $school_name = trim((string) get_the_title($school_id));
        if ($school_name === '') {
            $school_name = 'School team';
        }
        $candidate_name = '';
        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($candidate_id > 0 && get_post_type($candidate_id) === 'cmn_candidate') {
            $candidate_name = trim((string) get_the_title($candidate_id));
        }

        $booking_date_display = $booking_day_date;
        $booking_date_ts = strtotime($booking_day_date . ' 00:00:00');
        if ($booking_date_ts !== false) {
            if (function_exists('wp_date')) {
                $booking_date_display = wp_date('l j F Y', $booking_date_ts, wp_timezone());
            } else {
                $booking_date_display = date_i18n('l j F Y', $booking_date_ts);
            }
        }

        $subject = $this->get_school_partner_confirmation_reminder_subject($stage);
        $stage_label = $stage === 1 ? '24h' : ($stage === 2 ? '72h' : '7d');
        $candidate_html = $candidate_name !== ''
            ? '<p style="margin:0 0 12px;color:#c7cedf;"><strong>Candidate:</strong> ' . esc_html($candidate_name) . '</p>'
            : '';
        $candidate_text = $candidate_name !== '' ? "Candidate: {$candidate_name}\n" : '';
        $shared_copy = 'This helps keep records accurate and moves you closer to your partner discount.';
        $final_line = $stage === 3
            ? 'If you\'re unable to confirm, please reply to this email or log into the portal to dispute.'
            : '';

        $html_body = ''
            . '<p style="margin:0 0 14px;color:#f4f6fb;">Hello ' . esc_html($school_name) . ',</p>'
            . '<p style="margin:0 0 12px;color:#c7cedf;">Please confirm this completed booking day.</p>'
            . '<p style="margin:0 0 12px;color:#c7cedf;"><strong>Booking date:</strong> ' . esc_html($booking_date_display) . '</p>'
            . $candidate_html
            . '<p style="margin:18px 0;"><a href="' . esc_url($confirm_url) . '" style="display:inline-block;padding:12px 18px;border-radius:10px;background:#d7263d;color:#ffffff;text-decoration:none;font-weight:700;">Confirm booking day</a></p>'
            . '<p style="margin:0 0 10px;color:#c7cedf;">' . esc_html($shared_copy) . '</p>';
        if ($final_line !== '') {
            $html_body .= '<p style="margin:0;color:#c7cedf;">' . esc_html($final_line) . '</p>';
        }

        $plain_body = "Hello {$school_name},\n\n"
            . "Please confirm this completed booking day.\n"
            . "Booking date: {$booking_date_display}\n"
            . $candidate_text
            . "\nConfirm booking day:\n{$confirm_url}\n\n"
            . $shared_copy;
        if ($final_line !== '') {
            $plain_body .= "\n\n" . $final_line;
        }

        $previous_log_type_exists = array_key_exists('cmn_school_mail_log_type', $GLOBALS);
        $previous_log_type = $previous_log_type_exists ? (string) $GLOBALS['cmn_school_mail_log_type'] : '';
        $GLOBALS['cmn_school_mail_log_type'] = 'school_partner_confirmation_reminder';
        $send_result = $this->send_school_email_with_alt_body($to_email, $subject, $html_body, $plain_body, [
            'From: CoverMeNow ONE <school@covermenow.co.uk>',
            'Reply-To: school@covermenow.co.uk',
        ], []);
        if ($previous_log_type_exists) {
            $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
        } else {
            unset($GLOBALS['cmn_school_mail_log_type']);
        }

        if (empty($send_result['sent'])) {
            return [
                'status' => 'failed',
                'reason' => (string) ($send_result['error_message'] ?? 'Reminder send failed.'),
            ];
        }

        global $wpdb;
        $table = $this->get_booking_completion_confirmations_table();
        $now = current_time('mysql');
        $overdue_flag = $stage >= 3 ? 1 : 0;
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET reminder_stage = %d,
                 last_reminded_at = %s,
                 overdue_flag = %d,
                 updated_at = %s
             WHERE id = %d
               AND status = %s
               AND COALESCE(reminder_stage, 0) < %d",
            $stage,
            $now,
            $overdue_flag,
            $now,
            $confirmation_id,
            'pending',
            $stage
        ));
        if ($updated === false) {
            return [
                'status' => 'failed',
                'reason' => 'Reminder state update failed.',
            ];
        }
        if ((int) $updated < 1) {
            return [
                'status' => 'skipped',
                'reason' => 'Reminder stage already processed.',
            ];
        }

        $age_days = isset($context['age_days']) ? max(0, (int) $context['age_days']) : $this->get_school_partner_confirmation_age_days($booking_day_date);
        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'school',
                'entity_id' => $school_user_id,
                'event_type' => 'confirmation_reminder_sent',
                'event_ref' => $booking_id . ':' . $booking_day_date,
                'actor_user_id' => !empty($context['actor_user_id']) ? (int) $context['actor_user_id'] : null,
                'metadata' => [
                    'booking_id' => $booking_id,
                    'date' => $booking_day_date,
                    'stage' => $stage,
                    'stage_label' => $stage_label,
                    'age_days' => $age_days,
                ],
            ]);
            if ($stage >= 3) {
                cmn_audit_log_event([
                    'module' => 'school_partner',
                    'entity_type' => 'school',
                    'entity_id' => $school_user_id,
                    'event_type' => 'confirmation_overdue_7d',
                    'event_ref' => $booking_id . ':' . $booking_day_date,
                    'actor_user_id' => !empty($context['actor_user_id']) ? (int) $context['actor_user_id'] : null,
                    'metadata' => [
                        'booking_id' => $booking_id,
                        'date' => $booking_day_date,
                        'age_days' => $age_days,
                        'overdue_flag' => 1,
                    ],
                ]);
            }
        }

        return [
            'status' => 'sent',
            'stage' => $stage,
        ];
    }

    /*
     * Prompt 16 acceptance checks:
     * 1) 24h reminder (stage 1) sends once per pending booking-day.
     * 2) 72h reminder (stage 2) sends once when still pending.
     * 3) 7d reminder (stage 3) sends once and marks overdue_flag=1.
     * 4) Cron re-runs do not duplicate stage reminders.
     * 5) Reminder sends rotate to a fresh 14-day token.
     */
    private function run_school_partner_confirmation_reminder_job($trigger = 'cron', $actor_user_id = 0) {
        $lock_key = self::SCHOOL_PARTNER_CONFIRMATION_REMINDER_LOCK_KEY;
        if (get_transient($lock_key)) {
            return [
                'ok' => false,
                'message' => 'School partner confirmation reminder job is already running.',
            ];
        }
        set_transient($lock_key, 1, self::SCHOOL_PARTNER_CONFIRMATION_REMINDER_LOCK_TTL);

        try {
            $summary = [
                'ok' => true,
                'trigger' => (string) $trigger,
                'processed' => 0,
                'sent' => 0,
                'stage_1_sent' => 0,
                'stage_2_sent' => 0,
                'stage_3_sent' => 0,
                'skipped' => 0,
                'failed' => 0,
            ];
            $batch_limit = 100;
            $safety_batches = 0;
            $reference = function_exists('cmn_now')
                ? cmn_now()->setTimezone(wp_timezone())
                : new DateTimeImmutable('now', wp_timezone());

            do {
                $rows = $this->get_school_partner_confirmation_reminder_rows($batch_limit);
                if (!$rows) {
                    break;
                }

                foreach ($rows as $row) {
                    $summary['processed']++;
                    $age_days = $this->get_school_partner_confirmation_age_days((string) ($row['booking_day_date'] ?? ''), $reference);
                    $current_stage = $this->normalize_school_partner_confirmation_reminder_stage((int) ($row['reminder_stage'] ?? 0));
                    $target_stage = $this->determine_school_partner_confirmation_reminder_stage($age_days, $current_stage);
                    if ($target_stage < 1) {
                        $summary['skipped']++;
                        continue;
                    }

                    $dispatch = $this->send_school_partner_confirmation_reminder_for_row((array) $row, $target_stage, [
                        'trigger' => (string) $trigger,
                        'actor_user_id' => (int) $actor_user_id,
                        'age_days' => $age_days,
                    ]);
                    $status = sanitize_key((string) ($dispatch['status'] ?? 'failed'));
                    if ($status === 'sent') {
                        $summary['sent']++;
                        if ($target_stage === 1) {
                            $summary['stage_1_sent']++;
                        } elseif ($target_stage === 2) {
                            $summary['stage_2_sent']++;
                        } elseif ($target_stage === 3) {
                            $summary['stage_3_sent']++;
                        }
                    } elseif ($status === 'skipped') {
                        $summary['skipped']++;
                    } else {
                        $summary['failed']++;
                    }
                }

                $safety_batches++;
                if ($safety_batches >= 25) {
                    break;
                }
            } while (count($rows) === $batch_limit);

            return $summary;
        } finally {
            delete_transient($lock_key);
        }
    }

    /*
     * Prompt 15 acceptance checks:
     * 1) Pending rows from yesterday get emailed signed confirmation links.
     * 2) Confirm link succeeds once, then subsequent clicks fail with a generic error page.
     * 3) Expired tokens fail with the same generic error page.
     * 4) Audit events are written for confirmation_email_sent and booking_day_confirmed (method=email_link).
     */
    public function handle_confirm_booking_day() {
        $generic_message = $this->get_school_partner_confirmation_generic_error_message();

        $rate_limit = $this->enforce_school_partner_confirmation_rate_limit();
        if (is_wp_error($rate_limit)) {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 429);
        }

        $booking_id = isset($_REQUEST['booking_id']) ? (int) wp_unslash($_REQUEST['booking_id']) : 0;
        $school_id = isset($_REQUEST['school_id']) ? (int) wp_unslash($_REQUEST['school_id']) : 0;
        $booking_day_date = $this->normalize_invoice_date((string) wp_unslash($_REQUEST['date'] ?? ''));
        $token = strtolower(trim((string) wp_unslash($_REQUEST['token'] ?? '')));

        if ($booking_id < 1 || $school_id < 1 || $booking_day_date === '' || !preg_match('/^[a-f0-9]{64,128}$/', $token)) {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 400);
        }
        if (get_post_type($booking_id) !== 'cmn_booking') {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 400);
        }
        $booking_school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        if ($booking_school_id < 1 || $booking_school_id !== $school_id) {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 400);
        }

        $row = $this->get_booking_completion_confirmation_row_for_school($school_id, $booking_id, $booking_day_date);
        if (!$row) {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 400);
        }

        $current_status = $this->normalize_booking_completion_confirmation_status((string) ($row['status'] ?? 'pending'));
        if ($current_status !== 'pending') {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 400);
        }

        $now = function_exists('cmn_now')
            ? cmn_now()->setTimezone(wp_timezone())
            : new DateTimeImmutable('now', wp_timezone());
        $token_expires_at = (string) ($row['token_expires_at'] ?? '');
        if ($this->is_school_partner_confirmation_token_expired($token_expires_at, $now)) {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 400);
        }

        $stored_hash = $row['confirmation_token_hash'] ?? '';
        $provided_hash = hash('sha256', $token, true);
        if (!is_string($stored_hash) || strlen($stored_hash) !== 32 || !hash_equals($stored_hash, $provided_hash)) {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 400);
        }

        $school_user_id = (int) ($row['school_user_id'] ?? 0);
        if ($school_user_id < 1) {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 400);
        }

        $confirmed = $this->school_confirm_booking_day_completed($school_user_id, $booking_id, $booking_day_date, 0, 'email_link');
        if (is_wp_error($confirmed)) {
            $this->render_school_partner_confirmation_result_page(false, $generic_message, 400);
        }

        $this->render_school_partner_confirmation_result_page(true, '');
    }

    public function handle_booking_post_saved($post_id, $post, $update) {
        $post_id = (int) $post_id;
        if ($post_id < 1 || ($post instanceof WP_Post && $post->post_type !== 'cmn_booking')) {
            return;
        }
        if (wp_is_post_autosave($post_id) || wp_is_post_revision($post_id)) {
            return;
        }
        $result = $this->ensure_booking_completion_confirmations_for_booking($post_id);
        if (is_wp_error($result) && defined('WP_DEBUG') && WP_DEBUG) {
            error_log('CMN booking confirmation seed failed on save for booking #' . $post_id . ': ' . $result->get_error_message());
        }
    }

    private function get_allowed_invoice_statuses() {
        return ['draft', 'issued', 'sent', 'paid', 'void'];
    }

    private function normalize_invoice_status($status) {
        $status = sanitize_key((string) $status);
        if (!in_array($status, $this->get_allowed_invoice_statuses(), true)) {
            return 'draft';
        }
        return $status;
    }

    private function normalize_invoice_currency($currency) {
        $currency = strtoupper(trim((string) $currency));
        if (!preg_match('/^[A-Z]{3}$/', $currency)) {
            return 'GBP';
        }
        return $currency;
    }

    private function normalize_invoice_date($date_value) {
        $date_value = trim((string) $date_value);
        if ($date_value === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_value)) {
            return '';
        }
        return $date_value;
    }

    private function normalize_invoice_datetime($datetime_value) {
        $datetime_value = trim((string) $datetime_value);
        if ($datetime_value === '') {
            return '';
        }
        $timestamp = strtotime($datetime_value);
        if ($timestamp === false) {
            return '';
        }
        return gmdate('Y-m-d H:i:s', $timestamp);
    }

    private function can_modify_invoice_records($user_id = 0) {
        $user_id = (int) ($user_id ?: get_current_user_id());
        if ($user_id < 1) {
            return false;
        }
        return $this->is_admin_user($user_id) || $this->is_staff_role($user_id);
    }

    private function is_invoice_content_locked($status) {
        $status = $this->normalize_invoice_status((string) $status);
        return in_array($status, ['sent', 'paid', 'void'], true);
    }

    private function get_invoice_lock_message($status) {
        $status = $this->normalize_invoice_status((string) $status);
        if (!$this->is_invoice_content_locked($status)) {
            return '';
        }
        return sprintf('Invoice is %s and is locked.', strtoupper($status));
    }

    private function log_invoice_audit_event($invoice_id, $action, $details = []) {
        $invoice_id = (int) $invoice_id;
        $action = substr(sanitize_key((string) $action), 0, 80);
        $details = is_array($details) ? $details : [];
        if ($invoice_id < 1 || $action === '') {
            return 0;
        }

        $invoice = !empty($details['invoice']) && is_array($details['invoice'])
            ? (array) $details['invoice']
            : $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            return 0;
        }
        $school_id = max(0, (int) ($details['school_id'] ?? (int) ($invoice['school_id'] ?? 0)));
        if ($school_id < 1) {
            return 0;
        }

        $from_status = '';
        if (array_key_exists('from_status', $details) && $details['from_status'] !== null) {
            $from_status = $this->normalize_invoice_status((string) $details['from_status']);
        }
        $to_status = '';
        if (array_key_exists('to_status', $details) && $details['to_status'] !== null) {
            $to_status = $this->normalize_invoice_status((string) $details['to_status']);
        }
        $amount_delta = '';
        if (array_key_exists('amount_delta', $details) && $details['amount_delta'] !== null && $details['amount_delta'] !== '') {
            $amount_delta = number_format(round((float) $details['amount_delta'], 2), 2, '.', '');
        }
        $user_id = (int) ($details['user_id'] ?? get_current_user_id());
        $note = sanitize_textarea_field((string) ($details['note'] ?? ''));
        if (strlen($note) > 60000) {
            $note = substr($note, 0, 60000);
        }

        global $wpdb;
        $table = $this->get_invoice_audit_log_table();
        $sql = $wpdb->prepare(
            "INSERT INTO {$table}
            (invoice_id, school_id, action, from_status, to_status, amount_delta, user_id, note, created_at)
            VALUES
            (%d, %d, %s, NULLIF(%s, ''), NULLIF(%s, ''), NULLIF(%s, ''), NULLIF(%d, 0), NULLIF(%s, ''), %s)",
            $invoice_id,
            $school_id,
            $action,
            $from_status,
            $to_status,
            $amount_delta,
            $user_id,
            $note,
            current_time('mysql')
        );
        $inserted = $wpdb->query($sql);
        if ($inserted === false) {
            return 0;
        }
        return (int) $wpdb->insert_id;
    }

    private function get_invoice_audit_entries($invoice_id, $limit = 20) {
        $invoice_id = (int) $invoice_id;
        if ($invoice_id < 1) {
            return [];
        }
        $limit = max(1, min(200, (int) $limit));
        global $wpdb;
        $table = $this->get_invoice_audit_log_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE invoice_id = %d
             ORDER BY id DESC
             LIMIT %d",
            $invoice_id,
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function get_school_partner_tier_definitions() {
        return [
            'standard' => ['min' => 0, 'discount' => 0.00, 'rank' => 0],
            'bronze' => ['min' => 100, 'discount' => 1.00, 'rank' => 1],
            'silver' => ['min' => 300, 'discount' => 2.00, 'rank' => 2],
            'gold' => ['min' => 700, 'discount' => 3.00, 'rank' => 3],
            'elite' => ['min' => 1500, 'discount' => 5.00, 'rank' => 4],
        ];
    }

    private function normalize_school_partner_tier($tier) {
        $tier = sanitize_key((string) $tier);
        $definitions = $this->get_school_partner_tier_definitions();
        if (!isset($definitions[$tier])) {
            return 'standard';
        }
        return $tier;
    }

    private function get_school_partner_tier_rank($tier) {
        $tier = $this->normalize_school_partner_tier($tier);
        $definitions = $this->get_school_partner_tier_definitions();
        return (int) ($definitions[$tier]['rank'] ?? 0);
    }

    private function get_school_partner_tier_for_credits($credits) {
        $credits = max(0, (int) $credits);
        if ($credits >= 1500) {
            return 'elite';
        }
        if ($credits >= 700) {
            return 'gold';
        }
        if ($credits >= 300) {
            return 'silver';
        }
        if ($credits >= 100) {
            return 'bronze';
        }
        return 'standard';
    }

    private function get_school_partner_discount_percent_for_tier($tier) {
        $tier = $this->normalize_school_partner_tier($tier);
        $definitions = $this->get_school_partner_tier_definitions();
        return round((float) ($definitions[$tier]['discount'] ?? 0.00), 2);
    }

    private function get_school_partner_record($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return [];
        }
        global $wpdb;
        $table = $this->get_school_partner_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE school_id = %d LIMIT 1",
            $school_id
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function resolve_cmn_academic_year_context($reference_date = 'now') {
        $raw_reference = trim((string) $reference_date);
        if ($raw_reference === '') {
            $raw_reference = 'now';
        }
        $tz = wp_timezone();
        try {
            if ($raw_reference === 'now') {
                $reference = function_exists('cmn_now')
                    ? cmn_now()->setTimezone($tz)
                    : new DateTimeImmutable('now', $tz);
            } else {
                $reference = new DateTimeImmutable($raw_reference, $tz);
            }
        } catch (Throwable $e) {
            $reference = function_exists('cmn_now')
                ? cmn_now()->setTimezone($tz)
                : new DateTimeImmutable('now', $tz);
        }
        $reference = $reference->setTimezone($tz);
        $reference_date_label = $reference->format('Y-m-d');
        $year = (int) $reference->format('Y');
        $month = (int) $reference->format('n');

        /*
         * CMN academic year rules for rewards:
         * - Aug maps to the upcoming academic year label.
         * - Sep-Dec maps to current->next.
         * - Jan-Jul maps to previous->current.
         */
        $start_year = $month >= 8 ? $year : ($year - 1);
        $end_year = $start_year + 1;

        return [
            'reference_date' => $reference_date_label,
            'start_year' => $start_year,
            'end_year' => $end_year,
            'label' => sprintf('%04d-%04d', $start_year, $end_year),
            'start_date' => sprintf('%04d-09-01', $start_year),
            'end_date' => sprintf('%04d-07-31', $end_year),
            'is_august' => $month === 8,
            'month' => $month,
            'year' => $year,
        ];
    }

    public function get_academic_year_label($reference_date = 'now') {
        $context = $this->resolve_cmn_academic_year_context($reference_date);
        return (string) ($context['label'] ?? '');
    }

    private function get_school_partner_academic_year_context($reference_date = '') {
        $reference_date = $this->normalize_invoice_date((string) $reference_date);
        if ($reference_date === '') {
            $reference_date = function_exists('cmn_today_ymd') ? cmn_today_ymd() : current_time('Y-m-d');
        }
        $reference_ts = strtotime($reference_date);
        if ($reference_ts === false) {
            $reference_date = function_exists('cmn_today_ymd') ? cmn_today_ymd() : current_time('Y-m-d');
            $reference_ts = strtotime($reference_date);
        }
        $year = (int) date('Y', $reference_ts);
        $month = (int) date('n', $reference_ts);
        $start_year = $month >= 9 ? $year : ($year - 1);
        $start_date = sprintf('%04d-09-01', $start_year);
        $end_date = sprintf('%04d-07-31', ($start_year + 1));
        if ($month >= 9) {
            $months_elapsed = $month - 8;
        } elseif ($month <= 7) {
            $months_elapsed = $month + 4;
        } else {
            $months_elapsed = 11;
        }
        $months_elapsed = max(0, min(11, (int) $months_elapsed));

        return [
            'reference_date' => $reference_date,
            'start_year' => $start_year,
            'label' => sprintf('%04d-%04d', $start_year, ($start_year + 1)),
            'start_date' => $start_date,
            'end_date' => $end_date,
            'months_elapsed' => $months_elapsed,
        ];
    }

    public function recalculate_school_partner_savings($school_id, $context = []) {
        $school_id = (int) $school_id;
        $context = is_array($context) ? $context : [];
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return new WP_Error('cmn_school_partner_invalid_school', 'Invalid school for partner savings.');
        }

        $partner = $this->get_or_create_school_partner($school_id);
        if (is_wp_error($partner)) {
            return $partner;
        }

        $academic_year = $this->get_school_partner_academic_year_context((string) ($context['reference_date'] ?? ''));
        $academic_start = (string) ($academic_year['start_date'] ?? '');
        $academic_end = (string) ($academic_year['end_date'] ?? '');

        global $wpdb;
        $adjustments_table = $this->get_invoice_adjustments_table();
        $invoices_table = $this->get_invoices_table();
        $sums = $wpdb->get_row($wpdb->prepare(
            "SELECT
                COALESCE(SUM(CASE WHEN adj.amount < 0 THEN ABS(adj.amount) ELSE 0 END), 0) AS lifetime_savings,
                COALESCE(SUM(CASE
                    WHEN adj.amount < 0
                         AND inv.period_start >= %s
                         AND inv.period_start <= %s
                    THEN ABS(adj.amount)
                    ELSE 0
                END), 0) AS academic_year_savings
            FROM {$adjustments_table} adj
            INNER JOIN {$invoices_table} inv ON inv.id = adj.invoice_id
            WHERE inv.school_id = %d
              AND adj.type = %s
              AND inv.status <> %s",
            $academic_start,
            $academic_end,
            $school_id,
            'partner_credit',
            'void'
        ), ARRAY_A);

        $lifetime_savings = round(max(0, (float) ($sums['lifetime_savings'] ?? 0)), 2);
        $academic_year_savings = round(max(0, (float) ($sums['academic_year_savings'] ?? 0)), 2);
        $now = current_time('mysql');
        $table = $this->get_school_partner_table();
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET lifetime_savings = %f,
                 academic_year_savings = %f,
                 academic_year_start = %s,
                 savings_updated_at = %s,
                 updated_at = %s
             WHERE school_id = %d",
            $lifetime_savings,
            $academic_year_savings,
            $academic_start,
            $now,
            $now,
            $school_id
        ));
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_savings_update_failed', 'Unable to update partner savings.');
        }

        $partner = $this->get_school_partner_record($school_id);
        return [
            'school_id' => $school_id,
            'lifetime_savings' => $lifetime_savings,
            'academic_year_savings' => $academic_year_savings,
            'academic_year_start' => $academic_start,
            'academic_year_end' => $academic_end,
            'academic_year_label' => (string) ($academic_year['label'] ?? ''),
            'partner' => $partner,
        ];
    }

    private function calculate_school_partner_projected_academic_year_savings($academic_year_savings, $academic_year_context = []) {
        $academic_year_savings = round(max(0, (float) $academic_year_savings), 2);
        $months_elapsed = max(0, min(11, (int) ($academic_year_context['months_elapsed'] ?? 0)));
        if ($months_elapsed < 2) {
            return [
                'projected' => 0.00,
                'status' => 'insufficient_data',
                'months_elapsed' => $months_elapsed,
            ];
        }

        $projected = round(($academic_year_savings / $months_elapsed) * 11, 2);
        return [
            'projected' => $projected,
            'status' => 'ok',
            'months_elapsed' => $months_elapsed,
        ];
    }

    private function get_school_partner_programme_stats($school_id, $options = []) {
        $school_id = (int) $school_id;
        $options = is_array($options) ? $options : [];
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return new WP_Error('cmn_school_partner_invalid_school', 'Invalid school for partner stats.');
        }

        $reference_date = $this->normalize_invoice_date((string) ($options['reference_date'] ?? ''));
        if ($reference_date === '') {
            $reference_date = function_exists('cmn_today_ymd') ? cmn_today_ymd() : current_time('Y-m-d');
        }
        $refresh = !array_key_exists('refresh', $options) || !empty($options['refresh']);
        if ($refresh) {
            $savings_refresh = $this->recalculate_school_partner_savings($school_id, [
                'reference_date' => $reference_date,
                'source' => sanitize_key((string) ($options['source'] ?? 'partner_stats')),
            ]);
            if (is_wp_error($savings_refresh)) {
                return $savings_refresh;
            }
            $partner = is_array($savings_refresh['partner'] ?? null) ? (array) $savings_refresh['partner'] : [];
        } else {
            $partner = $this->get_or_create_school_partner($school_id);
            if (is_wp_error($partner)) {
                return $partner;
            }
        }

        $partner = is_array($partner) ? $partner : [];
        $academic_year = $this->get_school_partner_academic_year_context($reference_date);
        $lifetime_savings = round((float) ($partner['lifetime_savings'] ?? 0), 2);
        $academic_year_savings = round((float) ($partner['academic_year_savings'] ?? 0), 2);
        $projection = $this->calculate_school_partner_projected_academic_year_savings($academic_year_savings, $academic_year);

        return [
            'school_id' => $school_id,
            'tier' => (string) $this->normalize_school_partner_tier((string) ($partner['tier'] ?? 'standard')),
            'discount_percent' => round((float) ($partner['discount_percent'] ?? 0), 2),
            'lifetime_credits' => max(0, (int) ($partner['lifetime_credits'] ?? 0)),
            'lifetime_savings' => $lifetime_savings,
            'academic_year_savings' => $academic_year_savings,
            'projected_academic_year_savings' => round((float) ($projection['projected'] ?? 0), 2),
            'projection_status' => (string) ($projection['status'] ?? 'insufficient_data'),
            'academic_year_label' => (string) ($academic_year['label'] ?? ''),
            'academic_year_start' => (string) ($academic_year['start_date'] ?? ''),
            'academic_year_end' => (string) ($academic_year['end_date'] ?? ''),
            'months_elapsed' => (int) ($projection['months_elapsed'] ?? 0),
            'savings_updated_at' => sanitize_text_field((string) ($partner['savings_updated_at'] ?? '')),
        ];
    }

    public function get_or_create_school_partner($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return new WP_Error('cmn_school_partner_invalid_school', 'Invalid school for partner programme.');
        }
        $existing = $this->get_school_partner_record($school_id);
        if ($existing) {
            return $existing;
        }

        global $wpdb;
        $table = $this->get_school_partner_table();
        $now = current_time('mysql');
        $reference_date = function_exists('cmn_today_ymd') ? cmn_today_ymd() : current_time('Y-m-d');
        $academic_year = $this->get_school_partner_academic_year_context($reference_date);
        $academic_start = (string) ($academic_year['start_date'] ?? '');
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT INTO {$table}
            (school_id, lifetime_credits, tier, discount_percent, partner_since, lifetime_savings, academic_year_savings, academic_year_start, savings_updated_at, created_at, updated_at)
            VALUES
            (%d, %d, %s, %f, %s, %f, %f, %s, %s, %s, %s)",
            $school_id,
            0,
            'standard',
            0.00,
            $now,
            0.00,
            0.00,
            $academic_start,
            $now,
            $now,
            $now
        ));
        if ($inserted === false) {
            $existing = $this->get_school_partner_record($school_id);
            if ($existing) {
                return $existing;
            }
            return new WP_Error('cmn_school_partner_create_failed', 'Unable to create partner profile.');
        }
        return $this->get_school_partner_record($school_id);
    }

    public function recalculate_school_partner_tier($school_id) {
        $school_id = (int) $school_id;
        $row = $this->get_or_create_school_partner($school_id);
        if (is_wp_error($row)) {
            return $row;
        }

        $lifetime_credits = max(0, (int) ($row['lifetime_credits'] ?? 0));
        $current_tier = $this->normalize_school_partner_tier((string) ($row['tier'] ?? 'standard'));
        $calculated_tier = $this->get_school_partner_tier_for_credits($lifetime_credits);
        $final_tier = $this->get_school_partner_tier_rank($current_tier) > $this->get_school_partner_tier_rank($calculated_tier)
            ? $current_tier
            : $calculated_tier;
        $final_discount = $this->get_school_partner_discount_percent_for_tier($final_tier);
        $current_discount = round((float) ($row['discount_percent'] ?? 0.00), 2);
        $needs_update = ($lifetime_credits !== (int) ($row['lifetime_credits'] ?? 0))
            || ($final_tier !== $current_tier)
            || (abs($final_discount - $current_discount) > 0.0001);

        if ($needs_update) {
            global $wpdb;
            $table = $this->get_school_partner_table();
            $wpdb->query($wpdb->prepare(
                "UPDATE {$table}
                 SET lifetime_credits = %d,
                     tier = %s,
                     discount_percent = %f,
                     updated_at = %s
                 WHERE school_id = %d",
                $lifetime_credits,
                $final_tier,
                $final_discount,
                current_time('mysql'),
                $school_id
            ));
            if ($this->get_school_partner_tier_rank($final_tier) > $this->get_school_partner_tier_rank($current_tier)) {
                $this->add_audit_log('school_partner_tier_upgraded', 'school', (string) $school_id, [
                    'from_tier' => $current_tier,
                    'to_tier' => $final_tier,
                    'lifetime_credits' => $lifetime_credits,
                    'discount_percent' => $final_discount,
                ]);
            }
        }

        return $this->get_school_partner_record($school_id);
    }

    public function increment_school_partner_credits($school_id, $delta, $context = []) {
        $school_id = (int) $school_id;
        $delta = (int) $delta;
        $context = is_array($context) ? $context : [];
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return new WP_Error('cmn_school_partner_invalid_school', 'Invalid school for partner credits.');
        }
        if ($delta === 0) {
            return new WP_Error('cmn_school_partner_invalid_delta', 'Credit delta cannot be zero.');
        }
        if ($delta < 0) {
            return new WP_Error('cmn_school_partner_negative_delta', 'Lifetime credits cannot be reduced.');
        }

        $partner = $this->get_or_create_school_partner($school_id);
        if (is_wp_error($partner)) {
            return $partner;
        }

        $event_type = sanitize_key((string) ($context['event_type'] ?? 'credit_awarded'));
        if ($event_type === '') {
            $event_type = 'credit_awarded';
        }
        $booking_id = (int) ($context['booking_id'] ?? 0);
        $shift_date = $this->normalize_invoice_date((string) ($context['shift_date'] ?? ''));

        if ($booking_id > 0 && $shift_date !== '') {
            global $wpdb;
            $events_table = $this->get_school_partner_events_table();
            $event_inserted = $wpdb->query($wpdb->prepare(
                "INSERT IGNORE INTO {$events_table}
                (school_id, booking_id, shift_date, event_type, delta, created_at)
                VALUES
                (%d, %d, %s, %s, %d, %s)",
                $school_id,
                $booking_id,
                $shift_date,
                $event_type,
                $delta,
                current_time('mysql')
            ));
            if ($event_inserted === false) {
                return new WP_Error('cmn_school_partner_event_insert_failed', 'Unable to log partner credit event.');
            }
            if ((int) $event_inserted === 0) {
                return [
                    'school_id' => $school_id,
                    'incremented' => false,
                    'duplicate' => true,
                    'delta' => 0,
                    'partner' => $partner,
                ];
            }
        }

        global $wpdb;
        $table = $this->get_school_partner_table();
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET lifetime_credits = GREATEST(0, lifetime_credits + %d),
                 updated_at = %s
             WHERE school_id = %d",
            $delta,
            current_time('mysql'),
            $school_id
        ));
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_increment_failed', 'Unable to update partner credits.');
        }

        $recalculated = $this->recalculate_school_partner_tier($school_id);
        if (is_wp_error($recalculated)) {
            return $recalculated;
        }
        $this->reconcile_single_school_list_visibility($school_id, false, (int) get_current_user_id(), 'partner_credit_increment');
        $this->add_audit_log('school_partner_credit_incremented', 'school', (string) $school_id, [
            'delta' => $delta,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'event_type' => $event_type,
            'lifetime_credits' => (int) ($recalculated['lifetime_credits'] ?? 0),
            'tier' => (string) ($recalculated['tier'] ?? 'standard'),
            'discount_percent' => round((float) ($recalculated['discount_percent'] ?? 0), 2),
            'source' => sanitize_key((string) ($context['source'] ?? '')),
        ]);

        return [
            'school_id' => $school_id,
            'incremented' => true,
            'duplicate' => false,
            'delta' => $delta,
            'partner' => $recalculated,
        ];
    }

    private function award_school_partner_credit_for_day($school_id, $booking_id, $shift_date, $context = []) {
        $school_id = (int) $school_id;
        $booking_id = (int) $booking_id;
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $context = is_array($context) ? $context : [];
        if ($school_id < 1) {
            return new WP_Error('cmn_school_partner_missing_school', 'Missing school id for partner credit award.');
        }
        if ($booking_id < 1 || $shift_date === '') {
            return new WP_Error('cmn_school_partner_invalid_day', 'Invalid booking day context for partner credit award.');
        }
        $context['event_type'] = 'credit_awarded';
        $context['booking_id'] = $booking_id;
        $context['shift_date'] = $shift_date;
        $context['source'] = sanitize_key((string) ($context['source'] ?? ''));
        return $this->increment_school_partner_credits($school_id, 1, $context);
    }

    private function award_school_partner_credits_for_day_rows($day_rows, $context = []) {
        $summary = [
            'processed' => 0,
            'awarded' => 0,
            'duplicates' => 0,
            'errors' => 0,
        ];
        foreach ((array) $day_rows as $day_row) {
            $school_id = (int) ($day_row['school_id'] ?? 0);
            $booking_id = (int) ($day_row['booking_id'] ?? 0);
            $shift_date = (string) ($day_row['shift_date'] ?? '');
            $summary['processed']++;
            $result = $this->award_school_partner_credit_for_day($school_id, $booking_id, $shift_date, $context);
            if (is_wp_error($result)) {
                $summary['errors']++;
                $this->add_audit_log('school_partner_credit_award_failed', 'booking', (string) $booking_id, [
                    'school_id' => $school_id,
                    'shift_date' => $shift_date,
                    'message' => $result->get_error_message(),
                    'source' => sanitize_key((string) ($context['source'] ?? '')),
                ]);
                continue;
            }
            if (!empty($result['duplicate'])) {
                $summary['duplicates']++;
            }
            if (!empty($result['incremented'])) {
                $summary['awarded']++;
            }
        }
        return $summary;
    }

    private function maybe_award_school_partner_credits_for_booking($booking_id, $status = '') {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return 0;
        }
        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        if ($school_id < 1) {
            $this->add_audit_log('school_partner_credit_skipped_missing_school', 'booking', (string) $booking_id, [
                'reason' => 'missing_school_id',
            ]);
            return 0;
        }
        if (get_post_type($school_id) !== 'cmn_school') {
            $this->add_audit_log('school_partner_credit_skipped_missing_school', 'booking', (string) $booking_id, [
                'reason' => 'invalid_school_id',
                'school_id' => $school_id,
            ]);
            return 0;
        }
        $status = sanitize_key((string) ($status !== '' ? $status : get_post_meta($booking_id, 'cmn_status', true)));
        if (!$this->is_completed_payable_booking_status($status)) {
            return 0;
        }
        $start_date = $this->normalize_booking_invoice_date_value((string) get_post_meta($booking_id, 'cmn_start_date', true));
        if ($start_date === '') {
            $start_date = $this->normalize_booking_invoice_date_value((string) get_post_meta($booking_id, 'cmn_date', true));
        }
        if ($start_date === '') {
            return 0;
        }
        $end_date = $this->normalize_booking_invoice_date_value((string) get_post_meta($booking_id, 'cmn_end_date', true));
        if ($end_date === '') {
            $end_date = $start_date;
        }
        if (strtotime($end_date) < strtotime($start_date)) {
            $end_date = $start_date;
        }
        $shift_dates = $this->expand_booking_dates_for_period(
            $start_date,
            $end_date,
            $start_date,
            $end_date,
            current_time('Y-m-d')
        );
        if (!$shift_dates) {
            return 0;
        }
        $awarded = 0;
        foreach ($shift_dates as $shift_date) {
            $credit_result = $this->award_school_partner_credit_for_day($school_id, $booking_id, $shift_date, [
                'source' => 'booking_status_update',
                'status' => $status,
            ]);
            if (!is_wp_error($credit_result) && !empty($credit_result['incremented'])) {
                $awarded++;
            }
        }
        return $awarded;
    }

    private function is_candidate_rewards_august_shift_date($shift_date) {
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        if ($shift_date === '') {
            return false;
        }
        $shift_ts = strtotime($shift_date);
        if ($shift_ts === false) {
            return false;
        }
        return ((int) date('n', $shift_ts)) === 8;
    }

    private function award_candidate_rewards_for_day($candidate_id, $booking_id, $shift_date, $context = []) {
        $candidate_id = (int) $candidate_id;
        $booking_id = (int) $booking_id;
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $context = is_array($context) ? $context : [];
        $created_by_user_id = max(0, (int) ($context['created_by_user_id'] ?? get_current_user_id()));

        if ($candidate_id < 1) {
            return new WP_Error('cmn_candidate_rewards_missing_candidate', 'Missing candidate id for rewards shift completion.');
        }
        if ($booking_id < 1 || $shift_date === '') {
            return new WP_Error('cmn_candidate_rewards_invalid_day', 'Invalid booking day context for candidate rewards.');
        }
        if (get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Invalid candidate for rewards shift completion.');
        }
        if ($this->is_candidate_rewards_august_shift_date($shift_date)) {
            $this->add_audit_log('candidate_rewards_shift_skipped_august', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'source' => sanitize_key((string) ($context['source'] ?? 'completed_payable_hook')),
            ]);
            return [
                'candidate_id' => $candidate_id,
                'booking_id' => $booking_id,
                'shift_date' => $shift_date,
                'incremented' => false,
                'duplicate' => false,
                'paused' => false,
                'august' => true,
            ];
        }

        $academic_year = function_exists('cmn_get_academic_year_label')
            ? (string) cmn_get_academic_year_label($shift_date)
            : (string) $this->get_academic_year_label($shift_date);
        $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($rewards_row)) {
            return $rewards_row;
        }

        $is_paused = !empty($rewards_row['rewards_paused']) && ((int) $rewards_row['rewards_paused']) === 1;
        $delta_cycle = $is_paused ? 0 : 1;
        $event_insert = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'event_type' => 'shift_completed',
            'delta_cycle' => $delta_cycle,
            'delta_year_total' => 1,
            'meta' => [
                'source' => 'completed_payable_hook',
                'status' => sanitize_key((string) ($context['status'] ?? '')),
                'paused' => $is_paused,
            ],
            'created_by_user_id' => $created_by_user_id,
        ]);
        if (is_wp_error($event_insert)) {
            return $event_insert;
        }
        if (empty($event_insert['inserted'])) {
            return [
                'candidate_id' => $candidate_id,
                'booking_id' => $booking_id,
                'shift_date' => $shift_date,
                'incremented' => false,
                'duplicate' => true,
                'paused' => $is_paused,
                'august' => false,
            ];
        }

        global $wpdb;
        $table = $this->get_candidate_rewards_table();
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET shift_cycle_count = shift_cycle_count + %d,
                 academic_year_shift_total = GREATEST(0, academic_year_shift_total + 1),
                 updated_at = %s
             WHERE candidate_id = %d
               AND academic_year = %s",
            $delta_cycle,
            current_time('mysql'),
            $candidate_id,
            $academic_year
        ));
        if ($updated === false) {
            return new WP_Error('cmn_candidate_rewards_increment_failed', 'Unable to apply candidate rewards shift increment.');
        }

        $updated_rewards_row = $this->get_candidate_rewards_record($candidate_id, $academic_year);
        if (!$updated_rewards_row) {
            return new WP_Error('cmn_candidate_rewards_increment_lookup_failed', 'Unable to load candidate rewards row after shift increment.');
        }

        $tier_progression = $this->maybe_apply_candidate_rewards_tier_progression(
            $candidate_id,
            $booking_id,
            $shift_date,
            $academic_year,
            $updated_rewards_row,
            [
                'source' => sanitize_key((string) ($context['source'] ?? 'completed_payable_hook')),
                'created_by_user_id' => $created_by_user_id,
            ]
        );
        if (is_wp_error($tier_progression)) {
            return $tier_progression;
        }
        if (!empty($tier_progression['row']) && is_array($tier_progression['row'])) {
            $updated_rewards_row = $tier_progression['row'];
        }

        $probation_result = [
            'incremented' => false,
            'duplicate' => false,
            'reinstated' => false,
            'probation_count_after' => max(0, (int) ($updated_rewards_row['probation_consecutive_shifts'] ?? 0)),
            'event_id' => 0,
            'reinstated_event_id' => 0,
        ];
        if ($is_paused) {
            $probation_result = $this->maybe_increment_candidate_probation_shift(
                $candidate_id,
                $booking_id,
                $shift_date,
                $academic_year,
                $updated_rewards_row,
                [
                    'source' => sanitize_key((string) ($context['source'] ?? 'completed_payable_hook')),
                    'status' => sanitize_key((string) ($context['status'] ?? '')),
                    'created_by_user_id' => $created_by_user_id,
                ]
            );
            if (is_wp_error($probation_result)) {
                return $probation_result;
            }
            $reloaded_rewards_row = $this->get_candidate_rewards_record($candidate_id, $academic_year);
            if ($reloaded_rewards_row) {
                $updated_rewards_row = $reloaded_rewards_row;
            }
        }

        $bonus_result = [
            'triggered' => false,
            'duplicate' => false,
            'skipped' => true,
            'reason' => 'cycle_not_reached',
            'event_id' => 0,
            'cycle_reset_event_id' => 0,
            'payout_id' => 0,
            'cycle_number' => 0,
            'cycle_target' => max(1, (int) apply_filters('cmn_candidate_rewards_cycle_target', self::CANDIDATE_REWARDS_CYCLE_TARGET)),
            'bonus_amount' => 0.00,
            'average_daily_pay' => 0.00,
            'total_gross_pay_cycle' => 0.00,
        ];
        $bonus_result_raw = $this->maybe_trigger_candidate_rewards_cycle_bonus(
            $candidate_id,
            $booking_id,
            $shift_date,
            $academic_year,
            $updated_rewards_row,
            [
                'source' => sanitize_key((string) ($context['source'] ?? 'completed_payable_hook')),
                'created_by_user_id' => $created_by_user_id,
            ]
        );
        if (is_wp_error($bonus_result_raw)) {
            $bonus_result['reason'] = sanitize_key((string) $bonus_result_raw->get_error_code());
            $bonus_result['error_message'] = $bonus_result_raw->get_error_message();
            $this->add_audit_log('candidate_rewards_bonus_trigger_error', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'reason' => $bonus_result['reason'],
                'message' => $bonus_result['error_message'],
            ]);
        } elseif (is_array($bonus_result_raw)) {
            $bonus_result = array_merge($bonus_result, $bonus_result_raw);
            if (!empty($bonus_result_raw['row']) && is_array($bonus_result_raw['row'])) {
                $updated_rewards_row = $bonus_result_raw['row'];
            }
        }

        $this->add_audit_log('candidate_rewards_shift_completed', 'booking', (string) $booking_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'academic_year' => $academic_year,
            'delta_cycle' => $delta_cycle,
            'delta_year_total' => 1,
            'paused' => $is_paused ? 1 : 0,
            'conduct_status' => sanitize_key((string) ($updated_rewards_row['conduct_status'] ?? 'clear')),
            'tier' => sanitize_key((string) ($updated_rewards_row['tier'] ?? 'standard')),
            'multiplier' => round((float) ($updated_rewards_row['multiplier'] ?? 1.00), 2),
            'tier_updated' => !empty($tier_progression['updated']) ? 1 : 0,
            'probation_count_after' => max(0, (int) ($updated_rewards_row['probation_consecutive_shifts'] ?? 0)),
            'probation_incremented' => !empty($probation_result['incremented']) ? 1 : 0,
            'rewards_reinstated' => !empty($probation_result['reinstated']) ? 1 : 0,
            'bonus_triggered' => !empty($bonus_result['triggered']) ? 1 : 0,
            'bonus_duplicate' => !empty($bonus_result['duplicate']) ? 1 : 0,
            'bonus_reason' => sanitize_key((string) ($bonus_result['reason'] ?? '')),
            'bonus_event_id' => (int) ($bonus_result['event_id'] ?? 0),
            'bonus_cycle_reset_event_id' => (int) ($bonus_result['cycle_reset_event_id'] ?? 0),
            'bonus_payout_id' => (int) ($bonus_result['payout_id'] ?? 0),
            'bonus_amount' => round((float) ($bonus_result['bonus_amount'] ?? 0), 2),
            'source' => sanitize_key((string) ($context['source'] ?? 'completed_payable_hook')),
        ]);

        return [
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'incremented' => true,
            'duplicate' => false,
            'paused' => $is_paused,
            'tier' => sanitize_key((string) ($updated_rewards_row['tier'] ?? 'standard')),
            'multiplier' => round((float) ($updated_rewards_row['multiplier'] ?? 1.00), 2),
            'tier_updated' => !empty($tier_progression['updated']),
            'probation_incremented' => !empty($probation_result['incremented']),
            'probation_duplicate' => !empty($probation_result['duplicate']),
            'probation_count_after' => max(0, (int) ($updated_rewards_row['probation_consecutive_shifts'] ?? 0)),
            'rewards_reinstated' => !empty($probation_result['reinstated']),
            'bonus_triggered' => !empty($bonus_result['triggered']),
            'bonus_duplicate' => !empty($bonus_result['duplicate']),
            'bonus_reason' => sanitize_key((string) ($bonus_result['reason'] ?? '')),
            'bonus_event_id' => (int) ($bonus_result['event_id'] ?? 0),
            'bonus_cycle_reset_event_id' => (int) ($bonus_result['cycle_reset_event_id'] ?? 0),
            'bonus_payout_id' => (int) ($bonus_result['payout_id'] ?? 0),
            'bonus_cycle_number' => (int) ($bonus_result['cycle_number'] ?? 0),
            'bonus_cycle_target' => (int) ($bonus_result['cycle_target'] ?? 0),
            'bonus_amount' => round((float) ($bonus_result['bonus_amount'] ?? 0), 2),
            'bonus_average_daily_pay' => round((float) ($bonus_result['average_daily_pay'] ?? 0), 2),
            'bonus_total_gross_pay_cycle' => round((float) ($bonus_result['total_gross_pay_cycle'] ?? 0), 2),
            'august' => false,
        ];
    }

    private function get_rewards_attended_completion_statuses() {
        return ['completed', 'completed_attended'];
    }

    private function get_rewards_credit_cancelled_booking_statuses() {
        return ['declined', 'cancelled', 'candidate_declined', 'expired', 'no_show', 'noshow'];
    }

    private function is_rewards_attended_completion_status($status) {
        $status = sanitize_key((string) $status);
        return in_array($status, $this->get_rewards_attended_completion_statuses(), true);
    }

    private function is_rewards_credit_cancelled_status($status) {
        $status = sanitize_key((string) $status);
        return in_array($status, $this->get_rewards_credit_cancelled_booking_statuses(), true);
    }

    private function parse_rewards_cancelled_shift_dates($raw_value, array &$date_map) {
        if (is_array($raw_value)) {
            foreach ($raw_value as $key => $nested) {
                $key_date = $this->normalize_invoice_date((string) $key);
                if ($key_date !== '') {
                    $date_map[$key_date] = true;
                }
                $this->parse_rewards_cancelled_shift_dates($nested, $date_map);
            }
            return;
        }
        if (is_object($raw_value)) {
            $this->parse_rewards_cancelled_shift_dates((array) $raw_value, $date_map);
            return;
        }
        if (!is_string($raw_value)) {
            return;
        }
        $raw_value = trim($raw_value);
        if ($raw_value === '') {
            return;
        }

        $decoded = json_decode($raw_value, true);
        if (json_last_error() === JSON_ERROR_NONE && (is_array($decoded) || is_object($decoded))) {
            $this->parse_rewards_cancelled_shift_dates($decoded, $date_map);
            return;
        }

        $tokens = preg_split('/[\s,;|]+/', $raw_value) ?: [];
        foreach ($tokens as $token) {
            $date = $this->normalize_invoice_date((string) $token);
            if ($date !== '') {
                $date_map[$date] = true;
            }
        }
    }

    private function get_rewards_cancelled_shift_dates_for_booking($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return [];
        }
        $map = [];
        $meta_keys = ['cmn_cancelled_dates', 'cmn_cancelled_days', 'cmn_cancelled_shift_dates', 'cmn_cancelled_date'];
        foreach ($meta_keys as $meta_key) {
            $value = get_post_meta($booking_id, $meta_key, true);
            $this->parse_rewards_cancelled_shift_dates($value, $map);
        }
        return $map;
    }

    private function get_rewards_booking_shift_dates($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return [];
        }
        $window = $this->get_booking_shift_date_window($booking_id);
        $start_date = (string) ($window['start_date'] ?? '');
        $end_date = (string) ($window['end_date'] ?? '');
        if ($start_date === '' || $end_date === '') {
            return [];
        }
        $today = current_time('Y-m-d');
        $dates = $this->expand_booking_dates_for_period(
            $start_date,
            $end_date,
            $start_date,
            $end_date,
            $today
        );
        $normalized = [];
        foreach ((array) $dates as $date_value) {
            $date_value = $this->normalize_invoice_date((string) $date_value);
            if ($date_value !== '') {
                $normalized[$date_value] = $date_value;
            }
        }
        return array_values($normalized);
    }

    private function resolve_rewards_actor_user_id($actor_user_id = null) {
        if ($actor_user_id === null) {
            $actor_user_id = get_current_user_id();
        }
        return max(0, (int) $actor_user_id);
    }

    private function enforce_rewards_mutation_permission($actor_user_id, $ability, array $context = []) {
        $actor_user_id = max(0, (int) $actor_user_id);
        $ability = trim((string) $ability);
        if ($ability === '') {
            $ability = 'rewards.mutate_any';
        }
        if ($actor_user_id < 1) {
            return true;
        }

        $current_user_id = (int) get_current_user_id();
        if ($current_user_id > 0 && $current_user_id === $actor_user_id && function_exists('cmn_require_ability')) {
            $check = cmn_require_ability($ability, $context);
            if (is_wp_error($check)) {
                return $check;
            }
            return true;
        }

        if (function_exists('cmn_can') && !cmn_can($actor_user_id, $ability, $context)) {
            if (function_exists('cmn_log_permission_denied_event')) {
                cmn_log_permission_denied_event($actor_user_id, $ability, $context, 'unknown');
            }
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }
        return true;
    }

    private function get_candidate_conduct_allowed_event_types() {
        return ['no_show', 'appeal_opened', 'appeal_approved', 'appeal_rejected', 'yellow_card', 'red_card', 'meeting_required', 'termination'];
    }

    private function normalize_candidate_conduct_event_type($event_type) {
        $event_type = sanitize_key((string) $event_type);
        if (!in_array($event_type, $this->get_candidate_conduct_allowed_event_types(), true)) {
            return '';
        }
        return $event_type;
    }

    private function resolve_candidate_id_for_conduct_user($candidate_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return 0;
        }

        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        if ($candidate_id > 0 && get_post_type($candidate_id) === 'cmn_candidate') {
            return $candidate_id;
        }

        $candidates = get_posts([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish', 'pending', 'draft', 'private'],
            'posts_per_page' => 1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_user_id',
                    'value' => (string) $candidate_user_id,
                ],
            ],
        ]);
        if ($candidates && !empty($candidates[0])) {
            return (int) $candidates[0];
        }

        return 0;
    }

    private function resolve_no_show_shift_date_for_booking($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return '';
        }

        $shift_date = $this->normalize_invoice_date((string) $this->get_booking_service_date($booking_id));
        if ($shift_date !== '') {
            return $shift_date;
        }

        $window = $this->get_booking_shift_date_window($booking_id);
        $start_date = $this->normalize_invoice_date((string) ($window['start_date'] ?? ''));
        if ($start_date !== '') {
            return $start_date;
        }

        return '';
    }

    private function get_candidate_conduct_event_by_booking($candidate_user_id, $booking_id, $event_type, $status = 'active') {
        $candidate_user_id = (int) $candidate_user_id;
        $booking_id = (int) $booking_id;
        $event_type = $this->normalize_candidate_conduct_event_type($event_type);
        $status = sanitize_key((string) $status);
        if ($candidate_user_id < 1 || $booking_id < 1 || $event_type === '') {
            return [];
        }
        if ($status !== '' && !in_array($status, ['active', 'reversed'], true)) {
            $status = 'active';
        }

        global $wpdb;
        $table = $this->get_candidate_conduct_events_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }
        if ($status !== '') {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE candidate_user_id = %d
                   AND booking_id = %d
                   AND event_type = %s
                   AND status = %s
                 ORDER BY occurred_at DESC, id DESC
                 LIMIT 1",
                $candidate_user_id,
                $booking_id,
                $event_type,
                $status
            ), ARRAY_A);
        } else {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE candidate_user_id = %d
                   AND booking_id = %d
                   AND event_type = %s
                 ORDER BY occurred_at DESC, id DESC
                 LIMIT 1",
                $candidate_user_id,
                $booking_id,
                $event_type
            ), ARRAY_A);
        }
        return is_array($row) ? $row : [];
    }

    private function get_latest_active_no_show_datetime($candidate_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return '';
        }
        global $wpdb;
        $table = $this->get_candidate_conduct_events_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return '';
        }
        $occurred_at = (string) $wpdb->get_var($wpdb->prepare(
            "SELECT occurred_at
             FROM {$table}
             WHERE candidate_user_id = %d
               AND event_type = %s
               AND status = %s
             ORDER BY occurred_at DESC, id DESC
             LIMIT 1",
            $candidate_user_id,
            'no_show',
            'active'
        ));
        return $this->normalize_invoice_datetime($occurred_at);
    }

    private function insert_candidate_conduct_event($candidate_user_id, $booking_id, $event_type, $notes = '', $actor_user_id = 0, $occurred_at = '') {
        $candidate_user_id = (int) $candidate_user_id;
        $booking_id = (int) $booking_id;
        $event_type = $this->normalize_candidate_conduct_event_type($event_type);
        $notes = trim(sanitize_textarea_field((string) $notes));
        if (function_exists('mb_substr')) {
            $notes = mb_substr($notes, 0, 65535);
        } else {
            $notes = substr($notes, 0, 65535);
        }
        $actor_user_id = max(0, (int) $actor_user_id);
        $occurred_at = $this->normalize_invoice_datetime((string) $occurred_at);
        if ($occurred_at === '') {
            $occurred_at = current_time('mysql');
        }

        if ($candidate_user_id < 1 || $event_type === '') {
            return new WP_Error('cmn_conduct_invalid_event_input', 'Candidate and valid event type are required.');
        }

        global $wpdb;
        $table = $this->get_candidate_conduct_events_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return new WP_Error('cmn_conduct_table_missing', 'Candidate conduct table does not exist. Run schema migrations first.');
        }
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT INTO {$table}
            (candidate_user_id, booking_id, event_type, occurred_at, notes, actor_user_id, status, reversed_at, reversed_by_user_id)
            VALUES
            (%d, NULLIF(%d, 0), %s, %s, NULLIF(%s, ''), NULLIF(%d, 0), %s, NULL, NULL)",
            $candidate_user_id,
            max(0, $booking_id),
            $event_type,
            $occurred_at,
            $notes,
            $actor_user_id,
            'active'
        ));
        if ($inserted === false) {
            return new WP_Error('cmn_conduct_event_insert_failed', 'Unable to save candidate conduct event.');
        }

        return [
            'event_id' => (int) $wpdb->insert_id,
            'candidate_user_id' => $candidate_user_id,
            'booking_id' => $booking_id > 0 ? $booking_id : 0,
            'event_type' => $event_type,
            'occurred_at' => $occurred_at,
        ];
    }

    private function log_candidate_conduct_audit_event($candidate_user_id, $booking_id, $event_type, $actor_user_id = 0, array $metadata = []) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1 || !function_exists('cmn_audit_log_event')) {
            return;
        }

        $audit_metadata = is_array($metadata) ? $metadata : [];
        $audit_metadata['booking_id'] = max(0, (int) $booking_id);
        cmn_audit_log_event([
            'module' => 'rewards',
            'entity_type' => 'candidate',
            'entity_id' => $candidate_user_id,
            'event_type' => sanitize_key((string) $event_type),
            'event_ref' => $booking_id > 0 ? (string) ((int) $booking_id) : null,
            'actor_user_id' => max(0, (int) $actor_user_id),
            'metadata' => $audit_metadata,
        ]);
    }

    private function resolve_conduct_status_from_no_show_count($no_show_count) {
        $no_show_count = max(0, (int) $no_show_count);
        if ($no_show_count >= 3) {
            return 'terminated';
        }
        if ($no_show_count >= 1) {
            return 'yellow';
        }
        return 'clear';
    }

    private function update_candidate_rewards_conduct_state($candidate_id, $academic_year, $shift_delta, $no_show_count, $conduct_status, $last_no_show_at = '') {
        $candidate_id = (int) $candidate_id;
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year);
        $shift_delta = (int) $shift_delta;
        $no_show_count = max(0, (int) $no_show_count);
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) $conduct_status);
        $last_no_show_at = $this->normalize_invoice_datetime((string) $last_no_show_at);
        $rewards_paused = $no_show_count >= 1 ? 1 : 0;
        $review_required = $no_show_count >= 2 ? 1 : 0;

        if ($candidate_id < 1 || $academic_year === '') {
            return new WP_Error('cmn_conduct_rewards_state_invalid', 'Invalid rewards state context.');
        }

        global $wpdb;
        $table = $this->get_candidate_rewards_table();
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET shift_cycle_count = shift_cycle_count + %d,
                 academic_year_shift_total = academic_year_shift_total + %d,
                 no_show_count = %d,
                 conduct_status = %s,
                 rewards_paused = %d,
                 review_required = %d,
                 last_no_show_at = NULLIF(%s, ''),
                 updated_at = %s
             WHERE candidate_id = %d
               AND academic_year = %s",
            $shift_delta,
            $shift_delta,
            $no_show_count,
            $conduct_status,
            $rewards_paused,
            $review_required,
            $last_no_show_at,
            current_time('mysql'),
            $candidate_id,
            $academic_year
        ));
        if ($updated === false) {
            return new WP_Error('cmn_conduct_rewards_state_update_failed', 'Unable to update rewards state.');
        }

        return $this->get_candidate_rewards_record($candidate_id, $academic_year);
    }

    /*
     * Prompt 6 acceptance checks:
     * 1) Recording a no-show decrements rewards counters by 3 and can go negative.
     * 2) 1st no-show sets yellow, 2nd creates meeting_required, 3rd sets terminated.
     * 3) Duplicate active no-show for the same candidate+booking is blocked.
     */
    public function conduct_record_no_show($candidate_user_id, $booking_id, $notes, $actor_user_id = null) {
        $candidate_user_id = (int) $candidate_user_id;
        $booking_id = (int) $booking_id;
        $notes = sanitize_textarea_field((string) $notes);
        $actor_user_id = $this->resolve_rewards_actor_user_id($actor_user_id);

        $permission = $this->enforce_rewards_mutation_permission($actor_user_id, 'rewards.mutate_any', [
            'candidate_user_id' => $candidate_user_id,
            'booking_id' => $booking_id,
        ]);
        if (is_wp_error($permission)) {
            return $permission;
        }
        if ($candidate_user_id < 1 || $booking_id < 1) {
            return new WP_Error('cmn_conduct_invalid_input', 'Candidate and booking are required.');
        }
        if (get_post_type($booking_id) !== 'cmn_booking') {
            return new WP_Error('cmn_conduct_invalid_booking', 'Booking not found.');
        }

        $candidate_id = (int) $this->resolve_candidate_id_for_conduct_user($candidate_user_id);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_conduct_invalid_candidate', 'Candidate not found for conduct processing.');
        }

        $booking_candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($booking_candidate_id > 0 && $booking_candidate_id !== $candidate_id) {
            return new WP_Error('cmn_conduct_candidate_mismatch', 'Booking does not belong to the candidate.');
        }
        $booking_candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($booking_candidate_user_id > 0 && $booking_candidate_user_id !== $candidate_user_id) {
            return new WP_Error('cmn_conduct_candidate_user_mismatch', 'Candidate user does not match booking candidate.');
        }

        $existing = $this->get_candidate_conduct_event_by_booking($candidate_user_id, $booking_id, 'no_show', '');
        if ($existing) {
            return new WP_Error('cmn_conduct_duplicate_no_show', 'No-show already recorded for this booking.');
        }

        $shift_date = $this->resolve_no_show_shift_date_for_booking($booking_id);
        if ($shift_date === '') {
            return new WP_Error('cmn_conduct_missing_shift_date', 'Unable to determine booking day for no-show.');
        }

        $assessment = $this->assess_candidate_no_show_day($candidate_id, $booking_id, $shift_date);
        if (is_wp_error($assessment)) {
            return $assessment;
        }
        $shift_start_datetime = $this->get_booking_shift_start_datetime_for_day($booking_id, $shift_date);
        $chat_evidence = $this->get_booking_chat_evidence_before_shift_start($booking_id, $candidate_id, $shift_start_datetime);
        if (!empty($chat_evidence['checked']) && !empty($chat_evidence['candidate_message_before_start'])) {
            return new WP_Error('cmn_conduct_no_show_has_communication', 'No-show cannot be recorded because candidate communication exists for this booking-day.');
        }

        $no_show_event = $this->insert_candidate_conduct_event($candidate_user_id, $booking_id, 'no_show', $notes, $actor_user_id);
        if (is_wp_error($no_show_event)) {
            return $no_show_event;
        }

        $academic_year = function_exists('cmn_get_academic_year_label')
            ? (string) cmn_get_academic_year_label($shift_date)
            : (string) $this->get_academic_year_label($shift_date);
        $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($rewards_row)) {
            return $rewards_row;
        }

        $before_no_show_count = max(0, (int) ($rewards_row['no_show_count'] ?? 0));
        $after_no_show_count = $before_no_show_count + 1;
        $next_status = $this->resolve_conduct_status_from_no_show_count($after_no_show_count);
        $updated_rewards_row = $this->update_candidate_rewards_conduct_state(
            $candidate_id,
            $academic_year,
            -3,
            $after_no_show_count,
            $next_status,
            current_time('mysql')
        );
        if (is_wp_error($updated_rewards_row)) {
            return $updated_rewards_row;
        }
        $tier_sync = $this->rewards_apply_tier_if_needed($candidate_user_id, $academic_year, $actor_user_id);
        if (is_wp_error($tier_sync)) {
            $this->add_audit_log('candidate_rewards_tier_sync_failed_after_no_show', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'candidate_user_id' => $candidate_user_id,
                'academic_year' => $academic_year,
                'message' => $tier_sync->get_error_message(),
            ], $actor_user_id);
        } elseif (is_array($tier_sync['row'] ?? null) && !empty($tier_sync['row'])) {
            $updated_rewards_row = $tier_sync['row'];
        }

        $discipline_events = [
            'yellow_card_event_id' => 0,
            'meeting_required_event_id' => 0,
            'termination_event_id' => 0,
        ];
        if ($after_no_show_count === 1) {
            $yellow_event = $this->insert_candidate_conduct_event(
                $candidate_user_id,
                $booking_id,
                'yellow_card',
                'First no-show recorded. Yellow warning applied.',
                $actor_user_id
            );
            if (!is_wp_error($yellow_event)) {
                $discipline_events['yellow_card_event_id'] = (int) ($yellow_event['event_id'] ?? 0);
            }
        } elseif ($after_no_show_count === 2) {
            $meeting_event = $this->insert_candidate_conduct_event(
                $candidate_user_id,
                $booking_id,
                'meeting_required',
                'Second no-show recorded. Staff meeting required before next assignment.',
                $actor_user_id
            );
            if (!is_wp_error($meeting_event)) {
                $discipline_events['meeting_required_event_id'] = (int) ($meeting_event['event_id'] ?? 0);
            }
        } elseif ($after_no_show_count >= 3) {
            $termination_event = $this->insert_candidate_conduct_event(
                $candidate_user_id,
                $booking_id,
                'termination',
                'Third no-show recorded. Candidate rewards eligibility terminated.',
                $actor_user_id
            );
            if (!is_wp_error($termination_event)) {
                $discipline_events['termination_event_id'] = (int) ($termination_event['event_id'] ?? 0);
            }
        }

        $this->log_candidate_conduct_audit_event($candidate_user_id, $booking_id, 'no_show', $actor_user_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'conduct_event_id' => (int) ($no_show_event['event_id'] ?? 0),
            'notes' => $notes,
            'school_expected' => !empty($assessment['school_expected']) ? 1 : 0,
            'chat_checked' => !empty($chat_evidence['checked']) ? 1 : 0,
        ]);
        $this->log_candidate_conduct_audit_event($candidate_user_id, $booking_id, 'shift_debit', $actor_user_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'delta' => -3,
            'no_show_count_before' => $before_no_show_count,
            'no_show_count_after' => $after_no_show_count,
            'conduct_status' => $next_status,
            'academic_year' => $academic_year,
        ]);
        if ($discipline_events['yellow_card_event_id'] > 0) {
            $this->log_candidate_conduct_audit_event($candidate_user_id, $booking_id, 'yellow_card', $actor_user_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'event_id' => $discipline_events['yellow_card_event_id'],
                'no_show_count' => $after_no_show_count,
            ]);
        }
        if ($discipline_events['meeting_required_event_id'] > 0) {
            $this->log_candidate_conduct_audit_event($candidate_user_id, $booking_id, 'meeting_required', $actor_user_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'event_id' => $discipline_events['meeting_required_event_id'],
                'no_show_count' => $after_no_show_count,
            ]);
        }
        if ($discipline_events['termination_event_id'] > 0) {
            $this->log_candidate_conduct_audit_event($candidate_user_id, $booking_id, 'termination', $actor_user_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'event_id' => $discipline_events['termination_event_id'],
                'no_show_count' => $after_no_show_count,
            ]);
        }

        return [
            'candidate_user_id' => $candidate_user_id,
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'conduct_event_id' => (int) ($no_show_event['event_id'] ?? 0),
            'no_show_count' => $after_no_show_count,
            'conduct_status' => $this->normalize_candidate_rewards_conduct_status((string) ($updated_rewards_row['conduct_status'] ?? $next_status)),
            'shift_delta' => -3,
            'discipline_events' => $discipline_events,
            'terminated' => $after_no_show_count >= 3,
        ];
    }

    public function conduct_open_appeal($candidate_user_id, $booking_id, $message) {
        $candidate_user_id = (int) $candidate_user_id;
        $booking_id = (int) $booking_id;
        $message = sanitize_textarea_field((string) $message);
        $current_user_id = (int) get_current_user_id();

        $permission = function_exists('cmn_require_ability')
            ? cmn_require_ability('rewards.view_self', ['candidate_user_id' => $candidate_user_id, 'booking_id' => $booking_id])
            : (is_user_logged_in() ? true : new WP_Error('cmn_auth_required', 'Not authorised', ['status' => 401]));
        if (is_wp_error($permission)) {
            return $permission;
        }
        if ($candidate_user_id < 1 || $booking_id < 1) {
            return new WP_Error('cmn_conduct_appeal_invalid_input', 'Candidate and booking are required.');
        }
        if ($current_user_id < 1 || $current_user_id !== $candidate_user_id) {
            if (function_exists('cmn_log_permission_denied_event')) {
                $resolved_role = function_exists('cmn_role_from_user') ? (string) cmn_role_from_user($current_user_id) : 'candidate';
                cmn_log_permission_denied_event($current_user_id, 'rewards.view_self', [
                    'candidate_user_id' => $candidate_user_id,
                    'booking_id' => $booking_id,
                ], $resolved_role);
            }
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }
        if ($message === '') {
            return new WP_Error('cmn_conduct_appeal_message_required', 'Appeal message is required.');
        }
        if (get_post_type($booking_id) !== 'cmn_booking') {
            return new WP_Error('cmn_conduct_appeal_invalid_booking', 'Booking not found.');
        }

        $candidate_id = (int) $this->resolve_candidate_id_for_conduct_user($candidate_user_id);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_conduct_appeal_invalid_candidate', 'Candidate not found for appeal.');
        }
        $booking_candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($booking_candidate_id > 0 && $booking_candidate_id !== $candidate_id) {
            return new WP_Error('cmn_conduct_appeal_candidate_mismatch', 'Booking does not belong to candidate.');
        }

        $active_no_show = $this->get_candidate_conduct_event_by_booking($candidate_user_id, $booking_id, 'no_show', 'active');
        if (!$active_no_show) {
            return new WP_Error('cmn_conduct_appeal_no_no_show', 'No active no-show found for this booking.');
        }

        $appeal_event = $this->insert_candidate_conduct_event($candidate_user_id, $booking_id, 'appeal_opened', $message, $current_user_id);
        if (is_wp_error($appeal_event)) {
            return $appeal_event;
        }

        $this->log_candidate_conduct_audit_event($candidate_user_id, $booking_id, 'appeal_opened', $current_user_id, [
            'candidate_id' => $candidate_id,
            'message' => $message,
            'appeal_event_id' => (int) ($appeal_event['event_id'] ?? 0),
            'linked_no_show_event_id' => (int) ($active_no_show['id'] ?? 0),
        ]);

        return [
            'candidate_user_id' => $candidate_user_id,
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'appeal_event_id' => (int) ($appeal_event['event_id'] ?? 0),
            'opened' => true,
        ];
    }

    /*
     * Prompt 6 acceptance checks:
     * 1) Appeal approved reverses no-show penalty by +3 and decrements no_show_count floor 0.
     * 2) Appeal rejected only logs decision, with no rewards counter mutation.
     * 3) All actions are logged to cmn_audit_events with booking reference metadata.
     */
    public function conduct_resolve_appeal($candidate_user_id, $booking_id, $decision, $notes, $actor_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        $booking_id = (int) $booking_id;
        $decision = strtolower(trim((string) $decision));
        $notes = sanitize_textarea_field((string) $notes);
        $actor_user_id = $this->resolve_rewards_actor_user_id($actor_user_id);

        $permission = $this->enforce_rewards_mutation_permission($actor_user_id, 'rewards.mutate_any', [
            'candidate_user_id' => $candidate_user_id,
            'booking_id' => $booking_id,
        ]);
        if (is_wp_error($permission)) {
            return $permission;
        }
        if ($candidate_user_id < 1 || $booking_id < 1) {
            return new WP_Error('cmn_conduct_appeal_resolve_invalid_input', 'Candidate and booking are required.');
        }
        if ($actor_user_id < 1) {
            return new WP_Error('cmn_conduct_appeal_resolve_actor_required', 'A staff/admin actor is required.');
        }
        if ($decision === 'approve') {
            $decision = 'approved';
        } elseif ($decision === 'reject' || $decision === 'denied') {
            $decision = 'rejected';
        }
        if (!in_array($decision, ['approved', 'rejected'], true)) {
            return new WP_Error('cmn_conduct_appeal_resolve_invalid_decision', 'Decision must be approved or rejected.');
        }
        if ($notes === '') {
            return new WP_Error('cmn_conduct_appeal_resolve_notes_required', 'Appeal decision notes are required.');
        }

        $candidate_id = (int) $this->resolve_candidate_id_for_conduct_user($candidate_user_id);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_conduct_appeal_resolve_invalid_candidate', 'Candidate not found for appeal resolution.');
        }
        if (get_post_type($booking_id) !== 'cmn_booking') {
            return new WP_Error('cmn_conduct_appeal_resolve_invalid_booking', 'Booking not found.');
        }
        $booking_candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($booking_candidate_id > 0 && $booking_candidate_id !== $candidate_id) {
            return new WP_Error('cmn_conduct_appeal_resolve_candidate_mismatch', 'Booking does not belong to candidate.');
        }

        $active_no_show = $this->get_candidate_conduct_event_by_booking($candidate_user_id, $booking_id, 'no_show', 'active');
        if (!$active_no_show) {
            return new WP_Error('cmn_conduct_appeal_resolve_no_active_no_show', 'No active no-show found for this booking.');
        }

        if ($decision === 'rejected') {
            $appeal_rejected = $this->insert_candidate_conduct_event($candidate_user_id, $booking_id, 'appeal_rejected', $notes, $actor_user_id);
            if (is_wp_error($appeal_rejected)) {
                return $appeal_rejected;
            }
            $this->log_candidate_conduct_audit_event($candidate_user_id, $booking_id, 'appeal_rejected', $actor_user_id, [
                'candidate_id' => $candidate_id,
                'appeal_event_id' => (int) ($appeal_rejected['event_id'] ?? 0),
                'linked_no_show_event_id' => (int) ($active_no_show['id'] ?? 0),
                'notes' => $notes,
            ]);
            return [
                'candidate_user_id' => $candidate_user_id,
                'candidate_id' => $candidate_id,
                'booking_id' => $booking_id,
                'decision' => 'rejected',
                'appeal_event_id' => (int) ($appeal_rejected['event_id'] ?? 0),
            ];
        }

        global $wpdb;
        $conduct_table = $this->get_candidate_conduct_events_table();
        $reversed_at = current_time('mysql');
        $reversed = $wpdb->query($wpdb->prepare(
            "UPDATE {$conduct_table}
             SET status = %s,
                 reversed_at = %s,
                 reversed_by_user_id = %d
             WHERE id = %d
               AND status = %s",
            'reversed',
            $reversed_at,
            $actor_user_id,
            (int) ($active_no_show['id'] ?? 0),
            'active'
        ));
        if ($reversed === false) {
            return new WP_Error('cmn_conduct_appeal_reverse_update_failed', 'Unable to reverse no-show event.');
        }
        if ((int) $reversed === 0) {
            return new WP_Error('cmn_conduct_appeal_already_resolved', 'No-show has already been reversed.');
        }

        $shift_date = $this->normalize_invoice_date(substr((string) ($active_no_show['occurred_at'] ?? ''), 0, 10));
        if ($shift_date === '') {
            $shift_date = $this->resolve_no_show_shift_date_for_booking($booking_id);
        }
        if ($shift_date === '') {
            return new WP_Error('cmn_conduct_appeal_missing_shift_date', 'Unable to determine shift date for appeal reversal.');
        }
        $academic_year = function_exists('cmn_get_academic_year_label')
            ? (string) cmn_get_academic_year_label($shift_date)
            : (string) $this->get_academic_year_label($shift_date);

        $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($rewards_row)) {
            return $rewards_row;
        }
        $before_no_show_count = max(0, (int) ($rewards_row['no_show_count'] ?? 0));
        $after_no_show_count = max(0, $before_no_show_count - 1);
        $after_status = $this->resolve_conduct_status_from_no_show_count($after_no_show_count);
        $last_no_show_at = $after_no_show_count > 0
            ? $this->get_latest_active_no_show_datetime($candidate_user_id)
            : '';

        $updated_rewards_row = $this->update_candidate_rewards_conduct_state(
            $candidate_id,
            $academic_year,
            3,
            $after_no_show_count,
            $after_status,
            $last_no_show_at
        );
        if (is_wp_error($updated_rewards_row)) {
            return $updated_rewards_row;
        }
        $tier_sync = $this->rewards_apply_tier_if_needed($candidate_user_id, $academic_year, $actor_user_id);
        if (is_wp_error($tier_sync)) {
            $this->add_audit_log('candidate_rewards_tier_sync_failed_after_appeal', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'candidate_user_id' => $candidate_user_id,
                'academic_year' => $academic_year,
                'message' => $tier_sync->get_error_message(),
            ], $actor_user_id);
        } elseif (is_array($tier_sync['row'] ?? null) && !empty($tier_sync['row'])) {
            $updated_rewards_row = $tier_sync['row'];
        }

        $appeal_approved = $this->insert_candidate_conduct_event($candidate_user_id, $booking_id, 'appeal_approved', $notes, $actor_user_id);
        if (is_wp_error($appeal_approved)) {
            return $appeal_approved;
        }

        $this->log_candidate_conduct_audit_event($candidate_user_id, $booking_id, 'appeal_approved', $actor_user_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'linked_no_show_event_id' => (int) ($active_no_show['id'] ?? 0),
            'appeal_event_id' => (int) ($appeal_approved['event_id'] ?? 0),
            'shift_delta' => 3,
            'no_show_count_before' => $before_no_show_count,
            'no_show_count_after' => $after_no_show_count,
            'conduct_status' => $after_status,
            'academic_year' => $academic_year,
            'notes' => $notes,
        ]);
        $this->log_candidate_conduct_audit_event($candidate_user_id, $booking_id, 'shift_credit', $actor_user_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'delta' => 3,
            'source' => 'appeal_approved',
        ]);

        return [
            'candidate_user_id' => $candidate_user_id,
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'decision' => 'approved',
            'shift_date' => $shift_date,
            'appeal_event_id' => (int) ($appeal_approved['event_id'] ?? 0),
            'reversed_no_show_event_id' => (int) ($active_no_show['id'] ?? 0),
            'no_show_count' => $after_no_show_count,
            'conduct_status' => $this->normalize_candidate_rewards_conduct_status((string) ($updated_rewards_row['conduct_status'] ?? $after_status)),
            'shift_delta' => 3,
        ];
    }

    private function mark_shift_credit_row_voided_without_state_adjustment($credit_id, $reason = '') {
        $credit_id = (int) $credit_id;
        if ($credit_id < 1) {
            return false;
        }
        global $wpdb;
        $table = $this->get_candidate_shift_credits_table();
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET status = %s,
                 voided_at = %s,
                 void_reason = NULLIF(%s, '')
             WHERE id = %d
               AND status = %s",
            'voided',
            current_time('mysql'),
            substr(sanitize_text_field((string) $reason), 0, 255),
            $credit_id,
            'credited'
        ));
        return $updated !== false && (int) $updated > 0;
    }

    private function get_credit_row_by_booking_and_date($booking_id, $shift_date, $status = '') {
        $booking_id = (int) $booking_id;
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $status = sanitize_key((string) $status);
        if ($booking_id < 1 || $shift_date === '') {
            return [];
        }
        global $wpdb;
        $table = $this->get_candidate_shift_credits_table();
        if ($status !== '') {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE booking_id = %d
                   AND booking_day_date = %s
                   AND status = %s
                 ORDER BY id DESC
                 LIMIT 1",
                $booking_id,
                $shift_date,
                $status
            ), ARRAY_A);
        } else {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE booking_id = %d
                   AND booking_day_date = %s
                 ORDER BY id DESC
                 LIMIT 1",
                $booking_id,
                $shift_date
            ), ARRAY_A);
        }
        return is_array($row) ? $row : [];
    }

    public function rewards_credit_completed_booking_days($booking_id, $actor_user_id = null) {
        $booking_id = (int) $booking_id;
        $actor_user_id = $this->resolve_rewards_actor_user_id($actor_user_id);
        $permission = $this->enforce_rewards_mutation_permission($actor_user_id, 'rewards.mutate_any', [
            'booking_id' => $booking_id,
        ]);
        if (is_wp_error($permission)) {
            return $permission;
        }
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking') {
            return new WP_Error('cmn_rewards_invalid_booking', 'Booking not found for rewards crediting.');
        }

        $booking_status = sanitize_key((string) get_post_meta($booking_id, 'cmn_status', true));
        if ($this->is_rewards_credit_cancelled_status($booking_status)) {
            return [
                'booking_id' => $booking_id,
                'credited' => 0,
                'duplicates' => 0,
                'errors' => 0,
                'skipped_cancelled' => 0,
                'skipped_not_completed' => 1,
                'referral_tickets_awarded' => 0,
            ];
        }
        if (!$this->is_rewards_attended_completion_status($booking_status)) {
            return [
                'booking_id' => $booking_id,
                'credited' => 0,
                'duplicates' => 0,
                'errors' => 0,
                'skipped_cancelled' => 0,
                'skipped_not_completed' => 1,
                'referral_tickets_awarded' => 0,
            ];
        }

        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_rewards_invalid_candidate', 'Booking candidate is missing or invalid.');
        }
        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            return new WP_Error('cmn_rewards_missing_candidate_user', 'Candidate user account is required for shift credits.');
        }

        $shift_dates = $this->get_rewards_booking_shift_dates($booking_id);
        if (!$shift_dates) {
            return [
                'booking_id' => $booking_id,
                'candidate_id' => $candidate_id,
                'candidate_user_id' => $candidate_user_id,
                'credited' => 0,
                'duplicates' => 0,
                'errors' => 0,
                'skipped_cancelled' => 0,
                'skipped_not_completed' => 0,
                'referral_tickets_awarded' => 0,
            ];
        }

        $cancelled_dates = $this->get_rewards_cancelled_shift_dates_for_booking($booking_id);
        $summary = [
            'booking_id' => $booking_id,
            'candidate_id' => $candidate_id,
            'candidate_user_id' => $candidate_user_id,
            'credited' => 0,
            'duplicates' => 0,
            'errors' => 0,
            'skipped_cancelled' => 0,
            'skipped_not_completed' => 0,
            'referral_tickets_awarded' => 0,
        ];

        global $wpdb;
        $table = $this->get_candidate_shift_credits_table();
        foreach ($shift_dates as $shift_date) {
            $shift_date = $this->normalize_invoice_date((string) $shift_date);
            if ($shift_date === '') {
                continue;
            }
            if (isset($cancelled_dates[$shift_date])) {
                $summary['skipped_cancelled']++;
                continue;
            }

            $credited_at = current_time('mysql');
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT IGNORE INTO {$table}
                (candidate_user_id, booking_id, booking_day_date, status, credited_at)
                VALUES
                (%d, %d, %s, %s, %s)",
                $candidate_user_id,
                $booking_id,
                $shift_date,
                'credited',
                $credited_at
            ));
            if ($inserted === false) {
                $summary['errors']++;
                continue;
            }
            if ((int) $inserted === 0) {
                $summary['duplicates']++;
                continue;
            }

            $credit_id = (int) $wpdb->insert_id;
            $rewards_result = $this->award_candidate_rewards_for_day($candidate_id, $booking_id, $shift_date, [
                'source' => 'shift_credit_ledger',
                'status' => $booking_status,
                'created_by_user_id' => $actor_user_id,
            ]);
            if (is_wp_error($rewards_result)) {
                $this->mark_shift_credit_row_voided_without_state_adjustment(
                    $credit_id,
                    'credit_state_increment_failed: ' . $rewards_result->get_error_code()
                );
                $summary['errors']++;
                continue;
            }

            if (function_exists('cmn_audit_log_event')) {
                cmn_audit_log_event([
                    'module' => 'rewards',
                    'entity_type' => 'candidate',
                    'entity_id' => $candidate_user_id,
                    'event_type' => 'shift_credit',
                    'event_ref' => $booking_id . ':' . $shift_date,
                    'actor_user_id' => $actor_user_id,
                    'metadata' => [
                        'booking_id' => $booking_id,
                        'date' => $shift_date,
                        'candidate_id' => $candidate_id,
                        'candidate_user_id' => $candidate_user_id,
                    ],
                ]);
            }

            $qualification_result = $this->maybe_qualify_referral_after_first_shift($candidate_user_id, $shift_date, $actor_user_id);
            if (is_wp_error($qualification_result)) {
                $this->add_audit_log('candidate_referral_qualification_error', 'booking', (string) $booking_id, [
                    'candidate_user_id' => $candidate_user_id,
                    'shift_date' => $shift_date,
                    'message' => $qualification_result->get_error_message(),
                ], $actor_user_id);
            } elseif (!empty($qualification_result['ticket_created'])) {
                $summary['referral_tickets_awarded']++;
            }

            $summary['credited']++;
        }

        return $summary;
    }

    /*
     * Prompt 5 acceptance checks:
     * 1) Re-voiding the same booking day is idempotent (no extra decrement).
     * 2) Voiding decrements rewards counters and marks shift credit row as voided.
     */
    public function rewards_void_shift_credit($booking_id, $date, $reason, $actor_user_id) {
        $booking_id = (int) $booking_id;
        $shift_date = $this->normalize_invoice_date((string) $date);
        $reason = substr(sanitize_text_field((string) $reason), 0, 255);
        $actor_user_id = $this->resolve_rewards_actor_user_id($actor_user_id);
        $permission = $this->enforce_rewards_mutation_permission($actor_user_id, 'rewards.mutate_any', [
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
        ]);
        if (is_wp_error($permission)) {
            return $permission;
        }
        if ($actor_user_id < 1) {
            return new WP_Error('cmn_rewards_void_requires_actor', 'A valid actor user is required to void shift credits.');
        }
        if ($booking_id < 1 || $shift_date === '') {
            return new WP_Error('cmn_rewards_void_invalid_input', 'Booking and date are required for shift-credit voiding.');
        }
        if ($reason === '') {
            return new WP_Error('cmn_rewards_void_reason_required', 'A void reason is required.');
        }

        $credit_row = $this->get_credit_row_by_booking_and_date($booking_id, $shift_date, 'credited');
        if (!$credit_row) {
            return [
                'voided' => false,
                'booking_id' => $booking_id,
                'date' => $shift_date,
                'reason' => 'not_found_or_already_voided',
            ];
        }

        $credit_id = (int) ($credit_row['id'] ?? 0);
        $candidate_user_id = (int) ($credit_row['candidate_user_id'] ?? 0);
        global $wpdb;
        $table = $this->get_candidate_shift_credits_table();
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET status = %s,
                 voided_at = %s,
                 void_reason = %s
             WHERE id = %d
               AND status = %s",
            'voided',
            current_time('mysql'),
            $reason,
            $credit_id,
            'credited'
        ));
        if ($updated === false) {
            return new WP_Error('cmn_rewards_void_update_failed', 'Unable to void shift credit.');
        }
        if ((int) $updated === 0) {
            return [
                'voided' => false,
                'booking_id' => $booking_id,
                'date' => $shift_date,
                'reason' => 'already_voided',
            ];
        }

        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        }

        $delta_cycle = 1;
        $delta_year_total = 1;
        $event_row = [];
        if ($candidate_id > 0) {
            $event_row = $this->get_candidate_rewards_event_row($candidate_id, $booking_id, $shift_date, 'shift_completed');
            if ($event_row) {
                $delta_cycle = max(0, abs((int) ($event_row['delta_cycle'] ?? 0)));
                $delta_year_total = max(1, abs((int) ($event_row['delta_year_total'] ?? 1)));
            }

            $academic_year = function_exists('cmn_get_academic_year_label')
                ? (string) cmn_get_academic_year_label($shift_date)
                : (string) $this->get_academic_year_label($shift_date);
            $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
            if (!is_wp_error($rewards_row)) {
                $rewards_table = $this->get_candidate_rewards_table();
                $rewards_updated = $wpdb->query($wpdb->prepare(
                    "UPDATE {$rewards_table}
                     SET shift_cycle_count = GREATEST(0, shift_cycle_count - %d),
                         academic_year_shift_total = GREATEST(0, academic_year_shift_total - %d),
                         updated_at = %s
                     WHERE candidate_id = %d
                       AND academic_year = %s",
                    $delta_cycle,
                    $delta_year_total,
                    current_time('mysql'),
                    $candidate_id,
                    $academic_year
                ));
                if ($rewards_updated === false) {
                    return new WP_Error('cmn_rewards_void_state_update_failed', 'Shift credit was voided but rewards state update failed.');
                }
                $this->insert_candidate_rewards_event([
                    'candidate_id' => $candidate_id,
                    'booking_id' => $booking_id,
                    'shift_date' => $shift_date,
                    'event_type' => 'shift_voided',
                    'delta_cycle' => (0 - $delta_cycle),
                    'delta_year_total' => (0 - $delta_year_total),
                    'meta' => [
                        'reason' => $reason,
                        'source' => 'shift_credit_ledger',
                        'linked_shift_completed_event_id' => (int) ($event_row['id'] ?? 0),
                    ],
                    'created_by_user_id' => $actor_user_id,
                ]);

                $tier_sync = $this->rewards_apply_tier_if_needed($candidate_user_id, $academic_year, $actor_user_id);
                if (is_wp_error($tier_sync)) {
                    $this->add_audit_log('candidate_rewards_tier_sync_failed_after_void', 'booking', (string) $booking_id, [
                        'candidate_id' => $candidate_id,
                        'candidate_user_id' => $candidate_user_id,
                        'shift_date' => $shift_date,
                        'academic_year' => $academic_year,
                        'message' => $tier_sync->get_error_message(),
                    ], $actor_user_id);
                }
            }
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'rewards',
                'entity_type' => 'candidate',
                'entity_id' => $candidate_user_id,
                'event_type' => 'shift_voided',
                'event_ref' => $booking_id . ':' . $shift_date,
                'actor_user_id' => $actor_user_id,
                'metadata' => [
                    'booking_id' => $booking_id,
                    'date' => $shift_date,
                    'reason' => $reason,
                    'candidate_id' => $candidate_id,
                    'candidate_user_id' => $candidate_user_id,
                    'decrement_cycle' => $delta_cycle,
                    'decrement_year_total' => $delta_year_total,
                ],
            ]);
        }

        $flagged_for_review_count = 0;
        if ($candidate_user_id > 0) {
            $academic_year_for_void = function_exists('cmn_get_academic_year_label')
                ? (string) cmn_get_academic_year_label($shift_date)
                : (string) $this->get_academic_year_label($shift_date);
            $flag_result = $this->maybe_flag_bonus_awards_for_voided_shift_credit(
                $candidate_user_id,
                $academic_year_for_void,
                $credit_row,
                $actor_user_id,
                $reason
            );
            if (is_wp_error($flag_result)) {
                $this->add_audit_log('candidate_rewards_bonus_flag_review_failed', 'booking', (string) $booking_id, [
                    'candidate_user_id' => $candidate_user_id,
                    'date' => $shift_date,
                    'reason' => $reason,
                    'message' => $flag_result->get_error_message(),
                ], $actor_user_id);
            } else {
                $flagged_for_review_count = max(0, (int) ($flag_result['flagged_count'] ?? 0));
            }
        }

        return [
            'voided' => true,
            'booking_id' => $booking_id,
            'date' => $shift_date,
            'candidate_id' => $candidate_id,
            'candidate_user_id' => $candidate_user_id,
            'decrement_cycle' => $delta_cycle,
            'decrement_year_total' => $delta_year_total,
            'bonus_flagged_for_review_count' => $flagged_for_review_count,
        ];
    }

    private function maybe_award_candidate_rewards_for_booking($booking_id, $status = '') {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            $this->add_audit_log('candidate_rewards_shift_skipped_missing_booking', 'booking', '0', [
                'reason' => 'missing_booking_id',
            ]);
            return 0;
        }

        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($candidate_id < 1) {
            $this->add_audit_log('candidate_rewards_shift_skipped_missing_candidate', 'booking', (string) $booking_id, [
                'reason' => 'missing_candidate_id',
            ]);
            return 0;
        }
        if (get_post_type($candidate_id) !== 'cmn_candidate') {
            $this->add_audit_log('candidate_rewards_shift_skipped_missing_candidate', 'booking', (string) $booking_id, [
                'reason' => 'invalid_candidate_id',
                'candidate_id' => $candidate_id,
            ]);
            return 0;
        }

        $status = sanitize_key((string) ($status !== '' ? $status : get_post_meta($booking_id, 'cmn_status', true)));
        if (!$this->is_completed_payable_booking_status($status)) {
            return 0;
        }

        $start_date = $this->normalize_booking_invoice_date_value((string) get_post_meta($booking_id, 'cmn_start_date', true));
        if ($start_date === '') {
            $start_date = $this->normalize_booking_invoice_date_value((string) get_post_meta($booking_id, 'cmn_date', true));
        }
        if ($start_date === '') {
            $this->add_audit_log('candidate_rewards_shift_skipped_missing_date', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'reason' => 'missing_start_date',
            ]);
            return 0;
        }

        $end_date = $this->normalize_booking_invoice_date_value((string) get_post_meta($booking_id, 'cmn_end_date', true));
        if ($end_date === '') {
            $end_date = $start_date;
        }
        if (strtotime($end_date) < strtotime($start_date)) {
            $end_date = $start_date;
        }

        $shift_dates = $this->expand_booking_dates_for_period(
            $start_date,
            $end_date,
            $start_date,
            $end_date,
            current_time('Y-m-d')
        );
        if (!$shift_dates) {
            return 0;
        }

        $awarded = 0;
        foreach ($shift_dates as $shift_date) {
            $result = $this->award_candidate_rewards_for_day($candidate_id, $booking_id, $shift_date, [
                'source' => 'booking_status_update',
                'status' => $status,
            ]);
            if (is_wp_error($result)) {
                $this->add_audit_log('candidate_rewards_shift_award_failed', 'booking', (string) $booking_id, [
                    'candidate_id' => $candidate_id,
                    'shift_date' => $shift_date,
                    'status' => $status,
                    'message' => $result->get_error_message(),
                ]);
                continue;
            }
            if (!empty($result['incremented'])) {
                $awarded++;
            }
        }

        return $awarded;
    }

    private function get_candidate_rewards_tier_order() {
        return ['standard', 'bronze', 'silver', 'gold', 'elite'];
    }

    private function get_candidate_rewards_tier_multiplier_map(array $config_row = []) {
        $map = [
            'standard' => 1.00,
            'bronze' => 1.10,
            'silver' => 1.20,
            'gold' => 1.30,
            'elite' => 1.50,
        ];
        if ($config_row) {
            $map['bronze'] = round(max(1.00, (float) ($config_row['bronze_multiplier'] ?? $map['bronze'])), 2);
            $map['silver'] = round(max($map['bronze'], (float) ($config_row['silver_multiplier'] ?? $map['silver'])), 2);
            $map['gold'] = round(max($map['silver'], (float) ($config_row['gold_multiplier'] ?? $map['gold'])), 2);
            $map['elite'] = round(max($map['gold'], (float) ($config_row['elite_multiplier'] ?? $map['elite'])), 2);
        }
        return $map;
    }

    private function normalize_rewards_config_year_label($academic_year_label = '', $reference_date = '') {
        $academic_year_label = trim((string) $academic_year_label);
        if (preg_match('/^(\d{4})\/(\d{2})$/', $academic_year_label, $m) === 1) {
            $start = (int) $m[1];
            $end_short = (int) $m[2];
            if (($start + 1) % 100 === $end_short) {
                return sprintf('%04d/%02d', $start, $end_short);
            }
        }
        if (preg_match('/^(\d{4})-(\d{4})$/', $academic_year_label, $m) === 1) {
            $start = (int) $m[1];
            $end = (int) $m[2];
            if ($end === ($start + 1)) {
                return sprintf('%04d/%02d', $start, ($end % 100));
            }
        }

        $normalized_candidate_label = $this->normalize_candidate_rewards_academic_year_label($academic_year_label, $reference_date);
        if (preg_match('/^(\d{4})-(\d{4})$/', $normalized_candidate_label, $m) === 1) {
            $start = (int) $m[1];
            $end = (int) $m[2];
            if ($end === ($start + 1)) {
                return sprintf('%04d/%02d', $start, ($end % 100));
            }
        }
        return '';
    }

    private function get_rewards_config_row_for_academic_year($academic_year_label = '', $reference_date = '') {
        $config_label = $this->normalize_rewards_config_year_label($academic_year_label, $reference_date);
        if ($config_label === '') {
            return [];
        }

        $ensure = $this->ensure_rewards_year_config_with_audit($config_label, [
            'actor_user_id' => (int) get_current_user_id(),
            'trigger' => 'tier_engine',
        ]);
        $row = is_array($ensure['row'] ?? null) ? $ensure['row'] : [];
        if ($row) {
            return $row;
        }

        global $wpdb;
        $table = $this->get_rewards_config_years_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE academic_year_label = %s
             LIMIT 1",
            $config_label
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function get_candidate_rewards_tier_threshold_map(array $config_row = []) {
        $defaults = self::CANDIDATE_REWARDS_TIER_THRESHOLDS;
        $thresholds = $defaults;
        if ($config_row) {
            $thresholds = [
                'standard' => 0,
                'bronze' => max(0, (int) ($config_row['bronze_threshold'] ?? $defaults['bronze'])),
                'silver' => max(0, (int) ($config_row['silver_threshold'] ?? $defaults['silver'])),
                'gold' => max(0, (int) ($config_row['gold_threshold'] ?? $defaults['gold'])),
                'elite' => max(0, (int) ($config_row['elite_threshold'] ?? $defaults['elite'])),
            ];
        } else {
            $filtered = apply_filters('cmn_candidate_rewards_tier_thresholds', $defaults);
            if (is_array($filtered)) {
                $thresholds = $filtered;
            }
        }
        $normalized = [];
        foreach ($this->get_candidate_rewards_tier_order() as $tier) {
            $normalized[$tier] = max(0, (int) ($thresholds[$tier] ?? ($defaults[$tier] ?? 0)));
        }
        $running_min = 0;
        foreach ($this->get_candidate_rewards_tier_order() as $tier) {
            $normalized[$tier] = max($running_min, (int) ($normalized[$tier] ?? 0));
            $running_min = (int) $normalized[$tier];
        }
        return $normalized;
    }

    /*
     * Prompt 7 acceptance checks:
     * 1) 29 => standard, 30 => bronze, 60 => silver, 120 => elite (with default config).
     * 2) Deterministic and idempotent for the same shifts/config input.
     */
    public function rewards_compute_tier($shifts_completed, $config_row = []) {
        $shift_total = max(0, (int) $shifts_completed);
        $thresholds = $this->get_candidate_rewards_tier_threshold_map(is_array($config_row) ? $config_row : []);
        $resolved_tier = 'standard';
        foreach ($this->get_candidate_rewards_tier_order() as $tier) {
            if ($shift_total >= (int) ($thresholds[$tier] ?? 0)) {
                $resolved_tier = $tier;
            }
        }
        return $this->normalize_candidate_rewards_tier($resolved_tier);
    }

    private function get_candidate_rewards_tier_rank($tier) {
        $tier = $this->normalize_candidate_rewards_tier($tier);
        $rank = 0;
        foreach ($this->get_candidate_rewards_tier_order() as $index => $key) {
            if ($tier === $key) {
                $rank = (int) $index;
                break;
            }
        }
        return $rank;
    }

    /*
     * Prompt 7 acceptance checks:
     * 1) Upgrades happen only once per threshold crossing.
     * 2) Terminated/suspended rewards rows are never upgraded.
     * 3) Repeated calls with unchanged state do not create duplicate tier_change audit events.
     */
    public function rewards_apply_tier_if_needed($candidate_user_id, $academic_year_label, $actor_user_id = null) {
        $candidate_user_id = (int) $candidate_user_id;
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year_label, current_time('Y-m-d'));
        $actor_user_id = $actor_user_id === null ? (int) get_current_user_id() : max(0, (int) $actor_user_id);
        if ($candidate_user_id < 1 || $academic_year === '') {
            return new WP_Error('cmn_rewards_tier_invalid_input', 'Candidate user and academic year are required for tier progression.');
        }

        $candidate_id = (int) $this->resolve_candidate_id_for_conduct_user($candidate_user_id);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_rewards_tier_invalid_candidate', 'Candidate not found for tier progression.');
        }

        $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($rewards_row)) {
            return $rewards_row;
        }
        if (!is_array($rewards_row) || !$rewards_row) {
            return new WP_Error('cmn_rewards_tier_missing_state', 'Candidate rewards state row is unavailable.');
        }

        $state_status = sanitize_key((string) ($rewards_row['status'] ?? ''));
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($rewards_row['conduct_status'] ?? 'clear'));
        $is_suspended = ($state_status === 'rewards_suspended') || (!empty($rewards_row['rewards_paused']) && (int) $rewards_row['rewards_paused'] === 1);
        $is_terminated = ($state_status === 'terminated') || ($conduct_status === 'terminated');
        if ($is_terminated) {
            return [
                'updated' => false,
                'skipped' => true,
                'reason' => 'terminated',
                'row' => $rewards_row,
                'candidate_id' => $candidate_id,
                'candidate_user_id' => $candidate_user_id,
                'academic_year' => $academic_year,
            ];
        }
        if ($is_suspended) {
            return [
                'updated' => false,
                'skipped' => true,
                'reason' => 'suspended',
                'row' => $rewards_row,
                'candidate_id' => $candidate_id,
                'candidate_user_id' => $candidate_user_id,
                'academic_year' => $academic_year,
            ];
        }

        $config_row = $this->get_rewards_config_row_for_academic_year($academic_year, current_time('Y-m-d'));
        $target_tier = $this->rewards_compute_tier((int) ($rewards_row['academic_year_shift_total'] ?? 0), $config_row);
        $current_tier = $this->normalize_candidate_rewards_tier((string) ($rewards_row['tier'] ?? 'standard'));
        $target_rank = $this->get_candidate_rewards_tier_rank($target_tier);
        $current_rank = $this->get_candidate_rewards_tier_rank($current_tier);
        if ($target_rank <= $current_rank) {
            return [
                'updated' => false,
                'skipped' => true,
                'reason' => 'no_upgrade',
                'row' => $rewards_row,
                'candidate_id' => $candidate_id,
                'candidate_user_id' => $candidate_user_id,
                'academic_year' => $academic_year,
                'from_tier' => $current_tier,
                'to_tier' => $target_tier,
            ];
        }

        $multiplier_map = $this->get_candidate_rewards_tier_multiplier_map($config_row);
        $target_multiplier = round((float) ($multiplier_map[$target_tier] ?? $this->get_candidate_rewards_multiplier_for_tier($target_tier)), 2);
        if ($target_multiplier <= 0) {
            $target_multiplier = $this->get_candidate_rewards_multiplier_for_tier($target_tier);
        }

        global $wpdb;
        $table = $this->get_candidate_rewards_table();
        $now_mysql = current_time('mysql');
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET tier = %s,
                 multiplier = %f,
                 last_tier_change_at = %s,
                 updated_at = %s
             WHERE candidate_id = %d
               AND academic_year = %s
               AND tier = %s",
            $target_tier,
            $target_multiplier,
            $now_mysql,
            $now_mysql,
            $candidate_id,
            $academic_year,
            $current_tier
        ));
        if ($updated === false) {
            return new WP_Error('cmn_rewards_tier_update_failed', 'Unable to update candidate tier.');
        }

        $row_after = $this->get_candidate_rewards_record($candidate_id, $academic_year);
        if (!is_array($row_after) || !$row_after) {
            return new WP_Error('cmn_rewards_tier_lookup_failed', 'Unable to load rewards state after tier update.');
        }
        $final_tier = $this->normalize_candidate_rewards_tier((string) ($row_after['tier'] ?? $current_tier));
        if ($updated === 0 || $final_tier === $current_tier) {
            return [
                'updated' => false,
                'skipped' => true,
                'reason' => 'no_upgrade',
                'row' => $row_after,
                'candidate_id' => $candidate_id,
                'candidate_user_id' => $candidate_user_id,
                'academic_year' => $academic_year,
                'from_tier' => $current_tier,
                'to_tier' => $final_tier,
            ];
        }

        $config_label = $this->normalize_rewards_config_year_label($academic_year, current_time('Y-m-d'));
        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'rewards',
                'entity_type' => 'candidate',
                'entity_id' => $candidate_user_id,
                'event_type' => 'tier_change',
                'event_ref' => $academic_year,
                'actor_user_id' => $actor_user_id,
                'metadata' => [
                    'from' => $current_tier,
                    'to' => $final_tier,
                    'shifts' => (int) ($row_after['academic_year_shift_total'] ?? 0),
                    'label' => $config_label,
                    'academic_year' => $academic_year,
                    'candidate_id' => $candidate_id,
                ],
            ]);
        }

        return [
            'updated' => true,
            'skipped' => false,
            'reason' => '',
            'row' => $row_after,
            'candidate_id' => $candidate_id,
            'candidate_user_id' => $candidate_user_id,
            'academic_year' => $academic_year,
            'from_tier' => $current_tier,
            'to_tier' => $final_tier,
            'multiplier' => $target_multiplier,
        ];
    }

    public function cmn_candidate_rewards_resolve_tier($academic_year_shift_total) {
        $shift_total = max(0, (int) $academic_year_shift_total);
        $thresholds = $this->get_candidate_rewards_tier_threshold_map();
        $resolved_tier = $this->rewards_compute_tier($shift_total, []);
        $resolved_tier = $this->normalize_candidate_rewards_tier($resolved_tier);
        $resolved_multiplier = $this->get_candidate_rewards_multiplier_for_tier($resolved_tier);
        return [
            'tier' => $resolved_tier,
            'multiplier' => $resolved_multiplier,
            'threshold' => (int) ($thresholds[$resolved_tier] ?? 0),
            'academic_year_shift_total' => $shift_total,
        ];
    }

    private function maybe_apply_candidate_rewards_tier_progression($candidate_id, $booking_id, $shift_date, $academic_year, $rewards_row = [], $context = []) {
        $candidate_id = (int) $candidate_id;
        $booking_id = max(0, (int) $booking_id);
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        if ($shift_date === '') {
            $shift_date = current_time('Y-m-d');
        }
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, $shift_date);
        $context = is_array($context) ? $context : [];
        if ($candidate_id < 1 || $academic_year === '') {
            return new WP_Error('cmn_candidate_rewards_tier_progression_invalid_input', 'Invalid candidate tier progression input.');
        }
        if (!is_array($rewards_row) || !$rewards_row) {
            $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
            if (is_wp_error($rewards_row)) {
                return $rewards_row;
            }
        }

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            return new WP_Error('cmn_candidate_rewards_tier_user_missing', 'Candidate user account is required for tier progression.');
        }

        $actor_user_id = (int) ($context['created_by_user_id'] ?? 0);
        $tier_result = $this->rewards_apply_tier_if_needed($candidate_user_id, $academic_year, $actor_user_id);
        if (is_wp_error($tier_result)) {
            return $tier_result;
        }
        $updated_row = is_array($tier_result['row'] ?? null) ? $tier_result['row'] : $this->get_candidate_rewards_record($candidate_id, $academic_year);
        if (!$updated_row) {
            return new WP_Error('cmn_candidate_rewards_tier_update_lookup_failed', 'Unable to load candidate rewards row after tier update.');
        }
        if (empty($tier_result['updated'])) {
            return [
                'updated' => false,
                'skipped' => true,
                'reason' => sanitize_key((string) ($tier_result['reason'] ?? 'no_upgrade')),
                'event_id' => 0,
                'row' => $updated_row,
                'previous_tier' => $this->normalize_candidate_rewards_tier((string) ($rewards_row['tier'] ?? 'standard')),
                'new_tier' => $this->normalize_candidate_rewards_tier((string) ($updated_row['tier'] ?? ($rewards_row['tier'] ?? 'standard'))),
                'previous_multiplier' => round((float) ($rewards_row['multiplier'] ?? 1.00), 2),
                'new_multiplier' => round((float) ($updated_row['multiplier'] ?? ($rewards_row['multiplier'] ?? 1.00)), 2),
            ];
        }

        $current_tier = $this->normalize_candidate_rewards_tier((string) ($tier_result['from_tier'] ?? ($rewards_row['tier'] ?? 'standard')));
        $new_tier = $this->normalize_candidate_rewards_tier((string) ($tier_result['to_tier'] ?? ($updated_row['tier'] ?? 'standard')));
        $current_multiplier = round((float) ($rewards_row['multiplier'] ?? $this->get_candidate_rewards_multiplier_for_tier($current_tier)), 2);
        $new_multiplier = round((float) ($updated_row['multiplier'] ?? ($tier_result['multiplier'] ?? $this->get_candidate_rewards_multiplier_for_tier($new_tier))), 2);
        $shift_total = (int) ($updated_row['academic_year_shift_total'] ?? 0);

        $event_insert = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'event_type' => 'tier_updated',
            'delta_cycle' => 0,
            'delta_year_total' => 0,
            'meta' => [
                'previous_tier' => $current_tier,
                'new_tier' => $new_tier,
                'previous_multiplier' => $current_multiplier,
                'new_multiplier' => $new_multiplier,
                'academic_year_shift_total' => $shift_total,
                'source' => sanitize_key((string) ($context['source'] ?? 'completed_payable_hook')),
            ],
            'created_by_user_id' => $actor_user_id,
        ]);
        if (is_wp_error($event_insert)) {
            $this->add_audit_log('candidate_rewards_tier_update_event_failed', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'message' => $event_insert->get_error_message(),
            ]);
            $event_insert = [
                'event_id' => 0,
                'inserted' => false,
                'duplicate' => false,
            ];
        }

        $this->add_audit_log('candidate_rewards_tier_updated', 'booking', (string) $booking_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'academic_year' => $academic_year,
            'academic_year_shift_total' => $shift_total,
            'previous_tier' => $current_tier,
            'new_tier' => $new_tier,
            'previous_multiplier' => $current_multiplier,
            'new_multiplier' => $new_multiplier,
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
            'event_duplicate' => empty($event_insert['inserted']) ? 1 : 0,
        ]);

        return [
            'updated' => true,
            'skipped' => false,
            'reason' => '',
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
            'row' => $updated_row,
            'previous_tier' => $current_tier,
            'new_tier' => $new_tier,
            'previous_multiplier' => $current_multiplier,
            'new_multiplier' => $new_multiplier,
        ];
    }

    private function decode_candidate_rewards_event_meta($meta_raw) {
        if (is_array($meta_raw)) {
            return $meta_raw;
        }
        if (is_object($meta_raw)) {
            return (array) $meta_raw;
        }
        $meta_raw = trim((string) $meta_raw);
        if ($meta_raw === '') {
            return [];
        }
        $decoded = json_decode($meta_raw, true);
        if (json_last_error() !== JSON_ERROR_NONE || !is_array($decoded)) {
            return [];
        }
        return $decoded;
    }

    private function candidate_rewards_meta_flag_is_true($value) {
        if (is_bool($value)) {
            return $value;
        }
        if (is_numeric($value)) {
            return ((int) $value) === 1;
        }
        $value = strtolower(trim((string) $value));
        return in_array($value, ['1', 'true', 'yes', 'on'], true);
    }

    private function normalize_candidate_bonus_award_status($status) {
        $status = sanitize_key((string) $status);
        if (!in_array($status, ['awarded', 'flagged_for_review', 'voided'], true)) {
            return 'awarded';
        }
        return $status;
    }

    private function decode_candidate_bonus_award_notes($notes) {
        $notes = is_string($notes) ? trim($notes) : '';
        if ($notes === '') {
            return [];
        }
        $decoded = json_decode($notes, true);
        if (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) {
            return $decoded;
        }
        return ['legacy_note' => $notes];
    }

    private function get_candidate_rewards_bonus_window_for_block($block_index, $elite_block_index = 4) {
        $block_index = max(1, (int) $block_index);
        $elite_block_index = max(1, (int) $elite_block_index);
        // Rolling windows scale with tier milestones then stay fixed at 120 for elite recurring milestones.
        if ($block_index <= 1) {
            return 30;
        }
        if ($block_index === 2) {
            return 60;
        }
        if ($block_index === 3 && $block_index < $elite_block_index) {
            return 90;
        }
        return 120;
    }

    private function get_candidate_rewards_bonus_multiplier_for_block($block_index, array $config_row = [], $elite_block_index = 4) {
        $block_index = max(1, (int) $block_index);
        $elite_block_index = max(1, (int) $elite_block_index);
        $multiplier_map = $this->get_candidate_rewards_tier_multiplier_map($config_row);
        $bronze_multiplier = round((float) ($multiplier_map['bronze'] ?? 1.10), 2);
        $silver_multiplier = round((float) ($multiplier_map['silver'] ?? 1.20), 2);
        $gold_multiplier = round((float) ($multiplier_map['gold'] ?? 1.30), 2);
        $elite_multiplier = round((float) ($multiplier_map['elite'] ?? 1.50), 2);
        $elite_recurring_multiplier = round(max(
            $elite_multiplier,
            (float) ($config_row['elite_recurring_multiplier'] ?? $elite_multiplier)
        ), 2);

        // Tier multipliers align with 30/60/90/120 milestones; elite+ recurring stays on the elite multiplier.
        if ($block_index <= 1) {
            return max(1.00, $bronze_multiplier);
        }
        if ($block_index === 2) {
            return max(1.00, $silver_multiplier);
        }
        if ($block_index === 3) {
            return max(1.00, $gold_multiplier);
        }
        if ($block_index === $elite_block_index) {
            return max(1.00, $elite_multiplier);
        }
        return max(1.00, $elite_recurring_multiplier);
    }

    private function get_candidate_shift_credits_for_bonus_block($candidate_user_id, $academic_year_label, $block_index, $rolling_window = 0) {
        $candidate_user_id = (int) $candidate_user_id;
        $block_index = max(1, (int) $block_index);
        if ($candidate_user_id < 1) {
            return new WP_Error('cmn_rewards_bonus_invalid_candidate_user', 'Candidate user is required.');
        }

        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year_label, current_time('Y-m-d'));
        $bounds = $this->get_candidate_rewards_academic_year_bounds($academic_year, current_time('Y-m-d'));
        $start_date = (string) ($bounds['start_date'] ?? '');
        $end_date = (string) ($bounds['end_date'] ?? '');
        if ($academic_year === '' || $start_date === '' || $end_date === '') {
            return new WP_Error('cmn_rewards_bonus_invalid_year', 'Academic year is invalid for bonus block calculation.');
        }

        $milestone_shift_total = $block_index * 30;
        $rolling_window = (int) $rolling_window;
        if ($rolling_window < 1) {
            $rolling_window = $this->get_candidate_rewards_bonus_window_for_block($block_index, 4);
        }
        $rolling_window = max(1, $rolling_window);
        $rolling_window = min($rolling_window, $milestone_shift_total);

        global $wpdb;
        $table = $this->get_candidate_shift_credits_table();
        $milestone_rows = $wpdb->get_results($wpdb->prepare(
            "SELECT id, candidate_user_id, booking_id, booking_day_date, status, credited_at, voided_at, void_reason
             FROM {$table}
             WHERE candidate_user_id = %d
               AND status = %s
               AND booking_day_date >= %s
               AND booking_day_date <= %s
             ORDER BY booking_day_date ASC, id ASC
             LIMIT %d",
            $candidate_user_id,
            'credited',
            $start_date,
            $end_date,
            $milestone_shift_total
        ), ARRAY_A);
        if (!is_array($milestone_rows)) {
            $milestone_rows = [];
        }
        if (count($milestone_rows) < $milestone_shift_total) {
            return new WP_Error('cmn_rewards_bonus_insufficient_shifts', 'Insufficient credited shifts for requested bonus block.');
        }

        $rows = array_slice($milestone_rows, (-1 * $rolling_window));
        if (!is_array($rows)) {
            $rows = [];
        }
        if (count($rows) < $rolling_window) {
            return new WP_Error('cmn_rewards_bonus_insufficient_shifts', 'Insufficient credited shifts for requested rolling bonus window.');
        }

        return [
            'academic_year' => $academic_year,
            'start_date' => $start_date,
            'end_date' => $end_date,
            'rolling_window' => $rolling_window,
            'milestone_shift_total' => $milestone_shift_total,
            'rows' => $rows,
        ];
    }

    /*
     * Source of truth for per-day pay in bonus calculations:
     * 1) cmn_booking_rates.candidate_pay_rate (preferred)
     * 2) booking meta cmn_candidate_pay_rate
     * 3) booking meta cmn_rate (legacy fallback)
     */
    private function get_candidate_day_pay_for_shift_credit_row($credit_row) {
        $credit_row = is_array($credit_row) ? $credit_row : [];
        $booking_id = (int) ($credit_row['booking_id'] ?? 0);
        if ($booking_id < 1) {
            return new WP_Error('cmn_rewards_bonus_invalid_credit_booking', 'Bonus credit row missing booking reference.');
        }

        $rate_row = $this->get_booking_rate_row($booking_id);
        $candidate_pay = round((float) ($rate_row['candidate_pay_rate'] ?? 0), 2);
        if ($candidate_pay <= 0) {
            $candidate_pay = round((float) get_post_meta($booking_id, 'cmn_candidate_pay_rate', true), 2);
        }
        if ($candidate_pay <= 0) {
            $candidate_pay = round((float) get_post_meta($booking_id, 'cmn_rate', true), 2);
        }
        if ($candidate_pay <= 0) {
            return new WP_Error('cmn_rewards_bonus_missing_day_pay', 'Candidate day pay is missing for one or more booking-days in the bonus block.');
        }
        return $candidate_pay;
    }

    public function rewards_get_completed_block_index($shifts_completed) {
        $shifts_completed = (int) $shifts_completed;
        if ($shifts_completed <= 0) {
            return 0;
        }
        return (int) floor($shifts_completed / 30);
    }

    public function rewards_block_multiplier($block_index, $elite_block_index = 4) {
        $block_index = max(0, (int) $block_index);
        $elite_block_index = max(1, (int) $elite_block_index);
        if ($block_index <= 0) {
            return 1.00;
        }
        return $this->get_candidate_rewards_bonus_multiplier_for_block($block_index, [], $elite_block_index);
    }

    private function calculate_bonus_block_payload($candidate_user_id, $academic_year_label, $block_index) {
        $candidate_user_id = (int) $candidate_user_id;
        $block_index = max(1, (int) $block_index);
        if ($candidate_user_id < 1) {
            return new WP_Error('cmn_rewards_bonus_invalid_candidate_user', 'Candidate user is required.');
        }

        $rolling_window = $this->get_candidate_rewards_bonus_window_for_block($block_index, 4);
        $credit_bundle = $this->get_candidate_shift_credits_for_bonus_block($candidate_user_id, $academic_year_label, $block_index, $rolling_window);
        if (is_wp_error($credit_bundle)) {
            return $credit_bundle;
        }
        $credit_rows = (array) ($credit_bundle['rows'] ?? []);
        if (count($credit_rows) < $rolling_window) {
            return new WP_Error('cmn_rewards_bonus_insufficient_shifts', 'Insufficient credited shifts for requested rolling bonus window.');
        }

        $total_day_pay = 0.00;
        $credit_ids = [];
        $booking_day_refs = [];
        foreach ($credit_rows as $credit_row) {
            $day_pay = $this->get_candidate_day_pay_for_shift_credit_row($credit_row);
            if (is_wp_error($day_pay)) {
                return $day_pay;
            }
            $total_day_pay += (float) $day_pay;
            $credit_ids[] = (int) ($credit_row['id'] ?? 0);
            $booking_id = (int) ($credit_row['booking_id'] ?? 0);
            $booking_day_date = $this->normalize_invoice_date((string) ($credit_row['booking_day_date'] ?? ''));
            $booking_day_refs[] = $booking_id . ':' . $booking_day_date;
        }
        $total_day_pay = round($total_day_pay, 2);
        $average_day_pay = round($total_day_pay / max(1, $rolling_window), 2);
        $normalized_academic_year = (string) ($credit_bundle['academic_year'] ?? $this->normalize_candidate_rewards_academic_year_label((string) $academic_year_label, current_time('Y-m-d')));
        $milestone_shift_total = max($block_index * 30, (int) ($credit_bundle['milestone_shift_total'] ?? 0));

        return [
            'academic_year' => $normalized_academic_year,
            'block_index' => $block_index,
            'block_start_shift' => (($block_index - 1) * 30) + 1,
            'block_end_shift' => $block_index * 30,
            'rolling_window' => $rolling_window,
            'milestone_shift_total' => $milestone_shift_total,
            'average_day_pay' => $average_day_pay,
            'total_day_pay' => $total_day_pay,
            'credit_rows' => $credit_rows,
            'credit_ids' => $credit_ids,
            'booking_day_refs' => $booking_day_refs,
        ];
    }

    public function rewards_calculate_average_day_pay_for_block($candidate_user_id, $academic_year_label, $block_index) {
        $payload = $this->calculate_bonus_block_payload($candidate_user_id, $academic_year_label, $block_index);
        if (is_wp_error($payload)) {
            return $payload;
        }
        return round((float) ($payload['average_day_pay'] ?? 0), 2);
    }

    private function get_candidate_bonus_award_row($candidate_user_id, $academic_year_label, $block_index) {
        $candidate_user_id = (int) $candidate_user_id;
        $academic_year_label = trim((string) $academic_year_label);
        $block_index = max(1, (int) $block_index);
        if ($candidate_user_id < 1 || $academic_year_label === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_bonus_awards_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_user_id = %d
               AND academic_year_label = %s
               AND block_index = %d
             LIMIT 1",
            $candidate_user_id,
            $academic_year_label,
            $block_index
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function insert_candidate_bonus_award($award_data = []) {
        $award_data = is_array($award_data) ? $award_data : [];
        $candidate_user_id = (int) ($award_data['candidate_user_id'] ?? 0);
        $academic_year_label = trim((string) ($award_data['academic_year_label'] ?? ''));
        $block_index = max(1, (int) ($award_data['block_index'] ?? 0));
        $block_start_shift = max(1, (int) ($award_data['block_start_shift'] ?? ((($block_index - 1) * 30) + 1)));
        $block_end_shift = max($block_start_shift, (int) ($award_data['block_end_shift'] ?? ($block_index * 30)));
        $multiplier = round((float) ($award_data['multiplier'] ?? 1.00), 2);
        if ($multiplier <= 0) {
            $multiplier = 1.00;
        }
        $average_day_pay = round(max(0, (float) ($award_data['average_day_pay'] ?? 0)), 2);
        $bonus_amount = round(max(0, (float) ($award_data['bonus_amount'] ?? 0)), 2);
        $status = $this->normalize_candidate_bonus_award_status((string) ($award_data['status'] ?? 'awarded'));
        $awarded_at = $this->normalize_invoice_datetime((string) ($award_data['awarded_at'] ?? ''));
        if ($awarded_at === '') {
            $awarded_at = current_time('mysql');
        }
        $notes_json = '';
        if (array_key_exists('notes', $award_data)) {
            $notes_input = $award_data['notes'];
            if (is_array($notes_input) || is_object($notes_input)) {
                $encoded = wp_json_encode($notes_input, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                $notes_json = is_string($encoded) ? $encoded : '';
            } else {
                $notes_json = trim((string) $notes_input);
            }
        }

        if ($candidate_user_id < 1 || $academic_year_label === '') {
            return new WP_Error('cmn_rewards_bonus_invalid_award_context', 'Candidate and academic year are required for bonus award.');
        }

        global $wpdb;
        $table = $this->get_candidate_bonus_awards_table();
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT IGNORE INTO {$table}
            (candidate_user_id, academic_year_label, block_index, block_start_shift, block_end_shift, multiplier, average_day_pay, bonus_amount, status, awarded_at, notes)
            VALUES
            (%d, %s, %d, %d, %d, %f, %f, %f, %s, %s, NULLIF(%s, ''))",
            $candidate_user_id,
            $academic_year_label,
            $block_index,
            $block_start_shift,
            $block_end_shift,
            $multiplier,
            $average_day_pay,
            $bonus_amount,
            $status,
            $awarded_at,
            $notes_json
        ));
        if ($inserted === false) {
            return new WP_Error('cmn_rewards_bonus_award_insert_failed', 'Unable to insert candidate bonus award.');
        }

        $existing_row = $this->get_candidate_bonus_award_row($candidate_user_id, $academic_year_label, $block_index);
        if (!$existing_row) {
            return new WP_Error('cmn_rewards_bonus_award_lookup_failed', 'Unable to load candidate bonus award.');
        }
        return [
            'inserted' => ((int) $inserted) > 0,
            'duplicate' => ((int) $inserted) === 0,
            'row' => $existing_row,
        ];
    }

    /*
     * Prompt 58 acceptance checks:
     * 1) Candidate at 30/60/90/120 shifts receives 1.1x/1.2x/1.3x/1.5x bonus multiplier.
     * 2) Candidate at 150+ shifts receives recurring 1.5x bonuses every additional 30 completed shifts.
     * 3) Rolling windows are 30/60/90/120 and remain 120 for elite recurring milestones.
     * 4) Re-running awards is idempotent due unique candidate+year+block key.
     * 5) Historical bonus rows are never recalculated or overwritten.
     */
    public function rewards_award_bonus_if_needed($candidate_user_id, $academic_year_label, $actor_user_id = null) {
        $candidate_user_id = (int) $candidate_user_id;
        $actor_user_id = $this->resolve_rewards_actor_user_id($actor_user_id);
        if ($candidate_user_id < 1) {
            return new WP_Error('cmn_rewards_bonus_invalid_candidate_user', 'Candidate user is required for bonus calculation.');
        }

        $candidate_id = (int) $this->resolve_candidate_id_for_conduct_user($candidate_user_id);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_rewards_bonus_invalid_candidate', 'Candidate not found for bonus calculation.');
        }

        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year_label, current_time('Y-m-d'));
        if ($academic_year === '') {
            return new WP_Error('cmn_rewards_bonus_invalid_year', 'Academic year is required for bonus calculation.');
        }
        $rewards_label = $this->normalize_rewards_config_year_label($academic_year, current_time('Y-m-d'));
        if ($rewards_label === '') {
            return new WP_Error('cmn_rewards_bonus_invalid_year_label', 'Academic year label could not be resolved for bonus calculation.');
        }
        $config_row = $this->get_rewards_config_row_for_academic_year($academic_year, current_time('Y-m-d'));

        $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($rewards_row)) {
            return $rewards_row;
        }
        if (!is_array($rewards_row) || !$rewards_row) {
            return new WP_Error('cmn_rewards_bonus_missing_state', 'Candidate rewards state row is unavailable.');
        }

        $state_status = sanitize_key((string) ($rewards_row['status'] ?? ''));
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($rewards_row['conduct_status'] ?? 'clear'));
        if ($state_status === 'terminated' || $conduct_status === 'terminated') {
            return [
                'skipped' => true,
                'reason' => 'terminated',
                'awarded_count' => 0,
                'existing_count' => 0,
                'latest_award' => [],
                'row' => $rewards_row,
                'academic_year' => $academic_year,
                'academic_year_label' => $rewards_label,
            ];
        }
        if ($state_status === 'rewards_suspended') {
            return [
                'skipped' => true,
                'reason' => 'rewards_suspended',
                'awarded_count' => 0,
                'existing_count' => 0,
                'latest_award' => [],
                'row' => $rewards_row,
                'academic_year' => $academic_year,
                'academic_year_label' => $rewards_label,
            ];
        }

        $shifts_completed = (int) ($rewards_row['academic_year_shift_total'] ?? 0);
        $completed_block_index = $this->rewards_get_completed_block_index($shifts_completed);
        if ($completed_block_index <= 0) {
            return [
                'skipped' => true,
                'reason' => 'no_completed_blocks',
                'awarded_count' => 0,
                'existing_count' => 0,
                'latest_award' => [],
                'row' => $rewards_row,
                'academic_year' => $academic_year,
                'academic_year_label' => $rewards_label,
            ];
        }

        $awarded_count = 0;
        $existing_count = 0;
        $latest_award = [];
        for ($block_index = 1; $block_index <= $completed_block_index; $block_index++) {
            $existing_award = $this->get_candidate_bonus_award_row($candidate_user_id, $rewards_label, $block_index);
            if ($existing_award) {
                $existing_count++;
                $latest_award = $existing_award;
                continue;
            }

            $payload = $this->calculate_bonus_block_payload($candidate_user_id, $academic_year, $block_index);
            if (is_wp_error($payload)) {
                return $payload;
            }
            $rolling_window = max(1, (int) ($payload['rolling_window'] ?? $this->get_candidate_rewards_bonus_window_for_block($block_index, 4)));
            $multiplier = $this->get_candidate_rewards_bonus_multiplier_for_block($block_index, is_array($config_row) ? $config_row : [], 4);
            $average_day_pay = round((float) ($payload['average_day_pay'] ?? 0), 2);
            $bonus_amount = round($average_day_pay * $multiplier, 2);
            $milestone_shift_total = max($block_index * 30, (int) ($payload['milestone_shift_total'] ?? 0));
            $rolling_window_start_shift = max(1, ($milestone_shift_total - $rolling_window) + 1);
            $notes_payload = [
                'block_index' => $block_index,
                'block_start_shift' => (int) ($payload['block_start_shift'] ?? ((($block_index - 1) * 30) + 1)),
                'block_end_shift' => (int) ($payload['block_end_shift'] ?? ($block_index * 30)),
                'rolling_window_shifts' => $rolling_window,
                'rolling_window_start_shift' => $rolling_window_start_shift,
                'rolling_window_end_shift' => $milestone_shift_total,
                'milestone_shift_total' => $milestone_shift_total,
                'credit_ids' => array_values(array_filter(array_map('intval', (array) ($payload['credit_ids'] ?? [])))),
                'booking_day_refs' => array_values(array_map('strval', (array) ($payload['booking_day_refs'] ?? []))),
                'total_day_pay' => round((float) ($payload['total_day_pay'] ?? ($average_day_pay * $rolling_window)), 2),
                'pay_source' => 'booking_rates.candidate_pay_rate|booking_meta.cmn_candidate_pay_rate|booking_meta.cmn_rate',
            ];

            $insert = $this->insert_candidate_bonus_award([
                'candidate_user_id' => $candidate_user_id,
                'academic_year_label' => $rewards_label,
                'block_index' => $block_index,
                'block_start_shift' => (int) ($payload['block_start_shift'] ?? ((($block_index - 1) * 30) + 1)),
                'block_end_shift' => (int) ($payload['block_end_shift'] ?? ($block_index * 30)),
                'multiplier' => $multiplier,
                'average_day_pay' => $average_day_pay,
                'bonus_amount' => $bonus_amount,
                'status' => 'awarded',
                'awarded_at' => current_time('mysql'),
                'notes' => $notes_payload,
            ]);
            if (is_wp_error($insert)) {
                return $insert;
            }

            $latest_award = is_array($insert['row'] ?? null) ? $insert['row'] : [];
            if (!empty($insert['inserted'])) {
                $awarded_count++;
                $rewards_row = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
                    'last_bonus_awarded_at' => current_time('mysql'),
                    'last_bonus_amount' => $bonus_amount,
                ]);
                if (is_wp_error($rewards_row)) {
                    return $rewards_row;
                }

                if (function_exists('cmn_audit_log_event')) {
                    cmn_audit_log_event([
                        'module' => 'rewards',
                        'entity_type' => 'candidate',
                        'entity_id' => $candidate_user_id,
                        'event_type' => 'bonus_awarded',
                        'event_ref' => $rewards_label . ':' . $block_index,
                        'actor_user_id' => $actor_user_id,
                        'metadata' => [
                            'label' => $rewards_label,
                            'block_index' => $block_index,
                            'avg' => $average_day_pay,
                            'mult' => $multiplier,
                            'amount' => $bonus_amount,
                            'academic_year' => $academic_year,
                            'candidate_id' => $candidate_id,
                            'block_start_shift' => (int) ($payload['block_start_shift'] ?? ((($block_index - 1) * 30) + 1)),
                            'block_end_shift' => (int) ($payload['block_end_shift'] ?? ($block_index * 30)),
                            'rolling_window_shifts' => $rolling_window,
                            'rolling_window_start_shift' => $rolling_window_start_shift,
                            'rolling_window_end_shift' => $milestone_shift_total,
                            'milestone_shift_total' => $milestone_shift_total,
                        ],
                    ]);
                }
            } else {
                $existing_count++;
            }
        }

        return [
            'skipped' => false,
            'reason' => $awarded_count > 0 ? '' : 'no_new_blocks',
            'awarded_count' => $awarded_count,
            'existing_count' => $existing_count,
            'latest_award' => $latest_award,
            'row' => $rewards_row,
            'academic_year' => $academic_year,
            'academic_year_label' => $rewards_label,
        ];
    }

    /*
     * Prompt 8 acceptance checks:
     * 1) Re-running award engine never creates duplicate candidate/year/block awards.
     * 2) Voiding a previously credited shift inside an awarded block marks that award flagged_for_review.
     */
    private function maybe_flag_bonus_awards_for_voided_shift_credit($candidate_user_id, $academic_year_label, $credit_row, $actor_user_id = 0, $reason = '') {
        $candidate_user_id = (int) $candidate_user_id;
        $actor_user_id = max(0, (int) $actor_user_id);
        $reason = sanitize_text_field((string) $reason);
        $credit_row = is_array($credit_row) ? $credit_row : [];
        $credit_id = (int) ($credit_row['id'] ?? 0);
        $booking_id = (int) ($credit_row['booking_id'] ?? 0);
        $booking_day_date = $this->normalize_invoice_date((string) ($credit_row['booking_day_date'] ?? ''));
        if ($candidate_user_id < 1 || $credit_id < 1 || $booking_day_date === '') {
            return [
                'flagged_count' => 0,
                'checked_count' => 0,
            ];
        }

        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year_label, $booking_day_date);
        $rewards_label = $this->normalize_rewards_config_year_label($academic_year, $booking_day_date);
        if ($rewards_label === '') {
            return [
                'flagged_count' => 0,
                'checked_count' => 0,
            ];
        }

        global $wpdb;
        $table = $this->get_candidate_bonus_awards_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_user_id = %d
               AND academic_year_label = %s
               AND status = %s
             ORDER BY block_index ASC",
            $candidate_user_id,
            $rewards_label,
            'awarded'
        ), ARRAY_A);
        if (!is_array($rows) || !$rows) {
            return [
                'flagged_count' => 0,
                'checked_count' => 0,
            ];
        }

        $target_ref = $booking_id . ':' . $booking_day_date;
        $flagged_count = 0;
        $checked_count = 0;
        foreach ($rows as $award_row) {
            $checked_count++;
            $award_id = (int) ($award_row['id'] ?? 0);
            if ($award_id < 1) {
                continue;
            }

            $notes_payload = $this->decode_candidate_bonus_award_notes((string) ($award_row['notes'] ?? ''));
            $credit_ids = array_values(array_filter(array_map('intval', (array) ($notes_payload['credit_ids'] ?? []))));
            $refs = array_values(array_map('strval', (array) ($notes_payload['booking_day_refs'] ?? [])));
            $matched = in_array($credit_id, $credit_ids, true) || in_array($target_ref, $refs, true);
            if (!$matched) {
                continue;
            }

            $notes_payload['flagged_for_review'] = 1;
            $notes_payload['flagged_reason'] = $reason !== '' ? $reason : 'shift_credit_voided';
            $notes_payload['flagged_credit_id'] = $credit_id;
            $notes_payload['flagged_booking_id'] = $booking_id;
            $notes_payload['flagged_booking_day_date'] = $booking_day_date;
            $notes_payload['flagged_at'] = current_time('mysql');
            $notes_payload['flagged_by_user_id'] = $actor_user_id > 0 ? $actor_user_id : null;
            $notes_json = wp_json_encode($notes_payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            if (!is_string($notes_json)) {
                $notes_json = '';
            }

            $updated = $wpdb->query($wpdb->prepare(
                "UPDATE {$table}
                 SET status = %s,
                     notes = NULLIF(%s, '')
                 WHERE id = %d
                   AND status = %s",
                'flagged_for_review',
                $notes_json,
                $award_id,
                'awarded'
            ));
            if ($updated === false || (int) $updated < 1) {
                continue;
            }
            $flagged_count++;

            if (function_exists('cmn_audit_log_event')) {
                cmn_audit_log_event([
                    'module' => 'rewards',
                    'entity_type' => 'candidate',
                    'entity_id' => $candidate_user_id,
                    'event_type' => 'bonus_flagged_for_review',
                    'event_ref' => $rewards_label . ':' . ((int) ($award_row['block_index'] ?? 0)),
                    'actor_user_id' => $actor_user_id,
                    'metadata' => [
                        'academic_year_label' => $rewards_label,
                        'block_index' => (int) ($award_row['block_index'] ?? 0),
                        'booking_id' => $booking_id,
                        'date' => $booking_day_date,
                        'credit_id' => $credit_id,
                        'award_id' => $award_id,
                        'reason' => $reason,
                    ],
                ]);
            }
        }

        return [
            'flagged_count' => $flagged_count,
            'checked_count' => $checked_count,
        ];
    }

    private function get_referral_programme_academic_year_label($reference_date = '') {
        $reference_date = $this->normalize_invoice_date((string) $reference_date);
        if ($reference_date === '') {
            $reference_date = current_time('Y-m-d');
        }
        $label = $this->normalize_rewards_config_year_label('', $reference_date);
        if ($label !== '') {
            return $label;
        }
        $fallback_internal = $this->normalize_candidate_rewards_academic_year_label('', $reference_date);
        if (preg_match('/^(\d{4})-(\d{4})$/', $fallback_internal, $m) === 1) {
            $start = (int) $m[1];
            $end = (int) $m[2];
            if ($end === ($start + 1)) {
                return sprintf('%04d/%02d', $start, ($end % 100));
            }
        }
        $year = (int) date('Y');
        return sprintf('%04d/%02d', $year, (($year + 1) % 100));
    }

    private function get_referral_row_for_referred_user($referred_user_id) {
        $referred_user_id = (int) $referred_user_id;
        if ($referred_user_id < 1) {
            return [];
        }
        global $wpdb;
        $table = $this->get_candidate_referrals_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE referred_user_id = %d
             LIMIT 1",
            $referred_user_id
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function count_candidate_credited_shifts_total($candidate_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return 0;
        }
        global $wpdb;
        $table = $this->get_candidate_shift_credits_table();
        $count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM {$table}
             WHERE candidate_user_id = %d
               AND status = %s",
            $candidate_user_id,
            'credited'
        ));
        return max(0, $count);
    }

    private function is_referred_candidate_terminated_before_ticket($referred_user_id, $academic_year_label) {
        $referred_user_id = (int) $referred_user_id;
        $academic_year_label = trim((string) $academic_year_label);
        if ($referred_user_id < 1) {
            return false;
        }

        $candidate_id = (int) $this->get_candidate_id_for_user($referred_user_id);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return false;
        }

        $candidate_status = sanitize_key((string) get_post_meta($candidate_id, 'cmn_status', true));
        if (in_array($candidate_status, ['terminated', 'inactive', 'blocked'], true)) {
            return true;
        }

        $academic_year = $this->normalize_candidate_rewards_academic_year_label($academic_year_label, current_time('Y-m-d'));
        if ($academic_year === '') {
            return false;
        }
        $row = $this->get_candidate_rewards_record($candidate_id, $academic_year);
        if (!is_array($row) || !$row) {
            return false;
        }
        $state_status = sanitize_key((string) ($row['status'] ?? ''));
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($row['conduct_status'] ?? 'clear'));
        return $state_status === 'terminated' || $conduct_status === 'terminated';
    }

    /*
     * Prompt 9 acceptance checks:
     * 1) Self-referral is rejected.
     * 2) Duplicate referral for same referred user is blocked (idempotent if same relationship already exists).
     * 3) Invalid/unknown referral code returns WP_Error.
     */
    public function referrals_record_signup($referred_user_id, $referral_code) {
        $referred_user_id = (int) $referred_user_id;
        $referral_code = $this->normalize_candidate_referral_code($referral_code);
        if ($referred_user_id < 1) {
            return new WP_Error('cmn_referrals_invalid_referred_user', 'Referred candidate user is required.');
        }
        if ($referral_code === '') {
            return new WP_Error('cmn_referrals_invalid_code', 'Referral code is invalid.');
        }

        $referrer_user_id = $this->get_user_id_by_candidate_referral_code($referral_code);
        if ($referrer_user_id < 1) {
            return new WP_Error('cmn_referrals_code_not_found', 'Referral code not found.');
        }
        if ($referrer_user_id === $referred_user_id) {
            return new WP_Error('cmn_referrals_self_referral', 'Self-referrals are not allowed.');
        }
        $referrer_user = get_user_by('id', $referrer_user_id);
        if (!$referrer_user || !$referrer_user->ID) {
            return new WP_Error('cmn_referrals_referrer_missing', 'Referrer account could not be found.');
        }
        $referrer_roles = (array) $referrer_user->roles;
        if (!in_array('cmn_candidate', $referrer_roles, true) && !in_array('cmn_candidate_pending', $referrer_roles, true) && !in_array('candidate', $referrer_roles, true)) {
            return new WP_Error('cmn_referrals_referrer_not_candidate', 'Referral code is not assigned to a candidate account.');
        }

        if ($this->count_candidate_credited_shifts_total($referred_user_id) > 0) {
            return new WP_Error('cmn_referrals_too_late', 'Referral must be recorded before first credited shift.');
        }

        $existing = $this->get_referral_row_for_referred_user($referred_user_id);
        if ($existing) {
            $existing_referrer_user_id = (int) ($existing['referrer_user_id'] ?? 0);
            if ($existing_referrer_user_id === $referrer_user_id) {
                return [
                    'inserted' => false,
                    'duplicate' => true,
                    'row' => $existing,
                ];
            }
            return new WP_Error('cmn_referrals_duplicate_referred_user', 'A referral is already registered for this candidate.');
        }

        $academic_year_label = $this->get_referral_programme_academic_year_label(current_time('Y-m-d'));
        global $wpdb;
        $table = $this->get_candidate_referrals_table();
        $created_at = current_time('mysql');
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT INTO {$table}
            (referrer_user_id, referred_user_id, academic_year_label, status, qualified_at, created_at)
            VALUES
            (%d, %d, %s, %s, NULL, %s)",
            $referrer_user_id,
            $referred_user_id,
            $academic_year_label,
            'pending',
            $created_at
        ));
        if ($inserted === false) {
            $existing_retry = $this->get_referral_row_for_referred_user($referred_user_id);
            if ($existing_retry && (int) ($existing_retry['referrer_user_id'] ?? 0) === $referrer_user_id) {
                return [
                    'inserted' => false,
                    'duplicate' => true,
                    'row' => $existing_retry,
                ];
            }
            return new WP_Error('cmn_referrals_insert_failed', 'Unable to register referral.');
        }

        $row = $this->get_referral_row_for_referred_user($referred_user_id);
        if (!$row) {
            return new WP_Error('cmn_referrals_lookup_failed', 'Referral registered but could not be loaded.');
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'rewards',
                'entity_type' => 'candidate',
                'entity_id' => $referred_user_id,
                'event_type' => 'referral_registered',
                'event_ref' => (string) ((int) ($row['id'] ?? 0)),
                'actor_user_id' => (int) get_current_user_id(),
                'metadata' => [
                    'referrer' => $referrer_user_id,
                    'referred' => $referred_user_id,
                    'year' => $academic_year_label,
                    'referral_code' => $referral_code,
                ],
            ]);
        }

        return [
            'inserted' => true,
            'duplicate' => false,
            'row' => $row,
        ];
    }

    /*
     * Prompt 9 acceptance checks:
     * 1) Referred candidate first credited shift creates one ticket for referrer.
     * 2) Additional shifts are idempotent and do not create duplicate tickets.
     * 3) If referred candidate is terminated before first shift, referral is marked invalid and no ticket is created.
     */
    private function maybe_qualify_referral_after_first_shift($referred_user_id, $shift_date, $actor_user_id = 0) {
        $referred_user_id = (int) $referred_user_id;
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $actor_user_id = max(0, (int) $actor_user_id);
        if ($referred_user_id < 1) {
            return [
                'qualified' => false,
                'reason' => 'missing_referred_user',
            ];
        }
        if ($shift_date === '') {
            $shift_date = current_time('Y-m-d');
        }

        $referral = $this->get_referral_row_for_referred_user($referred_user_id);
        if (!$referral) {
            return [
                'qualified' => false,
                'reason' => 'no_referral',
            ];
        }
        $referral_id = (int) ($referral['id'] ?? 0);
        $referrer_user_id = (int) ($referral['referrer_user_id'] ?? 0);
        $academic_year_label = trim((string) ($referral['academic_year_label'] ?? ''));
        if ($referral_id < 1 || $referrer_user_id < 1 || $academic_year_label === '') {
            return [
                'qualified' => false,
                'reason' => 'invalid_referral',
            ];
        }

        $status = sanitize_key((string) ($referral['status'] ?? 'pending'));
        if ($status === 'invalid') {
            return [
                'qualified' => false,
                'reason' => 'invalid',
            ];
        }

        if ($this->is_referred_candidate_terminated_before_ticket($referred_user_id, $academic_year_label)) {
            if ($status === 'pending') {
                global $wpdb;
                $table = $this->get_candidate_referrals_table();
                $wpdb->query($wpdb->prepare(
                    "UPDATE {$table}
                     SET status = %s
                     WHERE id = %d
                       AND status = %s",
                    'invalid',
                    $referral_id,
                    'pending'
                ));
            }
            return [
                'qualified' => false,
                'reason' => 'terminated_before_first_shift',
            ];
        }

        if ($this->count_candidate_credited_shifts_total($referred_user_id) < 1) {
            return [
                'qualified' => false,
                'reason' => 'first_shift_not_completed',
            ];
        }

        global $wpdb;
        $referrals_table = $this->get_candidate_referrals_table();
        $tickets_table = $this->get_candidate_referral_tickets_table();
        $qualified_at = current_time('mysql');

        $wpdb->query($wpdb->prepare(
            "UPDATE {$referrals_table}
             SET status = %s,
                 qualified_at = %s
             WHERE id = %d
               AND status = %s",
            'qualified',
            $qualified_at,
            $referral_id,
            'pending'
        ));

        $ticket_inserted = $wpdb->query($wpdb->prepare(
            "INSERT IGNORE INTO {$tickets_table}
            (candidate_user_id, academic_year_label, referral_id, awarded_at)
            VALUES
            (%d, %s, %d, %s)",
            $referrer_user_id,
            $academic_year_label,
            $referral_id,
            $qualified_at
        ));
        if ($ticket_inserted === false) {
            return new WP_Error('cmn_referrals_ticket_insert_failed', 'Unable to award referral ticket.');
        }

        $ticket_id = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id
             FROM {$tickets_table}
             WHERE referral_id = %d
             LIMIT 1",
            $referral_id
        ));
        if ($ticket_id < 1) {
            return new WP_Error('cmn_referrals_ticket_lookup_failed', 'Referral ticket could not be loaded.');
        }

        $ticket_was_new = ((int) $ticket_inserted) > 0;
        if ($ticket_was_new && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'rewards',
                'entity_type' => 'candidate',
                'entity_id' => $referrer_user_id,
                'event_type' => 'referral_ticket_awarded',
                'event_ref' => (string) $referral_id,
                'actor_user_id' => $actor_user_id,
                'metadata' => [
                    'referrer' => $referrer_user_id,
                    'referred' => $referred_user_id,
                    'year' => $academic_year_label,
                    'ticket_id' => $ticket_id,
                    'referral_id' => $referral_id,
                    'qualified_at' => $qualified_at,
                    'first_shift_date' => $shift_date,
                ],
            ]);
        }

        return [
            'qualified' => true,
            'ticket_created' => $ticket_was_new,
            'ticket_id' => $ticket_id,
            'referral_id' => $referral_id,
            'referrer_user_id' => $referrer_user_id,
            'referred_user_id' => $referred_user_id,
            'academic_year_label' => $academic_year_label,
        ];
    }

    /*
     * Prompt 9 acceptance checks:
     * 1) Ticket count is scoped per candidate and academic year.
     * 2) Additional shifts after qualification do not increase ticket count for same referral.
     */
    public function referrals_get_ticket_count($candidate_user_id, $academic_year_label) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return 0;
        }
        $provided_label = trim((string) $academic_year_label);
        if ($provided_label === '') {
            $academic_year_label = $this->get_referral_programme_academic_year_label(current_time('Y-m-d'));
        } else {
            $normalized_label = $this->normalize_rewards_config_year_label($provided_label, current_time('Y-m-d'));
            $academic_year_label = $normalized_label !== '' ? $normalized_label : $this->get_referral_programme_academic_year_label(current_time('Y-m-d'));
        }

        global $wpdb;
        $table = $this->get_candidate_referral_tickets_table();
        $count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM {$table}
             WHERE candidate_user_id = %d
               AND academic_year_label = %s",
            $candidate_user_id,
            $academic_year_label
        ));
        return max(0, $count);
    }

    private function get_candidate_rewards_cycle_shift_completed_events($candidate_id, $academic_year, $required_count = 30) {
        $candidate_id = (int) $candidate_id;
        $required_count = max(1, (int) $required_count);
        if ($candidate_id < 1) {
            return [];
        }
        $bounds = $this->get_candidate_rewards_academic_year_bounds($academic_year);
        $start_date = (string) ($bounds['start_date'] ?? '');
        $end_date = (string) ($bounds['end_date'] ?? '');
        if ($start_date === '' || $end_date === '') {
            return [];
        }

        $scan_limit = max(120, $required_count * 8);
        $scan_limit = min(2000, $scan_limit);
        global $wpdb;
        $table = $this->get_candidate_rewards_events_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT id, candidate_id, booking_id, shift_date, event_type, delta_cycle, delta_year_total, meta, created_at
             FROM {$table}
             WHERE candidate_id = %d
               AND event_type = %s
               AND delta_cycle > 0
               AND shift_date >= %s
               AND shift_date <= %s
             ORDER BY shift_date DESC, id DESC
             LIMIT %d",
            $candidate_id,
            'shift_completed',
            $start_date,
            $end_date,
            $scan_limit
        ), ARRAY_A);
        if (!is_array($rows) || !$rows) {
            return [];
        }

        $eligible = [];
        foreach ($rows as $row) {
            $shift_date = $this->normalize_invoice_date((string) ($row['shift_date'] ?? ''));
            if ($shift_date === '' || $this->is_candidate_rewards_august_shift_date($shift_date)) {
                continue;
            }
            $booking_id = (int) ($row['booking_id'] ?? 0);
            if ($booking_id < 1) {
                continue;
            }
            $meta = $this->decode_candidate_rewards_event_meta($row['meta'] ?? '');
            if ($this->candidate_rewards_meta_flag_is_true($meta['paused'] ?? false)) {
                continue;
            }
            if ($this->candidate_rewards_meta_flag_is_true($meta['reversed'] ?? false)) {
                continue;
            }
            $row['_meta'] = $meta;
            $eligible[] = $row;
            if (count($eligible) >= $required_count) {
                break;
            }
        }
        return $eligible;
    }

    private function get_candidate_rewards_daily_pay_for_shift_event($candidate_id, $event_row) {
        $candidate_id = (int) $candidate_id;
        $event_row = is_array($event_row) ? $event_row : [];
        $booking_id = (int) ($event_row['booking_id'] ?? 0);
        if ($candidate_id < 1 || $booking_id < 1) {
            return new WP_Error('cmn_candidate_rewards_bonus_invalid_event_context', 'Invalid event context while calculating candidate bonus.');
        }
        $booking_candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($booking_candidate_id > 0 && $booking_candidate_id !== $candidate_id) {
            return new WP_Error('cmn_candidate_rewards_bonus_candidate_mismatch', 'Booking does not belong to candidate for bonus calculation.');
        }

        $rate_row = $this->get_booking_rate_row($booking_id);
        $candidate_pay = (float) ($rate_row['candidate_pay_rate'] ?? 0);
        if ($candidate_pay <= 0) {
            $candidate_pay = (float) get_post_meta($booking_id, 'cmn_candidate_pay_rate', true);
        }
        if ($candidate_pay <= 0) {
            $candidate_pay = (float) get_post_meta($booking_id, 'cmn_rate', true);
        }
        $candidate_pay = round($candidate_pay, 2);
        if ($candidate_pay <= 0) {
            return new WP_Error('cmn_candidate_rewards_bonus_missing_pay_rate', 'Candidate pay rate missing for booking-day in bonus cycle.');
        }
        return $candidate_pay;
    }

    private function get_candidate_rewards_next_cycle_number($candidate_id, $academic_year) {
        $candidate_id = (int) $candidate_id;
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year);
        if ($candidate_id < 1 || $academic_year === '') {
            return 1;
        }
        global $wpdb;
        $table = $this->get_candidate_reward_payouts_table();
        $max_cycle = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT MAX(cycle_number)
             FROM {$table}
             WHERE candidate_id = %d
               AND academic_year = %s",
            $candidate_id,
            $academic_year
        ));
        return max(1, $max_cycle + 1);
    }

    private function build_candidate_rewards_cycle_bonus_payload($candidate_id, $academic_year, $required_shifts = 30) {
        $candidate_id = (int) $candidate_id;
        $required_shifts = max(1, (int) $required_shifts);
        if ($candidate_id < 1) {
            return new WP_Error('cmn_candidate_rewards_bonus_invalid_candidate', 'Invalid candidate for bonus payload.');
        }
        $events = $this->get_candidate_rewards_cycle_shift_completed_events($candidate_id, $academic_year, $required_shifts);
        if (count($events) < $required_shifts) {
            return new WP_Error('cmn_candidate_rewards_bonus_insufficient_shifts', 'Insufficient eligible completed payable shifts for 30-shift bonus calculation.');
        }

        $total_gross_pay_cycle = 0.00;
        foreach ($events as $event_row) {
            $daily_pay = $this->get_candidate_rewards_daily_pay_for_shift_event($candidate_id, $event_row);
            if (is_wp_error($daily_pay)) {
                return $daily_pay;
            }
            $total_gross_pay_cycle += (float) $daily_pay;
        }
        $total_gross_pay_cycle = round($total_gross_pay_cycle, 2);
        $average_daily_pay = round($total_gross_pay_cycle / $required_shifts, 2);

        return [
            'events' => $events,
            'total_gross_pay_cycle' => $total_gross_pay_cycle,
            'average_daily_pay' => $average_daily_pay,
            'shifts_in_cycle' => $required_shifts,
        ];
    }

    private function maybe_trigger_candidate_rewards_cycle_bonus($candidate_id, $booking_id, $shift_date, $academic_year, $rewards_row = [], $context = []) {
        $candidate_id = (int) $candidate_id;
        $booking_id = max(0, (int) $booking_id);
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, $shift_date);
        $context = is_array($context) ? $context : [];
        if ($candidate_id < 1 || $booking_id < 1 || $shift_date === '' || $academic_year === '') {
            return new WP_Error('cmn_candidate_rewards_bonus_invalid_input', 'Invalid candidate bonus trigger input.');
        }
        if (!is_array($rewards_row) || !$rewards_row) {
            $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
            if (is_wp_error($rewards_row)) {
                return $rewards_row;
            }
        }

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            return new WP_Error('cmn_candidate_rewards_bonus_missing_candidate_user', 'Candidate user account is required for bonus calculation.');
        }

        $actor_user_id = max(0, (int) ($context['created_by_user_id'] ?? 0));
        $award_result = $this->rewards_award_bonus_if_needed($candidate_user_id, $academic_year, $actor_user_id);
        if (is_wp_error($award_result)) {
            return $award_result;
        }

        $latest_award = is_array($award_result['latest_award'] ?? null) ? $award_result['latest_award'] : [];
        $row_after = is_array($award_result['row'] ?? null) ? $award_result['row'] : $rewards_row;
        $triggered = !empty($award_result['awarded_count']);
        $duplicate = !$triggered && ((int) ($award_result['existing_count'] ?? 0)) > 0;
        $reason = $triggered ? '' : sanitize_key((string) ($award_result['reason'] ?? 'no_new_blocks'));
        $average_daily_pay = round((float) ($latest_award['average_day_pay'] ?? 0), 2);
        $bonus_amount = round((float) ($latest_award['bonus_amount'] ?? 0), 2);
        $block_index = (int) ($latest_award['block_index'] ?? 0);
        $multiplier = round((float) ($latest_award['multiplier'] ?? 0), 2);
        if ($multiplier <= 0 && $block_index > 0) {
            $multiplier = $this->rewards_block_multiplier($block_index, 4);
        }
        $award_notes = $this->decode_candidate_bonus_award_notes((string) ($latest_award['notes'] ?? ''));
        $rolling_window = max(1, (int) ($award_notes['rolling_window_shifts'] ?? ($block_index > 0 ? $this->get_candidate_rewards_bonus_window_for_block($block_index, 4) : 30)));

        return [
            'triggered' => $triggered,
            'duplicate' => $duplicate,
            'skipped' => !$triggered,
            'reason' => $reason,
            'event_id' => (int) ($latest_award['id'] ?? 0),
            'cycle_reset_event_id' => 0,
            'payout_id' => 0,
            'cycle_number' => $block_index,
            'cycle_target' => 30,
            'shift_cycle_count_at_trigger' => (int) ($rewards_row['shift_cycle_count'] ?? 0),
            'tier' => $this->normalize_candidate_rewards_tier((string) ($row_after['tier'] ?? ($rewards_row['tier'] ?? 'standard'))),
            'multiplier' => $multiplier,
            'total_gross_pay_cycle' => round($average_daily_pay * $rolling_window, 2),
            'average_daily_pay' => $average_daily_pay,
            'bonus_amount' => $bonus_amount,
            'row' => $row_after,
        ];
    }

    private function normalize_candidate_rewards_tier($tier) {
        $tier = sanitize_key((string) $tier);
        $map = $this->get_candidate_rewards_tier_multiplier_map();
        if (!array_key_exists($tier, $map)) {
            return 'standard';
        }
        return $tier;
    }

    private function get_candidate_rewards_multiplier_for_tier($tier) {
        $tier = $this->normalize_candidate_rewards_tier($tier);
        $map = $this->get_candidate_rewards_tier_multiplier_map();
        return round((float) ($map[$tier] ?? 1.00), 2);
    }

    private function normalize_candidate_rewards_conduct_status($status) {
        $status = sanitize_key((string) $status);
        $allowed = ['clear', 'yellow', 'red', 'terminated'];
        if (!in_array($status, $allowed, true)) {
            return 'clear';
        }
        return $status;
    }

    private function normalize_candidate_rewards_payout_status($status) {
        $status = sanitize_key((string) $status);
        $allowed = ['queued', 'included', 'processed', 'void'];
        if (!in_array($status, $allowed, true)) {
            return 'queued';
        }
        return $status;
    }

    private function get_candidate_rewards_academic_year_context($reference_date = '') {
        $context = $this->resolve_cmn_academic_year_context($reference_date !== '' ? $reference_date : 'now');
        return [
            'reference_date' => (string) ($context['reference_date'] ?? current_time('Y-m-d')),
            'start_year' => (int) ($context['start_year'] ?? 0),
            'label' => (string) ($context['label'] ?? ''),
            'start_date' => (string) ($context['start_date'] ?? ''),
            'end_date' => (string) ($context['end_date'] ?? ''),
            'is_august' => !empty($context['is_august']),
        ];
    }

    private function normalize_candidate_rewards_academic_year_label($academic_year = '', $reference_date = '') {
        $academic_year = sanitize_text_field((string) $academic_year);
        if (preg_match('/^(\d{4})\/(\d{2})$/', $academic_year, $m) === 1) {
            $start = (int) $m[1];
            $expected_end_short = ($start + 1) % 100;
            if ((int) $m[2] === $expected_end_short) {
                return sprintf('%04d-%04d', $start, ($start + 1));
            }
        }
        if (preg_match('/^(\d{4})-(\d{4})$/', $academic_year, $m) === 1) {
            $start = (int) $m[1];
            $end = (int) $m[2];
            if ($end === ($start + 1)) {
                return sprintf('%04d-%04d', $start, $end);
            }
        }
        $context = $this->get_candidate_rewards_academic_year_context($reference_date);
        $label = (string) ($context['label'] ?? '');
        if (preg_match('/^\d{4}-\d{4}$/', $label) === 1) {
            return $label;
        }
        $year = (int) current_time('Y');
        return sprintf('%04d-%04d', $year, $year + 1);
    }

    private function get_candidate_rewards_academic_year_bounds($academic_year = '', $reference_date = '') {
        $label = $this->normalize_candidate_rewards_academic_year_label($academic_year, $reference_date);
        if (preg_match('/^(\d{4})-(\d{4})$/', $label, $m) === 1) {
            $start_year = (int) $m[1];
            $end_year = (int) $m[2];
            if ($end_year === ($start_year + 1)) {
                return [
                    'label' => $label,
                    'start_date' => sprintf('%04d-09-01', $start_year),
                    'end_date' => sprintf('%04d-07-31', $end_year),
                ];
            }
        }
        $context = $this->get_candidate_rewards_academic_year_context($reference_date);
        return [
            'label' => (string) ($context['label'] ?? $label),
            'start_date' => (string) ($context['start_date'] ?? ''),
            'end_date' => (string) ($context['end_date'] ?? ''),
        ];
    }

    private function normalize_candidate_rewards_meta_json($meta) {
        if ($meta === null) {
            return '';
        }
        if (is_string($meta)) {
            $meta = trim($meta);
            if ($meta === '') {
                return '';
            }
            $decoded = json_decode($meta, true);
            if (json_last_error() === JSON_ERROR_NONE) {
                $encoded = wp_json_encode($decoded, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
                return is_string($encoded) ? $encoded : '{}';
            }
            $encoded = wp_json_encode(['raw' => $meta], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
            return is_string($encoded) ? $encoded : '{}';
        }
        if (is_array($meta) || is_object($meta)) {
            $encoded = wp_json_encode($meta, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
            return is_string($encoded) ? $encoded : '{}';
        }
        $encoded = wp_json_encode(['value' => $meta], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        return is_string($encoded) ? $encoded : '{}';
    }

    private function is_valid_candidate_rewards_candidate($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return false;
        }
        return get_post_type($candidate_id) === 'cmn_candidate';
    }

    public function get_candidate_rewards_record($candidate_id, $academic_year = '') {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return [];
        }
        $academic_year = $this->normalize_candidate_rewards_academic_year_label($academic_year);
        global $wpdb;
        $table = $this->get_candidate_rewards_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_id = %d
               AND academic_year = %s
             LIMIT 1",
            $candidate_id,
            $academic_year
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    public function get_or_create_candidate_rewards($candidate_id, $academic_year = '') {
        $candidate_id = (int) $candidate_id;
        if (!$this->is_valid_candidate_rewards_candidate($candidate_id)) {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Invalid candidate for CMN Rewards.');
        }
        $bounds = $this->get_candidate_rewards_academic_year_bounds($academic_year);
        $academic_year = (string) ($bounds['label'] ?? '');
        if ($academic_year === '') {
            return new WP_Error('cmn_candidate_rewards_invalid_year', 'Invalid academic year for CMN Rewards.');
        }

        $existing = $this->get_candidate_rewards_record($candidate_id, $academic_year);
        if (!empty($existing)) {
            return $existing;
        }

        $now = current_time('mysql');
        $tier = 'standard';
        $multiplier = $this->get_candidate_rewards_multiplier_for_tier($tier);
        global $wpdb;
        $table = $this->get_candidate_rewards_table();
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT INTO {$table}
            (candidate_id, academic_year, shift_cycle_count, academic_year_shift_total, tier, multiplier, no_show_count, conduct_status, rewards_paused, review_required, probation_consecutive_shifts, last_bonus_paid_at, created_at, updated_at)
            VALUES
            (%d, %s, %d, %d, %s, %f, %d, %s, %d, %d, %d, NULL, %s, %s)",
            $candidate_id,
            $academic_year,
            0,
            0,
            $tier,
            $multiplier,
            0,
            'clear',
            0,
            0,
            0,
            $now,
            $now
        ));
        if ($inserted === false) {
            $existing = $this->get_candidate_rewards_record($candidate_id, $academic_year);
            if (!empty($existing)) {
                return $existing;
            }
            return new WP_Error('cmn_candidate_rewards_create_failed', 'Unable to create candidate rewards row.');
        }

        return $this->get_candidate_rewards_record($candidate_id, $academic_year);
    }

    public function update_candidate_rewards_record($candidate_id, $academic_year, $updates = []) {
        $candidate_id = (int) $candidate_id;
        if (!$this->is_valid_candidate_rewards_candidate($candidate_id)) {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Invalid candidate for CMN Rewards.');
        }
        $updates = is_array($updates) ? $updates : [];
        $bounds = $this->get_candidate_rewards_academic_year_bounds($academic_year);
        $academic_year = (string) ($bounds['label'] ?? '');
        if ($academic_year === '') {
            return new WP_Error('cmn_candidate_rewards_invalid_year', 'Invalid academic year for CMN Rewards.');
        }

        $existing = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($existing)) {
            return $existing;
        }

        $data = [];
        $formats = [];
        if (array_key_exists('shift_cycle_count', $updates)) {
            $data['shift_cycle_count'] = (int) $updates['shift_cycle_count'];
            $formats[] = '%d';
        }
        if (array_key_exists('academic_year_shift_total', $updates)) {
            $data['academic_year_shift_total'] = max(0, (int) $updates['academic_year_shift_total']);
            $formats[] = '%d';
        }
        if (array_key_exists('tier', $updates)) {
            $data['tier'] = $this->normalize_candidate_rewards_tier((string) $updates['tier']);
            $formats[] = '%s';
            if (!array_key_exists('multiplier', $updates)) {
                $data['multiplier'] = $this->get_candidate_rewards_multiplier_for_tier((string) $data['tier']);
                $formats[] = '%f';
            }
        }
        if (array_key_exists('multiplier', $updates)) {
            $multiplier_value = round((float) $updates['multiplier'], 2);
            if ($multiplier_value <= 0) {
                $tier_for_multiplier = (string) ($data['tier'] ?? ($existing['tier'] ?? 'standard'));
                $multiplier_value = $this->get_candidate_rewards_multiplier_for_tier($tier_for_multiplier);
            }
            $data['multiplier'] = $multiplier_value;
            $formats[] = '%f';
        }
        if (array_key_exists('last_tier_change_at', $updates)) {
            $last_tier_change_at = $this->normalize_invoice_datetime((string) $updates['last_tier_change_at']);
            $data['last_tier_change_at'] = $last_tier_change_at !== '' ? $last_tier_change_at : null;
            $formats[] = '%s';
        }
        if (array_key_exists('no_show_count', $updates)) {
            $data['no_show_count'] = max(0, (int) $updates['no_show_count']);
            $formats[] = '%d';
        }
        if (array_key_exists('conduct_status', $updates)) {
            $data['conduct_status'] = $this->normalize_candidate_rewards_conduct_status((string) $updates['conduct_status']);
            $formats[] = '%s';
        }
        if (array_key_exists('rewards_paused', $updates)) {
            $data['rewards_paused'] = !empty($updates['rewards_paused']) ? 1 : 0;
            $formats[] = '%d';
        }
        if (array_key_exists('review_required', $updates)) {
            $data['review_required'] = !empty($updates['review_required']) ? 1 : 0;
            $formats[] = '%d';
        }
        if (array_key_exists('probation_consecutive_shifts', $updates)) {
            $data['probation_consecutive_shifts'] = max(0, (int) $updates['probation_consecutive_shifts']);
            $formats[] = '%d';
        }
        if (array_key_exists('last_bonus_paid_at', $updates)) {
            $last_bonus_paid_at = $this->normalize_invoice_datetime((string) $updates['last_bonus_paid_at']);
            $data['last_bonus_paid_at'] = $last_bonus_paid_at !== '' ? $last_bonus_paid_at : null;
            $formats[] = '%s';
        }
        if (array_key_exists('last_bonus_awarded_at', $updates)) {
            $last_bonus_awarded_at = $this->normalize_invoice_datetime((string) $updates['last_bonus_awarded_at']);
            $data['last_bonus_awarded_at'] = $last_bonus_awarded_at !== '' ? $last_bonus_awarded_at : null;
            $formats[] = '%s';
        }
        if (array_key_exists('last_bonus_amount', $updates)) {
            $data['last_bonus_amount'] = round(max(0, (float) $updates['last_bonus_amount']), 2);
            $formats[] = '%f';
        }

        if (!$data) {
            return $this->get_candidate_rewards_record($candidate_id, $academic_year);
        }

        $data['updated_at'] = current_time('mysql');
        $formats[] = '%s';
        global $wpdb;
        $table = $this->get_candidate_rewards_table();
        $updated = $wpdb->update(
            $table,
            $data,
            [
                'candidate_id' => $candidate_id,
                'academic_year' => $academic_year,
            ],
            $formats,
            ['%d', '%s']
        );
        if ($updated === false) {
            return new WP_Error('cmn_candidate_rewards_update_failed', 'Unable to update candidate rewards row.');
        }

        return $this->get_candidate_rewards_record($candidate_id, $academic_year);
    }

    public function insert_candidate_rewards_event($event_data = []) {
        $event_data = is_array($event_data) ? $event_data : [];
        $candidate_id = (int) ($event_data['candidate_id'] ?? 0);
        if (!$this->is_valid_candidate_rewards_candidate($candidate_id)) {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Invalid candidate for rewards event.');
        }
        $booking_id = max(0, (int) ($event_data['booking_id'] ?? 0));
        $shift_date = $this->normalize_invoice_date((string) ($event_data['shift_date'] ?? ''));
        if ($shift_date === '') {
            return new WP_Error('cmn_candidate_rewards_invalid_shift_date', 'Rewards event requires a valid shift date.');
        }
        $event_type = substr(sanitize_key((string) ($event_data['event_type'] ?? '')), 0, 32);
        if ($event_type === '') {
            return new WP_Error('cmn_candidate_rewards_invalid_event_type', 'Rewards event requires a valid event type.');
        }
        $delta_cycle = (int) ($event_data['delta_cycle'] ?? 0);
        $delta_year_total = (int) ($event_data['delta_year_total'] ?? 0);
        $meta_json = $this->normalize_candidate_rewards_meta_json($event_data['meta'] ?? '');
        $created_by_user_id = (int) ($event_data['created_by_user_id'] ?? 0);
        $created_at = current_time('mysql');

        global $wpdb;
        $table = $this->get_candidate_rewards_events_table();
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT IGNORE INTO {$table}
            (candidate_id, booking_id, shift_date, event_type, delta_cycle, delta_year_total, meta, created_by_user_id, created_at)
            VALUES
            (%d, %d, %s, %s, %d, %d, NULLIF(%s, ''), NULLIF(%d, 0), %s)",
            $candidate_id,
            $booking_id,
            $shift_date,
            $event_type,
            $delta_cycle,
            $delta_year_total,
            $meta_json,
            $created_by_user_id,
            $created_at
        ));
        if ($inserted === false) {
            return new WP_Error('cmn_candidate_rewards_event_insert_failed', 'Unable to save candidate rewards event.');
        }
        if ((int) $inserted === 0) {
            $existing_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id
                 FROM {$table}
                 WHERE candidate_id = %d
                   AND booking_id = %d
                   AND shift_date = %s
                   AND event_type = %s
                 LIMIT 1",
                $candidate_id,
                $booking_id,
                $shift_date,
                $event_type
            ));
            return [
                'event_id' => $existing_id,
                'inserted' => false,
                'duplicate' => true,
            ];
        }

        return [
            'event_id' => (int) $wpdb->insert_id,
            'inserted' => true,
            'duplicate' => false,
        ];
    }

    public function get_candidate_rewards_events($candidate_id, $academic_year = '', $limit = 100) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return [];
        }
        $limit = max(1, min(500, (int) $limit));
        $bounds = $this->get_candidate_rewards_academic_year_bounds($academic_year);
        $start_date = (string) ($bounds['start_date'] ?? '');
        $end_date = (string) ($bounds['end_date'] ?? '');
        if ($start_date === '' || $end_date === '') {
            return [];
        }
        global $wpdb;
        $table = $this->get_candidate_rewards_events_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_id = %d
               AND shift_date >= %s
               AND shift_date <= %s
             ORDER BY shift_date DESC, id DESC
             LIMIT %d",
            $candidate_id,
            $start_date,
            $end_date,
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    public function insert_candidate_reward_payout($payout_data = []) {
        $payout_data = is_array($payout_data) ? $payout_data : [];
        $candidate_id = (int) ($payout_data['candidate_id'] ?? 0);
        if (!$this->is_valid_candidate_rewards_candidate($candidate_id)) {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Invalid candidate for rewards payout.');
        }
        $bounds = $this->get_candidate_rewards_academic_year_bounds((string) ($payout_data['academic_year'] ?? ''));
        $academic_year = (string) ($bounds['label'] ?? '');
        if ($academic_year === '') {
            return new WP_Error('cmn_candidate_rewards_invalid_year', 'Invalid academic year for rewards payout.');
        }

        $cycle_number = max(0, (int) ($payout_data['cycle_number'] ?? 0));
        $shifts_in_cycle = max(1, (int) ($payout_data['shifts_in_cycle'] ?? 30));
        $total_gross_pay_cycle = round(max(0, (float) ($payout_data['total_gross_pay_cycle'] ?? 0)), 2);
        $average_daily_pay = round(max(0, (float) ($payout_data['average_daily_pay'] ?? 0)), 2);
        $bonus_amount = round(max(0, (float) ($payout_data['bonus_amount'] ?? 0)), 2);
        $payroll_week_start = $this->normalize_invoice_date((string) ($payout_data['payroll_week_start'] ?? ''));
        $status = $this->normalize_candidate_rewards_payout_status((string) ($payout_data['status'] ?? 'queued'));

        $multiplier_applied = round((float) ($payout_data['multiplier_applied'] ?? 0), 2);
        if ($multiplier_applied <= 0) {
            $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
            if (is_wp_error($rewards_row)) {
                return $rewards_row;
            }
            $tier = (string) ($rewards_row['tier'] ?? 'standard');
            $multiplier_applied = $this->get_candidate_rewards_multiplier_for_tier($tier);
        }

        global $wpdb;
        $table = $this->get_candidate_reward_payouts_table();
        $now = current_time('mysql');
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT INTO {$table}
            (candidate_id, academic_year, cycle_number, shifts_in_cycle, total_gross_pay_cycle, average_daily_pay, multiplier_applied, bonus_amount, payroll_week_start, status, created_at, updated_at)
            VALUES
            (%d, %s, %d, %d, %f, %f, %f, %f, NULLIF(%s, ''), %s, %s, %s)",
            $candidate_id,
            $academic_year,
            $cycle_number,
            $shifts_in_cycle,
            $total_gross_pay_cycle,
            $average_daily_pay,
            $multiplier_applied,
            $bonus_amount,
            $payroll_week_start,
            $status,
            $now,
            $now
        ));
        if ($inserted === false) {
            return new WP_Error('cmn_candidate_rewards_payout_insert_failed', 'Unable to save candidate rewards payout.');
        }
        return [
            'payout_id' => (int) $wpdb->insert_id,
            'candidate_id' => $candidate_id,
            'academic_year' => $academic_year,
        ];
    }

    public function get_candidate_reward_payouts($candidate_id, $academic_year = '', $limit = 100) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return [];
        }
        $limit = max(1, min(500, (int) $limit));
        $academic_year = $this->normalize_candidate_rewards_academic_year_label($academic_year);
        global $wpdb;
        $table = $this->get_candidate_reward_payouts_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_id = %d
               AND academic_year = %s
             ORDER BY id DESC
             LIMIT %d",
            $candidate_id,
            $academic_year,
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function get_candidate_rewards_tier_label($tier) {
        $tier = $this->normalize_candidate_rewards_tier($tier);
        return ucfirst($tier);
    }

    private function get_candidate_rewards_conduct_status_label($status) {
        $status = $this->normalize_candidate_rewards_conduct_status($status);
        $labels = [
            'clear' => 'Clear',
            'yellow' => 'Yellow Card',
            'red' => 'Red Card',
            'terminated' => 'Terminated',
        ];
        return (string) ($labels[$status] ?? 'Clear');
    }

    private function get_candidate_rewards_safe_event_types() {
        return [
            'shift_completed',
            'shift_voided',
            'tier_updated',
            'bonus_triggered',
            'cycle_reset',
            'bonus_included_in_payroll',
            'bonus_paid',
            'no_show_confirmed',
            'no_show_reversed',
            'penalty_applied',
            'penalty_reversed',
            'probation_shift_completed',
            'probation_reset',
            'rewards_reinstated',
            'rewards_reinstated_override',
            'review_required',
            'candidate_terminated',
            'termination_reversed',
        ];
    }

    private function get_candidate_rewards_event_label($event_type) {
        $event_type = sanitize_key((string) $event_type);
        $labels = [
            'shift_completed' => 'Completed shift',
            'shift_voided' => 'Shift voided',
            'tier_updated' => 'Tier updated',
            'bonus_triggered' => 'Bonus triggered',
            'cycle_reset' => 'Bonus cycle reset',
            'bonus_included_in_payroll' => 'Bonus queued for payroll',
            'bonus_paid' => 'Bonus paid',
            'no_show_confirmed' => 'No-show confirmed',
            'no_show_reversed' => 'No-show reversed',
            'penalty_applied' => 'No-show penalty applied',
            'penalty_reversed' => 'No-show penalty reversed',
            'probation_shift_completed' => 'Probation shift completed',
            'probation_reset' => 'Probation reset',
            'rewards_reinstated' => 'Rewards reinstated',
            'rewards_reinstated_override' => 'Rewards reinstated by override',
            'review_required' => 'Senior review required',
            'candidate_terminated' => 'Rewards account terminated',
            'termination_reversed' => 'Termination reversed',
        ];
        return (string) ($labels[$event_type] ?? ucfirst(str_replace('_', ' ', $event_type)));
    }

    private function build_candidate_rewards_event_summary($event_row = []) {
        $event_row = is_array($event_row) ? $event_row : [];
        $event_type = sanitize_key((string) ($event_row['event_type'] ?? ''));
        $label = $this->get_candidate_rewards_event_label($event_type);
        $meta = $this->decode_candidate_rewards_event_meta((string) ($event_row['meta'] ?? ''));

        if ($event_type === 'tier_updated') {
            $from_tier = $this->get_candidate_rewards_tier_label((string) ($meta['previous_tier'] ?? 'standard'));
            $to_tier = $this->get_candidate_rewards_tier_label((string) ($meta['new_tier'] ?? 'standard'));
            return $from_tier . ' -> ' . $to_tier;
        }
        if ($event_type === 'bonus_triggered') {
            $bonus_amount = round((float) ($meta['bonus_amount'] ?? 0), 2);
            return $bonus_amount > 0 ? ('Bonus amount: GBP ' . number_format($bonus_amount, 2)) : '30-shift bonus triggered.';
        }
        if ($event_type === 'bonus_paid') {
            $amount = round((float) ($meta['amount'] ?? 0), 2);
            return $amount > 0 ? ('Processed: GBP ' . number_format($amount, 2)) : 'Bonus marked as processed.';
        }
        if ($event_type === 'probation_shift_completed') {
            $probation_after = (int) ($meta['probation_count_after'] ?? 0);
            if ($probation_after > 0) {
                return 'Probation progress: ' . $probation_after . '/10';
            }
        }
        if ($event_type === 'penalty_applied') {
            return 'Cycle reduced by 3 shifts.';
        }
        if ($event_type === 'penalty_reversed') {
            return 'Cycle restored by 3 shifts.';
        }
        if ($event_type === 'no_show_confirmed') {
            return 'No pre-shift communication recorded in booking chat.';
        }
        if ($event_type === 'no_show_reversed') {
            return 'Exceptional circumstance accepted. No-show reversed.';
        }
        if ($event_type === 'rewards_reinstated') {
            return 'Probation complete. Rewards active again.';
        }
        if ($event_type === 'rewards_reinstated_override') {
            return 'Rewards resumed by senior override decision.';
        }
        if ($event_type === 'termination_reversed') {
            return 'Termination reversed. Portal access restored where available.';
        }

        return $label;
    }

    private function get_candidate_rewards_stats_payload($candidate_id, $options = []) {
        $candidate_id = (int) $candidate_id;
        $options = is_array($options) ? $options : [];
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_candidate_rewards_invalid_candidate', 'Invalid candidate for rewards stats.');
        }

        $reference_date = $this->normalize_invoice_date((string) ($options['reference_date'] ?? ''));
        if ($reference_date === '') {
            $reference_date = current_time('Y-m-d');
        }
        $academic_year = $this->normalize_candidate_rewards_academic_year_label('', $reference_date);
        $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($rewards_row)) {
            return $rewards_row;
        }
        $rewards_row = is_array($rewards_row) ? $rewards_row : [];

        $tier = $this->normalize_candidate_rewards_tier((string) ($rewards_row['tier'] ?? 'standard'));
        $multiplier = round((float) ($rewards_row['multiplier'] ?? $this->get_candidate_rewards_multiplier_for_tier($tier)), 2);
        if ($multiplier <= 0) {
            $multiplier = $this->get_candidate_rewards_multiplier_for_tier($tier);
        }

        $academic_year_shift_total = max(0, (int) ($rewards_row['academic_year_shift_total'] ?? 0));
        $shift_cycle_count = (int) ($rewards_row['shift_cycle_count'] ?? 0);
        $no_show_count = max(0, (int) ($rewards_row['no_show_count'] ?? 0));
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($rewards_row['conduct_status'] ?? 'clear'));
        $rewards_paused = !empty($rewards_row['rewards_paused']) ? 1 : 0;
        $probation_consecutive_shifts = max(0, (int) ($rewards_row['probation_consecutive_shifts'] ?? 0));

        $thresholds = $this->get_candidate_rewards_tier_threshold_map();
        $next_tier_name = 'Top tier achieved';
        $next_tier_threshold = max(0, (int) ($thresholds['elite'] ?? 0));
        $shifts_to_next_tier = 0;
        foreach ($this->get_candidate_rewards_tier_order() as $tier_key) {
            $threshold = max(0, (int) ($thresholds[$tier_key] ?? 0));
            if ($threshold > $academic_year_shift_total) {
                $next_tier_name = $this->get_candidate_rewards_tier_label($tier_key);
                $next_tier_threshold = $threshold;
                $shifts_to_next_tier = max(0, $threshold - $academic_year_shift_total);
                break;
            }
        }
        if ($tier === 'elite') {
            $next_tier_name = 'Top tier achieved';
            $shifts_to_next_tier = 0;
        }

        $elite_threshold = max(1, (int) ($thresholds['elite'] ?? 120));
        $tier_progress_percent = max(0, min(100, round(($academic_year_shift_total / $elite_threshold) * 100, 2)));
        $cycle_target = max(1, (int) apply_filters('cmn_candidate_rewards_cycle_target', self::CANDIDATE_REWARDS_CYCLE_TARGET));
        $shifts_to_next_bonus = max(0, $cycle_target - $shift_cycle_count);
        $cycle_progress_percent = max(0, min(100, round(($shift_cycle_count / $cycle_target) * 100, 2)));

        $payout_limit = max(1, min(20, (int) ($options['payout_limit'] ?? 5)));
        $payout_rows = $this->get_candidate_reward_payouts($candidate_id, $academic_year, $payout_limit);
        $payouts = [];
        foreach ((array) $payout_rows as $payout_row) {
            $status_key = $this->normalize_candidate_rewards_payout_status((string) ($payout_row['status'] ?? 'queued'));
            $payroll_week_start = $this->normalize_invoice_date((string) ($payout_row['payroll_week_start'] ?? ''));
            $created_at_raw = sanitize_text_field((string) ($payout_row['created_at'] ?? ''));
            $created_at_label = '—';
            if ($created_at_raw !== '' && strtotime($created_at_raw) !== false) {
                $created_at_label = date_i18n('j M Y', strtotime($created_at_raw));
            }
            $payouts[] = [
                'bonus_amount' => round((float) ($payout_row['bonus_amount'] ?? 0), 2),
                'multiplier_applied' => round((float) ($payout_row['multiplier_applied'] ?? 1.00), 2),
                'payroll_week_start' => $payroll_week_start,
                'payroll_week_start_label' => $payroll_week_start !== '' ? date_i18n('j M Y', strtotime($payroll_week_start)) : '—',
                'status' => $status_key,
                'status_label' => ucfirst($status_key),
                'created_at' => $created_at_raw,
                'created_at_label' => $created_at_label,
            ];
        }

        $events = [];
        $include_events = !array_key_exists('include_events', $options) || !empty($options['include_events']);
        if ($include_events) {
            $safe_types = $this->get_candidate_rewards_safe_event_types();
            $event_limit = max(1, min(50, (int) ($options['event_limit'] ?? 10)));
            $event_rows = $this->get_candidate_rewards_events($candidate_id, $academic_year, max(40, $event_limit * 4));
            foreach ((array) $event_rows as $event_row) {
                $event_type = sanitize_key((string) ($event_row['event_type'] ?? ''));
                if (!in_array($event_type, $safe_types, true)) {
                    continue;
                }
                $shift_date = $this->normalize_invoice_date((string) ($event_row['shift_date'] ?? ''));
                $created_at_raw = sanitize_text_field((string) ($event_row['created_at'] ?? ''));
                $events[] = [
                    'event_type' => $event_type,
                    'label' => $this->get_candidate_rewards_event_label($event_type),
                    'summary' => $this->build_candidate_rewards_event_summary($event_row),
                    'shift_date' => $shift_date,
                    'shift_date_label' => $shift_date !== '' ? date_i18n('j M Y', strtotime($shift_date)) : '—',
                    'created_at' => $created_at_raw,
                    'created_at_label' => ($created_at_raw !== '' && strtotime($created_at_raw) !== false) ? date_i18n('j M Y g:ia', strtotime($created_at_raw)) : '—',
                ];
                if (count($events) >= $event_limit) {
                    break;
                }
            }
        }

        return [
            'candidate_id' => $candidate_id,
            'academic_year_label' => $academic_year,
            'tier' => $tier,
            'tier_label' => $this->get_candidate_rewards_tier_label($tier),
            'multiplier' => $multiplier,
            'academic_year_shift_total' => $academic_year_shift_total,
            'shift_cycle_count' => $shift_cycle_count,
            'cycle_target' => $cycle_target,
            'shifts_to_next_bonus' => $shifts_to_next_bonus,
            'cycle_progress_percent' => $cycle_progress_percent,
            'no_show_count' => $no_show_count,
            'conduct_status' => $conduct_status,
            'conduct_status_label' => $this->get_candidate_rewards_conduct_status_label($conduct_status),
            'rewards_paused' => $rewards_paused,
            'probation_consecutive_shifts' => $probation_consecutive_shifts,
            'next_tier_name' => $next_tier_name,
            'next_tier_threshold' => $next_tier_threshold,
            'shifts_to_next_tier' => $shifts_to_next_tier,
            'tier_progress_percent' => $tier_progress_percent,
            'tier_thresholds' => [
                'bronze' => (int) ($thresholds['bronze'] ?? 30),
                'silver' => (int) ($thresholds['silver'] ?? 60),
                'gold' => (int) ($thresholds['gold'] ?? 90),
                'elite' => (int) ($thresholds['elite'] ?? 120),
            ],
            'payouts' => $payouts,
            'events' => $events,
        ];
    }

    public function get_payroll_period_for_date($date = 'now') {
        if (function_exists('cmn_payroll_get_period_for_date')) {
            return (array) cmn_payroll_get_period_for_date($date);
        }

        try {
            $tz = wp_timezone();
            $reference = ($date instanceof DateTimeInterface)
                ? DateTimeImmutable::createFromInterface($date)->setTimezone($tz)
                : (($date === null || trim((string) $date) === '' || (string) $date === 'now')
                    ? (function_exists('cmn_now') ? cmn_now()->setTimezone($tz) : new DateTimeImmutable('now', $tz))
                    : new DateTimeImmutable((string) $date, $tz));
        } catch (Throwable $e) {
            $reference = function_exists('cmn_now')
                ? cmn_now()->setTimezone(wp_timezone())
                : new DateTimeImmutable('now', wp_timezone());
        }

        $reference = $reference->setTimezone(wp_timezone());
        $iso_day = (int) $reference->format('N');
        $delta = $iso_day - 5; // Friday start.
        if ($delta < 0) {
            $delta += 7;
        }

        $period_start = $reference->modify('-' . $delta . ' days')->setTime(0, 0, 0);
        $period_end = $period_start->modify('+6 days');
        $pay_date = $period_end->modify('+1 day');

        return [
            'period_start' => $period_start->format('Y-m-d'),
            'period_end' => $period_end->format('Y-m-d'),
            'pay_date' => $pay_date->format('Y-m-d'),
            'label' => 'Fri ' . wp_date('d M', $period_start->getTimestamp(), wp_timezone()) . ' – Thu ' . wp_date('d M', $period_end->getTimestamp(), wp_timezone()),
        ];
    }

    public function get_payroll_current_period() {
        return $this->get_payroll_period_for_date('now');
    }

    public function get_payroll_previous_period() {
        $current = $this->get_payroll_current_period();
        $start = sanitize_text_field((string) ($current['period_start'] ?? ''));
        if ($start === '') {
            return $this->get_payroll_period_for_date('-7 days');
        }
        try {
            $start_dt = new DateTimeImmutable($start, wp_timezone());
        } catch (Throwable $e) {
            return $this->get_payroll_period_for_date('-7 days');
        }
        return $this->get_payroll_period_for_date($start_dt->modify('-1 day'));
    }

    public function get_payroll_period_id($period_start, $period_end) {
        if (function_exists('cmn_payroll_period_id')) {
            return (string) cmn_payroll_period_id($period_start, $period_end);
        }

        $period_start = sanitize_text_field((string) $period_start);
        $period_end = sanitize_text_field((string) $period_end);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $period_start) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $period_end)) {
            return '';
        }
        return $period_start . '__' . $period_end;
    }

    public function get_payroll_week_start($date = 'now') {
        $period = $this->get_payroll_period_for_date($date);
        return sanitize_text_field((string) ($period['period_start'] ?? ''));
    }

    private function get_payroll_week_end_from_start($week_start_date) {
        $period = $this->get_payroll_period_for_date((string) $week_start_date);
        return sanitize_text_field((string) ($period['period_end'] ?? ''));
    }

    private function normalize_payroll_addon_status($status) {
        $status = sanitize_key((string) $status);
        if (!in_array($status, ['queued', 'included', 'processed', 'void'], true)) {
            return 'queued';
        }
        return $status;
    }

    private function payroll_addons_table_exists() {
        global $wpdb;
        $table = $this->get_payroll_addons_table();
        if ($table === '') {
            return false;
        }
        $found = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
        return $found === $table;
    }

    private function get_payroll_addon_by_source($source_type, $source_id) {
        $source_type = substr(sanitize_key((string) $source_type), 0, 40);
        $source_id = (int) $source_id;
        if ($source_type === '' || $source_id < 1 || !$this->payroll_addons_table_exists()) {
            return [];
        }
        global $wpdb;
        $table = $this->get_payroll_addons_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE source_type = %s
               AND source_id = %d
             LIMIT 1",
            $source_type,
            $source_id
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function create_or_get_payroll_addon_row($payload = []) {
        $payload = is_array($payload) ? $payload : [];
        if (!$this->payroll_addons_table_exists()) {
            return new WP_Error('cmn_payroll_addons_table_missing', 'Payroll add-ons table is not available.');
        }

        $candidate_id = (int) ($payload['candidate_id'] ?? 0);
        $source_type = substr(sanitize_key((string) ($payload['source_type'] ?? 'candidate_rewards_bonus')), 0, 40);
        $source_id = (int) ($payload['source_id'] ?? 0);
        $payroll_week_start = $this->normalize_invoice_date((string) ($payload['payroll_week_start'] ?? ''));
        $payroll_week_end = $this->normalize_invoice_date((string) ($payload['payroll_week_end'] ?? ''));
        $label = substr(sanitize_text_field((string) ($payload['label'] ?? '')), 0, 255);
        $amount = round((float) ($payload['amount'] ?? 0), 2);
        $status = $this->normalize_payroll_addon_status((string) ($payload['status'] ?? 'included'));
        if ($candidate_id < 1 || $source_type === '' || $source_id < 1 || $payroll_week_start === '' || $payroll_week_end === '' || $label === '' || $amount <= 0) {
            return new WP_Error('cmn_payroll_addon_invalid_payload', 'Invalid payroll add-on payload.');
        }

        global $wpdb;
        $table = $this->get_payroll_addons_table();
        $now = current_time('mysql');
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT IGNORE INTO {$table}
            (candidate_id, payroll_week_start, payroll_week_end, source_type, source_id, label, amount, status, created_at, updated_at)
            VALUES
            (%d, %s, %s, %s, %d, %s, %f, %s, %s, %s)",
            $candidate_id,
            $payroll_week_start,
            $payroll_week_end,
            $source_type,
            $source_id,
            $label,
            $amount,
            $status,
            $now,
            $now
        ));
        if ($inserted === false) {
            return new WP_Error('cmn_payroll_addon_insert_failed', 'Unable to create payroll add-on row.');
        }

        $row = $this->get_payroll_addon_by_source($source_type, $source_id);
        if (!$row) {
            return new WP_Error('cmn_payroll_addon_lookup_failed', 'Payroll add-on row could not be retrieved.');
        }
        return [
            'addon_id' => (int) ($row['id'] ?? 0),
            'inserted' => ((int) $inserted) > 0,
            'duplicate' => ((int) $inserted) === 0,
            'row' => $row,
        ];
    }

    private function update_payroll_addon_row($addon_id, $updates = []) {
        $addon_id = (int) $addon_id;
        if ($addon_id < 1 || !$this->payroll_addons_table_exists()) {
            return false;
        }
        $updates = is_array($updates) ? $updates : [];
        $data = [];
        $formats = [];
        if (array_key_exists('status', $updates)) {
            $data['status'] = $this->normalize_payroll_addon_status((string) $updates['status']);
            $formats[] = '%s';
        }
        if (array_key_exists('payroll_week_start', $updates)) {
            $week_start = $this->normalize_invoice_date((string) $updates['payroll_week_start']);
            if ($week_start !== '') {
                $data['payroll_week_start'] = $week_start;
                $formats[] = '%s';
            }
        }
        if (array_key_exists('payroll_week_end', $updates)) {
            $week_end = $this->normalize_invoice_date((string) $updates['payroll_week_end']);
            if ($week_end !== '') {
                $data['payroll_week_end'] = $week_end;
                $formats[] = '%s';
            }
        }
        if (!$data) {
            return false;
        }
        $data['updated_at'] = current_time('mysql');
        $formats[] = '%s';

        global $wpdb;
        $table = $this->get_payroll_addons_table();
        $updated = $wpdb->update($table, $data, ['id' => $addon_id], $formats, ['%d']);
        return $updated !== false;
    }

    private function update_candidate_reward_payout_row($payout_id, $updates = []) {
        $payout_id = (int) $payout_id;
        if ($payout_id < 1) {
            return false;
        }
        $updates = is_array($updates) ? $updates : [];
        $data = [];
        $formats = [];
        if (array_key_exists('status', $updates)) {
            $data['status'] = $this->normalize_candidate_rewards_payout_status((string) $updates['status']);
            $formats[] = '%s';
        }
        if (array_key_exists('payroll_week_start', $updates)) {
            $payroll_week_start = $this->normalize_invoice_date((string) $updates['payroll_week_start']);
            $data['payroll_week_start'] = $payroll_week_start !== '' ? $payroll_week_start : null;
            $formats[] = '%s';
        }
        if (!$data) {
            return false;
        }
        $data['updated_at'] = current_time('mysql');
        $formats[] = '%s';

        global $wpdb;
        $table = $this->get_candidate_reward_payouts_table();
        $updated = $wpdb->update($table, $data, ['id' => $payout_id], $formats, ['%d']);
        return $updated !== false;
    }

    private function get_candidate_rewards_tier_label_for_multiplier($multiplier) {
        $multiplier = round((float) $multiplier, 2);
        $map = $this->get_candidate_rewards_tier_multiplier_map();
        foreach ($map as $tier => $tier_multiplier) {
            if (abs(((float) $tier_multiplier) - $multiplier) < 0.001) {
                return ucfirst((string) $tier);
            }
        }
        return 'Tier';
    }

    public function process_candidate_rewards_payouts_for_week($week_start_date = '', $context = []) {
        $context = is_array($context) ? $context : [];
        $trigger = sanitize_key((string) ($context['trigger'] ?? 'manual'));
        if ($trigger === '') {
            $trigger = 'manual';
        }
        $actor_user_id = (int) ($context['actor_user_id'] ?? get_current_user_id());
        $week_start = $this->get_payroll_week_start($week_start_date !== '' ? $week_start_date : 'now');
        $week_end = $this->get_payroll_week_end_from_start($week_start);
        if ($week_start === '' || $week_end === '') {
            return new WP_Error('cmn_rewards_payroll_invalid_week', 'Invalid payroll week.');
        }

        $lock_key = self::CANDIDATE_REWARDS_PAYROLL_ADDON_LOCK_KEY . '_' . $week_start;
        if (get_transient($lock_key)) {
            return [
                'status' => 'skipped',
                'week_start' => $week_start,
                'week_end' => $week_end,
                'processed' => 0,
                'included' => 0,
                'duplicates' => 0,
                'warnings' => 0,
                'message' => 'Skipped due to lock.',
            ];
        }
        set_transient($lock_key, 1, self::CANDIDATE_REWARDS_PAYROLL_ADDON_LOCK_TTL);

        $summary = [
            'status' => 'success',
            'week_start' => $week_start,
            'week_end' => $week_end,
            'processed' => 0,
            'included' => 0,
            'duplicates' => 0,
            'warnings' => 0,
            'message' => '',
        ];
        $week_start_ts = strtotime($week_start);
        if ($week_start_ts === false) {
            return new WP_Error('cmn_rewards_payroll_invalid_week_timestamp', 'Invalid payroll week timestamp.');
        }

        try {
            global $wpdb;
            $payouts_table = $this->get_candidate_reward_payouts_table();
            $queued_rows = $wpdb->get_results($wpdb->prepare(
                "SELECT *
                 FROM {$payouts_table}
                 WHERE status = %s
                 ORDER BY id ASC",
                'queued'
            ), ARRAY_A);
            if (!is_array($queued_rows)) {
                $queued_rows = [];
            }

            foreach ($queued_rows as $payout_row) {
                $summary['processed']++;
                $payout_id = (int) ($payout_row['id'] ?? 0);
                $candidate_id = (int) ($payout_row['candidate_id'] ?? 0);
                $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) ($payout_row['academic_year'] ?? ''), $week_start);
                if ($payout_id < 1 || $candidate_id < 1 || $academic_year === '') {
                    $summary['warnings']++;
                    continue;
                }
                $bonus_amount = round((float) ($payout_row['bonus_amount'] ?? 0), 2);
                if ($bonus_amount <= 0) {
                    $summary['warnings']++;
                    $this->add_audit_log('candidate_rewards_payroll_addon_invalid_bonus_amount', 'candidate', (string) $candidate_id, [
                        'payout_id' => $payout_id,
                        'bonus_amount' => $bonus_amount,
                    ], $actor_user_id);
                    continue;
                }

                $payout_week_start = $this->normalize_invoice_date((string) ($payout_row['payroll_week_start'] ?? ''));
                if ($payout_week_start === '') {
                    $created_at = (string) ($payout_row['created_at'] ?? '');
                    $payout_week_start = $this->get_payroll_week_start($created_at !== '' ? $created_at : $week_start);
                }
                $payout_week_start_ts = strtotime($payout_week_start);
                if ($payout_week_start_ts === false) {
                    $summary['warnings']++;
                    continue;
                }
                // Include payouts due for this week and any older queued payouts so nothing expires.
                if ($payout_week_start_ts > $week_start_ts) {
                    continue;
                }
                $payout_week_end = $this->get_payroll_week_end_from_start($payout_week_start);
                if ($payout_week_end === '') {
                    $summary['warnings']++;
                    continue;
                }

                $rewards_row = $this->get_candidate_rewards_record($candidate_id, $academic_year);
                if (!empty($rewards_row)) {
                    $conduct_status = sanitize_key((string) ($rewards_row['conduct_status'] ?? 'clear'));
                    if ($conduct_status === 'terminated') {
                        $summary['warnings']++;
                        $this->add_audit_log('candidate_rewards_payroll_addon_candidate_terminated', 'candidate', (string) $candidate_id, [
                            'payout_id' => $payout_id,
                            'week_start' => $payout_week_start,
                        ], $actor_user_id);
                    }
                }

                $multiplier = round((float) ($payout_row['multiplier_applied'] ?? 0), 2);
                if ($multiplier <= 0) {
                    $multiplier = 1.00;
                }
                $tier_label = $this->get_candidate_rewards_tier_label_for_multiplier($multiplier);
                $label = sprintf('CMN Rewards Bonus (%s %.2fx)', $tier_label, $multiplier);

                $addon_result = $this->create_or_get_payroll_addon_row([
                    'candidate_id' => $candidate_id,
                    'payroll_week_start' => $payout_week_start,
                    'payroll_week_end' => $payout_week_end,
                    'source_type' => 'candidate_rewards_bonus',
                    'source_id' => $payout_id,
                    'label' => $label,
                    'amount' => $bonus_amount,
                    'status' => 'included',
                ]);
                if (is_wp_error($addon_result)) {
                    $summary['warnings']++;
                    $this->add_audit_log('candidate_rewards_payroll_addon_create_failed', 'candidate', (string) $candidate_id, [
                        'payout_id' => $payout_id,
                        'week_start' => $payout_week_start,
                        'message' => $addon_result->get_error_message(),
                    ], $actor_user_id);
                    continue;
                }

                $addon_id = (int) ($addon_result['addon_id'] ?? 0);
                if (!empty($addon_result['duplicate'])) {
                    $summary['duplicates']++;
                } else {
                    $summary['included']++;
                }
                if ($addon_id > 0) {
                    $existing_addon_status = $this->normalize_payroll_addon_status((string) (($addon_result['row']['status'] ?? '')));
                    $target_addon_status = $existing_addon_status === 'processed' ? 'processed' : 'included';
                    $this->update_payroll_addon_row($addon_id, [
                        'status' => $target_addon_status,
                        'payroll_week_start' => $payout_week_start,
                        'payroll_week_end' => $payout_week_end,
                    ]);
                } else {
                    $target_addon_status = 'included';
                }
                $this->update_candidate_reward_payout_row($payout_id, [
                    'status' => $target_addon_status === 'processed' ? 'processed' : 'included',
                    'payroll_week_start' => $payout_week_start,
                ]);

                $included_event = $this->insert_candidate_rewards_event([
                    'candidate_id' => $candidate_id,
                    'booking_id' => $payout_id,
                    'shift_date' => $payout_week_start,
                    'event_type' => 'bonus_included_in_payroll',
                    'delta_cycle' => 0,
                    'delta_year_total' => 0,
                    'meta' => [
                        'payout_id' => $payout_id,
                        'payroll_week_start' => $payout_week_start,
                        'addon_id' => $addon_id,
                        'amount' => $bonus_amount,
                        'trigger' => $trigger,
                    ],
                    'created_by_user_id' => $actor_user_id,
                ]);
                if (is_wp_error($included_event)) {
                    $summary['warnings']++;
                    $this->add_audit_log('candidate_rewards_payroll_included_event_failed', 'candidate', (string) $candidate_id, [
                        'payout_id' => $payout_id,
                        'addon_id' => $addon_id,
                        'message' => $included_event->get_error_message(),
                    ], $actor_user_id);
                }
            }

            if ($summary['warnings'] > 0) {
                $summary['status'] = 'partial';
            }
        } finally {
            delete_transient($lock_key);
        }

        $this->add_audit_log('candidate_rewards_payroll_addon_processor_run', 'candidate_rewards_week', $week_start, [
            'trigger' => $trigger,
            'status' => $summary['status'],
            'week_start' => $week_start,
            'week_end' => $week_end,
            'processed' => (int) $summary['processed'],
            'included' => (int) $summary['included'],
            'duplicates' => (int) $summary['duplicates'],
            'warnings' => (int) $summary['warnings'],
        ], $actor_user_id);

        return $summary;
    }

    public function mark_rewards_addons_processed_for_week($week_start_date = '', $context = []) {
        $context = is_array($context) ? $context : [];
        $trigger = sanitize_key((string) ($context['trigger'] ?? 'manual'));
        if ($trigger === '') {
            $trigger = 'manual';
        }
        $processed_by = (int) ($context['processed_by_user_id'] ?? get_current_user_id());
        $week_start = $this->get_payroll_week_start($week_start_date !== '' ? $week_start_date : 'now');
        if ($week_start === '') {
            return new WP_Error('cmn_rewards_payroll_invalid_week', 'Invalid payroll week.');
        }
        $week_end = $this->get_payroll_week_end_from_start($week_start);
        if ($week_end === '') {
            return new WP_Error('cmn_rewards_payroll_invalid_week_end', 'Invalid payroll week end.');
        }
        if (!$this->payroll_addons_table_exists()) {
            return new WP_Error('cmn_rewards_payroll_addons_missing', 'Payroll add-ons table is not available.');
        }

        $summary = [
            'status' => 'success',
            'week_start' => $week_start,
            'week_end' => $week_end,
            'processed' => 0,
            'warnings' => 0,
        ];

        global $wpdb;
        $addons_table = $this->get_payroll_addons_table();
        $addon_rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$addons_table}
             WHERE source_type = %s
               AND payroll_week_start = %s
               AND status IN (%s, %s)
             ORDER BY id ASC",
            'candidate_rewards_bonus',
            $week_start,
            'queued',
            'included'
        ), ARRAY_A);
        if (!is_array($addon_rows)) {
            $addon_rows = [];
        }

        foreach ($addon_rows as $addon_row) {
            $addon_id = (int) ($addon_row['id'] ?? 0);
            $candidate_id = (int) ($addon_row['candidate_id'] ?? 0);
            $payout_id = (int) ($addon_row['source_id'] ?? 0);
            $amount = round((float) ($addon_row['amount'] ?? 0), 2);
            if ($addon_id < 1 || $candidate_id < 1 || $payout_id < 1 || $amount <= 0) {
                $summary['warnings']++;
                continue;
            }

            $this->update_payroll_addon_row($addon_id, [
                'status' => 'processed',
                'payroll_week_start' => $week_start,
                'payroll_week_end' => $week_end,
            ]);

            global $wpdb;
            $payouts_table = $this->get_candidate_reward_payouts_table();
            $payout_row = $wpdb->get_row($wpdb->prepare(
                "SELECT *
                 FROM {$payouts_table}
                 WHERE id = %d
                 LIMIT 1",
                $payout_id
            ), ARRAY_A);
            if (is_array($payout_row) && !empty($payout_row)) {
                $this->update_candidate_reward_payout_row($payout_id, [
                    'status' => 'processed',
                    'payroll_week_start' => $week_start,
                ]);
                $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) ($payout_row['academic_year'] ?? ''), $week_start);
                if ($academic_year !== '') {
                    $this->update_candidate_rewards_record($candidate_id, $academic_year, [
                        'last_bonus_paid_at' => current_time('mysql'),
                    ]);
                }
            } else {
                $summary['warnings']++;
            }

            $paid_event = $this->insert_candidate_rewards_event([
                'candidate_id' => $candidate_id,
                'booking_id' => $payout_id,
                'shift_date' => $week_start,
                'event_type' => 'bonus_paid',
                'delta_cycle' => 0,
                'delta_year_total' => 0,
                'meta' => [
                    'payout_id' => $payout_id,
                    'payroll_week_start' => $week_start,
                    'addon_id' => $addon_id,
                    'amount' => $amount,
                    'processed_by' => $processed_by,
                    'trigger' => $trigger,
                ],
                'created_by_user_id' => $processed_by,
            ]);
            if (is_wp_error($paid_event)) {
                $summary['warnings']++;
                $this->add_audit_log('candidate_rewards_bonus_paid_event_failed', 'candidate', (string) $candidate_id, [
                    'payout_id' => $payout_id,
                    'addon_id' => $addon_id,
                    'message' => $paid_event->get_error_message(),
                ], $processed_by);
            }
            $summary['processed']++;
        }

        if ($summary['warnings'] > 0) {
            $summary['status'] = 'partial';
        }
        $this->add_audit_log('candidate_rewards_payroll_addons_marked_processed', 'candidate_rewards_week', $week_start, [
            'trigger' => $trigger,
            'status' => $summary['status'],
            'week_start' => $week_start,
            'processed' => (int) $summary['processed'],
            'warnings' => (int) $summary['warnings'],
        ], $processed_by);

        return $summary;
    }

    /*
     * Prompt 28 acceptance checks:
     * 1) Cron locks each payroll period once using UNIQUE(period_id).
     * 2) Re-running job does not duplicate pay approvals for candidate+booking+day.
     * 3) Cancelled/no-show booking-days are not auto-approved.
     * 4) School confirmation records are read-only and unchanged by this job.
     */
    private function run_payroll_period_auto_lock_job($trigger = 'cron', $actor_user_id = 0, $context = []) {
        $trigger = sanitize_key((string) $trigger);
        if ($trigger === '') {
            $trigger = 'cron';
        }
        $actor_user_id = max(0, (int) $actor_user_id);
        $context = is_array($context) ? $context : [];
        $is_training = $this->resolve_training_flag($context['is_training'] ?? null, 0);
        $locked_by = ($actor_user_id > 0 && $trigger !== 'cron') ? 'staff' : 'system';

        $summary = [
            'status' => 'failed',
            'trigger' => $trigger,
            'period_id' => '',
            'period_start' => '',
            'period_end' => '',
            'pay_date' => '',
            'period_locked' => 0,
            'booking_days_scanned' => 0,
            'approvals_created' => 0,
            'approvals_skipped_existing' => 0,
            'approvals_skipped_no_show' => 0,
            'approvals_errors' => 0,
            'is_training' => $is_training,
            'error_message' => '',
        ];

        $lock_key = self::PAYROLL_PERIOD_AUTO_LOCK_LOCK_KEY;
        if (get_transient($lock_key)) {
            $summary['status'] = 'skipped';
            $summary['error_message'] = 'Skipped due to lock: payroll auto-lock job is already in progress.';
            return $summary;
        }
        set_transient($lock_key, 1, self::PAYROLL_PERIOD_AUTO_LOCK_LOCK_TTL);

        try {
            $period = function_exists('cmn_payroll_get_current_period')
                ? (array) cmn_payroll_get_current_period()
                : (array) $this->get_payroll_current_period();
            $period_start = $this->normalize_invoice_date((string) ($period['period_start'] ?? ''));
            $period_end = $this->normalize_invoice_date((string) ($period['period_end'] ?? ''));
            $pay_date = $this->normalize_invoice_date((string) ($period['pay_date'] ?? ''));
            if ($period_start === '' || $period_end === '') {
                $summary['error_message'] = 'Unable to resolve payroll period boundaries.';
                return $summary;
            }

            $base_period_id = sanitize_text_field((string) ($period['period_id'] ?? ''));
            if ($base_period_id === '') {
                $base_period_id = $this->get_payroll_period_id($period_start, $period_end);
            }
            if ($base_period_id === '') {
                $summary['error_message'] = 'Unable to resolve payroll period ID.';
                return $summary;
            }
            $period_id = $is_training ? ($base_period_id . '__training') : $base_period_id;

            $summary['period_id'] = $period_id;
            $summary['period_start'] = $period_start;
            $summary['period_end'] = $period_end;
            $summary['pay_date'] = $pay_date;

            $lock_result = $this->insert_payroll_period_lock_row($period_id, $period_start, $period_end, $locked_by, $is_training);
            if (is_wp_error($lock_result)) {
                $summary['error_message'] = $lock_result->get_error_message();
                return $summary;
            }
            $summary['period_locked'] = !empty($lock_result['inserted']) ? 1 : 0;

            if (!empty($lock_result['inserted']) && function_exists('cmn_audit_log_event')) {
                $lock_audit = cmn_audit_log_event([
                    'module' => 'payroll',
                    'entity_type' => 'period',
                    'entity_id' => $this->get_payroll_period_audit_entity_id($period_id, $period_start, $period_end),
                    'event_type' => 'payroll_period_locked',
                    'event_ref' => $period_id,
                    'actor_user_id' => $actor_user_id,
                    'metadata' => [
                            'period_id' => $period_id,
                            'base_period_id' => $base_period_id,
                            'period_start' => $period_start,
                            'period_end' => $period_end,
                            'pay_date' => $pay_date,
                            'locked_by' => $locked_by,
                            'is_training' => $is_training,
                        ],
                    ]);
                if (is_wp_error($lock_audit)) {
                    $this->add_audit_log('payroll_period_locked_audit_failed', 'payroll_period', $period_id, [
                        'message' => $lock_audit->get_error_message(),
                    ], $actor_user_id);
                }
            }

            $approval_candidates_payload = $this->get_payroll_auto_approval_candidates_for_period($period_start, $period_end);
            $approval_candidates = (array) ($approval_candidates_payload['rows'] ?? []);
            $summary['booking_days_scanned'] = count($approval_candidates);
            $summary['approvals_skipped_no_show'] = max(0, (int) ($approval_candidates_payload['skipped_no_show'] ?? 0));

            global $wpdb;
            $approvals_table = $this->get_candidate_pay_approvals_table();
            $approvals_table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $approvals_table));
            if ($approvals_table_exists !== $approvals_table) {
                $summary['error_message'] = 'Candidate pay approvals table is not available.';
                return $summary;
            }

            foreach ($approval_candidates as $approval_row) {
                $candidate_user_id = max(0, (int) ($approval_row['candidate_user_id'] ?? 0));
                $booking_id = max(0, (int) ($approval_row['booking_id'] ?? 0));
                $booking_day_date = $this->normalize_invoice_date((string) ($approval_row['booking_day_date'] ?? ''));
                if ($candidate_user_id < 1 || $booking_id < 1 || $booking_day_date === '') {
                    $summary['approvals_errors']++;
                    continue;
                }

                $now = current_time('mysql');
                $has_training_column = self::table_has_column($approvals_table, 'is_training');
                if ($has_training_column) {
                    $inserted = $wpdb->query($wpdb->prepare(
                        "INSERT IGNORE INTO {$approvals_table}
                        (candidate_user_id, booking_id, booking_day_date, period_id, approval_status, approved_method, approved_at, created_at, updated_at, is_training)
                        VALUES
                        (%d, %d, %s, %s, %s, %s, %s, %s, %s, %d)",
                        $candidate_user_id,
                        $booking_id,
                        $booking_day_date,
                        $period_id,
                        'approved',
                        'auto_approved',
                        $now,
                        $now,
                        $now,
                        $is_training
                    ));
                } else {
                    $inserted = $wpdb->query($wpdb->prepare(
                        "INSERT IGNORE INTO {$approvals_table}
                        (candidate_user_id, booking_id, booking_day_date, period_id, approval_status, approved_method, approved_at, created_at, updated_at)
                        VALUES
                        (%d, %d, %s, %s, %s, %s, %s, %s, %s)",
                        $candidate_user_id,
                        $booking_id,
                        $booking_day_date,
                        $period_id,
                        'approved',
                        'auto_approved',
                        $now,
                        $now,
                        $now
                    ));
                }
                if ($inserted === false) {
                    $summary['approvals_errors']++;
                    continue;
                }
                if ((int) $inserted === 0) {
                    $summary['approvals_skipped_existing']++;
                    continue;
                }

                $summary['approvals_created']++;
                if (function_exists('cmn_audit_log_event')) {
                    $approval_audit = cmn_audit_log_event([
                        'module' => 'payroll',
                        'entity_type' => 'booking',
                        'entity_id' => $booking_id,
                        'event_type' => 'booking_day_auto_approved',
                        'event_ref' => $booking_id . ':' . $booking_day_date,
                        'actor_user_id' => $actor_user_id,
                        'metadata' => [
                            'date' => $booking_day_date,
                            'candidate_user_id' => $candidate_user_id,
                            'period_id' => $period_id,
                            'approved_method' => 'auto_approved',
                            'is_training' => $is_training,
                        ],
                    ]);
                    if (is_wp_error($approval_audit)) {
                        $this->add_audit_log('booking_day_auto_approved_audit_failed', 'booking', (string) $booking_id, [
                            'date' => $booking_day_date,
                            'candidate_user_id' => $candidate_user_id,
                            'message' => $approval_audit->get_error_message(),
                        ], $actor_user_id);
                    }
                }
            }

            $summary['status'] = $summary['approvals_errors'] > 0 ? 'partial' : 'success';
            return $summary;
        } catch (Throwable $e) {
            $summary['status'] = 'failed';
            $summary['error_message'] = 'Unhandled error: ' . $e->getMessage();
            return $summary;
        } finally {
            delete_transient($lock_key);
        }
    }

    private function insert_payroll_period_lock_row($period_id, $period_start, $period_end, $locked_by = 'system', $is_training = 0) {
        $period_id = sanitize_text_field((string) $period_id);
        $period_start = $this->normalize_invoice_date((string) $period_start);
        $period_end = $this->normalize_invoice_date((string) $period_end);
        $locked_by = sanitize_key((string) $locked_by);
        $is_training = $this->resolve_training_flag($is_training, 0);
        if (!in_array($locked_by, ['system', 'staff'], true)) {
            $locked_by = 'system';
        }
        if ($period_id === '' || $period_start === '' || $period_end === '') {
            return new WP_Error('cmn_payroll_lock_invalid_period', 'Invalid payroll period lock payload.');
        }

        global $wpdb;
        $table = $this->get_payroll_period_locks_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return new WP_Error('cmn_payroll_lock_table_missing', 'Payroll period lock table is not available.');
        }

        $now = current_time('mysql');
        $has_training_column = self::table_has_column($table, 'is_training');
        if ($has_training_column) {
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT IGNORE INTO {$table}
                (period_id, period_start, period_end, locked_at, locked_by, created_at, is_training)
                VALUES
                (%s, %s, %s, %s, %s, %s, %d)",
                $period_id,
                $period_start,
                $period_end,
                $now,
                $locked_by,
                $now,
                $is_training
            ));
        } else {
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT IGNORE INTO {$table}
                (period_id, period_start, period_end, locked_at, locked_by, created_at)
                VALUES
                (%s, %s, %s, %s, %s, %s)",
                $period_id,
                $period_start,
                $period_end,
                $now,
                $locked_by,
                $now
            ));
        }
        if ($inserted === false) {
            return new WP_Error('cmn_payroll_lock_insert_failed', 'Unable to insert payroll period lock row.');
        }

        return [
            'period_id' => $period_id,
            'inserted' => (int) $inserted > 0,
            'locked_at' => $now,
            'is_training' => $is_training,
        ];
    }

    private function get_payroll_shift_credit_marks_for_period($period_start, $period_end) {
        $period_start = $this->normalize_invoice_date((string) $period_start);
        $period_end = $this->normalize_invoice_date((string) $period_end);
        if ($period_start === '' || $period_end === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_shift_credits_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }

        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT candidate_user_id, booking_id, booking_day_date
             FROM {$table}
             WHERE status = %s
               AND booking_day_date >= %s
               AND booking_day_date <= %s
             ORDER BY booking_day_date ASC, id ASC",
            'credited',
            $period_start,
            $period_end
        ), ARRAY_A);
        $marks = [];
        foreach ((array) $rows as $row) {
            $candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
            $booking_id = max(0, (int) ($row['booking_id'] ?? 0));
            $booking_day_date = $this->normalize_invoice_date((string) ($row['booking_day_date'] ?? ''));
            if ($booking_id < 1 || $booking_day_date === '') {
                continue;
            }
            $booking_day_key = $booking_id . '|' . $booking_day_date;
            if (!isset($marks[$booking_day_key]) || $candidate_user_id > 0) {
                $marks[$booking_day_key] = [
                    'candidate_user_id' => $candidate_user_id,
                    'booking_id' => $booking_id,
                    'booking_day_date' => $booking_day_date,
                ];
            }
        }
        return $marks;
    }

    private function get_payroll_no_show_booking_day_map($period_start, $period_end) {
        $period_start = $this->normalize_invoice_date((string) $period_start);
        $period_end = $this->normalize_invoice_date((string) $period_end);
        if ($period_start === '' || $period_end === '') {
            return [];
        }

        global $wpdb;
        $no_show_map = [];
        $rewards_events_table = $this->get_candidate_rewards_events_table();
        $rewards_events_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $rewards_events_table));
        if ($rewards_events_exists === $rewards_events_table) {
            $event_rows = $wpdb->get_results($wpdb->prepare(
                "SELECT booking_id, shift_date, event_type
                 FROM {$rewards_events_table}
                 WHERE shift_date >= %s
                   AND shift_date <= %s
                   AND event_type IN (%s, %s)
                 ORDER BY shift_date ASC, id ASC",
                $period_start,
                $period_end,
                'no_show_confirmed',
                'no_show_reversed'
            ), ARRAY_A);

            $confirmed = [];
            $reversed = [];
            foreach ((array) $event_rows as $event_row) {
                $booking_id = max(0, (int) ($event_row['booking_id'] ?? 0));
                $shift_date = $this->normalize_invoice_date((string) ($event_row['shift_date'] ?? ''));
                $event_type = sanitize_key((string) ($event_row['event_type'] ?? ''));
                if ($booking_id < 1 || $shift_date === '' || $event_type === '') {
                    continue;
                }
                $event_key = $booking_id . '|' . $shift_date;
                if ($event_type === 'no_show_confirmed') {
                    $confirmed[$event_key] = true;
                } elseif ($event_type === 'no_show_reversed') {
                    $reversed[$event_key] = true;
                }
            }
            foreach ($confirmed as $event_key => $is_confirmed) {
                if (!$is_confirmed || !empty($reversed[$event_key])) {
                    continue;
                }
                $no_show_map[$event_key] = true;
            }
        }

        $conduct_events_table = $this->get_candidate_conduct_events_table();
        $conduct_events_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $conduct_events_table));
        if ($conduct_events_exists === $conduct_events_table) {
            $conduct_rows = $wpdb->get_results($wpdb->prepare(
                "SELECT booking_id, occurred_at
                 FROM {$conduct_events_table}
                 WHERE booking_id > 0
                   AND event_type = %s
                   AND status = %s
                   AND occurred_at >= %s
                   AND occurred_at <= %s
                 ORDER BY occurred_at ASC, id ASC",
                'no_show',
                'active',
                $period_start . ' 00:00:00',
                $period_end . ' 23:59:59'
            ), ARRAY_A);
            foreach ((array) $conduct_rows as $conduct_row) {
                $booking_id = max(0, (int) ($conduct_row['booking_id'] ?? 0));
                $shift_date = $this->normalize_invoice_date(substr((string) ($conduct_row['occurred_at'] ?? ''), 0, 10));
                if ($booking_id < 1 || $shift_date === '') {
                    continue;
                }
                $event_key = $booking_id . '|' . $shift_date;
                $no_show_map[$event_key] = true;
            }
        }

        return $no_show_map;
    }

    private function get_payroll_auto_approval_candidates_for_period($period_start, $period_end) {
        $period_start = $this->normalize_invoice_date((string) $period_start);
        $period_end = $this->normalize_invoice_date((string) $period_end);
        if ($period_start === '' || $period_end === '') {
            return [
                'rows' => [],
                'skipped_no_show' => 0,
            ];
        }

        $attendance_marks = $this->get_payroll_shift_credit_marks_for_period($period_start, $period_end);
        $no_show_map = $this->get_payroll_no_show_booking_day_map($period_start, $period_end);
        $worked_statuses = $this->get_rewards_attended_completion_statuses();
        $cancelled_statuses = $this->get_rewards_credit_cancelled_booking_statuses();
        $booking_rows = $this->get_invoice_booking_rows(0);

        $rows = [];
        $seen = [];
        $candidate_user_cache = [];
        $cancelled_dates_cache = [];
        $booking_row_map = [];
        $no_show_skips = [];
        $period_today_cap = $period_end;

        foreach ((array) $booking_rows as $booking_row) {
            $booking_id = max(0, (int) ($booking_row['booking_id'] ?? 0));
            if ($booking_id < 1) {
                continue;
            }
            if (!isset($booking_row_map[$booking_id])) {
                $booking_row_map[$booking_id] = is_array($booking_row) ? $booking_row : [];
            }

            $status = sanitize_key((string) ($booking_row['booking_status'] ?? ''));
            if (in_array($status, $cancelled_statuses, true)) {
                continue;
            }

            $date_window = $this->get_invoice_booking_date_window($booking_row);
            if (!$date_window) {
                continue;
            }
            $shift_dates = $this->expand_booking_dates_for_period(
                (string) ($date_window['start_date'] ?? ''),
                (string) ($date_window['end_date'] ?? ''),
                $period_start,
                $period_end,
                $period_today_cap
            );
            if (!$shift_dates) {
                continue;
            }

            if (!isset($cancelled_dates_cache[$booking_id])) {
                $cancelled_dates_cache[$booking_id] = $this->get_rewards_cancelled_shift_dates_for_booking($booking_id);
            }

            $candidate_id = max(0, (int) ($booking_row['candidate_id'] ?? 0));
            if (!isset($candidate_user_cache[$candidate_id])) {
                $candidate_user_cache[$candidate_id] = $candidate_id > 0 ? (int) $this->get_candidate_user_id($candidate_id) : 0;
            }
            $candidate_user_id_from_booking = max(0, (int) ($candidate_user_cache[$candidate_id] ?? 0));

            foreach ((array) $shift_dates as $shift_date) {
                $shift_date = $this->normalize_invoice_date((string) $shift_date);
                if ($shift_date === '') {
                    continue;
                }
                if (!empty($cancelled_dates_cache[$booking_id][$shift_date])) {
                    continue;
                }

                $booking_day_key = $booking_id . '|' . $shift_date;
                $has_attendance_mark = isset($attendance_marks[$booking_day_key]);
                $eligible_by_status = in_array($status, $worked_statuses, true);
                if (!$eligible_by_status && !$has_attendance_mark) {
                    continue;
                }
                if (!empty($no_show_map[$booking_day_key])) {
                    $no_show_skips[$booking_day_key] = true;
                    continue;
                }

                $candidate_user_id = $has_attendance_mark
                    ? max(0, (int) ($attendance_marks[$booking_day_key]['candidate_user_id'] ?? 0))
                    : 0;
                if ($candidate_user_id < 1) {
                    $candidate_user_id = $candidate_user_id_from_booking;
                }
                if ($candidate_user_id < 1) {
                    continue;
                }

                $approval_key = $candidate_user_id . '|' . $booking_id . '|' . $shift_date;
                if (isset($seen[$approval_key])) {
                    continue;
                }
                $seen[$approval_key] = true;
                $rows[] = [
                    'candidate_user_id' => $candidate_user_id,
                    'booking_id' => $booking_id,
                    'booking_day_date' => $shift_date,
                ];
            }
        }

        foreach ($attendance_marks as $booking_day_key => $attendance_row) {
            $booking_id = max(0, (int) ($attendance_row['booking_id'] ?? 0));
            $shift_date = $this->normalize_invoice_date((string) ($attendance_row['booking_day_date'] ?? ''));
            if ($booking_id < 1 || $shift_date === '') {
                continue;
            }
            if (!empty($no_show_map[$booking_day_key])) {
                $no_show_skips[$booking_day_key] = true;
                continue;
            }

            $booking_row = isset($booking_row_map[$booking_id]) && is_array($booking_row_map[$booking_id])
                ? (array) $booking_row_map[$booking_id]
                : [];
            $status = $booking_row
                ? sanitize_key((string) ($booking_row['booking_status'] ?? ''))
                : sanitize_key((string) get_post_meta($booking_id, 'cmn_status', true));
            if (in_array($status, $cancelled_statuses, true)) {
                continue;
            }

            if (!isset($cancelled_dates_cache[$booking_id])) {
                $cancelled_dates_cache[$booking_id] = $this->get_rewards_cancelled_shift_dates_for_booking($booking_id);
            }
            if (!empty($cancelled_dates_cache[$booking_id][$shift_date])) {
                continue;
            }

            $candidate_user_id = max(0, (int) ($attendance_row['candidate_user_id'] ?? 0));
            if ($candidate_user_id < 1) {
                $candidate_id = $booking_row
                    ? max(0, (int) ($booking_row['candidate_id'] ?? 0))
                    : max(0, (int) get_post_meta($booking_id, 'cmn_candidate_id', true));
                if (!isset($candidate_user_cache[$candidate_id])) {
                    $candidate_user_cache[$candidate_id] = $candidate_id > 0 ? (int) $this->get_candidate_user_id($candidate_id) : 0;
                }
                $candidate_user_id = max(0, (int) ($candidate_user_cache[$candidate_id] ?? 0));
            }
            if ($candidate_user_id < 1) {
                continue;
            }

            $approval_key = $candidate_user_id . '|' . $booking_id . '|' . $shift_date;
            if (isset($seen[$approval_key])) {
                continue;
            }
            $seen[$approval_key] = true;
            $rows[] = [
                'candidate_user_id' => $candidate_user_id,
                'booking_id' => $booking_id,
                'booking_day_date' => $shift_date,
            ];
        }

        usort($rows, static function ($left, $right) {
            $left_date = (string) ($left['booking_day_date'] ?? '');
            $right_date = (string) ($right['booking_day_date'] ?? '');
            if ($left_date === $right_date) {
                return ((int) ($left['booking_id'] ?? 0)) <=> ((int) ($right['booking_id'] ?? 0));
            }
            return strcmp($left_date, $right_date);
        });

        return [
            'rows' => $rows,
            'skipped_no_show' => count($no_show_skips),
        ];
    }

    private function get_payroll_period_audit_entity_id($period_id, $period_start = '', $period_end = '') {
        $period_id = sanitize_text_field((string) $period_id);
        $period_start = $this->normalize_invoice_date((string) $period_start);
        $period_end = $this->normalize_invoice_date((string) $period_end);
        $digits = preg_replace('/\D+/', '', $period_id);
        if (!is_string($digits) || strlen($digits) < 8) {
            $digits = preg_replace('/\D+/', '', $period_start . $period_end);
        }
        if (is_string($digits) && $digits !== '') {
            if (strlen($digits) > 18) {
                $digits = substr($digits, 0, 18);
            }
            $entity_id = (int) ltrim($digits, '0');
            if ($entity_id > 0) {
                return $entity_id;
            }
        }
        $seed = $period_id !== '' ? $period_id : ($period_start . '__' . $period_end . '__' . current_time('Y-m-d'));
        $entity_id = (int) hexdec(substr(md5($seed), 0, 7));
        if ($entity_id < 1) {
            $entity_id = 1;
        }
        return $entity_id;
    }

    private function resolve_training_flag($value, $default = 0) {
        if ($value === null) {
            return !empty($default) ? 1 : 0;
        }
        return !empty($value) ? 1 : 0;
    }

    private function parse_payroll_period_id($period_id) {
        $period_id = sanitize_text_field((string) $period_id);
        if ($period_id === '') {
            return [
                'period_start' => '',
                'period_end' => '',
            ];
        }
        if (!preg_match('/^(\d{4}-\d{2}-\d{2})__(\d{4}-\d{2}-\d{2})(?:__training)?$/', $period_id, $matches)) {
            return [
                'period_start' => '',
                'period_end' => '',
            ];
        }

        $period_start = $this->normalize_invoice_date((string) ($matches[1] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($matches[2] ?? ''));
        if ($period_start === '' || $period_end === '') {
            return [
                'period_start' => '',
                'period_end' => '',
            ];
        }
        return [
            'period_start' => $period_start,
            'period_end' => $period_end,
        ];
    }

