    private function normalize_remittance_doc_status($status) {
        $status = sanitize_key((string) $status);
        if (!in_array($status, ['generated', 'voided', 'regenerated'], true)) {
            return 'generated';
        }
        return $status;
    }

    private function sanitize_remittance_pdf_relative_path($path) {
        $path = str_replace('\\', '/', trim((string) $path));
        $path = ltrim($path, '/');
        if ($path === '' || strpos($path, '..') !== false) {
            return '';
        }
        if (strpos($path, 'cmn/remittance/') !== 0) {
            return '';
        }
        return $path;
    }

    private function get_candidate_remittance_storage_directory() {
        $uploads = wp_upload_dir(null, false);
        $base_dir = isset($uploads['basedir']) ? (string) $uploads['basedir'] : '';
        $base_dir = rtrim($base_dir, '/\\');
        if ($base_dir === '' || !is_dir($base_dir) || !is_writable($base_dir)) {
            return new WP_Error('cmn_remittance_upload_dir_unavailable', 'Uploads directory is unavailable.');
        }

        $cmn_dir = $base_dir . '/cmn';
        if (!is_dir($cmn_dir)) {
            wp_mkdir_p($cmn_dir);
        }
        if (!is_dir($cmn_dir) || !is_writable($cmn_dir)) {
            return new WP_Error('cmn_remittance_cmn_dir_unavailable', 'CMN uploads directory is unavailable.');
        }

        $remittance_dir = $cmn_dir . '/remittance';
        if (!is_dir($remittance_dir)) {
            wp_mkdir_p($remittance_dir);
        }
        if (!is_dir($remittance_dir) || !is_writable($remittance_dir)) {
            return new WP_Error('cmn_remittance_dir_unavailable', 'Remittance storage directory is unavailable.');
        }

        $this->ensure_remittance_storage_protection_files($remittance_dir);
        return [
            'base_dir' => $base_dir,
            'cmn_dir' => $cmn_dir,
            'remittance_dir' => $remittance_dir,
            'relative_prefix' => 'cmn/remittance/',
        ];
    }

    private function ensure_remittance_storage_protection_files($remittance_dir) {
        $remittance_dir = rtrim((string) $remittance_dir, '/\\');
        if ($remittance_dir === '' || !is_dir($remittance_dir)) {
            return;
        }

        $index_path = $remittance_dir . '/index.php';
        if (!file_exists($index_path)) {
            @file_put_contents($index_path, "<?php\n// Silence is golden.\n", LOCK_EX);
        }

        $htaccess_path = $remittance_dir . '/.htaccess';
        if (!file_exists($htaccess_path)) {
            @file_put_contents($htaccess_path, "Require all denied\nDeny from all\n", LOCK_EX);
        }

        $web_config_path = $remittance_dir . '/web.config';
        if (!file_exists($web_config_path)) {
            $xml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<configuration>\n  <system.webServer>\n    <security>\n      <authorization>\n        <add accessType=\"Deny\" users=\"*\" />\n      </authorization>\n    </security>\n  </system.webServer>\n</configuration>\n";
            @file_put_contents($web_config_path, $xml, LOCK_EX);
        }
    }

    private function get_candidate_remittance_doc_absolute_path($pdf_path) {
        $relative_path = $this->sanitize_remittance_pdf_relative_path($pdf_path);
        if ($relative_path === '') {
            return '';
        }

        $uploads = wp_upload_dir(null, false);
        $base_dir = isset($uploads['basedir']) ? (string) $uploads['basedir'] : '';
        $base_dir = rtrim($base_dir, '/\\');
        if ($base_dir === '' || !is_dir($base_dir)) {
            return '';
        }
        $base_real = realpath($base_dir);
        if (!is_string($base_real) || $base_real === '') {
            return '';
        }

        $candidate_path = $base_dir . '/' . $relative_path;
        if (!file_exists($candidate_path)) {
            return '';
        }
        $real = realpath($candidate_path);
        if (!is_string($real) || $real === '') {
            return '';
        }

        $base_real_normalized = str_replace('\\', '/', $base_real);
        $real_normalized = str_replace('\\', '/', $real);
        if (strpos($real_normalized, $base_real_normalized . '/') !== 0) {
            return '';
        }
        if (strpos($real_normalized, '/cmn/remittance/') === false) {
            return '';
        }
        return $real;
    }

    private function get_candidate_remittance_doc_record($candidate_user_id, $period_id = '', $is_training = 0) {
        $candidate_user_id = (int) $candidate_user_id;
        $period_id = sanitize_text_field((string) $period_id);
        $is_training = $this->resolve_training_flag($is_training, 0);
        if ($candidate_user_id < 1) {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_remittance_docs_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }
        $has_training_column = self::table_has_column($table, 'is_training');

        if ($period_id !== '') {
            if ($has_training_column) {
                $row = $wpdb->get_row($wpdb->prepare(
                    "SELECT *
                     FROM {$table}
                     WHERE candidate_user_id = %d
                       AND period_id = %s
                       AND COALESCE(is_training, 0) = %d
                     ORDER BY id DESC
                     LIMIT 1",
                    $candidate_user_id,
                    $period_id,
                    $is_training
                ), ARRAY_A);
            } else {
                $row = $wpdb->get_row($wpdb->prepare(
                    "SELECT *
                     FROM {$table}
                     WHERE candidate_user_id = %d
                       AND period_id = %s
                     ORDER BY id DESC
                     LIMIT 1",
                    $candidate_user_id,
                    $period_id
                ), ARRAY_A);
            }
        } else {
            if ($has_training_column) {
                $row = $wpdb->get_row($wpdb->prepare(
                    "SELECT *
                     FROM {$table}
                     WHERE candidate_user_id = %d
                       AND COALESCE(is_training, 0) = %d
                     ORDER BY created_at DESC, id DESC
                     LIMIT 1",
                    $candidate_user_id,
                    $is_training
                ), ARRAY_A);
            } else {
                $row = $wpdb->get_row($wpdb->prepare(
                    "SELECT *
                     FROM {$table}
                     WHERE candidate_user_id = %d
                     ORDER BY created_at DESC, id DESC
                     LIMIT 1",
                    $candidate_user_id
                ), ARRAY_A);
            }
        }
        if (!is_array($row)) {
            return [];
        }

        $pdf_path = $this->sanitize_remittance_pdf_relative_path((string) ($row['pdf_path'] ?? ''));
        $pdf_hash = strtolower(preg_replace('/[^a-f0-9]/i', '', (string) ($row['pdf_hash'] ?? '')));
        if (!is_string($pdf_hash)) {
            $pdf_hash = '';
        }
        $pdf_hash = substr($pdf_hash, 0, 64);

        return [
            'id' => (int) ($row['id'] ?? 0),
            'candidate_user_id' => (int) ($row['candidate_user_id'] ?? 0),
            'period_id' => sanitize_text_field((string) ($row['period_id'] ?? '')),
            'payout_run_id' => max(0, (int) ($row['payout_run_id'] ?? 0)),
            'doc_status' => $this->normalize_remittance_doc_status((string) ($row['doc_status'] ?? 'generated')),
            'pdf_path' => $pdf_path,
            'pdf_hash' => $pdf_hash,
            'created_at' => $this->normalize_invoice_datetime((string) ($row['created_at'] ?? '')),
            'is_training' => $has_training_column ? (!empty($row['is_training']) ? 1 : 0) : 0,
        ];
    }

    private function get_candidate_remittance_doc_map_for_periods($candidate_user_id, $period_ids = [], $is_training = 0) {
        $candidate_user_id = (int) $candidate_user_id;
        $period_ids = array_values(array_unique(array_filter(array_map(static function ($value) {
            return sanitize_text_field((string) $value);
        }, (array) $period_ids))));
        $is_training = $this->resolve_training_flag($is_training, 0);
        if ($candidate_user_id < 1 || !$period_ids) {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_remittance_docs_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }
        $has_training_column = self::table_has_column($table, 'is_training');

        $placeholders = implode(',', array_fill(0, count($period_ids), '%s'));
        if ($has_training_column) {
            $params = array_merge([$candidate_user_id], $period_ids, [$is_training]);
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE candidate_user_id = %d
                   AND period_id IN ({$placeholders})
                   AND COALESCE(is_training, 0) = %d",
                ...$params
            ), ARRAY_A);
        } else {
            $params = array_merge([$candidate_user_id], $period_ids);
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE candidate_user_id = %d
                   AND period_id IN ({$placeholders})",
                ...$params
            ), ARRAY_A);
        }
        if (!is_array($rows)) {
            return [];
        }

        $map = [];
        foreach ($rows as $row) {
            $period_id = sanitize_text_field((string) ($row['period_id'] ?? ''));
            if ($period_id === '') {
                continue;
            }
            $parsed = [
                'id' => (int) ($row['id'] ?? 0),
                'candidate_user_id' => (int) ($row['candidate_user_id'] ?? 0),
                'period_id' => $period_id,
                'payout_run_id' => max(0, (int) ($row['payout_run_id'] ?? 0)),
                'doc_status' => $this->normalize_remittance_doc_status((string) ($row['doc_status'] ?? 'generated')),
                'pdf_path' => $this->sanitize_remittance_pdf_relative_path((string) ($row['pdf_path'] ?? '')),
                'pdf_hash' => substr(strtolower((string) preg_replace('/[^a-f0-9]/i', '', (string) ($row['pdf_hash'] ?? ''))), 0, 64),
                'created_at' => $this->normalize_invoice_datetime((string) ($row['created_at'] ?? '')),
                'is_training' => $has_training_column ? (!empty($row['is_training']) ? 1 : 0) : 0,
            ];
            if (!isset($map[$period_id])) {
                $map[$period_id] = $parsed;
                continue;
            }
            $existing_id = (int) ($map[$period_id]['id'] ?? 0);
            if ((int) ($parsed['id'] ?? 0) > $existing_id) {
                $map[$period_id] = $parsed;
            }
        }
        return $map;
    }

    private function get_candidate_remittance_generation_map_for_period($period_id, $candidate_user_ids = [], $is_training = 0) {
        $period_id = sanitize_text_field((string) $period_id);
        $candidate_user_ids = array_values(array_unique(array_filter(array_map('intval', (array) $candidate_user_ids))));
        $is_training = $this->resolve_training_flag($is_training, 0);
        if ($period_id === '' || !$candidate_user_ids) {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_remittance_docs_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }
        $has_training_column = self::table_has_column($table, 'is_training');

        $placeholders = implode(',', array_fill(0, count($candidate_user_ids), '%d'));
        if ($has_training_column) {
            $params = array_merge([$period_id], $candidate_user_ids, [$is_training]);
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT candidate_user_id, doc_status, pdf_path
                 FROM {$table}
                 WHERE period_id = %s
                   AND candidate_user_id IN ({$placeholders})
                   AND COALESCE(is_training, 0) = %d",
                ...$params
            ), ARRAY_A);
        } else {
            $params = array_merge([$period_id], $candidate_user_ids);
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT candidate_user_id, doc_status, pdf_path
                 FROM {$table}
                 WHERE period_id = %s
                   AND candidate_user_id IN ({$placeholders})",
                ...$params
            ), ARRAY_A);
        }
        if (!is_array($rows)) {
            return [];
        }

        $map = [];
        foreach ($rows as $row) {
            $candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
            if ($candidate_user_id < 1) {
                continue;
            }
            $status = $this->normalize_remittance_doc_status((string) ($row['doc_status'] ?? 'generated'));
            $path = $this->sanitize_remittance_pdf_relative_path((string) ($row['pdf_path'] ?? ''));
            if ($status === 'voided' || $path === '') {
                continue;
            }
            $map[$candidate_user_id] = true;
        }
        return $map;
    }

