    private function get_candidate_pay_approvals_for_remittance($candidate_user_id, $period_id, $is_training = 0) {
        $candidate_user_id = (int) $candidate_user_id;
        $period_id = sanitize_text_field((string) $period_id);
        $is_training = $this->resolve_training_flag($is_training, 0);
        if ($candidate_user_id < 1 || $period_id === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_pay_approvals_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }
        $has_dispute_flag = self::table_has_column($table, 'dispute_flag');
        $dispute_sql = $has_dispute_flag ? "AND COALESCE(dispute_flag, 0) = 0" : '';
        $has_training_column = self::table_has_column($table, 'is_training');
        if ($has_training_column) {
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT booking_id, booking_day_date, approved_method
                 FROM {$table}
                 WHERE candidate_user_id = %d
                   AND period_id = %s
                   AND approval_status = %s
                   {$dispute_sql}
                   AND COALESCE(is_training, 0) = %d
                 ORDER BY booking_day_date ASC, id ASC",
                $candidate_user_id,
                $period_id,
                'approved',
                $is_training
            ), ARRAY_A);
        } else {
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT booking_id, booking_day_date, approved_method
                 FROM {$table}
                 WHERE candidate_user_id = %d
                   AND period_id = %s
                   AND approval_status = %s
                   {$dispute_sql}
                 ORDER BY booking_day_date ASC, id ASC",
                $candidate_user_id,
                $period_id,
                'approved'
            ), ARRAY_A);
        }
        if (!is_array($rows)) {
            return [];
        }

        $out = [];
        foreach ($rows as $row) {
            $booking_id = max(0, (int) ($row['booking_id'] ?? 0));
            $booking_day_date = $this->normalize_invoice_date((string) ($row['booking_day_date'] ?? ''));
            if ($booking_id < 1 || $booking_day_date === '') {
                continue;
            }
            $out[] = [
                'booking_id' => $booking_id,
                'booking_day_date' => $booking_day_date,
                'approved_method' => sanitize_key((string) ($row['approved_method'] ?? 'school_confirmed')),
            ];
        }
        return $out;
    }

    private function get_remittance_approval_status_label($approved_method) {
        $approved_method = sanitize_key((string) $approved_method);
        if ($approved_method === 'auto_approved') {
            return 'Auto-approved';
        }
        if ($approved_method === 'staff_override') {
            return 'Staff override';
        }
        return 'Approved';
    }

    private function get_remittance_school_label_for_booking($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return 'Unknown school';
        }

        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        if ($school_id > 0) {
            return $this->get_invoice_school_display_name($school_id, '');
        }

        $fallback = trim((string) get_post_meta($booking_id, 'cmn_school_name', true));
        if ($fallback !== '') {
            return sanitize_text_field($fallback);
        }

        return 'Unknown school';
    }

    private function get_remittance_role_label_for_booking($booking_id, $rate_row = []) {
        $booking_id = (int) $booking_id;
        $rate_row = is_array($rate_row) ? $rate_row : [];

        $role = sanitize_text_field((string) ($rate_row['role_label'] ?? ''));
        if ($role !== '') {
            return $role;
        }

        foreach (['cmn_role_label', 'cmn_role_type', 'cmn_role', 'cmn_role_name'] as $meta_key) {
            $value = sanitize_text_field((string) get_post_meta($booking_id, $meta_key, true));
            if ($value !== '') {
                return $value;
            }
        }

        return 'Cover booking';
    }

    private function trim_remittance_text($value, $max_chars = 0) {
        $value = sanitize_text_field((string) $value);
        $max_chars = max(0, (int) $max_chars);
        if ($max_chars < 1 || $value === '') {
            return $value;
        }

        if (function_exists('mb_strlen') && function_exists('mb_substr')) {
            if (mb_strlen($value) > $max_chars) {
                return (string) mb_substr($value, 0, $max_chars);
            }
            return $value;
        }

        if (strlen($value) > $max_chars) {
            return (string) substr($value, 0, $max_chars);
        }
        return $value;
    }

    private function build_candidate_remittance_pdf_lines($payload = []) {
        $payload = is_array($payload) ? $payload : [];
        $candidate_label = $this->trim_remittance_text((string) ($payload['candidate_label'] ?? 'Candidate'), 100);
        $period_start = $this->normalize_invoice_date((string) ($payload['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($payload['period_end'] ?? ''));
        $pay_date = $this->normalize_invoice_date((string) ($payload['pay_date'] ?? ''));
        $gross_amount = round((float) ($payload['gross_amount'] ?? 0), 2);
        $shifts_count = max(0, (int) ($payload['shifts_count'] ?? 0));
        $adjustments_total = round((float) ($payload['adjustments_total'] ?? 0), 2);
        $approval_rows = is_array($payload['approval_rows'] ?? null) ? (array) $payload['approval_rows'] : [];

        $period_label = ($period_start !== '' ? $period_start : 'N/A') . ' to ' . ($period_end !== '' ? $period_end : 'N/A');
        $pay_date_label = $pay_date !== '' ? $pay_date : 'N/A';

        $lines = [];
        $lines[] = 'CoverMeNow Weekly Remittance Statement';
        $lines[] = '';
        $lines[] = 'Candidate   : ' . $candidate_label;
        $lines[] = 'Pay period  : ' . $period_label . ' (Fri-Thu)';
        $lines[] = 'Pay date    : ' . $pay_date_label;
        $lines[] = 'Gross pay   : GBP ' . number_format($gross_amount, 2);
        $lines[] = 'Shifts count: ' . number_format($shifts_count);
        if (abs($adjustments_total) > 0.009) {
            $adjustment_prefix = $adjustments_total >= 0 ? '+' : '-';
            $lines[] = 'Adjustments : ' . $adjustment_prefix . 'GBP ' . number_format(abs($adjustments_total), 2);
        }
        $lines[] = '';
        $lines[] = 'Worked booking days';
        $lines[] = sprintf('%-10s %-22s %-16s %10s %-14s', 'Date', 'School', 'Role', 'Day Rate', 'Status');
        $lines[] = str_repeat('-', 80);

        if (!$approval_rows) {
            $lines[] = 'No approved booking-days were recorded for this payout item.';
        } else {
            foreach ($approval_rows as $approval_row) {
                $date_label = $this->normalize_invoice_date((string) ($approval_row['booking_day_date'] ?? ''));
                if ($date_label === '') {
                    $date_label = 'N/A';
                }
                $school_label = $this->trim_remittance_text((string) ($approval_row['school_label'] ?? 'Unknown school'), 22);
                $role_label = $this->trim_remittance_text((string) ($approval_row['role_label'] ?? 'Cover booking'), 16);
                $status_label = $this->trim_remittance_text((string) ($approval_row['status_label'] ?? 'Approved'), 14);
                $day_rate = round((float) ($approval_row['day_rate'] ?? 0), 2);
                $lines[] = sprintf(
                    '%-10s %-22s %-16s %10s %-14s',
                    $date_label,
                    $school_label,
                    $role_label,
                    number_format($day_rate, 2),
                    $status_label
                );
            }
        }

        $lines[] = '';
        $lines[] = 'Self-employed: tax is your responsibility.';
        return $lines;
    }

    private function generate_candidate_remittance_pdf_binary($payload = []) {
        $lines = $this->build_candidate_remittance_pdf_lines($payload);
        if (!$lines) {
            $lines = ['CoverMeNow Weekly Remittance Statement', '', 'No remittance data available.'];
        }

        $pages = array_chunk($lines, 52);
        if (!$pages) {
            $pages = [[]];
        }

        $objects = [];
        $add_object = static function ($body) use (&$objects) {
            $object_id = count($objects) + 1;
            $objects[] = $object_id . " 0 obj\n" . $body . "\nendobj\n";
            return $object_id;
        };

        $font_regular_id = $add_object('<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>');
        $content_object_ids = [];
        foreach ($pages as $page_lines) {
            $stream_lines = [];
            $stream_lines[] = 'BT';
            $stream_lines[] = '/F1 9 Tf';
            $stream_lines[] = '11 TL';
            $stream_lines[] = '40 800 Td';
            foreach ($page_lines as $idx => $line) {
                if ($idx > 0) {
                    $stream_lines[] = 'T*';
                }
                $stream_lines[] = '(' . $this->escape_invoice_pdf_text((string) $line, 150) . ') Tj';
            }
            $stream_lines[] = 'ET';
            $stream = implode("\n", $stream_lines) . "\n";
            $content_object_ids[] = $add_object('<< /Length ' . strlen($stream) . " >>\nstream\n" . $stream . "endstream");
        }

        $pages_object_id = count($objects) + 1;
        $page_object_ids = [];
        for ($i = 0; $i < count($content_object_ids); $i++) {
            $page_object_ids[] = $pages_object_id + 1 + $i;
        }
        $page_kids = implode(' ', array_map(static function ($id) {
            return (int) $id . ' 0 R';
        }, $page_object_ids));
        $add_object('<< /Type /Pages /Kids [' . $page_kids . '] /Count ' . count($page_object_ids) . ' >>');

        foreach ($content_object_ids as $content_object_id) {
            $resources = '<< /Font << /F1 ' . $font_regular_id . ' 0 R >> >>';
            $add_object(
                '<< /Type /Page /Parent ' . $pages_object_id . ' 0 R /MediaBox [0 0 595 842] ' .
                '/Resources ' . $resources . ' /Contents ' . (int) $content_object_id . ' 0 R >>'
            );
        }

        $catalog_id = $add_object('<< /Type /Catalog /Pages ' . $pages_object_id . ' 0 R >>');

        $pdf = "%PDF-1.4\n";
        $offsets = [0];
        foreach ($objects as $object_text) {
            $offsets[] = strlen($pdf);
            $pdf .= $object_text;
        }
        $xref_offset = strlen($pdf);
        $pdf .= "xref\n0 " . (count($objects) + 1) . "\n";
        $pdf .= "0000000000 65535 f \n";
        for ($i = 1; $i <= count($objects); $i++) {
            $pdf .= sprintf("%010d 00000 n \n", (int) $offsets[$i]);
        }
        $pdf .= "trailer\n<< /Size " . (count($objects) + 1) . " /Root " . $catalog_id . " 0 R >>\n";
        $pdf .= "startxref\n" . $xref_offset . "\n%%EOF";
        return $pdf;
    }

    private function get_candidate_remittance_pdf_download_filename($candidate_user_id, $period_id) {
        $candidate_user_id = (int) $candidate_user_id;
        $parsed_period = $this->parse_payroll_period_id($period_id);
        $period_start = $this->normalize_invoice_date((string) ($parsed_period['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($parsed_period['period_end'] ?? ''));
        if ($period_start === '' || $period_end === '') {
            return 'CMN-Remittance-' . max(1, $candidate_user_id) . '.pdf';
        }
        return 'CMN-Remittance-' . $period_start . '-to-' . $period_end . '.pdf';
    }

    /*
     * Prompt 32 acceptance tests:
     * 1) Candidate remittance PDF is generated from payout run item + approved pay approvals.
     * 2) Document row stores hash/path and supports regeneration updates.
     * 3) PDF output excludes bank details and includes self-employed disclaimer.
     */
    public function generate_candidate_remittance_pdf($candidate_user_id, $period_id, $context = []) {
        $candidate_user_id = (int) $candidate_user_id;
        $period_id = sanitize_text_field((string) $period_id);
        $context = is_array($context) ? $context : [];
        $force_regenerate = !empty($context['force_regenerate']);
        $actor_user_id = max(0, (int) ($context['actor_user_id'] ?? get_current_user_id()));
        $trigger = sanitize_key((string) ($context['trigger'] ?? 'manual'));
        $is_training = $this->resolve_training_flag($context['is_training'] ?? null, 0);
        if ($trigger === '') {
            $trigger = 'manual';
        }

        if ($candidate_user_id < 1 || $period_id === '') {
            return new WP_Error('cmn_remittance_invalid_context', 'Candidate remittance context is invalid.');
        }
        $base_period_id = $period_id;
        if ($is_training && substr($period_id, -10) !== '__training') {
            $period_id .= '__training';
        }

        self::migrate_schema_v56_payroll_payout_runs();
        self::migrate_schema_v57_payroll_adjustments_and_disputes();
        self::migrate_schema_v59_candidate_remittance_docs();
        self::migrate_schema_v62_training_mode_state_and_scoping();

        $existing_doc = $this->get_candidate_remittance_doc_record($candidate_user_id, $period_id, $is_training);
        if (!$force_regenerate && !empty($existing_doc['id'])) {
            $existing_file_path = $this->get_candidate_remittance_doc_absolute_path((string) ($existing_doc['pdf_path'] ?? ''));
            if ($existing_file_path !== '' && is_readable($existing_file_path)) {
                return [
                    'ok' => true,
                    'created' => false,
                    'regenerated' => false,
                    'doc' => $existing_doc,
                    'file_path' => $existing_file_path,
                    'download_name' => $this->get_candidate_remittance_pdf_download_filename($candidate_user_id, $period_id),
                    'period_id' => $period_id,
                    'payout_run_id' => (int) ($existing_doc['payout_run_id'] ?? 0),
                ];
            }
        }

        $payout_item = $this->get_candidate_payout_run_item_for_period($candidate_user_id, $period_id, $is_training);
        if (empty($payout_item['id'])) {
            return new WP_Error('cmn_remittance_payout_item_missing', 'Remittance is not available for this period yet.');
        }

        $approval_rows = $this->get_candidate_pay_approvals_for_remittance($candidate_user_id, $period_id, $is_training);
        $booking_ids = array_values(array_unique(array_filter(array_map('intval', array_column($approval_rows, 'booking_id')))));
        $rate_rows_map = $this->get_booking_rate_rows_map($booking_ids);
        $booking_meta_rate_cache = [];
        $approval_lines = [];
        foreach ($approval_rows as $approval_row) {
            $booking_id = max(0, (int) ($approval_row['booking_id'] ?? 0));
            $booking_day_date = $this->normalize_invoice_date((string) ($approval_row['booking_day_date'] ?? ''));
            if ($booking_id < 1 || $booking_day_date === '') {
                continue;
            }
            $rate_row = (isset($rate_rows_map[$booking_id]) && is_array($rate_rows_map[$booking_id]))
                ? (array) $rate_rows_map[$booking_id]
                : [];
            $day_rate = $this->resolve_payroll_day_rate_for_booking($booking_id, $rate_rows_map, $booking_meta_rate_cache);
            $booking_meta_rate_cache[$booking_id] = $day_rate;
            $approval_lines[] = [
                'booking_id' => $booking_id,
                'booking_day_date' => $booking_day_date,
                'day_rate' => round((float) $day_rate, 2),
                'school_label' => $this->get_remittance_school_label_for_booking($booking_id),
                'role_label' => $this->get_remittance_role_label_for_booking($booking_id, $rate_row),
                'status_label' => $this->get_remittance_approval_status_label((string) ($approval_row['approved_method'] ?? 'school_confirmed')),
            ];
        }

        $period_start = $this->normalize_invoice_date((string) ($payout_item['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($payout_item['period_end'] ?? ''));
        if ($period_start === '' || $period_end === '') {
            $parsed = $this->parse_payroll_period_id($is_training ? $base_period_id : $period_id);
            $period_start = $this->normalize_invoice_date((string) ($parsed['period_start'] ?? ''));
            $period_end = $this->normalize_invoice_date((string) ($parsed['period_end'] ?? ''));
        }
        $pay_date = '';
        if ($period_start !== '') {
            $period_ref = function_exists('cmn_payroll_get_period_for_date')
                ? (array) cmn_payroll_get_period_for_date($period_start)
                : (array) $this->get_payroll_period_for_date($period_start);
            $pay_date = $this->normalize_invoice_date((string) ($period_ref['pay_date'] ?? ''));
        }

        $payload = [
            'candidate_label' => $this->get_payroll_candidate_label($candidate_user_id),
            'period_start' => $period_start,
            'period_end' => $period_end,
            'pay_date' => $pay_date,
            'gross_amount' => round((float) ($payout_item['gross_amount'] ?? 0), 2),
            'shifts_count' => max(0, (int) ($payout_item['shifts_count'] ?? 0)),
            'adjustments_total' => round((float) ($payout_item['adjustments_total'] ?? 0), 2),
            'approval_rows' => $approval_lines,
        ];
        $binary = $this->generate_candidate_remittance_pdf_binary($payload);
        if (!is_string($binary) || $binary === '') {
            return new WP_Error('cmn_remittance_pdf_generate_failed', 'Unable to generate remittance PDF.');
        }

        $storage = $this->get_candidate_remittance_storage_directory();
        if (is_wp_error($storage)) {
            return $storage;
        }
        $remittance_dir = (string) ($storage['remittance_dir'] ?? '');
        if ($remittance_dir === '' || !is_dir($remittance_dir) || !is_writable($remittance_dir)) {
            return new WP_Error('cmn_remittance_storage_unavailable', 'Remittance storage directory is unavailable.');
        }

        $period_slug = preg_replace('/[^0-9\-_]+/', '-', str_replace('__', '-to-', $period_id));
        if (!is_string($period_slug) || $period_slug === '') {
            $period_slug = 'period';
        }
        $token = substr(hash('sha256', $candidate_user_id . '|' . $period_id . '|' . microtime(true) . '|' . wp_generate_password(8, false, false)), 0, 14);
        $filename = sanitize_file_name('remittance-' . $candidate_user_id . '-' . $period_slug . '-' . $token . '.pdf');
        if ($filename === '' || strtolower(substr($filename, -4)) !== '.pdf') {
            $filename = 'remittance-' . $candidate_user_id . '-' . $period_slug . '-' . $token . '.pdf';
        }
        $absolute_path = $remittance_dir . '/' . $filename;
        $write_bytes = @file_put_contents($absolute_path, $binary, LOCK_EX);
        if ($write_bytes === false || (int) $write_bytes < 1 || !is_readable($absolute_path)) {
            return new WP_Error('cmn_remittance_file_write_failed', 'Unable to write remittance PDF.');
        }
        @chmod($absolute_path, 0600);

        $relative_path = 'cmn/remittance/' . $filename;
        $pdf_hash = hash('sha256', $binary);
        $doc_status = !empty($existing_doc['id']) ? 'regenerated' : 'generated';
        $payout_run_id = max(0, (int) ($payout_item['payout_run_id'] ?? 0));
        $now = current_time('mysql');

        global $wpdb;
        $table = $this->get_candidate_remittance_docs_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return new WP_Error('cmn_remittance_table_missing', 'Remittance document table is unavailable.');
        }
        $has_training_column = self::table_has_column($table, 'is_training');

        if (!empty($existing_doc['id'])) {
            $update_payload = [
                'payout_run_id' => $payout_run_id,
                'doc_status' => $doc_status,
                'pdf_path' => $relative_path,
                'pdf_hash' => $pdf_hash,
                'created_at' => $now,
            ];
            $update_format = ['%d', '%s', '%s', '%s', '%s'];
            if ($has_training_column) {
                $update_payload['is_training'] = $is_training;
                $update_format[] = '%d';
            }
            $updated = $wpdb->update(
                $table,
                $update_payload,
                [
                    'id' => (int) ($existing_doc['id'] ?? 0),
                ],
                $update_format,
                ['%d']
            );
            if ($updated === false) {
                return new WP_Error('cmn_remittance_doc_update_failed', 'Unable to update remittance document record.');
            }

            $old_file = $this->get_candidate_remittance_doc_absolute_path((string) ($existing_doc['pdf_path'] ?? ''));
            if ($old_file !== '' && $old_file !== $absolute_path && file_exists($old_file)) {
                @unlink($old_file);
            }
        } else {
            $insert_payload = [
                'candidate_user_id' => $candidate_user_id,
                'period_id' => $period_id,
                'payout_run_id' => $payout_run_id,
                'doc_status' => $doc_status,
                'pdf_path' => $relative_path,
                'pdf_hash' => $pdf_hash,
                'created_at' => $now,
            ];
            $insert_format = ['%d', '%s', '%d', '%s', '%s', '%s', '%s'];
            if ($has_training_column) {
                $insert_payload['is_training'] = $is_training;
                $insert_format[] = '%d';
            }
            $inserted = $wpdb->insert($table, $insert_payload, $insert_format);
            if ($inserted === false) {
                return new WP_Error('cmn_remittance_doc_insert_failed', 'Unable to save remittance document record.');
            }
        }

        $doc = $this->get_candidate_remittance_doc_record($candidate_user_id, $period_id, $is_training);
        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'finance',
                'entity_type' => 'candidate',
                'entity_id' => $candidate_user_id,
                'event_type' => 'remittance_pdf_generated',
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'period_id' => $period_id,
                    'base_period_id' => $base_period_id,
                    'payout_run_id' => $payout_run_id,
                    'doc_status' => $doc_status,
                    'trigger' => $trigger,
                    'is_training' => $is_training,
                    'shifts_count' => max(0, (int) ($payout_item['shifts_count'] ?? 0)),
                    'gross_amount' => round((float) ($payout_item['gross_amount'] ?? 0), 2),
                ],
            ]);
        }

        return [
            'ok' => true,
            'created' => empty($existing_doc['id']),
            'regenerated' => !empty($existing_doc['id']),
            'doc' => $doc,
            'file_path' => $absolute_path,
            'download_name' => $this->get_candidate_remittance_pdf_download_filename($candidate_user_id, $period_id),
            'period_id' => $period_id,
            'payout_run_id' => $payout_run_id,
        ];
    }

    private function is_candidate_bank_complete_for_payroll($candidate_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return false;
        }
        $bank_details = $this->get_candidate_bank_details_record($candidate_user_id);
        if (!$bank_details) {
            return false;
        }

        $sort_code_masked = sanitize_text_field((string) ($bank_details['sort_code_masked'] ?? ''));
        $account_number_last4 = preg_replace('/\D+/', '', (string) ($bank_details['account_number_last4'] ?? ''));
        if (!is_string($account_number_last4)) {
            $account_number_last4 = '';
        }

        return $sort_code_masked !== '' && strlen($account_number_last4) === 4;
    }

    private function get_payroll_candidate_label($candidate_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return 'Candidate';
        }

        $user = get_user_by('id', $candidate_user_id);
        if ($user instanceof WP_User) {
            $label = trim((string) ($user->display_name ?? ''));
            if ($label !== '') {
                return $label;
            }
            $fallback = trim((string) ($user->user_login ?? ''));
            if ($fallback !== '') {
                return $fallback;
            }
        }

        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        if ($candidate_id > 0) {
            $title = trim((string) get_the_title($candidate_id));
            if ($title !== '') {
                return $title;
            }
        }

        return 'Candidate #' . $candidate_user_id;
    }

    private function get_payroll_approved_booking_days_for_period($period_id, $candidate_user_id = 0, $is_training = 0) {
        $period_id = sanitize_text_field((string) $period_id);
        $candidate_user_id = max(0, (int) $candidate_user_id);
        $is_training = $this->resolve_training_flag($is_training, 0);
        if ($period_id === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_pay_approvals_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }
        $has_dispute_flag = self::table_has_column($table, 'dispute_flag');
        $dispute_sql = $has_dispute_flag ? "AND COALESCE(dispute_flag, 0) = 0" : "";
        $has_training_column = self::table_has_column($table, 'is_training');
        $training_sql = $has_training_column ? "AND COALESCE(is_training, 0) = %d" : "";

        if ($candidate_user_id > 0) {
            if ($has_training_column) {
                $rows = $wpdb->get_results($wpdb->prepare(
                    "SELECT candidate_user_id, booking_id, booking_day_date
                     FROM {$table}
                     WHERE period_id = %s
                       AND approval_status = %s
                       {$dispute_sql}
                       {$training_sql}
                       AND candidate_user_id = %d
                     ORDER BY booking_day_date ASC, id ASC",
                    $period_id,
                    'approved',
                    $is_training,
                    $candidate_user_id
                ), ARRAY_A);
            } else {
                $rows = $wpdb->get_results($wpdb->prepare(
                    "SELECT candidate_user_id, booking_id, booking_day_date
                     FROM {$table}
                     WHERE period_id = %s
                       AND approval_status = %s
                       {$dispute_sql}
                       AND candidate_user_id = %d
                     ORDER BY booking_day_date ASC, id ASC",
                    $period_id,
                    'approved',
                    $candidate_user_id
                ), ARRAY_A);
            }
        } else {
            if ($has_training_column) {
                $rows = $wpdb->get_results($wpdb->prepare(
                    "SELECT candidate_user_id, booking_id, booking_day_date
                     FROM {$table}
                     WHERE period_id = %s
                       AND approval_status = %s
                       {$dispute_sql}
                       {$training_sql}
                     ORDER BY booking_day_date ASC, id ASC",
                    $period_id,
                    'approved',
                    $is_training
                ), ARRAY_A);
            } else {
                $rows = $wpdb->get_results($wpdb->prepare(
                    "SELECT candidate_user_id, booking_id, booking_day_date
                     FROM {$table}
                     WHERE period_id = %s
                       AND approval_status = %s
                       {$dispute_sql}
                     ORDER BY booking_day_date ASC, id ASC",
                    $period_id,
                    'approved'
                ), ARRAY_A);
            }
        }
        if (!is_array($rows)) {
            return [];
        }

        $out = [];
        foreach ($rows as $row) {
            $row_candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
            $booking_id = max(0, (int) ($row['booking_id'] ?? 0));
            $booking_day_date = $this->normalize_invoice_date((string) ($row['booking_day_date'] ?? ''));
            if ($row_candidate_user_id < 1 || $booking_id < 1 || $booking_day_date === '') {
                continue;
            }
            $out[] = [
                'candidate_user_id' => $row_candidate_user_id,
                'booking_id' => $booking_id,
                'booking_day_date' => $booking_day_date,
            ];
        }
        return $out;
    }

    private function resolve_payroll_day_rate_for_booking($booking_id, $rate_rows_map = [], $booking_meta_rate_cache = []) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return 0.00;
        }

        $rate_row = (is_array($rate_rows_map) && isset($rate_rows_map[$booking_id]) && is_array($rate_rows_map[$booking_id]))
            ? (array) $rate_rows_map[$booking_id]
            : [];
        $candidate_pay = round((float) ($rate_row['candidate_pay_rate'] ?? 0), 2);
        if ($candidate_pay > 0) {
            return $candidate_pay;
        }

        if (is_array($booking_meta_rate_cache) && isset($booking_meta_rate_cache[$booking_id])) {
            return round((float) $booking_meta_rate_cache[$booking_id], 2);
        }

        $candidate_pay = round((float) get_post_meta($booking_id, 'cmn_candidate_pay_rate', true), 2);
        if ($candidate_pay <= 0) {
            $candidate_pay = round((float) get_post_meta($booking_id, 'cmn_rate', true), 2);
        }
        return max(0, round($candidate_pay, 2));
    }

    private function build_payroll_candidate_totals_for_period($period_id, $candidate_filter_user_id = 0, $actor_user_id = 0, $log_missing_pay_events = true, $is_training = 0) {
        $period_id = sanitize_text_field((string) $period_id);
        $candidate_filter_user_id = max(0, (int) $candidate_filter_user_id);
        $actor_user_id = max(0, (int) $actor_user_id);
        $log_missing_pay_events = (bool) $log_missing_pay_events;
        $is_training = $this->resolve_training_flag($is_training, 0);
        if ($period_id === '') {
            return [
                'rows' => [],
                'total_candidates' => 0,
                'total_gross' => 0.00,
                'missing_rate_days' => 0,
            ];
        }

        $approval_rows = $this->get_payroll_approved_booking_days_for_period($period_id, $candidate_filter_user_id, $is_training);
        if (!$approval_rows) {
            return [
                'rows' => [],
                'total_candidates' => 0,
                'total_gross' => 0.00,
                'missing_rate_days' => 0,
            ];
        }

        $booking_ids = array_values(array_unique(array_filter(array_map('intval', array_column($approval_rows, 'booking_id')))));
        $rate_rows_map = $this->get_booking_rate_rows_map($booking_ids);
        $booking_meta_rate_cache = [];

        $candidate_totals = [];
        $missing_rate_days = 0;
        foreach ($approval_rows as $approval_row) {
            $candidate_user_id = max(0, (int) ($approval_row['candidate_user_id'] ?? 0));
            $booking_id = max(0, (int) ($approval_row['booking_id'] ?? 0));
            $booking_day_date = $this->normalize_invoice_date((string) ($approval_row['booking_day_date'] ?? ''));
            if ($candidate_user_id < 1 || $booking_id < 1 || $booking_day_date === '') {
                continue;
            }

            $day_rate = $this->resolve_payroll_day_rate_for_booking($booking_id, $rate_rows_map, $booking_meta_rate_cache);
            $booking_meta_rate_cache[$booking_id] = $day_rate;
            if ($day_rate <= 0) {
                $missing_rate_days++;
                if ($log_missing_pay_events && function_exists('cmn_audit_log_event')) {
                    cmn_audit_log_event([
                        'module' => 'payroll',
                        'entity_type' => 'booking',
                        'entity_id' => $booking_id,
                        'event_type' => 'missing_pay_data',
                        'event_ref' => $period_id . ':' . $booking_id . ':' . $booking_day_date,
                        'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                        'metadata' => [
                            'period_id' => $period_id,
                            'booking_day_date' => $booking_day_date,
                            'candidate_user_id' => $candidate_user_id,
                            'source' => 'payroll_payout_generation',
                            'error_code' => 'missing_day_rate',
                        ],
                    ]);
                }
                continue;
            }

            if (!isset($candidate_totals[$candidate_user_id])) {
                $candidate_totals[$candidate_user_id] = [
                    'candidate_user_id' => $candidate_user_id,
                    'candidate_label' => $this->get_payroll_candidate_label($candidate_user_id),
                    'gross_amount' => 0.00,
                    'shifts_count' => 0,
                    'bank_status' => 'missing',
                    'payout_item_status' => 'hold',
                ];
            }

            $candidate_totals[$candidate_user_id]['gross_amount'] += (float) $day_rate;
            $candidate_totals[$candidate_user_id]['shifts_count'] += 1;
        }

        $rows = [];
        $total_gross = 0.00;
        foreach ($candidate_totals as $candidate_user_id => $row) {
            $candidate_user_id = (int) $candidate_user_id;
            $bank_complete = $this->is_candidate_bank_complete_for_payroll($candidate_user_id);
            $self_employed_ack_complete = $this->is_candidate_self_employed_ack_complete_for_payroll($candidate_user_id);
            $bank_status = $bank_complete ? 'complete' : 'missing';
            $payout_item_status = ($bank_complete && $self_employed_ack_complete) ? 'ready' : 'hold';

            $gross_amount = round((float) ($row['gross_amount'] ?? 0), 2);
            $total_gross += $gross_amount;
            $rows[] = [
                'candidate_user_id' => $candidate_user_id,
                'candidate_label' => sanitize_text_field((string) ($row['candidate_label'] ?? $this->get_payroll_candidate_label($candidate_user_id))),
                'gross_amount' => $gross_amount,
                'shifts_count' => max(0, (int) ($row['shifts_count'] ?? 0)),
                'bank_status' => $bank_status,
                'compliance_status' => $self_employed_ack_complete ? 'accepted' : 'missing',
                'payout_item_status' => $payout_item_status,
            ];
        }

        usort($rows, static function ($left, $right) {
            $left_label = strtolower((string) ($left['candidate_label'] ?? ''));
            $right_label = strtolower((string) ($right['candidate_label'] ?? ''));
            if ($left_label === $right_label) {
                return ((int) ($left['candidate_user_id'] ?? 0)) <=> ((int) ($right['candidate_user_id'] ?? 0));
            }
            return strcmp($left_label, $right_label);
        });

        return [
            'rows' => $rows,
            'total_candidates' => count($rows),
            'total_gross' => round($total_gross, 2),
            'missing_rate_days' => $missing_rate_days,
        ];
    }

    private function normalize_payroll_adjustment_status($status) {
        $status = sanitize_key((string) $status);
        if (!in_array($status, ['pending', 'approved', 'rejected', 'applied'], true)) {
            return 'pending';
        }
        return $status;
    }

    private function get_payroll_period_start_for_comparison($period_id) {
        $period_id = sanitize_text_field((string) $period_id);
        if ($period_id === '') {
            return '';
        }
        $parsed = $this->parse_payroll_period_id($period_id);
        return $this->normalize_invoice_date((string) ($parsed['period_start'] ?? ''));
    }

    private function is_payroll_adjustment_eligible_for_period($adjustment_period_id, $target_period_id) {
        $adjustment_period_id = sanitize_text_field((string) $adjustment_period_id);
        $target_period_id = sanitize_text_field((string) $target_period_id);
        if ($adjustment_period_id === '' || $target_period_id === '') {
            return false;
        }
        if ($adjustment_period_id === $target_period_id) {
            return true;
        }

        $adjustment_start = $this->get_payroll_period_start_for_comparison($adjustment_period_id);
        $target_start = $this->get_payroll_period_start_for_comparison($target_period_id);
        if ($adjustment_start === '' || $target_start === '') {
            return false;
        }
        return strcmp($adjustment_start, $target_start) <= 0;
    }

    private function get_payroll_approved_unapplied_adjustments_for_period($period_id, $is_training = 0) {
        $period_id = sanitize_text_field((string) $period_id);
        $is_training = $this->resolve_training_flag($is_training, 0);
        if ($period_id === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_payroll_adjustments_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }

        $has_training_column = self::table_has_column($table, 'is_training');
        if ($has_training_column) {
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE adjustment_status = %s
                   AND (applied_in_period_id IS NULL OR applied_in_period_id = '')
                   AND COALESCE(is_training, 0) = %d
                 ORDER BY created_at ASC, id ASC",
                'approved',
                $is_training
            ), ARRAY_A);
        } else {
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE adjustment_status = %s
                   AND (applied_in_period_id IS NULL OR applied_in_period_id = '')
                 ORDER BY created_at ASC, id ASC",
                'approved'
            ), ARRAY_A);
        }
        if (!is_array($rows) || !$rows) {
            return [];
        }

        $out = [];
        foreach ($rows as $row) {
            $adjustment_id = (int) ($row['id'] ?? 0);
            $candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
            $adjustment_period_id = sanitize_text_field((string) ($row['period_id'] ?? ''));
            $amount = round((float) ($row['adjustment_amount'] ?? 0), 2);
            if ($adjustment_id < 1 || $candidate_user_id < 1 || $adjustment_period_id === '' || $amount == 0.00) {
                continue;
            }
            if (!$this->is_payroll_adjustment_eligible_for_period($adjustment_period_id, $period_id)) {
                continue;
            }

            $out[] = [
                'id' => $adjustment_id,
                'candidate_user_id' => $candidate_user_id,
                'period_id' => $adjustment_period_id,
                'adjustment_amount' => $amount,
                'adjustment_reason' => sanitize_text_field((string) ($row['adjustment_reason'] ?? '')),
                'adjustment_status' => $this->normalize_payroll_adjustment_status((string) ($row['adjustment_status'] ?? 'approved')),
                'created_by_user_id' => max(0, (int) ($row['created_by_user_id'] ?? 0)),
                'created_at' => $this->normalize_invoice_datetime((string) ($row['created_at'] ?? '')),
                'updated_at' => $this->normalize_invoice_datetime((string) ($row['updated_at'] ?? '')),
                'is_training' => $has_training_column ? (!empty($row['is_training']) ? 1 : 0) : 0,
            ];
        }

        return $out;
    }

    private function merge_payroll_adjustments_into_totals($base_totals, $adjustment_rows = []) {
        $base_totals = is_array($base_totals) ? $base_totals : [];
        $rows = is_array($base_totals['rows'] ?? null) ? (array) $base_totals['rows'] : [];
        $adjustment_rows = is_array($adjustment_rows) ? array_values($adjustment_rows) : [];

        if (!$rows && !$adjustment_rows) {
            return [
                'rows' => [],
                'total_candidates' => 0,
                'total_gross' => 0.00,
                'missing_rate_days' => max(0, (int) ($base_totals['missing_rate_days'] ?? 0)),
                'adjustments_count' => 0,
                'adjustments_total' => 0.00,
                'adjustment_rows' => [],
            ];
        }

        $rows_by_candidate = [];
        foreach ($rows as $row) {
            $candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
            if ($candidate_user_id < 1) {
                continue;
            }
            $rows_by_candidate[$candidate_user_id] = [
                'candidate_user_id' => $candidate_user_id,
                'candidate_label' => sanitize_text_field((string) ($row['candidate_label'] ?? $this->get_payroll_candidate_label($candidate_user_id))),
                'gross_amount' => round((float) ($row['gross_amount'] ?? 0), 2),
                'shifts_count' => max(0, (int) ($row['shifts_count'] ?? 0)),
                'adjustments_total' => round((float) ($row['adjustments_total'] ?? 0), 2),
                'bank_status' => sanitize_key((string) ($row['bank_status'] ?? 'missing')),
                'compliance_status' => sanitize_key((string) ($row['compliance_status'] ?? 'missing')),
                'payout_item_status' => sanitize_key((string) ($row['payout_item_status'] ?? 'hold')),
            ];
        }

        $adjustments_total = 0.00;
        $adjustments_count = 0;
        foreach ($adjustment_rows as $adjustment_row) {
            $candidate_user_id = max(0, (int) ($adjustment_row['candidate_user_id'] ?? 0));
            $amount = round((float) ($adjustment_row['adjustment_amount'] ?? 0), 2);
            if ($candidate_user_id < 1 || $amount == 0.00) {
                continue;
            }

            if (!isset($rows_by_candidate[$candidate_user_id])) {
                $bank_complete = $this->is_candidate_bank_complete_for_payroll($candidate_user_id);
                $self_employed_ack_complete = $this->is_candidate_self_employed_ack_complete_for_payroll($candidate_user_id);
                $rows_by_candidate[$candidate_user_id] = [
                    'candidate_user_id' => $candidate_user_id,
                    'candidate_label' => $this->get_payroll_candidate_label($candidate_user_id),
                    'gross_amount' => 0.00,
                    'shifts_count' => 0,
                    'adjustments_total' => 0.00,
                    'bank_status' => $bank_complete ? 'complete' : 'missing',
                    'compliance_status' => $self_employed_ack_complete ? 'accepted' : 'missing',
                    'payout_item_status' => ($bank_complete && $self_employed_ack_complete) ? 'ready' : 'hold',
                ];
            }

            $rows_by_candidate[$candidate_user_id]['gross_amount'] = round(((float) $rows_by_candidate[$candidate_user_id]['gross_amount']) + $amount, 2);
            $rows_by_candidate[$candidate_user_id]['adjustments_total'] = round(((float) $rows_by_candidate[$candidate_user_id]['adjustments_total']) + $amount, 2);
            $adjustments_total += $amount;
            $adjustments_count++;
        }

        $normalized_rows = array_values($rows_by_candidate);
        usort($normalized_rows, static function ($left, $right) {
            $left_label = strtolower((string) ($left['candidate_label'] ?? ''));
            $right_label = strtolower((string) ($right['candidate_label'] ?? ''));
            if ($left_label === $right_label) {
                return ((int) ($left['candidate_user_id'] ?? 0)) <=> ((int) ($right['candidate_user_id'] ?? 0));
            }
            return strcmp($left_label, $right_label);
        });

        $total_gross = 0.00;
        foreach ($normalized_rows as $row) {
            $total_gross += round((float) ($row['gross_amount'] ?? 0), 2);
        }

        return [
            'rows' => $normalized_rows,
            'total_candidates' => count($normalized_rows),
            'total_gross' => round($total_gross, 2),
            'missing_rate_days' => max(0, (int) ($base_totals['missing_rate_days'] ?? 0)),
            'adjustments_count' => $adjustments_count,
            'adjustments_total' => round($adjustments_total, 2),
            'adjustment_rows' => $adjustment_rows,
        ];
    }

    private function apply_payroll_adjustments_for_generated_run($adjustment_rows, $applied_period_id, $updated_at, $is_training = 0) {
        $adjustment_rows = is_array($adjustment_rows) ? $adjustment_rows : [];
        $applied_period_id = sanitize_text_field((string) $applied_period_id);
        $updated_at = $this->normalize_invoice_datetime((string) $updated_at);
        $is_training = $this->resolve_training_flag($is_training, 0);
        if (!$adjustment_rows || $applied_period_id === '' || $updated_at === '') {
            return [
                'applied_count' => 0,
                'applied_total' => 0.00,
                'applied_ids' => [],
            ];
        }

        global $wpdb;
        $table = $this->get_payroll_adjustments_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return new WP_Error('cmn_payroll_adjustments_table_missing', 'Payroll adjustments table is not available.');
        }
        $has_training_column = self::table_has_column($table, 'is_training');

        $applied_count = 0;
        $applied_total = 0.00;
        $applied_ids = [];
        foreach ($adjustment_rows as $adjustment_row) {
            $adjustment_id = (int) ($adjustment_row['id'] ?? 0);
            if ($adjustment_id < 1) {
                continue;
            }

            if ($has_training_column) {
                $updated = $wpdb->query($wpdb->prepare(
                    "UPDATE {$table}
                     SET adjustment_status = %s,
                         applied_in_period_id = %s,
                         updated_at = %s
                     WHERE id = %d
                       AND adjustment_status = %s
                       AND (applied_in_period_id IS NULL OR applied_in_period_id = '')
                       AND COALESCE(is_training, 0) = %d",
                    'applied',
                    $applied_period_id,
                    $updated_at,
                    $adjustment_id,
                    'approved',
                    $is_training
                ));
            } else {
                $updated = $wpdb->query($wpdb->prepare(
                    "UPDATE {$table}
                     SET adjustment_status = %s,
                         applied_in_period_id = %s,
                         updated_at = %s
                     WHERE id = %d
                       AND adjustment_status = %s
                       AND (applied_in_period_id IS NULL OR applied_in_period_id = '')",
                    'applied',
                    $applied_period_id,
                    $updated_at,
                    $adjustment_id,
                    'approved'
                ));
            }
            if ($updated === false) {
                return new WP_Error('cmn_payroll_adjustment_apply_failed', 'Unable to mark payroll adjustment as applied.');
            }
            if ((int) $updated < 1) {
                continue;
            }

            $amount = round((float) ($adjustment_row['adjustment_amount'] ?? 0), 2);
            $applied_count++;
            $applied_total += $amount;
            $applied_ids[] = $adjustment_id;
        }

        return [
            'applied_count' => $applied_count,
            'applied_total' => round($applied_total, 2),
            'applied_ids' => $applied_ids,
        ];
    }

    /*
     * Prompt 29 acceptance tests:
     * 1) Run is generated once per period (idempotent on period_id).
     * 2) Gross totals are calculated from approved pay-approval booking-days and booking rates.
     * 3) Missing bank details force payout_item_status='hold' while preserving calculated gross.
     *
     * Prompt 31 acceptance tests:
     * 1) Missing self-employed acknowledgement forces payout_item_status='hold'.
     * 2) Candidate can still work; only payout readiness is gated.
     *
     * Prompt 30 acceptance tests:
     * 1) Approved unapplied adjustments are included once and then marked applied.
     * 2) Disputed approvals are excluded because only approval_status='approved' rows are read.
     * 3) Existing historical runs are returned without mutation.
     */
    public function generate_payout_run_for_period($period_id, $context = []) {
        $period_id = sanitize_text_field((string) $period_id);
        $context = is_array($context) ? $context : [];
        $actor_user_id = max(0, (int) ($context['actor_user_id'] ?? get_current_user_id()));
        $trigger = sanitize_key((string) ($context['trigger'] ?? 'manual'));
        if ($trigger === '') {
            $trigger = 'manual';
        }
        $is_training = $this->resolve_training_flag($context['is_training'] ?? null, 0);
        $generated_by = sanitize_key((string) ($context['generated_by'] ?? ''));
        if (!in_array($generated_by, ['system', 'staff'], true)) {
            $generated_by = $actor_user_id > 0 ? 'staff' : 'system';
        }

        if ($period_id === '') {
            return new WP_Error('cmn_payroll_payout_period_required', 'Payroll period is required.');
        }
        $base_period_id = $period_id;
        if ($is_training && substr($period_id, -10) !== '__training') {
            $period_id .= '__training';
        }

        self::migrate_schema_v56_payroll_payout_runs();
        self::migrate_schema_v57_payroll_adjustments_and_disputes();
        self::migrate_schema_v58_candidate_compliance_ack();
        self::migrate_schema_v62_training_mode_state_and_scoping();

        global $wpdb;
        $runs_table = $this->get_payroll_payout_runs_table();
        $items_table = $this->get_payroll_payout_run_items_table();
        $runs_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $runs_table));
        $items_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $items_table));
        if ($runs_exists !== $runs_table || $items_exists !== $items_table) {
            return new WP_Error('cmn_payroll_payout_tables_missing', 'Payroll payout tables are not available.');
        }

        $existing_run = $this->get_payroll_payout_run_by_period_id($period_id, $is_training);
        if (!empty($existing_run['id'])) {
            $existing_items = $this->get_payroll_payout_run_items((int) $existing_run['id'], $is_training);
            return [
                'ok' => true,
                'created' => false,
                'already_exists' => true,
                'payout_run' => $existing_run,
                'items' => $existing_items,
            ];
        }

        $lock_row = $this->get_payroll_period_lock_row($period_id);
        $period_start = $this->normalize_invoice_date((string) ($lock_row['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($lock_row['period_end'] ?? ''));
        if ($period_start === '' || $period_end === '') {
            $parsed_bounds = $this->parse_payroll_period_id($is_training ? $base_period_id : $period_id);
            $period_start = $this->normalize_invoice_date((string) ($parsed_bounds['period_start'] ?? ''));
            $period_end = $this->normalize_invoice_date((string) ($parsed_bounds['period_end'] ?? ''));
        }
        if ($period_start === '' || $period_end === '') {
            return new WP_Error('cmn_payroll_invalid_period_bounds', 'Unable to resolve payroll period boundaries.');
        }

        $totals = $this->build_payroll_candidate_totals_for_period($period_id, 0, $actor_user_id, true, $is_training);
        $adjustment_rows = $this->get_payroll_approved_unapplied_adjustments_for_period($period_id, $is_training);
        $totals = $this->merge_payroll_adjustments_into_totals($totals, $adjustment_rows);
        $rows = is_array($totals['rows'] ?? null) ? (array) $totals['rows'] : [];
        $total_candidates = max(0, (int) ($totals['total_candidates'] ?? count($rows)));
        $total_gross = round((float) ($totals['total_gross'] ?? 0), 2);
        $adjustments_count = max(0, (int) ($totals['adjustments_count'] ?? 0));
        $adjustments_total = round((float) ($totals['adjustments_total'] ?? 0), 2);
        $now = current_time('mysql');

        $has_transaction = $wpdb->query('START TRANSACTION') !== false;
        $created = false;
        $adjustment_apply_result = [
            'applied_count' => 0,
            'applied_total' => 0.00,
            'applied_ids' => [],
        ];
        try {
            $has_run_training_column = self::table_has_column($runs_table, 'is_training');
            if ($has_run_training_column) {
                $inserted = $wpdb->query($wpdb->prepare(
                    "INSERT IGNORE INTO {$runs_table}
                    (period_id, period_start, period_end, generated_at, generated_by, total_candidates, total_gross, run_status, created_at, is_training)
                    VALUES
                    (%s, %s, %s, %s, %s, %d, %f, %s, %s, %d)",
                    $period_id,
                    $period_start,
                    $period_end,
                    $now,
                    $generated_by,
                    $total_candidates,
                    $total_gross,
                    'generated',
                    $now,
                    $is_training
                ));
            } else {
                $inserted = $wpdb->query($wpdb->prepare(
                    "INSERT IGNORE INTO {$runs_table}
                    (period_id, period_start, period_end, generated_at, generated_by, total_candidates, total_gross, run_status, created_at)
                    VALUES
                    (%s, %s, %s, %s, %s, %d, %f, %s, %s)",
                    $period_id,
                    $period_start,
                    $period_end,
                    $now,
                    $generated_by,
                    $total_candidates,
                    $total_gross,
                    'generated',
                    $now
                ));
            }
            if ($inserted === false) {
                throw new RuntimeException('Unable to create payout run row.');
            }

            $run_row = $this->get_payroll_payout_run_by_period_id($period_id, $is_training);
            if (empty($run_row['id'])) {
                throw new RuntimeException('Unable to load payout run row after insert.');
            }
            $run_id = (int) ($run_row['id'] ?? 0);
            $created = (int) $inserted > 0;

            if ($created) {
                foreach ($rows as $row) {
                    $candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
                    if ($candidate_user_id < 1) {
                        continue;
                    }
                    $item_payload = [
                        'payout_run_id' => $run_id,
                        'candidate_user_id' => $candidate_user_id,
                        'gross_amount' => round((float) ($row['gross_amount'] ?? 0), 2),
                        'shifts_count' => max(0, (int) ($row['shifts_count'] ?? 0)),
                        'adjustments_total' => round((float) ($row['adjustments_total'] ?? 0), 2),
                        'bank_status' => sanitize_key((string) ($row['bank_status'] ?? 'missing')),
                        'payout_item_status' => sanitize_key((string) ($row['payout_item_status'] ?? 'hold')),
                        'created_at' => $now,
                    ];
                    $item_format = ['%d', '%d', '%f', '%d', '%f', '%s', '%s', '%s'];
                    if (self::table_has_column($items_table, 'is_training')) {
                        $item_payload['is_training'] = $is_training;
                        $item_format[] = '%d';
                    }
                    $insert_item = $wpdb->insert($items_table, $item_payload, $item_format);
                    if ($insert_item === false) {
                        throw new RuntimeException('Unable to create payout run item row.');
                    }
                }

                $adjustment_apply_result = $this->apply_payroll_adjustments_for_generated_run($adjustment_rows, $period_id, $now, $is_training);
                if (is_wp_error($adjustment_apply_result)) {
                    throw new RuntimeException($adjustment_apply_result->get_error_message());
                }
            }

            if ($has_transaction) {
                $wpdb->query('COMMIT');
            }
        } catch (Throwable $e) {
            if ($has_transaction) {
                $wpdb->query('ROLLBACK');
            }
            return new WP_Error('cmn_payroll_payout_generation_failed', $e->getMessage());
        }

        $run_row = $this->get_payroll_payout_run_by_period_id($period_id, $is_training);
        if (empty($run_row['id'])) {
            return new WP_Error('cmn_payroll_payout_run_missing', 'Payout run could not be loaded.');
        }
        $items = $this->get_payroll_payout_run_items((int) $run_row['id'], $is_training);

        if ($created) {
            foreach ($items as $item) {
                $candidate_user_id = max(0, (int) ($item['candidate_user_id'] ?? 0));
                if ($candidate_user_id > 0) {
                    delete_transient($this->get_candidate_weekly_earnings_cache_key($candidate_user_id));
                }
            }
        }

        if ($created && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'payroll',
                'entity_type' => 'period',
                'entity_id' => $this->get_payroll_period_audit_entity_id($period_id, $period_start, $period_end),
                'event_type' => 'payout_run_generated',
                'event_ref' => $period_id,
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'period_id' => $period_id,
                    'base_period_id' => $base_period_id,
                    'period_start' => $period_start,
                    'period_end' => $period_end,
                    'payout_run_id' => (int) ($run_row['id'] ?? 0),
                    'generated_by' => $generated_by,
                    'trigger' => $trigger,
                    'is_training' => $is_training,
                    'total_candidates' => max(0, (int) ($run_row['total_candidates'] ?? $total_candidates)),
                    'total_gross' => round((float) ($run_row['total_gross'] ?? $total_gross), 2),
                    'adjustments_count' => $adjustments_count,
                    'adjustments_total' => $adjustments_total,
                ],
            ]);

            $ready_count = 0;
            $hold_count = 0;
            foreach ($items as $item) {
                $item_status = sanitize_key((string) ($item['payout_item_status'] ?? 'hold'));
                if ($item_status === 'ready') {
                    $ready_count++;
                } else {
                    $hold_count++;
                }
            }

            cmn_audit_log_event([
                'module' => 'payroll',
                'entity_type' => 'period',
                'entity_id' => $this->get_payroll_period_audit_entity_id($period_id, $period_start, $period_end),
                'event_type' => 'payout_run_item_created',
                'event_ref' => $period_id . ':aggregate',
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => [
                    'period_id' => $period_id,
                    'base_period_id' => $base_period_id,
                    'payout_run_id' => (int) ($run_row['id'] ?? 0),
                    'items_count' => count($items),
                    'is_training' => $is_training,
                    'ready_count' => $ready_count,
                    'hold_count' => $hold_count,
                    'total_candidates' => max(0, (int) ($run_row['total_candidates'] ?? $total_candidates)),
                    'total_gross' => round((float) ($run_row['total_gross'] ?? $total_gross), 2),
                ],
            ]);

            $applied_adjustment_count = max(0, (int) ($adjustment_apply_result['applied_count'] ?? 0));
            if ($applied_adjustment_count > 0) {
                cmn_audit_log_event([
                    'module' => 'payroll',
                    'entity_type' => 'period',
                    'entity_id' => $this->get_payroll_period_audit_entity_id($period_id, $period_start, $period_end),
                    'event_type' => 'payroll_adjustment_applied',
                    'event_ref' => $period_id . ':adjustments',
                    'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                    'metadata' => [
                        'period_id' => $period_id,
                        'base_period_id' => $base_period_id,
                        'payout_run_id' => (int) ($run_row['id'] ?? 0),
                        'applied_count' => $applied_adjustment_count,
                        'applied_total' => round((float) ($adjustment_apply_result['applied_total'] ?? 0), 2),
                        'is_training' => $is_training,
                    ],
                ]);
            }
        }

        return [
            'ok' => true,
            'created' => $created,
            'already_exists' => !$created,
            'payout_run' => $run_row,
            'items' => $items,
        ];
    }

    private function is_credit_adjustment_type($type) {
        $type = sanitize_key((string) $type);
        if ($type === '') {
            return false;
        }
        if (in_array($type, ['partner_credit', 'manual_credit', 'credit', 'credit_note'], true)) {
            return true;
        }
        return strpos($type, 'credit') !== false;
    }

    private function is_positive_adjustment_type($type) {
        $type = sanitize_key((string) $type);
        if ($type === '') {
            return false;
        }
        if (in_array($type, ['fee', 'vat', 'charge'], true)) {
            return true;
        }
        return strpos($type, 'fee') !== false || strpos($type, 'vat') !== false;
    }

    private function normalize_adjustment_amount_for_type($type, $amount) {
        $type = sanitize_key((string) $type);
        $amount = round((float) $amount, 2);
        if ($this->is_credit_adjustment_type($type)) {
            return round(-abs($amount), 2);
        }
        if ($this->is_positive_adjustment_type($type)) {
            return round(abs($amount), 2);
        }
        return $amount;
    }

    private function begin_invoice_transaction() {
        global $wpdb;
        return $wpdb->query('START TRANSACTION') !== false;
    }

    private function finish_invoice_transaction($has_transaction, $success) {
        if (!$has_transaction) {
            return;
        }
        global $wpdb;
        if ($success) {
            $wpdb->query('COMMIT');
            return;
        }
        $wpdb->query('ROLLBACK');
    }

    public function insert_invoice($invoice_data = []) {
        $invoice_data = is_array($invoice_data) ? $invoice_data : [];
        $school_id = (int) ($invoice_data['school_id'] ?? 0);
        $invoice_number = substr(sanitize_text_field((string) ($invoice_data['invoice_number'] ?? '')), 0, 80);
        $period_start = $this->normalize_invoice_date($invoice_data['period_start'] ?? '');
        $period_end = $this->normalize_invoice_date($invoice_data['period_end'] ?? '');
        if ($school_id < 1 || $invoice_number === '' || $period_start === '' || $period_end === '') {
            return 0;
        }
        if (strtotime($period_end) < strtotime($period_start)) {
            return 0;
        }

        $status = $this->normalize_invoice_status((string) ($invoice_data['status'] ?? 'draft'));
        $currency = $this->normalize_invoice_currency((string) ($invoice_data['currency'] ?? 'GBP'));
        $subtotal = round((float) ($invoice_data['subtotal'] ?? 0), 2);
        $adjustments_total = round((float) ($invoice_data['adjustments_total'] ?? 0), 2);
        $vat_total = round((float) ($invoice_data['vat_total'] ?? 0), 2);
        $total = round((float) ($invoice_data['total'] ?? 0), 2);
        if ($total < 0) {
            $total = 0.00;
        }

        $billing_contact = substr(sanitize_text_field((string) ($invoice_data['billing_contact'] ?? '')), 0, 190);
        $billing_reference = substr(sanitize_text_field((string) ($invoice_data['billing_reference'] ?? '')), 0, 190);
        $billing_email = sanitize_email((string) ($invoice_data['billing_email'] ?? ''));
        if ($billing_email !== '' && !is_email($billing_email)) {
            $billing_email = '';
        }
        $invoice_email = sanitize_email((string) ($invoice_data['invoice_email'] ?? ''));
        if ($invoice_email !== '' && !is_email($invoice_email)) {
            $invoice_email = '';
        }
        if ($invoice_email === '' && $billing_email !== '') {
            $invoice_email = $billing_email;
        }

        $now = current_time('mysql');
        $sent_at = $this->normalize_invoice_datetime($invoice_data['sent_at'] ?? '');
        $paid_at = $this->normalize_invoice_datetime($invoice_data['paid_at'] ?? '');
        if ($status === 'sent' && $sent_at === '') {
            $sent_at = $now;
        }
        if ($status === 'paid') {
            if ($sent_at === '') {
                $sent_at = $now;
            }
            if ($paid_at === '') {
                $paid_at = $now;
            }
        }
        $amount_paid = round((float) ($invoice_data['amount_paid'] ?? 0), 2);
        if ($amount_paid < 0) {
            $amount_paid = 0.00;
        }
        if ($status === 'paid' && $amount_paid <= 0) {
            $amount_paid = $total;
        }
        $amount_due = round((float) ($invoice_data['amount_due'] ?? ($total - $amount_paid)), 2);
        if ($status === 'paid') {
            $amount_due = 0.00;
        }
        if ($amount_due < 0) {
            $amount_due = 0.00;
        }
        if ($amount_paid <= 0 && !array_key_exists('amount_due', $invoice_data)) {
            $amount_due = $total;
        }

        global $wpdb;
        $table = $this->get_invoices_table();
        $sql = $wpdb->prepare(
            "INSERT INTO {$table}
            (school_id, invoice_number, period_start, period_end, status, currency, subtotal, adjustments_total, vat_total, total, amount_paid, amount_due, billing_email, billing_contact, billing_reference, invoice_email, created_at, updated_at, sent_at, paid_at)
            VALUES
            (%d, %s, %s, %s, %s, %s, %f, %f, %f, %f, %f, %f, %s, %s, %s, %s, %s, %s, NULLIF(%s, ''), NULLIF(%s, ''))",
            $school_id,
            $invoice_number,
            $period_start,
            $period_end,
            $status,
            $currency,
            $subtotal,
            $adjustments_total,
            $vat_total,
            $total,
            $amount_paid,
            $amount_due,
            $billing_email,
            $billing_contact,
            $billing_reference,
            $invoice_email,
            $now,
            $now,
            $sent_at,
            $paid_at
        );
        $inserted = $wpdb->query($sql);
        if ($inserted === false) {
            return 0;
        }
        return (int) $wpdb->insert_id;
    }

    public function insert_invoice_item($item_data = [], $options = []) {
        $result = $this->add_invoice_item($item_data, $options);
        if (is_wp_error($result)) {
            return 0;
        }
        return (int) ($result['item_id'] ?? 0);
    }

    public function insert_invoice_adjustment($adjustment_data = [], $options = []) {
        $result = $this->add_invoice_adjustment($adjustment_data, $options);
        if (is_wp_error($result)) {
            return 0;
        }
        return (int) ($result['adjustment_id'] ?? 0);
    }

    public function recalculate_invoice_totals($invoice_id) {
        $invoice_id = (int) $invoice_id;
        if ($invoice_id < 1) {
            return new WP_Error('cmn_invoice_invalid_invoice', 'Invalid invoice id.');
        }

        $invoice = $this->get_invoice_by_id($invoice_id);
        if (empty($invoice)) {
            return new WP_Error('cmn_invoice_not_found', 'Invoice not found.');
        }

        global $wpdb;
        $items_table = $this->get_invoice_items_table();
        $adjustments_table = $this->get_invoice_adjustments_table();
        $payments_table = $this->get_invoice_payments_table();
        $invoices_table = $this->get_invoices_table();

        $subtotal_raw = $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(line_total), 0) FROM {$items_table} WHERE invoice_id = %d",
            $invoice_id
        ));
        $adjustments_total_raw = $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(amount), 0) FROM {$adjustments_table} WHERE invoice_id = %d",
            $invoice_id
        ));

        $subtotal = round((float) $subtotal_raw, 2);
        $adjustments_total = round((float) $adjustments_total_raw, 2);
        $vat_total = 0.00;
        $total = round($subtotal + $adjustments_total + $vat_total, 2);
        if ($total < 0) {
            $total = 0.00;
        }
        $amount_paid_raw = $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(amount), 0) FROM {$payments_table} WHERE invoice_id = %d",
            $invoice_id
        ));
        $amount_paid = round(max(0, (float) $amount_paid_raw), 2);
        $amount_due = round($total - $amount_paid, 2);
        if ($amount_due < 0) {
            $amount_due = 0.00;
        }

        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$invoices_table}
             SET subtotal = %f,
                 adjustments_total = %f,
                 vat_total = %f,
                 total = %f,
                 amount_paid = %f,
                 amount_due = %f,
                 updated_at = %s
             WHERE id = %d",
            $subtotal,
            $adjustments_total,
            $vat_total,
            $total,
            $amount_paid,
            $amount_due,
            current_time('mysql'),
            $invoice_id
        ));
        if ($updated === false) {
            return new WP_Error('cmn_invoice_update_failed', 'Failed to update invoice totals.');
        }

        return [
            'invoice_id' => $invoice_id,
            'subtotal' => $subtotal,
            'adjustments_total' => $adjustments_total,
            'vat_total' => $vat_total,
            'total' => $total,
            'amount_paid' => $amount_paid,
            'amount_due' => $amount_due,
        ];
    }

    public function add_invoice_item($item_data = [], $options = []) {
        $item_data = is_array($item_data) ? $item_data : [];
        $options = is_array($options) ? $options : [];
        $skip_permission_check = !empty($options['skip_permission_check']) || !empty($options['permission_validated']);
        $actor_user_id = (int) ($options['actor_user_id'] ?? get_current_user_id());
        if (!$skip_permission_check && !$this->can_modify_invoice_records($actor_user_id)) {
            return new WP_Error('cmn_invoice_forbidden', 'Only admin/staff can modify invoice items.');
        }

        $invoice_id = (int) ($item_data['invoice_id'] ?? 0);
        $booking_id = (int) ($item_data['booking_id'] ?? 0);
        $shift_date = $this->normalize_invoice_date($item_data['shift_date'] ?? '');
        $role_label = substr(sanitize_text_field((string) ($item_data['role_label'] ?? '')), 0, 190);
        $qty = (int) ($item_data['qty'] ?? 1);
        if ($qty < 1) {
            $qty = 1;
        }
        $unit_price = round((float) ($item_data['unit_price'] ?? 0), 2);
        if ($unit_price < 0) {
            return new WP_Error('cmn_invoice_invalid_unit_price', 'Unit price cannot be negative.');
        }
        $line_total = round($qty * $unit_price, 2);
        $candidate_id = (int) ($item_data['candidate_id'] ?? 0);
        $notes = sanitize_textarea_field((string) ($item_data['notes'] ?? ''));

        if ($invoice_id < 1 || $booking_id < 1 || $shift_date === '' || $role_label === '') {
            return new WP_Error('cmn_invoice_invalid_item', 'Missing required invoice item fields.');
        }

        $invoice = $this->get_invoice_by_id($invoice_id);
        if (empty($invoice)) {
            return new WP_Error('cmn_invoice_not_found', 'Invoice not found.');
        }
        $status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        if ($this->is_invoice_content_locked($status)) {
            return new WP_Error('cmn_invoice_locked', $this->get_invoice_lock_message($status));
        }

        global $wpdb;
        $table = $this->get_invoice_items_table();
        $has_transaction = $this->begin_invoice_transaction();
        $success = false;
        $item_id = 0;
        $totals = null;
        try {
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT INTO {$table}
                (invoice_id, booking_id, shift_date, role_label, qty, unit_price, line_total, candidate_id, notes, created_at)
                VALUES
                (%d, %d, %s, %s, %d, %f, %f, NULLIF(%d, 0), NULLIF(%s, ''), %s)",
                $invoice_id,
                $booking_id,
                $shift_date,
                $role_label,
                $qty,
                $unit_price,
                $line_total,
                $candidate_id,
                $notes,
                current_time('mysql')
            ));
            if ($inserted === false) {
                throw new Exception('insert_failed');
            }
            $item_id = (int) $wpdb->insert_id;
            $totals = $this->recalculate_invoice_totals($invoice_id);
            if (is_wp_error($totals)) {
                throw new Exception('recalc_failed');
            }
            $success = true;
        } catch (Exception $e) {
            $success = false;
        }
        $this->finish_invoice_transaction($has_transaction, $success);
        if (!$success && !$has_transaction && $item_id > 0) {
            $wpdb->query($wpdb->prepare(
                "DELETE FROM {$table} WHERE id = %d",
                $item_id
            ));
        }

        if (!$success || $item_id < 1 || is_wp_error($totals)) {
            return new WP_Error('cmn_invoice_item_add_failed', 'Failed to add invoice item.');
        }

        return [
            'invoice_id' => $invoice_id,
            'item_id' => $item_id,
            'line_total' => $line_total,
            'totals' => $totals,
        ];
    }

    public function add_invoice_adjustment($adjustment_data = [], $options = []) {
        $adjustment_data = is_array($adjustment_data) ? $adjustment_data : [];
        $options = is_array($options) ? $options : [];
        $skip_permission_check = !empty($options['skip_permission_check']) || !empty($options['permission_validated']);
        $actor_user_id = (int) ($options['actor_user_id'] ?? get_current_user_id());
        if (!$skip_permission_check && !$this->can_modify_invoice_records($actor_user_id)) {
            return new WP_Error('cmn_invoice_forbidden', 'Only admin/staff can modify invoice adjustments.');
        }

        $invoice_id = (int) ($adjustment_data['invoice_id'] ?? 0);
        $type = substr(sanitize_key((string) ($adjustment_data['type'] ?? 'manual_credit')), 0, 40);
        $label = substr(sanitize_text_field((string) ($adjustment_data['label'] ?? 'Adjustment')), 0, 190);
        $input_amount = round((float) ($adjustment_data['amount'] ?? 0), 2);
        $amount = $this->normalize_adjustment_amount_for_type($type, $input_amount);
        if ($amount === 0.0) {
            return new WP_Error('cmn_invoice_invalid_adjustment_amount', 'Adjustment amount cannot be zero.');
        }
        $created_by_user_id = (int) ($adjustment_data['created_by_user_id'] ?? $actor_user_id);
        $reason = sanitize_textarea_field((string) ($adjustment_data['reason'] ?? ''));
        if ($invoice_id < 1 || $type === '' || $label === '') {
            return new WP_Error('cmn_invoice_invalid_adjustment', 'Missing required adjustment fields.');
        }
        if ($reason === '') {
            return new WP_Error('cmn_invoice_adjustment_reason_required', 'Adjustment reason is required.');
        }

        $invoice = $this->get_invoice_by_id($invoice_id);
        if (empty($invoice)) {
            return new WP_Error('cmn_invoice_not_found', 'Invoice not found.');
        }
        $status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        if ($this->is_invoice_content_locked($status)) {
            return new WP_Error('cmn_invoice_locked', $this->get_invoice_lock_message($status));
        }

        global $wpdb;
        $table = $this->get_invoice_adjustments_table();
        $has_transaction = $this->begin_invoice_transaction();
        $success = false;
        $adjustment_id = 0;
        $totals = null;
        try {
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT INTO {$table}
                (invoice_id, type, label, amount, created_by_user_id, reason, created_at)
                VALUES
                (%d, %s, %s, %f, NULLIF(%d, 0), NULLIF(%s, ''), %s)",
                $invoice_id,
                $type,
                $label,
                $amount,
                $created_by_user_id,
                $reason,
                current_time('mysql')
            ));
            if ($inserted === false) {
                throw new Exception('insert_failed');
            }
            $adjustment_id = (int) $wpdb->insert_id;
            $totals = $this->recalculate_invoice_totals($invoice_id);
            if (is_wp_error($totals)) {
                throw new Exception('recalc_failed');
            }
            $success = true;
        } catch (Exception $e) {
            $success = false;
        }
        $this->finish_invoice_transaction($has_transaction, $success);
        if (!$success && !$has_transaction && $adjustment_id > 0) {
            $wpdb->query($wpdb->prepare(
                "DELETE FROM {$table} WHERE id = %d",
                $adjustment_id
            ));
        }

        if (!$success || $adjustment_id < 1 || is_wp_error($totals)) {
            return new WP_Error('cmn_invoice_adjustment_add_failed', 'Failed to add invoice adjustment.');
        }

        $audit_action = ($type === 'partner_credit') ? 'partner_credit_updated' : 'manual_adjustment_added';
        $this->log_invoice_audit_event($invoice_id, $audit_action, [
            'invoice' => $invoice,
            'amount_delta' => $amount,
            'user_id' => $created_by_user_id > 0 ? $created_by_user_id : $actor_user_id,
            'note' => $reason,
        ]);

        $savings_sync_warning = '';
        if ($type === 'partner_credit') {
            $invoice_school_id = (int) ($invoice['school_id'] ?? 0);
            if ($invoice_school_id > 0) {
                $savings_sync = $this->recalculate_school_partner_savings($invoice_school_id, [
                    'source' => 'manual_partner_credit_adjustment',
                    'invoice_id' => $invoice_id,
                ]);
                if (is_wp_error($savings_sync)) {
                    $savings_sync_warning = $savings_sync->get_error_message();
                    $this->add_audit_log('invoice_partner_savings_sync_failed', 'invoice', (string) $invoice_id, [
                        'school_id' => $invoice_school_id,
                        'message' => $savings_sync_warning,
                        'adjustment_id' => $adjustment_id,
                        'source' => 'manual_partner_credit_adjustment',
                    ], $actor_user_id);
                }
            }
        }

        return [
            'invoice_id' => $invoice_id,
            'adjustment_id' => $adjustment_id,
            'amount' => $amount,
            'totals' => $totals,
            'savings_sync_warning' => $savings_sync_warning,
        ];
    }

