    private function get_allowed_invoice_payment_methods() {
        return ['bank_transfer', 'card', 'cheque', 'other'];
    }

    private function normalize_invoice_payment_method($method) {
        $method = sanitize_key((string) $method);
        if (!in_array($method, $this->get_allowed_invoice_payment_methods(), true)) {
            return 'other';
        }
        return $method;
    }

    private function get_invoice_payment_method_label($method) {
        $method = $this->normalize_invoice_payment_method($method);
        $labels = [
            'bank_transfer' => 'Bank transfer',
            'card' => 'Card',
            'cheque' => 'Cheque',
            'other' => 'Other',
        ];
        return (string) ($labels[$method] ?? 'Other');
    }

    private function normalize_invoice_payment_datetime_input($value) {
        $value = trim((string) $value);
        if ($value === '') {
            return '';
        }
        $value = str_replace('T', ' ', $value);
        if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $value) === 1) {
            $value .= ' 00:00:00';
        } elseif (preg_match('/^\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}$/', $value) === 1) {
            $value .= ':00';
        } elseif (preg_match('/^\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}$/', $value) !== 1) {
            return '';
        }
        $tz = wp_timezone();
        try {
            $dt = new DateTimeImmutable($value, $tz);
        } catch (Throwable $e) {
            return '';
        }
        return $dt->format('Y-m-d H:i:s');
    }

    public function get_invoice_payments($invoice_id, $limit = 200) {
        $invoice_id = (int) $invoice_id;
        if ($invoice_id < 1) {
            return [];
        }
        $limit = max(1, min(1000, (int) $limit));
        global $wpdb;
        $table = $this->get_invoice_payments_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE invoice_id = %d
             ORDER BY paid_at DESC, id DESC
             LIMIT %d",
            $invoice_id,
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function insert_invoice_payment_record($payment_data = [], $options = []) {
        $payment_data = is_array($payment_data) ? $payment_data : [];
        $options = is_array($options) ? $options : [];
        $invoice_id = (int) ($payment_data['invoice_id'] ?? 0);
        if ($invoice_id < 1) {
            return new WP_Error('cmn_invoice_payment_invalid_invoice', 'Invalid invoice.');
        }
        $invoice = $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            return new WP_Error('cmn_invoice_payment_not_found', 'Invoice not found.');
        }
        $status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        if ($status === 'void') {
            return new WP_Error('cmn_invoice_payment_void_blocked', 'Cannot record payment on void invoice.');
        }
        $allow_paid_invoice = !empty($options['allow_paid_invoice']);
        if ($status === 'paid' && !$allow_paid_invoice) {
            return new WP_Error('cmn_invoice_payment_paid_blocked', 'Invoice is already paid.');
        }

        $school_id = (int) ($invoice['school_id'] ?? 0);
        if ($school_id < 1) {
            return new WP_Error('cmn_invoice_payment_school_missing', 'Invoice school is missing.');
        }
        $amount = round((float) ($payment_data['amount'] ?? 0), 2);
        if ($amount <= 0) {
            return new WP_Error('cmn_invoice_payment_amount_invalid', 'Payment amount must be greater than zero.');
        }
        $currency = $this->normalize_invoice_currency((string) ($payment_data['currency'] ?? ($invoice['currency'] ?? 'GBP')));
        $paid_at = $this->normalize_invoice_payment_datetime_input($payment_data['paid_at'] ?? '');
        if ($paid_at === '') {
            return new WP_Error('cmn_invoice_payment_paid_at_invalid', 'Payment date/time is required.');
        }
        $payment_method = $this->normalize_invoice_payment_method($payment_data['payment_method'] ?? 'other');
        $payment_reference = substr(sanitize_text_field((string) ($payment_data['payment_reference'] ?? '')), 0, 190);
        if ($payment_reference === '') {
            return new WP_Error('cmn_invoice_payment_reference_required', 'Payment reference is required.');
        }
        $note = sanitize_textarea_field((string) ($payment_data['note'] ?? ''));
        $recorded_by_user_id = (int) ($payment_data['recorded_by_user_id'] ?? get_current_user_id());

        global $wpdb;
        $table = $this->get_invoice_payments_table();
        $inserted = $wpdb->insert($table, [
            'invoice_id' => $invoice_id,
            'school_id' => $school_id,
            'amount' => $amount,
            'currency' => $currency,
            'paid_at' => $paid_at,
            'payment_method' => $payment_method,
            'payment_reference' => $payment_reference,
            'note' => $note !== '' ? $note : null,
            'recorded_by_user_id' => $recorded_by_user_id > 0 ? $recorded_by_user_id : null,
            'created_at' => current_time('mysql'),
        ], ['%d', '%d', '%f', '%s', '%s', '%s', '%s', '%s', '%d', '%s']);
        if ($inserted === false) {
            return new WP_Error('cmn_invoice_payment_insert_failed', 'Unable to record payment.');
        }

        return [
            'payment_id' => (int) $wpdb->insert_id,
            'invoice' => $invoice,
            'amount' => $amount,
            'currency' => $currency,
            'paid_at' => $paid_at,
            'payment_method' => $payment_method,
            'payment_reference' => $payment_reference,
            'note' => $note,
            'recorded_by_user_id' => $recorded_by_user_id,
        ];
    }

    private function recalculate_invoice_payment_totals($invoice_id) {
        $invoice_id = (int) $invoice_id;
        if ($invoice_id < 1) {
            return new WP_Error('cmn_invoice_payment_invalid_invoice', 'Invalid invoice.');
        }
        $invoice = $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            return new WP_Error('cmn_invoice_payment_not_found', 'Invoice not found.');
        }

        global $wpdb;
        $payments_table = $this->get_invoice_payments_table();
        $invoices_table = $this->get_invoices_table();
        $amount_paid_raw = $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(amount), 0)
             FROM {$payments_table}
             WHERE invoice_id = %d",
            $invoice_id
        ));
        $latest_paid_at_raw = $wpdb->get_var($wpdb->prepare(
            "SELECT paid_at
             FROM {$payments_table}
             WHERE invoice_id = %d
             ORDER BY paid_at DESC, id DESC
             LIMIT 1",
            $invoice_id
        ));
        $amount_paid = round(max(0, (float) $amount_paid_raw), 2);
        $total = round((float) ($invoice['total'] ?? 0), 2);
        $amount_due = round($total - $amount_paid, 2);
        if ($amount_due < 0) {
            $amount_due = 0.00;
        }
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$invoices_table}
             SET amount_paid = %f,
                 amount_due = %f,
                 updated_at = %s
             WHERE id = %d",
            $amount_paid,
            $amount_due,
            current_time('mysql'),
            $invoice_id
        ));
        if ($updated === false) {
            return new WP_Error('cmn_invoice_payment_recalc_failed', 'Unable to recalculate payment totals.');
        }
        return [
            'invoice_id' => $invoice_id,
            'amount_paid' => $amount_paid,
            'amount_due' => $amount_due,
            'latest_paid_at' => sanitize_text_field((string) $latest_paid_at_raw),
        ];
    }

    private function reconcile_invoice_status_after_payment($invoice_id, $actor_user_id = 0, $final_paid_at = '') {
        $invoice_id = (int) $invoice_id;
        $actor_user_id = (int) ($actor_user_id ?: get_current_user_id());
        $final_paid_at = $this->normalize_invoice_payment_datetime_input($final_paid_at);
        if ($invoice_id < 1) {
            return new WP_Error('cmn_invoice_payment_invalid_invoice', 'Invalid invoice.');
        }
        $invoice = $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            return new WP_Error('cmn_invoice_payment_not_found', 'Invoice not found.');
        }

        $original_status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        $current_status = $original_status;
        $amount_due = round(max(0, (float) ($invoice['amount_due'] ?? 0)), 2);
        if ($current_status === 'void') {
            return [
                'invoice' => $invoice,
                'from_status' => $original_status,
                'to_status' => $current_status,
            ];
        }

        if ($amount_due > 0.00001) {
            if ($current_status === 'draft') {
                $issued_result = $this->set_invoice_status(
                    $invoice_id,
                    'issued',
                    $actor_user_id,
                    'Invoice moved to issued during payment reconciliation.'
                );
                if (is_wp_error($issued_result)) {
                    return $issued_result;
                }
                $invoice = is_array($issued_result) ? $issued_result : $invoice;
                $current_status = 'issued';
            }
            if ($current_status === 'issued') {
                $sent_result = $this->set_invoice_status(
                    $invoice_id,
                    'sent',
                    $actor_user_id,
                    'Invoice moved to sent after partial payment reconciliation.'
                );
                if (is_wp_error($sent_result)) {
                    return $sent_result;
                }
                $invoice = is_array($sent_result) ? $sent_result : $invoice;
                $current_status = 'sent';
            }
            return [
                'invoice' => $invoice,
                'from_status' => $original_status,
                'to_status' => $current_status,
            ];
        }

        if ($current_status === 'draft') {
            $issued_result = $this->set_invoice_status(
                $invoice_id,
                'issued',
                $actor_user_id,
                'Invoice moved to issued during payment reconciliation.'
            );
            if (is_wp_error($issued_result)) {
                return $issued_result;
            }
            $invoice = is_array($issued_result) ? $issued_result : $invoice;
            $current_status = 'issued';
        }
        if ($current_status === 'issued') {
            $sent_result = $this->set_invoice_status(
                $invoice_id,
                'sent',
                $actor_user_id,
                'Invoice moved to sent during payment reconciliation.'
            );
            if (is_wp_error($sent_result)) {
                return $sent_result;
            }
            $invoice = is_array($sent_result) ? $sent_result : $invoice;
            $current_status = 'sent';
        }
        if ($current_status === 'sent') {
            $paid_result = $this->set_invoice_status(
                $invoice_id,
                'paid',
                $actor_user_id,
                'Invoice fully paid during payment reconciliation.'
            );
            if (is_wp_error($paid_result)) {
                return $paid_result;
            }
            $invoice = is_array($paid_result) ? $paid_result : $invoice;
            $current_status = 'paid';
        }

        if ($current_status === 'paid' && $final_paid_at !== '') {
            global $wpdb;
            $invoices_table = $this->get_invoices_table();
            $wpdb->query($wpdb->prepare(
                "UPDATE {$invoices_table}
                 SET paid_at = %s,
                     updated_at = %s
                 WHERE id = %d",
                $final_paid_at,
                current_time('mysql'),
                $invoice_id
            ));
            $refreshed = $this->get_invoice_by_id($invoice_id);
            if ($refreshed) {
                $invoice = $refreshed;
            }
        }

        return [
            'invoice' => $invoice,
            'from_status' => $original_status,
            'to_status' => $current_status,
        ];
    }

    public function get_invoices_by_school_period($school_id, $period_start, $period_end, $statuses = []) {
        $school_id = (int) $school_id;
        $period_start = $this->normalize_invoice_date($period_start);
        $period_end = $this->normalize_invoice_date($period_end);
        if ($school_id < 1 || $period_start === '' || $period_end === '') {
            return [];
        }
        if (strtotime($period_end) < strtotime($period_start)) {
            return [];
        }

        $status_filters = [];
        if (is_array($statuses)) {
            foreach ($statuses as $status) {
                $status_key = sanitize_key((string) $status);
                if (in_array($status_key, $this->get_allowed_invoice_statuses(), true)) {
                    $status_filters[] = $status_key;
                }
            }
        }
        $status_filters = array_values(array_unique($status_filters));

        global $wpdb;
        $table = $this->get_invoices_table();
        $params = [$school_id, $period_end, $period_start];
        $status_sql = '';
        if (!empty($status_filters)) {
            $status_sql = ' AND status IN (' . implode(',', array_fill(0, count($status_filters), '%s')) . ')';
            $params = array_merge($params, $status_filters);
        }

        $sql = "SELECT *
                FROM {$table}
                WHERE school_id = %d
                  AND period_start <= %s
                  AND period_end >= %s
                  {$status_sql}
                ORDER BY period_start DESC, id DESC";
        $prepared = $wpdb->prepare($sql, ...$params);
        $rows = $wpdb->get_results($prepared, ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function get_invoices_for_exact_period($period_start, $period_end, $limit = 300) {
        $period_start = $this->normalize_invoice_date($period_start);
        $period_end = $this->normalize_invoice_date($period_end);
        if ($period_start === '' || $period_end === '') {
            return [];
        }
        $limit = max(1, min(1000, (int) $limit));
        global $wpdb;
        $table = $this->get_invoices_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE period_start = %s
               AND period_end = %s
             ORDER BY school_id ASC, id DESC
             LIMIT %d",
            $period_start,
            $period_end,
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function get_invoice_status_chip_class($status) {
        $status = $this->normalize_invoice_status($status);
        if ($status === 'paid') {
            return 'is-approved';
        }
        if ($status === 'void') {
            return 'is-declined';
        }
        if ($status === 'sent') {
            return 'is-requested';
        }
        if ($status === 'issued') {
            return 'is-warning';
        }
        return 'is-pending';
    }

    private function get_invoice_status_label($status) {
        $status = $this->normalize_invoice_status($status);
        return ucfirst($status);
    }

    private function get_invoice_school_display_name($school_id, $fallback = '') {
        $school_id = (int) $school_id;
        $fallback = sanitize_text_field((string) $fallback);
        if ($fallback !== '') {
            return $fallback;
        }
        if ($school_id < 1) {
            return 'Unknown school';
        }
        $name = (string) get_the_title($school_id);
        $name = sanitize_text_field($name);
        if ($name !== '') {
            return $name;
        }
        return 'School #' . $school_id;
    }

    private function can_user_access_invoice_pdf($invoice, $user_id = 0) {
        $invoice = is_array($invoice) ? $invoice : [];
        $invoice_id = (int) ($invoice['id'] ?? 0);
        if ($invoice_id < 1) {
            return false;
        }
        $user_id = (int) ($user_id ?: get_current_user_id());
        if ($user_id < 1) {
            return false;
        }
        if ($this->can_modify_invoice_records($user_id)) {
            return true;
        }
        if ($this->is_school_user($user_id)) {
            $user_school_id = (int) $this->resolve_school_id_for_user($user_id);
            $invoice_school_id = (int) ($invoice['school_id'] ?? 0);
            return $user_school_id > 0 && $invoice_school_id > 0 && $user_school_id === $invoice_school_id;
        }
        return false;
    }

    private function get_invoice_pdf_download_filename($invoice) {
        $invoice = is_array($invoice) ? $invoice : [];
        $invoice_id = (int) ($invoice['id'] ?? 0);
        $invoice_number = sanitize_text_field((string) ($invoice['invoice_number'] ?? ''));
        if ($invoice_number === '') {
            $invoice_number = (string) max(1, $invoice_id);
        }
        $invoice_number = strtoupper(preg_replace('/[^A-Z0-9\-]+/', '-', $invoice_number));
        $invoice_number = trim((string) $invoice_number, '-');
        if ($invoice_number === '') {
            $invoice_number = (string) max(1, $invoice_id);
        }
        return 'CMN-INV-' . $invoice_number . '.pdf';
    }

    private function get_invoice_pdf_cache_directory() {
        $base_dir = function_exists('sys_get_temp_dir') ? (string) sys_get_temp_dir() : '';
        $base_dir = trim($base_dir);
        if ($base_dir === '' || !is_dir($base_dir) || !is_writable($base_dir)) {
            return '';
        }
        $cache_dir = rtrim($base_dir, '/\\') . '/cmn_invoice_pdf_cache';
        if (!is_dir($cache_dir)) {
            wp_mkdir_p($cache_dir);
        }
        if (!is_dir($cache_dir) || !is_writable($cache_dir)) {
            return '';
        }
        return $cache_dir;
    }

    private function get_invoice_email_primary_recipient($invoice) {
        $invoice = is_array($invoice) ? $invoice : [];
        $invoice_email = sanitize_email((string) ($invoice['invoice_email'] ?? ''));
        if ($invoice_email !== '') {
            return [
                'email' => $invoice_email,
                'source' => 'invoice_email',
            ];
        }
        $billing_email = sanitize_email((string) ($invoice['billing_email'] ?? ''));
        if ($billing_email !== '') {
            return [
                'email' => $billing_email,
                'source' => 'billing_email',
            ];
        }
        return [
            'email' => '',
            'source' => 'none',
        ];
    }

    private function should_cc_invoice_sender() {
        $raw = get_option('cmn_invoice_email_cc_sender', '0');
        $enabled = false;
        if (is_bool($raw)) {
            $enabled = $raw;
        } elseif (is_numeric($raw)) {
            $enabled = ((int) $raw) === 1;
        } else {
            $raw_text = strtolower(trim((string) $raw));
            $enabled = in_array($raw_text, ['1', 'yes', 'true', 'on'], true);
        }
        return (bool) apply_filters('cmn_invoice_email_cc_sender_enabled', $enabled);
    }

    private function get_invoice_email_payment_instruction_lines($invoice) {
        $invoice = is_array($invoice) ? $invoice : [];
        $invoice_number = sanitize_text_field((string) ($invoice['invoice_number'] ?? 'invoice number'));
        $instructions = apply_filters('cmn_invoice_email_payment_instructions', [
            'Please arrange payment via bank transfer within 14 days of the invoice issue date.',
            'Use payment reference: ' . ($invoice_number !== '' ? $invoice_number : 'invoice number'),
            'For remittance advice or billing queries, contact accounts@covermenow.co.uk.',
            'Always communicate changes inside the booking chat.',
        ], $invoice);
        if (!is_array($instructions) || !$instructions) {
            $instructions = ['Please contact accounts@covermenow.co.uk for payment instructions.'];
        }
        $lines = [];
        foreach ($instructions as $line) {
            $line = sanitize_text_field((string) $line);
            if ($line === '') {
                continue;
            }
            $lines[] = $line;
        }
        if (!$lines) {
            $lines[] = 'Please contact accounts@covermenow.co.uk for payment instructions.';
        }
        return $lines;
    }

    private function build_invoice_email_subject($invoice) {
        $invoice = is_array($invoice) ? $invoice : [];
        $invoice_id = (int) ($invoice['id'] ?? 0);
        $invoice_number = sanitize_text_field((string) ($invoice['invoice_number'] ?? ''));
        if ($invoice_number === '') {
            $invoice_number = 'INV-' . max(1, $invoice_id);
        }
        $period_start = $this->normalize_invoice_date((string) ($invoice['period_start'] ?? ''));
        if ($period_start === '') {
            $period_start = sanitize_text_field((string) ($invoice['period_start'] ?? 'N/A'));
        }
        $period_end = $this->normalize_invoice_date((string) ($invoice['period_end'] ?? ''));
        if ($period_end === '') {
            $period_end = sanitize_text_field((string) ($invoice['period_end'] ?? 'N/A'));
        }
        return sprintf(
            'CoverMeNow Invoice %s (%s-%s)',
            $invoice_number,
            $period_start !== '' ? $period_start : 'N/A',
            $period_end !== '' ? $period_end : 'N/A'
        );
    }

    private function build_invoice_email_message_id($invoice_id) {
        $invoice_id = max(1, (int) $invoice_id);
        $host = (string) parse_url(home_url('/'), PHP_URL_HOST);
        $host = strtolower(preg_replace('/[^a-z0-9\.\-]/', '', (string) $host));
        if ($host === '') {
            $host = 'covermenow.local';
        }
        $token = strtolower(wp_generate_password(14, false, false));
        if ($token === '') {
            $token = (string) time();
        }
        return '<cmn-invoice-' . $invoice_id . '-' . $token . '@' . $host . '>';
    }

    private function build_invoice_email_bodies($invoice, $school_name) {
        $invoice = is_array($invoice) ? $invoice : [];
        $school_name = sanitize_text_field((string) $school_name);
        $invoice_id = (int) ($invoice['id'] ?? 0);
        $invoice_number = sanitize_text_field((string) ($invoice['invoice_number'] ?? ''));
        if ($invoice_number === '') {
            $invoice_number = 'INV-' . max(1, $invoice_id);
        }
        $period_start = $this->normalize_invoice_date((string) ($invoice['period_start'] ?? ''));
        if ($period_start === '') {
            $period_start = sanitize_text_field((string) ($invoice['period_start'] ?? 'N/A'));
        }
        $period_end = $this->normalize_invoice_date((string) ($invoice['period_end'] ?? ''));
        if ($period_end === '') {
            $period_end = sanitize_text_field((string) ($invoice['period_end'] ?? 'N/A'));
        }
        $total = number_format((float) ($invoice['total'] ?? 0), 2);
        $billing_contact = sanitize_text_field((string) ($invoice['billing_contact'] ?? ''));
        $recipient_line = $billing_contact !== '' ? $billing_contact : 'Accounts Team';
        $period_label = ($period_start !== '' ? $period_start : 'N/A') . ' to ' . ($period_end !== '' ? $period_end : 'N/A');
        $instruction_lines = $this->get_invoice_email_payment_instruction_lines($invoice);

        $plain_lines = [
            'Hello ' . $recipient_line . ',',
            '',
            'Please find attached your CoverMeNow invoice.',
            '',
            'Invoice number: ' . $invoice_number,
            'Period: ' . $period_label,
            'School: ' . ($school_name !== '' ? $school_name : 'N/A'),
            'Total (GBP): ' . $total,
            '',
            'The branded PDF invoice is attached to this email.',
            '',
            'Payment instructions:',
        ];
        foreach ($instruction_lines as $instruction_line) {
            $plain_lines[] = '- ' . $instruction_line;
        }
        $plain_lines[] = '';
        $plain_lines[] = 'CoverMeNow';
        $plain_lines[] = 'accounts@covermenow.co.uk';
        $plain_body = implode("\n", $plain_lines);

        $instruction_items = '';
        foreach ($instruction_lines as $instruction_line) {
            $instruction_items .= '<li>' . esc_html($instruction_line) . '</li>';
        }
        $html_body = '<!doctype html><html><body style="margin:0;padding:0;background:#f6f6f6;color:#1f2933;font-family:Arial,sans-serif;">'
            . '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f6f6f6;padding:24px 0;">'
            . '<tr><td align="center">'
            . '<table role="presentation" width="640" cellspacing="0" cellpadding="0" style="max-width:640px;background:#ffffff;border:1px solid #e5e7eb;">'
            . '<tr><td style="background:#9f1225;color:#ffffff;padding:16px 22px;font-size:18px;font-weight:700;">CoverMeNow Invoice</td></tr>'
            . '<tr><td style="padding:22px;font-size:14px;line-height:1.6;color:#1f2933;">'
            . '<p style="margin:0 0 12px;">Hello ' . esc_html($recipient_line) . ',</p>'
            . '<p style="margin:0 0 12px;">Please find attached your CoverMeNow invoice.</p>'
            . '<p style="margin:0 0 14px;"><strong>Invoice number:</strong> ' . esc_html($invoice_number)
            . '<br><strong>Period:</strong> ' . esc_html($period_label)
            . '<br><strong>School:</strong> ' . esc_html($school_name !== '' ? $school_name : 'N/A')
            . '<br><strong>Total (GBP):</strong> ' . esc_html($total) . '</p>'
            . '<p style="margin:0 0 12px;">The branded PDF invoice is attached to this email.</p>'
            . '<p style="margin:0 0 8px;"><strong>Payment instructions:</strong></p>'
            . '<ul style="margin:0 0 16px 20px;padding:0;">' . $instruction_items . '</ul>'
            . '<p style="margin:0;color:#4b5563;">CoverMeNow<br>accounts@covermenow.co.uk</p>'
            . '</td></tr>'
            . '</table></td></tr></table></body></html>';

        return [
            'plain' => $plain_body,
            'html' => $html_body,
        ];
    }

    private function get_latest_invoice_email_log_entry($invoice_id, $status = '') {
        $invoice_id = (int) $invoice_id;
        if ($invoice_id < 1) {
            return [];
        }
        $status = sanitize_key((string) $status);
        global $wpdb;
        $table = $this->get_invoice_email_log_table();
        if ($status !== '') {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE invoice_id = %d
                   AND status = %s
                 ORDER BY id DESC
                 LIMIT 1",
                $invoice_id,
                $status
            ), ARRAY_A);
        } else {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT *
                 FROM {$table}
                 WHERE invoice_id = %d
                 ORDER BY id DESC
                 LIMIT 1",
                $invoice_id
            ), ARRAY_A);
        }
        return is_array($row) ? $row : [];
    }

    private function get_recent_invoice_sent_log_entry($invoice_id, $within_hours = 24) {
        $invoice_id = (int) $invoice_id;
        $within_hours = max(1, min(168, (int) $within_hours));
        if ($invoice_id < 1) {
            return [];
        }
        $tz = wp_timezone();
        $cutoff = (new DateTimeImmutable('now', $tz))
            ->modify('-' . $within_hours . ' hours')
            ->format('Y-m-d H:i:s');
        global $wpdb;
        $table = $this->get_invoice_email_log_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE invoice_id = %d
               AND status = %s
               AND sent_at >= %s
             ORDER BY id DESC
             LIMIT 1",
            $invoice_id,
            'sent',
            $cutoff
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function insert_invoice_email_log_entry($data = []) {
        $data = is_array($data) ? $data : [];
        $invoice_id = (int) ($data['invoice_id'] ?? 0);
        $school_id = (int) ($data['school_id'] ?? 0);
        if ($invoice_id < 1 || $school_id < 1) {
            return 0;
        }
        $to_email = sanitize_email((string) ($data['to_email'] ?? ''));
        $subject = sanitize_text_field((string) ($data['subject'] ?? ''));
        $sent_by_user_id = (int) ($data['sent_by_user_id'] ?? get_current_user_id());
        $sent_at = $this->normalize_invoice_datetime((string) ($data['sent_at'] ?? ''));
        if ($sent_at === '') {
            $sent_at = current_time('mysql');
        }
        $message_id = sanitize_text_field((string) ($data['message_id'] ?? ''));
        if (strlen($message_id) > 255) {
            $message_id = substr($message_id, 0, 255);
        }
        $status = sanitize_key((string) ($data['status'] ?? 'sent'));
        if (!in_array($status, ['sent', 'failed'], true)) {
            $status = 'failed';
        }
        $error_message = sanitize_textarea_field((string) ($data['error_message'] ?? ''));
        $note = sanitize_textarea_field((string) ($data['note'] ?? ''));

        global $wpdb;
        $table = $this->get_invoice_email_log_table();
        $inserted = $wpdb->insert($table, [
            'invoice_id' => $invoice_id,
            'school_id' => $school_id,
            'to_email' => $to_email,
            'subject' => $subject,
            'sent_by_user_id' => $sent_by_user_id > 0 ? $sent_by_user_id : null,
            'sent_at' => $sent_at,
            'message_id' => $message_id !== '' ? $message_id : null,
            'status' => $status,
            'error_message' => $error_message !== '' ? $error_message : null,
            'note' => $note !== '' ? $note : null,
        ], ['%d', '%d', '%s', '%s', '%d', '%s', '%s', '%s', '%s', '%s']);
        if ($inserted === false) {
            return 0;
        }
        return (int) $wpdb->insert_id;
    }

    private function create_invoice_email_attachment_file($invoice, $document = []) {
        $invoice = is_array($invoice) ? $invoice : [];
        $document = is_array($document) ? $document : [];
        $invoice_id = (int) ($invoice['id'] ?? 0);
        if ($invoice_id < 1) {
            return new WP_Error('cmn_invoice_attachment_invalid_invoice', 'Invalid invoice context.');
        }
        $download_name = sanitize_file_name((string) ($document['download_name'] ?? $this->get_invoice_pdf_download_filename($invoice)));
        if ($download_name === '') {
            $download_name = 'CMN-INV-' . $invoice_id . '.pdf';
        }
        if (strtolower(substr($download_name, -4)) !== '.pdf') {
            $download_name .= '.pdf';
        }
        $source_file = (string) ($document['file_path'] ?? '');
        $binary = (string) ($document['binary'] ?? '');
        if (($source_file === '' || !is_readable($source_file)) && $binary === '') {
            return new WP_Error('cmn_invoice_attachment_missing_pdf', 'Invoice PDF was not available.');
        }
        $base_dir = function_exists('sys_get_temp_dir') ? trim((string) sys_get_temp_dir()) : '';
        if ($base_dir === '' || !is_dir($base_dir) || !is_writable($base_dir)) {
            return new WP_Error('cmn_invoice_attachment_no_tmp_dir', 'Temporary directory unavailable for invoice attachment.');
        }
        $root_dir = rtrim($base_dir, '/\\') . '/cmn_invoice_email_attachments';
        if (!is_dir($root_dir)) {
            wp_mkdir_p($root_dir);
        }
        if (!is_dir($root_dir) || !is_writable($root_dir)) {
            return new WP_Error('cmn_invoice_attachment_no_tmp_dir', 'Invoice attachment directory is not writable.');
        }
        $token = strtolower(wp_generate_password(10, false, false));
        if ($token === '') {
            $token = (string) time();
        }
        $attachment_dir = $root_dir . '/inv-' . $invoice_id . '-' . $token;
        if (!wp_mkdir_p($attachment_dir) || !is_dir($attachment_dir) || !is_writable($attachment_dir)) {
            return new WP_Error('cmn_invoice_attachment_dir_failed', 'Unable to prepare invoice attachment directory.');
        }
        $attachment_path = $attachment_dir . '/' . $download_name;
        $written = false;
        if ($source_file !== '' && is_readable($source_file)) {
            $written = @copy($source_file, $attachment_path);
        } else {
            $bytes = @file_put_contents($attachment_path, $binary, LOCK_EX);
            $written = $bytes !== false && $bytes > 0;
        }
        if (!$written || !is_readable($attachment_path)) {
            @unlink($attachment_path);
            @rmdir($attachment_dir);
            return new WP_Error('cmn_invoice_attachment_write_failed', 'Unable to create invoice PDF attachment.');
        }
        @chmod($attachment_path, 0600);
        return [
            'path' => $attachment_path,
            'cleanup_dir' => $attachment_dir,
        ];
    }

    private function cleanup_invoice_email_attachment_file($attachment_path, $cleanup_dir = '') {
        $attachment_path = is_string($attachment_path) ? trim($attachment_path) : '';
        if ($attachment_path !== '' && file_exists($attachment_path)) {
            @unlink($attachment_path);
        }
        $cleanup_dir = is_string($cleanup_dir) ? trim($cleanup_dir) : '';
        if ($cleanup_dir !== '' && is_dir($cleanup_dir)) {
            @rmdir($cleanup_dir);
        }
    }

    private function send_school_email_with_alt_body($to, $subject, $html_body, $plain_body, $headers = [], $attachments = []) {
        $to = sanitize_email((string) $to);
        if ($to === '') {
            return [
                'sent' => false,
                'error_message' => 'Recipient email is required.',
            ];
        }
        $subject = sanitize_text_field((string) $subject);
        $html_body = (string) $html_body;
        $plain_body = trim((string) $plain_body);

        $had_context = !empty($GLOBALS['cmn_school_mail_context']);
        $context_state = $this->begin_school_mail_context();
        if ($context_state === null) {
            return [
                'sent' => false,
                'error_message' => 'Mail context is unavailable.',
            ];
        }

        $from_email = $this->get_school_from_email();
        $from_name = $this->get_school_from_name();
        $default_headers = [
            'From: ' . $from_name . ' <' . $from_email . '>',
            'Reply-To: ' . $from_email,
            'Content-Type: text/html; charset=UTF-8',
        ];
        if (!empty($headers)) {
            if (is_array($headers)) {
                $default_headers = array_merge($default_headers, $headers);
            } else {
                $default_headers[] = (string) $headers;
            }
        }

        $phpmailer_alt_body = static function ($phpmailer) use ($plain_body) {
            if (is_object($phpmailer) && $plain_body !== '') {
                $phpmailer->AltBody = $plain_body;
            }
        };
        add_action('phpmailer_init', $phpmailer_alt_body, 20, 1);
        $log_type = !empty($GLOBALS['cmn_school_mail_log_type']) ? $GLOBALS['cmn_school_mail_log_type'] : 'school_email';
        $mail_result = $this->send_wp_mail_with_email_log(
            $to,
            $subject,
            $html_body,
            $default_headers,
            $attachments,
            [
                'template_key' => sanitize_key((string) ($log_type !== '' ? $log_type : 'school_email')),
                'recipient_role' => 'school',
                'from_email' => $from_email,
                'from_name' => $from_name,
                'metadata' => [
                    'log_type' => sanitize_key((string) $log_type),
                    'has_alt_body' => $plain_body !== '' ? 1 : 0,
                    'has_attachments' => !empty($attachments) ? 1 : 0,
                ],
            ]
        );
        remove_action('phpmailer_init', $phpmailer_alt_body, 20);
        $sent = !empty($mail_result['success']);
        $mail_error = sanitize_text_field((string) ($mail_result['error_message'] ?? ''));
        $this->log_email($to, $subject, ['type' => $log_type], $sent ? 'sent' : 'failed', $mail_error);

        if ($had_context) {
            $GLOBALS['cmn_school_mail_context'] = true;
        } elseif ($context_state) {
            unset($GLOBALS['cmn_school_mail_context']);
        }

        return [
            'sent' => (bool) $sent,
            'error_message' => $mail_error,
        ];
    }

    private function transition_invoice_status_after_email_send($invoice, $actor_user_id, $recipient_email) {
        $invoice = is_array($invoice) ? $invoice : [];
        $invoice_id = (int) ($invoice['id'] ?? 0);
        if ($invoice_id < 1) {
            return new WP_Error('cmn_invoice_status_invalid', 'Invalid invoice for status transition.');
        }
        $actor_user_id = (int) ($actor_user_id ?: get_current_user_id());
        $from_status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        $to_status = $from_status;
        $recipient_email = sanitize_email((string) $recipient_email);

        if ($from_status === 'draft') {
            $issued_result = $this->set_invoice_status(
                $invoice_id,
                'issued',
                $actor_user_id,
                'Invoice prepared for email dispatch.'
            );
            if (is_wp_error($issued_result)) {
                return $issued_result;
            }
            $invoice = is_array($issued_result) ? $issued_result : $invoice;
            $to_status = 'issued';
        }

        if ($to_status === 'issued') {
            $sent_result = $this->set_invoice_status(
                $invoice_id,
                'sent',
                $actor_user_id,
                'Invoice email sent to ' . ($recipient_email !== '' ? $recipient_email : 'recipient') . '.'
            );
            if (is_wp_error($sent_result)) {
                return $sent_result;
            }
            $invoice = is_array($sent_result) ? $sent_result : $invoice;
            $to_status = 'sent';
        }

        return [
            'invoice' => $invoice,
            'from_status' => $from_status,
            'to_status' => $to_status,
        ];
    }

    private function parse_invoice_pdf_logo_png($file_path) {
        $file_path = is_string($file_path) ? trim($file_path) : '';
        if ($file_path === '' || !is_readable($file_path)) {
            return [];
        }
        $png_data = @file_get_contents($file_path);
        if (!is_string($png_data) || $png_data === '') {
            return [];
        }
        if (substr($png_data, 0, 8) !== "\x89PNG\r\n\x1a\n") {
            return [];
        }

        $width = 0;
        $height = 0;
        $bit_depth = 0;
        $color_type = 0;
        $compression = 0;
        $filter_method = 0;
        $interlace = 0;
        $idat = '';
        $offset = 8;
        $total_len = strlen($png_data);
        while ($offset + 8 <= $total_len) {
            $length_raw = substr($png_data, $offset, 4);
            $chunk_len_unpack = unpack('Nlen', $length_raw);
            $chunk_len = isset($chunk_len_unpack['len']) ? (int) $chunk_len_unpack['len'] : 0;
            $chunk_type = substr($png_data, $offset + 4, 4);
            $chunk_data_start = $offset + 8;
            $chunk_data_end = $chunk_data_start + $chunk_len;
            if ($chunk_len < 0 || $chunk_data_end + 4 > $total_len) {
                return [];
            }
            $chunk_data = substr($png_data, $chunk_data_start, $chunk_len);

            if ($chunk_type === 'IHDR') {
                if ($chunk_len !== 13) {
                    return [];
                }
                $ihdr = unpack(
                    'Nwidth/Nheight/Cbit_depth/Ccolor_type/Ccompression/Cfilter_method/Cinterlace',
                    $chunk_data
                );
                if (!is_array($ihdr)) {
                    return [];
                }
                $width = (int) ($ihdr['width'] ?? 0);
                $height = (int) ($ihdr['height'] ?? 0);
                $bit_depth = (int) ($ihdr['bit_depth'] ?? 0);
                $color_type = (int) ($ihdr['color_type'] ?? 0);
                $compression = (int) ($ihdr['compression'] ?? 0);
                $filter_method = (int) ($ihdr['filter_method'] ?? 0);
                $interlace = (int) ($ihdr['interlace'] ?? 0);
            } elseif ($chunk_type === 'IDAT') {
                $idat .= $chunk_data;
            } elseif ($chunk_type === 'IEND') {
                break;
            }

            $offset = $chunk_data_end + 4;
        }

        if ($width < 1 || $height < 1 || $idat === '') {
            return [];
        }
        if ($bit_depth !== 8 || $color_type !== 2 || $compression !== 0 || $filter_method !== 0 || $interlace !== 0) {
            return [];
        }

        return [
            'width' => $width,
            'height' => $height,
            'stream' => $idat,
        ];
    }

    private function get_invoice_pdf_logo_data() {
        $base_path = plugin_dir_path(__FILE__);
        $candidates = [
            $base_path . 'portal-logo.png',
            $base_path . 'rightlogo.png',
        ];
        foreach ($candidates as $candidate_path) {
            $parsed = $this->parse_invoice_pdf_logo_png($candidate_path);
            if ($parsed) {
                return $parsed;
            }
        }
        return [];
    }

    private function escape_invoice_pdf_text($text, $max_chars = 0) {
        $text = wp_strip_all_tags((string) $text);
        $text = preg_replace('/\s+/', ' ', trim($text));
        if (!is_string($text)) {
            $text = '';
        }
        $max_chars = max(0, (int) $max_chars);
        if ($max_chars > 0) {
            if (function_exists('mb_substr')) {
                $text = mb_substr($text, 0, $max_chars);
            } else {
                $text = substr($text, 0, $max_chars);
            }
        }
        if (function_exists('iconv')) {
            $converted = @iconv('UTF-8', 'Windows-1252//TRANSLIT//IGNORE', $text);
            if (is_string($converted) && $converted !== '') {
                $text = $converted;
            }
        }
        $text = preg_replace('/[^\x20-\x7E\xA0-\xFF]/', '?', $text);
        if (!is_string($text)) {
            $text = '';
        }
        return str_replace(['\\', '(', ')'], ['\\\\', '\\(', '\\)'], $text);
    }

    private function truncate_invoice_pdf_text($text, $max_chars = 32) {
        $text = trim(preg_replace('/\s+/', ' ', wp_strip_all_tags((string) $text)));
        $max_chars = max(4, (int) $max_chars);
        $length = function_exists('mb_strlen') ? mb_strlen($text) : strlen($text);
        if ($length <= $max_chars) {
            return $text;
        }
        if (function_exists('mb_substr')) {
            return mb_substr($text, 0, $max_chars - 3) . '...';
        }
        return substr($text, 0, $max_chars - 3) . '...';
    }

    private function wrap_invoice_pdf_text($text, $max_chars = 88) {
        $text = trim(preg_replace('/\s+/', ' ', wp_strip_all_tags((string) $text)));
        $max_chars = max(16, (int) $max_chars);
        if ($text === '') {
            return [''];
        }
        $words = preg_split('/\s+/', $text) ?: [];
        $lines = [];
        $current = '';
        foreach ($words as $word) {
            $word = (string) $word;
            if ($word === '') {
                continue;
            }
            $candidate = $current === '' ? $word : ($current . ' ' . $word);
            $candidate_len = function_exists('mb_strlen') ? mb_strlen($candidate) : strlen($candidate);
            if ($candidate_len <= $max_chars) {
                $current = $candidate;
                continue;
            }
            if ($current !== '') {
                $lines[] = $current;
                $current = '';
            }
            $word_len = function_exists('mb_strlen') ? mb_strlen($word) : strlen($word);
            if ($word_len <= $max_chars) {
                $current = $word;
                continue;
            }
            $offset = 0;
            while ($offset < $word_len) {
                if (function_exists('mb_substr')) {
                    $segment = mb_substr($word, $offset, $max_chars);
                } else {
                    $segment = substr($word, $offset, $max_chars);
                }
                $lines[] = $segment;
                $offset += $max_chars;
            }
        }
        if ($current !== '') {
            $lines[] = $current;
        }
        return $lines ?: [''];
    }

    private function build_invoice_pdf_rows($invoice, $school_name, $items, $adjustments) {
        $invoice = is_array($invoice) ? $invoice : [];
        $items = is_array($items) ? $items : [];
        $adjustments = is_array($adjustments) ? $adjustments : [];
        $rows = [];
        $add_section = function ($title) use (&$rows) {
            if (!empty($rows)) {
                $rows[] = ['type' => 'gap', 'text' => ''];
            }
            $rows[] = ['type' => 'section', 'text' => (string) $title];
        };
        $add_line = function ($text, $type = 'line') use (&$rows) {
            $rows[] = ['type' => sanitize_key((string) $type), 'text' => (string) $text];
        };
        $add_wrapped = function ($text, $type = 'line', $max_chars = 88) use ($add_line) {
            $wrapped = $this->wrap_invoice_pdf_text((string) $text, (int) $max_chars);
            foreach ((array) $wrapped as $wrapped_line) {
                $add_line($wrapped_line, $type);
            }
        };

        $invoice_number = sanitize_text_field((string) ($invoice['invoice_number'] ?? ''));
        $period_start = $this->normalize_invoice_date((string) ($invoice['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($invoice['period_end'] ?? ''));
        $billing_contact = sanitize_text_field((string) ($invoice['billing_contact'] ?? ''));
        $billing_email = sanitize_text_field((string) ($invoice['billing_email'] ?? ''));
        $billing_reference = sanitize_text_field((string) ($invoice['billing_reference'] ?? ''));
        $invoice_email = sanitize_text_field((string) ($invoice['invoice_email'] ?? ''));

        $add_section('Invoice Details');
        $add_line('Invoice number : ' . ($invoice_number !== '' ? $invoice_number : 'N/A'));
        $add_line('Period         : ' . ($period_start !== '' ? $period_start : 'N/A') . ' to ' . ($period_end !== '' ? $period_end : 'N/A'));
        $add_line('School         : ' . $school_name);
        $add_line('Billing contact: ' . ($billing_contact !== '' ? $billing_contact : 'N/A'));
        $add_line('Billing email  : ' . ($billing_email !== '' ? $billing_email : 'N/A'));
        $add_line('Invoice email  : ' . ($invoice_email !== '' ? $invoice_email : 'N/A'));
        if ($billing_reference !== '') {
            $add_line('Reference      : ' . $billing_reference);
        }

        $add_section('Invoice Items');
        $add_line(sprintf('%-10s %-28s %11s %11s', 'Date', 'Role', 'Unit GBP', 'Line GBP'), 'table_header');
        $add_line(str_repeat('-', 64), 'table_rule');
        if (!$items) {
            $add_line('No invoice items recorded.');
        } else {
            foreach ($items as $item_row) {
                $shift_date = $this->normalize_invoice_date((string) ($item_row['shift_date'] ?? ''));
                if ($shift_date === '') {
                    $shift_date = sanitize_text_field((string) ($item_row['shift_date'] ?? '-'));
                }
                $role_label = $this->truncate_invoice_pdf_text((string) ($item_row['role_label'] ?? 'Role'), 28);
                $unit_price = round((float) ($item_row['unit_price'] ?? 0), 2);
                $line_total = round((float) ($item_row['line_total'] ?? 0), 2);
                $add_line(sprintf(
                    '%-10s %-28s %11s %11s',
                    $shift_date !== '' ? $shift_date : '-',
                    $role_label,
                    number_format($unit_price, 2),
                    number_format($line_total, 2)
                ), 'table_row');
            }
        }

        $add_section('Adjustments');
        $add_line(sprintf('%-12s %-44s %12s', 'Type', 'Label', 'Amount GBP'), 'table_header');
        $add_line(str_repeat('-', 70), 'table_rule');
        if (!$adjustments) {
            $add_line('No adjustments recorded.');
        } else {
            foreach ($adjustments as $adjustment_row) {
                $type = strtoupper($this->truncate_invoice_pdf_text((string) ($adjustment_row['type'] ?? 'adjustment'), 12));
                $label = $this->truncate_invoice_pdf_text((string) ($adjustment_row['label'] ?? 'Adjustment'), 44);
                $amount = round((float) ($adjustment_row['amount'] ?? 0), 2);
                $add_line(sprintf(
                    '%-12s %-44s %12s',
                    $type,
                    $label,
                    number_format($amount, 2)
                ), 'table_row');
            }
        }

        $add_section('Totals');
        $add_line(sprintf('%-30s %12s', 'Subtotal (GBP)', number_format((float) ($invoice['subtotal'] ?? 0), 2)));
        $add_line(sprintf('%-30s %12s', 'Adjustments total (GBP)', number_format((float) ($invoice['adjustments_total'] ?? 0), 2)));
        $add_line(sprintf('%-30s %12s', 'VAT (GBP)', number_format((float) ($invoice['vat_total'] ?? 0), 2)));
        $add_line(sprintf('%-30s %12s', 'Final total (GBP)', number_format((float) ($invoice['total'] ?? 0), 2)), 'table_header');

        $add_section('Payment Instructions');
        $instructions = apply_filters('cmn_invoice_pdf_payment_instructions', [
            'Please pay via bank transfer within 14 days of invoice issue date.',
            'Use payment reference: ' . ($invoice_number !== '' ? $invoice_number : 'invoice number'),
            'Send remittance advice to accounts@covermenow.co.uk.',
            'Always communicate changes inside the booking chat.',
        ], $invoice);
        if (!is_array($instructions) || !$instructions) {
            $instructions = ['Please contact accounts@covermenow.co.uk for payment instructions.'];
        }
        foreach ($instructions as $instruction_line) {
            $instruction_line = sanitize_text_field((string) $instruction_line);
            if ($instruction_line === '') {
                continue;
            }
            $add_wrapped($instruction_line, 'line', 88);
        }

        return $rows;
    }

    private function build_invoice_pdf_page_stream($invoice, $page_rows, $page_number, $total_pages, $logo_data = []) {
        $invoice = is_array($invoice) ? $invoice : [];
        $page_rows = is_array($page_rows) ? $page_rows : [];
        $page_number = max(1, (int) $page_number);
        $total_pages = max(1, (int) $total_pages);
        $logo_data = is_array($logo_data) ? $logo_data : [];

        $invoice_number = sanitize_text_field((string) ($invoice['invoice_number'] ?? 'Invoice'));
        $period_start = $this->normalize_invoice_date((string) ($invoice['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($invoice['period_end'] ?? ''));
        $period_label = ($period_start !== '' ? $period_start : 'N/A') . ' to ' . ($period_end !== '' ? $period_end : 'N/A');

        $commands = [];
        $commands[] = 'q';
        $commands[] = '0.78 0.08 0.16 rg';
        $commands[] = '0 782 595 60 re f';
        $commands[] = 'Q';

        $header_x = 24.0;
        if (!empty($logo_data['width']) && !empty($logo_data['height'])) {
            $logo_w = max(1, (int) $logo_data['width']);
            $logo_h = max(1, (int) $logo_data['height']);
            $max_w = 120.0;
            $max_h = 36.0;
            $scale = min($max_w / $logo_w, $max_h / $logo_h);
            $draw_w = round($logo_w * $scale, 2);
            $draw_h = round($logo_h * $scale, 2);
            $draw_x = 20.0;
            $draw_y = 794.0;
            $commands[] = 'q';
            $commands[] = sprintf('%.2F 0 0 %.2F %.2F %.2F cm', $draw_w, $draw_h, $draw_x, $draw_y);
            $commands[] = '/Im1 Do';
            $commands[] = 'Q';
            $header_x = $draw_x + $draw_w + 12.0;
        }

        $commands[] = 'BT';
        $commands[] = '/F2 15 Tf';
        $commands[] = '1 1 1 rg';
        $commands[] = sprintf('1 0 0 1 %.2F %.2F Tm', $header_x, 819.0);
        $commands[] = '(' . $this->escape_invoice_pdf_text('CoverMeNow ONE - School Invoice', 80) . ') Tj';
        $commands[] = 'ET';

        $commands[] = 'BT';
        $commands[] = '/F1 10 Tf';
        $commands[] = '1 1 1 rg';
        $commands[] = sprintf('1 0 0 1 %.2F %.2F Tm', $header_x, 803.0);
        $commands[] = '(' . $this->escape_invoice_pdf_text($invoice_number . ' | ' . $period_label, 96) . ') Tj';
        $commands[] = 'ET';

        $commands[] = 'BT';
        $commands[] = '/F1 9 Tf';
        $commands[] = '1 1 1 rg';
        $commands[] = sprintf('1 0 0 1 %.2F %.2F Tm', 500.0, 803.0);
        $commands[] = '(' . $this->escape_invoice_pdf_text('Page ' . $page_number . ' / ' . $total_pages, 24) . ') Tj';
        $commands[] = 'ET';

        $y = 760.0;
        foreach ($page_rows as $row) {
            $row = is_array($row) ? $row : [];
            $row_type = sanitize_key((string) ($row['type'] ?? 'line'));
            $row_text = (string) ($row['text'] ?? '');
            if ($row_type === 'gap') {
                $y -= 6.0;
                continue;
            }
            if ($y < 50.0) {
                break;
            }
            $font = '/F3';
            $size = 9.0;
            $color = '0 0 0 rg';
            if ($row_type === 'section') {
                $font = '/F2';
                $size = 10.0;
                $color = '0.62 0.07 0.15 rg';
            } elseif ($row_type === 'table_header') {
                $font = '/F2';
                $size = 9.0;
            } elseif ($row_type === 'table_rule') {
                $font = '/F3';
                $size = 8.5;
            }
            $commands[] = 'BT';
            $commands[] = $font . ' ' . number_format($size, 1, '.', '') . ' Tf';
            $commands[] = $color;
            $commands[] = sprintf('1 0 0 1 %.2F %.2F Tm', 28.0, $y);
            $commands[] = '(' . $this->escape_invoice_pdf_text($row_text, 140) . ') Tj';
            $commands[] = 'ET';
            $y -= ($row_type === 'section') ? 12.5 : 11.0;
        }

        return implode("\n", $commands) . "\n";
    }

    private function generate_invoice_pdf_binary($invoice, $school_name, $items, $adjustments) {
        $invoice = is_array($invoice) ? $invoice : [];
        $school_name = sanitize_text_field((string) $school_name);
        $rows = $this->build_invoice_pdf_rows($invoice, $school_name, $items, $adjustments);
        $rows = is_array($rows) ? $rows : [];
        if (!$rows) {
            $rows = [['type' => 'line', 'text' => 'No invoice content available.']];
        }

        $rows_per_page = 52;
        $pages = array_chunk($rows, $rows_per_page);
        if (!$pages) {
            $pages = [[]];
        }
        $logo_data = $this->get_invoice_pdf_logo_data();

        $objects = [];
        $add_object = function ($body) use (&$objects) {
            $object_id = count($objects) + 1;
            $objects[] = $object_id . " 0 obj\n" . $body . "\nendobj\n";
            return $object_id;
        };

        $font_regular_id = $add_object('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
        $font_bold_id = $add_object('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
        $font_mono_id = $add_object('<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>');

        $image_object_id = 0;
        if (!empty($logo_data['stream']) && !empty($logo_data['width']) && !empty($logo_data['height'])) {
            $image_stream = (string) $logo_data['stream'];
            $image_object_id = $add_object(
                '<< /Type /XObject /Subtype /Image /Width ' . (int) $logo_data['width'] .
                ' /Height ' . (int) $logo_data['height'] .
                ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /FlateDecode ' .
                '/DecodeParms << /Predictor 15 /Colors 3 /BitsPerComponent 8 /Columns ' . (int) $logo_data['width'] . ' >> ' .
                '/Length ' . strlen($image_stream) . " >>\nstream\n" . $image_stream . "\nendstream"
            );
        }

        $content_object_ids = [];
        $page_total = count($pages);
        foreach ($pages as $page_index => $page_rows) {
            $stream = $this->build_invoice_pdf_page_stream(
                $invoice,
                $page_rows,
                $page_index + 1,
                $page_total,
                $logo_data
            );
            $content_object_ids[] = $add_object('<< /Length ' . strlen($stream) . " >>\nstream\n" . $stream . "endstream");
        }

        $pages_object_id = count($objects) + 1;
        $page_object_ids = [];
        for ($i = 0; $i < count($content_object_ids); $i++) {
            $page_object_ids[] = $pages_object_id + 1 + $i;
        }
        $page_kids = implode(' ', array_map(static function ($id) {
            return (int) $id . ' 0 R';
        }, $page_object_ids));
        $add_object('<< /Type /Pages /Kids [' . $page_kids . '] /Count ' . count($page_object_ids) . ' >>');

        foreach ($content_object_ids as $content_id) {
            $resources = '<< /Font << /F1 ' . $font_regular_id . ' 0 R /F2 ' . $font_bold_id . ' 0 R /F3 ' . $font_mono_id . ' 0 R >>';
            if ($image_object_id > 0) {
                $resources .= ' /XObject << /Im1 ' . $image_object_id . ' 0 R >>';
            }
            $resources .= ' >>';
            $add_object(
                '<< /Type /Page /Parent ' . $pages_object_id . ' 0 R /MediaBox [0 0 595 842] ' .
                '/Resources ' . $resources . ' /Contents ' . (int) $content_id . ' 0 R >>'
            );
        }

        $catalog_id = $add_object('<< /Type /Catalog /Pages ' . $pages_object_id . ' 0 R >>');

        $pdf = "%PDF-1.4\n";
        $offsets = [0];
        foreach ($objects as $object_text) {
            $offsets[] = strlen($pdf);
            $pdf .= $object_text;
        }
        $xref_offset = strlen($pdf);
        $pdf .= "xref\n0 " . (count($objects) + 1) . "\n";
        $pdf .= "0000000000 65535 f \n";
        for ($i = 1; $i <= count($objects); $i++) {
            $pdf .= sprintf("%010d 00000 n \n", (int) $offsets[$i]);
        }
        $pdf .= "trailer\n<< /Size " . (count($objects) + 1) . " /Root " . $catalog_id . " 0 R >>\n";
        $pdf .= "startxref\n" . $xref_offset . "\n%%EOF";
        return $pdf;
    }

    private function get_invoice_pdf_document($invoice, $options = []) {
        $options = is_array($options) ? $options : [];
        $force_regenerate = !empty($options['force_regenerate']);
        $invoice = is_array($invoice) ? $invoice : [];
        $invoice_id = (int) ($invoice['id'] ?? 0);
        if ($invoice_id < 1) {
            return new WP_Error('cmn_invoice_pdf_invalid_invoice', 'Invalid invoice context.');
        }

        $items = $this->get_invoice_items($invoice_id);
        $adjustments = $this->get_invoice_adjustments($invoice_id);
        $school_name = $this->get_invoice_school_display_name(
            (int) ($invoice['school_id'] ?? 0),
            (string) ($invoice['school_name'] ?? '')
        );
        $download_name = $this->get_invoice_pdf_download_filename($invoice);

        $status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        $cache_allowed = in_array($status, ['sent', 'paid', 'void'], true);
        $cache_path = '';
        if ($cache_allowed) {
            $cache_dir = $this->get_invoice_pdf_cache_directory();
            if ($cache_dir !== '') {
                $signature_payload = [
                    'invoice' => [
                        'id' => $invoice_id,
                        'invoice_number' => (string) ($invoice['invoice_number'] ?? ''),
                        'status' => $status,
                        'period_start' => (string) ($invoice['period_start'] ?? ''),
                        'period_end' => (string) ($invoice['period_end'] ?? ''),
                        'subtotal' => round((float) ($invoice['subtotal'] ?? 0), 2),
                        'adjustments_total' => round((float) ($invoice['adjustments_total'] ?? 0), 2),
                        'vat_total' => round((float) ($invoice['vat_total'] ?? 0), 2),
                        'total' => round((float) ($invoice['total'] ?? 0), 2),
                        'updated_at' => (string) ($invoice['updated_at'] ?? ''),
                    ],
                    'items' => array_values((array) $items),
                    'adjustments' => array_values((array) $adjustments),
                ];
                $signature = substr(hash('sha256', (string) wp_json_encode($signature_payload)), 0, 24);
                if ($signature === '') {
                    $signature = substr(hash('sha256', (string) microtime(true)), 0, 24);
                }
                $cache_path = $cache_dir . '/inv-' . $invoice_id . '-' . $signature . '.pdf';
                if (!$force_regenerate && is_readable($cache_path)) {
                    return [
                        'file_path' => $cache_path,
                        'binary' => '',
                        'download_name' => $download_name,
                        'cached' => true,
                    ];
                }
            }
        }

        $binary = $this->generate_invoice_pdf_binary($invoice, $school_name, $items, $adjustments);
        if (!is_string($binary) || $binary === '') {
            return new WP_Error('cmn_invoice_pdf_generate_failed', 'Failed to generate PDF binary.');
        }

        if ($cache_allowed && $cache_path !== '') {
            @file_put_contents($cache_path, $binary, LOCK_EX);
            @chmod($cache_path, 0600);
            $cache_glob = glob(dirname($cache_path) . '/inv-' . $invoice_id . '-*.pdf');
            if (is_array($cache_glob)) {
                foreach ($cache_glob as $old_path) {
                    if ($old_path === $cache_path) {
                        continue;
                    }
                    @unlink($old_path);
                }
            }
        }

        return [
            'file_path' => ($cache_allowed && $cache_path !== '' && is_readable($cache_path)) ? $cache_path : '',
            'binary' => $binary,
            'download_name' => $download_name,
            'cached' => false,
        ];
    }

    private function get_invoice_list_results($filters = []) {
        $filters = is_array($filters) ? $filters : [];
        $status_filter = sanitize_key((string) ($filters['status'] ?? ''));
        if (!in_array($status_filter, $this->get_allowed_invoice_statuses(), true)) {
            $status_filter = '';
        }
        $month_filter = sanitize_text_field((string) ($filters['month'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}$/', $month_filter)) {
            $month_filter = '';
        }
        $school_filter = sanitize_text_field((string) ($filters['school'] ?? ''));
        $page = max(1, (int) ($filters['page'] ?? 1));
        $per_page = max(10, min(100, (int) ($filters['per_page'] ?? 20)));
        $offset = ($page - 1) * $per_page;

        global $wpdb;
        $table = $this->get_invoices_table();
        $posts_table = $wpdb->posts;
        $where = ['1=1'];
        $params = [];

        if ($status_filter !== '') {
            $where[] = 'i.status = %s';
            $params[] = $status_filter;
        }

        if ($month_filter !== '') {
            $month_year = (int) substr($month_filter, 0, 4);
            $month_month = (int) substr($month_filter, 5, 2);
            $bounds = $this->get_invoice_month_bounds($month_year, $month_month);
            if ($bounds) {
                $where[] = 'i.period_start <= %s';
                $params[] = (string) ($bounds['period_end'] ?? '');
                $where[] = 'i.period_end >= %s';
                $params[] = (string) ($bounds['period_start'] ?? '');
            }
        }

        if ($school_filter !== '') {
            if (preg_match('/^(\d+)/', $school_filter, $m) === 1) {
                $where[] = 'i.school_id = %d';
                $params[] = (int) $m[1];
            } else {
                $where[] = 'p.post_title LIKE %s';
                $params[] = '%' . $wpdb->esc_like($school_filter) . '%';
            }
        }

        $where_sql = implode(' AND ', $where);
        $count_sql = "SELECT COUNT(*)
                      FROM {$table} i
                      LEFT JOIN {$posts_table} p ON p.ID = i.school_id
                      WHERE {$where_sql}";
        $count_query = !empty($params) ? $wpdb->prepare($count_sql, ...$params) : $count_sql;
        $total_rows = (int) $wpdb->get_var($count_query);

        $list_sql = "SELECT i.*, p.post_title AS school_name
                     FROM {$table} i
                     LEFT JOIN {$posts_table} p ON p.ID = i.school_id
                     WHERE {$where_sql}
                     ORDER BY i.created_at DESC, i.id DESC
                     LIMIT %d OFFSET %d";
        $list_params = array_merge($params, [$per_page, $offset]);
        $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
        if (!is_array($rows)) {
            $rows = [];
        }
        $total_pages = (int) max(1, ceil($total_rows / max(1, $per_page)));
        if ($page > $total_pages && $total_pages > 0) {
            $page = $total_pages;
            $offset = ($page - 1) * $per_page;
            $list_params = array_merge($params, [$per_page, $offset]);
            $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
            if (!is_array($rows)) {
                $rows = [];
            }
        }

        return [
            'rows' => $rows,
            'total_rows' => $total_rows,
            'page' => $page,
            'per_page' => $per_page,
            'total_pages' => $total_pages,
            'status_filter' => $status_filter,
            'month_filter' => $month_filter,
            'school_filter' => $school_filter,
        ];
    }

    private function can_access_finance_reporting($user_id = 0) {
        $user_id = (int) ($user_id ?: get_current_user_id());
        if ($user_id < 1) {
            return false;
        }
        return $this->is_admin_user($user_id) || $this->is_staff_role($user_id);
    }

    private function normalize_finance_month_filter($month_value) {
        $month_value = sanitize_text_field((string) $month_value);
        if (preg_match('/^\d{4}-\d{2}$/', $month_value) !== 1) {
            return current_time('Y-m');
        }
        $year = (int) substr($month_value, 0, 4);
        $month = (int) substr($month_value, 5, 2);
        $bounds = $this->get_invoice_month_bounds($year, $month);
        if (!$bounds) {
            return current_time('Y-m');
        }
        return sprintf('%04d-%02d', $year, $month);
    }

    private function normalize_finance_paid_filter($paid_filter) {
        $paid_filter = sanitize_key((string) $paid_filter);
        if (!in_array($paid_filter, ['all', 'paid', 'unpaid'], true)) {
            return 'all';
        }
        return $paid_filter;
    }

    private function append_finance_paid_filter_sql($paid_filter, &$where_clauses, &$params, $status_column = 'i.status', $exclude_void_for_unpaid = true) {
        $paid_filter = $this->normalize_finance_paid_filter($paid_filter);
        $where_clauses = is_array($where_clauses) ? $where_clauses : [];
        $params = is_array($params) ? $params : [];
        if ($paid_filter === 'paid') {
            $where_clauses[] = "{$status_column} = %s";
            $params[] = 'paid';
            return $paid_filter;
        }
        if ($paid_filter === 'unpaid') {
            $where_clauses[] = "{$status_column} <> %s";
            $params[] = 'paid';
            if ($exclude_void_for_unpaid) {
                $where_clauses[] = "{$status_column} <> %s";
                $params[] = 'void';
            }
        }
        return $paid_filter;
    }

    private function get_finance_report_date_range($month_filter, $date_from = '', $date_to = '') {
        $month_filter = $this->normalize_finance_month_filter($month_filter);
        $date_from = $this->normalize_invoice_date((string) $date_from);
        $date_to = $this->normalize_invoice_date((string) $date_to);
        if ($date_from !== '' && $date_to !== '' && strtotime($date_to) >= strtotime($date_from)) {
            return [
                'mode' => 'range',
                'from' => $date_from,
                'to' => $date_to,
                'label' => date_i18n('j M Y', strtotime($date_from)) . ' to ' . date_i18n('j M Y', strtotime($date_to)),
                'month_filter' => $month_filter,
            ];
        }

        $year = (int) substr($month_filter, 0, 4);
        $month = (int) substr($month_filter, 5, 2);
        $bounds = $this->get_invoice_month_bounds($year, $month);
        if (!$bounds) {
            $fallback = current_time('Y-m');
            $year = (int) substr($fallback, 0, 4);
            $month = (int) substr($fallback, 5, 2);
            $bounds = $this->get_invoice_month_bounds($year, $month);
        }
        return [
            'mode' => 'month',
            'from' => (string) ($bounds['period_start'] ?? current_time('Y-m-01')),
            'to' => (string) ($bounds['period_end'] ?? current_time('Y-m-d')),
            'label' => date_i18n('F Y', strtotime($month_filter . '-01')),
            'month_filter' => $month_filter,
        ];
    }

    private function get_finance_overview_monthly_metrics($month_filter, $paid_filter = 'all') {
        $month_filter = $this->normalize_finance_month_filter($month_filter);
        $paid_filter = $this->normalize_finance_paid_filter($paid_filter);
        $year = (int) substr($month_filter, 0, 4);
        $month = (int) substr($month_filter, 5, 2);
        $bounds = $this->get_invoice_month_bounds($year, $month);
        if (!$bounds) {
            return [
                'month_filter' => $month_filter,
                'paid_filter' => $paid_filter,
                'invoice_count' => 0,
                'schools_invoiced' => 0,
                'subtotal_total' => 0.00,
                'partner_credit_total' => 0.00,
                'net_invoiced_total' => 0.00,
                'recorded_total' => 0.00,
            ];
        }

        global $wpdb;
        $invoices_table = $this->get_invoices_table();
        $adjustments_table = $this->get_invoice_adjustments_table();
        $where = [
            'i.status <> %s',
            'i.period_start <= %s',
            'i.period_end >= %s',
        ];
        $params = [
            'void',
            (string) ($bounds['period_end'] ?? ''),
            (string) ($bounds['period_start'] ?? ''),
        ];
        $this->append_finance_paid_filter_sql($paid_filter, $where, $params, 'i.status', true);
        $where_sql = implode(' AND ', $where);

        $invoice_totals = $wpdb->get_row($wpdb->prepare(
            "SELECT
                COALESCE(SUM(i.subtotal), 0) AS subtotal_total,
                COALESCE(SUM(i.total), 0) AS recorded_total,
                COUNT(*) AS invoice_count,
                COUNT(DISTINCT i.school_id) AS schools_invoiced
             FROM {$invoices_table} i
             WHERE {$where_sql}",
            ...$params
        ), ARRAY_A);
        $invoice_totals = is_array($invoice_totals) ? $invoice_totals : [];

        $credit_where = array_merge(['adj.type = %s'], $where);
        $credit_params = array_merge(['partner_credit'], $params);
        $partner_credit_raw = (float) $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(ABS(adj.amount)), 0)
             FROM {$adjustments_table} adj
             INNER JOIN {$invoices_table} i ON i.id = adj.invoice_id
             WHERE " . implode(' AND ', $credit_where),
            ...$credit_params
        ));

        $subtotal_total = round((float) ($invoice_totals['subtotal_total'] ?? 0), 2);
        $recorded_total = round((float) ($invoice_totals['recorded_total'] ?? 0), 2);
        $partner_credit_total = round(max(0, $partner_credit_raw), 2);
        $net_invoiced_total = round(max(0, $subtotal_total - $partner_credit_total), 2);

        return [
            'month_filter' => $month_filter,
            'month_label' => date_i18n('F Y', strtotime($month_filter . '-01')),
            'paid_filter' => $paid_filter,
            'invoice_count' => max(0, (int) ($invoice_totals['invoice_count'] ?? 0)),
            'schools_invoiced' => max(0, (int) ($invoice_totals['schools_invoiced'] ?? 0)),
            'subtotal_total' => $subtotal_total,
            'partner_credit_total' => $partner_credit_total,
            'net_invoiced_total' => $net_invoiced_total,
            'recorded_total' => $recorded_total,
        ];
    }

    private function get_finance_overview_top_schools_by_revenue($period_start, $period_end, $paid_filter = 'all', $limit = 5) {
        $period_start = $this->normalize_invoice_date($period_start);
        $period_end = $this->normalize_invoice_date($period_end);
        $paid_filter = $this->normalize_finance_paid_filter($paid_filter);
        $limit = max(1, min(20, (int) $limit));
        if ($period_start === '' || $period_end === '') {
            return [];
        }

        global $wpdb;
        $invoices_table = $this->get_invoices_table();
        $posts_table = $wpdb->posts;
        $where = [
            'i.status <> %s',
            'i.period_start <= %s',
            'i.period_end >= %s',
        ];
        $params = ['void', $period_end, $period_start];
        $this->append_finance_paid_filter_sql($paid_filter, $where, $params, 'i.status', true);
        $where_sql = implode(' AND ', $where);
        $params[] = $limit;
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT
                i.school_id,
                p.post_title AS school_name,
                COALESCE(SUM(i.subtotal), 0) AS gross_revenue,
                COALESCE(SUM(i.total), 0) AS recorded_total,
                COUNT(*) AS invoice_count
             FROM {$invoices_table} i
             LEFT JOIN {$posts_table} p ON p.ID = i.school_id
             WHERE {$where_sql}
             GROUP BY i.school_id, p.post_title
             ORDER BY gross_revenue DESC, i.school_id ASC
             LIMIT %d",
            ...$params
        ), ARRAY_A);
        if (!is_array($rows)) {
            return [];
        }
        foreach ($rows as &$row) {
            $row_school_id = (int) ($row['school_id'] ?? 0);
            $row['school_name'] = $this->get_invoice_school_display_name($row_school_id, (string) ($row['school_name'] ?? ''));
            $row['gross_revenue'] = round((float) ($row['gross_revenue'] ?? 0), 2);
            $row['recorded_total'] = round((float) ($row['recorded_total'] ?? 0), 2);
            $row['invoice_count'] = max(0, (int) ($row['invoice_count'] ?? 0));
        }
        unset($row);
        return $rows;
    }

    private function get_finance_overview_top_schools_by_savings($period_start, $period_end, $paid_filter = 'all', $limit = 5) {
        $period_start = $this->normalize_invoice_date($period_start);
        $period_end = $this->normalize_invoice_date($period_end);
        $paid_filter = $this->normalize_finance_paid_filter($paid_filter);
        $limit = max(1, min(20, (int) $limit));
        if ($period_start === '' || $period_end === '') {
            return [];
        }

        global $wpdb;
        $invoices_table = $this->get_invoices_table();
        $adjustments_table = $this->get_invoice_adjustments_table();
        $posts_table = $wpdb->posts;
        $where = [
            'adj.type = %s',
            'i.status <> %s',
            'i.period_start <= %s',
            'i.period_end >= %s',
        ];
        $params = ['partner_credit', 'void', $period_end, $period_start];
        $this->append_finance_paid_filter_sql($paid_filter, $where, $params, 'i.status', true);
        $where_sql = implode(' AND ', $where);
        $params[] = $limit;
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT
                i.school_id,
                p.post_title AS school_name,
                COALESCE(SUM(ABS(adj.amount)), 0) AS savings_total,
                COUNT(DISTINCT i.id) AS invoice_count
             FROM {$adjustments_table} adj
             INNER JOIN {$invoices_table} i ON i.id = adj.invoice_id
             LEFT JOIN {$posts_table} p ON p.ID = i.school_id
             WHERE {$where_sql}
             GROUP BY i.school_id, p.post_title
             ORDER BY savings_total DESC, i.school_id ASC
             LIMIT %d",
            ...$params
        ), ARRAY_A);
        if (!is_array($rows)) {
            return [];
        }
        foreach ($rows as &$row) {
            $row_school_id = (int) ($row['school_id'] ?? 0);
            $row['school_name'] = $this->get_invoice_school_display_name($row_school_id, (string) ($row['school_name'] ?? ''));
            $row['savings_total'] = round((float) ($row['savings_total'] ?? 0), 2);
            $row['invoice_count'] = max(0, (int) ($row['invoice_count'] ?? 0));
        }
        unset($row);
        return $rows;
    }

    private function get_finance_overview_academic_year_metrics($reference_date = '', $paid_filter = 'all') {
        $paid_filter = $this->normalize_finance_paid_filter($paid_filter);
        $context = $this->get_school_partner_academic_year_context($reference_date);
        $period_start = (string) ($context['start_date'] ?? '');
        $period_end = (string) ($context['end_date'] ?? '');
        if ($period_start === '' || $period_end === '') {
            return [
                'academic_year_label' => '',
                'total_partner_savings' => 0.00,
                'total_invoice_revenue_gross' => 0.00,
                'total_net_revenue' => 0.00,
                'top_schools_by_revenue' => [],
                'top_schools_by_savings' => [],
            ];
        }

        global $wpdb;
        $invoices_table = $this->get_invoices_table();
        $adjustments_table = $this->get_invoice_adjustments_table();
        $where = [
            'i.status <> %s',
            'i.period_start <= %s',
            'i.period_end >= %s',
        ];
        $params = ['void', $period_end, $period_start];
        $this->append_finance_paid_filter_sql($paid_filter, $where, $params, 'i.status', true);
        $where_sql = implode(' AND ', $where);

        $gross_raw = (float) $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(i.subtotal), 0)
             FROM {$invoices_table} i
             WHERE {$where_sql}",
            ...$params
        ));
        $credit_params = array_merge(['partner_credit'], $params);
        $credit_raw = (float) $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(ABS(adj.amount)), 0)
             FROM {$adjustments_table} adj
             INNER JOIN {$invoices_table} i ON i.id = adj.invoice_id
             WHERE adj.type = %s
               AND {$where_sql}",
            ...$credit_params
        ));
        $gross = round(max(0, $gross_raw), 2);
        $partner_savings = round(max(0, $credit_raw), 2);
        $net = round(max(0, $gross - $partner_savings), 2);

        return [
            'academic_year_label' => (string) ($context['label'] ?? ''),
            'academic_year_start' => $period_start,
            'academic_year_end' => $period_end,
            'paid_filter' => $paid_filter,
            'total_partner_savings' => $partner_savings,
            'total_invoice_revenue_gross' => $gross,
            'total_net_revenue' => $net,
            'top_schools_by_revenue' => $this->get_finance_overview_top_schools_by_revenue($period_start, $period_end, $paid_filter, 5),
            'top_schools_by_savings' => $this->get_finance_overview_top_schools_by_savings($period_start, $period_end, $paid_filter, 5),
        ];
    }

    private function get_finance_overview_tier_distribution() {
        $definitions = (array) $this->get_school_partner_tier_definitions();
        $counts = [];
        foreach (array_keys($definitions) as $tier_key) {
            $counts[$tier_key] = 0;
        }

        global $wpdb;
        $posts_table = $wpdb->posts;
        $partner_table = $this->get_school_partner_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT
                COALESCE(NULLIF(sp.tier, ''), %s) AS tier,
                COUNT(*) AS school_count
             FROM {$posts_table} p
             LEFT JOIN {$partner_table} sp ON sp.school_id = p.ID
             WHERE p.post_type = %s
               AND p.post_status IN ('publish', 'private', 'draft', 'pending', 'future')
             GROUP BY COALESCE(NULLIF(sp.tier, ''), %s)",
            'standard',
            'cmn_school',
            'standard'
        ), ARRAY_A);
        if (is_array($rows)) {
            foreach ($rows as $row) {
                $tier = $this->normalize_school_partner_tier((string) ($row['tier'] ?? 'standard'));
                $counts[$tier] = max(0, (int) ($row['school_count'] ?? 0));
            }
        }

        $total = array_sum($counts);
        $output_rows = [];
        foreach (array_keys($definitions) as $tier_key) {
            $output_rows[] = [
                'tier' => $tier_key,
                'label' => $this->get_school_partner_tier_label($tier_key),
                'count' => max(0, (int) ($counts[$tier_key] ?? 0)),
            ];
        }
        return [
            'total' => max(0, (int) $total),
            'rows' => $output_rows,
        ];
    }

    private function get_finance_month_option_rows($count = 18) {
        $count = max(1, min(36, (int) $count));
        $current_ts = strtotime(current_time('Y-m-01'));
        if ($current_ts === false) {
            $current_ts = strtotime(gmdate('Y-m-01'));
        }
        $rows = [];
        for ($i = 0; $i < $count; $i++) {
            $ts = strtotime('-' . $i . ' month', $current_ts);
            if ($ts === false) {
                continue;
            }
            $rows[] = [
                'value' => gmdate('Y-m', $ts),
                'label' => date_i18n('F Y', $ts),
            ];
        }
        return $rows;
    }

    private function get_school_invoice_list_results($school_id, $filters = []) {
        $school_id = (int) $school_id;
        $filters = is_array($filters) ? $filters : [];
        $status_filter = sanitize_key((string) ($filters['status'] ?? ''));
        if (!in_array($status_filter, $this->get_allowed_invoice_statuses(), true)) {
            $status_filter = '';
        }
        $month_filter = sanitize_text_field((string) ($filters['month'] ?? current_time('Y-m')));
        if (!preg_match('/^\d{4}-\d{2}$/', $month_filter)) {
            $month_filter = current_time('Y-m');
        }
        $page = max(1, (int) ($filters['page'] ?? 1));
        $per_page = max(5, min(100, (int) ($filters['per_page'] ?? 10)));

        if ($school_id < 1) {
            return [
                'rows' => [],
                'total_rows' => 0,
                'page' => 1,
                'per_page' => $per_page,
                'total_pages' => 1,
                'status_filter' => $status_filter,
                'month_filter' => $month_filter,
            ];
        }

        $offset = ($page - 1) * $per_page;
        global $wpdb;
        $table = $this->get_invoices_table();
        $where = ['school_id = %d'];
        $params = [$school_id];

        if ($status_filter !== '') {
            $where[] = 'status = %s';
            $params[] = $status_filter;
        }
        if ($month_filter !== '') {
            $month_year = (int) substr($month_filter, 0, 4);
            $month_month = (int) substr($month_filter, 5, 2);
            $bounds = $this->get_invoice_month_bounds($month_year, $month_month);
            if ($bounds) {
                $where[] = 'period_start <= %s';
                $params[] = (string) ($bounds['period_end'] ?? '');
                $where[] = 'period_end >= %s';
                $params[] = (string) ($bounds['period_start'] ?? '');
            }
        }

        $where_sql = implode(' AND ', $where);
        $count_sql = "SELECT COUNT(*) FROM {$table} WHERE {$where_sql}";
        $count_query = $wpdb->prepare($count_sql, ...$params);
        $total_rows = (int) $wpdb->get_var($count_query);

        $list_sql = "SELECT * FROM {$table}
                     WHERE {$where_sql}
                     ORDER BY created_at DESC, id DESC
                     LIMIT %d OFFSET %d";
        $list_params = array_merge($params, [$per_page, $offset]);
        $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
        if (!is_array($rows)) {
            $rows = [];
        }

        $total_pages = (int) max(1, ceil($total_rows / max(1, $per_page)));
        if ($page > $total_pages && $total_pages > 0) {
            $page = $total_pages;
            $offset = ($page - 1) * $per_page;
            $list_params = array_merge($params, [$per_page, $offset]);
            $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
            if (!is_array($rows)) {
                $rows = [];
            }
        }

        return [
            'rows' => $rows,
            'total_rows' => $total_rows,
            'page' => $page,
            'per_page' => $per_page,
            'total_pages' => $total_pages,
            'status_filter' => $status_filter,
            'month_filter' => $month_filter,
        ];
    }

    private function get_school_partner_tier_label($tier) {
        $tier = $this->normalize_school_partner_tier((string) $tier);
        return ucfirst($tier);
    }

    private function get_school_partner_progress_snapshot($lifetime_credits) {
        $lifetime_credits = max(0, (int) $lifetime_credits);
        $current_tier = $this->get_school_partner_tier_for_credits($lifetime_credits);
        $thresholds = [
            'standard' => ['min' => 0, 'next_tier' => 'bronze', 'next_threshold' => 100],
            'bronze' => ['min' => 100, 'next_tier' => 'silver', 'next_threshold' => 300],
            'silver' => ['min' => 300, 'next_tier' => 'gold', 'next_threshold' => 700],
            'gold' => ['min' => 700, 'next_tier' => 'elite', 'next_threshold' => 1500],
            'elite' => ['min' => 1500, 'next_tier' => '', 'next_threshold' => 0],
        ];
        $current = $thresholds[$current_tier] ?? $thresholds['standard'];
        $current_min = (int) ($current['min'] ?? 0);
        $next_threshold = (int) ($current['next_threshold'] ?? 0);
        $next_tier = (string) ($current['next_tier'] ?? '');
        $is_top_tier = ($next_threshold < 1 || $next_tier === '');
        if ($is_top_tier) {
            return [
                'tier' => $current_tier,
                'tier_label' => $this->get_school_partner_tier_label($current_tier),
                'is_top_tier' => true,
                'next_tier' => '',
                'next_tier_label' => '',
                'next_threshold' => 0,
                'credits_remaining' => 0,
                'progress_percent' => 100.0,
            ];
        }

        $credits_remaining = max(0, $next_threshold - $lifetime_credits);
        $range = max(1, $next_threshold - $current_min);
        $progress_percent = (($lifetime_credits - $current_min) / $range) * 100;
        $progress_percent = max(0.0, min(100.0, round((float) $progress_percent, 2)));

        return [
            'tier' => $current_tier,
            'tier_label' => $this->get_school_partner_tier_label($current_tier),
            'is_top_tier' => false,
            'next_tier' => $next_tier,
            'next_tier_label' => $this->get_school_partner_tier_label($next_tier),
            'next_threshold' => $next_threshold,
            'credits_remaining' => $credits_remaining,
            'progress_percent' => $progress_percent,
        ];
    }

    private function get_school_partner_recent_invoices($school_id, $limit = 5) {
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return [];
        }
        $limit = max(1, min(20, (int) $limit));
        global $wpdb;
        $invoices_table = $this->get_invoices_table();
        $adjustments_table = $this->get_invoice_adjustments_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT
                i.id,
                i.invoice_number,
                i.period_start,
                i.period_end,
                i.status,
                i.total,
                i.created_at,
                COALESCE(ABS(SUM(CASE WHEN adj.type = %s THEN adj.amount ELSE 0 END)), 0) AS partner_credit_amount
             FROM {$invoices_table} i
             LEFT JOIN {$adjustments_table} adj
               ON adj.invoice_id = i.id
             WHERE i.school_id = %d
               AND i.status <> %s
             GROUP BY i.id, i.invoice_number, i.period_start, i.period_end, i.status, i.total, i.created_at
             ORDER BY i.created_at DESC, i.id DESC
             LIMIT %d",
            'partner_credit',
            $school_id,
            'void',
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function get_staff_partner_programme_list_results($filters = []) {
        $filters = is_array($filters) ? $filters : [];
        $tier_filter = sanitize_key((string) ($filters['tier'] ?? ''));
        if ($tier_filter === 'all') {
            $tier_filter = '';
        }
        $allowed_tiers = array_keys((array) $this->get_school_partner_tier_definitions());
        if ($tier_filter !== '' && !in_array($tier_filter, $allowed_tiers, true)) {
            $tier_filter = '';
        }
        $search_filter = sanitize_text_field((string) ($filters['search'] ?? ''));
        $sort_filter = sanitize_key((string) ($filters['sort'] ?? 'credits'));
        if (!in_array($sort_filter, ['credits', 'savings', 'tier', 'activity', 'name'], true)) {
            $sort_filter = 'credits';
        }
        $page = max(1, (int) ($filters['page'] ?? 1));
        $per_page = max(10, min(100, (int) ($filters['per_page'] ?? 25)));
        $offset = ($page - 1) * $per_page;

        global $wpdb;
        $posts_table = $wpdb->posts;
        $partner_table = $this->get_school_partner_table();
        $invoices_table = $this->get_invoices_table();
        $school_list_post_statuses = $this->get_school_list_post_statuses();
        $status_placeholders = implode(',', array_fill(0, count($school_list_post_statuses), '%s'));
        /*
         * Eligibility contract: Partner Programme list
         * - Entity source: cmn_school posts joined to cmn_school_partner state/savings rows.
         * - Inclusion: all school CRM records with internal post status in portal-visible school statuses.
         * - Optional filters: tier and free-text school search.
         */
        $where = [
            "p.post_type = %s",
            "p.post_status IN ({$status_placeholders})",
        ];
        $params = array_merge(['cmn_school'], $school_list_post_statuses);

        if ($tier_filter !== '') {
            $where[] = "COALESCE(sp.tier, 'standard') = %s";
            $params[] = $tier_filter;
        }

        if ($search_filter !== '') {
            $search_like = '%' . $wpdb->esc_like($search_filter) . '%';
            if (ctype_digit($search_filter)) {
                $where[] = "(p.post_title LIKE %s OR p.ID = %d)";
                $params[] = $search_like;
                $params[] = (int) $search_filter;
            } else {
                $where[] = "p.post_title LIKE %s";
                $params[] = $search_like;
            }
        }

        $order_sql = "lifetime_credits DESC, p.post_title ASC";
        if ($sort_filter === 'name') {
            $order_sql = "p.post_title ASC, p.ID ASC";
        } elseif ($sort_filter === 'savings') {
            $order_sql = "lifetime_savings DESC, p.post_title ASC";
        } elseif ($sort_filter === 'tier') {
            $order_sql = "tier_rank DESC, lifetime_credits DESC, p.post_title ASC";
        } elseif ($sort_filter === 'activity') {
            $order_sql = "last_activity_at DESC, p.post_title ASC";
        }

        $where_sql = implode(' AND ', $where);
        $count_sql = "SELECT COUNT(*)
                      FROM {$posts_table} p
                      LEFT JOIN {$partner_table} sp ON sp.school_id = p.ID
                      WHERE {$where_sql}";
        $count_query = $wpdb->prepare($count_sql, ...$params);
        $total_rows = (int) $wpdb->get_var($count_query);

        $list_sql = "SELECT
                        p.ID AS school_id,
                        p.post_title AS school_name,
                        COALESCE(sp.tier, 'standard') AS tier,
                        COALESCE(sp.discount_percent, 0) AS discount_percent,
                        COALESCE(sp.lifetime_credits, 0) AS lifetime_credits,
                        COALESCE(sp.lifetime_savings, 0) AS lifetime_savings,
                        COALESCE(sp.academic_year_savings, 0) AS academic_year_savings,
                        latest.last_invoice_date,
                        GREATEST(
                            COALESCE(latest.last_invoice_date, '1970-01-01 00:00:00'),
                            COALESCE(sp.updated_at, '1970-01-01 00:00:00'),
                            COALESCE(p.post_modified, '1970-01-01 00:00:00')
                        ) AS last_activity_at,
                        CASE COALESCE(sp.tier, 'standard')
                            WHEN 'elite' THEN 5
                            WHEN 'gold' THEN 4
                            WHEN 'silver' THEN 3
                            WHEN 'bronze' THEN 2
                            ELSE 1
                        END AS tier_rank
                    FROM {$posts_table} p
                    LEFT JOIN {$partner_table} sp ON sp.school_id = p.ID
                    LEFT JOIN (
                        SELECT school_id, MAX(created_at) AS last_invoice_date
                        FROM {$invoices_table}
                        WHERE status <> 'void'
                        GROUP BY school_id
                    ) latest ON latest.school_id = p.ID
                    WHERE {$where_sql}
                    ORDER BY {$order_sql}
                    LIMIT %d OFFSET %d";
        $list_params = array_merge($params, [$per_page, $offset]);
        $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
        if (!is_array($rows)) {
            $rows = [];
        }

        $total_pages = (int) max(1, ceil($total_rows / max(1, $per_page)));
        if ($page > $total_pages && $total_pages > 0) {
            $page = $total_pages;
            $offset = ($page - 1) * $per_page;
            $list_params = array_merge($params, [$per_page, $offset]);
            $rows = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_params), ARRAY_A);
            if (!is_array($rows)) {
                $rows = [];
            }
        }

        return [
            'rows' => $rows,
            'total_rows' => $total_rows,
            'page' => $page,
            'per_page' => $per_page,
            'total_pages' => $total_pages,
            'tier_filter' => $tier_filter,
            'search_filter' => $search_filter,
            'sort_filter' => $sort_filter,
        ];
    }

    private function get_school_partner_credit_adjustments_rows($school_id, $limit = 10) {
        $school_id = (int) $school_id;
