        $limit = max(1, min(50, (int) $limit));
        global $wpdb;
        $adjustments_table = $this->get_invoice_adjustments_table();
        $invoices_table = $this->get_invoices_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT
                adj.id,
                adj.invoice_id,
                inv.invoice_number,
                inv.period_start,
                inv.period_end,
                adj.label,
                adj.amount,
                adj.reason,
                adj.created_at
             FROM {$adjustments_table} adj
             INNER JOIN {$invoices_table} inv ON inv.id = adj.invoice_id
             WHERE inv.school_id = %d
               AND adj.type = %s
               AND inv.status <> %s
             ORDER BY adj.id DESC
             LIMIT %d",
            $school_id,
            'partner_credit',
            'void',
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

