    private function recalculate_school_partner_profile_for_staff($school_id, $actor_user_id = 0, $source = 'staff_manual_recalculate') {
        $school_id = (int) $school_id;
        $actor_user_id = (int) ($actor_user_id ?: get_current_user_id());
        $source = sanitize_key((string) $source);
        if ($source === '') {
            $source = 'staff_manual_recalculate';
        }
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return new WP_Error('cmn_school_partner_invalid_school', 'Invalid school for recalculation.');
        }
        $before = $this->get_or_create_school_partner($school_id);
        if (is_wp_error($before)) {
            return $before;
        }
        $before = is_array($before) ? $before : [];

        global $wpdb;
        $events_table = $this->get_school_partner_events_table();
        $partner_table = $this->get_school_partner_table();
        $event_credit_total = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(delta), 0)
             FROM {$events_table}
             WHERE school_id = %d",
            $school_id
        ));
        $recomputed_credits = max(0, $event_credit_total);
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$partner_table}
             SET lifetime_credits = %d,
                 updated_at = %s
             WHERE school_id = %d",
            $recomputed_credits,
            current_time('mysql'),
            $school_id
        ));
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_recalculate_failed', 'Unable to update lifetime credits.');
        }

        $tier_result = $this->recalculate_school_partner_tier($school_id);
        if (is_wp_error($tier_result)) {
            return $tier_result;
        }
        $savings_result = $this->recalculate_school_partner_savings($school_id, [
            'source' => $source,
            'reference_date' => current_time('Y-m-d'),
        ]);
        if (is_wp_error($savings_result)) {
            return $savings_result;
        }
        $after = $this->get_or_create_school_partner($school_id);
        if (is_wp_error($after)) {
            return $after;
        }
        $after = is_array($after) ? $after : [];

        $this->add_audit_log('school_partner_recalculated', 'school', (string) $school_id, [
            'source' => $source,
            'before_credits' => (int) ($before['lifetime_credits'] ?? 0),
            'after_credits' => (int) ($after['lifetime_credits'] ?? 0),
            'before_tier' => (string) ($before['tier'] ?? 'standard'),
            'after_tier' => (string) ($after['tier'] ?? 'standard'),
            'before_lifetime_savings' => round((float) ($before['lifetime_savings'] ?? 0), 2),
            'after_lifetime_savings' => round((float) ($after['lifetime_savings'] ?? 0), 2),
        ], $actor_user_id);

        return [
            'school_id' => $school_id,
            'before' => $before,
            'after' => $after,
        ];
    }

    private function apply_school_partner_admin_credit_delta($school_id, $delta, $reason = '', $actor_user_id = 0) {
        $school_id = (int) $school_id;
        $delta = (int) $delta;
        $reason = sanitize_textarea_field((string) $reason);
        $actor_user_id = (int) ($actor_user_id ?: get_current_user_id());
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return new WP_Error('cmn_school_partner_invalid_school', 'Invalid school for credit adjustment.');
        }
        if ($delta === 0) {
            return new WP_Error('cmn_school_partner_invalid_delta', 'Credit delta must be non-zero.');
        }
        if ($reason === '') {
            return new WP_Error('cmn_school_partner_reason_required', 'A reason is required for credit adjustments.');
        }

        $before = $this->get_or_create_school_partner($school_id);
        if (is_wp_error($before)) {
            return $before;
        }
        $before = is_array($before) ? $before : [];
        $before_credits = max(0, (int) ($before['lifetime_credits'] ?? 0));
        $after_credits = max(0, $before_credits + $delta);
        if ($after_credits === $before_credits) {
            return new WP_Error('cmn_school_partner_delta_no_effect', 'Adjustment would not change lifetime credits.');
        }

        global $wpdb;
        $events_table = $this->get_school_partner_events_table();
        $partner_table = $this->get_school_partner_table();
        $shift_date = current_time('Y-m-d');
        $event_type = 'admin_adjustment';
        $event_inserted = false;
        $event_booking_id = 0;
        for ($attempt = 0; $attempt < 5; $attempt++) {
            $event_booking_id = (int) floor(microtime(true) * 1000) + $attempt;
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT INTO {$events_table}
                 (school_id, booking_id, shift_date, event_type, delta, created_at)
                 VALUES
                 (%d, %d, %s, %s, %d, %s)",
                $school_id,
                $event_booking_id,
                $shift_date,
                $event_type,
                $delta,
                current_time('mysql')
            ));
            if ($inserted !== false) {
                $event_inserted = true;
                break;
            }
        }
        if (!$event_inserted) {
            return new WP_Error('cmn_school_partner_event_insert_failed', 'Could not log credit adjustment event.');
        }

        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$partner_table}
             SET lifetime_credits = %d,
                 updated_at = %s
             WHERE school_id = %d",
            $after_credits,
            current_time('mysql'),
            $school_id
        ));
        if ($updated === false) {
            return new WP_Error('cmn_school_partner_adjust_failed', 'Unable to apply lifetime credit adjustment.');
        }

        $tier_result = $this->recalculate_school_partner_tier($school_id);
        if (is_wp_error($tier_result)) {
            return $tier_result;
        }
        $savings_result = $this->recalculate_school_partner_savings($school_id, [
            'source' => 'admin_credit_adjustment',
            'reference_date' => current_time('Y-m-d'),
        ]);
        if (is_wp_error($savings_result)) {
            return $savings_result;
        }
        $after = $this->get_or_create_school_partner($school_id);
        if (is_wp_error($after)) {
            return $after;
        }
        $after = is_array($after) ? $after : [];
        $this->reconcile_single_school_list_visibility($school_id, false, $actor_user_id, 'partner_admin_credit_adjustment');

        $this->add_audit_log('school_partner_admin_credit_adjusted', 'school', (string) $school_id, [
            'reason' => $reason,
            'delta' => $delta,
            'before_credits' => $before_credits,
            'after_credits' => (int) ($after['lifetime_credits'] ?? $after_credits),
            'event_type' => $event_type,
            'event_booking_id' => $event_booking_id,
        ], $actor_user_id);

        return [
            'school_id' => $school_id,
            'before' => $before,
            'after' => $after,
        ];
    }

    private function get_invoice_school_filter_options($limit = 150) {
        global $wpdb;
        $table = $this->get_invoices_table();
        $posts_table = $wpdb->posts;
        $limit = max(10, min(500, (int) $limit));
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT DISTINCT i.school_id, p.post_title AS school_name
             FROM {$table} i
             LEFT JOIN {$posts_table} p ON p.ID = i.school_id
             WHERE i.school_id > 0
             ORDER BY p.post_title ASC, i.school_id ASC
             LIMIT %d",
            $limit
        ), ARRAY_A);
        if (!is_array($rows)) {
            return [];
        }
        $out = [];
        foreach ($rows as $row) {
            $school_id = (int) ($row['school_id'] ?? 0);
            if ($school_id < 1) {
                continue;
            }
            $out[] = [
                'school_id' => $school_id,
                'school_name' => $this->get_invoice_school_display_name($school_id, (string) ($row['school_name'] ?? '')),
            ];
        }
        return $out;
    }

    private function get_invoice_allowed_status_transitions($current_status, $user_id = 0) {
        $current_status = $this->normalize_invoice_status((string) $current_status);
        $user_id = (int) ($user_id ?: get_current_user_id());
        $targets = [];
        if ($current_status === 'draft') {
            $targets[] = 'issued';
            if ($this->is_admin_user($user_id)) {
                $targets[] = 'void';
            }
        } elseif ($current_status === 'issued') {
            $targets[] = 'sent';
            if ($this->is_admin_user($user_id)) {
                $targets[] = 'void';
            }
        } elseif ($current_status === 'sent') {
            $targets[] = 'paid';
        }
        return array_values(array_unique($targets));
    }

    public function set_invoice_status($invoice_id, $target_status, $actor_user_id = 0, $note = '') {
        $invoice_id = (int) $invoice_id;
        $target_status = $this->normalize_invoice_status($target_status);
        $actor_user_id = (int) ($actor_user_id ?: get_current_user_id());
        $note = sanitize_textarea_field((string) $note);
        if ($invoice_id < 1) {
            return new WP_Error('cmn_invoice_invalid', 'Invalid invoice.');
        }
        if (!$this->can_modify_invoice_records($actor_user_id)) {
            return new WP_Error('cmn_invoice_forbidden', 'Only admin/staff can change invoice status.');
        }
        $invoice = $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            return new WP_Error('cmn_invoice_not_found', 'Invoice not found.');
        }
        $current_status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        if (in_array($current_status, ['paid', 'void'], true)) {
            return new WP_Error('cmn_invoice_locked', 'Paid or void invoices cannot be modified.');
        }
        if ($target_status === $current_status) {
            return $invoice;
        }

        $allowed = $this->get_invoice_allowed_status_transitions($current_status, $actor_user_id);
        if (!in_array($target_status, $allowed, true)) {
            return new WP_Error('cmn_invoice_transition_blocked', 'Invalid status transition.');
        }
        if ($target_status === 'void' && !$this->is_admin_user($actor_user_id)) {
            return new WP_Error('cmn_invoice_void_forbidden', 'Only admin can void invoices.');
        }
        if ($target_status === 'void' && $current_status === 'paid') {
            return new WP_Error('cmn_invoice_void_paid_forbidden', 'Paid invoices cannot be voided.');
        }

        global $wpdb;
        $table = $this->get_invoices_table();
        $now = current_time('mysql');
        if ($target_status === 'sent') {
            $updated = $wpdb->query($wpdb->prepare(
                "UPDATE {$table}
                 SET status = %s,
                     updated_at = %s,
                     sent_at = CASE WHEN sent_at IS NULL OR sent_at = '' THEN %s ELSE sent_at END
                 WHERE id = %d",
                $target_status,
                $now,
                $now,
                $invoice_id
            ));
        } elseif ($target_status === 'paid') {
            $updated = $wpdb->query($wpdb->prepare(
                "UPDATE {$table}
                 SET status = %s,
                     updated_at = %s,
                     sent_at = CASE WHEN sent_at IS NULL OR sent_at = '' THEN %s ELSE sent_at END,
                     paid_at = %s
                 WHERE id = %d",
                $target_status,
                $now,
                $now,
                $now,
                $invoice_id
            ));
        } else {
            $updated = $wpdb->query($wpdb->prepare(
                "UPDATE {$table}
                 SET status = %s,
                     updated_at = %s
                 WHERE id = %d",
                $target_status,
                $now,
                $invoice_id
            ));
        }
        if ($updated === false) {
            return new WP_Error('cmn_invoice_status_update_failed', 'Failed to update invoice status.');
        }

        $audit_note = $note !== '' ? $note : ('Status changed from ' . $current_status . ' to ' . $target_status . '.');
        $this->log_invoice_audit_event($invoice_id, 'status_change', [
            'invoice' => $invoice,
            'from_status' => $current_status,
            'to_status' => $target_status,
            'user_id' => $actor_user_id,
            'note' => $audit_note,
        ]);
        if ($target_status === 'void') {
            $void_note = $note !== '' ? $note : 'Invoice voided.';
            $this->log_invoice_audit_event($invoice_id, 'invoice_voided', [
                'invoice' => $invoice,
                'from_status' => $current_status,
                'to_status' => $target_status,
                'user_id' => $actor_user_id,
                'note' => $void_note,
            ]);
        }

        $this->add_audit_log('invoice_status_changed', 'invoice', (string) $invoice_id, [
            'from' => $current_status,
            'to' => $target_status,
            'note' => $note,
        ], $actor_user_id);

        return $this->get_invoice_by_id($invoice_id);
    }

    private function update_invoice_status_record($invoice_id, $target_status, $actor_user_id = 0) {
        return $this->set_invoice_status($invoice_id, $target_status, $actor_user_id, '');
    }

    private function get_invoice_month_bounds($year, $month) {
        $year = (int) $year;
        $month = (int) $month;
        if ($year < 2000 || $year > 2100 || $month < 1 || $month > 12) {
            return [];
        }
        $days_in_month = cal_days_in_month(CAL_GREGORIAN, $month, $year);
        return [
            'year' => $year,
            'month' => $month,
            'month_key' => sprintf('%04d-%02d', $year, $month),
            'period_start' => sprintf('%04d-%02d-01', $year, $month),
            'period_end' => sprintf('%04d-%02d-%02d', $year, $month, $days_in_month),
        ];
    }

    private function get_completed_payable_booking_statuses() {
        return ['approved', 'confirmed', 'completed', 'completed_attended', 'accepted', 'candidate_accepted'];
    }

    private function is_completed_payable_booking_status($status) {
        $status = sanitize_key((string) $status);
        if ($status === '') {
            $status = 'approved';
        }
        if (in_array($status, ['declined', 'cancelled', 'candidate_declined', 'expired', 'no_show', 'noshow'], true)) {
            return false;
        }
        return in_array($status, $this->get_completed_payable_booking_statuses(), true);
    }

    private function normalize_booking_invoice_date_value($value) {
        $value = trim((string) $value);
        if ($value === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $value)) {
            return '';
        }
        return $value;
    }

    private function get_invoice_booking_date_window($booking_row) {
        $booking_row = is_array($booking_row) ? $booking_row : [];
        $start_date = $this->normalize_booking_invoice_date_value($booking_row['start_date'] ?? '');
        if ($start_date === '') {
            $start_date = $this->normalize_booking_invoice_date_value($booking_row['day_date'] ?? '');
        }
        if ($start_date === '') {
            return [];
        }
        $end_date = $this->normalize_booking_invoice_date_value($booking_row['end_date'] ?? '');
        if ($end_date === '') {
            $end_date = $start_date;
        }
        if (strtotime($end_date) < strtotime($start_date)) {
            $end_date = $start_date;
        }
        return [
            'start_date' => $start_date,
            'end_date' => $end_date,
        ];
    }

    private function expand_booking_dates_for_period($start_date, $end_date, $period_start, $period_end, $today) {
        $start_date = $this->normalize_booking_invoice_date_value($start_date);
        $end_date = $this->normalize_booking_invoice_date_value($end_date);
        $period_start = $this->normalize_invoice_date($period_start);
        $period_end = $this->normalize_invoice_date($period_end);
        $today = $this->normalize_invoice_date($today);
        if ($start_date === '' || $end_date === '' || $period_start === '' || $period_end === '' || $today === '') {
            return [];
        }
        $start_ts = strtotime($start_date);
        $end_ts = strtotime($end_date);
        $period_start_ts = strtotime($period_start);
        $period_end_ts = strtotime($period_end);
        $today_ts = strtotime($today);
        if ($start_ts === false || $end_ts === false || $period_start_ts === false || $period_end_ts === false || $today_ts === false) {
            return [];
        }
        $range_start = max($start_ts, $period_start_ts);
        $range_end = min($end_ts, $period_end_ts, $today_ts);
        if ($range_end < $range_start) {
            return [];
        }
        $dates = [];
        $cursor = $range_start;
        while ($cursor <= $range_end) {
            $dates[] = date('Y-m-d', $cursor);
            $next_cursor = strtotime('+1 day', $cursor);
            if ($next_cursor === false || $next_cursor <= $cursor) {
                break;
            }
            $cursor = $next_cursor;
        }
        return $dates;
    }

    private function get_invoice_booking_rows($school_id = 0) {
        global $wpdb;
        $school_id = (int) $school_id;
        $posts_table = $wpdb->posts;
        $meta_table = $wpdb->postmeta;
        $sql = "SELECT p.ID AS booking_id,
                       school_meta.meta_value AS school_id,
                       status_meta.meta_value AS booking_status,
                       start_meta.meta_value AS start_date,
                       day_meta.meta_value AS day_date,
                       end_meta.meta_value AS end_date,
                       role_meta.meta_value AS role_label,
                       candidate_meta.meta_value AS candidate_id
                FROM {$posts_table} p
                INNER JOIN {$meta_table} school_meta
                    ON school_meta.post_id = p.ID
                   AND school_meta.meta_key = 'cmn_school_id'
                LEFT JOIN {$meta_table} status_meta
                    ON status_meta.post_id = p.ID
                   AND status_meta.meta_key = 'cmn_status'
                LEFT JOIN {$meta_table} start_meta
                    ON start_meta.post_id = p.ID
                   AND start_meta.meta_key = 'cmn_start_date'
                LEFT JOIN {$meta_table} day_meta
                    ON day_meta.post_id = p.ID
                   AND day_meta.meta_key = 'cmn_date'
                LEFT JOIN {$meta_table} end_meta
                    ON end_meta.post_id = p.ID
                   AND end_meta.meta_key = 'cmn_end_date'
                LEFT JOIN {$meta_table} role_meta
                    ON role_meta.post_id = p.ID
                   AND role_meta.meta_key = 'cmn_role'
                LEFT JOIN {$meta_table} candidate_meta
                    ON candidate_meta.post_id = p.ID
                   AND candidate_meta.meta_key = 'cmn_candidate_id'
                WHERE p.post_type = 'cmn_booking'
                  AND p.post_status NOT IN ('trash', 'auto-draft')
                  AND school_meta.meta_value <> ''";
        if ($school_id > 0) {
            $sql .= $wpdb->prepare(' AND school_meta.meta_value = %s', (string) $school_id);
        }
        $rows = $wpdb->get_results($sql, ARRAY_A);
        if (!is_array($rows) || !$rows) {
            return [];
        }
        $normalized = [];
        foreach ($rows as $row) {
            $booking_id = (int) ($row['booking_id'] ?? 0);
            if ($booking_id < 1) {
                continue;
            }
            if (!isset($normalized[$booking_id])) {
                $normalized[$booking_id] = [
                    'booking_id' => $booking_id,
                    'school_id' => (string) ($row['school_id'] ?? ''),
                    'booking_status' => (string) ($row['booking_status'] ?? ''),
                    'start_date' => (string) ($row['start_date'] ?? ''),
                    'day_date' => (string) ($row['day_date'] ?? ''),
                    'end_date' => (string) ($row['end_date'] ?? ''),
                    'role_label' => (string) ($row['role_label'] ?? ''),
                    'candidate_id' => (string) ($row['candidate_id'] ?? ''),
                ];
                continue;
            }
            foreach (['school_id', 'booking_status', 'start_date', 'day_date', 'end_date', 'role_label', 'candidate_id'] as $field) {
                if (($normalized[$booking_id][$field] ?? '') === '' && !empty($row[$field])) {
                    $normalized[$booking_id][$field] = (string) $row[$field];
                }
            }
        }
        return array_values($normalized);
    }

    private function get_completed_payable_booking_days_for_month_period($period_start, $period_end, $school_id = 0) {
        $period_start = $this->normalize_invoice_date($period_start);
        $period_end = $this->normalize_invoice_date($period_end);
        $school_id = (int) $school_id;
        if ($period_start === '' || $period_end === '') {
            return ['days' => [], 'warnings' => []];
        }
        $today = current_time('Y-m-d');
        $rows = $this->get_invoice_booking_rows($school_id);
        $seen = [];
        $days = [];
        $warnings = [];
        foreach ((array) $rows as $row) {
            $booking_id = (int) ($row['booking_id'] ?? 0);
            $row_school_id = (int) ($row['school_id'] ?? 0);
            if ($booking_id < 1 || $row_school_id < 1) {
                continue;
            }
            $status = sanitize_key((string) ($row['booking_status'] ?? ''));
            if (!$this->is_completed_payable_booking_status($status)) {
                continue;
            }
            $date_window = $this->get_invoice_booking_date_window($row);
            if (!$date_window) {
                $warnings[] = [
                    'code' => 'missing_booking_date',
                    'school_id' => $row_school_id,
                    'booking_id' => $booking_id,
                ];
                continue;
            }
            $shift_dates = $this->expand_booking_dates_for_period(
                (string) ($date_window['start_date'] ?? ''),
                (string) ($date_window['end_date'] ?? ''),
                $period_start,
                $period_end,
                $today
            );
            if (!$shift_dates) {
                continue;
            }
            $candidate_id = (int) ($row['candidate_id'] ?? 0);
            $role_label = sanitize_text_field((string) ($row['role_label'] ?? ''));
            if ($role_label === '') {
                $role_label = 'Cover booking';
            }
            foreach ((array) $shift_dates as $shift_date) {
                $key = $row_school_id . '|' . $booking_id . '|' . $shift_date;
                if (isset($seen[$key])) {
                    continue;
                }
                $seen[$key] = true;
                $days[] = [
                    'school_id' => $row_school_id,
                    'booking_id' => $booking_id,
                    'candidate_id' => $candidate_id,
                    'shift_date' => (string) $shift_date,
                    'role_label' => $role_label,
                    'booking_status' => $status !== '' ? $status : 'approved',
                ];
            }
        }
        return [
            'days' => $days,
            'warnings' => $warnings,
        ];
    }

    private function get_booking_rate_rows_map($booking_ids) {
        $booking_ids = array_values(array_unique(array_filter(array_map('intval', (array) $booking_ids))));
        if (!$booking_ids) {
            return [];
        }
        global $wpdb;
        $table = $this->get_booking_rates_table();
        $placeholders = implode(',', array_fill(0, count($booking_ids), '%d'));
        $sql = "SELECT * FROM {$table} WHERE booking_id IN ({$placeholders})";
        $prepared = $wpdb->prepare($sql, ...$booking_ids);
        $rows = $wpdb->get_results($prepared, ARRAY_A);
        $map = [];
        foreach ((array) $rows as $row) {
            $booking_id = (int) ($row['booking_id'] ?? 0);
            if ($booking_id < 1) {
                continue;
            }
            $map[$booking_id] = is_array($row) ? $row : [];
        }
        return $map;
    }

    private function get_existing_invoice_for_school_period($school_id, $period_start, $period_end) {
        $school_id = (int) $school_id;
        $period_start = $this->normalize_invoice_date($period_start);
        $period_end = $this->normalize_invoice_date($period_end);
        if ($school_id < 1 || $period_start === '' || $period_end === '') {
            return [];
        }
        global $wpdb;
        $table = $this->get_invoices_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE school_id = %d
               AND period_start = %s
               AND period_end = %s
               AND status <> %s
             ORDER BY id DESC
             LIMIT 1",
            $school_id,
            $period_start,
            $period_end,
            'void'
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function get_existing_invoice_item_keys($invoice_id) {
        $invoice_id = (int) $invoice_id;
        if ($invoice_id < 1) {
            return [];
        }
        global $wpdb;
        $table = $this->get_invoice_items_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT booking_id, shift_date
             FROM {$table}
             WHERE invoice_id = %d",
            $invoice_id
        ), ARRAY_A);
        $keys = [];
        foreach ((array) $rows as $row) {
            $booking_id = (int) ($row['booking_id'] ?? 0);
            $shift_date = $this->normalize_invoice_date((string) ($row['shift_date'] ?? ''));
            if ($booking_id < 1 || $shift_date === '') {
                continue;
            }
            $keys[$booking_id . '|' . $shift_date] = true;
        }
        return $keys;
    }

    private function generate_invoice_number($school_id, $year, $month) {
        $school_id = (int) $school_id;
        $year = (int) $year;
        $month = (int) $month;
        $prefix = sprintf('CMN-%04d%02d-%d-', $year, $month, $school_id);
        global $wpdb;
        $table = $this->get_invoices_table();
        for ($attempt = 0; $attempt < 25; $attempt++) {
            $suffix = strtoupper(wp_generate_password(6, false, false));
            $candidate = substr($prefix . $suffix, 0, 80);
            $existing_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$table} WHERE invoice_number = %s LIMIT 1",
                $candidate
            ));
            if ($existing_id < 1) {
                return $candidate;
            }
        }
        return substr($prefix . strtoupper(uniqid()), 0, 80);
    }

    private function get_school_invoice_billing_snapshot($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return [
                'billing_email' => '',
                'billing_contact' => '',
                'billing_reference' => '',
                'invoice_email' => '',
                'missing_billing_email' => true,
            ];
        }
        $billing_email = sanitize_email((string) get_post_meta($school_id, 'cmn_billing_email', true));
        if ($billing_email !== '' && !is_email($billing_email)) {
            $billing_email = '';
        }
        $billing_contact = sanitize_text_field((string) get_post_meta($school_id, 'cmn_billing_contact', true));
        $billing_reference = sanitize_text_field((string) get_post_meta($school_id, 'cmn_billing_reference', true));
        $invoice_email = sanitize_email((string) get_post_meta($school_id, 'cmn_invoice_email', true));
        if ($invoice_email !== '' && !is_email($invoice_email)) {
            $invoice_email = '';
        }
        if ($invoice_email === '' && $billing_email !== '') {
            $invoice_email = $billing_email;
        }
        return [
            'billing_email' => $billing_email,
            'billing_contact' => $billing_contact,
            'billing_reference' => $billing_reference,
            'invoice_email' => $invoice_email,
            'missing_billing_email' => ($billing_email === '' && $invoice_email === ''),
        ];
    }

    private function log_invoice_generation_warning($school_id, $period_start, $period_end, $warning_code, $details = []) {
        $payload = is_array($details) ? $details : [];
        $payload['warning_code'] = sanitize_key((string) $warning_code);
        $payload['period_start'] = $this->normalize_invoice_date($period_start);
        $payload['period_end'] = $this->normalize_invoice_date($period_end);
        $this->add_audit_log(
            'invoice_generation_warning',
            'school',
            (string) ((int) $school_id),
            $payload
        );
    }

    private function format_partner_discount_percent_label($percent) {
        $percent = round((float) $percent, 2);
        $formatted = number_format($percent, 2, '.', '');
        $formatted = rtrim(rtrim($formatted, '0'), '.');
        return $formatted !== '' ? $formatted : '0';
    }

    private function get_partner_credit_adjustments_for_invoice($invoice_id) {
        $invoice_id = (int) $invoice_id;
        if ($invoice_id < 1) {
            return [];
        }
        global $wpdb;
        $table = $this->get_invoice_adjustments_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE invoice_id = %d
               AND type = %s
             ORDER BY id ASC",
            $invoice_id,
            'partner_credit'
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function remove_partner_credit_adjustments_for_invoice($invoice_id, $keep_adjustment_id = 0) {
        $invoice_id = (int) $invoice_id;
        $keep_adjustment_id = (int) $keep_adjustment_id;
        if ($invoice_id < 1) {
            return 0;
        }
        global $wpdb;
        $table = $this->get_invoice_adjustments_table();
        if ($keep_adjustment_id > 0) {
            $deleted = $wpdb->query($wpdb->prepare(
                "DELETE FROM {$table}
                 WHERE invoice_id = %d
                   AND type = %s
                   AND id <> %d",
                $invoice_id,
                'partner_credit',
                $keep_adjustment_id
            ));
            return $deleted === false ? 0 : (int) $deleted;
        }
        $deleted = $wpdb->query($wpdb->prepare(
            "DELETE FROM {$table}
             WHERE invoice_id = %d
               AND type = %s",
            $invoice_id,
            'partner_credit'
        ));
        return $deleted === false ? 0 : (int) $deleted;
    }

    private function apply_partner_credit_adjustment_to_invoice($invoice_id, $school_id, $options = []) {
        $invoice_id = (int) $invoice_id;
        $school_id = (int) $school_id;
        $options = is_array($options) ? $options : [];
        if ($invoice_id < 1 || $school_id < 1) {
            return new WP_Error('cmn_partner_credit_invalid_context', 'Invalid invoice/school for partner credit.');
        }

        $invoice = $this->get_invoice_by_id($invoice_id);
        if (!$invoice) {
            return new WP_Error('cmn_partner_credit_invoice_missing', 'Invoice not found.');
        }
        $status = $this->normalize_invoice_status((string) ($invoice['status'] ?? 'draft'));
        if ($this->is_invoice_content_locked($status)) {
            return [
                'mode' => 'skipped_locked',
                'applied' => false,
                'credit_amount' => 0.00,
                'amount' => 0.00,
                'tier' => '',
                'discount_percent' => 0.00,
                'lifetime_credits' => 0,
                'adjustment_id' => 0,
                'totals' => [
                    'invoice_id' => $invoice_id,
                    'subtotal' => round((float) ($invoice['subtotal'] ?? 0), 2),
                    'adjustments_total' => round((float) ($invoice['adjustments_total'] ?? 0), 2),
                    'vat_total' => round((float) ($invoice['vat_total'] ?? 0), 2),
                    'total' => round((float) ($invoice['total'] ?? 0), 2),
                ],
                'warning_code' => 'invoice_locked',
                'warning_details' => [
                    'invoice_id' => $invoice_id,
                    'school_id' => $school_id,
                    'status' => $status,
                ],
            ];
        }

        $current_totals = $this->recalculate_invoice_totals($invoice_id);
        if (is_wp_error($current_totals)) {
            return $current_totals;
        }
        $subtotal = round((float) ($current_totals['subtotal'] ?? 0), 2);
        $existing_rows = $this->get_partner_credit_adjustments_for_invoice($invoice_id);

        if ($subtotal <= 0) {
            $deleted = $this->remove_partner_credit_adjustments_for_invoice($invoice_id, 0);
            $final_totals = $deleted > 0 ? $this->recalculate_invoice_totals($invoice_id) : $current_totals;
            if (is_wp_error($final_totals)) {
                return $final_totals;
            }
            $savings_sync_warning = '';
            if ($deleted > 0) {
                $savings_sync = $this->recalculate_school_partner_savings($school_id, [
                    'source' => 'partner_credit_removed_zero_subtotal',
                    'invoice_id' => $invoice_id,
                ]);
                if (is_wp_error($savings_sync)) {
                    $savings_sync_warning = $savings_sync->get_error_message();
                    $this->add_audit_log('invoice_partner_savings_sync_failed', 'invoice', (string) $invoice_id, [
                        'school_id' => $school_id,
                        'message' => $savings_sync_warning,
                        'source' => 'partner_credit_removed_zero_subtotal',
                    ], (int) ($options['actor_user_id'] ?? 0));
                }
            }
            return [
                'mode' => $deleted > 0 ? 'removed' : 'skipped_zero_subtotal',
                'applied' => false,
                'credit_amount' => 0.00,
                'amount' => 0.00,
                'tier' => '',
                'discount_percent' => 0.00,
                'lifetime_credits' => 0,
                'adjustment_id' => 0,
                'totals' => $final_totals,
                'warning_code' => '',
                'warning_details' => [],
                'savings_sync_warning' => $savings_sync_warning,
            ];
        }

        $partner = $this->get_school_partner_record($school_id);
        if (!$partner) {
            $deleted = $this->remove_partner_credit_adjustments_for_invoice($invoice_id, 0);
            $final_totals = $deleted > 0 ? $this->recalculate_invoice_totals($invoice_id) : $current_totals;
            if (is_wp_error($final_totals)) {
                return $final_totals;
            }
            $savings_sync_warning = '';
            if ($deleted > 0) {
                $savings_sync = $this->recalculate_school_partner_savings($school_id, [
                    'source' => 'partner_credit_removed_missing_partner',
                    'invoice_id' => $invoice_id,
                ]);
                if (is_wp_error($savings_sync)) {
                    $savings_sync_warning = $savings_sync->get_error_message();
                    $this->add_audit_log('invoice_partner_savings_sync_failed', 'invoice', (string) $invoice_id, [
                        'school_id' => $school_id,
                        'message' => $savings_sync_warning,
                        'source' => 'partner_credit_removed_missing_partner',
                    ], (int) ($options['actor_user_id'] ?? 0));
                }
            }
            return [
                'mode' => $deleted > 0 ? 'removed' : 'skipped_missing_partner',
                'applied' => false,
                'credit_amount' => 0.00,
                'amount' => 0.00,
                'tier' => '',
                'discount_percent' => 0.00,
                'lifetime_credits' => 0,
                'adjustment_id' => 0,
                'totals' => $final_totals,
                'warning_code' => 'missing_partner_record',
                'warning_details' => [
                    'invoice_id' => $invoice_id,
                    'school_id' => $school_id,
                ],
                'savings_sync_warning' => $savings_sync_warning,
            ];
        }

        $tier = $this->normalize_school_partner_tier((string) ($partner['tier'] ?? 'standard'));
        $discount_percent = round((float) ($partner['discount_percent'] ?? 0.00), 2);
        $lifetime_credits = max(0, (int) ($partner['lifetime_credits'] ?? 0));
        if ($discount_percent <= 0) {
            $deleted = $this->remove_partner_credit_adjustments_for_invoice($invoice_id, 0);
            $final_totals = $deleted > 0 ? $this->recalculate_invoice_totals($invoice_id) : $current_totals;
            if (is_wp_error($final_totals)) {
                return $final_totals;
            }
            $savings_sync_warning = '';
            if ($deleted > 0) {
                $savings_sync = $this->recalculate_school_partner_savings($school_id, [
                    'source' => 'partner_credit_removed_no_discount',
                    'invoice_id' => $invoice_id,
                ]);
                if (is_wp_error($savings_sync)) {
                    $savings_sync_warning = $savings_sync->get_error_message();
                    $this->add_audit_log('invoice_partner_savings_sync_failed', 'invoice', (string) $invoice_id, [
                        'school_id' => $school_id,
                        'message' => $savings_sync_warning,
                        'source' => 'partner_credit_removed_no_discount',
                    ], (int) ($options['actor_user_id'] ?? 0));
                }
            }
            return [
                'mode' => $deleted > 0 ? 'removed' : 'skipped_no_discount',
                'applied' => false,
                'credit_amount' => 0.00,
                'amount' => 0.00,
                'tier' => $tier,
                'discount_percent' => $discount_percent,
                'lifetime_credits' => $lifetime_credits,
                'adjustment_id' => 0,
                'totals' => $final_totals,
                'warning_code' => '',
                'warning_details' => [],
                'savings_sync_warning' => $savings_sync_warning,
            ];
        }

        $credit_amount = round($subtotal * ($discount_percent / 100), 2);
        if ($credit_amount > $subtotal) {
            $credit_amount = $subtotal;
        }
        if ($credit_amount <= 0) {
            $deleted = $this->remove_partner_credit_adjustments_for_invoice($invoice_id, 0);
            $final_totals = $deleted > 0 ? $this->recalculate_invoice_totals($invoice_id) : $current_totals;
            if (is_wp_error($final_totals)) {
                return $final_totals;
            }
            $savings_sync_warning = '';
            if ($deleted > 0) {
                $savings_sync = $this->recalculate_school_partner_savings($school_id, [
                    'source' => 'partner_credit_removed_no_credit_amount',
                    'invoice_id' => $invoice_id,
                ]);
                if (is_wp_error($savings_sync)) {
                    $savings_sync_warning = $savings_sync->get_error_message();
                    $this->add_audit_log('invoice_partner_savings_sync_failed', 'invoice', (string) $invoice_id, [
                        'school_id' => $school_id,
                        'message' => $savings_sync_warning,
                        'source' => 'partner_credit_removed_no_credit_amount',
                    ], (int) ($options['actor_user_id'] ?? 0));
                }
            }
            return [
                'mode' => $deleted > 0 ? 'removed' : 'skipped_no_discount',
                'applied' => false,
                'credit_amount' => 0.00,
                'amount' => 0.00,
                'tier' => $tier,
                'discount_percent' => $discount_percent,
                'lifetime_credits' => $lifetime_credits,
                'adjustment_id' => 0,
                'totals' => $final_totals,
                'warning_code' => '',
                'warning_details' => [],
                'savings_sync_warning' => $savings_sync_warning,
            ];
        }

        $amount = round(-$credit_amount, 2);
        $tier_label = ucfirst($tier);
        $label = 'CMN Partner Programme Credit (' . $tier_label . ' ' . $this->format_partner_discount_percent_label($discount_percent) . '%)';
        $reason_payload = [
            'snapshot_type' => 'partner_credit',
            'tier' => $tier,
            'discount_percent' => $discount_percent,
            'lifetime_credits' => $lifetime_credits,
            'subtotal' => $subtotal,
            'credit_amount' => $credit_amount,
            'generated_at' => current_time('mysql'),
            'month_key' => sanitize_text_field((string) ($options['month_key'] ?? '')),
        ];
        $reason = wp_json_encode($reason_payload);
        $actor_user_id = (int) ($options['actor_user_id'] ?? get_current_user_id());
        if ($actor_user_id < 1) {
            $actor_user_id = 0;
        }

        global $wpdb;
        $table = $this->get_invoice_adjustments_table();
        $has_transaction = $this->begin_invoice_transaction();
        $success = false;
        $mode = 'updated';
        $adjustment_id = 0;
        $totals = null;
        try {
            if (!empty($existing_rows)) {
                $primary = (array) $existing_rows[0];
                $adjustment_id = (int) ($primary['id'] ?? 0);
                if ($adjustment_id < 1) {
                    throw new Exception('invalid_adjustment');
                }
                $updated = $wpdb->query($wpdb->prepare(
                    "UPDATE {$table}
                     SET label = %s,
                         amount = %f,
                         reason = NULLIF(%s, '')
                     WHERE id = %d",
                    $label,
                    $amount,
                    (string) $reason,
                    $adjustment_id
                ));
                if ($updated === false) {
                    throw new Exception('partner_credit_update_failed');
                }
                $this->remove_partner_credit_adjustments_for_invoice($invoice_id, $adjustment_id);
                $mode = 'updated';
            } else {
                $inserted = $wpdb->query($wpdb->prepare(
                    "INSERT INTO {$table}
                    (invoice_id, type, label, amount, created_by_user_id, reason, created_at)
                    VALUES
                    (%d, %s, %s, %f, NULLIF(%d, 0), NULLIF(%s, ''), %s)",
                    $invoice_id,
                    'partner_credit',
                    $label,
                    $amount,
                    $actor_user_id,
                    (string) $reason,
                    current_time('mysql')
                ));
                if ($inserted === false) {
                    throw new Exception('partner_credit_insert_failed');
                }
                $adjustment_id = (int) $wpdb->insert_id;
                if ($adjustment_id < 1) {
                    throw new Exception('partner_credit_insert_id_missing');
                }
                $mode = 'created';
            }
            $totals = $this->recalculate_invoice_totals($invoice_id);
            if (is_wp_error($totals)) {
                throw new Exception('partner_credit_recalc_failed');
            }
            $success = true;
        } catch (Exception $e) {
            $success = false;
        }
        $this->finish_invoice_transaction($has_transaction, $success);
        if (!$success) {
            return new WP_Error('cmn_partner_credit_apply_failed', 'Failed to apply partner credit.');
        }

        $this->add_audit_log('invoice_partner_credit_applied', 'invoice', (string) $invoice_id, [
            'school_id' => $school_id,
            'tier' => $tier,
            'discount_percent' => $discount_percent,
            'credit_amount' => $credit_amount,
            'amount' => $amount,
            'mode' => $mode,
            'adjustment_id' => $adjustment_id,
        ], $actor_user_id);
        $this->log_invoice_audit_event($invoice_id, 'partner_credit_updated', [
            'invoice' => $invoice,
            'amount_delta' => $amount,
            'user_id' => $actor_user_id,
            'note' => sprintf(
                'Partner credit %s (%s %s%%).',
                $mode,
                ucfirst($tier),
                $this->format_partner_discount_percent_label($discount_percent)
            ),
        ]);

        $savings_sync_warning = '';
        $partner_stats = [];
        $savings_sync = $this->recalculate_school_partner_savings($school_id, [
            'source' => 'partner_credit_applied',
            'invoice_id' => $invoice_id,
        ]);
        if (is_wp_error($savings_sync)) {
            $savings_sync_warning = $savings_sync->get_error_message();
            $this->add_audit_log('invoice_partner_savings_sync_failed', 'invoice', (string) $invoice_id, [
                'school_id' => $school_id,
                'message' => $savings_sync_warning,
                'source' => 'partner_credit_applied',
            ], $actor_user_id);
        } else {
            $partner_stats = is_array($savings_sync['partner'] ?? null) ? (array) $savings_sync['partner'] : [];
        }

        return [
            'mode' => $mode,
            'applied' => true,
            'credit_amount' => $credit_amount,
            'amount' => $amount,
            'tier' => $tier,
            'discount_percent' => $discount_percent,
            'lifetime_credits' => $lifetime_credits,
            'adjustment_id' => $adjustment_id,
            'totals' => $totals,
            'warning_code' => '',
            'warning_details' => [],
            'lifetime_savings' => round((float) ($partner_stats['lifetime_savings'] ?? 0), 2),
            'academic_year_savings' => round((float) ($partner_stats['academic_year_savings'] ?? 0), 2),
            'savings_sync_warning' => $savings_sync_warning,
        ];
    }

    public function generate_invoices_for_month($year, $month, $options = []) {
        $options = is_array($options) ? $options : [];
        $actor_user_id = (int) ($options['actor_user_id'] ?? get_current_user_id());
        $skip_permission_check = !empty($options['skip_permission_check']) || !empty($options['permission_validated']);
        if (!$skip_permission_check && !$this->can_modify_invoice_records($actor_user_id)) {
            return new WP_Error('cmn_invoice_forbidden', 'Only admin/staff can run invoice generation.');
        }
        $bounds = $this->get_invoice_month_bounds($year, $month);
        if (!$bounds) {
            return new WP_Error('cmn_invoice_invalid_month', 'Invalid invoice month.');
        }
        $period_start = (string) ($bounds['period_start'] ?? '');
        $period_end = (string) ($bounds['period_end'] ?? '');
        $month_key = (string) ($bounds['month_key'] ?? '');

        $payable_days_payload = $this->get_completed_payable_booking_days_for_month_period($period_start, $period_end, 0);
        $payable_days = (array) ($payable_days_payload['days'] ?? []);
        $warnings = (array) ($payable_days_payload['warnings'] ?? []);
        $days_by_school = [];
        foreach ($payable_days as $day_row) {
            $school_id = (int) ($day_row['school_id'] ?? 0);
            if ($school_id < 1) {
                continue;
            }
            if (!isset($days_by_school[$school_id])) {
                $days_by_school[$school_id] = [];
            }
            $days_by_school[$school_id][] = $day_row;
        }

        $result = [
            'year' => (int) ($bounds['year'] ?? 0),
            'month' => (int) ($bounds['month'] ?? 0),
            'month_key' => $month_key,
            'period_start' => $period_start,
            'period_end' => $period_end,
            'schools_total' => (int) count($days_by_school),
            'invoices_created' => 0,
            'invoices_touched' => 0,
            'items_added' => 0,
            'warnings_count' => (int) count($warnings),
            'school_results' => [],
        ];

        foreach ($warnings as $warning_row) {
            $this->log_invoice_generation_warning(
                (int) ($warning_row['school_id'] ?? 0),
                $period_start,
                $period_end,
                (string) ($warning_row['code'] ?? 'invoice_generation_warning'),
                $warning_row
            );
        }

        ksort($days_by_school);
        foreach ($days_by_school as $school_id => $school_days) {
            $school_result = $this->generate_invoice_for_school_month((int) $school_id, (int) ($bounds['year'] ?? 0), (int) ($bounds['month'] ?? 0), [
                'actor_user_id' => $actor_user_id,
                'skip_permission_check' => true,
                'precomputed_days' => $school_days,
            ]);
            if (is_wp_error($school_result)) {
                $result['warnings_count']++;
                $this->log_invoice_generation_warning((int) $school_id, $period_start, $period_end, 'school_generation_failed', [
                    'message' => $school_result->get_error_message(),
                ]);
                continue;
            }
            $result['school_results'][] = $school_result;
            $result['items_added'] += (int) ($school_result['items_added'] ?? 0);
            $result['warnings_count'] += (int) ($school_result['warnings_count'] ?? 0);
            if (!empty($school_result['invoice_id'])) {
                $result['invoices_touched']++;
            }
            if (!empty($school_result['created_invoice'])) {
                $result['invoices_created']++;
            }
        }

        $this->add_audit_log('invoice_generation_month', 'invoice_period', $month_key, [
            'period_start' => $period_start,
            'period_end' => $period_end,
            'schools_total' => $result['schools_total'],
            'invoices_created' => $result['invoices_created'],
            'invoices_touched' => $result['invoices_touched'],
            'items_added' => $result['items_added'],
            'warnings_count' => $result['warnings_count'],
        ], $actor_user_id);

        return $result;
    }

    public function generate_invoice_for_school_month($school_id, $year, $month, $options = []) {
        $school_id = (int) $school_id;
        $options = is_array($options) ? $options : [];
        $actor_user_id = (int) ($options['actor_user_id'] ?? get_current_user_id());
        $skip_permission_check = !empty($options['skip_permission_check']) || !empty($options['permission_validated']);
        if (!$skip_permission_check && !$this->can_modify_invoice_records($actor_user_id)) {
            return new WP_Error('cmn_invoice_forbidden', 'Only admin/staff can generate invoices.');
        }
        $bounds = $this->get_invoice_month_bounds($year, $month);
        if ($school_id < 1 || !$bounds) {
            return new WP_Error('cmn_invoice_invalid_input', 'Invalid school/month for invoice generation.');
        }
        $period_start = (string) ($bounds['period_start'] ?? '');
        $period_end = (string) ($bounds['period_end'] ?? '');
        $month_key = (string) ($bounds['month_key'] ?? '');

        $warnings = [];
        $days = [];
        if (!empty($options['precomputed_days']) && is_array($options['precomputed_days'])) {
            $days = array_values((array) $options['precomputed_days']);
        } else {
            $payable_days_payload = $this->get_completed_payable_booking_days_for_month_period($period_start, $period_end, $school_id);
            $days = (array) ($payable_days_payload['days'] ?? []);
            $warnings = (array) ($payable_days_payload['warnings'] ?? []);
        }
        if (!$days) {
            $this->add_audit_log('invoice_generation_school_skipped', 'school', (string) $school_id, [
                'month_key' => $month_key,
                'reason' => 'no_completed_payable_days',
                'period_start' => $period_start,
                'period_end' => $period_end,
            ], $actor_user_id);
            return [
                'school_id' => $school_id,
                'month_key' => $month_key,
                'period_start' => $period_start,
                'period_end' => $period_end,
                'invoice_id' => 0,
                'created_invoice' => false,
                'items_added' => 0,
                'warnings_count' => 0,
                'warnings' => [],
            ];
        }

        $partner_credit_summary = $this->award_school_partner_credits_for_day_rows($days, [
            'source' => 'invoice_generation',
            'month_key' => $month_key,
        ]);
        if ((int) ($partner_credit_summary['errors'] ?? 0) > 0) {
            $warnings[] = [
                'code' => 'partner_credit_award_errors',
                'school_id' => $school_id,
                'errors' => (int) ($partner_credit_summary['errors'] ?? 0),
            ];
        }

        $invoice_row = $this->get_existing_invoice_for_school_period($school_id, $period_start, $period_end);
        $created_invoice = false;
        if (!$invoice_row) {
            $billing_snapshot = $this->get_school_invoice_billing_snapshot($school_id);
            if (!empty($billing_snapshot['missing_billing_email'])) {
                $warning = [
                    'code' => 'missing_billing_email',
                    'school_id' => $school_id,
                ];
                $warnings[] = $warning;
                $this->log_invoice_generation_warning($school_id, $period_start, $period_end, 'missing_billing_email', $warning);
            }
            $invoice_id = (int) $this->insert_invoice([
                'school_id' => $school_id,
                'invoice_number' => $this->generate_invoice_number($school_id, (int) ($bounds['year'] ?? 0), (int) ($bounds['month'] ?? 0)),
                'period_start' => $period_start,
                'period_end' => $period_end,
                'status' => 'draft',
                'currency' => 'GBP',
                'billing_email' => (string) ($billing_snapshot['billing_email'] ?? ''),
                'billing_contact' => (string) ($billing_snapshot['billing_contact'] ?? ''),
                'billing_reference' => (string) ($billing_snapshot['billing_reference'] ?? ''),
                'invoice_email' => (string) ($billing_snapshot['invoice_email'] ?? ''),
            ]);
            if ($invoice_id < 1) {
                return new WP_Error('cmn_invoice_create_failed', 'Unable to create invoice record.');
            }
            $invoice_row = $this->get_invoice_by_id($invoice_id);
            $created_invoice = true;
        }

        $invoice_id = (int) ($invoice_row['id'] ?? 0);
        if ($invoice_id < 1) {
            return new WP_Error('cmn_invoice_not_found', 'Invoice record unavailable.');
        }
        $invoice_status = $this->normalize_invoice_status((string) ($invoice_row['status'] ?? 'draft'));
        if ($this->is_invoice_content_locked($invoice_status)) {
            $this->add_audit_log('invoice_generation_school_skipped', 'invoice', (string) $invoice_id, [
                'school_id' => $school_id,
                'month_key' => $month_key,
                'reason' => 'invoice_locked',
                'status' => $invoice_status,
            ], $actor_user_id);
            return [
                'school_id' => $school_id,
                'month_key' => $month_key,
                'period_start' => $period_start,
                'period_end' => $period_end,
                'invoice_id' => $invoice_id,
                'created_invoice' => $created_invoice,
                'items_added' => 0,
                'warnings_count' => (int) count($warnings),
                'warnings' => $warnings,
            ];
        }

        $existing_item_keys = $this->get_existing_invoice_item_keys($invoice_id);
        $booking_ids = [];
        foreach ($days as $day_row) {
            $booking_id = (int) ($day_row['booking_id'] ?? 0);
            if ($booking_id > 0) {
                $booking_ids[] = $booking_id;
            }
        }
        $rate_map = $this->get_booking_rate_rows_map($booking_ids);
        $items_added = 0;
        $skipped_existing = 0;
        $skipped_missing_rate = 0;
        $item_errors = 0;

        foreach ($days as $day_row) {
            $booking_id = (int) ($day_row['booking_id'] ?? 0);
            $shift_date = $this->normalize_invoice_date((string) ($day_row['shift_date'] ?? ''));
            if ($booking_id < 1 || $shift_date === '') {
                continue;
            }
            $item_key = $booking_id . '|' . $shift_date;
            if (isset($existing_item_keys[$item_key])) {
                $skipped_existing++;
                continue;
            }
            $rate_row = isset($rate_map[$booking_id]) && is_array($rate_map[$booking_id]) ? $rate_map[$booking_id] : [];
            $unit_price = round((float) ($rate_row['school_charge_rate'] ?? 0), 2);
            if (!$rate_row || $unit_price <= 0) {
                $skipped_missing_rate++;
                $warning = [
                    'code' => 'missing_booking_rate',
                    'school_id' => $school_id,
                    'invoice_id' => $invoice_id,
                    'booking_id' => $booking_id,
                    'shift_date' => $shift_date,
                ];
                $warnings[] = $warning;
                $this->log_invoice_generation_warning($school_id, $period_start, $period_end, 'missing_booking_rate', $warning);
                continue;
            }
            $role_label = sanitize_text_field((string) ($day_row['role_label'] ?? ''));
            if ($role_label === '') {
                $role_label = 'Cover booking';
            }
            $candidate_id = (int) ($day_row['candidate_id'] ?? 0);
            $insert_result = $this->add_invoice_item([
                'invoice_id' => $invoice_id,
                'booking_id' => $booking_id,
                'shift_date' => $shift_date,
                'role_label' => $role_label,
                'qty' => 1,
                'unit_price' => $unit_price,
                'candidate_id' => $candidate_id,
            ], [
                'skip_permission_check' => true,
                'actor_user_id' => $actor_user_id,
            ]);
            if (is_wp_error($insert_result)) {
                $item_errors++;
                $warning = [
                    'code' => 'item_insert_failed',
                    'school_id' => $school_id,
                    'invoice_id' => $invoice_id,
                    'booking_id' => $booking_id,
                    'shift_date' => $shift_date,
                    'message' => $insert_result->get_error_message(),
                ];
                $warnings[] = $warning;
                $this->log_invoice_generation_warning($school_id, $period_start, $period_end, 'item_insert_failed', $warning);
                continue;
            }
            $existing_item_keys[$item_key] = true;
            $items_added++;
        }

        $totals = $this->recalculate_invoice_totals($invoice_id);
        if (is_wp_error($totals)) {
            return new WP_Error('cmn_invoice_recalc_failed', 'Failed to recalculate invoice totals.');
        }
        $partner_credit_result = $this->apply_partner_credit_adjustment_to_invoice($invoice_id, $school_id, [
            'actor_user_id' => $actor_user_id,
            'month_key' => $month_key,
        ]);
        if (is_wp_error($partner_credit_result)) {
            return new WP_Error('cmn_partner_credit_apply_failed', 'Failed to apply partner credit adjustment.');
        }
        if (!empty($partner_credit_result['warning_code'])) {
            $partner_warning = is_array($partner_credit_result['warning_details'] ?? null)
                ? (array) $partner_credit_result['warning_details']
                : [];
            $partner_warning['code'] = (string) $partner_credit_result['warning_code'];
            $partner_warning['invoice_id'] = $invoice_id;
            $partner_warning['school_id'] = $school_id;
            $warnings[] = $partner_warning;
            if ((string) $partner_credit_result['warning_code'] === 'missing_partner_record') {
                $this->log_invoice_generation_warning($school_id, $period_start, $period_end, 'missing_partner_record', $partner_warning);
            }
        }
        if (!empty($partner_credit_result['savings_sync_warning'])) {
            $warnings[] = [
                'code' => 'partner_savings_sync_failed',
                'school_id' => $school_id,
                'invoice_id' => $invoice_id,
                'message' => sanitize_text_field((string) $partner_credit_result['savings_sync_warning']),
            ];
            $this->log_invoice_generation_warning($school_id, $period_start, $period_end, 'partner_savings_sync_failed', [
                'school_id' => $school_id,
                'invoice_id' => $invoice_id,
                'message' => sanitize_text_field((string) $partner_credit_result['savings_sync_warning']),
            ]);
        }
        if (!empty($partner_credit_result['totals']) && is_array($partner_credit_result['totals'])) {
            $totals = (array) $partner_credit_result['totals'];
        }

        foreach ($warnings as $warning_row) {
            if (!is_array($warning_row) || empty($warning_row['code'])) {
                continue;
            }
            if (($warning_row['code'] ?? '') === 'missing_booking_date') {
                $this->log_invoice_generation_warning(
                    (int) ($warning_row['school_id'] ?? $school_id),
                    $period_start,
                    $period_end,
                    'missing_booking_date',
                    $warning_row
                );
            }
        }

        $result = [
            'school_id' => $school_id,
            'month_key' => $month_key,
            'period_start' => $period_start,
            'period_end' => $period_end,
            'invoice_id' => $invoice_id,
            'created_invoice' => $created_invoice,
            'items_added' => $items_added,
            'skipped_existing' => $skipped_existing,
            'skipped_missing_rate' => $skipped_missing_rate,
            'item_errors' => $item_errors,
            'partner_credits_awarded' => (int) ($partner_credit_summary['awarded'] ?? 0),
            'partner_credits_duplicates' => (int) ($partner_credit_summary['duplicates'] ?? 0),
            'partner_credit_errors' => (int) ($partner_credit_summary['errors'] ?? 0),
            'partner_credit_mode' => (string) ($partner_credit_result['mode'] ?? ''),
            'partner_credit_applied' => !empty($partner_credit_result['applied']) ? 1 : 0,
            'partner_credit_tier' => (string) ($partner_credit_result['tier'] ?? ''),
            'partner_credit_percent' => round((float) ($partner_credit_result['discount_percent'] ?? 0), 2),
            'partner_credit_amount' => round((float) ($partner_credit_result['credit_amount'] ?? 0), 2),
            'partner_lifetime_savings' => round((float) ($partner_credit_result['lifetime_savings'] ?? 0), 2),
            'partner_academic_year_savings' => round((float) ($partner_credit_result['academic_year_savings'] ?? 0), 2),
            'warnings_count' => (int) count($warnings),
            'warnings' => $warnings,
            'total' => (float) ($totals['total'] ?? 0),
        ];

        $this->add_audit_log('invoice_generation_school', 'invoice', (string) $invoice_id, [
            'school_id' => $school_id,
            'month_key' => $month_key,
            'period_start' => $period_start,
            'period_end' => $period_end,
            'created_invoice' => $created_invoice ? 1 : 0,
            'items_added' => $items_added,
            'skipped_existing' => $skipped_existing,
            'skipped_missing_rate' => $skipped_missing_rate,
            'item_errors' => $item_errors,
            'partner_credits_awarded' => (int) ($partner_credit_summary['awarded'] ?? 0),
            'partner_credits_duplicates' => (int) ($partner_credit_summary['duplicates'] ?? 0),
            'partner_credit_errors' => (int) ($partner_credit_summary['errors'] ?? 0),
            'partner_credit_mode' => (string) ($partner_credit_result['mode'] ?? ''),
            'partner_credit_applied' => !empty($partner_credit_result['applied']) ? 1 : 0,
            'partner_credit_tier' => (string) ($partner_credit_result['tier'] ?? ''),
            'partner_credit_percent' => round((float) ($partner_credit_result['discount_percent'] ?? 0), 2),
            'partner_credit_amount' => round((float) ($partner_credit_result['credit_amount'] ?? 0), 2),
            'partner_lifetime_savings' => round((float) ($partner_credit_result['lifetime_savings'] ?? 0), 2),
            'partner_academic_year_savings' => round((float) ($partner_credit_result['academic_year_savings'] ?? 0), 2),
            'warnings_count' => (int) count($warnings),
        ], $actor_user_id);

        return $result;
    }

    private function get_feedback_insights_engine() {
        if ($this->feedback_insights instanceof CmnFeedbackInsights) {
            return $this->feedback_insights;
        }
        global $wpdb;
        $this->feedback_insights = new CmnFeedbackInsights($wpdb, $this->get_feedback_table());
        return $this->feedback_insights;
    }

    private function get_rate_engine() {
        if ($this->rate_engine instanceof CmnRateEngine) {
            return $this->rate_engine;
        }
        $this->rate_engine = new CmnRateEngine(function ($role_key, $region_key) {
            return $this->fetch_applicable_rate_rule($role_key, $region_key);
        });
        return $this->rate_engine;
    }

    private function get_vetting_engine() {
        if ($this->vetting_engine instanceof CmnVettingEngine) {
            return $this->vetting_engine;
        }
        $this->vetting_engine = new CmnVettingEngine();
        return $this->vetting_engine;
    }

    private function normalize_rate_role_key($value) {
        $value = strtolower(trim((string) $value));
        if ($value === '') {
            return 'default';
        }
        $value = preg_replace('/[^a-z0-9]+/', '_', $value);
        $value = trim((string) $value, '_');
        return $value !== '' ? $value : 'default';
    }

    private function normalize_rate_region_key($value) {
        $value = strtolower(trim((string) $value));
        if ($value === '') {
            return 'default';
        }
        $value = preg_replace('/[^a-z0-9]+/', '_', $value);
        $value = trim((string) $value, '_');
        return $value !== '' ? $value : 'default';
    }

    private function resolve_rate_context($candidate_id = 0, $school_id = 0, $request = [], $booking_id = 0) {
        $role_value = '';
        if (!empty($request['role_key'])) {
            $role_value = (string) $request['role_key'];
        }
        if ($role_value === '' && $booking_id > 0) {
            $role_value = (string) get_post_meta((int) $booking_id, 'cmn_role', true);
        }
        if ($role_value === '' && $candidate_id > 0) {
            $roles = get_post_meta((int) $candidate_id, 'cmn_roles', true);
            if (is_array($roles) && !empty($roles[0])) {
                $role_value = (string) $roles[0];
            } elseif (is_string($roles)) {
                $role_value = $roles;
            }
        }
        if ($role_value === '') {
            $role_value = 'default';
        }

        $region_value = '';
        if (!empty($request['region_key'])) {
            $region_value = (string) $request['region_key'];
        }
        if ($region_value === '' && $school_id > 0) {
            $region_value = (string) get_post_meta((int) $school_id, 'cmn_location', true);
        }
        if ($region_value === '' && $booking_id > 0) {
            $region_value = (string) get_post_meta((int) $booking_id, 'cmn_location', true);
        }

        return [
            'role_key' => $this->normalize_rate_role_key($role_value),
            'region_key' => $this->normalize_rate_region_key($region_value),
        ];
    }

    private function fetch_applicable_rate_rule($role_key, $region_key) {
        global $wpdb;
        $table = $this->get_rate_rules_table();
        $role_key = $this->normalize_rate_role_key($role_key);
        $region_key = $this->normalize_rate_region_key($region_key);
        $now = current_time('mysql');
        $candidates = [
            [$role_key, $region_key],
            [$role_key, 'default'],
            ['default', $region_key],
            ['default', 'default'],
        ];
        foreach ($candidates as $candidate) {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM {$table}
                 WHERE role_key = %s
                   AND region_key = %s
                   AND status = 'active'
                   AND (effective_from IS NULL OR effective_from = '' OR effective_from <= %s)
                 ORDER BY effective_from DESC, id DESC
                 LIMIT 1",
                (string) $candidate[0],
                (string) $candidate[1],
                $now
            ), ARRAY_A);
            if (!empty($row)) {
                return $row;
            }
        }
        return [];
    }

    private function get_suggested_rates_for_context($role_key, $region_key) {
        return $this->get_rate_engine()->suggest_default_rates($role_key, $region_key);
    }

    private function get_rate_validation_payload($school_rate, $candidate_pay, $role_key, $region_key) {
        $engine = $this->get_rate_engine();
        $rule = $engine->get_applicable_rule($role_key, $region_key);
        $validation = $engine->validate_rates($school_rate, $candidate_pay, $rule);
        $validation['rule'] = $rule;
        $validation['role_key'] = $role_key;
        $validation['region_key'] = $region_key;
        return $validation;
    }

    private function get_booking_rate_row($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return [];
        }
        global $wpdb;
        $table = $this->get_booking_rates_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE booking_id = %d LIMIT 1",
            $booking_id
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function log_rate_audit($booking_id, $old_state, $new_state, $reason = '') {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return;
        }
        global $wpdb;
        $table = $this->get_rate_audit_table();
        $wpdb->insert($table, [
            'booking_id' => $booking_id,
            'changed_by' => get_current_user_id() ?: null,
            'changed_at' => current_time('mysql'),
            'old_json' => !empty($old_state) ? wp_json_encode($old_state) : null,
            'new_json' => !empty($new_state) ? wp_json_encode($new_state) : null,
            'reason' => sanitize_textarea_field((string) $reason),
        ], ['%d', '%d', '%s', '%s', '%s', '%s']);
    }

    private function upsert_booking_rates($booking_id, $request_id, $role_key, $region_key, $school_rate, $candidate_pay, $override_flag = 0, $override_reason = '') {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return [];
        }
        $role_key = $this->normalize_rate_role_key($role_key);
        $region_key = $this->normalize_rate_region_key($region_key);
        $school_rate = round((float) $school_rate, 2);
        $candidate_pay = round((float) $candidate_pay, 2);
        $validation = $this->get_rate_validation_payload($school_rate, $candidate_pay, $role_key, $region_key);
        $rule = (array) ($validation['rule'] ?? []);
        $old_row = $this->get_booking_rate_row($booking_id);

        global $wpdb;
        $table = $this->get_booking_rates_table();
        $now = current_time('mysql');
        $wpdb->replace($table, [
            'booking_id' => $booking_id,
            'request_id' => (int) $request_id ?: null,
            'role_key' => $role_key,
            'region_key' => $region_key,
            'rule_id' => isset($rule['id']) ? (int) $rule['id'] : null,
            'school_charge_rate' => $school_rate,
            'candidate_pay_rate' => $candidate_pay,
            'margin_amount' => (float) ($validation['margin_amount'] ?? 0),
            'margin_percent' => (float) ($validation['margin_percent'] ?? 0),
            'guardrail_status' => (string) ($validation['status'] ?? 'OK'),
            'validation_json' => wp_json_encode($validation),
            'override_flag' => (int) ($override_flag ? 1 : 0),
            'override_reason' => $override_reason !== '' ? sanitize_textarea_field($override_reason) : null,
            'updated_by' => get_current_user_id() ?: null,
            'updated_at' => $now,
            'created_at' => (!empty($old_row['created_at']) ? (string) $old_row['created_at'] : $now),
        ], ['%d', '%d', '%s', '%s', '%d', '%f', '%f', '%f', '%f', '%s', '%s', '%d', '%s', '%d', '%s', '%s']);

        update_post_meta($booking_id, 'cmn_school_charge_rate', $school_rate);
        update_post_meta($booking_id, 'cmn_candidate_pay_rate', $candidate_pay);
        update_post_meta($booking_id, 'cmn_rate_guardrail_status', (string) ($validation['status'] ?? 'OK'));
        update_post_meta($booking_id, 'cmn_rate_role_key', $role_key);
        update_post_meta($booking_id, 'cmn_rate_region_key', $region_key);

        $new_row = $this->get_booking_rate_row($booking_id);
        if ($new_row) {
            $this->log_rate_audit($booking_id, $old_row, $new_row, $override_reason !== '' ? $override_reason : 'Rate updated');
        }
        return $validation;
    }

    private function get_request_rate_values($request, $candidate_id = 0, $school_id = 0) {
        $context = $this->resolve_rate_context((int) $candidate_id, (int) $school_id, (array) $request, 0);
        $suggested = $this->get_suggested_rates_for_context($context['role_key'], $context['region_key']);
        $candidate_pay = !empty($request['candidate_pay_rate']) ? (float) $request['candidate_pay_rate'] : (float) ($suggested['candidate_pay'] ?? 0.0);
        $school_rate = !empty($request['school_charge_rate']) ? (float) $request['school_charge_rate'] : (float) ($suggested['school_rate'] ?? 0.0);
        return [
            'role_key' => $context['role_key'],
            'region_key' => $context['region_key'],
            'candidate_pay_rate' => round($candidate_pay, 2),
            'school_charge_rate' => round($school_rate, 2),
        ];
    }

    private function ensure_request_has_guardrail_rates($request) {
        global $wpdb;
        $request_id = (int) ($request['id'] ?? 0);
        if ($request_id < 1) {
            return (array) $request;
        }
        $candidate_id = (int) ($request['candidate_id'] ?? 0);
        $school_id = (int) ($request['school_id'] ?? 0);
        if (!$school_id && !empty($request['school_email_domain'])) {
            $school_id = (int) $this->get_school_post_id_by_domain((string) $request['school_email_domain']);
        }
        $rates = $this->get_request_rate_values($request, $candidate_id, $school_id);
        $needs_update = empty($request['candidate_pay_rate']) || empty($request['school_charge_rate']);
        if ($needs_update) {
            $wpdb->update($this->get_candidate_requests_table(), [
                'candidate_pay_rate' => (float) $rates['candidate_pay_rate'],
                'school_charge_rate' => (float) $rates['school_charge_rate'],
                'updated_at' => current_time('mysql'),
            ], ['id' => $request_id], ['%f', '%f', '%s'], ['%d']);
            $request['candidate_pay_rate'] = $rates['candidate_pay_rate'];
            $request['school_charge_rate'] = $rates['school_charge_rate'];
        }
        $request['role_key'] = $rates['role_key'];
        $request['region_key'] = $rates['region_key'];
        return (array) $request;
    }

