    private function get_candidate_role_labels($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return [];
        }
        $roles = get_post_meta($candidate_id, 'cmn_roles', true);
        if (is_string($roles)) {
            $decoded = json_decode($roles, true);
            if (is_array($decoded)) {
                $roles = $decoded;
            } else {
                $roles = [$roles];
            }
        }
        if (!is_array($roles)) {
            $roles = [];
        }

        $labels = [];
        foreach ($roles as $role) {
            $label = sanitize_text_field((string) $role);
            if ($label === '' || strtolower($label) === 'other') {
                continue;
            }
            $labels[] = $label;
        }

        $role_other = sanitize_text_field((string) get_post_meta($candidate_id, 'cmn_roles_other', true));
        if ($role_other !== '') {
            $labels[] = $role_other;
        }

        return array_values(array_unique(array_filter($labels)));
    }

    private function normalize_candidate_role_rate_map($raw_map, $role_labels = []) {
        if (is_string($raw_map)) {
            $decoded = json_decode($raw_map, true);
            $raw_map = is_array($decoded) ? $decoded : [];
        }
        if (!is_array($raw_map)) {
            $raw_map = [];
        }

        $normalized = [];
        foreach ((array) $role_labels as $label) {
            $clean_label = sanitize_text_field((string) $label);
            if ($clean_label === '') {
                continue;
            }
            $key = sanitize_title($clean_label);
            if ($key === '') {
                continue;
            }
            $item = isset($raw_map[$key]) && is_array($raw_map[$key]) ? $raw_map[$key] : [];
            $candidate_pay = isset($item['candidate_pay_rate']) ? (float) $item['candidate_pay_rate'] : 0.0;
            $school_charge = isset($item['school_charge_rate']) ? (float) $item['school_charge_rate'] : 0.0;
            $normalized[$key] = [
                'role_label' => $clean_label,
                'candidate_pay_rate' => $candidate_pay > 0 ? round($candidate_pay, 2) : 0.0,
                'school_charge_rate' => $school_charge > 0 ? round($school_charge, 2) : 0.0,
            ];
        }

        return $normalized;
    }

    private function get_candidate_role_rate_map($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return [];
        }

        $role_labels = $this->get_candidate_role_labels($candidate_id);
        $stored = get_post_meta($candidate_id, 'cmn_role_rate_map', true);
        $map = $this->normalize_candidate_role_rate_map($stored, $role_labels);

        $default_candidate_pay = (float) get_post_meta($candidate_id, 'cmn_candidate_pay_rate', true);
        $default_school_charge = (float) get_post_meta($candidate_id, 'cmn_school_charge_rate', true);

        foreach ($map as $key => $entry) {
            if ((float) ($entry['candidate_pay_rate'] ?? 0) <= 0) {
                $map[$key]['candidate_pay_rate'] = $default_candidate_pay > 0 ? round($default_candidate_pay, 2) : 0.0;
            }
            if ((float) ($entry['school_charge_rate'] ?? 0) <= 0) {
                $map[$key]['school_charge_rate'] = $default_school_charge > 0 ? round($default_school_charge, 2) : 0.0;
            }
        }

        return $map;
    }

    private function get_candidate_role_rate_entry($candidate_id, $role_label = '') {
        $map = $this->get_candidate_role_rate_map((int) $candidate_id);
        $role_key = sanitize_title((string) $role_label);
        if ($role_key !== '' && isset($map[$role_key])) {
            return $map[$role_key];
        }
        foreach ($map as $entry) {
            if (is_array($entry)) {
                return $entry;
            }
        }

        return [
            'role_label' => sanitize_text_field((string) $role_label),
            'candidate_pay_rate' => 0.0,
            'school_charge_rate' => 0.0,
        ];
    }

    private function get_school_candidate_request_id_for_date($school_id, $candidate_id, $requested_date) {
        $school_id = (int) $school_id;
        $candidate_id = (int) $candidate_id;
        $requested_date = sanitize_text_field((string) $requested_date);
        if ($school_id < 1 || $candidate_id < 1 || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $requested_date)) {
            return 0;
        }
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        return (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table} WHERE school_id = %d AND candidate_id = %d AND requested_date = %s ORDER BY id DESC LIMIT 1",
            $school_id,
            $candidate_id,
            $requested_date
        ));
    }

    private function get_school_candidate_profile_url($candidate_id, $user_id = 0) {
        $candidate_id = (int) $candidate_id;
        $user_id = (int) $user_id;
        if ($candidate_id < 1 || $user_id < 1) {
            return '';
        }

        if ($this->is_candidate_doc_visible_to_school($candidate_id, 'cv_formatted')) {
            $formatted = $this->get_candidate_cv_formatted_status($candidate_id);
            if (!empty($formatted['available'])) {
                return (string) add_query_arg([
                    'action' => 'cmn_candidate_download_doc',
                    'candidate_id' => $candidate_id,
                    'doc_type' => 'cv',
                    'cmn_nonce' => wp_create_nonce('cmn_candidate_download_doc_' . $candidate_id . '_cv_' . $user_id),
                ], admin_url('admin-post.php'));
            }
        }

        if ($this->is_candidate_doc_visible_to_school($candidate_id, 'cv')) {
            return (string) add_query_arg([
                'action' => 'cmn_candidate_download_doc',
                'candidate_id' => $candidate_id,
                'doc_type' => 'cv',
                'cmn_nonce' => wp_create_nonce('cmn_candidate_download_doc_' . $candidate_id . '_cv_' . $user_id),
            ], admin_url('admin-post.php'));
        }

        return '';
    }

    private function get_request_candidate_pay_rate($candidate_id, $school_id, $request = []) {
        if (!empty($request['candidate_pay_rate'])) {
            return (float) $request['candidate_pay_rate'];
        }
        $request = is_array($request) ? $request : [];
        $role_key = sanitize_title((string) ($request['role_key'] ?? ''));
        if ($role_key !== '' && (int) $candidate_id > 0) {
            $role_rate_map = $this->get_candidate_role_rate_map((int) $candidate_id);
            if (isset($role_rate_map[$role_key]) && (float) ($role_rate_map[$role_key]['candidate_pay_rate'] ?? 0) > 0) {
                return round((float) $role_rate_map[$role_key]['candidate_pay_rate'], 2);
            }
        }
        $context = $this->resolve_rate_context((int) $candidate_id, (int) $school_id, $request, 0);
        $suggested = $this->get_suggested_rates_for_context($context['role_key'], $context['region_key']);
        $candidate_pay = isset($suggested['candidate_pay']) ? (float) $suggested['candidate_pay'] : 0.0;
        if ($candidate_pay <= 0) {
            $candidate_pay = (float) $this->get_candidate_rate((int) $candidate_id, (int) $school_id);
        }
        return round($candidate_pay, 2);
    }

    private function get_request_school_charge_rate($candidate_pay_rate, $request = []) {
        if (!empty($request['school_charge_rate'])) {
            return (float) $request['school_charge_rate'];
        }
        $request = is_array($request) ? $request : [];
        $candidate_id = isset($request['candidate_id']) ? (int) $request['candidate_id'] : 0;
        $role_key = sanitize_title((string) ($request['role_key'] ?? ''));
        if ($role_key !== '' && $candidate_id > 0) {
            $role_rate_map = $this->get_candidate_role_rate_map($candidate_id);
            if (isset($role_rate_map[$role_key]) && (float) ($role_rate_map[$role_key]['school_charge_rate'] ?? 0) > 0) {
                return round((float) $role_rate_map[$role_key]['school_charge_rate'], 2);
            }
        }
        $school_id = isset($request['school_id']) ? (int) $request['school_id'] : 0;
        if (!$school_id && !empty($request['school_email_domain'])) {
            $school_id = (int) $this->get_school_post_id_by_domain((string) $request['school_email_domain']);
        }
        $context = $this->resolve_rate_context($candidate_id, $school_id, $request, 0);
        $suggested = $this->get_suggested_rates_for_context($context['role_key'], $context['region_key']);
        $school_rate = isset($suggested['school_rate']) ? (float) $suggested['school_rate'] : 0.0;
        if ($school_rate <= 0) {
            $school_rate = round((float) $candidate_pay_rate + 60, 2);
        }
        if ($school_rate < (float) $candidate_pay_rate) {
            $school_rate = (float) $candidate_pay_rate;
        }
        return round($school_rate, 2);
    }

    private function get_request_expires_at($request) {
        $expires_at = trim((string) ($request['expires_at'] ?? ''));
        if ($expires_at !== '') {
            return $expires_at;
        }
        $sent_at = trim((string) ($request['request_sent_at'] ?? $request['requested_at'] ?? ''));
        if ($sent_at === '') {
            return '';
        }
        return gmdate('Y-m-d H:i:s', strtotime($sent_at . ' +15 minutes'));
    }

    private function is_request_expired($request) {
        $status = strtolower((string) ($request['status'] ?? ''));
        if ($status !== 'requested' && $status !== 'pending') {
            return false;
        }
        $expires_at = $this->get_request_expires_at($request);
        if ($expires_at === '') {
            return false;
        }
        return strtotime($expires_at) <= current_time('timestamp', true);
    }

    private function maybe_mark_request_expired(&$request) {
        if (!$this->is_request_expired($request)) {
            return false;
        }
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $request_id = (int) ($request['id'] ?? 0);
        if (!$request_id) {
            return false;
        }
        $wpdb->update($table, [
            'status' => 'expired',
            'updated_at' => current_time('mysql'),
        ], [
            'id' => $request_id,
            'status' => $request['status'],
        ], ['%s', '%s'], ['%d', '%s']);
        $request['status'] = 'expired';
        return true;
    }

    private function create_or_get_booking_thread($booking_id, $thread_type = 'booking_details', $context = []) {
        $booking_id = (int) $booking_id;
        if (!$booking_id) {
            return 0;
        }
        global $wpdb;
        $table = $this->get_booking_threads_table();
        $columns = $this->get_booking_thread_columns();
        $thread_type = sanitize_key($thread_type);
        $existing = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table} WHERE booking_id = %d AND thread_type = %s LIMIT 1",
            $booking_id,
            $thread_type
        ));
        if ($existing) {
            if (!empty($context) && !empty($columns)) {
                $updates = [];
                $formats = [];
                if (in_array('candidate_user_id', $columns, true) && isset($context['candidate_user_id'])) {
                    $updates['candidate_user_id'] = (int) $context['candidate_user_id'];
                    $formats[] = '%d';
                }
                if (in_array('school_user_id', $columns, true) && isset($context['school_user_id'])) {
                    $updates['school_user_id'] = (int) $context['school_user_id'];
                    $formats[] = '%d';
                }
                if (in_array('account_manager_user_id', $columns, true) && isset($context['account_manager_user_id'])) {
                    $updates['account_manager_user_id'] = (int) $context['account_manager_user_id'];
                    $formats[] = '%d';
                }
                if (in_array('status', $columns, true) && isset($context['status'])) {
                    $updates['status'] = sanitize_key((string) $context['status']);
                    $formats[] = '%s';
                }
                if ($updates) {
                    $wpdb->update($table, $updates, ['id' => $existing], $formats, ['%d']);
                }
            }
            return $existing;
        }
        $insert_data = [
            'booking_id' => $booking_id,
            'thread_type' => $thread_type,
            'created_at' => current_time('mysql'),
        ];
        $insert_formats = ['%d', '%s', '%s'];
        if (in_array('candidate_user_id', $columns, true)) {
            $insert_data['candidate_user_id'] = isset($context['candidate_user_id']) ? (int) $context['candidate_user_id'] : null;
            $insert_formats[] = '%d';
        }
        if (in_array('school_user_id', $columns, true)) {
            $insert_data['school_user_id'] = isset($context['school_user_id']) ? (int) $context['school_user_id'] : null;
            $insert_formats[] = '%d';
        }
        if (in_array('account_manager_user_id', $columns, true)) {
            $insert_data['account_manager_user_id'] = isset($context['account_manager_user_id']) ? (int) $context['account_manager_user_id'] : null;
            $insert_formats[] = '%d';
        }
        if (in_array('status', $columns, true)) {
            $insert_data['status'] = isset($context['status']) ? sanitize_key((string) $context['status']) : 'active';
            $insert_formats[] = '%s';
        }
        $wpdb->insert($table, $insert_data, $insert_formats);
        return (int) $wpdb->insert_id;
    }

    private function add_booking_thread_participant($thread_id, $user_id, $role_type) {
        $thread_id = (int) $thread_id;
        $user_id = (int) $user_id;
        if (!$thread_id || !$user_id) {
            return;
        }
        global $wpdb;
        $table = $this->get_booking_participants_table();
        $wpdb->replace($table, [
            'thread_id' => $thread_id,
            'user_id' => $user_id,
            'role_type' => sanitize_key($role_type),
            'created_at' => current_time('mysql'),
        ], ['%d', '%d', '%s', '%s']);
    }

    private function add_booking_thread_message($thread_id, $sender_user_id, $sender_role_type, $message, $attachment_ids = []) {
        $thread_id = (int) $thread_id;
        if (!$thread_id || trim((string) $message) === '') {
            return;
        }
        global $wpdb;
        $table = $this->get_booking_messages_table();
        $columns = $this->get_booking_message_columns();
        $insert_data = [
            'thread_id' => $thread_id,
            'sender_user_id' => (int) $sender_user_id ?: null,
            'sender_role_type' => sanitize_key($sender_role_type),
            'message' => wp_kses_post((string) $message),
            'created_at' => current_time('mysql'),
        ];
        $formats = ['%d', '%d', '%s', '%s', '%s'];
        if (in_array('attachment_ids', $columns, true)) {
            $safe_ids = [];
            if (is_array($attachment_ids)) {
                foreach ($attachment_ids as $attachment_id) {
                    $attachment_id = (int) $attachment_id;
                    if ($attachment_id > 0) {
                        $safe_ids[] = $attachment_id;
                    }
                }
            }
            $insert_data['attachment_ids'] = $safe_ids ? wp_json_encode(array_values(array_unique($safe_ids))) : null;
            $formats[] = '%s';
        }
        $wpdb->insert($table, $insert_data, $formats);
    }

    private function user_can_access_booking_thread($thread_id, $user_id = 0) {
        $thread_id = (int) $thread_id;
        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        if (!$thread_id || !$user_id) {
            return false;
        }
        if ($this->is_staff_user()) {
            return true;
        }
        global $wpdb;
        $table = $this->get_booking_participants_table();
        $has = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table} WHERE thread_id = %d AND user_id = %d LIMIT 1",
            $thread_id,
            $user_id
        ));
        return $has > 0;
    }

    private function get_booking_thread_by_booking($booking_id, $thread_type = 'booking_details') {
        global $wpdb;
        $table = $this->get_booking_threads_table();
        return $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE booking_id = %d AND thread_type = %s LIMIT 1",
            (int) $booking_id,
            sanitize_key($thread_type)
        ), ARRAY_A);
    }

    private function ensure_booking_thread_for_view($booking_id, $thread_type = 'booking_details') {
        $booking_id = (int) $booking_id;
        $thread_type = sanitize_key((string) $thread_type);
        if ($booking_id < 1 || !in_array($thread_type, ['booking_details', 'pay_negotiation', 'decline_followup', 'school_coordination', 'candidate_coordination'], true)) {
            return [];
        }

        $viewer_user_id = (int) get_current_user_id();
        if ($viewer_user_id < 1) {
            return [];
        }
        $candidate_user_id = (int) $this->get_booking_candidate_user_id($booking_id);
        $school_user_id = (int) $this->get_booking_school_user_id($booking_id);
        if (!$this->is_staff_user($viewer_user_id)) {
            $is_booking_candidate = $this->is_candidate_user($viewer_user_id) && $candidate_user_id > 0 && $candidate_user_id === $viewer_user_id;
            $is_booking_school = $this->is_school_user($viewer_user_id) && $school_user_id > 0 && $school_user_id === $viewer_user_id;
            if (!$is_booking_candidate && !$is_booking_school) {
                return [];
            }
        }

        $thread = $this->get_booking_thread_by_booking($booking_id, $thread_type);
        if ($thread) {
            return $thread;
        }

        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        $request_id = (int) get_post_meta($booking_id, 'cmn_request_id', true);
        $request = $request_id > 0 ? (array) $this->get_candidate_request_by_id($request_id) : [];
        $am_user_id = (int) $this->get_request_account_manager_user_id($school_id, $request);
        $thread_id = (int) $this->create_or_get_booking_thread($booking_id, $thread_type, [
            'candidate_user_id' => $candidate_user_id,
            'school_user_id' => $school_user_id,
            'account_manager_user_id' => $am_user_id,
            'status' => 'active',
        ]);
        if ($thread_id < 1) {
            return [];
        }

        if ($am_user_id > 0) {
            $this->add_booking_thread_participant($thread_id, $am_user_id, 'account_manager');
        }
        if ($thread_type === 'school_coordination') {
            if ($school_user_id > 0) {
                $this->add_booking_thread_participant($thread_id, $school_user_id, 'school');
            }
        } elseif ($thread_type === 'candidate_coordination' || $thread_type === 'pay_negotiation') {
            if ($candidate_user_id > 0) {
                $this->add_booking_thread_participant($thread_id, $candidate_user_id, 'candidate');
            }
        } else {
            if ($candidate_user_id > 0) {
                $this->add_booking_thread_participant($thread_id, $candidate_user_id, 'candidate');
            }
            if ($school_user_id > 0) {
                $this->add_booking_thread_participant($thread_id, $school_user_id, 'school');
            }
        }

        $thread = $this->get_booking_thread_by_booking($booking_id, $thread_type);
        return $thread ? $thread : [];
    }

    private function get_booking_thread_status($thread_id) {
        global $wpdb;
        $table = $this->get_booking_threads_table();
        $status = (string) $wpdb->get_var($wpdb->prepare(
            "SELECT status FROM {$table} WHERE id = %d LIMIT 1",
            (int) $thread_id
        ));
        $status = sanitize_key($status);
        return $status !== '' ? $status : 'active';
    }

    private function set_booking_thread_status($thread_id, $status) {
        $thread_id = (int) $thread_id;
        $status = sanitize_key((string) $status);
        if ($thread_id < 1 || !in_array($status, ['active', 'closed'], true)) {
            return false;
        }
        global $wpdb;
        $table = $this->get_booking_threads_table();
        $updated = $wpdb->update($table, [
            'status' => $status,
        ], [
            'id' => $thread_id,
        ], ['%s'], ['%d']);
        return $updated !== false;
    }

    private function get_booking_thread_messages($thread_id) {
        global $wpdb;
        $table = $this->get_booking_messages_table();
        return $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE thread_id = %d ORDER BY created_at ASC, id ASC",
            (int) $thread_id
        ), ARRAY_A);
    }

    private function get_no_show_cancelled_booking_statuses() {
        return ['declined', 'cancelled', 'candidate_declined', 'expired'];
    }

    private function get_no_show_expected_booking_statuses() {
        return ['accepted', 'approved', 'confirmed', 'candidate_accepted', 'completed', 'completed_attended', 'no_show', 'noshow'];
    }

    private function get_booking_shift_date_window($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return [];
        }
        $start_date = $this->normalize_booking_invoice_date_value((string) get_post_meta($booking_id, 'cmn_start_date', true));
        if ($start_date === '') {
            $start_date = $this->normalize_booking_invoice_date_value((string) get_post_meta($booking_id, 'cmn_date', true));
        }
        if ($start_date === '') {
            return [];
        }
        $end_date = $this->normalize_booking_invoice_date_value((string) get_post_meta($booking_id, 'cmn_end_date', true));
        if ($end_date === '') {
            $end_date = $start_date;
        }
        if (strtotime($end_date) < strtotime($start_date)) {
            $end_date = $start_date;
        }
        return [
            'start_date' => $start_date,
            'end_date' => $end_date,
        ];
    }

    private function get_booking_shift_start_datetime_for_day($booking_id, $shift_date) {
        $booking_id = (int) $booking_id;
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        if ($booking_id < 1 || $shift_date === '') {
            return '';
        }
        $start_time = sanitize_text_field((string) get_post_meta($booking_id, 'cmn_start_time', true));
        if ($start_time === '') {
            return '';
        }
        try {
            $shift_start = new DateTime($shift_date . ' ' . $start_time, wp_timezone());
            return $shift_start->format('Y-m-d H:i:s');
        } catch (Exception $e) {
            return '';
        }
    }

    private function get_booking_chat_evidence_before_shift_start($booking_id, $candidate_id, $shift_start_datetime = '') {
        $booking_id = (int) $booking_id;
        $candidate_id = (int) $candidate_id;
        $shift_start_datetime = $this->normalize_invoice_datetime((string) $shift_start_datetime);
        $payload = [
            'checked' => false,
            'candidate_message_before_start' => false,
            'last_message_at' => '',
            'on_behalf_detected' => false,
            'candidate_last_message_at' => '',
        ];
        if ($booking_id < 1 || $candidate_id < 1 || $shift_start_datetime === '') {
            return $payload;
        }

        global $wpdb;
        $threads_table = $this->get_booking_threads_table();
        $messages_table = $this->get_booking_messages_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT m.id, m.created_at, m.sender_user_id, m.sender_role_type, t.thread_type
             FROM {$messages_table} m
             INNER JOIN {$threads_table} t ON t.id = m.thread_id
             WHERE t.booking_id = %d
               AND m.created_at <= %s
             ORDER BY m.created_at DESC, m.id DESC
             LIMIT 500",
            $booking_id,
            $shift_start_datetime
        ), ARRAY_A);

        $payload['checked'] = true;
        if (!$rows || !is_array($rows)) {
            return $payload;
        }
        $payload['last_message_at'] = (string) ($rows[0]['created_at'] ?? '');

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        foreach ($rows as $row) {
            $sender_role = sanitize_key((string) ($row['sender_role_type'] ?? ''));
            $thread_type = sanitize_key((string) ($row['thread_type'] ?? ''));
            $sender_user_id = (int) ($row['sender_user_id'] ?? 0);
            $is_candidate_direct = $sender_role === 'candidate' || ($candidate_user_id > 0 && $sender_user_id === $candidate_user_id);
            $is_on_behalf = !$is_candidate_direct
                && $thread_type === 'candidate_coordination'
                && in_array($sender_role, ['account_manager', 'admin'], true);
            if (!$is_candidate_direct && !$is_on_behalf) {
                continue;
            }
            $payload['candidate_message_before_start'] = true;
            $payload['candidate_last_message_at'] = (string) ($row['created_at'] ?? '');
            $payload['on_behalf_detected'] = $is_on_behalf;
            break;
        }

        return $payload;
    }

    private function assess_candidate_no_show_day($candidate_id, $booking_id, $shift_date) {
        $candidate_id = (int) $candidate_id;
        $booking_id = (int) $booking_id;
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        if ($candidate_id < 1 || $booking_id < 1 || $shift_date === '') {
            return new WP_Error('cmn_no_show_invalid_input', 'Candidate, booking, and shift date are required.');
        }
        if (get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_no_show_invalid_candidate', 'Invalid candidate selected for no-show confirmation.');
        }
        if (get_post_type($booking_id) !== 'cmn_booking') {
            return new WP_Error('cmn_no_show_invalid_booking', 'Invalid booking selected for no-show confirmation.');
        }
        $booking_candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if ($booking_candidate_id !== $candidate_id) {
            return new WP_Error('cmn_no_show_candidate_mismatch', 'Candidate does not match the selected booking.');
        }

        $status = sanitize_key((string) get_post_meta($booking_id, 'cmn_status', true));
        $cancelled = in_array($status, $this->get_no_show_cancelled_booking_statuses(), true);
        if ($cancelled) {
            return new WP_Error('cmn_no_show_cancelled', 'Cancelled shifts cannot be confirmed as no-show.');
        }

        $shift_window = $this->get_booking_shift_date_window($booking_id);
        $start_date = (string) ($shift_window['start_date'] ?? '');
        $end_date = (string) ($shift_window['end_date'] ?? '');
        if ($start_date === '' || $end_date === '') {
            return new WP_Error('cmn_no_show_missing_dates', 'Booking dates are missing, so this no-show cannot be confirmed.');
        }
        if (strtotime($shift_date) < strtotime($start_date) || strtotime($shift_date) > strtotime($end_date)) {
            return new WP_Error('cmn_no_show_date_outside_booking', 'Shift date is outside the booking date range.');
        }

        $today = current_time('Y-m-d');
        if ($shift_date > $today) {
            return new WP_Error('cmn_no_show_future_shift', 'Future booking-days cannot be confirmed as no-show.');
        }

        $school_expected = in_array($status, $this->get_no_show_expected_booking_statuses(), true);
        if (!$school_expected) {
            return new WP_Error('cmn_no_show_not_expected', 'Booking is not in a confirmed state where the school would expect attendance.');
        }

        $attendance_completed = in_array($status, ['completed', 'completed_attended'], true);
        $status_no_show = in_array($status, ['no_show', 'noshow'], true);
        $candidate_not_attended = $status_no_show || (!$attendance_completed && $shift_date <= $today);
        if (!$candidate_not_attended) {
            return new WP_Error('cmn_no_show_not_absent', 'This booking-day is marked as completed and cannot be confirmed as no-show.');
        }

        return [
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'booking_status' => $status,
            'school_expected' => true,
            'cancelled' => false,
            'attendance_completed' => $attendance_completed,
            'status_no_show' => $status_no_show,
            'start_date' => $start_date,
            'end_date' => $end_date,
        ];
    }

    private function get_candidate_no_show_policy_guidance_text() {
        return 'If urgency or exceptional circumstances are raised, reopen booking chat and notify both school and account manager. Keep all communication in booking chat.';
    }

    private function get_candidate_rewards_event_row($candidate_id, $booking_id, $shift_date, $event_type) {
        $candidate_id = (int) $candidate_id;
        $booking_id = max(0, (int) $booking_id);
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $event_type = substr(sanitize_key((string) $event_type), 0, 32);
        if ($candidate_id < 1 || $shift_date === '' || $event_type === '') {
            return [];
        }
        global $wpdb;
        $table = $this->get_candidate_rewards_events_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_id = %d
               AND booking_id = %d
               AND shift_date = %s
               AND event_type = %s
             LIMIT 1",
            $candidate_id,
            $booking_id,
            $shift_date,
            $event_type
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function maybe_reinstate_candidate_rewards_after_probation($candidate_id, $booking_id, $shift_date, $academic_year, $rewards_row = [], $context = []) {
        $candidate_id = (int) $candidate_id;
        $booking_id = max(0, (int) $booking_id);
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, $shift_date);
        $context = is_array($context) ? $context : [];
        if ($candidate_id < 1 || $shift_date === '' || $academic_year === '') {
            return new WP_Error('cmn_candidate_rewards_probation_reinstate_invalid_input', 'Invalid candidate probation reinstatement input.');
        }
        if (!is_array($rewards_row) || !$rewards_row) {
            $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
            if (is_wp_error($rewards_row)) {
                return $rewards_row;
            }
        }

        $previous_status = sanitize_key((string) ($rewards_row['conduct_status'] ?? 'clear'));
        $is_paused = !empty($rewards_row['rewards_paused']) && ((int) $rewards_row['rewards_paused']) === 1;
        $probation_count = max(0, (int) ($rewards_row['probation_consecutive_shifts'] ?? 0));
        if ($previous_status === 'terminated') {
            $this->add_audit_log('candidate_rewards_probation_reinstate_skipped_terminated', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'probation_count' => $probation_count,
            ]);
            return [
                'reinstated' => false,
                'eligible' => false,
                'reason' => 'terminated',
                'event_id' => 0,
            ];
        }
        if (!$is_paused || !in_array($previous_status, ['yellow', 'red'], true) || $probation_count < 10) {
            return [
                'reinstated' => false,
                'eligible' => false,
                'reason' => 'threshold_not_met',
                'event_id' => 0,
            ];
        }

        $reinstated_row = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'conduct_status' => 'clear',
            'rewards_paused' => 0,
            'review_required' => 0,
            'probation_consecutive_shifts' => 0,
        ]);
        if (is_wp_error($reinstated_row)) {
            return $reinstated_row;
        }

        $event_insert = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'event_type' => 'rewards_reinstated',
            'delta_cycle' => 0,
            'delta_year_total' => 0,
            'meta' => [
                'reinstated_at' => current_time('mysql'),
                'previous_status' => $previous_status,
                'rule' => '10_consecutive_payable_shifts',
                'source' => sanitize_key((string) ($context['source'] ?? 'completed_payable_hook')),
            ],
            'created_by_user_id' => (int) ($context['created_by_user_id'] ?? 0),
        ]);
        if (is_wp_error($event_insert)) {
            return $event_insert;
        }

        $this->add_audit_log('candidate_rewards_reinstated', 'booking', (string) $booking_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'academic_year' => $academic_year,
            'previous_status' => $previous_status,
            'rule' => '10_consecutive_payable_shifts',
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
            'event_duplicate' => empty($event_insert['inserted']) ? 1 : 0,
        ]);

        return [
            'reinstated' => true,
            'eligible' => true,
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
            'duplicate' => empty($event_insert['inserted']),
            'row' => is_array($reinstated_row) ? $reinstated_row : [],
        ];
    }

    private function maybe_increment_candidate_probation_shift($candidate_id, $booking_id, $shift_date, $academic_year, $rewards_row = [], $context = []) {
        $candidate_id = (int) $candidate_id;
        $booking_id = max(0, (int) $booking_id);
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, $shift_date);
        $context = is_array($context) ? $context : [];
        if ($candidate_id < 1 || $shift_date === '' || $academic_year === '') {
            return new WP_Error('cmn_candidate_rewards_probation_invalid_input', 'Invalid candidate probation shift input.');
        }
        if ($this->is_candidate_rewards_august_shift_date($shift_date)) {
            return [
                'incremented' => false,
                'duplicate' => false,
                'reinstated' => false,
                'skipped' => true,
                'reason' => 'august_excluded',
                'probation_count_after' => 0,
                'event_id' => 0,
                'reinstated_event_id' => 0,
            ];
        }
        if (!is_array($rewards_row) || !$rewards_row) {
            $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
            if (is_wp_error($rewards_row)) {
                return $rewards_row;
            }
        }

        $conduct_status = sanitize_key((string) ($rewards_row['conduct_status'] ?? 'clear'));
        $is_paused = !empty($rewards_row['rewards_paused']) && ((int) $rewards_row['rewards_paused']) === 1;
        $current_probation_count = max(0, (int) ($rewards_row['probation_consecutive_shifts'] ?? 0));
        if ($conduct_status === 'terminated') {
            $this->add_audit_log('candidate_rewards_probation_shift_skipped_terminated', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'probation_count' => $current_probation_count,
            ]);
            return [
                'incremented' => false,
                'duplicate' => false,
                'reinstated' => false,
                'skipped' => true,
                'reason' => 'terminated',
                'probation_count_after' => $current_probation_count,
                'event_id' => 0,
                'reinstated_event_id' => 0,
            ];
        }
        if (!$is_paused || !in_array($conduct_status, ['yellow', 'red'], true)) {
            return [
                'incremented' => false,
                'duplicate' => false,
                'reinstated' => false,
                'skipped' => true,
                'reason' => 'not_on_probation',
                'probation_count_after' => $current_probation_count,
                'event_id' => 0,
                'reinstated_event_id' => 0,
            ];
        }

        $probation_count_after = $current_probation_count + 1;
        $event_insert = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'event_type' => 'probation_shift_completed',
            'delta_cycle' => 0,
            'delta_year_total' => 0,
            'meta' => [
                'source' => sanitize_key((string) ($context['source'] ?? 'completed_payable_hook')),
                'status' => sanitize_key((string) ($context['status'] ?? '')),
                'conduct_status' => $conduct_status,
                'probation_count_after' => $probation_count_after,
            ],
            'created_by_user_id' => (int) ($context['created_by_user_id'] ?? 0),
        ]);
        if (is_wp_error($event_insert)) {
            return $event_insert;
        }
        if (empty($event_insert['inserted'])) {
            return [
                'incremented' => false,
                'duplicate' => true,
                'reinstated' => false,
                'skipped' => false,
                'reason' => 'duplicate',
                'probation_count_after' => $current_probation_count,
                'event_id' => (int) ($event_insert['event_id'] ?? 0),
                'reinstated_event_id' => 0,
            ];
        }

        $updated_row = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'probation_consecutive_shifts' => $probation_count_after,
        ]);
        if (is_wp_error($updated_row)) {
            return $updated_row;
        }

        $reinstatement = $this->maybe_reinstate_candidate_rewards_after_probation(
            $candidate_id,
            $booking_id,
            $shift_date,
            $academic_year,
            $updated_row,
            $context
        );
        if (is_wp_error($reinstatement)) {
            return $reinstatement;
        }

        $this->add_audit_log('candidate_rewards_probation_shift_completed', 'booking', (string) $booking_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'academic_year' => $academic_year,
            'conduct_status' => $conduct_status,
            'probation_count_after' => $probation_count_after,
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
            'reinstated' => !empty($reinstatement['reinstated']) ? 1 : 0,
            'reinstated_event_id' => (int) ($reinstatement['event_id'] ?? 0),
        ]);

        return [
            'incremented' => true,
            'duplicate' => false,
            'reinstated' => !empty($reinstatement['reinstated']),
            'skipped' => false,
            'reason' => '',
            'probation_count_after' => !empty($reinstatement['reinstated']) ? 0 : $probation_count_after,
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
            'reinstated_event_id' => (int) ($reinstatement['event_id'] ?? 0),
        ];
    }

    private function maybe_reset_candidate_probation_on_no_show($candidate_id, $booking_id, $shift_date, $academic_year, $rewards_row = [], $context = []) {
        $candidate_id = (int) $candidate_id;
        $booking_id = max(0, (int) $booking_id);
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $academic_year = $this->normalize_candidate_rewards_academic_year_label((string) $academic_year, $shift_date);
        $context = is_array($context) ? $context : [];
        if ($candidate_id < 1 || $shift_date === '' || $academic_year === '') {
            return new WP_Error('cmn_candidate_rewards_probation_reset_invalid_input', 'Invalid candidate probation reset input.');
        }
        if (!is_array($rewards_row) || !$rewards_row) {
            $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
            if (is_wp_error($rewards_row)) {
                return $rewards_row;
            }
        }

        $conduct_status = sanitize_key((string) ($rewards_row['conduct_status'] ?? 'clear'));
        $is_paused = !empty($rewards_row['rewards_paused']) && ((int) $rewards_row['rewards_paused']) === 1;
        $probation_count_before = max(0, (int) ($rewards_row['probation_consecutive_shifts'] ?? 0));
        if (!$is_paused || !in_array($conduct_status, ['yellow', 'red'], true)) {
            return [
                'reset' => false,
                'duplicate' => false,
                'skipped' => true,
                'reason' => 'not_on_probation',
                'probation_count_before' => $probation_count_before,
                'event_id' => 0,
            ];
        }

        $event_insert = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'event_type' => 'probation_reset',
            'delta_cycle' => 0,
            'delta_year_total' => 0,
            'meta' => [
                'reason' => 'no_show_during_probation',
                'source' => sanitize_key((string) ($context['source'] ?? 'no_show_confirmation')),
                'conduct_status' => $conduct_status,
                'probation_count_before' => $probation_count_before,
            ],
            'created_by_user_id' => (int) ($context['created_by_user_id'] ?? 0),
        ]);
        if (is_wp_error($event_insert)) {
            return $event_insert;
        }
        if (empty($event_insert['inserted'])) {
            return [
                'reset' => false,
                'duplicate' => true,
                'skipped' => false,
                'reason' => 'duplicate',
                'probation_count_before' => $probation_count_before,
                'event_id' => (int) ($event_insert['event_id'] ?? 0),
            ];
        }

        $updated_row = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'probation_consecutive_shifts' => 0,
        ]);
        if (is_wp_error($updated_row)) {
            return $updated_row;
        }

        $this->add_audit_log('candidate_rewards_probation_reset', 'booking', (string) $booking_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'academic_year' => $academic_year,
            'conduct_status' => $conduct_status,
            'probation_count_before' => $probation_count_before,
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
        ]);

        return [
            'reset' => true,
            'duplicate' => false,
            'skipped' => false,
            'reason' => '',
            'probation_count_before' => $probation_count_before,
            'event_id' => (int) ($event_insert['event_id'] ?? 0),
        ];
    }

    private function disable_candidate_portal_access_for_rewards($candidate_id, $context = []) {
        $candidate_id = (int) $candidate_id;
        $context = is_array($context) ? $context : [];
        $reason = sanitize_textarea_field((string) ($context['reason'] ?? 'Candidate terminated after repeated confirmed no-shows.'));
        $actor_user_id = (int) ($context['actor_user_id'] ?? 0);
        $timestamp = current_time('mysql');
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return [
                'disabled' => false,
                'user_id' => 0,
                'message' => 'Invalid candidate.',
            ];
        }

        update_post_meta($candidate_id, 'cmn_deactivated', '1');
        update_post_meta($candidate_id, 'cmn_rewards_conduct_status', 'terminated');
        update_post_meta($candidate_id, 'cmn_rewards_terminated_at', $timestamp);
        if ($reason !== '') {
            update_post_meta($candidate_id, 'cmn_rewards_termination_reason', $reason);
        }
        if ($actor_user_id > 0) {
            update_post_meta($candidate_id, 'cmn_rewards_terminated_by_user_id', $actor_user_id);
        }

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            return [
                'disabled' => false,
                'user_id' => 0,
                'message' => 'Candidate user mapping missing.',
            ];
        }

        update_user_meta($candidate_user_id, 'cmn_deactivated', 1);
        update_user_meta($candidate_user_id, 'cmn_rewards_conduct_status', 'terminated');
        update_user_meta($candidate_user_id, 'cmn_rewards_terminated_at', $timestamp);
        if ($reason !== '') {
            update_user_meta($candidate_user_id, 'cmn_rewards_termination_reason', $reason);
        }
        if ($actor_user_id > 0) {
            update_user_meta($candidate_user_id, 'cmn_rewards_terminated_by_user_id', $actor_user_id);
        }

        if (class_exists('WP_Session_Tokens')) {
            try {
                $session_tokens = WP_Session_Tokens::get_instance($candidate_user_id);
                if ($session_tokens) {
                    $session_tokens->destroy_all();
                }
            } catch (Exception $e) {
                // Ignore session invalidation failures; login block still applies via cmn_deactivated.
            }
        }

        return [
            'disabled' => true,
            'user_id' => $candidate_user_id,
            'message' => 'Candidate portal access disabled.',
        ];
    }

    private function restore_candidate_portal_access_for_rewards($candidate_id, $context = []) {
        $candidate_id = (int) $candidate_id;
        $context = is_array($context) ? $context : [];
        $reason = sanitize_textarea_field((string) ($context['reason'] ?? 'Termination reversed via Candidate Rewards override.'));
        $actor_user_id = (int) ($context['actor_user_id'] ?? 0);
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($context['conduct_status'] ?? 'clear'));
        if ($conduct_status === 'terminated') {
            $conduct_status = 'red';
        }
        $timestamp = current_time('mysql');
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return [
                'restored' => false,
                'user_id' => 0,
                'message' => 'Invalid candidate.',
            ];
        }

        update_post_meta($candidate_id, 'cmn_deactivated', '0');
        update_post_meta($candidate_id, 'cmn_rewards_conduct_status', $conduct_status);
        update_post_meta($candidate_id, 'cmn_rewards_termination_reversed_at', $timestamp);
        if ($reason !== '') {
            update_post_meta($candidate_id, 'cmn_rewards_termination_reversal_reason', $reason);
        }
        if ($actor_user_id > 0) {
            update_post_meta($candidate_id, 'cmn_rewards_termination_reversed_by_user_id', $actor_user_id);
        }

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            return [
                'restored' => false,
                'user_id' => 0,
                'message' => 'Candidate user mapping missing.',
            ];
        }

        update_user_meta($candidate_user_id, 'cmn_deactivated', 0);
        update_user_meta($candidate_user_id, 'cmn_rewards_conduct_status', $conduct_status);
        update_user_meta($candidate_user_id, 'cmn_rewards_termination_reversed_at', $timestamp);
        if ($reason !== '') {
            update_user_meta($candidate_user_id, 'cmn_rewards_termination_reversal_reason', $reason);
        }
        if ($actor_user_id > 0) {
            update_user_meta($candidate_user_id, 'cmn_rewards_termination_reversed_by_user_id', $actor_user_id);
        }

        return [
            'restored' => true,
            'user_id' => $candidate_user_id,
            'message' => 'Candidate portal access restored.',
        ];
    }

    private function reverse_candidate_no_show_penalty_for_override($candidate_id, $booking_id, $shift_date, $reversal_reason = '', $actor_user_id = 0, $context = []) {
        $candidate_id = (int) $candidate_id;
        $booking_id = (int) $booking_id;
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $reversal_reason = sanitize_textarea_field((string) $reversal_reason);
        $actor_user_id = (int) ($actor_user_id ?: get_current_user_id());
        $context = is_array($context) ? $context : [];
        $source = sanitize_key((string) ($context['source'] ?? 'staff_override_no_show_reversal'));
        if ($source === '') {
            $source = 'staff_override_no_show_reversal';
        }

        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_Error('cmn_no_show_reverse_invalid_candidate', 'Candidate not found.');
        }
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking') {
            return new WP_Error('cmn_no_show_reverse_invalid_booking', 'Booking not found.');
        }
        if ($shift_date === '') {
            return new WP_Error('cmn_no_show_reverse_invalid_shift_date', 'Valid shift date is required.');
        }
        if ($reversal_reason === '') {
            return new WP_Error('cmn_no_show_reverse_reason_required', 'Override reason is required.');
        }

        $confirmed_event = $this->get_candidate_rewards_event_row($candidate_id, $booking_id, $shift_date, 'no_show_confirmed');
        if (!$confirmed_event) {
            return new WP_Error('cmn_no_show_reverse_missing_confirmation', 'No confirmed no-show exists for this booking-day.');
        }
        $existing_reversal_event = $this->get_candidate_rewards_event_row($candidate_id, $booking_id, $shift_date, 'no_show_reversed');
        if ($existing_reversal_event) {
            return new WP_Error('cmn_no_show_reverse_duplicate', 'This no-show has already been reversed.');
        }

        $academic_year = function_exists('cmn_get_academic_year_label')
            ? (string) cmn_get_academic_year_label($shift_date)
            : (string) $this->get_academic_year_label($shift_date);
        $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($rewards_row)) {
            return $rewards_row;
        }
        $rewards_row = is_array($rewards_row) ? $rewards_row : [];

        $confirmed_meta_snapshot = $this->decode_candidate_rewards_event_meta((string) ($confirmed_event['meta'] ?? ''));
        $penalty_event = $this->get_candidate_rewards_event_row($candidate_id, $booking_id, $shift_date, 'penalty_applied');
        $existing_penalty_reversed = $this->get_candidate_rewards_event_row($candidate_id, $booking_id, $shift_date, 'penalty_reversed');

        $payout_rows = $this->get_candidate_reward_payouts($candidate_id, $academic_year, 5);
        $finance_review_required = !empty($payout_rows);
        $finance_warning = $finance_review_required
            ? 'Payout history exists for this academic year; finance review is required before any payout adjustment.'
            : '';

        $before_conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($rewards_row['conduct_status'] ?? 'clear'));
        $before_rewards_paused = !empty($rewards_row['rewards_paused']) ? 1 : 0;
        $before_no_show_count = max(0, (int) ($rewards_row['no_show_count'] ?? 0));
        $before_cycle_count = (int) ($rewards_row['shift_cycle_count'] ?? 0);

        $penalty_found = !empty($penalty_event);
        $penalty_reversed_event_id = max(0, (int) ($existing_penalty_reversed['id'] ?? 0));
        $penalty_reversal_applied = false;
        $penalty_already_reversed = !empty($existing_penalty_reversed);
        if ($penalty_found && !$penalty_already_reversed) {
            $penalty_reversed_event = $this->insert_candidate_rewards_event([
                'candidate_id' => $candidate_id,
                'booking_id' => $booking_id,
                'shift_date' => $shift_date,
                'event_type' => 'penalty_reversed',
                'delta_cycle' => 3,
                'delta_year_total' => 0,
                'meta' => [
                    'linked_penalty_event_id' => (int) ($penalty_event['id'] ?? 0),
                    'linked_no_show_event_id' => (int) ($confirmed_event['id'] ?? 0),
                    'reversal_reason' => $reversal_reason,
                    'reversed_by_user_id' => $actor_user_id,
                    'source' => $source,
                    'timestamp' => current_time('mysql'),
                    'finance_manual_review_required' => $finance_review_required ? 1 : 0,
                    'finance_warning' => $finance_warning,
                ],
                'created_by_user_id' => $actor_user_id,
            ]);
            if (is_wp_error($penalty_reversed_event)) {
                return $penalty_reversed_event;
            }
            $penalty_reversed_event_id = (int) ($penalty_reversed_event['event_id'] ?? 0);
            $penalty_reversal_applied = !empty($penalty_reversed_event['inserted']);
            $penalty_already_reversed = !$penalty_reversal_applied;
        }

        $updated_rewards_row = $rewards_row;
        if ($penalty_reversal_applied) {
            $after_cycle_count = $before_cycle_count + 3;
            $after_no_show_count = max(0, $before_no_show_count - 1);
            $after_conduct_status = 'clear';
            $after_rewards_paused = 0;
            $after_review_required = 0;
            if ($after_no_show_count >= 3) {
                $after_conduct_status = 'terminated';
                $after_rewards_paused = 1;
                $after_review_required = 1;
            } elseif ($after_no_show_count >= 2) {
                $after_conduct_status = 'red';
                $after_rewards_paused = 1;
                $after_review_required = 1;
            } elseif ($after_no_show_count === 1) {
                $after_conduct_status = 'yellow';
                $after_rewards_paused = 1;
                $after_review_required = 0;
            }
            $updated_rewards_row = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
                'shift_cycle_count' => $after_cycle_count,
                'no_show_count' => $after_no_show_count,
                'conduct_status' => $after_conduct_status,
                'rewards_paused' => $after_rewards_paused,
                'review_required' => $after_review_required,
                'probation_consecutive_shifts' => 0,
            ]);
            if (is_wp_error($updated_rewards_row)) {
                return $updated_rewards_row;
            }
        }

        $updated_rewards_row = is_array($updated_rewards_row) ? $updated_rewards_row : [];
        $after_conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($updated_rewards_row['conduct_status'] ?? $before_conduct_status));
        $after_rewards_paused = !empty($updated_rewards_row['rewards_paused']) ? 1 : 0;
        $after_no_show_count = max(0, (int) ($updated_rewards_row['no_show_count'] ?? $before_no_show_count));
        $after_cycle_count = (int) ($updated_rewards_row['shift_cycle_count'] ?? $before_cycle_count);

        $rewards_reinstated_override_event_id = 0;
        if ($penalty_reversal_applied && $before_rewards_paused === 1 && $after_rewards_paused === 0) {
            $reinstated_event = $this->insert_candidate_rewards_event([
                'candidate_id' => $candidate_id,
                'booking_id' => $booking_id,
                'shift_date' => $shift_date,
                'event_type' => 'rewards_reinstated_override',
                'delta_cycle' => 0,
                'delta_year_total' => 0,
                'meta' => [
                    'reason' => 'no_show_reversal_override',
                    'reversal_reason' => $reversal_reason,
                    'linked_no_show_event_id' => (int) ($confirmed_event['id'] ?? 0),
                    'linked_penalty_reversed_event_id' => $penalty_reversed_event_id,
                    'reversed_by_user_id' => $actor_user_id,
                    'source' => $source,
                    'timestamp' => current_time('mysql'),
                ],
                'created_by_user_id' => $actor_user_id,
            ]);
            if (is_wp_error($reinstated_event)) {
                return $reinstated_event;
            }
            $rewards_reinstated_override_event_id = (int) ($reinstated_event['event_id'] ?? 0);
        }

        $termination_reversed_event_id = 0;
        $access_restored = [
            'restored' => false,
            'user_id' => 0,
            'message' => '',
        ];
        if ($before_conduct_status === 'terminated' && $after_conduct_status !== 'terminated') {
            $access_restored = $this->restore_candidate_portal_access_for_rewards($candidate_id, [
                'actor_user_id' => $actor_user_id,
                'reason' => $reversal_reason,
                'conduct_status' => $after_conduct_status,
            ]);
            $termination_reversed_event = $this->insert_candidate_rewards_event([
                'candidate_id' => $candidate_id,
                'booking_id' => $booking_id,
                'shift_date' => $shift_date,
                'event_type' => 'termination_reversed',
                'delta_cycle' => 0,
                'delta_year_total' => 0,
                'meta' => [
                    'reason' => $reversal_reason,
                    'reversed_by_user_id' => $actor_user_id,
                    'source' => $source,
                    'timestamp' => current_time('mysql'),
                    'previous_conduct_status' => $before_conduct_status,
                    'new_conduct_status' => $after_conduct_status,
                    'access_restored' => !empty($access_restored['restored']) ? 1 : 0,
                    'restored_user_id' => (int) ($access_restored['user_id'] ?? 0),
                    'access_message' => sanitize_text_field((string) ($access_restored['message'] ?? '')),
                ],
                'created_by_user_id' => $actor_user_id,
            ]);
            if (is_wp_error($termination_reversed_event)) {
                return $termination_reversed_event;
            }
            $termination_reversed_event_id = (int) ($termination_reversed_event['event_id'] ?? 0);
        }

        $no_show_reversed_event = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'event_type' => 'no_show_reversed',
            'delta_cycle' => 0,
            'delta_year_total' => 0,
            'meta' => [
                'reversed_event_id' => (int) ($confirmed_event['id'] ?? 0),
                'linked_penalty_event_id' => (int) ($penalty_event['id'] ?? 0),
                'penalty_reversed_event_id' => $penalty_reversed_event_id,
                'penalty_found' => $penalty_found ? 1 : 0,
                'penalty_reversed' => ($penalty_reversal_applied || $penalty_already_reversed) ? 1 : 0,
                'reversal_reason' => $reversal_reason,
                'reversed_by_user_id' => $actor_user_id,
                'original_no_show_meta_snapshot' => $confirmed_meta_snapshot,
                'source' => $source,
                'academic_year' => $academic_year,
                'timestamp' => current_time('mysql'),
                'finance_manual_review_required' => $finance_review_required ? 1 : 0,
                'finance_warning' => $finance_warning,
            ],
            'created_by_user_id' => $actor_user_id,
        ]);
        if (is_wp_error($no_show_reversed_event)) {
            return $no_show_reversed_event;
        }
        if (empty($no_show_reversed_event['inserted'])) {
            return new WP_Error('cmn_no_show_reverse_duplicate', 'This no-show has already been reversed.');
        }

        $this->add_audit_log('candidate_no_show_reversed_override', 'booking', (string) $booking_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'academic_year' => $academic_year,
            'reason' => $reversal_reason,
            'actor_user_id' => $actor_user_id,
            'no_show_reversed_event_id' => (int) ($no_show_reversed_event['event_id'] ?? 0),
            'penalty_reversed_event_id' => $penalty_reversed_event_id,
            'penalty_found' => $penalty_found ? 1 : 0,
            'penalty_reversal_applied' => $penalty_reversal_applied ? 1 : 0,
            'penalty_already_reversed' => $penalty_already_reversed ? 1 : 0,
            'termination_reversed_event_id' => $termination_reversed_event_id,
            'finance_manual_review_required' => $finance_review_required ? 1 : 0,
        ], $actor_user_id);
        if ($penalty_found && !$penalty_reversal_applied && $penalty_already_reversed) {
            $this->add_audit_log('candidate_no_show_penalty_reverse_skipped', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'reason' => 'Penalty was already reversed.',
            ], $actor_user_id);
        } elseif (!$penalty_found) {
            $this->add_audit_log('candidate_no_show_penalty_reverse_skipped', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'reason' => 'No penalty_applied event found for this booking-day.',
            ], $actor_user_id);
        }
        if ($finance_review_required) {
            $this->add_audit_log('candidate_no_show_reverse_finance_review_required', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'reason' => $finance_warning,
            ], $actor_user_id);
        }
        if ($rewards_reinstated_override_event_id > 0) {
            $this->add_audit_log('candidate_rewards_reinstated_override', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'event_id' => $rewards_reinstated_override_event_id,
            ], $actor_user_id);
        }
        if ($termination_reversed_event_id > 0) {
            $this->add_audit_log('candidate_no_show_termination_reversed', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'event_id' => $termination_reversed_event_id,
                'access_restored' => !empty($access_restored['restored']) ? 1 : 0,
                'restored_user_id' => (int) ($access_restored['user_id'] ?? 0),
            ], $actor_user_id);
        }

        return [
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'academic_year' => $academic_year,
            'no_show_reversed_event_id' => (int) ($no_show_reversed_event['event_id'] ?? 0),
            'penalty_reversed_event_id' => $penalty_reversed_event_id,
            'penalty_found' => $penalty_found,
            'penalty_reversal_applied' => $penalty_reversal_applied,
            'penalty_already_reversed' => $penalty_already_reversed,
            'rewards_reinstated_override_event_id' => $rewards_reinstated_override_event_id,
            'termination_reversed_event_id' => $termination_reversed_event_id,
            'access_restored' => $access_restored,
            'before' => [
                'shift_cycle_count' => $before_cycle_count,
                'no_show_count' => $before_no_show_count,
                'conduct_status' => $before_conduct_status,
                'rewards_paused' => $before_rewards_paused,
            ],
            'after' => [
                'shift_cycle_count' => $after_cycle_count,
                'no_show_count' => $after_no_show_count,
                'conduct_status' => $after_conduct_status,
                'rewards_paused' => $after_rewards_paused,
            ],
            'finance_manual_review_required' => $finance_review_required,
            'finance_warning' => $finance_warning,
        ];
    }

    private function apply_candidate_no_show_penalty($candidate_id, $booking_id, $shift_date, $context = []) {
        $candidate_id = (int) $candidate_id;
        $booking_id = (int) $booking_id;
        $shift_date = $this->normalize_invoice_date((string) $shift_date);
        $context = is_array($context) ? $context : [];
        if ($candidate_id < 1 || $booking_id < 1 || $shift_date === '') {
            return new WP_Error('cmn_no_show_penalty_invalid_input', 'Candidate, booking, and shift date are required for no-show penalty.');
        }
        if ($this->is_candidate_rewards_august_shift_date($shift_date)) {
            return new WP_Error('cmn_no_show_penalty_august_excluded', 'August booking-days are excluded from candidate rewards penalties.');
        }

        $assessment = $this->assess_candidate_no_show_day($candidate_id, $booking_id, $shift_date);
        if (is_wp_error($assessment)) {
            return $assessment;
        }

        $confirmed_event = $this->get_candidate_rewards_event_row($candidate_id, $booking_id, $shift_date, 'no_show_confirmed');
        if (!$confirmed_event) {
            return new WP_Error('cmn_no_show_penalty_missing_confirmation', 'No-show must be confirmed before penalty is applied.');
        }

        $academic_year = function_exists('cmn_get_academic_year_label')
            ? (string) cmn_get_academic_year_label($shift_date)
            : (string) $this->get_academic_year_label($shift_date);
        $rewards_row = $this->get_or_create_candidate_rewards($candidate_id, $academic_year);
        if (is_wp_error($rewards_row)) {
            return $rewards_row;
        }

        $applied_by_user_id = (int) ($context['applied_by_user_id'] ?? get_current_user_id());
        $source = sanitize_key((string) ($context['source'] ?? 'no_show_confirmation'));
        if ($source === '') {
            $source = 'no_show_confirmation';
        }
        $confirmation_reason = sanitize_textarea_field((string) ($context['confirmation_reason'] ?? ''));
        $evidence_notes = sanitize_textarea_field((string) ($context['evidence_notes'] ?? ''));

        $probation_reset = $this->maybe_reset_candidate_probation_on_no_show(
            $candidate_id,
            $booking_id,
            $shift_date,
            $academic_year,
            $rewards_row,
            [
                'source' => $source,
                'created_by_user_id' => $applied_by_user_id,
            ]
        );
        if (is_wp_error($probation_reset)) {
            return $probation_reset;
        }
        if (!empty($probation_reset['reset'])) {
            $reloaded_rewards = $this->get_candidate_rewards_record($candidate_id, $academic_year);
            if ($reloaded_rewards) {
                $rewards_row = $reloaded_rewards;
            }
        }

        $penalty_event = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'event_type' => 'penalty_applied',
            'delta_cycle' => -3,
            'delta_year_total' => 0,
            'meta' => [
                'reason' => 'no_show_penalty',
                'linked_event' => 'no_show_confirmed',
                'linked_event_id' => (int) ($confirmed_event['id'] ?? 0),
                'applied_by_user_id' => $applied_by_user_id,
                'source' => $source,
                'confirmation_reason' => $confirmation_reason,
                'evidence_notes' => $evidence_notes,
                'policy_guidance' => $this->get_candidate_no_show_policy_guidance_text(),
                'probation_reset_event_id' => (int) ($probation_reset['event_id'] ?? 0),
                'probation_reset_applied' => !empty($probation_reset['reset']),
            ],
            'created_by_user_id' => $applied_by_user_id,
        ]);
        if (is_wp_error($penalty_event)) {
            return $penalty_event;
        }
        if (empty($penalty_event['inserted'])) {
            return [
                'applied' => false,
                'duplicate' => true,
                'candidate_id' => $candidate_id,
                'booking_id' => $booking_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'event_id' => (int) ($penalty_event['event_id'] ?? 0),
                'no_show_count' => max(0, (int) ($rewards_row['no_show_count'] ?? 0)),
                'conduct_status' => sanitize_key((string) ($rewards_row['conduct_status'] ?? 'clear')),
                'rewards_paused' => !empty($rewards_row['rewards_paused']) ? 1 : 0,
                'review_required' => !empty($rewards_row['review_required']) ? 1 : 0,
                'terminated' => sanitize_key((string) ($rewards_row['conduct_status'] ?? '')) === 'terminated',
            ];
        }

        global $wpdb;
        $table = $this->get_candidate_rewards_table();
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$table}
             SET shift_cycle_count = shift_cycle_count - 3,
                 no_show_count = GREATEST(0, no_show_count + 1),
                 updated_at = %s
             WHERE candidate_id = %d
               AND academic_year = %s",
            current_time('mysql'),
            $candidate_id,
            $academic_year
        ));
        if ($updated === false) {
            return new WP_Error('cmn_no_show_penalty_update_failed', 'Unable to apply candidate no-show penalty.');
        }

        $after_increment = $this->get_candidate_rewards_record($candidate_id, $academic_year);
        if (!$after_increment) {
            return new WP_Error('cmn_no_show_penalty_missing_rewards_row', 'Candidate rewards row was not available after penalty update.');
        }
        $no_show_count = max(0, (int) ($after_increment['no_show_count'] ?? 0));
        $escalation_status = 'yellow';
        $review_required = 0;
        if ($no_show_count >= 3) {
            $escalation_status = 'terminated';
            $review_required = 1;
        } elseif ($no_show_count >= 2) {
            $escalation_status = 'red';
            $review_required = 1;
        }

        $rewards_row = $this->update_candidate_rewards_record($candidate_id, $academic_year, [
            'conduct_status' => $escalation_status,
            'rewards_paused' => 1,
            'review_required' => $review_required,
            'probation_consecutive_shifts' => 0,
        ]);
        if (is_wp_error($rewards_row)) {
            return $rewards_row;
        }

        $review_event_id = 0;
        if ($no_show_count === 2) {
            $review_event = $this->insert_candidate_rewards_event([
                'candidate_id' => $candidate_id,
                'booking_id' => $booking_id,
                'shift_date' => $shift_date,
                'event_type' => 'review_required',
                'delta_cycle' => 0,
                'delta_year_total' => 0,
                'meta' => [
                    'reason' => 'second_no_show',
                    'no_show_count' => $no_show_count,
                    'policy_guidance' => $this->get_candidate_no_show_policy_guidance_text(),
                ],
                'created_by_user_id' => $applied_by_user_id,
            ]);
            if (is_wp_error($review_event)) {
                $this->add_audit_log('candidate_no_show_review_event_failed', 'booking', (string) $booking_id, [
                    'candidate_id' => $candidate_id,
                    'shift_date' => $shift_date,
                    'message' => $review_event->get_error_message(),
                ]);
            } else {
                $review_event_id = (int) ($review_event['event_id'] ?? 0);
            }
        }

        $termination_event_id = 0;
        $termination_access = [
            'disabled' => false,
            'user_id' => 0,
            'message' => '',
        ];
        if ($no_show_count >= 3) {
            $termination_access = $this->disable_candidate_portal_access_for_rewards($candidate_id, [
                'actor_user_id' => $applied_by_user_id,
                'reason' => 'Terminated from portal access after third confirmed no-show.',
            ]);
            $terminated_event = $this->insert_candidate_rewards_event([
                'candidate_id' => $candidate_id,
                'booking_id' => $booking_id,
                'shift_date' => $shift_date,
                'event_type' => 'candidate_terminated',
                'delta_cycle' => 0,
                'delta_year_total' => 0,
                'meta' => [
                    'reason' => 'third_no_show',
                    'no_show_count' => $no_show_count,
                    'access_disabled' => !empty($termination_access['disabled']),
                    'disabled_user_id' => (int) ($termination_access['user_id'] ?? 0),
                    'disable_message' => (string) ($termination_access['message'] ?? ''),
                    'policy_guidance' => $this->get_candidate_no_show_policy_guidance_text(),
                ],
                'created_by_user_id' => $applied_by_user_id,
            ]);
            if (is_wp_error($terminated_event)) {
                $this->add_audit_log('candidate_no_show_terminated_event_failed', 'booking', (string) $booking_id, [
                    'candidate_id' => $candidate_id,
                    'shift_date' => $shift_date,
                    'message' => $terminated_event->get_error_message(),
                ]);
            } else {
                $termination_event_id = (int) ($terminated_event['event_id'] ?? 0);
            }
            if (empty($termination_access['disabled'])) {
                $this->add_audit_log('candidate_no_show_termination_access_disable_failed', 'booking', (string) $booking_id, [
                    'candidate_id' => $candidate_id,
                    'shift_date' => $shift_date,
                    'message' => (string) ($termination_access['message'] ?? 'Unable to disable candidate portal access.'),
                ]);
            }
        }

        $this->add_audit_log('candidate_no_show_penalty_applied', 'booking', (string) $booking_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'academic_year' => $academic_year,
            'delta_cycle' => -3,
            'no_show_count' => $no_show_count,
            'conduct_status' => $escalation_status,
            'review_required' => $review_required,
            'terminated' => $no_show_count >= 3 ? 1 : 0,
            'event_id' => (int) ($penalty_event['event_id'] ?? 0),
            'probation_reset' => !empty($probation_reset['reset']) ? 1 : 0,
            'probation_reset_event_id' => (int) ($probation_reset['event_id'] ?? 0),
        ]);
        if ($no_show_count === 2) {
            $this->add_audit_log('candidate_no_show_review_required', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'no_show_count' => $no_show_count,
                'review_event_id' => $review_event_id,
            ]);
        }
        if ($no_show_count >= 3) {
            $this->add_audit_log('candidate_no_show_terminated', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'academic_year' => $academic_year,
                'no_show_count' => $no_show_count,
                'termination_event_id' => $termination_event_id,
                'access_disabled' => !empty($termination_access['disabled']) ? 1 : 0,
            ]);
        }

        return [
            'applied' => true,
            'duplicate' => false,
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'academic_year' => $academic_year,
            'event_id' => (int) ($penalty_event['event_id'] ?? 0),
            'no_show_count' => $no_show_count,
            'conduct_status' => sanitize_key((string) ($rewards_row['conduct_status'] ?? $escalation_status)),
            'rewards_paused' => !empty($rewards_row['rewards_paused']) ? 1 : 0,
            'review_required' => !empty($rewards_row['review_required']) ? 1 : 0,
            'terminated' => sanitize_key((string) ($rewards_row['conduct_status'] ?? $escalation_status)) === 'terminated',
            'review_event_id' => $review_event_id,
            'termination_event_id' => $termination_event_id,
            'access_disabled' => !empty($termination_access['disabled']),
            'access_disabled_user_id' => (int) ($termination_access['user_id'] ?? 0),
        ];
    }

    private function build_candidate_no_show_penalty_message($result, $already_confirmed = false) {
        $result = is_array($result) ? $result : [];
        $no_show_count = max(0, (int) ($result['no_show_count'] ?? 0));
        $prefix = $already_confirmed
            ? 'No-show already confirmed for this booking-day.'
            : 'No-show confirmed.';
        if (empty($result['applied'])) {
            return $prefix . ' Penalty already applied.';
        }
        if (!empty($result['terminated'])) {
            $access_msg = !empty($result['access_disabled']) ? ' Portal access disabled.' : ' Portal access disable is pending staff follow-up.';
            return $prefix . ' Penalty applied (-3 shifts). Conduct status is now terminated.' . $access_msg . ' No-shows this academic year: ' . $no_show_count . '.';
        }
        if (!empty($result['review_required'])) {
            return $prefix . ' Penalty applied (-3 shifts). Conduct status is now red and senior review is required. No-shows this academic year: ' . $no_show_count . '.';
        }
        return $prefix . ' Penalty applied (-3 shifts). Conduct status is yellow and rewards are paused pending probation. No-shows this academic year: ' . $no_show_count . '.';
    }

    private function get_booking_message_attachments($message_row) {
        $ids = [];
        if (!empty($message_row['attachment_ids'])) {
            $decoded = json_decode((string) $message_row['attachment_ids'], true);
            if (is_array($decoded)) {
                foreach ($decoded as $id) {
                    $id = (int) $id;
                    if ($id > 0) {
                        $ids[] = $id;
                    }
                }
            }
        }
        $attachments = [];
        foreach ($ids as $id) {
            $url = wp_get_attachment_url($id);
            if (!$url) {
                continue;
            }
            $path = get_attached_file($id);
            $attachments[] = [
                'id' => $id,
                'filename' => $path ? basename($path) : ('Attachment #' . $id),
                'url' => esc_url_raw($url),
            ];
        }
        return $attachments;
    }

    private function get_booking_service_date($booking_id) {
        $booking_id = (int) $booking_id;
        if (!$booking_id) {
            return '';
        }
        $date = trim((string) get_post_meta($booking_id, 'cmn_date', true));
        if ($date === '') {
            $date = trim((string) get_post_meta($booking_id, 'cmn_start_date', true));
        }
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
            return '';
        }
        return $date;
    }

    private function get_booking_candidate_user_id($booking_id) {
        $booking_id = (int) $booking_id;
        if (!$booking_id) {
            return 0;
        }
        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if (!$candidate_id) {
            return 0;
        }
        return (int) $this->get_candidate_user_id($candidate_id);
    }

    private function get_booking_school_user_id($booking_id) {
        $booking_id = (int) $booking_id;
        if (!$booking_id) {
            return 0;
        }
        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        $request_id = (int) get_post_meta($booking_id, 'cmn_request_id', true);
        if ($request_id) {
            $request = $this->get_candidate_request_by_id($request_id);
            if ($request) {
                return (int) $this->get_school_user_id_for_request($request, $school_id);
            }
        }
        if (!$school_id) {
            return 0;
        }
        $contact_email = $this->get_school_primary_contact_email($school_id);
        if (!$contact_email) {
            return 0;
        }
        $user = get_user_by('email', $contact_email);
        return $user ? (int) $user->ID : 0;
    }

    private function get_booking_feedback_role_for_user($user_id = 0) {
        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        if (!$user_id) {
            return '';
        }
        if ($this->is_admin_user($user_id) || $this->is_account_manager_user($user_id) || $this->is_staff_role($user_id)) {
            return 'staff';
        }
        if ($this->is_candidate_user($user_id)) {
            return 'candidate';
        }
        if ($this->is_school_user($user_id)) {
            return 'school';
        }
        return '';
    }

    private function user_can_access_booking_feedback($booking_id, $user_id, $viewer_role = '') {
        $booking_id = (int) $booking_id;
        $user_id = (int) $user_id;
        if (!$booking_id || !$user_id) {
            return false;
        }
        $viewer_role = $viewer_role !== '' ? $viewer_role : $this->get_booking_feedback_role_for_user($user_id);
        if ($viewer_role === 'staff') {
            return true;
        }
        $details_thread = $this->get_booking_thread_by_booking($booking_id, 'booking_details');
        if ($details_thread && $this->user_can_access_booking_thread((int) ($details_thread['id'] ?? 0), $user_id)) {
            return true;
        }
        if ($viewer_role === 'candidate') {
            return (int) $this->get_booking_candidate_user_id($booking_id) === $user_id;
        }
        if ($viewer_role === 'school') {
            return (int) $this->get_booking_school_user_id($booking_id) === $user_id;
        }
        return false;
    }

    private function is_booking_feedback_eligible($booking_id, $status = '') {
        $booking_id = (int) $booking_id;
        if (!$booking_id) {
            return false;
        }
        $status = $status !== '' ? sanitize_key($status) : sanitize_key((string) get_post_meta($booking_id, 'cmn_status', true));
        if ($status === 'completed') {
            return true;
        }
        if (in_array($status, ['declined', 'cancelled', 'expired', 'candidate_declined'], true)) {
            return false;
        }
        $booking_date = $this->get_booking_service_date($booking_id);
        if ($booking_date === '') {
            return false;
        }
        $today = current_time('Y-m-d');
        return $booking_date < $today;
    }

    private function get_candidate_feedback_module_fields() {
        return [
            'score_punctuality' => 'Punctuality',
            'score_classroom_management' => 'Classroom Management',
            'score_professionalism' => 'Professionalism',
            'score_communication' => 'Communication',
            'score_adaptability' => 'Adaptability',
            'score_lesson_delivery' => 'Lesson Delivery / Engagement',
            'score_safeguarding' => 'Safeguarding Awareness',
        ];
    }

    private function is_school_candidate_feedback_eligible($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking') {
            return false;
        }

        $status = sanitize_key((string) get_post_meta($booking_id, 'cmn_status', true));
        if ($status === 'completed') {
            return true;
        }

        global $wpdb;
        $confirmation_table = self::get_booking_completion_confirmations_table_name();
        if (!self::table_exists($confirmation_table) || !self::table_has_column($confirmation_table, 'booking_id')) {
            return false;
        }

        $confirmed_count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(1)
             FROM {$confirmation_table}
             WHERE booking_id = %d
               AND status IN ('confirmed','auto_confirmed')",
            $booking_id
        ));
        return $confirmed_count > 0;
    }

    private function get_candidate_feedback_row_by_booking($booking_id, $candidate_user_id = 0) {
        global $wpdb;
        $table = $this->get_candidate_feedback_table();
        $booking_id = (int) $booking_id;
        if ($booking_id < 1 || !self::table_exists($table)) {
            return [];
        }

        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id > 0) {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM {$table}
                 WHERE booking_id = %d
                   AND candidate_user_id = %d
                 LIMIT 1",
                $booking_id,
                $candidate_user_id
            ), ARRAY_A);
        } else {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM {$table}
                 WHERE booking_id = %d
                 LIMIT 1",
                $booking_id
            ), ARRAY_A);
        }
        return is_array($row) ? $row : [];
    }

    private function school_has_submitted_candidate_feedback($booking_id, $school_user_id = 0) {
        $booking_id = (int) $booking_id;
        $school_user_id = $school_user_id > 0 ? (int) $school_user_id : (int) get_current_user_id();
        if ($booking_id < 1 || $school_user_id < 1) {
            return false;
        }
        $row = $this->get_candidate_feedback_row_by_booking($booking_id);
        if (!$row) {
            return false;
        }
        return (int) ($row['school_user_id'] ?? 0) === $school_user_id;
    }

    private function format_candidate_feedback_row($row) {
        $row = is_array($row) ? $row : [];
        $module_fields = $this->get_candidate_feedback_module_fields();
        $module_scores = [];
        foreach ($module_fields as $field => $label) {
            $module_scores[] = [
                'field' => $field,
                'label' => $label,
                'score' => max(1, min(5, (int) ($row[$field] ?? 0))),
            ];
        }

        return [
            'id' => (int) ($row['id'] ?? 0),
            'booking_id' => (int) ($row['booking_id'] ?? 0),
            'school_user_id' => (int) ($row['school_user_id'] ?? 0),
            'candidate_user_id' => (int) ($row['candidate_user_id'] ?? 0),
            'average_rating' => round((float) ($row['average_rating'] ?? 0), 2),
            'comments' => sanitize_textarea_field((string) ($row['comments'] ?? '')),
            'created_at' => sanitize_text_field((string) ($row['created_at'] ?? '')),
            'updated_at' => sanitize_text_field((string) ($row['updated_at'] ?? '')),
            'module_scores' => $module_scores,
        ];
    }

    private function upsert_candidate_rating_stats($candidate_user_id) {
        global $wpdb;
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return false;
        }

        $feedback_table = $this->get_candidate_feedback_table();
        $stats_table = $this->get_candidate_rating_stats_table();
        if (!self::table_exists($feedback_table) || !self::table_exists($stats_table)) {
            return false;
        }

        $aggregate = $wpdb->get_row($wpdb->prepare(
            "SELECT AVG(average_rating) AS avg_rating, COUNT(1) AS feedback_count
             FROM {$feedback_table}
             WHERE candidate_user_id = %d",
            $candidate_user_id
        ), ARRAY_A);

        $avg_rating = round((float) ($aggregate['avg_rating'] ?? 0), 2);
        $feedback_count = max(0, (int) ($aggregate['feedback_count'] ?? 0));
        $wpdb->replace($stats_table, [
            'candidate_user_id' => $candidate_user_id,
            'avg_rating' => $avg_rating,
            'feedback_count' => $feedback_count,
            'updated_at' => current_time('mysql'),
        ], ['%d', '%f', '%d', '%s']);

        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        if ($candidate_id > 0) {
            update_post_meta($candidate_id, 'cmn_candidate_avg_rating', $avg_rating);
            update_post_meta($candidate_id, 'cmn_candidate_feedback_count', $feedback_count);
        }
        update_user_meta($candidate_user_id, 'cmn_candidate_avg_rating', $avg_rating);
        update_user_meta($candidate_user_id, 'cmn_candidate_feedback_count', $feedback_count);
        return true;
    }

    private function get_candidate_average_rating_payload($candidate_user_id) {
        static $cache = [];
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return [
                'avg_rating' => 0.0,
                'avg_rating_raw' => 0.0,
                'feedback_count' => 0,
            ];
        }
        if (isset($cache[$candidate_user_id])) {
            return $cache[$candidate_user_id];
        }

        global $wpdb;
        $avg_rating = 0.0;
        $feedback_count = 0;
        $stats_table = $this->get_candidate_rating_stats_table();
        if (self::table_exists($stats_table)) {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT avg_rating, feedback_count
                 FROM {$stats_table}
                 WHERE candidate_user_id = %d
                 LIMIT 1",
                $candidate_user_id
            ), ARRAY_A);
            if (is_array($row)) {
                $avg_rating = (float) ($row['avg_rating'] ?? 0);
                $feedback_count = max(0, (int) ($row['feedback_count'] ?? 0));
            }
        }

        if ($feedback_count < 1) {
            $feedback_table = $this->get_candidate_feedback_table();
            if (self::table_exists($feedback_table)) {
                $aggregate = $wpdb->get_row($wpdb->prepare(
                    "SELECT AVG(average_rating) AS avg_rating, COUNT(1) AS feedback_count
                     FROM {$feedback_table}
                     WHERE candidate_user_id = %d",
                    $candidate_user_id
                ), ARRAY_A);
                if (is_array($aggregate)) {
                    $avg_rating = (float) ($aggregate['avg_rating'] ?? 0);
                    $feedback_count = max(0, (int) ($aggregate['feedback_count'] ?? 0));
                }
            }
        }

        if ($avg_rating < 0) {
            $avg_rating = 0.0;
        } elseif ($avg_rating > 5) {
            $avg_rating = 5.0;
        }

        $cache[$candidate_user_id] = [
            'avg_rating' => round($avg_rating, 1),
            'avg_rating_raw' => round($avg_rating, 2),
            'feedback_count' => $feedback_count,
        ];
        return $cache[$candidate_user_id];
    }

    public function cmn_get_candidate_average_rating($candidate_user_id) {
        return $this->get_candidate_average_rating_payload((int) $candidate_user_id);
    }

    private function get_candidate_feedback_entries_for_candidate_user($candidate_user_id, $limit = 100) {
        global $wpdb;
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return [];
        }
        $table = $this->get_candidate_feedback_table();
        if (!self::table_exists($table)) {
            return [];
        }
        $limit = max(1, min(500, (int) $limit));
        return (array) $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_user_id = %d
             ORDER BY created_at DESC, id DESC
             LIMIT %d",
            $candidate_user_id,
            $limit
        ), ARRAY_A);
    }

    private function get_candidate_feedback_breakdown_for_candidate_user($candidate_user_id) {
        global $wpdb;
        $candidate_user_id = (int) $candidate_user_id;
        $module_fields = $this->get_candidate_feedback_module_fields();
        $empty = [];
        foreach ($module_fields as $field => $label) {
            $empty[] = [
                'field' => $field,
                'label' => $label,
                'average' => 0.0,
            ];
        }
        if ($candidate_user_id < 1) {
            return $empty;
        }

        $table = $this->get_candidate_feedback_table();
        if (!self::table_exists($table)) {
            return $empty;
        }

        $select_parts = [];
        foreach ($module_fields as $field => $label) {
            $select_parts[] = "AVG({$field}) AS {$field}";
        }
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT " . implode(', ', $select_parts) . "
             FROM {$table}
             WHERE candidate_user_id = %d",
            $candidate_user_id
        ), ARRAY_A);
        if (!is_array($row)) {
            return $empty;
        }

        $out = [];
        foreach ($module_fields as $field => $label) {
            $out[] = [
                'field' => $field,
                'label' => $label,
                'average' => round((float) ($row[$field] ?? 0), 1),
            ];
        }
        return $out;
    }

    private function get_school_user_label_for_feedback($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return 'School';
        }
        $school_id = (int) $this->resolve_school_id_for_user($school_user_id);
        if ($school_id > 0) {
            $school_title = trim((string) get_the_title($school_id));
            if ($school_title !== '') {
                return $school_title;
            }
        }
        $user = get_user_by('id', $school_user_id);
        if ($user instanceof WP_User) {
            $display = trim((string) $user->display_name);
            if ($display !== '') {
                return $display;
            }
        }
        return 'School';
    }

    private function get_school_candidate_feedback_payload($booking_id, $viewer_user_id) {
        $booking_id = (int) $booking_id;
        $viewer_user_id = (int) $viewer_user_id;
        $candidate_user_id = (int) $this->get_booking_candidate_user_id($booking_id);
        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        $existing = $this->get_candidate_feedback_row_by_booking($booking_id, $candidate_user_id);
        $viewer_feedback = $existing ? $this->format_candidate_feedback_row($existing) : null;

        return [
            'booking_id' => $booking_id,
            'booking_status' => (string) get_post_meta($booking_id, 'cmn_status', true),
            'booking_date' => $this->get_booking_service_date($booking_id),
            'eligible' => $this->is_school_candidate_feedback_eligible($booking_id),
            'viewer_role' => 'school',
            'requires_feedback' => !$viewer_feedback,
            'viewer_feedback' => $viewer_feedback,
            'counterparty_feedback' => null,
            'feedback_rows' => [],
            'form' => [
                'star_fields' => array_keys($this->get_candidate_feedback_module_fields()),
                'star_labels' => $this->get_candidate_feedback_module_fields(),
                'show_would_rebook' => false,
                'tags' => [],
                'submit_label' => 'Submit feedback',
            ],
            'candidate_name' => $candidate_id > 0 ? (string) get_the_title($candidate_id) : 'Candidate',
            'school_name' => $school_id > 0 ? (string) get_the_title($school_id) : 'School',
        ];
    }

    private function maybe_request_school_candidate_feedback_prompt($booking_id, $force = false) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1) {
            return;
        }
        if (!$force && !$this->is_school_candidate_feedback_eligible($booking_id)) {
            return;
        }
        if (get_post_meta($booking_id, 'cmn_candidate_feedback_requested_at', true)) {
            return;
        }

        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        $candidate_name = $candidate_id > 0 ? (string) get_the_title($candidate_id) : 'Candidate';
        $school_name = $school_id > 0 ? (string) get_the_title($school_id) : 'School';
        $school_user_id = (int) $this->get_booking_school_user_id($booking_id);
        $feedback_link = add_query_arg([
            'school' => 'requests',
            'cmn_booking_chat' => $booking_id,
            'cmn_thread_type' => 'booking_details',
            'cmn_feedback_prompt' => '1',
        ], $this->get_portal_base_url());

        if ($school_user_id > 0) {
            $this->add_notification(
                $school_user_id,
                'candidate_feedback_request',
                'Rate your booking - help maintain quality and unlock partner benefits.',
                'Please rate candidate ' . $candidate_name . ' for this completed booking.',
                $feedback_link
            );

            $school_user = get_user_by('id', $school_user_id);
            $to_email = $school_user instanceof WP_User ? sanitize_email((string) $school_user->user_email) : '';
            if ($to_email !== '' && is_email($to_email)) {
                $booking_date = $this->get_booking_service_date($booking_id);
                $booking_role = trim((string) get_post_meta($booking_id, 'cmn_role', true));
                cmn_send_email('school_candidate_feedback_request', $to_email, [
                    'school_name' => $school_name,
                    'candidate_name' => $candidate_name,
                    'booking_date' => $booking_date !== '' ? date_i18n('l j M Y', strtotime($booking_date)) : '',
                    'booking_role' => $booking_role,
                    'portal_link' => $feedback_link,
                    'company_name' => 'CoverMeNow ONE',
                ], [
                    'module' => 'feedback',
                    'recipient_role' => 'school',
                    'related_entity_type' => 'booking',
                    'related_entity_id' => $booking_id,
                    'recipient_user_id' => $school_user_id,
                ]);
            }
        }

        update_post_meta($booking_id, 'cmn_candidate_feedback_requested_at', current_time('mysql'));
    }

    private function get_booking_chat_link_for_role($booking_id, $role = 'candidate') {
        $booking_id = (int) $booking_id;
        if (!$booking_id) {
            return $this->get_portal_base_url();
        }
        $params = [
            'cmn_booking_chat' => $booking_id,
            'cmn_thread_type' => 'booking_details',
            'cmn_feedback_prompt' => '1',
        ];
        if ($role === 'school') {
            $params['school'] = 'requests';
        } elseif ($role === 'candidate') {
            $params['candidate'] = 'bookings';
        } else {
            $params['view'] = 'requests';
        }
        return add_query_arg($params, $this->get_portal_base_url());
    }

    private function maybe_request_booking_feedback_notifications($booking_id, $force = false) {
        $booking_id = (int) $booking_id;
        if (!$booking_id) {
            return;
        }
        $this->maybe_request_school_candidate_feedback_prompt($booking_id, $force);
        if (!$force && !$this->is_booking_feedback_eligible($booking_id)) {
            return;
        }
        if (get_post_meta($booking_id, 'cmn_feedback_requested_at', true)) {
            return;
        }
        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        $candidate_name = $candidate_id ? (string) get_the_title($candidate_id) : 'Candidate';
        $school_name = $school_id ? (string) get_the_title($school_id) : 'School';
        $candidate_user_id = (int) $this->get_booking_candidate_user_id($booking_id);
        $school_user_id = (int) $this->get_booking_school_user_id($booking_id);
        if ($school_user_id) {
            $this->add_notification(
                $school_user_id,
                'feedback_request_school',
                'Feedback requested: Candidate ' . $candidate_name,
                'Please rate ' . $candidate_name . ' for this completed booking.',
                $this->get_booking_chat_link_for_role($booking_id, 'school')
            );
        }
        if ($candidate_user_id) {
            $this->add_notification(
                $candidate_user_id,
                'feedback_request_candidate',
                'Feedback requested: Booking with ' . $school_name,
                'Please rate your completed booking with ' . $school_name . '.',
                $this->get_booking_chat_link_for_role($booking_id, 'candidate')
            );
        }
        update_post_meta($booking_id, 'cmn_feedback_requested_at', current_time('mysql'));
    }

    private function maybe_request_feedback_for_past_bookings($limit = 150) {
        $booking_ids = get_posts([
            'post_type' => 'cmn_booking',
            'posts_per_page' => max(10, (int) $limit),
            'fields' => 'ids',
            'orderby' => 'date',
            'order' => 'DESC',
        ]);
        foreach ((array) $booking_ids as $booking_id) {
            if (get_post_meta((int) $booking_id, 'cmn_feedback_requested_at', true)) {
                continue;
            }
            if (!$this->is_booking_feedback_eligible((int) $booking_id)) {
                continue;
            }
            $this->maybe_request_booking_feedback_notifications((int) $booking_id);
        }
    }

    private function get_booking_feedback_tag_options($viewer_role) {
        if ($viewer_role === 'candidate') {
            return [
                'Friendly staff',
                'Clear timetable',
                'Behaviour well managed',
                'Good handover',
                'Poor instructions',
                'Behaviour issues',
                'No support on arrival',
            ];
        }
        return [
            'Great communicator',
            'Calm under pressure',
            'Followed instructions',
            'Would rebook',
            'Late arrival',
            'Poor communication',
            'Unprepared',
        ];
    }

    private function sanitize_booking_feedback_tags($raw_tags, $viewer_role) {
        $allowed = $this->get_booking_feedback_tag_options($viewer_role);
        $allowed_map = array_fill_keys($allowed, true);
        $incoming = [];
        if (is_string($raw_tags)) {
            $decoded = json_decode($raw_tags, true);
            if (is_array($decoded)) {
                $incoming = $decoded;
            } else {
                $incoming = array_filter(array_map('trim', explode(',', $raw_tags)));
            }
        } elseif (is_array($raw_tags)) {
            $incoming = $raw_tags;
        }
        $clean = [];
        foreach ($incoming as $tag) {
            $tag = sanitize_text_field((string) $tag);
            if ($tag === '' || !isset($allowed_map[$tag])) {
                continue;
            }
            $clean[$tag] = $tag;
        }
        return array_values($clean);
    }

    private function get_booking_feedback_rows($booking_id) {
        global $wpdb;
        $table = $this->get_booking_feedback_table();
        return (array) $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE booking_id = %d ORDER BY created_at DESC, id DESC",
            (int) $booking_id
        ), ARRAY_A);
    }

    private function format_booking_feedback_row($row, $viewer_user_id, $viewer_role, $is_owner_feedback) {
        $viewer_user_id = (int) $viewer_user_id;
        $is_staff_view = $viewer_role === 'staff';
        $raw_tags = [];
        if (!empty($row['tags'])) {
            $decoded_tags = json_decode((string) $row['tags'], true);
            if (is_array($decoded_tags)) {
                foreach ($decoded_tags as $tag) {
                    $tag = sanitize_text_field((string) $tag);
                    if ($tag !== '') {
                        $raw_tags[] = $tag;
                    }
                }
            }
        }
        $show_comment = $is_staff_view || $is_owner_feedback;
        return [
            'id' => (int) ($row['id'] ?? 0),
            'booking_id' => (int) ($row['booking_id'] ?? 0),
            'rater_user_id' => (int) ($row['rater_user_id'] ?? 0),
            'rated_entity_type' => (string) ($row['rated_entity_type'] ?? ''),
            'rated_entity_id' => (int) ($row['rated_entity_id'] ?? 0),
            'stars_overall' => (int) ($row['stars_overall'] ?? 0),
            'stars_1' => $is_staff_view || $is_owner_feedback ? (int) ($row['stars_1'] ?? 0) : 0,
            'stars_2' => $is_staff_view || $is_owner_feedback ? (int) ($row['stars_2'] ?? 0) : 0,
            'stars_3' => $is_staff_view || $is_owner_feedback ? (int) ($row['stars_3'] ?? 0) : 0,
            'tags' => $raw_tags,
            'would_rebook' => $is_staff_view || $is_owner_feedback ? (isset($row['would_rebook']) && $row['would_rebook'] !== null ? (int) $row['would_rebook'] : null) : null,
            'comment' => $show_comment ? (string) ($row['comment'] ?? '') : '',
            'comment_hidden' => !$show_comment && !empty($row['comment']),
            'created_at' => (string) ($row['created_at'] ?? ''),
            'is_low_rating' => (int) ($row['stars_overall'] ?? 0) <= 2,
        ];
    }

    private function get_school_feedback_third_metric_label($booking_id) {
        $role = strtolower((string) get_post_meta((int) $booking_id, 'cmn_role', true));
        if ($role === '') {
            return 'Classroom management';
        }
        if (strpos($role, 'teaching assistant') !== false || strpos($role, 'ta') !== false) {
            return 'Engagement';
        }
        if (strpos($role, 'teacher') !== false || strpos($role, 'class') !== false) {
            return 'Classroom management';
        }
        return 'Classroom management / engagement';
    }

    private function get_booking_feedback_form_config($booking_id, $viewer_role) {
        if ($viewer_role === 'candidate') {
            return [
                'star_labels' => [
                    'stars_1' => 'Check-in/Reception',
                    'stars_2' => 'Clarity of Instructions',
                    'stars_3' => 'Support On-site',
                    'stars_overall' => 'Overall',
                ],
                'show_would_rebook' => true,
                'tags' => $this->get_booking_feedback_tag_options('candidate'),
                'submit_label' => 'Submit feedback',
            ];
        }
        return [
            'star_labels' => [
                'stars_1' => 'Punctuality',
                'stars_2' => 'Professionalism',
                'stars_3' => $this->get_school_feedback_third_metric_label($booking_id),
                'stars_overall' => 'Overall',
            ],
            'show_would_rebook' => false,
            'tags' => $this->get_booking_feedback_tag_options('school'),
            'submit_label' => 'Submit feedback',
        ];
    }

    private function get_booking_feedback_payload($booking_id, $viewer_user_id, $viewer_role = '') {
        $booking_id = (int) $booking_id;
        $viewer_user_id = (int) $viewer_user_id;
        $viewer_role = $viewer_role !== '' ? $viewer_role : $this->get_booking_feedback_role_for_user($viewer_user_id);
        $rows = $this->get_booking_feedback_rows($booking_id);
        $viewer_feedback = null;
        $counterparty_feedback = null;
        $staff_rows = [];
        foreach ($rows as $row) {
            $is_owner = (int) ($row['rater_user_id'] ?? 0) === $viewer_user_id;
            $formatted = $this->format_booking_feedback_row($row, $viewer_user_id, $viewer_role, $is_owner);
            if ($viewer_role === 'staff') {
                $staff_rows[] = $formatted;
                continue;
            }
            if ($is_owner) {
                $viewer_feedback = $formatted;
            } elseif ($counterparty_feedback === null) {
                $counterparty_feedback = $formatted;
            }
        }
        $eligible = $this->is_booking_feedback_eligible($booking_id);
        $requires_feedback = in_array($viewer_role, ['candidate', 'school'], true) && $eligible && !$viewer_feedback;
        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        return [
            'booking_id' => $booking_id,
            'booking_status' => (string) get_post_meta($booking_id, 'cmn_status', true),
            'booking_date' => $this->get_booking_service_date($booking_id),
            'eligible' => $eligible,
            'viewer_role' => $viewer_role,
            'requires_feedback' => $requires_feedback,
            'viewer_feedback' => $viewer_feedback,
            'counterparty_feedback' => $counterparty_feedback,
            'feedback_rows' => $viewer_role === 'staff' ? $staff_rows : [],
            'form' => in_array($viewer_role, ['candidate', 'school'], true) ? $this->get_booking_feedback_form_config($booking_id, $viewer_role) : null,
            'candidate_name' => $candidate_id ? (string) get_the_title($candidate_id) : 'Candidate',
            'school_name' => $school_id ? (string) get_the_title($school_id) : 'School',
        ];
    }

    private function get_school_ready_responses($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if (!$school_user_id) {
            return [];
        }
        global $wpdb;
        $table = $this->get_ready_responses_table();
        return (array) $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE school_user_id = %d ORDER BY is_default DESC, updated_at DESC, id DESC",
            $school_user_id
        ), ARRAY_A);
    }

    private function get_school_ready_response_by_id($response_id, $school_user_id = 0) {
        $response_id = (int) $response_id;
        if (!$response_id) {
            return null;
        }
        global $wpdb;
        $table = $this->get_ready_responses_table();
        if ($school_user_id > 0) {
            return $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM {$table} WHERE id = %d AND school_user_id = %d LIMIT 1",
                $response_id,
                (int) $school_user_id
            ), ARRAY_A);
        }
        return $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE id = %d LIMIT 1",
            $response_id
        ), ARRAY_A);
    }

    private function get_default_school_ready_response($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if (!$school_user_id) {
            return null;
        }
        global $wpdb;
        $table = $this->get_ready_responses_table();
        return $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE school_user_id = %d AND is_default = 1 ORDER BY updated_at DESC LIMIT 1",
            $school_user_id
        ), ARRAY_A);
    }

    private function normalize_ready_response_selection_for_request($raw_value, $school_user_id) {
        $raw = sanitize_text_field((string) $raw_value);
        if ($raw === '' || $raw === 'default') {
            return null;
        }
        if ($raw === 'none') {
            return 0;
        }
        $response_id = (int) $raw;
        if ($response_id < 1) {
            return null;
        }
        $response = $this->get_school_ready_response_by_id($response_id, (int) $school_user_id);
        if (!$response) {
            return null;
        }
        return (int) ($response['id'] ?? 0);
    }

    private function resolve_request_ready_response_template($request, $school_user_id) {
        $selected_id = isset($request['ready_response_id']) ? (int) $request['ready_response_id'] : null;
        if ($selected_id === 0) {
            return null;
        }
        if ($selected_id > 0) {
            $selected_template = $this->get_school_ready_response_by_id($selected_id, (int) $school_user_id);
            if ($selected_template) {
                return $selected_template;
            }
        }
        return $this->get_default_school_ready_response((int) $school_user_id);
    }

    private function format_school_address($school_id) {
        $school_id = (int) $school_id;
        if (!$school_id) {
            return '';
        }
        $parts = [];
        foreach (['cmn_address_line1', 'cmn_address_line2', 'cmn_town', 'cmn_county', 'cmn_postcode'] as $field) {
            $value = trim((string) get_post_meta($school_id, $field, true));
            if ($value !== '') {
                $parts[] = $value;
            }
        }
        return implode(', ', $parts);
    }

    private function build_ready_response_tokens($booking_id, $request, $school_id, $candidate_id) {
        $booking_id = (int) $booking_id;
        $school_id = (int) $school_id;
        $candidate_id = (int) $candidate_id;
        $booking_date_raw = $this->get_booking_service_date($booking_id);
        $booking_date = $booking_date_raw ? date_i18n('M j, Y', strtotime($booking_date_raw)) : '';
        $contact_name = trim((string) get_post_meta($school_id, 'cmn_primary_contact_name', true));
        if ($contact_name === '') {
            $contact_name = trim((string) get_post_meta($school_id, 'cmn_contact1', true));
        }
        if ($contact_name === '') {
            $contact_name = trim((string) get_post_meta($school_id, 'cmn_template_contact_name_default', true));
        }
        $contact_phone = trim((string) get_post_meta($school_id, 'cmn_primary_contact_phone', true));
        if ($contact_phone === '') {
            $contact_phone = trim((string) get_post_meta($school_id, 'cmn_phone', true));
        }
        return [
            'candidate_name' => $candidate_id ? (string) get_the_title($candidate_id) : '',
            'school_name' => trim((string) get_post_meta($school_id, 'cmn_template_school_name_default', true)) ?: ($school_id ? (string) get_the_title($school_id) : ''),
            'booking_date' => $booking_date,
            'start_time' => trim((string) get_post_meta($booking_id, 'cmn_start_time', true)) ?: trim((string) get_post_meta($school_id, 'cmn_template_start_time_default', true)),
            'end_time' => trim((string) get_post_meta($booking_id, 'cmn_end_time', true)),
            'location_name' => trim((string) get_post_meta($booking_id, 'cmn_location', true)) ?: trim((string) get_post_meta($school_id, 'cmn_location', true)),
            'location_address' => $this->format_school_address($school_id),
            'reception_instructions' => trim((string) get_post_meta($school_id, 'cmn_reception_instructions', true)),
            'parking_info' => trim((string) get_post_meta($school_id, 'cmn_parking_info', true)),
            'teacher_name' => trim((string) get_post_meta($booking_id, 'cmn_teacher_name', true)),
            'contact_name' => $contact_name,
            'contact_phone' => $contact_phone,
            'notes' => trim((string) get_post_meta($booking_id, 'cmn_notes', true)) ?: trim((string) ($request['internal_note'] ?? '')),
        ];
    }

    private function render_ready_response_template_message($template, $tokens) {
        $template = (string) $template;
        if ($template === '') {
            return '';
        }
        $replacements = [];
        foreach ((array) $tokens as $key => $value) {
            $replacements['{' . sanitize_key($key) . '}'] = sanitize_text_field((string) $value);
        }
        $rendered = strtr($template, $replacements);
        $lines = preg_split('/\r\n|\r|\n/', $rendered);
        $clean_lines = [];
        foreach ((array) $lines as $line) {
            $line = trim((string) $line);
            if ($line === '') {
                continue;
            }
            if (preg_match('/^[A-Za-z0-9\/\-\s]+:\s*$/', $line)) {
                continue;
            }
            $clean_lines[] = $line;
        }
        return implode("\n", $clean_lines);
    }

    private function post_booking_acceptance_auto_messages($thread_id, $booking_id, $request, $school_id, $candidate_id, $school_user_id, $am_user_id) {
        $thread_id = (int) $thread_id;
        $booking_id = (int) $booking_id;
        $school_id = (int) $school_id;
        $candidate_id = (int) $candidate_id;
        $school_user_id = (int) $school_user_id;
        $am_user_id = (int) $am_user_id;
        if (!$thread_id || !$booking_id) {
            return;
        }
        if (get_post_meta($booking_id, 'cmn_accept_auto_messages_posted', true) === '1') {
            return;
        }

        $candidate_name = $candidate_id ? (string) get_the_title($candidate_id) : 'Candidate';
        $accept_msg = 'Candidate ' . $candidate_name . ' has accepted this booking.';
        $accept_sender_user_id = $am_user_id ?: $school_user_id;
        $accept_sender_role = $am_user_id ? 'account_manager' : ($school_user_id ? 'school' : 'system');
        $this->add_booking_thread_message($thread_id, $accept_sender_user_id, $accept_sender_role, $accept_msg);
        $this->add_booking_thread_message($thread_id, $accept_sender_user_id, $accept_sender_role, 'Please use this chat to confirm start time, exact location, who to ask for on arrival, dress code, and any important on-site notes.');
        $this->add_booking_thread_message($thread_id, $accept_sender_user_id, $accept_sender_role, 'Important: do not discuss pay rates in this booking chat. Keep all booking communication documented here.');

        $template_row = $this->resolve_request_ready_response_template($request, $school_user_id);
        if ($template_row && !empty($template_row['message_template'])) {
            $tokens = $this->build_ready_response_tokens($booking_id, $request, $school_id, $candidate_id);
            $template_message = $this->render_ready_response_template_message((string) $template_row['message_template'], $tokens);
            if ($template_message !== '') {
                $template_sender_user_id = $school_user_id ?: $am_user_id;
                $template_sender_role = $school_user_id ? 'school' : ($am_user_id ? 'account_manager' : 'system');
                $this->add_booking_thread_message($thread_id, $template_sender_user_id, $template_sender_role, $template_message);
            }
        }
        update_post_meta($booking_id, 'cmn_accept_auto_messages_posted', '1');
    }

    private function sync_feedback_insights_entry_from_booking_feedback($booking_id, $from_role, $rated_entity_type, $rated_entity_id, $stars_overall, $stars_1, $stars_2, $would_rebook, $comment) {
        $booking_id = (int) $booking_id;
        $rated_entity_id = (int) $rated_entity_id;
        $stars_overall = (int) $stars_overall;
        $stars_1 = (int) $stars_1;
        $stars_2 = (int) $stars_2;
        $from_role = sanitize_key((string) $from_role);
        $rated_entity_type = sanitize_key((string) $rated_entity_type);
        if ($booking_id < 1 || $rated_entity_id < 1 || !in_array($from_role, ['candidate', 'school'], true) || !in_array($rated_entity_type, ['candidate', 'school'], true)) {
            return;
        }
        $issue_resolved = null;
        if ($would_rebook !== null) {
            $issue_resolved = ((int) $would_rebook === 1) ? 1 : 0;
        }
        global $wpdb;
        $table = $this->get_feedback_table();
        $wpdb->replace($table, [
            'booking_id' => $booking_id,
            'from_role' => $from_role,
            'to_role' => $rated_entity_type,
            'to_entity_id' => $rated_entity_id,
            'rating_overall' => max(1, min(5, $stars_overall)),
            'rating_reliability' => max(1, min(5, $stars_1)),
            'rating_response_time' => max(1, min(5, $stars_2)),
            'issue_resolved' => $issue_resolved,
            'comments' => sanitize_textarea_field((string) $comment),
            'created_at' => current_time('mysql'),
        ], ['%d', '%s', '%s', '%d', '%d', '%d', '%d', '%d', '%s', '%s']);
    }

    private function maybe_process_candidate_feedback_risk_alerts($candidate_id, $booking_id = 0) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return;
        }
        $score = $this->get_feedback_insights_engine()->get_candidate_score($candidate_id);
        $risk = (array) ($score['risk'] ?? []);
        $is_urgent = !empty($risk['is_urgent']);
        if (!$is_urgent) {
            delete_post_meta($candidate_id, 'cmn_feedback_risk');
            $existing_tags = (array) get_post_meta($candidate_id, 'cmn_tags', true);
            if ($existing_tags) {
                $filtered = [];
                foreach ($existing_tags as $tag) {
                    $tag = sanitize_text_field((string) $tag);
                    if ($tag !== '' && strtolower($tag) !== 'feedback risk') {
                        $filtered[] = $tag;
                    }
                }
                update_post_meta($candidate_id, 'cmn_tags', array_values(array_unique($filtered)));
            }
            return;
        }
        update_post_meta($candidate_id, 'cmn_feedback_risk', 'urgent');
        $existing_tags = (array) get_post_meta($candidate_id, 'cmn_tags', true);
        $existing_tags[] = 'Feedback Risk';
        $clean_tags = [];
        foreach ($existing_tags as $tag) {
            $tag = sanitize_text_field((string) $tag);
            if ($tag !== '') {
                $clean_tags[] = $tag;
            }
        }
        update_post_meta($candidate_id, 'cmn_tags', array_values(array_unique($clean_tags)));

        $meta_key = 'cmn_feedback_risk_alert_sent';
        if (get_post_meta($candidate_id, $meta_key, true) === '1') {
            return;
        }
        $candidate_name = (string) get_the_title($candidate_id);
        $portal_link = add_query_arg([
            'view' => 'candidates',
            'candidate_id' => $candidate_id,
        ], $this->get_portal_base_url());
        if ($booking_id > 0) {
            $portal_link = add_query_arg([
                'view' => 'requests',
                'cmn_booking_chat' => (int) $booking_id,
                'cmn_thread_type' => 'booking_details',
            ], $this->get_portal_base_url());
        }
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            $this->add_notification(
                (int) $admin_id,
                'candidate_feedback_risk_urgent',
                'Candidate feedback risk alert',
                'Urgent feedback risk detected for ' . $candidate_name . '.',
                $portal_link
            );
        }
        update_post_meta($candidate_id, $meta_key, '1');
    }

    private function get_feedback_summary_for_entity($entity_type, $entity_id) {
        $entity_type = sanitize_key((string) $entity_type);
        $entity_id = (int) $entity_id;
        if (!in_array($entity_type, ['candidate', 'school'], true) || $entity_id < 1) {
            return [
                'avg_overall' => 0.0,
                'avg_reliability' => 0.0,
                'feedback_count' => 0,
                'trend' => 'stable',
                'trend_label' => '->',
            ];
        }
        $score = $entity_type === 'candidate'
            ? $this->get_feedback_insights_engine()->get_candidate_score($entity_id)
            : $this->get_feedback_insights_engine()->get_school_score($entity_id);
        $trend = (string) ($score['trend'] ?? 'stable');
        $trend_label = '->';
        if ($trend === 'up') {
            $trend_label = '^';
        } elseif ($trend === 'down') {
            $trend_label = 'v';
        }
        return [
            'avg_overall' => (float) ($score['avg_overall'] ?? 0),
            'avg_reliability' => (float) ($score['avg_reliability'] ?? 0),
            'feedback_count' => (int) ($score['feedback_count'] ?? 0),
            'trend' => $trend,
            'trend_label' => $trend_label,
            'risk' => (array) ($score['risk'] ?? []),
        ];
    }

    private function maybe_notify_low_booking_feedback($booking_id, $viewer_role, $stars_overall, $rater_user_id) {
        $booking_id = (int) $booking_id;
        $rater_user_id = (int) $rater_user_id;
        $stars_overall = (int) $stars_overall;
        if ($booking_id < 1 || $rater_user_id < 1) {
            return;
        }
        $meta_key = 'cmn_feedback_low_alert_' . $booking_id . '_' . $rater_user_id;
        if ($stars_overall > 2) {
            delete_post_meta($booking_id, $meta_key);
            return;
        }
        if (get_post_meta($booking_id, $meta_key, true) === '1') {
            return;
        }
        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        $candidate_name = $candidate_id ? (string) get_the_title($candidate_id) : 'Candidate';
        $school_name = $school_id ? (string) get_the_title($school_id) : 'School';
        $staff_link = add_query_arg([
            'view' => 'requests',
            'cmn_booking_chat' => $booking_id,
            'cmn_thread_type' => 'booking_details',
        ], $this->get_portal_base_url());
        $message = 'Low feedback alert (' . $stars_overall . '/5) for ' . $school_name . ' - ' . $candidate_name . '.';
        $notify_user_ids = [];
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            $notify_user_ids[(int) $admin_id] = (int) $admin_id;
        }
        $request_id = (int) get_post_meta($booking_id, 'cmn_request_id', true);
        if ($request_id > 0) {
            $request = $this->get_candidate_request_by_id($request_id);
            if ($request && !empty($request['account_manager_user_id'])) {
                $notify_user_ids[(int) $request['account_manager_user_id']] = (int) $request['account_manager_user_id'];
            }
        }
        foreach ($notify_user_ids as $notify_user_id) {
            $this->add_notification((int) $notify_user_id, 'booking_feedback_low', 'Low booking feedback', $message, $staff_link);
        }
        update_post_meta($booking_id, $meta_key, '1');
    }

    private function get_tomorrow_date() {
        $tz = wp_timezone();
        $now = new DateTime('now', $tz);
        return $now->modify('+1 day')->format('Y-m-d');
    }

    private function get_candidate_availability_window(DateTime $now = null) {
        $tz = wp_timezone();
        if (!$now) {
            $now = new DateTime('now', $tz);
        }

        $target = $this->get_next_weekday_date((clone $now));
        $window_open = (clone $target)->modify('-1 day')->setTime(19, 0, 0);
        $window_close = (clone $target)->setTime(7, 30, 0);
        $is_open = ($now >= $window_open && $now <= $window_close);
        $next_press_label = 'PRESS FROM ' . strtoupper((clone $window_open)->format('l')) . ' @ 7PM';

        return [
            'is_open' => $is_open,
            'target_date' => $target->format('Y-m-d'),
            'window_open_at' => $window_open->format(DateTime::ATOM),
            'window_close_at' => $window_close->format(DateTime::ATOM),
            'next_press_label' => $next_press_label,
            'closed_message' => 'You can confirm availability from 7:00pm on the previous day until 7:30am.',
        ];
    }

    private function get_next_weekday_date(DateTime $from) {
        $candidate = clone $from;
        $weekday = (int) $candidate->format('N');
        $hour = (int) $candidate->format('G');
        $minute = (int) $candidate->format('i');

        // Weekend always targets Monday morning.
        if ($weekday >= 6) {
            while ((int) $candidate->format('N') !== 1) {
                $candidate->modify('+1 day');
            }
            return $candidate;
        }

        // On weekdays, "this morning" window is until 7:30am.
        $is_morning_window = ($hour < 7) || ($hour === 7 && $minute <= 30);
        if ($is_morning_window) {
            return $candidate;
        }

        // Otherwise, target next weekday morning.
        $candidate->modify('+1 day');
        while ((int) $candidate->format('N') > 5) {
            $candidate->modify('+1 day');
        }
        return $candidate;
    }

    private function get_availability_period_label($target_date, DateTime $now = null) {
        if (!$now) {
            $now = new DateTime('now', wp_timezone());
        }
        $today = $now->format('Y-m-d');
        if ($target_date === $today) {
            return 'this morning';
        }
        $tomorrow = (clone $now)->modify('+1 day')->format('Y-m-d');
        if ($target_date === $tomorrow) {
            return 'tomorrow morning';
        }
        return date_i18n('l', strtotime($target_date)) . ' morning';
    }

    private function has_candidate_availability($candidate_id, $date) {
        if (!$candidate_id || !$date) {
            return false;
        }
        global $wpdb;
        $table = $this->get_candidate_availability_table();
        $exists = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table} WHERE candidate_id = %d AND available_date = %s",
            $candidate_id,
            $date
        ));
        return !empty($exists);
    }

    private function get_candidate_availability_entry($candidate_id, $date) {
        if (!$candidate_id || !$date) {
            return null;
        }
        global $wpdb;
        $table = $this->get_candidate_availability_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT id, available_date, available_type, created_at
             FROM {$table}
             WHERE candidate_id = %d
               AND available_date = %s
             ORDER BY created_at DESC, id DESC
             LIMIT 1",
            $candidate_id,
            $date
        ), ARRAY_A);
        return is_array($row) && $row ? $row : null;
    }

    private function is_candidate_unavailable($candidate_id, $date) {
        if (!$candidate_id || !$date) {
            return false;
        }
        global $wpdb;
        $table = $this->get_candidate_calendar_table();
        if (!$table) {
            return false;
        }
        $status = $wpdb->get_var($wpdb->prepare(
            "SELECT status FROM {$table} WHERE candidate_id = %d AND date = %s",
            $candidate_id,
            $date
        ));
        return $status === 'unavailable';
    }

    private function get_candidate_calendar_map($candidate_id, $start_date, $end_date) {
        if (!$candidate_id || !$start_date || !$end_date) {
            return [];
        }
        global $wpdb;
        $table = $this->get_candidate_calendar_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT date, status FROM {$table} WHERE candidate_id = %d AND date BETWEEN %s AND %s",
            $candidate_id,
            $start_date,
            $end_date
        ), ARRAY_A);
        $map = [];
        if ($rows) {
            foreach ($rows as $row) {
                if (!empty($row['date']) && !empty($row['status'])) {
                    $map[$row['date']] = $row['status'];
                }
            }
        }
        $booked_map = $this->get_candidate_confirmed_booking_dates_map($candidate_id, $start_date, $end_date);
        if ($booked_map) {
            foreach ($booked_map as $booked_date => $booked_status) {
                $map[$booked_date] = $booked_status;
            }
        }
        return $map;
    }

    private function get_candidate_confirmed_booking_dates_map($candidate_id, $start_date, $end_date) {
        $candidate_id = (int) $candidate_id;
        $start_date = $this->normalize_invoice_date($start_date);
        $end_date = $this->normalize_invoice_date($end_date);
        if ($candidate_id < 1 || $start_date === '' || $end_date === '' || $end_date < $start_date) {
            return [];
        }

        $allowed_statuses = $this->get_completed_payable_booking_statuses();
        if (!$allowed_statuses) {
            return [];
        }

        global $wpdb;
        $posts_table = $wpdb->posts;
        $meta_table = $wpdb->postmeta;
        $status_placeholders = implode(',', array_fill(0, count($allowed_statuses), '%s'));
        $sql = "SELECT p.ID AS booking_id,
                       status_meta.meta_value AS booking_status,
                       start_meta.meta_value AS start_date,
                       day_meta.meta_value AS day_date,
                       end_meta.meta_value AS end_date
                FROM {$posts_table} p
                INNER JOIN {$meta_table} candidate_meta
                    ON candidate_meta.post_id = p.ID
                   AND candidate_meta.meta_key = 'cmn_candidate_id'
                   AND candidate_meta.meta_value = %d
                LEFT JOIN {$meta_table} status_meta
                    ON status_meta.post_id = p.ID
                   AND status_meta.meta_key = 'cmn_status'
                LEFT JOIN {$meta_table} start_meta
                    ON start_meta.post_id = p.ID
                   AND start_meta.meta_key = 'cmn_start_date'
                LEFT JOIN {$meta_table} day_meta
                    ON day_meta.post_id = p.ID
                   AND day_meta.meta_key = 'cmn_date'
                LEFT JOIN {$meta_table} end_meta
                    ON end_meta.post_id = p.ID
                   AND end_meta.meta_key = 'cmn_end_date'
                WHERE p.post_type = 'cmn_booking'
                  AND p.post_status NOT IN ('trash', 'auto-draft')
                  AND (status_meta.meta_value = '' OR status_meta.meta_value IS NULL OR status_meta.meta_value IN ({$status_placeholders}))";
        $params = array_merge([$candidate_id], $allowed_statuses);
        $rows = $wpdb->get_results($wpdb->prepare($sql, $params), ARRAY_A);
        if (!$rows) {
            return [];
        }

        $booked = [];
        foreach ($rows as $row) {
            $status = sanitize_key((string) ($row['booking_status'] ?? ''));
            if (!$this->is_completed_payable_booking_status($status)) {
                continue;
            }
            $window = $this->get_invoice_booking_date_window([
                'start_date' => (string) ($row['start_date'] ?? ''),
                'day_date' => (string) ($row['day_date'] ?? ''),
                'end_date' => (string) ($row['end_date'] ?? ''),
            ]);
            if (!$window) {
                continue;
            }
            $window_start = (string) ($window['start_date'] ?? '');
            $window_end = (string) ($window['end_date'] ?? '');
            if ($window_start === '' || $window_end === '') {
                continue;
            }
            if ($window_end < $window_start) {
                $window_end = $window_start;
            }

            $range_start = max($start_date, $window_start);
            $range_end = min($end_date, $window_end);
            if ($range_end < $range_start) {
                continue;
            }

            $cursor = DateTime::createFromFormat('Y-m-d', $range_start, wp_timezone());
            $stop = DateTime::createFromFormat('Y-m-d', $range_end, wp_timezone());
            if (!$cursor || !$stop) {
                continue;
            }
            while ($cursor <= $stop) {
                $cursor_date = $cursor->format('Y-m-d');
                if ($this->is_weekday_date($cursor_date)) {
                    $booked[$cursor_date] = 'booked_confirmed';
                }
                $cursor->modify('+1 day');
            }
        }

        return $booked;
    }

    private function is_candidate_booking_confirmed_on_date($candidate_id, $date) {
        $date = $this->normalize_invoice_date($date);
        if ($date === '') {
            return false;
        }
        $booked = $this->get_candidate_confirmed_booking_dates_map((int) $candidate_id, $date, $date);
        return isset($booked[$date]);
    }

    private function is_weekday_date($date) {
        if (!$date || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
            return false;
        }
        $dt = DateTime::createFromFormat('Y-m-d', $date, wp_timezone());
        if (!$dt) {
            return false;
        }
        $weekday = (int) $dt->format('N');
        return $weekday >= 1 && $weekday <= 5;
    }

    private function get_calendar_limit_dates() {
        $tz = wp_timezone();
        $start = (new DateTime(current_time('Y-m-d'), $tz))->modify('+1 day');
        $start_year = (int) $start->format('Y');
        $end_of_july = new DateTime($start_year . '-07-31', $tz);
        if ($start > $end_of_july) {
            $end_of_july = new DateTime(($start_year + 1) . '-07-31', $tz);
        }
        return [$start->format('Y-m-d'), $end_of_july->format('Y-m-d')];
    }

    private function get_candidate_calendar_summary($candidate_id) {
        if (!$candidate_id) {
            return [
                'available_count' => 0,
                'unavailable_count' => 0,
                'next_available' => '',
                'next_available_label' => 'Not set',
            ];
        }
        [$today, $limit] = $this->get_calendar_limit_dates();
        $map = $this->get_candidate_calendar_map($candidate_id, $today, $limit);
        $available = 0;
        $unavailable = 0;
        $next = '';
        foreach ($map as $date => $status) {
            if ($status === 'available') {
                $available++;
                if ($next === '' || $date < $next) {
                    $next = $date;
                }
            } elseif ($status === 'unavailable') {
                $unavailable++;
            }
        }
        $next_label = $next ? date_i18n('l, F jS', strtotime($next)) : 'Not set';
        return [
            'available_count' => $available,
            'unavailable_count' => $unavailable,
            'next_available' => $next,
            'next_available_label' => $next_label,
        ];
    }

    private function get_candidate_requests($status = 'requested', $limit = 10) {
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $status = sanitize_text_field($status);
        if ($status === 'pending') {
            $status = 'requested';
        }
        $limit = (int) $limit;
        if ($limit < 1) {
            $limit = 10;
        }
        $sql = $wpdb->prepare(
            "SELECT * FROM {$table} WHERE status = %s ORDER BY requested_at DESC LIMIT %d",
            $status,
            $limit
        );
        $rows = $wpdb->get_results($sql, ARRAY_A);
        foreach ($rows as &$row) {
            $this->maybe_mark_request_expired($row);
        }
        return $rows;
    }

    private function get_candidate_requests_for_status($status, $limit = 50, $school_domains = []) {
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $limit = (int) $limit;
        if ($limit < 1) {
            $limit = 50;
        }
        $where = [];
        $params = [];
        if ($status && $status !== 'all') {
            if ($status === 'pending') {
                $status = 'requested';
            }
            $where[] = 'status = %s';
            $params[] = sanitize_text_field($status);
        }
        if ($school_domains) {
            $school_domains = array_values(array_unique(array_filter(array_map('strtolower', $school_domains))));
            $placeholders = implode(',', array_fill(0, count($school_domains), '%s'));
            $where[] = "school_email_domain IN ({$placeholders})";
            $params = array_merge($params, $school_domains);
        }
        $where_sql = $where ? ('WHERE ' . implode(' AND ', $where)) : '';
        $sql = "SELECT * FROM {$table} {$where_sql} ORDER BY requested_at DESC LIMIT {$limit}";
        if ($params) {
            $sql = $wpdb->prepare($sql, $params);
        }
        $rows = $wpdb->get_results($sql, ARRAY_A);
        foreach ($rows as &$row) {
            $this->maybe_mark_request_expired($row);
        }
        return $rows;
    }

    private function get_school_candidate_requests($school_domain, $limit = 20) {
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $school_domain = strtolower(trim((string) $school_domain));
        if ($school_domain === '') {
            return [];
        }
        $limit = (int) $limit;
        if ($limit < 1) {
            $limit = 20;
        }
        $sql = $wpdb->prepare(
            "SELECT * FROM {$table} WHERE school_email_domain = %s ORDER BY requested_at DESC LIMIT %d",
            $school_domain,
            $limit
        );
        $rows = $wpdb->get_results($sql, ARRAY_A);
        foreach ($rows as &$row) {
            $this->maybe_mark_request_expired($row);
        }
        return $rows;
    }

    private function get_candidate_request_by_id($request_id) {
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $request_id = (int) $request_id;
        if (!$request_id) {
            return null;
        }
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE id = %d LIMIT 1",
            $request_id
        ), ARRAY_A);
        if ($row) {
            $this->maybe_mark_request_expired($row);
        }
        return $row ?: null;
    }

    private function get_candidate_requests_for_candidate($candidate_id, $limit = 20) {
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $candidate_id = (int) $candidate_id;
        if (!$candidate_id) {
            return [];
        }
        $limit = max(1, (int) $limit);
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE candidate_id = %d ORDER BY requested_at DESC LIMIT %d",
            $candidate_id,
            $limit
        ), ARRAY_A);
        foreach ($rows as &$row) {
            $this->maybe_mark_request_expired($row);
        }
        unset($row);
        return $this->apply_weighted_routing_to_candidate_requests($candidate_id, $rows, 15);
    }

    private function get_school_routing_meta_by_tier($tier) {
        $tier = $this->normalize_school_partner_lifetime_tier((string) $tier);
        if ($tier === 'elite') {
            return ['tier' => 'elite', 'weight' => 400, 'level' => 'Premier Priority'];
        }
        if ($tier === 'gold') {
            return ['tier' => 'gold', 'weight' => 300, 'level' => 'Top Priority'];
        }
        if ($tier === 'silver') {
            return ['tier' => 'silver', 'weight' => 200, 'level' => 'Priority'];
        }
        if ($tier === 'bronze') {
            return ['tier' => 'bronze', 'weight' => 100, 'level' => 'Standard'];
        }
        return ['tier' => 'standard', 'weight' => 0, 'level' => 'Standard'];
    }

    private function get_school_routing_meta_map(array $school_user_ids) {
        global $wpdb;
        $map = [];
        $school_user_ids = array_values(array_unique(array_filter(array_map('intval', (array) $school_user_ids), static function ($id) {
            return $id > 0;
        })));
        if (!$school_user_ids) {
            return $map;
        }

        $default_meta = $this->get_school_routing_meta_by_tier('standard');
        foreach ($school_user_ids as $school_user_id) {
            $map[$school_user_id] = $default_meta;
        }

        $table = $this->get_school_partner_state_table();
        if (!$this->table_exists($table)) {
            return $map;
        }

        $placeholders = implode(',', array_fill(0, count($school_user_ids), '%d'));
        $sql = "SELECT school_user_id, current_tier FROM {$table} WHERE school_user_id IN ({$placeholders})";
        $rows = (array) $wpdb->get_results($wpdb->prepare($sql, $school_user_ids), ARRAY_A);
        foreach ($rows as $row) {
            $school_user_id = (int) ($row['school_user_id'] ?? 0);
            if ($school_user_id < 1) {
                continue;
            }
            $map[$school_user_id] = $this->get_school_routing_meta_by_tier((string) ($row['current_tier'] ?? 'standard'));
        }

        return $map;
    }

    public function get_school_routing_weight($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return 0;
        }
        $meta_map = $this->get_school_routing_meta_map([$school_user_id]);
        $meta = (array) ($meta_map[$school_user_id] ?? $this->get_school_routing_meta_by_tier('standard'));
        return max(0, (int) ($meta['weight'] ?? 0));
    }

    private function is_candidate_request_active_for_weighted_routing($status) {
        $status = sanitize_key((string) $status);
        if ($status === '') {
            $status = 'requested';
        }
        return !in_array($status, ['accepted', 'declined', 'expired', 'cancelled', 'closed', 'confirmed'], true);
    }

    private function log_weighted_routing_applied_once($candidate_user_id, $window_minutes, $items_count, $top_school_user_id, $top_weight) {
        $candidate_user_id = (int) $candidate_user_id;
        $window_minutes = max(1, (int) $window_minutes);
        $items_count = max(0, (int) $items_count);
        $top_school_user_id = max(0, (int) $top_school_user_id);
        $top_weight = max(0, (int) $top_weight);
        if ($candidate_user_id < 1 || $items_count < 2 || !function_exists('cmn_audit_log_event')) {
            return;
        }

        $window_seconds = $window_minutes * MINUTE_IN_SECONDS;
        $bucket = (int) floor(time() / max(1, $window_seconds));
        $transient_key = 'cmn_weighted_routing_' . $candidate_user_id . '_' . $bucket;
        if (get_transient($transient_key)) {
            return;
        }

        cmn_audit_log_event([
            'module' => 'school_partner',
            'entity_type' => 'candidate',
            'entity_id' => $candidate_user_id,
            'event_type' => 'weighted_routing_applied',
            'metadata' => [
                'window_minutes' => $window_minutes,
                'items_count' => $items_count,
                'top_school_user_id' => $top_school_user_id,
                'top_weight' => $top_weight,
            ],
        ]);

        set_transient($transient_key, 1, $window_seconds);
    }

    /*
     * Acceptance checks:
     * 1) Two schools targeting the same candidate within 15 minutes are ordered by routing_weight DESC.
     * 2) Same-tier competing requests remain newest-first.
     * 3) If there is no competing window, chronological ordering is unchanged.
     * 4) Candidate can still accept any request (ordering only, no auto-assignment).
     * 5) Audit writes only when weighted ordering actually changes the default order.
     */
    private function apply_weighted_routing_to_candidate_requests($candidate_id, array $rows, $window_minutes = 15) {
        $candidate_id = (int) $candidate_id;
        $window_minutes = max(1, (int) $window_minutes);
        if ($candidate_id < 1 || empty($rows)) {
            return $rows;
        }

        $school_user_ids = [];
        foreach ($rows as $index => $row) {
            $row = is_array($row) ? $row : [];
            $school_user_id = max(0, (int) ($row['school_user_id'] ?? 0));
            $school_id = max(0, (int) ($row['school_id'] ?? 0));
            if ($school_user_id < 1) {
                if ($school_id < 1 && !empty($row['school_email_domain'])) {
                    $school_id = (int) $this->get_school_post_id_by_domain((string) $row['school_email_domain']);
                }
                if ($school_id > 0) {
                    $school_user_id = max(0, (int) $this->get_school_user_id_for_request($row, $school_id));
                }
            }
            $rows[$index]['school_user_id'] = $school_user_id;
            if ($school_user_id > 0) {
                $school_user_ids[] = $school_user_id;
            }
        }

        $routing_meta_map = $this->get_school_routing_meta_map($school_user_ids);
        $default_meta = $this->get_school_routing_meta_by_tier('standard');

        foreach ($rows as $index => $row) {
            $row = is_array($row) ? $row : [];
            $school_user_id = max(0, (int) ($row['school_user_id'] ?? 0));
            $routing_meta = (array) ($routing_meta_map[$school_user_id] ?? $default_meta);
            $requested_at_raw = (string) ($row['requested_at'] ?? '');
            if ($requested_at_raw === '') {
                $requested_at_raw = (string) ($row['updated_at'] ?? '');
            }
            $requested_ts = $requested_at_raw !== '' ? (int) strtotime($requested_at_raw) : 0;
            $rows[$index]['routing_weight'] = max(0, (int) ($routing_meta['weight'] ?? 0));
            $rows[$index]['routing_level'] = sanitize_text_field((string) ($routing_meta['level'] ?? 'Standard'));
            $rows[$index]['routing_tier'] = sanitize_key((string) ($routing_meta['tier'] ?? 'standard'));
            $rows[$index]['created_at'] = $requested_at_raw;
            $rows[$index]['routing_created_at'] = $requested_at_raw;
            $rows[$index]['_routing_ts'] = $requested_ts;
            $rows[$index]['_routing_active'] = $this->is_candidate_request_active_for_weighted_routing((string) ($row['status'] ?? 'requested'));
        }

        usort($rows, static function ($a, $b) {
            $ts_a = (int) ($a['_routing_ts'] ?? 0);
            $ts_b = (int) ($b['_routing_ts'] ?? 0);
            if ($ts_a !== $ts_b) {
                return ($ts_a > $ts_b) ? -1 : 1;
            }
            $id_a = max(0, (int) ($a['id'] ?? 0));
            $id_b = max(0, (int) ($b['id'] ?? 0));
            if ($id_a === $id_b) {
                return 0;
            }
            return ($id_a > $id_b) ? -1 : 1;
        });

        $weighted_rows = $rows;
        $window_seconds = $window_minutes * MINUTE_IN_SECONDS;
        $active_indexes = [];
        foreach ($weighted_rows as $idx => $row) {
            if (!empty($row['_routing_active']) && (int) ($row['_routing_ts'] ?? 0) > 0) {
                $active_indexes[] = (int) $idx;
            }
        }

        $reordered = false;
        $competing_items_count = 0;
        if (count($active_indexes) >= 2) {
            $clusters = [];
            $current_cluster = [(int) $active_indexes[0]];
            for ($i = 1, $max = count($active_indexes); $i < $max; $i++) {
                $current_index = (int) $active_indexes[$i];
                $previous_index = (int) $active_indexes[$i - 1];
                $current_ts = (int) ($weighted_rows[$current_index]['_routing_ts'] ?? 0);
                $previous_ts = (int) ($weighted_rows[$previous_index]['_routing_ts'] ?? 0);
                if ($previous_ts > 0 && $current_ts > 0 && ($previous_ts - $current_ts) <= $window_seconds) {
                    $current_cluster[] = $current_index;
                } else {
                    $clusters[] = $current_cluster;
                    $current_cluster = [$current_index];
                }
            }
            if ($current_cluster) {
                $clusters[] = $current_cluster;
            }

            foreach ($clusters as $cluster) {
                if (count($cluster) < 2) {
                    continue;
                }
                $school_ids_in_cluster = [];
                foreach ($cluster as $cluster_index) {
                    $sid = max(0, (int) ($weighted_rows[$cluster_index]['school_user_id'] ?? 0));
                    if ($sid > 0) {
                        $school_ids_in_cluster[$sid] = true;
                    }
                }
                if (count($school_ids_in_cluster) < 2) {
                    continue;
                }

                $before_ids = [];
                $cluster_rows = [];
                foreach ($cluster as $cluster_index) {
                    $before_ids[] = max(0, (int) ($weighted_rows[$cluster_index]['id'] ?? 0));
                    $cluster_rows[] = $weighted_rows[$cluster_index];
                }

                usort($cluster_rows, static function ($a, $b) {
                    $weight_a = max(0, (int) ($a['routing_weight'] ?? 0));
                    $weight_b = max(0, (int) ($b['routing_weight'] ?? 0));
                    if ($weight_a !== $weight_b) {
                        return ($weight_a > $weight_b) ? -1 : 1;
                    }
                    $ts_a = (int) ($a['_routing_ts'] ?? 0);
                    $ts_b = (int) ($b['_routing_ts'] ?? 0);
                    if ($ts_a !== $ts_b) {
                        return ($ts_a > $ts_b) ? -1 : 1;
                    }
                    $id_a = max(0, (int) ($a['id'] ?? 0));
                    $id_b = max(0, (int) ($b['id'] ?? 0));
                    if ($id_a === $id_b) {
                        return 0;
                    }
                    return ($id_a > $id_b) ? -1 : 1;
                });

                $after_ids = array_map(static function ($row) {
                    return max(0, (int) ($row['id'] ?? 0));
                }, $cluster_rows);
                if ($before_ids !== $after_ids) {
                    $reordered = true;
                }
                $competing_items_count += count($cluster_rows);

                foreach ($cluster as $position => $cluster_index) {
                    if (!isset($cluster_rows[$position])) {
                        continue;
                    }
                    $weighted_rows[$cluster_index] = $cluster_rows[$position];
                    $weighted_rows[$cluster_index]['_routing_competing'] = 1;
                }
            }
        }

        if ($reordered) {
            $top_school_user_id = 0;
            $top_weight = 0;
            foreach ($weighted_rows as $row) {
                if (empty($row['_routing_competing'])) {
                    continue;
                }
                $top_school_user_id = max(0, (int) ($row['school_user_id'] ?? 0));
                $top_weight = max(0, (int) ($row['routing_weight'] ?? 0));
                break;
            }
            $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
            $this->log_weighted_routing_applied_once(
                $candidate_user_id,
                $window_minutes,
                max(2, $competing_items_count),
                $top_school_user_id,
                $top_weight
            );
        }

        foreach ($weighted_rows as &$row) {
            unset($row['_routing_ts'], $row['_routing_active'], $row['_routing_competing']);
        }
        unset($row);

        return $weighted_rows;
    }

    private function get_candidate_completed_booking_count($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if (!$candidate_id) {
            return 0;
        }
        $ids = get_posts([
            'post_type' => 'cmn_booking',
            'posts_per_page' => -1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_candidate_id',
                    'value' => $candidate_id,
                ],
                [
                    'key' => 'cmn_status',
                    'value' => ['approved', 'completed', 'confirmed'],
                    'compare' => 'IN',
                ],
            ],
        ]);
        return is_array($ids) ? count($ids) : 0;
    }

    private function get_candidate_earnings_metrics($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return [
                'month_total' => 0.0,
                'academic_year_total' => 0.0,
                'lifetime_total' => 0.0,
                'upcoming_total' => 0.0,
                'average_daily_rate' => 0.0,
                'completed_count' => 0,
            ];
        }

        $today = current_time('Y-m-d');
        $today_ts = strtotime($today);
        $month_start = date('Y-m-01', $today_ts);
        $month_end = date('Y-m-t', $today_ts);
        $current_year = (int) date('Y', $today_ts);
        $current_month = (int) date('n', $today_ts);
        if ($current_month >= 9) {
            $academic_start = sprintf('%d-09-01', $current_year);
            $academic_end = sprintf('%d-08-31', $current_year + 1);
        } else {
            $academic_start = sprintf('%d-09-01', $current_year - 1);
            $academic_end = sprintf('%d-08-31', $current_year);
        }

        $booking_ids = get_posts([
            'post_type' => 'cmn_booking',
            'posts_per_page' => -1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_candidate_id',
                    'value' => $candidate_id,
                ],
            ],
        ]);
        if (!$booking_ids) {
            return [
                'month_total' => 0.0,
                'academic_year_total' => 0.0,
                'lifetime_total' => 0.0,
                'upcoming_total' => 0.0,
                'average_daily_rate' => 0.0,
                'completed_count' => 0,
            ];
        }

        $month_total = 0.0;
        $academic_total = 0.0;
        $lifetime_total = 0.0;
        $upcoming_total = 0.0;
        $completed_count = 0;
        $completed_sum = 0.0;
        foreach ($booking_ids as $booking_id) {
            $booking_id = (int) $booking_id;
            $status = sanitize_key((string) get_post_meta($booking_id, 'cmn_status', true));
            if ($status === '') {
                $status = 'approved';
            }
            if (in_array($status, ['declined', 'cancelled', 'expired'], true)) {
                continue;
            }
            $booking_date = (string) get_post_meta($booking_id, 'cmn_date', true);
            if ($booking_date === '') {
                $booking_date = (string) get_post_meta($booking_id, 'cmn_start_date', true);
            }
            if ($booking_date === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $booking_date)) {
                continue;
            }
            $candidate_pay_rate = (float) get_post_meta($booking_id, 'cmn_candidate_pay_rate', true);
            if ($candidate_pay_rate <= 0) {
                $candidate_pay_rate = (float) get_post_meta($booking_id, 'cmn_rate', true);
            }
            if ($candidate_pay_rate <= 0) {
                continue;
            }

            $is_completed = in_array($status, ['approved', 'confirmed', 'completed', 'accepted'], true) && ($booking_date <= $today);
            if ($is_completed) {
                $lifetime_total += $candidate_pay_rate;
                $completed_sum += $candidate_pay_rate;
                $completed_count++;
                if ($booking_date >= $month_start && $booking_date <= $month_end) {
                    $month_total += $candidate_pay_rate;
                }
                if ($booking_date >= $academic_start && $booking_date <= $academic_end) {
                    $academic_total += $candidate_pay_rate;
                }
            } elseif ($booking_date > $today && in_array($status, ['approved', 'confirmed', 'accepted'], true)) {
                $upcoming_total += $candidate_pay_rate;
            }
        }

        $average_daily_rate = $completed_count > 0 ? ($completed_sum / $completed_count) : 0.0;
        return [
            'month_total' => round($month_total, 2),
            'academic_year_total' => round($academic_total, 2),
            'lifetime_total' => round($lifetime_total, 2),
            'upcoming_total' => round($upcoming_total, 2),
            'average_daily_rate' => round($average_daily_rate, 2),
            'completed_count' => $completed_count,
        ];
    }

    private function get_candidate_strength_metrics($candidate_id, $candidate_user_id = 0) {
        $candidate_id = (int) $candidate_id;
        $candidate_user_id = (int) $candidate_user_id;
        if (!$candidate_id) {
            return [
                'score' => 0,
                'profile_completion' => 0,
                'docs_approved' => 0,
                'docs_total' => 3,
                'bookings_completed' => 0,
                'avg_rating' => 0.0,
                'years_experience' => 0,
            ];
        }

        $profile_completion = $candidate_user_id ? (int) get_user_meta($candidate_user_id, 'cmn_profile_completion_pct', true) : 0;
        if ($profile_completion < 1) {
            $profile_completion = (int) get_post_meta($candidate_id, 'cmn_profile_completion_pct', true);
        }
        $profile_completion = max(0, min(100, $profile_completion));

        $doc_states = [];
        foreach (['dbs', 'id', 'cv'] as $doc_type) {
            $doc = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, $doc_type);
            $doc_states[$doc_type] = [
                'uploaded' => !empty($doc['uploaded']),
                'status' => sanitize_key((string) ($doc['doc_status'] ?? 'not_uploaded')),
            ];
        }
        $docs_approved = 0;
        $doc_points = 0;
        foreach ($doc_states as $state) {
            if ($state['status'] === 'approved') {
                $docs_approved++;
                $doc_points += 15;
            } elseif ($state['status'] === 'pending' || $state['uploaded']) {
                $doc_points += 8;
            } elseif ($state['status'] === 'rejected') {
                $doc_points += 2;
            }
        }

        $bookings_completed = $this->get_candidate_completed_booking_count($candidate_id);
        $bookings_points = min(15, (int) round($bookings_completed * 1.5));

        $avg_rating = 0.0;
        if ($candidate_user_id) {
            $avg_rating = (float) get_user_meta($candidate_user_id, 'cmn_candidate_avg_rating', true);
        }
        if ($avg_rating <= 0) {
            $avg_rating = (float) get_post_meta($candidate_id, 'cmn_candidate_avg_rating', true);
        }
        if ($avg_rating < 0) {
            $avg_rating = 0.0;
        }
        if ($avg_rating > 5) {
            $avg_rating = 5.0;
        }
        $rating_points = (int) round(($avg_rating / 5) * 10);

        $years_experience = 0;
        foreach (['cmn_years_experience', 'years_experience', 'cmn_experience_years'] as $key) {
            $value = (float) get_post_meta($candidate_id, $key, true);
            if ($value <= 0 && $candidate_user_id) {
                $value = (float) get_user_meta($candidate_user_id, $key, true);
            }
            if ($value > 0) {
                $years_experience = (int) round($value);
                break;
            }
        }
        $experience_points = min(5, max(0, (int) round(($years_experience / 10) * 5)));

        $profile_points = (int) round(($profile_completion / 100) * 25);
        $score = max(0, min(100, $profile_points + $doc_points + $bookings_points + $rating_points + $experience_points));

        return [
            'score' => $score,
            'profile_completion' => $profile_completion,
            'docs_approved' => $docs_approved,
            'docs_total' => 3,
            'bookings_completed' => $bookings_completed,
            'avg_rating' => round($avg_rating, 1),
            'years_experience' => $years_experience,
        ];
    }

    private function get_booking_id_for_request($request_id) {
        $request_id = (int) $request_id;
        if (!$request_id) {
            return 0;
        }
        $bookings = get_posts([
            'post_type' => 'cmn_booking',
            'posts_per_page' => 1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_request_id',
                    'value' => $request_id,
                ],
            ],
        ]);
        return $bookings ? (int) $bookings[0] : 0;
    }

