    private function get_candidate_registration_profile_mapping_matrix() {
        $contract = $this->get_candidate_profile_field_contract();
        $matrix = [];
        foreach ($contract as $registration_field_key => $field_config) {
            $storage = (string) ($field_config['storage'] ?? '');
            $stored_meta_key = (string) ($field_config['key'] ?? '');
            if ($storage === 'post_meta' && $stored_meta_key === '') {
                $stored_meta_key = (string) ($field_config['form_key'] ?? $registration_field_key);
            }
            if ($storage === 'user_meta' && $stored_meta_key !== '') {
                $stored_meta_key = 'user_meta:' . $stored_meta_key;
            }
            $matrix[] = [
                'registration_field_key' => $registration_field_key,
                'stored_meta_key' => $stored_meta_key,
                'profile_render_location' => 'candidate.profile.' . $registration_field_key,
                'label' => (string) ($field_config['label'] ?? $registration_field_key),
            ];
        }
        return $matrix;
    }

    private function get_school_registration_profile_mapping_matrix() {
        $contract = $this->get_school_profile_field_contract();
        $matrix = [];
        foreach ($contract as $registration_field_key => $field_config) {
            $storage = (string) ($field_config['storage'] ?? '');
            $stored_meta_key = (string) ($field_config['key'] ?? '');
            if ($storage === 'post_title') {
                $stored_meta_key = 'post_title';
            } elseif ($storage === 'post_meta' && $stored_meta_key === '') {
                $stored_meta_key = 'cmn_' . $registration_field_key;
            }
            $matrix[] = [
                'registration_field_key' => $registration_field_key,
                'stored_meta_key' => $stored_meta_key,
                'profile_render_location' => 'school.profile.' . $registration_field_key,
                'label' => ucfirst(str_replace('_', ' ', (string) $registration_field_key)),
            ];
        }
        return $matrix;
    }

    private function get_data_integrity_audit_rows($entity_type = 'candidate', $limit = 200) {
        $entity_type = $entity_type === 'school' ? 'school' : 'candidate';
        $limit = max(1, min(1000, (int) $limit));
        $rows = [];
        if ($entity_type === 'candidate') {
            $mapping = $this->get_candidate_registration_profile_mapping_matrix();
            $displayed_keys = [
                'cmn_email', 'cmn_phone', 'cmn_location', 'cmn_roles', 'cmn_roles_other',
                'cmn_travel_distance', 'cmn_driving_licence', 'cmn_car_owner', 'cmn_dbs_update_service',
                'cmn_qts_status',
                'cmn_house_number', 'cmn_address_line1', 'cmn_address_line2', 'cmn_address_line3',
                'cmn_town', 'cmn_county', 'cmn_postcode', 'cmn_notes', 'cmn_availability_days'
            ];
            $candidate_ids = get_posts([
                'post_type' => 'cmn_candidate',
                'post_status' => ['publish', 'pending', 'draft', 'private'],
                'fields' => 'ids',
                'posts_per_page' => $limit,
                'orderby' => 'ID',
                'order' => 'DESC',
            ]);
            foreach ((array) $candidate_ids as $candidate_id) {
                $candidate_id = (int) $candidate_id;
                if ($candidate_id < 1) {
                    continue;
                }
                $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
                $missing = [];
                $captured_not_displayed = [];
                foreach ($mapping as $map_row) {
                    $storage_key = (string) ($map_row['stored_meta_key'] ?? '');
                    $value = '';
                    if (strpos($storage_key, 'user_meta:') === 0) {
                        $meta_key = substr($storage_key, 10);
                        $value = $candidate_user_id > 0 ? (string) get_user_meta($candidate_user_id, $meta_key, true) : '';
                    } elseif ($storage_key === 'post_title') {
                        $value = (string) get_the_title($candidate_id);
                    } elseif ($storage_key !== '') {
                        $value = (string) get_post_meta($candidate_id, $storage_key, true);
                    }
                    if (trim((string) $value) === '') {
                        $missing[] = (string) ($map_row['label'] ?? $map_row['registration_field_key']);
                    }
                    if (strpos($storage_key, 'user_meta:') !== 0 && $storage_key !== '' && !in_array($storage_key, $displayed_keys, true) && trim((string) $value) !== '') {
                        $captured_not_displayed[] = $storage_key;
                    }
                }
                $rows[] = [
                    'entity_id' => $candidate_id,
                    'name' => (string) get_the_title($candidate_id),
                    'missing_count' => count($missing),
                    'missing_fields' => $missing,
                    'captured_not_displayed' => array_values(array_unique($captured_not_displayed)),
                    'displayed_not_captured' => [],
                ];
            }
        } else {
            $mapping = $this->get_school_registration_profile_mapping_matrix();
            $displayed_keys = [
                'cmn_location', 'cmn_email', 'cmn_phone', 'cmn_website', 'cmn_contact1',
                'cmn_contact_role', 'cmn_contact1_email', 'cmn_primary_contact_phone', 'cmn_cover_manager',
                'cmn_cover_manager_email', 'cmn_email_name', 'cmn_house_number', 'cmn_address_line1',
                'cmn_address_line2', 'cmn_address_line3', 'cmn_town', 'cmn_county', 'cmn_postcode',
                'cmn_school_type', 'cmn_pupil_count', 'cmn_supply_frequency', 'cmn_use_agencies',
                'cmn_agency_count', 'cmn_notes'
            ];
            $school_ids = get_posts([
                'post_type' => 'cmn_school',
                'post_status' => ['publish', 'pending', 'draft', 'private'],
                'fields' => 'ids',
                'posts_per_page' => $limit,
                'orderby' => 'ID',
                'order' => 'DESC',
            ]);
            foreach ((array) $school_ids as $school_id) {
                $school_id = (int) $school_id;
                if ($school_id < 1) {
                    continue;
                }
                $missing = [];
                $captured_not_displayed = [];
                foreach ($mapping as $map_row) {
                    $storage_key = (string) ($map_row['stored_meta_key'] ?? '');
                    $value = '';
                    if ($storage_key === 'post_title') {
                        $value = (string) get_the_title($school_id);
                    } elseif ($storage_key !== '') {
                        $value = (string) get_post_meta($school_id, $storage_key, true);
                    }
                    if (trim((string) $value) === '') {
                        $missing[] = (string) ($map_row['label'] ?? $map_row['registration_field_key']);
                    }
                    if ($storage_key !== '' && $storage_key !== 'post_title' && !in_array($storage_key, $displayed_keys, true) && trim((string) $value) !== '') {
                        $captured_not_displayed[] = $storage_key;
                    }
                }
                $rows[] = [
                    'entity_id' => $school_id,
                    'name' => (string) get_the_title($school_id),
                    'missing_count' => count($missing),
                    'missing_fields' => $missing,
                    'captured_not_displayed' => array_values(array_unique($captured_not_displayed)),
                    'displayed_not_captured' => [],
                ];
            }
        }
        return $rows;
    }

    private function sanitize_profile_contract_value($value, $field_config) {
        $sanitize = (string) ($field_config['sanitize'] ?? 'text');
        if ($sanitize === 'multi_choice') {
            $choices = (array) ($field_config['choices'] ?? []);
            $raw_values = is_array($value) ? $value : [];
            $clean_values = [];
            foreach ($raw_values as $raw_value) {
                $clean = sanitize_text_field((string) $raw_value);
                if ($clean !== '' && in_array($clean, $choices, true)) {
                    $clean_values[] = $clean;
                }
            }
            return array_values(array_unique($clean_values));
        }
        $value = is_array($value) ? '' : (string) $value;
        switch ($sanitize) {
            case 'email':
                return sanitize_email($value);
            case 'url':
                return esc_url_raw($value);
            case 'textarea':
                return sanitize_textarea_field($value);
            case 'choice':
                $clean = strtolower(sanitize_text_field($value));
                $choices = array_map('strval', (array) ($field_config['choices'] ?? []));
                return in_array($clean, $choices, true) ? $clean : '';
            case 'text':
            default:
                return sanitize_text_field($value);
        }
    }

    private function get_candidate_doc_meta_keys($doc_type) {
        $doc_type = sanitize_key((string) $doc_type);
        $map = [
            'dbs' => [
                'attachment' => 'cmn_doc_dbs_attachment_id',
                'legacy_attachment' => 'cmn_candidate_dbs_doc',
                'uploaded_at' => 'cmn_doc_dbs_uploaded_at',
                'legacy_uploaded_at' => 'cmn_candidate_dbs_doc_uploaded_at',
                'filename' => 'cmn_doc_dbs_filename',
                'filesize' => 'cmn_doc_dbs_filesize',
                'mime' => 'cmn_doc_dbs_mime',
                'review_status' => 'cmn_doc_dbs_review_status',
                'review_reason' => 'cmn_doc_dbs_review_reason',
                'reviewed_at' => 'cmn_doc_dbs_reviewed_at',
                'reviewed_by' => 'cmn_doc_dbs_reviewed_by',
                'post_meta' => 'cmn_dbs_file',
            ],
            'id' => [
                'attachment' => 'cmn_doc_id_attachment_id',
                'legacy_attachment' => 'cmn_candidate_id_doc',
                'uploaded_at' => 'cmn_doc_id_uploaded_at',
                'legacy_uploaded_at' => 'cmn_candidate_id_doc_uploaded_at',
                'filename' => 'cmn_doc_id_filename',
                'filesize' => 'cmn_doc_id_filesize',
                'mime' => 'cmn_doc_id_mime',
                'review_status' => 'cmn_doc_id_review_status',
                'review_reason' => 'cmn_doc_id_review_reason',
                'reviewed_at' => 'cmn_doc_id_reviewed_at',
                'reviewed_by' => 'cmn_doc_id_reviewed_by',
                'post_meta' => 'cmn_id_file',
            ],
            'cv' => [
                'attachment' => 'cmn_doc_cv_attachment_id',
                'legacy_attachment' => 'cmn_candidate_cv_doc',
                'uploaded_at' => 'cmn_doc_cv_uploaded_at',
                'legacy_uploaded_at' => 'cmn_candidate_cv_doc_uploaded_at',
                'filename' => 'cmn_doc_cv_filename',
                'filesize' => 'cmn_doc_cv_filesize',
                'mime' => 'cmn_doc_cv_mime',
                'review_status' => 'cmn_doc_cv_review_status',
                'review_reason' => 'cmn_doc_cv_review_reason',
                'reviewed_at' => 'cmn_doc_cv_reviewed_at',
                'reviewed_by' => 'cmn_doc_cv_reviewed_by',
                'post_meta' => 'cmn_cv_file',
            ],
        ];
        return $map[$doc_type] ?? [];
    }

    private function get_candidate_doc_types() {
        return ['dbs', 'id', 'cv'];
    }

    private function normalize_candidate_doc_review_status($status, $has_upload) {
        if (!$has_upload) {
            return 'not_uploaded';
        }
        $status = sanitize_key((string) $status);
        if (in_array($status, ['approved', 'rejected', 'pending'], true)) {
            return $status;
        }
        return 'pending';
    }

    private function get_candidate_doc_summary($docs) {
        $doc_types = $this->get_candidate_doc_types();
        $states = [];
        foreach ($doc_types as $doc_type) {
            $states[] = (string) ($docs[$doc_type]['doc_status'] ?? 'not_uploaded');
        }
        $has_rejected = in_array('rejected', $states, true);
        $has_missing = in_array('not_uploaded', $states, true);
        $all_approved = !in_array('pending', $states, true) && !in_array('rejected', $states, true) && !in_array('not_uploaded', $states, true);

        if ($has_rejected) {
            return [
                'key' => 'action_required',
                'badge_class' => 'is-declined',
                'badge_label' => 'Action Required',
                'copy' => 'Action Required - Document Rejected',
            ];
        }
        if ($has_missing) {
            return [
                'key' => 'incomplete',
                'badge_class' => 'is-declined',
                'badge_label' => 'Incomplete',
                'copy' => 'Incomplete - Documents Required',
            ];
        }
        if ($all_approved) {
            return [
                'key' => 'verified',
                'badge_class' => 'is-verified',
                'badge_label' => 'Verified',
                'copy' => 'Verified',
            ];
        }
        return [
            'key' => 'awaiting_review',
            'badge_class' => 'is-pending',
            'badge_label' => 'Awaiting Review',
            'copy' => 'Documents Awaiting Review',
        ];
    }

    public function cmn_get_candidate_compliance_score($candidate_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return 0;
        }
        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        if ($candidate_id < 1) {
            return 0;
        }
        $vetting = $this->get_candidate_vetting_payload($candidate_id, $candidate_user_id);
        return (int) ($vetting['score'] ?? 0);
    }

    private function get_candidate_vetting_payload($candidate_id, $candidate_user_id) {
        $candidate_id = (int) $candidate_id;
        $candidate_user_id = (int) $candidate_user_id;
        $doc_statuses = [];
        foreach ($this->get_candidate_doc_types() as $doc_type) {
            $doc_statuses[$doc_type] = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, $doc_type);
        }
        $profile_completion = (int) get_user_meta($candidate_user_id, 'cmn_profile_completion_pct', true);
        if ($profile_completion < 1) {
            $profile_completion = (int) get_post_meta($candidate_id, 'cmn_profile_completion_pct', true);
        }
        if ($profile_completion < 1) {
            $profile_completion = (int) $this->update_candidate_profile_completion($candidate_id, $candidate_user_id);
        }
        $driving_licence = strtolower(trim((string) get_post_meta($candidate_id, 'cmn_driving_licence', true)));
        $driving_licence_present = in_array($driving_licence, ['yes', '1', 'true'], true);
        $feedback_summary = $this->get_feedback_summary_for_entity('candidate', $candidate_id);
        $feedback_average = (float) ($feedback_summary['avg_overall'] ?? 0);
        $formatted_cv = $this->get_candidate_cv_formatted_status($candidate_id);
        $cv_formatted = !empty($formatted_cv['available']);

        $evaluation = $this->get_vetting_engine()->evaluate([
            'docs' => [
                'dbs' => (string) ($doc_statuses['dbs']['doc_status'] ?? 'not_uploaded'),
                'id' => (string) ($doc_statuses['id']['doc_status'] ?? 'not_uploaded'),
                'cv' => (string) ($doc_statuses['cv']['doc_status'] ?? 'not_uploaded'),
            ],
            'driving_licence_present' => $driving_licence_present,
            'profile_completion_pct' => $profile_completion,
            'feedback_average' => $feedback_average,
            'cv_formatted' => $cv_formatted,
        ]);

        $doc_label_map = [
            'dbs' => 'DBS',
            'id' => 'ID',
            'cv' => 'CV',
        ];
        $docs_pending_labels = [];
        foreach ((array) ($evaluation['docs_pending'] ?? []) as $doc_key) {
            $doc_key = sanitize_key((string) $doc_key);
            if (isset($doc_label_map[$doc_key])) {
                $docs_pending_labels[] = $doc_label_map[$doc_key];
            }
        }
        $evaluation['docs_pending_labels'] = array_values(array_unique($docs_pending_labels));
        $evaluation['feedback_count'] = (int) ($feedback_summary['feedback_count'] ?? 0);
        return $evaluation;
    }

    private function get_candidate_compliance_payload($candidate_id, $candidate_user_id) {
        $candidate_id = (int) $candidate_id;
        $candidate_user_id = (int) $candidate_user_id;
        $docs = [];
        foreach ($this->get_candidate_doc_types() as $doc_type) {
            $status = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, $doc_type);
            $docs[$doc_type] = [
                'status' => sanitize_key((string) ($status['doc_status'] ?? 'not_uploaded')),
                'label' => sanitize_text_field((string) ($status['status_label'] ?? 'Not Uploaded')),
                'review_reason' => sanitize_text_field((string) ($status['review_reason'] ?? '')),
                'uploaded_at' => sanitize_text_field((string) ($status['uploaded_at'] ?? '')),
                'uploaded_at_label' => sanitize_text_field((string) ($status['uploaded_at_label'] ?? '')),
            ];
        }
        $vetting = $this->get_candidate_vetting_payload($candidate_id, $candidate_user_id);
        $risk_level = (string) ($vetting['risk_level'] ?? 'Medium');
        return [
            'score' => (int) ($vetting['score'] ?? 0),
            'risk_level' => $risk_level,
            'risk_badge_class' => $risk_level === 'Low' ? 'is-verified' : ($risk_level === 'High' ? 'is-declined' : 'is-pending'),
            'vetting' => $vetting,
            'breakdown' => (array) ($vetting['breakdown'] ?? []),
            'docs' => $docs,
            'summary' => $this->get_candidate_doc_summary([
                'dbs' => ['doc_status' => $docs['dbs']['status']],
                'id' => ['doc_status' => $docs['id']['status']],
                'cv' => ['doc_status' => $docs['cv']['status']],
            ]),
        ];
    }

    private function sync_candidate_admin_verification_status($candidate_id, $candidate_user_id, $docs = null) {
        $candidate_id = (int) $candidate_id;
        $candidate_user_id = (int) $candidate_user_id;
        if (!$candidate_id || !$candidate_user_id) {
            return '';
        }
        if (!is_array($docs)) {
            $docs = [];
            foreach ($this->get_candidate_doc_types() as $doc_type) {
                $docs[$doc_type] = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, $doc_type);
            }
        }
        $summary = $this->get_candidate_doc_summary($docs);
        $status_map = [
            'verified' => 'approved',
            'action_required' => 'rejected',
            'incomplete' => 'incomplete',
            'awaiting_review' => 'awaiting_review',
        ];
        $verification_status = $status_map[$summary['key']] ?? 'awaiting_review';
        update_user_meta($candidate_user_id, 'cmn_admin_verification_status', $verification_status);
        update_post_meta($candidate_id, 'cmn_admin_verification_status', $verification_status);
        return $verification_status;
    }

    private function get_candidate_doc_attachment_id($candidate_user_id, $doc_type) {
        $keys = $this->get_candidate_doc_meta_keys($doc_type);
        if (!$keys || !$candidate_user_id) {
            return 0;
        }
        $attachment_id = (int) get_user_meta((int) $candidate_user_id, $keys['attachment'], true);
        if (!$attachment_id && !empty($keys['legacy_attachment'])) {
            $attachment_id = (int) get_user_meta((int) $candidate_user_id, $keys['legacy_attachment'], true);
        }
        return $attachment_id;
    }

    private function cmn_school_can_access_candidate_docs($school_user_id, $candidate_user_id) {
        global $wpdb;
        $school_user_id = (int) $school_user_id;
        $candidate_user_id = (int) $candidate_user_id;
        if (!$school_user_id || !$candidate_user_id || !$this->is_school_user($school_user_id)) {
            return false;
        }
        $school_id = (int) $this->resolve_school_id_for_user($school_user_id);
        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        if (!$school_id || !$candidate_id) {
            return false;
        }

        $requests_table = $this->get_candidate_requests_table();
        $request_match = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$requests_table} WHERE school_id = %d AND candidate_id = %d AND status IN ('accepted','confirmed') ORDER BY id DESC LIMIT 1",
            $school_id,
            $candidate_id
        ));
        if ($request_match > 0) {
            return true;
        }

        $booking_ids = get_posts([
            'post_type' => 'cmn_booking',
            'fields' => 'ids',
            'posts_per_page' => 1,
            'meta_query' => [
                [
                    'key' => 'cmn_school_id',
                    'value' => $school_id,
                ],
                [
                    'key' => 'cmn_candidate_id',
                    'value' => $candidate_id,
                ],
                [
                    'key' => 'cmn_status',
                    'value' => ['approved', 'confirmed', 'accepted'],
                    'compare' => 'IN',
                ],
            ],
        ]);
        return !empty($booking_ids);
    }

    private function cmn_candidate_can_access_doc($viewer_user_id, $candidate_user_id, $attachment_id = 0) {
        $viewer_user_id = (int) $viewer_user_id;
        $candidate_user_id = (int) $candidate_user_id;
        if (!$viewer_user_id || !$candidate_user_id) {
            return false;
        }
        if ($viewer_user_id === $candidate_user_id) {
            return true;
        }
        if ($this->is_admin_user($viewer_user_id) || $this->is_staff_role($viewer_user_id) || $this->is_account_manager_user($viewer_user_id)) {
            return true;
        }
        if ($this->is_school_user($viewer_user_id) && $this->cmn_school_can_access_candidate_docs($viewer_user_id, $candidate_user_id)) {
            $attachment_id = (int) $attachment_id;
            if (!$attachment_id) {
                return false;
            }
            $doc_type = sanitize_key((string) get_post_meta($attachment_id, 'cmn_doc_type', true));
            if ($doc_type !== 'cv_formatted') {
                return false;
            }
            $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
            if (!$candidate_id) {
                return false;
            }
            $formatted_attachment_id = $this->get_candidate_cv_formatted_attachment_id($candidate_id);
            return $formatted_attachment_id > 0 && $formatted_attachment_id === $attachment_id;
        }
        return false;
    }

    public function protect_candidate_doc_attachment_access() {
        if (is_admin() || !is_attachment()) {
            return;
        }
        $attachment_id = (int) get_queried_object_id();
        if (!$attachment_id) {
            return;
        }
        $owner_user_id = (int) get_post_meta($attachment_id, 'cmn_owner_user_id', true);
        if (!$owner_user_id) {
            $candidate_id = (int) get_post_meta($attachment_id, 'cmn_candidate_id', true);
            if ($candidate_id) {
                $owner_user_id = (int) $this->get_candidate_user_id($candidate_id);
            }
        }
        if (!$owner_user_id) {
            return;
        }
        if (!is_user_logged_in()) {
            wp_safe_redirect(wp_login_url($this->get_portal_base_url()));
            exit;
        }
        $viewer_user_id = get_current_user_id();
        if (!$this->cmn_candidate_can_access_doc($viewer_user_id, $owner_user_id, $attachment_id)) {
            status_header(403);
            wp_die('Access restricted.');
        }
    }

    private function get_candidate_doc_status($candidate_id, $user_id, $doc_type) {
        $keys = $this->get_candidate_doc_meta_keys($doc_type);
        if (!$keys) {
            return [
                'doc_status' => 'not_uploaded',
                'status_label' => 'Not Uploaded',
                'status_copy' => 'Not Uploaded',
                'badge_class' => 'is-declined',
                'uploaded' => false,
                'attachment_id' => 0,
                'filename' => '',
                'url' => '',
                'uploaded_at' => '',
                'uploaded_label' => 'Not uploaded',
                'uploaded_at_label' => '',
                'filesize' => 0,
                'filesize_label' => '',
                'mime' => '',
                'review_status' => 'not_uploaded',
                'review_reason' => '',
                'reviewed_at' => '',
                'reviewed_at_label' => '',
                'reviewed_by' => 0,
            ];
        }
        $attachment_id = $this->get_candidate_doc_attachment_id((int) $user_id, $doc_type);
        $legacy_url = $keys && !empty($keys['post_meta']) ? (string) get_post_meta((int) $candidate_id, (string) $keys['post_meta'], true) : '';
        if (!$attachment_id && $legacy_url !== '') {
            $resolved_attachment_id = (int) attachment_url_to_postid($legacy_url);
            if ($resolved_attachment_id > 0) {
                $attachment_id = $resolved_attachment_id;
                update_user_meta((int) $user_id, $keys['attachment'], $attachment_id);
                if (!empty($keys['legacy_attachment'])) {
                    update_user_meta((int) $user_id, $keys['legacy_attachment'], $attachment_id);
                }
            }
        }
        $uploaded_at = (string) get_user_meta((int) $user_id, $keys['uploaded_at'], true);
        if ($uploaded_at === '' && !empty($keys['legacy_uploaded_at'])) {
            $uploaded_at = (string) get_user_meta((int) $user_id, $keys['legacy_uploaded_at'], true);
        }
        $url = $attachment_id ? wp_get_attachment_url($attachment_id) : '';
        if ($url === '' && $legacy_url !== '') {
            $url = esc_url_raw($legacy_url);
        }
        if ($attachment_id) {
            $existing_owner = (int) get_post_meta($attachment_id, 'cmn_owner_user_id', true);
            if (!$existing_owner && $user_id) {
                update_post_meta($attachment_id, 'cmn_owner_user_id', (int) $user_id);
            }
            $existing_doc_type = (string) get_post_meta($attachment_id, 'cmn_doc_type', true);
            if ($existing_doc_type === '') {
                update_post_meta($attachment_id, 'cmn_doc_type', $doc_type);
            }
        }
        $filename = $attachment_id ? (string) get_user_meta((int) $user_id, $keys['filename'], true) : '';
        if ($filename === '' && $attachment_id) {
            $filename = basename((string) get_attached_file($attachment_id));
        }
        if (!$filename && $url) {
            $filename = basename((string) parse_url($url, PHP_URL_PATH));
        }
        $filesize = $attachment_id ? (int) get_user_meta((int) $user_id, $keys['filesize'], true) : 0;
        if (!$filesize && $attachment_id) {
            $path = get_attached_file($attachment_id);
            if ($path && file_exists($path)) {
                $filesize = (int) filesize($path);
            }
        }
        $mime = $attachment_id ? (string) get_user_meta((int) $user_id, $keys['mime'], true) : '';
        if ($mime === '' && $attachment_id) {
            $mime = (string) get_post_mime_type($attachment_id);
        }
        $review_status_raw = !empty($keys['review_status']) ? (string) get_user_meta((int) $user_id, $keys['review_status'], true) : '';
        $review_reason = !empty($keys['review_reason']) ? sanitize_text_field((string) get_user_meta((int) $user_id, $keys['review_reason'], true)) : '';
        $reviewed_at = !empty($keys['reviewed_at']) ? (string) get_user_meta((int) $user_id, $keys['reviewed_at'], true) : '';
        $reviewed_by = !empty($keys['reviewed_by']) ? (int) get_user_meta((int) $user_id, $keys['reviewed_by'], true) : 0;
        $doc_status = $this->normalize_candidate_doc_review_status($review_status_raw, (bool) ($url !== ''));
        $status_label_map = [
            'not_uploaded' => 'Not Uploaded',
            'pending' => 'Pending Review',
            'approved' => 'Approved',
            'rejected' => 'Rejected',
        ];
        $badge_class_map = [
            'not_uploaded' => 'is-declined',
            'pending' => 'is-pending',
            'approved' => 'is-verified',
            'rejected' => 'is-declined',
        ];
        $status_label = $status_label_map[$doc_status] ?? 'Not Uploaded';
        $badge_class = $badge_class_map[$doc_status] ?? 'is-declined';
        $status_copy = $status_label;
        if ($doc_status === 'rejected' && $review_reason !== '') {
            $status_copy .= ' - ' . $review_reason;
        }
        $reviewed_at_label = $reviewed_at ? date_i18n('M j, Y g:ia', strtotime($reviewed_at)) : '';
        $uploaded_label = 'Not uploaded';
        $uploaded_at_label = '';
        if ($url && $filename) {
            $uploaded_label = 'Uploaded: ' . $filename;
            if ($uploaded_at) {
                $uploaded_at_label = date_i18n('M j, Y g:ia', strtotime($uploaded_at));
                $uploaded_label .= ' on ' . $uploaded_at_label;
            }
        }
        return [
            'doc_status' => $doc_status,
            'status_label' => $status_label,
            'status_copy' => $status_copy,
            'badge_class' => $badge_class,
            'uploaded' => (bool) ($url !== ''),
            'attachment_id' => $attachment_id,
            'filename' => $filename,
            'url' => $url,
            'uploaded_at' => $uploaded_at,
            'uploaded_at_label' => $uploaded_at_label,
            'uploaded_label' => $uploaded_label,
            'filesize' => $filesize,
            'filesize_label' => $filesize > 0 ? size_format($filesize) : '',
            'mime' => $mime,
            'review_status' => $doc_status,
            'review_reason' => $doc_status === 'rejected' ? $review_reason : '',
            'reviewed_at' => $reviewed_at,
            'reviewed_at_label' => $reviewed_at_label,
            'reviewed_by' => $reviewed_by,
        ];
    }

    private function is_candidate_doc_attachment_still_linked($attachment_id) {
        global $wpdb;
        $attachment_id = (int) $attachment_id;
        if (!$attachment_id) {
            return false;
        }
        $keys = [];
        foreach ($this->get_candidate_doc_types() as $doc_type) {
            $map = $this->get_candidate_doc_meta_keys($doc_type);
            if (!empty($map['attachment'])) {
                $keys[] = $map['attachment'];
            }
            if (!empty($map['legacy_attachment'])) {
                $keys[] = $map['legacy_attachment'];
            }
        }
        $keys = array_values(array_unique(array_filter($keys)));
        if (!$keys) {
            return false;
        }
        $placeholders = implode(',', array_fill(0, count($keys), '%s'));
        $params = array_merge($keys, [(string) $attachment_id]);
        $sql = $wpdb->prepare(
            "SELECT COUNT(*) FROM {$wpdb->usermeta} WHERE meta_key IN ({$placeholders}) AND meta_value = %s",
            $params
        );
        $count = (int) $wpdb->get_var($sql);
        return $count > 0;
    }

    private function get_candidate_availability_days($candidate_id, $user_id = 0) {
        $candidate_id = (int) $candidate_id;
        $days = (array) get_post_meta($candidate_id, 'cmn_availability_days', true);
        if (!$days) {
            $days_raw = (string) get_post_meta($candidate_id, 'cmn_availability_days', true);
            if ($days_raw !== '') {
                $days = array_map('trim', explode(',', $days_raw));
            }
        }
        return array_values(array_filter(array_map('sanitize_text_field', (array) $days)));
    }

    private function get_candidate_profile_completion_state($candidate_id, $user_id) {
        $candidate_id = (int) $candidate_id;
        $user_id = (int) $user_id;
        if (!$candidate_id || !$user_id) {
            return [
                'percent' => 0,
                'completed' => 0,
                'total' => 0,
                'missing' => [],
            ];
        }
        $candidate_post = get_post($candidate_id);
        $profile_email = (string) get_post_meta($candidate_id, 'cmn_email', true);
        $first_name = (string) get_user_meta($user_id, 'first_name', true);
        $last_name = (string) get_user_meta($user_id, 'last_name', true);
        $profile_phone = (string) get_user_meta($user_id, 'phone', true);
        if ($profile_phone === '') {
            $profile_phone = (string) get_post_meta($candidate_id, 'cmn_phone', true);
        }
        if ($first_name === '' && $candidate_post) {
            $parts = preg_split('/\s+/', trim((string) $candidate_post->post_title));
            $first_name = (string) ($parts[0] ?? '');
            $last_name = count($parts) > 1 ? (string) end($parts) : $last_name;
        }
        $nationality = (string) get_post_meta($candidate_id, 'cmn_nationality', true);
        if ($nationality === '') {
            $nationality = (string) get_user_meta($user_id, 'cmn_nationality', true);
        }
        $travel_distance = (string) get_user_meta($user_id, 'travel_radius', true);
        if ($travel_distance === '') {
            $travel_distance = (string) get_post_meta($candidate_id, 'cmn_travel_distance', true);
        }
        $role_label = (string) get_user_meta($user_id, 'role_type', true);
        if ($role_label === '') {
            $roles = (array) get_post_meta($candidate_id, 'cmn_roles', true);
            $role_label = $roles ? (string) $roles[0] : '';
        }
        $location = (string) get_post_meta($candidate_id, 'cmn_location', true);
        $driving_licence = sanitize_key((string) get_post_meta($candidate_id, 'cmn_driving_licence', true));
        $car_owner = sanitize_key((string) get_post_meta($candidate_id, 'cmn_car_owner', true));
        $qts_status = sanitize_key((string) get_post_meta($candidate_id, 'cmn_qts_status', true));
        $availability_days = $this->get_candidate_availability_days($candidate_id, $user_id);
        $doc_dbs = $this->get_candidate_doc_status($candidate_id, $user_id, 'dbs');
        $doc_id = $this->get_candidate_doc_status($candidate_id, $user_id, 'id');
        $doc_cv = $this->get_candidate_doc_status($candidate_id, $user_id, 'cv');

        // Soft-gate includes two final admin/payment checks.
        $bank_complete = $this->is_candidate_bank_complete_for_payroll($user_id);
        $self_employed_ack_complete = $this->is_candidate_self_employed_ack_complete_for_payroll($user_id);

        $core_checks = [
            !empty($first_name),
            !empty($last_name),
            !empty($profile_email),
            !empty($profile_phone),
            !empty($nationality),
            !empty($role_label),
            !empty($travel_distance),
            !empty($location),
            in_array($driving_licence, ['yes', 'no'], true),
            in_array($car_owner, ['yes', 'no'], true),
            in_array($qts_status, ['yes', 'no'], true),
            !empty($availability_days),
            !empty($doc_cv['uploaded']),
            !empty($doc_dbs['uploaded']),
            !empty($doc_id['uploaded']),
        ];
        $core_total = count($core_checks);
        $core_completed = count(array_filter($core_checks));
        $completed = $core_completed + ($bank_complete ? 1 : 0) + ($self_employed_ack_complete ? 1 : 0);
        $total = $core_total + 2;
        $pct = (int) round(($completed / max(1, $total)) * 100);

        $missing = [];
        if (!$bank_complete) {
            $missing[] = 'Add bank details';
        }
        if (!$self_employed_ack_complete) {
            $missing[] = 'Accept self-employment notice';
        }

        return [
            'percent' => $pct,
            'completed' => $completed,
            'total' => $total,
            'missing' => array_values(array_unique(array_filter(array_map('sanitize_text_field', $missing)))),
        ];
    }

    private function get_candidate_operational_gate_state($candidate_id, $user_id = 0) {
        $candidate_id = (int) $candidate_id;
        $user_id = (int) $user_id;
        if ($candidate_id < 1) {
            return [
                'unlocked' => false,
                'missing' => ['Upload CV', 'Upload DBS', 'Upload Photo ID'],
                'docs' => ['cv' => false, 'dbs' => false, 'id' => false],
            ];
        }
        if ($user_id < 1) {
            $user_id = (int) $this->get_candidate_user_id($candidate_id);
        }
        $doc_cv = $this->get_candidate_doc_status($candidate_id, $user_id, 'cv');
        $doc_dbs = $this->get_candidate_doc_status($candidate_id, $user_id, 'dbs');
        $doc_id = $this->get_candidate_doc_status($candidate_id, $user_id, 'id');
        $has_cv = !empty($doc_cv['uploaded']);
        $has_dbs = !empty($doc_dbs['uploaded']);
        $has_id = !empty($doc_id['uploaded']);
        $missing = [];
        if (!$has_cv) {
            $missing[] = 'Upload CV';
        }
        if (!$has_dbs) {
            $missing[] = 'Upload DBS';
        }
        if (!$has_id) {
            $missing[] = 'Upload Photo ID';
        }
        return [
            'unlocked' => empty($missing),
            'missing' => $missing,
            'docs' => [
                'cv' => $has_cv,
                'dbs' => $has_dbs,
                'id' => $has_id,
            ],
        ];
    }

    private function is_candidate_operationally_unlocked($candidate_id, $user_id = 0) {
        $state = $this->get_candidate_operational_gate_state((int) $candidate_id, (int) $user_id);
        return !empty($state['unlocked']);
    }

    private function update_candidate_profile_completion($candidate_id, $user_id) {
        $candidate_id = (int) $candidate_id;
        $user_id = (int) $user_id;
        if (!$candidate_id || !$user_id) {
            return 0;
        }
        $state = $this->get_candidate_profile_completion_state($candidate_id, $user_id);
        $pct = (int) ($state['percent'] ?? 0);
        update_user_meta($user_id, 'cmn_profile_completion_pct', (string) $pct);
        update_post_meta($candidate_id, 'cmn_profile_completion_pct', (string) $pct);
        return $pct;
    }

    private function maybe_notify_candidate_qts_required($candidate_id, $user_id) {
        try {
            $candidate_id = (int) $candidate_id;
            $user_id = (int) $user_id;
            if ($candidate_id < 1 || $user_id < 1) {
                return;
            }
            $qts_status = sanitize_key((string) get_post_meta($candidate_id, 'cmn_qts_status', true));
            if (in_array($qts_status, ['yes', 'no'], true)) {
                delete_user_meta($user_id, 'cmn_qts_prompt_sent');
                return;
            }
            if (get_user_meta($user_id, 'cmn_qts_prompt_sent', true) === '1') {
                return;
            }
            $profile_link = function_exists('add_query_arg')
                ? add_query_arg(['candidate' => 'profile'], $this->get_portal_base_url())
                : $this->get_portal_base_url();
            $this->add_notification(
                $user_id,
                'candidate_qts_required',
                'Action needed: add QTS status',
                'Please answer the QTS question in your profile to complete onboarding.',
                (string) $profile_link
            );
            update_user_meta($user_id, 'cmn_qts_prompt_sent', '1');
        } catch (Throwable $e) {
            error_log('CMN QTS notify skipped: ' . $e->getMessage());
        }
    }

    private function get_candidate_users_for_compliance_reminders() {
        return get_users([
            'role__in' => ['cmn_candidate', 'cmn_candidate_pending', 'candidate'],
            'fields' => ['ID', 'display_name', 'user_email'],
            'number' => 500,
        ]);
    }

    private function get_candidate_dbs_expiry_timestamp($candidate_id, $user_id) {
        $keys = [
            'cmn_doc_dbs_expiry_date',
            'cmn_dbs_expiry_date',
            'cmn_dbs_expiry',
            'dbs_expiry_date',
            'dbs_expiry',
        ];
        foreach ($keys as $key) {
            $value = (string) get_user_meta((int) $user_id, $key, true);
            if ($value === '') {
                $value = (string) get_post_meta((int) $candidate_id, $key, true);
            }
            if ($value === '') {
                continue;
            }
            if (ctype_digit($value)) {
                $numeric = (int) $value;
                if ($numeric > 1000000) {
                    return $numeric;
                }
            }
            $timestamp = strtotime($value);
            if ($timestamp !== false) {
                return $timestamp;
            }
        }
        return 0;
    }

    private function build_candidate_compliance_issues($candidate_id, $user_id) {
        $issues = [];
        $label_map = [
            'dbs' => 'DBS',
            'id' => 'Photo ID',
            'cv' => 'CV',
        ];
        foreach ($this->get_candidate_doc_types() as $doc_type) {
            $doc = $this->get_candidate_doc_status($candidate_id, $user_id, $doc_type);
            $doc_label = $label_map[$doc_type] ?? strtoupper((string) $doc_type);
            $status = (string) ($doc['doc_status'] ?? 'not_uploaded');
            if ($status === 'not_uploaded') {
                $issues[] = [
                    'key' => 'missing_' . $doc_type,
                    'message' => $doc_label . ' is missing.',
                ];
            } elseif ($status === 'rejected') {
                $reason = trim((string) ($doc['review_reason'] ?? ''));
                $issues[] = [
                    'key' => 'rejected_' . $doc_type,
                    'message' => $doc_label . ' was rejected' . ($reason !== '' ? (': ' . $reason) : '.'),
                ];
            }
        }

        $profile_completion = (int) get_user_meta((int) $user_id, 'cmn_profile_completion_pct', true);
        if ($profile_completion < 1) {
            $profile_completion = (int) get_post_meta((int) $candidate_id, 'cmn_profile_completion_pct', true);
        }
        if ($profile_completion < 1) {
            $profile_completion = (int) $this->update_candidate_profile_completion($candidate_id, $user_id);
        }
        if ($profile_completion < 100) {
            $issues[] = [
                'key' => 'profile_incomplete',
                'message' => 'Profile is ' . $profile_completion . '% complete.',
            ];
        }

        $expiry_ts = $this->get_candidate_dbs_expiry_timestamp($candidate_id, $user_id);
        if ($expiry_ts > 0) {
            $today_ts = current_time('timestamp');
            $soon_ts = strtotime('+30 days', $today_ts);
            if ($expiry_ts <= $today_ts) {
                $issues[] = [
                    'key' => 'dbs_expired',
                    'message' => 'DBS has expired. Please upload an updated DBS document.',
                ];
            } elseif ($expiry_ts <= $soon_ts) {
                $issues[] = [
                    'key' => 'dbs_expiring_soon',
                    'message' => 'DBS expires on ' . date_i18n('M j, Y', $expiry_ts) . '.',
                ];
            }
        }

        return $issues;
    }

    private function should_send_compliance_reminder_issue($user_id, $issue_key, $now_ts) {
        $meta_key = 'cmn_compliance_reminder_sent_' . sanitize_key((string) $issue_key);
        $last_sent = (string) get_user_meta((int) $user_id, $meta_key, true);
        if ($last_sent === '') {
            return true;
        }
        $last_ts = strtotime($last_sent);
        if ($last_ts === false) {
            return true;
        }
        return ($now_ts - $last_ts) >= DAY_IN_SECONDS;
    }

    private function mark_compliance_reminder_issue_sent($user_id, $issue_key) {
        $meta_key = 'cmn_compliance_reminder_sent_' . sanitize_key((string) $issue_key);
        update_user_meta((int) $user_id, $meta_key, current_time('mysql'));
    }

    public function run_compliance_reminders() {
        if (get_transient('cmn_compliance_reminder_lock')) {
            return;
        }
        set_transient('cmn_compliance_reminder_lock', 1, 300);
        $now_ts = time();
        update_option('cmn_compliance_reminder_last_run_ts', $now_ts, false);

        try {
            $candidates = $this->get_candidate_users_for_compliance_reminders();
            if (!$candidates) {
                return;
            }
            foreach ($candidates as $candidate_user) {
                $user_id = isset($candidate_user->ID) ? (int) $candidate_user->ID : 0;
                $email = isset($candidate_user->user_email) ? sanitize_email((string) $candidate_user->user_email) : '';
                if ($user_id < 1 || $email === '' || !$this->is_candidate_user($user_id)) {
                    continue;
                }
                $candidate_id = (int) $this->get_candidate_id_for_user($user_id);
                if ($candidate_id < 1) {
                    continue;
                }

                $issues = $this->build_candidate_compliance_issues($candidate_id, $user_id);
                if (!$issues) {
                    continue;
                }

                $sendable_issues = [];
                foreach ($issues as $issue) {
                    $issue_key = (string) ($issue['key'] ?? '');
                    if ($issue_key === '') {
                        continue;
                    }
                    if ($this->should_send_compliance_reminder_issue($user_id, $issue_key, $now_ts)) {
                        $sendable_issues[] = $issue;
                    }
                }
                if (!$sendable_issues) {
                    continue;
                }

                $portal_profile_link = add_query_arg(['candidate' => 'profile'], $this->get_portal_base_url());
                $issue_lines = [];
                foreach ($sendable_issues as $issue) {
                    $issue_lines[] = '- ' . trim((string) ($issue['message'] ?? 'Compliance item requires attention.'));
                }
                $display_name = trim((string) ($candidate_user->display_name ?? ''));
                if ($display_name === '') {
                    $display_name = 'there';
                }
                $subject = 'Compliance reminder: action needed';
                $message = "Hi {$display_name},\n\nPlease review the following compliance item(s):\n" . implode("\n", $issue_lines) . "\n\nUpdate your profile here:\n{$portal_profile_link}\n\nCoverMeNow ONE";
                $this->send_candidate_email($email, $subject, $message, [
                    'type' => 'candidate_status_update',
                    'user_id' => $user_id,
                    'related_candidate_id' => $candidate_id,
                ]);

                $count = count($sendable_issues);
                $notification_message = $count === 1
                    ? (string) ($sendable_issues[0]['message'] ?? 'Compliance action required.')
                    : sprintf('%d compliance items need your attention.', $count);
                $this->add_notification(
                    $user_id,
                    'candidate_compliance_reminder',
                    'Compliance reminder',
                    $notification_message,
                    $portal_profile_link
                );

                foreach ($sendable_issues as $issue) {
                    $this->mark_compliance_reminder_issue_sent($user_id, (string) ($issue['key'] ?? ''));
                }
            }
        } finally {
            delete_transient('cmn_compliance_reminder_lock');
        }
    }

    private function candidate_allows_availability_nudges($user_id) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return false;
        }
        $this->ensure_candidate_notification_defaults($user_id);
        return get_user_meta($user_id, 'cmn_notify_email_availability_nudges', true) !== '0';
    }

    private function should_send_availability_nudge_slot($user_id, $target_date, $slot) {
        $user_id = (int) $user_id;
        $target_date = sanitize_text_field((string) $target_date);
        $slot = sanitize_key((string) $slot);
        if ($user_id < 1 || $target_date === '' || $slot === '') {
            return false;
        }
        $meta_key = 'cmn_availability_nudge_sent_' . str_replace('-', '', $target_date) . '_' . $slot;
        return get_user_meta($user_id, $meta_key, true) !== '1';
    }

    private function mark_availability_nudge_slot_sent($user_id, $target_date, $slot) {
        $user_id = (int) $user_id;
        $target_date = sanitize_text_field((string) $target_date);
        $slot = sanitize_key((string) $slot);
        if ($user_id < 1 || $target_date === '' || $slot === '') {
            return;
        }
        $meta_key = 'cmn_availability_nudge_sent_' . str_replace('-', '', $target_date) . '_' . $slot;
        update_user_meta($user_id, $meta_key, '1');
    }

    private function maybe_send_post_login_availability_nudge($user_id, $candidate_id, $target_date, $target_label, $window_is_open, $already_marked, $calendar_blocked, $is_online_now) {
        $user_id = (int) $user_id;
        $candidate_id = (int) $candidate_id;
        $target_date = sanitize_text_field((string) $target_date);
        $target_label = sanitize_text_field((string) $target_label);
        if (
            $user_id < 1
            || $candidate_id < 1
            || !$this->is_candidate_user($user_id)
            || $target_date === ''
            || !$window_is_open
            || $already_marked
            || $calendar_blocked
            || !$is_online_now
        ) {
            return;
        }

        $last_login = (int) get_user_meta($user_id, 'cmn_last_login', true);
        if ($last_login < 1) {
            return;
        }

        $nudge_meta_key = 'cmn_post_login_availability_nudge_login_ts';
        $nudge_login_ts = (int) get_user_meta($user_id, $nudge_meta_key, true);
        if ($nudge_login_ts === $last_login) {
            return;
        }

        $dashboard_link = add_query_arg(['candidate' => 'dashboard'], $this->get_portal_base_url());
        $message = 'You are online now. Confirm your availability for ' . $target_label . '.';
        $this->add_notification(
            $user_id,
            'candidate_availability_nudge',
            'Availability reminder',
            $message,
            $dashboard_link
        );
        update_user_meta($user_id, $nudge_meta_key, (string) $last_login);
    }

    private function normalize_location_for_match($value) {
        $value = strtolower(trim((string) $value));
        $value = preg_replace('/[^a-z0-9,\s]/', ' ', $value);
        $value = preg_replace('/\s+/', ' ', $value);
        return trim((string) $value);
    }

    private function locations_roughly_match($candidate_location, $school_location) {
        $candidate_location = $this->normalize_location_for_match($candidate_location);
        $school_location = $this->normalize_location_for_match($school_location);
        if ($candidate_location === '' || $school_location === '') {
            return false;
        }
        if (strpos($school_location, $candidate_location) !== false || strpos($candidate_location, $school_location) !== false) {
            return true;
        }
        $candidate_primary = trim((string) strtok($candidate_location, ','));
        $school_primary = trim((string) strtok($school_location, ','));
        if ($candidate_primary !== '' && $school_primary !== '') {
            return $candidate_primary === $school_primary;
        }
        return false;
    }

    private function get_candidate_school_demand_count_for_date($candidate_id, $target_date) {
        $candidate_id = (int) $candidate_id;
        $target_date = sanitize_text_field((string) $target_date);
        if ($candidate_id < 1 || $target_date === '') {
            return 0;
        }
        $candidate_location = (string) get_post_meta($candidate_id, 'cmn_location', true);
        if ($candidate_location === '') {
            return 0;
        }
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $statuses = ['requested', 'pending', 'staff_reviewing', 'candidate_contacted'];
        $status_placeholders = implode(',', array_fill(0, count($statuses), '%s'));
        $sql = "SELECT DISTINCT school_email_domain FROM {$table} WHERE requested_date = %s AND status IN ({$status_placeholders})";
        $params = array_merge([$target_date], $statuses);
        $domains = (array) $wpdb->get_col($wpdb->prepare($sql, $params));
        if (!$domains) {
            return 0;
        }
        $count = 0;
        foreach ($domains as $domain) {
            $domain = sanitize_text_field((string) $domain);
            if ($domain === '') {
                continue;
            }
            $school_id = (int) $this->get_school_post_id_by_domain($domain);
            if ($school_id < 1) {
                continue;
            }
            $school_location = (string) get_post_meta($school_id, 'cmn_location', true);
            if ($this->locations_roughly_match($candidate_location, $school_location)) {
                $count++;
            }
        }
        return $count;
    }

    public function run_availability_nudges() {
        if (get_transient('cmn_availability_nudge_lock')) {
            return;
        }
        set_transient('cmn_availability_nudge_lock', 1, 300);
        try {
            $tz = wp_timezone();
            $now = new DateTime('now', $tz);
            $hour = (int) $now->format('G');
            if ($hour !== 18 && $hour !== 19) {
                return;
            }
            $slot = (string) $hour;
            $slot_key = $now->format('Y-m-d-H');
            $last_slot = (string) get_option('cmn_availability_nudge_last_slot', '');
            if ($last_slot === $slot_key) {
                return;
            }

            $target_date = (clone $now)->modify('+1 day')->format('Y-m-d');
            $target_day = (int) (clone $now)->modify('+1 day')->format('N');
            if ($target_day < 1 || $target_day > 5) {
                return;
            }
            $target_label = date_i18n('l, F jS', strtotime($target_date));
            $dashboard_link = add_query_arg(['candidate' => 'dashboard'], $this->get_portal_base_url());
            $candidates = $this->get_candidate_users_for_compliance_reminders();
            foreach ($candidates as $candidate_user) {
                $user_id = isset($candidate_user->ID) ? (int) $candidate_user->ID : 0;
                $email = isset($candidate_user->user_email) ? sanitize_email((string) $candidate_user->user_email) : '';
                if ($user_id < 1 || $email === '' || !$this->is_candidate_user($user_id)) {
                    continue;
                }
                if (!$this->candidate_allows_availability_nudges($user_id)) {
                    continue;
                }
                if (!$this->should_send_availability_nudge_slot($user_id, $target_date, $slot)) {
                    continue;
                }
                $candidate_id = (int) $this->get_candidate_id_for_user($user_id);
                if ($candidate_id < 1) {
                    continue;
                }
                if ($this->has_candidate_availability($candidate_id, $target_date)) {
                    continue;
                }
                if ($this->is_candidate_unavailable($candidate_id, $target_date)) {
                    continue;
                }

                $demand_count = $this->get_candidate_school_demand_count_for_date($candidate_id, $target_date);
                $demand_line = '';
                if ($demand_count >= 3) {
                    $demand_line = "\n\nDemand is high: {$demand_count} schools are searching in your area for {$target_label}.";
                }
                $display_name = trim((string) ($candidate_user->display_name ?? ''));
                if ($display_name === '') {
                    $display_name = 'there';
                }

                if ($hour === 18) {
                    $subject = 'Availability reminder for tomorrow';
                    $message = "Hi {$display_name},\n\nYou can confirm your availability for {$target_label} after 7pm.\n\nOpen your dashboard:\n{$dashboard_link}{$demand_line}\n\nCoverMeNow ONE";
                    $bell_message = "Reminder: confirm your availability after 7pm for {$target_label}.";
                } else {
                    $subject = 'Confirm your availability now';
                    $message = "Hi {$display_name},\n\nYou can now confirm your availability for {$target_label}.\n\nOpen your dashboard:\n{$dashboard_link}{$demand_line}\n\nCoverMeNow ONE";
                    $bell_message = "You can now confirm availability for {$target_label}.";
                    if ($demand_count >= 3) {
                        $bell_message .= " {$demand_count} schools are searching in your area.";
                    }
                }

                $this->send_candidate_email($email, $subject, $message, [
                    'type' => 'candidate_availability_nudge',
                    'user_id' => $user_id,
                    'related_candidate_id' => $candidate_id,
                ]);

                $this->add_notification(
                    $user_id,
                    'candidate_availability_nudge',
                    'Availability reminder',
                    $bell_message,
                    $dashboard_link
                );

                $this->mark_availability_nudge_slot_sent($user_id, $target_date, $slot);
            }

            update_option('cmn_availability_nudge_last_slot', $slot_key, false);
        } finally {
            delete_transient('cmn_availability_nudge_lock');
        }
    }

    private function has_booking_for_candidate_date($candidate_id, $date) {
        if (!$candidate_id || !$date) {
            return false;
        }
        $existing = get_posts([
            'post_type' => 'cmn_booking',
            'posts_per_page' => 10,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_candidate_id',
                    'value' => (int) $candidate_id,
                ],
                [
                    'key' => 'cmn_date',
                    'value' => $date,
                ],
            ],
        ]);
        if (!$existing) {
            return false;
        }
        foreach ($existing as $booking_id) {
            $status = get_post_meta($booking_id, 'cmn_status', true);
            if (!in_array($status, ['declined', 'expired'], true)) {
                return true;
            }
        }
        return false;
    }

    private function create_booking_from_request($request, $school_id, $created_by) {
        $candidate_id = (int) ($request['candidate_id'] ?? 0);
        $request_id = (int) ($request['id'] ?? 0);
        $requested_date = sanitize_text_field($request['requested_date'] ?? '');
        if (!$candidate_id || !$requested_date || !$school_id) {
            return 0;
        }
        $request = $this->ensure_request_has_guardrail_rates((array) $request);
        $rate_values = $this->get_request_rate_values($request, $candidate_id, $school_id);
        $candidate = get_post($candidate_id);
        $role_meta = (array) get_post_meta($candidate_id, 'cmn_roles', true);
        $role = $role_meta ? $role_meta[0] : 'Candidate';
        $location = get_post_meta($school_id, 'cmn_location', true);
        $title = $candidate ? $candidate->post_title : 'Candidate';
        $post_id = wp_insert_post([
            'post_type' => 'cmn_booking',
            'post_title' => $title . ' - ' . $requested_date,
            'post_status' => 'publish',
        ]);
        if (is_wp_error($post_id) || !$post_id) {
            return 0;
        }
        update_post_meta($post_id, 'cmn_date', $requested_date);
        update_post_meta($post_id, 'cmn_start_date', $requested_date);
        update_post_meta($post_id, 'cmn_status', 'approved');
        update_post_meta($post_id, 'cmn_role', $role);
        update_post_meta($post_id, 'cmn_location', $location);
        update_post_meta($post_id, 'cmn_school_id', $school_id);
        update_post_meta($post_id, 'cmn_candidate_id', $candidate_id);
        update_post_meta($post_id, 'cmn_booking_type', 'morning');
        update_post_meta($post_id, 'cmn_source', 'availability_request');
        update_post_meta($post_id, 'cmn_created_by', (int) $created_by);
        update_post_meta($post_id, 'cmn_created_at', time());
        update_post_meta($post_id, 'cmn_candidate_pay_rate', (float) $rate_values['candidate_pay_rate']);
        update_post_meta($post_id, 'cmn_school_charge_rate', (float) $rate_values['school_charge_rate']);
        $this->upsert_booking_rates(
            (int) $post_id,
            $request_id,
            (string) $rate_values['role_key'],
            (string) $rate_values['region_key'],
            (float) $rate_values['school_charge_rate'],
            (float) $rate_values['candidate_pay_rate'],
            0,
            'Booking created with default guardrail rates'
        );
        $confirmation_seed = $this->ensure_booking_completion_confirmations_for_booking(
            (int) $post_id,
            (int) $this->get_school_user_id_for_request((array) $request, (int) $school_id)
        );
        if (is_wp_error($confirmation_seed)) {
            $this->add_audit_log('school_partner_confirmation_seed_failed', 'booking', (string) $post_id, [
                'school_id' => (int) $school_id,
                'school_user_id' => (int) $this->get_school_user_id_for_request((array) $request, (int) $school_id),
                'message' => $confirmation_seed->get_error_message(),
                'source' => 'create_booking_from_request',
            ], (int) $created_by);
        }
        return (int) $post_id;
    }

    private function get_school_primary_contact_email($school_id) {
        if (!$school_id) {
            return '';
        }
        $email = get_post_meta($school_id, 'cmn_primary_contact_email', true);
        if (!$email) {
            $email = get_post_meta($school_id, 'cmn_contact1_email', true);
        }
        if (!$email) {
            $email = get_post_meta($school_id, 'cmn_email', true);
        }
        return sanitize_email($email);
    }

    private function get_school_user_id_for_request($request, $school_id) {
        $user_id = isset($request['school_user_id']) ? (int) $request['school_user_id'] : 0;
        if ($user_id) {
            return $user_id;
        }
        $email = $this->get_school_primary_contact_email($school_id);
        if ($email) {
            $user = get_user_by('email', $email);
            if ($user) {
                return (int) $user->ID;
            }
        }
        return 0;
    }

    private function count_available_candidates() {
        global $wpdb;
        $table = $this->get_candidate_availability_table();
        $tomorrow = $this->get_tomorrow_date();
        if (!$table || !$tomorrow) {
            return 0;
        }
        $count = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$table} WHERE available_date = %s AND available_type = %s",
            $tomorrow,
            'morning'
        ));
        return (int) $count;
    }

    private function count_available_candidates_for_date($date) {
        global $wpdb;
        $table = $this->get_candidate_availability_table();
        $date = (string) $date;
        if (!$table || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
            return 0;
        }
        $count = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$table} WHERE available_date = %s AND available_type = %s",
            $date,
            'morning'
        ));
        return (int) $count;
    }

