                        </header>
                        <?php
                        $partner_savings_data = new WP_Error('cmn_partner_savings_unavailable', 'Partner savings is unavailable right now.');
                        $partner_dashboard_user_id = (int) get_current_user_id();
                        if (!$this->is_school_user($partner_dashboard_user_id)) {
                            $partner_savings_data = new WP_Error('cmn_partner_savings_school_only', 'Not authorised');
                        } else {
                            $partner_savings_data = cmn_get_school_partner_dashboard_data($partner_dashboard_user_id);
                        }
                        ?>
                        <?php if (is_wp_error($partner_savings_data)) : ?>
                            <div class="cmn-dashboard-card">
                                <div class="cmn-empty"><?php echo esc_html($partner_savings_data->get_error_message()); ?></div>
                            </div>
                        <?php else : ?>
                            <?php
                            $partner_current_tier = (string) ($partner_savings_data['current_tier'] ?? 'Standard');
                            $partner_current_tier_key = sanitize_key((string) ($partner_savings_data['current_tier_key'] ?? 'standard'));
                            $partner_discount_percent = round((float) ($partner_savings_data['discount_percent'] ?? 0), 2);
                            $partner_discount_label = rtrim(rtrim(number_format($partner_discount_percent, 2, '.', ''), '0'), '.');
                            if ($partner_discount_label === '') {
                                $partner_discount_label = '0';
                            }
                            $partner_confirmed_days = max(0, (int) ($partner_savings_data['confirmed_completed_days'] ?? 0));
                            $partner_next_threshold = isset($partner_savings_data['next_threshold']) && $partner_savings_data['next_threshold'] !== null
                                ? max(0, (int) $partner_savings_data['next_threshold'])
                                : 0;
                            $partner_next_tier_label = (string) ($partner_savings_data['next_tier_label'] ?? '');
                            $partner_progress_percent = round(max(0, min(100, (float) ($partner_savings_data['progress_percent'] ?? 0))), 2);
                            $partner_estimated_savings_total = round((float) ($partner_savings_data['estimated_savings_total'] ?? 0), 2);
                            $partner_estimated_savings_updated_at = (string) ($partner_savings_data['estimated_savings_updated_at'] ?? '');
                            $partner_has_overdue_confirmations = !empty($partner_savings_data['has_overdue_confirmations']);
                            $partner_tier_breakdown = is_array($partner_savings_data['tier_breakdown'] ?? null) ? (array) $partner_savings_data['tier_breakdown'] : [];
                            $partner_savings_updated_label = 'Not updated yet.';
                            if ($partner_estimated_savings_updated_at !== '') {
