                    <?php endif; ?>
                </main>
            </div>
        </section>
        <div id="cmn-portal-overlay-root" aria-live="polite" aria-atomic="true"></div>
        <?php
        return ob_get_clean();
    }

    public function render_candidate_dashboard_shortcode() {
        $user = wp_get_current_user();
        $candidate_id = 0;
        $is_preview = isset($_GET['as']) && sanitize_text_field($_GET['as']) === 'candidate' && $this->can_preview_dashboards();
        $candidate_url = add_query_arg(['view' => 'register-candidate'], $this->get_portal_base_url());
        if ($user && $user->user_email) {
            $candidate = get_posts([
                'post_type' => 'cmn_candidate',
                'posts_per_page' => 1,
                'meta_query' => [
                    [
                        'key' => 'cmn_email',
                        'value' => $user->user_email,
                    ],
                ],
            ]);
            if (!empty($candidate)) {
                $candidate_id = $candidate[0]->ID;
            }
        }

        $meta = function ($key) use ($candidate_id) {
            return $candidate_id ? get_post_meta($candidate_id, $key, true) : '';
        };
        $roles = (array) $meta('cmn_roles');
        $role_label = $roles ? $roles[0] : 'Candidate';
        $candidate_user_id = $user ? (int) $user->ID : 0;
        $first_name = $candidate_user_id ? (string) get_user_meta($candidate_user_id, 'first_name', true) : '';
        $last_name = $candidate_user_id ? (string) get_user_meta($candidate_user_id, 'last_name', true) : '';
        $profile_name = trim($first_name . ' ' . $last_name);
        if ($profile_name === '') {
            $profile_name = $candidate_id ? get_the_title($candidate_id) : ($user ? $user->display_name : 'Candidate');
            $parts = preg_split('/\s+/', trim((string) $profile_name));
            if ($first_name === '') {
                $first_name = (string) ($parts[0] ?? '');
            }
            if ($last_name === '' && count($parts) > 1) {
                $last_name = (string) end($parts);
            }
        }
        $profile_photo_state = $this->get_candidate_profile_photo_state($candidate_id, $candidate_user_id);
        $profile_photo_url = (string) ($profile_photo_state['url'] ?? $this->get_default_profile_photo_url());
        $has_profile_photo = !empty($profile_photo_state['has_photo']);
        $profile_photo_fallback = $this->get_default_profile_photo_url();
        $profile_email = $meta('cmn_email') ?: ($user ? $user->user_email : '');
        $profile_phone = $candidate_user_id ? (string) get_user_meta($candidate_user_id, 'phone', true) : '';
        if ($profile_phone === '') {
            $profile_phone = (string) $meta('cmn_phone');
        }
        $profile_nationality = (string) $meta('cmn_nationality');
        if ($profile_nationality === '' && $candidate_user_id > 0) {
            $profile_nationality = (string) get_user_meta($candidate_user_id, 'cmn_nationality', true);
        }
        $profile_location = (string) $meta('cmn_location');
        $profile_postcode = $meta('cmn_postcode');
        $profile_house_number = (string) $meta('cmn_house_number');
        $profile_address_line1 = (string) $meta('cmn_address_line1');
        $profile_address_line2 = (string) $meta('cmn_address_line2');
        $profile_address_line3 = (string) $meta('cmn_address_line3');
        $profile_town = (string) $meta('cmn_town');
        $profile_county = (string) $meta('cmn_county');
        $profile_notes = (string) $meta('cmn_notes');
        $travel_distance = $candidate_user_id ? (string) get_user_meta($candidate_user_id, 'travel_radius', true) : '';
        if ($travel_distance === '') {
            $travel_distance = (string) $meta('cmn_travel_distance');
        }
        $role_type = $candidate_user_id ? (string) get_user_meta($candidate_user_id, 'role_type', true) : '';
        if ($role_type !== '') {
            $role_label = $role_type;
        }
        $driving_licence = strtolower((string) $meta('cmn_driving_licence'));
        $car_owner = strtolower((string) $meta('cmn_car_owner'));
        $qts_status = strtolower((string) $meta('cmn_qts_status'));
        $no_dbs = (string) $meta('cmn_no_dbs');
        $dbs_update_service = strtolower((string) $meta('cmn_dbs_update_service'));
        if ($dbs_update_service === '' && $candidate_user_id > 0) {
            $dbs_update_service = strtolower((string) get_user_meta($candidate_user_id, 'cmn_dbs_update_service', true));
        }
        $roles_other = (string) $meta('cmn_roles_other');
        $preferred_roles = array_values(array_filter(array_map('sanitize_text_field', (array) $roles)));
        if (!$preferred_roles && $role_label !== '') {
            $preferred_roles = [$role_label];
        }
        $preferred_roles_label = $preferred_roles ? implode(', ', $preferred_roles) : 'Not set';
        $availability_days = (array) $meta('cmn_availability_days');
        if (!$availability_days) {
            $availability_days_raw = (string) $meta('cmn_availability_days');
            if ($availability_days_raw !== '') {
                $availability_days = array_map('trim', explode(',', $availability_days_raw));
            }
        }
        $availability_days = array_values(array_filter(array_map('sanitize_text_field', (array) $availability_days)));
        $yes_no_map = [
            'yes' => 'Yes',
            'no' => 'No',
        ];
        $driving_licence_label = $yes_no_map[$driving_licence] ?? 'Not set';
        $car_owner_label = $yes_no_map[$car_owner] ?? 'Not set';
        $qts_status_label = $yes_no_map[$qts_status] ?? 'Not set';
        $dbs_update_label = $yes_no_map[$dbs_update_service] ?? 'Not set';
        $availability_days_label = $availability_days ? implode(', ', $availability_days) : 'Not set';
        $profile_address_parts = array_filter([
            $profile_house_number,
            $profile_address_line1,
            $profile_address_line2,
            $profile_address_line3,
            $profile_town,
            $profile_county,
            $profile_postcode,
        ]);
        $profile_address_display = $profile_address_parts ? implode(', ', $profile_address_parts) : 'Not set';
        $doc_dbs = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, 'dbs');
        $doc_id = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, 'id');
        $doc_cv = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, 'cv');
        $has_dbs_label = (
            !empty($doc_dbs['uploaded'])
            && (string) ($doc_dbs['review_status'] ?? '') === 'approved'
        ) ? 'Yes' : ($no_dbs === '1' ? 'No' : 'Not set');
        $doc_summary = $this->get_candidate_doc_summary([
            'dbs' => $doc_dbs,
            'id' => $doc_id,
            'cv' => $doc_cv,
        ]);
        $compliance_status_payload = $this->get_candidate_compliance_payload($candidate_id, $candidate_user_id);
        if ($candidate_id && $candidate_user_id) {
            $this->sync_candidate_admin_verification_status($candidate_id, $candidate_user_id, [
                'dbs' => $doc_dbs,
                'id' => $doc_id,
                'cv' => $doc_cv,
            ]);
            $this->maybe_notify_candidate_qts_required($candidate_id, $candidate_user_id);
        }
        $learning_opt_in = $candidate_user_id ? get_user_meta($candidate_user_id, 'cmn_learning_notify_opt_in', true) === '1' : false;
        $contact_card_skill_options = [
            'Communication',
            'Building Rapport',
            'Classroom Management',
            'Lesson Planning',
            'Behaviour Management',
            'Punctuality',
            'Safeguarding Awareness',
            'Adaptability',
            'Professionalism',
            'Teamwork',
        ];
        $saved_contact_card_skills = [];
        if ($candidate_user_id > 0) {
            $saved_contact_card_skills = get_user_meta($candidate_user_id, 'cmn_contact_card_skills', true);
        }
        if (!$saved_contact_card_skills && $candidate_id > 0) {
            $saved_contact_card_skills = get_post_meta($candidate_id, 'cmn_contact_card_skills', true);
        }
        if (is_string($saved_contact_card_skills) && $saved_contact_card_skills !== '') {
            $decoded_contact_card_skills = json_decode($saved_contact_card_skills, true);
            if (is_array($decoded_contact_card_skills)) {
                $saved_contact_card_skills = $decoded_contact_card_skills;
            } else {
                $saved_contact_card_skills = array_map('trim', explode(',', $saved_contact_card_skills));
            }
        }
        if (!is_array($saved_contact_card_skills)) {
            $saved_contact_card_skills = [];
        }
        $saved_contact_card_skills = array_values(array_unique(array_filter(array_map(
            static function ($item) {
                return sanitize_text_field((string) $item);
            },
            $saved_contact_card_skills
        ))));
        if (count($saved_contact_card_skills) > 3) {
            $saved_contact_card_skills = array_slice($saved_contact_card_skills, 0, 3);
        }
        $saved_contact_card_custom_skill = '';
        foreach ($saved_contact_card_skills as $contact_skill) {
            if (!in_array($contact_skill, $contact_card_skill_options, true)) {
                $saved_contact_card_custom_skill = $contact_skill;
                break;
            }
        }
        $contact_card_skill_preview = $saved_contact_card_skills;
        if (empty($contact_card_skill_preview)) {
            $contact_card_skill_preview = ['Select 3 skills to complete your contact card'];
        }

        $completion_percent = 0;
        $completion_missing_items = [];
        if ($candidate_id && $candidate_user_id) {
            $completion_state = $this->get_candidate_profile_completion_state($candidate_id, $candidate_user_id);
            $completion_missing_items = (array) ($completion_state['missing'] ?? []);
            $completion_percent = $this->update_candidate_profile_completion($candidate_id, $candidate_user_id);
        }

        $tz = wp_timezone();
        try {
            $now = new DateTime('now', $tz);
        } catch (Exception $e) {
            $now = new DateTime('@' . current_time('timestamp'));
            $now->setTimezone($tz);
            error_log('CMN availability fallback DateTime used in candidate dashboard: ' . $e->getMessage());
        }
        $availability_window = $this->get_candidate_availability_window($now);
        $availability_allowed = !empty($availability_window['is_open']);
        $target_date = (string) ($availability_window['target_date'] ?? '');
        if (!$target_date || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $target_date)) {
            $target_date = date_i18n('Y-m-d', strtotime('+1 day', current_time('timestamp')));
            error_log('CMN availability fallback target_date used in candidate dashboard render.');
        }
        $already_marked = $candidate_id ? $this->has_candidate_availability($candidate_id, $target_date) : false;
        $calendar_blocked = $candidate_id ? $this->is_candidate_unavailable($candidate_id, $target_date) : false;
        $availability_confirmed_entry = ($candidate_id && $already_marked)
            ? $this->get_candidate_availability_entry($candidate_id, $target_date)
            : null;
        $availability_confirmed_time_label = '';
        if (is_array($availability_confirmed_entry) && !empty($availability_confirmed_entry['created_at'])) {
            try {
                $confirmed_dt = new DateTime((string) $availability_confirmed_entry['created_at'], wp_timezone());
                $availability_confirmed_time_label = $confirmed_dt->format('H:i');
            } catch (Exception $e) {
                $availability_confirmed_time_label = '';
            }
        }
        $saved_contact_card_show_available_raw = '';
        if ($candidate_user_id > 0) {
            $saved_contact_card_show_available_raw = (string) get_user_meta($candidate_user_id, 'cmn_contact_card_show_available', true);
        }
        if ($saved_contact_card_show_available_raw === '' && $candidate_id > 0) {
            $saved_contact_card_show_available_raw = (string) get_post_meta($candidate_id, 'cmn_contact_card_show_available', true);
        }
        $contact_card_show_available = ($already_marked && !$calendar_blocked);
        if ($saved_contact_card_show_available_raw !== '') {
            $contact_card_show_available = in_array(strtolower(trim($saved_contact_card_show_available_raw)), ['1', 'true', 'yes', 'on'], true);
        }
        if ($candidate_user_id > 0) {
            $this->touch_candidate_presence($candidate_user_id, false);
        }
        $candidate_presence_snapshot = $candidate_user_id > 0
            ? $this->get_candidate_presence_snapshot($candidate_user_id)
            : ['is_online' => false, 'last_online_label' => 'Last seen at --:--'];
        $contact_card_is_online_now = !empty($candidate_presence_snapshot['is_online']);
        $contact_card_last_online_label = sanitize_text_field((string) ($candidate_presence_snapshot['last_online_label'] ?? 'Last seen at --:--'));
        if ($contact_card_last_online_label === '') {
            $contact_card_last_online_label = 'Last seen at --:--';
        }
        $availability_target_label = date_i18n('l, F jS', strtotime($target_date));
        if (!$is_preview && $candidate_user_id > 0 && $candidate_id > 0) {
            $this->maybe_send_post_login_availability_nudge(
                $candidate_user_id,
                $candidate_id,
                $target_date,
                $availability_target_label,
                $availability_allowed,
                $already_marked,
                $calendar_blocked,
                $contact_card_is_online_now
            );
        }
        $contact_card_display_name = $first_name !== '' ? $first_name : $profile_name;
        $contact_card_feedback_percent = $feedback_has_reviews ? max(0.0, min(100.0, ($feedback_score_raw / 5) * 100)) : 0.0;
        $contact_card_feedback_text = number_format((float) $feedback_score_raw, 2) . ' out of 5 stars';
        $contact_card_primary_role = trim((string) $role_label) !== '' ? trim((string) $role_label) : 'Not set';
        $contact_card_distance_raw = trim((string) $travel_distance);
        $contact_card_distance_label = 'Not set';
        if ($contact_card_distance_raw !== '') {
            if (preg_match('/^\d+(\.\d+)?$/', $contact_card_distance_raw)) {
                $numeric_distance = (float) $contact_card_distance_raw;
                $contact_card_distance_label = rtrim(rtrim(number_format($numeric_distance, 1, '.', ''), '0'), '.') . ' miles';
            } else {
                $contact_card_distance_label = $contact_card_distance_raw;
                $has_time_unit = preg_match('/\b(min|mins|minute|minutes|hour|hours|hr|hrs)\b/i', $contact_card_distance_label);
                $has_distance_unit = preg_match('/\b(mile|miles|mi|km|kilometre|kilometer|kilometres|kilometers)\b/i', $contact_card_distance_label);
                if ($has_time_unit) {
                    $contact_card_distance_label = trim((string) preg_replace('/\s*miles?\b/i', '', $contact_card_distance_label));
                } elseif (!$has_distance_unit) {
                    $contact_card_distance_label .= ' miles';
                }
            }
        }
        $contact_card_availability_class = $contact_card_show_available ? 'is-available' : 'is-pending';
        $contact_card_id_verified = ((string) ($doc_id['doc_status'] ?? '') === 'approved');
        $contact_card_dbs_verified = ((string) ($doc_dbs['doc_status'] ?? '') === 'approved');
        $contact_card_compliance_complete = empty($completion_missing_items);
        $contact_card_profile_completion_pct = max(0, min(100, (int) round((float) $completion_percent)));
        $contact_card_status_pending_label = 'NOT YET CONFIRMED';
        $contact_card_status_available_label = 'BOOKABLE';
        $contact_card_status_pending_detail = '';
        $contact_card_availability_label = $contact_card_show_available ? $contact_card_status_available_label : $contact_card_status_pending_label;
        $contact_card_button_time_label = $already_marked && $availability_confirmed_time_label !== ''
            ? ('Confirmed at ' . $availability_confirmed_time_label)
            : '';
        $contact_card_status_available_detail = $contact_card_button_time_label !== ''
            ? $contact_card_button_time_label
            : 'Confirmed';
        $contact_card_status_detail = $contact_card_show_available ? $contact_card_status_available_detail : $contact_card_status_pending_detail;
        $contact_card_verified_bundle = $contact_card_id_verified && $contact_card_dbs_verified;
        $contact_card_other_checked = $saved_contact_card_custom_skill !== '';

        [$calendar_start, $calendar_end] = $this->get_calendar_limit_dates();
        $calendar_window_start = DateTime::createFromFormat('Y-m-d', $calendar_start, $tz);
        $calendar_window_end = DateTime::createFromFormat('Y-m-d', $calendar_end, $tz);
        if (!$calendar_window_start || !$calendar_window_end) {
            $calendar_window_start = (clone $now)->modify('+1 day');
            $calendar_window_end = new DateTime($calendar_window_start->format('Y') . '-07-31', $tz);
            if ($calendar_window_start > $calendar_window_end) {
                $calendar_window_end = new DateTime(((int) $calendar_window_start->format('Y') + 1) . '-07-31', $tz);
            }
            $calendar_start = $calendar_window_start->format('Y-m-d');
            $calendar_end = $calendar_window_end->format('Y-m-d');
        }
        $calendar_min_date = $calendar_start;
        $calendar_max_date = $calendar_end;
        $calendar_weekday_options = [];
        $calendar_default_start_date = $calendar_min_date;
        $calendar_default_end_date = $calendar_min_date;
        $calendar_cursor = clone $calendar_window_start;
        while ($calendar_cursor <= $calendar_window_end) {
            $weekday_number = (int) $calendar_cursor->format('N');
            if ($weekday_number <= 5) {
                $option_value = $calendar_cursor->format('Y-m-d');
                $calendar_weekday_options[] = [
                    'value' => $option_value,
                    'label' => date_i18n('D j M', strtotime($option_value)),
                ];
                if (count($calendar_weekday_options) === 1) {
                    $calendar_default_start_date = $option_value;
                }
                $calendar_default_end_date = $option_value;
            }
            $calendar_cursor->modify('+1 day');
        }
        if (!$calendar_weekday_options) {
            $calendar_weekday_options[] = [
                'value' => $calendar_min_date,
                'label' => date_i18n('D j M', strtotime($calendar_min_date)),
            ];
            $calendar_default_start_date = $calendar_min_date;
            $calendar_default_end_date = $calendar_min_date;
        }
        $calendar_min_month = $calendar_window_start->format('Y-m');
        $calendar_max_month = $calendar_window_end->format('Y-m');
        $calendar_map = $candidate_id ? $this->get_candidate_calendar_map($candidate_id, $calendar_start, $calendar_end) : [];
        $calendar_data = $calendar_map;
        $cal_month = $calendar_min_month;
        $month_start = new DateTime($cal_month . '-01', $tz);
        $days_in_month = (int) $month_start->format('t');
        $start_weekday = (int) $month_start->format('N'); // 1 (Mon) - 7 (Sun)

        $available_count = 0;
        $unavailable_count = 0;
        $next_available = '';
        foreach ($calendar_data as $date => $status) {
            if ($status === 'available') {
                $available_count++;
                if ($date >= $calendar_min_date && ($next_available === '' || $date < $next_available)) {
                    $next_available = $date;
                }
            }
            if ($status === 'unavailable') {
                $unavailable_count++;
            }
        }
        $tour_dismissed = $user && $user->ID ? get_user_meta($user->ID, 'cmn_candidate_tour_dismissed', true) === '1' : true;
        $next_available_label = $next_available ? (new DateTime($next_available, $tz))->format('l, F jS') : 'Not set';

        $today = current_time('Y-m-d');
        $upcoming_booking = null;
        $past_bookings = [];
        $candidate_requests = [];
        $earnings_metrics = [
            'month_total' => 0.0,
            'academic_year_total' => 0.0,
            'lifetime_total' => 0.0,
            'upcoming_total' => 0.0,
            'average_daily_rate' => 0.0,
            'completed_count' => 0,
        ];
        if ($candidate_id) {
            $upcoming_query = new WP_Query([
                'post_type' => 'cmn_booking',
                'posts_per_page' => 1,
                'meta_query' => [
                    [
                        'key' => 'cmn_candidate_id',
                        'value' => $candidate_id,
                    ],
                    [
                        'key' => 'cmn_status',
                        'value' => 'approved',
                    ],
                    [
                        'key' => 'cmn_date',
                        'value' => $today,
                        'compare' => '>=',
                        'type' => 'DATE',
                    ],
                ],
                'meta_key' => 'cmn_date',
                'orderby' => 'meta_value',
                'order' => 'ASC',
            ]);
            if ($upcoming_query->have_posts()) {
                $upcoming_booking = $upcoming_query->posts[0];
            }
            wp_reset_postdata();
            $past_query = new WP_Query([
                'post_type' => 'cmn_booking',
                'posts_per_page' => 5,
                'meta_query' => [
                    [
                        'key' => 'cmn_candidate_id',
                        'value' => $candidate_id,
                    ],
                    [
                        'key' => 'cmn_status',
                        'value' => 'approved',
                    ],
                    [
                        'key' => 'cmn_date',
                        'value' => $today,
                        'compare' => '<',
                        'type' => 'DATE',
                    ],
                ],
                'meta_key' => 'cmn_date',
                'orderby' => 'meta_value',
                'order' => 'DESC',
            ]);
            if ($past_query->have_posts()) {
                $past_bookings = $past_query->posts;
            }
            wp_reset_postdata();
            $candidate_requests = $this->get_candidate_requests_for_candidate($candidate_id, 20);
            $earnings_metrics = $this->get_candidate_earnings_metrics($candidate_id);
        }

        $weekly_earnings_payload = [
            'week_range' => [
                'start_date' => '',
                'end_date' => '',
                'label' => 'Fri-Thu',
            ],
            'total' => 0.00,
            'expected_payout' => 0.00,
            'last_week_total' => 0.00,
        ];
        $weekly_earnings_error = '';
        if ($candidate_user_id > 0 && $this->is_candidate_user($candidate_user_id)) {
            $weekly_earnings_result = $this->get_candidate_weekly_earnings_payload($candidate_user_id, true);
            if (is_wp_error($weekly_earnings_result)) {
                $weekly_earnings_error = $weekly_earnings_result->get_error_message();
            } elseif (is_array($weekly_earnings_result)) {
                $weekly_earnings_payload = array_merge($weekly_earnings_payload, $weekly_earnings_result);
            }
        }
        $weekly_earnings_week_label = sanitize_text_field((string) (($weekly_earnings_payload['week_range']['label'] ?? 'Fri-Thu')));
        $weekly_earnings_total = round((float) ($weekly_earnings_payload['total'] ?? 0), 2);
        $weekly_expected_payout = round((float) ($weekly_earnings_payload['expected_payout'] ?? $weekly_earnings_total), 2);
        $weekly_expected_is_hold = !empty($weekly_earnings_payload['expected_payout_is_hold']);
        $weekly_expected_hold_message = sanitize_text_field((string) ($weekly_earnings_payload['expected_payout_display'] ?? 'On hold until bank details added'));
        $weekly_expected_display = $weekly_expected_is_hold
            ? ($weekly_expected_hold_message !== '' ? $weekly_expected_hold_message : 'On hold until bank details added')
            : ('GBP ' . number_format($weekly_expected_payout, 2));
        $weekly_last_week_total = round((float) ($weekly_earnings_payload['last_week_total'] ?? 0), 2);
        $weekly_state_label = sanitize_text_field((string) ($weekly_earnings_payload['payout_state_label'] ?? 'Estimate'));
        $weekly_state_chip_class = sanitize_html_class((string) ($weekly_earnings_payload['payout_state_chip_class'] ?? 'is-pending'));
        if ($weekly_state_chip_class === '') {
            $weekly_state_chip_class = 'is-pending';
        }
        $weekly_state_note = sanitize_text_field((string) ($weekly_earnings_payload['payout_state_note'] ?? 'Estimate (pending lock).'));
        if ($weekly_state_note === '') {
            $weekly_state_note = 'Estimate (pending lock).';
        }
        $weekly_pay_date_raw = $this->normalize_invoice_date((string) ($weekly_earnings_payload['pay_date'] ?? ''));
        if ($weekly_pay_date_raw === '') {
            $range_end_for_payday = $this->normalize_invoice_date((string) (($weekly_earnings_payload['week_range']['end_date'] ?? '')));
            if ($range_end_for_payday !== '' && strtotime($range_end_for_payday) !== false) {
                $weekly_pay_date_raw = gmdate('Y-m-d', strtotime($range_end_for_payday . ' +1 day'));
            }
        }
        if ($weekly_pay_date_raw === '' || strtotime($weekly_pay_date_raw) === false) {
            $weekly_pay_date_raw = gmdate('Y-m-d', strtotime(current_time('Y-m-d') . ' next friday'));
        }
        $weekly_pay_date_display = date_i18n('d/m/Y', strtotime($weekly_pay_date_raw));

        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        $tab = isset($_GET['candidate']) ? sanitize_text_field($_GET['candidate']) : 'dashboard';
        $cmn_tab = isset($_GET['cmn_tab']) ? sanitize_key((string) wp_unslash($_GET['cmn_tab'])) : '';
        if ($cmn_tab === 'candidate_finance') {
            $tab = 'candidate_finance';
        }
        $is_candidate_rewards_allowed = $candidate_user_id > 0 && $this->is_candidate_user($candidate_user_id);
        $candidate_profile_url = add_query_arg(['candidate' => 'profile'], $portal_url);
        $candidate_profile_personal_url = add_query_arg([
            'candidate' => 'profile',
            'cmn_profile_focus' => 'personal',
        ], $portal_url) . '#cmn-profile-personal';
        $candidate_profile_documents_url = add_query_arg([
            'candidate' => 'profile',
            'cmn_profile_focus' => 'documents',
        ], $portal_url) . '#cmn-profile-documents';
        $candidate_profile_contact_card_url = add_query_arg([
            'candidate' => 'profile',
            'cmn_profile_focus' => 'contact_card',
        ], $portal_url) . '#cmn-profile-contact-card';
        $profile_focus_tab_raw = strtolower(trim((string) (wp_unslash($_GET['cmn_profile_focus'] ?? 'personal'))));
        if (in_array($profile_focus_tab_raw, ['documents', 'document', 'doc', 'docs'], true)) {
            $profile_focus_tab = 'documents';
        } elseif (in_array($profile_focus_tab_raw, ['contact_card', 'contact-card', 'contactcard', 'contact'], true)) {
            $profile_focus_tab = 'contact_card';
        } else {
            $profile_focus_tab = 'personal';
        }
        $hub_tabs = ['profile', 'candidate_finance', 'feedback_ratings', 'calendar', 'bookings'];
        $is_hub_tab = in_array($tab, $hub_tabs, true);
        $candidate_learning_url = add_query_arg(['candidate' => 'learning'], $portal_url);
        $candidate_rewards_url = add_query_arg(['candidate' => 'rewards'], $portal_url);
        $candidate_feedback_url = add_query_arg(['candidate' => 'feedback_ratings'], $portal_url);
        $candidate_calendar_url = add_query_arg([
            'candidate' => 'calendar',
            'cmn_tab' => false,
        ], $portal_url);
        $candidate_bookings_url = add_query_arg([
            'candidate' => 'bookings',
            'cmn_tab' => false,
        ], $portal_url);
        $learning_focus_raw = sanitize_key((string) wp_unslash($_GET['cmn_learning_focus'] ?? ''));
        $learning_focus = in_array($learning_focus_raw, ['modules', 'hub'], true) ? $learning_focus_raw : 'landing';
        $learning_open_course_key = sanitize_key((string) wp_unslash($_GET['cmn_learning_course'] ?? ''));
        $learning_open_module_param = sanitize_key((string) wp_unslash($_GET['cmn_learning_module'] ?? ''));
        $candidate_finance_url = add_query_arg([
            'cmn_tab' => 'candidate_finance',
            'candidate' => false,
            'view' => false,
        ], $portal_url);
        $candidate_finance_bank_url = $candidate_finance_url . '#cmn-candidate-bank-details';
        $candidate_finance_ack_url = $candidate_finance_url . '#cmn-candidate-compliance-ack';
        $weekly_expected_has_bank_hold = $weekly_expected_is_hold && stripos((string) $weekly_expected_display, 'bank details') !== false;

        $completion_missing_map = [
            'add bank details' => ['label' => 'Add bank details', 'url' => $candidate_finance_bank_url],
            'accept self-employment notice' => ['label' => 'Accept self-employment notice', 'url' => $candidate_finance_ack_url],
            'upload cv' => ['label' => 'Upload CV', 'url' => $candidate_profile_documents_url],
            'upload dbs' => ['label' => 'Upload DBS', 'url' => $candidate_profile_documents_url],
            'upload photo id' => ['label' => 'Upload photo ID', 'url' => $candidate_profile_documents_url],
        ];
        $completion_outstanding_links = [];
        $completion_seen = [];
        foreach ((array) $completion_missing_items as $missing_item_raw) {
            $missing_item = trim((string) $missing_item_raw);
            if ($missing_item === '') {
                continue;
            }
            $missing_key = strtolower($missing_item);
            $mapped = $completion_missing_map[$missing_key] ?? null;
            if (!is_array($mapped)) {
                $fallback_label = preg_replace('/\s+/', ' ', trim($missing_item));
                $mapped = [
                    'label' => $fallback_label !== '' ? $fallback_label : 'Update details',
                    'url' => $candidate_profile_personal_url,
                ];
            }
            $label = sanitize_text_field((string) ($mapped['label'] ?? 'Update'));
            $url = esc_url_raw((string) ($mapped['url'] ?? $candidate_profile_url));
            if ($label === '' || $url === '') {
                continue;
            }
            $signature = strtolower($label) . '|' . $url;
            if (isset($completion_seen[$signature])) {
                continue;
            }
            $completion_seen[$signature] = true;
            $completion_outstanding_links[] = [
                'label' => $label,
                'url' => $url,
            ];
        }

        $learning_catalog = get_option('cmn_learning_courses_catalog', []);
        $learning_modules_catalog = $this->get_candidate_learning_modules_catalog();
        $learning_course_catalog = $this->get_candidate_learning_course_catalog();
        if (is_string($learning_catalog) && $learning_catalog !== '') {
            $decoded_learning_catalog = json_decode($learning_catalog, true);
            if (is_array($decoded_learning_catalog)) {
                $learning_catalog = $decoded_learning_catalog;
            }
        }
        if (!is_array($learning_catalog)) {
            $learning_catalog = [];
        }
        $learning_course_keys = [];
        foreach ((array) $learning_course_catalog as $course_key => $course_item) {
            $normalized_key = sanitize_key((string) $course_key);
            if ($normalized_key === '') {
                continue;
            }
            $learning_course_keys[$normalized_key] = true;
        }
        foreach ((array) $learning_catalog as $course_item) {
            if (is_array($course_item)) {
                $is_active = !isset($course_item['active']) || (string) $course_item['active'] !== '0';
                if ($is_active) {
                    $course_key = sanitize_key((string) ($course_item['key'] ?? $course_item['slug'] ?? ''));
                    if ($course_key === '') {
                        $course_key = 'catalog_' . substr(md5(wp_json_encode($course_item)), 0, 10);
                    }
                    $learning_course_keys[$course_key] = true;
                }
                continue;
            }
            if ((string) $course_item !== '') {
                $course_key = 'catalog_' . substr(md5((string) $course_item), 0, 10);
                $learning_course_keys[$course_key] = true;
            }
        }
        $learning_total_courses = count($learning_course_keys);
        $learning_completed_courses = 0;
        $learning_completed_meta = $candidate_user_id > 0 ? get_user_meta($candidate_user_id, 'cmn_learning_courses_completed', true) : [];
        if (is_string($learning_completed_meta) && $learning_completed_meta !== '') {
            $decoded_learning_completed = json_decode($learning_completed_meta, true);
            if (is_array($decoded_learning_completed)) {
                $learning_completed_meta = $decoded_learning_completed;
            } else {
                $learning_completed_meta = array_map('trim', explode(',', $learning_completed_meta));
            }
        }
        if (is_array($learning_completed_meta)) {
            foreach (array_filter(array_map('trim', array_map('strval', $learning_completed_meta))) as $completed_course_key) {
                $normalized_key = sanitize_key((string) $completed_course_key);
                if (isset($learning_course_keys[$normalized_key])) {
                    $learning_completed_courses++;
                }
            }
        }
        $learning_completed_courses = max(0, min($learning_total_courses, $learning_completed_courses));
        $learning_progress_text = $learning_total_courses > 0
            ? sprintf('%d out of %d completed', $learning_completed_courses, $learning_total_courses)
            : 'N/A';
        $learning_progress_subtext = $learning_total_courses > 0 ? 'Open Learning Centre' : 'No courses live yet';

        $tier_label = 'N/A';
        if ($is_candidate_rewards_allowed && $candidate_user_id > 0) {
            $tier_payload = $this->get_candidate_rewards_overview_payload($candidate_user_id);
            if (is_array($tier_payload) && !is_wp_error($tier_payload)) {
                $tier_label = sanitize_text_field((string) ($tier_payload['tier_label'] ?? ''));
                if ($tier_label === '') {
                    $tier_label = $this->get_candidate_rewards_tier_label((string) ($tier_payload['tier'] ?? 'standard'));
                }
            }
        }
        if ($tier_label === '') {
            $tier_label = 'Standard';
        }

        $feedback_rating_payload = $candidate_user_id > 0
            ? $this->get_candidate_average_rating_payload($candidate_user_id)
            : [
                'avg_rating' => 0.0,
                'avg_rating_raw' => 0.0,
                'feedback_count' => 0,
            ];
        $feedback_score_raw = (float) ($feedback_rating_payload['avg_rating_raw'] ?? ($feedback_rating_payload['avg_rating'] ?? 0));
        $feedback_score_raw = max(0.0, min(5.0, $feedback_score_raw));
        $feedback_count_total = max(0, (int) ($feedback_rating_payload['feedback_count'] ?? 0));
        $feedback_has_reviews = $feedback_count_total > 0;
        $feedback_star_fill_percent = $feedback_has_reviews ? (($feedback_score_raw / 5) * 100) : 100;
        $feedback_score_label = $feedback_has_reviews
            ? number_format(round($feedback_score_raw, 1), 1) . ' out of 5 stars'
            : 'NA - Feedback not yet received';
        $nav_items = [
            'dashboard' => 'Dashboard',
            'profile' => 'My Hub',
            'rewards' => 'Candidate Loyalty Programme (CLP)',
            'learning' => 'Learning Centre',
            'support' => 'Support',
            'settings' => 'Settings',
        ];
        if (!$is_candidate_rewards_allowed) {
            unset($nav_items['rewards']);
            if ($tab === 'rewards') {
                $tab = 'dashboard';
            }
        }
        $logout_url = add_query_arg([
            'view' => 'logout',
            'candidate' => false,
            'cmn_tab' => false,
        ], $this->get_portal_base_url());

        $render_static_calendar = function () use ($calendar_data, $cal_month, $start_weekday, $days_in_month) {
            ?>
            <div class="cmn-calendar-grid cmn-calendar-static">
                <div class="cmn-calendar-day">S</div>
                <div class="cmn-calendar-day">M</div>
                <div class="cmn-calendar-day">T</div>
                <div class="cmn-calendar-day">W</div>
                <div class="cmn-calendar-day">T</div>
                <div class="cmn-calendar-day">F</div>
                <div class="cmn-calendar-day">S</div>
                <?php for ($i = 1; $i < $start_weekday; $i++) : ?>
                    <div class="cmn-calendar-cell is-empty"></div>
                <?php endfor; ?>
                <?php for ($day = 1; $day <= $days_in_month; $day++) : ?>
                    <?php
                    $date = $cal_month . '-' . str_pad((string) $day, 2, '0', STR_PAD_LEFT);
                    $status = $calendar_data[$date] ?? '';
                    $classes = 'cmn-calendar-cell';
                    if ($status === 'available') {
                        $classes .= ' is-available';
                    } elseif ($status === 'unavailable') {
                        $classes .= ' is-unavailable';
                    }
                    ?>
                    <div class="<?php echo esc_attr($classes); ?>">
                        <span><?php echo esc_html($day); ?></span>
                    </div>
                <?php endfor; ?>
            </div>
            <?php
        };

        ob_start();
        ?>
        <section class="cmn-portal cmn-candidate-portal cmn-portal-light">
            <div class="cmn-portal-topbar">
                <div class="cmn-topbar-left"><?php echo $this->render_portal_branding(); ?></div>
                <div class="cmn-topbar-right">
                    <?php echo $this->render_topbar_livechat_button(); ?>
                    <div data-tour-target="bell"><?php echo $this->render_notifications_bell($user ? $user->ID : 0); ?></div>
                    <span>Welcome, <?php echo esc_html($user ? $user->display_name : 'Candidate'); ?></span>
                    <a class="cmn-topbar-logout" href="<?php echo esc_url($logout_url); ?>" data-tour-target="logout-top">Logout</a>
                </div>
            </div>
            <div class="cmn-candidate-shell">
                <aside class="cmn-candidate-nav">
                    <div class="cmn-candidate-nav-title">Candidate Dashboard</div>
                    <nav class="cmn-candidate-nav-links">
                        <?php foreach ($nav_items as $key => $label) : ?>
                            <?php
                            $link = $key === 'settings'
                                ? add_query_arg(['view' => 'candidate-settings', 'cmn_tab' => false], $this->get_portal_base_url())
                                : add_query_arg(['candidate' => $key, 'cmn_tab' => false], $portal_url);
                            $active = ($tab === $key || ($key === 'profile' && in_array($tab, ['candidate_finance', 'feedback_ratings', 'bookings', 'calendar'], true))) ? ' is-active' : '';
                            ?>
                            <a class="cmn-candidate-nav-link<?php echo esc_attr($active); ?>" href="<?php echo esc_url($link); ?>" data-candidate-nav="<?php echo esc_attr($key); ?>">
                                <span class="cmn-candidate-nav-label"><?php echo esc_html($label); ?></span>
                            </a>
                        <?php endforeach; ?>
                        <a class="cmn-candidate-nav-link" href="<?php echo esc_url($logout_url); ?>" data-tour-target="logout-nav">Logout</a>
                    </nav>
                </aside>
                <main class="cmn-candidate-main cmn-candidate-main--<?php echo esc_attr(sanitize_html_class((string) $tab)); ?>" data-candidate-tour="<?php echo $tour_dismissed ? '0' : '1'; ?>">
                    <?php
                    if ($candidate_id) {
                        $invite_query = new WP_Query([
                            'post_type' => 'cmn_booking',
                            'posts_per_page' => 1,
                            'meta_query' => [
                                [
                                    'key' => 'cmn_candidate_id',
                                    'value' => $candidate_id,
                                ],
                                [
                                    'key' => 'cmn_status',
                                    'value' => 'candidate_invited',
                                ],
                            ],
                        ]);
                        if ($invite_query->have_posts()) :
                            $invite_query->the_post();
                            $invite_deadline = (int) get_post_meta(get_the_ID(), 'cmn_candidate_deadline', true);
                            $invite_token = get_post_meta(get_the_ID(), 'cmn_candidate_token', true);
                            $invite_remaining = $invite_deadline ? max(0, $invite_deadline - time()) : 0;
                    ?>
                        <div class="cmn-invite-banner">
                            <div>
                                <strong>New booking request</strong>
                                <span>Response needed within <?php echo esc_html(ceil($invite_remaining / 60)); ?> minutes.</span>
                            </div>
                            <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
                                <input type="hidden" name="action" value="cmn_candidate_response">
                                <input type="hidden" name="booking_id" value="<?php echo esc_attr(get_the_ID()); ?>">
                                <input type="hidden" name="token" value="<?php echo esc_attr($invite_token); ?>">
                                <button class="cmn-primary" type="submit" name="response" value="accept">Accept</button>
                                <button class="cmn-ghost" type="submit" name="response" value="decline">Decline</button>
                            </form>
                        </div>
                    <?php
                        wp_reset_postdata();
                        endif;
                    }
                    ?>
                    <?php if ($is_hub_tab) : ?>
                        <?php $is_completion_verified = $completion_percent >= 100 && empty($completion_outstanding_links); ?>
                        <div class="cmn-candidate-hub-toprow">
                            <nav class="cmn-tabs cmn-candidate-profile-hub-tabs" aria-label="My Hub quick tabs">
                                <a class="cmn-tab<?php echo ($tab === 'profile' && $profile_focus_tab === 'personal') ? ' is-active' : ''; ?>" href="<?php echo esc_url($candidate_profile_personal_url); ?>">Personal Details</a>
                                <a class="cmn-tab<?php echo ($tab === 'profile' && $profile_focus_tab === 'contact_card') ? ' is-active' : ''; ?>" href="<?php echo esc_url($candidate_profile_contact_card_url); ?>">Contact Card</a>
                                <a class="cmn-tab<?php echo ($tab === 'profile' && $profile_focus_tab === 'documents') ? ' is-active' : ''; ?>" href="<?php echo esc_url($candidate_profile_documents_url); ?>">Documents</a>
                                <a class="cmn-tab<?php echo $tab === 'candidate_finance' ? ' is-active' : ''; ?>" href="<?php echo esc_url($candidate_finance_url); ?>">Finance</a>
                                <a class="cmn-tab<?php echo $tab === 'feedback_ratings' ? ' is-active' : ''; ?>" href="<?php echo esc_url($candidate_feedback_url); ?>">Feedback &amp; Ratings</a>
                                <a class="cmn-tab<?php echo $tab === 'calendar' ? ' is-active' : ''; ?>" href="<?php echo esc_url($candidate_calendar_url); ?>">Calendar</a>
                                <a class="cmn-tab<?php echo $tab === 'bookings' ? ' is-active' : ''; ?>" href="<?php echo esc_url($candidate_bookings_url); ?>">Bookings</a>
                            </nav>
                            <div class="cmn-candidate-hub-status">
                                <div class="cmn-profile-admin-status <?php echo $is_completion_verified ? 'is-verified' : 'is-pending'; ?>" data-profile-admin-status>
                                    <span class="cmn-profile-admin-status-label">Status:</span>
                                    <strong class="cmn-profile-admin-status-value" data-profile-admin-status-text data-profile-completion-text><?php echo esc_html($completion_percent); ?>% Complete</strong>
                                    <div class="cmn-profile-admin-status-tooltip" data-profile-admin-tooltip<?php echo $is_completion_verified ? ' hidden' : ''; ?>>
                                        <p>To reach 100% complete:</p>
                                        <ul data-profile-admin-missing>
                                            <?php if (!$is_completion_verified && !empty($completion_outstanding_links)) : ?>
                                                <?php foreach ($completion_outstanding_links as $item) : ?>
                                                    <li><a href="<?php echo esc_url((string) ($item['url'] ?? $candidate_profile_personal_url)); ?>"><?php echo esc_html((string) ($item['label'] ?? 'Update details')); ?></a></li>
                                                <?php endforeach; ?>
                                            <?php endif; ?>
                                        </ul>
                                    </div>
                                </div>
                            </div>
                        </div>
                    <?php endif; ?>
                    <?php if ($tab === 'profile') : ?>
                        <header class="cmn-candidate-header" data-tour-target="profile-tab">
                            <h2>My Hub</h2>
                        </header>
                        <div class="cmn-profile-global-editbar" data-profile-global-actions hidden<?php echo $profile_focus_tab !== 'personal' ? ' data-profile-doc-hidden="1"' : ''; ?>>
                            <span class="cmn-muted" data-profile-global-msg></span>
                            <div class="cmn-profile-global-editbar-actions">
                                <button class="cmn-primary" type="button" data-profile-global-save disabled>Save changes</button>
                                <button class="cmn-ghost" type="button" data-profile-global-cancel>Cancel</button>
