                            <script>
                            (function () {
                                if (window.__cmnLearningInlineFallbackInit) {
                                    return;
                                }
                                window.__cmnLearningInlineFallbackInit = true;

                                var initLearningFallback = function () {
                                    var root = document.querySelector('[data-learning-root]');
                                    if (!root) {
                                        return;
                                    }

                                    // Always hard-navigate module buttons. This keeps "Open modules" working even if main JS fails.
                                    document.addEventListener('click', function (event) {
                                        var moduleLink = event.target.closest('[data-learning-open-module]');
                                        if (!moduleLink) {
                                            return;
                                        }
                                        if (moduleLink.disabled || moduleLink.getAttribute('aria-disabled') === 'true') {
                                            event.preventDefault();
                                            return;
                                        }
                                        var moduleHref = String(
                                            moduleLink.getAttribute('href')
                                            || moduleLink.getAttribute('data-learning-open-module-url')
                                            || ''
                                        ).trim();
                                        if (!moduleHref || moduleHref === '#') {
                                            return;
                                        }
                                        event.preventDefault();
                                        window.location.assign(moduleHref);
                                    }, true);

                                    // Fallback player boot: only if the main learning initializer did not complete.
                                    window.setTimeout(function () {
                                        if (window.__cmnLearningMainReady) {
                                            return;
                                        }

                                        var player = root.querySelector('[data-learning-player]');
                                        if (!player) {
                                            return;
                                        }

                                        var parseJson = function (raw, fallback) {
                                            if (!raw) {
                                                return fallback;
                                            }
                                            try {
                                                var parsed = JSON.parse(raw);
                                                return parsed && typeof parsed === 'object' ? parsed : fallback;
                                            } catch (error) {
                                                return fallback;
                                            }
                                        };
                                        var escapeHtml = function (value) {
                                            return String(value == null ? '' : value)
                                                .replace(/&/g, '&amp;')
                                                .replace(/</g, '&lt;')
                                                .replace(/>/g, '&gt;')
                                                .replace(/"/g, '&quot;')
                                                .replace(/'/g, '&#39;');
                                        };

                                        var coursesScript = root.querySelector('[data-learning-courses-json]');
                                        var courses = parseJson(coursesScript ? String(coursesScript.textContent || '').trim() : '', {});
                                        if (!courses || typeof courses !== 'object' || !Object.keys(courses).length) {
                                            courses = parseJson(String(player.getAttribute('data-learning-courses') || ''), {});
                                        }
                                        if (!courses || typeof courses !== 'object') {
                                            courses = {};
                                        }
                                        var isValidCourseObject = function (course) {
                                            return !!course && typeof course === 'object' && !Array.isArray(course);
                                        };

                                        var panelEmpty = player.querySelector('[data-learning-player-empty]');
                                        var panelSummary = player.querySelector('[data-learning-player-summary]');
                                        var panelSlides = player.querySelector('[data-learning-player-slides]');
                                        var panelExam = player.querySelector('[data-learning-player-exam]');
                                        var panelResult = player.querySelector('[data-learning-player-result]');
                                        var summaryTitle = player.querySelector('[data-learning-summary-title]');
                                        var summaryDescription = player.querySelector('[data-learning-summary-description]');
                                        var summaryPass = player.querySelector('[data-learning-summary-pass]');
                                        var summarySlides = player.querySelector('[data-learning-summary-slides]');
                                        var summaryExamCount = player.querySelector('[data-learning-summary-exam-count]');
                                        var startCourseBtn = player.querySelector('[data-learning-start-course]');
                                        var slideCount = player.querySelector('[data-learning-slide-count]');
                                        var slideTitle = player.querySelector('[data-learning-slide-title]');
                                        var slideBody = player.querySelector('[data-learning-slide-body]');
                                        var slideImageWrap = player.querySelector('[data-learning-slide-image-wrap]');
                                        var slideImage = player.querySelector('[data-learning-slide-image]');
                                        var slideImageCaption = player.querySelector('[data-learning-slide-image-caption]');
                                        var prevBtn = player.querySelector('[data-learning-prev-slide]');
                                        var nextBtn = player.querySelector('[data-learning-next-slide]');
                                        var examPassMark = player.querySelector('[data-learning-exam-pass-mark]');
                                        var examForm = player.querySelector('[data-learning-exam-form]');
                                        var examQuestions = player.querySelector('[data-learning-exam-questions]');
                                        var backToSlides = player.querySelector('[data-learning-back-to-slides]');
                                        var backToSummary = player.querySelector('[data-learning-back-to-summary]');
                                        var retakeExam = player.querySelector('[data-learning-retake-exam]');
                                        var resultTitle = player.querySelector('[data-learning-result-title]');
                                        var resultScore = player.querySelector('[data-learning-result-score]');
                                        var resultFeedback = player.querySelector('[data-learning-result-feedback]');

                                        var state = {
                                            courseKey: '',
                                            course: null,
                                            slideIndex: 0
                                        };

                                        var showPanel = function (panel) {
                                            [panelEmpty, panelSummary, panelSlides, panelExam, panelResult].forEach(function (node) {
                                                if (!node) {
                                                    return;
                                                }
                                                node.hidden = node !== panel;
                                            });
                                        };

                                        var renderSummary = function () {
                                            if (!state.course) {
                                                showPanel(panelEmpty);
                                                return;
                                            }
                                            var slides = Array.isArray(state.course.slides) ? state.course.slides : [];
                                            var exam = Array.isArray(state.course.exam) ? state.course.exam : [];
                                            var passMark = parseInt(state.course.pass_mark || '100', 10);
                                            if (!isFinite(passMark) || passMark < 1) {
                                                passMark = 100;
                                            }
                                            if (summaryTitle) {
                                                summaryTitle.textContent = String(state.course.title || 'Course');
                                            }
                                            if (summaryDescription) {
                                                summaryDescription.textContent = String(state.course.description || '');
                                            }
                                            if (summaryPass) {
                                                summaryPass.textContent = String(passMark) + '%';
                                            }
                                            if (summarySlides) {
                                                summarySlides.textContent = String(slides.length);
                                            }
                                            if (summaryExamCount) {
                                                summaryExamCount.textContent = String(exam.length);
                                            }
                                            showPanel(panelSummary || panelEmpty);
                                        };

                                        var renderSlide = function () {
                                            if (!state.course || !Array.isArray(state.course.slides) || !state.course.slides.length) {
                                                showPanel(panelEmpty);
                                                return;
                                            }
                                            var slides = state.course.slides;
                                            if (state.slideIndex < 0) {
                                                state.slideIndex = 0;
                                            }
                                            if (state.slideIndex > slides.length - 1) {
                                                state.slideIndex = slides.length - 1;
                                            }
                                            var slide = slides[state.slideIndex] || {};
                                            if (slideCount) {
                                                slideCount.textContent = 'Slide ' + String(state.slideIndex + 1) + ' of ' + String(slides.length);
                                            }
                                            if (slideTitle) {
                                                slideTitle.textContent = String(slide.title || 'Slide');
                                            }
                                            if (slideBody) {
                                                slideBody.textContent = String(slide.body || '');
                                            }
                                            var imageUrl = String(slide.image_url || slide.imageUrl || slide.image || '');
                                            var imageAlt = String(slide.image_alt || slide.imageAlt || slide.title || 'Course slide image');
                                            var imageCaption = String(slide.image_caption || slide.imageCaption || '');
                                            if (slideImageWrap) {
                                                var hasImage = imageUrl !== '';
                                                slideImageWrap.hidden = !hasImage;
                                                if (hasImage) {
                                                    if (slideImage) {
                                                        slideImage.src = imageUrl;
                                                        slideImage.alt = imageAlt;
                                                    }
                                                    if (slideImageCaption) {
                                                        slideImageCaption.textContent = imageCaption;
                                                        slideImageCaption.hidden = imageCaption === '';
                                                    }
                                                }
                                            }
                                            if (prevBtn) {
                                                prevBtn.disabled = state.slideIndex === 0;
                                            }
                                            if (nextBtn) {
                                                nextBtn.textContent = state.slideIndex === (slides.length - 1) ? 'Go to exam' : 'Next';
                                            }
                                            showPanel(panelSlides);
                                        };

                                        var renderExam = function () {
                                            if (!state.course || !Array.isArray(state.course.exam) || !state.course.exam.length) {
                                                renderSlide();
                                                return;
                                            }
                                            var passMark = parseInt(state.course.pass_mark || '100', 10);
                                            if (!isFinite(passMark) || passMark < 1) {
                                                passMark = 100;
                                            }
                                            if (examPassMark) {
                                                examPassMark.textContent = String(passMark) + '%';
                                            }
                                            if (examQuestions) {
                                                examQuestions.innerHTML = state.course.exam.map(function (question, index) {
                                                    var options = (question && typeof question.options === 'object') ? question.options : {};
                                                    var optionRows = Object.keys(options).map(function (optionKey) {
                                                        var optionLabel = String(options[optionKey] || '');
                                                        return ''
                                                            + '<label class="cmn-learning-exam-option">'
                                                            + '<input type="radio" name="q' + String(index) + '" value="' + escapeHtml(optionKey) + '" required>'
                                                            + '<span><strong>' + escapeHtml(optionKey) + '.</strong> ' + escapeHtml(optionLabel) + '</span>'
                                                            + '</label>';
                                                    }).join('');
                                                    return ''
                                                        + '<fieldset class="cmn-learning-exam-question">'
                                                        + '<legend>Question ' + String(index + 1) + ': ' + escapeHtml(String(question.question || '')) + '</legend>'
                                                        + optionRows
                                                        + '</fieldset>';
                                                }).join('');
                                            }
                                            showPanel(panelExam);
                                        };

                                        var renderResult = function (passed, score, feedbackRows) {
                                            if (resultTitle) {
                                                resultTitle.textContent = passed ? 'Exam passed' : 'Exam not passed';
                                            }
                                            if (resultScore) {
                                                var passMark = parseInt(state.course && state.course.pass_mark ? state.course.pass_mark : '100', 10);
                                                resultScore.textContent = 'Score: ' + String(score) + '% (Pass mark: ' + String((isFinite(passMark) && passMark > 0) ? passMark : 100) + '%)';
                                            }
                                            if (resultFeedback) {
                                                resultFeedback.innerHTML = feedbackRows.join('');
                                            }
                                            showPanel(panelResult);
                                        };

                                        var openCourse = function (courseKey, startSlides) {
                                            var key = String(courseKey || '').trim();
                                            if (!key || !isValidCourseObject(courses[key])) {
                                                return false;
                                            }
                                            state.courseKey = key;
                                            state.course = courses[key];
                                            state.slideIndex = 0;
                                            if (startSlides) {
                                                renderSlide();
                                            } else {
                                                renderSummary();
                                            }
                                            return true;
                                        };

                                        var courseButtons = Array.prototype.slice.call(root.querySelectorAll('[data-learning-open-course]'));
                                        courseButtons.forEach(function (button) {
                                            button.addEventListener('click', function (event) {
                                                if (button.disabled || button.getAttribute('aria-disabled') === 'true') {
                                                    event.preventDefault();
                                                    return;
                                                }
                                                var key = String(button.getAttribute('data-learning-open-course') || '').trim();
                                                var href = String(button.getAttribute('href') || button.getAttribute('data-learning-open-course-url') || '').trim();
                                                if (key && isValidCourseObject(courses[key])) {
                                                    event.preventDefault();
                                                    openCourse(key, true);
                                                    return;
                                                }
                                                if (href && href !== '#') {
                                                    event.preventDefault();
                                                    window.location.assign(href);
                                                }
                                            });
                                        });

                                        if (startCourseBtn) {
                                            startCourseBtn.addEventListener('click', function () {
                                                if (!state.course) {
                                                    return;
                                                }
                                                state.slideIndex = 0;
                                                renderSlide();
                                            });
                                        }
                                        if (prevBtn) {
                                            prevBtn.addEventListener('click', function () {
                                                state.slideIndex -= 1;
                                                renderSlide();
                                            });
                                        }
                                        if (nextBtn) {
                                            nextBtn.addEventListener('click', function () {
                                                if (!state.course || !Array.isArray(state.course.slides)) {
                                                    return;
                                                }
                                                if (state.slideIndex >= state.course.slides.length - 1) {
                                                    renderExam();
                                                    return;
                                                }
                                                state.slideIndex += 1;
                                                renderSlide();
                                            });
                                        }
                                        if (backToSlides) {
                                            backToSlides.addEventListener('click', function () {
                                                renderSlide();
                                            });
                                        }
                                        if (backToSummary) {
                                            backToSummary.addEventListener('click', function () {
                                                renderSummary();
                                            });
                                        }
                                        if (retakeExam) {
                                            retakeExam.addEventListener('click', function () {
                                                renderExam();
                                            });
                                        }
                                        if (examForm) {
                                            examForm.addEventListener('submit', function (event) {
                                                event.preventDefault();
                                                if (!state.course || !Array.isArray(state.course.exam) || !state.course.exam.length) {
                                                    return;
                                                }
                                                var allAnswered = true;
                                                var correctCount = 0;
                                                var feedbackRows = [];
                                                state.course.exam.forEach(function (question, index) {
                                                    var selected = examForm.querySelector('input[name="q' + String(index) + '"]:checked');
                                                    var selectedValue = selected ? String(selected.value || '') : '';
                                                    if (!selectedValue) {
                                                        allAnswered = false;
                                                    }
                                                    var answer = String(question && question.answer ? question.answer : '');
                                                    var isCorrect = selectedValue !== '' && selectedValue === answer;
                                                    if (isCorrect) {
                                                        correctCount += 1;
                                                    }
                                                    feedbackRows.push(
                                                        '<div class="cmn-learning-exam-feedback-row ' + (isCorrect ? 'is-correct' : 'is-incorrect') + '">'
                                                            + '<strong>Question ' + String(index + 1) + ': ' + (isCorrect ? 'Correct' : 'Incorrect') + '</strong>'
                                                            + '<span>Your answer: ' + escapeHtml(selectedValue || 'Not answered') + ' | Correct answer: ' + escapeHtml(answer) + '</span>'
                                                            + '<p>' + escapeHtml(String(question && question.explanation ? question.explanation : '')) + '</p>'
                                                        + '</div>'
                                                    );
                                                });
                                                if (!allAnswered) {
                                                    renderResult(false, 0, ['<div class="cmn-learning-exam-feedback-row is-incorrect"><strong>Complete all questions before submitting.</strong></div>']);
                                                    return;
                                                }
                                                var score = Math.round((correctCount / state.course.exam.length) * 100);
                                                var passMark = parseInt(state.course.pass_mark || '100', 10);
                                                if (!isFinite(passMark) || passMark < 1) {
                                                    passMark = 100;
                                                }
                                                renderResult(score >= passMark, score, feedbackRows);
                                            });
                                        }

                                        var initialKey = String(player.getAttribute('data-learning-open-key') || '').trim();
                                        if (initialKey && isValidCourseObject(courses[initialKey])) {
                                            openCourse(initialKey, true);
                                        } else {
                                            showPanel(panelEmpty);
                                        }

                                        window.__cmnLearningMainReady = true;
                                    }, 220);
                                };

                                if (document.readyState === 'loading') {
                                    document.addEventListener('DOMContentLoaded', initLearningFallback);
                                } else {
                                    initLearningFallback();
                                }
                            })();
                            </script>
                        <?php endif; ?>
                    <?php elseif ($tab === 'rewards') : ?>
                        <?php echo $this->render_candidate_rewards_tab($candidate_id, $portal_url); ?>
                    <?php elseif ($tab === 'candidate_finance') : ?>
                        <?php echo $this->render_candidate_finance_tab(); ?>
                    <?php elseif ($tab === 'feedback_ratings') : ?>
                        <?php echo $this->render_candidate_feedback_ratings_tab($candidate_user_id); ?>
                    <?php elseif ($tab === 'settings') : ?>
                        <?php
                        $current_candidate_user_id = get_current_user_id();
                        $candidate_email_confirm = '';
                        if ($current_candidate_user_id) {
                            $candidate_user_obj = get_user_by('id', $current_candidate_user_id);
                            $candidate_email_confirm = $candidate_user_obj ? (string) $candidate_user_obj->user_email : '';
                        }
                        $deletion_requested = $current_candidate_user_id ? get_user_meta($current_candidate_user_id, 'cmn_deletion_requested', true) : '';
                        $deletion_requested_at = $current_candidate_user_id ? (string) get_user_meta($current_candidate_user_id, 'cmn_deletion_requested_at', true) : '';
                        ?>
                        <header class="cmn-candidate-header" data-tour-target="settings">
                            <h2>Settings</h2>
                        </header>
                        <div class="cmn-dashboard-card" data-candidate-settings>
                            <h3>Appearance</h3>
                            <p class="cmn-muted">Your portal uses the same colour scheme as admin.</p>
                            <label>Theme
                                <select name="cmn_theme" data-settings-theme>
                                    <?php foreach ($this->get_theme_scheme_choices() as $theme_key => $theme_label) : ?>
                                        <option value="<?php echo esc_attr($theme_key); ?>"><?php echo esc_html($theme_label); ?></option>
                                    <?php endforeach; ?>
                                </select>
                            </label>
                            <h3>Notification Centre</h3>
                            <p class="cmn-muted">Portal + email channels, quiet hours, and urgency rules.</p>
                            <div class="cmn-settings-grid">
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-notify="cmn_notify_portal_enabled"> Portal notifications</label>
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-notify="cmn_notify_email_enabled"> Email notifications</label>
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-notify="cmn_notify_quiet_hours_enabled"> Enable quiet hours</label>
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-notify="cmn_notify_allow_urgent_quiet"> Allow urgent alerts during quiet hours</label>
                                <label>Quiet hours start
                                    <input type="time" data-settings-notify-time="cmn_notify_quiet_start" step="300">
                                </label>
                                <label>Quiet hours end
                                    <input type="time" data-settings-notify-time="cmn_notify_quiet_end" step="300">
                                </label>
                            </div>
                            <h3>Email Notifications</h3>
                            <p class="cmn-muted">Control which email updates you receive.</p>
                            <div class="cmn-settings-grid">
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-pref="cmn_notify_email_support_updates"> Support updates</label>
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-pref="cmn_notify_email_booking_request"> Booking requests</label>
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-pref="cmn_notify_email_booking_confirmed"> Booking confirmations</label>
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-pref="cmn_notify_email_booking_cancelled"> Booking cancellations</label>
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-pref="cmn_notify_email_profile_reminders"> Profile reminders</label>
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-pref="cmn_notify_email_learning_courses"> Learning course updates</label>
                                <label class="cmn-inline-check"><input type="checkbox" data-settings-pref="cmn_notify_email_availability_nudges"> Availability nudges</label>
                            </div>
                            <div class="cmn-settings-actions">
                                <button class="cmn-primary" type="button" data-settings-save>Save settings</button>
                                <span class="cmn-muted" data-settings-message></span>
                            </div>
                            <div class="cmn-settings-danger-zone">
                                <h3>Delete Account</h3>
                                <p class="cmn-muted">This will permanently remove your access and delete your profile. This cannot be undone.</p>
                                <label>Type your email to confirm
                                    <input type="email" data-delete-confirm-email placeholder="<?php echo esc_attr($candidate_email_confirm); ?>" <?php echo $deletion_requested ? 'disabled' : ''; ?>>
                                </label>
                                <div class="cmn-settings-actions">
                                    <button class="cmn-danger" type="button" data-delete-request-btn <?php echo $deletion_requested ? 'disabled' : ''; ?>>Request account deletion</button>
                                    <span class="cmn-muted" data-delete-request-msg>
                                        <?php if ($deletion_requested) : ?>
                                            Pending admin action<?php echo $deletion_requested_at ? ' since ' . esc_html(date_i18n('M j, Y g:ia', strtotime($deletion_requested_at))) : ''; ?>.
                                        <?php endif; ?>
                                    </span>
                                </div>
                            </div>
                        </div>
                    <?php elseif ($tab === 'bookings') : ?>
                        <header class="cmn-candidate-header" data-tour-target="bookings-tab">
                            <h2>Bookings</h2>
                        </header>
                        <?php $booking_notice = isset($_GET['cmn_notice']) ? sanitize_text_field(wp_unslash($_GET['cmn_notice'])) : ''; ?>
                        <?php if ($booking_notice) : ?>
                            <div class="cmn-register-success"><?php echo esc_html($booking_notice); ?></div>
                        <?php endif; ?>
                        <div class="cmn-candidate-bookings-grid">
                        <div class="cmn-dashboard-card cmn-candidate-bookings-requests">
                            <div class="cmn-card-header">
                                <h3>Booking Requests</h3>
                                <span class="cmn-muted">15-minute response window</span>
                            </div>
                            <?php if ($candidate_requests) : ?>
                                <div class="cmn-list">
                                    <?php foreach ($candidate_requests as $request) : ?>
                                        <?php
                                        $request_id = (int) ($request['id'] ?? 0);
                                        $request_status = strtolower((string) ($request['status'] ?? 'requested'));
                                        $expires_at = $this->get_request_expires_at($request);
                                        $is_expired = $this->is_request_expired($request);
                                        if ($request_status === 'requested' && $is_expired) {
                                            $request_status = 'expired';
                                        }
                                        $requested_date = sanitize_text_field($request['requested_date'] ?? '');
                                        $requested_label = $requested_date ? date_i18n('l, F jS', strtotime($requested_date)) : 'Tomorrow';
                                        $candidate_rate = isset($request['candidate_pay_rate']) ? (float) $request['candidate_pay_rate'] : 0.0;
                                        $location_label = '';
                                        $school_id_for_request = (int) ($request['school_id'] ?? 0);
                                        if (!$school_id_for_request && !empty($request['school_email_domain'])) {
                                            $school_id_for_request = $this->get_school_post_id_by_domain((string) $request['school_email_domain']);
                                        }
                                        $school_name_for_request = 'School';
                                        if ($school_id_for_request > 0) {
                                            $resolved_school_name = (string) get_the_title($school_id_for_request);
                                            if ($resolved_school_name !== '') {
                                                $school_name_for_request = $resolved_school_name;
                                            }
                                        }
                                        if ($school_name_for_request === 'School' && !empty($request['school_email_domain'])) {
                                            $resolved_school_name = (string) $this->get_school_name_by_domain((string) $request['school_email_domain']);
                                            if ($resolved_school_name !== '') {
                                                $school_name_for_request = $resolved_school_name;
                                            }
                                        }
                                        if ($school_id_for_request) {
                                            $location_label = (string) get_post_meta($school_id_for_request, 'cmn_location', true);
                                        }
                                        $routing_level_label = sanitize_text_field((string) ($request['routing_level'] ?? 'Standard'));
                                        $routing_tier_key = sanitize_key((string) ($request['routing_tier'] ?? 'standard'));
                                        if (!in_array($routing_tier_key, ['standard', 'bronze', 'silver', 'gold', 'elite'], true)) {
                                            $routing_tier_key = 'standard';
                                        }
                                        $booking_id_for_request = $this->get_booking_id_for_request($request_id);
                                        ?>
                                        <div class="cmn-list-item cmn-request-card">
                                            <strong><?php echo esc_html($requested_label); ?></strong>
                                            <span class="cmn-request-school">
                                                <?php echo esc_html($school_name_for_request); ?>
                                                <span class="cmn-spp-routing-badge is-<?php echo esc_attr($routing_tier_key); ?>"><?php echo esc_html($routing_level_label); ?></span>
                                            </span>
                                            <span><?php echo esc_html($location_label ?: 'Location shared after acceptance'); ?></span>
                                            <span class="cmn-pill cmn-pill--status">Pay: GBP <?php echo esc_html(number_format($candidate_rate, 2)); ?></span>
                                            <span class="cmn-pill cmn-pill--<?php echo esc_attr($request_status); ?>"><?php echo esc_html(ucfirst(str_replace('_', ' ', $request_status))); ?></span>
                                            <?php if ($request_status === 'requested') : ?>
                                                <?php if ($expires_at) : ?>
                                                    <small class="cmn-request-countdown" data-request-expires="<?php echo esc_attr(gmdate('c', strtotime($expires_at))); ?>">Time remaining...</small>
                                                <?php endif; ?>
                                                <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="cmn-inline" data-cmn-accept-warning>
                                                    <?php wp_nonce_field('cmn_candidate_request_action', 'cmn_candidate_request_action_nonce'); ?>
                                                    <input type="hidden" name="action" value="cmn_candidate_request_action">
                                                    <input type="hidden" name="cmn_request_id" value="<?php echo esc_attr($request_id); ?>">
                                                    <input type="hidden" name="cmn_request_action" value="accept">
