    private function candidate_rewards_table_exists($table_name) {
        $table_name = trim((string) $table_name);
        if ($table_name === '') {
            return false;
        }
        global $wpdb;
        $found = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table_name));
        return $found === $table_name;
    }

    private function get_candidate_rewards_state_table() {
        global $wpdb;
        return $wpdb->prefix . 'cmn_candidate_rewards_state';
    }

    private function get_candidate_rewards_conduct_badge_label($status) {
        $status = $this->normalize_candidate_rewards_conduct_status((string) $status);
        $labels = [
            'clear' => 'Clear',
            'yellow' => 'Yellow',
            'red' => 'Red',
            'terminated' => 'Terminated',
        ];
        return (string) ($labels[$status] ?? 'Clear');
    }

    private function get_candidate_rewards_conduct_badge_class($status) {
        $status = $this->normalize_candidate_rewards_conduct_status((string) $status);
        if ($status === 'yellow') {
            return 'is-pending';
        }
        if ($status === 'red' || $status === 'terminated') {
            return 'is-declined';
        }
        return 'is-approved';
    }

    private function get_candidate_rewards_state_row_for_portal($candidate_user_id, $academic_year_label) {
        $candidate_user_id = (int) $candidate_user_id;
        $academic_year_label = $this->normalize_rewards_config_year_label((string) $academic_year_label, current_time('Y-m-d'));
        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        $internal_year = $this->normalize_candidate_rewards_academic_year_label($academic_year_label, current_time('Y-m-d'));

        $state = [
            'candidate_user_id' => $candidate_user_id,
            'candidate_id' => $candidate_id,
            'academic_year_label' => $academic_year_label,
            'shifts_completed' => 0,
            'current_tier' => 'standard',
            'status' => 'active',
            'conduct_status' => 'clear',
            'no_show_count' => 0,
            'last_no_show_at' => '',
            'last_tier_change_at' => '',
            'last_bonus_awarded_at' => '',
            'last_bonus_amount' => 0.00,
        ];

        $state_table = $this->get_candidate_rewards_state_table();
        if ($this->candidate_rewards_table_exists($state_table)) {
            global $wpdb;
            $state_row = $wpdb->get_row($wpdb->prepare(
                "SELECT *
                 FROM {$state_table}
                 WHERE candidate_user_id = %d
                   AND academic_year_label = %s
                 LIMIT 1",
                $candidate_user_id,
                $academic_year_label
            ), ARRAY_A);
            if (is_array($state_row) && $state_row) {
                $state['shifts_completed'] = (int) ($state_row['shifts_completed'] ?? ($state_row['academic_year_shift_total'] ?? 0));
                $state['current_tier'] = $this->normalize_candidate_rewards_tier((string) ($state_row['current_tier'] ?? ($state_row['tier'] ?? 'standard')));
                $state_status = sanitize_key((string) ($state_row['status'] ?? 'active'));
                if ($state_status === '') {
                    $state_status = 'active';
                }
                $state['status'] = $state_status;
                $state['conduct_status'] = $this->normalize_candidate_rewards_conduct_status((string) ($state_row['conduct_status'] ?? 'clear'));
                $state['no_show_count'] = max(0, (int) ($state_row['no_show_count'] ?? 0));
                $state['last_no_show_at'] = $this->normalize_invoice_datetime((string) ($state_row['last_no_show_at'] ?? ''));
                $state['last_tier_change_at'] = $this->normalize_invoice_datetime((string) ($state_row['last_tier_change_at'] ?? ''));
                $state['last_bonus_awarded_at'] = $this->normalize_invoice_datetime((string) ($state_row['last_bonus_awarded_at'] ?? ''));
                $state['last_bonus_amount'] = round((float) ($state_row['last_bonus_amount'] ?? 0), 2);
                return $state;
            }
        }

        if ($candidate_id < 1 || $internal_year === '') {
            return $state;
        }
        $legacy_row = $this->get_or_create_candidate_rewards($candidate_id, $internal_year);
        if (is_wp_error($legacy_row) || !is_array($legacy_row) || !$legacy_row) {
            return $state;
        }

        $state['shifts_completed'] = (int) ($legacy_row['academic_year_shift_total'] ?? 0);
        $state['current_tier'] = $this->normalize_candidate_rewards_tier((string) ($legacy_row['tier'] ?? 'standard'));
        $legacy_status = sanitize_key((string) ($legacy_row['status'] ?? ''));
        $legacy_conduct = $this->normalize_candidate_rewards_conduct_status((string) ($legacy_row['conduct_status'] ?? 'clear'));
        if ($legacy_status === '') {
            $legacy_status = $legacy_conduct === 'terminated' ? 'terminated' : 'active';
        }
        $state['status'] = $legacy_status;
        $state['conduct_status'] = $legacy_conduct;
        $state['no_show_count'] = max(0, (int) ($legacy_row['no_show_count'] ?? 0));
        $state['last_no_show_at'] = $this->normalize_invoice_datetime((string) ($legacy_row['last_no_show_at'] ?? ''));
        $state['last_tier_change_at'] = $this->normalize_invoice_datetime((string) ($legacy_row['last_tier_change_at'] ?? ''));
        $state['last_bonus_awarded_at'] = $this->normalize_invoice_datetime((string) ($legacy_row['last_bonus_awarded_at'] ?? ''));
        $state['last_bonus_amount'] = round((float) ($legacy_row['last_bonus_amount'] ?? 0), 2);
        return $state;
    }

    private function get_candidate_rewards_overview_payload($candidate_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return new WP_Error('cmn_candidate_rewards_invalid_user', 'Candidate account not found.');
        }
        if (!$this->is_candidate_user($candidate_user_id)) {
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }

        $year_context = function_exists('cmn_rewards_get_current_academic_year')
            ? (array) cmn_rewards_get_current_academic_year()
            : [];
        $academic_year_label = $this->normalize_rewards_config_year_label((string) ($year_context['label'] ?? ''), current_time('Y-m-d'));
        if ($academic_year_label === '') {
            $academic_year_label = $this->normalize_rewards_config_year_label('', current_time('Y-m-d'));
        }
        if ($academic_year_label === '') {
            $academic_year_label = '0000/00';
        }
        $state = $this->get_candidate_rewards_state_row_for_portal($candidate_user_id, $academic_year_label);

        $config_row = $this->get_rewards_config_row_for_academic_year($academic_year_label, current_time('Y-m-d'));
        $thresholds = $this->get_candidate_rewards_tier_threshold_map(is_array($config_row) ? $config_row : []);
        $threshold_bronze = max(0, (int) ($thresholds['bronze'] ?? 30));
        $threshold_silver = max($threshold_bronze, (int) ($thresholds['silver'] ?? 60));
        $threshold_gold = max($threshold_silver, (int) ($thresholds['gold'] ?? 90));
        $threshold_elite = max($threshold_gold, (int) ($thresholds['elite'] ?? 120));

        $tier = $this->normalize_candidate_rewards_tier((string) ($state['current_tier'] ?? 'standard'));
        $shifts_completed = (int) ($state['shifts_completed'] ?? 0);
        $status = sanitize_key((string) ($state['status'] ?? 'active'));
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($state['conduct_status'] ?? 'clear'));
        $no_show_count = max(0, (int) ($state['no_show_count'] ?? 0));
        $next_tier = 'Top tier achieved';
        $next_tier_threshold = 0;
        $shifts_to_next_tier = 0;
        foreach (['bronze', 'silver', 'gold', 'elite'] as $tier_key) {
            $tier_threshold = max(0, (int) ($thresholds[$tier_key] ?? 0));
            if ($shifts_completed < $tier_threshold) {
                $next_tier = $this->get_candidate_rewards_tier_label($tier_key);
                $next_tier_threshold = $tier_threshold;
                $shifts_to_next_tier = max(0, $tier_threshold - $shifts_completed);
                break;
            }
        }

        $awards = [];
        $last_bonus_amount = round((float) ($state['last_bonus_amount'] ?? 0), 2);
        $last_bonus_awarded_at = $this->normalize_invoice_datetime((string) ($state['last_bonus_awarded_at'] ?? ''));
        $awards_table = $this->get_candidate_bonus_awards_table();
        if ($this->candidate_rewards_table_exists($awards_table)) {
            global $wpdb;
            $award_rows = $wpdb->get_results($wpdb->prepare(
                "SELECT id, block_index, block_start_shift, block_end_shift, multiplier, average_day_pay, bonus_amount, status, awarded_at
                 FROM {$awards_table}
                 WHERE candidate_user_id = %d
                   AND academic_year_label = %s
                 ORDER BY block_index DESC, awarded_at DESC
                 LIMIT 12",
                $candidate_user_id,
                $academic_year_label
            ), ARRAY_A);
            foreach ((array) $award_rows as $award_row) {
                $awarded_at = $this->normalize_invoice_datetime((string) ($award_row['awarded_at'] ?? ''));
                $awarded_label = '—';
                if ($awarded_at !== '' && strtotime($awarded_at) !== false) {
                    $awarded_label = date_i18n('j M Y', strtotime($awarded_at));
                }
                $awards[] = [
                    'id' => (int) ($award_row['id'] ?? 0),
                    'block_index' => max(1, (int) ($award_row['block_index'] ?? 1)),
                    'block_start_shift' => max(1, (int) ($award_row['block_start_shift'] ?? 1)),
                    'block_end_shift' => max(1, (int) ($award_row['block_end_shift'] ?? 30)),
                    'multiplier' => round((float) ($award_row['multiplier'] ?? 1.00), 2),
                    'average_day_pay' => round((float) ($award_row['average_day_pay'] ?? 0), 2),
                    'bonus_amount' => round((float) ($award_row['bonus_amount'] ?? 0), 2),
                    'status' => $this->normalize_candidate_bonus_award_status((string) ($award_row['status'] ?? 'awarded')),
                    'awarded_at' => $awarded_at,
                    'awarded_at_label' => $awarded_label,
                ];
            }
            if ($awards) {
                $last_bonus_amount = round((float) ($awards[0]['bonus_amount'] ?? $last_bonus_amount), 2);
                $last_bonus_awarded_at = $this->normalize_invoice_datetime((string) ($awards[0]['awarded_at'] ?? $last_bonus_awarded_at));
            }
        }

        $effective_shifts = max(0, $shifts_completed);
        $completed_blocks = (int) floor($effective_shifts / 30);
        $next_bonus_at = ($completed_blocks + 1) * 30;
        $shifts_to_next_bonus = max(0, $next_bonus_at - $shifts_completed);
        $elite_plus_active = $shifts_completed >= $threshold_elite;
        $multiplier_map = $this->get_candidate_rewards_tier_multiplier_map(is_array($config_row) ? $config_row : []);
        $next_tier_key = 'elite';
        if ($shifts_completed < $threshold_bronze) {
            $next_tier_key = 'bronze';
        } elseif ($shifts_completed < $threshold_silver) {
            $next_tier_key = 'silver';
        } elseif ($shifts_completed < $threshold_gold) {
            $next_tier_key = 'gold';
        } elseif ($shifts_completed < $threshold_elite) {
            $next_tier_key = 'elite';
        }
        $current_tier_multiplier = round((float) ($multiplier_map[$tier] ?? $this->get_candidate_rewards_multiplier_for_tier($tier)), 2);
        $next_tier_multiplier = round((float) ($multiplier_map[$next_tier_key] ?? $this->get_candidate_rewards_multiplier_for_tier($next_tier_key)), 2);
        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        $admin_candidate_pay_rate = 0.0;
        if ($candidate_id > 0) {
            $role_labels = $this->get_candidate_role_labels($candidate_id);
            $primary_role = isset($role_labels[0]) ? (string) $role_labels[0] : '';
            $rate_entry = $this->get_candidate_role_rate_entry($candidate_id, $primary_role);
            $admin_candidate_pay_rate = round((float) ($rate_entry['candidate_pay_rate'] ?? 0), 2);
            if ($admin_candidate_pay_rate <= 0) {
                $admin_candidate_pay_rate = round((float) get_post_meta($candidate_id, 'cmn_candidate_pay_rate', true), 2);
            }
        }
        $estimated_average_day_pay = 0.0;
        if ($admin_candidate_pay_rate > 0) {
            $estimated_average_day_pay = $admin_candidate_pay_rate;
        } elseif ($awards) {
            $estimated_average_day_pay = round((float) ($awards[0]['average_day_pay'] ?? 0), 2);
        }
        if ($estimated_average_day_pay <= 0 && $last_bonus_amount > 0 && $current_tier_multiplier > 0) {
            $estimated_average_day_pay = round($last_bonus_amount / $current_tier_multiplier, 2);
        }
        if ($estimated_average_day_pay <= 0) {
            $estimated_average_day_pay = 160.0;
        }
        $estimated_next_bonus = round($estimated_average_day_pay * max(0.0, $next_tier_multiplier), 2);
        $confirmation_compliance_pct = null;
        if ($shifts_completed > 0) {
            $confirmation_compliance_pct = (int) round(max(0, min(100, (($shifts_completed - $no_show_count) / $shifts_completed) * 100)));
        }
        $rating_payload = $this->get_candidate_average_rating_payload($candidate_user_id);
        $rating_breakdown = $this->get_candidate_feedback_breakdown_for_candidate_user($candidate_user_id);

        $ticket_count = 0;
        if (function_exists('cmn_referrals_get_ticket_count')) {
            $ticket_count = (int) cmn_referrals_get_ticket_count($candidate_user_id, $academic_year_label);
        } else {
            $tickets_table = $this->get_candidate_referral_tickets_table();
            if ($this->candidate_rewards_table_exists($tickets_table)) {
                global $wpdb;
                $ticket_count = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*)
                     FROM {$tickets_table}
                     WHERE candidate_user_id = %d
                       AND academic_year_label = %s",
                    $candidate_user_id,
                    $academic_year_label
                ));
            }
        }
        $ticket_count = max(0, $ticket_count);

        $referral_code = $this->ensure_candidate_referral_code($candidate_user_id);
        if ($referral_code === '') {
            $referral_code = $this->normalize_candidate_referral_code((string) get_user_meta($candidate_user_id, 'cmn_referral_code', true));
        }

        $appeal_booking_options = [];
        $recent_conduct = [];
        $conduct_table = $this->get_candidate_conduct_events_table();
        if ($this->candidate_rewards_table_exists($conduct_table)) {
            global $wpdb;
            $no_show_rows = $wpdb->get_results($wpdb->prepare(
                "SELECT booking_id, occurred_at
                 FROM {$conduct_table}
                 WHERE candidate_user_id = %d
                   AND event_type = %s
                   AND status = %s
                 ORDER BY occurred_at DESC, id DESC
                 LIMIT 20",
                $candidate_user_id,
                'no_show',
                'active'
            ), ARRAY_A);
            $seen_booking_ids = [];
            foreach ((array) $no_show_rows as $no_show_row) {
                $booking_id = (int) ($no_show_row['booking_id'] ?? 0);
                if ($booking_id < 1 || isset($seen_booking_ids[$booking_id])) {
                    continue;
                }
                $occurred_at = $this->normalize_invoice_datetime((string) ($no_show_row['occurred_at'] ?? ''));
                $occurred_label = '—';
                if ($occurred_at !== '' && strtotime($occurred_at) !== false) {
                    $occurred_label = date_i18n('j M Y g:ia', strtotime($occurred_at));
                }
                $appeal_booking_options[] = [
                    'booking_id' => $booking_id,
                    'label' => 'Booking #' . $booking_id . ' - ' . $occurred_label,
                    'occurred_at' => $occurred_at,
                ];
                $seen_booking_ids[$booking_id] = true;
            }

            $event_labels = [
                'no_show' => 'No-show recorded',
                'appeal_opened' => 'Appeal opened',
                'appeal_approved' => 'Appeal approved',
                'appeal_rejected' => 'Appeal rejected',
                'yellow_card' => 'Yellow card',
                'red_card' => 'Red card',
                'meeting_required' => 'Meeting required',
                'termination' => 'Rewards terminated',
            ];
            $conduct_rows = $wpdb->get_results($wpdb->prepare(
                "SELECT event_type, booking_id, occurred_at, status
                 FROM {$conduct_table}
                 WHERE candidate_user_id = %d
                 ORDER BY occurred_at DESC, id DESC
                 LIMIT 10",
                $candidate_user_id
            ), ARRAY_A);
            foreach ((array) $conduct_rows as $conduct_row) {
                $event_type = sanitize_key((string) ($conduct_row['event_type'] ?? ''));
                if ($event_type === '') {
                    continue;
                }
                $occurred_at = $this->normalize_invoice_datetime((string) ($conduct_row['occurred_at'] ?? ''));
                $recent_conduct[] = [
                    'event_type' => $event_type,
                    'label' => (string) ($event_labels[$event_type] ?? ucfirst(str_replace('_', ' ', $event_type))),
                    'booking_id' => (int) ($conduct_row['booking_id'] ?? 0),
                    'status' => sanitize_key((string) ($conduct_row['status'] ?? 'active')),
                    'occurred_at' => $occurred_at,
                    'occurred_at_label' => ($occurred_at !== '' && strtotime($occurred_at) !== false)
                        ? date_i18n('j M Y g:ia', strtotime($occurred_at))
                        : '—',
                ];
            }
        }

        $last_bonus_awarded_at_label = 'Not yet awarded';
        if ($last_bonus_awarded_at !== '' && strtotime($last_bonus_awarded_at) !== false) {
            $last_bonus_awarded_at_label = date_i18n('j M Y', strtotime($last_bonus_awarded_at));
        }
        $last_no_show_at = $this->normalize_invoice_datetime((string) ($state['last_no_show_at'] ?? ''));

        return [
            'candidate_user_id' => $candidate_user_id,
            'academic_year_label' => $academic_year_label,
            'thresholds' => [
                'bronze' => $threshold_bronze,
                'silver' => $threshold_silver,
                'gold' => $threshold_gold,
                'elite' => $threshold_elite,
            ],
            'state' => [
                'tier' => $tier,
                'tier_label' => $this->get_candidate_rewards_tier_label($tier),
                'shifts_completed' => $shifts_completed,
                'status' => $status,
                'conduct_status' => $conduct_status,
                'conduct_label' => $this->get_candidate_rewards_conduct_badge_label($conduct_status),
                'conduct_chip_class' => $this->get_candidate_rewards_conduct_badge_class($conduct_status),
                'no_show_count' => $no_show_count,
                'last_no_show_at' => $last_no_show_at,
                'last_no_show_at_label' => ($last_no_show_at !== '' && strtotime($last_no_show_at) !== false)
                    ? date_i18n('j M Y g:ia', strtotime($last_no_show_at))
                    : 'No no-show recorded',
                'next_tier' => $next_tier,
                'next_tier_key' => $next_tier_key,
                'next_tier_threshold' => $next_tier_threshold,
                'shifts_to_next_tier' => $shifts_to_next_tier,
                'confirmation_compliance_pct' => $confirmation_compliance_pct,
            ],
            'multipliers' => [
                'standard' => round((float) ($multiplier_map['standard'] ?? 1.00), 2),
                'bronze' => round((float) ($multiplier_map['bronze'] ?? 1.10), 2),
                'silver' => round((float) ($multiplier_map['silver'] ?? 1.20), 2),
                'gold' => round((float) ($multiplier_map['gold'] ?? 1.30), 2),
                'elite' => round((float) ($multiplier_map['elite'] ?? 1.50), 2),
            ],
            'bonus' => [
                'last_bonus_amount' => $last_bonus_amount,
                'last_bonus_awarded_at' => $last_bonus_awarded_at,
                'last_bonus_awarded_at_label' => $last_bonus_awarded_at_label,
                'next_bonus_at' => $next_bonus_at,
                'shifts_to_next_bonus' => $shifts_to_next_bonus,
                'elite_plus_active' => $elite_plus_active,
                'next_multiplier' => $next_tier_multiplier,
                'estimated_average_day_pay' => $estimated_average_day_pay,
                'estimated_next_bonus' => $estimated_next_bonus,
                'awards' => $awards,
            ],
            'referral' => [
                'ticket_count' => $ticket_count,
                'referral_code' => $referral_code,
            ],
            'rating' => [
                'avg_rating' => round((float) ($rating_payload['avg_rating'] ?? 0), 1),
                'avg_rating_raw' => round((float) ($rating_payload['avg_rating_raw'] ?? 0), 2),
                'feedback_count' => max(0, (int) ($rating_payload['feedback_count'] ?? 0)),
                'breakdown' => is_array($rating_breakdown) ? $rating_breakdown : [],
            ],
            'conduct' => [
                'status' => $conduct_status,
                'status_label' => $this->get_candidate_rewards_conduct_badge_label($conduct_status),
                'status_chip_class' => $this->get_candidate_rewards_conduct_badge_class($conduct_status),
                'no_show_count' => $no_show_count,
                'appeal_available' => !empty($appeal_booking_options),
                'appeal_booking_options' => $appeal_booking_options,
                'recent_events' => $recent_conduct,
            ],
        ];
    }

    private function get_candidate_weekly_earnings_cache_key($candidate_user_id) {
        $candidate_user_id = max(1, (int) $candidate_user_id);
        return 'cmn_candidate_weekly_earnings_' . $candidate_user_id;
    }

    private function get_candidate_weekly_earnings_range(DateTimeImmutable $reference, $weeks_ago = 0) {
        $weeks_ago = max(0, (int) $weeks_ago);
        $base = $reference->setTime(0, 0, 0);
        if ($weeks_ago > 0) {
            $base = $base->modify('-' . $weeks_ago . ' week');
        }

        $weekday = (int) $base->format('N'); // 1 (Mon) ... 7 (Sun)
        $days_since_friday = ($weekday - 5 + 7) % 7;
        $start = $base->modify('-' . $days_since_friday . ' days');
        $end = $start->modify('+6 days'); // Thu
        $timezone = $start->getTimezone();

        return [
            'start_date' => $start->format('Y-m-d'),
            'end_date' => $end->format('Y-m-d'),
            'label' => wp_date('D j M', $start->getTimestamp(), $timezone) . ' - ' . wp_date('D j M', $end->getTimestamp(), $timezone),
        ];
    }

    private function calculate_candidate_weekly_earnings_total_for_range($candidate_user_id, $start_date, $end_date, $actor_user_id = 0) {
        $candidate_user_id = (int) $candidate_user_id;
        $actor_user_id = (int) $actor_user_id;
        $start_date = $this->normalize_invoice_date((string) $start_date);
        $end_date = $this->normalize_invoice_date((string) $end_date);

        $result = [
            'total' => 0.00,
            'credited_days' => 0,
            'approved_days' => 0,
            'missing_pay_days' => 0,
        ];

        if ($candidate_user_id < 1 || $start_date === '' || $end_date === '') {
            return $result;
        }

        $table = $this->get_candidate_pay_approvals_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return $result;
        }

        global $wpdb;
        $has_training_column = self::table_has_column($table, 'is_training');
        $training_sql = $has_training_column ? "AND COALESCE(is_training, 0) = 0" : '';
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT booking_id, booking_day_date
             FROM {$table}
             WHERE candidate_user_id = %d
               AND approval_status = %s
               AND booking_day_date >= %s
               AND booking_day_date <= %s
               {$training_sql}
             ORDER BY booking_day_date ASC, id ASC",
            $candidate_user_id,
            'approved',
            $start_date,
            $end_date
        ), ARRAY_A);
        if (!is_array($rows) || !$rows) {
            return $result;
        }

        $booking_ids = array_values(array_unique(array_filter(array_map('intval', array_column($rows, 'booking_id')))));
        $rate_rows_map = $this->get_booking_rate_rows_map($booking_ids);
        $booking_meta_rate_cache = [];
        $total = 0.00;
        $approved_days = 0;
        $missing_pay_days = 0;

        foreach ($rows as $row) {
            $booking_id = (int) ($row['booking_id'] ?? 0);
            $booking_day_date = $this->normalize_invoice_date((string) ($row['booking_day_date'] ?? ''));
            $day_pay = $this->resolve_payroll_day_rate_for_booking($booking_id, $rate_rows_map, $booking_meta_rate_cache);
            $booking_meta_rate_cache[$booking_id] = $day_pay;
            if ((float) $day_pay <= 0) {
                $missing_pay_days++;
                if (function_exists('cmn_audit_log_event')) {
                    cmn_audit_log_event([
                        'module' => 'finance',
                        'entity_type' => 'candidate',
                        'entity_id' => $candidate_user_id,
                        'event_type' => 'missing_pay_data',
                        'event_ref' => $booking_id . ':' . $booking_day_date,
                        'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                        'metadata' => [
                            'booking_id' => $booking_id,
                            'booking_day_date' => $booking_day_date,
                            'range_start' => $start_date,
                            'range_end' => $end_date,
                            'source' => 'candidate_weekly_earnings_widget_pay_approvals',
                            'error_code' => 'missing_day_rate',
                        ],
                    ]);
                }
                continue;
            }

            $total += (float) $day_pay;
            $approved_days++;
        }

        $result['total'] = round($total, 2);
        $result['credited_days'] = $approved_days;
        $result['approved_days'] = $approved_days;
        $result['missing_pay_days'] = $missing_pay_days;
        return $result;
    }

    private function get_candidate_finance_join_date($candidate_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return '';
        }
        $join_date = '';
        $user = get_user_by('id', $candidate_user_id);
        if ($user && !empty($user->user_registered)) {
            $join_date = $this->normalize_invoice_date((string) $user->user_registered);
        }
        if ($join_date !== '') {
            return $join_date;
        }
        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        if ($candidate_id > 0) {
            $candidate_post = get_post($candidate_id);
            if ($candidate_post && !empty($candidate_post->post_date)) {
                $join_date = $this->normalize_invoice_date((string) $candidate_post->post_date);
            }
        }
        return $join_date;
    }

    private function get_candidate_year_to_date_monthly_earnings($candidate_user_id, $academic_year = '') {
        $candidate_user_id = (int) $candidate_user_id;
        $response = [
            'academic_year_label' => '',
            'months' => [],
            'total_confirmed' => 0.00,
        ];
        if ($candidate_user_id < 1) {
            return $response;
        }

        $bounds = $this->get_candidate_rewards_academic_year_bounds($academic_year, current_time('Y-m-d'));
        $start_date = $this->normalize_invoice_date((string) ($bounds['start_date'] ?? ''));
        $end_date = $this->normalize_invoice_date((string) ($bounds['end_date'] ?? ''));
        if ($start_date === '' || $end_date === '' || strtotime($start_date) === false || strtotime($end_date) === false) {
            return $response;
        }

        $timezone = wp_timezone();
        try {
            $cursor = new DateTimeImmutable($start_date, $timezone);
            $end_dt = new DateTimeImmutable($end_date, $timezone);
        } catch (Exception $e) {
            return $response;
        }

        $join_date = $this->get_candidate_finance_join_date($candidate_user_id);
        $actor_user_id = (int) get_current_user_id();
        $months = [];
        $total_confirmed = 0.00;

        while ($cursor <= $end_dt) {
            $month_start = $cursor->format('Y-m-01');
            $month_end = $cursor->format('Y-m-t');
            if ($month_start < $start_date) {
                $month_start = $start_date;
            }
            if ($month_end > $end_date) {
                $month_end = $end_date;
            }

            $is_na = ($join_date !== '' && $month_end < $join_date);
            $month_total = 0.00;
            if (!$is_na) {
                $calc_start = $month_start;
                if ($join_date !== '' && $join_date > $month_start && $join_date <= $month_end) {
                    $calc_start = $join_date;
                }
                $month_totals = $this->calculate_candidate_weekly_earnings_total_for_range(
                    $candidate_user_id,
                    $calc_start,
                    $month_end,
                    $actor_user_id
                );
                $month_total = round((float) ($month_totals['total'] ?? 0), 2);
                $total_confirmed += $month_total;
            }

            $months[] = [
                'month_label' => wp_date('M', $cursor->getTimestamp(), $timezone),
                'is_na' => $is_na ? 1 : 0,
                'amount' => $is_na ? null : $month_total,
            ];
            $cursor = $cursor->modify('first day of next month');
        }

        $response['academic_year_label'] = sanitize_text_field((string) ($bounds['label'] ?? ''));
        $response['months'] = $months;
        $response['total_confirmed'] = round($total_confirmed, 2);
        return $response;
    }

    private function get_candidate_weekly_earnings_payload($candidate_user_id, $use_cache = true) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return new WP_Error('cmn_candidate_weekly_earnings_invalid_user', 'Candidate account not found.');
        }
        if (!$this->is_candidate_user($candidate_user_id)) {
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }

        $cache_key = $this->get_candidate_weekly_earnings_cache_key($candidate_user_id);
        if ($use_cache) {
            $cached = get_transient($cache_key);
            if (is_array($cached) && isset($cached['week_range'], $cached['total'], $cached['last_week_total'])) {
                return $cached;
            }
        }

        $timezone = wp_timezone();
        try {
            $now = new DateTimeImmutable('now', $timezone);
        } catch (Exception $e) {
            $now = new DateTimeImmutable('@' . current_time('timestamp'));
            $now = $now->setTimezone($timezone);
        }

        $current_range = $this->get_candidate_weekly_earnings_range($now, 0);
        $last_range = $this->get_candidate_weekly_earnings_range($now, 1);
        $actor_user_id = (int) get_current_user_id();

        $current_totals = $this->calculate_candidate_weekly_earnings_total_for_range(
            $candidate_user_id,
            (string) ($current_range['start_date'] ?? ''),
            (string) ($current_range['end_date'] ?? ''),
            $actor_user_id
        );
        $last_totals = $this->calculate_candidate_weekly_earnings_total_for_range(
            $candidate_user_id,
            (string) ($last_range['start_date'] ?? ''),
            (string) ($last_range['end_date'] ?? ''),
            $actor_user_id
        );

        $period_start = $this->normalize_invoice_date((string) ($current_range['start_date'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($current_range['end_date'] ?? ''));
        $period_id = ($period_start !== '' && $period_end !== '')
            ? $this->get_payroll_period_id($period_start, $period_end)
            : '';
        $period_locked = $period_id !== '' ? $this->is_payroll_period_locked($period_id) : false;
        $bank_complete = $this->is_candidate_bank_complete_for_payroll($candidate_user_id);
        $self_employed_ack_complete = $this->is_candidate_self_employed_ack_complete_for_payroll($candidate_user_id);
        $pay_date = '';
        if ($period_start !== '') {
            $period_ref = function_exists('cmn_payroll_get_period_for_date')
                ? (array) cmn_payroll_get_period_for_date($period_start)
                : (array) $this->get_payroll_period_for_date($period_start);
            $pay_date = $this->normalize_invoice_date((string) ($period_ref['pay_date'] ?? ''));
        }

        $expected_payout = round((float) ($current_totals['total'] ?? 0), 2);
        $expected_payout_display = '';
        $payout_state_label = 'Estimate';
        $payout_state_chip_class = 'is-pending';
        $payout_state_note = 'Estimate (pending lock).';
        $expected_payout_hold = false;
        if (!$bank_complete) {
            $expected_payout_hold = true;
            $expected_payout_display = 'On hold until bank details added';
            $payout_state_label = 'On hold';
            $payout_state_chip_class = 'is-declined';
            $payout_state_note = 'On hold until bank details added.';
            if (!$period_locked) {
                $payout_state_note .= ' Estimate (pending lock).';
            }
        } elseif (!$self_employed_ack_complete) {
            $expected_payout_hold = true;
            $expected_payout_display = 'On hold until self-employed acknowledgement is confirmed';
            $payout_state_label = 'On hold';
            $payout_state_chip_class = 'is-warning';
            $payout_state_note = 'On hold until self-employed acknowledgement is confirmed.';
            if (!$period_locked) {
                $payout_state_note .= ' Estimate (pending lock).';
            }
        } elseif ($period_locked) {
            $payout_state_label = 'Locked';
            $payout_state_chip_class = 'is-approved';
            $payout_state_note = 'Payroll period locked. Expected payout shown from approved booking-days.';
        }

        $payload = [
            'week_range' => $current_range,
            'last_week_range' => $last_range,
            'total' => round((float) ($current_totals['total'] ?? 0), 2),
            'expected_payout' => $expected_payout,
            'expected_payout_is_hold' => $expected_payout_hold ? 1 : 0,
            'expected_payout_display' => $expected_payout_display,
            'last_week_total' => round((float) ($last_totals['total'] ?? 0), 2),
            'credited_days' => (int) ($current_totals['credited_days'] ?? 0),
            'approved_days' => (int) ($current_totals['approved_days'] ?? 0),
            'last_week_credited_days' => (int) ($last_totals['credited_days'] ?? 0),
            'last_week_approved_days' => (int) ($last_totals['approved_days'] ?? 0),
            'missing_pay_days' => (int) ($current_totals['missing_pay_days'] ?? 0),
            'last_week_missing_pay_days' => (int) ($last_totals['missing_pay_days'] ?? 0),
            'period_id' => $period_id,
            'period_locked' => $period_locked ? 1 : 0,
            'pay_date' => $pay_date,
            'bank_status' => $bank_complete ? 'complete' : 'missing',
            'compliance_ack_status' => $self_employed_ack_complete ? 'accepted' : 'missing',
            'payout_state_label' => $payout_state_label,
            'payout_state_chip_class' => $payout_state_chip_class,
            'payout_state_note' => $payout_state_note,
            'currency' => 'GBP',
            'generated_at' => current_time('mysql'),
        ];

        set_transient($cache_key, $payload, 5 * MINUTE_IN_SECONDS);
        return $payload;
    }

    public function handle_candidate_weekly_earnings_overview() {
        if (!function_exists('cmn_require_login') || !function_exists('cmn_require_nonce') || !function_exists('cmn_require_ability')) {
            wp_send_json_error(['message' => 'Weekly earnings service unavailable.'], 500);
        }

        $login_check = cmn_require_login();
        if (is_wp_error($login_check)) {
            if (function_exists('cmn_json_error')) {
                cmn_json_error($login_check);
                return;
            }
            wp_send_json_error(['message' => $login_check->get_error_message()], 401);
        }

        $nonce_check = cmn_require_nonce('cmn_candidate_weekly_earnings_view', 'nonce');
        if (is_wp_error($nonce_check)) {
            if (function_exists('cmn_json_error')) {
                cmn_json_error($nonce_check);
                return;
            }
            wp_send_json_error(['message' => $nonce_check->get_error_message()], 403);
        }

        $candidate_user_id = (int) get_current_user_id();
        if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
            if (function_exists('cmn_json_error')) {
                cmn_json_error(new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]));
                return;
            }
            wp_send_json_error(['message' => 'Not authorised.'], 403);
        }

        $ability_check = cmn_require_ability('finance.view_self', ['candidate_user_id' => $candidate_user_id]);
        if (is_wp_error($ability_check)) {
            if (function_exists('cmn_json_error')) {
                cmn_json_error($ability_check);
                return;
            }
            wp_send_json_error(['message' => $ability_check->get_error_message()], 403);
        }

        $payload = $this->get_candidate_weekly_earnings_payload($candidate_user_id, true);
        if (is_wp_error($payload)) {
            if (function_exists('cmn_json_error')) {
                cmn_json_error($payload);
                return;
            }
            wp_send_json_error(['message' => $payload->get_error_message()], 400);
        }

        wp_send_json_success([
            'ok' => true,
            'data' => $payload,
        ]);
    }

