    public function handle_training_mode_update() {
        $redirect = admin_url('admin.php?page=cmn-training-mode');
        $build_redirect = static function ($status, $message) use ($redirect) {
            return add_query_arg([
                'cmn_training_notice' => sanitize_key((string) $status),
                'cmn_training_msg' => rawurlencode((string) $message),
            ], $redirect);
        };

        if (!is_user_logged_in() || !$this->can_manage_training_mode()) {
            wp_safe_redirect($build_redirect('error', 'Access denied.'));
            exit;
        }
        $actor_user_id = (int) get_current_user_id();

        $nonce = isset($_POST['cmn_training_mode_nonce']) ? sanitize_text_field((string) wp_unslash($_POST['cmn_training_mode_nonce'])) : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_training_mode_update')) {
            wp_safe_redirect($build_redirect('error', 'Invalid request.'));
            exit;
        }

        $action = sanitize_key((string) wp_unslash($_POST['cmn_training_action'] ?? ''));
        if ($action === '') {
            wp_safe_redirect($build_redirect('error', 'No training action specified.'));
            exit;
        }

        $before = $this->get_training_mode_state();
        $updates = [];
        $event_type = '';

        if ($action === 'enable') {
            if ($this->is_training_mode_kill_switch_enabled()) {
                wp_safe_redirect($build_redirect('warning', 'Training mode is blocked by global kill switch.'));
                exit;
            }
            $updates['is_enabled'] = 1;
            $event_type = 'training_enabled';
        } elseif ($action === 'disable') {
            $updates['is_enabled'] = 0;
            $event_type = 'training_disabled';
        } elseif ($action === 'set_virtual_now') {
            $raw_value = sanitize_text_field((string) wp_unslash($_POST['cmn_virtual_now'] ?? ''));
            if ($raw_value === '') {
                wp_safe_redirect($build_redirect('error', 'Virtual now is required.'));
                exit;
            }
            try {
                $virtual_now = new DateTimeImmutable($raw_value, wp_timezone());
            } catch (Throwable $e) {
                wp_safe_redirect($build_redirect('error', 'Invalid virtual now value.'));
                exit;
            }
            $updates['virtual_now'] = $virtual_now->format('Y-m-d H:i:s');
            $event_type = 'training_virtual_now_set';
        } elseif ($action === 'clear_virtual_now') {
            $updates['virtual_now'] = null;
            $event_type = 'training_virtual_now_cleared';
        } elseif ($action === 'set_scope') {
            $scope = $this->normalize_training_mode_scope((string) wp_unslash($_POST['cmn_training_scope'] ?? 'admin_only'));
            if ($scope === 'all_users' && !$this->is_admin_user($actor_user_id)) {
                wp_safe_redirect($build_redirect('error', 'Only admin users can set scope to all users.'));
                exit;
            }
            $updates['scope'] = $scope;
            $event_type = 'training_scope_changed';
        } else {
            wp_safe_redirect($build_redirect('error', 'Unsupported training action.'));
            exit;
        }

        $after = $this->update_training_mode_state($updates, $actor_user_id);
        if (is_wp_error($after)) {
            wp_safe_redirect($build_redirect('error', $after->get_error_message()));
            exit;
        }

        if ($event_type !== '' && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'training',
                'entity_type' => 'system',
                'entity_id' => 0,
                'event_type' => $event_type,
                'actor_user_id' => $actor_user_id,
                'metadata' => [
                    'previous' => [
                        'is_enabled' => !empty($before['is_enabled']) ? 1 : 0,
                        'virtual_now' => (string) ($before['virtual_now'] ?? ''),
                        'scope' => (string) ($before['scope'] ?? 'admin_only'),
                    ],
                    'new' => [
                        'is_enabled' => !empty($after['is_enabled']) ? 1 : 0,
                        'virtual_now' => (string) ($after['virtual_now'] ?? ''),
                        'scope' => (string) ($after['scope'] ?? 'admin_only'),
                    ],
                    'actor_user_id' => $actor_user_id,
                ],
            ]);
        }

        wp_safe_redirect($build_redirect('success', 'Training mode updated.'));
        exit;
    }

    public function handle_training_console_action() {
        $redirect = $this->get_training_console_redirect_url();
        $build_redirect = static function ($status, $message, $extra = []) use ($redirect) {
            $args = array_merge([
                'cmn_training_notice' => sanitize_key((string) $status),
                'cmn_training_msg' => rawurlencode((string) $message),
            ], is_array($extra) ? $extra : []);
            return add_query_arg($args, $redirect);
        };

        if (!is_user_logged_in() || !$this->can_manage_training_mode()) {
            wp_safe_redirect($build_redirect('error', 'Access denied.'));
            exit;
        }
        if (!$this->is_training_simulator_enabled()) {
            wp_safe_redirect($build_redirect('error', 'Training simulator is disabled.'));
            exit;
        }

        $actor_user_id = (int) get_current_user_id();
        $nonce = isset($_POST['cmn_training_console_nonce']) ? sanitize_text_field((string) wp_unslash($_POST['cmn_training_console_nonce'])) : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_training_console_action')) {
            wp_safe_redirect($build_redirect('error', 'Invalid request.'));
            exit;
        }

        if ($this->is_training_mode_kill_switch_enabled()) {
            wp_safe_redirect($build_redirect('warning', 'Global kill switch is enabled. Training actions are disabled.'));
            exit;
        }

        $state = $this->get_training_mode_state();
        if (empty($state['is_enabled'])) {
            wp_safe_redirect($build_redirect('warning', 'Enable Training Mode first.'));
            exit;
        }
        $scope = $this->normalize_training_mode_scope((string) ($state['scope'] ?? 'admin_only'));
        $is_training_context = ($scope === 'admin_only');
        $action_name = sanitize_key((string) wp_unslash($_POST['cmn_training_console_action'] ?? ''));
        if ($action_name === '') {
            wp_safe_redirect($build_redirect('error', 'No action selected.'));
            exit;
        }

        $current_period = function_exists('cmn_payroll_get_current_period')
            ? (array) cmn_payroll_get_current_period()
            : (array) $this->get_payroll_current_period();
        $period_start = $this->normalize_invoice_date((string) ($current_period['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($current_period['period_end'] ?? ''));
        $period_id = sanitize_text_field((string) ($current_period['period_id'] ?? ''));
        if ($period_id === '' && $period_start !== '' && $period_end !== '') {
            $period_id = $this->get_payroll_period_id($period_start, $period_end);
        }

        $message = 'Training action completed.';
        $status = 'success';
        $action_metadata = [
            'action_name' => $action_name,
            'scope' => $scope,
            'is_training' => $is_training_context ? 1 : 0,
            'period_id' => $period_id,
        ];

        if ($action_name === 'simulate_payroll_auto_lock') {
            $result = $this->run_payroll_period_auto_lock_job('training_console', $actor_user_id, [
                'is_training' => $is_training_context,
            ]);
            if (!is_array($result) || (($result['status'] ?? 'failed') === 'failed')) {
                $status = 'error';
                $message = 'Auto-lock simulation failed.';
            } else {
                $message = 'Auto-lock simulation finished.';
            }
            $action_metadata['result'] = is_array($result) ? $result : [];
        } elseif ($action_name === 'generate_payout_run_current') {
            if ($period_id === '') {
                wp_safe_redirect($build_redirect('error', 'Unable to resolve current payroll period.'));
                exit;
            }
            $result = $this->generate_payout_run_for_period($period_id, [
                'actor_user_id' => $actor_user_id,
                'generated_by' => 'staff',
                'trigger' => 'training_console',
                'is_training' => $is_training_context,
            ]);
            if (is_wp_error($result)) {
                $status = 'error';
                $message = $result->get_error_message();
            } else {
                $message = !empty($result['created']) ? 'Training payout run generated.' : 'Training payout run already exists.';
            }
            $action_metadata['result'] = is_wp_error($result) ? ['error' => $result->get_error_message()] : $result;
        } elseif ($action_name === 'send_school_confirmation_reminders') {
            if ($is_training_context) {
                wp_safe_redirect($build_redirect('warning', 'Switch scope to All users before running school reminder dispatch.'));
                exit;
            }
            $result = $this->run_school_partner_confirmation_reminder_job('training_console', $actor_user_id);
            if (!is_array($result) || empty($result['ok'])) {
                $status = 'error';
                $message = 'School reminder dispatch failed.';
            } else {
                $message = 'School reminder dispatch completed.';
            }
            $action_metadata['result'] = is_array($result) ? $result : [];
        } elseif ($action_name === 'generate_remittance_current') {
            if ($period_id === '') {
                wp_safe_redirect($build_redirect('error', 'Unable to resolve current payroll period.'));
                exit;
            }
            $run_row = $this->get_payroll_payout_run_by_period_id($period_id, $is_training_context ? 1 : 0);
            if (empty($run_row['id'])) {
                $run_result = $this->generate_payout_run_for_period($period_id, [
                    'actor_user_id' => $actor_user_id,
                    'generated_by' => 'staff',
                    'trigger' => 'training_console',
                    'is_training' => $is_training_context,
                ]);
                if (is_wp_error($run_result)) {
                    wp_safe_redirect($build_redirect('error', $run_result->get_error_message()));
                    exit;
                }
                $run_row = is_array($run_result['payout_run'] ?? null) ? (array) $run_result['payout_run'] : [];
            }

            $items = $this->get_payroll_payout_run_items((int) ($run_row['id'] ?? 0), $is_training_context ? 1 : 0);
            $generated = 0;
            $errors = 0;
            foreach ($items as $item) {
                $candidate_user_id = max(0, (int) ($item['candidate_user_id'] ?? 0));
                if ($candidate_user_id < 1) {
                    continue;
                }
                $doc_result = $this->generate_candidate_remittance_pdf($candidate_user_id, $period_id, [
                    'force_regenerate' => true,
                    'actor_user_id' => $actor_user_id,
                    'trigger' => 'training_console',
                    'is_training' => $is_training_context,
                ]);
                if (is_wp_error($doc_result)) {
                    $errors++;
                    continue;
                }
                $generated++;
            }
            if ($errors > 0) {
                $status = 'warning';
            }
            $message = 'Remittance generation run completed. Generated: ' . $generated . ', errors: ' . $errors . '.';
            $action_metadata['result'] = [
                'generated' => $generated,
                'errors' => $errors,
                'run_id' => (int) ($run_row['id'] ?? 0),
            ];
        } else {
            wp_safe_redirect($build_redirect('error', 'Unsupported training action.'));
            exit;
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'training',
                'entity_type' => 'system',
                'entity_id' => 0,
                'event_type' => 'training_action_run',
                'actor_user_id' => $actor_user_id,
                'metadata' => $action_metadata,
            ]);
        }

        wp_safe_redirect($build_redirect($status, $message));
        exit;
    }

