    private function format_candidate_sort_code($sort_code) {
        $digits = preg_replace('/\D+/', '', (string) $sort_code);
        if (!is_string($digits) || strlen($digits) !== 6) {
            return '';
        }
        return substr($digits, 0, 2) . '-' . substr($digits, 2, 2) . '-' . substr($digits, 4, 2);
    }

    private function mask_candidate_account_number($account_number) {
        $digits = preg_replace('/\D+/', '', (string) $account_number);
        if (!is_string($digits) || strlen($digits) !== 8) {
            return '';
        }
        return '****' . substr($digits, -4);
    }

    private function get_candidate_ack_text_hash($ack_text) {
        return hash('sha256', (string) $ack_text);
    }

    private function get_candidate_self_employed_ack_hash() {
        return $this->get_candidate_ack_text_hash(self::CANDIDATE_COMPLIANCE_ACK_TEXT_SELF_EMPLOYED_TAX);
    }

    private function get_candidate_compliance_ack_record($candidate_user_id, $ack_type, $ack_version) {
        $candidate_user_id = (int) $candidate_user_id;
        $ack_type = sanitize_key((string) $ack_type);
        $ack_version = sanitize_text_field((string) $ack_version);
        if ($candidate_user_id < 1 || $ack_type === '' || $ack_version === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_compliance_ack_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }

        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_user_id = %d
               AND ack_type = %s
               AND ack_version = %s
             ORDER BY id DESC
             LIMIT 1",
            $candidate_user_id,
            $ack_type,
            $ack_version
        ), ARRAY_A);
        if (!is_array($row)) {
            return [];
        }

        $ack_text_hash = strtolower(preg_replace('/[^a-f0-9]/i', '', (string) ($row['ack_text_hash'] ?? '')));
        if (!is_string($ack_text_hash)) {
            $ack_text_hash = '';
        }
        $ack_text_hash = substr($ack_text_hash, 0, 64);

        return [
            'id' => (int) ($row['id'] ?? 0),
            'candidate_user_id' => (int) ($row['candidate_user_id'] ?? 0),
            'ack_type' => sanitize_key((string) ($row['ack_type'] ?? '')),
            'ack_version' => sanitize_text_field((string) ($row['ack_version'] ?? '')),
            'ack_text_hash' => $ack_text_hash,
            'accepted_at' => $this->normalize_invoice_datetime((string) ($row['accepted_at'] ?? '')),
            'accepted_ip' => substr(sanitize_text_field((string) ($row['accepted_ip'] ?? '')), 0, 45),
            'accepted_user_agent' => substr(sanitize_text_field((string) ($row['accepted_user_agent'] ?? '')), 0, 255),
            'created_at' => $this->normalize_invoice_datetime((string) ($row['created_at'] ?? '')),
        ];
    }

    private function get_candidate_self_employed_ack_record($candidate_user_id) {
        return $this->get_candidate_compliance_ack_record(
            $candidate_user_id,
            self::CANDIDATE_COMPLIANCE_ACK_TYPE_SELF_EMPLOYED_TAX,
            self::CANDIDATE_COMPLIANCE_ACK_VERSION_SELF_EMPLOYED_TAX
        );
    }

    private function has_candidate_self_employed_ack($candidate_user_id) {
        $record = $this->get_candidate_self_employed_ack_record($candidate_user_id);
        if (empty($record['id'])) {
            return false;
        }

        $stored_hash = strtolower((string) ($record['ack_text_hash'] ?? ''));
        $expected_hash = strtolower($this->get_candidate_self_employed_ack_hash());
        if (strlen($stored_hash) !== 64 || strlen($expected_hash) !== 64) {
            return false;
        }

        return hash_equals($expected_hash, $stored_hash);
    }

    private function is_candidate_self_employed_ack_complete_for_payroll($candidate_user_id) {
        return $this->has_candidate_self_employed_ack($candidate_user_id);
    }

    private function get_candidate_bank_details_record($candidate_user_id) {
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1) {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_bank_details_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }

        $active_row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_user_id = %d AND is_active = 1
             ORDER BY id DESC
             LIMIT 1",
            $candidate_user_id
        ), ARRAY_A);
        $row = is_array($active_row) ? $active_row : $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE candidate_user_id = %d
             ORDER BY id DESC
             LIMIT 1",
            $candidate_user_id
        ), ARRAY_A);
        if (!is_array($row)) {
            return [];
        }

        $sort_code_masked = sanitize_text_field((string) ($row['sort_code_masked'] ?? ''));
        $account_number_last4 = preg_replace('/\D+/', '', (string) ($row['account_number_last4'] ?? ''));
        if (!is_string($account_number_last4)) {
            $account_number_last4 = '';
        }

        return [
            'id' => (int) ($row['id'] ?? 0),
            'candidate_user_id' => (int) ($row['candidate_user_id'] ?? 0),
            'account_name' => sanitize_text_field((string) ($row['account_name'] ?? '')),
            'sort_code_masked' => $sort_code_masked,
            'account_number_last4' => $account_number_last4,
            'enc_version' => max(1, (int) ($row['enc_version'] ?? 1)),
            'is_active' => (int) ($row['is_active'] ?? 0),
            'created_at' => sanitize_text_field((string) ($row['created_at'] ?? '')),
            'updated_at' => sanitize_text_field((string) ($row['updated_at'] ?? '')),
        ];
    }

    /*
     * Prompt 24 acceptance tests:
     * 1) Candidate can add bank details.
     * 2) Invalid formats are rejected.
     * 3) Masked values are displayed on finance page.
     * 4) Non-candidate roles cannot access this endpoint.
     * 5) Audit event bank_details_updated is logged.
     *
     * Prompt 25 acceptance tests:
     * 1) Saving bank details uses configured CMN_BANK_ENC_KEY when present, otherwise secure fallback key.
     * 2) sort_code/account_number are encrypted at rest.
     * 3) Audit metadata never includes raw bank fields.
     */
    public function handle_save_candidate_bank_details() {
        $default_redirect = $this->get_candidate_finance_focus_url('bank-details');
        $redirect_raw = isset($_POST['cmn_redirect']) ? (string) wp_unslash($_POST['cmn_redirect']) : '';
        $redirect = $redirect_raw !== ''
            ? wp_validate_redirect(esc_url_raw($redirect_raw), $default_redirect)
            : $default_redirect;

        $build_redirect = static function ($target, $status, $message) {
            $target = (string) $target;
            $fragment = '';
            $hash_pos = strpos($target, '#');
            if ($hash_pos !== false) {
                $fragment = substr($target, $hash_pos + 1);
                $target = substr($target, 0, $hash_pos);
            }
            $url = add_query_arg([
                'cmn_finance_bank_status' => sanitize_key((string) $status),
                'cmn_finance_bank_msg' => rawurlencode((string) $message),
            ], $target);
            if ($fragment !== '') {
                $url .= '#' . ltrim($fragment, '#');
            }
            return $url;
        };

        if (!is_user_logged_in()) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        $candidate_user_id = (int) get_current_user_id();
        if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('finance.view_self', ['candidate_user_id' => $candidate_user_id]);
            if (is_wp_error($ability_check)) {
                wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
                exit;
            }
        }

        $nonce = isset($_POST['cmn_candidate_bank_details_nonce'])
            ? sanitize_text_field((string) wp_unslash($_POST['cmn_candidate_bank_details_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_save_candidate_bank_details')) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Invalid request. Please refresh and try again.'));
            exit;
        }

        $account_name = sanitize_text_field(trim((string) wp_unslash($_POST['cmn_bank_account_name'] ?? '')));
        $sort_code_raw = trim((string) wp_unslash($_POST['cmn_bank_sort_code'] ?? ''));
        $account_number_raw = trim((string) wp_unslash($_POST['cmn_bank_account_number'] ?? ''));
        $name_length = function_exists('mb_strlen') ? mb_strlen($account_name) : strlen($account_name);
        if ($account_name === '' || $name_length < 2 || $name_length > 150) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Account holder name must be between 2 and 150 characters.'));
            exit;
        }

        $sort_code_digits = preg_replace('/\D+/', '', $sort_code_raw);
        if (!is_string($sort_code_digits) || strlen($sort_code_digits) !== 6) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Sort code must be exactly 6 digits (e.g. 12-34-56).'));
            exit;
        }

        $account_number_digits = preg_replace('/\D+/', '', $account_number_raw);
        if (!is_string($account_number_digits) || strlen($account_number_digits) !== 8) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Account number must be exactly 8 digits.'));
            exit;
        }

        self::migrate_schema_v54_candidate_bank_details_encryption();
        global $wpdb;
        $table = $this->get_candidate_bank_details_table();
        $legacy_sort_exists = self::table_has_column($table, 'sort_code');
        $legacy_account_exists = self::table_has_column($table, 'account_number');
        $now = current_time('mysql');
        $existing_id = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id
             FROM {$table}
             WHERE candidate_user_id = %d
             ORDER BY is_active DESC, id DESC
             LIMIT 1",
            $candidate_user_id
        ));

        $sort_code_enc = function_exists('cmn_encrypt_secret') ? cmn_encrypt_secret($sort_code_digits) : new WP_Error('cmn_bank_encrypt_missing', 'Bank encryption helper missing.');
        if (is_wp_error($sort_code_enc)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Secure bank storage is not configured. Please contact support.'));
            exit;
        }
        $account_number_enc = function_exists('cmn_encrypt_secret') ? cmn_encrypt_secret($account_number_digits) : new WP_Error('cmn_bank_encrypt_missing', 'Bank encryption helper missing.');
        if (is_wp_error($account_number_enc)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Secure bank storage is not configured. Please contact support.'));
            exit;
        }
        $sort_code_masked = $this->format_candidate_sort_code($sort_code_digits);
        $sort_code_last2 = substr($sort_code_digits, -2);
        $account_number_last4 = substr($account_number_digits, -4);
        if ($sort_code_masked === '' || $sort_code_last2 === '' || $account_number_last4 === '') {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Unable to prepare masked bank details.'));
            exit;
        }

        $notice_message = 'Bank details saved.';
        if ($existing_id > 0) {
            $update_data = [
                'account_name' => $account_name,
                'sort_code_enc' => $sort_code_enc,
                'account_number_enc' => $account_number_enc,
                'sort_code_last2' => $sort_code_last2,
                'sort_code_masked' => $sort_code_masked,
                'account_number_last4' => $account_number_last4,
                'enc_version' => 1,
                'is_active' => 1,
                'updated_at' => $now,
            ];
            $update_format = ['%s', '%s', '%s', '%s', '%s', '%s', '%d', '%d', '%s'];
            if ($legacy_sort_exists) {
                $update_data['sort_code'] = '';
                $update_format[] = '%s';
            }
            if ($legacy_account_exists) {
                $update_data['account_number'] = '';
                $update_format[] = '%s';
            }
            $update_result = $wpdb->update(
                $table,
                $update_data,
                ['id' => $existing_id],
                $update_format,
                ['%d']
            );
            if ($update_result === false) {
                wp_safe_redirect($build_redirect($redirect, 'error', 'Unable to update bank details right now. Please try again.'));
                exit;
            }

            $wpdb->query($wpdb->prepare(
                "UPDATE {$table}
                 SET is_active = 0, updated_at = %s
                 WHERE candidate_user_id = %d AND id <> %d",
                $now,
                $candidate_user_id,
                $existing_id
            ));
            $notice_message = 'Bank details updated.';
        } else {
            $insert_data = [
                'candidate_user_id' => $candidate_user_id,
                'account_name' => $account_name,
                'sort_code_enc' => $sort_code_enc,
                'account_number_enc' => $account_number_enc,
                'sort_code_last2' => $sort_code_last2,
                'sort_code_masked' => $sort_code_masked,
                'account_number_last4' => $account_number_last4,
                'enc_version' => 1,
                'is_active' => 1,
                'created_at' => $now,
                'updated_at' => $now,
            ];
            $insert_format = ['%d', '%s', '%s', '%s', '%s', '%s', '%s', '%d', '%d', '%s', '%s'];
            if ($legacy_sort_exists) {
                $insert_data['sort_code'] = '';
                $insert_format[] = '%s';
            }
            if ($legacy_account_exists) {
                $insert_data['account_number'] = '';
                $insert_format[] = '%s';
            }
            $insert_result = $wpdb->insert(
                $table,
                $insert_data,
                $insert_format
            );
            if ($insert_result === false) {
                wp_safe_redirect($build_redirect($redirect, 'error', 'Unable to save bank details right now. Please try again.'));
                exit;
            }
        }

        if (function_exists('cmn_migrate_bank_details_plain_to_encrypted')) {
            cmn_migrate_bank_details_plain_to_encrypted();
        }

        delete_transient($this->get_candidate_weekly_earnings_cache_key($candidate_user_id));

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'finance',
                'entity_type' => 'candidate',
                'entity_id' => $candidate_user_id,
                'event_type' => 'bank_details_updated',
                'actor_user_id' => $candidate_user_id,
                'metadata' => [
                    'source' => 'candidate_finance_bank_details_form',
                    'change_type' => $existing_id > 0 ? 'update' : 'create',
                ],
            ]);
        }
        if (function_exists('cmn_migrate_bank_details_plain_to_encrypted')) {
            cmn_migrate_bank_details_plain_to_encrypted();
        }

        wp_safe_redirect($build_redirect($redirect, 'success', $notice_message));
        exit;
    }

    /*
     * Prompt 31 acceptance tests:
     * 1) Candidate can accept self-employed acknowledgement once.
     * 2) Duplicate submissions do not create duplicate records.
     * 3) Non-candidate roles cannot submit acknowledgement.
     * 4) compliance_ack_accepted audit event is written without sensitive finance fields.
     */
    public function handle_candidate_accept_compliance_ack() {
        $default_redirect = $this->get_candidate_finance_focus_url('compliance-ack');
        $redirect_raw = isset($_POST['cmn_redirect']) ? (string) wp_unslash($_POST['cmn_redirect']) : '';
        $redirect = $redirect_raw !== ''
            ? wp_validate_redirect(esc_url_raw($redirect_raw), $default_redirect)
            : $default_redirect;

        $build_redirect = static function ($target, $status, $message) {
            $target = (string) $target;
            $fragment = '';
            $hash_pos = strpos($target, '#');
            if ($hash_pos !== false) {
                $fragment = substr($target, $hash_pos + 1);
                $target = substr($target, 0, $hash_pos);
            }
            $url = add_query_arg([
                'cmn_finance_ack_status' => sanitize_key((string) $status),
                'cmn_finance_ack_msg' => rawurlencode((string) $message),
            ], $target);
            if ($fragment !== '') {
                $url .= '#' . ltrim($fragment, '#');
            }
            return $url;
        };

        if (!is_user_logged_in()) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        $candidate_user_id = (int) get_current_user_id();
        if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('finance.view_self', ['candidate_user_id' => $candidate_user_id]);
            if (is_wp_error($ability_check)) {
                wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
                exit;
            }
        }

        $nonce = isset($_POST['cmn_candidate_compliance_ack_nonce'])
            ? sanitize_text_field((string) wp_unslash($_POST['cmn_candidate_compliance_ack_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_candidate_accept_compliance_ack')) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Invalid request. Please refresh and try again.'));
            exit;
        }

        $ack_confirmed = (string) wp_unslash($_POST['cmn_self_employed_ack_confirm'] ?? '') === '1';
        if (!$ack_confirmed) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Please confirm the acknowledgement before continuing.'));
            exit;
        }

        self::migrate_schema_v58_candidate_compliance_ack();
        global $wpdb;
        $table = $this->get_candidate_compliance_ack_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Compliance acknowledgement storage is unavailable.'));
            exit;
        }

        $ack_type = self::CANDIDATE_COMPLIANCE_ACK_TYPE_SELF_EMPLOYED_TAX;
        $ack_version = self::CANDIDATE_COMPLIANCE_ACK_VERSION_SELF_EMPLOYED_TAX;
        $ack_text_hash = $this->get_candidate_self_employed_ack_hash();
        $now = current_time('mysql');
        $accepted_ip = substr($this->get_request_ip_address(), 0, 45);
        $accepted_user_agent = substr(sanitize_text_field((string) ($_SERVER['HTTP_USER_AGENT'] ?? '')), 0, 255);

        $insert_result = $wpdb->query($wpdb->prepare(
            "INSERT INTO {$table}
                (candidate_user_id, ack_type, ack_version, ack_text_hash, accepted_at, accepted_ip, accepted_user_agent, created_at)
             VALUES
                (%d, %s, %s, %s, %s, %s, %s, %s)
             ON DUPLICATE KEY UPDATE id = id",
            $candidate_user_id,
            $ack_type,
            $ack_version,
            $ack_text_hash,
            $now,
            $accepted_ip,
            $accepted_user_agent,
            $now
        ));
        if ($insert_result === false) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Unable to save acknowledgement right now. Please try again.'));
            exit;
        }

        delete_transient($this->get_candidate_weekly_earnings_cache_key($candidate_user_id));

        if ((int) $insert_result > 0 && function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'finance',
                'entity_type' => 'candidate',
                'entity_id' => $candidate_user_id,
                'event_type' => 'compliance_ack_accepted',
                'actor_user_id' => $candidate_user_id,
                'metadata' => [
                    'ack_type' => $ack_type,
                    'ack_version' => $ack_version,
                ],
            ]);
        }

        // Keep acknowledged state clean in UI (no extra success banner text).
        wp_safe_redirect($redirect);
        exit;
    }

    /*
     * Prompt 32 acceptance tests:
     * 1) Candidate can generate/remake remittance PDFs for periods with payout run items.
     * 2) Non-candidate users are denied.
     */
    public function handle_candidate_generate_remittance_pdf() {
        $default_redirect = $this->get_candidate_finance_tab_url();
        $redirect_raw = isset($_POST['cmn_redirect']) ? (string) wp_unslash($_POST['cmn_redirect']) : '';
        $redirect = $redirect_raw !== ''
            ? wp_validate_redirect(esc_url_raw($redirect_raw), $default_redirect)
            : $default_redirect;

        $build_redirect = static function ($target, $status, $message) {
            return add_query_arg([
                'cmn_finance_docs_status' => sanitize_key((string) $status),
                'cmn_finance_docs_msg' => rawurlencode((string) $message),
            ], (string) $target);
        };

        if (!is_user_logged_in()) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        $candidate_user_id = (int) get_current_user_id();
        if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('finance.view_self', ['candidate_user_id' => $candidate_user_id]);
            if (is_wp_error($ability_check)) {
                wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
                exit;
            }
        }

        $nonce = isset($_POST['cmn_candidate_generate_remittance_pdf_nonce'])
            ? sanitize_text_field((string) wp_unslash($_POST['cmn_candidate_generate_remittance_pdf_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_candidate_generate_remittance_pdf')) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Invalid request. Please refresh and try again.'));
            exit;
        }

        $period_id = sanitize_text_field((string) wp_unslash($_POST['cmn_period_id'] ?? ''));
        if ($period_id === '') {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Payroll period is required.'));
            exit;
        }

        $result = $this->generate_candidate_remittance_pdf($candidate_user_id, $period_id, [
            'force_regenerate' => true,
            'actor_user_id' => $candidate_user_id,
            'trigger' => 'candidate_finance_generate',
        ]);
        if (is_wp_error($result)) {
            wp_safe_redirect($build_redirect($redirect, 'error', $result->get_error_message()));
            exit;
        }

        $message = !empty($result['regenerated'])
            ? 'Remittance PDF regenerated.'
            : 'Remittance PDF generated.';
        wp_safe_redirect($build_redirect($redirect, 'success', $message));
        exit;
    }

    /*
     * Prompt 32 acceptance tests:
     * 1) Candidate download endpoint enforces nonce + ownership checks.
     * 2) Staff/admin cannot download candidate remittance PDFs here.
     * 3) Download uses controlled file streaming and never exposes raw storage paths.
     */
    public function handle_candidate_download_remittance_pdf() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized', 403);
        }

        $candidate_user_id = (int) get_current_user_id();
        if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
            wp_die('Unauthorized', 403);
        }
        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('finance.view_self', ['candidate_user_id' => $candidate_user_id]);
            if (is_wp_error($ability_check)) {
                wp_die('Unauthorized', 403);
            }
        }

        $period_id = sanitize_text_field((string) wp_unslash($_REQUEST['cmn_period_id'] ?? ''));
        $nonce = isset($_REQUEST['cmn_remittance_nonce'])
            ? sanitize_text_field((string) wp_unslash($_REQUEST['cmn_remittance_nonce']))
            : '';
        if ($period_id === '') {
            wp_die('Remittance period is required.', 400);
        }
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_candidate_download_remittance_' . $candidate_user_id . '_' . $period_id)) {
            wp_die('Invalid request', 403);
        }

        $result = $this->generate_candidate_remittance_pdf($candidate_user_id, $period_id, [
            'force_regenerate' => false,
            'actor_user_id' => $candidate_user_id,
            'trigger' => 'candidate_finance_download',
        ]);
        if (is_wp_error($result)) {
            wp_die('Unable to download remittance: ' . esc_html($result->get_error_message()), 400);
        }

        $file_path = (string) ($result['file_path'] ?? '');
        if ($file_path === '' || !is_readable($file_path)) {
            $doc = is_array($result['doc'] ?? null) ? (array) $result['doc'] : [];
            $file_path = $this->get_candidate_remittance_doc_absolute_path((string) ($doc['pdf_path'] ?? ''));
        }
        if ($file_path === '' || !is_readable($file_path)) {
            wp_die('Remittance file not found.', 404);
        }

        $download_name = sanitize_file_name((string) ($result['download_name'] ?? $this->get_candidate_remittance_pdf_download_filename($candidate_user_id, $period_id)));
        if ($download_name === '' || strtolower(substr($download_name, -4)) !== '.pdf') {
            $download_name = $this->get_candidate_remittance_pdf_download_filename($candidate_user_id, $period_id);
        }
        $content_length = max(0, (int) @filesize($file_path));
        if ($content_length < 1) {
            wp_die('Remittance file is empty.', 500);
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'finance',
                'entity_type' => 'candidate',
                'entity_id' => $candidate_user_id,
                'event_type' => 'remittance_pdf_downloaded',
                'actor_user_id' => $candidate_user_id,
                'metadata' => [
                    'period_id' => $period_id,
                    'payout_run_id' => max(0, (int) ($result['payout_run_id'] ?? 0)),
                    'size' => $content_length,
                ],
            ]);
        }

        if (!headers_sent()) {
            nocache_headers();
            header('Content-Type: application/pdf');
            header('X-Content-Type-Options: nosniff');
            header('Content-Disposition: attachment; filename="' . str_replace('"', '', $download_name) . '"');
            header('Content-Length: ' . $content_length);
        }
        $handle = @fopen($file_path, 'rb');
        if ($handle) {
            while (!feof($handle)) {
                $chunk = fread($handle, 8192);
                if ($chunk === false) {
                    break;
                }
                echo $chunk;
            }
            fclose($handle);
            exit;
        }

        readfile($file_path);
        exit;
    }

    public function handle_generate_payout_run() {
        $default_redirect = $this->get_staff_payroll_tab_url();
        $redirect_raw = isset($_POST['cmn_redirect']) ? (string) wp_unslash($_POST['cmn_redirect']) : '';
        $redirect = $redirect_raw !== ''
            ? wp_validate_redirect(esc_url_raw($redirect_raw), $default_redirect)
            : $default_redirect;

        $build_redirect = static function ($target, $status, $message, $period_id = '') {
            $args = [
                'cmn_payroll_notice' => sanitize_key((string) $status),
                'cmn_payroll_msg' => rawurlencode((string) $message),
            ];
            $period_id = sanitize_text_field((string) $period_id);
            if ($period_id !== '') {
                $args['cmn_period_id'] = $period_id;
            }
            return add_query_arg($args, (string) $target);
        };

        if (!is_user_logged_in()) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        $current_user_id = (int) get_current_user_id();
        $is_staff_or_admin = $this->is_admin_user($current_user_id) || $this->is_staff_role($current_user_id);
        if ($current_user_id < 1 || !$is_staff_or_admin) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('payroll.run', ['actor_user_id' => $current_user_id]);
            if (is_wp_error($ability_check)) {
                wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
                exit;
            }
        }

        $nonce = isset($_POST['cmn_generate_payout_run_nonce'])
            ? sanitize_text_field((string) wp_unslash($_POST['cmn_generate_payout_run_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_generate_payout_run')) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Invalid request. Please refresh and try again.'));
            exit;
        }

        $period_id = sanitize_text_field((string) wp_unslash($_POST['cmn_period_id'] ?? ''));
        if ($period_id === '') {
            $current_period = function_exists('cmn_payroll_get_current_period')
                ? (array) cmn_payroll_get_current_period()
                : (array) $this->get_payroll_current_period();
            $period_id = sanitize_text_field((string) ($current_period['period_id'] ?? ''));
            if ($period_id === '') {
                $period_start = $this->normalize_invoice_date((string) ($current_period['period_start'] ?? ''));
                $period_end = $this->normalize_invoice_date((string) ($current_period['period_end'] ?? ''));
                if ($period_start !== '' && $period_end !== '') {
                    $period_id = $this->get_payroll_period_id($period_start, $period_end);
                }
            }
        }
        if ($period_id === '') {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Payroll period is required.'));
            exit;
        }

        $result = $this->generate_payout_run_for_period($period_id, [
            'actor_user_id' => $current_user_id,
            'generated_by' => 'staff',
            'trigger' => 'staff_manual',
        ]);
        if (is_wp_error($result)) {
            wp_safe_redirect($build_redirect($redirect, 'error', $result->get_error_message(), $period_id));
            exit;
        }

        $created = !empty($result['created']);
        $message = $created ? 'Payout run generated.' : 'Payout run already generated.';
        wp_safe_redirect($build_redirect($redirect, 'success', $message, $period_id));
        exit;
    }

    private function get_staff_payroll_candidate_options($limit = 500) {
        $limit = max(20, min(1000, (int) $limit));
        $users = get_users([
            'role__in' => ['cmn_candidate', 'cmn_candidate_pending', 'candidate'],
            'orderby' => 'display_name',
            'order' => 'ASC',
            'number' => $limit,
            'fields' => ['ID', 'display_name', 'user_login'],
        ]);
        if (!is_array($users) || !$users) {
            return [];
        }

        $options = [];
        foreach ($users as $user) {
            if (!$user instanceof WP_User) {
                continue;
            }
            $candidate_user_id = (int) ($user->ID ?? 0);
            if ($candidate_user_id < 1) {
                continue;
            }
            $label = trim((string) ($user->display_name ?? ''));
            if ($label === '') {
                $label = trim((string) ($user->user_login ?? ''));
            }
            if ($label === '') {
                $label = 'Candidate #' . $candidate_user_id;
            }

            $options[] = [
                'candidate_user_id' => $candidate_user_id,
                'candidate_label' => $label,
            ];
        }
        return $options;
    }

    private function get_staff_payroll_pending_adjustments($limit = 50) {
        $limit = max(1, min(500, (int) $limit));

        global $wpdb;
        $table = $this->get_payroll_adjustments_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }

        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE adjustment_status = %s
             ORDER BY created_at ASC, id ASC
             LIMIT %d",
            'pending',
            $limit
        ), ARRAY_A);
        if (!is_array($rows)) {
            return [];
        }

        $out = [];
        foreach ($rows as $row) {
            $candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
            $out[] = [
                'id' => (int) ($row['id'] ?? 0),
                'candidate_user_id' => $candidate_user_id,
                'candidate_label' => $this->get_payroll_candidate_label($candidate_user_id),
                'period_id' => sanitize_text_field((string) ($row['period_id'] ?? '')),
                'adjustment_amount' => round((float) ($row['adjustment_amount'] ?? 0), 2),
                'adjustment_reason' => sanitize_text_field((string) ($row['adjustment_reason'] ?? '')),
                'adjustment_status' => $this->normalize_payroll_adjustment_status((string) ($row['adjustment_status'] ?? 'pending')),
                'created_by_user_id' => max(0, (int) ($row['created_by_user_id'] ?? 0)),
                'created_at' => $this->normalize_invoice_datetime((string) ($row['created_at'] ?? '')),
                'updated_at' => $this->normalize_invoice_datetime((string) ($row['updated_at'] ?? '')),
            ];
        }
        return $out;
    }

    private function get_staff_payroll_adjustment_row($adjustment_id) {
        $adjustment_id = (int) $adjustment_id;
        if ($adjustment_id < 1) {
            return [];
        }

        global $wpdb;
        $table = $this->get_payroll_adjustments_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }

        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE id = %d
             LIMIT 1",
            $adjustment_id
        ), ARRAY_A);
        if (!is_array($row)) {
            return [];
        }

        $candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
        return [
            'id' => (int) ($row['id'] ?? 0),
            'candidate_user_id' => $candidate_user_id,
            'candidate_label' => $this->get_payroll_candidate_label($candidate_user_id),
            'period_id' => sanitize_text_field((string) ($row['period_id'] ?? '')),
            'adjustment_amount' => round((float) ($row['adjustment_amount'] ?? 0), 2),
            'adjustment_reason' => sanitize_text_field((string) ($row['adjustment_reason'] ?? '')),
            'adjustment_status' => $this->normalize_payroll_adjustment_status((string) ($row['adjustment_status'] ?? 'pending')),
            'created_by_user_id' => max(0, (int) ($row['created_by_user_id'] ?? 0)),
            'created_at' => $this->normalize_invoice_datetime((string) ($row['created_at'] ?? '')),
            'updated_at' => $this->normalize_invoice_datetime((string) ($row['updated_at'] ?? '')),
            'applied_in_period_id' => sanitize_text_field((string) ($row['applied_in_period_id'] ?? '')),
        ];
    }

    private function get_staff_payroll_approved_pay_approvals_for_period($period_id, $limit = 40) {
        $period_id = sanitize_text_field((string) $period_id);
        $limit = max(1, min(200, (int) $limit));
        if ($period_id === '') {
            return [];
        }

        global $wpdb;
        $table = $this->get_candidate_pay_approvals_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            return [];
        }

        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT id, candidate_user_id, booking_id, booking_day_date, period_id, approval_status, approved_method, dispute_flag
             FROM {$table}
             WHERE period_id = %s
               AND approval_status = %s
               AND COALESCE(dispute_flag, 0) = 0
             ORDER BY booking_day_date ASC, id ASC
             LIMIT %d",
            $period_id,
            'approved',
            $limit
        ), ARRAY_A);
        if (!is_array($rows)) {
            return [];
        }

        $out = [];
        foreach ($rows as $row) {
            $candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
            $out[] = [
                'id' => (int) ($row['id'] ?? 0),
                'candidate_user_id' => $candidate_user_id,
                'candidate_label' => $this->get_payroll_candidate_label($candidate_user_id),
                'booking_id' => max(0, (int) ($row['booking_id'] ?? 0)),
                'booking_day_date' => $this->normalize_invoice_date((string) ($row['booking_day_date'] ?? '')),
                'period_id' => sanitize_text_field((string) ($row['period_id'] ?? '')),
                'approval_status' => sanitize_key((string) ($row['approval_status'] ?? 'approved')),
                'approved_method' => sanitize_key((string) ($row['approved_method'] ?? '')),
            ];
        }
        return $out;
    }

    private function get_staff_payroll_period_label_from_id($period_id) {
        $period_id = sanitize_text_field((string) $period_id);
        if ($period_id === '') {
            return 'Unknown period';
        }
        $parsed = $this->parse_payroll_period_id($period_id);
        $period_start = $this->normalize_invoice_date((string) ($parsed['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($parsed['period_end'] ?? ''));
        if ($period_start === '' || $period_end === '') {
            return $period_id;
        }

        $period_start_label = date_i18n('j M Y', strtotime($period_start));
        $period_end_label = date_i18n('j M Y', strtotime($period_end));
        return 'Fri ' . $period_start_label . ' -> Thu ' . $period_end_label;
    }

    public function handle_payroll_adjustment_create() {
        $default_redirect = $this->get_staff_payroll_tab_url();
        $redirect_raw = isset($_POST['cmn_redirect']) ? (string) wp_unslash($_POST['cmn_redirect']) : '';
        $redirect = $redirect_raw !== ''
            ? wp_validate_redirect(esc_url_raw($redirect_raw), $default_redirect)
            : $default_redirect;

        $build_redirect = static function ($target, $status, $message, $period_id = '') {
            $args = [
                'cmn_payroll_notice' => sanitize_key((string) $status),
                'cmn_payroll_msg' => rawurlencode((string) $message),
            ];
            $period_id = sanitize_text_field((string) $period_id);
            if ($period_id !== '') {
                $args['cmn_period_id'] = $period_id;
            }
            return add_query_arg($args, (string) $target);
        };

        if (!is_user_logged_in()) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        $actor_user_id = (int) get_current_user_id();
        $is_admin = $this->is_admin_user($actor_user_id);
        $is_staff = $this->is_staff_role($actor_user_id);
        if ($actor_user_id < 1 || (!$is_admin && !$is_staff)) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('payroll.mutate_any', ['actor_user_id' => $actor_user_id]);
            if (is_wp_error($ability_check)) {
                wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
                exit;
            }
        }

        $nonce = isset($_POST['cmn_payroll_adjustment_create_nonce'])
            ? sanitize_text_field((string) wp_unslash($_POST['cmn_payroll_adjustment_create_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_payroll_adjustment_create')) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Invalid request. Please refresh and try again.'));
            exit;
        }

        $candidate_user_id = max(0, (int) wp_unslash($_POST['cmn_candidate_user_id'] ?? 0));
        if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Please select a valid candidate.'));
            exit;
        }

        $amount_raw = str_replace(',', '', trim((string) wp_unslash($_POST['cmn_adjustment_amount'] ?? '')));
        if ($amount_raw === '' || !is_numeric($amount_raw)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Adjustment amount is required.'));
            exit;
        }
        $amount = round((float) $amount_raw, 2);
        if ($amount == 0.00) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Adjustment amount cannot be zero.'));
            exit;
        }
        if (!$is_admin && abs($amount) > 200) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Staff can only create adjustments up to £200.'));
            exit;
        }

        $reason = sanitize_text_field((string) wp_unslash($_POST['cmn_adjustment_reason'] ?? ''));
        $reason = substr(trim($reason), 0, 255);
        if ($reason === '' || strlen($reason) < 3) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Adjustment reason is required.'));
            exit;
        }

        $period_id = sanitize_text_field((string) wp_unslash($_POST['cmn_adjustment_period_id'] ?? ''));
        if ($period_id === '') {
            $current_period = function_exists('cmn_payroll_get_current_period')
                ? (array) cmn_payroll_get_current_period()
                : (array) $this->get_payroll_current_period();
            $period_start = $this->normalize_invoice_date((string) ($current_period['period_start'] ?? ''));
            $period_end = $this->normalize_invoice_date((string) ($current_period['period_end'] ?? ''));
            if ($period_start !== '' && $period_end !== '') {
                $period_id = $this->get_payroll_period_id($period_start, $period_end);
            }
        }
        $parsed_period = $this->parse_payroll_period_id($period_id);
        if ($period_id === '' || $this->normalize_invoice_date((string) ($parsed_period['period_start'] ?? '')) === '' || $this->normalize_invoice_date((string) ($parsed_period['period_end'] ?? '')) === '') {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Target period is invalid.'));
            exit;
        }

        self::migrate_schema_v57_payroll_adjustments_and_disputes();
        global $wpdb;
        $table = $this->get_payroll_adjustments_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Payroll adjustments table is unavailable.'));
            exit;
        }

        $now = current_time('mysql');
        $inserted = $wpdb->insert(
            $table,
            [
                'candidate_user_id' => $candidate_user_id,
                'period_id' => $period_id,
                'adjustment_amount' => $amount,
                'adjustment_reason' => $reason,
                'adjustment_status' => 'pending',
                'created_by_user_id' => $actor_user_id,
                'created_at' => $now,
                'updated_at' => $now,
                'applied_in_period_id' => null,
            ],
            ['%d', '%s', '%f', '%s', '%s', '%d', '%s', '%s', '%s']
        );
        if ($inserted === false) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Unable to create payroll adjustment right now.'));
            exit;
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'payroll',
                'entity_type' => 'candidate',
                'entity_id' => $candidate_user_id,
                'event_type' => 'payroll_adjustment_created',
                'event_ref' => $period_id . ':' . (int) $wpdb->insert_id,
                'actor_user_id' => $actor_user_id,
                'metadata' => [
                    'adjustment_id' => (int) $wpdb->insert_id,
                    'period_id' => $period_id,
                    'adjustment_amount' => $amount,
                    'adjustment_reason' => $reason,
                ],
            ]);
        }

        wp_safe_redirect($build_redirect($redirect, 'success', 'Payroll adjustment created and pending review.', $period_id));
        exit;
    }

    public function handle_payroll_adjustment_decision() {
        $default_redirect = $this->get_staff_payroll_tab_url();
        $redirect_raw = isset($_POST['cmn_redirect']) ? (string) wp_unslash($_POST['cmn_redirect']) : '';
        $redirect = $redirect_raw !== ''
            ? wp_validate_redirect(esc_url_raw($redirect_raw), $default_redirect)
            : $default_redirect;

        $build_redirect = static function ($target, $status, $message, $period_id = '') {
            $args = [
                'cmn_payroll_notice' => sanitize_key((string) $status),
                'cmn_payroll_msg' => rawurlencode((string) $message),
            ];
            $period_id = sanitize_text_field((string) $period_id);
            if ($period_id !== '') {
                $args['cmn_period_id'] = $period_id;
            }
            return add_query_arg($args, (string) $target);
        };

        if (!is_user_logged_in()) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        $actor_user_id = (int) get_current_user_id();
        $is_admin = $this->is_admin_user($actor_user_id);
        $is_staff = $this->is_staff_role($actor_user_id);
        if ($actor_user_id < 1 || (!$is_admin && !$is_staff)) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('payroll.mutate_any', ['actor_user_id' => $actor_user_id]);
            if (is_wp_error($ability_check)) {
                wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
                exit;
            }
        }

        $nonce = isset($_POST['cmn_payroll_adjustment_decision_nonce'])
            ? sanitize_text_field((string) wp_unslash($_POST['cmn_payroll_adjustment_decision_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_payroll_adjustment_decision')) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Invalid request. Please refresh and try again.'));
            exit;
        }

        $adjustment_id = max(0, (int) wp_unslash($_POST['cmn_adjustment_id'] ?? 0));
        $decision = sanitize_key((string) wp_unslash($_POST['cmn_decision'] ?? ''));
        if (!in_array($decision, ['approve', 'reject'], true)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Decision is invalid.'));
            exit;
        }

        $decision_reason = sanitize_text_field((string) wp_unslash($_POST['cmn_decision_reason'] ?? ''));
        $decision_reason = substr(trim($decision_reason), 0, 255);
        if ($decision_reason === '' || strlen($decision_reason) < 3) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Decision reason is required.'));
            exit;
        }

        $adjustment_row = $this->get_staff_payroll_adjustment_row($adjustment_id);
        $period_id = sanitize_text_field((string) ($adjustment_row['period_id'] ?? ''));
        if (!$adjustment_row) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Adjustment not found.'));
            exit;
        }
        if (($adjustment_row['adjustment_status'] ?? '') !== 'pending') {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Only pending adjustments can be updated.', $period_id));
            exit;
        }
        if ($decision === 'approve' && !$is_admin && abs((float) ($adjustment_row['adjustment_amount'] ?? 0)) > 200) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Staff can only approve adjustments up to £200.', $period_id));
            exit;
        }

        global $wpdb;
        $table = $this->get_payroll_adjustments_table();
        if (!$this->candidate_rewards_table_exists($table)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Payroll adjustments table is unavailable.', $period_id));
            exit;
        }

        $new_status = $decision === 'approve' ? 'approved' : 'rejected';
        $updated = $wpdb->update(
            $table,
            [
                'adjustment_status' => $new_status,
                'updated_at' => current_time('mysql'),
            ],
            [
                'id' => $adjustment_id,
                'adjustment_status' => 'pending',
            ],
            ['%s', '%s'],
            ['%d', '%s']
        );
        if ($updated === false) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Unable to update payroll adjustment.', $period_id));
            exit;
        }
        if ((int) $updated < 1) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Adjustment was already updated by another staff member.', $period_id));
            exit;
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'payroll',
                'entity_type' => 'adjustment',
                'entity_id' => $adjustment_id,
                'event_type' => $new_status === 'approved' ? 'payroll_adjustment_approved' : 'payroll_adjustment_rejected',
                'event_ref' => $period_id . ':' . $adjustment_id,
                'actor_user_id' => $actor_user_id,
                'metadata' => [
                    'period_id' => $period_id,
                    'candidate_user_id' => (int) ($adjustment_row['candidate_user_id'] ?? 0),
                    'adjustment_amount' => round((float) ($adjustment_row['adjustment_amount'] ?? 0), 2),
                    'decision_reason' => $decision_reason,
                ],
            ]);
        }

        $message = $new_status === 'approved' ? 'Payroll adjustment approved.' : 'Payroll adjustment rejected.';
        wp_safe_redirect($build_redirect($redirect, 'success', $message, $period_id));
        exit;
    }

