    public function handle_staff_payroll_ticket_quick_action() {
        $default_redirect = $this->get_staff_payroll_tab_url();
        $redirect_raw = isset($_POST['cmn_redirect']) ? (string) wp_unslash($_POST['cmn_redirect']) : '';
        $redirect = $redirect_raw !== ''
            ? wp_validate_redirect(esc_url_raw($redirect_raw), $default_redirect)
            : $default_redirect;

        $build_redirect = static function ($target, $status, $message) {
            return add_query_arg([
                'cmn_payroll_notice' => sanitize_key((string) $status),
                'cmn_payroll_msg' => rawurlencode((string) $message),
            ], (string) $target);
        };

        if (!is_user_logged_in()) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }

        $actor_user_id = (int) get_current_user_id();
        $is_staff_or_admin = $this->is_admin_user($actor_user_id) || $this->is_staff_role($actor_user_id);
        if ($actor_user_id < 1 || !$is_staff_or_admin) {
            wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
            exit;
        }
        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('payroll.view_any', ['actor_user_id' => $actor_user_id]);
            if (is_wp_error($ability_check)) {
                wp_safe_redirect($build_redirect($default_redirect, 'error', 'Access denied.'));
                exit;
            }
        }

        $nonce = isset($_POST['cmn_staff_payroll_ticket_quick_action_nonce'])
            ? sanitize_text_field((string) wp_unslash($_POST['cmn_staff_payroll_ticket_quick_action_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_staff_payroll_ticket_quick_action')) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Invalid request. Please refresh and try again.'));
            exit;
        }

        $ticket_id = max(0, (int) wp_unslash($_POST['cmn_ticket_id'] ?? 0));
        $ticket_action = sanitize_key((string) wp_unslash($_POST['cmn_ticket_action'] ?? ''));
        if ($ticket_id < 1 || !in_array($ticket_action, ['mark_pending', 'resolve', 'close', 'request_info'], true)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Payroll ticket action is invalid.'));
            exit;
        }

        $ticket = $this->get_support_ticket($ticket_id);
        if (!is_array($ticket) || !$ticket || !$this->is_payroll_support_ticket_row($ticket)) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Payroll ticket not found.'));
            exit;
        }

        $status_before = $this->normalize_payroll_support_ticket_status((string) ($ticket['status'] ?? 'open'));
        $status_after = $status_before;
        $message = 'Payroll ticket updated.';
        $request_info_message = '';

        if ($ticket_action === 'mark_pending') {
            $status_after = 'pending';
            $message = 'Payroll ticket marked pending.';
        } elseif ($ticket_action === 'resolve') {
            $status_after = 'resolved';
            $message = 'Payroll ticket marked resolved.';
        } elseif ($ticket_action === 'close') {
            $status_after = 'closed';
            $message = 'Payroll ticket closed.';
        } elseif ($ticket_action === 'request_info') {
            $status_after = 'pending';
            $message = 'Requested more information from candidate.';
            $request_info_message = sanitize_textarea_field((string) wp_unslash($_POST['cmn_request_info_message'] ?? ''));
            $request_info_message = trim($request_info_message);
            if ($request_info_message === '') {
                $request_info_message = 'Please share any additional details for this payroll query, including relevant booking dates or attendance notes.';
            }
        }

        global $wpdb;
        $ticket_table = $this->get_support_ticket_table();
        $message_table = $this->get_support_message_table();
        $has_assignee = $this->support_ticket_has_column('assigned_to_user_id');
        $assignee_before = max(0, (int) ($ticket['assigned_to_user_id'] ?? 0));
        $assignee_after = $assignee_before;
        if ($has_assignee && $assignee_after < 1) {
            $assignee_after = $actor_user_id;
        }

        $update_data = [
            'status' => $status_after,
            'updated_at' => current_time('mysql'),
            'is_new_for_admin' => 0,
            'closed_at' => $status_after === 'closed' ? current_time('mysql') : null,
        ];
        $update_format = ['%s', '%s', '%d', '%s'];
        if ($has_assignee && $assignee_after > 0) {
            $update_data['assigned_to_user_id'] = $assignee_after;
            $update_format[] = '%d';
        }

        $updated = $wpdb->update(
            $ticket_table,
            $update_data,
            ['id' => $ticket_id],
            $update_format,
            ['%d']
        );
        if ($updated === false) {
            wp_safe_redirect($build_redirect($redirect, 'error', 'Unable to update payroll ticket.'));
            exit;
        }

        if ($status_before !== $status_after) {
            $this->log_payroll_ticket_status_changed_event($ticket_id, $status_before, $status_after, $actor_user_id);
        }
        $this->log_payroll_ticket_assigned_event(
            $ticket_id,
            $assignee_before,
            $assignee_after,
            $actor_user_id,
            $status_before,
            $status_after
        );

        if ($ticket_action === 'close') {
            $this->insert_support_system_message_once($ticket_id, 'Ticket closed by payroll support.', $actor_user_id, 'admin');
        }

        if ($ticket_action === 'request_info') {
            $wpdb->insert(
                $message_table,
                [
                    'ticket_id' => $ticket_id,
                    'sender_user_id' => $actor_user_id,
                    'sender_type' => 'admin',
                    'message' => $request_info_message,
                    'attachment_ids' => null,
                    'created_at' => current_time('mysql'),
                ],
                ['%d', '%d', '%s', '%s', '%s', '%s']
            );
            $owner_user_id = (int) $this->get_support_owner_user_id($ticket);
            if ($owner_user_id > 0) {
                $ticket_ref = sanitize_text_field((string) ($ticket['ticket_ref'] ?? ''));
                $portal_link = $this->get_support_link_for_user($owner_user_id, $ticket_id, $ticket_ref);
                $subject_line = 'Update on your payroll ticket: ' . $ticket_ref;
                $email_body = "We've requested more information on your payroll query.\n\n{$request_info_message}\n\nReply in your portal:\n{$portal_link}";
                $this->send_support_email_to_user($owner_user_id, $subject_line, $email_body, 'support_ticket_reply', [
                    'ticket_id' => $ticket_id,
                ]);
                $this->add_notification($owner_user_id, 'support_reply', 'Payroll support update', $ticket_ref . ' needs more information.', $portal_link);
            }
        }

        wp_safe_redirect($build_redirect($redirect, 'success', $message));
        exit;
    }

    /*
     * Prompt 22 acceptance tests:
     * 1) Candidate can view Finance page.
     * 2) Non-candidates are denied access.
     * 3) Weekly figures display.
     * 4) Placeholder buttons are present and do not error.
     *
     * Prompt 24 acceptance tests:
     * 1) Candidate can view and submit bank details form.
     * 2) Masked bank values display after save.
     * 3) Validation messages are returned for invalid formats.
     *
     * Prompt 25 acceptance tests:
     * 1) Finance page displays masked bank fields only (no decrypt for UI).
     * 2) Migration path supports legacy plaintext rows without exposing full values.
     *
     * Prompt 29 acceptance tests:
     * 1) Candidate weekly earnings are sourced from approved pay-approval booking-days.
     * 2) Missing bank details show expected payout as on hold.
     * 3) Before payroll lock, UI note shows estimate pending lock.
     *
     * Prompt 31 acceptance tests:
     * 1) Candidate can submit self-employed acknowledgement once.
     * 2) Accepted status persists and shows accepted timestamp.
     * 3) Missing acknowledgement warns and keeps payout readiness on hold.
     *
     * Prompt 32 acceptance tests:
     * 1) Candidate can generate/download weekly remittance PDFs for payout periods.
     * 2) Documents list shows current and previous payroll periods.
     * 3) Download controls are candidate-only and nonce-protected.
     *
     * Prompt 33 acceptance tests:
     * 1) Candidate can open payroll query form from Weekly Pay Overview.
     * 2) Form includes period selector, issue type, optional booking-day multi-select, and message.
     * 3) Submission uses secure candidate-only AJAX handler.
     */
    private function render_candidate_finance_tab() {
        $candidate_user_id = (int) get_current_user_id();
        if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
            return '<div class="cmn-dashboard-card"><h3>Access denied</h3><p>You do not have permission to access this page.</p></div>';
        }
        $portal_url = $this->get_portal_base_url();
        $candidate_support_url = add_query_arg(['candidate' => 'support'], $portal_url);
        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('finance.view_self', ['candidate_user_id' => $candidate_user_id]);
            if (is_wp_error($ability_check)) {
                return '<div class="cmn-dashboard-card"><h3>Access denied</h3><p>You do not have permission to access this page.</p></div>';
            }
        }
        self::migrate_schema_v58_candidate_compliance_ack();
        self::migrate_schema_v59_candidate_remittance_docs();

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'finance',
                'entity_type' => 'candidate',
                'entity_id' => $candidate_user_id,
                'event_type' => 'candidate_finance_viewed',
                'actor_user_id' => $candidate_user_id,
                'metadata' => [
                    'source' => 'candidate_finance_tab',
                ],
            ]);
        }

        $weekly_earnings_payload = [
            'week_range' => [
                'start_date' => '',
                'end_date' => '',
                'label' => 'Fri-Thu',
            ],
            'total' => 0.00,
            'expected_payout' => 0.00,
            'last_week_total' => 0.00,
        ];
        $weekly_earnings_error = '';
        $weekly_earnings_result = $this->get_candidate_weekly_earnings_payload($candidate_user_id, true);
        if (is_wp_error($weekly_earnings_result)) {
            $weekly_earnings_error = $weekly_earnings_result->get_error_message();
        } elseif (is_array($weekly_earnings_result)) {
            $weekly_earnings_payload = array_merge($weekly_earnings_payload, $weekly_earnings_result);
        }

        $weekly_earnings_week_label = sanitize_text_field((string) (($weekly_earnings_payload['week_range']['label'] ?? 'Fri-Thu')));
        $weekly_earnings_total = round((float) ($weekly_earnings_payload['total'] ?? 0), 2);
        $weekly_expected_payout = round((float) ($weekly_earnings_payload['expected_payout'] ?? $weekly_earnings_total), 2);
        $weekly_expected_is_hold = !empty($weekly_earnings_payload['expected_payout_is_hold']);
        $weekly_expected_hold_message = sanitize_text_field((string) ($weekly_earnings_payload['expected_payout_display'] ?? 'On hold until bank details added'));
        $weekly_expected_display = $weekly_expected_is_hold
            ? ($weekly_expected_hold_message !== '' ? $weekly_expected_hold_message : 'On hold until bank details added')
            : ('GBP ' . number_format($weekly_expected_payout, 2));
        $weekly_last_week_total = round((float) ($weekly_earnings_payload['last_week_total'] ?? 0), 2);
        $weekly_state_label = sanitize_text_field((string) ($weekly_earnings_payload['payout_state_label'] ?? 'Estimate'));
        $weekly_state_chip_class = sanitize_html_class((string) ($weekly_earnings_payload['payout_state_chip_class'] ?? 'is-pending'));
        if ($weekly_state_chip_class === '') {
            $weekly_state_chip_class = 'is-pending';
        }
        $weekly_state_note = sanitize_text_field((string) ($weekly_earnings_payload['payout_state_note'] ?? 'Estimate (pending lock).'));
        if ($weekly_state_note === '') {
            $weekly_state_note = 'Estimate (pending lock).';
        }
        $ytd_monthly_payload = $this->get_candidate_year_to_date_monthly_earnings($candidate_user_id);
        $ytd_month_rows = is_array($ytd_monthly_payload['months'] ?? null) ? (array) ($ytd_monthly_payload['months'] ?? []) : [];
        $ytd_total_confirmed = round((float) ($ytd_monthly_payload['total_confirmed'] ?? 0), 2);
        $ytd_academic_year_label = sanitize_text_field((string) ($ytd_monthly_payload['academic_year_label'] ?? ''));

        $bank_details = $this->get_candidate_bank_details_record($candidate_user_id);
        $bank_sort_code_display = sanitize_text_field((string) ($bank_details['sort_code_masked'] ?? ''));
        $bank_account_last4 = preg_replace('/\D+/', '', (string) ($bank_details['account_number_last4'] ?? ''));
        if (!is_string($bank_account_last4)) {
            $bank_account_last4 = '';
        }
        $has_bank_details = ($bank_sort_code_display !== '' && strlen($bank_account_last4) === 4);
        $bank_status_label = $has_bank_details ? 'Added' : 'Not added';
        $bank_status_chip = $has_bank_details ? 'is-approved' : 'is-pending';
        $bank_action_label = $has_bank_details ? 'Edit' : 'Save bank details';
        $bank_account_name = sanitize_text_field((string) ($bank_details['account_name'] ?? ''));
        $bank_account_number_display = $has_bank_details ? ('****' . $bank_account_last4) : '';
        $finance_notice_status = sanitize_key((string) wp_unslash($_GET['cmn_finance_bank_status'] ?? ''));
        $finance_notice_message_raw = (string) wp_unslash((string) ($_GET['cmn_finance_bank_msg'] ?? ''));
        $finance_notice_message = $finance_notice_message_raw !== ''
            ? sanitize_text_field(rawurldecode($finance_notice_message_raw))
            : '';
        $finance_notice_class = 'cmn-register-warning';
        if ($finance_notice_status === 'success') {
            $finance_notice_class = 'cmn-register-success';
        } elseif ($finance_notice_status === 'error') {
            $finance_notice_class = 'cmn-register-error';
        }
        $ack_record = $this->get_candidate_self_employed_ack_record($candidate_user_id);
        $has_self_employed_ack = $this->has_candidate_self_employed_ack($candidate_user_id);
        $ack_status_chip = $has_self_employed_ack ? 'is-approved' : 'is-warning';
        $ack_status_label = $has_self_employed_ack ? 'Accepted' : 'Required';
        $ack_accepted_at = $this->normalize_invoice_datetime((string) ($ack_record['accepted_at'] ?? ''));
        $ack_accepted_date_display = $ack_accepted_at !== '' ? mysql2date('d/m/Y', $ack_accepted_at, false) : '';
        $finance_ack_notice_status = sanitize_key((string) wp_unslash($_GET['cmn_finance_ack_status'] ?? ''));
        $finance_ack_notice_message_raw = (string) wp_unslash((string) ($_GET['cmn_finance_ack_msg'] ?? ''));
        $finance_ack_notice_message = $finance_ack_notice_message_raw !== ''
            ? sanitize_text_field(rawurldecode($finance_ack_notice_message_raw))
            : '';
        $finance_ack_notice_class = 'cmn-register-warning';
        if ($finance_ack_notice_status === 'success') {
            $finance_ack_notice_class = 'cmn-register-success';
        } elseif ($finance_ack_notice_status === 'error') {
            $finance_ack_notice_class = 'cmn-register-error';
        }
        $finance_docs_notice_status = sanitize_key((string) wp_unslash($_GET['cmn_finance_docs_status'] ?? ''));
        $finance_docs_notice_message_raw = (string) wp_unslash((string) ($_GET['cmn_finance_docs_msg'] ?? ''));
        $finance_docs_notice_message = $finance_docs_notice_message_raw !== ''
            ? sanitize_text_field(rawurldecode($finance_docs_notice_message_raw))
            : '';
        $finance_docs_notice_class = 'cmn-register-warning';
        if ($finance_docs_notice_status === 'success') {
            $finance_docs_notice_class = 'cmn-register-success';
        } elseif ($finance_docs_notice_status === 'error') {
            $finance_docs_notice_class = 'cmn-register-error';
        }

        $remittance_period_rows = [];
        $current_period = function_exists('cmn_payroll_get_current_period')
            ? (array) cmn_payroll_get_current_period()
            : (array) $this->get_payroll_current_period();
        $previous_period = function_exists('cmn_payroll_get_previous_period')
            ? (array) cmn_payroll_get_previous_period()
            : (array) $this->get_payroll_previous_period();
        $candidate_remittance_periods = [$current_period, $previous_period];
        $candidate_remittance_period_ids = [];
        foreach ($candidate_remittance_periods as $period_row) {
            $period_row = is_array($period_row) ? $period_row : [];
            $period_start = $this->normalize_invoice_date((string) ($period_row['period_start'] ?? ''));
            $period_end = $this->normalize_invoice_date((string) ($period_row['period_end'] ?? ''));
            if ($period_start === '' || $period_end === '') {
                continue;
            }
            $period_id = sanitize_text_field((string) ($period_row['period_id'] ?? ''));
            if ($period_id === '') {
                $period_id = $this->get_payroll_period_id($period_start, $period_end);
            }
            if ($period_id === '' || isset($candidate_remittance_period_ids[$period_id])) {
                continue;
            }
            $candidate_remittance_period_ids[$period_id] = true;
            $remittance_period_rows[] = [
                'period_id' => $period_id,
                'period_start' => $period_start,
                'period_end' => $period_end,
                'pay_date' => $this->normalize_invoice_date((string) ($period_row['pay_date'] ?? '')),
                'label' => sanitize_text_field((string) ($period_row['label'] ?? ('Fri ' . $period_start . ' – Thu ' . $period_end))),
            ];
        }
        $remittance_doc_map = $this->get_candidate_remittance_doc_map_for_periods($candidate_user_id, array_keys($candidate_remittance_period_ids));
        foreach ($remittance_period_rows as $index => $period_row) {
            $period_id = sanitize_text_field((string) ($period_row['period_id'] ?? ''));
            if ($period_id === '') {
                continue;
            }
            $payout_item = $this->get_candidate_payout_run_item_for_period($candidate_user_id, $period_id);
            $has_payout_item = !empty($payout_item['id']);
            $doc_row = isset($remittance_doc_map[$period_id]) && is_array($remittance_doc_map[$period_id])
                ? (array) $remittance_doc_map[$period_id]
                : [];
            $has_doc = !empty($doc_row['id']) && $this->sanitize_remittance_pdf_relative_path((string) ($doc_row['pdf_path'] ?? '')) !== '' && $this->normalize_remittance_doc_status((string) ($doc_row['doc_status'] ?? 'generated')) !== 'voided';
            $download_url = '';
            if ($has_doc) {
                $download_url = wp_nonce_url(
                    add_query_arg([
                        'action' => 'cmn_candidate_download_remittance_pdf',
                        'cmn_period_id' => $period_id,
                    ], admin_url('admin-post.php')),
                    'cmn_candidate_download_remittance_' . $candidate_user_id . '_' . $period_id,
                    'cmn_remittance_nonce'
                );
            }
            $remittance_period_rows[$index]['has_payout_item'] = $has_payout_item;
            $remittance_period_rows[$index]['payout_item'] = $payout_item;
            $remittance_period_rows[$index]['doc_row'] = $doc_row;
            $remittance_period_rows[$index]['has_doc'] = $has_doc;
            $remittance_period_rows[$index]['download_url'] = $download_url;
        }
        $payroll_query_period_options = $this->get_candidate_payroll_query_period_options(5);
        $payroll_query_issue_type_map = $this->get_candidate_payroll_query_issue_type_map();
        $payroll_query_default_period_id = '';
        $payroll_query_booking_map = [];
        foreach ($payroll_query_period_options as $period_row) {
            if (!is_array($period_row)) {
                continue;
            }
            $period_id = sanitize_text_field((string) ($period_row['period_id'] ?? ''));
            if ($period_id === '') {
                continue;
            }
            if ($payroll_query_default_period_id === '') {
                $payroll_query_default_period_id = $period_id;
            }
            $payroll_query_booking_map[$period_id] = $this->get_candidate_payroll_query_booking_day_options($candidate_user_id, $period_id);
        }
        $payroll_query_booking_map_json = wp_json_encode(
            $payroll_query_booking_map,
            JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT
        );
        if (!is_string($payroll_query_booking_map_json) || $payroll_query_booking_map_json === '') {
            $payroll_query_booking_map_json = '{}';
        }
        $candidate_finance_focus = str_replace('_', '-', sanitize_key((string) wp_unslash($_GET['cmn_candidate_focus'] ?? '')));
        $finance_notice_is_error = ($finance_notice_status === 'error');
        $bank_details_open = (
            ($candidate_finance_focus === 'bank-details' && (!$has_bank_details || $finance_notice_is_error))
            || $finance_notice_is_error
        );

        ob_start();
        ?>
        <section class="cmn-candidate-finance-page">
            <?php if ($finance_notice_message !== '') : ?>
                <div class="<?php echo esc_attr($finance_notice_class); ?> cmn-candidate-finance-bank-message"><?php echo esc_html($finance_notice_message); ?></div>
