    private function render_candidate_rewards_tab($candidate_id, $portal_url) {
        $candidate_id = (int) $candidate_id;
        $portal_url = (string) $portal_url;
        $candidate_user_id = (int) get_current_user_id();
        if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
            return '<div class="cmn-dashboard-card"><h3>Access restricted</h3><p>This section is available to candidates only.</p></div>';
        }
        if ($candidate_id > 0) {
            $linked_user_id = (int) $this->get_candidate_user_id($candidate_id);
            if ($linked_user_id > 0 && $linked_user_id !== $candidate_user_id) {
                return '<div class="cmn-dashboard-card"><h3>Access restricted</h3><p>Rewards data is only available for your own candidate account.</p></div>';
            }
        }

        $payload_result = $this->get_candidate_rewards_overview_payload($candidate_user_id);
        $payload = [];
        $payload_error = '';
        if (is_wp_error($payload_result)) {
            $payload_error = $payload_result->get_error_message();
        } else {
            $payload = (array) $payload_result;
        }

        $state = (array) ($payload['state'] ?? []);
        $bonus = (array) ($payload['bonus'] ?? []);
        $conduct = (array) ($payload['conduct'] ?? []);
        $awards = is_array($bonus['awards'] ?? null) ? (array) $bonus['awards'] : [];
        $appeal_options = is_array($conduct['appeal_booking_options'] ?? null) ? (array) $conduct['appeal_booking_options'] : [];
        $recent_conduct = is_array($conduct['recent_events'] ?? null) ? (array) $conduct['recent_events'] : [];

        $tier = $this->normalize_candidate_rewards_tier((string) ($state['tier'] ?? 'standard'));
        $tier_label = sanitize_text_field((string) ($state['tier_label'] ?? $this->get_candidate_rewards_tier_label($tier)));
        $conduct_status = $this->normalize_candidate_rewards_conduct_status((string) ($state['conduct_status'] ?? 'clear'));
        $conduct_label = sanitize_text_field((string) ($state['conduct_label'] ?? $this->get_candidate_rewards_conduct_badge_label($conduct_status)));
        $conduct_chip_class = sanitize_html_class((string) ($state['conduct_chip_class'] ?? $this->get_candidate_rewards_conduct_badge_class($conduct_status)));
        $academic_year_label = sanitize_text_field((string) ($payload['academic_year_label'] ?? ''));
        $shifts_completed = (int) ($state['shifts_completed'] ?? 0);
        $next_tier = sanitize_text_field((string) ($state['next_tier'] ?? 'Top tier achieved'));
        $next_tier_threshold = max(0, (int) ($state['next_tier_threshold'] ?? 0));
        $shifts_to_next_tier = max(0, (int) ($state['shifts_to_next_tier'] ?? 0));
        $last_bonus_amount = round((float) ($bonus['last_bonus_amount'] ?? 0), 2);
        $last_bonus_awarded_at_label = sanitize_text_field((string) ($bonus['last_bonus_awarded_at_label'] ?? 'Not yet awarded'));
        $next_bonus_at = max(30, (int) ($bonus['next_bonus_at'] ?? 30));
        $shifts_to_next_bonus = max(0, (int) ($bonus['shifts_to_next_bonus'] ?? 30));
        $elite_plus_active = !empty($bonus['elite_plus_active']);
        $support_url = add_query_arg(['candidate' => 'support'], $portal_url);
        $thresholds = (array) ($payload['thresholds'] ?? []);
        $threshold_bronze = max(1, (int) ($thresholds['bronze'] ?? 30));
        $threshold_silver = max($threshold_bronze, (int) ($thresholds['silver'] ?? 60));
        $threshold_gold = max($threshold_silver, (int) ($thresholds['gold'] ?? 90));
        $threshold_elite = max($threshold_gold, (int) ($thresholds['elite'] ?? 120));
        $multipliers = (array) ($payload['multipliers'] ?? []);
        $multiplier_standard = round((float) ($multipliers['standard'] ?? 1.00), 2);
        $multiplier_bronze = round((float) ($multipliers['bronze'] ?? 1.10), 2);
        $multiplier_silver = round((float) ($multipliers['silver'] ?? 1.20), 2);
        $multiplier_gold = round((float) ($multipliers['gold'] ?? 1.30), 2);
        $multiplier_elite = round((float) ($multipliers['elite'] ?? 1.50), 2);
        $estimated_average_day_pay = round((float) ($bonus['estimated_average_day_pay'] ?? 160), 2);
        if ($estimated_average_day_pay <= 0) {
            $estimated_average_day_pay = 160.00;
        }
        $estimated_next_bonus = round((float) ($bonus['estimated_next_bonus'] ?? 0), 2);
        $next_multiplier = round((float) ($bonus['next_multiplier'] ?? 1.00), 2);
        if ($estimated_next_bonus <= 0) {
            $estimated_next_bonus = round($estimated_average_day_pay * max(0.0, $next_multiplier), 2);
