        $rating_payload = (array) ($payload['rating'] ?? []);
        $rating_breakdown = is_array($rating_payload['breakdown'] ?? null)
            ? (array) $rating_payload['breakdown']
            : $this->get_candidate_feedback_breakdown_for_candidate_user($candidate_user_id);
