    }

    private function get_candidate_profile_photo_state($candidate_id, $candidate_user_id = 0) {
        $candidate_id = (int) $candidate_id;
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id < 1 && $candidate_id > 0) {
            $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        }

        $attachment_id = 0;
        if ($candidate_user_id > 0) {
            $attachment_id = (int) get_user_meta($candidate_user_id, 'cmn_profile_photo_attachment_id', true);
        }
        if ($attachment_id < 1 && $candidate_id > 0) {
            $attachment_id = (int) get_post_meta($candidate_id, 'cmn_profile_photo_attachment_id', true);
        }
        if ($attachment_id > 0) {
            $url = wp_get_attachment_image_url($attachment_id, 'medium');
            if (!is_string($url) || $url === '') {
                $url = wp_get_attachment_url($attachment_id);
            }
            if (is_string($url) && $url !== '') {
                return [
                    'url' => $url,
                    'has_photo' => true,
                    'attachment_id' => $attachment_id,
                ];
            }
        }

        $meta_keys = ['cmn_profile_photo', 'cmn_photo_url', 'cmn_avatar_url', 'profile_photo_url'];
        if ($candidate_user_id > 0) {
            foreach ($meta_keys as $meta_key) {
                $url = esc_url_raw((string) get_user_meta($candidate_user_id, $meta_key, true));
                if ($url !== '') {
                    return [
                        'url' => $url,
                        'has_photo' => true,
                        'attachment_id' => 0,
                    ];
                }
            }
        }
        if ($candidate_id > 0) {
            foreach ($meta_keys as $meta_key) {
                $url = esc_url_raw((string) get_post_meta($candidate_id, $meta_key, true));
                if ($url !== '') {
                    return [
                        'url' => $url,
                        'has_photo' => true,
                        'attachment_id' => 0,
                    ];
                }
            }
            $thumb_id = (int) get_post_thumbnail_id($candidate_id);
            if ($thumb_id > 0) {
                $url = wp_get_attachment_image_url($thumb_id, 'medium');
                if (is_string($url) && $url !== '') {
                    return [
                        'url' => $url,
                        'has_photo' => true,
                        'attachment_id' => $thumb_id,
                    ];
                }
            }
        }

        return [
            'url' => $this->get_default_profile_photo_url(),
            'has_photo' => false,
            'attachment_id' => 0,
        ];
    }

    private function get_school_live_match_photo_url($candidate_id) {
        $photo_state = $this->get_candidate_profile_photo_state((int) $candidate_id);
        return (string) ($photo_state['url'] ?? $this->get_default_profile_photo_url());
    }

    private function get_candidate_identity_key($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return '';
        }
        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id > 0) {
            return 'u:' . (string) $candidate_user_id;
        }
        $candidate_email = strtolower(trim((string) get_post_meta($candidate_id, 'cmn_email', true)));
        if ($candidate_email !== '' && is_email($candidate_email)) {
            return 'e:' . $candidate_email;
        }
        return 'p:' . (string) $candidate_id;
    }

    private function normalize_candidate_skill_values($raw_value) {
        $flattened = [];
        $walk = static function ($value) use (&$walk, &$flattened) {
            if (is_array($value)) {
                foreach ($value as $nested_value) {
                    $walk($nested_value);
                }
                return;
            }
            if (!is_scalar($value)) {
                return;
            }
            $text = trim((string) $value);
            if ($text === '') {
                return;
            }
            $decoded = json_decode($text, true);
            if (is_array($decoded)) {
                $walk($decoded);
                return;
            }
            $parts = preg_split('/[\r\n,;|]+/', $text);
            if (!is_array($parts)) {
                $parts = [$text];
            }
            foreach ($parts as $part) {
                $clean = sanitize_text_field((string) $part);
                if ($clean !== '') {
                    $flattened[] = $clean;
                }
            }
        };
        $walk($raw_value);
        return array_values(array_unique(array_filter($flattened, static function ($item) {
            return trim((string) $item) !== '';
        })));
    }

    private function get_candidate_live_match_skills($candidate_id, $limit = 3) {
        $candidate_id = (int) $candidate_id;
        $limit = max(1, min(6, (int) $limit));
        $fallback_skills = ['Classroom Management', 'Communication', 'First Aid'];
        if ($candidate_id < 1) {
            return array_slice($fallback_skills, 0, $limit);
        }

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        $skill_meta_keys = [
            'cmn_contact_card_skills',
            'contact_card_skills',
            'cmn_skills',
            'skills',
            'cmn_core_skills',
            'cmn_strengths',
        ];
        $skills = [];
        if ($candidate_user_id > 0) {
            foreach ($skill_meta_keys as $meta_key) {
                $meta_values = $this->normalize_candidate_skill_values(get_user_meta($candidate_user_id, $meta_key, true));
                foreach ($meta_values as $meta_value) {
                    if (!in_array($meta_value, $skills, true)) {
                        $skills[] = $meta_value;
                    }
                    if (count($skills) >= $limit) {
                        break 2;
                    }
                }
            }
        }
        if (count($skills) < $limit) {
            foreach ($skill_meta_keys as $meta_key) {
                $meta_values = $this->normalize_candidate_skill_values(get_post_meta($candidate_id, $meta_key, true));
                foreach ($meta_values as $meta_value) {
                    if (!in_array($meta_value, $skills, true)) {
                        $skills[] = $meta_value;
                    }
                    if (count($skills) >= $limit) {
                        break 2;
                    }
                }
            }
        }
        if (count($skills) > $limit) {
            $skills = array_slice($skills, 0, $limit);
        }
        foreach ($fallback_skills as $fallback_skill) {
            if (count($skills) >= $limit) {
                break;
            }
            if (!in_array($fallback_skill, $skills, true)) {
                $skills[] = $fallback_skill;
            }
        }
        return $skills;
    }

    private function resolve_candidate_profile_post_id($candidate_id, $candidate_user_id = 0) {
        $candidate_id = (int) $candidate_id;
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_id < 1 && $candidate_user_id < 1) {
            return 0;
        }
        if ($candidate_user_id < 1 && $candidate_id > 0) {
            $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        }
        if ($candidate_user_id < 1) {
            return max(0, $candidate_id);
        }
        static $candidate_profile_cache = [];
        if (isset($candidate_profile_cache[$candidate_user_id])) {
            $cached_id = (int) $candidate_profile_cache[$candidate_user_id];
            return $cached_id > 0 ? $cached_id : max(0, $candidate_id);
        }
        $latest_candidate_ids = get_posts([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish', 'private', 'draft', 'pending'],
            'posts_per_page' => 1,
            'fields' => 'ids',
            'orderby' => 'modified',
            'order' => 'DESC',
            'meta_query' => [
                [
                    'key' => 'cmn_user_id',
                    'value' => $candidate_user_id,
                    'compare' => '=',
                    'type' => 'NUMERIC',
                ],
            ],
        ]);
        $resolved_id = !empty($latest_candidate_ids[0]) ? (int) $latest_candidate_ids[0] : 0;
        if ($resolved_id < 1) {
            $resolved_id = max(0, $candidate_id);
        }
        $candidate_profile_cache[$candidate_user_id] = $resolved_id;
        return $resolved_id;
    }

    private function get_candidate_town_city_label($candidate_id, $candidate_user_id = 0) {
        $candidate_id = (int) $candidate_id;
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_id < 1 && $candidate_user_id < 1) {
            return '';
        }
        if ($candidate_user_id < 1 && $candidate_id > 0) {
            $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        }

        $values = [];
        $append_value = static function (&$target_values, $raw_value) use (&$append_value) {
            if (is_array($raw_value)) {
                foreach ($raw_value as $nested_value) {
                    $append_value($target_values, $nested_value);
                }
                return;
            }
            if (is_object($raw_value)) {
                return;
            }
            $value = sanitize_text_field((string) $raw_value);
            if ($value === '' || in_array($value, $target_values, true)) {
                return;
            }
            $target_values[] = $value;
        };

        if ($candidate_user_id > 0) {
            $user_keys = ['cmn_town', 'town', 'cmn_city', 'city', 'cmn_location', 'location', 'cmn_address_line2'];
            foreach ($user_keys as $meta_key) {
                $meta_values = get_user_meta($candidate_user_id, $meta_key, false);
                foreach ((array) $meta_values as $meta_value) {
                    $append_value($values, $meta_value);
                }
            }
        }

        if ($candidate_id > 0) {
            $post_keys = ['cmn_town', 'town', 'cmn_city', 'city', 'cmn_location', 'location', 'cmn_address_line2'];
            foreach ($post_keys as $meta_key) {
                $meta_values = get_post_meta($candidate_id, $meta_key, false);
                foreach ((array) $meta_values as $meta_value) {
                    $append_value($values, $meta_value);
                }
            }
        }

        foreach ($values as $value) {
            if ($value === '') {
                continue;
            }
            if ($this->normalize_uk_postcode_for_lookup($value) !== '' && preg_match('/^[A-Z0-9 ]+$/i', $value) === 1) {
                continue;
            }
            return $value;
        }
        return '';
    }

    private function is_candidate_hidden_for_school_live_matches($school_id, $candidate_id) {
        $school_id = (int) $school_id;
        $candidate_id = (int) $candidate_id;
        if ($school_id < 1 || $candidate_id < 1) {
            return false;
        }
        $until = (string) get_post_meta($candidate_id, 'cmn_school_hidden_until_' . $school_id, true);
        if ($until === '') {
            return false;
        }
        $until_ts = strtotime($until);
        return $until_ts && $until_ts > current_time('timestamp');
    }

    private function get_school_not_interested_candidates($school_id, $limit = 30) {
        $school_id = (int) $school_id;
        $limit = max(1, (int) $limit);
        if ($school_id < 1) {
            return [];
        }
        $ids = get_posts([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish', 'private', 'draft'],
            'posts_per_page' => -1,
            'fields' => 'ids',
        ]);
        $rows = [];
        foreach ((array) $ids as $candidate_id_raw) {
            $candidate_id = (int) $candidate_id_raw;
            if ($candidate_id < 1 || !$this->is_candidate_hidden_for_school_live_matches($school_id, $candidate_id)) {
                continue;
            }
            $until_raw = (string) get_post_meta($candidate_id, 'cmn_school_hidden_until_' . $school_id, true);
            $until_ts = $until_raw !== '' ? strtotime($until_raw) : 0;
            $rows[] = [
                'candidate_id' => $candidate_id,
                'name' => (string) get_the_title($candidate_id),
                'until_ts' => $until_ts,
                'until_label' => $until_ts ? date_i18n('j M Y g:i A', $until_ts) : '',
            ];
        }
        usort($rows, static function($a, $b){
            $a_ts = (int) ($a['until_ts'] ?? 0);
            $b_ts = (int) ($b['until_ts'] ?? 0);
            if ($a_ts === $b_ts) {
                return strcmp((string) ($a['name'] ?? ''), (string) ($b['name'] ?? ''));
            }
            return $a_ts <=> $b_ts;
        });
        if (count($rows) > $limit) {
            $rows = array_slice($rows, 0, $limit);
        }
        return $rows;
    }

    private function render_school_live_matches_panel($school_id, $availability_candidates, $can_request, $school_ready_responses, $availability_label) {
        $school_id = (int) $school_id;
        $today = current_time('Y-m-d');
        $tomorrow = $this->get_tomorrow_date();
        $visibility_reasons = [
            'hidden_not_interested' => 0,
            'marked_unavailable' => 0,
        ];
        $visibility_candidate_ids = get_posts([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish', 'private', 'draft'],
            'posts_per_page' => -1,
            'fields' => 'ids',
        ]);
        $visibility_seen_identity = [];
        foreach ((array) $visibility_candidate_ids as $visibility_candidate_id_raw) {
            $visibility_candidate_id = (int) $visibility_candidate_id_raw;
            if ($visibility_candidate_id < 1) {
                continue;
            }
            $visibility_identity_key = $this->get_candidate_identity_key($visibility_candidate_id);
            if ($visibility_identity_key !== '' && isset($visibility_seen_identity[$visibility_identity_key])) {
                continue;
            }
            if ($visibility_identity_key !== '') {
                $visibility_seen_identity[$visibility_identity_key] = true;
            }
            if ($this->is_candidate_hidden_for_school_live_matches($school_id, $visibility_candidate_id)) {
                $visibility_reasons['hidden_not_interested']++;
                continue;
            }
            if ($this->is_candidate_unavailable($visibility_candidate_id, $today) && $this->is_candidate_unavailable($visibility_candidate_id, $tomorrow)) {
                $visibility_reasons['marked_unavailable']++;
                continue;
            }
        }
        $candidates = $this->get_school_dashboard_available_candidates($school_id, 40);
        if (!$candidates) {
            $fallback_posts = get_posts([
                'post_type' => 'cmn_candidate',
                'post_status' => ['publish', 'private'],
                'posts_per_page' => 40,
                'orderby' => 'date',
                'order' => 'DESC',
            ]);
            $fallback_seen_identity = [];
            foreach ((array) $fallback_posts as $fallback_post) {
                if (!($fallback_post instanceof WP_Post)) {
                    continue;
                }
                $candidate_id = (int) $fallback_post->ID;
                if ($candidate_id < 1) {
                    continue;
                }
                $fallback_identity_key = $this->get_candidate_identity_key($candidate_id);
                if ($fallback_identity_key !== '' && isset($fallback_seen_identity[$fallback_identity_key])) {
                    continue;
                }
                $candidate_status = sanitize_key((string) get_post_meta($candidate_id, 'cmn_status', true));
                if ($candidate_status === 'rejected') {
                    continue;
                }
                if ($this->is_candidate_unavailable($candidate_id, $today) && $this->is_candidate_unavailable($candidate_id, $tomorrow)) {
                    continue;
                }
                $target_date = !$this->is_candidate_unavailable($candidate_id, $today) ? $today : $tomorrow;
                $candidates[] = [
                    'post' => $fallback_post,
                    'created_at' => current_time('mysql'),
                    'availability_label' => 'Not Responded',
                    'availability_date' => $target_date,
                    'is_confirmed' => false,
                ];
                if ($fallback_identity_key !== '') {
                    $fallback_seen_identity[$fallback_identity_key] = true;
                }
            }
        }
        if (!$candidates) {
            $availability_empty_reason = 'No matching candidates are currently eligible.';
            $empty_reason_parts = [];
            if ($visibility_reasons['marked_unavailable'] > 0) {
                $empty_reason_parts[] = (string) ((int) $visibility_reasons['marked_unavailable']) . ' marked not available';
            }
            if ($visibility_reasons['hidden_not_interested'] > 0) {
                $empty_reason_parts[] = (string) ((int) $visibility_reasons['hidden_not_interested']) . ' hidden from Not Interested';
            }
            if ($empty_reason_parts) {
                $availability_empty_reason .= ' Current exclusions: ' . implode(' | ', $empty_reason_parts) . '.';
            }
            return $this->render_empty_explain_panel('No live matches yet', $availability_empty_reason, 'Open support', add_query_arg(['school' => 'support'], $this->get_portal_base_url()));
        }
        $all = [];
        $available_now_count = 0;
        $not_responded_count = 0;
        $shortlisted_count = 0;
        $target_date = current_time('Y-m-d');
        $school_live_coords = $school_id > 0 ? $this->ensure_school_geo_coordinates($school_id) : null;
        $distance_debug_school_user_id = 0;
        if ($school_id > 0) {
            $distance_debug_school_user_ids = $this->get_school_user_ids_for_school_request($school_id);
            if (!empty($distance_debug_school_user_ids[0])) {
                $distance_debug_school_user_id = (int) $distance_debug_school_user_ids[0];
            }
        }
        if ($distance_debug_school_user_id < 1) {
            $distance_debug_school_user_id = (int) get_current_user_id();
        }
        $distance_debug_school_postcode = $school_id > 0
            ? $this->get_geo_lookup_postcode_for_post($school_id, $distance_debug_school_user_id)
            : '';
        $distance_debug_school_exact_postcodes = $school_id > 0
            ? $this->get_geo_exact_postcodes_for_post($school_id, $distance_debug_school_user_id)
            : [];
        $distance_debug_school_exact_postcode = $this->normalize_uk_postcode_for_lookup($distance_debug_school_postcode);
        $candidate_geo_lookup_budget = 40;
        $rendered_identity_keys = [];
        foreach ($candidates as $item) {
            $candidate = $item['post'] ?? null;
            if (!$candidate || empty($candidate->ID)) {
                continue;
            }
            $candidate_id = (int) $candidate->ID;
            $render_identity_key = $this->get_candidate_identity_key($candidate_id);
            if ($render_identity_key !== '' && isset($rendered_identity_keys[$render_identity_key])) {
                continue;
            }
            if ($this->is_candidate_hidden_for_school_live_matches($school_id, $candidate_id)) {
                continue;
            }
            $role_labels = $this->get_candidate_role_labels($candidate_id);
            $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
            $candidate_profile_id = $this->resolve_candidate_profile_post_id($candidate_id, $candidate_user_id);
            if ($candidate_profile_id < 1) {
                $candidate_profile_id = $candidate_id;
            }
            if ($candidate_profile_id !== $candidate_id) {
                $role_labels = $this->get_candidate_role_labels($candidate_profile_id);
            }
            $role_primary = isset($role_labels[0]) ? (string) $role_labels[0] : 'Candidate';
            $role_secondary = isset($role_labels[1]) ? (string) $role_labels[1] : '';
            $candidate_town_city = $this->get_candidate_town_city_label($candidate_profile_id, $candidate_user_id);
            $distance_debug_candidate_postcode = $this->get_geo_lookup_postcode_for_post($candidate_profile_id, $candidate_user_id);
            $distance_debug_candidate_exact_postcodes = $this->get_geo_exact_postcodes_for_post($candidate_profile_id, $candidate_user_id);
            $distance_debug_candidate_exact_postcode = $this->normalize_uk_postcode_for_lookup($distance_debug_candidate_postcode);
            $rating = $this->get_candidate_average_rating_payload($candidate_user_id);
            $name_parts = preg_split('/\s+/', trim((string) $candidate->post_title));
            $first_name = $name_parts ? (string) $name_parts[0] : (string) $candidate->post_title;
            $is_confirmed = !empty($item['is_confirmed']);
            $status_key = $is_confirmed ? 'available' : 'not_responded';
            $candidate_presence_snapshot = $candidate_user_id > 0
                ? $this->get_candidate_presence_snapshot($candidate_user_id)
                : ['is_online' => false, 'last_online_label' => 'Last seen at --:--'];
            $is_physically_online = !empty($candidate_presence_snapshot['is_online']);
            $presence_label = sanitize_text_field((string) ($candidate_presence_snapshot['last_online_label'] ?? 'Last seen at --:--'));
            if ($status_key === 'available') {
                $available_now_count++;
            } else {
                $not_responded_count++;
            }
            $shortlisted_ids = (array) get_post_meta($school_id, 'cmn_shortlisted_candidate_ids', true);
            $is_shortlisted = in_array($candidate_id, array_map('intval', $shortlisted_ids), true);
            if ($is_shortlisted) {
                $shortlisted_count++;
            }
            $rate_entry = $this->get_candidate_role_rate_entry($candidate_id, $role_primary);
            $day_rate = isset($rate_entry['school_charge_rate']) ? (float) $rate_entry['school_charge_rate'] : 0;
            if ($day_rate <= 0) {
                $day_rate = 160.0;
            }
            $distance_label = 'Distance pending';
            $exact_postcode_overlap = array_values(array_intersect(
                (array) $distance_debug_school_exact_postcodes,
                (array) $distance_debug_candidate_exact_postcodes
            ));
            $has_exact_postcode_match = !empty($exact_postcode_overlap);
            if (
                !$has_exact_postcode_match
                &&
                $distance_debug_school_exact_postcode !== ''
                && $distance_debug_candidate_exact_postcode !== ''
                && $distance_debug_school_exact_postcode === $distance_debug_candidate_exact_postcode
            ) {
                $has_exact_postcode_match = true;
            }
            if ($has_exact_postcode_match) {
                $distance_label = '0 miles';
            } elseif ($school_live_coords && isset($school_live_coords['lat'], $school_live_coords['lng'])) {
                $candidate_coords = null;
                if ($candidate_geo_lookup_budget > 0) {
                    $candidate_geo_lookup_budget--;
                    $candidate_coords = $this->ensure_candidate_geo_coordinates($candidate_profile_id);
                }
                if (!$candidate_coords || !isset($candidate_coords['lat'], $candidate_coords['lng'])) {
                    $candidate_coords = $this->get_geo_coordinates_for_post($candidate_profile_id);
                }
                if ($candidate_coords && isset($candidate_coords['lat'], $candidate_coords['lng'])) {
                    $distance_miles = (float) $this->marketing_haversine_miles(
                        (float) $candidate_coords['lat'],
                        (float) $candidate_coords['lng'],
                        (float) $school_live_coords['lat'],
                        (float) $school_live_coords['lng']
                    );
                    if ($distance_miles >= 0) {
                        $distance_label = rtrim(rtrim(number_format(max(0.0, $distance_miles), 1, '.', ''), '0'), '.') . ' miles';
                    }
                }
            }
            if ($distance_label === 'Distance pending') {
                $fallback_travel_radius = (float) $this->get_candidate_travel_radius_miles($candidate_profile_id);
                if ($fallback_travel_radius > 0) {
                    $distance_label = 'Up to ' . rtrim(rtrim(number_format($fallback_travel_radius, 1, '.', ''), '0'), '.') . ' miles';
                }
            }
            $distance_debug_key = 'cmn_distance_debug_' . md5(
                (string) $school_id
                . '|'
                . (string) $candidate_id
                . '|'
                . (string) $candidate_profile_id
                . '|'
                . (string) $distance_label
                . '|'
                . (string) $distance_debug_school_postcode
                . '|'
                . (string) $distance_debug_candidate_postcode
            );
            if (get_transient($distance_debug_key) === false) {
                set_transient($distance_debug_key, 1, HOUR_IN_SECONDS);
                error_log('[CMN_DISTANCE_DEBUG] ' . wp_json_encode([
                    'school_id' => (int) $school_id,
                    'candidate_id' => (int) $candidate_id,
                    'candidate_profile_id' => (int) $candidate_profile_id,
                    'distance' => (string) $distance_label,
                    'school_postcode' => (string) $distance_debug_school_postcode,
                    'school_exact_postcodes' => array_values((array) $distance_debug_school_exact_postcodes),
                    'candidate_postcode' => (string) $distance_debug_candidate_postcode,
                    'candidate_exact_postcodes' => array_values((array) $distance_debug_candidate_exact_postcodes),
                    'school_coords' => is_array($school_live_coords) ? $school_live_coords : null,
                    'candidate_coords' => isset($candidate_coords) && is_array($candidate_coords) ? $candidate_coords : null,
                ]));
            }
            $all[] = [
                'candidate_id' => $candidate_id,
                'first_name' => $first_name,
                'photo_url' => $this->get_school_live_match_photo_url($candidate_profile_id),
                'profile_url' => $this->get_school_candidate_profile_url($candidate_id, get_current_user_id()),
                'role_line' => trim($role_primary . ($role_secondary !== '' ? ' • ' . $role_secondary : '')),
                'rating' => round((float) ($rating['avg_rating'] ?? 0), 1),
                'rating_label' => number_format((float) ($rating['avg_rating'] ?? 0), 2) . ' out of 5 stars',
                'reviews' => (int) ($rating['feedback_count'] ?? 0),
                'status' => $status_key,
                'status_label' => $status_key === 'available' ? 'AVAILABLE NOW' : 'NOT RESPONDED',
                'distance' => $distance_label,
                'town_city' => $candidate_town_city,
                'availability_label' => (string) ($item['availability_label'] ?? 'Available This Morning'),
                'confirmed_at' => $status_key === 'available' ? date_i18n('g:i A', strtotime((string) ($item['created_at'] ?? current_time('mysql')))) : '',
                'day_rate' => round($day_rate, 0),
                'skills' => $this->get_candidate_live_match_skills($candidate_profile_id, 3),
                'is_shortlisted' => $is_shortlisted ? 1 : 0,
                'is_physically_online' => $is_physically_online ? 1 : 0,
                'presence_label' => $presence_label,
                'target_date' => (string) ($item['availability_date'] ?? $target_date),
            ];
            if ($render_identity_key !== '') {
                $rendered_identity_keys[$render_identity_key] = true;
            }
        }
        usort($all, static function($a, $b){
            $a_online = !empty($a['is_physically_online']) ? 1 : 0;
            $b_online = !empty($b['is_physically_online']) ? 1 : 0;
            if ($a_online !== $b_online) {
                return ($a_online > $b_online) ? -1 : 1;
            }
            if (($a['status'] ?? '') !== ($b['status'] ?? '')) {
                return (($a['status'] ?? '') === 'available') ? -1 : 1;
            }
            $a_rating = (float) ($a['rating'] ?? 0);
            $b_rating = (float) ($b['rating'] ?? 0);
            if ($a_rating !== $b_rating) {
                return ($a_rating > $b_rating) ? -1 : 1;
            }
            $a_reviews = (int) ($a['reviews'] ?? 0);
            $b_reviews = (int) ($b['reviews'] ?? 0);
            if ($a_reviews !== $b_reviews) {
                return ($a_reviews > $b_reviews) ? -1 : 1;
            }
            return strcmp((string) ($a['first_name'] ?? ''), (string) ($b['first_name'] ?? ''));
        });
        $payload = [
            'all' => $all,
            'counts' => [
                'all' => count($all),
                'available' => $available_now_count,
                'not_responded' => $not_responded_count,
