    private function get_school_dashboard_available_candidates($school_id = 0, $limit = 24) {
        $today = function_exists('cmn_today_ymd') ? cmn_today_ymd() : current_time('Y-m-d');
        if (function_exists('cmn_now')) {
            $tomorrow = cmn_now()->setTimezone(wp_timezone())->modify('+1 day')->format('Y-m-d');
        } else {
            $tomorrow = $this->get_tomorrow_date();
        }

        $today_rows = $today ? $this->get_available_candidates_with_times($today, $school_id, $limit) : [];
        $tomorrow_rows = $tomorrow ? $this->get_available_candidates_with_times($tomorrow, $school_id, $limit) : [];

        $out = [];
        $seen = [];
        $seen_identity = [];

        foreach ($today_rows as $item) {
            $post = $item['post'] ?? null;
            $candidate_id = ($post && isset($post->ID)) ? (int) $post->ID : 0;
            $candidate_identity_key = $this->get_candidate_identity_key($candidate_id);
            if (
                $candidate_id < 1
                || isset($seen[$candidate_id])
                || ($candidate_identity_key !== '' && isset($seen_identity[$candidate_identity_key]))
                || $this->is_candidate_unavailable($candidate_id, $today)
            ) {
                continue;
            }
            $item['availability_label'] = 'Available This Morning';
            $item['availability_date'] = $today;
            $item['is_confirmed'] = true;
            $out[] = $item;
            $seen[$candidate_id] = true;
            if ($candidate_identity_key !== '') {
                $seen_identity[$candidate_identity_key] = true;
            }
            if ($limit > 0 && count($out) >= $limit) {
                return $out;
            }
        }

        foreach ($tomorrow_rows as $item) {
            $post = $item['post'] ?? null;
            $candidate_id = ($post && isset($post->ID)) ? (int) $post->ID : 0;
            $candidate_identity_key = $this->get_candidate_identity_key($candidate_id);
            if (
                $candidate_id < 1
                || isset($seen[$candidate_id])
                || ($candidate_identity_key !== '' && isset($seen_identity[$candidate_identity_key]))
                || $this->is_candidate_unavailable($candidate_id, $tomorrow)
            ) {
                continue;
            }
            $item['availability_label'] = 'Available Tomorrow Morning';
            $item['availability_date'] = $tomorrow;
            $item['is_confirmed'] = true;
            $out[] = $item;
            $seen[$candidate_id] = true;
            if ($candidate_identity_key !== '') {
                $seen_identity[$candidate_identity_key] = true;
            }
            if ($limit > 0 && count($out) >= $limit) {
                break;
            }
        }

        $base_candidate_ids = get_posts([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish', 'private', 'draft'],
            'posts_per_page' => -1,
            'fields' => 'ids',
        ]);
        foreach ((array) $base_candidate_ids as $candidate_id_raw) {
            $candidate_id = (int) $candidate_id_raw;
            $candidate_identity_key = $this->get_candidate_identity_key($candidate_id);
            if ($candidate_id < 1 || isset($seen[$candidate_id])) {
                continue;
            }
            if ($candidate_identity_key !== '' && isset($seen_identity[$candidate_identity_key])) {
                continue;
            }
            $candidate_status = sanitize_key((string) get_post_meta($candidate_id, 'cmn_status', true));
            if ($candidate_status === 'rejected') {
                continue;
            }
            if ($this->is_candidate_unavailable($candidate_id, $today) && $this->is_candidate_unavailable($candidate_id, $tomorrow)) {
                continue;
            }
            $candidate_post = get_post($candidate_id);
            if (!$candidate_post) {
                continue;
            }
            $target_date = !$this->is_candidate_unavailable($candidate_id, $today) ? $today : $tomorrow;
            $out[] = [
                'post' => $candidate_post,
                'created_at' => current_time('mysql'),
                'availability_label' => 'Not Responded',
                'availability_date' => $target_date,
                'is_confirmed' => false,
            ];
            $seen[$candidate_id] = true;
            if ($candidate_identity_key !== '') {
                $seen_identity[$candidate_identity_key] = true;
            }
            if ($limit > 0 && count($out) >= $limit) {
                break;
            }
        }

        return $out;
    }

    private function get_available_candidates_with_times($date, $school_id = 0, $limit = 6) {
        $rows = $this->get_available_candidate_rows($date, 0, $limit);
        if (!$rows) {
            return [];
        }
        $ids = array_map('intval', array_column($rows, 'candidate_id'));
        if (!$ids) {
            return [];
        }
        $posts = get_posts([
            'post_type' => 'cmn_candidate',
            'posts_per_page' => count($ids),
            'post__in' => $ids,
            'orderby' => 'post__in',
        ]);
        $indexed = [];
        foreach ($posts as $post) {
            $indexed[$post->ID] = $post;
        }
        $output = [];
        foreach ($rows as $row) {
            $candidate_id = (int) $row['candidate_id'];
            if (!isset($indexed[$candidate_id])) {
                continue;
            }
            $output[] = [
                'post' => $indexed[$candidate_id],
                'created_at' => $row['created_at'],
            ];
        }
        return $output;
    }


    private function get_geo_coordinates_for_post($post_id) {
        $post_id = (int) $post_id;
        if ($post_id < 1) {
            return null;
        }
        $lat_keys = ['cmn_lat', 'cmn_latitude', 'cmn_location_lat', 'cmn_geo_lat'];
        $lng_keys = ['cmn_lng', 'cmn_long', 'cmn_longitude', 'cmn_location_lng', 'cmn_geo_lng'];
        $lat = null;
        $lng = null;
        foreach ($lat_keys as $key) {
            $parsed = $this->parse_marketing_coordinate_value(get_post_meta($post_id, $key, true));
            if ($parsed !== null) {
                $lat = $parsed;
                break;
            }
        }
        foreach ($lng_keys as $key) {
            $parsed = $this->parse_marketing_coordinate_value(get_post_meta($post_id, $key, true));
            if ($parsed !== null) {
                $lng = $parsed;
                break;
            }
        }
        if ($lat !== null && $lng !== null) {
            if ($lat < -90 || $lat > 90 || $lng < -180 || $lng > 180) {
                return null;
            }
            return ['lat' => (float) $lat, 'lng' => (float) $lng];
        }

        $fallback_user_ids = [];
        $post_type = (string) get_post_type($post_id);
        if ($post_type === 'cmn_candidate') {
            $candidate_user_id = (int) $this->get_candidate_user_id($post_id);
            if ($candidate_user_id > 0) {
                $fallback_user_ids[] = $candidate_user_id;
            }
        } elseif ($post_type === 'cmn_school') {
            $school_user_ids = $this->get_school_user_ids_for_school_request($post_id);
            foreach ((array) $school_user_ids as $school_user_id) {
                $school_user_id = (int) $school_user_id;
                if ($school_user_id > 0) {
                    $fallback_user_ids[] = $school_user_id;
                }
            }
            $current_user_id = (int) get_current_user_id();
            if ($current_user_id > 0 && (int) $this->resolve_school_id_for_user($current_user_id) === $post_id) {
                $fallback_user_ids[] = $current_user_id;
            }
        }

        foreach (array_values(array_unique(array_map('intval', (array) $fallback_user_ids))) as $user_id) {
            if ($user_id < 1) {
                continue;
            }
            $coords = $this->get_geo_coordinates_for_user($user_id);
            if (is_array($coords) && isset($coords['lat'], $coords['lng'])) {
                return $coords;
            }
        }
        return null;
    }

    private function parse_distance_miles($value) {
        $raw = strtolower(trim((string) $value));
        if ($raw === '') {
            return 0.0;
        }
        if (preg_match('/(-?\d+(?:\.\d+)?)/', $raw, $m) !== 1) {
            return 0.0;
        }
        $distance = (float) $m[1];
        if ($distance <= 0) {
            return 0.0;
        }
        if (strpos($raw, 'km') !== false || strpos($raw, 'kilomet') !== false) {
            $distance *= 0.621371;
        }
        return min(200.0, $distance);
    }

    private function get_candidate_travel_radius_miles($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1) {
            return 0.0;
        }
        $candidate_user_id = (int) get_post_meta($candidate_id, 'cmn_user_id', true);
        $travel_radius = $candidate_user_id > 0 ? (string) get_user_meta($candidate_user_id, 'travel_radius', true) : '';
        if ($travel_radius === '') {
            $travel_radius = (string) get_post_meta($candidate_id, 'cmn_travel_distance', true);
        }
        return $this->parse_distance_miles($travel_radius);
    }

    private function candidate_matches_school_for_dashboard($candidate_id, $school_id) {
        $candidate_id = (int) $candidate_id;
        $school_id = (int) $school_id;
        if ($candidate_id < 1 || $school_id < 1) {
            return true;
        }

        $location_match = $this->candidate_matches_school_location_fallback($candidate_id, $school_id);

        $travel_miles = $this->get_candidate_travel_radius_miles($candidate_id);
        $candidate_coords = $this->get_geo_coordinates_for_post($candidate_id);
        $school_coords = $this->ensure_school_geo_coordinates($school_id);
        if ($travel_miles > 0 && $candidate_coords && $school_coords) {
            $distance = $this->marketing_haversine_miles(
                (float) $candidate_coords['lat'],
                (float) $candidate_coords['lng'],
                (float) $school_coords['lat'],
                (float) $school_coords['lng']
            );
            return $distance <= $travel_miles;
        }

        // When coordinate data is incomplete, do not collapse to zero results.
        // Fall back to location/town/postcode matching until geocoding is available.
        return $location_match;
    }

    private function extract_uk_postcode_outward_code($postcode) {
        return $this->normalize_uk_outward_code_for_lookup($postcode);
    }

    private function normalize_uk_postcode_for_lookup($postcode) {
        $postcode_raw = strtoupper(trim((string) $postcode));
        if ($postcode_raw === '') {
            return '';
        }
        $postcode_compact = preg_replace('/[^A-Z0-9]/', '', $postcode_raw);
        if (preg_match('/^(GIR0AA|[A-Z]{1,2}\d[A-Z\d]?\d[A-Z]{2})$/', $postcode_compact) === 1) {
            return $postcode_compact;
        }
        if (preg_match('/\b(GIR\s*0AA|[A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2})\b/i', $postcode_raw, $matches) !== 1) {
            return '';
        }
        $extracted = strtoupper(preg_replace('/[^A-Z0-9]/', '', (string) ($matches[1] ?? '')));
        if (preg_match('/^(GIR0AA|[A-Z]{1,2}\d[A-Z\d]?\d[A-Z]{2})$/', $extracted) !== 1) {
            return '';
        }
        return $extracted;
    }

    private function normalize_uk_outward_code_for_lookup($postcode) {
        $normalized_postcode = $this->normalize_uk_postcode_for_lookup($postcode);
        if ($normalized_postcode !== '' && preg_match('/^([A-Z]{1,2}\d[A-Z\d]?)/', $normalized_postcode, $matches) === 1) {
            return (string) ($matches[1] ?? '');
        }

        $postcode_raw = strtoupper(trim((string) $postcode));
        if ($postcode_raw === '') {
            return '';
        }

        $postcode_compact = preg_replace('/[^A-Z0-9]/', '', $postcode_raw);
        if (preg_match('/^[A-Z]{1,2}\d[A-Z\d]?$/', $postcode_compact) === 1) {
            return $postcode_compact;
        }

        if (preg_match('/\b([A-Z]{1,2}\d[A-Z\d]?)\b/i', $postcode_raw, $matches) !== 1) {
            return '';
        }
        $extracted = strtoupper(preg_replace('/[^A-Z0-9]/', '', (string) ($matches[1] ?? '')));
        if (preg_match('/^[A-Z]{1,2}\d[A-Z\d]?$/', $extracted) !== 1) {
            return '';
        }
        return $extracted;
    }

    private function get_geo_coordinates_for_user($user_id) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return null;
        }
        $lat_keys = ['cmn_lat', 'cmn_latitude', 'cmn_location_lat', 'cmn_geo_lat', 'lat', 'latitude'];
        $lng_keys = ['cmn_lng', 'cmn_long', 'cmn_longitude', 'cmn_location_lng', 'cmn_geo_lng', 'lng', 'longitude'];
        $lat = null;
        $lng = null;
        foreach ($lat_keys as $key) {
            $parsed = $this->parse_marketing_coordinate_value(get_user_meta($user_id, $key, true));
            if ($parsed !== null) {
                $lat = $parsed;
                break;
            }
        }
        foreach ($lng_keys as $key) {
            $parsed = $this->parse_marketing_coordinate_value(get_user_meta($user_id, $key, true));
            if ($parsed !== null) {
                $lng = $parsed;
                break;
            }
        }
        if ($lat === null || $lng === null) {
            return null;
        }
        if ($lat < -90 || $lat > 90 || $lng < -180 || $lng > 180) {
            return null;
        }
        return [
            'lat' => (float) $lat,
            'lng' => (float) $lng,
        ];
    }

    private function get_geo_lookup_postcode_for_post($post_id, $fallback_user_id = 0) {
        $post_id = (int) $post_id;
        if ($post_id < 1) {
            return '';
        }
        $candidate_values = $this->get_geo_lookup_values_for_post($post_id, $fallback_user_id);

        foreach ($candidate_values as $candidate_value) {
            $normalized = $this->normalize_uk_postcode_for_lookup($candidate_value);
            if ($normalized !== '') {
                return $normalized;
            }
        }
        foreach ($candidate_values as $candidate_value) {
            $normalized_outward = $this->normalize_uk_outward_code_for_lookup($candidate_value);
            if ($normalized_outward !== '') {
                return $normalized_outward;
            }
        }
        return '';
    }

    private function get_geo_exact_postcodes_for_post($post_id, $fallback_user_id = 0) {
        $candidate_values = $this->get_geo_lookup_values_for_post($post_id, $fallback_user_id);
        if (!$candidate_values) {
            return [];
        }
        $exact_postcodes = [];
        foreach ($candidate_values as $candidate_value) {
            $normalized = $this->normalize_uk_postcode_for_lookup($candidate_value);
            if ($normalized !== '' && !in_array($normalized, $exact_postcodes, true)) {
                $exact_postcodes[] = $normalized;
            }
        }
        return $exact_postcodes;
    }

    private function get_geo_lookup_values_for_post($post_id, $fallback_user_id = 0) {
        $post_id = (int) $post_id;
        if ($post_id < 1) {
            return [];
        }

        $candidate_values = [];
        $post_meta_keys = [
            'cmn_postcode',
            'postcode',
            'postal_code',
            'postalcode',
            'post_code',
            'zip',
            'zip_code',
            'billing_postcode',
            'shipping_postcode',
            'cmn_address_line1',
            'cmn_address_line2',
            'cmn_address_line3',
            'cmn_location',
            'cmn_town',
            'cmn_county',
        ];
        foreach ($post_meta_keys as $meta_key) {
            $meta_values = get_post_meta($post_id, $meta_key, false);
            foreach ((array) $meta_values as $meta_value) {
                $this->append_geo_lookup_values($candidate_values, $meta_value);
            }
        }
        $post_meta_all = get_post_meta($post_id);
        if (is_array($post_meta_all)) {
            foreach ($post_meta_all as $meta_key => $meta_values) {
                $meta_key = (string) $meta_key;
                if ($meta_key === '' || in_array($meta_key, $post_meta_keys, true)) {
                    continue;
                }
                if (preg_match('/(postcode|post_code|postal|zip|address|location|town|city|county)/i', $meta_key) !== 1) {
                    continue;
                }
                foreach ((array) $meta_values as $meta_value) {
                    $this->append_geo_lookup_values($candidate_values, $meta_value);
                }
            }
        }

        $fallback_user_id = (int) $fallback_user_id;
        if ($fallback_user_id < 1 && get_post_type($post_id) === 'cmn_candidate') {
            $fallback_user_id = (int) $this->get_candidate_user_id($post_id);
        }
        if ($fallback_user_id > 0) {
            $user_meta_keys = [
                'cmn_postcode',
                'postcode',
                'postal_code',
                'postalcode',
                'post_code',
                'zip',
                'zip_code',
                'billing_postcode',
                'shipping_postcode',
                'address',
                'cmn_location',
            ];
            foreach ($user_meta_keys as $meta_key) {
                $meta_values = get_user_meta($fallback_user_id, $meta_key, false);
                foreach ((array) $meta_values as $meta_value) {
                    $this->append_geo_lookup_values($candidate_values, $meta_value);
                }
            }
            $user_meta_all = get_user_meta($fallback_user_id);
            if (is_array($user_meta_all)) {
                foreach ($user_meta_all as $meta_key => $meta_values) {
                    $meta_key = (string) $meta_key;
                    if ($meta_key === '' || in_array($meta_key, $user_meta_keys, true)) {
                        continue;
                    }
                    if (preg_match('/(postcode|post_code|postal|zip|address|location|town|city|county)/i', $meta_key) !== 1) {
                        continue;
                    }
                    foreach ((array) $meta_values as $meta_value) {
                        $this->append_geo_lookup_values($candidate_values, $meta_value);
                    }
                }
            }
        }

        return $candidate_values;
    }

    private function append_geo_lookup_values(&$candidate_values, $raw_value) {
        if (is_array($raw_value)) {
            foreach ($raw_value as $nested_value) {
                $this->append_geo_lookup_values($candidate_values, $nested_value);
            }
            return;
        }
        if (is_object($raw_value)) {
            return;
        }
        $value = trim((string) $raw_value);
        if ($value === '' || in_array($value, $candidate_values, true)) {
            return;
        }
        $candidate_values[] = $value;
    }

    private function geocode_uk_outward_code_coordinates($outward_code) {
        $normalized_outward_code = $this->normalize_uk_outward_code_for_lookup($outward_code);
        if ($normalized_outward_code === '') {
            return null;
        }
        $cache_key = 'cmn_geo_outcode_' . md5($normalized_outward_code);
        $cached = get_transient($cache_key);
        if (is_array($cached) && isset($cached['lat'], $cached['lng'])) {
            return [
                'lat' => (float) $cached['lat'],
                'lng' => (float) $cached['lng'],
                'source' => 'postcodes_io_outcode_cache',
            ];
        }

        $response = wp_remote_get('https://api.postcodes.io/outcodes/' . rawurlencode($normalized_outward_code), [
            'timeout' => 4,
            'redirection' => 2,
            'user-agent' => 'CoverMeNow ONE',
        ]);
        if (is_wp_error($response)) {
            return null;
        }
        $status_code = (int) wp_remote_retrieve_response_code($response);
        if ($status_code !== 200) {
            return null;
        }
        $body = json_decode((string) wp_remote_retrieve_body($response), true);
        if (!is_array($body) || (int) ($body['status'] ?? 0) !== 200 || !is_array($body['result'] ?? null)) {
            return null;
        }
        $lat = isset($body['result']['latitude']) ? (float) $body['result']['latitude'] : null;
        $lng = isset($body['result']['longitude']) ? (float) $body['result']['longitude'] : null;
        if ($lat === null || $lng === null || $lat < -90 || $lat > 90 || $lng < -180 || $lng > 180) {
            return null;
        }
        set_transient($cache_key, ['lat' => $lat, 'lng' => $lng], DAY_IN_SECONDS * 7);
        return [
            'lat' => $lat,
            'lng' => $lng,
            'source' => 'postcodes_io_outcode',
        ];
    }

    private function geocode_uk_postcode_coordinates($postcode) {
        $normalized_postcode = $this->normalize_uk_postcode_for_lookup($postcode);
        if ($normalized_postcode === '') {
            return $this->geocode_uk_outward_code_coordinates($postcode);
        }
        $cache_key = 'cmn_geo_postcode_' . md5($normalized_postcode);
        $cached = get_transient($cache_key);
        if (is_array($cached) && isset($cached['lat'], $cached['lng'])) {
            return [
                'lat' => (float) $cached['lat'],
                'lng' => (float) $cached['lng'],
                'source' => 'postcodes_io_cache',
            ];
        }

        $response = wp_remote_get('https://api.postcodes.io/postcodes/' . rawurlencode($normalized_postcode), [
            'timeout' => 4,
            'redirection' => 2,
            'user-agent' => 'CoverMeNow ONE',
        ]);
        if (is_wp_error($response)) {
            return $this->geocode_uk_outward_code_coordinates($normalized_postcode);
        }
        $status_code = (int) wp_remote_retrieve_response_code($response);
        if ($status_code !== 200) {
            return $this->geocode_uk_outward_code_coordinates($normalized_postcode);
        }
        $body = json_decode((string) wp_remote_retrieve_body($response), true);
        if (!is_array($body) || (int) ($body['status'] ?? 0) !== 200 || !is_array($body['result'] ?? null)) {
            return $this->geocode_uk_outward_code_coordinates($normalized_postcode);
        }
        $lat = isset($body['result']['latitude']) ? (float) $body['result']['latitude'] : null;
        $lng = isset($body['result']['longitude']) ? (float) $body['result']['longitude'] : null;
        if ($lat === null || $lng === null || $lat < -90 || $lat > 90 || $lng < -180 || $lng > 180) {
            return $this->geocode_uk_outward_code_coordinates($normalized_postcode);
        }
        set_transient($cache_key, ['lat' => $lat, 'lng' => $lng], DAY_IN_SECONDS * 7);
        return [
            'lat' => $lat,
            'lng' => $lng,
            'source' => 'postcodes_io',
        ];
    }

    private function persist_geo_coordinates_for_post($post_id, $lat, $lng, $source = 'manual') {
        $post_id = (int) $post_id;
        if ($post_id < 1) {
            return;
        }
        $lat = (float) $lat;
        $lng = (float) $lng;
        if ($lat < -90 || $lat > 90 || $lng < -180 || $lng > 180) {
            return;
        }
        update_post_meta($post_id, 'cmn_lat', $lat);
        update_post_meta($post_id, 'cmn_lng', $lng);
        update_post_meta($post_id, 'cmn_geo_lat', $lat);
        update_post_meta($post_id, 'cmn_geo_lng', $lng);
        update_post_meta($post_id, 'cmn_geo_source', sanitize_key((string) $source));
        update_post_meta($post_id, 'cmn_geo_updated_at', current_time('mysql'));
    }

    private function ensure_school_geo_coordinates($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return null;
        }
        $existing = $this->get_geo_coordinates_for_post($school_id);

        $fallback_school_user_id = 0;
        $school_user_ids = $this->get_school_user_ids_for_school_request($school_id);
        if (!empty($school_user_ids[0])) {
            $fallback_school_user_id = (int) $school_user_ids[0];
        }
        if ($fallback_school_user_id < 1) {
            $current_user_id = (int) get_current_user_id();
            if ($current_user_id > 0 && (int) $this->resolve_school_id_for_user($current_user_id) === $school_id) {
                $fallback_school_user_id = $current_user_id;
            }
        }
        $normalized_postcode = $this->get_geo_lookup_postcode_for_post($school_id, $fallback_school_user_id);
        if ($normalized_postcode === '') {
            return $existing ?: null;
        }

        $attempted_postcode = strtoupper(trim((string) get_post_meta($school_id, 'cmn_geo_lookup_postcode', true)));
        if ($existing && $attempted_postcode !== '' && $attempted_postcode === $normalized_postcode) {
            return $existing;
        }

        $attempted_at = (string) get_post_meta($school_id, 'cmn_geo_lookup_attempted_at', true);
        if ($attempted_postcode === $normalized_postcode && $attempted_at !== '' && (time() - strtotime($attempted_at)) < MINUTE_IN_SECONDS * 10) {
            return $existing ?: null;
        }

        $geocoded = $this->geocode_uk_postcode_coordinates($normalized_postcode);
        update_post_meta($school_id, 'cmn_geo_lookup_postcode', $normalized_postcode);
        update_post_meta($school_id, 'cmn_geo_lookup_attempted_at', current_time('mysql'));
        if (!is_array($geocoded) || !isset($geocoded['lat'], $geocoded['lng'])) {
            $this->log_school_debug('school_geo_lookup_failed', [
                'school_post_id' => $school_id,
                'postcode' => $normalized_postcode,
            ]);
            return $existing ?: null;
        }

        $lat = (float) $geocoded['lat'];
        $lng = (float) $geocoded['lng'];
        $this->persist_geo_coordinates_for_post($school_id, $lat, $lng, (string) ($geocoded['source'] ?? 'postcodes_io'));
        $this->log_school_debug('school_geo_lookup_success', [
            'school_post_id' => $school_id,
            'postcode' => $normalized_postcode,
            'lat' => $lat,
            'lng' => $lng,
            'source' => (string) ($geocoded['source'] ?? 'postcodes_io'),
        ]);
        return ['lat' => $lat, 'lng' => $lng];
    }

    private function ensure_candidate_geo_coordinates($candidate_id) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return null;
        }
        $existing = $this->get_geo_coordinates_for_post($candidate_id);

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        $normalized_postcode = $this->get_geo_lookup_postcode_for_post($candidate_id, $candidate_user_id);
        if ($normalized_postcode === '') {
            return $existing ?: null;
        }

        $attempted_postcode = strtoupper(trim((string) get_post_meta($candidate_id, 'cmn_geo_lookup_postcode', true)));
        if ($existing && $attempted_postcode !== '' && $attempted_postcode === $normalized_postcode) {
            return $existing;
        }

        $attempted_at = (string) get_post_meta($candidate_id, 'cmn_geo_lookup_attempted_at', true);
        if ($attempted_postcode === $normalized_postcode && $attempted_at !== '' && (time() - strtotime($attempted_at)) < MINUTE_IN_SECONDS * 10) {
            return $existing ?: null;
        }

        $geocoded = $this->geocode_uk_postcode_coordinates($normalized_postcode);
        update_post_meta($candidate_id, 'cmn_geo_lookup_postcode', $normalized_postcode);
        update_post_meta($candidate_id, 'cmn_geo_lookup_attempted_at', current_time('mysql'));
        if (!is_array($geocoded) || !isset($geocoded['lat'], $geocoded['lng'])) {
            $this->log_school_debug('candidate_geo_lookup_failed', [
                'candidate_post_id' => $candidate_id,
                'postcode' => $normalized_postcode,
            ]);
            return $existing ?: null;
        }

        $lat = (float) $geocoded['lat'];
        $lng = (float) $geocoded['lng'];
        $this->persist_geo_coordinates_for_post($candidate_id, $lat, $lng, (string) ($geocoded['source'] ?? 'postcodes_io'));
        $this->log_school_debug('candidate_geo_lookup_success', [
            'candidate_post_id' => $candidate_id,
            'postcode' => $normalized_postcode,
            'lat' => $lat,
            'lng' => $lng,
            'source' => (string) ($geocoded['source'] ?? 'postcodes_io'),
        ]);
        return ['lat' => $lat, 'lng' => $lng];
    }

    private function candidate_matches_school_location_fallback($candidate_id, $school_id) {
        $candidate_id = (int) $candidate_id;
        $school_id = (int) $school_id;
        if ($candidate_id < 1 || $school_id < 1) {
            return true;
        }

        $candidate_location_values = array_filter([
            (string) get_post_meta($candidate_id, 'cmn_location', true),
            (string) get_post_meta($candidate_id, 'cmn_town', true),
            (string) get_post_meta($candidate_id, 'cmn_county', true),
        ], static function ($value) {
            return trim((string) $value) !== '';
        });
        $school_location_values = array_filter([
            (string) get_post_meta($school_id, 'cmn_location', true),
            (string) get_post_meta($school_id, 'cmn_town', true),
            (string) get_post_meta($school_id, 'cmn_county', true),
        ], static function ($value) {
            return trim((string) $value) !== '';
        });

        foreach ($candidate_location_values as $candidate_location_value) {
            foreach ($school_location_values as $school_location_value) {
                if ($this->locations_roughly_match($candidate_location_value, $school_location_value)) {
                    return true;
                }
            }
        }

        $candidate_outward = $this->extract_uk_postcode_outward_code((string) get_post_meta($candidate_id, 'cmn_postcode', true));
        $school_outward = $this->extract_uk_postcode_outward_code((string) get_post_meta($school_id, 'cmn_postcode', true));
        if ($candidate_outward !== '' && $school_outward !== '' && $candidate_outward === $school_outward) {
            return true;
        }

        return false;
    }

    private function evaluate_candidate_distance_for_debug($candidate_id, $school_id, $school_coords = null) {
        $candidate_id = (int) $candidate_id;
        $school_id = (int) $school_id;
        if ($candidate_id < 1 || $school_id < 1) {
            return ['ok' => true, 'reason' => ''];
        }

        $travel_miles = $this->get_candidate_travel_radius_miles($candidate_id);
        $candidate_coords = $this->get_geo_coordinates_for_post($candidate_id);
        $school_coords = $school_coords ?: $this->ensure_school_geo_coordinates($school_id);
        $location_match = $this->candidate_matches_school_location_fallback($candidate_id, $school_id);

        if ($travel_miles > 0 && $candidate_coords && $school_coords) {
            $distance = $this->marketing_haversine_miles(
                (float) $candidate_coords['lat'],
                (float) $candidate_coords['lng'],
                (float) $school_coords['lat'],
                (float) $school_coords['lng']
            );
            if ($distance <= $travel_miles) {
                return ['ok' => true, 'reason' => ''];
            }
            return ['ok' => false, 'reason' => 'outside_radius'];
        }

        if ($travel_miles > 0 && (!$candidate_coords || !$school_coords)) {
            return $location_match ? ['ok' => true, 'reason' => ''] : ['ok' => false, 'reason' => 'no_coords'];
        }

        if ($travel_miles <= 0) {
            return $location_match ? ['ok' => true, 'reason' => ''] : ['ok' => false, 'reason' => 'no_travel_radius'];
        }

        return $location_match ? ['ok' => true, 'reason' => ''] : ['ok' => false, 'reason' => 'location_mismatch'];
    }

    private function collect_school_availability_debug_report($school_id, $availability_candidates = []) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [];
        }

        $timezone = wp_timezone();
        $now = function_exists('cmn_now') ? cmn_now()->setTimezone($timezone) : new DateTimeImmutable('now', $timezone);
        $today = $now->format('Y-m-d');
        $tomorrow = $now->modify('+1 day')->format('Y-m-d');

        $base_candidate_ids = get_posts([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish', 'private', 'draft'],
            'posts_per_page' => -1,
            'fields' => 'ids',
        ]);
        $base_candidate_ids = array_values(array_unique(array_filter(array_map('intval', (array) $base_candidate_ids))));

        $today_rows = $this->get_available_candidate_rows($today, 0, 0);
        $tomorrow_rows = $this->get_available_candidate_rows($tomorrow, 0, 0);
        $availability_candidate_ids = array_values(array_unique(array_filter(array_map('intval', array_merge(
            array_column((array) $today_rows, 'candidate_id'),
            array_column((array) $tomorrow_rows, 'candidate_id')
        )))));

        $verified_candidate_ids = [];
        $excluded_reason_counts = [];
        $excluded_reason_samples = [];
        $travel_radius_values = [];
        $school_coords = $this->ensure_school_geo_coordinates($school_id);
        $school_postcode = (string) get_post_meta($school_id, 'cmn_postcode', true);
        $school_town = (string) get_post_meta($school_id, 'cmn_town', true);
        $school_location = (string) get_post_meta($school_id, 'cmn_location', true);
        foreach ($base_candidate_ids as $candidate_id) {
            $candidate_status = sanitize_key((string) get_post_meta($candidate_id, 'cmn_status', true));
            if ($candidate_status !== '' && $candidate_status !== 'approved') {
                $excluded_reason_counts['not_approved'] = (int) ($excluded_reason_counts['not_approved'] ?? 0) + 1;
                if (empty($excluded_reason_samples['not_approved'])) {
                    $excluded_reason_samples['not_approved'] = $candidate_id;
                }
                continue;
            }
            $verified_candidate_ids[] = $candidate_id;
            $travel_radius_values[] = $this->get_candidate_travel_radius_miles($candidate_id);
        }
        $verified_candidate_ids = array_values(array_unique($verified_candidate_ids));

        $distance_filtered_candidate_ids = [];
        foreach ($verified_candidate_ids as $candidate_id) {
            $distance_eval = $this->evaluate_candidate_distance_for_debug($candidate_id, $school_id, $school_coords);
            if (!empty($distance_eval['ok'])) {
                $distance_filtered_candidate_ids[] = $candidate_id;
                continue;
            }
            $reason = (string) ($distance_eval['reason'] ?? 'location_mismatch');
            $excluded_reason_counts[$reason] = (int) ($excluded_reason_counts[$reason] ?? 0) + 1;
            if (empty($excluded_reason_samples[$reason])) {
                $excluded_reason_samples[$reason] = $candidate_id;
            }
        }
        $distance_filtered_candidate_ids = array_values(array_unique($distance_filtered_candidate_ids));

        $availability_filtered_candidate_ids = array_values(array_intersect($distance_filtered_candidate_ids, $availability_candidate_ids));
        $availability_filtered_map = array_fill_keys($availability_filtered_candidate_ids, true);
        foreach ($distance_filtered_candidate_ids as $candidate_id) {
            if (!isset($availability_filtered_map[$candidate_id])) {
                $excluded_reason_counts['not_marked_available'] = (int) ($excluded_reason_counts['not_marked_available'] ?? 0) + 1;
                if (empty($excluded_reason_samples['not_marked_available'])) {
                    $excluded_reason_samples['not_marked_available'] = $candidate_id;
                }
            }
        }
        $role_filtered_candidate_ids = $availability_filtered_candidate_ids; // No explicit role filter is currently applied in this widget.

        $manager_assigned_user_id = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
        if ($manager_assigned_user_id < 1) {
            $manager_assigned_user_id = (int) get_post_meta($school_id, 'cmn_account_manager_user_id', true);
        }
        $admin_approved = ((string) $this->get_school_access_request_status($school_id)) === 'approved';
        $final_display_count = 0;
        foreach ((array) $availability_candidates as $availability_item) {
            $candidate_post = $availability_item['post'] ?? null;
            $candidate_id = ($candidate_post instanceof WP_Post) ? (int) $candidate_post->ID : 0;
            if ($candidate_id < 1) {
                continue;
            }
            $candidate_status = sanitize_key((string) get_post_meta($candidate_id, 'cmn_status', true));
            if ($candidate_status !== '' && $candidate_status !== 'approved') {
                continue;
            }
            $final_display_count++;
        }

        $warnings = [];
        if (!$school_coords) {
            $warnings[] = 'Precise distance unavailable — add postcode to improve matching.';
        }

        $travel_radius_values = array_values(array_filter(array_map(static function ($value) {
            return (float) $value;
        }, (array) $travel_radius_values), static function ($value) {
            return $value > 0;
        }));
        $travel_radius_stats = [
            'min' => $travel_radius_values ? min($travel_radius_values) : 0,
            'avg' => $travel_radius_values ? round(array_sum($travel_radius_values) / count($travel_radius_values), 1) : 0,
            'max' => $travel_radius_values ? max($travel_radius_values) : 0,
        ];

        $reason_labels = [
            'not_approved' => 'not approved',
            'outside_radius' => 'outside radius',
            'no_coords' => 'no coords for distance match',
            'location_mismatch' => 'location mismatch',
            'no_travel_radius' => 'no travel radius set',
            'not_marked_available' => 'not marked available',
        ];
        arsort($excluded_reason_counts);
        $top_reasons = [];
        foreach ($excluded_reason_counts as $reason => $count) {
            $top_reasons[] = [
                'reason' => $reason_labels[$reason] ?? $reason,
                'count' => (int) $count,
                'sample_candidate_id' => (int) ($excluded_reason_samples[$reason] ?? 0),
            ];
            if (count($top_reasons) >= 5) {
                break;
            }
        }

        return [
            'school_id' => $school_id,
            'school_status' => (string) get_post_meta($school_id, 'cmn_status', true),
            'admin_approved' => $admin_approved ? 1 : 0,
            'manager_assigned' => $manager_assigned_user_id > 0 ? 1 : 0,
            'manager_assigned_user_id' => $manager_assigned_user_id,
            'manager_decision' => (string) get_post_meta($school_id, 'cmn_access_request_status', true),
            'school_location_inputs' => [
                'location' => $school_location,
                'town' => $school_town,
                'postcode' => $school_postcode,
                'lat' => $school_coords ? (float) ($school_coords['lat'] ?? 0) : null,
                'lng' => $school_coords ? (float) ($school_coords['lng'] ?? 0) : null,
                'radius_rule' => 'candidate_travel_radius_miles',
                'travel_radius_stats' => $travel_radius_stats,
            ],
            'query_window' => [
                'timezone' => $timezone->getName(),
                'today' => $today,
                'tomorrow' => $tomorrow,
            ],
            'role_filter' => [
                'selected_role' => 'none',
                'role_filter_used' => 'none',
            ],
            'candidate_counts' => [
                'base_candidates' => count($base_candidate_ids),
                'after_verification_doc_status_filter' => count($verified_candidate_ids),
                'after_distance_filter' => count($distance_filtered_candidate_ids),
                'after_availability_flag_filter' => count($availability_filtered_candidate_ids),
                'after_role_filter' => count($role_filtered_candidate_ids),
                'final_candidates_count' => $final_display_count,
            ],
            'excluded_reasons_top5' => $top_reasons,
            'excluded_reasons_summary' => $excluded_reason_counts,
            'warnings' => $warnings,
        ];
    }

