    public function save_school_meta($post_id) {
        $nonce = isset($_POST['cmn_school_meta_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_school_meta_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_school_meta')) {
            return;
        }
        if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
            return;
        }
        $current_user_id = (int) get_current_user_id();
        $can_manage_billing = $this->is_admin_user($current_user_id) || $this->is_staff_role($current_user_id);
        if (!current_user_can('edit_post', $post_id) && !$can_manage_billing) {
            return;
        }
        $previous_status = get_post_meta($post_id, 'cmn_status', true);
        $fields = [
            'cmn_school_id',
            'cmn_location',
            'cmn_address_line1',
            'cmn_address_line2',
            'cmn_town',
            'cmn_county',
            'cmn_postcode',
            'cmn_phone',
            'cmn_switchboard',
            'cmn_website',
            'cmn_status',
            'cmn_school_type',
            'cmn_pupil_count',
            'cmn_supply_frequency',
            'cmn_use_agencies',
            'cmn_agency_count',
            'cmn_account_manager',
            'cmn_account_manager_name',
            'cmn_account_manager_email',
            'cmn_cover_manager',
            'cmn_email',
            'cmn_email_name',
            'cmn_primary_contact_name',
            'cmn_primary_contact_email',
            'cmn_primary_contact_phone',
            'cmn_primary_contact_role',
            'cmn_school_email_domain',
            'cmn_contact1',
            'cmn_contact_role',
            'cmn_contact1_email',
            'cmn_contact2',
            'cmn_contact2_email',
            'cmn_contact3',
            'cmn_contact3_email',
            'cmn_spoke_to_cm',
            'cmn_assigned_candidates',
            'cmn_pipeline_stage',
        ];
        foreach ($fields as $field) {
            if (isset($_POST[$field])) {
                $raw_field_value = wp_unslash((string) $_POST[$field]);
                if ($field === 'cmn_assigned_candidates') {
                    $raw = sanitize_text_field($raw_field_value);
                    $ids = array_filter(array_map('intval', array_map('trim', explode(',', $raw))));
                    update_post_meta($post_id, $field, $ids);
                } else {
                    if ($field === 'cmn_school_id') {
                        $new_id = strtoupper(trim(sanitize_text_field($raw_field_value)));
                        if ($new_id !== '') {
                            $existing_id = $this->get_school_post_id_by_school_id($new_id);
                            if ($existing_id && (int) $existing_id !== (int) $post_id) {
                                continue;
                            }
                        }
                        update_post_meta($post_id, $field, $new_id);
                    } elseif ($field === 'cmn_email') {
                        $email = sanitize_email($raw_field_value);
                        update_post_meta($post_id, $field, $email);
                        $domain = $this->get_email_domain($email);
                        if ($domain !== '') {
                            $existing_id = $this->get_school_post_id_by_domain($domain);
                            if (!$existing_id || (int) $existing_id === (int) $post_id) {
                                update_post_meta($post_id, 'cmn_school_email_domain', $domain);
                            }
                        }
                    } else {
                        update_post_meta($post_id, $field, sanitize_text_field($raw_field_value));
                    }
                }
            }
        }
        if (isset($_POST['cmn_cover_manager'])) {
            $this->store_cover_manager_split($post_id, sanitize_text_field(wp_unslash((string) $_POST['cmn_cover_manager'])));
        }

        $billing_fields_posted = isset($_POST['cmn_billing_email'])
            || isset($_POST['cmn_billing_contact'])
            || isset($_POST['cmn_billing_reference'])
            || isset($_POST['cmn_invoice_email']);

        if ($billing_fields_posted && !$can_manage_billing) {
            $this->add_audit_log(
                'school_billing_update_denied',
                'school',
                (string) $post_id,
                ['reason' => 'Only admin/staff can modify billing metadata.'],
                $current_user_id
            );
        }

        if ($can_manage_billing) {
            $existing_billing_email = sanitize_email((string) get_post_meta($post_id, 'cmn_billing_email', true));
            $existing_invoice_email = sanitize_email((string) get_post_meta($post_id, 'cmn_invoice_email', true));
            $billing_email = $existing_billing_email;
            $invoice_email = $existing_invoice_email;

            if (isset($_POST['cmn_billing_contact'])) {
                update_post_meta($post_id, 'cmn_billing_contact', sanitize_text_field(wp_unslash((string) $_POST['cmn_billing_contact'])));
            }
            if (isset($_POST['cmn_billing_reference'])) {
                update_post_meta($post_id, 'cmn_billing_reference', sanitize_text_field(wp_unslash((string) $_POST['cmn_billing_reference'])));
            }

            if (isset($_POST['cmn_billing_email'])) {
                $billing_email_raw = trim((string) wp_unslash((string) $_POST['cmn_billing_email']));
                if ($billing_email_raw === '') {
                    $billing_email = '';
                } else {
                    $billing_email_sanitized = sanitize_email($billing_email_raw);
                    if ($billing_email_sanitized !== '' && is_email($billing_email_sanitized)) {
                        $billing_email = $billing_email_sanitized;
                    } else {
                        $this->add_audit_log(
                            'school_billing_email_invalid',
                            'school',
                            (string) $post_id,
                            ['field' => 'cmn_billing_email'],
                            $current_user_id
                        );
                    }
                }
            }

            if (isset($_POST['cmn_invoice_email'])) {
                $invoice_email_raw = trim((string) wp_unslash((string) $_POST['cmn_invoice_email']));
                if ($invoice_email_raw === '') {
                    $invoice_email = '';
                } else {
                    $invoice_email_sanitized = sanitize_email($invoice_email_raw);
                    if ($invoice_email_sanitized !== '' && is_email($invoice_email_sanitized)) {
                        $invoice_email = $invoice_email_sanitized;
                    } else {
                        $this->add_audit_log(
                            'school_invoice_email_invalid',
                            'school',
                            (string) $post_id,
                            ['field' => 'cmn_invoice_email'],
                            $current_user_id
                        );
                    }
                }
            }

            if ($invoice_email === '' && $billing_email !== '') {
                $invoice_email = $billing_email;
            }

            update_post_meta($post_id, 'cmn_billing_email', $billing_email);
            update_post_meta($post_id, 'cmn_invoice_email', $invoice_email);

            if ($billing_email === '' && $invoice_email === '') {
                $this->add_audit_log(
                    'school_billing_missing_warning',
                    'school',
                    (string) $post_id,
                    ['message' => 'Both billing email fields are empty.'],
                    $current_user_id
                );
                error_log('[CMN_BILLING_WARNING] school_id=' . (int) $post_id . ' has no billing email or invoice email.');
            }
        }

        if (isset($_POST['cmn_status'])) {
            $new_status = sanitize_text_field(wp_unslash((string) $_POST['cmn_status']));
            if ($new_status !== $previous_status) {
                $this->send_school_status_email($post_id, $new_status);
            }
        }
        $this->upsert_school_index($post_id);
    }

    private function send_school_status_email($post_id, $new_status) {
        $email = sanitize_email(get_post_meta($post_id, 'cmn_email', true));
        if ($email === '') {
            return;
        }
        $school_name = get_the_title($post_id);
        $status = strtolower(trim(preg_replace('/\\s+/', ' ', $new_status)));
        $contact_line = "If you have any questions, email school@covermenow.co.uk or call 07438 766 532.";
        $portal_base_url = $this->get_portal_base_url();
        $login_url = add_query_arg(['view' => 'login'], $portal_base_url);

        $secure_chat_url = '';
        $thread_for_email = $this->create_or_get_school_request_thread((int) $post_id, (int) get_current_user_id());
        if (is_array($thread_for_email) && !empty($thread_for_email['id'])) {
            $this->sync_school_request_thread_participants((int) $thread_for_email['id'], (int) $post_id);
            $token_for_email = $this->issue_school_request_chat_token((int) $thread_for_email['id'], (int) $post_id, (int) get_current_user_id());
            if (!empty($token_for_email['token'])) {
                $secure_chat_url = $this->get_school_request_chat_secure_url((int) $post_id, (string) $token_for_email['token']);
            }
        }

        $subject = '';
        $message = '';
        if (in_array($status, ['accepted', 'approved'], true)) {
            $subject = 'Your CoverMeNow ONE access is live';
            $message = "Hi {$school_name},\n\nYour application has been accepted and your access is now live.\nLog in here: {$login_url}\n\n{$contact_line}";
        } elseif (in_array($status, ['further info needed', 'further information needed', 'needs more info', 'more info needed'], true)) {
            $subject = 'More information needed for your application';
            $message = "Hi {$school_name},\n\nWe need a bit more information to complete your application.";
            if ($secure_chat_url !== '') {
                $message .= "\n\nReply in the secure chat (not by email):\n{$secure_chat_url}";
            } else {
                $message .= "\n\nPlease contact the CoverMeNow ONE team to continue your application.";
            }
            $message .= "\n\n{$contact_line}";
        } elseif (in_array($status, ['declined', 'rejected'], true)) {
            $subject = 'Update on your application';
            $message = "Hi {$school_name},\n\nThank you for your interest. Unfortunately your application has been declined.\n\n{$contact_line}";
        } else {
            return;
        }

        $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
        $GLOBALS['cmn_school_mail_log_type'] = 'school_status_update';
        $this->send_school_email($email, $subject, $message);
        if ($previous_log_type !== null) {
            $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
        } else {
            unset($GLOBALS['cmn_school_mail_log_type']);
        }
    }

    public function save_candidate_meta($post_id) {
        if (!isset($_POST['cmn_candidate_meta_nonce']) || !wp_verify_nonce($_POST['cmn_candidate_meta_nonce'], 'cmn_candidate_meta')) {
            return;
        }
        if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
            return;
        }
        $fields = [
            'cmn_location',
            'cmn_phone',
            'cmn_email',
            'cmn_status',
            'cmn_available_tomorrow',
            'cmn_availability_notes',
            'cmn_cv_file',
            'cmn_dbs_file',
            'cmn_dbs_update_service',
            'cmn_qts_status',
            'cmn_id_file',
            'cmn_default_rate',
        ];
        foreach ($fields as $field) {
            if (isset($_POST[$field])) {
                update_post_meta($post_id, $field, sanitize_text_field($_POST[$field]));
            }
        }
    }

