        echo '<div><strong>Contact 2:</strong> ' . esc_html($meta('cmn_contact2')) . ' (' . esc_html($meta('cmn_contact2_email')) . ')</div>';
        echo '<div><strong>Contact 3:</strong> ' . esc_html($meta('cmn_contact3')) . ' (' . esc_html($meta('cmn_contact3_email')) . ')</div>';
