                                        <?php wp_nonce_field('cmn_toggle_automation_rule_' . (int) $rule_row['id'], 'cmn_toggle_automation_rule_nonce'); ?>
                                        <input type="hidden" name="action" value="cmn_toggle_automation_rule">
                                        <input type="hidden" name="rule_id" value="<?php echo esc_attr((string) ((int) $rule_row['id'])); ?>">
                                        <input type="hidden" name="status" value="<?php echo esc_attr($toggle_to); ?>">
                                        <button class="button button-small"><?php echo esc_html($toggle_to === 'active' ? 'Activate' : 'Pause'); ?></button>
                                    </form>
                                </td>
                            </tr>
                        <?php endforeach; ?>
                    <?php endif; ?>
                    </tbody>
                </table>
            </div>

            <?php if ($rule_id > 0) : ?>
                <div class="cmn-card" style="padding:16px;">
                    <h2 style="margin-top:0;">Execution History (Rule #<?php echo esc_html((string) $rule_id); ?>)</h2>
                    <form method="get" style="margin-bottom:10px;">
                        <input type="hidden" name="view" value="automation">
                        <input type="hidden" name="cmn_automation_tab" value="trigger_logs">
                        <input type="hidden" name="rule_id" value="<?php echo esc_attr((string) $rule_id); ?>">
                        <label>Entity Type <input type="text" name="entity_type" value="<?php echo esc_attr($filter_entity_type); ?>" placeholder="candidate"></label>
                        <label>Entity ID <input type="number" min="0" name="entity_id" value="<?php echo esc_attr((string) $filter_entity_id); ?>"></label>
                        <button class="button">Filter</button>
                        <a class="button" href="<?php echo esc_url($this->get_automation_console_url('trigger_logs', ['rule_id' => $rule_id])); ?>">Reset</a>
                    </form>
                    <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="margin:0 0 10px;">
                        <?php wp_nonce_field('cmn_export_automation_logs_' . $rule_id, 'cmn_export_automation_logs_nonce'); ?>
                        <input type="hidden" name="action" value="cmn_export_automation_logs">
                        <input type="hidden" name="rule_id" value="<?php echo esc_attr((string) $rule_id); ?>">
                        <input type="hidden" name="entity_type" value="<?php echo esc_attr($filter_entity_type); ?>">
                        <input type="hidden" name="entity_id" value="<?php echo esc_attr((string) $filter_entity_id); ?>">
                        <button class="button">Export CSV</button>
                    </form>
                    <table class="widefat striped">
                        <thead><tr><th>When</th><th>Entity</th><th>Result</th><th>Message</th><th>Payload</th></tr></thead>
                        <tbody>
                        <?php if (!$log_rows) : ?>
                            <tr><td colspan="5">No execution logs found for this filter.</td></tr>
                        <?php else : ?>
                            <?php foreach ($log_rows as $log) : ?>
                                <tr>
                                    <td><?php echo esc_html((string) ($log['executed_at'] ?? '')); ?></td>
                                    <td><?php echo esc_html((string) (($log['entity_type'] ?? '') . '#' . ((int) ($log['entity_id'] ?? 0)))); ?></td>
                                    <td><?php echo esc_html((string) ($log['result'] ?? '')); ?></td>
                                    <td><?php echo esc_html((string) ($log['message'] ?? '')); ?></td>
                                    <td><code><?php echo esc_html(wp_trim_words((string) ($log['payload_json'] ?? ''), 18, '...')); ?></code></td>
                                </tr>
                            <?php endforeach; ?>
                        <?php endif; ?>
                        </tbody>
                    </table>
                </div>
            <?php endif; ?>
        </div>
        <script>
        (function () {
            var conditionFieldsByEntity = <?php echo wp_json_encode($condition_field_map); ?>;
            var operators = <?php echo wp_json_encode($operators); ?>;
            var actionTypes = <?php echo wp_json_encode($action_types); ?>;
            var triggerLabels = <?php echo wp_json_encode($trigger_options); ?>;
            var entityTypeEl = document.getElementById('cmn-entity-type');
            var addConditionBtn = document.getElementById('cmn-add-condition');
            var addActionBtn = document.getElementById('cmn-add-action');
            var conditionsTable = document.getElementById('cmn-conditions-table');
            var actionsTable = document.getElementById('cmn-actions-table');
            var previewEl = document.getElementById('cmn-rule-preview-text');
            var triggerEl = document.getElementById('cmn-trigger-event');
            var nameEl = document.getElementById('cmn-rule-name');
            var smokeEventEl = document.getElementById('cmn-smoke-event');
            var smokeEntityEl = document.getElementById('cmn-smoke-entity');

            function refreshConditionFieldOptions() {
                if (!conditionsTable || !entityTypeEl) {
                    return;
                }
                var map = conditionFieldsByEntity[entityTypeEl.value] || {};
                var rows = conditionsTable.querySelectorAll('tbody tr');
                rows.forEach(function (row) {
                    var select = row.querySelector('select.cmn-condition-field');
                    if (!select) {
                        return;
                    }
                    var selected = select.getAttribute('data-selected') || select.value || '';
                    select.innerHTML = '';
                    Object.keys(map).forEach(function (key) {
                        var option = document.createElement('option');
                        option.value = key;
                        option.textContent = map[key];
                        if (selected === key) {
                            option.selected = true;
                        }
                        select.appendChild(option);
                    });
                    if (!select.value && select.options.length > 0) {
                        select.options[0].selected = true;
                    }
                    select.removeAttribute('data-selected');
                });
            }

            function nextIndex(selector) {
                var rows = document.querySelectorAll(selector);
                return rows ? rows.length : 0;
            }

            function addConditionRow() {
                if (!conditionsTable) {
                    return;
                }
                var idx = nextIndex('#cmn-conditions-table tbody tr');
                var tr = document.createElement('tr');
                tr.className = 'cmn-condition-row';
                var options = '';
                operators.forEach(function (operator) {
                    options += '<option value="' + operator + '">' + operator + '</option>';
                });
                tr.innerHTML = ''
                    + '<td><select class="cmn-condition-field" name="conditions[' + idx + '][field]"></select></td>'
                    + '<td><select name="conditions[' + idx + '][operator]">' + options + '</select></td>'
                    + '<td><input type="text" name="conditions[' + idx + '][value]"></td>'
                    + '<td><button type="button" class="button-link-delete cmn-remove-condition">Remove</button></td>';
                conditionsTable.querySelector('tbody').appendChild(tr);
                refreshConditionFieldOptions();
                updatePreview();
            }

            function addActionRow() {
                if (!actionsTable) {
                    return;
                }
                var idx = nextIndex('#cmn-actions-table tbody tr');
                var typeOptions = '';
                actionTypes.forEach(function (type) {
                    typeOptions += '<option value="' + type + '">' + type + '</option>';
                });
                var tr = document.createElement('tr');
                tr.className = 'cmn-action-row';
                tr.innerHTML = ''
                    + '<td><select name="actions[' + idx + '][type]">' + typeOptions + '</select></td>'
                    + '<td><input type="text" name="actions[' + idx + '][template]"></td>'
                    + '<td><input type="text" name="actions[' + idx + '][message]"></td>'
                    + '<td><input type="text" name="actions[' + idx + '][target]" placeholder="candidate|school|account_manager|user_id"></td>'
                    + '<td><input type="text" name="actions[' + idx + '][value]" placeholder="status or user ID"></td>'
                    + '<td><input type="date" name="actions[' + idx + '][due_date]"></td>'
                    + '<td><button type="button" class="button-link-delete cmn-remove-action">Remove</button></td>';
                actionsTable.querySelector('tbody').appendChild(tr);
                updatePreview();
            }

            function collectConditionSummary() {
                if (!conditionsTable) {
                    return 'no conditions';
                }
                var parts = [];
                conditionsTable.querySelectorAll('tbody tr').forEach(function (row) {
                    var field = row.querySelector('select[name*="[field]"]');
                    var operator = row.querySelector('select[name*="[operator]"]');
                    var value = row.querySelector('input[name*="[value]"]');
                    if (field && operator && value && field.value) {
                        parts.push(field.value + ' ' + operator.value + ' ' + value.value);
                    }
                });
                return parts.length ? parts.join(' AND ') : 'no conditions';
            }

            function collectActionSummary() {
                if (!actionsTable) {
                    return 'no actions';
                }
                var parts = [];
                actionsTable.querySelectorAll('tbody tr').forEach(function (row) {
                    var type = row.querySelector('select[name*="[type]"]');
                    var target = row.querySelector('input[name*="[target]"]');
                    var value = row.querySelector('input[name*="[value]"]');
                    if (type) {
                        var text = type.value;
                        if (target && target.value) {
                            text += ' -> ' + target.value;
                        }
                        if (value && value.value) {
                            text += ' (' + value.value + ')';
                        }
                        parts.push(text);
                    }
                });
                return parts.length ? parts.join(', ') : 'no actions';
            }

            function updatePreview() {
                if (!previewEl) {
                    return;
                }
                var name = nameEl && nameEl.value ? nameEl.value : 'Rule';
                var trigger = triggerEl && triggerLabels[triggerEl.value] ? triggerLabels[triggerEl.value] : 'Event';
                var conditionSummary = collectConditionSummary();
                var actionSummary = collectActionSummary();
                previewEl.textContent = name + ': when "' + trigger + '" and ' + conditionSummary + ', then ' + actionSummary + '.';
            }

            if (entityTypeEl) {
                entityTypeEl.addEventListener('change', function () {
                    refreshConditionFieldOptions();
                    updatePreview();
                });
            }
            if (addConditionBtn) {
                addConditionBtn.addEventListener('click', addConditionRow);
            }
            if (addActionBtn) {
                addActionBtn.addEventListener('click', addActionRow);
            }
            if (smokeEventEl && smokeEntityEl) {
                var refreshSmokeEntities = function () {
                    var wanted = smokeEventEl.value;
                    var options = smokeEntityEl.options;
                    var firstMatch = -1;
                    for (var i = 0; i < options.length; i++) {
                        var keep = options[i].getAttribute('data-event') === wanted;
                        options[i].style.display = keep ? '' : 'none';
                        if (keep && firstMatch < 0) {
                            firstMatch = i;
                        }
                    }
                    if (firstMatch >= 0) {
                        smokeEntityEl.selectedIndex = firstMatch;
                    }
                };
                smokeEventEl.addEventListener('change', refreshSmokeEntities);
                refreshSmokeEntities();
            }
            document.addEventListener('click', function (event) {
                if (event.target && event.target.classList.contains('cmn-remove-condition')) {
                    event.preventDefault();
                    var row = event.target.closest('tr');
                    if (row && row.parentNode) {
                        row.parentNode.removeChild(row);
                    }
                    updatePreview();
                }
                if (event.target && event.target.classList.contains('cmn-remove-action')) {
                    event.preventDefault();
                    var actionRow = event.target.closest('tr');
                    if (actionRow && actionRow.parentNode) {
                        actionRow.parentNode.removeChild(actionRow);
                    }
                    updatePreview();
                }
            });
            document.addEventListener('input', function (event) {
                if (event.target && event.target.closest('#cmn-automation-rule-form')) {
                    updatePreview();
                }
            });
            refreshConditionFieldOptions();
            updatePreview();
        })();
        </script>
        <?php
    }

    public function handle_save_automation_rule() {
        if (!is_user_logged_in() || !$this->can_manage_automation(get_current_user_id())) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_save_automation_rule_nonce']) || !wp_verify_nonce($_POST['cmn_save_automation_rule_nonce'], 'cmn_save_automation_rule')) {
            wp_die('Invalid request');
        }
        global $wpdb;
        $rules_table = $this->get_automation_rules_table();

        $rule_id = (int) ($_POST['rule_id'] ?? 0);
        $name = sanitize_text_field((string) ($_POST['name'] ?? ''));
        $description = sanitize_textarea_field((string) ($_POST['description'] ?? ''));
        $trigger_event = sanitize_key((string) ($_POST['trigger_event'] ?? ''));
        $trigger_options = $this->get_automation_trigger_events();
        if ($name === '' || !isset($trigger_options[$trigger_event])) {
            wp_safe_redirect($this->get_automation_console_url('rules', [
                'cmn_automation_msg' => 'Rule name and trigger event are required.',
            ]));
            exit;
        }

        $entity_type = sanitize_key((string) ($_POST['conditions_entity_type'] ?? 'candidate'));
        $field_map = $this->get_automation_condition_field_map();
        if (!isset($field_map[$entity_type])) {
            $entity_type = 'candidate';
        }
        $operators = ['equals', 'not_equals', 'contains', 'not_contains', 'greater_than', 'less_than', 'days_since', 'days_since_last_activity', 'is_empty', 'is_not_empty'];
        $condition_rules = [];
        $conditions_rows = isset($_POST['conditions']) && is_array($_POST['conditions']) ? $_POST['conditions'] : [];
        foreach ($conditions_rows as $row) {
            if (!is_array($row)) {
                continue;
            }
            $field = sanitize_key((string) ($row['field'] ?? ''));
            $operator = sanitize_key((string) ($row['operator'] ?? 'equals'));
            $value = sanitize_text_field((string) ($row['value'] ?? ''));
            if ($field === '' || !isset($field_map[$entity_type][$field])) {
                continue;
            }
            if (!in_array($operator, $operators, true)) {
                $operator = 'equals';
            }
            $condition_rules[] = [
                'field' => $field,
                'operator' => $operator,
                'value' => $value,
            ];
        }

        $action_types = ['send_email', 'create_task', 'add_notification', 'update_status', 'assign_account_manager'];
        $action_rows = isset($_POST['actions']) && is_array($_POST['actions']) ? $_POST['actions'] : [];
        $actions = [];
        foreach ($action_rows as $row) {
            if (!is_array($row)) {
                continue;
            }
            $type = sanitize_key((string) ($row['type'] ?? ''));
            if (!in_array($type, $action_types, true)) {
                continue;
            }
            $template = sanitize_text_field((string) ($row['template'] ?? ''));
            $message = sanitize_textarea_field((string) ($row['message'] ?? ''));
            $target = sanitize_text_field((string) ($row['target'] ?? ''));
            $value = sanitize_text_field((string) ($row['value'] ?? ''));
            $due_date = sanitize_text_field((string) ($row['due_date'] ?? ''));

            $action = ['type' => $type];
            if ($template !== '') {
                $action['template'] = $template;
                $action['subject'] = $template;
                $action['title'] = $template;
            }
            if ($message !== '') {
                $action['message'] = $message;
                $action['notes'] = $message;
            }
            if ($target !== '') {
                $action['target'] = $target;
                $action['assigned_to'] = $target;
                $action['recipient'] = $target;
            }
            if ($value !== '') {
                $action['value'] = $value;
                $action['status'] = $value;
                if (ctype_digit($value)) {
                    $action['manager_user_id'] = (int) $value;
                }
            }
            if ($due_date !== '') {
                $action['due_date'] = $due_date;
            }
            $actions[] = $action;
        }
        if (!$actions) {
            wp_safe_redirect($this->get_automation_console_url('rules', [
                'cmn_automation_msg' => 'At least one action is required.',
            ]));
            exit;
        }

        $status = $this->normalize_automation_rule_status($_POST['status'] ?? 'active');
        $cooldown_hours = max(0, (int) ($_POST['cooldown_hours'] ?? self::AUTOMATION_DEFAULT_COOLDOWN_HOURS));
        $scheduled_events = ['no_activity_days', 'daily_inactive_candidates', 'stale_leads', 'document_review_overdue'];
        $trigger_type = in_array($trigger_event, $scheduled_events, true) ? 'scheduled' : 'event';
        $now = current_time('mysql');
        $data = [
            'name' => $name,
            'description' => $description,
            'trigger_type' => $trigger_type,
            'trigger_event' => $trigger_event,
            'conditions_json' => wp_json_encode([
                'entity_type' => $entity_type,
                'rules' => array_values($condition_rules),
            ]),
            'actions_json' => wp_json_encode([
                'actions' => array_values($actions),
            ]),
            'cooldown_hours' => $cooldown_hours,
            'status' => $status,
            'updated_at' => $now,
        ];

        if ($rule_id > 0) {
            $wpdb->update($rules_table, $data, ['id' => $rule_id], ['%s', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%s'], ['%d']);
            $saved_rule_id = $rule_id;
        } else {
            $data['created_by'] = get_current_user_id();
            $data['created_at'] = $now;
            $data['last_run_at'] = null;
            $wpdb->insert($rules_table, $data, ['%s', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%s', '%d', '%s', '%s']);
            $saved_rule_id = (int) $wpdb->insert_id;
        }

        $redirect = $this->get_automation_console_url('rules', [
            'edit_rule_id' => $saved_rule_id,
            'cmn_automation_msg' => ($rule_id > 0 ? 'Rule updated.' : 'Rule created.'),
        ]);
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_toggle_automation_rule() {
        if (!is_user_logged_in() || !$this->can_manage_automation(get_current_user_id())) {
            wp_die('Unauthorized');
        }
        $rule_id = (int) ($_POST['rule_id'] ?? 0);
        if ($rule_id < 1) {
            wp_die('Invalid rule.');
        }
        if (!isset($_POST['cmn_toggle_automation_rule_nonce']) || !wp_verify_nonce($_POST['cmn_toggle_automation_rule_nonce'], 'cmn_toggle_automation_rule_' . $rule_id)) {
            wp_die('Invalid request');
        }
        $status = $this->normalize_automation_rule_status($_POST['status'] ?? 'paused');
        global $wpdb;
        $wpdb->update(
            $this->get_automation_rules_table(),
            ['status' => $status, 'updated_at' => current_time('mysql')],
            ['id' => $rule_id],
            ['%s', '%s'],
            ['%d']
        );
        wp_safe_redirect($this->get_automation_console_url('rules', [
            'cmn_automation_msg' => 'Rule status updated.',
        ]));
        exit;
    }

    public function handle_export_automation_logs() {
        if (!is_user_logged_in() || !$this->can_manage_automation(get_current_user_id())) {
            wp_die('Unauthorized');
        }
        $rule_id = (int) ($_POST['rule_id'] ?? 0);
        if ($rule_id < 1) {
            wp_die('Invalid rule.');
        }
        if (!isset($_POST['cmn_export_automation_logs_nonce']) || !wp_verify_nonce($_POST['cmn_export_automation_logs_nonce'], 'cmn_export_automation_logs_' . $rule_id)) {
            wp_die('Invalid request');
        }
        global $wpdb;
        $logs_table = $this->get_automation_logs_table();
        $entity_type = sanitize_key((string) ($_POST['entity_type'] ?? ''));
        $entity_id = (int) ($_POST['entity_id'] ?? 0);
        $where = ["rule_id = %d"];
        $params = [$rule_id];
        if ($entity_type !== '') {
            $where[] = "entity_type = %s";
            $params[] = $entity_type;
        }
        if ($entity_id > 0) {
            $where[] = "entity_id = %d";
            $params[] = $entity_id;
        }
        $sql = "SELECT id, rule_id, entity_type, entity_id, executed_at, result, message, payload_json
                FROM {$logs_table}
                WHERE " . implode(' AND ', $where) . "
                ORDER BY executed_at DESC
                LIMIT 5000";
        $rows = (array) $wpdb->get_results($wpdb->prepare($sql, $params), ARRAY_A);

        nocache_headers();
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=cmn-automation-logs-rule-' . $rule_id . '-' . gmdate('Ymd-His') . '.csv');
        $fp = fopen('php://output', 'w');
        fputcsv($fp, ['id', 'rule_id', 'entity_type', 'entity_id', 'executed_at', 'result', 'message', 'payload_json']);
        foreach ($rows as $row) {
            fputcsv($fp, [
                (int) ($row['id'] ?? 0),
                (int) ($row['rule_id'] ?? 0),
                (string) ($row['entity_type'] ?? ''),
                (int) ($row['entity_id'] ?? 0),
                (string) ($row['executed_at'] ?? ''),
                (string) ($row['result'] ?? ''),
                (string) ($row['message'] ?? ''),
                (string) ($row['payload_json'] ?? ''),
            ]);
        }
        fclose($fp);
        exit;
    }

    public function handle_run_automation_smoke_test() {
        if (!is_user_logged_in() || !$this->can_manage_automation(get_current_user_id())) {
            wp_die('Unauthorized');
        }
        if (
            !isset($_POST['cmn_run_automation_smoke_test_nonce']) ||
            !wp_verify_nonce((string) $_POST['cmn_run_automation_smoke_test_nonce'], 'cmn_run_automation_smoke_test')
        ) {
            wp_die('Invalid request');
        }

        $event = sanitize_key((string) ($_POST['cmn_smoke_event'] ?? ''));
        $entity = sanitize_text_field((string) ($_POST['cmn_smoke_entity'] ?? ''));
        $send_real_emails = !empty($_POST['cmn_smoke_send_real_emails']);
        $parts = explode(':', $entity, 2);
        $entity_type = sanitize_key((string) ($parts[0] ?? ''));
        $entity_id = (int) ($parts[1] ?? 0);

        $result = [
            'event' => $event,
            'entity_type' => $entity_type,
            'entity_id' => $entity_id,
            'dry_run' => $send_real_emails ? 0 : 1,
            'rules_matched' => [],
            'rules_skipped' => [],
            'actions_executed' => [],
            'failures' => [],
        ];
        if ($event !== '' && $entity_type !== '' && $entity_id > 0) {
            $result = $this->get_automation_engine()->run_smoke_test($event, $entity_type, $entity_id, $send_real_emails);
        }

        set_transient('cmn_automation_smoke_result_' . get_current_user_id(), $result, 10 * MINUTE_IN_SECONDS);
        $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? $this->get_automation_console_url('rules')));
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_add_activity() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_add_activity_nonce']) || !wp_verify_nonce($_POST['cmn_add_activity_nonce'], 'cmn_add_activity')) {
            wp_die('Invalid nonce');
        }
        $school_domain = sanitize_text_field($_POST['cmn_school_domain'] ?? '');
        $school_id = intval($_POST['cmn_school_id'] ?? 0);
        $candidate_id = intval($_POST['cmn_candidate_id'] ?? 0);
        $title = sanitize_text_field($_POST['cmn_activity_title'] ?? '');
        $type = sanitize_text_field($_POST['cmn_activity_type'] ?? 'note');
        $content = sanitize_textarea_field($_POST['cmn_activity_content'] ?? '');
        $date = sanitize_text_field($_POST['cmn_activity_date'] ?? '');
        $duration = sanitize_text_field($_POST['cmn_activity_duration'] ?? '');

        if ($school_domain === '' && $school_id) {
            $school_domain = get_post_meta($school_id, 'cmn_school_email_domain', true);
        }
        if ($school_domain === '' && $school_id) {
            $school_email = get_post_meta($school_id, 'cmn_email', true);
            $school_domain = $this->get_email_domain($school_email);
        }
        if ($school_domain === '' && $school_id === 0 && $candidate_id) {
            $school_domain = '';
        }

        if ($school_domain) {
            if (!$this->user_can_access_school($school_domain)) {
                wp_die('Unauthorized');
            }
            $details_thread = $this->get_booking_thread_by_booking((int) $booking_id_for_rates, 'booking_details');
            if (!empty($details_thread['id'])) {
                $this->set_booking_thread_status((int) $details_thread['id'], 'closed');
                $this->add_booking_thread_message((int) $details_thread['id'], get_current_user_id(), $this->is_admin_user() ? 'admin' : 'account_manager', 'Booking details finalized. Thread closed by CoverMeNow. Post a message any time to reopen.');
            }

            $this->insert_activity_row([
                'entity_type' => 'school',
                'entity_ref' => $school_domain,
                'activity_type' => $type,
                'subject' => $title ?: ucfirst($type),
                'notes' => $content,
                'due_date' => $date,
                'duration_minutes' => $duration,
                'created_by' => get_current_user_id(),
                'assigned_to_user_id' => get_current_user_id(),
                'assigned_to_school_domain' => $school_domain,
            ]);
        } elseif ($candidate_id) {
            $this->insert_activity_row([
                'entity_type' => 'contact',
                'entity_ref' => (string) $candidate_id,
                'activity_type' => $type,
                'subject' => $title ?: ucfirst($type),
                'notes' => $content,
                'due_date' => $date,
                'duration_minutes' => $duration,
                'created_by' => get_current_user_id(),
            ]);
        }

        $redirect = esc_url_raw($_POST['cmn_redirect'] ?? '');
        if ($redirect) {
            wp_redirect($redirect);
        } elseif ($school_id) {
            wp_redirect(admin_url('admin.php?page=cmn-school-profile&school_id=' . $school_id));
        } else {
            wp_redirect(admin_url('admin.php?page=cmn-candidate-profile&candidate_id=' . $candidate_id));
        }
        exit;
    }

    public function handle_complete_activity() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_complete_activity_nonce']) || !wp_verify_nonce($_POST['cmn_complete_activity_nonce'], 'cmn_complete_activity')) {
            wp_die('Invalid request');
        }
        $activity_id = intval($_POST['cmn_activity_id'] ?? 0);
        if ($activity_id) {
            global $wpdb;
            $table = $this->get_activity_table();
            $wpdb->update($table, [
                'completed_at' => current_time('mysql'),
                'updated_at' => current_time('mysql'),
            ], [
                'id' => $activity_id,
            ], ['%s', '%s'], ['%d']);
        }
        $redirect = esc_url_raw($_POST['cmn_redirect'] ?? '');
        if ($redirect) {
            wp_redirect($redirect);
        } else {
            $portal_page = cmn_get_page_by_title('Portal');
            $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
            wp_redirect(add_query_arg(['view' => 'schools'], $portal_url));
        }
        exit;
    }

    private function convert_school_to_client_and_send_invite($school_post_id) {
        $school_post_id = (int) $school_post_id;
        if ($school_post_id < 1 || get_post_type($school_post_id) !== 'cmn_school') {
            return ['ok' => false, 'message' => 'School not found.'];
        }
        $school_domain = strtolower(trim((string) get_post_meta($school_post_id, 'cmn_school_email_domain', true)));
        if ($school_domain === '') {
            $school_domain = $this->get_email_domain((string) get_post_meta($school_post_id, 'cmn_email', true));
        }
        if ($school_domain === '') {
            return ['ok' => false, 'message' => 'School email domain is missing.'];
        }
        update_post_meta($school_post_id, 'cmn_school_email_domain', $school_domain);

        $primary_email = sanitize_email((string) get_post_meta($school_post_id, 'cmn_primary_contact_email', true));
        if ($primary_email === '') {
            $primary_email = sanitize_email((string) get_post_meta($school_post_id, 'cmn_contact1_email', true));
        }
        if ($primary_email === '') {
            $primary_email = sanitize_email((string) get_post_meta($school_post_id, 'cmn_email', true));
        }
        if ($primary_email === '' || !is_email($primary_email)) {
            return ['ok' => false, 'message' => 'Primary contact email is missing.'];
        }

        update_post_meta($school_post_id, 'cmn_status', 'client');
        $current_stage = sanitize_key((string) get_post_meta($school_post_id, 'cmn_pipeline_stage', true));
        if ($current_stage !== 'lost') {
            update_post_meta($school_post_id, 'cmn_pipeline_stage', 'won');
        }

        $this->upsert_client_profile($school_domain, [
            'completion_status' => 'complete',
            'completed_at' => current_time('mysql'),
        ]);

        $account = $this->ensure_school_portal_user_and_reset_link($school_post_id, $primary_email);
        if (empty($account['ok'])) {
            return ['ok' => false, 'message' => (string) ($account['message'] ?? 'Client converted, but login setup could not be created.')];
        }

        $set_password_url = (string) ($account['set_password_url'] ?? '');
        $username = (string) ($account['username'] ?? '');
        if ($set_password_url === '') {
            return ['ok' => false, 'message' => 'Client converted, but password setup link could not be created.'];
        }

        $subject = 'Your account has been approved - set your password';
        $message = "Your school account has been approved.

";
        if ($username !== '') {
            $message .= "Username: {$username}
";
        }
        $message .= "Set your password here: {$set_password_url}

After setting your password, log in at: " . $this->get_portal_login_url() . "
";

        $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
        $GLOBALS['cmn_school_mail_log_type'] = 'school_profile_invite';
        $sent = $this->send_school_email($primary_email, $subject, $message);
        if ($previous_log_type !== null) {
            $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
        } else {
            unset($GLOBALS['cmn_school_mail_log_type']);
        }
        if (!$sent) {
            return ['ok' => false, 'message' => 'Client converted, but invite email could not be sent.'];
        }
        return [
            'ok' => true,
            'message' => 'Client converted and password setup email sent.',
            'school_id' => (int) $school_post_id,
            'school_domain' => (string) $school_domain,
            'school_user_id' => (int) ($account['user_id'] ?? 0),
            'school_username' => (string) $username,
            'set_password_url' => (string) $set_password_url,
        ];
    }


    public function handle_convert_client() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_convert_client_nonce']) || !wp_verify_nonce($_POST['cmn_convert_client_nonce'], 'cmn_convert_client')) {
            wp_die('Invalid request');
        }
        $school_post_id = (int) ($_POST['cmn_school_id'] ?? 0);
        $school_domain = sanitize_text_field((string) ($_POST['cmn_school_domain'] ?? ''));
        if ($school_post_id < 1 && $school_domain !== '') {
            $school_post_id = (int) $this->get_school_post_id_by_domain($school_domain);
        }
        if ($school_post_id < 1) {
            wp_die('Missing school.');
        }
        if (!$this->user_can_access_school($school_post_id)) {
            wp_die('Unauthorized');
        }
        $result = $this->convert_school_to_client_and_send_invite($school_post_id);
        $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? ''));
        $message = (string) ($result['message'] ?? 'Client conversion completed.');
        if ($redirect) {
            wp_redirect(add_query_arg(['cmn_convert_msg' => rawurlencode($message)], $redirect));
        } else {
            wp_redirect(home_url('/portal'));
        }
        exit;
    }


    private function get_school_request_chat_token_ttl_days() {
        $days = (int) apply_filters('cmn_school_request_chat_token_ttl_days', 30);
        return max(1, min(90, $days));
    }

    private function get_school_request_chat_rate_limit_key($school_id, $ip_address = '') {
        $school_id = (int) $school_id;
        $ip = $ip_address !== '' ? $ip_address : $this->get_request_ip_address();
        return 'cmn_thread_token_rl_' . $school_id . '_' . substr(hash('sha256', (string) $ip), 0, 20);
    }

    private function is_school_request_chat_rate_limited($school_id, $ip_address = '') {
        $key = $this->get_school_request_chat_rate_limit_key($school_id, $ip_address);
        $attempts = (int) get_transient($key);
        return $attempts >= 12;
    }

    private function bump_school_request_chat_rate_limit($school_id, $ip_address = '') {
        $key = $this->get_school_request_chat_rate_limit_key($school_id, $ip_address);
        $attempts = (int) get_transient($key);
        set_transient($key, $attempts + 1, 15 * MINUTE_IN_SECONDS);
    }

    private function clear_school_request_chat_rate_limit($school_id, $ip_address = '') {
        delete_transient($this->get_school_request_chat_rate_limit_key($school_id, $ip_address));
    }

    private function get_school_request_thread_by_school_id($school_id) {
        global $wpdb;
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return null;
        }
        $table = $this->get_threads_table();
        return $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE entity_type = %s AND entity_id = %d LIMIT 1",
            'school_request',
            $school_id
        ), ARRAY_A);
    }

    private function create_or_get_school_request_thread($school_id, $created_by_user_id = 0) {
        global $wpdb;
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return null;
        }
        $existing = $this->get_school_request_thread_by_school_id($school_id);
        if ($existing) {
            $thread_id = (int) ($existing['id'] ?? 0);
            if ($thread_id > 0) {
                $this->sync_school_request_thread_participants($thread_id, $school_id);
            }
            return $existing;
        }
        $now = current_time('mysql');
        $table = $this->get_threads_table();
        $wpdb->insert($table, [
            'entity_type' => 'school_request',
            'entity_id' => $school_id,
            'status' => 'open',
            'created_by_user_id' => (int) $created_by_user_id ?: null,
            'created_at' => $now,
            'updated_at' => $now,
            'last_message_at' => null,
        ], ['%s', '%d', '%s', '%d', '%s', '%s', '%s']);
        $thread_id = (int) $wpdb->insert_id;
        if ($thread_id < 1) {
            return $this->get_school_request_thread_by_school_id($school_id);
        }
        $this->sync_school_request_thread_participants($thread_id, $school_id);
        return $this->get_school_request_thread_by_school_id($school_id);
    }

    private function get_school_user_ids_for_school_request($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return [];
        }
        $user_ids = [];
        $mapped_users = get_users([
            'role__in' => ['cmn_school_manager', 'cmn_school_staff'],
            'meta_key' => 'cmn_school_id',
            'meta_value' => (string) $school_id,
            'fields' => ['ID'],
        ]);
        foreach ((array) $mapped_users as $mapped) {
            if (!empty($mapped->ID)) {
                $user_ids[] = (int) $mapped->ID;
            }
        }
        $emails = [
            sanitize_email((string) get_post_meta($school_id, 'cmn_primary_contact_email', true)),
            sanitize_email((string) get_post_meta($school_id, 'cmn_contact1_email', true)),
            sanitize_email((string) get_post_meta($school_id, 'cmn_contact2_email', true)),
            sanitize_email((string) get_post_meta($school_id, 'cmn_contact3_email', true)),
            sanitize_email((string) get_post_meta($school_id, 'cmn_email', true)),
        ];
        foreach ($emails as $email) {
            if ($email === '' || !is_email($email)) {
                continue;
            }
            $user = get_user_by('email', $email);
            if ($user && !empty($user->ID) && $this->is_school_user((int) $user->ID)) {
                $user_ids[] = (int) $user->ID;
            }
        }
        return array_values(array_unique(array_filter(array_map('intval', $user_ids))));
    }

    private function get_staff_user_ids_for_school_request($school_id) {
        $school_id = (int) $school_id;
        $user_ids = [];
        $assigned_manager = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
        if ($assigned_manager < 1) {
            $assigned_manager = (int) get_post_meta($school_id, 'cmn_account_manager_user_id', true);
        }
        if ($assigned_manager > 0) {
            $user_ids[] = $assigned_manager;
        }
        $staff_users = get_users([
            'role__in' => ['cmn_staff', 'cmn_admin', 'administrator'],
            'fields' => ['ID'],
        ]);
        foreach ((array) $staff_users as $staff_user) {
            if (!empty($staff_user->ID)) {
                $user_ids[] = (int) $staff_user->ID;
            }
        }
        return array_values(array_unique(array_filter(array_map('intval', $user_ids))));
    }

    private function add_school_request_thread_participant($thread_id, $user_id, $role, $last_read_at = null) {
        global $wpdb;
        $thread_id = (int) $thread_id;
        $user_id = (int) $user_id;
        if ($thread_id < 1 || $user_id < 1) {
            return;
        }
        $role = sanitize_key((string) $role);
        if (!in_array($role, ['staff', 'school'], true)) {
            $role = 'staff';
        }
        $table = $this->get_thread_participants_table();
        $wpdb->replace($table, [
            'thread_id' => $thread_id,
            'user_id' => $user_id,
            'role' => $role,
            'last_read_at' => $last_read_at !== null ? (string) $last_read_at : null,
            'created_at' => current_time('mysql'),
        ], ['%d', '%d', '%s', '%s', '%s']);
    }

    private function sync_school_request_thread_participants($thread_id, $school_id) {
        $thread_id = (int) $thread_id;
        $school_id = (int) $school_id;
        if ($thread_id < 1 || $school_id < 1) {
            return;
        }
        foreach ($this->get_staff_user_ids_for_school_request($school_id) as $staff_user_id) {
            $this->add_school_request_thread_participant($thread_id, $staff_user_id, 'staff');
        }
        foreach ($this->get_school_user_ids_for_school_request($school_id) as $school_user_id) {
            $this->add_school_request_thread_participant($thread_id, $school_user_id, 'school');
        }
    }

    private function get_school_request_thread_participant($thread_id, $user_id) {
        global $wpdb;
        $thread_id = (int) $thread_id;
        $user_id = (int) $user_id;
        if ($thread_id < 1 || $user_id < 1) {
            return null;
        }
        $table = $this->get_thread_participants_table();
        return $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE thread_id = %d AND user_id = %d LIMIT 1",
            $thread_id,
            $user_id
        ), ARRAY_A);
    }

    private function get_school_request_thread_messages($thread_id, $limit = 400) {
        global $wpdb;
        $thread_id = (int) $thread_id;
        if ($thread_id < 1) {
            return [];
        }
        $limit = max(20, min(1000, (int) $limit));
        $table = $this->get_thread_messages_table();
        return (array) $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE thread_id = %d ORDER BY id ASC LIMIT %d",
            $thread_id,
            $limit
        ), ARRAY_A);
    }

    private function add_school_request_thread_attachments($message_id, $attachment_ids = []) {
        global $wpdb;
        $message_id = (int) $message_id;
        if ($message_id < 1 || !is_array($attachment_ids) || !$attachment_ids) {
            return;
        }
        $table = $this->get_thread_attachments_table();
        $now = current_time('mysql');
        foreach ($attachment_ids as $attachment_id) {
            $attachment_id = (int) $attachment_id;
            if ($attachment_id < 1) {
                continue;
            }
            $file = get_attached_file($attachment_id);
            $wpdb->insert($table, [
                'message_id' => $message_id,
                'attachment_id' => $attachment_id,
                'storage_key' => null,
                'filename' => basename((string) ($file ?: wp_basename((string) get_post_field('post_title', $attachment_id)))),
                'mime_type' => (string) get_post_mime_type($attachment_id),
                'file_size' => ($file && file_exists($file)) ? (int) filesize($file) : null,
                'created_at' => $now,
            ], ['%d', '%d', '%s', '%s', '%s', '%d', '%s']);
        }
    }

    private function get_school_request_message_attachments($message_id, $school_id = 0, $token = '') {
        global $wpdb;
        $message_id = (int) $message_id;
        if ($message_id < 1) {
            return [];
        }
        $table = $this->get_thread_attachments_table();
        $rows = (array) $wpdb->get_results($wpdb->prepare(
            "SELECT id, attachment_id, filename, mime_type, file_size FROM {$table} WHERE message_id = %d ORDER BY id ASC",
            $message_id
        ), ARRAY_A);
        if (!$rows) {
            return [];
        }
        $out = [];
        foreach ($rows as $row) {
            $attachment_id = (int) ($row['attachment_id'] ?? 0);
            if ($attachment_id < 1) {
                continue;
            }
            $download_url = add_query_arg([
                'action' => 'cmn_thread_download_attachment',
                'entity_type' => 'school_request',
                'entity_id' => (int) $school_id,
                'message_id' => (int) $message_id,
                'attachment_id' => $attachment_id,
                'token' => (string) $token,
            ], admin_url('admin-ajax.php'));
            $filename = (string) ($row['filename'] ?? 'attachment');
            if ($filename === '') {
                $filename = basename((string) get_attached_file($attachment_id));
            }
            $out[] = [
                'id' => (int) ($row['id'] ?? 0),
                'attachment_id' => $attachment_id,
                'filename' => $filename,
                'mime_type' => (string) ($row['mime_type'] ?? ''),
                'file_size' => (int) ($row['file_size'] ?? 0),
                'url' => esc_url_raw($download_url),
            ];
        }
        return $out;
    }

    private function mark_school_request_thread_read($thread_id, $user_id) {
        global $wpdb;
        $thread_id = (int) $thread_id;
        $user_id = (int) $user_id;
        if ($thread_id < 1 || $user_id < 1) {
            return;
        }
        $now = current_time('mysql');
        $table = $this->get_thread_participants_table();
        $updated = $wpdb->update($table, [
            'last_read_at' => $now,
        ], [
            'thread_id' => $thread_id,
            'user_id' => $user_id,
        ], ['%s'], ['%d', '%d']);
        if ($updated === false || (int) $updated < 1) {
            $this->add_school_request_thread_participant($thread_id, $user_id, $this->is_school_user($user_id) ? 'school' : 'staff', $now);
        }
    }

    private function get_school_request_thread_unread_count($thread_id, $user_id) {
        global $wpdb;
        $thread_id = (int) $thread_id;
        $user_id = (int) $user_id;
        if ($thread_id < 1 || $user_id < 1) {
            return 0;
        }
        $participant = $this->get_school_request_thread_participant($thread_id, $user_id);
        $messages_table = $this->get_thread_messages_table();
        if (!$participant || empty($participant['last_read_at'])) {
            return (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$messages_table} WHERE thread_id = %d AND (sender_user_id IS NULL OR sender_user_id <> %d)",
                $thread_id,
                $user_id
            ));
        }
        return (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$messages_table} WHERE thread_id = %d AND created_at > %s AND (sender_user_id IS NULL OR sender_user_id <> %d)",
            $thread_id,
            (string) $participant['last_read_at'],
            $user_id
        ));
    }

    private function add_school_request_thread_message($thread_id, $sender_user_id, $sender_role, $body) {
        global $wpdb;
        $thread_id = (int) $thread_id;
        $sender_user_id = (int) $sender_user_id;
        $sender_role = sanitize_key((string) $sender_role);
        $body = trim((string) sanitize_textarea_field((string) $body));
        if ($thread_id < 1 || $body === '') {
            return 0;
        }
        if (!in_array($sender_role, ['staff', 'school', 'system'], true)) {
            $sender_role = 'system';
        }
        $table = $this->get_thread_messages_table();
        $now = current_time('mysql');
        $wpdb->insert($table, [
            'thread_id' => $thread_id,
            'sender_user_id' => $sender_user_id > 0 ? $sender_user_id : null,
            'sender_role' => $sender_role,
            'body' => $body,
            'created_at' => $now,
        ], ['%d', '%d', '%s', '%s', '%s']);
        $message_id = (int) $wpdb->insert_id;
        if ($message_id > 0) {
            $threads_table = $this->get_threads_table();
            $wpdb->update($threads_table, [
                'updated_at' => $now,
                'last_message_at' => $now,
            ], [
                'id' => $thread_id,
            ], ['%s', '%s'], ['%d']);
            if ($sender_user_id > 0) {
                $this->mark_school_request_thread_read($thread_id, $sender_user_id);
            }
        }
        return $message_id;
    }

    private function issue_school_request_chat_token($thread_id, $school_id, $created_by_user_id = 0) {
        global $wpdb;
        $thread_id = (int) $thread_id;
        $school_id = (int) $school_id;
        if ($thread_id < 1 || $school_id < 1) {
            return [];
        }
        try {
            $token = rtrim(strtr(base64_encode(random_bytes(32)), '+/', '-_'), '=');
        } catch (Exception $e) {
            $token = wp_generate_password(48, false, false);
        }
        if ($token === '') {
            return [];
        }
        $hash = hash('sha256', $token);
        $created_at = current_time('mysql');
        $expires_at = date('Y-m-d H:i:s', current_time('timestamp') + ($this->get_school_request_chat_token_ttl_days() * DAY_IN_SECONDS));
        $table = $this->get_thread_tokens_table();
        $ok = $wpdb->insert($table, [
            'thread_id' => $thread_id,
            'school_id' => $school_id,
            'token_hash' => $hash,
            'purpose' => 'school_request_chat',
            'expires_at' => $expires_at,
            'used_at' => null,
            'created_by_user_id' => (int) $created_by_user_id ?: null,
            'created_ip' => $this->get_request_ip_address(),
            'user_agent' => sanitize_text_field(substr((string) ($_SERVER['HTTP_USER_AGENT'] ?? ''), 0, 255)),
            'created_at' => $created_at,
        ], ['%d', '%d', '%s', '%s', '%s', '%s', '%d', '%s', '%s', '%s']);
        if ($ok === false) {
            return [];
        }
        return [
            'token' => $token,
            'expires_at' => $expires_at,
            'thread_id' => $thread_id,
            'school_id' => $school_id,
        ];
    }

    private function validate_school_request_chat_token($school_id, $token, $consume = true) {
        global $wpdb;
        $school_id = (int) $school_id;
        $token = trim((string) $token);
        if ($school_id < 1 || $token === '') {
            return new WP_Error('cmn_thread_token_invalid', 'Invalid secure chat link.');
        }
        if ($this->is_school_request_chat_rate_limited($school_id)) {
            return new WP_Error('cmn_thread_token_rate_limited', 'Too many attempts. Please wait and try again.');
        }
        $hash = hash('sha256', $token);
        $table = $this->get_thread_tokens_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE school_id = %d AND token_hash = %s AND purpose = %s LIMIT 1",
            $school_id,
            $hash,
            'school_request_chat'
        ), ARRAY_A);
        if (!$row) {
            $this->bump_school_request_chat_rate_limit($school_id);
            return new WP_Error('cmn_thread_token_invalid', 'Invalid secure chat link.');
        }
        $expires_at = (string) ($row['expires_at'] ?? '');
        if ($expires_at === '' || strtotime($expires_at) < current_time('timestamp')) {
            $this->bump_school_request_chat_rate_limit($school_id);
            return new WP_Error('cmn_thread_token_expired', 'Secure chat link has expired.');
        }
        if ($consume && !empty($row['used_at'])) {
            $this->bump_school_request_chat_rate_limit($school_id);
            return new WP_Error('cmn_thread_token_used', 'Secure chat link has already been used.');
        }
        $thread_id = (int) ($row['thread_id'] ?? 0);
        if ($thread_id < 1) {
            $this->bump_school_request_chat_rate_limit($school_id);
            return new WP_Error('cmn_thread_token_invalid', 'Invalid secure chat link.');
        }

        $rotation = [];
        if ($consume) {
            $updated = $wpdb->query($wpdb->prepare(
                "UPDATE {$table} SET used_at = %s WHERE id = %d AND used_at IS NULL",
                current_time('mysql'),
                (int) $row['id']
            ));
            if ((int) $updated < 1) {
                $this->bump_school_request_chat_rate_limit($school_id);
                return new WP_Error('cmn_thread_token_used', 'Secure chat link has already been used.');
            }
            $rotation = $this->issue_school_request_chat_token($thread_id, $school_id, 0);
        }
        $this->clear_school_request_chat_rate_limit($school_id);
        return [
            'thread_id' => $thread_id,
            'school_id' => $school_id,
            'token_row_id' => (int) ($row['id'] ?? 0),
            'rotation' => $rotation,
        ];
    }

    private function get_school_request_chat_secure_url($school_id, $token) {
        $school_id = (int) $school_id;
        $token = rawurlencode((string) $token);
        return home_url('/school/requests/' . $school_id . '/chat/' . $token . '/');
    }

    private function resolve_school_request_chat_access($school_id, $token = '', $write = false) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return new WP_Error('cmn_thread_not_found', 'Application not found.');
        }
        $thread = $this->create_or_get_school_request_thread($school_id, get_current_user_id());
        if (!$thread || empty($thread['id'])) {
            return new WP_Error('cmn_thread_not_found', 'Conversation unavailable.');
        }
        $thread_id = (int) $thread['id'];

        $user_id = is_user_logged_in() ? (int) get_current_user_id() : 0;
        if ($user_id > 0) {
            if ($this->user_can_manage_school_request($school_id, $user_id)) {
                $this->sync_school_request_thread_participants($thread_id, $school_id);
                $this->add_school_request_thread_participant($thread_id, $user_id, 'staff');
                return [
                    'thread' => $thread,
                    'thread_id' => $thread_id,
                    'school_id' => $school_id,
                    'user_id' => $user_id,
                    'role' => 'staff',
                    'auth' => 'user',
                    'rotation' => [],
                ];
            }
            if ($this->is_school_user($user_id) && (int) $this->resolve_school_id_for_user($user_id) === $school_id) {
                $this->sync_school_request_thread_participants($thread_id, $school_id);
                $this->add_school_request_thread_participant($thread_id, $user_id, 'school');
                return [
                    'thread' => $thread,
                    'thread_id' => $thread_id,
                    'school_id' => $school_id,
                    'user_id' => $user_id,
                    'role' => 'school',
                    'auth' => 'user',
                    'rotation' => [],
                ];
            }
        }

        $token = trim((string) $token);
        if ($token === '') {
            return new WP_Error('cmn_thread_forbidden', 'Unauthorized.');
        }
        $token_check = $this->validate_school_request_chat_token($school_id, $token, false);
        if (is_wp_error($token_check)) {
            return $token_check;
        }
        if ((int) ($token_check['thread_id'] ?? 0) !== $thread_id) {
            return new WP_Error('cmn_thread_forbidden', 'Unauthorized.');
        }
        return [
            'thread' => $thread,
            'thread_id' => $thread_id,
            'school_id' => $school_id,
            'user_id' => 0,
            'role' => 'school',
            'auth' => 'token',
            'access_token' => $token,
            'rotation' => is_array($token_check['rotation'] ?? null) ? (array) $token_check['rotation'] : [],
        ];
    }

    private function get_school_request_thread_message_sender_label($message_row, $school_id) {
        $sender_role = sanitize_key((string) ($message_row['sender_role'] ?? 'system'));
        $sender_user_id = (int) ($message_row['sender_user_id'] ?? 0);
        if ($sender_user_id > 0) {
            $user = get_user_by('id', $sender_user_id);
            if ($user && !empty($user->display_name)) {
                return (string) $user->display_name;
            }
        }
        if ($sender_role === 'school') {
            $school_name = trim((string) get_the_title($school_id));
            return $school_name !== '' ? $school_name : 'School';
        }
        if ($sender_role === 'staff') {
            return 'Staff';
        }
        return 'System';
    }

    private function get_school_request_thread_payload($thread, $school_id, $viewer_user_id = 0, $viewer_role = 'staff', $access_token = '') {
        $thread_id = (int) ($thread['id'] ?? 0);
        $messages = [];
        foreach ($this->get_school_request_thread_messages($thread_id, 500) as $message_row) {
            $sender_role = sanitize_key((string) ($message_row['sender_role'] ?? 'system'));
            $messages[] = [
                'id' => (int) ($message_row['id'] ?? 0),
                'sender_user_id' => (int) ($message_row['sender_user_id'] ?? 0),
                'sender_role' => $sender_role,
                'sender_label' => $this->get_school_request_thread_message_sender_label($message_row, (int) $school_id),
                'body' => (string) ($message_row['body'] ?? ''),
                'created_at' => (string) ($message_row['created_at'] ?? ''),
                'created_at_label' => !empty($message_row['created_at']) ? date_i18n('M j, Y g:ia', strtotime((string) $message_row['created_at'])) : '',
                'bubble_class' => ($sender_role === 'school') ? 'is-user is-school' : (($sender_role === 'staff') ? 'is-admin is-account_manager' : 'is-system'),
                'attachments' => $this->get_school_request_message_attachments((int) ($message_row['id'] ?? 0), (int) $school_id, (string) $access_token),
            ];
        }

        $status = sanitize_key((string) ($thread['status'] ?? 'open'));
        if (!in_array($status, ['open', 'closed'], true)) {
            $status = 'open';
        }
        $can_manage_status = ($viewer_role === 'staff');
        return [
            'thread_id' => $thread_id,
            'entity_type' => 'school_request',
            'entity_id' => (int) $school_id,
            'status' => $status,
            'status_label' => $status === 'closed' ? 'Closed' : 'Open',
            'can_manage_status' => $can_manage_status,
            'messages' => $messages,
            'unread_count' => ($viewer_user_id > 0) ? $this->get_school_request_thread_unread_count($thread_id, (int) $viewer_user_id) : 0,
            'last_message_at' => (string) ($thread['last_message_at'] ?? ''),
            'last_message_at_label' => !empty($thread['last_message_at']) ? date_i18n('M j, Y g:ia', strtotime((string) $thread['last_message_at'])) : '',
        ];
    }

    private function notify_school_request_staff_about_reply($school_id, $message_body, $exclude_user_id = 0) {
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return;
        }
        $staff_user_ids = $this->get_staff_user_ids_for_school_request($school_id);
        if (!$staff_user_ids) {
            return;
        }
        $school_name = trim((string) get_the_title($school_id));
        if ($school_name === '') {
            $school_name = 'School #' . $school_id;
        }
        $request_ref = sanitize_text_field((string) get_post_meta($school_id, 'cmn_registration_ref', true));
        if ($request_ref === '') {
            $request_ref = 'SR-' . $school_id;
        }
        $link = add_query_arg([
            'view' => 'school-requests',
            'request_id' => $school_id,
        ], $this->get_portal_base_url()) . '#chat';
        $snippet = wp_trim_words((string) $message_body, 28, '...');
        foreach ($staff_user_ids as $staff_user_id) {
            $staff_user_id = (int) $staff_user_id;
            if ($staff_user_id < 1 || $staff_user_id === (int) $exclude_user_id) {
                continue;
            }
            $this->add_notification(
                $staff_user_id,
                'thread_reply',
                'School replied',
                $school_name . ' replied to application ' . $request_ref . '.',
                $link
            );
            $staff_user = get_user_by('id', $staff_user_id);
            $staff_email = $staff_user && !empty($staff_user->user_email) ? sanitize_email((string) $staff_user->user_email) : '';
            if ($staff_email !== '' && is_email($staff_email)) {
                $subject = 'School replied: ' . $school_name . ' - ' . $request_ref;
                $body = "School: {$school_name}\nReference: {$request_ref}\n\nReply:\n{$snippet}\n\nOpen chat: {$link}";
                $this->send_school_email($staff_email, $subject, $body);
                $this->insert_audit('notification_sent_email', 'school', $school_id, [
                    'type' => 'thread_reply',
                    'to_user_id' => $staff_user_id,
                    'to_email' => $staff_email,
                    'subject' => $subject,
                ], get_current_user_id());
            }
        }
    }

    private function notify_school_request_school_about_staff_message($school_id, $message_body, $actor_user_id = 0) {
        $school_id = (int) $school_id;
        if ($school_id < 1) {
            return;
        }
        $thread = $this->create_or_get_school_request_thread($school_id, $actor_user_id);
        if (!$thread || empty($thread['id'])) {
            return;
        }
        $token_pack = $this->issue_school_request_chat_token((int) $thread['id'], $school_id, (int) $actor_user_id);
        $secure_url = !empty($token_pack['token']) ? $this->get_school_request_chat_secure_url($school_id, (string) $token_pack['token']) : '';
        $school_name = trim((string) get_the_title($school_id));
        if ($school_name === '') {
            $school_name = 'School';
        }
        $snippet = wp_trim_words((string) $message_body, 28, '...');

        $emails = [];
        foreach ($this->get_school_user_ids_for_school_request($school_id) as $school_user_id) {
            $school_user = get_user_by('id', (int) $school_user_id);
            if ($school_user && !empty($school_user->user_email)) {
                $emails[] = sanitize_email((string) $school_user->user_email);
            }
        }
        $emails[] = sanitize_email((string) get_post_meta($school_id, 'cmn_primary_contact_email', true));
        $emails[] = sanitize_email((string) get_post_meta($school_id, 'cmn_contact1_email', true));
        $emails[] = sanitize_email((string) get_post_meta($school_id, 'cmn_email', true));
        $emails = array_values(array_unique(array_filter($emails, static function ($email) {
            return $email !== '' && is_email($email);
        })));

        if (!$emails || $secure_url === '') {
            return;
        }

        $subject = 'Update on your school application';
        $body = "Hi {$school_name},\n\nOur team has added an update to your application:\n{$snippet}\n\nReply in the secure chat (not by email):\n{$secure_url}\n\nIf you have any questions, email school@covermenow.co.uk or call 07438 766 532.";
        foreach ($emails as $email) {
            $this->send_school_email($email, $subject, $body);
            $this->insert_audit('notification_sent_email', 'school', $school_id, [
                'type' => 'thread_staff_message',
                'to_email' => $email,
                'subject' => $subject,
            ], (int) $actor_user_id);
        }
    }

    private function render_school_request_thread_messages_html($messages) {
        ob_start();
        if (!$messages) {
            ?>
            <div class="cmn-empty">No messages yet.</div>
            <?php
            return ob_get_clean();
        }
        foreach ($messages as $message) {
            $bubble_class = (string) ($message['bubble_class'] ?? 'is-system');
            ?>
            <div class="cmn-support-bubble cmn-booking-bubble <?php echo esc_attr($bubble_class); ?>">
                <div class="cmn-support-meta"><?php echo esc_html((string) ($message['sender_label'] ?? '')); ?> - <?php echo esc_html((string) ($message['created_at_label'] ?? '')); ?></div>
                <div class="cmn-support-text"><?php echo nl2br(esc_html((string) ($message['body'] ?? ''))); ?></div>
                <?php $chat_attachments = is_array($message['attachments'] ?? null) ? (array) $message['attachments'] : []; ?>
                <?php if ($chat_attachments) : ?>
                    <div class="cmn-support-attachments">
                        <?php foreach ($chat_attachments as $attachment) : ?>
                            <a class="cmn-support-attachment-chip" href="<?php echo esc_url((string) ($attachment['url'] ?? '#')); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html((string) ($attachment['filename'] ?? 'Attachment')); ?></a>
                        <?php endforeach; ?>
                    </div>
                <?php endif; ?>
            </div>
            <?php
        }
        return ob_get_clean();
    }

