                    <span class="cmn-status-chip is-info<?php echo $unread_count > 0 ? '' : ' is-muted'; ?>" data-thread-unread><?php echo esc_html($unread_count > 0 ? ($unread_count . ' unread') : 'No unread'); ?></span>
