                </section>
                <section class="cmn-dashboard-card cmn-school-request-timeline">
                    <h3>Timeline</h3>
                    <?php if ($timeline) : ?>
                        <div class="cmn-school-request-timeline-list">
                            <?php foreach ($timeline as $entry) : ?>
                                <article class="cmn-school-request-timeline-item">
                                    <div class="cmn-support-meta"><?php echo esc_html((string) ($entry['created_at'] ? date_i18n('M j, Y g:ia', strtotime((string) $entry['created_at'])) : '')); ?> - <?php echo esc_html((string) ($entry['actor_name'] ?? 'System')); ?></div>
                                    <div><span class="cmn-status-chip <?php echo esc_attr((string) ($entry['status_class'] ?? 'is-muted')); ?>"><?php echo esc_html((string) ($entry['title'] ?? 'Update')); ?></span></div>
                                    <?php if (!empty($entry['note'])) : ?>
                                        <p><?php echo esc_html((string) $entry['note']); ?></p>
                                    <?php endif; ?>
                                </article>
                            <?php endforeach; ?>
                        </div>
                    <?php else : ?>
                        <div class="cmn-empty">No timeline events yet.</div>
                    <?php endif; ?>
                </section>
            </div>
            <aside class="cmn-school-request-detail-chat">
                <?php echo $this->render_school_request_chat_component($school_id, $thread_payload, 'staff', ''); ?>
            </aside>
        </div>
        <?php
        return $this->render_staff_shell('school_requests', ob_get_clean());
    }

    public function handle_thread_get() {
        $entity_type = sanitize_key((string) ($_REQUEST['entity_type'] ?? 'school_request'));
        $school_id = (int) ($_REQUEST['entity_id'] ?? ($_REQUEST['school_id'] ?? 0));
        $token = sanitize_text_field((string) ($_REQUEST['token'] ?? ''));
        if ($entity_type !== 'school_request') {
            wp_send_json_error(['message' => 'Unsupported thread type.'], 400);
        }
        $access = $this->resolve_school_request_chat_access($school_id, $token, false);
        if (is_wp_error($access)) {
            wp_send_json_error(['message' => $access->get_error_message()], 403);
        }
        $thread = (array) ($access['thread'] ?? []);
        $viewer_user_id = (int) ($access['user_id'] ?? 0);
        $viewer_role = (string) ($access['role'] ?? 'school');
        if ($viewer_user_id > 0) {
            $this->mark_school_request_thread_read((int) ($thread['id'] ?? 0), $viewer_user_id);
        }
        $payload = $this->get_school_request_thread_payload($thread, $school_id, $viewer_user_id, $viewer_role, (string) ($access['access_token'] ?? ''));
        $response = [
            'thread' => $payload,
        ];
        $rotation = is_array($access['rotation'] ?? null) ? (array) $access['rotation'] : [];
        if (!empty($rotation['token'])) {
            $response['token'] = (string) $rotation['token'];
            $response['token_expires_at'] = (string) ($rotation['expires_at'] ?? '');
        }
        wp_send_json_success($response);
    }

    public function handle_thread_post_message() {
        $entity_type = sanitize_key((string) ($_REQUEST['entity_type'] ?? 'school_request'));
        $school_id = (int) ($_REQUEST['entity_id'] ?? ($_REQUEST['school_id'] ?? 0));
        $token = sanitize_text_field((string) ($_REQUEST['token'] ?? ''));
        $body = trim((string) ($_POST['body'] ?? ''));
        $uploaded_attachments = $this->handle_support_attachments_upload('attachments');
        $attachment_ids = is_array($uploaded_attachments['ids'] ?? null) ? (array) $uploaded_attachments['ids'] : [];
        if ($entity_type !== 'school_request') {
            wp_send_json_error(['message' => 'Unsupported thread type.'], 400);
        }
        if ($body === '' && !$attachment_ids) {
            wp_send_json_error(['message' => 'Message or attachment is required.'], 400);
        }
        if ($body === '' && $attachment_ids) {
            $body = 'Attachment uploaded.';
        }
        $access = $this->resolve_school_request_chat_access($school_id, $token, true);
        if (is_wp_error($access)) {
            wp_send_json_error(['message' => $access->get_error_message()], 403);
        }
        if ((string) ($access['auth'] ?? '') === 'user' && !check_ajax_referer('cmn_thread_chat', 'nonce', false) && !check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        $thread = (array) ($access['thread'] ?? []);
        $thread_id = (int) ($thread['id'] ?? 0);
        if ($thread_id < 1) {
            wp_send_json_error(['message' => 'Conversation unavailable.'], 404);
        }

        $viewer_role = (string) ($access['role'] ?? 'school');
        $viewer_user_id = (int) ($access['user_id'] ?? 0);
        $status = sanitize_key((string) ($thread['status'] ?? 'open'));
        if ($status === 'closed' && $viewer_role === 'school') {
            global $wpdb;
            $wpdb->update($this->get_threads_table(), [
                'status' => 'open',
                'updated_at' => current_time('mysql'),
            ], [
                'id' => $thread_id,
            ], ['%s', '%s'], ['%d']);
            $this->insert_audit('school_request_thread_reopened', 'school', $school_id, [
                'thread_id' => $thread_id,
                'reason' => 'school_reply',
            ], $viewer_user_id);
            $thread['status'] = 'open';
        }

        $message_id = $this->add_school_request_thread_message($thread_id, $viewer_user_id, $viewer_role, $body);
        if ($message_id < 1) {
            wp_send_json_error(['message' => 'Unable to post message right now.'], 500);
        }
        if ($attachment_ids) {
            $this->add_school_request_thread_attachments($message_id, $attachment_ids);
        }

        if ($viewer_role === 'school') {
            update_post_meta($school_id, 'cmn_access_request_latest_school_reply', wp_trim_words($body, 30, '...'));
            update_post_meta($school_id, 'cmn_access_request_latest_school_reply_at', current_time('mysql'));
            $this->insert_audit('school_request_school_reply_received', 'school', $school_id, [
                'thread_id' => $thread_id,
                'message_id' => $message_id,
                'reply_excerpt' => wp_trim_words($body, 35, '...'),
            ], $viewer_user_id);
            $this->notify_school_request_staff_about_reply($school_id, $body, $viewer_user_id);
        } else {
            $this->insert_audit('school_request_staff_message_posted', 'school', $school_id, [
                'thread_id' => $thread_id,
                'message_id' => $message_id,
                'message_excerpt' => wp_trim_words($body, 35, '...'),
            ], $viewer_user_id);
            $this->notify_school_request_school_about_staff_message($school_id, $body, $viewer_user_id);
        }

        $thread = $this->get_school_request_thread_by_school_id($school_id);
        if ($viewer_user_id > 0 && $thread) {
            $this->mark_school_request_thread_read((int) ($thread['id'] ?? 0), $viewer_user_id);
        }
        $payload = $this->get_school_request_thread_payload((array) $thread, $school_id, $viewer_user_id, $viewer_role, (string) ($access['access_token'] ?? ''));
        $response = [
            'thread' => $payload,
            'message_id' => $message_id,
        ];
        if (!empty($uploaded_attachments['errors'])) {
            $response['attachment_errors'] = array_values(array_map('sanitize_text_field', (array) $uploaded_attachments['errors']));
        }
        $rotation = is_array($access['rotation'] ?? null) ? (array) $access['rotation'] : [];
        if (!empty($rotation['token'])) {
            $response['token'] = (string) $rotation['token'];
            $response['token_expires_at'] = (string) ($rotation['expires_at'] ?? '');
        }
        wp_send_json_success($response);
    }

    public function handle_thread_mark_read() {
        $entity_type = sanitize_key((string) ($_REQUEST['entity_type'] ?? 'school_request'));
        $school_id = (int) ($_REQUEST['entity_id'] ?? ($_REQUEST['school_id'] ?? 0));
        $token = sanitize_text_field((string) ($_REQUEST['token'] ?? ''));
        if ($entity_type !== 'school_request') {
            wp_send_json_error(['message' => 'Unsupported thread type.'], 400);
        }
        $access = $this->resolve_school_request_chat_access($school_id, $token, false);
        if (is_wp_error($access)) {
            wp_send_json_error(['message' => $access->get_error_message()], 403);
        }
        if ((string) ($access['auth'] ?? '') === 'user' && !check_ajax_referer('cmn_thread_chat', 'nonce', false) && !check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        $thread_id = (int) ($access['thread_id'] ?? 0);
        $viewer_user_id = (int) ($access['user_id'] ?? 0);
        if ($thread_id > 0 && $viewer_user_id > 0) {
            $this->mark_school_request_thread_read($thread_id, $viewer_user_id);
        }
        $response = ['ok' => true];
        $rotation = is_array($access['rotation'] ?? null) ? (array) $access['rotation'] : [];
        if (!empty($rotation['token'])) {
            $response['token'] = (string) $rotation['token'];
            $response['token_expires_at'] = (string) ($rotation['expires_at'] ?? '');
        }
        wp_send_json_success($response);
    }

    public function handle_thread_set_status() {
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if (!check_ajax_referer('cmn_thread_chat', 'nonce', false) && !check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        $school_id = (int) ($_POST['entity_id'] ?? ($_POST['school_id'] ?? 0));
        $status = sanitize_key((string) ($_POST['status'] ?? ''));
        if (!in_array($status, ['open', 'closed'], true)) {
            wp_send_json_error(['message' => 'Invalid status.'], 400);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->user_can_manage_school_request($school_id, $user_id)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $thread = $this->create_or_get_school_request_thread($school_id, $user_id);
        $thread_id = (int) ($thread['id'] ?? 0);
        if ($thread_id < 1) {
            wp_send_json_error(['message' => 'Conversation unavailable.'], 404);
        }
        global $wpdb;
        $wpdb->update($this->get_threads_table(), [
            'status' => $status,
            'updated_at' => current_time('mysql'),
        ], [
            'id' => $thread_id,
        ], ['%s', '%s'], ['%d']);
        $this->insert_audit('school_request_thread_status_changed', 'school', $school_id, [
            'thread_id' => $thread_id,
            'status' => $status,
        ], $user_id);
        $thread = $this->get_school_request_thread_by_school_id($school_id);
        $payload = $this->get_school_request_thread_payload((array) $thread, $school_id, $user_id, 'staff');
        wp_send_json_success(['thread' => $payload]);
    }

    public function handle_thread_download_attachment() {
        $entity_type = sanitize_key((string) ($_REQUEST['entity_type'] ?? 'school_request'));
        if ($entity_type !== 'school_request') {
            wp_die('Unsupported thread type.');
        }
        $school_id = (int) ($_REQUEST['entity_id'] ?? ($_REQUEST['school_id'] ?? 0));
        $token = sanitize_text_field((string) ($_REQUEST['token'] ?? ''));
        $message_id = (int) ($_REQUEST['message_id'] ?? 0);
        $attachment_id = (int) ($_REQUEST['attachment_id'] ?? 0);
        if ($school_id < 1 || $message_id < 1 || $attachment_id < 1) {
            wp_die('Invalid request.');
        }
        $access = $this->resolve_school_request_chat_access($school_id, $token, false);
        if (is_wp_error($access)) {
            wp_die(esc_html($access->get_error_message()));
        }
        $thread_id = (int) ($access['thread_id'] ?? 0);
        if ($thread_id < 1) {
            wp_die('Conversation unavailable.');
        }
        global $wpdb;
        $a_table = $this->get_thread_attachments_table();
        $m_table = $this->get_thread_messages_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT a.attachment_id FROM {$a_table} a INNER JOIN {$m_table} m ON m.id = a.message_id WHERE a.message_id = %d AND a.attachment_id = %d AND m.thread_id = %d LIMIT 1",
            $message_id,
            $attachment_id,
            $thread_id
        ), ARRAY_A);
        if (!$row) {
            wp_die('Attachment not found.');
        }
        $file = get_attached_file($attachment_id);
        if (!$file || !file_exists($file)) {
            wp_die('Attachment file missing.');
        }
        nocache_headers();
        header('Content-Description: File Transfer');
        header('Content-Type: ' . (string) (get_post_mime_type($attachment_id) ?: 'application/octet-stream'));
        header('Content-Disposition: attachment; filename="' . basename($file) . '"');
        header('Content-Length: ' . filesize($file));
        readfile($file);
        exit;
    }

