    public function handle_school_request_chat_route() {
        if (is_admin()) {
            return;
        }
        $path = wp_parse_url((string) ($_SERVER['REQUEST_URI'] ?? ''), PHP_URL_PATH);
        $path = trim((string) $path);
        if ($path === '') {
            return;
        }
        if (!preg_match('#^/school/requests/(\d+)/chat/([A-Za-z0-9\-_]+)/?$#', $path, $m)) {
            return;
        }
        $school_id = (int) ($m[1] ?? 0);
        $token = sanitize_text_field((string) ($m[2] ?? ''));
        if ($school_id < 1) {
            $this->render_school_request_chat_expired_page('Invalid application reference.');
        }

        if (is_user_logged_in()) {
            $user_id = (int) get_current_user_id();
            if ($this->user_can_manage_school_request($school_id, $user_id)) {
                $staff_url = add_query_arg([
                    'view' => 'school-requests',
                    'request_id' => $school_id,
                ], $this->get_portal_base_url()) . '#chat';
                wp_safe_redirect($staff_url);
                exit;
            }
            if ($this->is_school_user($user_id) && (int) $this->resolve_school_id_for_user($user_id) === $school_id) {
                $thread = $this->create_or_get_school_request_thread($school_id, $user_id);
                $access = [
                    'thread' => $thread,
                    'thread_id' => (int) ($thread['id'] ?? 0),
                    'school_id' => $school_id,
                    'user_id' => $user_id,
                    'role' => 'school',
                    'auth' => 'user',
                    'rotation' => [],
                ];
                $this->render_school_request_chat_public_page($school_id, $access);
            }
        }

        $access = $this->resolve_school_request_chat_access($school_id, $token, true);
        if (is_wp_error($access)) {
            $this->render_school_request_chat_expired_page($access->get_error_message());
        }
        $this->render_school_request_chat_public_page($school_id, $access);
    }
    private function send_school_request_status_change_emails($school_id, $new_status, $note = '', $context = []) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [
                'school_sent' => false,
                'manager_sent' => false,
                'targeted_manager' => false,
                'school_email' => '',
                'manager_email' => '',
                'manager_user_id' => 0,
                'status' => '',
            ];
        }

        $status = sanitize_key((string) $new_status);
        $status_map = [
            'approved' => 'Approved',
            'more_info_needed' => 'More Info Needed',
            'rejected' => 'Declined',
        ];
        if (!isset($status_map[$status])) {
            return [
                'school_sent' => false,
                'manager_sent' => false,
                'targeted_manager' => false,
                'school_email' => '',
                'manager_email' => '',
                'manager_user_id' => 0,
                'status' => $status,
            ];
        }

        $note = trim((string) $note);
        $status_label = (string) $status_map[$status];
        $school_name = trim((string) get_the_title($school_id));
        if ($school_name === '') {
            $school_name = 'School #' . $school_id;
        }
        $registration_ref = sanitize_text_field((string) ($context['registration_ref'] ?? get_post_meta($school_id, 'cmn_registration_ref', true)));
        $school_code = sanitize_text_field((string) get_post_meta($school_id, 'cmn_school_id', true));
        $contact_line = 'If you have any questions, email school@covermenow.co.uk or call 07438 766 532.';
        $portal_url = add_query_arg(['view' => 'schools', 'school_id' => $school_id], $this->get_portal_base_url());
        $portal_base_url = $this->get_portal_base_url();
        $login_url = add_query_arg(['view' => 'login'], $portal_base_url);
        $actor_user_id = isset($context['actor_user_id']) ? (int) $context['actor_user_id'] : (int) get_current_user_id();
        $actor_user = $actor_user_id > 0 ? get_user_by('id', $actor_user_id) : null;
        $actor_name = ($actor_user && !empty($actor_user->display_name)) ? (string) $actor_user->display_name : 'System';
        $secure_chat_url = '';
        $thread_for_email = $this->create_or_get_school_request_thread($school_id, $actor_user_id);
        if (is_array($thread_for_email) && !empty($thread_for_email['id'])) {
            $this->sync_school_request_thread_participants((int) $thread_for_email['id'], $school_id);
            $token_for_email = $this->issue_school_request_chat_token((int) $thread_for_email['id'], $school_id, $actor_user_id);
            if (!empty($token_for_email['token'])) {
                $secure_chat_url = $this->get_school_request_chat_secure_url($school_id, (string) $token_for_email['token']);
            }
        }

        $school_email = '';
        $school_email_candidates = [
            sanitize_email((string) get_post_meta($school_id, 'cmn_primary_contact_email', true)),
            sanitize_email((string) get_post_meta($school_id, 'cmn_contact1_email', true)),
            sanitize_email((string) get_post_meta($school_id, 'cmn_email', true)),
        ];
        foreach ($school_email_candidates as $candidate_email) {
            if ($candidate_email !== '' && is_email($candidate_email)) {
                $school_email = $candidate_email;
                break;
            }
        }

        $manager_user_id = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
        if ($manager_user_id < 1) {
            $manager_user_id = (int) get_post_meta($school_id, 'cmn_account_manager_user_id', true);
        }
        $manager_email = '';
        if ($manager_user_id > 0) {
            $manager_user = get_user_by('id', $manager_user_id);
            if ($manager_user && !empty($manager_user->user_email) && is_email((string) $manager_user->user_email)) {
                $manager_email = sanitize_email((string) $manager_user->user_email);
            }
        }
        if ($manager_email === '') {
            $manager_email_meta = sanitize_email((string) get_post_meta($school_id, 'cmn_account_manager_email', true));
            if ($manager_email_meta !== '' && is_email($manager_email_meta)) {
                $manager_email = $manager_email_meta;
            }
        }
        $targeted_manager = ($manager_email !== '');

        $school_subject = '';
        $school_message = '';
        if ($status === 'approved') {
            $school_subject = 'Update: your school application has been approved';
            $school_message = "Hi {$school_name},\n\nYour application has been approved.\n";
            if (!empty($context['convert_to_client'])) {
                $school_message .= "Your account is now being prepared as an active client profile.\n";
            }
            $set_password_url = sanitize_text_field((string) ($context['set_password_url'] ?? ''));
            $school_username = sanitize_text_field((string) ($context['school_username'] ?? ''));
            if ($school_username !== '') {
                $school_message .= "Username: {$school_username}\n";
            }
            if ($set_password_url !== '') {
                $school_message .= "Please set your password here: {$set_password_url}\n";
                $school_message .= "Then log in here: {$login_url}\n";
            } else {
                $school_message .= "Please set your password here, then log in: {$login_url}\n";
            }
        } elseif ($status === 'more_info_needed') {
            $school_subject = 'More information needed for your school application';
            if ($registration_ref !== '') {
                $school_subject .= ' [' . $registration_ref . ']';
            }
            $school_message = "Hi {$school_name},\n\nWe need a little more information before we can complete your application.\n";
            if ($note !== '') {
                $school_message .= "\nInformation needed:\n{$note}\n";
            }
            if ($secure_chat_url !== '') {
                $school_message .= "\nReply in the secure chat (not by email):\n" . $secure_chat_url . "\n";
            } else {
                $school_message .= "\nReply in the secure chat via your latest application link.\n";
            }
        } elseif ($status === 'rejected') {
            $school_subject = 'Update on your school application';
            $school_message = "Hi {$school_name},\n\nThank you for your interest. Unfortunately your application has been declined.\n";
            if ($note !== '') {
                $school_message .= "\nReason:\n{$note}\n";
            }
        }
        if ($registration_ref !== '') {
            $school_message .= "\nReference: {$registration_ref}\n";
        }
        $school_message .= "\n{$contact_line}";

        $manager_subject = 'School application status changed: ' . $school_name;
        $manager_lines = [];
        $manager_lines[] = 'A school application status has changed.';
        $manager_lines[] = '';
        $manager_lines[] = 'School: ' . $school_name;
        if ($school_code !== '') {
            $manager_lines[] = 'School ID: ' . $school_code;
        }
        if ($registration_ref !== '') {
            $manager_lines[] = 'Reference: ' . $registration_ref;
        }
        $manager_lines[] = 'New status: ' . $status_label;
        if ($note !== '') {
            $manager_lines[] = 'Note: ' . $note;
        }
        $manager_lines[] = 'Updated by: ' . $actor_name;
        $manager_lines[] = '';
        $manager_lines[] = 'Open in portal: ' . $portal_url;
        if ($secure_chat_url !== '') {
            $manager_lines[] = 'School secure chat: ' . $secure_chat_url;
        }
        $manager_message = implode("\n", $manager_lines);

        $school_sent = false;
        if ($school_email !== '' && $school_subject !== '' && $school_message !== '') {
            $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
            $GLOBALS['cmn_school_mail_log_type'] = 'school_request_status_change_school';
            $school_sent = $this->send_school_email($school_email, $school_subject, $school_message);
            if ($previous_log_type !== null) {
                $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
            } else {
                unset($GLOBALS['cmn_school_mail_log_type']);
            }
        }

        $manager_sent = false;
        if ($targeted_manager) {
            $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
            $GLOBALS['cmn_school_mail_log_type'] = 'school_request_status_change_manager';
            $manager_sent = $this->send_school_email($manager_email, $manager_subject, $manager_message);
            if ($previous_log_type !== null) {
                $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
            } else {
                unset($GLOBALS['cmn_school_mail_log_type']);
            }
        }

        return [
            'school_sent' => (bool) $school_sent,
            'manager_sent' => (bool) $manager_sent,
            'targeted_manager' => (bool) $targeted_manager,
            'school_email' => (string) $school_email,
            'manager_email' => (string) $manager_email,
            'manager_user_id' => (int) $manager_user_id,
            'status' => (string) $status,
        ];
    }

    public function handle_process_school_request() {
        try {
            if (!is_user_logged_in() || !$this->is_staff_user()) {
                wp_die('Unauthorized');
            }
            $current_user_id = (int) get_current_user_id();
            $can_update_assignment = $this->is_admin_user($current_user_id);
            $school_id = (int) ($_POST['school_id'] ?? 0);
            if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
                wp_die('Invalid school request.');
            }
            if (!$this->user_can_manage_school_request($school_id, $current_user_id)) {
                wp_die('Unauthorized');
            }
            if (
                !isset($_POST['cmn_process_school_request_nonce']) ||
                !wp_verify_nonce((string) $_POST['cmn_process_school_request_nonce'], 'cmn_process_school_request_' . $school_id)
            ) {
                wp_die('Invalid request.');
            }
            $previous_request_status = (string) $this->get_school_access_request_status($school_id);
            $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? add_query_arg(['view' => 'school-requests', 'status' => 'pending'], $this->get_portal_base_url())));
            $decision = sanitize_key((string) ($_POST['cmn_request_decision'] ?? 'assign_only'));
            if ($decision === '') {
                $decision = 'assign_only';
            }
            $allowed_decisions = ['assign_only', 'approved', 'more_info_needed', 'rejected'];
            if (!in_array($decision, $allowed_decisions, true)) {
                wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode('Choose a valid decision.')], $redirect));
                exit;
            }
            $note = sanitize_textarea_field((string) ($_POST['cmn_request_note'] ?? ''));
            $convert_to_client = ((string) ($_POST['cmn_convert_to_client'] ?? '0')) === '1';
            $manager_raw = isset($_POST['cmn_account_manager_user']) ? sanitize_text_field((string) wp_unslash($_POST['cmn_account_manager_user'])) : '__keep__';
            $messages = [];
            $assignment_result = null;
            $new_request_status = '';
            $status_email_result = null;
            $convert_result = null;
            $request_lifecycle_result = null;

            if ($manager_raw !== '__keep__') {
                if (!$can_update_assignment) {
                    wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode('Only admin can change account manager assignment.')], $redirect));
                    exit;
                }
                if (!preg_match('/^\d+$/', $manager_raw)) {
                    wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode('Select a valid account manager option.')], $redirect));
                    exit;
                }
                $assignment_result = $this->assign_account_manager_to_school($school_id, (int) $manager_raw, 'school_request', $current_user_id);
                if (empty($assignment_result['ok'])) {
                    wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode((string) ($assignment_result['message'] ?? 'Unable to update account manager assignment.'))], $redirect));
                    exit;
                }
                $messages[] = ((int) $manager_raw > 0) ? 'Account manager assigned.' : 'Account manager unassigned.';
            }

            if ($decision === 'rejected' && $note === '') {
                wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode('Decline reason is required.')], $redirect));
                exit;
            }
            if ($decision === 'more_info_needed' && $note === '') {
                wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode('Add what information is needed.')], $redirect));
                exit;
            }

            if ($decision === 'approved') {
                update_post_meta($school_id, 'cmn_access_request_status', 'approved');
                update_post_meta($school_id, 'cmn_access_request_processed_at', current_time('mysql'));
                update_post_meta($school_id, 'cmn_access_request_processed_by', $current_user_id);
                update_post_meta($school_id, 'cmn_access_request_processed_ref', (string) get_post_meta($school_id, 'cmn_registration_ref', true));
                delete_post_meta($school_id, 'cmn_access_request_reject_reason');
                delete_post_meta($school_id, 'cmn_access_request_more_info_note');
                $messages[] = 'School request approved.';
                if ($convert_to_client) {
                    $convert_result = $this->convert_school_to_client_and_send_invite($school_id);
                    $messages[] = (string) ($convert_result['message'] ?? 'Client conversion processed.');
                }
                $new_request_status = 'approved';
                $audit_action = 'school_request_approved';
            } elseif ($decision === 'more_info_needed') {
                update_post_meta($school_id, 'cmn_access_request_status', 'more_info_needed');
                update_post_meta($school_id, 'cmn_access_request_processed_at', current_time('mysql'));
                update_post_meta($school_id, 'cmn_access_request_processed_by', $current_user_id);
                update_post_meta($school_id, 'cmn_access_request_processed_ref', (string) get_post_meta($school_id, 'cmn_registration_ref', true));
                update_post_meta($school_id, 'cmn_access_request_more_info_note', $note);
                delete_post_meta($school_id, 'cmn_access_request_reject_reason');
                $messages[] = 'Marked as more info needed.';
                $new_request_status = 'more_info_needed';
                $audit_action = 'school_request_more_info_needed';
            } elseif ($decision === 'rejected') {
                update_post_meta($school_id, 'cmn_access_request_status', 'rejected');
                update_post_meta($school_id, 'cmn_access_request_processed_at', current_time('mysql'));
                update_post_meta($school_id, 'cmn_access_request_processed_by', $current_user_id);
                update_post_meta($school_id, 'cmn_access_request_processed_ref', (string) get_post_meta($school_id, 'cmn_registration_ref', true));
                update_post_meta($school_id, 'cmn_access_request_reject_reason', $note);
                delete_post_meta($school_id, 'cmn_access_request_more_info_note');
                $request_lifecycle_result = $this->apply_school_rejected_lifecycle_state($school_id);
                $messages[] = 'School request declined.';
                if (!empty($request_lifecycle_result['skipped_client'])) {
                    $messages[] = 'Client status preserved.';
                }
                $new_request_status = 'rejected';
                $audit_action = 'school_request_rejected';
            } else {
                $audit_action = 'school_request_assignment_updated';
                if (!$assignment_result) {
                    wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode('Select a decision or assign to an account manager.')], $redirect));
                    exit;
                }
            }

            $thread_for_status_update = $this->create_or_get_school_request_thread($school_id, $current_user_id);
            if (is_array($thread_for_status_update) && !empty($thread_for_status_update['id'])) {
                $thread_for_status_update_id = (int) $thread_for_status_update['id'];
                $this->sync_school_request_thread_participants($thread_for_status_update_id, $school_id);
                if ($decision === 'more_info_needed' && $note !== '') {
                    $this->add_school_request_thread_message($thread_for_status_update_id, $current_user_id, 'staff', $note);
                } elseif ($decision === 'rejected' && $note !== '') {
                    $this->add_school_request_thread_message($thread_for_status_update_id, $current_user_id, 'staff', 'Application declined: ' . $note);
                } elseif ($decision === 'approved') {
                    $this->add_school_request_thread_message($thread_for_status_update_id, $current_user_id, 'staff', 'Application approved.');
                }
            }

            $should_send_status_email = false;
            if ($new_request_status !== '' && $new_request_status !== $previous_request_status) {
                $should_send_status_email = true;
            } elseif (in_array($new_request_status, ['more_info_needed', 'rejected'], true) && $note !== '') {
                // Re-send updates when a fresh note/reason is added on the same status.
                $should_send_status_email = true;
            }
            if ($should_send_status_email) {
                $status_email_result = $this->send_school_request_status_change_emails($school_id, $new_request_status, $note, [
                    'actor_user_id' => $current_user_id,
                    'previous_status' => $previous_request_status,
                    'convert_to_client' => $convert_to_client ? 1 : 0,
                    'set_password_url' => is_array($convert_result) ? (string) ($convert_result['set_password_url'] ?? '') : '',
                    'school_username' => is_array($convert_result) ? (string) ($convert_result['school_username'] ?? '') : '',
                ]);
            }

            $ref = (string) get_post_meta($school_id, 'cmn_registration_ref', true);
            $assignment_changed = false;
            if (is_array($assignment_result)) {
                $assignment_changed = ((int) ($assignment_result['manager_id'] ?? 0) !== (int) ($assignment_result['previous_manager_id'] ?? 0));
            }
            if ($assignment_changed && $decision !== 'assign_only') {
                $this->insert_audit('school_request_assignment_updated', 'school', $school_id, [
                    'school_id' => $school_id,
                    'ref' => $ref,
                    'decision' => $decision,
                    'manager_selection' => $manager_raw,
                    'assignment_result' => $assignment_result,
                    'previous_status' => $previous_request_status,
                ], $current_user_id);
            }
            $this->insert_audit($audit_action, 'school', $school_id, [
                'school_id' => $school_id,
                'ref' => $ref,
                'decision' => $decision,
                'note' => $note,
                'convert_to_client' => $convert_to_client ? 1 : 0,
                'manager_selection' => $manager_raw,
                'assignment_result' => $assignment_result,
                'previous_status' => $previous_request_status,
                'new_status' => $new_request_status,
                'status_email_result' => $status_email_result,
                'request_lifecycle_result' => $request_lifecycle_result,
            ], $current_user_id);

            $message_text = trim(implode(' ', array_filter($messages)));
            if ($message_text === '') {
                $message_text = 'School request updated.';
            }
            wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode($message_text)], $redirect));
            exit;
        } catch (Throwable $e) {
            error_log('[CMN_SCHOOL_REQUEST] handle_process_school_request failed: ' . $e->getMessage());
            $fallback_redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? add_query_arg(['view' => 'school-requests', 'status' => 'pending'], $this->get_portal_base_url())));
            wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode('Application update failed. Please retry.')], $fallback_redirect));
            exit;
        }
    }

    public function handle_approve_school_request() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        $school_id = (int) ($_POST['school_id'] ?? 0);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            wp_die('Invalid school request.');
        }
        if (!$this->user_can_manage_school_request($school_id, (int) get_current_user_id())) {
            wp_die('Unauthorized');
        }
        if (
            !isset($_POST['cmn_approve_school_request_nonce']) ||
            !wp_verify_nonce((string) $_POST['cmn_approve_school_request_nonce'], 'cmn_approve_school_request_' . $school_id)
        ) {
            wp_die('Invalid request.');
        }
        $previous_request_status = (string) $this->get_school_access_request_status($school_id);
        update_post_meta($school_id, 'cmn_access_request_status', 'approved');
        update_post_meta($school_id, 'cmn_access_request_processed_at', current_time('mysql'));
        update_post_meta($school_id, 'cmn_access_request_processed_by', get_current_user_id());
        update_post_meta($school_id, 'cmn_access_request_processed_ref', (string) get_post_meta($school_id, 'cmn_registration_ref', true));
        delete_post_meta($school_id, 'cmn_access_request_reject_reason');
        delete_post_meta($school_id, 'cmn_access_request_more_info_note');
        $status_email_result = null;
        if ($previous_request_status !== 'approved') {
            $status_email_result = $this->send_school_request_status_change_emails($school_id, 'approved', '', [
                'actor_user_id' => (int) get_current_user_id(),
                'previous_status' => $previous_request_status,
            ]);
        }
        $ref = (string) get_post_meta($school_id, 'cmn_registration_ref', true);
        $this->insert_audit('school_request_approved', 'school', $school_id, [
            'school_id' => $school_id,
            'ref' => $ref,
            'status' => 'approved',
            'previous_status' => $previous_request_status,
            'status_email_result' => $status_email_result,
        ], get_current_user_id());
        $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? add_query_arg(['view' => 'school-requests', 'status' => 'pending'], $this->get_portal_base_url())));
        wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode('School request approved.')], $redirect));
        exit;
    }

    public function handle_reject_school_request() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        $school_id = (int) ($_POST['school_id'] ?? 0);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            wp_die('Invalid school request.');
        }
        if (!$this->user_can_manage_school_request($school_id, (int) get_current_user_id())) {
            wp_die('Unauthorized');
        }
        if (
            !isset($_POST['cmn_reject_school_request_nonce']) ||
            !wp_verify_nonce((string) $_POST['cmn_reject_school_request_nonce'], 'cmn_reject_school_request_' . $school_id)
        ) {
            wp_die('Invalid request.');
        }
        $reason = sanitize_textarea_field((string) ($_POST['cmn_reject_reason'] ?? ''));
        if ($reason === '') {
            $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? add_query_arg(['view' => 'school-requests', 'status' => 'pending'], $this->get_portal_base_url())));
            wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode('Reject reason is required.')], $redirect));
            exit;
        }
        $previous_request_status = (string) $this->get_school_access_request_status($school_id);
        update_post_meta($school_id, 'cmn_access_request_status', 'rejected');
        update_post_meta($school_id, 'cmn_access_request_processed_at', current_time('mysql'));
        update_post_meta($school_id, 'cmn_access_request_processed_by', get_current_user_id());
        update_post_meta($school_id, 'cmn_access_request_processed_ref', (string) get_post_meta($school_id, 'cmn_registration_ref', true));
        update_post_meta($school_id, 'cmn_access_request_reject_reason', $reason);
        delete_post_meta($school_id, 'cmn_access_request_more_info_note');
        $request_lifecycle_result = $this->apply_school_rejected_lifecycle_state($school_id);
        $status_email_result = null;
        if ($previous_request_status !== 'rejected') {
            $status_email_result = $this->send_school_request_status_change_emails($school_id, 'rejected', $reason, [
                'actor_user_id' => (int) get_current_user_id(),
                'previous_status' => $previous_request_status,
            ]);
        }
        $ref = (string) get_post_meta($school_id, 'cmn_registration_ref', true);
        $this->insert_audit('school_request_rejected', 'school', $school_id, [
            'school_id' => $school_id,
            'ref' => $ref,
            'status' => 'rejected',
            'reason' => $reason,
            'previous_status' => $previous_request_status,
            'status_email_result' => $status_email_result,
            'request_lifecycle_result' => $request_lifecycle_result,
        ], get_current_user_id());
        $redirect = esc_url_raw((string) ($_POST['cmn_redirect'] ?? add_query_arg(['view' => 'school-requests', 'status' => 'pending'], $this->get_portal_base_url())));
        $reject_message = !empty($request_lifecycle_result['skipped_client']) ? 'School request rejected. Client status preserved.' : 'School request rejected.';
        wp_safe_redirect(add_query_arg(['cmn_school_request_msg' => rawurlencode($reject_message)], $redirect));
        exit;
    }

    private function get_request_received_page_url() {
        $request_page = get_page_by_path('request-received', OBJECT, 'page');
        if ($request_page instanceof WP_Post) {
            return get_permalink((int) $request_page->ID);
        }
        $request_page = cmn_get_page_by_title('Request Received', OBJECT, 'page');
        if ($request_page instanceof WP_Post) {
            return get_permalink((int) $request_page->ID);
        }
        return home_url('/request-received/');
    }

    private function get_public_contact_page_url() {
        $paths = ['contact-us', 'contact'];
        foreach ($paths as $path) {
            $page = get_page_by_path($path, OBJECT, 'page');
            if ($page instanceof WP_Post) {
                return get_permalink((int) $page->ID);
            }
        }
        return home_url('/contact-us/');
    }

    private function normalize_school_registration_signature($school_name, $email, $email_domain) {
        $normalized_name = strtolower(trim(preg_replace('/\s+/', ' ', sanitize_text_field((string) $school_name))));
        $normalized_email = strtolower(trim(sanitize_email((string) $email)));
        $normalized_domain = strtolower(trim(sanitize_text_field((string) $email_domain)));
        return hash('sha256', $normalized_name . '|' . $normalized_email . '|' . $normalized_domain);
    }

    private function get_school_registration_idempotency_key($signature_hash) {
        $signature_hash = strtolower(preg_replace('/[^a-f0-9]/', '', (string) $signature_hash));
        if ($signature_hash === '') {
            return '';
        }
        return 'cmn_school_reg_recent_' . substr($signature_hash, 0, 32);
    }

    private function get_school_request_reference_for_post($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return '';
        }
        $public_ref = strtoupper(trim(sanitize_text_field((string) get_post_meta($school_id, 'cmn_public_reference', true))));
        if ($public_ref !== '') {
            return $public_ref;
        }
        $legacy_ref = strtoupper(trim(sanitize_text_field((string) get_post_meta($school_id, 'cmn_registration_ref', true))));
        if ($legacy_ref !== '') {
            update_post_meta($school_id, 'cmn_public_reference', $legacy_ref);
            return $legacy_ref;
        }
        return '';
    }

    private function cache_recent_school_registration($signature_hash, $school_id, $public_ref, $ttl_seconds = 600) {
        $cache_key = $this->get_school_registration_idempotency_key($signature_hash);
        if ($cache_key === '') {
            return;
        }
        $school_id = (int) $school_id;
        $public_ref = sanitize_text_field((string) $public_ref);
        if ($school_id < 1 || $public_ref === '') {
            return;
        }
        set_transient($cache_key, [
            'ref' => $public_ref,
            'post_id' => $school_id,
            'signature' => $signature_hash,
        ], max(60, (int) $ttl_seconds));
    }

    private function get_recent_school_registration($signature_hash, $window_seconds = 600) {
        $signature_hash = strtolower(trim((string) $signature_hash));
        if ($signature_hash === '') {
            return null;
        }
        $cache_key = $this->get_school_registration_idempotency_key($signature_hash);
        if ($cache_key !== '') {
            $cached = get_transient($cache_key);
            if (is_array($cached) && !empty($cached['ref']) && !empty($cached['post_id'])) {
                $cached_school_id = (int) $cached['post_id'];
                if ($cached_school_id > 0 && get_post_type($cached_school_id) === 'cmn_school') {
                    return [
                        'post_id' => $cached_school_id,
                        'ref' => sanitize_text_field((string) $cached['ref']),
                    ];
                }
            }
        }

        $threshold_ts = max(0, current_time('timestamp') - max(60, (int) $window_seconds));
        $threshold = date('Y-m-d H:i:s', $threshold_ts);
        $query = new WP_Query([
            'post_type' => 'cmn_school',
            'post_status' => 'publish',
            'fields' => 'ids',
            'posts_per_page' => 1,
            'orderby' => 'date',
            'order' => 'DESC',
            'meta_query' => [
                [
                    'key' => 'cmn_registration_signature_hash',
                    'value' => $signature_hash,
                ],
                [
                    'key' => 'cmn_registration_requested_at',
                    'value' => $threshold,
                    'compare' => '>=',
                    'type' => 'DATETIME',
                ],
            ],
        ]);
        if (empty($query->posts)) {
            return null;
        }
        $school_id = (int) $query->posts[0];
        $public_ref = $this->get_school_request_reference_for_post($school_id);
        if ($public_ref === '') {
            return null;
        }
        $this->cache_recent_school_registration($signature_hash, $school_id, $public_ref, $window_seconds);
        return [
            'post_id' => $school_id,
            'ref' => $public_ref,
        ];
    }

    private function generate_school_request_public_reference() {
        $prefix = 'CMN-SCH-';
        $alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
        $max_index = strlen($alphabet) - 1;
        for ($attempt = 0; $attempt < 32; $attempt++) {
            $raw = '';
            for ($i = 0; $i < 6; $i++) {
                try {
                    $idx = random_int(0, $max_index);
                } catch (Throwable $e) {
                    $idx = wp_rand(0, $max_index);
                }
                $raw .= $alphabet[$idx];
            }
            $candidate_ref = $prefix . $raw;
            $existing = get_posts([
                'post_type' => 'cmn_school',
                'post_status' => 'any',
                'posts_per_page' => 1,
                'fields' => 'ids',
                'meta_query' => [
                    'relation' => 'OR',
                    [
                        'key' => 'cmn_public_reference',
                        'value' => $candidate_ref,
                    ],
                    [
                        'key' => 'cmn_registration_ref',
                        'value' => $candidate_ref,
                    ],
                ],
            ]);
            if (empty($existing)) {
                return $candidate_ref;
            }
        }
        return $prefix . strtoupper(substr(wp_hash((string) microtime(true)), 0, 6));
    }

    public function handle_register_school() {
        $started_at = microtime(true);
        $log = function ($stage, $extra = '') use ($started_at) {
            $elapsed = number_format(microtime(true) - $started_at, 4, '.', '');
            $suffix = $extra !== '' ? (' | ' . $extra) : '';
            error_log('[CMN_SCHOOL_REG] ' . $stage . ' @' . $elapsed . 's' . $suffix);
        };
        $log('start');

        $referer_url = wp_get_referer() ?: home_url('/school-registration/');
        $request_received_url = $this->get_request_received_page_url();

        $redirect_error = function ($message) use ($referer_url, $log) {
            $log('validation_failed', $message);
            wp_safe_redirect(add_query_arg([
                'cmn_submitted' => '0',
                'cmn_error' => rawurlencode($message),
            ], $referer_url));
            exit;
        };

        $validation_started = microtime(true);
        if (!isset($_POST['cmn_register_school_nonce']) || !wp_verify_nonce((string) $_POST['cmn_register_school_nonce'], 'cmn_register_school')) {
            $redirect_error('Invalid request. Please try again.');
        }

        $client_token = sanitize_text_field((string) ($_POST['cmn_client_token'] ?? ''));
        $school_name = sanitize_text_field((string) ($_POST['cmn_school_name'] ?? ''));
        $email = sanitize_email((string) ($_POST['cmn_email'] ?? ''));
        $email_domain = $this->get_email_domain($email);
        if ($school_name === '') {
            $redirect_error('School name is required.');
        }
        if ($email_domain === '') {
            $redirect_error('Valid email is required.');
        }
        if (!$this->is_school_registration_domain($email_domain)) {
            $redirect_error('Please use your official school email address (school domain required).');
        }
        $signature_hash = $this->normalize_school_registration_signature($school_name, $email, $email_domain);
        $registration_source = $client_token !== '' ? 'token_form' : 'public_form';
        $log(
            'validation_complete',
            'duration=' . number_format(microtime(true) - $validation_started, 4, '.', '') . 's | domain=' . $email_domain
        );

        $idempotency_started = microtime(true);
        $existing_ref = $this->get_recent_school_registration($signature_hash, 10 * MINUTE_IN_SECONDS);
        if (is_array($existing_ref) && !empty($existing_ref['ref'])) {
            $existing_post_id = (int) ($existing_ref['post_id'] ?? 0);
            if ($existing_post_id > 0 && get_post_type($existing_post_id) === 'cmn_school') {
                $previous_request_status = (string) get_post_meta($existing_post_id, 'cmn_access_request_status', true);
                update_post_meta($existing_post_id, 'cmn_access_request_status', 'pending');
                update_post_meta($existing_post_id, 'cmn_registration_requested_at', current_time('mysql'));
                $this->set_school_access_request_source($existing_post_id, $registration_source);
                delete_post_meta($existing_post_id, 'cmn_access_request_manual_started_at');
                delete_post_meta($existing_post_id, 'cmn_access_request_processed_at');
                delete_post_meta($existing_post_id, 'cmn_access_request_processed_by');
                delete_post_meta($existing_post_id, 'cmn_access_request_processed_ref');
                delete_post_meta($existing_post_id, 'cmn_access_request_reject_reason');
                delete_post_meta($existing_post_id, 'cmn_access_request_more_info_note');
                if ($previous_request_status !== 'pending') {
                    $this->insert_audit('school_request_pending_set', 'school', $existing_post_id, [
                        'source' => sanitize_key((string) $registration_source),
                        'reason' => 'registration_resubmitted',
                        'previous_status' => sanitize_key((string) $previous_request_status),
                    ], (int) get_current_user_id());
                }
            }
            $this->cache_recent_school_registration($signature_hash, $existing_post_id, (string) $existing_ref['ref'], 10 * MINUTE_IN_SECONDS);
            $log(
                'idempotency_hit',
                'duration=' . number_format(microtime(true) - $idempotency_started, 4, '.', '') . 's | ref=' . (string) $existing_ref['ref']
            );
            wp_safe_redirect(add_query_arg([
                'rid' => (string) $existing_ref['ref'],
                'duplicate' => '1',
            ], $request_received_url));
            exit;
        }
        $log('idempotency_miss', 'duration=' . number_format(microtime(true) - $idempotency_started, 4, '.', '') . 's');

        $post_id = 0;
        $user_id = 0;
        $registration_ref = '';

        try {
            $db_started = microtime(true);
            if ($client_token !== '') {
                $token_data = $this->validate_client_token($client_token);
                if (!$token_data || empty($token_data['school_email_domain']) || (string) $token_data['school_email_domain'] !== $email_domain) {
                    $redirect_error('Invalid or expired token.');
                }
                $post_id = (int) $this->get_school_post_id_by_domain($email_domain);
                if ($post_id < 1) {
                    $redirect_error('School not found.');
                }
            } else {
                $post_id = (int) $this->get_school_post_id_by_domain($email_domain);
                if ($post_id < 1) {
                    $inserted = wp_insert_post([
                        'post_type' => 'cmn_school',
                        'post_title' => $school_name,
                        'post_status' => 'publish',
                    ], true);
                    if (is_wp_error($inserted) || (int) $inserted < 1) {
                        $log('school_insert_failed', is_wp_error($inserted) ? $inserted->get_error_message() : 'unknown');
                        $redirect_error('We could not submit your request. Please try again.');
                    }
                    $post_id = (int) $inserted;
                } else {
                    wp_update_post([
                        'ID' => $post_id,
                        'post_title' => $school_name !== '' ? $school_name : (string) get_the_title($post_id),
                    ]);
                }
            }

            $meta_payload = [
                'cmn_location' => sanitize_text_field((string) ($_POST['cmn_location'] ?? '')),
                'cmn_email' => $email,
                'cmn_school_email_domain' => $email_domain,
                'cmn_phone' => sanitize_text_field((string) ($_POST['cmn_phone'] ?? '')),
                'cmn_website' => esc_url_raw((string) ($_POST['cmn_website'] ?? '')),
                'cmn_contact1' => sanitize_text_field((string) ($_POST['cmn_contact1'] ?? '')),
                'cmn_contact_role' => sanitize_text_field((string) ($_POST['cmn_contact_role'] ?? '')),
                'cmn_primary_contact_name' => sanitize_text_field((string) ($_POST['cmn_contact1'] ?? '')),
                'cmn_primary_contact_role' => sanitize_text_field((string) ($_POST['cmn_contact_role'] ?? '')),
                'cmn_primary_contact_email' => $email,
                'cmn_primary_contact_phone' => sanitize_text_field((string) ($_POST['cmn_phone'] ?? '')),
                'cmn_address_line1' => sanitize_text_field((string) ($_POST['cmn_address_line1'] ?? '')),
                'cmn_address_line2' => sanitize_text_field((string) ($_POST['cmn_address_line2'] ?? '')),
                'cmn_town' => sanitize_text_field((string) ($_POST['cmn_town'] ?? '')),
                'cmn_county' => sanitize_text_field((string) ($_POST['cmn_county'] ?? '')),
                'cmn_postcode' => sanitize_text_field((string) ($_POST['cmn_postcode'] ?? '')),
                'cmn_school_type' => sanitize_text_field((string) ($_POST['cmn_school_type'] ?? '')),
                'cmn_pupil_count' => sanitize_text_field((string) ($_POST['cmn_pupil_count'] ?? '')),
                'cmn_supply_frequency' => sanitize_text_field((string) ($_POST['cmn_supply_frequency'] ?? '')),
                'cmn_use_agencies' => sanitize_text_field((string) ($_POST['cmn_use_agencies'] ?? '')),
                'cmn_agency_count' => sanitize_text_field((string) ($_POST['cmn_agency_count'] ?? '')),
                'cmn_notes' => sanitize_textarea_field((string) ($_POST['cmn_notes'] ?? '')),
                'cmn_status' => 'pending',
            ];
            foreach ($meta_payload as $meta_key => $meta_value) {
                $current = (string) get_post_meta($post_id, $meta_key, true);
                if ($current === '' || $meta_key === 'cmn_email' || $meta_key === 'cmn_school_email_domain') {
                    update_post_meta($post_id, $meta_key, $meta_value);
                }
            }
            if (!get_post_meta($post_id, 'cmn_pipeline_stage', true)) {
                update_post_meta($post_id, 'cmn_pipeline_stage', 'new_lead');
            }
            if (!get_post_meta($post_id, 'cmn_school_id', true)) {
                update_post_meta($post_id, 'cmn_school_id', $this->generate_school_id());
            }

            $existing_user = get_user_by('email', $email);
            if ($existing_user && !empty($existing_user->ID)) {
                $user_id = (int) $existing_user->ID;
                update_user_meta($user_id, 'cmn_school_id', (int) $post_id);
            }

            $registration_ref = $this->generate_school_request_public_reference();
            update_post_meta($post_id, 'cmn_public_reference', $registration_ref);
            update_post_meta($post_id, 'cmn_registration_ref', $registration_ref);
            update_post_meta($post_id, 'cmn_registration_requested_at', current_time('mysql'));
            update_post_meta($post_id, 'cmn_registration_signature_hash', $signature_hash);
            $previous_request_status = (string) get_post_meta($post_id, 'cmn_access_request_status', true);
            update_post_meta($post_id, 'cmn_access_request_status', 'pending');
            $this->set_school_access_request_source($post_id, $registration_source);
            delete_post_meta($post_id, 'cmn_access_request_manual_started_at');
            delete_post_meta($post_id, 'cmn_access_request_processed_at');
            delete_post_meta($post_id, 'cmn_access_request_processed_by');
            delete_post_meta($post_id, 'cmn_access_request_processed_ref');
            delete_post_meta($post_id, 'cmn_access_request_reject_reason');
            delete_post_meta($post_id, 'cmn_access_request_more_info_note');
            if ($previous_request_status !== 'pending') {
                $this->insert_audit('school_request_pending_set', 'school', $post_id, [
                    'source' => sanitize_key((string) $registration_source),
                    'reason' => 'registration_submitted',
                    'previous_status' => sanitize_key((string) $previous_request_status),
                ], (int) get_current_user_id());
            }

            if ($client_token !== '') {
                $this->upsert_client_profile($email_domain, [
                    'completion_status' => 'complete',
                    'school_type' => sanitize_text_field((string) ($_POST['cmn_school_type'] ?? '')),
                    'pupil_count' => sanitize_text_field((string) ($_POST['cmn_pupil_count'] ?? '')),
                    'supply_frequency' => sanitize_text_field((string) ($_POST['cmn_supply_frequency'] ?? '')),
                    'uses_agencies' => sanitize_text_field((string) ($_POST['cmn_use_agencies'] ?? '')),
                    'agency_count' => sanitize_text_field((string) ($_POST['cmn_agency_count'] ?? '')),
                    'completed_at' => current_time('mysql'),
                ]);
                $this->mark_client_token_used($client_token);
            }

            $this->cache_recent_school_registration($signature_hash, $post_id, $registration_ref, 10 * MINUTE_IN_SECONDS);
            $log('db_save_complete', 'duration=' . number_format(microtime(true) - $db_started, 4, '.', '') . 's | post_id=' . $post_id);

            $side_effects_started = microtime(true);
            $side_effect_args = [
                (int) $post_id,
                (int) $user_id,
                (string) $registration_ref,
                (string) $registration_source,
            ];
            if (!wp_next_scheduled('cmn_process_school_registration_side_effects', $side_effect_args)) {
                wp_schedule_single_event(time() + 2, 'cmn_process_school_registration_side_effects', $side_effect_args);
            }

            $email_args = [
                (int) $post_id,
                (int) $user_id,
                (string) $registration_ref,
            ];
            if (!wp_next_scheduled('cmn_send_school_registration_emails', $email_args)) {
                wp_schedule_single_event(time() + 5, 'cmn_send_school_registration_emails', $email_args);
            }
            $log(
                'side_effects_queued',
                'duration=' . number_format(microtime(true) - $side_effects_started, 4, '.', '') . 's | ref=' . $registration_ref
            );

            wp_safe_redirect(add_query_arg(['rid' => $registration_ref], $request_received_url));
            exit;
        } catch (Throwable $e) {
            $log('exception', $e->getMessage());
            if ($registration_ref !== '') {
                wp_safe_redirect(add_query_arg([
                    'rid' => $registration_ref,
                    'partial' => '1',
                ], $request_received_url));
                exit;
            }
            $redirect_error('There was a temporary issue submitting your request. Please try again.');
        }
    }

    public function handle_school_registration_side_effects($school_id, $user_id = 0, $registration_ref = '', $source = 'public_form') {
        $school_id = (int) $school_id;
        $user_id = (int) $user_id;
        $registration_ref = sanitize_text_field((string) $registration_ref);
        $source = sanitize_key((string) $source);
        if ($source === '') {
            $source = 'public_form';
        }
        $started_at = microtime(true);
        $log = function ($stage, $extra = '') use ($started_at, $school_id, $registration_ref) {
            $elapsed = number_format(microtime(true) - $started_at, 4, '.', '');
            $suffix = $extra !== '' ? (' | ' . $extra) : '';
            error_log('[CMN_SCHOOL_REG] side_effects ' . $stage . ' @' . $elapsed . 's | school_id=' . $school_id . ' | ref=' . $registration_ref . $suffix);
        };

        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            $log('invalid_school');
            return;
        }
        if ($registration_ref === '') {
            $registration_ref = $this->get_school_request_reference_for_post($school_id);
        }

        $index_started = microtime(true);
        $this->upsert_school_index($school_id);
        $log('index_upserted', 'duration=' . number_format(microtime(true) - $index_started, 4, '.', '') . 's');

        $notify_started = microtime(true);
        $notified_count = $this->maybe_notify_staff_about_school_request($school_id, $registration_ref);
        $log('staff_notified', 'duration=' . number_format(microtime(true) - $notify_started, 4, '.', '') . 's | count=' . (int) $notified_count);

        $audit_started = microtime(true);
        $this->insert_audit('school_request_submitted', 'school', $school_id, [
            'school_id' => (int) $school_id,
            'ref' => (string) $registration_ref,
            'source' => $source,
            'notifications_sent' => (int) $notified_count,
            'async' => true,
        ], $user_id > 0 ? $user_id : 0);
        $log('audit_written', 'duration=' . number_format(microtime(true) - $audit_started, 4, '.', '') . 's');
    }

    public function handle_deferred_school_registration_emails($school_id, $user_id = 0, $ref = '') {
        $school_id = (int) $school_id;
        $user_id = (int) $user_id;
        $ref = sanitize_text_field((string) $ref);
        $started_at = microtime(true);
        $log = function ($stage, $extra = '') use ($started_at, $school_id, $ref) {
            $elapsed = number_format(microtime(true) - $started_at, 4, '.', '');
            $suffix = $extra !== '' ? (' | ' . $extra) : '';
            error_log('[CMN_SCHOOL_REG] deferred_email ' . $stage . ' @' . $elapsed . 's | school_id=' . $school_id . ' | ref=' . $ref . $suffix);
        };
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            $log('invalid_school');
            return;
        }
        $school_name = (string) get_the_title($school_id);
        $school_email = sanitize_email((string) get_post_meta($school_id, 'cmn_email', true));
        $location = sanitize_text_field((string) get_post_meta($school_id, 'cmn_location', true));
        $admin_email = $this->get_admin_recipient_email();
        $subject = 'New School Registration Request';
        $message = "A new school registration request was submitted.\n\nReference: {$ref}\nSchool: {$school_name}\nEmail: {$school_email}\nLocation: {$location}\n\nReview in the CRM.";
        $sent_admin = false;
        if ($admin_email !== '') {
            $sent_admin = (bool) wp_mail($admin_email, $subject, $message);
        }
        $log('admin_email_sent', 'ok=' . ($sent_admin ? '1' : '0'));

        if ($school_email !== '') {
            $ack_subject = 'We received your CoverMeNow request';
            $ack_message = "Thanks for requesting access to CoverMeNow ONE.\n\nReference: {$ref}\n\nOur team will review and confirm next steps shortly.";
            $sent_school = $this->send_school_email($school_email, $ack_subject, $ack_message);
            $log('school_ack_sent', 'ok=' . ($sent_school ? '1' : '0'));
        } else {
            $log('school_ack_skipped', 'missing_school_email');
        }
        $this->trigger_automation_event('school_registered', 'school', (int) $school_id, [
            'registration_source' => 'public_form',
            'automation_meta' => ['source' => 'school_register_deferred'],
            'registration_ref' => $ref,
            'user_id' => $user_id,
        ]);
        $log('automation_event_triggered');
    }

    public function handle_register_candidate() {
        if (!isset($_POST['cmn_register_candidate_nonce']) || !wp_verify_nonce($_POST['cmn_register_candidate_nonce'], 'cmn_register_candidate')) {
            wp_die('Invalid request');
        }

        $candidate_name = sanitize_text_field($_POST['cmn_candidate_name'] ?? '');
        $candidate_email = sanitize_email($_POST['cmn_email'] ?? '');
        $candidate_nationality = sanitize_text_field((string) ($_POST['cmn_nationality'] ?? ''));
        $primary_role_input = sanitize_text_field((string) ($_POST['cmn_primary_role'] ?? ''));
        $role_other_input = sanitize_text_field((string) ($_POST['cmn_roles_other'] ?? ''));
        if ($primary_role_input === '' && isset($_POST['cmn_roles']) && is_array($_POST['cmn_roles']) && !empty($_POST['cmn_roles'][0])) {
            $primary_role_input = sanitize_text_field((string) $_POST['cmn_roles'][0]);
        }
        $primary_role = $primary_role_input === 'Other' ? $role_other_input : $primary_role_input;
        if ($candidate_name === '') {
            wp_die('Candidate name is required.');
        }
        if ($candidate_nationality === '') {
            wp_die('Nationality is required.');
        }
        if ($primary_role === '') {
            wp_die('Primary role is required.');
        }

        $post_id = wp_insert_post([
            'post_type' => 'cmn_candidate',
            'post_title' => $candidate_name,
            'post_status' => 'publish',
        ]);

        if (!is_wp_error($post_id)) {
            update_post_meta($post_id, 'cmn_email', $candidate_email);
            update_post_meta($post_id, 'cmn_phone', sanitize_text_field($_POST['cmn_phone'] ?? ''));
            update_post_meta($post_id, 'cmn_location', sanitize_text_field($_POST['cmn_location'] ?? ''));
            update_post_meta($post_id, 'cmn_nationality', $candidate_nationality);
            update_post_meta($post_id, 'cmn_status', 'approved');
            update_post_meta($post_id, 'cmn_notes', sanitize_textarea_field($_POST['cmn_notes'] ?? ''));
            update_post_meta($post_id, 'cmn_house_number', sanitize_text_field($_POST['cmn_house_number'] ?? ''));
            update_post_meta($post_id, 'cmn_address_line1', sanitize_text_field($_POST['cmn_address_line1'] ?? ''));
            update_post_meta($post_id, 'cmn_address_line2', sanitize_text_field($_POST['cmn_address_line2'] ?? ''));
            update_post_meta($post_id, 'cmn_address_line3', sanitize_text_field($_POST['cmn_address_line3'] ?? ''));
            update_post_meta($post_id, 'cmn_town', sanitize_text_field($_POST['cmn_town'] ?? ''));
            update_post_meta($post_id, 'cmn_county', sanitize_text_field($_POST['cmn_county'] ?? ''));
            update_post_meta($post_id, 'cmn_postcode', sanitize_text_field($_POST['cmn_postcode'] ?? ''));
            update_post_meta($post_id, 'cmn_roles', [$primary_role]);
            update_post_meta($post_id, 'cmn_role_type', $primary_role);
            update_post_meta($post_id, 'cmn_no_dbs', isset($_POST['cmn_no_dbs']) ? '1' : '0');
            update_post_meta($post_id, 'cmn_roles_other', $role_other_input);
            update_post_meta($post_id, 'cmn_driving_licence', sanitize_text_field($_POST['cmn_driving_licence'] ?? ''));
            update_post_meta($post_id, 'cmn_car_owner', sanitize_text_field($_POST['cmn_car_owner'] ?? ''));
            update_post_meta($post_id, 'cmn_travel_distance', sanitize_text_field($_POST['cmn_travel_distance'] ?? ''));
            update_post_meta($post_id, 'cmn_dbs_update_service', sanitize_text_field($_POST['cmn_dbs_update_service'] ?? ''));
            $qts_status = sanitize_key((string) ($_POST['cmn_qts_status'] ?? ''));
            if (!in_array($qts_status, ['yes', 'no'], true)) {
                $qts_status = '';
            }
            update_post_meta($post_id, 'cmn_qts_status', $qts_status);
            $days = isset($_POST['cmn_availability_days']) && is_array($_POST['cmn_availability_days']) ? array_map('sanitize_text_field', $_POST['cmn_availability_days']) : [];
            update_post_meta($post_id, 'cmn_availability_days', $days);
            if (!get_post_meta($post_id, 'cmn_default_rate', true)) {
                update_post_meta($post_id, 'cmn_default_rate', '100');
            }
            $candidate_user_id = 0;
            $user_id = $this->ensure_candidate_user($candidate_name, $candidate_email);
            if ($user_id && !is_wp_error($user_id)) {
                $candidate_user_id = (int) $user_id;
                update_post_meta($post_id, 'cmn_user_id', $candidate_user_id);
                update_user_meta($candidate_user_id, 'cmn_nationality', $candidate_nationality);
                update_user_meta($candidate_user_id, 'role_type', $primary_role);
                $this->send_candidate_verification_email((int) $user_id, $candidate_name, $candidate_email);
            }
            $referral_code_input = sanitize_text_field((string) ($_POST['cmn_referral_code'] ?? ''));
            if ($candidate_user_id > 0 && $referral_code_input !== '') {
                $referral_registration = $this->referrals_record_signup($candidate_user_id, $referral_code_input);
                if (is_wp_error($referral_registration)) {
                    if (function_exists('cmn_audit_log_event')) {
                        cmn_audit_log_event([
                            'module' => 'rewards',
                            'entity_type' => 'candidate',
                            'entity_id' => $candidate_user_id,
                            'event_type' => 'referral_registration_failed',
                            'event_ref' => $referral_code_input,
                            'actor_user_id' => (int) $candidate_user_id,
                            'metadata' => [
                                'code' => $referral_code_input,
                                'error_code' => $referral_registration->get_error_code(),
                                'error_message' => $referral_registration->get_error_message(),
                            ],
                        ]);
                    }
                }
            }
            $cv = $this->handle_file_upload_with_attachment('cmn_cv_file');
            $dbs = $this->handle_file_upload_with_attachment('cmn_dbs_file');
            $id_doc = $this->handle_file_upload_with_attachment('cmn_id_file');

            $this->sync_registered_candidate_doc_upload($post_id, $candidate_user_id, 'cv', $cv);
            $this->sync_registered_candidate_doc_upload($post_id, $candidate_user_id, 'dbs', $dbs);
            $this->sync_registered_candidate_doc_upload($post_id, $candidate_user_id, 'id', $id_doc);
            $uploaded_doc_labels = [];
            if (!empty($cv['attachment_id'])) {
                $uploaded_doc_labels[] = 'CV';
            }
            if (!empty($dbs['attachment_id'])) {
                $uploaded_doc_labels[] = 'DBS';
            }
            if (!empty($id_doc['attachment_id'])) {
                $uploaded_doc_labels[] = 'Photo ID';
            }

            if (!empty($cv['attachment_id'])) {
                $uploaded_at = (string) ($cv['uploaded_at'] ?? current_time('mysql'));
                update_post_meta($post_id, 'cmn_cv_original_attachment_id', (int) $cv['attachment_id']);
                update_post_meta($post_id, 'cmn_cv_original_uploaded_at', $uploaded_at);
                $this->add_candidate_cv_audit_entry(
                    $post_id,
                    'Candidate CV upload',
                    'Candidate uploaded original CV at ' . $uploaded_at . '.',
                    $candidate_user_id > 0 ? $candidate_user_id : get_current_user_id()
                );
                $this->mark_candidate_formatted_cv_outdated($post_id, true);
            }

            $this->trigger_automation_event('candidate_registered', 'candidate', (int) $post_id, [
                'registration_source' => 'public_form',
                'automation_meta' => ['source' => 'candidate_register'],
            ]);
            if (!empty($cv['attachment_id'])) {
                $this->trigger_automation_event('document_uploaded', 'candidate', (int) $post_id, [
                    'doc_type' => 'cv',
                    'automation_meta' => ['source' => 'candidate_register'],
                ]);
            }
            if (!empty($dbs['attachment_id'])) {
                $this->trigger_automation_event('document_uploaded', 'candidate', (int) $post_id, [
                    'doc_type' => 'dbs',
                    'automation_meta' => ['source' => 'candidate_register'],
                ]);
            }
            if (!empty($id_doc['attachment_id'])) {
                $this->trigger_automation_event('document_uploaded', 'candidate', (int) $post_id, [
                    'doc_type' => 'id',
                    'automation_meta' => ['source' => 'candidate_register'],
                ]);
            }
            if ($uploaded_doc_labels) {
                $admin_recipient = $this->get_admin_recipient_email();
                if ($admin_recipient !== '') {
                    $docs_label = implode(', ', $uploaded_doc_labels);
                    $subject = 'Document uploaded by candidate';
                    $message = "A candidate uploaded {$docs_label} during registration.\n\nCandidate: {$candidate_name}\nEmail: {$candidate_email}\n\nReview in the CRM.";
                    wp_mail($admin_recipient, $subject, $message);
                }
                $this->notify_staff_admins(
                    'candidate_document_uploaded',
                    'Candidate document uploaded',
                    $candidate_name . ' uploaded ' . implode(', ', $uploaded_doc_labels) . '.',
                    add_query_arg(['view' => 'compliance-review'], $this->get_portal_base_url()),
                    ['module' => 'compliance', 'urgency' => 'normal']
                );
            }

            $admin_email = $this->get_admin_recipient_email();
            $subject = 'New Candidate Registration Request';
            $message = "A new candidate registration request was submitted.\n\nCandidate: {$candidate_name}\nEmail: {$candidate_email}\nLocation: " . sanitize_text_field($_POST['cmn_location'] ?? '') . "\n\nReview in the CRM.";
            if ($admin_email !== '') {
                $this->send_candidate_email($admin_email, $subject, $message, [
                    'type' => 'candidate_registration_admin',
                    'related_candidate_id' => $post_id,
                ]);
            }

            $this->notify_staff_admins(
                'candidate_registration_submitted',
                'New candidate registration',
                "Candidate: {$candidate_name} ({$candidate_email})",
                add_query_arg(['view' => 'candidates'], $this->get_portal_base_url()),
                ['module' => 'onboarding', 'urgency' => 'normal']
            );
        }

        wp_redirect(add_query_arg([
            'cmn_submitted' => '1',
            'cmn_email' => $candidate_email,
        ], wp_get_referer() ?: home_url()));
        exit;
    }


    private function ensure_school_portal_user_and_reset_link($school_post_id, $primary_email = '') {
        $school_post_id = (int) $school_post_id;
        if ($school_post_id < 1 || get_post_type($school_post_id) !== 'cmn_school') {
            return ['ok' => false, 'message' => 'School not found.'];
        }

        $school_name = trim((string) get_the_title($school_post_id));
        if ($school_name === '') {
            $school_name = 'School';
        }

        $email = sanitize_email((string) $primary_email);
        if ($email === '' || !is_email($email)) {
            $email_candidates = [
                sanitize_email((string) get_post_meta($school_post_id, 'cmn_primary_contact_email', true)),
                sanitize_email((string) get_post_meta($school_post_id, 'cmn_contact1_email', true)),
                sanitize_email((string) get_post_meta($school_post_id, 'cmn_email', true)),
            ];
            foreach ($email_candidates as $candidate_email) {
                if ($candidate_email !== '' && is_email($candidate_email)) {
                    $email = $candidate_email;
                    break;
                }
            }
        }
        if ($email === '' || !is_email($email)) {
            return ['ok' => false, 'message' => 'Primary contact email is missing.'];
        }

        $user = get_user_by('email', $email);
        $user_id = $user && !empty($user->ID) ? (int) $user->ID : 0;
        if ($user_id < 1) {
            $email_local = sanitize_user(strstr($email, '@', true), true);
            if ($email_local === '') {
                $email_local = sanitize_user(strtolower(str_replace(' ', '', $school_name)), true);
            }
            if ($email_local === '') {
                $email_local = 'school';
            }
            $user_login = $email_local;
            $suffix = 1;
            while (username_exists($user_login)) {
                $user_login = $email_local . $suffix;
                $suffix++;
            }
            $password = wp_generate_password(20, true);
            $created_user_id = wp_insert_user([
                'user_login' => $user_login,
                'user_email' => $email,
                'display_name' => $school_name,
                'role' => 'cmn_school_manager',
                'user_pass' => $password,
            ]);
            if (is_wp_error($created_user_id) || (int) $created_user_id < 1) {
                return ['ok' => false, 'message' => 'Unable to create school login user.'];
            }
            $user_id = (int) $created_user_id;
            $user = get_user_by('id', $user_id);
        }

        if ($user && !empty($user->ID)) {
            $roles = (array) $user->roles;
            $is_staff_role = in_array('administrator', $roles, true) || in_array('cmn_admin', $roles, true) || in_array('cmn_staff', $roles, true) || in_array('cmn_account_manager', $roles, true);
            if (!$is_staff_role && !in_array('cmn_school_manager', $roles, true) && !in_array('cmn_school_staff', $roles, true)) {
                $wp_user = new WP_User((int) $user->ID);
                $wp_user->set_role('cmn_school_manager');
            }
            update_user_meta((int) $user->ID, 'cmn_school_id', $school_post_id);
            if ($this->is_school_user((int) $user->ID)) {
                $state_result = $this->ensure_school_partner_state_for_user((int) $user->ID);
                if (is_wp_error($state_result)) {
                    return ['ok' => false, 'message' => 'Unable to initialise school partner profile.'];
                }
            }
        }

        $user = get_user_by('id', $user_id);
        if (!$user || empty($user->ID)) {
            return ['ok' => false, 'message' => 'School login user unavailable.'];
        }

        $reset_key = get_password_reset_key($user);
        if (is_wp_error($reset_key) || !is_string($reset_key) || $reset_key === '') {
            return ['ok' => false, 'message' => 'Unable to generate password setup link.'];
        }

        return [
            'ok' => true,
            'user_id' => (int) $user->ID,
            'username' => (string) $user->user_login,
            'email' => (string) $user->user_email,
            'set_password_url' => (string) $this->get_portal_reset_url((string) $user->user_login, (string) $reset_key),
        ];
    }

    private function normalize_candidate_referral_code($referral_code) {
        $referral_code = strtoupper(trim((string) $referral_code));
        $referral_code = preg_replace('/[^A-Z0-9]/', '', $referral_code);
        if (!is_string($referral_code)) {
            return '';
        }
        return strlen($referral_code) === 8 ? $referral_code : '';
    }

    private function generate_candidate_referral_code_candidate() {
        $alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
        $max_index = strlen($alphabet) - 1;
        $code = '';
        for ($i = 0; $i < 8; $i++) {
            try {
                $idx = random_int(0, $max_index);
            } catch (Throwable $e) {
                $idx = wp_rand(0, $max_index);
            }
            $code .= $alphabet[$idx];
        }
        return $code;
    }

    private function get_user_id_by_candidate_referral_code($referral_code) {
        $referral_code = $this->normalize_candidate_referral_code($referral_code);
        if ($referral_code === '') {
            return 0;
        }
        $users = get_users([
            'number' => 1,
            'fields' => 'ids',
            'meta_key' => 'cmn_referral_code',
            'meta_value' => $referral_code,
        ]);
        if (is_array($users) && !empty($users[0])) {
            return (int) $users[0];
        }
        return 0;
    }

    private function ensure_candidate_referral_code($user_id) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return '';
        }
        $user = get_user_by('id', $user_id);
        if (!$user || !$user->ID) {
            return '';
        }
        $roles = (array) $user->roles;
        $is_candidate_role = in_array('cmn_candidate', $roles, true)
            || in_array('cmn_candidate_pending', $roles, true)
            || in_array('candidate', $roles, true);
        if (!$is_candidate_role) {
            return '';
        }

        $existing_code = $this->normalize_candidate_referral_code((string) get_user_meta($user_id, 'cmn_referral_code', true));
        if ($existing_code !== '') {
            $owner_user_id = $this->get_user_id_by_candidate_referral_code($existing_code);
            if ($owner_user_id === $user_id || $owner_user_id === 0) {
                if ($owner_user_id === 0) {
                    update_user_meta($user_id, 'cmn_referral_code', $existing_code);
                }
                return $existing_code;
            }
        }

        for ($attempt = 0; $attempt < 40; $attempt++) {
            $candidate_code = $this->generate_candidate_referral_code_candidate();
            if ($candidate_code === '') {
                continue;
            }
            $owner_user_id = $this->get_user_id_by_candidate_referral_code($candidate_code);
            if ($owner_user_id > 0 && $owner_user_id !== $user_id) {
                continue;
            }
            update_user_meta($user_id, 'cmn_referral_code', $candidate_code);
            return $candidate_code;
        }
        return '';
    }

    private function ensure_candidate_user($candidate_name, $candidate_email) {
        if ($candidate_email === '') {
            return 0;
        }

        $existing = get_user_by('email', $candidate_email);
        if ($existing) {
            $user = new WP_User($existing->ID);
            if (!in_array('cmn_candidate', (array) $user->roles, true) || in_array('cmn_candidate_pending', (array) $user->roles, true)) {
                $user->set_role('cmn_candidate');
            }
            $this->ensure_candidate_notification_defaults((int) $existing->ID);
            $this->ensure_candidate_referral_code((int) $existing->ID);
            return $existing->ID;
        }

        $base = sanitize_user(strstr($candidate_email, '@', true), true);
        if ($base === '') {
            $base = 'candidate';
        }
        $user_login = $base;
        $suffix = 1;
        while (username_exists($user_login)) {
            $user_login = $base . $suffix;
            $suffix++;
        }

        $password = wp_generate_password(12, false);
        $user_id = wp_insert_user([
            'user_login' => $user_login,
            'user_email' => $candidate_email,
            'display_name' => $candidate_name,
            'role' => 'cmn_candidate',
            'user_pass' => $password,
        ]);

        if ($user_id && !is_wp_error($user_id)) {
            $this->ensure_candidate_notification_defaults((int) $user_id);
            $this->ensure_candidate_referral_code((int) $user_id);
        }

        return $user_id;
    }

    private function is_staff_user_id($user_id) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return false;
        }
        $user = get_user_by('id', $user_id);
        if (!$user || !$user->ID) {
            return false;
        }
        $roles = (array) $user->roles;
        return in_array('administrator', $roles, true)
            || in_array('cmn_admin', $roles, true)
            || in_array('cmn_staff', $roles, true)
            || in_array('cmn_account_manager', $roles, true);
    }

    private function is_staff_user($user_id = 0) {
        $user_id = (int) ($user_id ?: get_current_user_id());
        return $this->is_staff_user_id($user_id);
    }

    private function can_manage_automation($user_id = 0) {
        $user_id = $user_id ?: get_current_user_id();
        if (!$user_id) {
            return false;
        }
        return $this->is_admin_user($user_id)
            || $this->is_staff_role($user_id);
    }

    private function can_manage_candidate_rewards_no_show_overrides($user_id = 0) {
        $user_id = (int) ($user_id ?: get_current_user_id());
        if ($user_id < 1) {
            return false;
        }
        if ($this->is_admin_user($user_id)) {
            return true;
        }
        if (!$this->is_staff_role($user_id)) {
            return false;
        }

        $override_flag_raw = strtolower(trim((string) get_user_meta($user_id, 'cmn_candidate_rewards_override_access', true)));
        $senior_flag_raw = strtolower(trim((string) get_user_meta($user_id, 'cmn_senior_staff', true)));
        $has_override_flag = in_array($override_flag_raw, ['1', 'yes', 'true', 'enabled'], true)
            || in_array($senior_flag_raw, ['1', 'yes', 'true', 'senior'], true);

        return (bool) apply_filters('cmn_candidate_rewards_can_manage_no_show_overrides', $has_override_flag, $user_id);
    }

    private function is_admin_user($user_id = 0) {
        $user = $user_id ? get_user_by('id', $user_id) : wp_get_current_user();
        if (!$user || !$user->ID) {
            return false;
        }
        $roles = (array) $user->roles;
        return in_array('administrator', $roles, true) || in_array('cmn_admin', $roles, true);
    }

    private function is_wordpress_admin_user($user_id = 0) {
        $user = $user_id ? get_user_by('id', $user_id) : wp_get_current_user();
        if (!$user || !$user->ID) {
            return false;
        }
        return in_array('administrator', (array) $user->roles, true);
    }

    private function is_account_manager_user($user_id = 0) {
        $user = $user_id ? get_user_by('id', $user_id) : wp_get_current_user();
        if (!$user || !$user->ID) {
            return false;
        }
        return in_array('cmn_account_manager', (array) $user->roles, true);
    }

    private function is_staff_role($user_id = 0) {
        $user = $user_id ? get_user_by('id', $user_id) : wp_get_current_user();
        if (!$user || !$user->ID) {
            return false;
        }
        return in_array('cmn_staff', (array) $user->roles, true);
    }

    private function is_restricted_account_manager($user_id = 0) {
        $user_id = (int) ($user_id ?: get_current_user_id());
        if ($user_id < 1) {
            return false;
        }
        return $this->is_account_manager_user($user_id) && !$this->is_admin_user($user_id) && !$this->is_staff_role($user_id);
    }

    private function touch_staff_presence($user_id = 0, $force = false) {
        $user_id = (int) ($user_id ?: get_current_user_id());
        if ($user_id < 1 || !$this->is_staff_user_id($user_id)) {
            return;
        }
        $now = time();
        $last_seen = (int) get_user_meta($user_id, 'cmn_last_seen', true);
        if ($force || $last_seen < 1 || ($now - $last_seen) >= 60) {
            update_user_meta($user_id, 'cmn_last_seen', $now);
        }
        if (get_user_meta($user_id, 'cmn_available_online', true) === '') {
            update_user_meta($user_id, 'cmn_available_online', '1');
        }
        if (get_user_meta($user_id, 'cmn_on_annual_leave', true) === '') {
            update_user_meta($user_id, 'cmn_on_annual_leave', '0');
        }
    }

    public function handle_touch_staff_presence() {
        if (!check_ajax_referer('cmn_staff_presence', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_staff_user_id($user_id)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $this->touch_staff_presence($user_id, false);
        $snapshot = $this->get_staff_presence_snapshot($user_id);
        wp_send_json_success([
            'status_key' => (string) ($snapshot['status_key'] ?? 'offline'),
            'label' => (string) ($snapshot['label'] ?? 'Offline'),
            'detail' => (string) ($snapshot['detail'] ?? ''),
        ]);
    }

    private function touch_candidate_presence($user_id = 0, $force = false) {
        $user_id = (int) ($user_id ?: get_current_user_id());
        if ($user_id < 1 || !$this->is_candidate_user($user_id)) {
            return;
        }
        $now = time();
        $last_seen = (int) get_user_meta($user_id, 'cmn_last_seen', true);
        if ($force || $last_seen < 1 || ($now - $last_seen) >= 20) {
            update_user_meta($user_id, 'cmn_last_seen', $now);
        }
    }

    private function format_candidate_last_seen_label($last_seen_ts, $now_ts = 0) {
        $last_seen_ts = (int) $last_seen_ts;
        $now_ts = $now_ts > 0 ? (int) $now_ts : time();
        if ($last_seen_ts < 1) {
            return 'Last seen at --:--';
        }
        $idle_seconds = max(0, $now_ts - $last_seen_ts);
        if ($idle_seconds < 60) {
            return 'Last seen just now';
        }
        if ($idle_seconds < 3600) {
            $minutes = (int) floor($idle_seconds / 60);
            if ($minutes < 1) {
                $minutes = 1;
            }
            return 'Last seen ' . $minutes . ' min' . ($minutes === 1 ? '' : 's') . ' ago';
        }
        if ($idle_seconds < 86400) {
            $hours = (int) floor($idle_seconds / 3600);
            if ($hours < 1) {
                $hours = 1;
            }
            return 'Last seen ' . $hours . ' hour' . ($hours === 1 ? '' : 's') . ' ago';
        }
        try {
            $tz = wp_timezone();
            $now_dt = new DateTime('@' . $now_ts);
            $now_dt->setTimezone($tz);
            $last_seen_dt = new DateTime('@' . $last_seen_ts);
            $last_seen_dt->setTimezone($tz);
            $time_label = $last_seen_dt->format('H:i');
            $today_label = $now_dt->format('Y-m-d');
            $yesterday_label = (clone $now_dt)->modify('-1 day')->format('Y-m-d');
            if ($last_seen_dt->format('Y-m-d') === $yesterday_label) {
                return 'Last seen yesterday at ' . $time_label;
            }
            if ($last_seen_dt->format('Y-m-d') === $today_label) {
                return 'Last seen today at ' . $time_label;
            }
            return 'Last seen ' . $last_seen_dt->format('d/m') . ' at ' . $time_label;
        } catch (Exception $e) {
            return 'Last seen at --:--';
        }
    }

    private function get_candidate_presence_snapshot($user_id, $now_ts = 0) {
        $user_id = (int) $user_id;
        $now_ts = $now_ts > 0 ? (int) $now_ts : time();
        $last_seen = (int) get_user_meta($user_id, 'cmn_last_seen', true);
        if ($last_seen < 1) {
            $last_seen = (int) get_user_meta($user_id, 'cmn_last_login', true);
        }
        $idle_seconds = $last_seen > 0 ? max(0, $now_ts - $last_seen) : PHP_INT_MAX;
        $is_online = $last_seen > 0 && $idle_seconds <= 120;
        $last_online_label = $this->format_candidate_last_seen_label($last_seen, $now_ts);
        if ($is_online) {
            $last_online_label = 'ONLINE NOW';
        }
        return [
            'is_online' => $is_online,
            'last_seen' => $last_seen,
            'last_online_label' => $last_online_label,
        ];
    }

    public function handle_touch_candidate_presence() {
        if (!check_ajax_referer('cmn_candidate_profile', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->is_candidate_user($user_id)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $this->touch_candidate_presence($user_id, false);
        $snapshot = $this->get_candidate_presence_snapshot($user_id);
        wp_send_json_success([
            'is_online' => !empty($snapshot['is_online']) ? 1 : 0,
            'last_seen' => (int) ($snapshot['last_seen'] ?? 0),
            'last_online_label' => (string) ($snapshot['last_online_label'] ?? 'Last seen at --:--'),
        ]);
    }

    private function get_staff_presence_flags($user_id) {
        $user_id = (int) $user_id;
        $online_raw = (string) get_user_meta($user_id, 'cmn_available_online', true);
        $leave_raw = (string) get_user_meta($user_id, 'cmn_on_annual_leave', true);
        $cover_user_id = (int) get_user_meta($user_id, 'cmn_cover_user_id', true);
        return [
            'available_online' => ($online_raw === '') ? true : ($online_raw === '1'),
            'on_annual_leave' => $leave_raw === '1',
            'cover_user_id' => $cover_user_id > 0 ? $cover_user_id : 0,
        ];
    }

    private function is_staff_unavailable($user_id) {
        $user_id = (int) $user_id;
        if ($user_id < 1 || !$this->is_staff_user_id($user_id)) {
            return false;
        }
        $flags = $this->get_staff_presence_flags($user_id);
        return !empty($flags['on_annual_leave']) || empty($flags['available_online']);
    }

    private function get_cover_delegate_users($exclude_user_id = 0) {
        $exclude_user_id = (int) $exclude_user_id;
        $users = get_users([
            'role__in' => ['cmn_account_manager', 'cmn_admin', 'administrator'],
            'orderby' => 'display_name',
            'order' => 'ASC',
        ]);
        $rows = [];
        foreach ((array) $users as $user) {
            if (!$user || empty($user->ID)) {
                continue;
            }
            $uid = (int) $user->ID;
            if ($exclude_user_id > 0 && $uid === $exclude_user_id) {
                continue;
            }
            if ((string) get_user_meta($uid, 'cmn_deactivated', true) === '1') {
                continue;
            }
            $rows[] = $user;
        }
        return $rows;
    }

    private function get_covering_school_ids_for_user($cover_user_id) {
        $cover_user_id = (int) $cover_user_id;
        if ($cover_user_id < 1 || !$this->is_staff_user_id($cover_user_id)) {
            return [];
        }
        $school_ids = get_posts([
            'post_type' => 'cmn_school',
            'post_status' => ['publish', 'draft', 'pending', 'private'],
            'posts_per_page' => 500,
            'fields' => 'ids',
            'meta_query' => [
                'relation' => 'OR',
                [
                    'key' => 'cmn_account_manager_user',
                    'compare' => 'EXISTS',
                ],
                [
                    'key' => 'cmn_account_manager_user_id',
                    'compare' => 'EXISTS',
                ],
            ],
        ]);
        $covered = [];
        foreach ((array) $school_ids as $school_id) {
            $school_id = (int) $school_id;
            if ($school_id < 1) {
                continue;
            }
            $manager_id = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
            if ($manager_id < 1) {
                $manager_id = (int) get_post_meta($school_id, 'cmn_account_manager_user_id', true);
            }
            if ($manager_id < 1 || $manager_id === $cover_user_id) {
                continue;
            }
            $manager_cover_id = (int) get_user_meta($manager_id, 'cmn_cover_user_id', true);
            if ($manager_cover_id !== $cover_user_id) {
                continue;
            }
            if (!$this->is_staff_unavailable($manager_id)) {
                continue;
            }
            $covered[] = $school_id;
        }
        return array_values(array_unique(array_map('intval', $covered)));
    }

    private function get_manageable_school_ids_for_user($user_id) {
        $user_id = (int) $user_id;
        if ($user_id < 1 || !$this->is_restricted_account_manager($user_id)) {
            return [];
        }
        $assigned_ids = $this->get_assigned_school_ids_for_account_manager($user_id);
        $cover_ids = $this->get_covering_school_ids_for_user($user_id);
        return array_values(array_unique(array_map('intval', array_merge($assigned_ids, $cover_ids))));
    }

    public function user_can_manage_school_request($school_id, $user_id = 0) {
        $user_id = (int) ($user_id ?: get_current_user_id());
        $school_id = (int) $school_id;
        if ($user_id < 1 || $school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return false;
        }
        if ($this->is_admin_user($user_id) || $this->is_staff_role($user_id)) {
            return true;
        }
        if ($this->is_restricted_account_manager($user_id)) {
            $manageable_ids = $this->get_manageable_school_ids_for_user($user_id);
            return in_array($school_id, $manageable_ids, true);
        }
        return false;
    }

    private function get_staff_presence_snapshot($user_id, $now_ts = 0) {
        $user_id = (int) $user_id;
        $now_ts = $now_ts > 0 ? (int) $now_ts : time();
        $last_seen = (int) get_user_meta($user_id, 'cmn_last_seen', true);
        if ($last_seen < 1) {
            $last_seen = (int) get_user_meta($user_id, 'cmn_last_login', true);
        }
        $is_deactivated = (string) get_user_meta($user_id, 'cmn_deactivated', true) === '1';
        $flags = $this->get_staff_presence_flags($user_id);
        $status_key = 'offline';
        $label = 'Offline';
        $detail = '';

        if ($is_deactivated) {
            $detail = 'Deactivated';
        } elseif (!empty($flags['on_annual_leave'])) {
            $detail = $last_seen > 0
                ? ('Annual leave - offline for ' . human_time_diff($last_seen, $now_ts))
                : 'Annual leave';
        } elseif (empty($flags['available_online'])) {
            $detail = $last_seen > 0
                ? ('Offline for ' . human_time_diff($last_seen, $now_ts) . ' (manual)')
                : 'Set as offline';
        } else {
            $idle = $last_seen > 0 ? max(0, $now_ts - $last_seen) : PHP_INT_MAX;
            if ($idle < 600) {
                $status_key = 'online';
                $label = 'Online';
                $detail = 'Active now';
            } elseif ($idle < 1800) {
                $status_key = 'away';
                $label = 'Away';
                $detail = $last_seen > 0 ? ('Away for ' . human_time_diff($last_seen, $now_ts)) : 'Away';
            } else {
                $detail = $last_seen > 0 ? ('Offline for ' . human_time_diff($last_seen, $now_ts)) : 'Offline';
            }
        }
        if ($status_key === 'offline' && $last_seen > 0 && $detail === '') {
            $detail = 'Offline for ' . human_time_diff($last_seen, $now_ts);
        }
        return [
            'status_key' => $status_key,
            'label' => $label,
            'detail' => $detail,
            'dot_class' => 'cmn-presence-dot--' . $status_key,
            'last_seen' => $last_seen,
            'available_online' => !empty($flags['available_online']) ? 1 : 0,
            'on_annual_leave' => !empty($flags['on_annual_leave']) ? 1 : 0,
            'cover_user_id' => (int) ($flags['cover_user_id'] ?? 0),
        ];
    }

    private function is_candidate_user($user_id = 0) {
        $user = $user_id ? get_user_by('id', $user_id) : wp_get_current_user();
        if (!$user || !$user->ID) {
            return false;
        }
        $roles = (array) $user->roles;
        return in_array('cmn_candidate', $roles, true)
            || in_array('cmn_candidate_pending', $roles, true)
            || in_array('candidate', $roles, true);
    }

    private function is_school_user($user_id = 0) {
        $user = $user_id ? get_user_by('id', $user_id) : wp_get_current_user();
        if (!$user || !$user->ID) {
            return false;
        }
        $roles = (array) $user->roles;
        return in_array('cmn_school_manager', $roles, true) || in_array('cmn_school_staff', $roles, true);
    }

    public function get_current_user_role() {
        $user = wp_get_current_user();
        if (!$user || !$user->ID) {
            return 'guest';
        }
        if ($this->is_admin_user($user->ID)) {
            return 'admin';
        }
        if ($this->is_account_manager_user($user->ID)) {
            return 'account_manager';
        }
        if ($this->is_staff_role($user->ID)) {
            return 'staff';
        }
        if ($this->is_candidate_user($user->ID)) {
            return 'candidate';
        }
        if ($this->is_school_user($user->ID)) {
            return 'school_user';
        }
        return 'guest';
    }

    private function get_assigned_school_ids_for_account_manager($user_id) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return [];
        }
        $school_ids = [];
        foreach (['cmn_account_manager_user', 'cmn_account_manager_user_id'] as $meta_key) {
            $schools = get_posts([
                'post_type' => 'cmn_school',
                'posts_per_page' => 500,
                'fields' => 'ids',
                'meta_query' => [
                    [
                        'key' => $meta_key,
                        'value' => (string) $user_id,
                    ],
                ],
            ]);
            foreach ((array) $schools as $school_id) {
                $school_ids[] = (int) $school_id;
            }
        }
        return array_values(array_unique(array_map('intval', $school_ids)));
    }

    private function get_assigned_candidate_ids_for_account_manager($user_id) {
        $school_ids = $this->get_assigned_school_ids_for_account_manager($user_id);
        if (!$school_ids) {
            return [];
        }
        $candidate_ids = [];
        foreach ($school_ids as $school_id) {
            $assigned = $this->get_assigned_candidates($school_id);
            foreach ($assigned as $candidate_id) {
                $candidate_ids[] = (int) $candidate_id;
            }
        }
        return array_values(array_unique(array_filter($candidate_ids)));
    }

    private function get_assigned_school_domains_for_account_manager($user_id) {
        $school_ids = $this->get_assigned_school_ids_for_account_manager($user_id);
        if (!$school_ids) {
            return [];
        }
        $domains = [];
        foreach ($school_ids as $school_id) {
            $domain = get_post_meta($school_id, 'cmn_school_email_domain', true);
            if (!$domain) {
                $email = get_post_meta($school_id, 'cmn_email', true);
                $domain = $this->get_email_domain($email);
            }
            if ($domain) {
                $domains[] = strtolower(trim($domain));
            }
        }
        return array_values(array_unique($domains));
    }

    public function user_can_access_school($school_identifier, $user_id = 0) {
        $user_id = $user_id ?: get_current_user_id();
        if (!$user_id) {
            return false;
        }
        if ($this->is_admin_user($user_id) || $this->is_staff_role($user_id)) {
            return true;
        }
        $school_post_id = $this->resolve_school_identifier($school_identifier);
        if (!$school_post_id) {
            return false;
        }
        if ($this->is_account_manager_user($user_id)) {
            $manageable_ids = $this->get_manageable_school_ids_for_user($user_id);
            return in_array((int) $school_post_id, $manageable_ids, true);
        }
        if ($this->is_school_user($user_id)) {
            $user_school_id = $this->resolve_school_id_for_user($user_id);
            return $user_school_id && (int) $user_school_id === (int) $school_post_id;
        }
        return false;
    }

    public function user_can_view_candidate($candidate_id, $user_id = 0) {
        $user_id = $user_id ?: get_current_user_id();
        if (!$user_id || !$candidate_id) {
            return false;
        }
        if ($this->is_admin_user($user_id) || $this->is_staff_role($user_id)) {
            return true;
        }
        if ($this->is_account_manager_user($user_id)) {
            return true;
        }
        if ($this->is_candidate_user($user_id)) {
            $user = get_user_by('id', $user_id);
            $candidate_email = get_post_meta($candidate_id, 'cmn_email', true);
            return $user && $candidate_email && strtolower($candidate_email) === strtolower($user->user_email);
        }
        return false;
    }

    private static function generate_school_id_static() {
        global $wpdb;
        $meta_key = 'cmn_school_id';
        $school_index = $wpdb->prefix . 'cmn_school_index';
        $values = [];
        if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $school_index)) === $school_index) {
            $values = $wpdb->get_col("SELECT school_id FROM {$school_index} WHERE school_id LIKE 'CMN%'");
        } else {
            $values = $wpdb->get_col($wpdb->prepare(
                "SELECT meta_value FROM {$wpdb->postmeta} WHERE meta_key = %s AND meta_value LIKE %s",
                $meta_key,
                'CMN%'
            ));
        }
        $max = 0;
        foreach ($values as $value) {
            if (preg_match('/^CMN(\\d+)$/i', $value, $match)) {
                $num = (int) $match[1];
                if ($num > $max) {
                    $max = $num;
                }
            }
        }
        $next = $max + 1;
        for ($i = 0; $i < 50; $i++) {
            $candidate = 'CMN' . str_pad((string) $next, 4, '0', STR_PAD_LEFT);
            $exists = $wpdb->get_var($wpdb->prepare(
                "SELECT 1 FROM {$school_index} WHERE school_id = %s",
                $candidate
            ));
            if (!$exists) {
                return $candidate;
            }
            $next++;
        }
        return 'CMN' . str_pad((string) ($max + 1), 4, '0', STR_PAD_LEFT);
    }

    private function generate_school_id() {
        return self::generate_school_id_static();
    }

    private function is_super_admin_user() {
        $user = wp_get_current_user();
        if (!$user || !$user->ID) {
