    private function get_school_domains_by_status($status = 'client') {
        $status = sanitize_key((string) $status);
        if (!in_array($status, ['lead', 'client'], true)) {
            return [];
        }
        $posts = get_posts([
            'post_type' => 'cmn_school',
            'posts_per_page' => 1000,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_status',
                    'value' => $status,
                ],
            ],
        ]);
        $domains = [];
        foreach ((array) $posts as $school_id) {
            $domain = strtolower(trim((string) get_post_meta((int) $school_id, 'cmn_school_email_domain', true)));
            if ($domain !== '') {
                $domains[] = $domain;
            }
        }
        return array_values(array_unique($domains));
    }

    private function get_candidate_ids_by_school_domains($domains = []) {
        global $wpdb;
        $domains = array_values(array_unique(array_filter(array_map(function ($value) {
            return strtolower(trim((string) $value));
        }, (array) $domains))));
        if (!$domains) {
            return [0];
        }
        $table = $this->get_candidate_requests_table();
        $placeholders = implode(',', array_fill(0, count($domains), '%s'));
        $sql = "SELECT DISTINCT candidate_id FROM {$table} WHERE candidate_id > 0 AND school_email_domain IN ({$placeholders})";
        $ids = (array) $wpdb->get_col($wpdb->prepare($sql, $domains));
        $ids = array_values(array_unique(array_filter(array_map('intval', $ids))));
        return $ids ?: [0];
    }

