    private function get_email_domain($email) {
        $email = strtolower(trim((string) $email));
        if ($email === '' || strpos($email, '@') === false) {
            return '';
        }
        $parts = explode('@', $email);
        $domain = strtolower(trim(end($parts)));
        return $domain;
    }

    private function is_school_registration_domain($domain) {
        $domain = strtolower(trim((string) $domain));
        if ($domain === '') {
            return false;
        }
        if (!preg_match('/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/', $domain)) {
            return false;
        }

        $blocked_domains = [
            'gmail.com',
            'googlemail.com',
            'yahoo.com',
            'hotmail.com',
            'outlook.com',
            'live.com',
            'icloud.com',
            'me.com',
            'msn.com',
            'aol.com',
            'gmx.com',
            'mail.com',
            'proton.me',
            'protonmail.com',
            'yandex.com',
            'zoho.com',
        ];

        return !in_array($domain, $blocked_domains, true);
    }

