    private function get_school_client_activity_snapshot($school_id) {
        $school_id = (int) $school_id;
        $snapshot = [
            'school_id' => $school_id,
            'invoice_count' => 0,
            'completed_booking_count' => 0,
            'confirmed_completed_days' => 0,
            'partner_lifetime_credits' => 0,
            'partner_lifetime_savings' => 0.0,
            'partner_academic_year_savings' => 0.0,
            'partner_event_count' => 0,
            'has_client_activity' => false,
            'client_activity_signals' => [],
        ];
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return $snapshot;
        }

        global $wpdb;

        $invoices_table = $this->get_invoices_table();
        $snapshot['invoice_count'] = max(0, (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM {$invoices_table}
             WHERE school_id = %d
               AND status <> %s",
            $school_id,
            'void'
        )));

        $partner_row = $this->get_school_partner_record($school_id);
        $snapshot['partner_lifetime_credits'] = max(0, (int) ($partner_row['lifetime_credits'] ?? 0));
        $snapshot['partner_lifetime_savings'] = round(max(0, (float) ($partner_row['lifetime_savings'] ?? 0)), 2);
        $snapshot['partner_academic_year_savings'] = round(max(0, (float) ($partner_row['academic_year_savings'] ?? 0)), 2);

        $events_table = $this->get_school_partner_events_table();
        $events_table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $events_table));
        if ($events_table_exists === $events_table) {
            $snapshot['partner_event_count'] = max(0, (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*)
                 FROM {$events_table}
                 WHERE school_id = %d",
                $school_id
            )));
        }

        $school_user_ids = $this->get_school_user_ids_for_school_list_visibility($school_id);
        foreach ($school_user_ids as $school_user_id) {
            $snapshot['confirmed_completed_days'] += max(0, (int) $this->school_partner_get_confirmed_completed_days($school_user_id));
        }

        $posts_table = $wpdb->posts;
        $meta_table = $wpdb->postmeta;
        $payable_statuses = $this->get_completed_payable_booking_statuses();
        $status_placeholders = implode(',', array_fill(0, count($payable_statuses), '%s'));
        $snapshot['completed_booking_count'] = max(0, (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(DISTINCT p.ID)
             FROM {$posts_table} p
             INNER JOIN {$meta_table} school_meta
               ON school_meta.post_id = p.ID
              AND school_meta.meta_key = 'cmn_school_id'
             LEFT JOIN {$meta_table} status_meta
               ON status_meta.post_id = p.ID
              AND status_meta.meta_key = 'cmn_status'
             WHERE p.post_type = %s
               AND p.post_status NOT IN ('trash', 'auto-draft')
               AND school_meta.meta_value = %s
               AND (
                    status_meta.meta_value IN ({$status_placeholders})
                    OR status_meta.meta_value IS NULL
                    OR status_meta.meta_value = ''
               )",
            array_merge(['cmn_booking', (string) $school_id], $payable_statuses)
        )));

        $signals = [];
        if ($snapshot['invoice_count'] > 0) {
            $signals[] = 'non_void_invoices';
        }
        if ($snapshot['completed_booking_count'] > 0) {
            $signals[] = 'completed_payable_bookings';
        }
        if ($snapshot['confirmed_completed_days'] > 0) {
            $signals[] = 'confirmed_completed_days';
        }
        if ($snapshot['partner_lifetime_credits'] > 0) {
            $signals[] = 'partner_lifetime_credits';
        }
        if ($snapshot['partner_lifetime_savings'] > 0 || $snapshot['partner_academic_year_savings'] > 0) {
            $signals[] = 'partner_savings';
        }
        if ($snapshot['partner_event_count'] > 0) {
            $signals[] = 'partner_events';
        }
        $snapshot['client_activity_signals'] = $signals;
        $snapshot['has_client_activity'] = !empty($signals);

        return $snapshot;
    }

    private function resolve_school_status_target_for_lists($current_status, $activity_snapshot = []) {
        $current_status = sanitize_key((string) $current_status);
        $activity_snapshot = is_array($activity_snapshot) ? $activity_snapshot : [];
        $has_client_activity = !empty($activity_snapshot['has_client_activity']);
        $terminal_statuses = ['archived', 'merged', 'deleted'];

        if (in_array($current_status, $terminal_statuses, true)) {
            return [
                'target_status' => $current_status,
                'reason' => 'terminal_status_preserved',
            ];
        }
        if ($has_client_activity) {
            return [
                'target_status' => 'client',
                'reason' => 'client_activity_detected',
            ];
        }
        if ($current_status === 'lead' || $current_status === 'client') {
            return [
                'target_status' => $current_status,
                'reason' => 'existing_list_status_kept',
            ];
        }
        return [
            'target_status' => 'lead',
            'reason' => 'default_sales_pipeline_status',
        ];
    }

    /*
     * Acceptance tests:
     * - A partner school that is also a client appears in Clients -> Schools.
     * - A partner-eligible school appears in Partner Programme.
     * - A lead school appears in Sales -> Schools.
     * - Debug report clearly explains inclusion/exclusion for any school user.
     * - No hardcoded school names.
     */
    private function get_school_visibility_report($school_user_id) {
        $school_user_id = (int) $school_user_id;
        $school_user = $school_user_id > 0 ? get_user_by('id', $school_user_id) : null;
        $user_roles = $school_user instanceof WP_User ? array_values((array) $school_user->roles) : [];
        $mapped_school_id = $school_user_id > 0 ? (int) get_user_meta($school_user_id, 'cmn_school_id', true) : 0;
        $resolved_school_id = $school_user_id > 0 ? (int) $this->resolve_school_id_for_user($school_user_id) : 0;
        $school_id = $resolved_school_id > 0 ? $resolved_school_id : $mapped_school_id;

        $report = [
            'school_user_id' => $school_user_id,
            'school_post_id' => $school_id,
            'role' => $user_roles,
            'key_meta_fields' => [
                'user_cmn_school_id' => $mapped_school_id,
                'resolved_school_id' => $resolved_school_id,
                'post_status' => '',
                'cmn_status' => '',
                'cmn_pipeline_stage' => '',
                'cmn_school_id' => '',
                'cmn_school_email_domain' => '',
                'cmn_email' => '',
            ],
            'partner_tier_state' => [
                'partner_table' => [],
                'school_partner_state' => [],
            ],
            'client_status_flag' => [
                'has_client_activity' => false,
                'target_status' => '',
                'target_reason' => 'missing_school_record',
                'activity_snapshot' => [],
            ],
            'sales_pipeline_stage' => '',
            'in_partner_programme' => [
                'included' => false,
                'reason' => 'No mapped school record.',
            ],
            'in_sales_schools' => [
                'included' => false,
                'reason' => 'No mapped school record.',
            ],
            'in_client_schools' => [
                'included' => false,
                'reason' => 'No mapped school record.',
            ],
        ];

        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return $report;
        }

        $post = get_post($school_id);
        $post_status = $post ? (string) $post->post_status : '';
        $status_meta_raw = sanitize_key((string) get_post_meta($school_id, 'cmn_status', true));
        $pipeline_stage = sanitize_key((string) get_post_meta($school_id, 'cmn_pipeline_stage', true));
        $status_for_list = $this->normalize_school_status_for_lists($status_meta_raw);
        $allowed_post_statuses = $this->get_school_list_post_statuses();

        $activity_snapshot = $this->get_school_client_activity_snapshot($school_id);
        $target_payload = $this->resolve_school_status_target_for_lists($status_meta_raw, $activity_snapshot);
        $target_status = sanitize_key((string) ($target_payload['target_status'] ?? ''));
        $target_reason = sanitize_key((string) ($target_payload['reason'] ?? ''));

        $report['key_meta_fields'] = [
            'user_cmn_school_id' => $mapped_school_id,
            'resolved_school_id' => $resolved_school_id,
            'post_status' => $post_status,
            'cmn_status' => $status_meta_raw,
            'cmn_pipeline_stage' => $pipeline_stage,
            'cmn_school_id' => (string) get_post_meta($school_id, 'cmn_school_id', true),
            'cmn_school_email_domain' => (string) get_post_meta($school_id, 'cmn_school_email_domain', true),
            'cmn_email' => (string) get_post_meta($school_id, 'cmn_email', true),
        ];

        $partner_row = $this->get_school_partner_record($school_id);
        $report['partner_tier_state']['partner_table'] = [
            'tier' => (string) ($partner_row['tier'] ?? 'standard'),
            'lifetime_credits' => max(0, (int) ($partner_row['lifetime_credits'] ?? 0)),
            'discount_percent' => round((float) ($partner_row['discount_percent'] ?? 0), 2),
            'lifetime_savings' => round((float) ($partner_row['lifetime_savings'] ?? 0), 2),
            'academic_year_savings' => round((float) ($partner_row['academic_year_savings'] ?? 0), 2),
        ];

        $state_rows = [];
        $state_table = $this->get_school_partner_state_table();
        global $wpdb;
        $state_table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $state_table));
        $school_user_ids = $this->get_school_user_ids_for_school_list_visibility($school_id);
        if ($state_table_exists === $state_table && !empty($school_user_ids)) {
            $ids_placeholders = implode(',', array_fill(0, count($school_user_ids), '%d'));
            $query = $wpdb->prepare(
                "SELECT school_user_id, current_tier, discount_pct, confirmed_completed_days, manual_days_adjustment, updated_at
                 FROM {$state_table}
                 WHERE school_user_id IN ({$ids_placeholders})
                 ORDER BY school_user_id ASC",
                ...$school_user_ids
            );
            $rows = (array) $wpdb->get_results($query, ARRAY_A);
            foreach ($rows as $row) {
                $state_rows[] = [
                    'school_user_id' => (int) ($row['school_user_id'] ?? 0),
                    'current_tier' => (string) ($row['current_tier'] ?? 'standard'),
                    'discount_pct' => round((float) ($row['discount_pct'] ?? 0), 2),
                    'confirmed_completed_days' => max(0, (int) ($row['confirmed_completed_days'] ?? 0)),
                    'manual_days_adjustment' => (int) ($row['manual_days_adjustment'] ?? 0),
                    'updated_at' => (string) ($row['updated_at'] ?? ''),
                ];
            }
        }
        $report['partner_tier_state']['school_partner_state'] = $state_rows;

        $report['client_status_flag'] = [
            'has_client_activity' => !empty($activity_snapshot['has_client_activity']),
            'target_status' => $target_status,
            'target_reason' => $target_reason,
            'activity_snapshot' => $activity_snapshot,
        ];
        $report['sales_pipeline_stage'] = $pipeline_stage;

        $partner_included = in_array($post_status, $allowed_post_statuses, true);
        if ($partner_included) {
            $report['in_partner_programme'] = [
                'included' => true,
                'reason' => 'cmn_school record uses a partner-programme-visible internal post status.',
            ];
        } else {
            $report['in_partner_programme'] = [
                'included' => false,
                'reason' => "Post status '{$post_status}' is outside the Partner Programme contract.",
            ];
        }

        if (!$partner_included) {
            $report['in_sales_schools'] = [
                'included' => false,
                'reason' => 'School record is outside Sales/Clients post-status contract.',
            ];
            $report['in_client_schools'] = [
                'included' => false,
                'reason' => 'School record is outside Sales/Clients post-status contract.',
            ];
            return $report;
        }

        if ($status_for_list === 'lead') {
            $report['in_sales_schools'] = [
                'included' => true,
                'reason' => "cmn_status='lead' satisfies Sales -> Schools contract.",
            ];
        } else {
            $report['in_sales_schools'] = [
                'included' => false,
                'reason' => "cmn_status='{$status_meta_raw}' does not satisfy Sales -> Schools (expected 'lead').",
            ];
        }

        if ($status_for_list === 'client') {
            $report['in_client_schools'] = [
                'included' => true,
                'reason' => "cmn_status='client' satisfies Clients -> Schools contract.",
            ];
        } else {
            $report['in_client_schools'] = [
                'included' => false,
                'reason' => "cmn_status='{$status_meta_raw}' does not satisfy Clients -> Schools (expected 'client').",
            ];
        }

        return $report;
    }

    private function reconcile_single_school_list_visibility($school_id, $dry_run = true, $actor_user_id = 0, $trigger = 'manual') {
        $school_id = (int) $school_id;
        $actor_user_id = max(0, (int) $actor_user_id);
        $trigger = sanitize_key((string) $trigger);
        if ($trigger === '') {
            $trigger = 'manual';
        }
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [
                'school_id' => $school_id,
                'updated' => false,
                'would_update' => false,
                'reason' => 'invalid_school',
                'before' => [],
                'after' => [],
                'activity_snapshot' => [],
            ];
        }

        $current_status = sanitize_key((string) get_post_meta($school_id, 'cmn_status', true));
        $current_pipeline_stage = sanitize_key((string) get_post_meta($school_id, 'cmn_pipeline_stage', true));
        $activity_snapshot = $this->get_school_client_activity_snapshot($school_id);
        $target_payload = $this->resolve_school_status_target_for_lists($current_status, $activity_snapshot);
        $target_status = sanitize_key((string) ($target_payload['target_status'] ?? $current_status));
        $target_reason = sanitize_key((string) ($target_payload['reason'] ?? 'no_change'));
        $target_pipeline_stage = $current_pipeline_stage;

        if ($target_status === 'client' && $current_pipeline_stage !== 'lost') {
            $target_pipeline_stage = 'won';
        } elseif ($target_status === 'lead' && $current_pipeline_stage === '') {
            $target_pipeline_stage = 'new_lead';
        }

        $before = [
            'cmn_status' => $current_status,
            'cmn_pipeline_stage' => $current_pipeline_stage,
        ];
        $after = [
            'cmn_status' => $target_status,
            'cmn_pipeline_stage' => $target_pipeline_stage,
        ];
        $would_update = ($before['cmn_status'] !== $after['cmn_status']) || ($before['cmn_pipeline_stage'] !== $after['cmn_pipeline_stage']);
        $updated = false;

        if ($would_update && !$dry_run) {
            if ($before['cmn_status'] !== $after['cmn_status']) {
                update_post_meta($school_id, 'cmn_status', $after['cmn_status']);
            }
            if ($before['cmn_pipeline_stage'] !== $after['cmn_pipeline_stage']) {
                update_post_meta($school_id, 'cmn_pipeline_stage', $after['cmn_pipeline_stage']);
            }
            $updated = true;

            $audit_metadata = [
                'trigger' => $trigger,
                'before' => $before,
                'after' => $after,
                'target_reason' => $target_reason,
                'client_activity_signals' => (array) ($activity_snapshot['client_activity_signals'] ?? []),
            ];
            $this->add_audit_log('school_list_visibility_reconciled', 'school', (string) $school_id, $audit_metadata, $actor_user_id);
            if (function_exists('cmn_audit_log_event')) {
                cmn_audit_log_event([
                    'module' => 'crm',
                    'entity_type' => 'school',
                    'entity_id' => $school_id,
                    'event_type' => 'school_list_visibility_reconciled',
                    'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                    'metadata' => $audit_metadata,
                ]);
            }
        }

        return [
            'school_id' => $school_id,
            'updated' => $updated,
            'would_update' => $would_update,
            'reason' => $target_reason,
            'before' => $before,
            'after' => $after,
            'activity_snapshot' => $activity_snapshot,
        ];
    }

    /*
     * Acceptance tests:
     * - Reconcile scan can run dry-run without changing school status metadata.
     * - Apply mode updates stale list flags and logs before/after state changes.
     * - Unmapped school users are surfaced in summary for follow-up.
     */
    private function run_school_list_visibility_reconciliation($dry_run = true, $actor_user_id = 0, $trigger = 'manual') {
        $dry_run = (bool) $dry_run;
        $actor_user_id = max(0, (int) $actor_user_id);
        $trigger = sanitize_key((string) $trigger);
        if ($trigger === '') {
            $trigger = 'manual';
        }

        $school_ids = get_posts([
            'post_type' => 'cmn_school',
            'post_status' => $this->get_school_list_post_statuses(),
            'posts_per_page' => -1,
            'fields' => 'ids',
        ]);
        $school_ids = array_values(array_unique(array_filter(array_map('intval', (array) $school_ids))));

        // Also include school accounts that may have stale/missing post mappings.
        $school_users = get_users([
            'role__in' => ['cmn_school_manager', 'cmn_school_staff'],
            'fields' => ['ID'],
            'number' => -1,
        ]);
        $missing_mapped_school_users = [];
        foreach ((array) $school_users as $school_user) {
            $uid = (int) ($school_user->ID ?? 0);
            if ($uid < 1) {
                continue;
            }
            $resolved_school_id = (int) $this->resolve_school_id_for_user($uid);
            if ($resolved_school_id > 0) {
                $school_ids[] = $resolved_school_id;
            } else {
                $missing_mapped_school_users[] = $uid;
            }
        }
        $school_ids = array_values(array_unique(array_filter(array_map('intval', $school_ids))));

        $summary = [
            'dry_run' => $dry_run,
            'trigger' => $trigger,
            'scanned_schools' => 0,
            'would_update' => 0,
            'updated' => 0,
            'unchanged' => 0,
            'missing_mapped_school_users' => $missing_mapped_school_users,
            'changes' => [],
        ];

        foreach ($school_ids as $school_id) {
            $result = $this->reconcile_single_school_list_visibility($school_id, $dry_run, $actor_user_id, $trigger);
            $summary['scanned_schools']++;
            if (!empty($result['would_update'])) {
                $summary['would_update']++;
            } elseif (empty($result['updated'])) {
                $summary['unchanged']++;
            }
            if (!empty($result['updated'])) {
                $summary['updated']++;
            }
            if (!empty($result['would_update']) || !empty($result['updated'])) {
                $summary['changes'][] = $result;
            }
        }

        $run_audit = [
            'dry_run' => $dry_run ? 1 : 0,
            'trigger' => $trigger,
            'scanned_schools' => (int) $summary['scanned_schools'],
            'would_update' => (int) $summary['would_update'],
            'updated' => (int) $summary['updated'],
            'unchanged' => (int) $summary['unchanged'],
            'missing_mapped_school_users' => array_values(array_map('intval', (array) $summary['missing_mapped_school_users'])),
        ];
        $this->add_audit_log('school_list_visibility_reconcile_run', 'system', 'school_lists', $run_audit, $actor_user_id);
        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'crm',
                'entity_type' => 'system',
                'entity_id' => 'school_lists',
                'event_type' => 'school_list_visibility_reconcile_run',
                'actor_user_id' => $actor_user_id > 0 ? $actor_user_id : null,
                'metadata' => $run_audit,
            ]);
        }

        return $summary;
    }

    public function handle_reconcile_school_lists() {
        if (!is_user_logged_in() || !$this->is_admin_user(get_current_user_id()) || !current_user_can('manage_options')) {
            wp_die('Not authorised.');
        }
        if (!isset($_POST['cmn_reconcile_school_lists_nonce']) || !wp_verify_nonce($_POST['cmn_reconcile_school_lists_nonce'], 'cmn_reconcile_school_lists')) {
            wp_die('Invalid request');
        }

        $dry_run = !empty($_POST['cmn_dry_run']);
        $actor_user_id = (int) get_current_user_id();
        $summary = $this->run_school_list_visibility_reconciliation($dry_run, $actor_user_id, 'admin_reconcile_button');

        $portal_fallback = add_query_arg(['view' => 'school-partner-admin'], $this->get_portal_base_url());
        $return_url_raw = esc_url_raw((string) ($_POST['cmn_return_url'] ?? $portal_fallback));
        $return_url = wp_validate_redirect($return_url_raw, $portal_fallback);
        $msg = sprintf(
            '%s complete. Scanned: %d, Would update: %d, Updated: %d, Unchanged: %d, Unmapped school users: %d.',
            $dry_run ? 'Dry-run reconcile' : 'Reconcile',
            (int) ($summary['scanned_schools'] ?? 0),
            (int) ($summary['would_update'] ?? 0),
            (int) ($summary['updated'] ?? 0),
            (int) ($summary['unchanged'] ?? 0),
            count((array) ($summary['missing_mapped_school_users'] ?? []))
        );
        $msg_type = (!empty($summary['missing_mapped_school_users'])) ? 'warning' : 'success';
        $args = [
            'cmn_sp_admin_msg' => rawurlencode($msg),
            'cmn_sp_admin_msg_type' => $msg_type,
        ];
        wp_safe_redirect(add_query_arg($args, $return_url));
        exit;
    }

    private function upsert_school_index($post_id) {
        global $wpdb;
        $school_id = get_post_meta($post_id, 'cmn_school_id', true);
        if (!$school_id) {
            $school_id = $this->generate_school_id();
            update_post_meta($post_id, 'cmn_school_id', $school_id);
        }
        $school_id = $this->normalize_school_id($school_id);
        $name = get_the_title($post_id);
        $email = get_post_meta($post_id, 'cmn_email', true);
        $domain = $this->get_email_domain($email);
        if ($domain) {
            $existing = $this->get_school_post_id_by_domain($domain);
            if ($existing && (int) $existing !== (int) $post_id) {
                return $school_id;
            }
            update_post_meta($post_id, 'cmn_school_email_domain', $domain);
        }
        $table = $this->get_school_index_table();
        $wpdb->replace($table, [
            'school_id' => $school_id,
            'post_id' => (int) $post_id,
            'name' => $name,
            'school_email' => $email,
            'school_email_domain' => $domain ?: null,
            'updated_at' => current_time('mysql'),
        ], ['%s', '%d', '%s', '%s', '%s', '%s']);
        return $school_id;
    }

    private function get_school_post_id_by_school_id($school_id) {
        global $wpdb;
        $school_id = $this->normalize_school_id($school_id);
        if ($school_id === '' || preg_match('/^CMN\d{4,}$/', $school_id) !== 1) {
            $this->log_school_id_resolution('invalid_format', [
                'school_id' => $school_id !== '' ? $school_id : '(empty)',
            ]);
            return 0;
        }

        $allowed_statuses = $this->get_school_lookup_post_statuses();
        $indexed_post_id = 0;
        $table = $this->get_school_index_table();
        $index_match = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT post_id FROM {$table} WHERE school_id = %s LIMIT 1",
            $school_id
        ));
        if ($index_match > 0) {
            $index_post = get_post($index_match);
            if (
                $index_post instanceof WP_Post
                && $index_post->post_type === 'cmn_school'
                && in_array((string) $index_post->post_status, $allowed_statuses, true)
            ) {
                $indexed_post_id = (int) $index_match;
            }
        }

        $lookup_args = [
            'post_type' => 'cmn_school',
            'post_status' => $allowed_statuses,
            'posts_per_page' => 1,
            'orderby' => 'date',
            'order' => 'DESC',
            'fields' => 'ids',
            'no_found_rows' => true,
            'update_post_meta_cache' => false,
            'update_post_term_cache' => false,
            'cache_results' => false,
            'suppress_filters' => true,
            'meta_query' => [
                [
                    'key' => 'cmn_school_id',
                    'value' => $school_id,
                    'compare' => '=',
                ],
            ],
        ];
        $ids = array_values(array_filter(array_map('intval', (array) get_posts($lookup_args))));
        if ($ids) {
            $post_id = (int) $ids[0];
            $dupe_args = $lookup_args;
            $dupe_args['posts_per_page'] = 5;
            $dupes = array_values(array_unique(array_filter(array_map('intval', (array) get_posts($dupe_args)))));
            if (count($dupes) > 1) {
                $this->log_school_id_resolution('duplicate_school_id', [
                    'school_id' => $school_id,
                    'post_ids' => $dupes,
                ]);
            }
            if ($post_id > 0 && $post_id !== $indexed_post_id) {
                $this->upsert_school_index($post_id);
            }
            return $post_id;
        }

        if ($indexed_post_id > 0) {
            return $indexed_post_id;
        }
        return 0;
    }

    private function get_school_post_id_by_domain($domain) {
        global $wpdb;
        $domain = strtolower(trim((string) $domain));
        if ($domain === '') {
            return 0;
        }
        $table = $this->get_school_index_table();
        $post_id = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT post_id FROM {$table} WHERE school_email_domain = %s LIMIT 1",
            $domain
        ));
        if ($post_id) {
            return $post_id;
        }
        $existing = get_posts([
            'post_type' => 'cmn_school',
            'posts_per_page' => 1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_school_email_domain',
                    'value' => $domain,
                ],
            ],
        ]);
        if ($existing) {
            $post_id = (int) $existing[0];
            $this->upsert_school_index($post_id);
            return $post_id;
        }
        return 0;
    }

    private function resolve_school_identifier($identifier, $requested_pid = 0) {
        $identifier = trim((string) $identifier);
        $requested_pid = max(0, (int) $requested_pid);
        $this->log_school_id_resolution('start', [
            'school_id' => $identifier !== '' ? $identifier : '-',
            'pid' => $requested_pid,
        ]);

        if ($requested_pid > 0) {
            $pid_post = get_post($requested_pid);
            if ($pid_post instanceof WP_Post && $pid_post->post_type === 'cmn_school') {
                $this->log_school_id_resolution('by_pid ok', [
                    'post_id' => $requested_pid,
                ]);
                return $requested_pid;
            }
        }

        // Backward-compatible numeric identifier support (treat numeric school_id as pid).
        if ($identifier !== '' && ctype_digit($identifier)) {
            $post_id = (int) $identifier;
            $post = get_post($post_id);
            if ($post instanceof WP_Post && $post->post_type === 'cmn_school') {
                $this->log_school_id_resolution('by_pid ok', [
                    'post_id' => $post_id,
                ]);
                return $post_id;
            }
        }

        if ($identifier !== '') {
            $post_id = (int) $this->get_school_post_id_by_school_id($identifier);
            if ($post_id > 0) {
                $this->log_school_id_resolution('by_school_id ok', [
                    'post_id' => $post_id,
                ]);
                return $post_id;
            }
        }

        $this->log_school_id_resolution('not_found', [
            'school_id' => $identifier !== '' ? $identifier : '-',
            'pid' => $requested_pid,
        ]);
        return 0;
    }

    private function log_school_id_resolution($event, $context = []) {
        $event = trim((string) $event);
        if ($event === '') {
            $event = 'event';
        }
        $parts = [];
        foreach ((array) $context as $key => $value) {
            $key = sanitize_key((string) $key);
            if ($key === '') {
                continue;
            }
            if (is_array($value)) {
                $value = '[' . implode(',', array_map('strval', $value)) . ']';
            } elseif (is_bool($value)) {
                $value = $value ? '1' : '0';
            } else {
                $value = (string) $value;
            }
            $parts[] = $key . '=' . preg_replace('/\s+/', '_', trim($value));
        }
        $line = '[CMN_SCHOOL_ID_RESOLVE] ' . $event . (!empty($parts) ? (' ' . implode(' ', $parts)) : '');
        error_log($line);

        $debug_log_path = trim((string) ini_get('error_log'));
        if ($debug_log_path !== '' && stripos($debug_log_path, 'debug.log') !== false) {
            return;
        }
        if (!function_exists('wp_upload_dir')) {
            return;
        }
        $uploads = wp_upload_dir(null, false);
        $base_dir = (string) ($uploads['basedir'] ?? '');
        if ($base_dir === '') {
            return;
        }
        $log_dir = trailingslashit($base_dir) . 'cmn-logs';
        if (!is_dir($log_dir)) {
            wp_mkdir_p($log_dir);
        }
        if (!is_dir($log_dir) || !is_writable($log_dir)) {
            return;
        }
        $log_file = trailingslashit($log_dir) . 'school-id-resolve.log';
        @file_put_contents($log_file, '[' . gmdate('Y-m-d H:i:s') . ' UTC] ' . $line . PHP_EOL, FILE_APPEND | LOCK_EX);
    }

    private function is_school_debug_enabled() {
        if (defined('CMN_DEBUG_SCHOOLS')) {
            $raw_value = CMN_DEBUG_SCHOOLS;
            if (is_bool($raw_value)) {
                return $raw_value;
            }
            $normalized = strtolower(trim((string) $raw_value));
            return in_array($normalized, ['1', 'true', 'yes', 'on'], true);
        }
        $env_value = getenv('CMN_DEBUG_SCHOOLS');
        $normalized_env = strtolower(trim((string) $env_value));
        return in_array($normalized_env, ['1', 'true', 'yes', 'on'], true);
    }

    private function log_school_debug($event, $context = []) {
        $event_key = sanitize_key((string) $event);
        $always_log = (strpos($event_key, 'staff_school_view_') === 0)
            || in_array($event_key, ['school_profile_related_data_failed', 'school_profile_timeline_failed'], true);
        if (!$always_log && !$this->is_school_debug_enabled()) {
            return;
        }
        $payload = [
            'event' => $event_key,
            'user_id' => (int) get_current_user_id(),
            'role' => $this->get_current_user_role(),
            'timestamp' => current_time('mysql'),
            'context' => is_array($context) ? $context : [],
        ];
        error_log('[CMN_SCHOOL_DEBUG] ' . wp_json_encode($payload));
    }

    private function log_school_view_event($req_id, $step, $context = [], $start_time = null) {
        $payload = [
            'req_id' => (string) $req_id,
            'step' => sanitize_key((string) $step),
            'timestamp' => current_time('mysql'),
            'context' => is_array($context) ? $context : [],
        ];
        if ($start_time !== null) {
            $payload['elapsed_ms'] = (int) round((microtime(true) - (float) $start_time) * 1000);
        }
        error_log('[CMN_SCHOOL_VIEW] ' . wp_json_encode($payload));
    }

    private function log_school_view_crash($req_id, $reference_code, $context = []) {
        $payload = [
            'req_id' => (string) $req_id,
            'reference' => (string) $reference_code,
            'timestamp' => current_time('mysql'),
            'context' => is_array($context) ? $context : [],
        ];
        error_log('[CMN_SCHOOL_VIEW_CRASH] ' . wp_json_encode($payload));
    }

    private function build_school_view_error_card($reference_code, $reason, $requested_identifier, $resolved_school_id) {
        $reference_code = sanitize_text_field((string) $reference_code);
        $reason = trim((string) $reason);
        if ($reason === '') {
            $reason = 'An unexpected error occurred.';
        }
        $requested_identifier = sanitize_text_field((string) $requested_identifier);
        $resolved_school_id = (int) $resolved_school_id;
        $school_name = '';
        $status_display = '';
        $edit_link = '';
        if ($resolved_school_id > 0) {
            $school_post = get_post($resolved_school_id);
            if ($school_post instanceof WP_Post) {
                $school_name = (string) $school_post->post_title;
            }
            $status_raw = trim((string) get_post_meta($resolved_school_id, 'cmn_status', true));
            $status_display = $status_raw !== '' ? $status_raw : 'pending';
            $edit_link = get_edit_post_link($resolved_school_id, '');
            if ($edit_link === '') {
                $portal_page = cmn_get_page_by_title('Portal');
                $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
                $school_code = (string) get_post_meta($resolved_school_id, 'cmn_school_id', true);
                if ($school_code === '') {
                    $school_code = (string) $resolved_school_id;
                }
                $edit_link = add_query_arg(['view' => 'schools', 'school_id' => $school_code, 'pid' => $resolved_school_id], $portal_url) . '#cmn-school-details';
            }
        }
        if (function_exists('mb_strimwidth')) {
            $reason_short = mb_strimwidth($reason, 0, 160, '...');
        } else {
            $reason_short = strlen($reason) > 160 ? (substr($reason, 0, 157) . '...') : $reason;
        }
        $lines = [
            '<div class="cmn-panel-card">',
            '<h3>School profile could not render</h3>',
            '<p>' . esc_html($reason_short) . '</p>',
            $school_name !== '' ? ('<p><strong>School:</strong> ' . esc_html($school_name) . '</p>') : '',
            $status_display !== '' ? ('<p><strong>Status:</strong> ' . esc_html(ucfirst($status_display)) . '</p>') : '',
            '<p class="cmn-muted">Reference: ' . esc_html($reference_code) . '</p>',
            '<p class="cmn-muted">Requested school_id: ' . esc_html($requested_identifier !== '' ? $requested_identifier : '—') . '</p>',
            '<p class="cmn-muted">Resolved post ID: ' . esc_html($resolved_school_id > 0 ? (string) $resolved_school_id : '—') . '</p>',
            $edit_link !== '' ? ('<p><a class="cmn-ghost cmn-btn-mini" href="' . esc_url($edit_link) . '">Edit profile</a></p>') : '',
            '</div>',
        ];
        return implode('', $lines);
    }

    private function build_school_not_resolved_card($requested_identifier, $requested_pid, $portal_url = '') {
        $requested_identifier = sanitize_text_field((string) $requested_identifier);
        $requested_pid = max(0, (int) $requested_pid);
        $portal_url = esc_url_raw((string) $portal_url);
        if ($portal_url === '') {
            $portal_page = cmn_get_page_by_title('Portal');
            $portal_url = $portal_page ? (string) get_permalink($portal_page) : home_url('/portal');
        }

        $open_requests_url = add_query_arg(['view' => 'school-requests'], $portal_url);
        $rebuild_index_url = add_query_arg(['view' => 'school-partner-admin'], $portal_url);
        $school_list_url = add_query_arg(['view' => 'schools'], $portal_url);
        $can_rebuild = $this->is_admin_user((int) get_current_user_id());

        $lines = [
            '<div class="cmn-panel-card">',
            '<h3>We couldn\'t open this school profile yet.</h3>',
            '<p class="cmn-muted">School identifier resolution did not return a valid school record.</p>',
            '<p><strong>Requested school_id:</strong> ' . esc_html($requested_identifier !== '' ? $requested_identifier : '-') . '</p>',
            '<p><strong>Requested pid:</strong> ' . esc_html($requested_pid > 0 ? (string) $requested_pid : '-') . '</p>',
            '<p class="cmn-muted">Admin hint: check duplicate or missing <code>cmn_school_id</code> values, then rebuild school index mappings.</p>',
            '<p>',
            '<a class="cmn-primary cmn-btn-mini cmn-button-link" href="' . esc_url($open_requests_url) . '">Open School Requests</a> ',
            $can_rebuild ? ('<a class="cmn-ghost cmn-btn-mini" href="' . esc_url($rebuild_index_url) . '">Rebuild Index</a> ') : '',
            '<a class="cmn-ghost cmn-btn-mini" href="' . esc_url($school_list_url) . '">Back to Schools</a>',
            '</p>',
            '</div>',
        ];
        return implode('', $lines);
    }

    private function build_school_view_fallback_profile($school_post_id, $missing_fields = []) {
        $school_post_id = (int) $school_post_id;
        if ($school_post_id < 1) {
            return '';
        }
        $school = get_post($school_post_id);
        if (!$school || $school->post_type !== 'cmn_school') {
            return '<div class="cmn-panel-card"><h3>School not found</h3><p>We could not resolve this school reference.</p></div>';
        }
        $meta = function ($key) use ($school_post_id) {
            return get_post_meta($school_post_id, $key, true);
        };
        $status_raw = trim((string) $meta('cmn_status'));
        $status_display = $status_raw !== '' ? $status_raw : 'pending';
        $school_code = trim((string) $meta('cmn_school_id'));
        if ($school_code === '') {
            $school_code = (string) $school_post_id;
        }
        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        $profile_url = add_query_arg(['view' => 'schools', 'school_id' => $school_code, 'pid' => $school_post_id], $portal_url);
        $edit_link = get_edit_post_link($school_post_id, '');
        if ($edit_link === '') {
            $edit_link = $profile_url . '#cmn-school-details';
        }
        $missing_fields = is_array($missing_fields) && $missing_fields ? $missing_fields : $this->get_school_profile_missing_fields($school_post_id);
        $missing_summary = $missing_fields ? ('Profile incomplete: ' . esc_html(implode(', ', $missing_fields)) . '.') : 'Profile details loaded.';
        $lines = [
            '<header class="cmn-school-header">',
            '<h2>' . esc_html((string) $school->post_title) . '</h2>',
            '<p>School profile</p>',
            '</header>',
            '<section class="cmn-panel-card">',
            '<h3>Status</h3>',
            '<p><strong>' . esc_html(ucfirst($status_display)) . '</strong>' . ($status_raw === '' ? ' (assumed)' : '') . '</p>',
            '<p class="cmn-muted">School ID: ' . esc_html($school_code) . '</p>',
            '</section>',
            '<section class="cmn-panel-card">',
            '<h3>Profile health</h3>',
            '<p>' . $missing_summary . '</p>',
            $edit_link !== '' ? ('<a class="cmn-ghost cmn-btn-mini" href="' . esc_url($edit_link) . '">Edit profile</a>') : '',
            '</section>',
        ];
        return implode('', $lines);
    }


    private function render_empty_explain_panel($title, $reason, $action_label, $action_url, $action_class = 'cmn-ghost') {
        $title = trim((string) $title);
        $reason = trim((string) $reason);
        $action_label = trim((string) $action_label);
        $action_url = (string) $action_url;
        $action_class = trim((string) $action_class);
        if ($title === '') {
            $title = 'Nothing to show yet';
        }
        if ($reason === '') {
            $reason = 'This list is currently empty.';
        }
        $action_html = '';
        if ($action_label !== '' && $action_url !== '') {
            $action_html = '<a class="' . esc_attr($action_class) . ' cmn-btn-mini" href="' . esc_url($action_url) . '">' . esc_html($action_label) . '</a>';
        }
        return '<div class="cmn-panel-card cmn-empty-explain"><h3>' . esc_html($title) . '</h3><p class="cmn-muted">' . esc_html($reason) . '</p>' . $action_html . '</div>';
    }

    private function is_school_active_for_availability($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return false;
        }
        $school_status = sanitize_key((string) get_post_meta($school_id, 'cmn_status', true));
        if ($school_status === 'client') {
            return true;
        }
        $access_request_status = (string) $this->get_school_access_request_status($school_id);
        return $access_request_status === 'approved';
    }

    private function get_school_profile_missing_fields($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [];
        }
        $missing = [];
        $school_identifier = trim((string) get_post_meta($school_id, 'cmn_school_id', true));
        $school_email = sanitize_email((string) get_post_meta($school_id, 'cmn_email', true));
        $school_location = trim((string) get_post_meta($school_id, 'cmn_location', true));
        $school_postcode = trim((string) get_post_meta($school_id, 'cmn_postcode', true));
        $school_domain = trim((string) get_post_meta($school_id, 'cmn_school_email_domain', true));
        if ($school_identifier === '') {
            $missing[] = 'School ID';
        }
        if ($school_email === '' || !is_email($school_email)) {
            $missing[] = 'School Email';
        }
        if ($school_location === '') {
            $missing[] = 'Location';
        }
        if ($school_postcode === '') {
            $missing[] = 'Postcode';
        }
        if ($school_domain === '' && $this->get_email_domain($school_email) === '') {
            $missing[] = 'School Email Domain';
        }
        return $missing;
    }

    public function cmn_admin_find_and_fix_duplicate_school_ids($apply_changes = false) {
        $is_cli = defined('WP_CLI') && WP_CLI;
        if (!$is_cli) {
            $current_user_id = (int) get_current_user_id();
            if ($current_user_id < 1 || !$this->is_admin_user($current_user_id)) {
                return [
                    'ok' => false,
                    'message' => 'Admin access required.',
                    'scanned' => 0,
                    'duplicates' => [],
                    'missing_school_id_meta' => [],
                ];
            }
        }

        $per_page = 200;
        $page = 1;
        $scanned = 0;
        $missing_school_id_meta = [];
        $id_map = [];
        do {
            $post_ids = array_values(array_filter(array_map('intval', (array) get_posts([
                'post_type' => 'cmn_school',
                'post_status' => $this->get_school_list_post_statuses(),
                'posts_per_page' => $per_page,
                'paged' => $page,
                'orderby' => 'ID',
                'order' => 'ASC',
                'fields' => 'ids',
                'no_found_rows' => true,
                'update_post_meta_cache' => false,
                'update_post_term_cache' => false,
                'cache_results' => false,
                'suppress_filters' => true,
            ]))));
            foreach ($post_ids as $post_id) {
                $scanned++;
                $normalized = $this->normalize_school_id(get_post_meta($post_id, 'cmn_school_id', true));
                if ($normalized === '' || preg_match('/^CMN\d{4,}$/', $normalized) !== 1) {
                    $missing_school_id_meta[] = [
                        'post_id' => (int) $post_id,
                        'cmn_school_id' => $normalized,
                    ];
                    continue;
                }
                if (!isset($id_map[$normalized])) {
                    $id_map[$normalized] = [];
                }
                $id_map[$normalized][] = (int) $post_id;
            }
            $page++;
        } while (count($post_ids) === $per_page);

        $duplicates = [];
        foreach ($id_map as $school_id => $post_ids) {
            $post_ids = array_values(array_unique(array_filter(array_map('intval', (array) $post_ids))));
            if (count($post_ids) < 2) {
                continue;
            }
            usort($post_ids, function ($a, $b) {
                $a_date = (string) get_post_field('post_date_gmt', $a);
                $b_date = (string) get_post_field('post_date_gmt', $b);
                if ($a_date === $b_date) {
                    return $b <=> $a;
                }
                return strcmp($b_date, $a_date);
            });
            $duplicates[] = [
                'school_id' => (string) $school_id,
                'post_ids' => $post_ids,
                'primary_post_id' => (int) $post_ids[0],
                'duplicate_post_ids' => array_slice($post_ids, 1),
            ];
        }

        $report = [
            'ok' => true,
            'apply_changes' => $apply_changes ? 1 : 0,
            'changes_applied' => 0,
            'scanned' => $scanned,
            'duplicate_count' => count($duplicates),
            'missing_count' => count($missing_school_id_meta),
            'duplicates' => $duplicates,
            'missing_school_id_meta' => $missing_school_id_meta,
            'generated_at' => current_time('mysql'),
            'note' => $apply_changes ? 'Change mode is currently report-only; no records were modified.' : 'Report generated.',
        ];
        $this->log_school_id_resolution('duplicate_report', [
            'scanned' => $scanned,
            'duplicate_count' => (int) count($duplicates),
            'missing_count' => (int) count($missing_school_id_meta),
        ]);
        return $report;
    }

    private function get_school_id_by_name($name) {
        $post_id = $this->find_school_by_name($name);
        if (!$post_id) {
            return '';
        }
        return (string) get_post_meta($post_id, 'cmn_school_id', true);
    }

    private function get_school_name_by_school_id($school_id) {
        $post_id = $this->get_school_post_id_by_school_id($school_id);
        if (!$post_id) {
            return '';
        }
        return get_the_title($post_id);
    }

    private function get_school_name_by_domain($domain) {
        $post_id = $this->get_school_post_id_by_domain($domain);
        if (!$post_id) {
            return '';
        }
        return get_the_title($post_id);
    }

    private function find_school_by_email_or_name($email, $name) {
        $email = sanitize_email($email);
        $domain = $this->get_email_domain($email);
        if ($domain) {
            $existing = $this->get_school_post_id_by_domain($domain);
            if ($existing) {
                return (int) $existing;
            }
        }
        $name = sanitize_text_field($name);
        if ($name !== '') {
            $by_title = cmn_get_page_by_title($name, OBJECT, 'cmn_school');
            if ($by_title) {
                return (int) $by_title->ID;
            }
        }
        return 0;
    }

    private function find_school_by_name($name) {
        $name = sanitize_text_field($name);
        if ($name === '') {
            return 0;
        }
        $by_title = cmn_get_page_by_title($name, OBJECT, 'cmn_school');
        if ($by_title) {
            return (int) $by_title->ID;
        }
        return 0;
    }

    private function find_school_domain_by_name($name, &$ambiguous = false) {
        $ambiguous = false;
        $name = sanitize_text_field($name);
        if ($name === '') {
            return '';
        }
        global $wpdb;
        $post_ids = $wpdb->get_col($wpdb->prepare(
            "SELECT ID FROM {$wpdb->posts} WHERE post_type = %s AND post_title = %s LIMIT 2",
            'cmn_school',
            $name
        ));
        if (!$post_ids) {
            return '';
        }
        if (count($post_ids) > 1) {
            $ambiguous = true;
        }
        $post_id = (int) $post_ids[0];
        $domain = get_post_meta($post_id, 'cmn_school_email_domain', true);
        return $domain ? strtolower(trim($domain)) : '';
    }

    private function get_contact_school_table() {
        global $wpdb;
        return $wpdb->prefix . 'cmn_contact_school';
    }

    private function resolve_school_domain_from_identifier($identifier) {
        if ($identifier === '' || $identifier === null) {
            return '';
        }
        $identifier = trim((string) $identifier);
        if ($identifier === '') {
            return '';
        }
        if (strpos($identifier, '@') !== false) {
            return $this->get_email_domain($identifier);
        }
        if (preg_match('/^CMN\\d+$/i', $identifier)) {
            $post_id = $this->get_school_post_id_by_school_id($identifier);
            if ($post_id) {
                return (string) get_post_meta($post_id, 'cmn_school_email_domain', true);
            }
        }
        if (strpos($identifier, '.') !== false && strpos($identifier, ' ') === false) {
            return strtolower($identifier);
        }
        $post_id = $this->find_school_by_name($identifier);
        if ($post_id) {
            return (string) get_post_meta($post_id, 'cmn_school_email_domain', true);
        }
        return '';
    }

    private function link_contact_to_school($contact_id, $school_domain, $is_primary = false) {
        global $wpdb;
        $contact_id = (int) $contact_id;
        $school_domain = strtolower(trim((string) $school_domain));
        if (!$contact_id || $school_domain === '') {
            return;
        }
        $school_post_id = $this->get_school_post_id_by_domain($school_domain);
        $school_id = $school_post_id ? (string) get_post_meta($school_post_id, 'cmn_school_id', true) : '';
        $table = $this->get_contact_school_table();
        if ($is_primary) {
            $wpdb->update($table, ['is_primary' => 0], ['contact_id' => $contact_id], ['%d'], ['%d']);
        }
        $wpdb->replace($table, [
            'school_id' => $school_id,
            'school_email_domain' => $school_domain,
            'contact_id' => $contact_id,
            'is_primary' => $is_primary ? 1 : 0,
            'created_at' => current_time('mysql'),
        ], ['%s', '%s', '%d', '%d', '%s']);
    }

    private function unlink_contact_from_school($contact_id, $school_domain) {
        global $wpdb;
        $contact_id = (int) $contact_id;
        $school_domain = strtolower(trim((string) $school_domain));
        if (!$contact_id || $school_domain === '') {
            return;
        }
        $table = $this->get_contact_school_table();
        $wpdb->delete($table, [
            'contact_id' => $contact_id,
            'school_email_domain' => $school_domain,
        ], ['%d', '%s']);
    }

    private function get_contact_school_links($contact_id) {
        global $wpdb;
        $contact_id = (int) $contact_id;
        if (!$contact_id) {
            return [];
        }
        $table = $this->get_contact_school_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT school_email_domain, is_primary FROM {$table} WHERE contact_id = %d ORDER BY is_primary DESC",
            $contact_id
        ), ARRAY_A);
        if (!$rows) {
            $legacy_school_post = (int) get_post_meta($contact_id, 'cmn_contact_school_id', true);
            if ($legacy_school_post) {
                $legacy_school_id = get_post_meta($legacy_school_post, 'cmn_school_id', true);
                if ($legacy_school_id) {
                    $legacy_domain = get_post_meta($legacy_school_post, 'cmn_school_email_domain', true);
                    if ($legacy_domain) {
                        $this->link_contact_to_school($contact_id, $legacy_domain, true);
                        $rows = [
                            ['school_email_domain' => strtolower(trim($legacy_domain)), 'is_primary' => 1],
                        ];
                    }
                }
            }
        }
        return $rows ?: [];
    }

    private function clear_contact_links($contact_id) {
        global $wpdb;
        $contact_id = (int) $contact_id;
        if (!$contact_id) {
            return;
        }
        $table = $this->get_contact_school_table();
        $wpdb->delete($table, ['contact_id' => $contact_id], ['%d']);
    }

    private function get_contact_primary_school_id($contact_id) {
        $links = $this->get_contact_school_links($contact_id);
        foreach ($links as $link) {
            if (!empty($link['is_primary'])) {
                return $link['school_email_domain'];
            }
        }
        return $links ? $links[0]['school_email_domain'] : '';
    }

    private function get_school_contact_ids($school_id) {
        global $wpdb;
        $school_domain = strtolower(trim((string) $school_id));
        if ($school_domain === '') {
            return [];
        }
        $table = $this->get_contact_school_table();
        $rows = $wpdb->get_col($wpdb->prepare(
            "SELECT contact_id FROM {$table} WHERE school_email_domain = %s",
            $school_domain
        ));
        return array_map('intval', $rows ?: []);
    }

    private function get_contacts_not_linked_to_school($school_id) {
        $school_domain = strtolower(trim((string) $school_id));
        if ($school_domain === '') {
            return [];
        }
        $linked_ids = $this->get_school_contact_ids($school_domain);
        $args = [
            'post_type' => 'cmn_contact',
            'posts_per_page' => 200,
            'fields' => 'ids',
        ];
        if ($linked_ids) {
            $args['post__not_in'] = $linked_ids;
        }
        $contacts = get_posts($args);
        if (!$contacts) {
            return [];
        }
        return array_map('get_post', $contacts);
    }

    private function get_activity_table() {
        global $wpdb;
        return $wpdb->prefix . 'cmn_activities';
    }

    private function get_automation_rules_table() {
        global $wpdb;
        return $wpdb->prefix . 'cmn_automation_rules';
    }

    private function get_automation_logs_table() {
        global $wpdb;
        return $wpdb->prefix . 'cmn_automation_logs';
    }

    private function get_automation_engine() {
        if (!$this->automation_engine instanceof CmnAutomationEngine) {
            $this->automation_engine = new CmnAutomationEngine($this, [
                'rules_table' => $this->get_automation_rules_table(),
                'logs_table' => $this->get_automation_logs_table(),
            ]);
        }
        return $this->automation_engine;
    }

    private function get_client_profile_table() {
        global $wpdb;
        return $wpdb->prefix . 'cmn_client_profiles';
    }

    private function get_client_token_table() {
        global $wpdb;
        return $wpdb->prefix . 'cmn_client_tokens';
    }

    private function upsert_client_profile($domain, $data) {
        global $wpdb;
        $table = $this->get_client_profile_table();
        $domain = strtolower(trim((string) $domain));
        if ($domain === '') {
            return;
        }
        $row = [
            'school_email_domain' => $domain,
            'completion_status' => $data['completion_status'] ?? 'incomplete',
            'school_type' => $data['school_type'] ?? null,
            'pupil_count' => $data['pupil_count'] ?? null,
            'supply_frequency' => $data['supply_frequency'] ?? null,
            'uses_agencies' => $data['uses_agencies'] ?? null,
            'agency_count' => $data['agency_count'] ?? null,
            'notes' => $data['notes'] ?? null,
            'completed_at' => $data['completed_at'] ?? null,
            'updated_at' => current_time('mysql'),
        ];
        $wpdb->replace($table, $row, ['%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s']);
    }

    private function create_client_token($domain) {
        global $wpdb;
        $domain = strtolower(trim((string) $domain));
        if ($domain === '') {
            return '';
        }
        $token = wp_generate_password(32, false, false);
        $hash = hash('sha256', $token);
        $table = $this->get_client_token_table();
        $wpdb->insert($table, [
            'school_email_domain' => $domain,
            'token_hash' => $hash,
            'expires_at' => gmdate('Y-m-d H:i:s', strtotime('+7 days')),
            'used_at' => null,
            'created_at' => current_time('mysql'),
        ], ['%s', '%s', '%s', '%s', '%s']);
        return $token;
    }

    private function validate_client_token($token) {
        global $wpdb;
        $token = trim((string) $token);
        if ($token === '') {
            return null;
        }
        $hash = hash('sha256', $token);
        $table = $this->get_client_token_table();
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE token_hash = %s LIMIT 1",
            $hash
        ), ARRAY_A);
        if (!$row) {
            return null;
        }
        if (!empty($row['used_at'])) {
            return null;
        }
        if (!empty($row['expires_at']) && strtotime($row['expires_at']) < time()) {
            return null;
        }
        return $row;
    }

    private function mark_client_token_used($token) {
        global $wpdb;
        $token = trim((string) $token);
        if ($token === '') {
            return;
        }
        $hash = hash('sha256', $token);
        $table = $this->get_client_token_table();
        $wpdb->update($table, [
            'used_at' => current_time('mysql'),
        ], [
            'token_hash' => $hash,
        ], ['%s'], ['%s']);
    }

    private function normalize_activity_type($type) {
        $type = strtolower(trim((string) $type));
        if ($type === 'todo') {
            $type = 'task';
        }
        if (!in_array($type, ['call', 'email', 'note', 'task'], true)) {
            $type = 'note';
        }
        return $type;
    }

    private function insert_activity_row($data) {
        global $wpdb;
        $table = $this->get_activity_table();
        $entity_type = sanitize_text_field($data['entity_type'] ?? '');
        $entity_ref = sanitize_text_field($data['entity_ref'] ?? '');
        $activity_type = $this->normalize_activity_type($data['activity_type'] ?? 'note');
        $subject = sanitize_text_field($data['subject'] ?? '');
        $notes = sanitize_textarea_field($data['notes'] ?? '');
        $due_date = sanitize_text_field($data['due_date'] ?? '');
        $duration = isset($data['duration_minutes']) ? (int) $data['duration_minutes'] : null;
        $assigned_to = isset($data['assigned_to_user_id']) ? (int) $data['assigned_to_user_id'] : null;
        $assigned_school = sanitize_text_field($data['assigned_to_school_domain'] ?? '');
        $completed_at = sanitize_text_field($data['completed_at'] ?? '');
        $created_by = isset($data['created_by']) ? (int) $data['created_by'] : null;
        if ($entity_type === '' || $entity_ref === '' || $subject === '') {
            return 0;
        }
        $wpdb->insert($table, [
            'entity_type' => $entity_type,
            'entity_ref' => $entity_ref,
            'activity_type' => $activity_type,
            'subject' => $subject,
            'notes' => $notes,
            'due_date' => $due_date ?: null,
            'duration_minutes' => $duration ?: null,
            'assigned_to_user_id' => $assigned_to ?: null,
            'assigned_to_school_domain' => $assigned_school ?: null,
            'completed_at' => $completed_at ?: null,
            'created_by' => $created_by ?: null,
            'created_at' => current_time('mysql'),
            'updated_at' => current_time('mysql'),
        ], ['%s', '%s', '%s', '%s', '%s', '%s', '%d', '%d', '%s', '%s', '%d', '%s', '%s']);
        return (int) $wpdb->insert_id;
    }

    private function get_school_activities($school_domain, $limit = 20) {
        global $wpdb;
        $table = $this->get_activity_table();
        $school_domain = strtolower(trim((string) $school_domain));
        if ($school_domain === '') {
            return [];
        }
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE entity_type = 'school' AND entity_ref = %s ORDER BY created_at DESC LIMIT %d",
            $school_domain,
            (int) $limit
        ), ARRAY_A);
        if ($rows) {
            return $rows;
        }
        $school_post_id = $this->get_school_post_id_by_domain($school_domain);
        if (!$school_post_id) {
            return [];
        }
        return $this->get_legacy_school_activity_rows($school_post_id, $limit);
    }

    private function get_school_tasks($school_domain, $limit = 10) {
        global $wpdb;
        $table = $this->get_activity_table();
        $school_domain = strtolower(trim((string) $school_domain));
        if ($school_domain === '') {
            return [];
        }
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE entity_type = 'school' AND entity_ref = %s AND activity_type = 'task' AND completed_at IS NULL ORDER BY due_date ASC, created_at DESC LIMIT %d",
            $school_domain,
            (int) $limit
        ), ARRAY_A);
        if ($rows) {
            return $rows;
        }
        $school_post_id = $this->get_school_post_id_by_domain($school_domain);
        if (!$school_post_id) {
            return [];
        }
        return $this->get_legacy_school_task_rows($school_post_id, $limit);
    }

    private function get_legacy_school_activity_rows($school_post_id, $limit) {
        $activities = get_posts([
            'post_type' => 'cmn_activity',
            'posts_per_page' => $limit,
            'meta_query' => [
                [
                    'key' => 'cmn_related_type',
                    'value' => 'school',
                ],
                [
                    'key' => 'cmn_related_id',
                    'value' => $school_post_id,
                ],
            ],
            'orderby' => 'date',
            'order' => 'DESC',
        ]);
        $rows = [];
        foreach ($activities as $activity) {
            $rows[] = [
                'id' => $activity->ID,
                'activity_type' => $this->normalize_activity_type(get_post_meta($activity->ID, 'cmn_activity_type', true)),
                'subject' => $activity->post_title,
                'notes' => get_post_meta($activity->ID, 'cmn_activity_content', true),
                'due_date' => get_post_meta($activity->ID, 'cmn_activity_date', true),
                'duration_minutes' => get_post_meta($activity->ID, 'cmn_activity_duration', true),
                'completed_at' => get_post_meta($activity->ID, 'cmn_activity_status', true) === 'done' ? get_post_time('Y-m-d H:i:s', true, $activity) : null,
            ];
        }
        return $rows;
    }

    private function get_legacy_school_task_rows($school_post_id, $limit) {
        $activities = get_posts([
            'post_type' => 'cmn_activity',
            'posts_per_page' => $limit,
            'meta_query' => [
                [
                    'key' => 'cmn_related_type',
                    'value' => 'school',
                ],
                [
                    'key' => 'cmn_related_id',
                    'value' => $school_post_id,
                ],
                [
                    'key' => 'cmn_activity_type',
                    'value' => 'todo',
                ],
            ],
            'orderby' => 'date',
            'order' => 'DESC',
        ]);
        $rows = [];
        foreach ($activities as $activity) {
            $status = get_post_meta($activity->ID, 'cmn_activity_status', true);
            if ($status === 'done') {
                continue;
            }
            $rows[] = [
                'id' => $activity->ID,
                'activity_type' => 'task',
                'subject' => $activity->post_title,
                'notes' => get_post_meta($activity->ID, 'cmn_activity_content', true),
                'due_date' => get_post_meta($activity->ID, 'cmn_activity_date', true),
                'duration_minutes' => get_post_meta($activity->ID, 'cmn_activity_duration', true),
                'completed_at' => null,
            ];
        }
        return $rows;
    }

    private function create_or_update_contact($data) {
        $name = sanitize_text_field($data['name'] ?? '');
        $email = sanitize_email($data['email'] ?? '');
        $phone = sanitize_text_field($data['phone'] ?? '');
        $role = sanitize_text_field($data['role'] ?? '');
        $school_id = isset($data['school_id']) ? (int) $data['school_id'] : 0;
        $school_domain = isset($data['school_domain']) ? sanitize_text_field($data['school_domain']) : '';
        $is_primary = !empty($data['is_primary']);
        if ($name === '') {
            return 0;
        }
        if ($email && !is_email($email)) {
            return 0;
        }
        $contact_id = 0;
        if ($email) {
            $existing = get_posts([
                'post_type' => 'cmn_contact',
                'posts_per_page' => 1,
                'fields' => 'ids',
                'meta_query' => [
                    [
                        'key' => 'cmn_contact_email',
                        'value' => $email,
                    ],
                ],
            ]);
            if ($existing) {
                $contact_id = (int) $existing[0];
            }
        }
        if ($contact_id) {
            wp_update_post([
                'ID' => $contact_id,
                'post_title' => $name,
            ]);
        } else {
            $contact_id = wp_insert_post([
                'post_type' => 'cmn_contact',
                'post_title' => $name,
                'post_status' => 'publish',
            ]);
        }
        if (is_wp_error($contact_id) || !$contact_id) {
            return 0;
        }
        update_post_meta($contact_id, 'cmn_contact_name', $name);
        update_post_meta($contact_id, 'cmn_contact_email', $email);
        update_post_meta($contact_id, 'cmn_contact_phone', $phone);
        update_post_meta($contact_id, 'cmn_contact_role', $role);
        if ($school_id) {
            update_post_meta($contact_id, 'cmn_contact_school_id', $school_id);
        }
        if ($school_domain) {
            $this->link_contact_to_school($contact_id, $school_domain, $is_primary);
        }
        return $contact_id;
    }

    private function store_cover_manager_split($post_id, $full_name) {
        $full_name = trim((string) $full_name);
        if ($full_name === '') {
            update_post_meta($post_id, 'cmn_cover_manager_first_name', '');
            update_post_meta($post_id, 'cmn_cover_manager_last_name', '');
            return;
        }
        $parts = preg_split('/\s+/', $full_name);
        $first = $parts ? $parts[0] : '';
        $last = '';
        if (count($parts) > 1) {
            $last = $parts[count($parts) - 1];
        }
        update_post_meta($post_id, 'cmn_cover_manager_first_name', $first);
        update_post_meta($post_id, 'cmn_cover_manager_last_name', $last);
    }

    private function build_password_reset_url($user_id) {
        $user = get_user_by('id', $user_id);
        if (!$user) {
            return wp_lostpassword_url();
        }
        $key = get_password_reset_key($user);
        if (is_wp_error($key)) {
            return wp_lostpassword_url();
        }
        return $this->get_portal_reset_url($user->user_login, $key);
    }

    private function verify_candidate_email_token($user_id, $token) {
        if (!$user_id || $token === '') {
            return ['success' => false, 'message' => 'This verification link is invalid or has expired.'];
        }
        $stored = get_user_meta($user_id, 'cmn_email_verify_hash', true);
        $hash = hash('sha256', $token);
        if (!$stored || !hash_equals($stored, $hash)) {
            return ['success' => false, 'message' => 'This verification link is invalid or has expired.'];
        }

        update_user_meta($user_id, 'cmn_email_verified', '1');
        update_user_meta($user_id, 'cmn_email_verified_at', current_time('mysql'));
        delete_user_meta($user_id, 'cmn_email_verify_hash');

        $user = get_user_by('id', $user_id);
        if ($user instanceof WP_User) {
            if (in_array('cmn_candidate_pending', (array) $user->roles, true) && !in_array('cmn_candidate', (array) $user->roles, true)) {
                $user->remove_role('cmn_candidate_pending');
                $user->add_role('cmn_candidate');
            }
            $candidate = get_posts([
                'post_type' => 'cmn_candidate',
                'posts_per_page' => 1,
                'meta_query' => [
                    [
                        'key' => 'cmn_email',
                        'value' => $user->user_email,
                    ],
                ],
            ]);
            if (!empty($candidate)) {
                update_post_meta($candidate[0]->ID, 'cmn_email_verified', '1');
            }
        }

        return ['success' => true, 'message' => 'Thank you - your email is now verified.'];
    }

    private function send_candidate_verification_email($user_id, $candidate_name, $candidate_email) {
        if (!$user_id || $candidate_email === '') {
            return;
        }
        $verified = get_user_meta($user_id, 'cmn_email_verified', true);
        if ($verified === '1') {
            return;
        }
        $token = wp_generate_password(32, false);
        $hash = hash('sha256', $token);
        update_user_meta($user_id, 'cmn_email_verify_hash', $hash);
        update_user_meta($user_id, 'cmn_email_verified', '0');
        update_user_meta($user_id, 'cmn_email_verify_sent', time());

        $user = get_user_by('id', $user_id);
        $login = ($user instanceof WP_User) ? $user->user_login : '';
        $key = ($user instanceof WP_User) ? get_password_reset_key($user) : '';
        if (is_wp_error($key)) {
            $key = '';
        }
        $verify_url = $this->get_candidate_verify_url($user_id, $token);
        $reset_url = ($login && $key) ? $this->get_portal_reset_url($login, $key) : $this->build_password_reset_url($user_id);

        $safe_name = $candidate_name ? $candidate_name : 'there';
        $subject = 'Verify your email for CoverMeNow ONE';
        $message = "Hi {$safe_name},\n\nThanks for registering with CoverMeNow ONE.\n\nPlease verify your email to continue:\n{$verify_url}\n\nOnce verified, you can complete the rest of your profile.\n\nSet your password here:\n{$reset_url}\n\nIf you did not request this, please ignore this email.";
        $this->send_candidate_email($candidate_email, $subject, $message, [
            'type' => 'candidate_verification',
            'related_candidate_id' => $this->get_candidate_id_for_user($user_id),
        ]);
    }

    public function handle_verify_candidate_email() {
        $user_id = isset($_GET['uid']) ? intval($_GET['uid']) : 0;
        $token = isset($_GET['token']) ? sanitize_text_field(wp_unslash($_GET['token'])) : '';
        $portal_verify_url = add_query_arg([
            'view' => 'candidate-verify',
            'uid' => $user_id,
            'token' => rawurlencode($token),
        ], $this->get_portal_base_url());
        wp_redirect($portal_verify_url);
        exit;
    }

    public function handle_resend_candidate_verification() {
        if (!isset($_POST['cmn_resend_candidate_verification_nonce']) || !wp_verify_nonce($_POST['cmn_resend_candidate_verification_nonce'], 'cmn_resend_candidate_verification')) {
            wp_redirect(add_query_arg([
                'view' => 'candidate-verify',
                'cmn_error' => rawurlencode('Invalid request.'),
            ], $this->get_portal_base_url()));
            exit;
        }
        $user_id = isset($_POST['uid']) ? intval($_POST['uid']) : 0;
        $redirect = add_query_arg(['view' => 'candidate-verify'], $this->get_portal_base_url());
        if ($user_id) {
            $user = get_user_by('id', $user_id);
            if ($user instanceof WP_User) {
                $this->send_candidate_verification_email($user_id, $user->display_name, $user->user_email);
            }
            $redirect = add_query_arg(['view' => 'candidate-verify', 'uid' => $user_id], $this->get_portal_base_url());
        }
        wp_redirect(add_query_arg(['cmn_notice' => rawurlencode('Verification email sent. Please check your inbox.')], $redirect));
        exit;
    }

    public function handle_toggle_availability() {
        if (!isset($_POST['cmn_toggle_availability_nonce']) || !wp_verify_nonce($_POST['cmn_toggle_availability_nonce'], 'cmn_toggle_availability')) {
            wp_die('Invalid request');
        }
        if (!$this->is_candidate_user()) {
            wp_die('Unauthorized');
        }

        // For now, map to the current logged-in user candidate record by email if exists.
        $user = wp_get_current_user();
        if (!$user || !$user->user_email) {
            wp_redirect(add_query_arg('cmn_error', 'login', wp_get_referer() ?: home_url()));
            exit;
        }

        $candidate = get_posts([
            'post_type' => 'cmn_candidate',
            'posts_per_page' => 1,
            'meta_query' => [
                [
                    'key' => 'cmn_email',
                    'value' => $user->user_email,
                ],
            ],
        ]);

        if (!empty($candidate)) {
            $candidate_id = $candidate[0]->ID;
            $value = isset($_POST['cmn_available_tomorrow']) ? sanitize_text_field($_POST['cmn_available_tomorrow']) : '0';
            $value = $value === '1' ? '1' : '0';
            update_post_meta($candidate_id, 'cmn_available_tomorrow', $value);

            $tz = wp_timezone();
            $now = new DateTime('now', $tz);
            $hour = (int) $now->format('G');
            $window_open = ($hour >= 19 || $hour < 8);
            if (!$window_open) {
                wp_redirect(add_query_arg('cmn_error', 'window', wp_get_referer() ?: home_url()));
                exit;
            }
            $target_date = $hour >= 19 ? (clone $now)->modify('+1 day')->format('Y-m-d') : $now->format('Y-m-d');
            update_post_meta($candidate_id, 'cmn_available_date', $value === '1' ? $target_date : '');

            if ($value === '1') {
                $admin_email = get_option('admin_email');
                $subject = 'Candidate Available Tomorrow';
                $message = "Candidate {$candidate[0]->post_title} has marked available tomorrow.\n\nReview in the CRM.";
                wp_mail($admin_email, $subject, $message);
            }
        }

        wp_redirect(add_query_arg('cmn_updated', '1', wp_get_referer() ?: home_url()));
        exit;
    }

    public function handle_save_calendar() {
        if (!isset($_POST['cmn_save_calendar_nonce']) || !wp_verify_nonce($_POST['cmn_save_calendar_nonce'], 'cmn_save_calendar')) {
            wp_die('Invalid request');
        }
        if (!$this->is_candidate_user()) {
            wp_die('Unauthorized');
        }

        $user = wp_get_current_user();
        if (!$user || !$user->user_email) {
            wp_redirect(add_query_arg('cmn_error', 'login', wp_get_referer() ?: home_url()));
            exit;
        }

        $candidate = get_posts([
            'post_type' => 'cmn_candidate',
            'posts_per_page' => 1,
            'meta_query' => [
                [
                    'key' => 'cmn_email',
                    'value' => $user->user_email,
                ],
            ],
        ]);

        if (!empty($candidate)) {
            $candidate_id = $candidate[0]->ID;
            $raw = wp_unslash($_POST['cmn_calendar_data'] ?? '{}');
            $decoded = json_decode($raw, true);
            if (!is_array($decoded)) {
                $decoded = [];
            }
            $clean = [];
            foreach ($decoded as $date => $status) {
                if (!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/', $date)) {
                    continue;
                }
                $status = sanitize_text_field($status);
                if (!in_array($status, ['available', 'unavailable'], true)) {
                    continue;
                }
                $clean[$date] = $status;
            }
            update_post_meta($candidate_id, 'cmn_calendar_data', wp_json_encode($clean));
        }

        wp_redirect(add_query_arg('cmn_saved', '1', wp_get_referer() ?: home_url()));
        exit;
    }

    public function handle_mark_available() {
        if (!check_ajax_referer('cmn_mark_available', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }

        $candidate_id = $this->get_candidate_id_for_user();
        if (!$candidate_id) {
            wp_send_json_error(['message' => 'Candidate profile not found.'], 404);
        }

        $tz = wp_timezone();
        try {
            $now = new DateTime('now', $tz);
        } catch (Exception $e) {
            $now = new DateTime('@' . current_time('timestamp'));
            $now->setTimezone($tz);
            error_log('CMN availability fallback DateTime used in AJAX handler: ' . $e->getMessage());
        }
        $availability_window = $this->get_candidate_availability_window($now);
        $allowed = !empty($availability_window['is_open']);
        $target_date = (string) ($availability_window['target_date'] ?? '');
        if (!$target_date || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $target_date)) {
            $target_date = date_i18n('Y-m-d', strtotime('+1 day', current_time('timestamp')));
            error_log('CMN availability AJAX fallback target_date used.');
        }
        $already_marked = $this->has_candidate_availability($candidate_id, $target_date);
        $period_label = $this->get_availability_period_label($target_date, $now);
        if (!$allowed) {
            $closed_message = !empty($availability_window['closed_message']) ? (string) $availability_window['closed_message'] : 'You can confirm availability from 7:00pm on the previous day until 7:30am.';
            wp_send_json_error([
                'message' => $closed_message,
                'available' => $already_marked,
                'button_text' => $already_marked ? 'Availability confirmed' : ('Confirm availability for ' . $period_label),
                'button_enabled' => false,
                'status_text' => $already_marked ? 'I\'m available' : 'Not confirmed yet',
            ], 400);
        }

        if ($this->is_candidate_unavailable($candidate_id, $target_date)) {
            wp_send_json_error([
                'message' => 'You have marked yourself unavailable for ' . $period_label . ' in your calendar.',
                'available' => false,
                'button_text' => 'Confirm availability for ' . $period_label,
                'button_enabled' => true,
                'status_text' => 'I\'m not available',
            ], 400);
        }
        global $wpdb;
        $table = $this->get_candidate_availability_table();
        if ($already_marked) {
            $confirmed_at_label = '';
            $existing_entry = $this->get_candidate_availability_entry($candidate_id, $target_date);
            if (is_array($existing_entry) && !empty($existing_entry['created_at'])) {
                try {
                    $existing_confirmed_dt = new DateTime((string) $existing_entry['created_at'], wp_timezone());
                    $confirmed_at_label = strtoupper($existing_confirmed_dt->format('g:i A'));
                } catch (Exception $e) {
                    $confirmed_at_label = '';
                }
            }
            wp_send_json_success([
                'message' => 'Availability confirmed for ' . $period_label . '.',
                'available' => true,
                'button_enabled' => true,
                'status_text' => 'I\'m available',
                'button_text' => 'Availability confirmed',
                'confirmed_at' => $confirmed_at_label,
            ]);
        }

        $inserted = $wpdb->insert($table, [
            'candidate_id' => $candidate_id,
            'available_date' => $target_date,
            'available_type' => 'morning',
            'created_at' => current_time('mysql'),
        ], ['%d', '%s', '%s', '%s']);

        if (!$inserted) {
            wp_send_json_error(['message' => 'Unable to save availability.'], 500);
        }

        wp_send_json_success([
            'message' => 'Availability confirmed for ' . $period_label . '.',
            'date' => $target_date,
            'available' => true,
            'button_enabled' => true,
            'status_text' => 'I\'m available',
            'button_text' => 'Availability confirmed',
            'confirmed_at' => strtoupper(date_i18n('g:i A', current_time('timestamp'))),
        ]);
    }

    public function handle_mark_unavailable_morning() {
        if (!check_ajax_referer('cmn_mark_available', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }

        $candidate_id = $this->get_candidate_id_for_user();
        if (!$candidate_id) {
            wp_send_json_error(['message' => 'Candidate profile not found.'], 404);
        }

        $tz = wp_timezone();
        $now = new DateTime('now', $tz);
        $availability_window = $this->get_candidate_availability_window($now);
        $target_date = (string) ($availability_window['target_date'] ?? '');
        if (!$target_date || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $target_date)) {
