    }

    public function handle_candidate_request_delete_account() {
        if (!check_ajax_referer('cmn_candidate_settings', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user = wp_get_current_user();
        if (!$user || !$user->ID) {
            wp_send_json_error(['message' => 'User not found.'], 404);
        }
        if (get_user_meta($user->ID, 'cmn_deletion_requested', true)) {
            wp_send_json_success([
                'message' => 'Deletion request is already pending admin action.',
                'pending' => 1,
            ]);
        }

        $typed_email = strtolower(trim((string) ($_POST['typed_email'] ?? '')));
        $actual_email = strtolower(trim((string) $user->user_email));
        if ($typed_email === '' || $typed_email !== $actual_email) {
            wp_send_json_error(['message' => 'Email does not match your account email.'], 400);
        }

        $requested_at = current_time('mysql');
        update_user_meta($user->ID, 'cmn_deletion_requested', '1');
        update_user_meta($user->ID, 'cmn_deletion_requested_at', $requested_at);

        $portal_url = $this->get_portal_base_url();
        $link = add_query_arg([
            'view' => 'candidates',
            'cmn_status' => 'deletion_requested',
            'candidate_id' => (int) $this->get_candidate_id_for_user($user->ID),
        ], $portal_url);
        $display_name = trim((string) $user->display_name) ?: $user->user_login;
        $message = sprintf('%s (%s) requested deletion. User ID %d.', $display_name, $user->user_email, (int) $user->ID);
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            $this->add_notification((int) $admin_id, 'candidate_delete_request', 'Account deletion request', $message, $link);
        }
        $this->add_audit_log('candidate_deletion_requested', 'candidate', (string) ((int) $this->get_candidate_id_for_user($user->ID)), [
            'user_id' => (int) $user->ID,
            'email' => (string) $user->user_email,
        ], (int) $user->ID);

        wp_send_json_success([
            'message' => 'Request sent to admin.',
            'pending' => 1,
            'requested_at' => $requested_at,
        ]);
    }

    public function handle_admin_delete_candidate_account() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->can_manage_staff_users()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $confirm_text = strtoupper(trim((string) ($_POST['confirm_text'] ?? '')));
        if (!in_array($confirm_text, ['DELETE', 'DELETING'], true)) {
            wp_send_json_error(['message' => 'Type DELETE (or DELETING) to confirm account deletion.'], 400);
        }
        $candidate_id = (int) ($_POST['candidate_id'] ?? 0);
        if (!$candidate_id || get_post_type($candidate_id) !== 'cmn_candidate') {
            wp_send_json_error(['message' => 'Candidate not found.'], 404);
        }
        $candidate_user_id = (int) get_post_meta($candidate_id, 'cmn_user_id', true);
        if (!$candidate_user_id) {
            wp_send_json_error(['message' => 'Candidate account is not linked to a user.'], 400);
        }
        if (!get_user_meta($candidate_user_id, 'cmn_deletion_requested', true)) {
            wp_send_json_error(['message' => 'No deletion request is pending for this candidate.'], 400);
        }

        global $wpdb;
        $wpdb->delete($this->get_candidate_availability_table(), ['candidate_id' => $candidate_id], ['%d']);
        $wpdb->delete($this->get_candidate_calendar_table(), ['candidate_id' => $candidate_id], ['%d']);
        $wpdb->delete($this->get_candidate_requests_table(), ['candidate_id' => $candidate_id], ['%d']);
        $wpdb->delete($wpdb->prefix . 'cmn_support_feedback', ['user_id' => $candidate_user_id], ['%d']);

        wp_delete_post($candidate_id, true);
        if (!function_exists('wp_delete_user')) {
            require_once ABSPATH . 'wp-admin/includes/user.php';
        }
        wp_delete_user($candidate_user_id);
        $this->add_audit_log('candidate_account_deleted', 'candidate', (string) $candidate_id, [
            'candidate_user_id' => $candidate_user_id,
        ]);

        wp_send_json_success([
            'message' => 'Candidate account deleted.',
            'candidate_id' => $candidate_id,
            'user_id' => $candidate_user_id,
        ]);
    }

    private function create_candidate_cv_attachment_from_upload($file_field, $candidate_id, $candidate_user_id, $doc_type, $allowed_mimes, $title_stub = '') {
        $candidate_id = (int) $candidate_id;
        $candidate_user_id = (int) $candidate_user_id;
        if (empty($_FILES[$file_field]) || !is_array($_FILES[$file_field])) {
            return new WP_Error('cmn_missing_file', 'Missing uploaded file: ' . $file_field);
        }
        $file = $_FILES[$file_field];
        $ext = strtolower((string) pathinfo((string) ($file['name'] ?? ''), PATHINFO_EXTENSION));
        if ($ext === '' || !isset($allowed_mimes[$ext])) {
            return new WP_Error('cmn_invalid_file_type', 'File type not allowed for ' . $file_field . '.');
        }
        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';
        $uploaded = wp_handle_upload($file, [
            'test_form' => false,
            'mimes' => $allowed_mimes,
        ]);
        if (!empty($uploaded['error'])) {
            return new WP_Error('cmn_upload_failed', sanitize_text_field((string) $uploaded['error']));
        }
        $title_stub = $title_stub !== '' ? $title_stub : ('candidate-' . $candidate_id . '-' . $doc_type);
        $attachment_id = wp_insert_attachment([
            'post_author' => get_current_user_id(),
            'post_mime_type' => (string) ($uploaded['type'] ?? ''),
            'post_title' => sanitize_file_name($title_stub),
            'post_status' => 'inherit',
            'guid' => (string) ($uploaded['url'] ?? ''),
        ], (string) ($uploaded['file'] ?? ''));
        if (is_wp_error($attachment_id) || !$attachment_id) {
            return new WP_Error('cmn_attachment_failed', 'Unable to save uploaded file.');
        }
        $meta = wp_generate_attachment_metadata($attachment_id, (string) ($uploaded['file'] ?? ''));
        if (!is_wp_error($meta)) {
            wp_update_attachment_metadata($attachment_id, $meta);
        }
        if ($candidate_user_id > 0) {
            update_post_meta((int) $attachment_id, 'cmn_owner_user_id', $candidate_user_id);
        }
        update_post_meta((int) $attachment_id, 'cmn_doc_type', sanitize_key((string) $doc_type));
        update_post_meta((int) $attachment_id, 'cmn_candidate_id', $candidate_id);
        return [
            'attachment_id' => (int) $attachment_id,
            'url' => (string) wp_get_attachment_url((int) $attachment_id),
        ];
    }

    public function register_cv_converter_rest_routes() {
        if (!function_exists('register_rest_route')) {
            return;
        }

        register_rest_route('cmn/v1', '/cv/original', [
            'methods' => 'GET',
            'callback' => [$this, 'handle_rest_cv_original'],
            'permission_callback' => static function () {
                return is_user_logged_in();
            },
        ]);

        register_rest_route('cmn/v1', '/cv/formatted', [
            'methods' => 'POST',
            'callback' => [$this, 'handle_rest_cv_formatted'],
            'permission_callback' => static function () {
                return is_user_logged_in();
            },
        ]);

        register_rest_route('cmn/v1', '/partner-programme/stats', [
            'methods' => 'GET',
            'callback' => [$this, 'handle_rest_partner_programme_stats'],
            'permission_callback' => static function () {
                return is_user_logged_in();
            },
        ]);

        register_rest_route('cmn/v1', '/candidate/rewards/stats', [
            'methods' => 'GET',
            'callback' => [$this, 'handle_rest_candidate_rewards_stats'],
            'permission_callback' => static function () {
                return is_user_logged_in();
            },
        ]);
    }

    public function handle_rest_partner_programme_stats($request) {
        if (!is_user_logged_in()) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Unauthorized.'], 403);
        }

        $user_id = (int) get_current_user_id();
        $requested_school_id = (int) ($request->get_param('school_id') ?? 0);
        $target_school_id = 0;
        $is_staff = $this->is_admin_user($user_id) || $this->is_staff_role($user_id);

        if ($is_staff) {
            if ($requested_school_id > 0) {
                $target_school_id = $requested_school_id;
            } else {
                $target_school_id = (int) $this->resolve_school_id_for_user($user_id);
            }
            if ($target_school_id < 1) {
                return new WP_REST_Response(['ok' => false, 'message' => 'school_id is required.'], 400);
            }
        } elseif ($this->is_school_user($user_id)) {
            $target_school_id = (int) $this->resolve_school_id_for_user($user_id);
            if ($target_school_id < 1) {
                return new WP_REST_Response(['ok' => false, 'message' => 'School account is not linked.'], 403);
            }
            if ($requested_school_id > 0 && $requested_school_id !== $target_school_id) {
                return new WP_REST_Response(['ok' => false, 'message' => 'Not authorised for this school.'], 403);
            }
        } else {
            return new WP_REST_Response(['ok' => false, 'message' => 'Unauthorized.'], 403);
        }

        if (get_post_type($target_school_id) !== 'cmn_school') {
            return new WP_REST_Response(['ok' => false, 'message' => 'School not found.'], 404);
        }

        $stats = $this->get_school_partner_programme_stats($target_school_id, [
            'refresh' => true,
            'reference_date' => current_time('Y-m-d'),
            'source' => 'partner_programme_stats_api',
        ]);
        if (is_wp_error($stats)) {
            return new WP_REST_Response([
                'ok' => false,
                'message' => $stats->get_error_message(),
            ], 400);
        }

        return new WP_REST_Response(array_merge(['ok' => true], (array) $stats), 200);
    }

    public function handle_rest_candidate_rewards_stats($request) {
        if (!is_user_logged_in()) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Unauthorized.'], 403);
        }

        $user_id = (int) get_current_user_id();
        $requested_candidate_id = (int) ($request->get_param('candidate_id') ?? 0);
        $target_candidate_id = 0;
        $is_staff = $this->is_admin_user($user_id) || $this->is_staff_role($user_id);

        if ($is_staff) {
            if ($requested_candidate_id > 0) {
                $target_candidate_id = $requested_candidate_id;
            } else {
                $target_candidate_id = (int) $this->get_candidate_id_for_user($user_id);
            }
            if ($target_candidate_id < 1) {
                return new WP_REST_Response(['ok' => false, 'message' => 'candidate_id is required.'], 400);
            }
        } elseif ($this->is_candidate_user($user_id)) {
            $target_candidate_id = (int) $this->get_candidate_id_for_user($user_id);
            if ($target_candidate_id < 1) {
                return new WP_REST_Response(['ok' => false, 'message' => 'Candidate account is not linked.'], 403);
            }
            if ($requested_candidate_id > 0 && $requested_candidate_id !== $target_candidate_id) {
                return new WP_REST_Response(['ok' => false, 'message' => 'Not authorised for this candidate.'], 403);
            }
        } else {
            return new WP_REST_Response(['ok' => false, 'message' => 'Unauthorized.'], 403);
        }

        if (get_post_type($target_candidate_id) !== 'cmn_candidate') {
            return new WP_REST_Response(['ok' => false, 'message' => 'Candidate not found.'], 404);
        }

        $stats = $this->get_candidate_rewards_stats_payload($target_candidate_id, [
            'reference_date' => current_time('Y-m-d'),
            'include_events' => true,
        ]);
        if (is_wp_error($stats)) {
            return new WP_REST_Response([
                'ok' => false,
                'message' => $stats->get_error_message(),
            ], 400);
        }

        return new WP_REST_Response(array_merge(['ok' => true], (array) $stats), 200);
    }

    public function handle_rest_cv_original($request) {
        if (!is_user_logged_in()) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Unauthorized.'], 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->user_can_manage_cv_converter($user_id)) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Unauthorized.'], 403);
        }

        $candidate_id = (int) ($request->get_param('candidate_id') ?? 0);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_REST_Response(['ok' => false, 'message' => 'Candidate not found.'], 404);
        }
        if (!$this->user_can_view_candidate($candidate_id, $user_id)) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Access restricted for this candidate.'], 403);
        }

        $token = sanitize_text_field((string) ($request->get_param('token') ?: $request->get_param('portal_token')));
        $token_check = $this->validate_cv_converter_token($token, $candidate_id, $user_id);
        if (is_wp_error($token_check)) {
            return new WP_REST_Response(['ok' => false, 'message' => (string) $token_check->get_error_message()], 403);
        }

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        $attachment_id = $this->get_candidate_cv_original_attachment_id($candidate_id, $candidate_user_id);
        if ($attachment_id < 1) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Original CV is not uploaded yet.'], 404);
        }

        $file = get_attached_file($attachment_id);
        $filename = $file ? basename((string) $file) : '';
        $original_cv_url = add_query_arg([
            'action' => 'cmn_get_candidate_original_cv',
            'candidate_id' => $candidate_id,
            'token' => $token,
            'portal_token' => $token,
            'download' => 1,
        ], admin_url('admin-ajax.php'));

        return new WP_REST_Response([
            'ok' => true,
            'original_cv_url' => esc_url_raw($original_cv_url),
            'attachment_id' => (int) $attachment_id,
            'filename' => sanitize_file_name((string) $filename),
        ], 200);
    }

    public function handle_rest_cv_formatted($request) {
        if (!is_user_logged_in()) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Unauthorized.'], 403);
        }
        $user_id = (int) get_current_user_id();
        if (!$this->user_can_manage_cv_converter($user_id)) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Unauthorized.'], 403);
        }

        $candidate_id = (int) ($request->get_param('candidate_id') ?? 0);
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            return new WP_REST_Response(['ok' => false, 'message' => 'Candidate not found.'], 404);
        }
        if (!$this->user_can_view_candidate($candidate_id, $user_id)) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Access restricted for this candidate.'], 403);
        }

        $token = sanitize_text_field((string) ($request->get_param('token') ?: $request->get_param('portal_token')));
        $token_check = $this->validate_cv_converter_token($token, $candidate_id, $user_id);
        if (is_wp_error($token_check)) {
            return new WP_REST_Response(['ok' => false, 'message' => (string) $token_check->get_error_message()], 403);
        }

        $format = sanitize_key((string) ($request->get_param('format') ?? 'pdf'));
        if (!in_array($format, ['pdf', 'html'], true)) {
            $format = 'pdf';
        }

        $files = (array) $request->get_file_params();
        $file = is_array($files['file'] ?? null) ? $files['file'] : null;
        if (!$file) {
            return new WP_REST_Response(['ok' => false, 'message' => 'A file upload is required.'], 400);
        }

        $max_bytes = 20 * 1024 * 1024;
        $size = (int) ($file['size'] ?? 0);
        if ($size < 1) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Uploaded file is empty.'], 400);
        }
        if ($size > $max_bytes) {
            return new WP_REST_Response(['ok' => false, 'message' => 'File exceeds 20MB limit.'], 400);
        }

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            return new WP_REST_Response(['ok' => false, 'message' => 'Candidate account is not linked to a user.'], 400);
        }

        $allowed_mimes = $format === 'html'
            ? ['html' => 'text/html', 'htm' => 'text/html']
            : ['pdf' => 'application/pdf'];
        $doc_type = $format === 'html' ? 'cv_formatted_html' : 'cv_formatted';
        $title_stub = $format === 'html'
            ? ('candidate-' . $candidate_id . '-formatted-cv-html')
            : ('candidate-' . $candidate_id . '-formatted-cv');

        $_FILES['cmn_rest_cv_file'] = $file;
        $upload = $this->create_candidate_cv_attachment_from_upload(
            'cmn_rest_cv_file',
            $candidate_id,
            $candidate_user_id,
            $doc_type,
            $allowed_mimes,
            $title_stub
        );
        unset($_FILES['cmn_rest_cv_file']);

        if (is_wp_error($upload)) {
            return new WP_REST_Response(['ok' => false, 'message' => $upload->get_error_message()], 400);
        }

        $attachment_id = (int) ($upload['attachment_id'] ?? 0);
        $attachment_url = (string) ($upload['url'] ?? '');
        $uploaded_at = current_time('mysql');
        $formatted_version = sanitize_text_field((string) ($request->get_param('formatted_version') ?? self::VERSION));
        if ($formatted_version === '') {
            $formatted_version = self::VERSION;
        }

        if ($format === 'pdf') {
            update_post_meta($candidate_id, 'cmn_cv_formatted_attachment_id', $attachment_id);
            update_post_meta($candidate_id, 'cmn_cv_formatted_generated_at', $uploaded_at);
            update_post_meta($candidate_id, 'cmn_cv_formatted_uploaded_at', $uploaded_at);
            update_post_meta($candidate_id, 'cmn_cv_formatted_generated_by', $user_id);
            update_post_meta($candidate_id, 'cmn_cv_formatted_version', $formatted_version);
            update_post_meta($candidate_id, 'cmn_cv_formatted_format', 'pdf');
            update_post_meta($candidate_id, 'cmn_cv_formatted_outdated', '0');
        } else {
            update_post_meta($candidate_id, 'cmn_cv_formatted_html_attachment_id', $attachment_id);
            update_post_meta($candidate_id, 'cmn_cv_formatted_generated_by', $user_id);
            update_post_meta($candidate_id, 'cmn_cv_formatted_version', $formatted_version);
            update_post_meta($candidate_id, 'cmn_cv_formatted_format', 'html');
        }

        $profile_url = add_query_arg([
            'view' => 'candidates',
            'candidate_id' => $candidate_id,
        ], $this->get_portal_base_url());

        return new WP_REST_Response([
            'ok' => true,
            'candidate_id' => $candidate_id,
            'attachment_id' => $attachment_id,
            'url' => esc_url_raw($attachment_url),
            'formatted_format' => $format,
            'uploaded_at' => $uploaded_at,
            'formatted_version' => $formatted_version,
            'profile_url' => esc_url_raw($profile_url),
            'message' => 'Formatted CV placed on candidate profile.',
        ], 200);
    }

    public function handle_generate_cv_converter_token() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = get_current_user_id();
        if (!$this->user_can_manage_cv_converter($user_id)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $candidate_id = (int) ($_POST['candidate_id'] ?? 0);
        if (!$candidate_id || get_post_type($candidate_id) !== 'cmn_candidate') {
            wp_send_json_error(['message' => 'Candidate not found.'], 404);
        }
        if (!$this->user_can_view_candidate($candidate_id, $user_id)) {
            wp_send_json_error(['message' => 'Access restricted for this candidate.'], 403);
        }
        $token = $this->create_cv_converter_token($candidate_id, $user_id, 1800);
        if ($token === '') {
            wp_send_json_error(['message' => 'Unable to create converter token.'], 500);
        }
        $converter_url = add_query_arg([
            'portal_ajax_url' => admin_url('admin-ajax.php'),
            'api_base_path' => $this->get_cv_converter_api_base_path(),
            'candidate_id' => $candidate_id,
            'token' => $token,
            'portal_token' => $token,
            'auto_load_original' => '1',
            'cv_build' => (string) filemtime(plugin_dir_path(__FILE__) . 'cv/dist/index.html'),
        ], $this->get_cv_converter_base_url());
        $portal_converter_url = add_query_arg([
            'view' => 'cv_converter',
            'candidate_id' => $candidate_id,
        ], $this->get_portal_base_url());
        $original_cv_url = add_query_arg([
            'action' => 'cmn_get_candidate_original_cv',
            'candidate_id' => $candidate_id,
            'portal_token' => $token,
            'download' => 1,
        ], admin_url('admin-ajax.php'));
        wp_send_json_success([
            'candidate_id' => $candidate_id,
            'token' => $token,
            'expires_in' => 3600,
            'converter_url' => esc_url_raw($converter_url),
            'portal_url' => esc_url_raw($portal_converter_url),
            'original_cv_url' => esc_url_raw($original_cv_url),
            'save_endpoint' => esc_url_raw(add_query_arg(['action' => 'cmn_save_candidate_formatted_cv'], admin_url('admin-ajax.php'))),
            'portal_ajax_url' => esc_url_raw(admin_url('admin-ajax.php')),
        ]);
    }

    public function handle_get_candidate_original_cv() {
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = get_current_user_id();
        if (!$this->user_can_manage_cv_converter($user_id)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $candidate_id = (int) ($_REQUEST['candidate_id'] ?? 0);
        if (!$candidate_id || get_post_type($candidate_id) !== 'cmn_candidate') {
            wp_send_json_error(['message' => 'Candidate not found.'], 404);
        }
        if (!$this->user_can_view_candidate($candidate_id, $user_id)) {
            wp_send_json_error(['message' => 'Access restricted for this candidate.'], 403);
        }
        $token = sanitize_text_field((string) ($_REQUEST['portal_token'] ?? ''));
        $token_check = $this->validate_cv_converter_token($token, $candidate_id, $user_id);
        if (is_wp_error($token_check)) {
            wp_send_json_error(['message' => $token_check->get_error_message()], 403);
        }
        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);

        // Re-open converter with last saved formatted CV when available, then fallback to original.
        $attachment_id = 0;
        $source = 'original';

        $formatted_html_attachment_id = (int) get_post_meta($candidate_id, 'cmn_cv_formatted_html_attachment_id', true);
        $formatted_pdf_attachment_id = (int) $this->get_candidate_cv_formatted_attachment_id($candidate_id);
        if ($formatted_html_attachment_id > 0) {
            $attachment_id = $formatted_html_attachment_id;
            $source = 'formatted_html';
        } elseif ($formatted_pdf_attachment_id > 0) {
            $attachment_id = $formatted_pdf_attachment_id;
            $source = 'formatted_pdf';
        } else {
            $attachment_id = $this->get_candidate_cv_original_attachment_id($candidate_id, $candidate_user_id);
            $source = 'original';
        }

        if ($attachment_id < 1) {
            wp_send_json_error(['message' => 'Original CV is not uploaded yet.'], 404);
        }
        $file = get_attached_file($attachment_id);
        if (!$file || !file_exists($file)) {
            wp_send_json_error(['message' => 'CV file not found.'], 404);
        }
        $as_meta = isset($_REQUEST['meta']) && (string) $_REQUEST['meta'] === '1';
        $filename = basename((string) $file);
        if ($as_meta) {
            wp_send_json_success([
                'candidate_id' => $candidate_id,
                'filename' => $filename,
                'mime' => (string) get_post_mime_type($attachment_id),
                'filesize' => filesize($file),
                'source' => $source,
            ]);
        }
        nocache_headers();
        header('Content-Type: ' . (string) (get_post_mime_type($attachment_id) ?: 'application/octet-stream'));
        header('Content-Disposition: attachment; filename="' . sanitize_file_name($filename) . '"');
        header('Content-Length: ' . (string) filesize($file));
        header('X-Content-Type-Options: nosniff');
        readfile($file);
        exit;
    }

    public function handle_save_candidate_formatted_cv() {
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = get_current_user_id();
        if (!$this->user_can_manage_cv_converter($user_id)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $candidate_id = (int) ($_POST['candidate_id'] ?? 0);
        if (!$candidate_id || get_post_type($candidate_id) !== 'cmn_candidate') {
            wp_send_json_error(['message' => 'Candidate not found.'], 404);
        }
        if (!$this->user_can_view_candidate($candidate_id, $user_id)) {
            wp_send_json_error(['message' => 'Access restricted for this candidate.'], 403);
        }
        $token = sanitize_text_field((string) ($_POST['portal_token'] ?? ''));
        $token_check = $this->validate_cv_converter_token($token, $candidate_id, $user_id);
        if (is_wp_error($token_check)) {
            wp_send_json_error(['message' => $token_check->get_error_message()], 403);
        }
        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            wp_send_json_error(['message' => 'Candidate account is not linked to a user.'], 400);
        }
        if (empty($_FILES['pdf_file']) || !is_array($_FILES['pdf_file'])) {
            wp_send_json_error(['message' => 'A formatted PDF file is required.'], 400);
        }
        $pdf_upload = $this->create_candidate_cv_attachment_from_upload(
            'pdf_file',
            $candidate_id,
            $candidate_user_id,
            'cv_formatted',
            ['pdf' => 'application/pdf'],
            'candidate-' . $candidate_id . '-formatted-cv'
        );
        if (is_wp_error($pdf_upload)) {
            wp_send_json_error(['message' => $pdf_upload->get_error_message()], 400);
        }
        $html_attachment_id = 0;
        $html_warning = '';
        if (!empty($_FILES['html_file']) && is_array($_FILES['html_file']) && (int) ($_FILES['html_file']['size'] ?? 0) > 0) {
            $html_upload = $this->create_candidate_cv_attachment_from_upload(
                'html_file',
                $candidate_id,
                $candidate_user_id,
                'cv_formatted_html',
                ['html' => 'text/html', 'htm' => 'text/html'],
                'candidate-' . $candidate_id . '-formatted-cv-html'
            );
            if (is_wp_error($html_upload)) {
                $html_error_message = strtolower((string) $html_upload->get_error_message());
                $html_blocked = (
                    strpos($html_error_message, 'not allowed to upload this file type') !== false
                    || strpos($html_error_message, 'file type not allowed') !== false
                );
                if ($html_blocked) {
                    $html_warning = 'HTML backup was skipped because this server blocks HTML uploads.';
                } else {
                    wp_send_json_error(['message' => $html_upload->get_error_message()], 400);
                }
            } else {
                $html_attachment_id = (int) ($html_upload['attachment_id'] ?? 0);
            }
        }
        $formatted_version = sanitize_text_field((string) ($_POST['formatted_version'] ?? self::VERSION));
        if ($formatted_version === '') {
            $formatted_version = self::VERSION;
        }
        $generated_at = current_time('mysql');
        update_post_meta($candidate_id, 'cmn_cv_formatted_attachment_id', (int) ($pdf_upload['attachment_id'] ?? 0));
        update_post_meta($candidate_id, 'cmn_cv_formatted_generated_at', $generated_at);
        update_post_meta($candidate_id, 'cmn_cv_formatted_version', $formatted_version);
        update_post_meta($candidate_id, 'cmn_cv_formatted_generated_by', $user_id);
        update_post_meta($candidate_id, 'cmn_cv_formatted_outdated', '0');
        if ($html_attachment_id > 0) {
            update_post_meta($candidate_id, 'cmn_cv_formatted_html_attachment_id', $html_attachment_id);
        } else {
            delete_post_meta($candidate_id, 'cmn_cv_formatted_html_attachment_id');
        }
        $actor = wp_get_current_user();
        $this->add_candidate_cv_audit_entry(
            $candidate_id,
            'Formatted CV saved to profile',
            'Formatted CV saved by ' . ($actor && $actor->display_name ? $actor->display_name : ('User #' . $user_id)) . ' at ' . $generated_at . '.',
            $user_id
        );
        $this->add_audit_log('cv_converted', 'candidate', (string) $candidate_id, [
            'formatted_attachment_id' => (int) ($pdf_upload['attachment_id'] ?? 0),
            'formatted_html_attachment_id' => (int) $html_attachment_id,
            'version' => $formatted_version,
        ], $user_id);
        $profile_url = add_query_arg([
            'view' => 'candidates',
            'candidate_id' => $candidate_id,
        ], $this->get_portal_base_url());
        wp_send_json_success([
            'candidate_id' => $candidate_id,
            'formatted_attachment_id' => (int) ($pdf_upload['attachment_id'] ?? 0),
            'formatted_html_attachment_id' => $html_attachment_id,
            'generated_at' => $generated_at,
            'formatted_version' => $formatted_version,
            'profile_url' => esc_url_raw($profile_url),
            'html_warning' => $html_warning,
            'message' => $html_warning !== '' ? 'Formatted CV placed on candidate profile. HTML backup skipped by server rules.' : 'Formatted CV placed on candidate profile.',
        ]);
    }

    public function handle_cv_save_formatted() {
        if (!check_ajax_referer('cmn_cv_save_formatted', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        $this->handle_save_candidate_formatted_cv();
    }

    public function handle_candidate_learning_opt_in() {
        if (!check_ajax_referer('cmn_candidate_learning', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $enabled = !empty($_POST['enabled']) && (string) $_POST['enabled'] !== '0';
        $user_id = get_current_user_id();
        update_user_meta($user_id, 'cmn_learning_notify_opt_in', $enabled ? '1' : '0');
        if ($enabled) {
            update_user_meta($user_id, 'cmn_learning_notify_opt_in_date', current_time('mysql'));
        } else {
            delete_user_meta($user_id, 'cmn_learning_notify_opt_in_date');
        }
        wp_send_json_success([
            'enabled' => $enabled ? 1 : 0,
            'message' => $enabled ? 'You will be notified when courses go live.' : 'Learning notifications turned off.',
        ]);
    }

    public function handle_candidate_learning_complete_course() {
        if (!check_ajax_referer('cmn_candidate_learning', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }

        $course_key = sanitize_key((string) ($_POST['course_key'] ?? ''));
        $score = max(0, min(100, (int) ($_POST['score'] ?? 0)));
        $catalog = $this->get_candidate_learning_course_catalog();
        if ($course_key === '' || !isset($catalog[$course_key])) {
            wp_send_json_error(['message' => 'Course not found.'], 404);
        }

        $user_id = (int) get_current_user_id();
        $results = get_user_meta($user_id, 'cmn_learning_course_results', true);
        if (is_string($results) && $results !== '') {
            $decoded_results = json_decode($results, true);
            if (is_array($decoded_results)) {
                $results = $decoded_results;
            }
        }
        if (!is_array($results)) {
            $results = [];
        }

        $required_course_keys = array_values(array_filter(array_map('sanitize_key', (array) ($catalog[$course_key]['requires_course_keys'] ?? []))));
        if ($required_course_keys) {
            $missing_required_titles = [];
            foreach ($required_course_keys as $required_course_key) {
                $required_completion = is_array($results[$required_course_key] ?? null) ? (array) $results[$required_course_key] : [];
                if (!empty($required_completion['passed'])) {
                    continue;
                }
                $required_title = sanitize_text_field((string) ($catalog[$required_course_key]['title'] ?? str_replace('_', ' ', ucfirst($required_course_key))));
                if ($required_title !== '') {
                    $missing_required_titles[] = $required_title;
                }
            }
            if ($missing_required_titles) {
                wp_send_json_error([
                    'message' => 'Complete required modules first: ' . implode(', ', $missing_required_titles) . '.',
                    'missing_required' => $missing_required_titles,
                ], 400);
            }
        }

        $pass_mark = max(1, min(100, (int) ($catalog[$course_key]['pass_mark'] ?? 100)));
        if ($score < $pass_mark) {
            wp_send_json_error(['message' => 'Pass mark not reached.'], 400);
        }

        $existing_code = sanitize_text_field((string) (($results[$course_key]['verification_code'] ?? '')));
        $certificate_prefix = strtoupper(trim((string) ($catalog[$course_key]['certificate_prefix'] ?? 'CMN')));
        $certificate_prefix = preg_replace('/[^A-Z0-9-]/', '', $certificate_prefix);
        if ($certificate_prefix === '') {
            $certificate_prefix = 'CMN';
        }
        if ($existing_code === '') {
            $existing_code = $certificate_prefix . '-' . strtoupper(substr(md5($user_id . '|' . $course_key . '|' . microtime(true) . '|' . wp_rand(1000, 999999)), 0, 10));
        }
        $issued_mysql = current_time('mysql');
        $issued_display = date_i18n('j M Y', strtotime($issued_mysql));
        $version = sanitize_text_field((string) ($catalog[$course_key]['version'] ?? 'v1.0'));
        $certificate_label = sanitize_text_field((string) ($catalog[$course_key]['certificate_label'] ?? 'Certificate of Course Completion'));

        $results[$course_key] = [
            'course_key' => $course_key,
            'passed' => 1,
            'score' => $score,
            'issued_at' => $issued_mysql,
            'issued_date' => $issued_display,
            'verification_code' => $existing_code,
            'version' => $version,
            'certificate_label' => $certificate_label,
        ];
        update_user_meta($user_id, 'cmn_learning_course_results', $results);

        $completed = get_user_meta($user_id, 'cmn_learning_courses_completed', true);
        if (is_string($completed) && $completed !== '') {
            $decoded_completed = json_decode($completed, true);
            if (is_array($decoded_completed)) {
                $completed = $decoded_completed;
            } else {
                $completed = array_map('trim', explode(',', $completed));
            }
        }
        if (!is_array($completed)) {
            $completed = [];
        }
        $completed[] = $course_key;
        $completed = array_values(array_unique(array_filter(array_map('sanitize_key', array_map('strval', $completed)))));
        update_user_meta($user_id, 'cmn_learning_courses_completed', $completed);

        $this->add_audit_log('candidate_learning_course_completed', 'candidate', (string) ((int) $this->get_candidate_id_for_user($user_id)), [
            'candidate_user_id' => $user_id,
            'course_key' => $course_key,
            'score' => $score,
            'verification_code' => $existing_code,
            'version' => $version,
        ], $user_id);

        wp_send_json_success([
            'course_key' => $course_key,
            'score' => $score,
            'issued_date' => $issued_display,
            'verification_code' => $existing_code,
            'version' => $version,
            'certificate_label' => $certificate_label,
            'message' => 'Course completion saved.',
        ]);
    }

    public function handle_candidate_profile_photo_upload() {
        if (!check_ajax_referer('cmn_candidate_profile', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if (empty($_FILES['profile_photo']) || !is_array($_FILES['profile_photo'])) {
            wp_send_json_error(['message' => 'Please choose a photo to upload.'], 400);
        }
        $file = $_FILES['profile_photo'];
        $max_size = 5 * 1024 * 1024;
        if (!empty($file['size']) && (int) $file['size'] > $max_size) {
            wp_send_json_error(['message' => 'Photo is too large. Maximum file size is 5MB.'], 400);
        }

        $user_id = (int) get_current_user_id();
        $candidate_id = (int) $this->get_candidate_id_for_user($user_id);
        if ($candidate_id < 1) {
            wp_send_json_error(['message' => 'Candidate profile not found.'], 404);
        }

        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';
        $overrides = [
            'test_form' => false,
            'mimes' => [
                'jpg|jpeg|jpe' => 'image/jpeg',
                'png' => 'image/png',
                'webp' => 'image/webp',
            ],
        ];
        $uploaded = wp_handle_upload($file, $overrides);
        if (!empty($uploaded['error'])) {
            wp_send_json_error(['message' => sanitize_text_field((string) $uploaded['error'])], 400);
        }

        $attachment_id = wp_insert_attachment([
            'post_mime_type' => (string) ($uploaded['type'] ?? ''),
            'post_title' => sanitize_file_name(pathinfo((string) ($file['name'] ?? 'profile-photo'), PATHINFO_FILENAME)),
            'post_status' => 'inherit',
            'guid' => (string) ($uploaded['url'] ?? ''),
        ], (string) ($uploaded['file'] ?? ''), $candidate_id);
        if (is_wp_error($attachment_id) || !$attachment_id) {
            wp_send_json_error(['message' => 'Unable to save profile photo.'], 500);
        }

        $meta = wp_generate_attachment_metadata($attachment_id, (string) ($uploaded['file'] ?? ''));
        if (!is_wp_error($meta)) {
            wp_update_attachment_metadata($attachment_id, $meta);
        }

        $photo_url = wp_get_attachment_image_url((int) $attachment_id, 'medium');
        if (!is_string($photo_url) || $photo_url === '') {
            $photo_url = wp_get_attachment_url((int) $attachment_id);
        }
        if (!is_string($photo_url) || $photo_url === '') {
            $photo_url = $this->get_default_profile_photo_url();
        }
        $photo_url = esc_url_raw($photo_url);

        $url_meta_keys = ['cmn_profile_photo', 'cmn_photo_url', 'cmn_avatar_url', 'profile_photo_url'];
        foreach ($url_meta_keys as $meta_key) {
            update_user_meta($user_id, $meta_key, $photo_url);
            update_post_meta($candidate_id, $meta_key, $photo_url);
        }
        update_user_meta($user_id, 'cmn_profile_photo_attachment_id', (int) $attachment_id);
        update_post_meta($candidate_id, 'cmn_profile_photo_attachment_id', (int) $attachment_id);
        update_post_meta((int) $attachment_id, 'cmn_owner_user_id', $user_id);
        update_post_meta((int) $attachment_id, 'cmn_candidate_id', $candidate_id);
        update_post_meta((int) $attachment_id, 'cmn_doc_type', 'profile_photo');

        wp_send_json_success([
            'photo_url' => add_query_arg('v', (string) time(), $photo_url),
            'has_photo' => 1,
            'message' => 'Profile photo updated.',
        ]);
    }

    public function handle_candidate_profile_photo_remove() {
        if (!check_ajax_referer('cmn_candidate_profile', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = (int) get_current_user_id();
        $candidate_id = (int) $this->get_candidate_id_for_user($user_id);
        if ($candidate_id < 1) {
            wp_send_json_error(['message' => 'Candidate profile not found.'], 404);
        }

        $url_meta_keys = ['cmn_profile_photo', 'cmn_photo_url', 'cmn_avatar_url', 'profile_photo_url'];
        foreach ($url_meta_keys as $meta_key) {
            delete_user_meta($user_id, $meta_key);
            delete_post_meta($candidate_id, $meta_key);
        }
        delete_user_meta($user_id, 'cmn_profile_photo_attachment_id');
        delete_post_meta($candidate_id, 'cmn_profile_photo_attachment_id');

        wp_send_json_success([
            'photo_url' => $this->get_default_profile_photo_url(),
            'has_photo' => 0,
            'message' => 'Profile photo removed.',
        ]);
    }

    public function handle_candidate_update_profile() {
        if (!check_ajax_referer('cmn_candidate_profile', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = get_current_user_id();
        $candidate_id = $this->get_candidate_id_for_user($user_id);
        if (!$candidate_id) {
            wp_send_json_error(['message' => 'Candidate profile not found.'], 404);
        }

        $field_contract = $this->get_candidate_profile_field_contract();
        $payload = [];
        foreach ($field_contract as $field_key => $field_config) {
            $raw = $field_config['sanitize'] === 'multi_choice'
                ? ($_POST[$field_key] ?? [])
                : ($_POST[$field_key] ?? '');
            $payload[$field_key] = $this->sanitize_profile_contract_value($raw, $field_config);
        }

        $profile_email = (string) ($payload['email'] ?? '');
        if ($profile_email === '' || !is_email($profile_email)) {
            wp_send_json_error(['message' => 'A valid email is required.'], 400);
        }
        $preferred_roles = array_values(array_filter(array_map('sanitize_text_field', (array) ($payload['roles'] ?? []))));
        if (empty($preferred_roles) && !empty($payload['role_type'])) {
            $preferred_roles[] = (string) $payload['role_type'];
        }
        if (!empty($payload['role_type']) && !in_array((string) $payload['role_type'], $preferred_roles, true)) {
            array_unshift($preferred_roles, (string) $payload['role_type']);
        }
        $payload['roles'] = array_values(array_unique($preferred_roles));
        if ((string) ($payload['no_dbs'] ?? '') !== '1') {
            $payload['no_dbs'] = '0';
        }

        $first_name = (string) ($payload['first_name'] ?? '');
        $last_name = (string) ($payload['last_name'] ?? '');
        if ($first_name === '' || $last_name === '') {
            wp_send_json_error(['message' => 'First name and last name are required.'], 400);
        }
        if ((string) ($payload['nationality'] ?? '') === '') {
            wp_send_json_error(['message' => 'Nationality is required.'], 400);
        }
        if ((string) ($payload['role_type'] ?? '') === '') {
            wp_send_json_error(['message' => 'Primary role is required.'], 400);
        }
        $existing_user = wp_get_current_user();
        if ($existing_user && strcasecmp((string) $existing_user->user_email, $profile_email) !== 0) {
            $existing_email_user_id = (int) email_exists($profile_email);
            if ($existing_email_user_id > 0 && $existing_email_user_id !== $user_id) {
                wp_send_json_error(['message' => 'Email is already in use by another account.'], 409);
            }
            $email_result = wp_update_user([
                'ID' => $user_id,
                'user_email' => $profile_email,
            ]);
            if (is_wp_error($email_result)) {
                wp_send_json_error(['message' => $email_result->get_error_message()], 400);
            }
        }

        foreach ($field_contract as $field_key => $field_config) {
            $value = $payload[$field_key] ?? '';
            $storage = (string) ($field_config['storage'] ?? '');
            if ($storage === 'user_meta') {
                if (is_array($value)) {
                    update_user_meta($user_id, (string) $field_config['key'], $value);
                } elseif ($value !== '') {
                    update_user_meta($user_id, (string) $field_config['key'], $value);
                } else {
                    delete_user_meta($user_id, (string) $field_config['key']);
                }
                $sync_post_meta = (string) ($field_config['sync_post_meta'] ?? '');
                if ($sync_post_meta !== '') {
                    if ($value !== '') {
                        update_post_meta($candidate_id, $sync_post_meta, $value);
                    } else {
                        delete_post_meta($candidate_id, $sync_post_meta);
                    }
                }
                if (!empty($field_config['sync_post_roles'])) {
                    if ($value !== '') {
                        update_post_meta($candidate_id, 'cmn_roles', [$value]);
                    } else {
                        delete_post_meta($candidate_id, 'cmn_roles');
                    }
                }
            } elseif ($storage === 'post_meta') {
                if (is_array($value)) {
                    update_post_meta($candidate_id, (string) $field_config['key'], $value);
                } elseif ($value !== '') {
                    update_post_meta($candidate_id, (string) $field_config['key'], $value);
                } else {
                    delete_post_meta($candidate_id, (string) $field_config['key']);
                }
            }
        }

        $full_name = trim($first_name . ' ' . $last_name);
        wp_update_user([
            'ID' => $user_id,
            'first_name' => $first_name,
            'last_name' => $last_name,
            'display_name' => $full_name !== '' ? $full_name : (string) ($existing_user->display_name ?? 'Candidate'),
        ]);

        $availability_days = (array) ($payload['availability_days'] ?? []);
        $availability_days_label = $availability_days ? implode(', ', $availability_days) : 'Not set';
        $yes_no_map = ['yes' => 'Yes', 'no' => 'No'];
        $driving_licence = (string) ($payload['driving_licence'] ?? '');
        $car_owner = (string) ($payload['car_owner'] ?? '');
        $qts_status = (string) ($payload['qts_status'] ?? '');
        $dbs_update_service = (string) ($payload['dbs_update_service'] ?? '');
        $no_dbs = (string) ($payload['no_dbs'] ?? '0');
        $roles_other = (string) ($payload['roles_other'] ?? '');
        $preferred_roles_label = $payload['roles'] ? implode(', ', (array) $payload['roles']) : 'Not set';
        $address_display_parts = array_filter([
            (string) ($payload['house_number'] ?? ''),
            (string) ($payload['address_line1'] ?? ''),
            (string) ($payload['address_line2'] ?? ''),
            (string) ($payload['address_line3'] ?? ''),
            (string) ($payload['town'] ?? ''),
            (string) ($payload['county'] ?? ''),
            (string) ($payload['postcode'] ?? ''),
        ]);
        $address_display = $address_display_parts ? implode(', ', $address_display_parts) : 'Not set';

        $completion = $this->update_candidate_profile_completion($candidate_id, $user_id);
        $completion_state = $this->get_candidate_profile_completion_state($candidate_id, $user_id);
        $doc_dbs_status = $this->get_candidate_doc_status($candidate_id, $user_id, 'dbs');
        $has_dbs_label = (
            !empty($doc_dbs_status['uploaded'])
            && (string) ($doc_dbs_status['review_status'] ?? '') === 'approved'
        ) ? 'Yes' : ($no_dbs === '1' ? 'No' : 'Not set');
        $this->maybe_notify_candidate_qts_required($candidate_id, $user_id);
        wp_send_json_success([
            'profile' => [
                'first_name' => $first_name,
                'last_name' => $last_name,
                'full_name' => $full_name,
                'email' => $profile_email,
                'phone' => (string) ($payload['phone'] ?? ''),
                'nationality' => (string) ($payload['nationality'] ?? ''),
                'role_type' => (string) ($payload['role_type'] ?? ''),
                'roles' => (array) ($payload['roles'] ?? []),
                'roles_label' => $preferred_roles_label,
                'roles_other' => $roles_other,
                'travel_radius' => (string) ($payload['travel_radius'] ?? ''),
                'location' => (string) ($payload['location'] ?? ''),
                'driving_licence' => $driving_licence,
                'driving_licence_label' => $yes_no_map[$driving_licence] ?? 'Not set',
                'car_owner' => $car_owner,
                'car_owner_label' => $yes_no_map[$car_owner] ?? 'Not set',
                'qts_status' => $qts_status,
                'qts_status_label' => $yes_no_map[$qts_status] ?? 'Not set',
                'no_dbs' => $no_dbs,
                'no_dbs_label' => $no_dbs === '1' ? 'No' : 'Yes',
                'has_dbs_label' => $has_dbs_label,
                'dbs_update_service' => $dbs_update_service,
                'dbs_update_service_label' => $yes_no_map[$dbs_update_service] ?? 'Not set',
                'availability_days' => $availability_days,
                'availability_days_label' => $availability_days_label,
                'house_number' => (string) ($payload['house_number'] ?? ''),
                'address_line1' => (string) ($payload['address_line1'] ?? ''),
                'address_line2' => (string) ($payload['address_line2'] ?? ''),
                'address_line3' => (string) ($payload['address_line3'] ?? ''),
                'town' => (string) ($payload['town'] ?? ''),
                'county' => (string) ($payload['county'] ?? ''),
                'postcode' => (string) ($payload['postcode'] ?? ''),
                'notes' => (string) ($payload['notes'] ?? ''),
                'address_display' => $address_display,
            ],
            'completion' => $completion,
            'completion_missing' => (array) ($completion_state['missing'] ?? []),
            'message' => 'Profile updated.',
        ]);
    }

    public function handle_candidate_contact_card_save() {
        if (!check_ajax_referer('cmn_candidate_profile', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = (int) get_current_user_id();
        $candidate_id = (int) $this->get_candidate_id_for_user($user_id);
        if ($candidate_id < 1) {
            wp_send_json_error(['message' => 'Candidate profile not found.'], 404);
        }

        $raw_skills = $_POST['skills'] ?? [];
        if (!is_array($raw_skills)) {
            $raw_skills = [];
        }
        $skills = array_values(array_unique(array_filter(array_map(
            static function ($item) {
                return sanitize_text_field((string) $item);
            },
            $raw_skills
        ))));
        if (count($skills) > 3) {
            $skills = array_slice($skills, 0, 3);
        }
        if (count($skills) !== 3) {
            wp_send_json_error(['message' => 'Select exactly 3 skills.'], 400);
        }
        $raw_show_available = sanitize_text_field((string) ($_POST['show_available'] ?? '0'));
        $show_available = in_array(strtolower(trim($raw_show_available)), ['1', 'true', 'yes', 'on'], true) ? '1' : '0';

        update_user_meta($user_id, 'cmn_contact_card_skills', $skills);
        update_post_meta($candidate_id, 'cmn_contact_card_skills', $skills);
        update_user_meta($user_id, 'cmn_contact_card_show_available', $show_available);
        update_post_meta($candidate_id, 'cmn_contact_card_show_available', $show_available);

        wp_send_json_success([
            'skills' => $skills,
            'show_available' => $show_available,
            'message' => 'Contact card settings saved.',
        ]);
    }

    public function handle_candidate_upload_doc() {
        if (!check_ajax_referer('cmn_candidate_doc', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $doc_type = sanitize_key((string) ($_POST['doc_type'] ?? ''));
        $keys = $this->get_candidate_doc_meta_keys($doc_type);
        if (!$keys) {
            wp_send_json_error(['message' => 'Invalid document type.'], 400);
        }
        if (empty($_FILES['cmn_doc_file']) || !is_array($_FILES['cmn_doc_file'])) {
            wp_send_json_error(['message' => 'No file selected.'], 400);
        }
        $file = $_FILES['cmn_doc_file'];
        $allowed = $this->get_candidate_doc_allowed_mimes($doc_type);
        $target_limit = (int) $this->get_candidate_doc_target_limit_bytes();
        $effective_limit = (int) wp_max_upload_size();
        $max_file_size = max(1, min($target_limit, $effective_limit > 0 ? $effective_limit : $target_limit));
        if (!empty($file['size']) && (int) $file['size'] > $max_file_size) {
            $message = 'File is too large. Maximum supported upload is ' . size_format($max_file_size) . '.';
            if ($effective_limit > 0 && $effective_limit < $target_limit) {
                $message .= ' Hosting limit is currently lower than the 20MB target.';
            }
            wp_send_json_error(['message' => $message], 400);
        }
        $ext = strtolower((string) pathinfo($file['name'] ?? '', PATHINFO_EXTENSION));
        if ($ext === '' || !isset($allowed[$ext])) {
            wp_send_json_error(['message' => 'File type not allowed.'], 400);
        }

        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';
        $overrides = [
            'test_form' => false,
            'mimes' => $allowed,
        ];
        $uploaded = wp_handle_upload($_FILES['cmn_doc_file'], $overrides);
        if (!empty($uploaded['error'])) {
            wp_send_json_error(['message' => sanitize_text_field((string) $uploaded['error'])], 500);
        }
        $attachment_id = wp_insert_attachment([
            'post_mime_type' => (string) ($uploaded['type'] ?? ''),
            'post_title' => sanitize_file_name(pathinfo((string) $file['name'], PATHINFO_FILENAME)),
            'post_status' => 'inherit',
            'guid' => (string) ($uploaded['url'] ?? ''),
        ], (string) ($uploaded['file'] ?? ''));
        if (is_wp_error($attachment_id) || !$attachment_id) {
            wp_send_json_error(['message' => 'Unable to save uploaded file.'], 500);
        }
        $meta = wp_generate_attachment_metadata($attachment_id, (string) ($uploaded['file'] ?? ''));
        if (!is_wp_error($meta)) {
            wp_update_attachment_metadata($attachment_id, $meta);
        }

        $user_id = get_current_user_id();
        $candidate_id = $this->get_candidate_id_for_user($user_id);
        if (!$candidate_id) {
            wp_delete_attachment((int) $attachment_id, true);
            wp_send_json_error(['message' => 'Candidate profile not found.'], 404);
        }
        $uploaded_at = gmdate('Y-m-d H:i:s');
        update_user_meta($user_id, $keys['attachment'], (int) $attachment_id);
        update_user_meta($user_id, $keys['uploaded_at'], $uploaded_at);
        if (!empty($keys['filename'])) {
            update_user_meta($user_id, $keys['filename'], sanitize_file_name((string) ($file['name'] ?? '')));
        }
        if (!empty($keys['filesize'])) {
            update_user_meta($user_id, $keys['filesize'], (string) (int) ($file['size'] ?? 0));
        }
        if (!empty($keys['mime'])) {
            update_user_meta($user_id, $keys['mime'], sanitize_text_field((string) ($uploaded['type'] ?? '')));
        }
        if (!empty($keys['review_status'])) {
            update_user_meta($user_id, $keys['review_status'], 'pending');
        }
        if (!empty($keys['review_reason'])) {
            delete_user_meta($user_id, $keys['review_reason']);
        }
        if (!empty($keys['reviewed_at'])) {
            delete_user_meta($user_id, $keys['reviewed_at']);
        }
        if (!empty($keys['reviewed_by'])) {
            delete_user_meta($user_id, $keys['reviewed_by']);
        }
        if (!empty($keys['legacy_attachment'])) {
            update_user_meta($user_id, $keys['legacy_attachment'], (int) $attachment_id);
        }
        if (!empty($keys['legacy_uploaded_at'])) {
            update_user_meta($user_id, $keys['legacy_uploaded_at'], $uploaded_at);
        }
        update_post_meta((int) $attachment_id, 'cmn_owner_user_id', (int) $user_id);
        update_post_meta((int) $attachment_id, 'cmn_doc_type', $doc_type);
        update_post_meta((int) $attachment_id, 'cmn_candidate_id', (int) $candidate_id);
        $url = wp_get_attachment_url((int) $attachment_id);
        if ($url) {
            update_post_meta($candidate_id, $keys['post_meta'], esc_url_raw($url));
        }
        if ($doc_type === 'cv') {
            update_post_meta($candidate_id, 'cmn_cv_original_attachment_id', (int) $attachment_id);
            update_post_meta($candidate_id, 'cmn_cv_original_uploaded_at', $uploaded_at);
            $this->add_candidate_cv_audit_entry(
                $candidate_id,
                'Candidate CV upload',
                'Candidate uploaded original CV at ' . $uploaded_at . '.',
                $user_id
            );
            $this->mark_candidate_formatted_cv_outdated($candidate_id, true);
        }
        $completion = $this->update_candidate_profile_completion($candidate_id, $user_id);
        $completion_state = $this->get_candidate_profile_completion_state($candidate_id, $user_id);
        $target_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if (!$target_user_id) {
            $target_user_id = $user_id;
        }
        $status = $this->get_candidate_doc_status($candidate_id, $target_user_id, $doc_type);
        $docs_for_sync = [];
        foreach ($this->get_candidate_doc_types() as $sync_doc_type) {
            $docs_for_sync[$sync_doc_type] = $sync_doc_type === $doc_type
                ? $status
                : $this->get_candidate_doc_status($candidate_id, $target_user_id, $sync_doc_type);
        }
        $verification_status = $this->sync_candidate_admin_verification_status($candidate_id, $target_user_id, $docs_for_sync);
        $compliance = $this->get_candidate_compliance_payload($candidate_id, $target_user_id);
        $this->trigger_automation_event('document_uploaded', 'candidate', (int) $candidate_id, [
            'doc_type' => $doc_type,
            'uploaded_at' => $uploaded_at,
            'automation_meta' => ['source' => 'candidate_doc_upload'],
        ]);
        $admin_recipient = $this->get_admin_recipient_email();
        if ($admin_recipient !== '') {
            $doc_label = strtoupper((string) $doc_type);
            if ($doc_type === 'dbs') {
                $doc_label = 'DBS';
            } elseif ($doc_type === 'id') {
                $doc_label = 'Photo ID';
            }
            $candidate_name = (string) get_the_title($candidate_id);
            $subject = 'Document uploaded by candidate';
            $message = "A candidate uploaded {$doc_label}.\n\nCandidate: {$candidate_name}\nEmail: " . sanitize_text_field((string) get_post_meta($candidate_id, 'cmn_email', true)) . "\n\nReview in the CRM.";
            wp_mail($admin_recipient, $subject, $message);
        }
        $this->notify_staff_admins(
            'candidate_document_uploaded',
            'Candidate document uploaded',
            (string) get_the_title($candidate_id) . ' uploaded ' . strtoupper((string) $doc_type) . '.',
            add_query_arg(['view' => 'compliance-review'], $this->get_portal_base_url()),
            ['module' => 'compliance', 'urgency' => 'normal']
        );
        wp_send_json_success([
            'doc_type' => $doc_type,
            'status' => $status,
            'completion' => $completion,
            'completion_missing' => (array) ($completion_state['missing'] ?? []),
            'verification_status' => $verification_status,
            'compliance' => $compliance,
        ]);
    }

    public function handle_candidate_delete_doc() {
        if (!check_ajax_referer('cmn_candidate_doc', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $doc_type = sanitize_key((string) ($_POST['doc_type'] ?? ''));
        $keys = $this->get_candidate_doc_meta_keys($doc_type);
        if (!$keys) {
            wp_send_json_error(['message' => 'Invalid document type.'], 400);
        }
        $user_id = get_current_user_id();
        $candidate_id = $this->get_candidate_id_for_user($user_id);
        if (!$candidate_id) {
            wp_send_json_error(['message' => 'Candidate profile not found.'], 404);
        }
        $attachment_id = $this->get_candidate_doc_attachment_id($user_id, $doc_type);
        delete_user_meta($user_id, $keys['attachment']);
        delete_user_meta($user_id, $keys['uploaded_at']);
        if (!empty($keys['filename'])) {
            delete_user_meta($user_id, $keys['filename']);
        }
        if (!empty($keys['filesize'])) {
            delete_user_meta($user_id, $keys['filesize']);
        }
        if (!empty($keys['mime'])) {
            delete_user_meta($user_id, $keys['mime']);
        }
        if (!empty($keys['review_status'])) {
            delete_user_meta($user_id, $keys['review_status']);
        }
        if (!empty($keys['review_reason'])) {
            delete_user_meta($user_id, $keys['review_reason']);
        }
        if (!empty($keys['reviewed_at'])) {
            delete_user_meta($user_id, $keys['reviewed_at']);
        }
        if (!empty($keys['reviewed_by'])) {
            delete_user_meta($user_id, $keys['reviewed_by']);
        }
        if (!empty($keys['legacy_attachment'])) {
            delete_user_meta($user_id, $keys['legacy_attachment']);
        }
        if (!empty($keys['legacy_uploaded_at'])) {
            delete_user_meta($user_id, $keys['legacy_uploaded_at']);
        }
        delete_post_meta($candidate_id, $keys['post_meta']);
        if ($doc_type === 'cv') {
            delete_post_meta($candidate_id, 'cmn_cv_original_attachment_id');
            delete_post_meta($candidate_id, 'cmn_cv_original_uploaded_at');
            $this->mark_candidate_formatted_cv_outdated($candidate_id, false);
            $this->add_candidate_cv_audit_entry(
                $candidate_id,
                'Candidate CV removed',
                'Candidate removed original CV from profile.',
                $user_id
            );
        }
        if ($attachment_id && !$this->is_candidate_doc_attachment_still_linked($attachment_id)) {
            wp_delete_attachment((int) $attachment_id, true);
        }
        $completion = $this->update_candidate_profile_completion($candidate_id, $user_id);
        $completion_state = $this->get_candidate_profile_completion_state($candidate_id, $user_id);
        $status = $this->get_candidate_doc_status($candidate_id, $user_id, $doc_type);
        $docs_for_sync = [];
        foreach ($this->get_candidate_doc_types() as $sync_doc_type) {
            $docs_for_sync[$sync_doc_type] = $sync_doc_type === $doc_type
                ? $status
                : $this->get_candidate_doc_status($candidate_id, $user_id, $sync_doc_type);
        }
        $verification_status = $this->sync_candidate_admin_verification_status($candidate_id, $user_id, $docs_for_sync);
        $compliance = $this->get_candidate_compliance_payload($candidate_id, $user_id);
        wp_send_json_success([
            'doc_type' => $doc_type,
            'status' => $status,
            'completion' => $completion,
            'completion_missing' => (array) ($completion_state['missing'] ?? []),
            'verification_status' => $verification_status,
            'compliance' => $compliance,
        ]);
    }

    private function get_candidate_doc_visibility($candidate_id, $doc_type) {
        $candidate_id = (int) $candidate_id;
        $doc_type = sanitize_key((string) $doc_type);
        if ($candidate_id < 1 || $doc_type === '') {
            return 'staff';
        }
        $stored = sanitize_key((string) get_post_meta($candidate_id, 'cmn_doc_visibility_' . $doc_type, true));
        if ($stored === 'all' || $stored === 'staff') {
            return $stored;
        }
        if ($doc_type === 'cv_formatted') {
            return 'all';
        }
        return 'staff';
    }

    private function is_candidate_doc_visible_to_school($candidate_id, $doc_type) {
        return $this->get_candidate_doc_visibility($candidate_id, $doc_type) === 'all';
    }

    public function handle_candidate_get_doc() {
        if (!check_ajax_referer('cmn_candidate_doc', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $doc_type = sanitize_key((string) ($_POST['doc_type'] ?? ''));
        $keys = $this->get_candidate_doc_meta_keys($doc_type);
        if (!$keys) {
            wp_send_json_error(['message' => 'Invalid document type.'], 400);
        }
        $user_id = get_current_user_id();
        $candidate_id = (int) ($_POST['candidate_id'] ?? 0);
        if (!$candidate_id) {
            $candidate_id = $this->get_candidate_id_for_user($user_id);
        }
        if (!$candidate_id) {
            wp_send_json_error(['message' => 'Candidate profile not found.'], 404);
        }
        $candidate_owner_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if (!$candidate_owner_user_id) {
            wp_send_json_error(['message' => 'Candidate owner not found.'], 404);
        }
        if ($this->is_school_user($user_id)) {
            if ($doc_type !== 'cv') {
                wp_send_json_error(['message' => 'Document unavailable.'], 403);
            }
            if (!$this->is_candidate_doc_visible_to_school($candidate_id, 'cv_formatted')) {
                wp_send_json_error(['message' => 'Document restricted to staff.'], 403);
            }
            if (!$this->cmn_school_can_access_candidate_docs($user_id, $candidate_owner_user_id)) {
                wp_send_json_error(['message' => 'Unauthorized.'], 403);
            }
            $formatted = $this->get_candidate_cv_formatted_status($candidate_id);
            if (empty($formatted['available'])) {
                wp_send_json_error(['message' => 'CV is being prepared by our team'], 404);
            }
            $download_url = add_query_arg([
                'action' => 'cmn_candidate_download_doc',
                'candidate_id' => $candidate_id,
                'doc_type' => 'cv',
                'cmn_nonce' => wp_create_nonce('cmn_candidate_download_doc_' . $candidate_id . '_cv_' . $user_id),
            ], admin_url('admin-post.php'));
            wp_send_json_success([
                'doc_type' => 'cv',
                'download_url' => esc_url_raw($download_url),
                'status' => [
                    'uploaded' => true,
                    'doc_status' => 'approved',
                    'status_label' => 'Formatted CV',
                    'filename' => (string) ($formatted['filename'] ?? ''),
                    'uploaded_at' => (string) ($formatted['generated_at'] ?? ''),
                    'uploaded_at_label' => (string) ($formatted['generated_at_label'] ?? ''),
                    'filesize_label' => (string) ($formatted['filesize_label'] ?? ''),
                    'attachment_id' => (int) ($formatted['attachment_id'] ?? 0),
                ],
            ]);
        }
        $status = $this->get_candidate_doc_status($candidate_id, $candidate_owner_user_id, $doc_type);
        if (empty($status['uploaded']) || empty($status['url']) || empty($status['attachment_id'])) {
            wp_send_json_error(['message' => 'Document not uploaded yet.'], 404);
        }
        if (!$this->cmn_candidate_can_access_doc($user_id, $candidate_owner_user_id, (int) $status['attachment_id'])) {
            $message = $this->is_school_user($user_id) ? 'Document not yet verified.' : 'Unauthorized.';
            wp_send_json_error(['message' => $message], 403);
        }
        $download_url = add_query_arg([
            'action' => 'cmn_candidate_download_doc',
            'candidate_id' => $candidate_id,
            'doc_type' => $doc_type,
            'cmn_nonce' => wp_create_nonce('cmn_candidate_download_doc_' . $candidate_id . '_' . $doc_type . '_' . $user_id),
        ], admin_url('admin-post.php'));
        wp_send_json_success([
            'doc_type' => $doc_type,
            'download_url' => esc_url_raw($download_url),
            'status' => $status,
        ]);
    }

    public function handle_get_compliance_status() {
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if (!check_ajax_referer('cmn_candidate_doc', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }

        $requester_id = get_current_user_id();
        $candidate_id = (int) ($_POST['candidate_id'] ?? 0);
        if ($candidate_id < 1) {
            $candidate_id = (int) $this->get_candidate_id_for_user($requester_id);
        }
        if ($candidate_id < 1) {
            wp_send_json_error(['message' => 'Candidate not found.'], 404);
        }

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            wp_send_json_error(['message' => 'Candidate account is not linked.'], 404);
        }

        $allowed = false;
        if ($requester_id === $candidate_user_id) {
            $allowed = true;
        } elseif ($this->is_admin_user($requester_id) || $this->is_staff_role($requester_id)) {
            $allowed = true;
        } elseif ($this->is_account_manager_user($requester_id) && $this->user_can_view_candidate($candidate_id, $requester_id)) {
            $allowed = true;
        }
        if (!$allowed) {
            wp_send_json_error(['message' => 'Access restricted.'], 403);
        }

        wp_send_json_success($this->get_candidate_compliance_payload($candidate_id, $candidate_user_id));
    }

    public function handle_staff_candidate_compliance_decision() {
        if (
            !isset($_POST['cmn_staff_candidate_compliance_decision_nonce'])
            || !wp_verify_nonce((string) $_POST['cmn_staff_candidate_compliance_decision_nonce'], 'cmn_staff_candidate_compliance_decision')
        ) {
            wp_die('Invalid request');
        }
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        $candidate_id = isset($_POST['candidate_id']) ? (int) $_POST['candidate_id'] : 0;
        $decision = sanitize_key((string) ($_POST['decision'] ?? ''));
        $reason = sanitize_text_field((string) ($_POST['reason'] ?? ''));
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            wp_die('Candidate not found');
        }
        if (!in_array($decision, ['approved', 'rejected'], true)) {
            wp_die('Invalid decision');
        }
        if ($decision === 'rejected' && trim($reason) === '') {
            wp_die('Rejection reason is required');
        }
        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            wp_die('Candidate account is not linked');
        }
        $status_value = $decision === 'approved' ? 'approved' : 'rejected';
        update_post_meta($candidate_id, 'cmn_status', $status_value);
        update_post_meta($candidate_id, 'cmn_admin_verification_status', $status_value);
        update_user_meta($candidate_user_id, 'cmn_admin_verification_status', $status_value);
        if ($decision === 'approved') {
            $this->trigger_automation_event('candidate_compliance_approved', 'candidate', (int) $candidate_id, [
                'approved_by' => (int) get_current_user_id(),
                'automation_meta' => ['source' => 'compliance_quick_approve'],
            ]);
        } else {
            update_post_meta($candidate_id, 'cmn_compliance_rejection_reason', $reason);
            $candidate_email = sanitize_email((string) get_post_meta($candidate_id, 'cmn_email', true));
            if ($candidate_email !== '') {
                $subject = 'Compliance review update';
                $message = "Your compliance review has been rejected.\n\nReason: {$reason}\n\nPlease update your profile and documents, then resubmit.";
                $this->send_candidate_email($candidate_email, $subject, $message, [
                    'type' => 'candidate_status_update',
                    'related_candidate_id' => $candidate_id,
                ]);
            }
        }
        $redirect = add_query_arg([
            'view' => 'compliance-review',
            'cmn_doc_review_msg' => rawurlencode($decision === 'approved' ? 'Candidate approved.' : 'Candidate rejected and notified.'),
        ], $this->get_portal_base_url());
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_candidate_download_doc() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized');
        }
        $candidate_id = (int) ($_GET['candidate_id'] ?? 0);
        $doc_type = sanitize_key((string) ($_GET['doc_type'] ?? ''));
        $nonce = sanitize_text_field((string) ($_GET['cmn_nonce'] ?? ''));
        $user_id = get_current_user_id();
        if (!$candidate_id || !$doc_type || !$nonce || !wp_verify_nonce($nonce, 'cmn_candidate_download_doc_' . $candidate_id . '_' . $doc_type . '_' . $user_id)) {
            wp_die('Invalid request');
        }
        $doc_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if (!$doc_user_id) {
            wp_die('Document owner not found.');
        }
        $attachment_id = 0;
        if ($doc_type === 'cv_formatted') {
            if ($this->is_school_user($user_id)) {
                if (!$this->cmn_school_can_access_candidate_docs($user_id, $doc_user_id)) {
                    wp_die('Unauthorized');
                }
                if (!$this->is_candidate_doc_visible_to_school($candidate_id, 'cv_formatted')) {
                    wp_die('Document restricted to staff.');
                }
            } elseif (!$this->is_admin_user($user_id) && !$this->is_staff_role($user_id) && !$this->is_account_manager_user($user_id)) {
                wp_die('Unauthorized');
            }
            $formatted = $this->get_candidate_cv_formatted_status($candidate_id);
            if (empty($formatted['available']) || empty($formatted['attachment_id'])) {
                wp_die('Formatted CV not found.');
            }
            $attachment_id = (int) $formatted['attachment_id'];
        } elseif ($this->is_school_user($user_id)) {
            if ($doc_type !== 'cv') {
                wp_die('Document unavailable.');
            }
            if (!$this->is_candidate_doc_visible_to_school($candidate_id, 'cv_formatted')) {
                wp_die('Document restricted to staff.');
            }
            if (!$this->cmn_school_can_access_candidate_docs($user_id, $doc_user_id)) {
                wp_die('Unauthorized');
            }
            $formatted = $this->get_candidate_cv_formatted_status($candidate_id);
            if (empty($formatted['available']) || empty($formatted['attachment_id'])) {
                wp_die('CV is being prepared by our team');
            }
            $attachment_id = (int) $formatted['attachment_id'];

            $school_id = (int) $this->resolve_school_id_for_user($user_id);
            $school_domain = $school_id ? (string) get_post_meta($school_id, 'cmn_school_email_domain', true) : '';
            if ($school_domain === '' && $school_id) {
                $school_email = (string) get_post_meta($school_id, 'cmn_email', true);
                $school_domain = $this->get_email_domain($school_email);
            }
            if ($school_domain !== '') {
                $this->insert_activity_row([
                    'entity_type' => 'school',
                    'entity_ref' => strtolower(trim($school_domain)),
                    'activity_type' => 'note',
                    'subject' => 'School downloaded formatted CV',
                    'notes' => ((string) get_the_title($candidate_id)) . ' formatted CV downloaded.',
                    'created_by' => $user_id,
                ]);
            }
            $this->add_candidate_cv_audit_entry(
                $candidate_id,
                'School downloaded formatted CV',
                'Formatted CV downloaded by school user #' . $user_id . '.',
                $user_id
            );
        } else {
            $status = $this->get_candidate_doc_status($candidate_id, $doc_user_id, $doc_type);
            if (empty($status['attachment_id'])) {
                wp_die('Document not found.');
            }
            if (!$this->cmn_candidate_can_access_doc($user_id, $doc_user_id, (int) $status['attachment_id'])) {
                wp_die('Unauthorized');
            }
            $attachment_id = (int) $status['attachment_id'];
        }
        if ($attachment_id < 1) {
            wp_die('Document not found.');
        }
        $file = get_attached_file($attachment_id);
        if (!$file || !file_exists($file)) {
            wp_die('Document not found.');
        }
        nocache_headers();
        header('Content-Description: File Transfer');
        header('Content-Type: ' . (string) get_post_mime_type($attachment_id));
        header('Content-Disposition: inline; filename="' . basename($file) . '"');
        header('Content-Length: ' . filesize($file));
        readfile($file);
        exit;
    }

    public function handle_staff_set_candidate_doc_visibility() {
        if (!isset($_POST['cmn_staff_set_candidate_doc_visibility_nonce']) || !wp_verify_nonce((string) $_POST['cmn_staff_set_candidate_doc_visibility_nonce'], 'cmn_staff_set_candidate_doc_visibility')) {
            wp_die('Invalid request');
        }
        if (!is_user_logged_in() || !($this->is_admin_user() || $this->is_staff_user())) {
            wp_die('Unauthorized');
        }
        $candidate_id = (int) ($_POST['candidate_id'] ?? 0);
        $doc_type = sanitize_key((string) ($_POST['doc_type'] ?? ''));
        $visibility = sanitize_key((string) ($_POST['visibility'] ?? 'staff'));
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            wp_die('Candidate not found');
        }
        if (!in_array($doc_type, ['id', 'dbs', 'cv', 'cv_formatted'], true)) {
            wp_die('Invalid document type');
        }
        if (!in_array($visibility, ['staff', 'all'], true)) {
            $visibility = 'staff';
        }
        $return_view = sanitize_key((string) ($_POST['return_view'] ?? 'candidates'));
        if (!in_array($return_view, ['candidates', 'compliance-review', 'compliance_review'], true)) {
            $return_view = 'candidates';
        }
        if ($return_view === 'compliance_review') {
            $return_view = 'compliance-review';
        }
        update_post_meta($candidate_id, 'cmn_doc_visibility_' . $doc_type, $visibility);
        $redirect = add_query_arg([
            'view' => $return_view,
            'candidate_id' => $candidate_id,
            'cmn_doc_review_msg' => rawurlencode('Document visibility updated.'),
        ], $this->get_portal_base_url());
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_staff_delete_candidate_doc() {
        if (!isset($_POST['cmn_staff_delete_candidate_doc_nonce']) || !wp_verify_nonce((string) $_POST['cmn_staff_delete_candidate_doc_nonce'], 'cmn_staff_delete_candidate_doc')) {
            wp_die('Invalid request');
        }
        if (!is_user_logged_in() || !($this->is_admin_user() || $this->is_staff_user())) {
            wp_die('Unauthorized');
        }
        $candidate_id = (int) ($_POST['candidate_id'] ?? 0);
        $doc_type = sanitize_key((string) ($_POST['doc_type'] ?? ''));
        $return_view = sanitize_key((string) ($_POST['return_view'] ?? 'candidates'));
        if (!in_array($return_view, ['candidates', 'compliance-review', 'compliance_review'], true)) {
            $return_view = 'candidates';
        }
        if ($return_view === 'compliance_review') {
            $return_view = 'compliance-review';
        }
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            wp_die('Candidate not found');
        }
        if (!in_array($doc_type, ['cv', 'cv_formatted'], true)) {
            wp_die('Invalid document type');
        }

        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if ($candidate_user_id < 1) {
            wp_die('Candidate account not linked');
        }

        if ($doc_type === 'cv_formatted') {
            $formatted_attachment_id = (int) get_post_meta($candidate_id, 'cmn_cv_formatted_attachment_id', true);
            $formatted_html_attachment_id = (int) get_post_meta($candidate_id, 'cmn_cv_formatted_html_attachment_id', true);
            delete_post_meta($candidate_id, 'cmn_cv_formatted_attachment_id');
            delete_post_meta($candidate_id, 'cmn_cv_formatted_html_attachment_id');
            delete_post_meta($candidate_id, 'cmn_cv_formatted_generated_at');
            delete_post_meta($candidate_id, 'cmn_cv_formatted_uploaded_at');
            delete_post_meta($candidate_id, 'cmn_cv_formatted_generated_by');
            delete_post_meta($candidate_id, 'cmn_cv_formatted_version');
            delete_post_meta($candidate_id, 'cmn_cv_formatted_format');
            delete_post_meta($candidate_id, 'cmn_cv_formatted_outdated');
            if ($formatted_attachment_id > 0) {
                wp_delete_attachment($formatted_attachment_id, true);
            }
            if ($formatted_html_attachment_id > 0) {
                wp_delete_attachment($formatted_html_attachment_id, true);
            }
            $this->add_candidate_cv_audit_entry($candidate_id, 'Formatted CV removed', 'Staff removed formatted CV from candidate profile.', get_current_user_id());
        } else {
            $keys = $this->get_candidate_doc_meta_keys('cv');
            if ($keys) {
                $attachment_id = $this->get_candidate_doc_attachment_id($candidate_user_id, 'cv');
                delete_user_meta($candidate_user_id, $keys['attachment']);
                delete_user_meta($candidate_user_id, $keys['uploaded_at']);
                if (!empty($keys['filename'])) {
                    delete_user_meta($candidate_user_id, $keys['filename']);
                }
                if (!empty($keys['filesize'])) {
                    delete_user_meta($candidate_user_id, $keys['filesize']);
                }
                if (!empty($keys['mime'])) {
                    delete_user_meta($candidate_user_id, $keys['mime']);
                }
                if (!empty($keys['review_status'])) {
                    delete_user_meta($candidate_user_id, $keys['review_status']);
                }
                if (!empty($keys['review_reason'])) {
                    delete_user_meta($candidate_user_id, $keys['review_reason']);
                }
                if (!empty($keys['reviewed_at'])) {
                    delete_user_meta($candidate_user_id, $keys['reviewed_at']);
                }
                if (!empty($keys['reviewed_by'])) {
                    delete_user_meta($candidate_user_id, $keys['reviewed_by']);
                }
                if (!empty($keys['legacy_attachment'])) {
                    delete_user_meta($candidate_user_id, $keys['legacy_attachment']);
                }
                if (!empty($keys['legacy_uploaded_at'])) {
                    delete_user_meta($candidate_user_id, $keys['legacy_uploaded_at']);
                }
                delete_post_meta($candidate_id, $keys['post_meta']);
                delete_post_meta($candidate_id, 'cmn_cv_original_attachment_id');
                delete_post_meta($candidate_id, 'cmn_cv_original_uploaded_at');
                $this->mark_candidate_formatted_cv_outdated($candidate_id, false);
                if ($attachment_id > 0 && !$this->is_candidate_doc_attachment_still_linked($attachment_id)) {
                    wp_delete_attachment((int) $attachment_id, true);
                }
                $this->add_candidate_cv_audit_entry($candidate_id, 'Original CV removed', 'Staff removed original CV from candidate profile.', get_current_user_id());
            }
        }

        $redirect = add_query_arg([
            'view' => $return_view,
            'candidate_id' => $candidate_id,
            'cmn_doc_review_msg' => rawurlencode('Candidate document deleted.'),
        ], $this->get_portal_base_url());
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_staff_review_candidate_doc() {
        if (!isset($_POST['cmn_staff_review_candidate_doc_nonce']) || !wp_verify_nonce($_POST['cmn_staff_review_candidate_doc_nonce'], 'cmn_staff_review_candidate_doc')) {
            wp_die('Invalid request');
        }
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        $candidate_id = (int) ($_POST['candidate_id'] ?? 0);
        $doc_type = sanitize_key((string) ($_POST['doc_type'] ?? ''));
        $review_action = sanitize_key((string) ($_POST['review_action'] ?? ''));
        $review_reason = sanitize_textarea_field((string) ($_POST['review_reason'] ?? ''));
        $return_view = sanitize_key((string) ($_POST['return_view'] ?? 'candidates'));
        if (!in_array($return_view, ['candidates', 'compliance-review', 'compliance_review'], true)) {
            $return_view = 'candidates';
        }
        if ($return_view === 'compliance_review') {
            $return_view = 'compliance-review';
        }
        $portal_url = $this->get_portal_base_url();
        $redirect_url = add_query_arg([
            'view' => $return_view,
            'candidate_id' => $candidate_id,
        ], $portal_url);
        $redirect_with_message = function ($message) use ($redirect_url) {
            wp_safe_redirect(add_query_arg(['cmn_doc_review_msg' => rawurlencode((string) $message)], $redirect_url));
            exit;
        };

        if (!$candidate_id || !$doc_type) {
            $redirect_with_message('Invalid candidate document request.');
        }
        if (!in_array($review_action, ['approved', 'rejected'], true)) {
            $redirect_with_message('Please choose approve or reject.');
        }
        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        if (!$candidate_user_id) {
            $redirect_with_message('Candidate user not found.');
        }
        $keys = $this->get_candidate_doc_meta_keys($doc_type);
        if (!$keys) {
            $redirect_with_message('Invalid document type.');
        }
        $doc_status = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, $doc_type);
        if (empty($doc_status['uploaded']) || empty($doc_status['attachment_id'])) {
            $redirect_with_message('Document is not uploaded yet.');
        }

        if (!empty($keys['review_status'])) {
            update_user_meta($candidate_user_id, $keys['review_status'], $review_action);
        }
        if (!empty($keys['review_reason'])) {
            if ($review_action === 'rejected' && $review_reason !== '') {
                update_user_meta($candidate_user_id, $keys['review_reason'], $review_reason);
            } else {
                delete_user_meta($candidate_user_id, $keys['review_reason']);
            }
        }
        if (!empty($keys['reviewed_at'])) {
            update_user_meta($candidate_user_id, $keys['reviewed_at'], current_time('mysql'));
        }
        if (!empty($keys['reviewed_by'])) {
            update_user_meta($candidate_user_id, $keys['reviewed_by'], get_current_user_id());
        }

        $docs_for_sync = [];
        foreach ($this->get_candidate_doc_types() as $sync_doc_type) {
            $docs_for_sync[$sync_doc_type] = $this->get_candidate_doc_status($candidate_id, $candidate_user_id, $sync_doc_type);
        }
        $this->sync_candidate_admin_verification_status($candidate_id, $candidate_user_id, $docs_for_sync);

        $doc_label_map = [
            'dbs' => 'DBS',
            'id' => 'ID',
            'cv' => 'CV',
        ];
        $doc_label = $doc_label_map[$doc_type] ?? strtoupper($doc_type);
        $candidate_profile_url = add_query_arg(['candidate' => 'profile'], $portal_url);
        if ($review_action === 'approved') {
            $this->add_notification(
                $candidate_user_id,
                'candidate_doc_approved',
                'Document approved',
                'Your ' . $doc_label . ' has been approved.',
                $candidate_profile_url
            );
            $redirect_with_message($doc_label . ' approved.');
        }
        $message = 'Your ' . $doc_label . ' has been rejected.';
        if ($review_reason !== '') {
            $message .= ' Reason: ' . $review_reason;
        }
        $this->add_notification(
            $candidate_user_id,
            'candidate_doc_rejected',
            'Document rejected',
            $message,
            $candidate_profile_url
        );
        $redirect_with_message($doc_label . ' rejected.');
    }

    public function handle_ready_response_save() {
        if (!is_user_logged_in() || !$this->is_school_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_ready_response_nonce']) || !wp_verify_nonce($_POST['cmn_ready_response_nonce'], 'cmn_ready_response_manage')) {
            wp_die('Invalid request');
        }
        $school_user_id = get_current_user_id();
        $response_id = (int) ($_POST['cmn_ready_response_id'] ?? 0);
        $title = sanitize_text_field((string) ($_POST['cmn_ready_response_title'] ?? ''));
        $message_template = sanitize_textarea_field((string) ($_POST['cmn_ready_response_template'] ?? ''));
        $is_default = !empty($_POST['cmn_ready_response_is_default']) ? 1 : 0;
        $redirect_url = add_query_arg(['school' => 'settings'], $this->get_portal_base_url());
        if ($title === '' || $message_template === '') {
            wp_redirect(add_query_arg(['cmn_ready_response_msg' => rawurlencode('Title and message are required.')], $redirect_url));
            exit;
        }

        global $wpdb;
        $table = $this->get_ready_responses_table();
        $now = current_time('mysql');
        $target_id = 0;
        if ($response_id > 0) {
            $existing = $this->get_school_ready_response_by_id($response_id, $school_user_id);
            if ($existing) {
                $wpdb->update($table, [
                    'title' => $title,
                    'is_default' => $is_default,
                    'message_template' => $message_template,
                    'updated_at' => $now,
                ], [
                    'id' => $response_id,
                    'school_user_id' => $school_user_id,
                ], ['%s', '%d', '%s', '%s'], ['%d', '%d']);
                $target_id = $response_id;
            }
        } else {
            $wpdb->insert($table, [
                'school_user_id' => $school_user_id,
                'title' => $title,
                'is_default' => $is_default,
                'message_template' => $message_template,
                'created_at' => $now,
                'updated_at' => $now,
            ], ['%d', '%s', '%d', '%s', '%s', '%s']);
            $target_id = (int) $wpdb->insert_id;
        }

        if ($target_id > 0) {
            if ($is_default) {
                $wpdb->query($wpdb->prepare(
                    "UPDATE {$table} SET is_default = 0 WHERE school_user_id = %d AND id <> %d",
                    $school_user_id,
                    $target_id
                ));
            } else {
                $default_exists = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(1) FROM {$table} WHERE school_user_id = %d AND is_default = 1",
                    $school_user_id
                ));
                if ($default_exists < 1) {
                    $wpdb->update($table, ['is_default' => 1], ['id' => $target_id], ['%d'], ['%d']);
                }
            }
            wp_redirect(add_query_arg(['cmn_ready_response_msg' => rawurlencode('Template saved.')], $redirect_url));
            exit;
        }

        wp_redirect(add_query_arg(['cmn_ready_response_msg' => rawurlencode('Unable to save template.')], $redirect_url));
        exit;
    }

    public function handle_ready_response_delete() {
        if (!is_user_logged_in() || !$this->is_school_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_ready_response_delete_nonce']) || !wp_verify_nonce($_POST['cmn_ready_response_delete_nonce'], 'cmn_ready_response_delete')) {
            wp_die('Invalid request');
        }
        $school_user_id = get_current_user_id();
        $response_id = (int) ($_POST['cmn_ready_response_id'] ?? 0);
        $redirect_url = add_query_arg(['school' => 'settings'], $this->get_portal_base_url());
        if (!$response_id) {
            wp_redirect(add_query_arg(['cmn_ready_response_msg' => rawurlencode('Template not found.')], $redirect_url));
            exit;
        }
        global $wpdb;
        $table = $this->get_ready_responses_table();
        $existing = $this->get_school_ready_response_by_id($response_id, $school_user_id);
        if (!$existing) {
            wp_redirect(add_query_arg(['cmn_ready_response_msg' => rawurlencode('Template not found.')], $redirect_url));
            exit;
        }
        $was_default = (int) ($existing['is_default'] ?? 0) === 1;
        $wpdb->delete($table, [
            'id' => $response_id,
            'school_user_id' => $school_user_id,
        ], ['%d', '%d']);
        if ($was_default) {
            $next_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$table} WHERE school_user_id = %d ORDER BY updated_at DESC, id DESC LIMIT 1",
                $school_user_id
            ));
            if ($next_id > 0) {
                $wpdb->update($table, ['is_default' => 1], ['id' => $next_id], ['%d'], ['%d']);
            }
        }
        wp_redirect(add_query_arg(['cmn_ready_response_msg' => rawurlencode('Template deleted.')], $redirect_url));
        exit;
    }

    private function normalize_priority_month_key($month_key = '') {
        $month_key = trim((string) $month_key);
        if ($month_key === '') {
            return $this->get_priority_month_key();
        }
        if (preg_match('/^\d{4}-\d{2}$/', $month_key) !== 1) {
            return $this->get_priority_month_key();
        }
        return $month_key;
    }

    private function get_priority_month_key(DateTimeImmutable $reference = null) {
        if (!$reference instanceof DateTimeImmutable) {
            $reference = function_exists('cmn_now')
                ? cmn_now()
                : new DateTimeImmutable('now', wp_timezone());
        }
        return $reference->setTimezone(wp_timezone())->format('Y-m');
    }

    private function get_priority_allocation_limit_map() {
        return [
            'standard' => 0,
            'bronze' => 3,
            'silver' => 5,
            'gold' => 10,
            'elite' => 25,
        ];
    }

    public function get_priority_allocation_limit($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return 0;
        }
        $state = $this->ensure_school_partner_state_for_user($school_user_id);
        if (is_wp_error($state)) {
            return 0;
        }
        $tier = sanitize_key((string) ($state['current_tier'] ?? 'standard'));
        $limits = $this->get_priority_allocation_limit_map();
        return max(0, (int) ($limits[$tier] ?? 0));
    }

    public function get_priority_allocation_usage($school_user_id, $month_key) {
        global $wpdb;
        $school_user_id = (int) $school_user_id;
        $month_key = $this->normalize_priority_month_key($month_key);
        if ($school_user_id < 1 || $month_key === '') {
            return 0;
        }
        $table = $this->get_priority_allocations_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return 0;
        }
        return (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM {$table}
             WHERE school_user_id = %d
               AND month_key = %s",
            $school_user_id,
            $month_key
        ));
    }

    private function get_priority_coordinates_for_user_meta($user_id) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return null;
        }
        $lat_keys = ['cmn_lat', 'cmn_latitude', 'cmn_location_lat', 'cmn_geo_lat', 'lat', 'latitude'];
        $lng_keys = ['cmn_lng', 'cmn_long', 'cmn_longitude', 'cmn_location_lng', 'cmn_geo_lng', 'lng', 'longitude'];
        $lat = null;
        $lng = null;
        foreach ($lat_keys as $key) {
            $parsed = $this->parse_marketing_coordinate_value(get_user_meta($user_id, $key, true));
            if ($parsed !== null) {
                $lat = $parsed;
                break;
            }
        }
        foreach ($lng_keys as $key) {
            $parsed = $this->parse_marketing_coordinate_value(get_user_meta($user_id, $key, true));
            if ($parsed !== null) {
                $lng = $parsed;
                break;
            }
        }
        if ($lat === null || $lng === null) {
            return null;
        }
        if ($lat < -90 || $lat > 90 || $lng < -180 || $lng > 180) {
            return null;
        }
        return [
            'lat' => (float) $lat,
            'lng' => (float) $lng,
        ];
    }

    private function get_priority_coordinates_for_school_user($school_user_id) {
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            return null;
        }
        $school_id = (int) $this->resolve_school_id_for_user($school_user_id);
        if ($school_id > 0) {
            $coords = $this->get_geo_coordinates_for_post($school_id);
            if (is_array($coords)) {
                return $coords;
            }
        }
        return $this->get_priority_coordinates_for_user_meta($school_user_id);
    }

    private function get_priority_coordinates_for_candidate($candidate_id, $candidate_user_id = 0) {
        $candidate_id = (int) $candidate_id;
        if ($candidate_id > 0) {
            $coords = $this->get_geo_coordinates_for_post($candidate_id);
            if (is_array($coords)) {
                return $coords;
            }
        }
        $candidate_user_id = (int) $candidate_user_id;
        if ($candidate_user_id > 0) {
            $coords = $this->get_priority_coordinates_for_user_meta($candidate_user_id);
            if (is_array($coords)) {
                return $coords;
            }
        }
        return null;
    }

    private function candidate_matches_priority_booking_role($candidate_id, $booking_role_label = '') {
        $candidate_id = (int) $candidate_id;
        $booking_role_label = sanitize_text_field((string) $booking_role_label);
        if ($candidate_id < 1 || $booking_role_label === '') {
            return true;
        }
        $booking_role_key = sanitize_title($booking_role_label);
        if ($booking_role_key === '') {
            return true;
        }
        $role_labels = $this->get_candidate_role_labels($candidate_id);
        foreach ((array) $role_labels as $label) {
            if (sanitize_title((string) $label) === $booking_role_key) {
                return true;
            }
        }
        return false;
    }

    public function get_candidates_within_radius($school_user_id, $radius_miles = 30, $booking_id = 0) {
        $school_user_id = (int) $school_user_id;
        $radius_miles = max(1.0, min(100.0, (float) $radius_miles));
        $booking_id = (int) $booking_id;
        if ($school_user_id < 1 || !$this->is_school_user($school_user_id)) {
            return [];
        }

        $school_id = (int) $this->resolve_school_id_for_user($school_user_id);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [];
        }

        $school_coords = $this->get_priority_coordinates_for_school_user($school_user_id);
        if (!is_array($school_coords)) {
            return [];
        }

        $booking_role_label = '';
        if ($booking_id > 0 && get_post_type($booking_id) === 'cmn_booking') {
            $booking_school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
            if ($booking_school_id !== $school_id) {
                return [];
            }
            $booking_role_label = sanitize_text_field((string) get_post_meta($booking_id, 'cmn_role', true));
        }

        $candidate_ids = get_posts([
            'post_type' => 'cmn_candidate',
            'post_status' => ['publish', 'private', 'draft', 'pending'],
            'posts_per_page' => 5000,
            'fields' => 'ids',
            'no_found_rows' => true,
            'meta_query' => [
                [
                    'key' => 'cmn_status',
                    'value' => 'approved',
                ],
                [
                    'key' => 'cmn_user_id',
                    'compare' => 'EXISTS',
                ],
            ],
        ]);
        if (!$candidate_ids) {
            return [];
        }

        $lat_delta = $radius_miles / 69.0;
        $lng_divisor = cos(deg2rad((float) $school_coords['lat']));
        if (abs($lng_divisor) < 0.01) {
            $lng_divisor = 0.01;
        }
        $lng_delta = $radius_miles / (69.0 * abs($lng_divisor));
        $matches = [];

        foreach ((array) $candidate_ids as $candidate_id) {
            $candidate_id = (int) $candidate_id;
            if ($candidate_id < 1) {
                continue;
            }
            $candidate_status = sanitize_key((string) get_post_meta($candidate_id, 'cmn_status', true));
            if ($candidate_status !== 'approved') {
                continue;
            }
            if ((string) get_post_meta($candidate_id, 'cmn_deactivated', true) === '1') {
                continue;
            }
            if (!$this->candidate_matches_priority_booking_role($candidate_id, $booking_role_label)) {
                continue;
            }

            $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
            if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
                continue;
            }
            if ((string) get_user_meta($candidate_user_id, 'cmn_deactivated', true) === '1') {
                continue;
            }

            $candidate_coords = $this->get_priority_coordinates_for_candidate($candidate_id, $candidate_user_id);
            if (!is_array($candidate_coords)) {
                continue;
            }
            if (abs((float) $candidate_coords['lat'] - (float) $school_coords['lat']) > $lat_delta) {
                continue;
            }
            if (abs((float) $candidate_coords['lng'] - (float) $school_coords['lng']) > $lng_delta) {
                continue;
            }

            $distance_miles = (float) $this->marketing_haversine_miles(
                (float) $school_coords['lat'],
                (float) $school_coords['lng'],
                (float) $candidate_coords['lat'],
                (float) $candidate_coords['lng']
            );
            if ($distance_miles > $radius_miles) {
                continue;
            }

            $matches[$candidate_user_id] = [
                'candidate_id' => $candidate_id,
                'candidate_user_id' => $candidate_user_id,
                'candidate_name' => (string) get_the_title($candidate_id),
                'distance_miles' => round($distance_miles, 2),
                'role_labels' => $this->get_candidate_role_labels($candidate_id),
            ];
        }

        if (!$matches) {
            return [];
        }
        uasort($matches, static function ($a, $b) {
            return ((float) ($a['distance_miles'] ?? 0)) <=> ((float) ($b['distance_miles'] ?? 0));
        });

        return array_values($matches);
    }

    private function get_school_priority_allocation_booking_options($school_id, $limit = 120) {
        $school_id = (int) $school_id;
        $limit = max(1, min(300, (int) $limit));
        if ($school_id < 1) {
            return [];
        }

        $bookings = get_posts([
            'post_type' => 'cmn_booking',
            'post_status' => ['publish', 'private', 'draft', 'pending'],
            'posts_per_page' => $limit,
            'meta_query' => [
                [
                    'key' => 'cmn_school_id',
                    'value' => $school_id,
                ],
            ],
            'meta_key' => 'cmn_date',
            'orderby' => 'meta_value',
            'order' => 'DESC',
        ]);
        if (!$bookings) {
            return [];
        }

        $rows = [];
        foreach ((array) $bookings as $booking) {
            if (!$booking instanceof WP_Post) {
                continue;
            }
            $booking_id = (int) $booking->ID;
            if ($booking_id < 1) {
                continue;
            }
            $booking_status = sanitize_key((string) get_post_meta($booking_id, 'cmn_status', true));
            if (in_array($booking_status, ['cancelled', 'canceled', 'void', 'deleted'], true)) {
                continue;
            }
            $booking_date = $this->normalize_invoice_date((string) get_post_meta($booking_id, 'cmn_date', true));
            $role_label = sanitize_text_field((string) get_post_meta($booking_id, 'cmn_role', true));
            $date_label = $booking_date !== '' ? date_i18n('D j M Y', strtotime($booking_date)) : 'Date TBC';
            $rows[] = [
                'booking_id' => $booking_id,
                'booking_date' => $booking_date,
                'role_label' => $role_label,
                'label' => 'Booking #' . $booking_id . ' - ' . $date_label . ($role_label !== '' ? ' - ' . $role_label : ''),
            ];
        }

        return $rows;
    }

    private function get_priority_allocation_rows_for_school($school_user_id, $limit = 50) {
        global $wpdb;
        $school_user_id = (int) $school_user_id;
        $limit = max(1, min(250, (int) $limit));
        if ($school_user_id < 1) {
            return [];
        }
        $table = $this->get_priority_allocations_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE school_user_id = %d
             ORDER BY created_at DESC, id DESC
             LIMIT %d",
            $school_user_id,
            $limit
        ), ARRAY_A);
        return is_array($rows) ? $rows : [];
    }

    private function get_priority_interest_count_map(array $allocation_ids) {
        global $wpdb;
        $allocation_ids = array_values(array_filter(array_map('intval', $allocation_ids), static function ($id) {
            return $id > 0;
        }));
        if (!$allocation_ids) {
            return [];
        }
        $table = $this->get_priority_interest_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }
        $placeholders = implode(',', array_fill(0, count($allocation_ids), '%d'));
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT allocation_id, COUNT(*) AS interested_total
             FROM {$table}
             WHERE allocation_id IN ({$placeholders})
             GROUP BY allocation_id",
            ...$allocation_ids
        ), ARRAY_A);
        $map = [];
        foreach ((array) $rows as $row) {
            $allocation_id = (int) ($row['allocation_id'] ?? 0);
            if ($allocation_id < 1) {
                continue;
            }
            $map[$allocation_id] = max(0, (int) ($row['interested_total'] ?? 0));
        }
        return $map;
    }

    private function get_priority_interest_candidates($allocation_id, $limit = 100) {
        global $wpdb;
        $allocation_id = (int) $allocation_id;
        $limit = max(1, min(500, (int) $limit));
        if ($allocation_id < 1) {
            return [];
        }
        $table = $this->get_priority_interest_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT candidate_user_id, created_at
             FROM {$table}
             WHERE allocation_id = %d
             ORDER BY created_at DESC, id DESC
             LIMIT %d",
            $allocation_id,
            $limit
        ), ARRAY_A);
        if (!is_array($rows) || !$rows) {
            return [];
        }

        $output = [];
        foreach ($rows as $row) {
            $candidate_user_id = max(0, (int) ($row['candidate_user_id'] ?? 0));
            if ($candidate_user_id < 1) {
                continue;
            }
            $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
            $candidate_name = '';
            $location = '';
            $role_labels = [];
            if ($candidate_id > 0 && get_post_type($candidate_id) === 'cmn_candidate') {
                $candidate_name = (string) get_the_title($candidate_id);
                $location = sanitize_text_field((string) get_post_meta($candidate_id, 'cmn_location', true));
                $role_labels = $this->get_candidate_role_labels($candidate_id);
            }
            if ($candidate_name === '') {
                $user = get_user_by('id', $candidate_user_id);
                $candidate_name = $user instanceof WP_User ? (string) $user->display_name : ('Candidate #' . $candidate_user_id);
            }
            $output[] = [
                'candidate_user_id' => $candidate_user_id,
                'candidate_id' => $candidate_id,
                'candidate_name' => $candidate_name,
                'location' => $location,
                'role_labels' => $role_labels,
                'created_at' => (string) ($row['created_at'] ?? ''),
            ];
        }
        return $output;
    }

    private function get_priority_allocation_by_id($allocation_id) {
        global $wpdb;
        $allocation_id = (int) $allocation_id;
        if ($allocation_id < 1) {
            return [];
        }
        $table = $this->get_priority_allocations_table();
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT *
             FROM {$table}
             WHERE id = %d
             LIMIT 1",
            $allocation_id
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }

    private function priority_allocation_notification_exists($candidate_user_id, $allocation_id) {
        global $wpdb;
        $candidate_user_id = (int) $candidate_user_id;
        $allocation_id = (int) $allocation_id;
        if ($candidate_user_id < 1 || $allocation_id < 1) {
            return false;
        }
        $table = $this->get_notifications_table();
        $pattern = '%cmn_priority_allocation_id=' . $allocation_id . '%';
        $existing = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*)
             FROM {$table}
             WHERE user_id = %d
               AND type = %s
               AND link_url LIKE %s",
            $candidate_user_id,
            'priority_allocation_alert',
            $pattern
        ));
        return $existing > 0;
    }

    private function build_priority_interest_action_url($allocation_id, $candidate_user_id = 0) {
        $allocation_id = (int) $allocation_id;
        $candidate_user_id = (int) $candidate_user_id;
        $url = add_query_arg([
            'action' => 'cmn_priority_interest_register',
            'cmn_priority_allocation_id' => $allocation_id,
        ], admin_url('admin-post.php'));
        $nonce_action = 'cmn_priority_interest_register_' . $allocation_id;
        return wp_nonce_url($url, $nonce_action, 'cmn_priority_interest_nonce');
    }

    /*
     * Prompt acceptance tests:
     * - Tier limits enforced correctly.
     * - Standard cannot send.
     * - Monthly reset works through month_key changes.
     * - Only candidates within 30 miles are notified.
     * - Duplicate notification per allocation/candidate is prevented.
     * - Audit event priority_allocation_sent is written.
     */
    public function handle_priority_allocation_send() {
        if (!is_user_logged_in() || !$this->is_school_user()) {
            wp_die('Unauthorized');
        }
        $nonce = isset($_POST['cmn_priority_allocation_send_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_priority_allocation_send_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_priority_allocation_send')) {
            wp_die('Invalid request');
        }

        $school_user_id = (int) get_current_user_id();
        $portal_url = $this->get_portal_base_url();
        $redirect_url = add_query_arg(['school' => 'priority-allocation'], $portal_url);
        $school_id = (int) $this->resolve_school_id_for_user($school_user_id);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            wp_safe_redirect(add_query_arg([
                'cmn_priority_notice' => rawurlencode('School profile is not available.'),
                'cmn_priority_notice_type' => 'error',
            ], $redirect_url));
            exit;
        }

        $booking_id = isset($_POST['cmn_priority_booking_id']) ? (int) $_POST['cmn_priority_booking_id'] : 0;
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking') {
            wp_safe_redirect(add_query_arg([
                'cmn_priority_notice' => rawurlencode('Select a valid booking before sending.'),
                'cmn_priority_notice_type' => 'error',
            ], $redirect_url));
            exit;
        }
        $booking_school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        if ($booking_school_id !== $school_id) {
            wp_safe_redirect(add_query_arg([
                'cmn_priority_notice' => rawurlencode('That booking does not belong to your school account.'),
                'cmn_priority_notice_type' => 'error',
            ], $redirect_url));
            exit;
        }

        $message = isset($_POST['cmn_priority_message']) ? sanitize_text_field(wp_unslash((string) $_POST['cmn_priority_message'])) : '';
        if (function_exists('mb_substr')) {
            $message = mb_substr($message, 0, 200);
        } else {
            $message = substr($message, 0, 200);
        }

        $limit = $this->get_priority_allocation_limit($school_user_id);
        if ($limit < 1) {
            wp_safe_redirect(add_query_arg([
                'cmn_priority_notice' => rawurlencode('Unlock Priority Allocation at 30 completed bookings.'),
                'cmn_priority_notice_type' => 'error',
            ], $redirect_url));
            exit;
        }

        $month_key = $this->get_priority_month_key();
        $usage = $this->get_priority_allocation_usage($school_user_id, $month_key);
        if ($usage >= $limit) {
            wp_safe_redirect(add_query_arg([
                'cmn_priority_notice' => rawurlencode('Monthly Priority Allocation limit reached for this tier.'),
                'cmn_priority_notice_type' => 'error',
            ], $redirect_url));
            exit;
        }

        global $wpdb;
        $allocations_table = $this->get_priority_allocations_table();
        $recent_cutoff_ts = max(0, (int) current_time('timestamp') - 120);
        $recent_cutoff = gmdate('Y-m-d H:i:s', $recent_cutoff_ts);
        $recent_duplicate_id = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id
             FROM {$allocations_table}
             WHERE school_user_id = %d
               AND booking_id = %d
               AND month_key = %s
               AND COALESCE(message, '') = %s
               AND created_at >= %s
             ORDER BY id DESC
             LIMIT 1",
            $school_user_id,
            $booking_id,
            $month_key,
            $message,
            $recent_cutoff
        ));
        if ($recent_duplicate_id > 0) {
            wp_safe_redirect(add_query_arg([
                'cmn_priority_notice' => rawurlencode('Priority alert already sent recently for this booking.'),
                'cmn_priority_notice_type' => 'error',
            ], $redirect_url));
            exit;
        }
        $inserted = $wpdb->insert($allocations_table, [
            'school_user_id' => $school_user_id,
            'booking_id' => $booking_id,
            'message' => $message !== '' ? $message : null,
            'status' => 'active',
            'month_key' => $month_key,
            'created_at' => current_time('mysql'),
        ], ['%d', '%d', '%s', '%s', '%s', '%s']);
        if ($inserted === false) {
            wp_safe_redirect(add_query_arg([
                'cmn_priority_notice' => rawurlencode('Unable to send priority allocation right now.'),
                'cmn_priority_notice_type' => 'error',
            ], $redirect_url));
            exit;
        }
        $allocation_id = (int) $wpdb->insert_id;

        $eligible_candidates = $this->get_candidates_within_radius($school_user_id, 30, $booking_id);
        $recipient_count = 0;
        $school_name = (string) get_the_title($school_id);
        if ($school_name === '') {
            $school_name = 'School';
        }
        $booking_date = $this->normalize_invoice_date((string) get_post_meta($booking_id, 'cmn_date', true));
        $booking_date_label = $booking_date !== ''
            ? date_i18n('D j M Y', strtotime($booking_date))
            : 'upcoming booking';
        foreach ((array) $eligible_candidates as $candidate_row) {
            $candidate_user_id = max(0, (int) ($candidate_row['candidate_user_id'] ?? 0));
            if ($candidate_user_id < 1) {
                continue;
            }
            if ($this->priority_allocation_notification_exists($candidate_user_id, $allocation_id)) {
                continue;
            }
            $alert_message = $school_name . ' sent a priority allocation for ' . $booking_date_label . '.';
            if ($message !== '') {
                $alert_message .= ' ' . $message;
            }
            $this->add_notification(
                $candidate_user_id,
                'priority_allocation_alert',
                'Register My Interest',
                $alert_message,
                $this->build_priority_interest_action_url($allocation_id, $candidate_user_id)
            );
            $recipient_count++;
        }

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'school_partner',
                'entity_type' => 'school',
                'entity_id' => $school_user_id,
                'event_type' => 'priority_allocation_sent',
                'metadata' => [
                    'booking_id' => $booking_id,
                    'recipient_count' => $recipient_count,
                ],
            ]);
        }

        wp_safe_redirect(add_query_arg([
            'cmn_priority_notice' => rawurlencode('Priority alert sent to ' . $recipient_count . ' candidate(s).'),
            'cmn_priority_notice_type' => 'success',
        ], $redirect_url));
        exit;
    }

    /*
     * Prompt acceptance tests:
     * - Candidate can register interest once per allocation.
     * - Duplicate interest attempts are prevented by unique key.
     * - School is notified when interest is registered.
     * - Audit event priority_interest_registered is written.
     * - No auto-booking is triggered.
     */
    public function handle_priority_interest_register() {
        $allocation_id = isset($_REQUEST['cmn_priority_allocation_id']) ? (int) wp_unslash($_REQUEST['cmn_priority_allocation_id']) : 0;
        $candidate_redirect = add_query_arg(['candidate' => 'bookings'], $this->get_portal_base_url());
        if (!is_user_logged_in()) {
            wp_safe_redirect(wp_login_url($candidate_redirect));
            exit;
        }
        $candidate_user_id = (int) get_current_user_id();
        if (!$this->is_candidate_user($candidate_user_id)) {
            wp_die('Unauthorized');
        }
        if ($allocation_id < 1) {
            wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('Priority allocation link is invalid.')], $candidate_redirect));
            exit;
        }

        $nonce = isset($_REQUEST['cmn_priority_interest_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_REQUEST['cmn_priority_interest_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_priority_interest_register_' . $allocation_id)) {
            wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('Priority allocation link has expired.')], $candidate_redirect));
            exit;
        }

        $allocation = $this->get_priority_allocation_by_id($allocation_id);
        if (!$allocation) {
            wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('Priority allocation no longer exists.')], $candidate_redirect));
            exit;
        }
        $allocation_status = sanitize_key((string) ($allocation['status'] ?? 'active'));
        if (!in_array($allocation_status, ['active'], true)) {
            wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('This priority allocation is closed.')], $candidate_redirect));
            exit;
        }

        $school_user_id = max(0, (int) ($allocation['school_user_id'] ?? 0));
        $booking_id = max(0, (int) ($allocation['booking_id'] ?? 0));
        if ($school_user_id < 1 || $booking_id < 1) {
            wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('Priority allocation data is incomplete.')], $candidate_redirect));
            exit;
        }

        $eligible = $this->get_candidates_within_radius($school_user_id, 30, $booking_id);
        $allowed_user_ids = array_map(static function ($row) {
            return max(0, (int) ($row['candidate_user_id'] ?? 0));
        }, (array) $eligible);
        if (!in_array($candidate_user_id, $allowed_user_ids, true)) {
            wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('You are not eligible for this priority allocation.')], $candidate_redirect));
            exit;
        }

        global $wpdb;
        $interest_table = $this->get_priority_interest_table();
        $inserted = $wpdb->insert($interest_table, [
            'allocation_id' => $allocation_id,
            'candidate_user_id' => $candidate_user_id,
            'created_at' => current_time('mysql'),
        ], ['%d', '%d', '%s']);
        if ($inserted === false) {
            $already_registered = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*)
                 FROM {$interest_table}
                 WHERE allocation_id = %d
                   AND candidate_user_id = %d",
                $allocation_id,
                $candidate_user_id
            )) > 0;
            if ($already_registered) {
                wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('Your interest is already registered.')], $candidate_redirect));
                exit;
            }
            wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('Unable to register interest right now.')], $candidate_redirect));
            exit;
        }

        $candidate_id = (int) $this->get_candidate_id_for_user($candidate_user_id);
        $candidate_name = $candidate_id > 0 ? (string) get_the_title($candidate_id) : '';
        if ($candidate_name === '') {
            $user = get_user_by('id', $candidate_user_id);
            $candidate_name = $user instanceof WP_User ? (string) $user->display_name : ('Candidate #' . $candidate_user_id);
        }
        $school_link = add_query_arg([
            'school' => 'priority-allocation',
            'cmn_priority_allocation_id' => $allocation_id,
        ], $this->get_portal_base_url());
        $this->add_notification(
            $school_user_id,
            'priority_interest_registered',
            'Priority interest received',
            $candidate_name . ' registered interest for Booking #' . $booking_id . '.',
            $school_link
        );

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'candidate',
                'entity_type' => 'candidate',
                'entity_id' => $candidate_user_id,
                'event_type' => 'priority_interest_registered',
                'metadata' => [
                    'allocation_id' => $allocation_id,
                ],
            ]);
        }

        wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('Your interest has been registered.')], $candidate_redirect));
        exit;
    }

    public function handle_school_live_match_action() {
        if (!check_ajax_referer('cmn_school_live_match_action', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_school_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $school_id = $this->resolve_school_id_for_user();
        if (!$school_id) {
            wp_send_json_error(['message' => 'School profile not found.'], 404);
        }
        $candidate_id = (int) ($_POST['candidate_id'] ?? 0);
        $action_type = sanitize_key((string) ($_POST['match_action'] ?? ''));
        if ($candidate_id < 1 || $action_type === '') {
            wp_send_json_error(['message' => 'Missing action details.'], 400);
        }

        if ($action_type === 'not_interested') {
            $days = max(1, (int) get_option('cmn_school_not_interested_days', 7));
            $until = gmdate('Y-m-d H:i:s', strtotime('+' . $days . ' days'));
            update_post_meta($candidate_id, 'cmn_school_hidden_until_' . (int) $school_id, $until);
            $this->add_audit_log('school_live_match_not_interested', 'candidate', (string) $candidate_id, [
                'school_id' => (int) $school_id,
                'days' => $days,
                'hidden_until' => $until,
            ]);
            wp_send_json_success(['message' => 'Candidate removed from this feed.']);
        }

        if ($action_type === 'restore_not_interested' || $action_type === 'put_back') {
            delete_post_meta($candidate_id, 'cmn_school_hidden_until_' . (int) $school_id);
            $this->add_audit_log('school_live_match_not_interested_restored', 'candidate', (string) $candidate_id, [
                'school_id' => (int) $school_id,
            ]);
            wp_send_json_success(['message' => 'Candidate restored to main list.']);
        }

        if ($action_type === 'shortlist_toggle') {
            $shortlisted_ids = array_values(array_unique(array_map('intval', (array) get_post_meta($school_id, 'cmn_shortlisted_candidate_ids', true))));
            $is_shortlisted = in_array($candidate_id, $shortlisted_ids, true);
            if ($is_shortlisted) {
                $shortlisted_ids = array_values(array_filter($shortlisted_ids, function($id) use ($candidate_id){ return (int) $id !== $candidate_id; }));
            } else {
                $shortlisted_ids[] = $candidate_id;
            }
            update_post_meta($school_id, 'cmn_shortlisted_candidate_ids', $shortlisted_ids);
            $this->add_audit_log('school_live_match_shortlist_toggled', 'candidate', (string) $candidate_id, [
                'school_id' => (int) $school_id,
                'is_shortlisted' => $is_shortlisted ? 0 : 1,
            ]);
            wp_send_json_success(['is_shortlisted' => $is_shortlisted ? 0 : 1]);
        }

        if ($action_type === 'broadcast_request') {
            $this->add_audit_log('school_live_match_broadcast_request', 'school', (string) $school_id, [
                'user_id' => (int) get_current_user_id(),
            ]);
            wp_send_json_success(['message' => 'Broadcast request logged.']);
        }

        if ($action_type === 'book_now') {
            $_POST['requested_date'] = sanitize_text_field((string) ($_POST['requested_date'] ?? current_time('Y-m-d')));
            $_POST['candidate_id'] = $candidate_id;
            $_POST['nonce'] = wp_create_nonce('cmn_request_candidate');
            // Mirror request creation while keeping expiry at 10 minutes.
            add_filter('cmn_request_expiry_minutes', function(){ return 10; });
            $this->add_audit_log('school_live_match_book_now_clicked', 'candidate', (string) $candidate_id, [
                'school_id' => (int) $school_id,
            ]);
            $this->handle_request_candidate();
            return;
        }

        wp_send_json_error(['message' => 'Unknown action.'], 400);
    }

    public function handle_school_live_match_presence() {
        if (!check_ajax_referer('cmn_school_live_match_action', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_school_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $school_id = $this->resolve_school_id_for_user();
        if (!$school_id) {
            wp_send_json_error(['message' => 'School profile not found.'], 404);
        }

        $raw_candidate_ids = $_POST['candidate_ids'] ?? [];
        if (!is_array($raw_candidate_ids)) {
            $raw_candidate_ids = explode(',', (string) $raw_candidate_ids);
        }
        $candidate_ids = [];
        foreach ((array) $raw_candidate_ids as $raw_id) {
            $candidate_id = (int) $raw_id;
            if ($candidate_id > 0) {
                $candidate_ids[$candidate_id] = $candidate_id;
            }
            if (count($candidate_ids) >= 100) {
                break;
            }
        }
        if (!$candidate_ids) {
            wp_send_json_success(['presence' => []]);
        }

        $presence = [];
        foreach (array_values($candidate_ids) as $candidate_id) {
            if (get_post_type($candidate_id) !== 'cmn_candidate') {
                continue;
            }
            if ($this->is_candidate_hidden_for_school_live_matches((int) $school_id, (int) $candidate_id)) {
                continue;
            }
            $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
            if ($candidate_user_id < 1) {
                $presence[(string) $candidate_id] = [
                    'is_online' => 0,
                    'label' => 'Last seen at --:--',
                ];
                continue;
            }
            $snapshot = $this->get_candidate_presence_snapshot($candidate_user_id);
            $presence[(string) $candidate_id] = [
                'is_online' => !empty($snapshot['is_online']) ? 1 : 0,
                'label' => sanitize_text_field((string) ($snapshot['last_online_label'] ?? 'Last seen at --:--')),
            ];
        }

        wp_send_json_success(['presence' => $presence]);
    }

    public function handle_request_candidate() {
        if (!check_ajax_referer('cmn_request_candidate', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_school_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }

        $school_id = $this->resolve_school_id_for_user();
        if (!$school_id) {
            wp_send_json_error(['message' => 'School profile not found.'], 404);
        }
        $status = get_post_meta($school_id, 'cmn_status', true);
        if ($status !== 'client') {
            wp_send_json_error(['message' => 'School access is pending approval.'], 403);
        }

        $candidate_id = intval($_POST['candidate_id'] ?? 0);
        if (!$candidate_id) {
            wp_send_json_error(['message' => 'Missing candidate.'], 400);
        }
        $candidate = get_post($candidate_id);
        if (!$candidate || $candidate->post_type !== 'cmn_candidate') {
            wp_send_json_error(['message' => 'Candidate not found.'], 404);
        }
        $candidate_status = get_post_meta($candidate_id, 'cmn_status', true);
        if ($candidate_status && $candidate_status !== 'approved') {
            wp_send_json_error(['message' => 'Candidate is not available.'], 400);
        }
        if (!$this->is_candidate_operationally_unlocked($candidate_id)) {
            wp_send_json_error(['message' => 'Candidate has not completed required operational documents.'], 400);
        }

        $today_date = current_time('Y-m-d');
        $tomorrow_date = $this->get_tomorrow_date();
        $requested_date = sanitize_text_field((string) ($_POST['requested_date'] ?? ''));
        $target_date = $tomorrow_date;
        if ($requested_date !== '' && in_array($requested_date, [$today_date, $tomorrow_date], true)) {
            $target_date = $requested_date;
        }
        if ($this->is_candidate_unavailable($candidate_id, $target_date)) {
            $label = ($target_date === $today_date) ? 'today morning' : 'tomorrow morning';
            wp_send_json_error(['message' => 'Candidate is marked unavailable for ' . $label . '.'], 400);
        }

        $school_domain = get_post_meta($school_id, 'cmn_school_email_domain', true);
        if (!$school_domain) {
            $school_email = get_post_meta($school_id, 'cmn_email', true);
            $school_domain = $this->get_email_domain($school_email);
        }
        if (!$school_domain) {
            wp_send_json_error(['message' => 'School domain missing.'], 400);
        }

        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $request_sent_at = current_time('mysql');
        $expiry_minutes = max(1, (int) apply_filters('cmn_request_expiry_minutes', 10));
        $expires_at = gmdate('Y-m-d H:i:s', strtotime(gmdate('Y-m-d H:i:s') . ' +' . $expiry_minutes . ' minutes'));
        $account_manager_user_id = $this->get_request_account_manager_user_id($school_id);
        $ready_response_id = $this->normalize_ready_response_selection_for_request($_POST['ready_response_id'] ?? '', get_current_user_id());
        $requested_role_label = sanitize_text_field((string) ($_POST['role_label'] ?? ''));
        $requested_role_key = sanitize_title($requested_role_label);
        $requested_candidate_pay_rate = isset($_POST['candidate_pay_rate']) ? (float) $_POST['candidate_pay_rate'] : 0.0;
        $requested_school_charge_rate = isset($_POST['school_charge_rate']) ? (float) $_POST['school_charge_rate'] : 0.0;
        $candidate_pay_rate = $requested_candidate_pay_rate > 0
            ? round($requested_candidate_pay_rate, 2)
            : $this->get_request_candidate_pay_rate($candidate_id, $school_id, [
                'role_key' => $requested_role_key !== '' ? $requested_role_key : 'default',
            ]);
        $school_charge_rate = $requested_school_charge_rate > 0
            ? round($requested_school_charge_rate, 2)
            : $this->get_request_school_charge_rate($candidate_pay_rate, [
                'candidate_id' => $candidate_id,
                'school_id' => $school_id,
                'role_key' => $requested_role_key !== '' ? $requested_role_key : 'default',
                'school_email_domain' => $school_domain,
            ]);
        $inserted = $wpdb->insert($table, [
            'school_id' => $school_id,
            'school_email_domain' => $school_domain,
            'school_user_id' => get_current_user_id(),
            'candidate_id' => $candidate_id,
            'account_manager_user_id' => $account_manager_user_id ?: null,
            'ready_response_id' => $ready_response_id,
            'requested_date' => $target_date,
            'status' => 'requested',
            'request_sent_at' => $request_sent_at,
            'expires_at' => $expires_at,
            'candidate_pay_rate' => $candidate_pay_rate,
            'school_charge_rate' => $school_charge_rate,
            'internal_note' => $requested_role_label !== '' ? ('Requested role: ' . $requested_role_label) : '',
            'requested_at' => $request_sent_at,
            'updated_at' => $request_sent_at,
        ], ['%d', '%s', '%d', '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%f', '%f', '%s', '%s', '%s']);

        if (!$inserted) {
            wp_send_json_success([
                'message' => 'Your request has already been sent.',
                'already' => true,
            ]);
        }

        $school_name = get_the_title($school_id);
        $candidate_name = $candidate ? $candidate->post_title : 'Candidate';
        $note = 'School requested ' . $candidate_name . ' for ' . $target_date . ' (morning).';
        $this->insert_activity_row([
            'entity_type' => 'school',
            'entity_ref' => $school_domain,
            'activity_type' => 'note',
            'subject' => 'School requested candidate',
            'notes' => $note,
            'created_by' => get_current_user_id(),
        ]);
        $this->insert_activity_row([
            'entity_type' => 'contact',
            'entity_ref' => (string) $candidate_id,
            'activity_type' => 'note',
            'subject' => 'School requested candidate',
            'notes' => ($school_name ? $school_name . ' requested availability.' : $note),
            'created_by' => get_current_user_id(),
        ]);
        $assigned_manager = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
        $this->insert_activity_row([
            'entity_type' => 'school',
            'entity_ref' => $school_domain,
            'activity_type' => 'task',
            'subject' => 'Confirm candidate availability',
            'notes' => $candidate_name . ' - ' . $target_date,
            'due_date' => $target_date,
            'assigned_to_user_id' => $assigned_manager ?: null,
            'assigned_to_school_domain' => $school_domain,
            'created_by' => get_current_user_id(),
        ]);

        $request_id = (int) $wpdb->insert_id;
        $this->add_audit_log('booking_request_created', 'request', (string) $request_id, [
            'school_id' => (int) $school_id,
            'candidate_id' => (int) $candidate_id,
            'requested_date' => $target_date,
        ]);
        $staff_link = add_query_arg(['view' => 'requests'], $this->get_portal_base_url());
        $candidate_link = add_query_arg(['candidate' => 'bookings'], $this->get_portal_base_url());
        $candidate_user_id = $this->get_candidate_user_id($candidate_id);

        if ($account_manager_user_id) {
            $this->add_notification(
                $account_manager_user_id,
                'booking_request_new',
                'New booking request',
                $school_name . ' requested ' . $candidate_name . ' for ' . date_i18n('M j, Y', strtotime($target_date)),
                $staff_link
            );
        }
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            if ($account_manager_user_id && (int) $admin_id === (int) $account_manager_user_id) {
                continue;
            }
            $this->add_notification(
                $admin_id,
                'booking_request_new',
                'New booking request',
                $school_name . ' requested ' . $candidate_name . ' for ' . date_i18n('M j, Y', strtotime($target_date)),
                $staff_link
            );
        }
        if ($candidate_user_id) {
            $this->add_notification(
                $candidate_user_id,
                'booking_request',
                'Booking request',
                'You have a booking request for ' . date_i18n('M j, Y', strtotime($target_date)),
                $candidate_link
            );
        }
        $candidate_email = sanitize_email(get_post_meta($candidate_id, 'cmn_email', true));
        if ($candidate_email) {
            $subject = 'You have a booking request';
            $message = "You have a booking request for " . date_i18n('l, F jS', strtotime($target_date)) . ".\n\nPlease log into your portal to respond:\n" . $candidate_link;
            $this->send_candidate_email($candidate_email, $subject, $message, [
                'type' => 'candidate_availability_request',
                'related_candidate_id' => $candidate_id,
                'related_request_id' => $request_id,
            ]);
        }

        wp_send_json_success([
            'message' => 'Your request has been sent. We will confirm availability shortly.',
            'date' => $target_date,
            'request_id' => $request_id,
            'expires_at' => $expires_at,
        ]);
    }

    public function handle_school_rebook_candidate() {
        if (
            !isset($_POST['cmn_school_rebook_nonce']) ||
            !wp_verify_nonce((string) $_POST['cmn_school_rebook_nonce'], 'cmn_school_rebook_candidate')
        ) {
            wp_die('Invalid request');
        }
        if (!is_user_logged_in() || !$this->is_school_user()) {
            wp_die('Unauthorized');
        }
        $school_id = $this->resolve_school_id_for_user();
        if (!$school_id) {
            wp_die('School profile not found');
        }
        $status = (string) get_post_meta($school_id, 'cmn_status', true);
        if ($status !== 'client') {
            wp_die('School access is pending approval.');
        }
        $candidate_id = isset($_POST['candidate_id']) ? (int) $_POST['candidate_id'] : 0;
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            wp_die('Candidate not found');
        }
        $requested_date = sanitize_text_field((string) ($_POST['requested_date'] ?? ''));
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $requested_date)) {
            $requested_date = $this->get_tomorrow_date();
        }
        $today = current_time('Y-m-d');
        if ($requested_date < $today) {
            $requested_date = $today;
        }
        $candidate_pay_rate = isset($_POST['candidate_pay_rate']) ? (float) $_POST['candidate_pay_rate'] : 0.0;
        if ($candidate_pay_rate <= 0) {
            $candidate_pay_rate = $this->get_request_candidate_pay_rate($candidate_id, $school_id);
        }
        $school_charge_rate = isset($_POST['school_charge_rate']) ? (float) $_POST['school_charge_rate'] : 0.0;
        if ($school_charge_rate <= 0) {
            $school_charge_rate = $this->get_request_school_charge_rate($candidate_pay_rate, [
                'candidate_id' => $candidate_id,
                'school_id' => $school_id,
                'school_email_domain' => $school_domain,
            ]);
        }
        $start_time = sanitize_text_field((string) ($_POST['start_time'] ?? ''));
        $end_time = sanitize_text_field((string) ($_POST['end_time'] ?? ''));
        $time_slot_note = trim($start_time . ($end_time !== '' ? (' - ' . $end_time) : ''));

        $school_domain = (string) get_post_meta($school_id, 'cmn_school_email_domain', true);
        if ($school_domain === '') {
            $school_email = (string) get_post_meta($school_id, 'cmn_email', true);
            $school_domain = $this->get_email_domain($school_email);
        }
        if ($school_domain === '') {
            wp_die('School domain missing.');
        }

        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $now_mysql = current_time('mysql');
        $expiry_minutes = max(1, (int) apply_filters('cmn_request_expiry_minutes', 10));
        $expires_at = gmdate('Y-m-d H:i:s', strtotime(gmdate('Y-m-d H:i:s') . ' +' . $expiry_minutes . ' minutes'));
        $ready_response_id = $this->normalize_ready_response_selection_for_request($_POST['ready_response_id'] ?? '', get_current_user_id());
        $account_manager_user_id = $this->get_request_account_manager_user_id($school_id);
        $internal_note = 'Rebook request created from booking history.';
        if ($time_slot_note !== '') {
            $internal_note .= ' Time slot: ' . $time_slot_note . '.';
        }
        $inserted = $wpdb->insert($table, [
            'school_id' => $school_id,
            'school_email_domain' => $school_domain,
            'school_user_id' => get_current_user_id(),
            'candidate_id' => $candidate_id,
            'account_manager_user_id' => $account_manager_user_id ?: null,
            'ready_response_id' => $ready_response_id,
            'requested_date' => $requested_date,
            'status' => 'requested',
            'request_sent_at' => $now_mysql,
            'expires_at' => $expires_at,
            'candidate_pay_rate' => $candidate_pay_rate,
            'school_charge_rate' => $school_charge_rate,
            'internal_note' => $internal_note,
            'requested_at' => $now_mysql,
            'updated_at' => $now_mysql,
        ], ['%d', '%s', '%d', '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%f', '%f', '%s', '%s', '%s']);
        $redirect_url = add_query_arg(['school' => 'requests'], $this->get_portal_base_url());
        if (!$inserted) {
            wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('This rebook request already exists.')], $redirect_url));
            exit;
        }

        $request_id = (int) $wpdb->insert_id;
        $this->add_audit_log('booking_request_created', 'request', (string) $request_id, [
            'school_id' => (int) $school_id,
            'candidate_id' => (int) $candidate_id,
            'requested_date' => $requested_date,
            'source' => 'rebook',
        ]);
        $candidate_name = get_the_title($candidate_id) ?: 'Candidate';
        $school_name = get_the_title($school_id) ?: 'School';
        $staff_link = add_query_arg(['view' => 'requests'], $this->get_portal_base_url());
        $candidate_link = add_query_arg(['candidate' => 'bookings'], $this->get_portal_base_url());
        $candidate_user_id = $this->get_candidate_user_id($candidate_id);

        if ($account_manager_user_id) {
            $this->add_notification(
                $account_manager_user_id,
                'booking_request_new',
                'New booking request',
                $school_name . ' rebooked ' . $candidate_name . ' for ' . date_i18n('M j, Y', strtotime($requested_date)),
                $staff_link
            );
        }
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            if ($account_manager_user_id && (int) $admin_id === (int) $account_manager_user_id) {
                continue;
            }
            $this->add_notification(
                (int) $admin_id,
                'booking_request_new',
                'New booking request',
                $school_name . ' rebooked ' . $candidate_name . ' for ' . date_i18n('M j, Y', strtotime($requested_date)),
                $staff_link
            );
        }
        if ($candidate_user_id) {
            $this->add_notification(
                $candidate_user_id,
                'booking_request',
                'Booking request',
                'You have a booking request for ' . date_i18n('M j, Y', strtotime($requested_date)),
                $candidate_link
            );
        }
        $candidate_email = sanitize_email((string) get_post_meta($candidate_id, 'cmn_email', true));
        if ($candidate_email) {
            $this->send_candidate_email($candidate_email, 'You have a booking request', "You have a booking request for " . date_i18n('l, F jS', strtotime($requested_date)) . ".\n\nPlease log into your portal:\n{$candidate_link}", [
                'type' => 'candidate_availability_request',
                'related_candidate_id' => $candidate_id,
                'related_request_id' => $request_id,
            ]);
        }
        wp_safe_redirect(add_query_arg(['cmn_notice' => rawurlencode('Rebook request sent.')], $redirect_url));
        exit;
    }

    public function handle_candidate_request_action() {
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_candidate_request_action_nonce']) || !wp_verify_nonce($_POST['cmn_candidate_request_action_nonce'], 'cmn_candidate_request_action')) {
            wp_die('Invalid request');
        }
        $request_id = (int) ($_POST['cmn_request_id'] ?? 0);
        $action = sanitize_key((string) ($_POST['cmn_request_action'] ?? ''));
        $request = $this->get_candidate_request_by_id($request_id);
        if (!$request) {
            wp_die('Request not found');
        }
        $request = $this->ensure_request_has_guardrail_rates($request);
        $candidate_id = $this->get_candidate_id_for_user();
        if (!$candidate_id || (int) $request['candidate_id'] !== (int) $candidate_id) {
            wp_die('Unauthorized');
        }
        $this->maybe_mark_request_expired($request);
        $school_id = (int) ($request['school_id'] ?? 0);
        if (!$school_id) {
            $school_id = $this->get_school_post_id_by_domain($request['school_email_domain'] ?? '');
        }
        $am_user_id = $this->get_request_account_manager_user_id($school_id, $request);
        $portal_url = $this->get_portal_base_url();
        $candidate_bookings_url = add_query_arg(['candidate' => 'bookings'], $portal_url);
        $staff_requests_url = add_query_arg(['view' => 'requests'], $portal_url);
        $school_requests_url = add_query_arg(['school' => 'requests'], $portal_url);
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $now = current_time('mysql');
        $current_status = strtolower((string) ($request['status'] ?? 'requested'));

        if ($action === 'still_needed') {
            if ($current_status === 'requested') {
                $this->maybe_mark_request_expired($request);
                $current_status = strtolower((string) ($request['status'] ?? 'expired'));
            }
            if ($current_status !== 'expired') {
                wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('This request is still active.')], $this->get_portal_base_url()));
                exit;
            }
            if ($am_user_id) {
                $this->add_notification(
                    $am_user_id,
                    'booking_request_expired_ping',
                    'Expired booking - candidate asking if still needed',
                    get_the_title($candidate_id) . " clicked 'Is this still needed?'",
                    $staff_requests_url
                );
            }
            foreach ($this->get_admin_users_for_support() as $admin_id) {
                if ($am_user_id && (int) $admin_id === (int) $am_user_id) {
                    continue;
                }
                $this->add_notification(
                    (int) $admin_id,
                    'booking_request_expired_ping',
                    'Expired booking - candidate asking if still needed',
                    get_the_title($candidate_id) . " clicked 'Is this still needed?'",
                    $staff_requests_url
                );
            }
            $this->add_audit_log('booking_request_still_needed_ping', 'request', (string) $request_id, [
                'candidate_id' => (int) $candidate_id,
                'school_domain' => (string) ($request['school_email_domain'] ?? ''),
            ]);
            wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('We\'re checking with the school. We will update you.')], $this->get_portal_base_url()));
            exit;
        }

        if (!in_array($current_status, ['requested'], true)) {
            wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('This request can no longer be updated.')], $this->get_portal_base_url()));
            exit;
        }
        if ($this->is_request_expired($request)) {
            $this->maybe_mark_request_expired($request);
            wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('This request has expired.')], $this->get_portal_base_url()));
            exit;
        }

        if ($action === 'negotiate') {
            $booking_id = (int) get_post_meta($request_id, 'cmn_booking_id', true);
            if (!$booking_id) {
                $booking_id = $this->create_booking_from_request($request, $school_id, get_current_user_id());
                if ($booking_id) {
                    update_post_meta($booking_id, 'cmn_status', 'requested');
                    update_post_meta($booking_id, 'cmn_request_id', $request_id);
                    update_post_meta($request_id, 'cmn_booking_id', $booking_id);
                }
            }
            if ($booking_id) {
                $candidate_user_id = get_current_user_id();
                $school_user_id = $this->get_school_user_id_for_request($request, $school_id);
                $thread_id = $this->create_or_get_booking_thread($booking_id, 'pay_negotiation', [
                    'candidate_user_id' => $candidate_user_id,
                    'school_user_id' => $school_user_id,
                    'account_manager_user_id' => $am_user_id,
                    'status' => 'active',
                ]);
                if ($thread_id) {
                    $this->add_booking_thread_participant($thread_id, $candidate_user_id, 'candidate');
                    if ($am_user_id) {
                        $this->add_booking_thread_participant($thread_id, $am_user_id, 'account_manager');
                    }
                    $existing_messages = $this->get_booking_thread_messages($thread_id);
                    if (!$existing_messages) {
                        $this->add_booking_thread_message($thread_id, $am_user_id, 'account_manager', 'Pay negotiation only. This chat is between you and the account manager.');
                    }
                    update_post_meta($booking_id, 'cmn_active_thread', 'pay_negotiation');
                }
                $candidate_name = get_the_title($candidate_id);
                $requested_label = !empty($request['requested_date']) ? date_i18n('M j, Y', strtotime($request['requested_date'])) : 'tomorrow';
                if ($am_user_id) {
                    $this->add_notification(
                        $am_user_id,
                        'booking_pay_negotiation',
                        'Pay negotiation started',
                        $candidate_name . ' opened pay negotiation for ' . $requested_label . '.',
                        $staff_requests_url
                    );
                }
                foreach ($this->get_admin_users_for_support() as $admin_id) {
                    if ($am_user_id && (int) $admin_id === (int) $am_user_id) {
                        continue;
                    }
                    $this->add_notification(
                        (int) $admin_id,
                        'booking_pay_negotiation',
                        'Pay negotiation started',
                        $candidate_name . ' opened pay negotiation for ' . $requested_label . '.',
                        $staff_requests_url
                    );
                }
            }
            $this->add_audit_log('booking_negotiation_opened', 'request', (string) $request_id, [
                'candidate_id' => (int) $candidate_id,
                'booking_id' => (int) $booking_id,
            ]);
            wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('Pay negotiation opened.')], $this->get_portal_base_url()));
            exit;
        }

        if ($action === 'tentative') {
            $tentative_note = sanitize_textarea_field((string) ($_POST['cmn_tentative_note'] ?? ''));
            $wpdb->update($table, [
                'status' => 'tentative',
                'internal_note' => $tentative_note,
                'updated_at' => $now,
            ], ['id' => $request_id], ['%s', '%s', '%s'], ['%d']);

            $booking_id = (int) get_post_meta($request_id, 'cmn_booking_id', true);
            if (!$booking_id) {
                $booking_id = $this->create_booking_from_request($request, $school_id, get_current_user_id());
                if ($booking_id) {
                    update_post_meta($booking_id, 'cmn_request_id', $request_id);
                    update_post_meta($request_id, 'cmn_booking_id', $booking_id);
                    update_post_meta($booking_id, 'cmn_status', 'requested');
                }
            }
            if ($booking_id) {
                update_post_meta($booking_id, 'cmn_status', 'requested');
                $school_user_id = $this->get_school_user_id_for_request($request, $school_id);
                $thread_id = $this->create_or_get_booking_thread($booking_id, 'candidate_coordination', [
                    'candidate_user_id' => get_current_user_id(),
                    'school_user_id' => $school_user_id,
                    'account_manager_user_id' => $am_user_id,
                    'status' => 'active',
                ]);
                if ($thread_id) {
                    $this->add_booking_thread_participant($thread_id, get_current_user_id(), 'candidate');
                    if ($am_user_id) {
                        $this->add_booking_thread_participant($thread_id, $am_user_id, 'account_manager');
                    }
                    if ($tentative_note !== '') {
                        $this->add_booking_thread_message($thread_id, get_current_user_id(), 'candidate', 'Candidate marked tentative: ' . $tentative_note);
                    } else {
                        $this->add_booking_thread_message($thread_id, get_current_user_id(), 'candidate', 'Candidate marked tentative - please coordinate details before final acceptance.');
                    }
                }
            }

            $candidate_name = get_the_title($candidate_id);
            $requested_label = !empty($request['requested_date']) ? date_i18n('M j, Y', strtotime($request['requested_date'])) : 'tomorrow';
            if ($am_user_id) {
                $this->add_notification(
                    $am_user_id,
                    'booking_tentative',
                    'Candidate marked tentative',
                    $candidate_name . ' marked tentative for ' . $requested_label . '.',
                    $staff_requests_url
                );
            }
            foreach ($this->get_admin_users_for_support() as $admin_id) {
                if ($am_user_id && (int) $admin_id === (int) $am_user_id) {
                    continue;
                }
                $this->add_notification(
                    (int) $admin_id,
                    'booking_tentative',
                    'Candidate marked tentative',
                    $candidate_name . ' marked tentative for ' . $requested_label . '.',
                    $staff_requests_url
                );
            }

            $this->add_audit_log('booking_tentative', 'request', (string) $request_id, [
                'candidate_id' => (int) $candidate_id,
                'booking_id' => (int) $booking_id,
                'note' => $tentative_note,
            ]);
            wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('Marked as tentative. Your account manager has been notified.')], $this->get_portal_base_url()));
            exit;
        }

        if ($action === 'decline') {
            $reason = sanitize_textarea_field($_POST['cmn_decline_reason'] ?? '');
            $wpdb->update($table, [
                'status' => 'declined',
                'internal_note' => $reason,
                'updated_at' => $now,
            ], ['id' => $request_id], ['%s', '%s', '%s'], ['%d']);
            $booking_id = (int) get_post_meta($request_id, 'cmn_booking_id', true);
            if (!$booking_id) {
                $booking_id = $this->create_booking_from_request($request, $school_id, get_current_user_id());
                if ($booking_id) {
                    update_post_meta($booking_id, 'cmn_request_id', $request_id);
                    update_post_meta($request_id, 'cmn_booking_id', $booking_id);
                }
            }
            if ($booking_id) {
                update_post_meta($booking_id, 'cmn_status', 'declined');
                $school_user_id = $this->get_school_user_id_for_request($request, $school_id);
                $thread_id = $this->create_or_get_booking_thread($booking_id, 'decline_followup', [
                    'candidate_user_id' => get_current_user_id(),
                    'school_user_id' => $school_user_id,
                    'account_manager_user_id' => $am_user_id,
                    'status' => 'active',
                ]);
                if ($thread_id) {
                    $this->add_booking_thread_participant($thread_id, get_current_user_id(), 'candidate');
                    if ($am_user_id) {
                        $this->add_booking_thread_participant($thread_id, $am_user_id, 'account_manager');
                    }
                    $this->add_booking_thread_message($thread_id, $am_user_id, 'account_manager', 'No problem - can you share why you declined? (e.g. distance, time, pay, already booked, other)');
                    if ($reason !== '') {
                        $this->add_booking_thread_message($thread_id, get_current_user_id(), 'candidate', 'Decline reason: ' . $reason);
                    }
                }
            }
            $school_name = $school_id ? get_the_title($school_id) : 'School';
            $requested_label = !empty($request['requested_date']) ? date_i18n('M j, Y', strtotime($request['requested_date'])) : 'tomorrow';
            if ($am_user_id) {
                $this->add_notification($am_user_id, 'booking_declined', 'Candidate declined booking', get_the_title($candidate_id) . ' declined ' . $school_name . ' / ' . $requested_label, $staff_requests_url);
            }
            foreach ($this->get_admin_users_for_support() as $admin_id) {
                if ($am_user_id && (int) $admin_id === (int) $am_user_id) {
                    continue;
                }
                $this->add_notification((int) $admin_id, 'booking_declined', 'Candidate declined booking', get_the_title($candidate_id) . ' declined ' . $school_name . ' / ' . $requested_label, $staff_requests_url);
            }
            $this->add_audit_log('booking_declined', 'request', (string) $request_id, [
                'candidate_id' => (int) $candidate_id,
                'booking_id' => (int) $booking_id,
                'reason' => $reason,
            ]);
            wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('Request declined.')], $this->get_portal_base_url()));
            exit;
        }

        if ($action === 'accept') {
            $context = $this->resolve_rate_context((int) $candidate_id, (int) $school_id, (array) $request, 0);
            $candidate_pay = !empty($request['candidate_pay_rate']) ? (float) $request['candidate_pay_rate'] : 0.0;
            $school_rate = !empty($request['school_charge_rate']) ? (float) $request['school_charge_rate'] : 0.0;
            $validation = $this->get_rate_validation_payload($school_rate, $candidate_pay, $context['role_key'], $context['region_key']);
            if (empty($validation['pass'])) {
                wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('This booking is currently blocked by margin guardrails. Please contact your account manager.')], $this->get_portal_base_url()));
                exit;
            }
            $booking_id = (int) get_post_meta($request_id, 'cmn_booking_id', true);
            if (!$booking_id) {
                $booking_id = $this->create_booking_from_request($request, $school_id, get_current_user_id());
                if ($booking_id) {
                    update_post_meta($booking_id, 'cmn_request_id', $request_id);
                    update_post_meta($request_id, 'cmn_booking_id', $booking_id);
                }
            }
            if (!$booking_id) {
                wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('Unable to accept request.')], $this->get_portal_base_url()));
                exit;
            }
            update_post_meta($booking_id, 'cmn_status', 'accepted');
            $request_candidate_pay = $this->get_request_candidate_pay_rate($candidate_id, $school_id, $request);
            $request_school_charge = $this->get_request_school_charge_rate($request_candidate_pay, $request);
            update_post_meta($booking_id, 'cmn_candidate_pay_rate', $request_candidate_pay);
            update_post_meta($booking_id, 'cmn_school_charge_rate', $request_school_charge);
            $this->upsert_booking_rates(
                (int) $booking_id,
                (int) $request_id,
                $context['role_key'],
                $context['region_key'],
                (float) $request_school_charge,
                (float) $request_candidate_pay,
                0,
                'Candidate accepted booking request'
            );
            $wpdb->update($table, [
                'status' => 'accepted',
                'updated_at' => $now,
            ], ['id' => $request_id], ['%s', '%s'], ['%d']);
            $school_user_id = $this->get_school_user_id_for_request($request, $school_id);
            $thread_id = $this->create_or_get_booking_thread($booking_id, 'booking_details', [
                'candidate_user_id' => get_current_user_id(),
                'school_user_id' => $school_user_id,
                'account_manager_user_id' => $am_user_id,
                'status' => 'active',
            ]);
            if ($thread_id) {
                $this->add_booking_thread_participant($thread_id, get_current_user_id(), 'candidate');
                if ($am_user_id) {
                    $this->add_booking_thread_participant($thread_id, $am_user_id, 'account_manager');
                }
                if ($school_user_id) {
                    $this->add_booking_thread_participant($thread_id, $school_user_id, 'school');
                }
                $this->post_booking_acceptance_auto_messages($thread_id, $booking_id, $request, $school_id, $candidate_id, $school_user_id, $am_user_id);
            }
            $requested_label = !empty($request['requested_date']) ? date_i18n('M j, Y', strtotime($request['requested_date'])) : 'tomorrow';
            $candidate_name = get_the_title($candidate_id);
            if ($school_user_id) {
                $school_chat_url = add_query_arg([
                    'school' => 'requests',
                    'cmn_booking_chat' => $booking_id,
                    'cmn_thread_type' => 'booking_details',
                ], $portal_url);
                $this->add_notification(
                    $school_user_id,
                    'booking_accepted',
                    'Candidate accepted booking',
                    $candidate_name . ' accepted for ' . $requested_label . '.',
                    $school_chat_url
                );
            }
            if ($am_user_id) {
                $this->add_notification(
                    $am_user_id,
                    'booking_accepted',
                    'Candidate accepted booking',
                    $candidate_name . ' accepted for ' . $requested_label . '.',
                    $staff_requests_url
                );
            }
            foreach ($this->get_admin_users_for_support() as $admin_id) {
                if ($am_user_id && (int) $admin_id === (int) $am_user_id) {
                    continue;
                }
                $this->add_notification(
                    (int) $admin_id,
                    'booking_accepted',
                    'Candidate accepted booking',
                    $candidate_name . ' accepted for ' . $requested_label . '.',
                    $staff_requests_url
                );
            }
            $this->add_audit_log('booking_accepted', 'request', (string) $request_id, [
                'candidate_id' => (int) $candidate_id,
                'booking_id' => (int) $booking_id,
                'school_domain' => (string) ($request['school_email_domain'] ?? ''),
            ]);
            wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('Booking accepted.')], $this->get_portal_base_url()));
            exit;
        }

        wp_redirect(add_query_arg(['candidate' => 'bookings', 'cmn_notice' => rawurlencode('Invalid request action.')], $this->get_portal_base_url()));
        exit;
    }

    public function handle_open_booking_thread() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_open_booking_thread_nonce']) || !wp_verify_nonce((string) $_POST['cmn_open_booking_thread_nonce'], 'cmn_open_booking_thread')) {
            wp_die('Invalid request');
        }
        $request_id = isset($_POST['cmn_request_id']) ? (int) $_POST['cmn_request_id'] : 0;
        $thread_type = sanitize_key((string) ($_POST['cmn_thread_type'] ?? 'booking_details'));
        if (!in_array($thread_type, ['booking_details', 'pay_negotiation', 'decline_followup', 'school_coordination', 'candidate_coordination'], true)) {
            wp_die('Invalid thread type');
        }
        $request = $this->get_candidate_request_by_id($request_id);
        if (!$request) {
            wp_die('Request not found');
        }
        $school_domain = (string) ($request['school_email_domain'] ?? '');
        if (!$this->user_can_access_school($school_domain)) {
            wp_die('Unauthorized');
        }

        $school_id = (int) ($request['school_id'] ?? 0);
        if ($school_id < 1 && $school_domain !== '') {
            $school_id = (int) $this->get_school_post_id_by_domain($school_domain);
        }
        $booking_id = (int) get_post_meta($request_id, 'cmn_booking_id', true);
        if (!$booking_id) {
            $booking_id = $this->create_booking_from_request($request, $school_id, get_current_user_id());
            if ($booking_id) {
                update_post_meta($booking_id, 'cmn_request_id', $request_id);
                update_post_meta($request_id, 'cmn_booking_id', $booking_id);
                update_post_meta($booking_id, 'cmn_status', 'requested');
            }
        }
        if (!$booking_id) {
            wp_die('Unable to create booking thread');
        }

        $candidate_id = (int) ($request['candidate_id'] ?? 0);
        $candidate_user_id = (int) $this->get_candidate_user_id($candidate_id);
        $school_user_id = (int) $this->get_school_user_id_for_request($request, $school_id);
        $am_user_id = (int) $this->get_request_account_manager_user_id($school_id, $request);

        $context = [
            'candidate_user_id' => $candidate_user_id,
            'school_user_id' => $school_user_id,
            'account_manager_user_id' => $am_user_id,
            'status' => 'active',
        ];
        $thread_id = (int) $this->create_or_get_booking_thread($booking_id, $thread_type, $context);
        if ($thread_id < 1) {
            wp_die('Unable to open thread');
        }

        if ($am_user_id) {
            $this->add_booking_thread_participant($thread_id, $am_user_id, 'account_manager');
        }
        if ($thread_type === 'school_coordination') {
            if ($school_user_id) {
                $this->add_booking_thread_participant($thread_id, $school_user_id, 'school');
            }
        } elseif ($thread_type === 'candidate_coordination' || $thread_type === 'pay_negotiation') {
            if ($candidate_user_id) {
                $this->add_booking_thread_participant($thread_id, $candidate_user_id, 'candidate');
            }
        } else {
            if ($candidate_user_id) {
                $this->add_booking_thread_participant($thread_id, $candidate_user_id, 'candidate');
            }
            if ($school_user_id) {
                $this->add_booking_thread_participant($thread_id, $school_user_id, 'school');
            }
        }

        $messages = (array) $this->get_booking_thread_messages($thread_id);
        if (empty($messages)) {
            if ($thread_type === 'school_coordination') {
                $this->add_booking_thread_message($thread_id, get_current_user_id(), $this->is_admin_user() ? 'admin' : 'account_manager', 'School/account-manager coordination chat opened. Please keep all booking communication documented here.');
            } elseif ($thread_type === 'candidate_coordination') {
                $this->add_booking_thread_message($thread_id, get_current_user_id(), $this->is_admin_user() ? 'admin' : 'account_manager', 'Candidate/account-manager coordination chat opened. Please keep all booking communication documented here.');
            }
        }

        $redirect = add_query_arg([
            'view' => 'requests',
            'cmn_booking_chat' => $booking_id,
            'cmn_thread_type' => $thread_type,
        ], $this->get_portal_base_url());
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_set_booking_thread_status() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_set_booking_thread_status_nonce']) || !wp_verify_nonce((string) $_POST['cmn_set_booking_thread_status_nonce'], 'cmn_set_booking_thread_status')) {
            wp_die('Invalid request');
        }
        $thread_id = isset($_POST['cmn_thread_id']) ? (int) $_POST['cmn_thread_id'] : 0;
        $status = sanitize_key((string) ($_POST['cmn_thread_status'] ?? 'active'));
        if (!in_array($status, ['active', 'closed'], true)) {
            wp_die('Invalid status');
        }
        if (!$this->user_can_access_booking_thread($thread_id, get_current_user_id())) {
            wp_die('Unauthorized');
        }
        $this->set_booking_thread_status($thread_id, $status);
        $this->add_booking_thread_message($thread_id, get_current_user_id(), $this->is_admin_user() ? 'admin' : 'account_manager', $status === 'closed' ? 'Thread closed by staff. If needed, post a message to reopen.' : 'Thread reopened by staff. Please keep all communication in this thread.');
        wp_safe_redirect(wp_get_referer() ?: add_query_arg(['view' => 'requests'], $this->get_portal_base_url()));
        exit;
    }

    public function handle_confirm_candidate_no_show() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        $nonce = isset($_POST['cmn_confirm_candidate_no_show_nonce'])
            ? sanitize_text_field(wp_unslash((string) $_POST['cmn_confirm_candidate_no_show_nonce']))
            : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_confirm_candidate_no_show')) {
            wp_die('Invalid request');
        }

        $default_redirect = add_query_arg(['view' => 'requests'], $this->get_portal_base_url());
        $redirect_raw = isset($_POST['cmn_redirect']) ? esc_url_raw(wp_unslash((string) $_POST['cmn_redirect'])) : '';
        $redirect_url = $redirect_raw !== '' ? wp_validate_redirect($redirect_raw, $default_redirect) : $default_redirect;
        $respond = function ($message) use ($redirect_url) {
            wp_safe_redirect(add_query_arg(['cmn_request_msg' => rawurlencode((string) $message)], $redirect_url));
            exit;
        };

        $candidate_id = isset($_POST['cmn_candidate_id']) ? (int) $_POST['cmn_candidate_id'] : 0;
        $booking_id = isset($_POST['cmn_booking_id']) ? (int) $_POST['cmn_booking_id'] : 0;
        $shift_date = isset($_POST['cmn_shift_date']) ? $this->normalize_invoice_date((string) wp_unslash($_POST['cmn_shift_date'])) : '';
        $confirmation_reason = isset($_POST['cmn_confirmation_reason'])
            ? sanitize_textarea_field((string) wp_unslash($_POST['cmn_confirmation_reason']))
            : '';
        $evidence_notes = isset($_POST['cmn_evidence_notes'])
            ? sanitize_textarea_field((string) wp_unslash($_POST['cmn_evidence_notes']))
            : '';
        $exceptional_circumstances_submitted = !empty($_POST['cmn_exceptional_circumstances']) ? true : false;
        if ($confirmation_reason === '') {
            $respond('No-show confirmation reason is required.');
        }

        $assessment = $this->assess_candidate_no_show_day($candidate_id, $booking_id, $shift_date);
        if (is_wp_error($assessment)) {
            $respond($assessment->get_error_message());
        }

        $shift_start_datetime = $this->get_booking_shift_start_datetime_for_day($booking_id, $shift_date);
        $chat_evidence = $this->get_booking_chat_evidence_before_shift_start($booking_id, $candidate_id, $shift_start_datetime);
        if (!empty($chat_evidence['checked']) && !empty($chat_evidence['candidate_message_before_start'])) {
            $this->add_audit_log('candidate_no_show_confirmation_blocked_chat_evidence', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'confirmed_by_user_id' => get_current_user_id(),
            ]);
            $respond('No-show cannot be confirmed because candidate communication exists before shift start in booking chat.');
        }

        $event_meta = [
            'source' => 'staff_no_show_confirmation',
            'shift_start_datetime' => $shift_start_datetime,
            'school_expected' => true,
            'cancelled' => false,
            'chat_evidence' => [
                'checked' => !empty($chat_evidence['checked']),
                'candidate_message_before_start' => !empty($chat_evidence['candidate_message_before_start']),
                'last_message_at' => (string) ($chat_evidence['last_message_at'] ?? ''),
            ],
            'chat_evidence_status' => !empty($chat_evidence['checked']) ? 'checked' : 'not_checked',
            'confirmed_by_user_id' => get_current_user_id(),
            'confirmation_reason' => $confirmation_reason,
            'exceptional_circumstances_submitted' => $exceptional_circumstances_submitted,
            'evidence_notes' => $evidence_notes,
            'decision_status' => 'confirmed',
            'booking_status' => (string) ($assessment['booking_status'] ?? ''),
            'policy_guidance' => $this->get_candidate_no_show_policy_guidance_text(),
        ];
        $event_result = $this->insert_candidate_rewards_event([
            'candidate_id' => $candidate_id,
            'booking_id' => $booking_id,
            'shift_date' => $shift_date,
            'event_type' => 'no_show_confirmed',
            'delta_cycle' => 0,
            'delta_year_total' => 0,
            'meta' => $event_meta,
            'created_by_user_id' => get_current_user_id(),
        ]);
        if (is_wp_error($event_result)) {
            $this->add_audit_log('candidate_no_show_confirmation_failed', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'message' => $event_result->get_error_message(),
            ]);
            $respond('Unable to confirm no-show: ' . $event_result->get_error_message());
        }
        if (empty($event_result['inserted'])) {
            $this->add_audit_log('candidate_no_show_confirmation_duplicate', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'event_id' => (int) ($event_result['event_id'] ?? 0),
            ]);
            $penalty_retry = $this->apply_candidate_no_show_penalty($candidate_id, $booking_id, $shift_date, [
                'applied_by_user_id' => get_current_user_id(),
                'source' => 'staff_retry_no_show_penalty',
                'confirmation_reason' => $confirmation_reason,
                'evidence_notes' => $evidence_notes,
            ]);
            if (is_wp_error($penalty_retry)) {
                $this->add_audit_log('candidate_no_show_penalty_retry_failed', 'booking', (string) $booking_id, [
                    'candidate_id' => $candidate_id,
                    'shift_date' => $shift_date,
                    'message' => $penalty_retry->get_error_message(),
                ]);
                $respond('No-show already confirmed for this booking-day. Penalty could not be applied: ' . $penalty_retry->get_error_message());
            }
            $respond($this->build_candidate_no_show_penalty_message($penalty_retry, true));
        }

        $this->add_audit_log('candidate_no_show_confirmed', 'booking', (string) $booking_id, [
            'candidate_id' => $candidate_id,
            'shift_date' => $shift_date,
            'event_id' => (int) ($event_result['event_id'] ?? 0),
            'confirmed_by_user_id' => get_current_user_id(),
            'chat_checked' => !empty($chat_evidence['checked']) ? 1 : 0,
        ]);
        $penalty_result = $this->apply_candidate_no_show_penalty($candidate_id, $booking_id, $shift_date, [
            'applied_by_user_id' => get_current_user_id(),
            'source' => 'staff_no_show_confirmation',
            'confirmation_reason' => $confirmation_reason,
            'evidence_notes' => $evidence_notes,
        ]);
        if (is_wp_error($penalty_result)) {
            $this->add_audit_log('candidate_no_show_penalty_failed', 'booking', (string) $booking_id, [
                'candidate_id' => $candidate_id,
                'shift_date' => $shift_date,
                'message' => $penalty_result->get_error_message(),
            ]);
            $respond('No-show confirmed, but penalty could not be applied: ' . $penalty_result->get_error_message());
        }
        $respond($this->build_candidate_no_show_penalty_message($penalty_result, false));
    }

    public function handle_booking_chat_post() {
        if (!is_user_logged_in()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_booking_chat_nonce']) || !wp_verify_nonce($_POST['cmn_booking_chat_nonce'], 'cmn_booking_chat')) {
            wp_die('Invalid request');
        }
        $thread_id = (int) ($_POST['cmn_thread_id'] ?? 0);
        $message = sanitize_textarea_field($_POST['cmn_message'] ?? '');
        if (!$thread_id || $message === '') {
            wp_die('Invalid message');
        }
        if (!$this->user_can_access_booking_thread($thread_id, get_current_user_id())) {
            wp_die('Unauthorized');
        }
        global $wpdb;
        $thread_table = $this->get_booking_threads_table();
        $thread = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$thread_table} WHERE id = %d LIMIT 1",
            $thread_id
        ), ARRAY_A);
        $booking_id_for_thread = (int) ($thread['booking_id'] ?? 0);
        if ($booking_id_for_thread > 0) {
            $rate_row = $this->get_booking_rate_row($booking_id_for_thread);
            $is_override = !empty($rate_row['override_flag']) && (int) $rate_row['override_flag'] === 1;
            $guardrail_status = strtoupper((string) ($rate_row['guardrail_status'] ?? 'OK'));
            if (!$is_override && in_array($guardrail_status, ['LOW', 'NEGATIVE'], true) && !$this->is_admin_user()) {
                wp_die('Booking chat is blocked until rate guardrails are resolved or overridden by admin.');
            }
        }
        $thread_status = sanitize_key((string) ($thread['status'] ?? 'active'));
        $thread_type = sanitize_key((string) ($thread['thread_type'] ?? 'booking_details'));
        $role_type = 'candidate';
        if ($this->is_school_user()) {
            $role_type = 'school';
        } elseif ($this->is_staff_user()) {
            $role_type = $this->is_admin_user() ? 'admin' : 'account_manager';
        }

        if ($thread_type !== 'pay_negotiation' && preg_match('/(\bpay\b|\brate\b|\bfee\b|\bmoney\b|£|\$|\beur\b)/i', (string) $message)) {
            wp_die('Please keep pay/rate discussion in the pay negotiation chat only.');
        }
        if ($role_type === 'school' && $thread_type === 'pay_negotiation') {
            wp_die('Schools cannot use the pay negotiation chat.');
        }


        if ($thread_status === 'closed' && !$this->is_staff_user()) {
            $this->set_booking_thread_status($thread_id, 'active');
            $this->add_booking_thread_message($thread_id, get_current_user_id(), $role_type, 'Thread reopened by participant. Please keep all booking communication documented here.');
        }

        $uploaded = $this->handle_support_attachments_upload('cmn_attachments');
        $this->add_booking_thread_message($thread_id, get_current_user_id(), $role_type, $message, $uploaded['ids']);
        wp_redirect(wp_get_referer() ?: $this->get_portal_base_url());
        exit;
    }

    public function handle_booking_chat_fetch() {
        if (!check_ajax_referer('cmn_booking_chat_fetch', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $thread_id = (int) ($_POST['thread_id'] ?? 0);
        if (!$thread_id || !$this->user_can_access_booking_thread($thread_id, get_current_user_id())) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        global $wpdb;
        $thread_table = $this->get_booking_threads_table();
        $thread = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$thread_table} WHERE id = %d LIMIT 1",
            $thread_id
        ), ARRAY_A);
        if (!$thread) {
            wp_send_json_error(['message' => 'Thread not found.'], 404);
        }
        if ($this->is_school_user() && sanitize_key((string) ($thread['thread_type'] ?? 'booking_details')) === 'pay_negotiation') {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $booking_id_for_thread = (int) ($thread['booking_id'] ?? 0);
        if ($booking_id_for_thread > 0) {
            $rate_row = $this->get_booking_rate_row($booking_id_for_thread);
            if (!$rate_row) {
                $candidate_id = (int) get_post_meta($booking_id_for_thread, 'cmn_candidate_id', true);
                $school_id = (int) get_post_meta($booking_id_for_thread, 'cmn_school_id', true);
                $context = $this->resolve_rate_context($candidate_id, $school_id, [], $booking_id_for_thread);
                $school_rate = (float) get_post_meta($booking_id_for_thread, 'cmn_school_charge_rate', true);
                $candidate_pay = (float) get_post_meta($booking_id_for_thread, 'cmn_candidate_pay_rate', true);
                if ($school_rate > 0 && $candidate_pay > 0) {
                    $this->upsert_booking_rates(
                        $booking_id_for_thread,
                        (int) get_post_meta($booking_id_for_thread, 'cmn_request_id', true),
                        $context['role_key'],
                        $context['region_key'],
                        $school_rate,
                        $candidate_pay,
                        0,
                        'Auto-evaluated before chat'
                    );
                    $rate_row = $this->get_booking_rate_row($booking_id_for_thread);
                }
            }
            if (!empty($rate_row)) {
                $is_override = !empty($rate_row['override_flag']) && (int) $rate_row['override_flag'] === 1;
                $guardrail_status = strtoupper((string) ($rate_row['guardrail_status'] ?? 'OK'));
                if (!$is_override && in_array($guardrail_status, ['LOW', 'NEGATIVE'], true) && !$this->is_admin_user()) {
                    wp_send_json_error(['message' => 'Booking chat is blocked until rate guardrails are resolved or admin override is applied.'], 403);
                }
            }
        }
        $this->maybe_request_booking_feedback_notifications((int) ($thread['booking_id'] ?? 0));
        $messages = $this->get_booking_thread_messages($thread_id);
        $payload = [];
        foreach ($messages as $message_row) {
            $sender_name = ucfirst(str_replace('_', ' ', (string) ($message_row['sender_role_type'] ?? 'system')));
            if (!empty($message_row['sender_user_id'])) {
                $sender_user = get_user_by('id', (int) $message_row['sender_user_id']);
                if ($sender_user) {
                    $sender_name = $sender_user->display_name ?: $sender_user->user_login;
                }
            }
            $payload[] = [
                'id' => (int) ($message_row['id'] ?? 0),
                'sender_user_id' => (int) ($message_row['sender_user_id'] ?? 0),
                'sender_role_type' => (string) ($message_row['sender_role_type'] ?? 'system'),
                'sender_name' => $sender_name,
                'message' => (string) ($message_row['message'] ?? ''),
                'created_at' => (string) ($message_row['created_at'] ?? ''),
                'attachments' => $this->get_booking_message_attachments($message_row),
            ];
        }
        wp_send_json_success([
            'thread' => [
                'id' => (int) ($thread['id'] ?? 0),
                'booking_id' => (int) ($thread['booking_id'] ?? 0),
                'thread_type' => (string) ($thread['thread_type'] ?? 'booking_details'),
                'status' => (string) ($thread['status'] ?? 'active'),
            ],
            'messages' => $payload,
        ]);
    }

    public function handle_booking_feedback_fetch() {
        if (!check_ajax_referer('cmn_booking_feedback', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $booking_id = (int) ($_POST['booking_id'] ?? 0);
        if (!$booking_id) {
            wp_send_json_error(['message' => 'Booking not found.'], 404);
        }
        $viewer_user_id = get_current_user_id();
        $viewer_role = $this->get_booking_feedback_role_for_user($viewer_user_id);
        if (!in_array($viewer_role, ['candidate', 'school', 'staff'], true)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if (!$this->user_can_access_booking_feedback($booking_id, $viewer_user_id, $viewer_role)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $this->maybe_request_booking_feedback_notifications($booking_id);
        if ($viewer_role === 'school') {
            wp_send_json_success($this->get_school_candidate_feedback_payload($booking_id, $viewer_user_id));
        }
        wp_send_json_success($this->get_booking_feedback_payload($booking_id, $viewer_user_id, $viewer_role));
    }

    public function handle_booking_feedback_submit() {
        if (!check_ajax_referer('cmn_booking_feedback', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $booking_id = (int) ($_POST['booking_id'] ?? 0);
        if (!$booking_id) {
            wp_send_json_error(['message' => 'Booking not found.'], 404);
        }
        $viewer_user_id = get_current_user_id();
        $viewer_role = $this->get_booking_feedback_role_for_user($viewer_user_id);
        if (!in_array($viewer_role, ['candidate', 'school'], true)) {
            wp_send_json_error(['message' => 'Only candidates and schools can submit booking feedback.'], 403);
        }
        if (!$this->user_can_access_booking_feedback($booking_id, $viewer_user_id, $viewer_role)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if ($viewer_role === 'school') {
            $booking_school_user_id = (int) $this->get_booking_school_user_id($booking_id);
            if ($booking_school_user_id < 1 || $booking_school_user_id !== $viewer_user_id) {
                wp_send_json_error(['message' => 'You can only submit feedback for your own school bookings.'], 403);
            }
            if (!$this->is_school_candidate_feedback_eligible($booking_id)) {
                wp_send_json_error(['message' => 'Feedback is available only after booking completion is confirmed.'], 400);
            }

            $candidate_user_id = (int) $this->get_booking_candidate_user_id($booking_id);
            if ($candidate_user_id < 1) {
                wp_send_json_error(['message' => 'Unable to resolve candidate for this booking.'], 400);
            }
            $existing_feedback = $this->get_candidate_feedback_row_by_booking($booking_id, $candidate_user_id);
            if (!empty($existing_feedback)) {
                wp_send_json_success([
                    'message' => 'Feedback already submitted.',
                    'feedback' => $this->get_school_candidate_feedback_payload($booking_id, $viewer_user_id),
                ]);
            }

            $module_fields = $this->get_candidate_feedback_module_fields();
            $scores = [];
            foreach ($module_fields as $field => $label) {
                $score = (int) ($_POST[$field] ?? 0);
                if ($score < 1 || $score > 5) {
                    wp_send_json_error(['message' => 'Please complete all module ratings (1-5).'], 400);
                }
                $scores[$field] = $score;
            }
            $comment = sanitize_textarea_field((string) ($_POST['comment'] ?? ''));
            $average_rating = round(array_sum($scores) / max(1, count($scores)), 2);

            global $wpdb;
            $candidate_feedback_table = $this->get_candidate_feedback_table();
            $inserted = $wpdb->insert($candidate_feedback_table, [
                'booking_id' => $booking_id,
                'school_user_id' => $viewer_user_id,
                'candidate_user_id' => $candidate_user_id,
                'score_punctuality' => (int) $scores['score_punctuality'],
                'score_classroom_management' => (int) $scores['score_classroom_management'],
                'score_professionalism' => (int) $scores['score_professionalism'],
                'score_communication' => (int) $scores['score_communication'],
                'score_adaptability' => (int) $scores['score_adaptability'],
                'score_lesson_delivery' => (int) $scores['score_lesson_delivery'],
                'score_safeguarding' => (int) $scores['score_safeguarding'],
                'average_rating' => $average_rating,
                'comments' => $comment !== '' ? $comment : null,
                'created_at' => current_time('mysql'),
                'updated_at' => current_time('mysql'),
            ], ['%d', '%d', '%d', '%d', '%d', '%d', '%d', '%d', '%d', '%d', '%f', '%s', '%s', '%s']);

            if ($inserted === false) {
                if (strpos((string) $wpdb->last_error, 'Duplicate') !== false) {
                    wp_send_json_success([
                        'message' => 'Feedback already submitted.',
                        'feedback' => $this->get_school_candidate_feedback_payload($booking_id, $viewer_user_id),
                    ]);
                }
                wp_send_json_error(['message' => 'Unable to save feedback right now.'], 500);
            }

            $this->upsert_candidate_rating_stats($candidate_user_id);

            $candidate_post_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
            if ($candidate_post_id > 0) {
                $legacy_overall = max(1, min(5, (int) round($average_rating)));
                $legacy_table = $this->get_booking_feedback_table();
                $wpdb->replace($legacy_table, [
                    'booking_id' => $booking_id,
                    'rater_user_id' => $viewer_user_id,
                    'rated_entity_type' => 'candidate',
                    'rated_entity_id' => $candidate_post_id,
                    'stars_overall' => $legacy_overall,
                    'stars_1' => (int) $scores['score_punctuality'],
                    'stars_2' => (int) $scores['score_professionalism'],
                    'stars_3' => (int) $scores['score_classroom_management'],
                    'tags' => null,
                    'would_rebook' => null,
                    'comment' => $comment,
                    'created_at' => current_time('mysql'),
                ], ['%d', '%d', '%s', '%d', '%d', '%d', '%d', '%d', '%s', '%d', '%s', '%s']);

                $this->sync_feedback_insights_entry_from_booking_feedback(
                    $booking_id,
                    'school',
                    'candidate',
                    $candidate_post_id,
                    $legacy_overall,
                    (int) $scores['score_punctuality'],
                    (int) $scores['score_professionalism'],
                    null,
                    $comment
                );
                $this->maybe_process_candidate_feedback_risk_alerts($candidate_post_id, $booking_id);
                $this->maybe_notify_low_booking_feedback($booking_id, 'school', $legacy_overall, $viewer_user_id);
            }

            if (function_exists('cmn_audit_log_event')) {
                cmn_audit_log_event([
                    'module' => 'feedback',
                    'entity_type' => 'booking',
                    'entity_id' => $booking_id,
                    'event_type' => 'candidate_feedback_submitted',
                    'actor_user_id' => $viewer_user_id,
                    'metadata' => [
                        'candidate_user_id' => $candidate_user_id,
                        'school_user_id' => $viewer_user_id,
                        'average_rating' => $average_rating,
                    ],
                ]);
            }

            wp_send_json_success([
                'message' => 'Feedback submitted.',
                'feedback' => $this->get_school_candidate_feedback_payload($booking_id, $viewer_user_id),
            ]);
        }

        if (!$this->is_booking_feedback_eligible($booking_id)) {
            wp_send_json_error(['message' => 'Feedback is available after a booking has completed.'], 400);
        }

        $stars_overall = (int) ($_POST['stars_overall'] ?? 0);
        $stars_1 = (int) ($_POST['stars_1'] ?? 0);
        $stars_2 = (int) ($_POST['stars_2'] ?? 0);
        $stars_3 = (int) ($_POST['stars_3'] ?? 0);
        foreach ([$stars_1, $stars_2, $stars_3, $stars_overall] as $stars_value) {
            if ($stars_value < 1 || $stars_value > 5) {
                wp_send_json_error(['message' => 'Please complete all star ratings.'], 400);
            }
        }

        $comment = sanitize_textarea_field((string) ($_POST['comment'] ?? ''));
        $tags = $this->sanitize_booking_feedback_tags($_POST['tags'] ?? [], $viewer_role);
        $would_rebook = null;
        if ($viewer_role === 'candidate') {
            $would_raw = (string) ($_POST['would_rebook'] ?? '');
            if ($would_raw === '1' || strtolower($would_raw) === 'yes') {
                $would_rebook = 1;
            } elseif ($would_raw === '0' || strtolower($would_raw) === 'no') {
                $would_rebook = 0;
            }
        }

        $rated_entity_type = $viewer_role === 'candidate' ? 'school' : 'candidate';
        $rated_entity_id = $rated_entity_type === 'school'
            ? (int) get_post_meta($booking_id, 'cmn_school_id', true)
            : (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        if (!$rated_entity_id) {
            wp_send_json_error(['message' => 'Unable to resolve booking feedback target.'], 400);
        }

        global $wpdb;
        $table = $this->get_booking_feedback_table();
        $wpdb->replace($table, [
            'booking_id' => $booking_id,
            'rater_user_id' => $viewer_user_id,
            'rated_entity_type' => $rated_entity_type,
            'rated_entity_id' => $rated_entity_id,
            'stars_overall' => $stars_overall,
            'stars_1' => $stars_1,
            'stars_2' => $stars_2,
            'stars_3' => $stars_3,
            'tags' => $tags ? wp_json_encode($tags) : null,
            'would_rebook' => $would_rebook,
            'comment' => $comment,
            'created_at' => current_time('mysql'),
        ], ['%d', '%d', '%s', '%d', '%d', '%d', '%d', '%d', '%s', '%d', '%s', '%s']);

        if (!empty($wpdb->last_error)) {
            wp_send_json_error(['message' => 'Unable to save feedback right now.'], 500);
        }

        $this->sync_feedback_insights_entry_from_booking_feedback(
            $booking_id,
            $viewer_role,
            $rated_entity_type,
            $rated_entity_id,
            $stars_overall,
            $stars_1,
            $stars_2,
            $would_rebook,
            $comment
        );
        if ($rated_entity_type === 'candidate' && $rated_entity_id > 0) {
            $this->maybe_process_candidate_feedback_risk_alerts($rated_entity_id, $booking_id);
        }

        $this->maybe_notify_low_booking_feedback($booking_id, $viewer_role, $stars_overall, $viewer_user_id);
        wp_send_json_success([
            'message' => 'Feedback submitted.',
            'feedback' => $this->get_booking_feedback_payload($booking_id, $viewer_user_id, $viewer_role),
        ]);
    }

    public function handle_booking_chat_ack() {
        if (!is_user_logged_in() || !$this->is_candidate_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_booking_chat_ack_nonce']) || !wp_verify_nonce($_POST['cmn_booking_chat_ack_nonce'], 'cmn_booking_chat_ack')) {
            wp_die('Invalid request');
        }
        $booking_id = (int) ($_POST['cmn_booking_id'] ?? 0);
        if ($booking_id) {
            update_user_meta(get_current_user_id(), 'cmn_booking_chat_ack_' . $booking_id, '1');
        }
        $default_redirect = add_query_arg(['candidate' => 'bookings'], $this->get_portal_base_url());
        $redirect_raw = isset($_POST['cmn_redirect']) ? esc_url_raw(wp_unslash((string) $_POST['cmn_redirect'])) : '';
        $referer_redirect = wp_get_referer();
        if (!is_string($referer_redirect) || $referer_redirect === '') {
            $referer_redirect = $default_redirect;
        }
        $referer_redirect = wp_validate_redirect($referer_redirect, $default_redirect);
        $redirect_url = $redirect_raw !== '' ? wp_validate_redirect($redirect_raw, $referer_redirect) : $referer_redirect;
        wp_safe_redirect($redirect_url);
        exit;
    }

    public function handle_staff_update_candidate_pay() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_staff_update_candidate_pay_nonce']) || !wp_verify_nonce($_POST['cmn_staff_update_candidate_pay_nonce'], 'cmn_staff_update_candidate_pay')) {
            wp_die('Invalid request');
        }
        $request_id = (int) ($_POST['cmn_request_id'] ?? 0);
        $pay_rate = (float) ($_POST['cmn_candidate_pay_rate'] ?? 0);
        if (!$request_id || $pay_rate <= 0) {
            wp_die('Invalid request');
        }
        $request = $this->get_candidate_request_by_id($request_id);
        if (!$request) {
            wp_die('Request not found');
        }
        $request = $this->ensure_request_has_guardrail_rates($request);
        if (!$this->user_can_access_school($request['school_email_domain'] ?? '')) {
            wp_die('Unauthorized');
        }
        $school_id = (int) ($request['school_id'] ?? 0);
        if (!$school_id && !empty($request['school_email_domain'])) {
            $school_id = (int) $this->get_school_post_id_by_domain((string) $request['school_email_domain']);
        }
        $context = $this->resolve_rate_context((int) ($request['candidate_id'] ?? 0), $school_id, (array) $request, 0);
        $school_charge_rate = !empty($request['school_charge_rate']) ? (float) $request['school_charge_rate'] : 0.0;
        if ($school_charge_rate <= 0) {
            $school_charge_rate = $this->get_request_school_charge_rate($pay_rate, (array) $request);
        }
        $validation = $this->get_rate_validation_payload($school_charge_rate, $pay_rate, $context['role_key'], $context['region_key']);
        if (empty($validation['pass'])) {
            wp_die('Rate blocked by guardrails. Use Rate Guardrails override with a required admin reason.');
        }
        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $wpdb->update($table, [
            'candidate_pay_rate' => $pay_rate,
            'school_charge_rate' => $school_charge_rate,
            'updated_at' => current_time('mysql'),
        ], ['id' => $request_id], ['%f', '%f', '%s'], ['%d']);
        $booking_id = (int) get_post_meta($request_id, 'cmn_booking_id', true);
        if ($booking_id) {
            update_post_meta($booking_id, 'cmn_candidate_pay_rate', $pay_rate);
            update_post_meta($booking_id, 'cmn_school_charge_rate', $school_charge_rate);
            $this->upsert_booking_rates(
                $booking_id,
                $request_id,
                $context['role_key'],
                $context['region_key'],
                $school_charge_rate,
                $pay_rate,
                0,
                'Staff updated candidate pay'
            );
        }
        if ($booking_id) {
            $candidate_user_id = (int) $this->get_candidate_user_id((int) ($request['candidate_id'] ?? 0));
            $school_user_id = $this->get_school_user_id_for_request($request, $school_id);
            $thread_id = $this->create_or_get_booking_thread($booking_id, 'pay_negotiation', [
                'candidate_user_id' => $candidate_user_id,
                'school_user_id' => $school_user_id,
                'account_manager_user_id' => get_current_user_id(),
                'status' => 'active',
            ]);
            if ($thread_id) {
                $this->add_booking_thread_message($thread_id, get_current_user_id(), 'account_manager', 'Account manager updated candidate pay to GBP ' . number_format($pay_rate, 2) . '.');
            }
        }
        $this->add_audit_log('rate_edited', 'request', (string) $request_id, [
            'candidate_pay_rate' => $pay_rate,
            'school_charge_rate' => $school_charge_rate,
            'guardrail_status' => (string) ($validation['status'] ?? 'OK'),
            'booking_id' => $booking_id,
            'candidate_id' => (int) ($request['candidate_id'] ?? 0),
            'school_domain' => (string) ($request['school_email_domain'] ?? ''),
        ]);
        wp_redirect(wp_get_referer() ?: add_query_arg(['view' => 'requests'], $this->get_portal_base_url()));
        exit;
    }

    public function handle_staff_save_candidate_role_rates() {
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_staff_save_candidate_role_rates_nonce']) || !wp_verify_nonce((string) $_POST['cmn_staff_save_candidate_role_rates_nonce'], 'cmn_staff_save_candidate_role_rates')) {
            wp_die('Invalid request');
        }

        $candidate_id = isset($_POST['candidate_id']) ? (int) $_POST['candidate_id'] : 0;
        if ($candidate_id < 1 || get_post_type($candidate_id) !== 'cmn_candidate') {
            wp_die('Candidate not found.');
        }

        $role_labels = $this->get_candidate_role_labels($candidate_id);
        $raw_rates = isset($_POST['cmn_role_rates']) && is_array($_POST['cmn_role_rates']) ? (array) $_POST['cmn_role_rates'] : [];
        $map = [];

        foreach ($role_labels as $role_label) {
            $role_key = sanitize_title((string) $role_label);
            if ($role_key === '') {
                continue;
            }
            $row = isset($raw_rates[$role_key]) && is_array($raw_rates[$role_key]) ? (array) $raw_rates[$role_key] : [];
            $school_charge = isset($row['school_charge_rate']) ? (float) $row['school_charge_rate'] : 0.0;
            $candidate_pay = isset($row['candidate_pay_rate']) ? (float) $row['candidate_pay_rate'] : 0.0;
            $map[$role_key] = [
                'role_label' => sanitize_text_field((string) $role_label),
                'school_charge_rate' => $school_charge > 0 ? round($school_charge, 2) : 0.0,
                'candidate_pay_rate' => $candidate_pay > 0 ? round($candidate_pay, 2) : 0.0,
            ];
        }

        update_post_meta($candidate_id, 'cmn_role_rate_map', wp_json_encode($map));

        $redirect = add_query_arg([
            'view' => 'candidate_profile',
            'candidate_id' => $candidate_id,
            'cmn_notice' => rawurlencode('Role rates saved.'),
        ], $this->get_portal_base_url());
        wp_safe_redirect($redirect);
        exit;
    }

    public function handle_update_candidate_request() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_update_candidate_request_nonce']) || !wp_verify_nonce($_POST['cmn_update_candidate_request_nonce'], 'cmn_update_candidate_request')) {
            wp_die('Invalid request');
        }
        $request_id = intval($_POST['cmn_request_id'] ?? 0);
        if (!$request_id) {
            wp_die('Invalid request.');
        }
        $request = $this->get_candidate_request_by_id($request_id);
        if (!$request) {
            wp_die('Request not found.');
        }
        $request = $this->ensure_request_has_guardrail_rates($request);
        $school_domain = $request['school_email_domain'] ?? '';
        if (!$this->user_can_access_school($school_domain)) {
            wp_die('Unauthorized');
        }

        $action = sanitize_text_field($_POST['cmn_request_action'] ?? 'confirm');
        $confirmed = sanitize_text_field($_POST['cmn_confirmed'] ?? 'yes');
        $note = sanitize_textarea_field($_POST['cmn_internal_note'] ?? '');
        $candidate_pay_rate_input = isset($_POST['cmn_candidate_pay_rate']) ? (float) $_POST['cmn_candidate_pay_rate'] : 0;
        $school_charge_rate_input = isset($_POST['cmn_school_charge_rate']) ? (float) $_POST['cmn_school_charge_rate'] : 0;
        $rate_action = sanitize_key((string) ($_POST['cmn_rate_action'] ?? 'save'));
        $override_requested = isset($_POST['cmn_rate_override']) && (string) $_POST['cmn_rate_override'] === '1';
        $override_reason = sanitize_textarea_field((string) ($_POST['cmn_rate_override_reason'] ?? ''));

        $candidate_id = (int) $request['candidate_id'];
        $school_id = $this->get_school_post_id_by_domain($school_domain);
        $rate_context = $this->resolve_rate_context($candidate_id, $school_id, (array) $request, 0);
        if ($rate_action === 'suggest') {
            $suggested = $this->get_suggested_rates_for_context($rate_context['role_key'], $rate_context['region_key']);
            $candidate_pay_rate_input = (float) ($suggested['candidate_pay'] ?? 0.0);
            $school_charge_rate_input = (float) ($suggested['school_rate'] ?? 0.0);
        }
        $requested_date = sanitize_text_field($request['requested_date'] ?? '');
        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        if ($requested_date && strtotime($requested_date) < strtotime(date('Y-m-d'))) {
            $redirect = wp_get_referer() ?: home_url('/portal');
            wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Request date has passed.')], $redirect));
            exit;
        }

        if ($rate_action === 'suggest') {
            global $wpdb;
            $table = $this->get_candidate_requests_table();
            $wpdb->update($table, [
                'candidate_pay_rate' => $candidate_pay_rate_input,
                'school_charge_rate' => $school_charge_rate_input,
                'updated_at' => current_time('mysql'),
            ], ['id' => $request_id], ['%f', '%f', '%s'], ['%d']);
            $booking_id = $this->get_booking_id_for_request($request_id);
            if ($booking_id > 0) {
                $this->upsert_booking_rates(
                    $booking_id,
                    $request_id,
                    $rate_context['role_key'],
                    $rate_context['region_key'],
                    $school_charge_rate_input,
                    $candidate_pay_rate_input,
                    0,
                    'Applied suggested rates'
                );
            }
            $redirect = wp_get_referer() ?: home_url('/portal');
            wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Suggested rates applied.')], $redirect));
            exit;
        }

        $status = 'requested';
        if ($action === 'decline' || $confirmed === 'no') {
            $status = 'declined';
        } elseif ($action === 'no_longer_needed') {
            $status = 'cancelled';
        } elseif ($action === 'save_rates') {
            $status = 'requested';
        } elseif ($action === 'refresh') {
            $status = 'requested';
        } else {
            $status = 'confirmed';
        }

        $effective_candidate_pay = $candidate_pay_rate_input > 0 ? round($candidate_pay_rate_input, 2) : (float) ($request['candidate_pay_rate'] ?? 0.0);
        if ($effective_candidate_pay <= 0) {
            $effective_candidate_pay = (float) $this->get_request_candidate_pay_rate($candidate_id, $school_id, (array) $request);
        }
        $effective_school_charge = $school_charge_rate_input > 0 ? round($school_charge_rate_input, 2) : (float) ($request['school_charge_rate'] ?? 0.0);
        if ($effective_school_charge <= 0) {
            $effective_school_charge = (float) $this->get_request_school_charge_rate($effective_candidate_pay, (array) $request);
        }
        $rate_validation = $this->get_rate_validation_payload($effective_school_charge, $effective_candidate_pay, $rate_context['role_key'], $rate_context['region_key']);
        $override_allowed = $override_requested && $this->is_admin_user();
        if ($override_requested && !$this->is_admin_user()) {
            $redirect = wp_get_referer() ?: home_url('/portal');
            wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Only admins can override guardrails.')], $redirect));
            exit;
        }
        if ($override_allowed && $override_reason === '') {
            $redirect = wp_get_referer() ?: home_url('/portal');
            wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Override reason is required.')], $redirect));
            exit;
        }
        if ($action === 'save_rates' && empty($rate_validation['pass']) && !$override_allowed) {
            $redirect = wp_get_referer() ?: home_url('/portal');
            $status_label = (string) ($rate_validation['status'] ?? 'LOW');
            wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode("Rates blocked by guardrails ({$status_label}). Admin override required.")], $redirect));
            exit;
        }

        if ($status === 'confirmed') {
            if (empty($rate_validation['pass']) && !$override_allowed) {
                $redirect = wp_get_referer() ?: home_url('/portal');
                $status_label = (string) ($rate_validation['status'] ?? 'LOW');
                wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode("Booking blocked by rate guardrails ({$status_label}). Admin override required.")], $redirect));
                exit;
            }
            if (!$this->has_candidate_availability($candidate_id, $requested_date)) {
                $redirect = wp_get_referer() ?: home_url('/portal');
                wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Candidate is no longer marked available.')], $redirect));
                exit;
            }
            if ($this->is_candidate_unavailable($candidate_id, $requested_date)) {
                $redirect = wp_get_referer() ?: home_url('/portal');
                wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Candidate marked unavailable in calendar.')], $redirect));
                exit;
            }
            if ($this->has_booking_for_candidate_date($candidate_id, $requested_date)) {
                $redirect = wp_get_referer() ?: home_url('/portal');
                wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Candidate already booked for that date.')], $redirect));
                exit;
            }
        }

        if ($action === 'refresh') {
            $new_sent = current_time('mysql');
            $new_expires = gmdate('Y-m-d H:i:s', strtotime(gmdate('Y-m-d H:i:s') . ' +15 minutes'));
            global $wpdb;
            $table = $this->get_candidate_requests_table();
            $wpdb->update($table, [
                'status' => 'requested',
                'request_sent_at' => $new_sent,
                'expires_at' => $new_expires,
                'updated_at' => $new_sent,
            ], [
                'id' => $request_id,
            ], ['%s', '%s', '%s', '%s'], ['%d']);
            $candidate_user_id = $this->get_candidate_user_id($candidate_id);
            if ($candidate_user_id) {
                $candidate_bookings_url = add_query_arg(['candidate' => 'bookings'], $portal_url);
                $this->add_notification($candidate_user_id, 'booking_request', 'Booking request', 'A booking request has been refreshed for ' . date_i18n('M j, Y', strtotime($requested_date)), $candidate_bookings_url);
            }
            $candidate_email = $candidate_id ? get_post_meta($candidate_id, 'cmn_email', true) : '';
            if ($candidate_email) {
                $this->send_candidate_email($candidate_email, 'Booking request refreshed', "A booking request has been refreshed for " . date_i18n('l, F jS', strtotime($requested_date)) . ".\n\nPlease log in to respond.", [
                    'type' => 'candidate_availability_request',
                    'related_school_domain' => $school_domain,
                    'related_candidate_id' => $candidate_id,
                    'related_request_id' => $request_id,
                ]);
            }
            $redirect = wp_get_referer() ?: home_url('/portal');
            wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Request refreshed for 15 minutes.')], $redirect));
            exit;
        }

        $school_id = $this->get_school_post_id_by_domain($school_domain);
        $candidate = get_post($candidate_id);
        $candidate_name = $candidate ? $candidate->post_title : 'Candidate';
        $name_parts = preg_split('/\\s+/', trim((string) $candidate_name));
        $first_name = $name_parts ? $name_parts[0] : $candidate_name;
        $role_meta = (array) get_post_meta($candidate_id, 'cmn_roles', true);
        $role_label = $role_meta ? $role_meta[0] : 'Candidate';
        $school_name = $school_id ? get_the_title($school_id) : 'School';
        $requested_label = $requested_date ? date_i18n('l, F jS', strtotime($requested_date)) : 'tomorrow';
        $candidate_email = $candidate_id ? get_post_meta($candidate_id, 'cmn_email', true) : '';
        $candidate_user_id = $this->get_candidate_user_id($candidate_id);
        $school_user_id = $this->get_school_user_id_for_request($request, $school_id);
        $school_requests_url = add_query_arg(['school' => 'requests'], $portal_url);
        $candidate_bookings_url = add_query_arg(['candidate' => 'bookings'], $portal_url);

        if ($status === 'confirmed') {
            $booking_id = $this->create_booking_from_request($request, $school_id, get_current_user_id());
            if (!$booking_id) {
                $redirect = wp_get_referer() ?: home_url('/portal');
                wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Unable to create booking.')], $redirect));
                exit;
            }
            update_post_meta((int) $booking_id, 'cmn_request_id', (int) $request_id);
            update_post_meta((int) $request_id, 'cmn_booking_id', (int) $booking_id);
        }

        global $wpdb;
        $table = $this->get_candidate_requests_table();
        $update_data = [
            'status' => $status,
            'internal_note' => $note,
            'candidate_pay_rate' => $effective_candidate_pay,
            'school_charge_rate' => $effective_school_charge,
            'updated_at' => current_time('mysql'),
        ];
        $update_format = ['%s', '%s', '%f', '%f', '%s'];
        $wpdb->update($table, $update_data, [
            'id' => $request_id,
        ], $update_format, ['%d']);
        $this->add_audit_log('booking_request_updated', 'request', (string) $request_id, [
            'action' => $action,
            'status' => $status,
            'candidate_id' => (int) $candidate_id,
            'requested_date' => $requested_date,
            'school_domain' => $school_domain,
            'candidate_pay_rate' => $effective_candidate_pay,
            'school_charge_rate' => $effective_school_charge,
            'guardrail_status' => (string) ($rate_validation['status'] ?? 'OK'),
            'override' => $override_allowed ? 1 : 0,
            'override_reason' => $override_allowed ? $override_reason : '',
        ]);

        if ($action === 'save_rates') {
            $booking_id_for_rates = (int) $this->get_booking_id_for_request($request_id);
            if ($booking_id_for_rates > 0) {
                $this->upsert_booking_rates(
                    $booking_id_for_rates,
                    $request_id,
                    $rate_context['role_key'],
                    $rate_context['region_key'],
                    $effective_school_charge,
                    $effective_candidate_pay,
                    $override_allowed ? 1 : 0,
                    $override_allowed ? $override_reason : 'Staff saved rates'
                );
            }
            $redirect = wp_get_referer() ?: home_url('/portal');
            wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Rates saved.')], $redirect));
            exit;
        }

        if ($status === 'confirmed') {
            $booking_id_for_rates = (int) $this->get_booking_id_for_request($request_id);
            if ($booking_id_for_rates > 0) {
                $this->upsert_booking_rates(
                    $booking_id_for_rates,
                    $request_id,
                    $rate_context['role_key'],
                    $rate_context['region_key'],
                    $effective_school_charge,
                    $effective_candidate_pay,
                    $override_allowed ? 1 : 0,
                    $override_allowed ? $override_reason : 'Rates validated by staff'
                );
            }
            $today_key = current_time("Y-m-d");
            $tomorrow_key = $this->get_tomorrow_date();
            $subject_when = $requested_label;
            if ($requested_date === $today_key) {
                $subject_when = "today";
            } elseif ($requested_date === $tomorrow_key) {
                $subject_when = "tomorrow";
            }
            $school_email = $this->get_school_primary_contact_email($school_id);
            if ($school_email) {
                $subject = 'Candidate confirmed for ' . $subject_when;
                $message = "Good news!\n\n{$first_name} ({$role_label}) is confirmed for {$requested_label}.\n\nWe will be in touch if anything changes.";
                $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
                $GLOBALS['cmn_school_mail_log_type'] = 'school_request_confirmed';
                $this->send_school_email($school_email, $subject, $message);
                if ($previous_log_type !== null) {
                    $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
                } else {
                    unset($GLOBALS['cmn_school_mail_log_type']);
                }
            }
            if ($school_user_id) {
                $this->add_notification($school_user_id, 'request_confirmed', 'Request confirmed', $first_name . ' confirmed for ' . $requested_label . '.', $school_requests_url);
            }
            if ($candidate_email) {
                $subject = 'You have been booked for ' . $subject_when;
                $message = "Hi {$first_name},\n\nYou have been booked for {$requested_label} at {$school_name}.\n\nPlease reply if you cannot attend.\n\nThank you,\nCoverMeNow ONE";
                $this->send_candidate_email($candidate_email, $subject, $message, [
                    'type' => 'candidate_booking_confirmed',
                    'related_school_domain' => $school_domain,
                    'related_candidate_id' => $candidate_id,
                    'related_request_id' => $request_id,
                ]);
            }
            if ($candidate_user_id) {
                $this->add_notification($candidate_user_id, 'booking_confirmed', 'Booking confirmed', 'You\'re booked for ' . $requested_label . ' at ' . $school_name . '.', $candidate_bookings_url);
            }
            $this->insert_activity_row([
                'entity_type' => 'school',
                'entity_ref' => $school_domain,
                'activity_type' => 'note',
                'subject' => 'Candidate availability confirmed',
                'notes' => $candidate_name . ' confirmed for ' . $requested_date . '.',
                'created_by' => get_current_user_id(),
            ]);
            $this->insert_activity_row([
                'entity_type' => 'contact',
                'entity_ref' => (string) $candidate_id,
                'activity_type' => 'note',
                'subject' => 'Availability confirmed',
                'notes' => 'Confirmed for ' . $requested_date . '.',
                'created_by' => get_current_user_id(),
            ]);
        } elseif ($status === 'declined') {
            $school_email = $this->get_school_primary_contact_email($school_id);
            if ($school_email) {
                $subject = 'Candidate unavailable';
                $message = "Unfortunately {$first_name} ({$role_label}) is unavailable for {$requested_label}.\n\nPlease select another available candidate and we'll confirm as quickly as possible.";
                $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
                $GLOBALS['cmn_school_mail_log_type'] = 'school_request_declined';
                $this->send_school_email($school_email, $subject, $message);
                if ($previous_log_type !== null) {
                    $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
                } else {
                    unset($GLOBALS['cmn_school_mail_log_type']);
                }
            }
            if ($school_user_id) {
                $this->add_notification($school_user_id, 'request_declined', 'Request declined', $first_name . ' is unavailable for ' . $requested_label . '.', $school_requests_url);
            }
            if (self::EMAIL_CANDIDATE_DECLINED && $candidate_email) {
                $subject = 'Update on your availability';
                $message = "Hi {$first_name},\n\nYou weren't selected for {$requested_label}.\n\nThank you for confirming your availability.\n\nCoverMeNow ONE";
                $this->send_candidate_email($candidate_email, $subject, $message, [
                    'type' => 'candidate_booking_declined',
                    'related_school_domain' => $school_domain,
                    'related_candidate_id' => $candidate_id,
                    'related_request_id' => $request_id,
                ]);
            }
            $this->insert_activity_row([
                'entity_type' => 'school',
                'entity_ref' => $school_domain,
                'activity_type' => 'note',
                'subject' => 'Request declined',
                'notes' => $candidate_name . ' unavailable for ' . $requested_date . '.',
                'created_by' => get_current_user_id(),
            ]);
            $this->insert_activity_row([
                'entity_type' => 'contact',
                'entity_ref' => (string) $candidate_id,
                'activity_type' => 'note',
                'subject' => 'Request declined',
                'notes' => 'Unavailable for ' . $requested_date . '.',
                'created_by' => get_current_user_id(),
            ]);
        } else {
            $school_email = $this->get_school_primary_contact_email($school_id);
            if ($school_email) {
                $subject = 'Booking request no longer needed';
                $message = "This request is no longer needed for {$requested_label}.";
                $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
                $GLOBALS['cmn_school_mail_log_type'] = 'school_request_cancelled';
                $this->send_school_email($school_email, $subject, $message);
                if ($previous_log_type !== null) {
                    $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
                } else {
                    unset($GLOBALS['cmn_school_mail_log_type']);
                }
            }
            if ($candidate_email) {
                $this->send_candidate_email($candidate_email, 'Booking request no longer needed', "This request for {$requested_label} is no longer needed.", [
                    'type' => 'candidate_booking_declined',
                    'related_school_domain' => $school_domain,
                    'related_candidate_id' => $candidate_id,
                    'related_request_id' => $request_id,
                ]);
            }
        }

        $redirect = wp_get_referer() ?: home_url('/portal');
        wp_redirect(add_query_arg(['cmn_request_msg' => rawurlencode('Request updated.')], $redirect));
        exit;
    }

    public function handle_create_booking() {
        if (!isset($_POST['cmn_create_booking_nonce']) || !wp_verify_nonce($_POST['cmn_create_booking_nonce'], 'cmn_create_booking')) {
            wp_die('Invalid request');
        }

        $start_date = sanitize_text_field($_POST['cmn_start_date'] ?? $_POST['cmn_date'] ?? '');
        $end_date = sanitize_text_field($_POST['cmn_end_date'] ?? '');
        $until_further_notice = isset($_POST['cmn_until_further_notice']) ? '1' : '0';
        $start_time = sanitize_text_field($_POST['cmn_start_time'] ?? '');
        $end_time = sanitize_text_field($_POST['cmn_end_time'] ?? '');
        $role = sanitize_text_field($_POST['cmn_role'] ?? '');
        $notes = sanitize_textarea_field($_POST['cmn_notes'] ?? '');
        $school_id = intval($_POST['cmn_school_id'] ?? 0);
        $candidate_id = intval($_POST['cmn_candidate_id'] ?? 0);
        $location = sanitize_text_field($_POST['cmn_location'] ?? '');
        if (!$location && $school_id) {
            $location = get_post_meta($school_id, 'cmn_location', true);
        }
        $requested_rate = sanitize_text_field($_POST['cmn_requested_rate'] ?? '');
        $rate_context = $this->resolve_rate_context($candidate_id, $school_id, [], 0);
        $suggested_rates = $this->get_suggested_rates_for_context($rate_context['role_key'], $rate_context['region_key']);

        $post_id = wp_insert_post([
            'post_type' => 'cmn_booking',
            'post_title' => $role && $start_date ? $role . ' - ' . $start_date : 'Booking Request',
            'post_status' => 'publish',
        ]);

        if (!is_wp_error($post_id)) {
            update_post_meta($post_id, 'cmn_date', $start_date);
            update_post_meta($post_id, 'cmn_start_date', $start_date);
            update_post_meta($post_id, 'cmn_end_date', $end_date);
            update_post_meta($post_id, 'cmn_until_further_notice', $until_further_notice);
            update_post_meta($post_id, 'cmn_start_time', $start_time);
            update_post_meta($post_id, 'cmn_end_time', $end_time);
            update_post_meta($post_id, 'cmn_role', $role);
            update_post_meta($post_id, 'cmn_notes', $notes);
            update_post_meta($post_id, 'cmn_status', 'requested');
            update_post_meta($post_id, 'cmn_location', $location);
            if ($requested_rate !== '') {
                update_post_meta($post_id, 'cmn_requested_rate', $requested_rate);
            }
            update_post_meta($post_id, 'cmn_created_at', time());
            if ($school_id) {
                update_post_meta($post_id, 'cmn_school_id', $school_id);
            }
            if ($candidate_id) {
                update_post_meta($post_id, 'cmn_candidate_id', $candidate_id);
            }
            $candidate_pay_rate = (float) ($suggested_rates['candidate_pay'] ?? 0.0);
            $school_charge_rate = (float) ($suggested_rates['school_rate'] ?? 0.0);
            if ($candidate_pay_rate > 0) {
                update_post_meta($post_id, 'cmn_candidate_pay_rate', $candidate_pay_rate);
            }
            if ($school_charge_rate > 0) {
                update_post_meta($post_id, 'cmn_school_charge_rate', $school_charge_rate);
            }
            if ($candidate_pay_rate > 0 && $school_charge_rate > 0) {
                $this->upsert_booking_rates(
                    (int) $post_id,
                    0,
                    (string) $rate_context['role_key'],
                    (string) $rate_context['region_key'],
                    $school_charge_rate,
                    $candidate_pay_rate,
                    0,
                    'Booking created with default rates'
                );
            }

            $confirmation_seed = $this->ensure_booking_completion_confirmations_for_booking(
                (int) $post_id,
                $this->is_school_user((int) get_current_user_id()) ? (int) get_current_user_id() : 0
            );
            if (is_wp_error($confirmation_seed)) {
                $this->add_audit_log('school_partner_confirmation_seed_failed', 'booking', (string) $post_id, [
                    'school_id' => (int) $school_id,
                    'school_user_id' => $this->is_school_user((int) get_current_user_id()) ? (int) get_current_user_id() : 0,
                    'message' => $confirmation_seed->get_error_message(),
                    'source' => 'handle_create_booking',
                ], (int) get_current_user_id());
            }

            $admin_email = get_option('admin_email');
            $subject = 'New Booking Request';
            $message = "A new booking request was submitted.\n\nStart: {$start_date}\nEnd: {$end_date}\nRole: {$role}\nNotes: {$notes}\n\nReview in the CRM.";
            wp_mail($admin_email, $subject, $message);
            $this->add_audit_log('booking_created', 'booking', (string) $post_id, [
                'school_id' => $school_id,
                'candidate_id' => $candidate_id,
                'start_date' => $start_date,
                'end_date' => $end_date,
                'role' => $role,
            ]);

            $this->trigger_automation_event('booking_created', 'booking', (int) $post_id, [
                'automation_meta' => ['source' => 'booking_create'],
            ]);
        }

        wp_redirect(add_query_arg('cmn_requested', '1', wp_get_referer() ?: home_url()));
        exit;
    }

    public function handle_update_status() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_update_status_nonce']) || !wp_verify_nonce($_POST['cmn_update_status_nonce'], 'cmn_update_status')) {
            wp_die('Invalid request');
        }
        $entity_type = sanitize_text_field($_POST['cmn_entity_type'] ?? '');
        $entity_id_raw = sanitize_text_field($_POST['cmn_entity_id'] ?? '');
        $status = sanitize_text_field($_POST['cmn_status'] ?? '');

        if ($entity_id_raw === '' || !$status) {
            wp_die('Invalid data');
        }
        $entity_id = intval($entity_id_raw);

        if ($entity_type === 'school') {
            $school_post_id = $this->resolve_school_identifier($entity_id_raw);
            if (!$school_post_id) {
                wp_die('Invalid school.');
            }
            if (!$this->user_can_access_school($school_post_id)) {
                wp_die('Unauthorized');
            }
            $previous_status = get_post_meta($school_post_id, 'cmn_status', true);
            update_post_meta($school_post_id, 'cmn_status', $status);
            $pipeline_stage = sanitize_text_field($_POST['cmn_pipeline_stage'] ?? '');
            if ($pipeline_stage) {
                if ($status === 'client' && $pipeline_stage !== 'lost') {
                    $pipeline_stage = 'won';
                }
                update_post_meta($school_post_id, 'cmn_pipeline_stage', $pipeline_stage);
            } elseif ($status === 'client') {
                $current_stage = get_post_meta($school_post_id, 'cmn_pipeline_stage', true);
                if ($current_stage !== 'lost') {
                    update_post_meta($school_post_id, 'cmn_pipeline_stage', 'won');
                }
            }
            if ($status !== $previous_status) {
                $this->send_school_status_email($school_post_id, $status);
            }
            $redirect = esc_url_raw($_POST['cmn_redirect'] ?? '');
            if ($redirect) {
                wp_redirect($redirect);
            } else {
                wp_redirect(admin_url('admin.php?page=cmn-school-profile&school_id=' . $school_post_id));
            }
            exit;
        }
        if ($entity_type === 'candidate') {
            if (!$this->user_can_view_candidate($entity_id)) {
                wp_die('Unauthorized');
            }
            update_post_meta($entity_id, 'cmn_status', $status);
            $email = get_post_meta($entity_id, 'cmn_email', true);
            if ($email) {
                $subject = 'Candidate Account Update';
                $message = "Your candidate account status is now: {$status}.";
                $this->send_candidate_email($email, $subject, $message, [
                    'type' => 'candidate_status_update',
                    'related_candidate_id' => $entity_id,
                ]);
            }
            $redirect = esc_url_raw($_POST['cmn_redirect'] ?? '');
            if ($redirect) {
                wp_redirect($redirect);
            } else {
                wp_redirect(admin_url('admin.php?page=cmn-candidate-profile&candidate_id=' . $entity_id));
            }
            exit;
        }
        if ($entity_type === 'booking') {
            $status_key = sanitize_key((string) $status);
            if (in_array($status_key, ['approved', 'confirmed', 'accepted'], true)) {
                $candidate_id = (int) get_post_meta($entity_id, 'cmn_candidate_id', true);
                $school_id = (int) get_post_meta($entity_id, 'cmn_school_id', true);
                $context = $this->resolve_rate_context($candidate_id, $school_id, [], (int) $entity_id);
                $school_rate = (float) get_post_meta($entity_id, 'cmn_school_charge_rate', true);
                $candidate_pay = (float) get_post_meta($entity_id, 'cmn_candidate_pay_rate', true);
                $validation = $this->get_rate_validation_payload($school_rate, $candidate_pay, $context['role_key'], $context['region_key']);
                $rate_row = $this->get_booking_rate_row((int) $entity_id);
                $is_override = !empty($rate_row['override_flag']) && (int) $rate_row['override_flag'] === 1;
                if (empty($validation['pass']) && !$is_override && !$this->is_admin_user()) {
                    wp_die('Booking blocked by margin guardrails. Admin override is required.');
                }
                $this->upsert_booking_rates(
                    (int) $entity_id,
                    (int) get_post_meta($entity_id, 'cmn_request_id', true),
                    $context['role_key'],
                    $context['region_key'],
                    $school_rate,
                    $candidate_pay,
                    $is_override ? 1 : 0,
                    $is_override ? (string) ($rate_row['override_reason'] ?? '') : 'Validated before status update'
                );
            }
            update_post_meta($entity_id, 'cmn_status', $status);
            $confirmation_seed = $this->ensure_booking_completion_confirmations_for_booking((int) $entity_id);
            if (is_wp_error($confirmation_seed)) {
                $this->add_audit_log('school_partner_confirmation_seed_failed', 'booking', (string) $entity_id, [
                    'status' => $status_key,
                    'message' => $confirmation_seed->get_error_message(),
                    'source' => 'booking_status_update',
                ], (int) get_current_user_id());
            }
            if ($this->is_completed_payable_booking_status($status_key)) {
                $this->maybe_award_school_partner_credits_for_booking((int) $entity_id, $status_key);
            }
            if ($this->is_rewards_attended_completion_status($status_key)) {
                $credit_result = $this->rewards_credit_completed_booking_days((int) $entity_id, (int) get_current_user_id());
                if (is_wp_error($credit_result)) {
                    $this->add_audit_log('candidate_rewards_shift_credit_failed', 'booking', (string) $entity_id, [
                        'status' => $status_key,
                        'message' => $credit_result->get_error_message(),
                    ], (int) get_current_user_id());
                }
            }
            if (in_array($status_key, ['completed', 'completed_attended'], true)) {
                $this->maybe_request_booking_feedback_notifications((int) $entity_id, true);
            }
            $subject = 'Booking Update';
            $message = "A booking has been {$status}. Please log in for details.";
            wp_mail(get_option('admin_email'), $subject, $message);
            $school_id = get_post_meta($entity_id, 'cmn_school_id', true);
            $candidate_id = get_post_meta($entity_id, 'cmn_candidate_id', true);
            $school_email = $school_id ? get_post_meta($school_id, 'cmn_email', true) : '';
            $candidate_email = $candidate_id ? get_post_meta($candidate_id, 'cmn_email', true) : '';
            $role = get_post_meta($entity_id, 'cmn_role', true);
            $start_date = get_post_meta($entity_id, 'cmn_start_date', true);
            $end_date = get_post_meta($entity_id, 'cmn_end_date', true);
            $start_time = get_post_meta($entity_id, 'cmn_start_time', true);
            $end_time = get_post_meta($entity_id, 'cmn_end_time', true);
            $location = get_post_meta($entity_id, 'cmn_location', true);
            if ($school_email) {
                $school_message = "Booking status: {$status}.\n\nRole: {$role}\nDates: {$start_date}" . ($end_date ? " to {$end_date}" : '') . "\nTime: {$start_time} - {$end_time}\nLocation: {$location}\n\nWe will confirm full placement details once approved.";
                if ($status === 'approved') {
                    $school_message = "Booking confirmed.\n\nRole: {$role}\nDates: {$start_date}" . ($end_date ? " to {$end_date}" : '') . "\nTime: {$start_time} - {$end_time}\nLocation: {$location}\n\nYour account manager will send full placement details.";
                }
                $previous_log_type = $GLOBALS['cmn_school_mail_log_type'] ?? null;
                $GLOBALS['cmn_school_mail_log_type'] = 'school_booking_update';
                $this->send_school_email($school_email, $subject, $school_message);
                if ($previous_log_type !== null) {
                    $GLOBALS['cmn_school_mail_log_type'] = $previous_log_type;
                } else {
                    unset($GLOBALS['cmn_school_mail_log_type']);
                }
            }
            if ($candidate_email) {
                $candidate_message = "Booking status updated: {$status}. We will be in touch with full details once confirmed.";
                if ($status === 'approved') {
                    $candidate_message = "Booking confirmed. You will receive placement details shortly.";
                }
                $this->send_candidate_email($candidate_email, $subject, $candidate_message, [
                    'type' => 'candidate_booking_update',
                    'related_candidate_id' => (int) $candidate_id,
                ]);
            }
            $booking_event = '';
            if (in_array($status_key, ['approved', 'accepted'], true)) {
                $booking_event = 'booking_accepted';
            } elseif ($status_key === 'declined') {
                $booking_event = 'booking_declined';
            }
            if ($booking_event !== '') {
                $this->trigger_automation_event($booking_event, 'booking', (int) $entity_id, [
                    'status' => $status_key,
                    'automation_meta' => ['source' => 'booking_status_update'],
                ]);
            }
            $redirect = esc_url_raw($_POST['cmn_redirect'] ?? '');
            if ($redirect) {
                wp_redirect($redirect);
            } else {
                wp_redirect(admin_url('admin.php?page=cmn-bookings'));
            }
            exit;
        }

        wp_die('Unknown entity type');
    }

    public function handle_marketing_lead_finder() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $criteria = [
            'status' => sanitize_text_field((string) ($_POST['status'] ?? 'lead')),
            'stage' => sanitize_text_field((string) ($_POST['stage'] ?? '')),
            'contacting' => sanitize_text_field((string) ($_POST['contacting'] ?? '')),
            'days' => (int) ($_POST['days'] ?? 14),
            'location' => sanitize_text_field((string) ($_POST['location'] ?? '')),
            'radius_center' => sanitize_text_field((string) ($_POST['radius_center'] ?? '')),
            'radius_miles' => (float) ($_POST['radius_miles'] ?? 0),
