            'q' => sanitize_text_field((string) ($_POST['q'] ?? '')),
        ];
        $meta = [];
        $rows = $this->get_marketing_school_rows($criteria, get_current_user_id(), $meta);
        wp_send_json_success([
            'rows' => $rows,
            'count' => count($rows),
            'warning' => (string) ($meta['warning'] ?? ''),
            'distance_active' => !empty($meta['distance_active']) ? 1 : 0,
