    public function handle_marketing_queue_campaign() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        global $wpdb;
        $campaign_id = (int) ($_POST['campaign_id'] ?? 0);
        $list_id = (int) ($_POST['list_id'] ?? 0);
        $override_recent = isset($_POST['override_recent']) && (int) $_POST['override_recent'] === 1;
        $cooldown_days = max(1, min(365, (int) ($_POST['cooldown_days'] ?? 30)));
        $confirm_large = !empty($_POST['confirm_large_send']) ? 1 : 0;
        if ($campaign_id < 1 || $list_id < 1) {
            wp_send_json_error(['message' => 'Campaign and list are required.'], 400);
        }
        $campaign = $this->get_marketing_campaign_by_id($campaign_id);
        if (!$campaign) {
            wp_send_json_error(['message' => 'Campaign not found.'], 404);
        }
        $members_table = $this->get_marketing_members_table();
        $sends_table = $this->get_marketing_sends_table();
        $member_rows = (array) $wpdb->get_results($wpdb->prepare(
            "SELECT entity_type, entity_id, school_id FROM {$members_table} WHERE list_id = %d",
            $list_id
        ), ARRAY_A);
        if (!$member_rows) {
            wp_send_json_error(['message' => 'Selected list has no members.'], 400);
        }
        if (count($member_rows) > 500 && (!$this->is_admin_user() || !$confirm_large)) {
            wp_send_json_error(['message' => 'Over 500 recipients requires admin confirmation checkbox.'], 400);
        }
        $queued = 0;
        $skipped = 0;
        $duplicates = 0;
        $cutoff = gmdate('Y-m-d H:i:s', strtotime('-' . $cooldown_days . ' days', current_time('timestamp')));
        foreach ($member_rows as $member_row) {
            $entity_type = sanitize_key((string) ($member_row['entity_type'] ?? 'school'));
            $entity_id = (int) ($member_row['entity_id'] ?? 0);
            $school_id = (int) ($member_row['school_id'] ?? 0);
            if ($entity_id < 1 && $school_id > 0) {
                $entity_type = 'school';
                $entity_id = $school_id;
            }
            if ($entity_id < 1) {
                continue;
            }
            $to_email = $entity_type === 'contact'
                ? sanitize_email((string) get_post_meta($entity_id, 'cmn_contact_email', true))
                : sanitize_email((string) get_post_meta($entity_id, 'cmn_email', true));
            if ($to_email === '') {
                $wpdb->insert($sends_table, [
                    'campaign_id' => $campaign_id,
                    'list_id' => $list_id,
                    'entity_type' => $entity_type,
                    'entity_id' => $entity_id,
                    'school_id' => $entity_type === 'school' ? $entity_id : 0,
                    'to_email' => '',
                    'status' => 'skipped_no_email',
                    'thread_key' => substr(wp_hash('cmn_marketing_skip_no_email_' . $campaign_id . '_' . $list_id . '_' . $entity_type . '_' . $entity_id . '_' . microtime(true)), 0, 60),
                    'created_at' => current_time('mysql'),
                ], ['%d', '%d', '%s', '%d', '%d', '%s', '%s', '%s', '%s']);
                $skipped++;
                continue;
            }
            if ($this->is_marketing_email_unsubscribed($to_email)) {
                $wpdb->insert($sends_table, [
                    'campaign_id' => $campaign_id,
                    'list_id' => $list_id,
                    'entity_type' => $entity_type,
                    'entity_id' => $entity_id,
                    'school_id' => $entity_type === 'school' ? $entity_id : 0,
                    'to_email' => $to_email,
                    'status' => 'skipped_unsubscribed',
                    'failure_reason' => 'Recipient unsubscribed.',
                    'error_message' => 'Recipient unsubscribed.',
                    'thread_key' => substr(wp_hash('cmn_marketing_skip_unsub_' . $campaign_id . '_' . $list_id . '_' . $entity_type . '_' . $entity_id . '_' . microtime(true)), 0, 60),
                    'created_at' => current_time('mysql'),
                ], ['%d', '%d', '%s', '%d', '%d', '%s', '%s', '%s', '%s', '%s', '%s']);
                $skipped++;
                continue;
            }
            if (!$override_recent) {
                $recent = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(1) FROM {$sends_table}
                     WHERE entity_type = %s
                       AND entity_id = %d
                       AND status IN ('queued','sent','replied')
                       AND COALESCE(sent_at, created_at) >= %s",
                    $entity_type,
                    $entity_id,
                    $cutoff
                ));
                if ($recent > 0) {
                    $wpdb->insert($sends_table, [
                        'campaign_id' => $campaign_id,
                        'list_id' => $list_id,
                        'entity_type' => $entity_type,
                        'entity_id' => $entity_id,
                        'school_id' => $entity_type === 'school' ? $entity_id : 0,
                        'to_email' => $to_email,
                        'status' => 'skipped_recently_contacted',
                        'failure_reason' => 'Skipped by cooldown window.',
                        'error_message' => 'Skipped by cooldown window.',
                        'thread_key' => substr(wp_hash('cmn_marketing_skip_recent_' . $campaign_id . '_' . $list_id . '_' . $entity_type . '_' . $entity_id . '_' . microtime(true)), 0, 60),
                        'created_at' => current_time('mysql'),
                    ], ['%d', '%d', '%s', '%d', '%d', '%s', '%s', '%s', '%s', '%s', '%s']);
                    $duplicates++;
                    continue;
                }
            }
            $thread_key = substr(wp_hash('cmn_marketing_' . $campaign_id . '_' . $list_id . '_' . $entity_type . '_' . $entity_id . '_' . microtime(true)), 0, 60);
            $inserted = $wpdb->insert($sends_table, [
                'campaign_id' => $campaign_id,
                'list_id' => $list_id,
                'entity_type' => $entity_type,
                'entity_id' => $entity_id,
                'school_id' => $entity_type === 'school' ? $entity_id : 0,
                'to_email' => $to_email,
                'status' => 'queued',
                'thread_key' => $thread_key,
                'created_at' => current_time('mysql'),
            ], ['%d', '%d', '%s', '%d', '%d', '%s', '%s', '%s', '%s']);
            if ($inserted) {
                $queued++;
            }
        }
        $wpdb->update($this->get_marketing_campaigns_table(), [
            'status' => 'sending',
            'send_started_at' => current_time('mysql'),
        ], ['id' => $campaign_id], ['%s', '%s'], ['%d']);

        $processed = $this->process_marketing_queue_batch($campaign_id, min(50, max(1, (int) ($campaign['throttle_per_minute'] ?? 30))));
        wp_send_json_success([
            'message' => sprintf('Queued %d send(s). %d skipped, %d duplicate(s).', $queued, $skipped, $duplicates),
            'queued' => $queued,
            'skipped' => $skipped,
            'duplicates' => $duplicates,
            'processed' => $processed,
            'queue' => $this->get_marketing_queue_snapshot(80),
        ]);
    }

