    public function handle_marketing_save_template() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        global $wpdb;
        $table = $this->get_marketing_templates_table();
        $template_id = (int) ($_POST['template_id'] ?? 0);
        $name = sanitize_text_field((string) ($_POST['name'] ?? ''));
        $subject = sanitize_text_field((string) ($_POST['subject_template'] ?? ''));
        $html = wp_kses_post((string) ($_POST['body_template_html'] ?? ''));
        $text = sanitize_textarea_field((string) ($_POST['body_template_text'] ?? ''));
        if ($name === '' || $subject === '') {
            wp_send_json_error(['message' => 'Template name and subject are required.'], 400);
        }
        $data = [
            'name' => $name,
            'subject_template' => $subject,
            'body_template_html' => $html,
            'body_template_text' => $text,
            'updated_at' => current_time('mysql'),
        ];
        if ($template_id > 0) {
            $wpdb->update($table, $data, ['id' => $template_id], ['%s', '%s', '%s', '%s', '%s'], ['%d']);
        } else {
            $data['created_by'] = get_current_user_id();
            $data['created_at'] = current_time('mysql');
            $wpdb->insert($table, $data, ['%s', '%s', '%s', '%s', '%s', '%d', '%s']);
