    public function handle_marketing_test_send() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $to_email = sanitize_email((string) ($_POST['to_email'] ?? ''));
        $entity_type = sanitize_key((string) ($_POST['entity_type'] ?? 'school'));
        $entity_id = (int) ($_POST['entity_id'] ?? 0);
        $subject_template = sanitize_text_field((string) ($_POST['subject_template'] ?? ''));
        $body_template_html = (string) ($_POST['body_template_html'] ?? '');
        $body_template_text = sanitize_textarea_field((string) ($_POST['body_template_text'] ?? ''));
        if ($to_email === '' || $subject_template === '' || $entity_id < 1) {
            wp_send_json_error(['message' => 'Test send requires recipient email, template subject, and preview entity.'], 400);
        }
        $subject = $this->render_marketing_template_text($subject_template, $entity_type, $entity_id);
        $body_html = $this->render_marketing_template_text($body_template_html, $entity_type, $entity_id);
        $body_text = $this->render_marketing_template_text($body_template_text, $entity_type, $entity_id);
        $mail_body = $body_html !== '' ? wp_kses_post($body_html) : nl2br(esc_html($body_text));
        $result = $this->send_school_email($to_email, $subject, $mail_body, ['Content-Type: text/html; charset=UTF-8'], []);
        wp_send_json_success([
            'message' => $result ? 'Test email sent.' : 'Test email failed (wp_mail returned false).',
            'sent' => $result ? 1 : 0,
            'subject' => $subject,
        ]);
    }

    public function handle_marketing_get_send_log() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        global $wpdb;
        $limit = max(1, min(500, (int) ($_POST['limit'] ?? 120)));
        $status = sanitize_key((string) ($_POST['status'] ?? ''));
        $campaign_id = (int) ($_POST['campaign_id'] ?? 0);
        $template_id = (int) ($_POST['template_id'] ?? 0);
        $days = (int) ($_POST['days'] ?? 30);
        $where = ['1=1'];
        $params = [];
        if ($status !== '') {
            $where[] = 's.status = %s';
            $params[] = $status;
        }
        if ($campaign_id > 0) {
            $where[] = 's.campaign_id = %d';
            $params[] = $campaign_id;
        }
        if ($template_id > 0) {
            $where[] = 'c.template_id = %d';
            $params[] = $template_id;
        }
        if ($days > 0) {
            $where[] = 's.created_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL %d DAY)';
            $params[] = $days;
        }
        $where_sql = implode(' AND ', $where);
        $params[] = $limit;
        $sql = "SELECT s.*, c.name AS campaign_name, c.template_id, t.name AS template_name
                FROM {$this->get_marketing_sends_table()} s
                LEFT JOIN {$this->get_marketing_campaigns_table()} c ON c.id = s.campaign_id
                LEFT JOIN {$this->get_marketing_templates_table()} t ON t.id = c.template_id
                WHERE {$where_sql}
                ORDER BY s.id DESC
                LIMIT %d";
        $rows = (array) $wpdb->get_results($wpdb->prepare($sql, ...$params), ARRAY_A);
        wp_send_json_success([
            'rows' => $rows,
            'campaigns' => $this->get_marketing_campaigns_for_user(get_current_user_id(), 200),
            'templates' => $this->get_marketing_templates(200),
        ]);
    }

    public function handle_marketing_export_send_log() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_die('Invalid request');
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_die('Unauthorized');
        }
        global $wpdb;
        $status = sanitize_key((string) ($_GET['status'] ?? ''));
        $campaign_id = (int) ($_GET['campaign_id'] ?? 0);
        $where = ['1=1'];
        $params = [];
        if ($status !== '') {
            $where[] = 's.status = %s';
            $params[] = $status;
        }
        if ($campaign_id > 0) {
            $where[] = 's.campaign_id = %d';
            $params[] = $campaign_id;
        }
        $where_sql = implode(' AND ', $where);
        $sql = "SELECT s.id AS send_id, s.campaign_id, c.name AS campaign_name, t.name AS template_name, s.to_email, s.entity_type, s.entity_id, s.status, s.error_message, s.sent_at
                FROM {$this->get_marketing_sends_table()} s
                LEFT JOIN {$this->get_marketing_campaigns_table()} c ON c.id = s.campaign_id
                LEFT JOIN {$this->get_marketing_templates_table()} t ON t.id = c.template_id
                WHERE {$where_sql}
                ORDER BY s.id DESC";
        $rows = (array) $wpdb->get_results($wpdb->prepare($sql, ...$params), ARRAY_A);
        nocache_headers();
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=cmn-marketing-send-log.csv');
        $out = fopen('php://output', 'w');
        fputcsv($out, ['send_id', 'campaign_id', 'campaign_name', 'template_name', 'to_email', 'entity_type', 'entity_id', 'status', 'error_message', 'sent_at']);
        foreach ($rows as $row) {
            fputcsv($out, [
                (int) ($row['send_id'] ?? 0),
                (int) ($row['campaign_id'] ?? 0),
                (string) ($row['campaign_name'] ?? ''),
                (string) ($row['template_name'] ?? ''),
                (string) ($row['to_email'] ?? ''),
                (string) ($row['entity_type'] ?? ''),
                (int) ($row['entity_id'] ?? 0),
                (string) ($row['status'] ?? ''),
                (string) ($row['error_message'] ?? ''),
                (string) ($row['sent_at'] ?? ''),
            ]);
        }
        fclose($out);
        exit;
    }

    public function handle_marketing_resend_failed() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        global $wpdb;
        $campaign_id = (int) ($_POST['campaign_id'] ?? 0);
        if ($campaign_id < 1) {
            wp_send_json_error(['message' => 'Campaign is required.'], 400);
        }
        $sends_table = $this->get_marketing_sends_table();
        $rows = (array) $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$sends_table} WHERE campaign_id = %d AND status = 'failed' ORDER BY id DESC LIMIT 1000",
            $campaign_id
        ), ARRAY_A);
        $requeued = 0;
        $skipped = 0;
        foreach ($rows as $row) {
            $to_email = sanitize_email((string) ($row['to_email'] ?? ''));
            if ($to_email === '' || $this->is_marketing_email_unsubscribed($to_email)) {
                $skipped++;
                continue;
            }
            $wpdb->update($sends_table, [
                'status' => 'queued',
                'error_message' => null,
                'failure_reason' => null,
            ], ['id' => (int) ($row['id'] ?? 0)], ['%s', '%s', '%s'], ['%d']);
            $requeued++;
        }
        wp_send_json_success([
            'message' => "Requeued {$requeued} failed send(s). Skipped {$skipped}.",
            'requeued' => $requeued,
            'skipped' => $skipped,
        ]);
    }

