    public function handle_marketing_segment_to_list() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        global $wpdb;
        $segment_id = (int) ($_POST['segment_id'] ?? 0);
        $name = sanitize_text_field((string) ($_POST['list_name'] ?? ''));
        if ($segment_id < 1 || $name === '') {
            wp_send_json_error(['message' => 'Segment and list name are required.'], 400);
        }
        $segment = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->get_marketing_segments_table()} WHERE id=%d", $segment_id), ARRAY_A);
        if (!$segment) {
            wp_send_json_error(['message' => 'Segment not found.'], 404);
        }
        $criteria = json_decode((string) ($segment['filter_json'] ?? '{}'), true);
        if (!is_array($criteria)) {
            $criteria = [];
        }
        $rows = $this->get_marketing_school_rows($criteria, get_current_user_id());
        $wpdb->insert($this->get_marketing_lists_table(), [
            'name' => $name,
            'type' => 'static',
            'criteria_json' => wp_json_encode($criteria),
            'created_by_user_id' => get_current_user_id(),
            'created_at' => current_time('mysql'),
            'updated_at' => current_time('mysql'),
        ], ['%s', '%s', '%s', '%d', '%s', '%s']);
        $list_id = (int) $wpdb->insert_id;
        $count = 0;
        foreach ($rows as $row) {
            $school_id = (int) ($row['school_id'] ?? 0);
            if ($school_id < 1) {
                continue;
            }
            $wpdb->insert($this->get_marketing_members_table(), [
                'list_id' => $list_id,
                'entity_type' => 'school',
                'entity_id' => $school_id,
                'school_id' => $school_id,
                'added_at' => current_time('mysql'),
                'added_by_user_id' => get_current_user_id(),
                'source' => 'segment',
            ], ['%d', '%s', '%d', '%d', '%s', '%d', '%s']);
            $count++;
        }
        wp_send_json_success(['list_id' => $list_id, 'member_count' => $count, 'message' => 'Segment converted to list.']);
    }

    public function handle_marketing_save_quick_campaign() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        global $wpdb;
        $id = (int) ($_POST['id'] ?? 0);
        $name = sanitize_text_field((string) ($_POST['name'] ?? ''));
        $template_id = (int) ($_POST['template_id'] ?? 0);
        $target_type = sanitize_key((string) ($_POST['target_type'] ?? 'list'));
        $list_id = (int) ($_POST['list_id'] ?? 0);
        $segment_id = (int) ($_POST['segment_id'] ?? 0);
        $filter_json = (string) ($_POST['filter_json'] ?? '{}');
        $cooldown_days = max(1, min(365, (int) ($_POST['cooldown_days'] ?? 30)));
        $only_new = !empty($_POST['only_new_since_last_run']) ? 1 : 0;
        if ($name === '' || $template_id < 1) {
            wp_send_json_error(['message' => 'Quick campaign name and template are required.'], 400);
        }
        $data = [
            'name' => $name,
            'template_id' => $template_id,
            'target_type' => $target_type,
            'list_id' => $list_id > 0 ? $list_id : null,
            'segment_id' => $segment_id > 0 ? $segment_id : null,
            'filter_json' => $filter_json,
            'cooldown_days' => $cooldown_days,
            'only_new_since_last_run' => $only_new,
            'updated_at' => current_time('mysql'),
        ];
        $table = $this->get_marketing_quick_campaigns_table();
        if ($id > 0) {
            $wpdb->update($table, $data, ['id' => $id], ['%s', '%d', '%s', '%d', '%d', '%s', '%d', '%d', '%s'], ['%d']);
        } else {
            $data['created_by'] = get_current_user_id();
            $data['created_at'] = current_time('mysql');
            $wpdb->insert($table, $data, ['%s', '%d', '%s', '%d', '%d', '%s', '%d', '%d', '%s', '%d', '%s']);
            $id = (int) $wpdb->insert_id;
        }
        wp_send_json_success(['id' => $id, 'quick_campaigns' => $this->get_marketing_quick_campaigns(), 'message' => 'Quick campaign saved.']);
    }

    private function get_marketing_quick_campaigns($limit = 200) {
        global $wpdb;
        return (array) $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$this->get_marketing_quick_campaigns_table()} ORDER BY updated_at DESC, id DESC LIMIT %d",
            max(1, min(500, (int) $limit))
        ), ARRAY_A);
    }

