            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        wp_send_json_success(['quick_campaigns' => $this->get_marketing_quick_campaigns()]);
    }

    public function handle_marketing_run_quick_campaign() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->user_can_access_marketing()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        global $wpdb;
        $id = (int) ($_POST['id'] ?? 0);
        $qc = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->get_marketing_quick_campaigns_table()} WHERE id=%d", $id), ARRAY_A);
        if (!$qc) {
            wp_send_json_error(['message' => 'Quick campaign not found.'], 404);
        }
        $template = $this->get_marketing_template_by_id((int) ($qc['template_id'] ?? 0));
        if (!$template) {
            wp_send_json_error(['message' => 'Template not found.'], 404);
        }
        $recipients = [];
        $target_type = sanitize_key((string) ($qc['target_type'] ?? 'list'));
        if ($target_type === 'list' && !empty($qc['list_id'])) {
            $recipients = array_map('intval', $this->get_marketing_list_school_ids((int) $qc['list_id']));
        } elseif ($target_type === 'segment' && !empty($qc['segment_id'])) {
            $segment = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->get_marketing_segments_table()} WHERE id=%d", (int) $qc['segment_id']), ARRAY_A);
            $criteria = $segment ? json_decode((string) ($segment['filter_json'] ?? '{}'), true) : [];
            $rows = $this->get_marketing_school_rows(is_array($criteria) ? $criteria : [], get_current_user_id());
            foreach ($rows as $row) {
                $recipients[] = (int) ($row['school_id'] ?? 0);
            }
        } else {
            $criteria = json_decode((string) ($qc['filter_json'] ?? '{}'), true);
            $rows = $this->get_marketing_school_rows(is_array($criteria) ? $criteria : [], get_current_user_id());
            foreach ($rows as $row) {
                $recipients[] = (int) ($row['school_id'] ?? 0);
            }
        }
        $recipients = array_values(array_filter(array_unique($recipients)));
        if (!$recipients) {
            wp_send_json_error(['message' => 'No recipients found for this quick campaign.'], 400);
        }
        $campaign_id = 0;
        $wpdb->insert($this->get_marketing_campaigns_table(), [
            'name' => sanitize_text_field((string) $qc['name']) . ' ' . current_time('mysql'),
            'from_context' => 'school',
            'from_identity' => 'school',
            'template_id' => (int) $template['id'],
            'subject' => (string) ($template['subject_template'] ?? ''),
            'html_body' => (string) ($template['body_template_html'] ?? ''),
            'text_body' => (string) ($template['body_template_text'] ?? ''),
            'created_by_user_id' => get_current_user_id(),
            'created_at' => current_time('mysql'),
            'status' => 'sending',
            'throttle_per_minute' => 30,
        ], ['%s', '%s', '%s', '%d', '%s', '%s', '%s', '%d', '%s', '%s', '%d']);
        $campaign_id = (int) $wpdb->insert_id;
        $cooldown_days = max(1, (int) ($qc['cooldown_days'] ?? 30));
        $cutoff = gmdate('Y-m-d H:i:s', strtotime('-' . $cooldown_days . ' days'));
        $queued = 0;
        $skipped = 0;
        foreach ($recipients as $school_id) {
            if ($school_id < 1) {
                continue;
            }
            $email = sanitize_email((string) get_post_meta($school_id, 'cmn_email', true));
            if ($email === '' || $this->is_marketing_email_unsubscribed($email)) {
                $skipped++;
                continue;
            }
            $recent = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$this->get_marketing_sends_table()} WHERE entity_type='school' AND entity_id=%d AND status='sent' AND sent_at >= %s",
                $school_id,
                $cutoff
            ));
            if ($recent > 0) {
                $skipped++;
                continue;
            }
            $wpdb->insert($this->get_marketing_sends_table(), [
                'campaign_id' => $campaign_id,
                'list_id' => !empty($qc['list_id']) ? (int) $qc['list_id'] : null,
                'entity_type' => 'school',
                'entity_id' => $school_id,
                'school_id' => $school_id,
                'to_email' => $email,
                'status' => 'queued',
                'thread_key' => substr(wp_hash('cmn_qc_' . $campaign_id . '_' . $school_id . '_' . microtime(true)), 0, 60),
                'created_at' => current_time('mysql'),
            ], ['%d', '%d', '%s', '%d', '%d', '%s', '%s', '%s', '%s']);
            $queued++;
        }
        $result = $this->process_marketing_queue_batch($campaign_id, 50);
        $stats = [
            'queued' => $queued,
            'skipped' => $skipped,
            'processed' => $result,
        ];
        $wpdb->update($this->get_marketing_quick_campaigns_table(), [
            'last_run_at' => current_time('mysql'),
            'last_run_stats_json' => wp_json_encode($stats),
            'updated_at' => current_time('mysql'),
        ], ['id' => $id], ['%s', '%s', '%s'], ['%d']);
        wp_send_json_success(['message' => 'Quick campaign run completed.', 'stats' => $stats]);
    }

    public function handle_send_candidate_invite() {
        if (!current_user_can('manage_options')) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_send_candidate_invite_nonce']) || !wp_verify_nonce($_POST['cmn_send_candidate_invite_nonce'], 'cmn_send_candidate_invite')) {
            wp_die('Invalid request');
        }
        $booking_id = intval($_POST['cmn_booking_id'] ?? 0);
        $candidate_id = intval($_POST['cmn_candidate_id'] ?? 0);
        if (!$booking_id || !$candidate_id) {
            wp_die('Missing booking or candidate.');
        }
        $school_id = get_post_meta($booking_id, 'cmn_school_id', true);
        update_post_meta($booking_id, 'cmn_candidate_id', $candidate_id);
        update_post_meta($booking_id, 'cmn_status', 'candidate_invited');
        update_post_meta($booking_id, 'cmn_candidate_invited_at', time());
        $deadline = time() + (15 * 60);
        update_post_meta($booking_id, 'cmn_candidate_deadline', $deadline);
        $token = wp_generate_password(20, false, false);
        update_post_meta($booking_id, 'cmn_candidate_token', $token);

        $candidate_email = get_post_meta($candidate_id, 'cmn_email', true);
        $role = get_post_meta($booking_id, 'cmn_role', true);
        $start_date = get_post_meta($booking_id, 'cmn_start_date', true);
        $end_date = get_post_meta($booking_id, 'cmn_end_date', true);
        $start_time = get_post_meta($booking_id, 'cmn_start_time', true);
        $end_time = get_post_meta($booking_id, 'cmn_end_time', true);
        $location = get_post_meta($booking_id, 'cmn_location', true);
        $rate = $this->get_candidate_rate($candidate_id, $school_id);
        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        $accept_url = add_query_arg([
            'action' => 'cmn_candidate_response',
            'booking_id' => $booking_id,
            'response' => 'accept',
            'token' => $token,
        ], admin_url('admin-post.php'));
        $decline_url = add_query_arg([
            'action' => 'cmn_candidate_response',
            'booking_id' => $booking_id,
            'response' => 'decline',
            'token' => $token,
        ], admin_url('admin-post.php'));

        $subject = 'CoverMeNow ONE - Availability Request';
        $message = "We have a cover request:\n\nRole: {$role}\nDates: {$start_date}" . ($end_date ? " to {$end_date}" : '') . "\nTime: {$start_time} - {$end_time}\nLocation: Within {$location}\nRate: GBP {$rate}/day\n\nWould you like to proceed?\nAccept: {$accept_url}\nDecline: {$decline_url}\n\nPlease respond within 15 minutes.";
        $account = $school_id ? $this->get_account_manager($school_id) : ['email' => get_option('admin_email'), 'name' => 'CoverMeNow ONE'];
        $this->send_candidate_email($candidate_email, $subject, $message, [
            'type' => 'candidate_availability_request',
            'related_candidate_id' => $candidate_id,
        ]);

        wp_redirect(add_query_arg(['view' => 'bookings', 'cmn_sent' => '1'], home_url('/cmn-one')));
        exit;
    }

    public function handle_candidate_response() {
        $booking_id = intval($_REQUEST['booking_id'] ?? 0);
        $response = sanitize_text_field($_REQUEST['response'] ?? '');
        $token = sanitize_text_field($_REQUEST['token'] ?? '');
        if (!$booking_id || !$token) {
            wp_die('Invalid response.');
        }
        $saved_token = get_post_meta($booking_id, 'cmn_candidate_token', true);
        $deadline = (int) get_post_meta($booking_id, 'cmn_candidate_deadline', true);
        if ($saved_token !== $token) {
            wp_die('Invalid token.');
        }
        if ($deadline && time() > $deadline) {
            update_post_meta($booking_id, 'cmn_status', 'expired');
            wp_die('This request has expired.');
        }
        if ($response === 'accept') {
            update_post_meta($booking_id, 'cmn_status', 'candidate_accepted');
        } else {
            update_post_meta($booking_id, 'cmn_status', 'candidate_declined');
        }

        $school_id = get_post_meta($booking_id, 'cmn_school_id', true);
        $account = $school_id ? $this->get_account_manager($school_id) : ['email' => get_option('admin_email'), 'name' => 'CoverMeNow ONE'];
        $subject = 'Candidate Response';
        $message = "Candidate response received: {$response}. Booking ID: {$booking_id}.";
        $this->send_cmn_mail($account['email'], $subject, $message, 'candidate@covermenow.co.uk', 'CoverMeNow ONE');

        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        wp_redirect(add_query_arg('candidate_response', $response, $portal_url));
        exit;
    }

    public function expire_booking_requests() {
        $args = [
            'post_type' => 'cmn_booking',
            'posts_per_page' => 20,
            'meta_query' => [
                [
                    'key' => 'cmn_status',
                    'value' => 'candidate_invited',
                ],
                [
                    'key' => 'cmn_candidate_deadline',
                    'value' => time(),
                    'compare' => '<',
                    'type' => 'NUMERIC',
                ],
            ],
        ];
        $items = get_posts($args);
        foreach ($items as $booking) {
            update_post_meta($booking->ID, 'cmn_status', 'expired');
            $school_id = get_post_meta($booking->ID, 'cmn_school_id', true);
            $account = $school_id ? $this->get_account_manager($school_id) : ['email' => get_option('admin_email'), 'name' => 'CoverMeNow ONE'];
            $subject = 'Booking Invite Expired';
            $message = 'A candidate did not respond in time. Booking ID: ' . $booking->ID . '.';
            $this->send_cmn_mail($account['email'], $subject, $message, 'candidate@covermenow.co.uk', 'CoverMeNow ONE');
        }
        $this->maybe_request_feedback_for_past_bookings();
    }

