        echo '<button class="button button-primary" type="submit">' . esc_html($is_enabled ? 'Disable Training Mode' : 'Enable Training Mode') . '</button>';
        echo '</form>';

        echo '<form method="post" action="' . esc_url(admin_url('admin-post.php')) . '" style="margin-bottom:16px;">';
        wp_nonce_field('cmn_training_mode_update', 'cmn_training_mode_nonce');
        echo '<input type="hidden" name="action" value="cmn_training_mode_update">';
        echo '<input type="hidden" name="cmn_training_action" value="set_virtual_now">';
