        echo '<input id="cmn_virtual_now" name="cmn_virtual_now" type="datetime-local" value="' . esc_attr($virtual_now_for_input) . '" style="min-width:260px;margin:8px 0;"> ';
        echo '<button class="button" type="submit">Set Virtual Now</button> ';
