        echo '<p><button class="button button-primary" type="submit">Import Schools CSV</button></p>';
        echo '</form>';
        echo '<p>Expected headers (required): School, Location, Phone, Email, Cover Manager, Cover Manager Email, Email Name. Optional: Account Manager, Status, Pipeline Stage, School ID, Contact Name, Contact Email, Contact Phone, Contact Role, Switchboard, Website. Status defaults to lead when blank.</p>';
        echo '</div>';
    }

    private function import_schools_csv($file) {
        $handle = fopen($file, 'r');
        if (!$handle) {
            return 'Could not open file.';
        }
        $header = fgetcsv($handle);
        if (!$header) {
            fclose($handle);
            return 'Empty CSV.';
        }
        $map = [];
        foreach ($header as $index => $name) {
            $map[trim($name)] = $index;
        }
        $required = ['School', 'Location', 'Phone', 'Email', 'Cover Manager', 'Cover Manager Email', 'Email Name'];
        foreach ($required as $req) {
            if (!array_key_exists($req, $map)) {
                fclose($handle);
                return 'Missing required column: ' . $req;
            }
        }

        $count = 0;
        $created = 0;
        $updated = 0;
        $skipped = 0;
        $contact_warnings = 0;
        while (($row = fgetcsv($handle)) !== false) {
            $school_name = trim($row[$map['School']] ?? '');
            if ($school_name === '') {
                $skipped++;
                continue;
            }
            $location = trim($row[$map['Location']] ?? '');
            $phone = trim($row[$map['Phone']] ?? '');
            $school_email = trim($row[$map['Email']] ?? '');
            $cover_manager_name = trim($row[$map['Cover Manager']] ?? '');
            $cover_manager_email = trim($row[$map['Cover Manager Email']] ?? '');
            $email_name = trim($row[$map['Email Name']] ?? '');
            if ($location === '' || $phone === '' || $school_email === '' || $cover_manager_name === '' || $cover_manager_email === '' || $email_name === '') {
                $skipped++;
                continue;
            }
            if ($school_email && !is_email($school_email)) {
                $skipped++;
                continue;
            }
            if ($cover_manager_email && !is_email($cover_manager_email)) {
                $skipped++;
                continue;
            }
            if (strlen(preg_replace('/\\D+/', '', $phone)) < 7) {
                $skipped++;
                continue;
            }
            $school_domain = $this->get_email_domain($school_email);
            if ($school_domain === '') {
                $skipped++;
                continue;
            }

            $school_code = isset($map['School ID']) ? trim($row[$map['School ID']] ?? '') : '';
            if (!preg_match('/^CMN\\d+$/i', $school_code)) {
                $school_code = '';
            }
            $existing_id = 0;
            if ($school_code !== '') {
                $existing_id = $this->get_school_post_id_by_school_id($school_code);
            }
            if (!$existing_id) {
                $existing_id = $this->get_school_post_id_by_domain($school_domain);
            }
            if ($existing_id) {
                $post_id = $existing_id;
                wp_update_post([
                    'ID' => $post_id,
                    'post_title' => $school_name,
                ]);
                $updated++;
            } else {
                $post_id = wp_insert_post([
                    'post_type' => 'cmn_school',
                    'post_title' => $school_name,
                    'post_status' => 'publish',
                ]);
                if (is_wp_error($post_id)) {
                    $skipped++;
                    continue;
                }
                $created++;
            }
            $domain_owner = $this->get_school_post_id_by_domain($school_domain);
            if ($domain_owner && (int) $domain_owner !== (int) $post_id) {
                $skipped++;
                continue;
            }
            if ($school_code === '') {
                $school_code = get_post_meta($post_id, 'cmn_school_id', true);
                if ($school_code === '') {
                    $school_code = $this->generate_school_id();
                }
            }
            $meta = [
                'cmn_location' => $location,
                'cmn_phone' => $phone,
                'cmn_account_manager' => isset($map['Account Manager']) ? ($row[$map['Account Manager']] ?? '') : '',
                'cmn_cover_manager' => $cover_manager_name,
                'cmn_cover_manager_email' => $cover_manager_email,
                'cmn_email' => $school_email,
                'cmn_email_name' => $email_name,
                'cmn_contact1' => isset($map['Contact Name']) ? ($row[$map['Contact Name']] ?? '') : '',
                'cmn_contact1_email' => isset($map['Contact Email']) ? ($row[$map['Contact Email']] ?? '') : '',
                'cmn_contact2' => isset($map['Contact 2']) ? ($row[$map['Contact 2']] ?? '') : '',
                'cmn_contact2_email' => isset($map['Email2']) ? ($row[$map['Email2']] ?? '') : '',
                'cmn_spoke_to_cm' => isset($map['spoken to cm']) ? ($row[$map['spoken to cm']] ?? '') : '',
                'cmn_switchboard' => isset($map['Switchboard']) ? ($row[$map['Switchboard']] ?? '') : '',
                'cmn_website' => isset($map['Website']) ? ($row[$map['Website']] ?? '') : '',
                'cmn_status' => isset($map['Status']) ? ($row[$map['Status']] ?? '') : '',
                'cmn_pipeline_stage' => isset($map['Pipeline Stage']) ? ($row[$map['Pipeline Stage']] ?? '') : 'new_lead',
                'cmn_school_id' => $school_code,
                'cmn_school_email_domain' => $school_domain,
            ];
            if (trim($meta['cmn_status']) === '') {
                $meta['cmn_status'] = 'lead';
            }
            if ($meta['cmn_status'] === 'client' && $meta['cmn_pipeline_stage'] !== 'lost') {
                $meta['cmn_pipeline_stage'] = $meta['cmn_pipeline_stage'] ?: 'won';
            }
            foreach ($meta as $key => $value) {
                update_post_meta($post_id, $key, sanitize_text_field($value));
            }
            $this->store_cover_manager_split($post_id, $cover_manager_name);
            $this->upsert_school_index($post_id);
            $this->assert_imported_school_not_application_without_submission((int) $post_id, 'bulk_import_row');
            $contact_name = isset($map['Contact Name']) ? trim($row[$map['Contact Name']] ?? '') : '';
            $contact_email = isset($map['Contact Email']) ? trim($row[$map['Contact Email']] ?? '') : '';
            $contact_phone = isset($map['Contact Phone']) ? trim($row[$map['Contact Phone']] ?? '') : '';
            $contact_role = isset($map['Contact Role']) ? trim($row[$map['Contact Role']] ?? '') : '';
            if ($contact_name !== '') {
                $contact_id = $this->create_or_update_contact([
                    'name' => $contact_name,
                    'email' => $contact_email,
                    'phone' => $contact_phone,
                    'role' => $contact_role,
                    'school_id' => $post_id,
                    'school_domain' => $school_domain,
                    'is_primary' => true,
                ]);
                if (!$contact_id) {
                    $contact_warnings++;
                }
                update_post_meta($post_id, 'cmn_primary_contact_name', $contact_name);
                update_post_meta($post_id, 'cmn_primary_contact_email', $contact_email ?: $school_email);
                update_post_meta($post_id, 'cmn_primary_contact_phone', $contact_phone ?: $phone);
                update_post_meta($post_id, 'cmn_primary_contact_role', $contact_role);
            }
            $count += 1;
        }
        fclose($handle);
        $message = 'Imported ' . $count . ' schools (' . $created . ' new, ' . $updated . ' updated).';
        if ($skipped > 0) {
            $message .= ' Skipped ' . $skipped . ' rows with missing or invalid required fields.';
        }
        if ($contact_warnings > 0) {
            $message .= ' Contact warnings: ' . $contact_warnings . '.';
        }
        return $message;
    }

    private function get_school_import_job_key($job_id) {
        $job_id = sanitize_key((string) $job_id);
        if ($job_id === '') {
            return '';
        }
        return 'cmn_school_import_job_' . $job_id;
    }

    private function get_school_import_job($job_id) {
        $key = $this->get_school_import_job_key($job_id);
        if ($key === '') {
            return null;
        }
        $job = get_transient($key);
        return is_array($job) ? $job : null;
    }

    private function save_school_import_job($job_id, $job) {
        $key = $this->get_school_import_job_key($job_id);
        if ($key === '' || !is_array($job)) {
            return false;
        }
        return (bool) set_transient($key, $job, 12 * HOUR_IN_SECONDS);
    }

    private function normalize_school_import_map($map) {
        $normalized = [];
        $allowed = [
            'cmn_school_name',
            'cmn_location',
            'cmn_phone',
            'cmn_email',
            'cmn_cover_manager',
            'cmn_cover_manager_email',
            'cmn_email_name',
            'cmn_account_manager',
            'cmn_contact_name',
            'cmn_contact_email',
            'cmn_contact_phone',
            'cmn_contact_role',
            'cmn_spoke_to_cm',
            'cmn_switchboard',
            'cmn_website',
            'cmn_school_id',
            'cmn_status',
            'cmn_pipeline_stage',
            'cmn_postcode',
        ];
        foreach ($allowed as $key) {
            $value = isset($map[$key]) ? trim((string) $map[$key]) : '';
            if ($value === '' || !preg_match('/^\d+$/', $value)) {
                $normalized[$key] = '';
                continue;
            }
            $normalized[$key] = (int) $value;
        }
        return $normalized;
    }

    private function build_school_import_source_row($header, $row) {
        $source_row = [];
        foreach ((array) $header as $idx => $col_name) {
            $normalized_col_name = trim((string) $col_name);
            if ($normalized_col_name === '') {
                $normalized_col_name = 'column_' . ((int) $idx + 1);
            }
            $source_row[$normalized_col_name] = isset($row[$idx]) ? trim((string) $row[$idx]) : '';
        }
        return $source_row;
    }

    private function normalize_school_import_text($value) {
        $value = strtolower(trim((string) $value));
        $value = preg_replace('/\s+/', ' ', $value);
        return trim((string) $value);
    }

    private function build_school_import_identity_key($school_code, $school_name, $postcode, $school_email, $school_domain) {
        $school_code = strtoupper(trim((string) $school_code));
        if ($school_code !== '') {
            return 'school_id:' . $school_code;
        }
        $name_norm = $this->normalize_school_import_text($school_name);
        if ($name_norm === '') {
            return '';
        }
        $postcode_norm = strtolower(preg_replace('/\s+/', '', trim((string) $postcode)));
        if ($postcode_norm !== '') {
            return 'name_postcode:' . $name_norm . '|' . $postcode_norm;
        }
        $email_norm = strtolower(trim((string) $school_email));
        if ($school_domain !== '') {
            return 'name_domain:' . $name_norm . '|' . strtolower(trim((string) $school_domain));
        }
        if ($email_norm !== '') {
            return 'name_email:' . $name_norm . '|' . $email_norm;
        }
        return 'name_only:' . $name_norm;
    }

    private function get_school_post_id_by_import_identity($identity_key) {
        $identity_key = trim((string) $identity_key);
        if ($identity_key === '') {
            return 0;
        }
        $ids = get_posts([
            'post_type' => 'cmn_school',
            'post_status' => $this->get_school_list_post_statuses(),
            'posts_per_page' => 1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => 'cmn_import_identity_key',
                    'value' => $identity_key,
                ],
            ],
            'no_found_rows' => true,
        ]);
        if (!$ids) {
            return 0;
        }
        return (int) $ids[0];
    }

    private function get_school_post_id_by_name_and_postcode($school_name, $postcode) {
        global $wpdb;
        $school_name_norm = $this->normalize_school_import_text($school_name);
        $postcode_norm = strtolower(preg_replace('/\s+/', '', trim((string) $postcode)));
        if ($school_name_norm === '' || $postcode_norm === '') {
            return 0;
        }
        $post_statuses = $this->get_school_list_post_statuses();
        if (empty($post_statuses)) {
            return 0;
        }
        $status_placeholders = implode(',', array_fill(0, count($post_statuses), '%s'));
        $sql = "SELECT p.ID
            FROM {$wpdb->posts} p
            INNER JOIN {$wpdb->postmeta} pm_postcode ON pm_postcode.post_id = p.ID AND pm_postcode.meta_key = 'cmn_postcode'
            WHERE p.post_type = 'cmn_school'
              AND p.post_status IN ({$status_placeholders})
              AND LOWER(TRIM(p.post_title)) = %s
              AND REPLACE(LOWER(TRIM(pm_postcode.meta_value)), ' ', '') = %s
            LIMIT 1";
        $params = array_merge($post_statuses, [$school_name_norm, $postcode_norm]);
        $id = $wpdb->get_var($wpdb->prepare($sql, $params));
        return $id ? (int) $id : 0;
    }

    private function get_school_post_id_by_name_and_email($school_name, $school_email) {
        global $wpdb;
        $school_name_norm = $this->normalize_school_import_text($school_name);
        $email_norm = strtolower(trim((string) $school_email));
        if ($school_name_norm === '' || $email_norm === '') {
            return 0;
        }
        $post_statuses = $this->get_school_list_post_statuses();
        if (empty($post_statuses)) {
            return 0;
        }
        $status_placeholders = implode(',', array_fill(0, count($post_statuses), '%s'));
        $sql = "SELECT p.ID
            FROM {$wpdb->posts} p
            INNER JOIN {$wpdb->postmeta} pm_email ON pm_email.post_id = p.ID AND pm_email.meta_key = 'cmn_email'
            WHERE p.post_type = 'cmn_school'
              AND p.post_status IN ({$status_placeholders})
              AND LOWER(TRIM(p.post_title)) = %s
              AND LOWER(TRIM(pm_email.meta_value)) = %s
            LIMIT 1";
        $params = array_merge($post_statuses, [$school_name_norm, $email_norm]);
        $id = $wpdb->get_var($wpdb->prepare($sql, $params));
        return $id ? (int) $id : 0;
    }

    private function find_existing_school_for_import_row($school_code, $school_domain, $school_name, $postcode, $school_email, $identity_key) {
        $school_code = trim((string) $school_code);
        $school_domain = trim((string) $school_domain);
        if ($school_code !== '') {
            $existing = (int) $this->get_school_post_id_by_school_id($school_code);
            if ($existing > 0) {
                return $existing;
            }
        }
        if ($identity_key !== '') {
            $identity_match = (int) $this->get_school_post_id_by_import_identity($identity_key);
            if ($identity_match > 0) {
                return $identity_match;
            }
        }
        if ($school_domain !== '') {
            $domain_match = (int) $this->get_school_post_id_by_domain($school_domain);
            if ($domain_match > 0) {
                return $domain_match;
            }
        }
        $postcode_match = (int) $this->get_school_post_id_by_name_and_postcode($school_name, $postcode);
        if ($postcode_match > 0) {
            return $postcode_match;
        }
        $email_match = (int) $this->get_school_post_id_by_name_and_email($school_name, $school_email);
        if ($email_match > 0) {
            return $email_match;
        }
        return 0;
    }

    private function process_school_import_row($row, $map, $header, $job, $data_row_index) {
        $row_index = max(1, (int) $data_row_index + 1);
        $school_name = $this->csv_value($row, $map['cmn_school_name'] ?? '');
        $location = $this->csv_value($row, $map['cmn_location'] ?? '');
        $phone = $this->csv_value($row, $map['cmn_phone'] ?? '');
        $school_email = $this->csv_value($row, $map['cmn_email'] ?? '');
        $cover_manager_name = $this->csv_value($row, $map['cmn_cover_manager'] ?? '');
        $cover_manager_email = $this->csv_value($row, $map['cmn_cover_manager_email'] ?? '');
        $email_name = $this->csv_value($row, $map['cmn_email_name'] ?? '');
        $postcode = $this->csv_value($row, $map['cmn_postcode'] ?? '');
        $school_code = strtoupper(trim((string) $this->csv_value($row, $map['cmn_school_id'] ?? '')));

        $row_has_any_data = false;
        foreach ((array) $row as $cell) {
            if (trim((string) $cell) !== '') {
                $row_has_any_data = true;
                break;
            }
        }
        if (!$row_has_any_data) {
            return [
                'row_index' => $row_index,
                'school_name' => '',
                'status' => 'hard_invalid',
                'message' => 'Empty row.',
                'issues' => ['Empty row'],
                'school_id' => 0,
            ];
        }

        if ($school_name === '') {
            return [
                'row_index' => $row_index,
                'school_name' => '',
                'status' => 'hard_invalid',
                'message' => 'Missing School Name.',
                'issues' => ['Missing school name'],
                'school_id' => 0,
            ];
        }

        if (!preg_match('/^CMN\\d+$/i', $school_code)) {
            $school_code = '';
        }

        $import_issues = [];
        if ($location === '') {
            $import_issues[] = 'Missing location';
        }
        if ($phone === '') {
            $import_issues[] = 'Missing contact number';
        } elseif (strlen(preg_replace('/\\D+/', '', $phone)) < 7) {
            $import_issues[] = 'Invalid contact number';
        }
        if ($cover_manager_name === '') {
            $import_issues[] = 'Missing cover manager name';
        }
        if ($cover_manager_email === '') {
            $import_issues[] = 'Missing cover manager email';
        } elseif (!is_email($cover_manager_email)) {
            $import_issues[] = 'Invalid cover manager email';
        }
        // Rule: school email follows cover manager email when available.
        if ($cover_manager_email !== '' && is_email($cover_manager_email)) {
            $school_email = $cover_manager_email;
        }
        if ($school_email === '') {
            $import_issues[] = 'Missing school email';
        } elseif (!is_email($school_email)) {
            $import_issues[] = 'Invalid school email';
        }
        if ($email_name === '') {
            $import_issues[] = 'Missing email name';
        }

        $school_domain = '';
        if ($school_email !== '' && is_email($school_email)) {
            $school_domain = $this->get_email_domain($school_email);
            if ($school_domain === '') {
                $import_issues[] = 'Invalid school email domain';
            }
        }

        $identity_key = $this->build_school_import_identity_key($school_code, $school_name, $postcode, $school_email, $school_domain);
        $existing_id = $this->find_existing_school_for_import_row($school_code, $school_domain, $school_name, $postcode, $school_email, $identity_key);
        $created_new = false;

        if ($existing_id > 0) {
            $post_id = $existing_id;
            wp_update_post([
                'ID' => $post_id,
                'post_title' => $school_name,
            ]);
        } else {
            $post_id = wp_insert_post([
                'post_type' => 'cmn_school',
                'post_title' => $school_name,
                'post_status' => 'publish',
            ]);
            if (is_wp_error($post_id)) {
                return [
                    'row_index' => $row_index,
                    'school_name' => $school_name,
                    'status' => 'hard_invalid',
                    'message' => 'Could not create school post.',
                    'issues' => ['Could not create school post'],
                    'school_id' => 0,
                ];
            }
            $created_new = true;
        }

        if ($school_code === '') {
            $school_code = (string) get_post_meta($post_id, 'cmn_school_id', true);
            if ($school_code === '') {
                $school_code = $this->generate_school_id();
            }
        }

        $existing_status = sanitize_key((string) get_post_meta($post_id, 'cmn_status', true));
        $status = $created_new ? 'lead' : ($existing_status !== '' ? $existing_status : 'lead');
        if (!in_array($status, ['lead', 'client', 'archived', 'rejected', 'needs_attention'], true)) {
            $status = 'lead';
        }
        if (!empty($import_issues)) {
            $status = 'needs_attention';
        }
        $pipeline_stage = sanitize_key((string) $this->csv_value($row, $map['cmn_pipeline_stage'] ?? ''));
        if ($pipeline_stage === '') {
            $pipeline_stage = 'new_lead';
        }

        $meta = [
            'cmn_location' => $location,
            'cmn_phone' => $phone,
            'cmn_cover_manager' => $cover_manager_name,
            'cmn_cover_manager_email' => $cover_manager_email,
            'cmn_account_manager' => $this->csv_value($row, $map['cmn_account_manager'] ?? ''),
            'cmn_email' => $school_email,
            'cmn_email_name' => $email_name,
            'cmn_spoke_to_cm' => $this->csv_value($row, $map['cmn_spoke_to_cm'] ?? ''),
            'cmn_switchboard' => $this->csv_value($row, $map['cmn_switchboard'] ?? ''),
            'cmn_website' => $this->csv_value($row, $map['cmn_website'] ?? ''),
            'cmn_school_id' => $school_code,
            'cmn_status' => $status,
            'cmn_pipeline_stage' => $pipeline_stage,
            'cmn_postcode' => $postcode,
        ];
        if ($school_domain !== '') {
            $meta['cmn_school_email_domain'] = $school_domain;
        }
        if ($meta['cmn_status'] === 'client' && $meta['cmn_pipeline_stage'] !== 'lost') {
            $meta['cmn_pipeline_stage'] = $meta['cmn_pipeline_stage'] ?: 'won';
        }
        foreach ($meta as $key => $value) {
            update_post_meta($post_id, $key, sanitize_text_field($value));
        }
        $this->store_cover_manager_split($post_id, $cover_manager_name);
        $this->upsert_school_index($post_id);
        update_post_meta($post_id, 'cmn_import_batch_id', sanitize_text_field((string) ($job['batch_id'] ?? '')));
        update_post_meta($post_id, 'cmn_bulk_import_key', sanitize_text_field((string) ($job['job_id'] ?? '')) . ':' . $row_index);
        if ($identity_key !== '') {
            update_post_meta($post_id, 'cmn_import_identity_key', $identity_key);
        }
        if (!empty($import_issues)) {
            update_post_meta($post_id, 'cmn_import_issues', wp_json_encode(array_values($import_issues)));
        } else {
            delete_post_meta($post_id, 'cmn_import_issues');
        }
        $source_row = $this->build_school_import_source_row($header, $row);
        update_post_meta($post_id, 'cmn_import_source_row', wp_json_encode($source_row));

        $contact_name = $this->csv_value($row, $map['cmn_contact_name'] ?? '');
        $contact_email = $this->csv_value($row, $map['cmn_contact_email'] ?? '');
        $contact_phone = $this->csv_value($row, $map['cmn_contact_phone'] ?? '');
        $contact_role = $this->csv_value($row, $map['cmn_contact_role'] ?? '');
        $contact_warning = false;
        if ($contact_name !== '') {
            $contact_id = $this->create_or_update_contact([
                'name' => $contact_name,
                'email' => $contact_email,
                'phone' => $contact_phone,
                'role' => $contact_role,
                'school_id' => $post_id,
                'school_domain' => $school_domain,
                'is_primary' => true,
            ]);
            if (!$contact_id) {
                $contact_warning = true;
            } else {
                update_post_meta($post_id, 'cmn_contact1', $contact_name);
                update_post_meta($post_id, 'cmn_contact1_email', $contact_email);
                update_post_meta($post_id, 'cmn_contact_role', $contact_role);
                update_post_meta($post_id, 'cmn_primary_contact_name', $contact_name);
                update_post_meta($post_id, 'cmn_primary_contact_email', $contact_email ?: $school_email);
                update_post_meta($post_id, 'cmn_primary_contact_phone', $contact_phone ?: $phone);
                update_post_meta($post_id, 'cmn_primary_contact_role', $contact_role);
            }
        }
        if ($contact_warning) {
            $import_issues[] = 'Contact could not be linked';
            update_post_meta($post_id, 'cmn_import_issues', wp_json_encode(array_values(array_unique($import_issues))));
            update_post_meta($post_id, 'cmn_status', 'needs_attention');
            $status = 'needs_attention';
        }
        $this->assert_imported_school_not_application_without_submission((int) $post_id, 'bulk_import_row');

        if ($status === 'needs_attention') {
            return [
                'row_index' => $row_index,
                'school_name' => $school_name,
                'status' => 'needs_attention',
                'message' => implode('; ', array_values(array_unique($import_issues))),
                'issues' => array_values(array_unique($import_issues)),
                'school_id' => (int) $post_id,
                'created' => $created_new ? 1 : 0,
                'updated' => $created_new ? 0 : 1,
            ];
        }

        return [
            'row_index' => $row_index,
            'school_name' => $school_name,
            'status' => 'imported_ok',
            'message' => $created_new ? 'Created' : 'Updated',
            'issues' => [],
            'school_id' => (int) $post_id,
            'created' => $created_new ? 1 : 0,
            'updated' => $created_new ? 0 : 1,
        ];
    }

    private function create_school_import_job($file, $map, $ext, $user_id) {
        $rows = $this->read_spreadsheet_rows($file, $ext);
        if (!$rows) {
            return new WP_Error('cmn_import_rows_missing', 'No rows found.');
        }
        $header = array_shift($rows);
        if (!$header) {
            return new WP_Error('cmn_import_header_missing', 'Empty spreadsheet.');
        }
        $normalized_map = $this->normalize_school_import_map($map);
        if (($normalized_map['cmn_school_name'] ?? '') === '') {
            return new WP_Error('cmn_import_map_missing_school_name', 'Please map School Name before importing.');
        }

        $job_id = sanitize_key('j' . wp_generate_password(14, false, false));
        $group_size = 10;
        $total_rows = count($rows);
        $job = [
            'job_id' => $job_id,
            'user_id' => (int) $user_id,
            'created_at' => time(),
            'updated_at' => time(),
            'started_at' => current_time('mysql'),
            'ext' => sanitize_key((string) $ext),
            'header' => array_map(function ($value) {
                return trim((string) $value);
            }, (array) $header),
            'rows' => array_values((array) $rows),
            'map' => $normalized_map,
            'offset' => 0,
            'group_size' => $group_size,
            'groups_total' => $total_rows > 0 ? (int) ceil($total_rows / $group_size) : 0,
            'total_rows' => (int) $total_rows,
            'results' => [],
            'last_processed' => null,
            'counts' => [
                'imported_ok' => 0,
                'needs_attention' => 0,
                'hard_invalid' => 0,
                'created' => 0,
                'updated' => 0,
                'processed' => 0,
            ],
            'batch_id' => 'IMP-' . gmdate('YmdHis') . '-' . wp_generate_password(6, false, false),
            'file_checksum' => is_string($file) && file_exists($file) ? md5_file($file) : '',
            'done' => ($total_rows === 0),
            'completed_at' => null,
        ];
        if ($job['done']) {
            $job['completed_at'] = current_time('mysql');
        }

        if (!$this->save_school_import_job($job_id, $job)) {
            return new WP_Error('cmn_import_job_save_failed', 'Could not create import job.');
        }
        return [
            'job_id' => $job_id,
            'total_rows' => $job['total_rows'],
            'groups_total' => $job['groups_total'],
        ];
    }

    private function append_school_import_job_row_result(&$job, $row_offset, $result) {
        $row_offset = max(0, (int) $row_offset);
        if (!is_array($result)) {
            return;
        }
        if (!isset($job['results']) || !is_array($job['results'])) {
            $job['results'] = [];
        }
        if (!isset($job['counts']) || !is_array($job['counts'])) {
            $job['counts'] = [];
        }
        $job['results'][$row_offset] = $result;
        $status = sanitize_key((string) ($result['status'] ?? ''));
        if ($status === 'needs_attention') {
            $job['counts']['needs_attention'] = (int) ($job['counts']['needs_attention'] ?? 0) + 1;
        } elseif ($status === 'hard_invalid') {
            $job['counts']['hard_invalid'] = (int) ($job['counts']['hard_invalid'] ?? 0) + 1;
        } else {
            $job['counts']['imported_ok'] = (int) ($job['counts']['imported_ok'] ?? 0) + 1;
        }
        $job['counts']['created'] = (int) ($job['counts']['created'] ?? 0) + (int) ($result['created'] ?? 0);
        $job['counts']['updated'] = (int) ($job['counts']['updated'] ?? 0) + (int) ($result['updated'] ?? 0);
        $job['counts']['processed'] = (int) ($job['counts']['processed'] ?? 0) + 1;
        $job['last_processed'] = [
            'row_index' => (int) ($result['row_index'] ?? ($row_offset + 1)),
            'school_name' => sanitize_text_field((string) ($result['school_name'] ?? '')),
            'status' => $status,
        ];
    }

    private function build_school_import_row_errors($row_results) {
        $errors = [];
        foreach ((array) $row_results as $row_result) {
            if (!is_array($row_result)) {
                continue;
            }
            $status = sanitize_key((string) ($row_result['status'] ?? ''));
            if ($status === '' || $status === 'imported_ok') {
                continue;
            }
            $issues = array_values(array_filter(array_map('sanitize_text_field', (array) ($row_result['issues'] ?? []))));
            if (!$issues) {
                $fallback_issue = sanitize_text_field((string) ($row_result['message'] ?? 'Import issue'));
                if ($fallback_issue !== '') {
                    $issues[] = $fallback_issue;
                }
            }
            if (!$issues) {
                $issues[] = 'Import issue';
            }
            foreach ($issues as $issue) {
                $errors[] = [
                    'row_index' => (int) ($row_result['row_index'] ?? 0),
                    'school_name' => sanitize_text_field((string) ($row_result['school_name'] ?? '')),
                    'field' => 'row',
                    'message' => $issue,
                    'severity' => $status === 'hard_invalid' ? 'hard_invalid' : 'needs_attention',
                ];
            }
        }
        return $errors;
    }

    private function mark_school_import_row_skipped(&$job, $offset, $reason = '') {
        $rows = (array) ($job['rows'] ?? []);
        $map = (array) ($job['map'] ?? []);
        $header = (array) ($job['header'] ?? []);
        $offset = max(0, (int) $offset);
        $row = (array) ($rows[$offset] ?? []);
        $row_index = $offset + 1;
        $reason = sanitize_text_field((string) $reason);
        if ($reason === '') {
            $reason = 'Skipped after repeated timeout';
        }

        $school_name = $this->csv_value($row, $map['cmn_school_name'] ?? '');
        if ($school_name === '') {
            return [
                'row_index' => $row_index,
                'school_name' => '',
                'status' => 'hard_invalid',
                'message' => $reason . ': missing School Name.',
                'issues' => ['Missing school name'],
                'school_id' => 0,
                'created' => 0,
                'updated' => 0,
            ];
        }

        $location = $this->csv_value($row, $map['cmn_location'] ?? '');
        $phone = $this->csv_value($row, $map['cmn_phone'] ?? '');
        $school_email = $this->csv_value($row, $map['cmn_email'] ?? '');
        $cover_manager_name = $this->csv_value($row, $map['cmn_cover_manager'] ?? '');
        $cover_manager_email = $this->csv_value($row, $map['cmn_cover_manager_email'] ?? '');
        $email_name = $this->csv_value($row, $map['cmn_email_name'] ?? '');
        $postcode = $this->csv_value($row, $map['cmn_postcode'] ?? '');
        $school_code = strtoupper(trim((string) $this->csv_value($row, $map['cmn_school_id'] ?? '')));
        if (!preg_match('/^CMN\\d+$/i', $school_code)) {
            $school_code = '';
        }
        $school_domain = '';
        if ($school_email !== '' && is_email($school_email)) {
            $school_domain = $this->get_email_domain($school_email);
        }
        $identity_key = $this->build_school_import_identity_key($school_code, $school_name, $postcode, $school_email, $school_domain);
        $existing_id = $this->find_existing_school_for_import_row($school_code, $school_domain, $school_name, $postcode, $school_email, $identity_key);
        $created_new = false;
        if ($existing_id > 0) {
            $post_id = $existing_id;
            wp_update_post([
                'ID' => $post_id,
                'post_title' => $school_name,
            ]);
        } else {
            $post_id = wp_insert_post([
                'post_type' => 'cmn_school',
                'post_title' => $school_name,
                'post_status' => 'publish',
            ]);
            if (is_wp_error($post_id)) {
                return [
                    'row_index' => $row_index,
                    'school_name' => $school_name,
                    'status' => 'hard_invalid',
                    'message' => $reason . ': unable to create school record.',
                    'issues' => ['Could not create school post'],
                    'school_id' => 0,
                    'created' => 0,
                    'updated' => 0,
                ];
            }
            $created_new = true;
        }

        if ($school_code === '') {
            $school_code = (string) get_post_meta($post_id, 'cmn_school_id', true);
            if ($school_code === '') {
                $school_code = $this->generate_school_id();
            }
        }

        $issues = [];
        if ($location === '') {
            $issues[] = 'Missing location';
        }
        if ($phone === '') {
            $issues[] = 'Missing contact number';
        }
        if ($school_email === '') {
            $issues[] = 'Missing school email';
        } elseif (!is_email($school_email)) {
            $issues[] = 'Invalid school email';
        }
        if ($cover_manager_name === '') {
            $issues[] = 'Missing cover manager name';
        }
        if ($cover_manager_email === '') {
            $issues[] = 'Missing cover manager email';
        } elseif (!is_email($cover_manager_email)) {
            $issues[] = 'Invalid cover manager email';
        }
        if ($email_name === '') {
            $issues[] = 'Missing email name';
        }
        $issues[] = $reason;
        $issues = array_values(array_unique(array_filter(array_map('sanitize_text_field', $issues))));

        update_post_meta($post_id, 'cmn_location', sanitize_text_field($location));
        update_post_meta($post_id, 'cmn_phone', sanitize_text_field($phone));
        update_post_meta($post_id, 'cmn_cover_manager', sanitize_text_field($cover_manager_name));
        update_post_meta($post_id, 'cmn_cover_manager_email', sanitize_email($cover_manager_email));
        update_post_meta($post_id, 'cmn_email', sanitize_email($school_email));
        update_post_meta($post_id, 'cmn_email_name', sanitize_text_field($email_name));
        update_post_meta($post_id, 'cmn_school_id', sanitize_text_field($school_code));
        update_post_meta($post_id, 'cmn_postcode', sanitize_text_field($postcode));
        update_post_meta($post_id, 'cmn_status', 'needs_attention');
        update_post_meta($post_id, 'cmn_pipeline_stage', 'new_lead');
        update_post_meta($post_id, 'cmn_import_batch_id', sanitize_text_field((string) ($job['batch_id'] ?? '')));
        update_post_meta($post_id, 'cmn_bulk_import_key', sanitize_text_field((string) ($job['job_id'] ?? '')) . ':' . $row_index);
        if ($identity_key !== '') {
            update_post_meta($post_id, 'cmn_import_identity_key', $identity_key);
        }
        if ($school_domain !== '') {
            update_post_meta($post_id, 'cmn_school_email_domain', sanitize_text_field($school_domain));
        }
        update_post_meta($post_id, 'cmn_import_issues', wp_json_encode($issues));
        update_post_meta($post_id, 'cmn_import_source_row', wp_json_encode($this->build_school_import_source_row($header, $row)));
        $this->store_cover_manager_split($post_id, $cover_manager_name);
        $this->upsert_school_index($post_id);
        $this->assert_imported_school_not_application_without_submission((int) $post_id, 'bulk_import_skip');

        return [
            'row_index' => $row_index,
            'school_name' => $school_name,
            'status' => 'needs_attention',
            'message' => implode('; ', $issues),
            'issues' => $issues,
            'school_id' => (int) $post_id,
            'created' => $created_new ? 1 : 0,
            'updated' => $created_new ? 0 : 1,
        ];
    }

    private function run_school_import_job_chunk(&$job, $limit = 10, $options = []) {
        if (!is_array($job)) {
            return [
                'processed' => 0,
                'processed_this_chunk' => 0,
                'row_results' => [],
                'next_offset' => 0,
                'offset_next' => 0,
                'done' => true,
            ];
        }
        $options = is_array($options) ? $options : [];
        $rows = (array) ($job['rows'] ?? []);
        $header = (array) ($job['header'] ?? []);
        $map = (array) ($job['map'] ?? []);
        $offset = max(0, (int) ($job['offset'] ?? 0));
        $total_rows = (int) ($job['total_rows'] ?? count($rows));
        $requested_offset = isset($options['offset']) ? max(0, (int) $options['offset']) : -1;
        if ($requested_offset > $offset && $requested_offset < $total_rows) {
            $offset = $requested_offset;
            $job['offset'] = $offset;
        }
        $limit = max(1, min(20, (int) $limit));
        $target_end = min($offset + $limit, $total_rows);
        $processed_end = $offset;

        $row_results = [];
        for ($i = $offset; $i < $target_end; $i++) {
            $row = (array) ($rows[$i] ?? []);
            try {
                $result = $this->process_school_import_row($row, $map, $header, $job, $i);
            } catch (Throwable $e) {
                $school_name = isset($row[(int) ($map['cmn_school_name'] ?? -1)]) ? trim((string) $row[(int) ($map['cmn_school_name'] ?? -1)]) : '';
                $result = [
                    'row_index' => $i + 1,
                    'school_name' => $school_name,
                    'status' => 'needs_attention',
                    'message' => 'Row processing error: ' . $e->getMessage(),
                    'issues' => ['Row processing error'],
                    'school_id' => 0,
                    'created' => 0,
                    'updated' => 0,
                ];
            }

            $row_results[] = $result;
            $this->append_school_import_job_row_result($job, $i, $result);
            $processed_end = $i + 1;
        }

        $job['offset'] = $processed_end;
        $job['updated_at'] = time();
        $done = ($processed_end >= $total_rows);
        if ($done) {
            $job['done'] = true;
            $job['completed_at'] = current_time('mysql');
        }

        $group_size = max(1, (int) ($job['group_size'] ?? 10));
        $group_index = $processed_end > 0 ? (int) ceil($processed_end / $group_size) : 1;
        $groups_total = max(1, (int) ($job['groups_total'] ?? ($total_rows > 0 ? ceil($total_rows / $group_size) : 1)));
        $group_start = (($group_index - 1) * $group_size) + 1;
        $group_end = min($group_start + $group_size - 1, max(1, $total_rows));
        $processed_in_group = $processed_end > 0 ? (($processed_end - 1) % $group_size) + 1 : 0;
        $group_progress = (int) round(($processed_in_group / max(1, min($group_size, ($group_end - $group_start + 1)))) * 100);
        $overall_progress = (int) round(($processed_end / max(1, $total_rows)) * 100);
        $errors = $this->build_school_import_row_errors($row_results);
        $processed_this_chunk = count($row_results);

        return [
            'processed' => $processed_this_chunk,
            'processed_this_chunk' => $processed_this_chunk,
            'row_results' => $row_results,
            'next_offset' => $processed_end,
            'offset_next' => $processed_end,
            'done' => $done,
            'group' => [
                'index' => $group_index,
                'total' => $groups_total,
                'start' => $group_start,
                'end' => $group_end,
                'progress_pct' => $group_progress,
            ],
            'overall_progress_pct' => $overall_progress,
            'totals' => [
                'total' => (int) $total_rows,
                'imported_ok' => (int) ($job['counts']['imported_ok'] ?? 0),
                'needs_attention' => (int) ($job['counts']['needs_attention'] ?? 0),
                'hard_invalid' => (int) ($job['counts']['hard_invalid'] ?? 0),
                'created' => (int) ($job['counts']['created'] ?? 0),
                'updated' => (int) ($job['counts']['updated'] ?? 0),
                'processed' => (int) ($job['counts']['processed'] ?? 0),
            ],
            'last_processed' => $job['last_processed'],
            'groups_total' => (int) ($job['groups_total'] ?? 0),
            'group_size' => $group_size,
            'total_rows' => (int) $total_rows,
            'valid_count' => (int) ($job['counts']['imported_ok'] ?? 0),
            'needs_attention_count' => (int) ($job['counts']['needs_attention'] ?? 0),
            'hard_invalid_count' => (int) ($job['counts']['hard_invalid'] ?? 0),
            'errors' => $errors,
            'target_rows_this_chunk' => max(0, $target_end - $offset),
            'requested_offset' => $requested_offset >= 0 ? $requested_offset : $offset,
            'applied_offset' => $offset,
        ];
    }

    public function handle_bulk_import_schools_run() {
        if (!$this->is_staff_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if (!check_ajax_referer('cmn_bulk_import_schools_run', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        $job_id = sanitize_key((string) ($_POST['job_id'] ?? ''));
        $limit = max(1, min(20, (int) ($_POST['limit'] ?? 10)));
        $requested_offset = isset($_POST['offset']) ? max(0, (int) $_POST['offset']) : -1;
        $skip_current = !empty($_POST['skip_current']) && (string) $_POST['skip_current'] !== '0';
        $skip_reason = sanitize_text_field((string) ($_POST['skip_reason'] ?? ''));
        $job = $this->get_school_import_job($job_id);
        if (!$job || !is_array($job)) {
            wp_send_json_error(['message' => 'Import job expired. Please restart import.'], 404);
        }
        if ((int) ($job['user_id'] ?? 0) !== (int) get_current_user_id()) {
            wp_send_json_error(['message' => 'This import job belongs to another user.'], 403);
        }

        $t0 = microtime(true);
        if (!empty($job['done'])) {
            $totals = (array) ($job['counts'] ?? []);
            wp_send_json_success([
                'job_id' => $job_id,
                'processed' => 0,
                'processed_this_chunk' => 0,
                'next_offset' => (int) ($job['offset'] ?? 0),
                'offset_next' => (int) ($job['offset'] ?? 0),
                'done' => true,
                'totals' => [
                    'total' => (int) ($job['total_rows'] ?? 0),
                    'imported_ok' => (int) ($totals['imported_ok'] ?? 0),
                    'needs_attention' => (int) ($totals['needs_attention'] ?? 0),
                    'hard_invalid' => (int) ($totals['hard_invalid'] ?? 0),
                    'created' => (int) ($totals['created'] ?? 0),
                    'updated' => (int) ($totals['updated'] ?? 0),
                    'processed' => (int) ($totals['processed'] ?? 0),
                ],
                'last_processed' => $job['last_processed'] ?? null,
                'groups_total' => (int) ($job['groups_total'] ?? 0),
                'group_size' => (int) ($job['group_size'] ?? 10),
                'overall_progress_pct' => 100,
                'total_rows' => (int) ($job['total_rows'] ?? 0),
                'valid_count' => (int) ($totals['imported_ok'] ?? 0),
                'needs_attention_count' => (int) ($totals['needs_attention'] ?? 0),
                'hard_invalid_count' => (int) ($totals['hard_invalid'] ?? 0),
                'errors' => [],
                'requested_offset' => $requested_offset,
                'applied_offset' => (int) ($job['offset'] ?? 0),
            ]);
        }

        $total_rows = (int) ($job['total_rows'] ?? 0);
        if ($requested_offset >= 0 && $requested_offset > (int) ($job['offset'] ?? 0) && $requested_offset < $total_rows) {
            $job['offset'] = $requested_offset;
        }
        $offset_before = (int) ($job['offset'] ?? 0);

        if ($skip_current && $offset_before < $total_rows) {
            if ($skip_reason === '') {
                $skip_reason = 'Skipped after repeated timeout';
            }
            $skipped_result = $this->mark_school_import_row_skipped($job, $offset_before, $skip_reason);
            $this->append_school_import_job_row_result($job, $offset_before, $skipped_result);
            $job['offset'] = $offset_before + 1;
            $job['updated_at'] = time();
            if ($job['offset'] >= $total_rows) {
                $job['done'] = true;
                $job['completed_at'] = current_time('mysql');
            }
            $row_results = [$skipped_result];
            $group_size = max(1, (int) ($job['group_size'] ?? 10));
            $offset_after_skip = (int) ($job['offset'] ?? 0);
            $group_index = $offset_after_skip > 0 ? (int) ceil($offset_after_skip / $group_size) : 1;
            $groups_total = max(1, (int) ($job['groups_total'] ?? ($total_rows > 0 ? ceil($total_rows / $group_size) : 1)));
            $group_start = (($group_index - 1) * $group_size) + 1;
            $group_end = min($group_start + $group_size - 1, max(1, $total_rows));
            $processed_in_group = $offset_after_skip > 0 ? (($offset_after_skip - 1) % $group_size) + 1 : 0;
            $group_progress = (int) round(($processed_in_group / max(1, min($group_size, ($group_end - $group_start + 1)))) * 100);
            $overall_progress = (int) round(($offset_after_skip / max(1, $total_rows)) * 100);
            $chunk = [
                'processed' => 1,
                'processed_this_chunk' => 1,
                'row_results' => $row_results,
                'next_offset' => $offset_after_skip,
                'offset_next' => $offset_after_skip,
                'done' => !empty($job['done']),
                'group' => [
                    'index' => $group_index,
                    'total' => $groups_total,
                    'start' => $group_start,
                    'end' => $group_end,
                    'progress_pct' => $group_progress,
                ],
                'overall_progress_pct' => $overall_progress,
                'totals' => [
                    'total' => (int) $total_rows,
                    'imported_ok' => (int) (($job['counts'] ?? [])['imported_ok'] ?? 0),
                    'needs_attention' => (int) (($job['counts'] ?? [])['needs_attention'] ?? 0),
                    'hard_invalid' => (int) (($job['counts'] ?? [])['hard_invalid'] ?? 0),
                    'created' => (int) (($job['counts'] ?? [])['created'] ?? 0),
                    'updated' => (int) (($job['counts'] ?? [])['updated'] ?? 0),
                    'processed' => (int) (($job['counts'] ?? [])['processed'] ?? 0),
                ],
                'last_processed' => $job['last_processed'] ?? null,
                'groups_total' => (int) ($job['groups_total'] ?? 0),
                'group_size' => $group_size,
                'total_rows' => (int) $total_rows,
                'valid_count' => (int) (($job['counts'] ?? [])['imported_ok'] ?? 0),
                'needs_attention_count' => (int) (($job['counts'] ?? [])['needs_attention'] ?? 0),
                'hard_invalid_count' => (int) (($job['counts'] ?? [])['hard_invalid'] ?? 0),
                'errors' => $this->build_school_import_row_errors($row_results),
                'target_rows_this_chunk' => 1,
                'requested_offset' => $requested_offset >= 0 ? $requested_offset : $offset_before,
                'applied_offset' => $offset_before,
            ];
            error_log('[CMN_IMPORT_JOB] job=' . $job_id . ' skip_current=1 offset=' . $offset_before . ' next_offset=' . $offset_after_skip . ' reason=' . $skip_reason);
        } else {
            error_log('[CMN_IMPORT_JOB] job=' . $job_id . ' start_offset=' . $offset_before . ' requested_offset=' . $requested_offset . ' limit=' . $limit . ' skip_current=0');
            $chunk = $this->run_school_import_job_chunk($job, $limit, [
                'offset' => $requested_offset,
            ]);
        }

        $this->save_school_import_job($job_id, $job);

        $duration_ms = (int) round((microtime(true) - $t0) * 1000);
        error_log('[CMN_IMPORT_JOB] job=' . $job_id . ' offset=' . (int) ($chunk['next_offset'] ?? 0) . '/' . (int) ($job['total_rows'] ?? 0) . ' processed=' . (int) ($chunk['processed'] ?? 0) . ' duration_ms=' . $duration_ms . ' done=' . (!empty($chunk['done']) ? '1' : '0'));

        wp_send_json_success(array_merge($chunk, [
            'job_id' => $job_id,
            'duration_ms' => $duration_ms,
        ]));
    }

    public function handle_school_import_errors_csv() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        $nonce = sanitize_text_field((string) ($_GET['cmn_nonce'] ?? ''));
        if (!wp_verify_nonce($nonce, 'cmn_school_import_errors_csv')) {
            wp_die('Invalid request');
        }
        $job_id = sanitize_key((string) ($_GET['job_id'] ?? ''));
        $job = $this->get_school_import_job($job_id);
        if (!$job || !is_array($job) || (int) ($job['user_id'] ?? 0) !== (int) get_current_user_id()) {
            wp_die('Import job not found.');
        }

        $filename = 'cmn-school-import-errors-' . gmdate('Ymd-His') . '.csv';
        nocache_headers();
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=' . $filename);
        $out = fopen('php://output', 'w');
        if (!$out) {
            wp_die('Could not open output stream.');
        }
        fputcsv($out, ['Row', 'School Name', 'Status', 'Issues', 'Message']);
        foreach ((array) ($job['results'] ?? []) as $result) {
            $status = sanitize_key((string) ($result['status'] ?? ''));
            if (!in_array($status, ['needs_attention', 'hard_invalid'], true)) {
                continue;
            }
            $issues = (array) ($result['issues'] ?? []);
            fputcsv($out, [
                (int) ($result['row_index'] ?? 0),
                sanitize_text_field((string) ($result['school_name'] ?? '')),
                $status,
                implode('; ', array_map('sanitize_text_field', $issues)),
                sanitize_text_field((string) ($result['message'] ?? '')),
            ]);
        }
        fclose($out);
        exit;
    }

    public function handle_import_schools_portal() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_import_schools_nonce']) || !wp_verify_nonce($_POST['cmn_import_schools_nonce'], 'cmn_import_schools')) {
            wp_die('Invalid request');
        }
        $referer = wp_get_referer() ?: home_url('/portal');
        $step = sanitize_text_field($_POST['cmn_import_step'] ?? '');

        if ($step === 'upload') {
            $pasted_csv = isset($_POST['cmn_csv_paste']) ? trim((string) wp_unslash($_POST['cmn_csv_paste'])) : '';
            $has_file_upload = !empty($_FILES['cmn_csv']['name']);
            $upload_file = '';
            $ext = '';
            $rows = [];

            if (!$has_file_upload && $pasted_csv === '') {
                wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Upload a file or paste CSV rows to continue.')], $referer));
                exit;
            }

            if ($has_file_upload) {
                $ext = strtolower(pathinfo((string) $_FILES['cmn_csv']['name'], PATHINFO_EXTENSION));
                if ($ext === 'xls') {
                    wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Please upload an .xlsx or .csv file. Save .xls as .xlsx first.')], $referer));
                    exit;
                }
                if (!in_array($ext, ['csv', 'xlsx'], true)) {
                    wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Please upload a .csv or .xlsx file.')], $referer));
                    exit;
                }
                if (!function_exists('wp_handle_upload')) {
                    require_once ABSPATH . 'wp-admin/includes/file.php';
                }
                $upload = wp_handle_upload($_FILES['cmn_csv'], ['test_form' => false]);
                if (isset($upload['error'])) {
                    wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode($upload['error'])], $referer));
                    exit;
                }
                $upload_file = (string) ($upload['file'] ?? '');
                $rows = $this->read_spreadsheet_rows($upload_file, $ext);
            } else {
                $rows = $this->parse_pasted_csv_rows($pasted_csv);
                $ext = 'csv';
                if ($rows) {
                    $tmp_file = wp_tempnam('cmn-school-import-paste.csv');
                    if (is_string($tmp_file) && $tmp_file !== '') {
                        $out = fopen($tmp_file, 'w');
                        if ($out) {
                            foreach ($rows as $csv_row) {
                                fputcsv($out, (array) $csv_row);
                            }
                            fclose($out);
                            $upload_file = $tmp_file;
                        } else {
                            wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Unable to process pasted CSV data.')], $referer));
                            exit;
                        }
                    }
                }
            }

            if (!$rows) {
                wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Unable to read spreadsheet rows. Check your CSV/file format.')], $referer));
                exit;
            }
            if ($upload_file === '' || !file_exists($upload_file)) {
                wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Import source could not be prepared. Please retry.')], $referer));
                exit;
            }
            $header = $rows[0] ?? [];
            $headers = array_map('trim', array_map('strval', (array) $header));
            if (!$headers) {
                wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Unable to read CSV headers.')], $referer));
                exit;
            }
            $preview_rows = array_slice($rows, 1, 10);
            $total_rows = max(0, count($rows) - 1);
            $token = wp_generate_password(12, false, false);
            set_transient('cmn_import_' . $token, [
                'user_id' => get_current_user_id(),
                'file' => $upload_file,
                'headers' => $headers,
                'ext' => $ext,
                'preview_rows' => $preview_rows,
                'total_rows' => $total_rows,
            ], HOUR_IN_SECONDS);
            wp_redirect(add_query_arg(['view' => 'schools', 'cmn_import_token' => $token], $referer));
            exit;
        }

        if ($step === 'map') {
            $token = sanitize_text_field($_POST['cmn_import_token'] ?? '');
            $data = $token ? get_transient('cmn_import_' . $token) : null;
            if (!$data || (int) ($data['user_id'] ?? 0) !== get_current_user_id()) {
                wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Import session expired. Please upload the file again.')], $referer));
                exit;
            }
            $map = $_POST['cmn_map'] ?? [];
            if (!is_array($map)) {
                wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Invalid mapping data.')], $referer));
                exit;
            }
            $required = ['cmn_school_name'];
            foreach ($required as $key) {
                if (!isset($map[$key]) || $map[$key] === '') {
                    wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Please map School Name before importing.')], $referer));
                    exit;
                }
            }
            $ext = $data['ext'] ?? 'csv';
            $job = $this->create_school_import_job($data['file'], $map, $ext, (int) get_current_user_id());
            delete_transient('cmn_import_' . $token);
            if (is_string($data['file']) && file_exists($data['file'])) {
                @unlink($data['file']);
            }
            if (is_wp_error($job)) {
                wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode($job->get_error_message())], $referer));
                exit;
            }
            $job_id = sanitize_key((string) ($job['job_id'] ?? ''));
            $start_msg = sprintf(
                'Import job started. %s rows in %s groups (10 rows per group).',
                number_format_i18n((int) ($job['total_rows'] ?? 0)),
                number_format_i18n((int) ($job['groups_total'] ?? 0))
            );
            wp_redirect(add_query_arg([
                'view' => 'schools',
                'cmn_imported' => '1',
                'cmn_import_msg' => rawurlencode($start_msg),
                'cmn_import_job' => $job_id,
            ], $referer));
            exit;
        }

        wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Invalid import request.')], $referer));
        exit;
    }

    public function handle_add_school_portal() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_add_school_nonce']) || !wp_verify_nonce($_POST['cmn_add_school_nonce'], 'cmn_add_school')) {
            wp_die('Invalid request');
        }
        $school_name = sanitize_text_field($_POST['cmn_school_name'] ?? '');
        $location = sanitize_text_field($_POST['cmn_location'] ?? '');
        $phone = sanitize_text_field($_POST['cmn_phone'] ?? '');
        $school_email_input = sanitize_email($_POST['cmn_email'] ?? '');
        $cover_manager_name = sanitize_text_field($_POST['cmn_cover_manager'] ?? '');
        $cover_manager_email = sanitize_email($_POST['cmn_cover_manager_email'] ?? '');
        $email = $cover_manager_email !== '' ? $cover_manager_email : $school_email_input;
        $email_name = sanitize_text_field($_POST['cmn_email_name'] ?? '');
        if ($school_name === '' || $location === '' || $phone === '') {
            $this->redirect_with_message('Missing required fields. Please add School Name, Location, and Contact Number.');
        }
        if ($cover_manager_name === '' || $cover_manager_email === '' || $email_name === '') {
            $this->redirect_with_message('Cover Manager Name, Cover Manager Email, and Email Name are required.');
        }
        if ($cover_manager_email === '' || !is_email($cover_manager_email)) {
            $this->redirect_with_message('Please enter a valid Cover Manager Email.');
        }
        if ($email === '' || !is_email($email)) {
            $this->redirect_with_message('Please enter a valid School Email.');
        }
        if (strlen(preg_replace('/\\D+/', '', $phone)) < 7) {
            $this->redirect_with_message('Please enter a valid Contact Number.');
        }
        $school_domain = $this->get_email_domain($email);
        if ($school_domain === '') {
            $this->redirect_with_message('Please enter a valid School Email.');
        }

        $existing_id = $this->get_school_post_id_by_domain($school_domain);
        if ($existing_id) {
            $post_id = $existing_id;
            wp_update_post([
                'ID' => $post_id,
                'post_title' => $school_name,
            ]);
        } else {
            $post_id = wp_insert_post([
                'post_type' => 'cmn_school',
                'post_title' => $school_name,
                'post_status' => 'publish',
            ]);
        }

        if (!is_wp_error($post_id)) {
            update_post_meta($post_id, 'cmn_location', $location);
            update_post_meta($post_id, 'cmn_phone', $phone);
            $cover_manager_name = sanitize_text_field($_POST['cmn_cover_manager'] ?? '');
            $cover_manager_email = sanitize_email($_POST['cmn_cover_manager_email'] ?? '');
            update_post_meta($post_id, 'cmn_cover_manager', $cover_manager_name);
            update_post_meta($post_id, 'cmn_cover_manager_email', $cover_manager_email);
            $this->store_cover_manager_split($post_id, $cover_manager_name);
            update_post_meta($post_id, 'cmn_account_manager', sanitize_text_field($_POST['cmn_account_manager'] ?? ''));
            update_post_meta($post_id, 'cmn_email', $email);
            update_post_meta($post_id, 'cmn_email_name', sanitize_text_field($_POST['cmn_email_name'] ?? ''));
            update_post_meta($post_id, 'cmn_spoke_to_cm', sanitize_text_field($_POST['cmn_spoke_to_cm'] ?? ''));
            update_post_meta($post_id, 'cmn_switchboard', sanitize_text_field($_POST['cmn_switchboard'] ?? ''));
            update_post_meta($post_id, 'cmn_website', esc_url_raw($_POST['cmn_website'] ?? ''));
            if (!get_post_meta($post_id, 'cmn_school_id', true)) {
                update_post_meta($post_id, 'cmn_school_id', $this->generate_school_id());
            }
            $existing_status = sanitize_key((string) get_post_meta($post_id, 'cmn_status', true));
            $status_to_apply = ($existing_id && $existing_status === 'client') ? 'client' : 'lead';
            update_post_meta($post_id, 'cmn_status', $status_to_apply);
            update_post_meta($post_id, 'cmn_pipeline_stage', 'new_lead');
            $school_domain = $this->get_email_domain($email);
            if ($school_domain) {
                update_post_meta($post_id, 'cmn_school_email_domain', $school_domain);
            }

            $contact_name = sanitize_text_field($_POST['cmn_contact_name'] ?? '');
            $contact_email = sanitize_email($_POST['cmn_contact_email'] ?? '');
            $contact_phone = sanitize_text_field($_POST['cmn_contact_phone'] ?? '');
            $contact_role = sanitize_text_field($_POST['cmn_contact_role'] ?? '');
            if ($contact_name !== '') {
                $contact_id = $this->create_or_update_contact([
                    'name' => $contact_name,
                    'email' => $contact_email,
                    'phone' => $contact_phone,
                    'role' => $contact_role,
                    'school_id' => $post_id,
                    'school_domain' => $school_domain,
                    'is_primary' => true,
                ]);
                if ($contact_id) {
                    update_post_meta($post_id, 'cmn_contact1', $contact_name);
                    update_post_meta($post_id, 'cmn_contact1_email', $contact_email);
                    update_post_meta($post_id, 'cmn_contact_role', $contact_role);
                    update_post_meta($post_id, 'cmn_primary_contact_name', $contact_name);
                    update_post_meta($post_id, 'cmn_primary_contact_email', $contact_email ?: $email);
                    update_post_meta($post_id, 'cmn_primary_contact_phone', $contact_phone ?: $phone);
                    update_post_meta($post_id, 'cmn_primary_contact_role', $contact_role);
                }
            }
            $this->upsert_school_index($post_id);
            $this->assert_imported_school_not_application_without_submission((int) $post_id, 'add_school');

            $this->trigger_automation_event('lead_created', 'school', (int) $post_id, [
                'status' => 'lead',
                'pipeline_stage' => 'new_lead',
                'automation_meta' => ['source' => 'school_create'],
            ]);
        }

        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        $school_code = get_post_meta($post_id, 'cmn_school_id', true);
        $redirect = add_query_arg(['view' => 'schools', 'school_id' => $school_code], $portal_url);
        wp_redirect($redirect);
        exit;
    }

    public function handle_add_staff_portal() {
        if (!$this->can_manage_staff_users()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_add_staff_nonce']) || !wp_verify_nonce($_POST['cmn_add_staff_nonce'], 'cmn_add_staff')) {
            wp_die('Invalid request');
        }
        $name = sanitize_text_field($_POST['cmn_staff_name'] ?? '');
        $email = sanitize_email($_POST['cmn_staff_email'] ?? '');
        $username_input = sanitize_text_field($_POST['cmn_staff_username'] ?? '');
        $role = sanitize_text_field($_POST['cmn_staff_role'] ?? 'cmn_staff');
        if ($name === '' || $email === '') {
            wp_die('Name and email are required.');
        }
        if (!in_array($role, ['cmn_staff', 'cmn_account_manager', 'cmn_admin'], true)) {
            $role = 'cmn_staff';
        }
        $existing = get_user_by('email', $email);
        if ($existing) {
            $user = new WP_User($existing->ID);
            $user->set_role($role);
            wp_update_user(['ID' => $existing->ID, 'display_name' => $name]);
        } else {
            $base_username = $username_input !== '' ? $username_input : strstr($email, '@', true);
            $username = $this->generate_unique_username($base_username ?: $email);
            $user_id = wp_insert_user([
                'user_login' => $username,
                'user_email' => $email,
                'display_name' => $name,
                'role' => $role,
                'user_pass' => wp_generate_password(12, false),
            ]);
            if (!is_wp_error($user_id)) {
                $user = get_user_by('id', $user_id);
                if ($user) {
                    update_user_meta($user_id, 'cmn_deactivated', 0);
                    $this->send_staff_welcome_email($user);
                }
            }
        }
        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        wp_redirect(add_query_arg(['view' => 'staff'], $portal_url));
        exit;
    }

    public function handle_add_staff_user_ajax() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!$this->can_manage_staff_users()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $name = sanitize_text_field($_POST['name'] ?? '');
        $email = sanitize_email($_POST['email'] ?? '');
        $username_input = sanitize_text_field($_POST['username'] ?? '');
        $role = sanitize_text_field($_POST['role'] ?? 'cmn_staff');
        if ($name === '' || $email === '') {
            wp_send_json_error(['message' => 'Name and email are required.'], 400);
        }
        if (!in_array($role, ['cmn_staff', 'cmn_account_manager', 'cmn_admin'], true)) {
            $role = 'cmn_staff';
        }
        $existing = get_user_by('email', $email);
        if ($existing) {
            $user = new WP_User($existing->ID);
            $user->set_role($role);
            wp_update_user(['ID' => $existing->ID, 'display_name' => $name]);
            wp_send_json_success([
                'user' => [
                    'id' => $existing->ID,
                    'name' => $name,
                    'username' => $existing->user_login,
                    'email' => $email,
                    'role' => $role,
                    'status' => get_user_meta($existing->ID, 'cmn_deactivated', true) ? 'deactivated' : 'active',
                ],
                'message' => 'Staff updated.',
            ]);
        }
        $base_username = $username_input !== '' ? $username_input : strstr($email, '@', true);
        $username = $this->generate_unique_username($base_username ?: $email);
        $user_id = wp_insert_user([
            'user_login' => $username,
            'user_email' => $email,
            'display_name' => $name,
            'role' => $role,
            'user_pass' => wp_generate_password(12, false),
        ]);
        if (is_wp_error($user_id)) {
            wp_send_json_error(['message' => $user_id->get_error_message()], 400);
        }
        update_user_meta($user_id, 'cmn_deactivated', 0);
        $user = get_user_by('id', $user_id);
        if ($user) {
            $this->send_staff_welcome_email($user);
        }
        wp_send_json_success([
            'user' => [
                'id' => $user_id,
                'name' => $name,
                'username' => $username,
                'email' => $email,
                'role' => $role,
                'status' => 'active',
            ],
            'message' => 'Staff added.',
        ]);
    }

    public function handle_update_staff_user_ajax() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!$this->can_manage_staff_users()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = intval($_POST['user_id'] ?? 0);
        $name = sanitize_text_field($_POST['name'] ?? '');
        $email = sanitize_email($_POST['email'] ?? '');
        $role = sanitize_text_field($_POST['role'] ?? 'cmn_staff');
        if (!$user_id || $name === '' || $email === '') {
            wp_send_json_error(['message' => 'Name and email are required.'], 400);
        }
        if (!in_array($role, ['cmn_staff', 'cmn_account_manager', 'cmn_admin'], true)) {
            $role = 'cmn_staff';
        }
        $existing_email_user = get_user_by('email', $email);
        if ($existing_email_user && (int) $existing_email_user->ID !== $user_id) {
            wp_send_json_error(['message' => 'Email already in use.'], 400);
        }
        $user = get_user_by('id', $user_id);
        if (!$user) {
            wp_send_json_error(['message' => 'User not found.'], 404);
        }
        wp_update_user([
            'ID' => $user_id,
            'user_email' => $email,
            'display_name' => $name,
        ]);
        $user->set_role($role);
        wp_send_json_success([
            'user' => [
                'id' => $user_id,
                'name' => $name,
                'username' => $user->user_login,
                'email' => $email,
                'role' => $role,
                'status' => get_user_meta($user_id, 'cmn_deactivated', true) ? 'deactivated' : 'active',
            ],
            'message' => 'Staff updated.',
        ]);
    }

    public function handle_send_staff_reset_password_ajax() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!$this->can_manage_staff_users()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = intval($_POST['user_id'] ?? 0);
        if (!$user_id) {
            wp_send_json_error(['message' => 'User not found.'], 404);
        }
        $user = get_user_by('id', $user_id);
        if (!$user) {
            wp_send_json_error(['message' => 'User not found.'], 404);
        }
        $sent = $this->send_staff_reset_email($user);
        if (!$sent) {
            wp_send_json_error(['message' => 'Unable to send reset email.'], 500);
        }
        wp_send_json_success(['message' => 'Reset email sent.']);
    }

    public function handle_toggle_staff_deactivated_ajax() {
        if (!check_ajax_referer('cmn_staff_manage', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!$this->can_manage_staff_users()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = intval($_POST['user_id'] ?? 0);
        if (!$user_id) {
            wp_send_json_error(['message' => 'User not found.'], 404);
        }
        if ($this->is_super_admin_user_id($user_id)) {
            wp_send_json_error(['message' => 'Cannot deactivate the super admin.'], 403);
        }
        $current = get_user_meta($user_id, 'cmn_deactivated', true) ? 1 : 0;
        $new_value = $current ? 0 : 1;
        update_user_meta($user_id, 'cmn_deactivated', $new_value);
        wp_send_json_success([
            'status' => $new_value ? 'deactivated' : 'active',
            'message' => $new_value ? 'User deactivated.' : 'User reactivated.',
        ]);
    }

    public function block_deactivated_staff_login($user, $username, $password) {
        if ($user instanceof WP_User) {
            $deactivated = get_user_meta($user->ID, 'cmn_deactivated', true);
            if ($deactivated) {
                return new WP_Error('cmn_deactivated', 'Your account has been deactivated.');
            }
        }
        return $user;
    }

    public function handle_portal_login() {
        if (!isset($_POST['cmn_portal_login_nonce']) || !wp_verify_nonce($_POST['cmn_portal_login_nonce'], 'cmn_portal_login')) {
            $this->portal_safe_redirect(add_query_arg(['view' => 'login', 'cmn_error' => rawurlencode('Invalid request.')], $this->get_portal_base_url()));
        }
        $creds = [
            'user_login' => sanitize_text_field($_POST['log'] ?? ''),
            'user_password' => sanitize_text_field($_POST['pwd'] ?? ''),
            'remember' => !empty($_POST['rememberme']),
        ];
        $user = wp_signon($creds, false);
        if (is_wp_error($user)) {
            $this->portal_safe_redirect(add_query_arg(['view' => 'login', 'cmn_error' => rawurlencode($user->get_error_message())], $this->get_portal_base_url()));
        }
        $redirect_to = esc_url_raw((string) ($_POST['redirect_to'] ?? ''));
        if ($redirect_to !== '') {
            $base = trailingslashit($this->get_portal_base_url());
            $normalized = trailingslashit(preg_replace('/\?.*/', '', $redirect_to));
            if (strpos($normalized, $base) === 0 || strpos($redirect_to, $this->get_portal_base_url()) === 0) {
                $this->portal_safe_redirect($redirect_to);
            }
        }
        $redirect = $this->handle_login_redirect($this->get_portal_base_url(), $this->get_portal_base_url(), $user);
        $this->portal_safe_redirect($redirect);
    }

    public function handle_portal_logout() {
        $nonce = isset($_REQUEST['_wpnonce']) ? sanitize_text_field((string) wp_unslash($_REQUEST['_wpnonce'])) : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, 'cmn_portal_logout')) {
            $this->portal_safe_redirect($this->get_portal_login_url());
        }

        $default_redirect = $this->get_portal_login_url();
        $redirect_to = isset($_REQUEST['redirect_to']) ? (string) wp_unslash($_REQUEST['redirect_to']) : '';
        $redirect_to = wp_validate_redirect($redirect_to, $default_redirect);

        wp_logout();
        $this->portal_safe_redirect($redirect_to);
    }

    public function handle_portal_login_fallback_admin_post() {
        $action_raw = isset($_REQUEST['action']) ? sanitize_text_field((string) $_REQUEST['action']) : '';
        if ($action_raw !== '') {
            return;
        }
        $looks_like_portal_login = isset($_POST['cmn_portal_login_nonce']) || isset($_POST['log']) || isset($_POST['pwd']);
        if (!$looks_like_portal_login) {
            return;
        }
        $_POST['action'] = 'cmn_portal_login';
        $this->handle_portal_login();
    }

    public function handle_portal_forgot_password() {
        if (!isset($_POST['cmn_portal_forgot_password_nonce']) || !wp_verify_nonce($_POST['cmn_portal_forgot_password_nonce'], 'cmn_portal_forgot_password')) {
            wp_redirect(add_query_arg(['view' => 'forgot-password', 'cmn_error' => rawurlencode('Invalid request.')], $this->get_portal_base_url()));
            exit;
        }
        $user_login = sanitize_text_field($_POST['user_login'] ?? '');
        if ($user_login === '') {
            wp_redirect(add_query_arg(['view' => 'forgot-password', 'cmn_error' => rawurlencode('Enter your email or username.')], $this->get_portal_base_url()));
            exit;
        }
        $result = retrieve_password($user_login);
        if (is_wp_error($result)) {
            wp_redirect(add_query_arg(['view' => 'forgot-password', 'cmn_error' => rawurlencode($result->get_error_message())], $this->get_portal_base_url()));
            exit;
        }
        wp_redirect(add_query_arg(['view' => 'forgot-password', 'cmn_notice' => rawurlencode('Reset link sent. Check your email.')], $this->get_portal_base_url()));
        exit;
    }

    public function handle_portal_reset_password() {
        if (!isset($_POST['cmn_portal_reset_password_nonce']) || !wp_verify_nonce($_POST['cmn_portal_reset_password_nonce'], 'cmn_portal_reset_password')) {
            wp_redirect(add_query_arg(['view' => 'set-password', 'cmn_error' => rawurlencode('Invalid request.')], $this->get_portal_base_url()));
            exit;
        }
        $login = sanitize_text_field($_POST['login'] ?? '');
        $key = sanitize_text_field($_POST['key'] ?? '');
        $pass1 = sanitize_text_field($_POST['pass1'] ?? '');
        $pass2 = sanitize_text_field($_POST['pass2'] ?? '');
        $reset_url = $this->get_portal_reset_url($login, $key);
        if (!$login || !$key) {
            $reset_url = add_query_arg(['view' => 'set-password'], $this->get_portal_base_url());
        }
        if ($pass1 === '' || $pass2 === '' || $pass1 !== $pass2) {
            wp_redirect(add_query_arg(['cmn_error' => rawurlencode('Passwords do not match.')], $reset_url));
            exit;
        }
        if (strlen($pass1) < 10) {
            wp_redirect(add_query_arg(['cmn_error' => rawurlencode('Password must be at least 10 characters.')], $reset_url));
            exit;
        }
        $user = check_password_reset_key($key, $login);
        if (is_wp_error($user)) {
            wp_redirect(add_query_arg(['cmn_error' => rawurlencode($user->get_error_message())], $reset_url));
            exit;
        }
        reset_password($user, $pass1);
        wp_logout();
        $redirect = add_query_arg([
            'view' => 'login',
            'cmn_notice' => rawurlencode('Password set - you can now log in.'),
        ], $this->get_portal_base_url());
        wp_redirect($redirect);
        exit;
    }

    /*
     * Prompt 33 acceptance tests:
     * 1) Candidate can submit payroll query ticket with period, issue type, and optional booking days.
     * 2) Non-candidates are denied.
     * 3) Rate limit enforces max 2 submissions per 24 hours.
     * 4) Structured payroll metadata is written for retrieval without post meta usage.
     */
    public function handle_candidate_submit_payroll_query() {
        $send_error = static function ($code, $message, $status = 400) {
            $error = new WP_Error((string) $code, (string) $message, ['status' => (int) $status]);
            if (function_exists('cmn_json_error')) {
                cmn_json_error($error);
            }
            wp_send_json_error([
                'ok' => false,
                'error' => [
                    'code' => (string) $code,
                    'message' => (string) $message,
                ],
            ], (int) $status);
        };

        if (!is_user_logged_in()) {
            $send_error('cmn_auth_required', 'Unauthorized.', 401);
        }

        $candidate_user_id = (int) get_current_user_id();
        if ($candidate_user_id < 1 || !$this->is_candidate_user($candidate_user_id)) {
            $send_error('cmn_not_authorized', 'Unauthorized.', 403);
        }

        if (function_exists('cmn_require_ability')) {
            $ability_check = cmn_require_ability('finance.view_self', ['candidate_user_id' => $candidate_user_id]);
            if (is_wp_error($ability_check)) {
                $send_error('cmn_not_authorized', 'Unauthorized.', 403);
            }
        }

        if (function_exists('cmn_require_nonce')) {
            $nonce_check = cmn_require_nonce('cmn_candidate_payroll_query_submit', 'nonce');
            if (is_wp_error($nonce_check)) {
                $send_error('cmn_invalid_nonce', 'Invalid request.', 403);
            }
        } elseif (!check_ajax_referer('cmn_candidate_payroll_query_submit', 'nonce', false)) {
            $send_error('cmn_invalid_nonce', 'Invalid request.', 403);
        }

        $period_id = sanitize_text_field((string) wp_unslash($_POST['period_id'] ?? ''));
        $issue_type_raw = sanitize_key((string) wp_unslash($_POST['issue_type'] ?? ''));
        $message = sanitize_textarea_field((string) wp_unslash($_POST['message'] ?? ''));
        $message = trim($message);
        if ($period_id === '') {
            $send_error('cmn_payroll_query_period_required', 'Pay period is required.', 400);
        }
        if ($message === '' || strlen($message) < 10) {
            $send_error('cmn_payroll_query_message_invalid', 'Message must be at least 10 characters.', 400);
        }

        $issue_type_map = $this->get_candidate_payroll_query_issue_type_map();
        if (!isset($issue_type_map[$issue_type_raw])) {
            $send_error('cmn_payroll_query_issue_type_invalid', 'Issue type is invalid.', 400);
        }
        $issue_type = $issue_type_raw;
        $issue_type_label = (string) ($issue_type_map[$issue_type] ?? 'Other');

        $period_options = $this->get_candidate_payroll_query_period_options(5);
        $period_map = [];
        foreach ($period_options as $period_row) {
            if (!is_array($period_row)) {
                continue;
            }
            $row_period_id = sanitize_text_field((string) ($period_row['period_id'] ?? ''));
            if ($row_period_id === '') {
                continue;
            }
            $period_map[$row_period_id] = $period_row;
        }
        if (!isset($period_map[$period_id]) || !is_array($period_map[$period_id])) {
            $send_error('cmn_payroll_query_period_invalid', 'Selected pay period is not available for payroll queries.', 400);
        }
        $period = (array) $period_map[$period_id];
        $period_start = $this->normalize_invoice_date((string) ($period['period_start'] ?? ''));
        $period_end = $this->normalize_invoice_date((string) ($period['period_end'] ?? ''));
        $pay_date = $this->normalize_invoice_date((string) ($period['pay_date'] ?? ''));
        $period_label = sanitize_text_field((string) ($period['label'] ?? $period_id));

        $rate_limit_check = $this->assert_candidate_payroll_query_rate_limit($candidate_user_id, 2, DAY_IN_SECONDS);
        if (is_wp_error($rate_limit_check)) {
            $send_error(
                (string) $rate_limit_check->get_error_code(),
                (string) $rate_limit_check->get_error_message(),
                (int) ((is_array($rate_limit_check->get_error_data()) && isset($rate_limit_check->get_error_data()['status'])) ? $rate_limit_check->get_error_data()['status'] : 429)
            );
        }

        $available_booking_rows = $this->get_candidate_payroll_query_booking_day_options($candidate_user_id, $period_id);
        $available_booking_map = [];
        foreach ($available_booking_rows as $booking_row) {
            if (!is_array($booking_row)) {
                continue;
            }
            $value = trim((string) ($booking_row['value'] ?? ''));
            if ($value === '') {
                continue;
            }
            $available_booking_map[$value] = $booking_row;
        }

        $selected_booking_refs = isset($_POST['booking_refs']) ? (array) wp_unslash($_POST['booking_refs']) : [];
        $selected_booking_refs = array_values(array_unique(array_filter(array_map(static function ($value) {
            $value = trim((string) $value);
            if ($value === '') {
                return '';
            }
            return substr(sanitize_text_field($value), 0, 64);
        }, $selected_booking_refs))));
        if (count($selected_booking_refs) > 40) {
            $send_error('cmn_payroll_query_booking_refs_invalid', 'Too many booking days selected.', 400);
        }

        $selected_booking_rows = [];
        foreach ($selected_booking_refs as $selected_ref) {
            if (!isset($available_booking_map[$selected_ref]) || !is_array($available_booking_map[$selected_ref])) {
                $send_error('cmn_payroll_query_booking_ref_unauthorized', 'One or more booking day selections are invalid.', 403);
            }
            $booking_row = (array) $available_booking_map[$selected_ref];
            $selected_booking_rows[] = [
                'booking_id' => max(0, (int) ($booking_row['booking_id'] ?? 0)),
                'booking_day_date' => $this->normalize_invoice_date((string) ($booking_row['booking_day_date'] ?? '')),
                'label' => sanitize_text_field((string) ($booking_row['label'] ?? '')),
            ];
        }

        self::migrate_schema_v60_support_payroll_query_metadata();

        $ticket_ref = $this->generate_support_ticket_ref();
        $subject = 'Payroll query - ' . $period_label;
        $subject = substr(sanitize_text_field($subject), 0, 255);
        if ($subject === '') {
            $subject = 'Payroll query - ' . $period_id;
        }

        $body_lines = [
            'Payroll query details',
            'Priority: Normal',
            'Issue type: ' . $issue_type_label,
            'Period ID: ' . $period_id,
            'Period dates: ' . ($period_start !== '' ? $period_start : 'N/A') . ' to ' . ($period_end !== '' ? $period_end : 'N/A'),
            'Pay date: ' . ($pay_date !== '' ? $pay_date : 'N/A'),
        ];
        if ($selected_booking_rows) {
            $body_lines[] = 'Booking days selected:';
            foreach ($selected_booking_rows as $booking_row) {
                $booking_label = sanitize_text_field((string) ($booking_row['label'] ?? ''));
                if ($booking_label === '') {
                    $booking_label = 'Booking #' . (int) ($booking_row['booking_id'] ?? 0) . ' on ' . sanitize_text_field((string) ($booking_row['booking_day_date'] ?? ''));
                }
                $body_lines[] = '- ' . $booking_label;
            }
        } else {
            $body_lines[] = 'Booking days selected: none';
        }
        $body_lines[] = '';
        $body_lines[] = 'Candidate message:';
        $body_lines[] = $message;
        $ticket_message = implode("\n", $body_lines);

        global $wpdb;
        $ticket_table = $this->get_support_ticket_table();
        $message_table = $this->get_support_message_table();
        $now = current_time('mysql');
        $ticket_data = [
            'ticket_ref' => $ticket_ref,
            'created_by_user_id' => $candidate_user_id,
            'user_role_type' => $this->get_support_user_role_type($candidate_user_id),
            'subject' => $subject,
            'category' => 'Payroll',
            'status' => 'new',
            'is_new_for_admin' => 1,
            'created_at' => $now,
            'updated_at' => $now,
            'closed_at' => null,
        ];
        $ticket_formats = ['%s', '%d', '%s', '%s', '%s', '%s', '%d', '%s', '%s', '%s'];
        if ($this->support_ticket_has_column('priority')) {
            $ticket_data['priority'] = 'normal';
            $ticket_formats[] = '%s';
        }

        $inserted_ticket = $wpdb->insert($ticket_table, $ticket_data, $ticket_formats);
        if (!$inserted_ticket) {
            $send_error('cmn_payroll_query_ticket_create_failed', 'Unable to create payroll query ticket.', 500);
        }
        $ticket_id = (int) $wpdb->insert_id;
        if ($ticket_id < 1) {
            $send_error('cmn_payroll_query_ticket_create_failed', 'Unable to create payroll query ticket.', 500);
        }

        $inserted_message = $wpdb->insert(
            $message_table,
            [
                'ticket_id' => $ticket_id,
                'sender_user_id' => $candidate_user_id,
                'sender_type' => 'user',
                'message' => $ticket_message,
                'attachment_ids' => null,
                'created_at' => $now,
            ],
            ['%d', '%d', '%s', '%s', '%s', '%s']
        );
        if (!$inserted_message) {
            $wpdb->delete($ticket_table, ['id' => $ticket_id], ['%d']);
            $send_error('cmn_payroll_query_message_create_failed', 'Unable to create payroll query ticket message.', 500);
        }

        $payout_run = $this->get_payroll_payout_run_by_period_id($period_id);
        $payout_run_id = max(0, (int) ($payout_run['id'] ?? 0));
        $saved_meta = $this->upsert_support_payroll_query_metadata(
            $ticket_id,
            $candidate_user_id,
            [
                'period_id' => $period_id,
                'period_start' => $period_start,
                'period_end' => $period_end,
                'pay_date' => $pay_date,
            ],
            $issue_type,
            $selected_booking_rows,
            $payout_run_id
        );
        if (is_wp_error($saved_meta)) {
            $wpdb->delete($message_table, ['ticket_id' => $ticket_id], ['%d']);
            $wpdb->delete($ticket_table, ['id' => $ticket_id], ['%d']);
            $send_error((string) $saved_meta->get_error_code(), (string) $saved_meta->get_error_message(), 500);
        }

        $this->route_payroll_support_ticket($ticket_id, [
            'actor_user_id' => $candidate_user_id,
            'period_id' => $period_id,
            'period_label' => $period_label,
            'issue_type_label' => $issue_type_label,
            'message_preview_source' => $message,
        ]);

        $this->record_candidate_payroll_query_submission($candidate_user_id, DAY_IN_SECONDS);
        $this->notify_admins_support($ticket_id, $ticket_ref, $subject, $message);

        $subject_line = 'Support ticket received: ' . $ticket_ref;
        $email_body = "Thanks for contacting CoverMeNow ONE.\n\nReference: {$ticket_ref}\nSubject: {$subject}\n\nYou can reply inside your portal. We will update you shortly.";
        $this->send_support_email_to_user($candidate_user_id, $subject_line, $email_body, 'support_ticket_received', [
            'ticket_id' => $ticket_id,
        ]);

        $this->trigger_automation_event('support_ticket_opened', 'support_ticket', (int) $ticket_id, [
            'ticket_ref' => $ticket_ref,
            'subject' => $subject,
            'status' => 'new',
            'category' => 'Payroll',
            'automation_meta' => [
                'source' => 'candidate_payroll_query',
                'period_id' => $period_id,
                'issue_type' => $issue_type,
            ],
        ]);

        if (function_exists('cmn_audit_log_event')) {
            cmn_audit_log_event([
                'module' => 'support',
                'entity_type' => 'ticket',
                'entity_id' => $ticket_id,
                'event_type' => 'payroll_query_ticket_created',
                'actor_user_id' => $candidate_user_id,
                'metadata' => [
                    'candidate_user_id' => $candidate_user_id,
                    'period_id' => $period_id,
                    'issue_type' => $issue_type,
                    'ticket_id' => $ticket_id,
                ],
            ]);
        }

        wp_send_json_success([
            'ok' => true,
            'message' => 'Payroll query submitted.',
            'ticket' => [
                'id' => $ticket_id,
                'ref' => $ticket_ref,
                'subject' => $subject,
                'category' => 'Payroll',
                'priority' => 'normal',
                'period_id' => $period_id,
            ],
            'support_url' => $this->get_support_link_for_user($candidate_user_id, $ticket_id, $ticket_ref),
        ]);
    }

    public function handle_support_create_ticket() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = get_current_user_id();
        $category = sanitize_text_field($_POST['category'] ?? '');
        $subject = sanitize_text_field($_POST['subject'] ?? '');
        $message = sanitize_textarea_field($_POST['message'] ?? '');
        if ($subject === '' || $message === '') {
            wp_send_json_error(['message' => 'Subject and message are required.'], 400);
        }
        $ticket_ref = $this->generate_support_ticket_ref();
        $role_type = $this->get_support_user_role_type($user_id);
        global $wpdb;
        $ticket_table = $this->get_support_ticket_table();
        $message_table = $this->get_support_message_table();
        $now = current_time('mysql');
        $inserted = $wpdb->insert($ticket_table, [
            'ticket_ref' => $ticket_ref,
            'created_by_user_id' => $user_id,
            'user_role_type' => $role_type,
            'subject' => $subject,
            'category' => $category ?: null,
            'status' => 'new',
            'is_new_for_admin' => 1,
            'created_at' => $now,
            'updated_at' => $now,
            'closed_at' => null,
        ], ['%s', '%d', '%s', '%s', '%s', '%s', '%d', '%s', '%s', '%s']);
        if (!$inserted) {
            wp_send_json_error(['message' => 'Unable to create ticket.'], 500);
        }
        $ticket_id = (int) $wpdb->insert_id;
        $uploaded = $this->handle_support_attachments_upload('attachments');
        $attachment_ids = !empty($uploaded['ids']) ? wp_json_encode(array_values(array_unique(array_map('intval', $uploaded['ids'])))) : null;
        $wpdb->insert($message_table, [
            'ticket_id' => $ticket_id,
            'sender_user_id' => $user_id,
            'sender_type' => 'user',
            'message' => $message,
            'attachment_ids' => $attachment_ids,
            'created_at' => $now,
        ], ['%d', '%d', '%s', '%s', '%s', '%s']);

        $this->route_payroll_support_ticket($ticket_id, [
            'actor_user_id' => $user_id,
            'message_preview_source' => $message,
        ]);

        $this->notify_admins_support($ticket_id, $ticket_ref, $subject, $message);

        $subject_line = 'Support ticket received: ' . $ticket_ref;
        $body = "Thanks for contacting CoverMeNow ONE.\n\nReference: {$ticket_ref}\nSubject: {$subject}\n\nYou can reply inside your portal. We will update you shortly.";
        $this->send_support_email_to_user($user_id, $subject_line, $body, 'support_ticket_received', [
            'ticket_id' => $ticket_id,
        ]);

        $this->trigger_automation_event('support_ticket_opened', 'support_ticket', (int) $ticket_id, [
            'ticket_ref' => $ticket_ref,
            'subject' => $subject,
            'status' => 'new',
            'category' => $category,
            'automation_meta' => ['source' => 'support_ticket_create'],
        ]);

        wp_send_json_success([
            'ticket' => [
                'id' => $ticket_id,
                'ref' => $ticket_ref,
                'subject' => $subject,
                'status' => 'new',
                'updated_at' => $now,
                'upload_errors' => $uploaded['errors'],
            ],
        ]);
    }

    public function handle_staff_lounge_fetch() {
        if (!check_ajax_referer('cmn_staff_lounge', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $thread_type = $this->normalize_staff_lounge_thread_type((string) ($_POST['thread_type'] ?? 'staff_lounge'));
        $messages = $this->get_staff_lounge_messages($thread_type, 120);
        wp_send_json_success([
            'thread_type' => $thread_type,
            'messages' => $messages,
        ]);
    }

    public function handle_staff_lounge_post() {
        if (!check_ajax_referer('cmn_staff_lounge', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $thread_type = $this->normalize_staff_lounge_thread_type((string) ($_POST['thread_type'] ?? 'staff_lounge'));
        $message = sanitize_textarea_field((string) ($_POST['message'] ?? ''));
        if ($message === '') {
            wp_send_json_error(['message' => 'Message is required.'], 400);
        }
        $actor_user_id = (int) get_current_user_id();
        $message_id = $this->add_staff_lounge_message($actor_user_id, $message, $thread_type);
        if ($message_id < 1) {
            wp_send_json_error(['message' => 'Unable to send message.'], 500);
        }
        $this->add_audit_log('staff_lounge_message', 'staff_lounge', (string) $message_id, [
            'thread_type' => $thread_type,
        ]);
        $portal_link = add_query_arg(['view' => 'staff-lounge'], $this->get_portal_base_url());
        $sender_user = get_user_by('id', $actor_user_id);
        $sender_name = $sender_user ? trim((string) ($sender_user->display_name ?: $sender_user->user_login)) : 'Staff';
        $snippet = trim(preg_replace('/\\s+/', ' ', wp_strip_all_tags($message)));
        if (strlen($snippet) > 180) {
            $snippet = substr($snippet, 0, 177) . '...';
        }
        $notified_count = 0;
        foreach ($this->get_staff_admin_users_for_cv_notifications() as $notify_user_id) {
            $notify_user_id = (int) $notify_user_id;
            if ($notify_user_id < 1 || $notify_user_id === $actor_user_id) {
                continue;
            }
            $insert_id = $this->add_notification(
                $notify_user_id,
                'staff_lounge_message',
                'Staff room message',
                $sender_name . ': ' . $snippet,
                $portal_link
            );
            if ($insert_id > 0) {
                $notified_count++;
            }
        }

        wp_send_json_success([
            'message' => 'Message sent.',
            'thread_type' => $thread_type,
            'messages' => $this->get_staff_lounge_messages($thread_type, 120),
        ]);
    }

    public function handle_support_list_tickets() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = get_current_user_id();
        $default_status = $this->is_staff_user($user_id) ? 'active' : 'all';
        $status = sanitize_key((string) ($_POST['status'] ?? $default_status));
        if (!in_array($status, ['active', 'new', 'open', 'closed', 'new_open', 'all', 'needs_feedback'], true)) {
            $status = $default_status;
        }
        if (!$this->is_staff_user($user_id) && in_array($status, ['active', 'new', 'new_open'], true)) {
            $status = 'all';
        }
        $ticket_id = (int) ($_POST['ticket_id'] ?? 0);
        $ticket_ref = sanitize_text_field((string) ($_POST['ticket_ref'] ?? ''));
        $debug_mode = (isset($_REQUEST['cmn_debug']) && (string) $_REQUEST['cmn_debug'] === '1' && $this->is_admin_user($user_id));
        global $wpdb;
        $table = $this->get_support_ticket_table();
        $columns = $this->get_support_ticket_columns();
        $this->maybe_expire_support_feedback_requests();
        $has_created_by = in_array('created_by_user_id', $columns, true);
        $has_user_id = in_array('user_id', $columns, true);
        $owner_scope = $has_created_by && $has_user_id
            ? 'created_by_or_user'
            : ($has_created_by ? 'created_by' : ($has_user_id ? 'user_id' : 'none'));
        $where = [];
        $params = [];
        if (!$this->is_staff_user()) {
            if ($owner_scope === 'created_by_or_user') {
                $where[] = '(t.created_by_user_id = %d OR t.user_id = %d)';
                $params[] = $user_id;
                $params[] = $user_id;
            } elseif ($owner_scope === 'created_by') {
                $where[] = 't.created_by_user_id = %d';
                $params[] = $user_id;
            } elseif ($owner_scope === 'user_id') {
                $where[] = 't.user_id = %d';
                $params[] = $user_id;
            }
        }
        $where_sql = $where ? 'WHERE ' . implode(' AND ', $where) : '';
        $limit = $this->is_staff_user() ? 200 : 50;
        $feedback_table = $this->get_support_feedback_table();
        $is_new_expr = in_array('is_new_for_admin', $columns, true) ? 't.is_new_for_admin' : '0';
        $feedback_request_status_expr = in_array('feedback_request_status', $columns, true)
            ? 't.feedback_request_status'
            : "'none' AS feedback_request_status";
        $feedback_requested_at_expr = in_array('feedback_requested_at', $columns, true)
            ? 't.feedback_requested_at'
            : "NULL AS feedback_requested_at";
        $feedback_request_expires_at_expr = in_array('feedback_request_expires_at', $columns, true)
            ? 't.feedback_request_expires_at'
            : "NULL AS feedback_request_expires_at";
        $sql = "SELECT t.id, t.ticket_ref, t.subject, t.status, {$is_new_expr} AS is_new_for_admin, t.updated_at, {$feedback_request_status_expr}, {$feedback_requested_at_expr}, {$feedback_request_expires_at_expr}, (SELECT COUNT(1) FROM {$feedback_table} sf WHERE sf.ticket_id = t.id) AS feedback_count FROM {$table} t {$where_sql} ORDER BY t.updated_at DESC LIMIT {$limit}";
        $prepared = $params ? $wpdb->prepare($sql, $params) : $sql;
        $rows = (array) $wpdb->get_results($prepared, ARRAY_A);
        if (!empty($wpdb->last_error)) {
            error_log('CMN support list query error: ' . $wpdb->last_error);
        }
        $tickets_all = array_map(function ($row) {
            return [
                'id' => (int) $row['id'],
                'ref' => $row['ticket_ref'],
                'subject' => $row['subject'],
                'status' => $this->normalize_support_ticket_for_view($row, $this->is_staff_user())['status'],
                'is_new_for_admin' => isset($row['is_new_for_admin']) ? (int) $row['is_new_for_admin'] : 0,
                'feedback_count' => isset($row['feedback_count']) ? (int) $row['feedback_count'] : 0,
                'feedback_request_status' => $this->normalize_support_feedback_request_status((string) ($row['feedback_request_status'] ?? 'none')),
                'feedback_requested_at' => (string) ($row['feedback_requested_at'] ?? ''),
                'feedback_request_expires_at' => (string) ($row['feedback_request_expires_at'] ?? ''),
                'linked_user_id' => 0,
                'updated_at' => $row['updated_at'],
            ];
        }, $rows);
        $livechat_source_map = [];
        if ($this->is_staff_user($user_id)) {
            $livechat_source_map = $this->get_livechat_source_map_for_tickets(array_map(function ($ticket_row) {
                return (int) ($ticket_row['id'] ?? 0);
            }, $tickets_all));
            if ($livechat_source_map) {
                foreach ($tickets_all as &$ticket_row) {
                    $ticket_row_id = (int) ($ticket_row['id'] ?? 0);
                    if ($ticket_row_id < 1 || empty($livechat_source_map[$ticket_row_id])) {
                        continue;
                    }
                    $meta = (array) $livechat_source_map[$ticket_row_id];
                    $ticket_row['channel_key'] = sanitize_key((string) ($meta['source_key'] ?? ''));
                    $ticket_row['channel_label'] = sanitize_text_field((string) ($meta['source_label'] ?? ''));
                    $ticket_row['livechat_guest_name'] = sanitize_text_field((string) ($meta['guest_name'] ?? ''));
                    $ticket_row['livechat_guest_email'] = sanitize_email((string) ($meta['guest_email'] ?? ''));
                    $ticket_row['livechat_guest_type'] = sanitize_key((string) ($meta['guest_type'] ?? 'other'));
                    $ticket_row['linked_user_id'] = max(0, (int) ($meta['linked_user_id'] ?? 0));
                }
                unset($ticket_row);
            }
        }
        foreach ($tickets_all as &$ticket_row) {
            if (!isset($ticket_row['linked_user_id'])) {
                $ticket_row['linked_user_id'] = 0;
            }
            $ticket_row['requires_feedback'] = $this->support_ticket_requires_feedback($ticket_row) ? 1 : 0;
        }
        unset($ticket_row);
        $dashboard_counts = [
            'all' => count($tickets_all),
            'open' => 0,
            'closed' => 0,
            'needs_feedback' => 0,
        ];
        foreach ($tickets_all as $ticket_row) {
            $ticket_status = (string) ($ticket_row['status'] ?? 'open');
            if (in_array($ticket_status, ['new', 'open'], true)) {
                $dashboard_counts['open']++;
            }
            if ($ticket_status === 'closed') {
                $dashboard_counts['closed']++;
                if (!empty($ticket_row['requires_feedback'])) {
                    $dashboard_counts['needs_feedback']++;
                }
            }
        }
        if ($status === 'all') {
            $tickets = $tickets_all;
        } else {
            $tickets = array_values(array_filter($tickets_all, function ($ticket) use ($status) {
                return $this->support_ticket_matches_filter($ticket, $status);
            }));
        }

        $selected_ticket = $this->resolve_support_requested_ticket($ticket_id, $ticket_ref);
        $forced_filter = '';
        if ($selected_ticket && $this->can_access_support_ticket($selected_ticket, $user_id)) {
            $selected_normalized = $this->normalize_support_ticket_for_view($selected_ticket, $this->is_staff_user());
            $selected_id = (int) $selected_normalized['id'];
            $already_in_list = false;
            foreach ($tickets as $ticket_item) {
                if ((int) ($ticket_item['id'] ?? 0) === $selected_id) {
                    $already_in_list = true;
                    break;
                }
            }
            if (!$already_in_list) {
                $forced_filter = $this->map_support_filter_for_status($selected_normalized['status'] ?? 'open');
                if ($forced_filter !== '' && $forced_filter !== $status) {
                    $status = $forced_filter;
                    if ($status === 'all') {
                        $tickets = $tickets_all;
                    } else {
                        $tickets = array_values(array_filter($tickets_all, function ($ticket) use ($status) {
                            return $this->support_ticket_matches_filter($ticket, $status);
                        }));
                    }
                }
                $already_in_list = false;
                foreach ($tickets as $ticket_item) {
                    if ((int) ($ticket_item['id'] ?? 0) === $selected_id) {
                        $already_in_list = true;
                        break;
                    }
                }
                if (!$already_in_list) {
                    $selected_feedback_count = (int) $wpdb->get_var($wpdb->prepare(
                        "SELECT COUNT(1) FROM {$feedback_table} WHERE ticket_id = %d",
                        $selected_id
                    ));
                    $selected_ticket_payload = [
                        'id' => (int) $selected_normalized['id'],
                        'ref' => (string) ($selected_normalized['ticket_ref'] ?? ''),
                        'subject' => (string) ($selected_normalized['subject'] ?? ''),
                        'status' => (string) ($selected_normalized['status'] ?? 'open'),
                        'is_new_for_admin' => isset($selected_normalized['is_new_for_admin']) ? (int) $selected_normalized['is_new_for_admin'] : 0,
                        'feedback_count' => $selected_feedback_count,
                        'feedback_request_status' => $this->normalize_support_feedback_request_status((string) ($selected_normalized['feedback_request_status'] ?? 'none')),
                        'feedback_requested_at' => (string) ($selected_normalized['feedback_requested_at'] ?? ''),
                        'feedback_request_expires_at' => (string) ($selected_normalized['feedback_request_expires_at'] ?? ''),
                        'linked_user_id' => 0,
                        'requires_feedback' => 0,
                        'updated_at' => (string) ($selected_normalized['updated_at'] ?? ''),
                    ];
                    $selected_ticket_payload['requires_feedback'] = $this->support_ticket_requires_feedback($selected_ticket_payload) ? 1 : 0;
                    $tickets = array_merge([$selected_ticket_payload], $tickets);
                    if ($this->is_staff_user($user_id)) {
                        $selected_id = (int) ($selected_normalized['id'] ?? 0);
                        $selected_source = $livechat_source_map[$selected_id] ?? $this->get_livechat_thread_by_ticket_id($selected_id);
                        if (is_array($selected_source) && !empty($selected_source['source_key']) && isset($tickets[0])) {
                            $tickets[0]['channel_key'] = sanitize_key((string) ($selected_source['source_key'] ?? ''));
                            $tickets[0]['channel_label'] = sanitize_text_field((string) ($selected_source['source_label'] ?? 'Website Live Chat'));
                            $tickets[0]['livechat_guest_name'] = sanitize_text_field((string) ($selected_source['guest_name'] ?? ''));
                            $tickets[0]['livechat_guest_email'] = sanitize_email((string) ($selected_source['guest_email'] ?? ''));
                            $tickets[0]['livechat_guest_type'] = sanitize_key((string) ($selected_source['guest_type'] ?? 'other'));
                            $tickets[0]['linked_user_id'] = max(0, (int) ($selected_source['linked_user_id'] ?? 0));
                        }
                        if (isset($tickets[0]) && is_array($tickets[0])) {
                            $tickets[0]['requires_feedback'] = $this->support_ticket_requires_feedback($tickets[0]) ? 1 : 0;
                        }
                    }
                }
            }
        }

        foreach ($tickets as &$ticket_row) {
            if (!is_array($ticket_row)) {
                continue;
            }
            if (!isset($ticket_row['linked_user_id'])) {
                $ticket_row['linked_user_id'] = 0;
            }
            $ticket_row['requires_feedback'] = $this->support_ticket_requires_feedback($ticket_row) ? 1 : 0;
        }
        unset($ticket_row);

        $feedback_scope_where = [];
        $feedback_scope_params = [];
        if (!$this->is_staff_user()) {
            if ($owner_scope === 'created_by_or_user') {
                $feedback_scope_where[] = '(t.created_by_user_id = %d OR t.user_id = %d)';
                $feedback_scope_params[] = $user_id;
                $feedback_scope_params[] = $user_id;
            } elseif ($owner_scope === 'created_by') {
                $feedback_scope_where[] = 't.created_by_user_id = %d';
                $feedback_scope_params[] = $user_id;
            } elseif ($owner_scope === 'user_id') {
                $feedback_scope_where[] = 't.user_id = %d';
                $feedback_scope_params[] = $user_id;
            }
        }
        $feedback_scope_sql = $feedback_scope_where ? 'WHERE ' . implode(' AND ', $feedback_scope_where) : '';
        $feedback_sql = "SELECT sf.ticket_id, sf.support_rating, sf.response_time_rating, sf.issue_resolved, sf.overall_satisfaction, sf.comments, sf.created_at, t.ticket_ref, t.subject, t.status FROM {$feedback_table} sf INNER JOIN {$table} t ON t.id = sf.ticket_id {$feedback_scope_sql} ORDER BY sf.created_at DESC LIMIT 50";
        $feedback_prepared = $feedback_scope_params ? $wpdb->prepare($feedback_sql, $feedback_scope_params) : $feedback_sql;
        $feedback_rows = (array) $wpdb->get_results($feedback_prepared, ARRAY_A);
        $feedback_avg_total = 0.0;
        $feedback_avg_count = 0;
        $recent_feedback = [];
        foreach ($feedback_rows as $feedback_row) {
            $overall = (int) ($feedback_row['overall_satisfaction'] ?? 0);
            if ($overall > 0) {
                $feedback_avg_total += $overall;
                $feedback_avg_count++;
            }
            $recent_feedback[] = [
                'ticket_id' => (int) ($feedback_row['ticket_id'] ?? 0),
                'ticket_ref' => (string) ($feedback_row['ticket_ref'] ?? ''),
                'subject' => (string) ($feedback_row['subject'] ?? ''),
                'status' => $this->normalize_support_status((string) ($feedback_row['status'] ?? 'open')),
                'support_rating' => (int) ($feedback_row['support_rating'] ?? 0),
                'response_time_rating' => (int) ($feedback_row['response_time_rating'] ?? 0),
                'overall_satisfaction' => $overall,
                'issue_resolved' => (int) ($feedback_row['issue_resolved'] ?? 0),
                'comments' => (string) ($feedback_row['comments'] ?? ''),
                'created_at' => (string) ($feedback_row['created_at'] ?? ''),
            ];
        }

        $response = [
            'tickets' => $tickets,
            'filter' => $status,
            'forced_filter' => $forced_filter,
            'selected_ticket_id' => $selected_ticket ? (int) $selected_ticket['id'] : 0,
            'dashboard' => [
                'counts' => $dashboard_counts,
                'recent_feedback_avg' => $feedback_avg_count > 0 ? round($feedback_avg_total / $feedback_avg_count, 1) : 0,
                'recent_feedback' => array_slice($recent_feedback, 0, 25),
            ],
        ];
        if ($debug_mode) {
            $total_unfiltered = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table}");
            $sample_query = "SELECT * FROM {$table} ORDER BY updated_at DESC LIMIT 5";
            $sample_rows = (array) $wpdb->get_results($sample_query, ARRAY_A);
            $samples = [];
            foreach ($sample_rows as $sample) {
                $samples[] = [
                    'ref' => (string) ($sample['ticket_ref'] ?? ''),
                    'status_raw' => (string) ($sample['status'] ?? ''),
                    'status_normalized' => $this->normalize_support_status((string) ($sample['status'] ?? '')),
                    'created_by_user_id' => isset($sample['created_by_user_id']) ? (int) $sample['created_by_user_id'] : null,
                    'user_id' => isset($sample['user_id']) ? (int) $sample['user_id'] : null,
                    'user_role_type' => (string) ($sample['user_role_type'] ?? ''),
                ];
            }
            $response['debug'] = [
                'current_user_id' => $user_id,
                'roles' => wp_get_current_user() ? (array) wp_get_current_user()->roles : [],
                'status_filter' => $status,
                'owner_scope' => $owner_scope,
                'query_sql' => $prepared,
                'query_where' => $where,
                'query_params' => $params,
                'total_count_unfiltered' => $total_unfiltered,
                'total_count_visible' => count($tickets_all),
                'total_count_filtered' => count($tickets),
                'sample_rows' => $samples,
                'selected_ticket_ref' => $selected_ticket ? (string) ($selected_ticket['ticket_ref'] ?? '') : '',
                'selected_ticket_status' => $selected_ticket ? $this->normalize_support_status((string) ($selected_ticket['status'] ?? '')) : '',
            ];
        }
        wp_send_json_success($response);
    }

    public function handle_support_list_tickets_unfiltered_admin() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_admin_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        global $wpdb;
        $table = $this->get_support_ticket_table();
        $rows = (array) $wpdb->get_results("SELECT * FROM {$table} ORDER BY updated_at DESC LIMIT 20", ARRAY_A);
        if (!empty($wpdb->last_error)) {
            error_log('CMN support unfiltered query error: ' . $wpdb->last_error);
        }
        $payload = [];
        foreach ($rows as $row) {
            $payload[] = [
                'id' => (int) ($row['id'] ?? 0),
                'ref' => (string) ($row['ticket_ref'] ?? ''),
                'status_raw' => (string) ($row['status'] ?? ''),
                'status_normalized' => $this->normalize_support_status((string) ($row['status'] ?? '')),
                'created_at' => (string) ($row['created_at'] ?? ''),
                'updated_at' => (string) ($row['updated_at'] ?? ''),
                'created_by_user_id' => isset($row['created_by_user_id']) ? (int) $row['created_by_user_id'] : null,
                'user_id' => isset($row['user_id']) ? (int) $row['user_id'] : null,
                'user_role_type' => (string) ($row['user_role_type'] ?? ''),
            ];
        }
        wp_send_json_success([
            'tickets' => $payload,
            'count' => count($payload),
        ]);
    }

    public function handle_support_get_ticket() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $this->maybe_expire_support_feedback_requests();
        $ticket_id = intval($_POST['ticket_id'] ?? 0);
        $ticket_ref = sanitize_text_field($_POST['ticket_ref'] ?? '');
        $ticket = null;
        if ($ticket_id) {
            $ticket = $this->get_support_ticket($ticket_id);
        } elseif ($ticket_ref !== '') {
            $ticket = $this->get_support_ticket_by_ref($ticket_ref);
        }
        if (!$ticket) {
            wp_send_json_error(['message' => 'Ticket not found.'], 404);
        }
        $ticket_id = (int) $ticket['id'];
        if (!$this->can_access_support_ticket($ticket)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if ($this->is_staff_user()) {
            global $wpdb;
            $ticket_table = $this->get_support_ticket_table();
            $wpdb->update($ticket_table, [
                'is_new_for_admin' => 0,
            ], [
                'id' => $ticket_id,
            ], ['%d'], ['%d']);
            $ticket['is_new_for_admin'] = 0;
        }
        $ticket = $this->normalize_support_ticket_for_view($ticket, $this->is_staff_user());
        $livechat_meta = $this->get_livechat_thread_by_ticket_id($ticket_id);
        $livechat_guest_name = $livechat_meta ? sanitize_text_field((string) ($livechat_meta['guest_name'] ?? '')) : '';
        $messages = $this->get_support_ticket_messages($ticket_id);
        $formatted = [];
        foreach ($messages as $msg) {
            $sender_type = sanitize_key((string) ($msg['sender_type'] ?? ''));
            $sender_name = $sender_type === 'admin' ? 'Support' : 'Requester';
            if ($sender_type !== 'admin' && $livechat_guest_name !== '') {
                $sender_name = $livechat_guest_name;
            }
            if (!empty($msg['sender_user_id'])) {
                $user = get_user_by('id', (int) $msg['sender_user_id']);
                if ($user) {
                    $sender_name = $user->display_name ?: $user->user_login;
                }
            }
            $formatted[] = [
                'id' => (int) $msg['id'],
                'sender_type' => $msg['sender_type'],
                'sender_name' => $sender_name,
                'message' => $msg['message'],
                'attachments' => $this->get_support_message_attachments($msg),
                'created_at' => $msg['created_at'],
            ];
        }
        $feedback = $this->get_support_feedback($ticket_id, $this->is_staff_user() ? 0 : get_current_user_id());
        global $wpdb;
        $feedback_table = $this->get_support_feedback_table();
        $feedback_count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(1) FROM {$feedback_table} WHERE ticket_id = %d",
            $ticket_id
        ));
        $ticket['feedback_count'] = $feedback_count;
        $ticket['feedback_request_status'] = $this->normalize_support_feedback_request_status((string) ($ticket['feedback_request_status'] ?? 'none'));
        $ticket['feedback_requested_at'] = (string) ($ticket['feedback_requested_at'] ?? '');
        $ticket['feedback_request_expires_at'] = (string) ($ticket['feedback_request_expires_at'] ?? '');
        $ticket['feedback_request_active'] = $this->is_support_feedback_request_active($ticket) ? 1 : 0;
        $ticket['feedback_request_can_send'] = $this->support_ticket_can_request_feedback($ticket) ? 1 : 0;
        $ticket['requires_feedback'] = $this->support_ticket_requires_feedback($ticket) ? 1 : 0;
        if (!empty($ticket['feedback_request_expires_at'])) {
            $expires_ts = strtotime((string) $ticket['feedback_request_expires_at']);
            if ($expires_ts !== false) {
                $ticket['feedback_request_expires_label'] = date_i18n('M j, Y g:ia', (int) $expires_ts);
            }
        }
        $payroll_query_meta = $this->get_support_payroll_query_metadata_by_ticket($ticket_id);
        $payroll_context = [];
        if ($this->is_staff_user() && $livechat_meta) {
            $ticket['channel_key'] = sanitize_key((string) ($livechat_meta['source_key'] ?? 'website_live_chat'));
            $ticket['channel_label'] = 'Website Live Chat';
            $ticket['livechat_guest_name'] = sanitize_text_field((string) ($livechat_meta['guest_name'] ?? ''));
            $ticket['livechat_guest_email'] = sanitize_email((string) ($livechat_meta['guest_email'] ?? ''));
            $ticket['livechat_guest_type'] = sanitize_key((string) ($livechat_meta['guest_type'] ?? 'other'));
        }
        if ($this->is_staff_user()) {
            $payroll_context = $this->build_staff_payroll_ticket_context($ticket, $payroll_query_meta);
        }
        wp_send_json_success([
            'ticket' => $ticket,
            'messages' => $formatted,
            'feedback' => $feedback ?: null,
            'payroll_query' => $payroll_query_meta ?: null,
            'payroll_context' => $payroll_context ?: null,
            'livechat' => $livechat_meta ?: null,
        ]);
    }

    public function handle_support_post_message() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $user_id = get_current_user_id();
        $ticket_id = intval($_POST['ticket_id'] ?? 0);
        $message = sanitize_textarea_field($_POST['message'] ?? '');
        if (!$ticket_id || $message === '') {
            wp_send_json_error(['message' => 'Message is required.'], 400);
        }
        $ticket = $this->get_support_ticket($ticket_id);
        if (!$this->can_access_support_ticket($ticket)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $sender_type = $this->is_staff_user() ? 'admin' : 'user';
        global $wpdb;
        $message_table = $this->get_support_message_table();
        $now = current_time('mysql');
        $uploaded = $this->handle_support_attachments_upload('attachments');
        $attachment_ids = !empty($uploaded['ids']) ? wp_json_encode(array_values(array_unique(array_map('intval', $uploaded['ids'])))) : null;
        $wpdb->insert($message_table, [
            'ticket_id' => $ticket_id,
            'sender_user_id' => $user_id,
            'sender_type' => $sender_type,
            'message' => $message,
            'attachment_ids' => $attachment_ids,
            'created_at' => $now,
        ], ['%d', '%d', '%s', '%s', '%s', '%s']);

        $ticket_table = $this->get_support_ticket_table();
        $new_status = 'open';
        $ticket_update = [
            'status' => $new_status,
            'is_new_for_admin' => $sender_type === 'admin' ? 0 : 1,
            'updated_at' => $now,
            'closed_at' => null,
        ];
        $ticket_update_format = ['%s', '%d', '%s', '%s'];
        if (
            $this->support_ticket_has_column('feedback_request_status')
            && $this->support_ticket_has_column('feedback_requested_at')
            && $this->support_ticket_has_column('feedback_request_expires_at')
        ) {
            $ticket_update['feedback_request_status'] = 'none';
            $ticket_update['feedback_requested_at'] = null;
            $ticket_update['feedback_request_expires_at'] = null;
            $ticket_update_format[] = '%s';
            $ticket_update_format[] = '%s';
            $ticket_update_format[] = '%s';
        }
        $wpdb->update($ticket_table, $ticket_update, ['id' => $ticket_id], $ticket_update_format, ['%d']);

        if ($sender_type === 'admin') {
            $owner_id = (int) $this->get_support_owner_user_id($ticket);
            $subject_line = 'Update on your support ticket: ' . $ticket['ticket_ref'];
            $portal_link = $this->get_support_link_for_user($owner_id, $ticket_id, $ticket['ticket_ref'] ?? '');
            $body = "We've replied to your support ticket.\n\n{$message}\n\nYou can reply in your portal:\n{$portal_link}";
            if ($owner_id > 0) {
                $this->send_support_email_to_user($owner_id, $subject_line, $body, 'support_ticket_reply', [
                    'ticket_id' => $ticket_id,
                ]);
                $this->add_notification($owner_id, 'support_reply', 'Support ticket reply', $ticket['ticket_ref'] . ' updated.', $portal_link);
            } else {
                $livechat_meta = $this->get_livechat_thread_by_ticket_id($ticket_id);
                if (is_array($livechat_meta) && sanitize_key((string) ($livechat_meta['source_key'] ?? '')) === 'website_live_chat') {
                    $guest_email = sanitize_email((string) ($livechat_meta['guest_email'] ?? ''));
                    if ($guest_email !== '' && is_email($guest_email)) {
                        $guest_name = sanitize_text_field((string) ($livechat_meta['guest_name'] ?? 'there'));
                        $guest_subject = 'Update on your live chat: ' . $ticket['ticket_ref'];
                        $guest_body = implode("\n", [
                            'Hi ' . ($guest_name !== '' ? $guest_name : 'there') . ',',
                            '',
                            'We have replied to your live chat message.',
                            '',
                            $message,
                            '',
                            'You can continue this conversation on the Contact page:',
                            home_url('/contact'),
                        ]);
                        $this->send_support_email($guest_email, $guest_subject, $guest_body, [
                            'type' => 'livechat_reply',
                            'template_key' => 'website_livechat_reply',
                            'recipient_role' => 'system',
                            'module' => 'support',
                            'related_entity_type' => 'support_ticket',
                            'related_entity_id' => $ticket_id,
                            'metadata' => [
                                'source' => 'website_live_chat',
                            ],
                        ]);
                    }
                }
            }
        } else {
            $this->notify_admins_support_reply($ticket_id, $ticket['ticket_ref'], $message, $user_id);
        }

        wp_send_json_success([
            'message' => 'Message sent.',
            'status' => $new_status,
            'upload_errors' => $uploaded['errors'],
        ]);
    }

    public function handle_support_close_ticket() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $ticket_id = intval($_POST['ticket_id'] ?? 0);
        $status = sanitize_text_field($_POST['status'] ?? 'closed');
        if (!$ticket_id) {
            wp_send_json_error(['message' => 'Ticket not found.'], 404);
        }
        if (!in_array($status, ['closed', 'open'], true)) {
            $status = 'closed';
        }
        global $wpdb;
        $table = $this->get_support_ticket_table();
        $ticket = $this->get_support_ticket($ticket_id);
        if (!$ticket) {
            wp_send_json_error(['message' => 'Ticket not found.'], 404);
        }
        $current_user = get_current_user_id();
        $is_staff = $this->is_staff_user($current_user);
        $is_owner = ((int) $this->get_support_owner_user_id($ticket) === (int) $current_user);
        if (!$is_staff && !$is_owner) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if (!$is_staff && $status !== 'open') {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $owner_id = (int) $this->get_support_owner_user_id($ticket);
        $ticket_ref = (string) ($ticket['ticket_ref'] ?? '');
        $now = current_time('mysql');
        $target_status = $status === 'closed' ? 'closed' : 'open';
        $current_status = $this->normalize_support_status($ticket['status'] ?? '');
        if ($current_status === $target_status) {
            wp_send_json_success(['status' => $target_status, 'unchanged' => true]);
        }
        $ticket_update = [
            'status' => $target_status,
            'updated_at' => $now,
            'closed_at' => $status === 'closed' ? $now : null,
            'is_new_for_admin' => 0,
        ];
        $ticket_update_format = ['%s', '%s', '%s', '%d'];
        if (
            $target_status === 'open'
            && $this->support_ticket_has_column('feedback_request_status')
            && $this->support_ticket_has_column('feedback_requested_at')
            && $this->support_ticket_has_column('feedback_request_expires_at')
        ) {
            $ticket_update['feedback_request_status'] = 'none';
            $ticket_update['feedback_requested_at'] = null;
            $ticket_update['feedback_request_expires_at'] = null;
            $ticket_update_format[] = '%s';
            $ticket_update_format[] = '%s';
            $ticket_update_format[] = '%s';
        }
        $wpdb->update($table, $ticket_update, ['id' => $ticket_id], $ticket_update_format, ['%d']);
        $livechat_meta = $this->get_livechat_thread_by_ticket_id($ticket_id);
        if (is_array($livechat_meta) && !empty($livechat_meta['id'])) {
            $this->update_livechat_thread_status((int) $livechat_meta['id'], $target_status === 'closed' ? 'closed' : 'open');
        }
        if ($is_staff) {
            if ($target_status === 'closed') {
                $this->insert_support_system_message_once($ticket_id, 'Ticket closed by support.', $current_user, 'admin');
            } else {
                $this->insert_support_system_message_once($ticket_id, 'Ticket reopened by support.', $current_user, 'admin');
            }
        }
        if ($owner_id) {
            $owner_link = $this->get_support_link_for_user($owner_id, $ticket_id, $ticket_ref);
            if ($target_status === 'closed') {
                $this->add_notification($owner_id, 'support_ticket_closed', 'Ticket closed', $ticket_ref . ' has been closed.', $owner_link);
                if ($is_staff && (int) $owner_id !== (int) $current_user) {
                    $owner_subject = 'Support ticket closed: ' . $ticket_ref;
                    $owner_message = implode("\n", [
                        'Your support ticket has been closed by support.',
                        '',
                        'Reference: ' . $ticket_ref,
                        'View ticket: ' . $owner_link,
                    ]);
                    $this->send_support_email_to_user($owner_id, $owner_subject, $owner_message, 'support_ticket_closed', [
                        'ticket_id' => $ticket_id,
                    ]);
                }
            } else {
                $this->add_notification($owner_id, 'support_ticket_reopened', 'Ticket reopened', $ticket_ref . ' has been reopened.', $owner_link);
                if ($is_staff && (int) $owner_id !== (int) $current_user) {
                    $owner_subject = 'Support ticket reopened: ' . $ticket_ref;
                    $owner_message = implode("\n", [
                        'Your support ticket has been reopened by support.',
                        '',
                        'Reference: ' . $ticket_ref,
                        'View ticket: ' . $owner_link,
                    ]);
                    $this->send_support_email_to_user($owner_id, $owner_subject, $owner_message, 'support_ticket_reopened', [
                        'ticket_id' => $ticket_id,
                    ]);
                }
            }
        }
        if ($target_status === 'open' && !$is_staff) {
            foreach ($this->get_admin_users_for_support() as $admin_id) {
                $admin_id = (int) $admin_id;
                if ($admin_id < 1) {
                    continue;
                }
                $admin_link = $this->get_support_link_for_user($admin_id, $ticket_id, $ticket_ref);
                $this->add_notification($admin_id, 'support_ticket_reopened', 'Ticket reopened', $ticket_ref . ' was reopened by the ticket owner.', $admin_link);
                $admin_subject = 'Support ticket reopened: ' . $ticket_ref;
                $admin_message = implode("\n", [
                    'A ticket owner has reopened a support ticket.',
                    '',
                    'Reference: ' . $ticket_ref,
                    'Open in portal: ' . $admin_link,
                ]);
                $this->send_support_email_to_user($admin_id, $admin_subject, $admin_message, 'support_ticket_reopened_admin', [
                    'ticket_id' => $ticket_id,
                ]);
            }
        }
        $this->add_audit_log(
            $target_status === 'closed' ? 'support_ticket_closed' : 'support_ticket_reopened',
            'support_ticket',
            (string) $ticket_id,
            [
                'ticket_ref' => $ticket_ref,
                'actor_is_staff' => $is_staff ? 1 : 0,
            ],
            $current_user
        );
        wp_send_json_success(['status' => $target_status]);
    }

    public function handle_support_request_feedback() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in() || !$this->is_staff_user()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $ticket_id = max(0, (int) ($_POST['ticket_id'] ?? 0));
        if ($ticket_id < 1) {
            wp_send_json_error(['message' => 'Ticket not found.'], 404);
        }

        self::migrate_schema_v73_support_feedback_request_lifecycle();
        $this->maybe_expire_support_feedback_requests();

        $ticket = $this->get_support_ticket($ticket_id);
        if (!$ticket || !$this->can_access_support_ticket($ticket)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if ($this->normalize_support_status((string) ($ticket['status'] ?? 'open')) !== 'closed') {
            wp_send_json_error(['message' => 'Feedback can only be requested for closed tickets.'], 400);
        }

        global $wpdb;
        $feedback_table = $this->get_support_feedback_table();
        $feedback_count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(1) FROM {$feedback_table} WHERE ticket_id = %d",
            $ticket_id
        ));
        if ($feedback_count > 0) {
            wp_send_json_error(['message' => 'Feedback is already submitted for this ticket.'], 400);
        }

        $ticket['feedback_count'] = $feedback_count;
        $ticket['feedback_request_status'] = $this->normalize_support_feedback_request_status((string) ($ticket['feedback_request_status'] ?? 'none'));
        $ticket['feedback_request_expires_at'] = (string) ($ticket['feedback_request_expires_at'] ?? '');
        if ($this->is_support_feedback_request_active($ticket)) {
            wp_send_json_success([
                'message' => 'Feedback request already active.',
                'already_requested' => true,
                'expires_at' => (string) ($ticket['feedback_request_expires_at'] ?? ''),
            ]);
        }
        if (!$this->support_ticket_can_request_feedback($ticket)) {
            wp_send_json_error(['message' => 'Unable to request feedback for this ticket.'], 400);
        }

        $ticket_ref = (string) ($ticket['ticket_ref'] ?? '');
        $owner_id = (int) $this->get_support_owner_user_id($ticket);
        $subject = 'We value your feedback: ' . ($ticket_ref !== '' ? $ticket_ref : 'Support ticket');
        $hours = max(1, (int) self::SUPPORT_FEEDBACK_REQUEST_WINDOW_HOURS);
        $sent = false;
        $recipient_email = '';
        $owner_link = '';

        if ($owner_id > 0) {
            $owner = get_user_by('id', $owner_id);
            if ($owner instanceof WP_User && is_email((string) $owner->user_email)) {
                $owner_link = $this->get_support_feedback_link_for_user($owner_id, $ticket_id, $ticket_ref);
                $body = implode("\n", [
                    'Your support ticket has been closed and support has requested your feedback.',
                    '',
                    'Reference: ' . $ticket_ref,
                    'Please submit feedback within ' . $hours . ' hours using your portal:',
                    $owner_link,
                ]);
                $sent = (bool) $this->send_support_email_to_user($owner_id, $subject, $body, 'support_feedback_request', [
                    'ticket_id' => $ticket_id,
                    'template_key' => 'support_feedback_request',
                ]);
                $recipient_email = sanitize_email((string) $owner->user_email);
            }
        }

        if (!$sent) {
            $livechat_meta = $this->get_livechat_thread_by_ticket_id($ticket_id);
            $guest_email = sanitize_email((string) ($livechat_meta['guest_email'] ?? ''));
            if ($guest_email !== '' && is_email($guest_email)) {
                $contact_link = home_url('/contact');
                $body = implode("\n", [
                    'Support has closed your live chat ticket and requested feedback.',
                    '',
                    'Reference: ' . $ticket_ref,
                    'Please submit feedback within ' . $hours . ' hours by returning to:',
                    $contact_link,
                ]);
                $sent = (bool) $this->send_support_email($guest_email, $subject, $body, [
                    'type' => 'support_feedback_request',
                    'template_key' => 'support_feedback_request',
                    'recipient_role' => 'system',
                    'module' => 'support',
                    'related_entity_type' => 'support_ticket',
                    'related_entity_id' => $ticket_id,
                    'metadata' => [
                        'source' => 'website_live_chat',
                    ],
                ]);
                $recipient_email = $guest_email;
            }
        }

        if (!$sent) {
            wp_send_json_error(['message' => 'Unable to send feedback request email for this ticket.'], 500);
        }

        $ticket_table = $this->get_support_ticket_table();
        $now = current_time('mysql');
        $expires_at = wp_date('Y-m-d H:i:s', ((int) current_time('timestamp')) + ($hours * HOUR_IN_SECONDS), wp_timezone());
        if (
            $this->support_ticket_has_column('feedback_request_status')
            && $this->support_ticket_has_column('feedback_requested_at')
            && $this->support_ticket_has_column('feedback_request_expires_at')
        ) {
            $wpdb->update($ticket_table, [
                'feedback_request_status' => 'requested',
                'feedback_requested_at' => $now,
                'feedback_request_expires_at' => $expires_at,
                'updated_at' => $now,
            ], [
                'id' => $ticket_id,
            ], ['%s', '%s', '%s', '%s'], ['%d']);
        }
        $this->insert_support_system_message_once(
            $ticket_id,
            'Support requested feedback from the requester (48 hour window).',
            (int) get_current_user_id(),
            'admin'
        );

        if ($owner_id > 0 && $owner_link !== '') {
            $this->add_notification(
                $owner_id,
                'support_feedback',
                'Feedback requested',
                ($ticket_ref !== '' ? $ticket_ref : 'Support ticket') . ' is awaiting your feedback.',
                $owner_link
            );
        }

        $this->add_audit_log('support_feedback_requested', 'support_ticket', (string) $ticket_id, [
            'ticket_ref' => $ticket_ref,
            'recipient_email' => $recipient_email,
            'expires_at' => $expires_at,
        ], get_current_user_id());

        wp_send_json_success([
            'message' => 'Feedback request sent.',
            'expires_at' => $expires_at,
        ]);
    }

    public function handle_support_submit_feedback() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $ticket_id = (int) ($_POST['ticket_id'] ?? 0);
        if (!$ticket_id) {
            wp_send_json_error(['message' => 'Ticket not found.'], 404);
        }
        $ticket = $this->get_support_ticket($ticket_id);
        if (!$ticket || !$this->can_access_support_ticket($ticket)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        if ($this->normalize_support_status($ticket['status'] ?? '') !== 'closed') {
            wp_send_json_error(['message' => 'Feedback is available only for closed tickets.'], 400);
        }
        $user_id = get_current_user_id();
        if ($this->is_staff_user($user_id)) {
            wp_send_json_error(['message' => 'Only ticket owner can submit feedback.'], 403);
        }
        $support_rating = max(1, min(5, (int) ($_POST['support_rating'] ?? 0)));
        $response_time_rating = max(1, min(5, (int) ($_POST['response_time_rating'] ?? 0)));
        $overall_satisfaction = max(1, min(5, (int) ($_POST['overall_satisfaction'] ?? 0)));
        $issue_resolved = !empty($_POST['issue_resolved']) && (string) $_POST['issue_resolved'] !== '0' ? 1 : 0;
        $comments = sanitize_textarea_field((string) ($_POST['comments'] ?? ''));
        if ($support_rating < 1 || $response_time_rating < 1 || $overall_satisfaction < 1) {
            wp_send_json_error(['message' => 'Please complete all ratings.'], 400);
        }
        global $wpdb;
        $table = $this->get_support_feedback_table();
        $now = current_time('mysql');
        $wpdb->replace($table, [
            'ticket_id' => $ticket_id,
            'user_id' => $user_id,
            'support_rating' => $support_rating,
            'response_time_rating' => $response_time_rating,
            'issue_resolved' => $issue_resolved,
            'overall_satisfaction' => $overall_satisfaction,
            'comments' => $comments,
            'created_at' => $now,
        ], ['%d', '%d', '%d', '%d', '%d', '%d', '%s', '%s']);
        if (
            $this->support_ticket_has_column('feedback_request_status')
            && $this->support_ticket_has_column('feedback_requested_at')
            && $this->support_ticket_has_column('feedback_request_expires_at')
        ) {
            $ticket_table = $this->get_support_ticket_table();
            $wpdb->update($ticket_table, [
                'feedback_request_status' => 'completed',
                'feedback_requested_at' => null,
                'feedback_request_expires_at' => null,
                'updated_at' => $now,
            ], [
                'id' => $ticket_id,
            ], ['%s', '%s', '%s', '%s'], ['%d']);
        }
        $ticket_ref = (string) ($ticket['ticket_ref'] ?? '');
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            $admin_link = $this->get_support_link_for_user($admin_id, $ticket_id, $ticket_ref);
            $this->add_notification(
                (int) $admin_id,
                'support_feedback',
                'Support feedback',
                ($ticket_ref ?: 'Ticket') . ' feedback submitted.',
                $admin_link
            );
        }
        wp_send_json_success([
            'message' => 'Feedback saved.',
            'feedback' => $this->get_support_feedback($ticket_id, $user_id),
        ]);
    }

    public function handle_support_save_transcript() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $ticket_id = (int) ($_POST['ticket_id'] ?? 0);
        if (!$ticket_id) {
            wp_send_json_error(['message' => 'Ticket not found.'], 404);
        }
        $ticket = $this->get_support_ticket($ticket_id);
        if (!$ticket || !$this->can_access_support_ticket($ticket)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $messages = $this->get_support_ticket_messages($ticket_id);
        $formatted = [];
        foreach ($messages as $msg) {
            $sender_name = 'Support';
            if (!empty($msg['sender_user_id'])) {
                $usr = get_user_by('id', (int) $msg['sender_user_id']);
                if ($usr) {
                    $sender_name = $usr->display_name ?: $usr->user_login;
                }
            }
            $formatted[] = [
                'sender_name' => $sender_name,
                'message' => (string) ($msg['message'] ?? ''),
                'created_at' => (string) ($msg['created_at'] ?? ''),
                'attachments' => $this->get_support_message_attachments($msg),
            ];
        }
        $transcript_text = $this->build_support_transcript_text($ticket, $formatted);
        global $wpdb;
        $table = $this->get_support_transcript_table();
        $wpdb->insert($table, [
            'ticket_id' => $ticket_id,
            'created_by' => get_current_user_id(),
            'transcript_text' => $transcript_text,
            'created_at' => current_time('mysql'),
        ], ['%d', '%d', '%s', '%s']);
        wp_send_json_success([
            'message' => 'Transcript saved.',
            'transcript' => $transcript_text,
        ]);
    }

    public function handle_support_email_transcript() {
        if (!check_ajax_referer('cmn_support', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid request.'], 403);
        }
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $ticket_id = (int) ($_POST['ticket_id'] ?? 0);
        if (!$ticket_id) {
            wp_send_json_error(['message' => 'Ticket not found.'], 404);
        }
        $ticket = $this->get_support_ticket($ticket_id);
        if (!$ticket || !$this->can_access_support_ticket($ticket)) {
            wp_send_json_error(['message' => 'Unauthorized.'], 403);
        }
        $owner_id = (int) ($ticket['created_by_user_id'] ?? 0);
        $owner = $owner_id ? get_user_by('id', $owner_id) : null;
        if (!$owner || !is_email($owner->user_email)) {
            wp_send_json_error(['message' => 'Ticket owner email not found.'], 400);
        }
        $messages = $this->get_support_ticket_messages($ticket_id);
        $formatted = [];
        foreach ($messages as $msg) {
            $sender_name = 'Support';
            if (!empty($msg['sender_user_id'])) {
                $usr = get_user_by('id', (int) $msg['sender_user_id']);
                if ($usr) {
                    $sender_name = $usr->display_name ?: $usr->user_login;
                }
            }
            $formatted[] = [
                'sender_name' => $sender_name,
                'message' => (string) ($msg['message'] ?? ''),
                'created_at' => (string) ($msg['created_at'] ?? ''),
                'attachments' => $this->get_support_message_attachments($msg),
            ];
        }
        $transcript_text = $this->build_support_transcript_text($ticket, $formatted);
        $subject = 'Support transcript: ' . (string) ($ticket['ticket_ref'] ?? 'CMN Ticket');
        $sent = $this->send_support_email_to_user($owner_id, $subject, $transcript_text, 'support_transcript', [
            'ticket_id' => $ticket_id,
        ]);
        global $wpdb;
        $table = $this->get_support_transcript_email_table();
        $wpdb->insert($table, [
            'ticket_id' => $ticket_id,
            'created_by' => get_current_user_id(),
            'to_email' => $owner->user_email,
            'status' => $sent ? 'sent' : 'failed',
            'error_message' => $sent ? null : 'Unable to send transcript.',
            'created_at' => current_time('mysql'),
        ], ['%d', '%d', '%s', '%s', '%s', '%s']);
        if (!$sent) {
            wp_send_json_error(['message' => 'Unable to send transcript email.'], 500);
        }
        wp_send_json_success(['message' => 'Transcript emailed to ticket owner.']);
    }

    public function handle_add_contact_portal() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_add_contact_nonce']) || !wp_verify_nonce($_POST['cmn_add_contact_nonce'], 'cmn_add_contact')) {
            wp_die('Invalid request');
        }
        $name = sanitize_text_field($_POST['cmn_contact_name'] ?? '');
        $email = sanitize_email($_POST['cmn_contact_email'] ?? '');
        $phone = sanitize_text_field($_POST['cmn_contact_phone'] ?? '');
        $role = sanitize_text_field($_POST['cmn_contact_role'] ?? '');
        $primary_domain = sanitize_text_field($_POST['cmn_contact_primary_school_domain'] ?? '');
        $additional_domains = isset($_POST['cmn_contact_school_domains']) && is_array($_POST['cmn_contact_school_domains'])
            ? array_map('sanitize_text_field', $_POST['cmn_contact_school_domains'])
            : [];
        $user_id = get_current_user_id();
        if ($this->is_account_manager_user($user_id) && !$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            $allowed_domains = [];
            foreach ($this->get_assigned_school_ids_for_account_manager($user_id) as $school_id) {
                $domain = get_post_meta($school_id, 'cmn_school_email_domain', true);
                if ($domain) {
                    $allowed_domains[] = $domain;
                }
            }
            $allowed_domains = array_unique($allowed_domains);
            if ($primary_domain && !in_array($primary_domain, $allowed_domains, true)) {
                $primary_domain = '';
            }
            if ($additional_domains) {
                $additional_domains = array_values(array_intersect($additional_domains, $allowed_domains));
            }
        }
        if ($name === '') {
            wp_die('Contact name is required.');
        }
        if ($email && !is_email($email)) {
            wp_die('Invalid email address.');
        }
        $contact_id = wp_insert_post([
            'post_type' => 'cmn_contact',
            'post_title' => $name,
            'post_status' => 'publish',
        ]);
        if (!is_wp_error($contact_id)) {
            update_post_meta($contact_id, 'cmn_contact_name', $name);
            update_post_meta($contact_id, 'cmn_contact_email', $email);
            update_post_meta($contact_id, 'cmn_contact_phone', $phone);
            update_post_meta($contact_id, 'cmn_contact_role', $role);
            if ($primary_domain) {
                $this->link_contact_to_school($contact_id, $primary_domain, true);
                $primary_post_id = $this->get_school_post_id_by_domain($primary_domain);
                if ($primary_post_id) {
                    update_post_meta($contact_id, 'cmn_contact_school_id', $primary_post_id);
                }
            }
            if ($additional_domains) {
                foreach ($additional_domains as $domain) {
                    if (!$domain || $domain === $primary_domain) {
                        continue;
                    }
                    $this->link_contact_to_school($contact_id, $domain, false);
                }
            }
        }
        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        $bucket = sanitize_key((string) ($_POST['cmn_bucket'] ?? 'clients'));
        if (!in_array($bucket, ['sales', 'clients', 'all'], true)) {
            $bucket = 'clients';
        }
        wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_bucket' => $bucket, 'cmn_contact_msg' => rawurlencode('Contact saved.')], $portal_url));
        exit;
    }

    public function handle_update_contact_portal() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_update_contact_nonce']) || !wp_verify_nonce($_POST['cmn_update_contact_nonce'], 'cmn_update_contact')) {
            wp_die('Invalid request');
        }
        $contact_id = intval($_POST['cmn_contact_id'] ?? 0);
        if (!$contact_id) {
            wp_die('Invalid contact.');
        }
        $user_id = get_current_user_id();
        if ($this->is_account_manager_user($user_id) && !$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            $allowed_domains = [];
            foreach ($this->get_assigned_school_ids_for_account_manager($user_id) as $school_id) {
                $domain = get_post_meta($school_id, 'cmn_school_email_domain', true);
                if ($domain) {
                    $allowed_domains[] = $domain;
                }
            }
            $allowed_domains = array_unique($allowed_domains);
            $links = $this->get_contact_school_links($contact_id);
            $contact_domains = [];
            foreach ($links as $link) {
                if (!empty($link['school_email_domain'])) {
                    $contact_domains[] = $link['school_email_domain'];
                }
            }
            if (!$allowed_domains || !array_intersect($allowed_domains, $contact_domains)) {
                wp_die('Unauthorized');
            }
        }
        $name = sanitize_text_field($_POST['cmn_contact_name'] ?? '');
        $email = sanitize_email($_POST['cmn_contact_email'] ?? '');
        $phone = sanitize_text_field($_POST['cmn_contact_phone'] ?? '');
        $role = sanitize_text_field($_POST['cmn_contact_role'] ?? '');
        $primary_domain = sanitize_text_field($_POST['cmn_contact_primary_school_domain'] ?? '');
        $additional_domains = isset($_POST['cmn_contact_school_domains']) && is_array($_POST['cmn_contact_school_domains'])
            ? array_map('sanitize_text_field', $_POST['cmn_contact_school_domains'])
            : [];
        $user_id = get_current_user_id();
        if ($this->is_account_manager_user($user_id) && !$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            $allowed_domains = [];
            foreach ($this->get_assigned_school_ids_for_account_manager($user_id) as $school_id) {
                $domain = get_post_meta($school_id, 'cmn_school_email_domain', true);
                if ($domain) {
                    $allowed_domains[] = $domain;
                }
            }
            $allowed_domains = array_unique($allowed_domains);
            if ($primary_domain && !in_array($primary_domain, $allowed_domains, true)) {
                $primary_domain = '';
            }
            if ($additional_domains) {
                $additional_domains = array_values(array_intersect($additional_domains, $allowed_domains));
            }
        }
        if ($name === '') {
            wp_die('Contact name is required.');
        }
        if ($email && !is_email($email)) {
            wp_die('Invalid email address.');
        }
        wp_update_post([
            'ID' => $contact_id,
            'post_title' => $name,
        ]);
        update_post_meta($contact_id, 'cmn_contact_name', $name);
        update_post_meta($contact_id, 'cmn_contact_email', $email);
        update_post_meta($contact_id, 'cmn_contact_phone', $phone);
        update_post_meta($contact_id, 'cmn_contact_role', $role);
        $this->clear_contact_links($contact_id);
        if ($primary_domain) {
            $this->link_contact_to_school($contact_id, $primary_domain, true);
            $primary_post_id = $this->get_school_post_id_by_domain($primary_domain);
            if ($primary_post_id) {
                update_post_meta($contact_id, 'cmn_contact_school_id', $primary_post_id);
            }
        } else {
            delete_post_meta($contact_id, 'cmn_contact_school_id');
        }
        if ($additional_domains) {
            foreach ($additional_domains as $domain) {
                if (!$domain || $domain === $primary_domain) {
                    continue;
                }
                $this->link_contact_to_school($contact_id, $domain, false);
            }
        }
        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        $bucket = sanitize_key((string) ($_POST['cmn_bucket'] ?? 'clients'));
        if (!in_array($bucket, ['sales', 'clients', 'all'], true)) {
            $bucket = 'clients';
        }
        wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_bucket' => $bucket, 'cmn_contact_msg' => rawurlencode('Contact updated.')], $portal_url));
        exit;
    }

    public function handle_delete_contact_portal() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_delete_contact_nonce']) || !wp_verify_nonce($_POST['cmn_delete_contact_nonce'], 'cmn_delete_contact')) {
            wp_die('Invalid request');
        }
        $contact_id = intval($_POST['cmn_contact_id'] ?? 0);
        $user_id = get_current_user_id();
        if ($contact_id && $this->is_account_manager_user($user_id) && !$this->is_admin_user($user_id) && !$this->is_staff_role($user_id)) {
            $allowed_domains = [];
            foreach ($this->get_assigned_school_ids_for_account_manager($user_id) as $school_id) {
                $domain = get_post_meta($school_id, 'cmn_school_email_domain', true);
                if ($domain) {
                    $allowed_domains[] = $domain;
                }
            }
            $allowed_domains = array_unique($allowed_domains);
            $links = $this->get_contact_school_links($contact_id);
            $contact_domains = [];
            foreach ($links as $link) {
                if (!empty($link['school_email_domain'])) {
                    $contact_domains[] = $link['school_email_domain'];
                }
            }
            if (!$allowed_domains || !array_intersect($allowed_domains, $contact_domains)) {
                wp_die('Unauthorized');
            }
        }
        if ($contact_id) {
            wp_delete_post($contact_id, true);
        }
        $portal_page = cmn_get_page_by_title('Portal');
        $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
        $bucket = sanitize_key((string) ($_POST['cmn_bucket'] ?? 'clients'));
        if (!in_array($bucket, ['sales', 'clients', 'all'], true)) {
            $bucket = 'clients';
        }
        wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_bucket' => $bucket, 'cmn_contact_msg' => rawurlencode('Contact deleted.')], $portal_url));
        exit;
    }

    public function handle_import_contacts_portal() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_import_contacts_nonce']) || !wp_verify_nonce($_POST['cmn_import_contacts_nonce'], 'cmn_import_contacts')) {
            wp_die('Invalid request');
        }
        $referer = wp_get_referer() ?: home_url('/portal');
        $step = sanitize_text_field($_POST['cmn_import_step'] ?? '');

        if ($step === 'upload') {
            if (empty($_FILES['cmn_contacts_file']['name'])) {
                wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode('No file selected.')], $referer));
                exit;
            }
            $ext = strtolower(pathinfo($_FILES['cmn_contacts_file']['name'], PATHINFO_EXTENSION));
            if ($ext === 'xls') {
                wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode('Please upload an .xlsx or .csv file. Save .xls as .xlsx first.')], $referer));
                exit;
            }
            if (!in_array($ext, ['csv', 'xlsx'], true)) {
                wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode('Please upload a .csv or .xlsx file.')], $referer));
                exit;
            }
            if (!function_exists('wp_handle_upload')) {
                require_once ABSPATH . 'wp-admin/includes/file.php';
            }
            $upload = wp_handle_upload($_FILES['cmn_contacts_file'], ['test_form' => false]);
            if (isset($upload['error'])) {
                wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode($upload['error'])], $referer));
                exit;
            }
            $headers = $this->read_spreadsheet_headers($upload['file'], $ext);
            if (!$headers) {
                wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode('Unable to read CSV headers.')], $referer));
                exit;
            }
            $token = wp_generate_password(12, false, false);
            set_transient('cmn_contact_import_' . $token, [
                'user_id' => get_current_user_id(),
                'file' => $upload['file'],
                'headers' => $headers,
                'ext' => $ext,
            ], HOUR_IN_SECONDS);
            wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_import_token' => $token], $referer));
            exit;
        }

        if ($step === 'map') {
            $token = sanitize_text_field($_POST['cmn_contact_import_token'] ?? '');
            $data = $token ? get_transient('cmn_contact_import_' . $token) : null;
            if (!$data || (int) ($data['user_id'] ?? 0) !== get_current_user_id()) {
                wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode('Import session expired. Please upload the file again.')], $referer));
                exit;
            }
            $map = $_POST['cmn_contact_map'] ?? [];
            if (!is_array($map)) {
                wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode('Invalid mapping data.')], $referer));
                exit;
            }
            if (!isset($map['cmn_contact_name']) || $map['cmn_contact_name'] === '') {
                wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode('Please map the required Contact Name field.')], $referer));
                exit;
            }
            $ext = $data['ext'] ?? 'csv';
            $message = $this->import_contacts_spreadsheet_mapped($data['file'], $map, $ext);
            delete_transient('cmn_contact_import_' . $token);
            if (is_string($data['file']) && file_exists($data['file'])) {
                @unlink($data['file']);
            }
            wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode($message)], $referer));
            exit;
        }

        wp_redirect(add_query_arg(['view' => 'contacts', 'cmn_contact_msg' => rawurlencode('Invalid import request.')], $referer));
        exit;
    }

    public function handle_mark_school_import_resolved() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        $school_id = isset($_REQUEST['school_id']) ? (int) $_REQUEST['school_id'] : 0;
        $nonce = isset($_REQUEST['cmn_nonce']) ? sanitize_text_field(wp_unslash((string) $_REQUEST['cmn_nonce'])) : '';
        if ($school_id < 1 || $nonce === '' || !wp_verify_nonce($nonce, 'cmn_mark_school_import_resolved_' . $school_id)) {
            wp_die('Invalid request');
        }
        $redirect = isset($_REQUEST['cmn_redirect']) ? esc_url_raw(wp_unslash((string) $_REQUEST['cmn_redirect'])) : '';
        if ($redirect === '') {
            $redirect = wp_get_referer() ?: home_url('/portal');
        }
        $post = get_post($school_id);
        if (!$post || $post->post_type !== 'cmn_school') {
            wp_safe_redirect(add_query_arg([
                'view' => 'schools',
                'cmn_imported' => '1',
                'cmn_import_msg' => rawurlencode('School not found.'),
            ], $redirect));
            exit;
        }

        delete_post_meta($school_id, 'cmn_import_issues');
        $status_value = sanitize_key((string) get_post_meta($school_id, 'cmn_status', true));
        if ($status_value === 'needs_attention') {
            update_post_meta($school_id, 'cmn_status', 'lead');
        }
        $pipeline_value = sanitize_key((string) get_post_meta($school_id, 'cmn_pipeline_stage', true));
        if ($pipeline_value === '') {
            update_post_meta($school_id, 'cmn_pipeline_stage', 'new_lead');
        }
        $this->upsert_school_index($school_id);
        $this->insert_audit('school_needs_attention_resolved', 'school', $school_id, [
            'resolved_by' => (int) get_current_user_id(),
        ], (int) get_current_user_id());

        wp_safe_redirect(add_query_arg([
            'view' => 'schools',
            'cmn_imported' => '1',
            'cmn_import_msg' => rawurlencode('School marked as resolved.'),
        ], $redirect));
        exit;
    }

    public function handle_bulk_schools() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_bulk_schools_nonce']) || !wp_verify_nonce($_POST['cmn_bulk_schools_nonce'], 'cmn_bulk_schools')) {
            wp_die('Invalid request');
        }
        $action = sanitize_key((string) ($_POST['cmn_bulk_action'] ?? ''));
        $ids = isset($_POST['cmn_school_ids']) && is_array($_POST['cmn_school_ids']) ? array_values(array_unique(array_filter(array_map('intval', $_POST['cmn_school_ids'])))) : [];
        $redirect = esc_url_raw($_POST['cmn_redirect'] ?? '') ?: (wp_get_referer() ?: home_url('/portal'));

        if ($action === '' || $action === 'select') {
            wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Select a bulk action first.')], $redirect));
            exit;
        }
        $action_requires_selection = !in_array($action, ['share_groups'], true);
        if ($action_requires_selection && empty($ids)) {
            wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode('Select at least one school.')], $redirect));
            exit;
        }
        $message = 'Unknown bulk action.';
        if ($action === 'delete') {
            $deleted = 0;
            foreach ($ids as $id) {
                $post = get_post($id);
                if (!$post || $post->post_type !== 'cmn_school') {
                    continue;
                }
                wp_delete_post($id, true);
                $deleted++;
            }
            $message = 'Deleted ' . $deleted . ' school(s).';
        } elseif ($action === 'assign_manager') {
            if (!$this->is_admin_user()) {
                $message = 'Only admins can bulk-assign account managers.';
            } else {
                $manager_raw = sanitize_text_field((string) ($_POST['cmn_bulk_manager_id'] ?? ''));
                if ($manager_raw === '') {
                    $message = 'Select an account manager first.';
                } else {
                    $manager_id = ($manager_raw === '__clear__') ? 0 : (int) $manager_raw;
                    $updated = 0;
                    $failed = 0;
                    foreach ($ids as $id) {
                        $post = get_post($id);
                        if (!$post || $post->post_type !== 'cmn_school') {
                            continue;
                        }
                        $result = $this->assign_account_manager_to_school($id, $manager_id, 'bulk', (int) get_current_user_id());
                        if (!empty($result['ok'])) {
                            $updated++;
                        } else {
                            $failed++;
                        }
                    }
                    $message = 'Updated account manager on ' . $updated . ' school(s).';
                    if ($failed > 0) {
                        $message .= ' Failed: ' . $failed . '.';
                    }
                }
            }
        } elseif ($action === 'set_status') {
            $status = sanitize_key((string) ($_POST['cmn_bulk_status'] ?? ''));
            $allowed_statuses = ['lead', 'needs_attention', 'client', 'rejected', 'archived'];
            if (!in_array($status, $allowed_statuses, true)) {
                $message = 'Select a valid status first.';
            } else {
                $updated = 0;
                foreach ($ids as $id) {
                    $post = get_post($id);
                    if (!$post || $post->post_type !== 'cmn_school') {
                        continue;
                    }
                    update_post_meta($id, 'cmn_status', $status);
                    $pipeline_stage = sanitize_key((string) get_post_meta($id, 'cmn_pipeline_stage', true));
                    if ($status === 'client' && $pipeline_stage === '') {
                        update_post_meta($id, 'cmn_pipeline_stage', 'won');
                    } elseif (($status === 'lead' || $status === 'needs_attention') && $pipeline_stage === '') {
                        update_post_meta($id, 'cmn_pipeline_stage', 'new_lead');
                    }
                    $this->assert_imported_school_not_application_without_submission($id, 'bulk_set_status');
                    $updated++;
                }
                $message = 'Updated status for ' . $updated . ' school(s).';
            }
        } elseif ($action === 'set_pipeline') {
            $pipeline = sanitize_key((string) ($_POST['cmn_bulk_pipeline'] ?? ''));
            $allowed_pipeline = ['new_lead', 'contacted', 'demo', 'negotiation', 'won', 'lost'];
            if (!in_array($pipeline, $allowed_pipeline, true)) {
                $message = 'Select a valid pipeline stage first.';
            } else {
                $updated = 0;
                foreach ($ids as $id) {
                    $post = get_post($id);
                    if (!$post || $post->post_type !== 'cmn_school') {
                        continue;
                    }
                    update_post_meta($id, 'cmn_pipeline_stage', $pipeline);
                    $updated++;
                }
                $message = 'Updated pipeline stage for ' . $updated . ' school(s).';
            }
        } elseif ($action === 'assign_groups') {
            $labels = $this->parse_lead_group_labels((string) ($_POST['cmn_bulk_groups'] ?? ''));
            if (!$labels) {
                $message = 'Enter at least one group name.';
            } else {
                $actor_user_id = (int) get_current_user_id();
                $shared = !empty($_POST['cmn_bulk_groups_shared']);
                $group_slugs = $this->ensure_lead_groups($labels, $actor_user_id, $shared);
                if (!$group_slugs) {
                    $message = 'Unable to create/resolve lead groups.';
                } else {
                    $updated = 0;
                    foreach ($ids as $id) {
                        $post = get_post($id);
                        if (!$post || $post->post_type !== 'cmn_school') {
                            continue;
                        }
                        $existing = $this->get_school_lead_groups($id);
                        $merged = array_values(array_unique(array_merge($existing, $group_slugs)));
                        $this->set_school_lead_groups($id, $merged);
                        $updated++;
                    }
                    $message = 'Assigned group(s) to ' . $updated . ' school(s).';
                }
            }
        } elseif ($action === 'share_groups') {
            $labels = $this->parse_lead_group_labels((string) ($_POST['cmn_bulk_groups'] ?? ''));
            if (!$labels) {
                $message = 'Enter at least one group name to share.';
            } else {
                $shared_count = $this->mark_lead_groups_shared($labels, (int) get_current_user_id());
                $message = 'Shared ' . $shared_count . ' group(s) internally.';
            }
        } elseif ($action === 'remove_duplicates') {
            $result = $this->remove_duplicate_schools_in_selection($ids);
            $message = 'Removed ' . (int) ($result['removed'] ?? 0) . ' duplicate school(s), kept ' . (int) ($result['kept'] ?? 0) . '.';
            if (!empty($result['unkeyed'])) {
                $message .= ' Unkeyed rows skipped: ' . (int) $result['unkeyed'] . '.';
            }
        }

        wp_redirect(add_query_arg(['view' => 'schools', 'cmn_imported' => '1', 'cmn_import_msg' => rawurlencode($message)], $redirect));
        exit;
    }

    private function get_school_bulk_dedupe_key($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return '';
        }
        $school_code = strtoupper(trim((string) get_post_meta($school_id, 'cmn_school_id', true)));
        if ($school_code !== '') {
            return 'code:' . $school_code;
        }
        $domain = strtolower(trim((string) get_post_meta($school_id, 'cmn_school_email_domain', true)));
        if ($domain === '') {
            $email = strtolower(trim((string) get_post_meta($school_id, 'cmn_email', true)));
            if ($email !== '' && strpos($email, '@') !== false) {
                $parts = explode('@', $email);
                $domain = strtolower(trim((string) end($parts)));
            }
        }
        if ($domain !== '') {
            return 'domain:' . $domain;
        }
        $title = strtolower(trim((string) get_the_title($school_id)));
        $postcode = strtolower(trim((string) get_post_meta($school_id, 'cmn_postcode', true)));
        if ($title !== '' && $postcode !== '') {
            return 'name_postcode:' . $title . '|' . $postcode;
        }
        return '';
    }

    private function remove_duplicate_schools_in_selection($school_ids) {
        $result = [
            'removed' => 0,
            'kept' => 0,
            'unkeyed' => 0,
        ];
        $seen = [];
        foreach ((array) $school_ids as $school_id_raw) {
            $school_id = (int) $school_id_raw;
            if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
                continue;
            }
            $dedupe_key = $this->get_school_bulk_dedupe_key($school_id);
            if ($dedupe_key === '') {
                $result['unkeyed']++;
                continue;
            }
            if (!isset($seen[$dedupe_key])) {
                $seen[$dedupe_key] = $school_id;
                $result['kept']++;
                continue;
            }
            wp_delete_post($school_id, true);
            $result['removed']++;
        }
        return $result;
    }

    private function sanitize_lead_group_slug($value) {
        $slug = sanitize_title((string) $value);
        if ($slug === '') {
            return '';
        }
        return substr($slug, 0, 64);
    }

    private function parse_lead_group_labels($raw_labels) {
        $raw = is_array($raw_labels) ? implode(',', array_map('strval', $raw_labels)) : (string) $raw_labels;
        $parts = preg_split('/[\r\n,]+/', $raw) ?: [];
        $labels = [];
        foreach ($parts as $part) {
            $label = sanitize_text_field(trim((string) $part));
            if ($label === '') {
                continue;
            }
            $labels[] = $label;
        }
        return array_values(array_unique($labels));
    }

    private function get_lead_group_registry() {
        $raw = get_option('cmn_lead_group_registry', []);
        if (!is_array($raw)) {
            return [];
        }
        $registry = [];
        foreach ($raw as $slug => $entry) {
            $normalized_slug = $this->sanitize_lead_group_slug((string) $slug);
            if ($normalized_slug === '' || !is_array($entry)) {
                continue;
            }
            $name = sanitize_text_field((string) ($entry['name'] ?? $normalized_slug));
            if ($name === '') {
                $name = $normalized_slug;
            }
            $registry[$normalized_slug] = [
                'name' => $name,
                'owner_user_id' => (int) ($entry['owner_user_id'] ?? 0),
                'shared' => !empty($entry['shared']) ? 1 : 0,
                'created_at' => sanitize_text_field((string) ($entry['created_at'] ?? '')),
                'updated_at' => sanitize_text_field((string) ($entry['updated_at'] ?? '')),
            ];
        }
        return $registry;
    }

    private function save_lead_group_registry($registry) {
        if (!is_array($registry)) {
            $registry = [];
        }
        update_option('cmn_lead_group_registry', $registry, false);
    }

    private function get_visible_lead_groups_for_user($user_id = 0) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            $user_id = (int) get_current_user_id();
        }
        $registry = $this->get_lead_group_registry();
        if (!$registry) {
            return [];
        }
        $is_admin = $this->is_admin_user($user_id);
        $visible = [];
        foreach ($registry as $slug => $entry) {
            $owner_user_id = (int) ($entry['owner_user_id'] ?? 0);
            $is_shared = !empty($entry['shared']);
            if ($is_admin || $is_shared || ($owner_user_id > 0 && $owner_user_id === $user_id)) {
                $visible[$slug] = $entry;
            }
        }
        uasort($visible, static function ($a, $b) {
            $a_name = strtolower((string) ($a['name'] ?? ''));
            $b_name = strtolower((string) ($b['name'] ?? ''));
            return strcmp($a_name, $b_name);
        });
        return $visible;
    }

    private function ensure_lead_groups($labels, $owner_user_id, $shared = false) {
        $owner_user_id = (int) $owner_user_id;
        $shared = (bool) $shared;
        $label_list = $this->parse_lead_group_labels($labels);
        if (!$label_list) {
            return [];
        }
        $registry = $this->get_lead_group_registry();
        $changed = false;
        $now = current_time('mysql');
        $slugs = [];
        foreach ($label_list as $label) {
            $slug = $this->sanitize_lead_group_slug($label);
            if ($slug === '') {
                continue;
            }
            $slugs[] = $slug;
            if (!isset($registry[$slug])) {
                $registry[$slug] = [
                    'name' => $label,
                    'owner_user_id' => $owner_user_id,
                    'shared' => $shared ? 1 : 0,
                    'created_at' => $now,
                    'updated_at' => $now,
                ];
                $changed = true;
                continue;
            }
            $current = (array) $registry[$slug];
            $updated = false;
            if ((string) ($current['name'] ?? '') === '') {
                $current['name'] = $label;
                $updated = true;
            }
            if ((int) ($current['owner_user_id'] ?? 0) < 1 && $owner_user_id > 0) {
                $current['owner_user_id'] = $owner_user_id;
                $updated = true;
            }
            if ($shared && empty($current['shared'])) {
                $current['shared'] = 1;
                $updated = true;
            }
            if ($updated) {
                $current['updated_at'] = $now;
                $registry[$slug] = $current;
                $changed = true;
            }
        }
        if ($changed) {
            $this->save_lead_group_registry($registry);
        }
        return array_values(array_unique(array_filter(array_map([$this, 'sanitize_lead_group_slug'], $slugs))));
    }

    private function mark_lead_groups_shared($labels, $actor_user_id = 0) {
        $actor_user_id = (int) $actor_user_id;
        if ($actor_user_id < 1) {
            $actor_user_id = (int) get_current_user_id();
        }
        $is_admin = $this->is_admin_user($actor_user_id);
        $label_list = $this->parse_lead_group_labels($labels);
        if (!$label_list) {
            return 0;
        }
        $registry = $this->get_lead_group_registry();
        $changed = 0;
        $now = current_time('mysql');
        foreach ($label_list as $label) {
            $slug = $this->sanitize_lead_group_slug($label);
            if ($slug === '' || !isset($registry[$slug]) || !is_array($registry[$slug])) {
                continue;
            }
            $entry = (array) $registry[$slug];
            $owner_user_id = (int) ($entry['owner_user_id'] ?? 0);
            if (!$is_admin && $owner_user_id > 0 && $owner_user_id !== $actor_user_id) {
                continue;
            }
            if (empty($entry['shared'])) {
                $entry['shared'] = 1;
                $entry['updated_at'] = $now;
                $registry[$slug] = $entry;
                $changed++;
            }
        }
        if ($changed > 0) {
            $this->save_lead_group_registry($registry);
        }
        return (int) $changed;
    }

    private function get_school_lead_groups($school_id) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return [];
        }
        $raw = get_post_meta($school_id, 'cmn_lead_groups', true);
        $groups = [];
        if (is_array($raw)) {
            $groups = $raw;
        } elseif (is_string($raw) && $raw !== '') {
            $decoded = json_decode($raw, true);
            if (is_array($decoded)) {
                $groups = $decoded;
            } else {
                $groups = preg_split('/[\r\n,]+/', $raw) ?: [];
            }
        }
        $slugs = [];
        foreach ($groups as $value) {
            $slug = $this->sanitize_lead_group_slug((string) $value);
            if ($slug !== '') {
                $slugs[] = $slug;
            }
        }
        return array_values(array_unique($slugs));
    }

    private function set_school_lead_groups($school_id, $group_slugs) {
        $school_id = (int) $school_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return;
        }
        $slugs = [];
        foreach ((array) $group_slugs as $slug_raw) {
            $slug = $this->sanitize_lead_group_slug((string) $slug_raw);
            if ($slug !== '') {
                $slugs[] = $slug;
            }
        }
        $slugs = array_values(array_unique($slugs));
        if (!$slugs) {
            delete_post_meta($school_id, 'cmn_lead_groups');
            delete_post_meta($school_id, 'cmn_lead_groups_csv');
            return;
        }
        update_post_meta($school_id, 'cmn_lead_groups', $slugs);
        update_post_meta($school_id, 'cmn_lead_groups_csv', '|' . implode('|', $slugs) . '|');
    }

    public function handle_assign_contact_to_school() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_assign_contact_nonce']) || !wp_verify_nonce($_POST['cmn_assign_contact_nonce'], 'cmn_assign_contact')) {
            wp_die('Invalid request');
        }
        $contact_id = intval($_POST['cmn_contact_id'] ?? 0);
        $school_domain = sanitize_text_field($_POST['cmn_school_domain'] ?? '');
        if ($school_domain && !$this->user_can_access_school($school_domain)) {
            wp_die('Unauthorized');
        }
        if ($contact_id && $school_domain) {
            $is_primary = $this->get_contact_primary_school_id($contact_id) === '';
            $this->link_contact_to_school($contact_id, $school_domain, $is_primary);
            if ($is_primary) {
                $primary_post = $this->get_school_post_id_by_domain($school_domain);
                if ($primary_post) {
                    update_post_meta($contact_id, 'cmn_contact_school_id', $primary_post);
                }
            }
        }
        $redirect = esc_url_raw($_POST['cmn_redirect'] ?? '');
        if ($redirect) {
            wp_redirect($redirect);
        } else {
            $portal_page = cmn_get_page_by_title('Portal');
            $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
            wp_redirect(add_query_arg(['view' => 'schools'], $portal_url));
        }
        exit;
    }

    public function handle_unassign_contact() {
        if (!$this->is_staff_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_unassign_contact_nonce']) || !wp_verify_nonce($_POST['cmn_unassign_contact_nonce'], 'cmn_unassign_contact')) {
            wp_die('Invalid request');
        }
        $contact_id = intval($_POST['cmn_contact_id'] ?? 0);
        $school_domain = sanitize_text_field($_POST['cmn_school_domain'] ?? '');
        if ($school_domain && !$this->user_can_access_school($school_domain)) {
            wp_die('Unauthorized');
        }
        if ($contact_id && $school_domain) {
            $this->unlink_contact_from_school($contact_id, $school_domain);
            $primary = $this->get_contact_primary_school_id($contact_id);
            if ($primary === '') {
                delete_post_meta($contact_id, 'cmn_contact_school_id');
            }
        }
        $redirect = esc_url_raw($_POST['cmn_redirect'] ?? '');
        if ($redirect) {
            wp_redirect($redirect);
        } else {
            $portal_page = cmn_get_page_by_title('Portal');
            $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
            wp_redirect(add_query_arg(['view' => 'schools'], $portal_url));
        }
        exit;
    }

    public function handle_assign_account_manager() {
        if (!$this->is_admin_user()) {
            wp_die('Unauthorized');
        }
        if (!isset($_POST['cmn_assign_account_manager_nonce']) || !wp_verify_nonce($_POST['cmn_assign_account_manager_nonce'], 'cmn_assign_account_manager')) {
            wp_die('Invalid request');
        }
        $school_id = intval($_POST['cmn_school_id'] ?? 0);
        $manager_id = intval($_POST['cmn_account_manager_user'] ?? 0);
        if (!$school_id) {
            wp_die('Invalid school.');
        }
        $assignment = $this->assign_account_manager_to_school($school_id, $manager_id, 'manual', get_current_user_id());
        if (empty($assignment['ok'])) {
            wp_die(esc_html((string) ($assignment['message'] ?? 'Unable to update account manager assignment.')));
        }
        $redirect = esc_url_raw($_POST['cmn_redirect'] ?? '');
        if ($redirect) {
            wp_redirect($redirect);
        } else {
            $portal_page = cmn_get_page_by_title('Portal');
            $portal_url = $portal_page ? get_permalink($portal_page) : home_url('/portal');
            $school_code = get_post_meta($school_id, 'cmn_school_id', true);
            wp_redirect(add_query_arg(['view' => 'schools', 'school_id' => $school_code], $portal_url));
        }
        exit;
    }

    private function assign_account_manager_to_school($school_id, $manager_id, $source = 'manual', $actor_user_id = 0) {
        $school_id = (int) $school_id;
        $manager_id = (int) $manager_id;
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return ['ok' => false, 'message' => 'Invalid school.'];
        }
        $previous_manager_id = (int) get_post_meta($school_id, 'cmn_account_manager_user', true);
        if ($previous_manager_id < 1) {
            $previous_manager_id = (int) get_post_meta($school_id, 'cmn_account_manager_user_id', true);
        }

        $manager = null;
        if ($manager_id > 0) {
            $manager = get_user_by('id', $manager_id);
            if (!$manager) {
                return ['ok' => false, 'message' => 'Selected account manager was not found.'];
            }
            $roles = array_map('strval', (array) $manager->roles);
            $allowed_roles = ['cmn_account_manager', 'cmn_admin', 'administrator', 'cmn_staff'];
            if (empty(array_intersect($allowed_roles, $roles))) {
                return ['ok' => false, 'message' => 'Selected user must be account manager, staff, or admin.'];
            }
            update_post_meta($school_id, 'cmn_account_manager_user', (int) $manager_id);
            update_post_meta($school_id, 'cmn_account_manager_user_id', (int) $manager_id);
            update_post_meta($school_id, 'cmn_account_manager', sanitize_text_field((string) $manager->display_name));
            update_post_meta($school_id, 'cmn_account_manager_name', sanitize_text_field((string) $manager->display_name));
            update_post_meta($school_id, 'cmn_account_manager_email', sanitize_email((string) $manager->user_email));
        } else {
            delete_post_meta($school_id, 'cmn_account_manager_user');
            delete_post_meta($school_id, 'cmn_account_manager_user_id');
            delete_post_meta($school_id, 'cmn_account_manager');
            delete_post_meta($school_id, 'cmn_account_manager_name');
            delete_post_meta($school_id, 'cmn_account_manager_email');
        }

        $requests_synced = $this->sync_school_request_account_manager($school_id, $manager_id);
        $notifications_sent = $this->notify_school_account_manager_assignment(
            $school_id,
            $previous_manager_id,
            $manager_id,
            (string) $source,
            (int) $actor_user_id
        );

        return [
            'ok' => true,
            'school_id' => (int) $school_id,
            'manager_id' => (int) $manager_id,
            'previous_manager_id' => (int) $previous_manager_id,
            'requests_synced' => (int) $requests_synced,
            'notifications_sent' => (int) $notifications_sent,
        ];
    }

    private function sync_school_request_account_manager($school_id, $manager_id) {
        global $wpdb;
        $school_id = (int) $school_id;
        $manager_id = max(0, (int) $manager_id);
        if ($school_id < 1) {
            return 0;
        }
        $table = $this->get_candidate_requests_table();
        $columns = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
        if (!in_array('account_manager_user_id', $columns, true)) {
            return 0;
        }
        $has_updated_at = in_array('updated_at', $columns, true);
        $has_school_id = in_array('school_id', $columns, true);
        $has_school_domain = in_array('school_email_domain', $columns, true);
        $updated_total = 0;
        $now = current_time('mysql');

        if ($has_school_id) {
            if ($has_updated_at) {
                $updated = (int) $wpdb->query($wpdb->prepare(
                    "UPDATE {$table} SET account_manager_user_id = %d, updated_at = %s WHERE school_id = %d",
                    $manager_id,
                    $now,
                    $school_id
                ));
            } else {
                $updated = (int) $wpdb->query($wpdb->prepare(
                    "UPDATE {$table} SET account_manager_user_id = %d WHERE school_id = %d",
                    $manager_id,
                    $school_id
                ));
            }
            if ($updated > 0) {
                $updated_total += $updated;
            }
        }

        $school_domain = strtolower(trim((string) get_post_meta($school_id, 'cmn_school_email_domain', true)));
        if ($school_domain !== '' && $has_school_id && $has_school_domain) {
            if ($has_updated_at) {
                $updated = (int) $wpdb->query($wpdb->prepare(
                    "UPDATE {$table} SET account_manager_user_id = %d, updated_at = %s WHERE (school_id IS NULL OR school_id = 0) AND school_email_domain = %s",
                    $manager_id,
                    $now,
                    $school_domain
                ));
            } else {
                $updated = (int) $wpdb->query($wpdb->prepare(
                    "UPDATE {$table} SET account_manager_user_id = %d WHERE (school_id IS NULL OR school_id = 0) AND school_email_domain = %s",
                    $manager_id,
                    $school_domain
                ));
            }
            if ($updated > 0) {
                $updated_total += $updated;
            }
        }

        return (int) $updated_total;
    }

    private function notify_school_account_manager_assignment($school_id, $previous_manager_id, $manager_id, $source = 'manual', $actor_user_id = 0) {
        $school_id = (int) $school_id;
        $previous_manager_id = max(0, (int) $previous_manager_id);
        $manager_id = max(0, (int) $manager_id);
        if ($school_id < 1 || get_post_type($school_id) !== 'cmn_school') {
            return 0;
        }
        if ($previous_manager_id === $manager_id) {
            return 0;
        }
        $school_name = trim((string) get_the_title($school_id));
        if ($school_name === '') {
            $school_name = 'School #' . $school_id;
        }
        $school_code = trim((string) get_post_meta($school_id, 'cmn_school_id', true));
        $school_label = $school_code !== '' ? ($school_name . ' (' . $school_code . ')') : $school_name;
        $school_url = add_query_arg(['view' => 'schools', 'school_id' => $school_id], $this->get_portal_base_url());
        $actor_id = $actor_user_id > 0 ? (int) $actor_user_id : (int) get_current_user_id();
        $actor_user = $actor_id > 0 ? get_user_by('id', $actor_id) : null;
        $actor_name = ($actor_user && !empty($actor_user->display_name)) ? (string) $actor_user->display_name : 'System';
        $secure_chat_url = '';
        $thread_for_email = $this->create_or_get_school_request_thread($school_id, $actor_user_id);
        if (is_array($thread_for_email) && !empty($thread_for_email['id'])) {
            $this->sync_school_request_thread_participants((int) $thread_for_email['id'], $school_id);
            $token_for_email = $this->issue_school_request_chat_token((int) $thread_for_email['id'], $school_id, $actor_user_id);
            if (!empty($token_for_email['token'])) {
                $secure_chat_url = $this->get_school_request_chat_secure_url($school_id, (string) $token_for_email['token']);
            }
        }
        $source_label = strtolower(trim((string) $source)) === 'automation' ? 'automation rule' : 'portal';
        $notification_count = 0;

        $new_manager = $manager_id > 0 ? get_user_by('id', $manager_id) : null;
        $new_manager_name = ($new_manager && !empty($new_manager->display_name))
            ? (string) $new_manager->display_name
            : 'Unassigned';

        if ($manager_id > 0 && $new_manager) {
            $manager_message = ($previous_manager_id > 0 && $previous_manager_id !== $manager_id)
                ? ('An account has been moved into your name: ' . $school_label . '.')
                : ('A school account has been assigned to you: ' . $school_label . '.');
            if ($source_label === 'automation rule') {
                $manager_message .= ' (automation rule)';
            }
            $insert_id = $this->add_notification(
                $manager_id,
                'account_assignment',
                'Account assigned',
                $manager_message,
                $school_url
            );
            if ($insert_id > 0) {
                $notification_count++;
            }
        }

        if ($previous_manager_id > 0 && $previous_manager_id !== $manager_id) {
            $insert_id = $this->add_notification(
                $previous_manager_id,
                'account_assignment_removed',
                'Account reassigned',
                'This account is no longer assigned to you: ' . $school_label . '.',
                $school_url
            );
            if ($insert_id > 0) {
                $notification_count++;
            }
        }

        $admin_message = $manager_id > 0
            ? ($school_label . ' is now assigned to ' . $new_manager_name . '. Updated by ' . $actor_name . ' via ' . $source_label . '.')
            : ($school_label . ' has been unassigned from an account manager. Updated by ' . $actor_name . ' via ' . $source_label . '.');
        foreach ($this->get_admin_users_for_support() as $admin_id) {
            $admin_id = (int) $admin_id;
            if ($admin_id < 1 || $admin_id === $manager_id) {
                continue;
            }
            $insert_id = $this->add_notification(
                $admin_id,
                'account_assignment_admin',
                'Account manager updated',
                $admin_message,
                $school_url
            );
            if ($insert_id > 0) {
                $notification_count++;
            }
        }

        return (int) $notification_count;
    }

    private function read_csv_headers($file) {
        $handle = fopen($file, 'r');
        if (!$handle) {
            return [];
        }
        $header = fgetcsv($handle);
        fclose($handle);
        if (!$header) {
            return [];
        }
        return array_map('trim', $header);
    }

    private function read_spreadsheet_headers($file, $ext) {
        $ext = strtolower($ext);
        if ($ext === 'xlsx') {
            $rows = $this->read_xlsx_rows($file);
            if (!$rows) {
                return [];
            }
            $header = $rows[0] ?? [];
            return array_map('trim', array_map('strval', $header));
        }
        return $this->read_csv_headers($file);
    }

    private function read_spreadsheet_rows($file, $ext) {
        $ext = strtolower($ext);
        if ($ext === 'xlsx') {
            return $this->read_xlsx_rows($file);
        }
        return $this->read_csv_rows($file);
    }

    private function read_csv_rows($file) {
        $handle = fopen($file, 'r');
        if (!$handle) {
            return [];
        }
        $rows = [];
        while (($row = fgetcsv($handle)) !== false) {
            $rows[] = $row;
        }
        fclose($handle);
        return $rows;
    }

    private function read_xlsx_rows($file) {
        if (!class_exists('ZipArchive')) {
            return [];
        }
        $zip = new ZipArchive();
        if ($zip->open($file) !== true) {
            return [];
        }
        $shared = $this->read_xlsx_shared_strings($zip);
        $sheetXml = $this->read_xlsx_sheet_xml($zip);
        if (!$sheetXml) {
            $zip->close();
            return [];
        }
        $xml = simplexml_load_string($sheetXml);
        if (!$xml || !isset($xml->sheetData)) {
            $zip->close();
            return [];
        }
        $rows = [];
        foreach ($xml->sheetData->row as $row) {
            $cells = [];
            foreach ($row->c as $c) {
                $ref = (string) $c['r'];
                $type = (string) $c['t'];
                $value = '';
                if ($type === 's') {
                    $idx = isset($c->v) ? (int) $c->v : -1;
                    $value = $idx >= 0 && isset($shared[$idx]) ? $shared[$idx] : '';
                } elseif ($type === 'inlineStr') {
                    $value = isset($c->is->t) ? (string) $c->is->t : '';
                } else {
                    $value = isset($c->v) ? (string) $c->v : '';
                }
                $colIndex = $this->xlsx_col_to_index($ref);
                if ($colIndex !== null) {
                    $cells[$colIndex] = $value;
                }
            }
            if (!$cells) {
                $rows[] = [];
                continue;
            }
            $maxIndex = max(array_keys($cells));
            $rowData = [];
            for ($i = 0; $i <= $maxIndex; $i++) {
                $rowData[$i] = $cells[$i] ?? '';
            }
            $rows[] = $rowData;
        }
        $zip->close();
        return $rows;
    }

    private function read_xlsx_shared_strings($zip) {
        $strings = [];
        $sharedXml = $zip->getFromName('xl/sharedStrings.xml');
        if (!$sharedXml) {
            return $strings;
        }
        $xml = simplexml_load_string($sharedXml);
        if (!$xml) {
            return $strings;
        }
        foreach ($xml->si as $si) {
            $text = '';
            if (isset($si->t)) {
                $text = (string) $si->t;
            } else {
                foreach ($si->r as $r) {
                    $text .= (string) $r->t;
                }
            }
            $strings[] = $text;
        }
        return $strings;
    }

    private function read_xlsx_sheet_xml($zip) {
        $sheetXml = $zip->getFromName('xl/worksheets/sheet1.xml');
        if ($sheetXml) {
            return $sheetXml;
        }
        for ($i = 1; $i <= 5; $i++) {
            $name = 'xl/worksheets/sheet' . $i . '.xml';
            $sheetXml = $zip->getFromName($name);
            if ($sheetXml) {
                return $sheetXml;
            }
        }
        return '';
    }

    private function xlsx_col_to_index($ref) {
        if (!preg_match('/^([A-Z]+)/i', $ref, $match)) {
            return null;
        }
        $letters = strtoupper($match[1]);
        $index = 0;
        $len = strlen($letters);
        for ($i = 0; $i < $len; $i++) {
            $index = $index * 26 + (ord($letters[$i]) - 64);
        }
        return $index - 1;
    }

    private function csv_value($row, $index) {
        if ($index === '' || $index === null) {
            return '';
        }
        $idx = (int) $index;
        return isset($row[$idx]) ? trim((string) $row[$idx]) : '';
    }

    private function parse_pasted_csv_rows($raw_text) {
        $raw_text = (string) $raw_text;
        if (trim($raw_text) === '') {
            return [];
        }
        $normalized = str_replace(["\r\n", "\r"], "\n", $raw_text);
        $lines = explode("\n", $normalized);
        $rows = [];
        $max_cols = 0;
        foreach ($lines as $line) {
            if (trim($line) === '') {
                continue;
            }
            $parsed = str_getcsv($line);
            if (!is_array($parsed)) {
                continue;
            }
            $parsed = array_map(static function ($value) {
                return trim((string) $value);
            }, $parsed);
            $rows[] = $parsed;
            $max_cols = max($max_cols, count($parsed));
        }
        if ($max_cols > 0) {
            foreach ($rows as &$row) {
                if (count($row) < $max_cols) {
                    $row = array_pad($row, $max_cols, '');
                }
            }
            unset($row);
        }
        return $rows;
    }

    private function import_schools_spreadsheet_mapped($file, $map, $ext) {
        $rows = $this->read_spreadsheet_rows($file, $ext);
        if (!$rows) {
            return 'No rows found.';
        }
        $header = array_shift($rows);
        if (!$header) {
            return 'Empty spreadsheet.';
        }
        $count = 0;
        $skipped = 0;
        $needs_attention = 0;

        $created = 0;
        $updated = 0;
        $contact_warnings = 0;
        $batch_id = 'IMP-' . gmdate('YmdHis') . '-' . wp_generate_password(6, false, false);
        foreach ($rows as $row) {
            $school_name = $this->csv_value($row, $map['cmn_school_name'] ?? '');
            $location = $this->csv_value($row, $map['cmn_location'] ?? '');
            $phone = $this->csv_value($row, $map['cmn_phone'] ?? '');
            $school_email = $this->csv_value($row, $map['cmn_email'] ?? '');
            $cover_manager_name = $this->csv_value($row, $map['cmn_cover_manager'] ?? '');
            $cover_manager_email = $this->csv_value($row, $map['cmn_cover_manager_email'] ?? '');
            $email_name = $this->csv_value($row, $map['cmn_email_name'] ?? '');
            $row_has_any_data = (
                $school_name !== '' ||
                $location !== '' ||
                $phone !== '' ||
                $school_email !== '' ||
                $cover_manager_name !== '' ||
                $cover_manager_email !== '' ||
                $email_name !== ''
            );
            if (!$row_has_any_data) {
                $skipped += 1;
                continue;
            }

            if ($school_name === '') {
                // Cannot create a usable school record without a name.
                $skipped += 1;
                continue;
            }

            $import_issues = [];
            if ($location === '') {
                $import_issues[] = 'Missing location';
            }
            if ($phone === '') {
                $import_issues[] = 'Missing contact number';
            } elseif (strlen(preg_replace('/\\D+/', '', $phone)) < 7) {
                $import_issues[] = 'Invalid contact number';
            }
            if ($cover_manager_name === '') {
                $import_issues[] = 'Missing cover manager name';
            }
            if ($cover_manager_email === '') {
                $import_issues[] = 'Missing cover manager email';
            } elseif (!is_email($cover_manager_email)) {
                $import_issues[] = 'Invalid cover manager email';
            }
            // Rule: school email follows cover manager email when available.
            if ($cover_manager_email !== '' && is_email($cover_manager_email)) {
                $school_email = $cover_manager_email;
            }
            if ($school_email === '') {
                $import_issues[] = 'Missing school email';
            } elseif (!is_email($school_email)) {
                $import_issues[] = 'Invalid school email';
            }
            if ($email_name === '') {
                $import_issues[] = 'Missing email name';
            }

            $school_domain = '';
            if ($school_email !== '' && is_email($school_email)) {
                $school_domain = $this->get_email_domain($school_email);
                if ($school_domain === '') {
                    $import_issues[] = 'Invalid school email domain';
                }
            }

            $school_code = $this->csv_value($row, $map['cmn_school_id'] ?? '');
            if (!preg_match('/^CMN\\d+$/i', $school_code)) {
                $school_code = '';
            }
            $existing_id = 0;
            if ($school_code !== '') {
                $existing_id = $this->get_school_post_id_by_school_id($school_code);
            }
            if (!$existing_id && $school_domain !== '') {
                $existing_id = $this->get_school_post_id_by_domain($school_domain);
            }
            if ($existing_id) {
                $post_id = $existing_id;
                wp_update_post([
                    'ID' => $post_id,
                    'post_title' => $school_name,
                ]);
                $updated++;
            } else {
                $post_id = wp_insert_post([
                    'post_type' => 'cmn_school',
                    'post_title' => $school_name,
                    'post_status' => 'publish',
                ]);
                if (is_wp_error($post_id)) {
                    $skipped += 1;
                    continue;
                }
                $created++;
            }
            if ($school_domain !== '') {
                $domain_owner = $this->get_school_post_id_by_domain($school_domain);
                if ($domain_owner && (int) $domain_owner !== (int) $post_id) {
                    $skipped += 1;
                    continue;
                }
            }

            if ($school_code === '') {
                $school_code = get_post_meta($post_id, 'cmn_school_id', true);
                if ($school_code === '') {
                    $school_code = $this->generate_school_id();
                }
            }
            $existing_status = sanitize_key((string) get_post_meta($post_id, 'cmn_status', true));
            $status = $existing_id ? ($existing_status !== '' ? $existing_status : 'lead') : 'lead';
            if (!in_array($status, ['lead', 'client', 'archived', 'rejected', 'needs_attention'], true)) {
                $status = 'lead';
            }
            if (!empty($import_issues)) {
                $status = 'needs_attention';
                $needs_attention++;
            }

            $meta = [
                'cmn_location' => $location,
                'cmn_phone' => $phone,
                'cmn_cover_manager' => $cover_manager_name,
                'cmn_cover_manager_email' => $cover_manager_email,
                'cmn_account_manager' => $this->csv_value($row, $map['cmn_account_manager'] ?? ''),
                'cmn_email' => $school_email,
                'cmn_email_name' => $email_name,
                'cmn_spoke_to_cm' => $this->csv_value($row, $map['cmn_spoke_to_cm'] ?? ''),
                'cmn_switchboard' => $this->csv_value($row, $map['cmn_switchboard'] ?? ''),
                'cmn_website' => $this->csv_value($row, $map['cmn_website'] ?? ''),
                'cmn_school_id' => $school_code,
                'cmn_status' => $status,
                'cmn_pipeline_stage' => $this->csv_value($row, $map['cmn_pipeline_stage'] ?? '') ?: 'new_lead',
            ];
            if ($school_domain !== '') {
                $meta['cmn_school_email_domain'] = $school_domain;
            }
            if ($meta['cmn_status'] === 'client' && $meta['cmn_pipeline_stage'] !== 'lost') {
                $meta['cmn_pipeline_stage'] = $meta['cmn_pipeline_stage'] ?: 'won';
            }
            foreach ($meta as $key => $value) {
                update_post_meta($post_id, $key, sanitize_text_field($value));
            }
            $this->store_cover_manager_split($post_id, $cover_manager_name);
            $this->upsert_school_index($post_id);
            update_post_meta($post_id, 'cmn_import_batch_id', $batch_id);
            update_post_meta($post_id, 'cmn_bulk_import_key', $batch_id . ':' . $count);
            if (!empty($import_issues)) {
                update_post_meta($post_id, 'cmn_import_issues', wp_json_encode($import_issues));
            } else {
                delete_post_meta($post_id, 'cmn_import_issues');
            }
            $source_row = [];
            foreach ((array) $header as $idx => $col_name) {
                $normalized_col_name = trim((string) $col_name);
                if ($normalized_col_name === '') {
                    $normalized_col_name = 'column_' . ((int) $idx + 1);
                }
                $source_row[$normalized_col_name] = isset($row[$idx]) ? trim((string) $row[$idx]) : '';
            }
            update_post_meta($post_id, 'cmn_import_source_row', wp_json_encode($source_row));

            $contact_name = $this->csv_value($row, $map['cmn_contact_name'] ?? '');
            $contact_email = $this->csv_value($row, $map['cmn_contact_email'] ?? '');
            $contact_phone = $this->csv_value($row, $map['cmn_contact_phone'] ?? '');
            $contact_role = $this->csv_value($row, $map['cmn_contact_role'] ?? '');
            if ($contact_name !== '') {
                $contact_id = $this->create_or_update_contact([
                    'name' => $contact_name,
                    'email' => $contact_email,
                    'phone' => $contact_phone,
                    'role' => $contact_role,
                    'school_id' => $post_id,
                    'school_domain' => $school_domain,
                    'is_primary' => true,
                ]);
                if (!$contact_id) {
                    $contact_warnings++;
                } else {
                    update_post_meta($post_id, 'cmn_contact1', $contact_name);
                    update_post_meta($post_id, 'cmn_contact1_email', $contact_email);
                    update_post_meta($post_id, 'cmn_contact_role', $contact_role);
                    update_post_meta($post_id, 'cmn_primary_contact_name', $contact_name);
                    update_post_meta($post_id, 'cmn_primary_contact_email', $contact_email ?: $school_email);
                    update_post_meta($post_id, 'cmn_primary_contact_phone', $contact_phone ?: $phone);
                    update_post_meta($post_id, 'cmn_primary_contact_role', $contact_role);
                }
            }
            $this->assert_imported_school_not_application_without_submission((int) $post_id, 'bulk_import_row');
            $count += 1;
        }
        $message = 'Imported ' . $count . ' schools (' . $created . ' new, ' . $updated . ' updated).';
        if ($needs_attention > 0) {
            $message .= ' Needs attention: ' . $needs_attention . '.';
        }
        if ($skipped > 0) {
            $message .= ' Skipped ' . $skipped . ' empty or unusable rows.';
        }
        if ($contact_warnings > 0) {
            $message .= ' Contact warnings: ' . $contact_warnings . '.';
        }
        return $message;
    }

    private function import_contacts_spreadsheet_mapped($file, $map, $ext) {
        $rows = $this->read_spreadsheet_rows($file, $ext);
        if (!$rows) {
            return 'No rows found.';
        }
        $header = array_shift($rows);
        if (!$header) {
            return 'Empty spreadsheet.';
        }

        $count = 0;
        $created = 0;
        $updated = 0;
        $skipped = 0;
        $warnings = 0;

        foreach ($rows as $row) {
            $name = $this->csv_value($row, $map['cmn_contact_name'] ?? '');
            if ($name === '') {
                $skipped++;
                continue;
            }
            $email = $this->csv_value($row, $map['cmn_contact_email'] ?? '');
            $phone = $this->csv_value($row, $map['cmn_contact_phone'] ?? '');
            $role = $this->csv_value($row, $map['cmn_contact_role'] ?? '');
            if ($email && !is_email($email)) {
                $skipped++;
                $warnings++;
                continue;
            }
            $school_domain = '';
            $school_identifier = $this->csv_value($row, $map['cmn_contact_school_id'] ?? '');
            if ($school_identifier !== '') {
                $post_id = $this->get_school_post_id_by_school_id($school_identifier);
                if ($post_id) {
                    $school_domain = (string) get_post_meta($post_id, 'cmn_school_email_domain', true);
                } else {
                    $warnings++;
                }
            }
            if ($school_domain === '') {
                $school_email = $this->csv_value($row, $map['cmn_contact_school_email'] ?? '');
                if ($school_email !== '') {
                    $school_domain = $this->get_email_domain($school_email);
                    if ($school_domain === '') {
                        $warnings++;
                    }
                }
            }
            if ($school_domain === '') {
                $school_name = $this->csv_value($row, $map['cmn_contact_school_name'] ?? '');
                if ($school_name !== '') {
                    $ambiguous = false;
                    $school_domain = $this->find_school_domain_by_name($school_name, $ambiguous);
                    if ($ambiguous || $school_domain === '') {
                        $warnings++;
                        $school_domain = '';
                    }
                }
            }

            $existing_id = 0;
            if ($email) {
                $existing = get_posts([
                    'post_type' => 'cmn_contact',
                    'posts_per_page' => 1,
                    'fields' => 'ids',
                    'meta_query' => [
                        [
                            'key' => 'cmn_contact_email',
                            'value' => $email,
                        ],
                    ],
                ]);
                if ($existing) {
                    $existing_id = (int) $existing[0];
                }
            }

            $contact_id = $this->create_or_update_contact([
                'name' => $name,
                'email' => $email,
                'phone' => $phone,
                'role' => $role,
                'school_id' => 0,
            ]);
            if (!$contact_id) {
                $skipped++;
                continue;
            }
            if ($school_domain) {
                $this->link_contact_to_school($contact_id, $school_domain, true);
                $primary_post = $this->get_school_post_id_by_domain($school_domain);
                if ($primary_post) {
                    update_post_meta($contact_id, 'cmn_contact_school_id', $primary_post);
                }
            }
            if ($existing_id) {
                $updated++;
            } else {
                $created++;
            }
            $count++;
        }

        $message = 'Imported ' . $count . ' contacts (' . $created . ' new, ' . $updated . ' updated).';
        if ($skipped > 0) {
            $message .= ' Skipped ' . $skipped . ' rows with missing or invalid required fields.';
        }
        if ($warnings > 0) {
            $message .= ' Warnings: ' . $warnings . '.';
        }
        return $message;
    }

    public function school_columns($columns) {
        $new = [];
        $new['cb'] = $columns['cb'];
        $new['title'] = 'School';
        $new['cmn_location'] = 'Location';
        $new['cmn_phone'] = 'Phone';
        $new['cmn_email'] = 'Email';
        $new['cmn_status'] = 'Status';
        $new['date'] = $columns['date'];
        return $new;
    }

