/*
 * Centralized portal authorization layer for Rewards / School Partner / Finance / Payroll.
 *
 * Capability map (single source of truth):
 * - rewards.view_self
 * - rewards.view_any
 * - rewards.mutate_any
 * - school_partner.view_self
 * - school_partner.mutate_self
 * - school_partner.view_any
 * - school_partner.mutate_any
 * - finance.view_self
 * - finance.view_any
 * - finance.mutate_any
 * - payroll.view_any
 * - payroll.run
 * - payroll.override
 *
 * Acceptance tests:
 * 1) Candidate can access rewards.view_self but not rewards.view_any.
 * 2) School can confirm its own booking only when booking context belongs to that school.
 * 3) Staff can view and mutate rewards/partner/finance across entities.
 * 4) Admin can run payroll override.
 */
if (!function_exists('cmn_role_from_user')) {
    function cmn_role_from_user($user_id) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return 'guest';
        }

        $user = get_user_by('id', $user_id);
        if (!$user instanceof WP_User) {
            return 'guest';
        }

        $roles = array_map('strtolower', (array) $user->roles);
        if (in_array('administrator', $roles, true) || in_array('cmn_admin', $roles, true)) {
            return 'admin';
        }
        if (in_array('cmn_staff', $roles, true) || in_array('cmn_account_manager', $roles, true)) {
            return 'staff';
        }
        if (in_array('cmn_school_manager', $roles, true) || in_array('cmn_school_staff', $roles, true)) {
            return 'school';
        }
        if (in_array('cmn_candidate', $roles, true) || in_array('cmn_candidate_pending', $roles, true) || in_array('candidate', $roles, true)) {
            return 'candidate';
        }
        return 'guest';
    }
}

if (!function_exists('cmn_is_system_context')) {
    function cmn_is_system_context($context = []) {
        $context = is_array($context) ? $context : [];
        if (isset($context['actor_role']) && strtolower((string) $context['actor_role']) === 'system') {
            return true;
        }
        if (!empty($context['system_actor']) || !empty($context['system_context'])) {
            return true;
        }
        if (function_exists('wp_doing_cron') && wp_doing_cron()) {
            return true;
        }
        if (defined('DOING_CRON') && DOING_CRON) {
            return true;
        }
        if ((defined('WP_CLI') && WP_CLI) || php_sapi_name() === 'cli') {
            return true;
        }
        return false;
    }
}

if (!function_exists('cmn_extract_booking_school_id')) {
    function cmn_extract_booking_school_id($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking') {
            return 0;
        }
        $school_id = (int) get_post_meta($booking_id, 'cmn_school_id', true);
        return $school_id > 0 ? $school_id : 0;
    }
}

if (!function_exists('cmn_extract_booking_candidate_id')) {
    function cmn_extract_booking_candidate_id($booking_id) {
        $booking_id = (int) $booking_id;
        if ($booking_id < 1 || get_post_type($booking_id) !== 'cmn_booking') {
            return 0;
        }
        $candidate_id = (int) get_post_meta($booking_id, 'cmn_candidate_id', true);
        return $candidate_id > 0 ? $candidate_id : 0;
    }
}

if (!function_exists('cmn_school_context_matches_user')) {
    function cmn_school_context_matches_user($user_id, array $context, $require_explicit_context = false) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return false;
        }

        $school_identifier = null;
        if (!empty($context['school_id'])) {
            $school_identifier = (int) $context['school_id'];
        } elseif (!empty($context['school_identifier'])) {
            $school_identifier = $context['school_identifier'];
        } elseif (!empty($context['school_domain'])) {
            $school_identifier = strtolower(trim((string) $context['school_domain']));
        } elseif (!empty($context['booking_id'])) {
            $school_id = cmn_extract_booking_school_id($context['booking_id']);
            if ($school_id > 0) {
                $school_identifier = $school_id;
            }
        }

        if ($school_identifier === null || $school_identifier === '') {
            return !$require_explicit_context;
        }

        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if ($plugin instanceof CMN_One_Plugin && is_callable([$plugin, 'user_can_access_school'])) {
            return (bool) $plugin->user_can_access_school($school_identifier, $user_id);
        }

        $mapped_school_id = (int) get_user_meta($user_id, 'cmn_school_id', true);
        if (is_numeric($school_identifier)) {
            return $mapped_school_id > 0 && $mapped_school_id === (int) $school_identifier;
        }
        return false;
    }
}

if (!function_exists('cmn_candidate_context_matches_user')) {
    function cmn_candidate_context_matches_user($user_id, array $context, $require_explicit_context = false) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return false;
        }

        $candidate_id = 0;
        if (!empty($context['candidate_id'])) {
            $candidate_id = (int) $context['candidate_id'];
        } elseif (!empty($context['booking_id'])) {
            $candidate_id = cmn_extract_booking_candidate_id($context['booking_id']);
        }

        if ($candidate_id > 0) {
            $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
            if ($plugin instanceof CMN_One_Plugin && is_callable([$plugin, 'user_can_view_candidate'])) {
                return (bool) $plugin->user_can_view_candidate($candidate_id, $user_id);
            }
        }

        if (!empty($context['candidate_user_id'])) {
            return (int) $context['candidate_user_id'] === $user_id;
        }

        return !$require_explicit_context;
    }
}

if (!function_exists('cmn_can')) {
    function cmn_can($user_id, $ability, $context = []) {
        $context = is_array($context) ? $context : [];
        $ability = trim((string) $ability);
        if ($ability === '') {
            return false;
        }

        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return cmn_is_system_context($context);
        }

        $role = cmn_role_from_user($user_id);
        $is_admin = $role === 'admin';
        $is_staff_or_admin = $is_admin || $role === 'staff';

        switch ($ability) {
            case 'rewards.view_self':
                return $role === 'candidate';
            case 'rewards.view_any':
            case 'rewards.mutate_any':
                return $is_staff_or_admin;

            case 'school_partner.view_self':
                return $role === 'school' && cmn_school_context_matches_user($user_id, $context, false);
            case 'school_partner.mutate_self':
                return $role === 'school' && cmn_school_context_matches_user($user_id, $context, true);
            case 'school_partner.view_any':
            case 'school_partner.mutate_any':
                return $is_staff_or_admin;

            case 'finance.view_self':
                if ($role === 'candidate') {
                    return cmn_candidate_context_matches_user($user_id, $context, false);
                }
                if ($role === 'school') {
                    return cmn_school_context_matches_user($user_id, $context, false);
                }
                return false;
            case 'finance.view_any':
            case 'finance.mutate_any':
                return $is_staff_or_admin;

            case 'payroll.view_any':
            case 'payroll.mutate_any':
            case 'payroll.run':
                return $is_staff_or_admin;
            case 'payroll.override':
                return $is_admin;
        }

        return false;
    }
}

if (!function_exists('cmn_require_login')) {
    function cmn_require_login() {
        if (is_user_logged_in()) {
            return true;
        }
        if (cmn_is_system_context()) {
            return true;
        }
        return new WP_Error('cmn_auth_required', 'Not authorised', ['status' => 401]);
    }
}

if (!function_exists('cmn_require_nonce')) {
    function cmn_require_nonce($action, $nonce_field = 'nonce') {
        $action = (string) $action;
        $nonce_field = trim((string) $nonce_field);
        if ($action === '' || $nonce_field === '') {
            return new WP_Error('cmn_invalid_nonce_config', 'Invalid request.', ['status' => 403]);
        }

        $nonce = isset($_REQUEST[$nonce_field]) ? sanitize_text_field((string) wp_unslash($_REQUEST[$nonce_field])) : '';
        if ($nonce === '' || !wp_verify_nonce($nonce, $action)) {
            return new WP_Error('cmn_invalid_nonce', 'Invalid request.', ['status' => 403]);
        }
        return true;
    }
}

if (!function_exists('cmn_get_bank_encryption_key_from_config')) {
    function cmn_get_bank_encryption_key_from_config() {
        $encoded_key = '';
        if (defined('CMN_BANK_ENC_KEY')) {
            $encoded_key = trim((string) CMN_BANK_ENC_KEY);
        }
        if ($encoded_key === '') {
            $env_value = getenv('CMN_BANK_ENC_KEY');
            if (is_string($env_value)) {
                $encoded_key = trim($env_value);
            }
        }
        if ($encoded_key === '' && isset($_ENV['CMN_BANK_ENC_KEY'])) {
            $encoded_key = trim((string) $_ENV['CMN_BANK_ENC_KEY']);
        }
        if ($encoded_key === '') {
            return new WP_Error('cmn_bank_enc_key_missing', 'Secure bank encryption key is not configured.');
        }
        $decoded_key = base64_decode($encoded_key, true);
        if (!is_string($decoded_key) || strlen($decoded_key) !== 32) {
            return new WP_Error('cmn_bank_enc_key_invalid', 'Secure bank encryption key is invalid.');
        }
        return $decoded_key;
    }
}

if (!function_exists('cmn_get_bank_encryption_fallback_key')) {
    function cmn_get_bank_encryption_fallback_key() {
        $seed_parts = [];
        if (function_exists('wp_salt')) {
            $salt = (string) wp_salt('auth');
            if ($salt !== '') {
                $seed_parts[] = $salt;
            }
        }
        foreach (['SECURE_AUTH_KEY', 'AUTH_KEY', 'LOGGED_IN_KEY', 'NONCE_KEY'] as $constant_name) {
            if (defined($constant_name)) {
                $value = trim((string) constant($constant_name));
                if ($value !== '') {
                    $seed_parts[] = $value;
                }
            }
        }
        $home_url = function_exists('home_url') ? (string) home_url('/') : '';
        if ($home_url !== '') {
            $seed_parts[] = $home_url;
        }
        if (!$seed_parts) {
            return new WP_Error('cmn_bank_enc_fallback_unavailable', 'Secure bank encryption key seed is unavailable.');
        }
        $seed = implode('|', $seed_parts) . '|cmn_bank_enc_fallback_v1';
        $key = hash('sha256', $seed, true);
        if (!is_string($key) || strlen($key) !== 32) {
            return new WP_Error('cmn_bank_enc_fallback_invalid', 'Secure bank encryption fallback key is invalid.');
        }
        return $key;
    }
}

if (!function_exists('cmn_get_bank_encryption_keys_for_decrypt')) {
    function cmn_get_bank_encryption_keys_for_decrypt() {
        $keys = [];
        $configured = function_exists('cmn_get_bank_encryption_key_from_config')
            ? cmn_get_bank_encryption_key_from_config()
            : new WP_Error('cmn_bank_enc_config_missing', 'Secure bank encryption config helper is missing.');
        if (!is_wp_error($configured)) {
            $keys[] = $configured;
        }
        $fallback = function_exists('cmn_get_bank_encryption_fallback_key')
            ? cmn_get_bank_encryption_fallback_key()
            : new WP_Error('cmn_bank_enc_fallback_missing', 'Secure bank encryption fallback helper is missing.');
        if (!is_wp_error($fallback)) {
            $keys[] = $fallback;
        }
        if (!$keys) {
            if (is_wp_error($configured) && $configured->get_error_code() !== 'cmn_bank_enc_key_missing') {
                return $configured;
            }
            if (is_wp_error($fallback)) {
                return $fallback;
            }
            return new WP_Error('cmn_bank_enc_key_missing', 'Secure bank encryption key is not configured.');
        }
        $unique = [];
        $seen = [];
        foreach ($keys as $key) {
            $fingerprint = bin2hex($key);
            if (isset($seen[$fingerprint])) {
                continue;
            }
            $seen[$fingerprint] = true;
            $unique[] = $key;
        }
        return $unique;
    }
}

if (!function_exists('cmn_get_bank_encryption_key')) {
    function cmn_get_bank_encryption_key() {
        $configured = function_exists('cmn_get_bank_encryption_key_from_config')
            ? cmn_get_bank_encryption_key_from_config()
            : new WP_Error('cmn_bank_enc_config_missing', 'Secure bank encryption config helper is missing.');
        if (!is_wp_error($configured)) {
            return $configured;
        }
        if ($configured->get_error_code() !== 'cmn_bank_enc_key_missing') {
            return $configured;
        }
        $fallback = function_exists('cmn_get_bank_encryption_fallback_key')
            ? cmn_get_bank_encryption_fallback_key()
            : new WP_Error('cmn_bank_enc_fallback_missing', 'Secure bank encryption fallback helper is missing.');
        if (is_wp_error($fallback)) {
            return $configured;
        }
        return $fallback;
    }
}

if (!function_exists('cmn_encrypt_secret')) {
    function cmn_encrypt_secret($plaintext) {
        $plaintext = (string) $plaintext;
        if ($plaintext === '') {
            return new WP_Error('cmn_bank_encrypt_empty', 'Cannot encrypt an empty value.');
        }
        if (!function_exists('openssl_encrypt')) {
            return new WP_Error('cmn_bank_encrypt_unavailable', 'OpenSSL encryption is unavailable.');
        }

        $key = cmn_get_bank_encryption_key();
        if (is_wp_error($key)) {
            return $key;
        }

        try {
            $nonce = random_bytes(12);
        } catch (Throwable $e) {
            return new WP_Error('cmn_bank_encrypt_nonce_failed', 'Unable to generate encryption nonce.');
        }

        $tag = '';
        $ciphertext_raw = openssl_encrypt($plaintext, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $nonce, $tag, '', 16);
        if (!is_string($ciphertext_raw) || $ciphertext_raw === '' || !is_string($tag) || strlen($tag) !== 16) {
            return new WP_Error('cmn_bank_encrypt_failed', 'Unable to encrypt secure value.');
        }

        $payload = chr(1) . $nonce . $tag . $ciphertext_raw;
        return base64_encode($payload);
    }
}

if (!function_exists('cmn_decrypt_secret')) {
    function cmn_decrypt_secret($ciphertext) {
        $ciphertext = (string) $ciphertext;
        if ($ciphertext === '') {
            return new WP_Error('cmn_bank_decrypt_empty', 'Encrypted value is empty.');
        }
        if (!function_exists('openssl_decrypt')) {
            return new WP_Error('cmn_bank_decrypt_unavailable', 'OpenSSL decryption is unavailable.');
        }

        $keys = function_exists('cmn_get_bank_encryption_keys_for_decrypt')
            ? cmn_get_bank_encryption_keys_for_decrypt()
            : new WP_Error('cmn_bank_decrypt_key_helper_missing', 'Decryption key helper unavailable.');
        if (is_wp_error($keys)) {
            return $keys;
        }

        $payload = base64_decode($ciphertext, true);
        if (!is_string($payload) || strlen($payload) < 30) {
            return new WP_Error('cmn_bank_decrypt_payload_invalid', 'Encrypted payload is invalid.');
        }

        $version = ord($payload[0]);
        if ($version !== 1) {
            return new WP_Error('cmn_bank_decrypt_version_invalid', 'Encrypted payload version is unsupported.');
        }

        $nonce = substr($payload, 1, 12);
        $tag = substr($payload, 13, 16);
        $ciphertext_raw = substr($payload, 29);
        if (!is_string($nonce) || strlen($nonce) !== 12 || !is_string($tag) || strlen($tag) !== 16 || !is_string($ciphertext_raw) || $ciphertext_raw === '') {
            return new WP_Error('cmn_bank_decrypt_payload_invalid', 'Encrypted payload is malformed.');
        }

        foreach ((array) $keys as $key) {
            $plaintext = openssl_decrypt($ciphertext_raw, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $nonce, $tag, '');
            if (is_string($plaintext)) {
                return $plaintext;
            }
        }
        return new WP_Error('cmn_bank_decrypt_failed', 'Unable to decrypt secure value.');
    }
}

if (!function_exists('cmn_migrate_bank_details_plain_to_encrypted')) {
    function cmn_migrate_bank_details_plain_to_encrypted() {
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if (!$plugin instanceof CMN_One_Plugin || !is_callable([$plugin, 'migrate_bank_details_plain_to_encrypted'])) {
            return new WP_Error('cmn_bank_migration_service_unavailable', 'Bank details migration service unavailable.');
        }
        return $plugin->migrate_bank_details_plain_to_encrypted();
    }
}

if (!function_exists('cmn_resolve_permission_denied_entity_context')) {
    function cmn_resolve_permission_denied_entity_context(array $context, $fallback_user_id = 0) {
        $entity_type = '';
        $entity_id = 0;

        if (!empty($context['entity_type'])) {
            $entity_type = sanitize_key((string) $context['entity_type']);
        }
        if (!empty($context['entity_id'])) {
            $entity_id = (int) $context['entity_id'];
        }

        $field_to_type = [
            'booking_id' => 'booking',
            'candidate_id' => 'candidate',
            'school_id' => 'school',
            'ticket_id' => 'ticket',
            'request_id' => 'request',
            'invoice_id' => 'invoice',
            'payout_run_id' => 'payout_run',
        ];
        foreach ($field_to_type as $field => $type) {
            if ($entity_id > 0) {
                break;
            }
            if (!empty($context[$field]) && is_numeric($context[$field])) {
                $entity_id = (int) $context[$field];
                if ($entity_type === '') {
                    $entity_type = $type;
                }
            }
        }

        if ($entity_type === '') {
            $entity_type = 'user';
        }
        if ($entity_id < 1) {
            $entity_id = (int) $fallback_user_id;
        }

        return [
            'entity_type' => $entity_type,
            'entity_id' => max(0, $entity_id),
        ];
    }
}

if (!function_exists('cmn_sanitize_permission_context_for_audit')) {
    function cmn_sanitize_permission_context_for_audit($value, $depth = 0) {
        $depth = (int) $depth;
        if ($depth > 3) {
            return '[max-depth]';
        }

        if (is_null($value) || is_scalar($value)) {
            return $value;
        }
        if (is_array($value)) {
            $out = [];
            $count = 0;
            foreach ($value as $key => $item) {
                $count++;
                if ($count > 50) {
                    $out['...'] = '[truncated]';
                    break;
                }
                $safe_key = is_int($key) ? $key : sanitize_key((string) $key);
                $out[$safe_key] = cmn_sanitize_permission_context_for_audit($item, $depth + 1);
            }
            return $out;
        }
        if (is_object($value)) {
            return '[object:' . sanitize_text_field((string) get_class($value)) . ']';
        }
        return '[' . sanitize_text_field((string) gettype($value)) . ']';
    }
}

if (!function_exists('cmn_log_permission_denied_event')) {
    function cmn_log_permission_denied_event($user_id, $ability, array $context, $resolved_role) {
        $user_id = (int) $user_id;
        if ($user_id < 1) {
            return;
        }

        $entity = cmn_resolve_permission_denied_entity_context($context, $user_id);
        $safe_context = cmn_sanitize_permission_context_for_audit($context);
        $metadata = [
            'ability' => (string) $ability,
            'resolved_role' => (string) $resolved_role,
            'request_method' => isset($_SERVER['REQUEST_METHOD']) ? sanitize_text_field((string) $_SERVER['REQUEST_METHOD']) : '',
            'request_uri' => isset($_SERVER['REQUEST_URI']) ? sanitize_text_field((string) $_SERVER['REQUEST_URI']) : '',
            'context' => $safe_context,
        ];

        cmn_audit_log_event([
            'module' => 'security',
            'entity_type' => (string) ($entity['entity_type'] ?? 'user'),
            'entity_id' => (int) ($entity['entity_id'] ?? $user_id),
            'event_type' => 'permission_denied',
            'event_ref' => (string) $ability,
            'actor_user_id' => $user_id,
            'actor_role' => (string) $resolved_role,
            'metadata' => $metadata,
        ]);
    }
}

if (!function_exists('cmn_require_ability')) {
    function cmn_require_ability($ability, $context = []) {
        $context = is_array($context) ? $context : [];
        $ability = trim((string) $ability);
        if ($ability === '') {
            return new WP_Error('cmn_invalid_ability', 'Not authorised', ['status' => 403]);
        }

        if (!is_user_logged_in() && cmn_is_system_context($context) && cmn_can(0, $ability, $context)) {
            return true;
        }

        $login_check = cmn_require_login();
        if (is_wp_error($login_check)) {
            return $login_check;
        }

        $user_id = (int) get_current_user_id();
        if (cmn_can($user_id, $ability, $context)) {
            return true;
        }

        $resolved_role = cmn_role_from_user($user_id);
        cmn_log_permission_denied_event($user_id, $ability, $context, $resolved_role);

        if ($resolved_role === 'admin' || $resolved_role === 'staff') {
            error_log(sprintf(
                'CMN permission denied: user_id=%d role=%s ability=%s context=%s',
                $user_id,
                $resolved_role,
                $ability,
                wp_json_encode($context)
            ));
        }

        // Portal-safe message for candidate/school users and generic fallback.
        return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
    }
}

if (!function_exists('cmn_json_error')) {
    function cmn_json_error($wp_error) {
        if (!is_wp_error($wp_error)) {
            $wp_error = new WP_Error('cmn_unknown_error', 'Request failed.', ['status' => 400]);
        }

        $code = (string) $wp_error->get_error_code();
        $message = (string) $wp_error->get_error_message();
        $data = $wp_error->get_error_data();
        $status = 400;
        if (is_array($data) && isset($data['status'])) {
            $status = (int) $data['status'];
        } elseif ($code === 'cmn_auth_required') {
            $status = 401;
        } elseif ($code === 'cmn_not_authorized' || $code === 'cmn_invalid_nonce') {
            $status = 403;
        }
        if ($status < 100 || $status > 599) {
            $status = 400;
        }

        $public_data = [];
        if (is_array($data) && isset($data['status'])) {
            $public_data['status'] = (int) $data['status'];
        }

        wp_send_json_error([
            'ok' => false,
            'error' => [
                'code' => $code !== '' ? $code : 'cmn_error',
                'message' => $message !== '' ? $message : 'Request failed.',
                'data' => $public_data,
            ],
        ], $status);
    }
}

if (!function_exists('cmn_audit_allowed_modules')) {
    function cmn_audit_allowed_modules() {
        // Allowed modules for the immutable ledger.
        return ['rewards', 'school_partner', 'finance', 'payroll', 'support', 'security', 'candidate', 'feedback'];
    }
}

if (!function_exists('cmn_audit_resolve_actor_role_for_user')) {
    function cmn_audit_resolve_actor_role_for_user($actor_user_id) {
        $actor_user_id = (int) $actor_user_id;
        if ($actor_user_id < 1) {
            return 'system';
        }

        $user = get_user_by('id', $actor_user_id);
        if (!$user instanceof WP_User) {
            return new WP_Error('cmn_audit_invalid_actor', 'Actor user does not exist.');
        }

        $roles = array_map('strtolower', (array) $user->roles);
        if (user_can($user, 'manage_options') || in_array('administrator', $roles, true) || in_array('cmn_admin', $roles, true)) {
            return 'admin';
        }
        if (in_array('cmn_staff', $roles, true) || in_array('cmn_account_manager', $roles, true) || user_can($user, 'edit_posts')) {
            return 'staff';
        }
        if (in_array('cmn_school_manager', $roles, true) || in_array('cmn_school_staff', $roles, true)) {
            return 'school';
        }
        if (in_array('cmn_candidate', $roles, true) || in_array('cmn_candidate_pending', $roles, true)) {
            return 'candidate';
        }
        return 'system';
    }
}

/*
 * Acceptance tests:
 * 1) Logging with metadata array stores a JSON string in metadata.
 * 2) Logging invalid JSON string metadata returns WP_Error.
 * 3) Query helper returns newest events for a module/entity filter.
 *
 * Security: server-side helper only. No public route is registered here.
 */
if (!function_exists('cmn_audit_log_event')) {
    function cmn_audit_log_event(array $args) {
        global $wpdb;
        if (!$wpdb instanceof wpdb) {
            return new WP_Error('cmn_audit_db_unavailable', 'Database connection is unavailable.');
        }

        $module = sanitize_key((string) ($args['module'] ?? ''));
        $entity_type = sanitize_key((string) ($args['entity_type'] ?? ''));
        $event_type = sanitize_key((string) ($args['event_type'] ?? ''));
        $entity_id_raw = $args['entity_id'] ?? null;

        if ($module === '' || !in_array($module, cmn_audit_allowed_modules(), true)) {
            return new WP_Error('cmn_audit_invalid_module', 'Invalid module for audit event.');
        }
        if ($entity_type === '') {
            return new WP_Error('cmn_audit_invalid_entity_type', 'entity_type is required.');
        }
        if ($event_type === '') {
            return new WP_Error('cmn_audit_invalid_event_type', 'event_type is required.');
        }
        if (!is_numeric($entity_id_raw) || (int) $entity_id_raw < 1) {
            return new WP_Error('cmn_audit_invalid_entity_id', 'entity_id must be a positive integer.');
        }
        $entity_id = (int) $entity_id_raw;

        $event_ref = sanitize_text_field((string) ($args['event_ref'] ?? ''));
        if ($event_ref !== '') {
            $event_ref = function_exists('mb_substr') ? mb_substr($event_ref, 0, 128) : substr($event_ref, 0, 128);
        } else {
            $event_ref = null;
        }

        $actor_user_id = isset($args['actor_user_id']) ? (int) $args['actor_user_id'] : 0;
        $actor_user_id = $actor_user_id > 0 ? $actor_user_id : null;
        if ($actor_user_id !== null) {
            $actor_role = cmn_audit_resolve_actor_role_for_user($actor_user_id);
            if (is_wp_error($actor_role)) {
                return $actor_role;
            }
        } else {
            $actor_role = 'system';
        }

        $explicit_ip = array_key_exists('ip_address', $args);
        $ip_input = trim((string) ($args['ip_address'] ?? ''));
        if (!$explicit_ip && $ip_input === '') {
            if (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
                $parts = explode(',', (string) $_SERVER['HTTP_X_FORWARDED_FOR']);
                $ip_input = trim((string) ($parts[0] ?? ''));
            } elseif (!empty($_SERVER['REMOTE_ADDR'])) {
                $ip_input = trim((string) $_SERVER['REMOTE_ADDR']);
            }
        }
        $packed_ip = null;
        if ($ip_input !== '') {
            $packed = @inet_pton($ip_input);
            if ($packed === false) {
                if ($explicit_ip) {
                    return new WP_Error('cmn_audit_invalid_ip', 'ip_address is not a valid IPv4/IPv6 value.');
                }
            } else {
                $packed_ip = $packed;
            }
        }

        $user_agent = trim((string) ($args['user_agent'] ?? ''));
        if ($user_agent === '' && !empty($_SERVER['HTTP_USER_AGENT'])) {
            $user_agent = trim((string) $_SERVER['HTTP_USER_AGENT']);
        }
        if ($user_agent !== '') {
            $user_agent = sanitize_text_field($user_agent);
            $user_agent = function_exists('mb_substr') ? mb_substr($user_agent, 0, 255) : substr($user_agent, 0, 255);
        } else {
            $user_agent = null;
        }

        $metadata_json = null;
        if (array_key_exists('metadata', $args)) {
            $metadata = $args['metadata'];
            if (is_array($metadata) || is_object($metadata)) {
                $metadata_json = wp_json_encode($metadata);
                if (!is_string($metadata_json)) {
                    return new WP_Error('cmn_audit_invalid_metadata', 'Failed to encode metadata as JSON.');
                }
            } elseif (is_string($metadata)) {
                $metadata = trim($metadata);
                if ($metadata !== '') {
                    json_decode($metadata, true);
                    if (json_last_error() !== JSON_ERROR_NONE) {
                        return new WP_Error('cmn_audit_invalid_metadata_json', 'Metadata must be valid JSON.');
                    }
                    $metadata_json = $metadata;
                }
            } elseif ($metadata !== null) {
                return new WP_Error('cmn_audit_invalid_metadata', 'Metadata must be an array, object, JSON string, or null.');
            }
        }

        $table = $wpdb->prefix . 'cmn_audit_events';
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return new WP_Error('cmn_audit_table_missing', 'Audit events table does not exist. Run schema migrations first.');
        }

        $inserted = $wpdb->insert($table, [
            'module' => $module,
            'entity_type' => $entity_type,
            'entity_id' => $entity_id,
            'event_type' => $event_type,
            'event_ref' => $event_ref,
            'actor_user_id' => $actor_user_id,
            'actor_role' => $actor_role,
            'ip_address' => $packed_ip,
            'user_agent' => $user_agent,
            'metadata' => $metadata_json,
            'created_at' => current_time('mysql'),
        ], ['%s', '%s', '%d', '%s', '%s', '%d', '%s', '%s', '%s', '%s', '%s']);

        if ($inserted === false) {
            return new WP_Error('cmn_audit_insert_failed', 'Failed to insert audit event.', ['db_error' => $wpdb->last_error]);
        }

        return (int) $wpdb->insert_id;
    }
}

if (!function_exists('cmn_audit_query_events')) {
    function cmn_audit_query_events(array $filters, int $limit = 50, int $offset = 0) {
        global $wpdb;
        if (!$wpdb instanceof wpdb) {
            return [];
        }

        $table = $wpdb->prefix . 'cmn_audit_events';
        $table_exists = (string) $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($table_exists !== $table) {
            return [];
        }

        $where = ['1=1'];
        $params = [];

        $module = sanitize_key((string) ($filters['module'] ?? ''));
        if ($module !== '') {
            if (!in_array($module, cmn_audit_allowed_modules(), true)) {
                return new WP_Error('cmn_audit_invalid_module_filter', 'Invalid module filter.');
            }
            $where[] = 'module = %s';
            $params[] = $module;
        }

        $entity_type = sanitize_key((string) ($filters['entity_type'] ?? ''));
        if ($entity_type !== '') {
            $where[] = 'entity_type = %s';
            $params[] = $entity_type;
        }

        if (isset($filters['entity_id']) && $filters['entity_id'] !== '') {
            if (!is_numeric($filters['entity_id'])) {
                return new WP_Error('cmn_audit_invalid_entity_id_filter', 'entity_id filter must be numeric.');
            }
            $where[] = 'entity_id = %d';
            $params[] = (int) $filters['entity_id'];
        }

        $event_type = sanitize_key((string) ($filters['event_type'] ?? ''));
        if ($event_type !== '') {
            $where[] = 'event_type = %s';
            $params[] = $event_type;
        }

        $parse_date = static function ($raw_value, $is_end) {
            $raw_value = trim((string) $raw_value);
            if ($raw_value === '') {
                return '';
            }
            if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $raw_value)) {
                $raw_value .= $is_end ? ' 23:59:59' : ' 00:00:00';
            }
            try {
                $tz = function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC');
                $dt = new DateTimeImmutable($raw_value, $tz);
                return $dt->format('Y-m-d H:i:s');
            } catch (Throwable $e) {
                return new WP_Error('cmn_audit_invalid_date_filter', 'Invalid date filter value.');
            }
        };

        if (!empty($filters['date_from'])) {
            $date_from = $parse_date($filters['date_from'], false);
            if (is_wp_error($date_from)) {
                return $date_from;
            }
            $where[] = 'created_at >= %s';
            $params[] = $date_from;
        }

        if (!empty($filters['date_to'])) {
            $date_to = $parse_date($filters['date_to'], true);
            if (is_wp_error($date_to)) {
                return $date_to;
            }
            $where[] = 'created_at <= %s';
            $params[] = $date_to;
        }

        $limit = max(1, min(500, (int) $limit));
        $offset = max(0, (int) $offset);
        $params[] = $limit;
        $params[] = $offset;

        $sql = "SELECT id, module, entity_type, entity_id, event_type, event_ref, actor_user_id, actor_role, ip_address, user_agent, metadata, created_at
                FROM {$table}
                WHERE " . implode(' AND ', $where) . "
                ORDER BY created_at DESC, id DESC
                LIMIT %d OFFSET %d";

        $query = $wpdb->prepare($sql, $params);
        $rows = $wpdb->get_results($query, ARRAY_A);
        if (!is_array($rows)) {
            return [];
        }

        foreach ($rows as &$row) {
            $row['id'] = (int) ($row['id'] ?? 0);
            $row['entity_id'] = (int) ($row['entity_id'] ?? 0);
            $row['actor_user_id'] = isset($row['actor_user_id']) ? (int) $row['actor_user_id'] : null;
            if (isset($row['ip_address']) && $row['ip_address'] !== null && $row['ip_address'] !== '') {
                $decoded_ip = @inet_ntop($row['ip_address']);
                $row['ip_address'] = $decoded_ip !== false ? $decoded_ip : '';
            } else {
                $row['ip_address'] = null;
            }
        }
        unset($row);

        return $rows;
    }
}

if (!function_exists('cmn_get_academic_year_bounds')) {
    function cmn_get_academic_year_bounds(DateTime $d) {
        $year = cmn_rewards_get_academic_year_for_date($d);
        return [
            'start_year' => (int) ($year['start_year'] ?? 0),
            'end_year' => (int) ($year['end_year'] ?? 0),
            'start_date' => (string) ($year['start'] ?? ''),
            'end_date' => (string) ($year['end'] ?? ''),
            'label' => (string) ($year['label'] ?? ''),
            'is_off_season' => !empty($year['is_off_season']),
        ];
    }
}

if (!function_exists('cmn_rewards_get_academic_year_for_date')) {
    function cmn_rewards_get_academic_year_for_date(DateTimeInterface $dt) {
        $timezone = function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC');
        if ($dt instanceof DateTimeImmutable) {
            $reference = $dt->setTimezone($timezone);
        } else {
            $source_timezone = $dt->getTimezone();
            if (!$source_timezone instanceof DateTimeZone) {
                $source_timezone = $timezone;
            }
            $reference = new DateTimeImmutable($dt->format('Y-m-d H:i:s'), $source_timezone);
            $reference = $reference->setTimezone($timezone);
        }

        $year = (int) $reference->format('Y');
        $month = (int) $reference->format('n');
        $start_year = $month >= 9 ? $year : ($year - 1);
        if ($month === 8) {
            $start_year = $year - 1;
        }
        $end_year = $start_year + 1;

        return [
            'label' => sprintf('%04d/%02d', $start_year, ($end_year % 100)),
            'start' => sprintf('%04d-09-01', $start_year),
            'end' => sprintf('%04d-07-31', $end_year),
            'start_year' => $start_year,
            'end_year' => $end_year,
            'is_off_season' => ($month === 8),
            'reference_date' => $reference->format('Y-m-d'),
        ];
    }
}

if (!function_exists('cmn_rewards_get_current_academic_year')) {
    function cmn_rewards_get_current_academic_year() {
        $now = function_exists('cmn_now') ? cmn_now() : new DateTimeImmutable('now', (function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC')));
        return cmn_rewards_get_academic_year_for_date($now);
    }
}

if (!function_exists('cmn_get_academic_year_label')) {
    function cmn_get_academic_year_label($date = 'now') {
        if ($date instanceof DateTime) {
            $bounds = cmn_get_academic_year_bounds($date);
            return (string) ($bounds['label'] ?? '');
        }

        // Backward-compatible path used by existing rewards/invoicing code.
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if ($plugin instanceof CMN_One_Plugin) {
            return (string) $plugin->get_academic_year_label($date);
        }
        try {
            $tz = function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC');
            $reference = ($date === null || trim((string) $date) === '' || (string) $date === 'now')
                ? (function_exists('cmn_now') ? cmn_now() : new DateTimeImmutable('now', $tz))
                : new DateTimeImmutable((string) $date, $tz);
        } catch (Throwable $e) {
            $reference = function_exists('cmn_now') ? cmn_now() : new DateTimeImmutable('now', new DateTimeZone('UTC'));
        }
        $reference = $reference->setTimezone(function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC'));
        $year = (int) $reference->format('Y');
        $month = (int) $reference->format('n');
        $start_year = $month >= 8 ? $year : ($year - 1);
        return sprintf('%04d-%04d', $start_year, ($start_year + 1));
    }
}

if (!function_exists('cmn_rewards_ensure_year_config')) {
    function cmn_rewards_ensure_year_config(string $label) {
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if ($plugin instanceof CMN_One_Plugin && is_callable([$plugin, 'rewards_ensure_year_config'])) {
            return (array) $plugin->rewards_ensure_year_config($label);
        }

        global $wpdb;
        if (!$wpdb instanceof wpdb) {
            return [];
        }
        if (!preg_match('/^(\d{4})\/(\d{2})$/', trim($label), $matches)) {
            return [];
        }

        $start_year = (int) $matches[1];
        $normalized_label = sprintf('%04d/%02d', $start_year, (($start_year + 1) % 100));
        $table = $wpdb->prefix . 'cmn_rewards_config_years';
        $existing = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE academic_year_label = %s LIMIT 1",
            $normalized_label
        ), ARRAY_A);
        if (is_array($existing) && !empty($existing)) {
            return $existing;
        }

        $now = current_time('mysql');
        $wpdb->insert($table, [
            'academic_year_label' => $normalized_label,
            'starts_on' => sprintf('%04d-09-01', $start_year),
            'ends_on' => sprintf('%04d-07-31', ($start_year + 1)),
            'bronze_threshold' => 30,
            'silver_threshold' => 60,
            'gold_threshold' => 90,
            'elite_threshold' => 120,
            'bronze_multiplier' => 1.10,
            'silver_multiplier' => 1.20,
            'gold_multiplier' => 1.30,
            'elite_multiplier' => 1.50,
            'elite_recurring_block' => 30,
            'elite_recurring_multiplier' => 1.50,
            'created_at' => $now,
            'updated_at' => $now,
        ], ['%s', '%s', '%s', '%d', '%d', '%d', '%d', '%f', '%f', '%f', '%f', '%d', '%f', '%s', '%s']);

        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE academic_year_label = %s LIMIT 1",
            $normalized_label
        ), ARRAY_A);
        return is_array($row) ? $row : [];
    }
}

if (!function_exists('cmn_school_partner_get_config')) {
    function cmn_school_partner_get_config() {
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if ($plugin instanceof CMN_One_Plugin && is_callable([$plugin, 'school_partner_get_config'])) {
            return (array) $plugin->school_partner_get_config();
        }

        global $wpdb;
        if (!$wpdb instanceof wpdb) {
            return [];
        }
        $table = $wpdb->prefix . 'cmn_school_partner_config';
        $row = $wpdb->get_row("SELECT * FROM {$table} ORDER BY id ASC LIMIT 1", ARRAY_A);
        return is_array($row) ? $row : [];
    }
}

if (!function_exists('cmn_school_partner_compute_tier')) {
    function cmn_school_partner_compute_tier($confirmed_days, $config_row) {
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if ($plugin instanceof CMN_One_Plugin && is_callable([$plugin, 'school_partner_compute_tier'])) {
            return (string) $plugin->school_partner_compute_tier((int) $confirmed_days, is_array($config_row) ? $config_row : []);
        }

        $confirmed_days = max(0, (int) $confirmed_days);
        $config_row = is_array($config_row) ? $config_row : [];
        $bronze = max(0, (int) ($config_row['bronze_threshold'] ?? 20));
        $silver = max($bronze, (int) ($config_row['silver_threshold'] ?? 50));
        $gold = max($silver, (int) ($config_row['gold_threshold'] ?? 100));
        $elite = max($gold, (int) ($config_row['elite_threshold'] ?? 200));

        if ($confirmed_days >= $elite) {
            return 'elite';
        }
        if ($confirmed_days >= $gold) {
            return 'gold';
        }
        if ($confirmed_days >= $silver) {
            return 'silver';
        }
        if ($confirmed_days >= $bronze) {
            return 'bronze';
        }
        return 'standard';
    }
}

if (!function_exists('cmn_school_partner_apply_tier_if_needed')) {
    function cmn_school_partner_apply_tier_if_needed($school_user_id, $actor_user_id = null) {
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if (!$plugin instanceof CMN_One_Plugin || !is_callable([$plugin, 'school_partner_apply_tier_if_needed'])) {
            return new WP_Error('cmn_school_partner_service_unavailable', 'School partner service is unavailable.');
        }
        $actor_user_id = $actor_user_id === null ? null : (int) $actor_user_id;
        return $plugin->school_partner_apply_tier_if_needed((int) $school_user_id, $actor_user_id);
    }
}

if (!function_exists('cmn_school_partner_refresh_confirmed_days')) {
    function cmn_school_partner_refresh_confirmed_days($school_user_id, $actor_user_id = null) {
        $school_user_id = (int) $school_user_id;
        $actor_user_id = $actor_user_id === null ? (int) get_current_user_id() : (int) $actor_user_id;
        if ($school_user_id < 1) {
            return new WP_Error('cmn_school_partner_invalid_school_user', 'School user is required.');
        }

        $context = [
            'school_user_id' => $school_user_id,
        ];
        $ability = $actor_user_id > 0 && $actor_user_id === $school_user_id
            ? 'school_partner.mutate_self'
            : 'school_partner.mutate_any';
        if ($actor_user_id > 0 && function_exists('cmn_require_ability') && (int) get_current_user_id() === $actor_user_id) {
            $permission = cmn_require_ability($ability, $context);
            if (is_wp_error($permission)) {
                return $permission;
            }
        } elseif ($actor_user_id > 0 && function_exists('cmn_can') && !cmn_can($actor_user_id, $ability, $context)) {
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }

        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if (!$plugin instanceof CMN_One_Plugin || !is_callable([$plugin, 'school_partner_refresh_confirmed_days'])) {
            return new WP_Error('cmn_school_partner_service_unavailable', 'School partner refresh service is unavailable.');
        }

        return $plugin->school_partner_refresh_confirmed_days($school_user_id, $actor_user_id);
    }
}

if (!function_exists('cmn_school_confirm_booking_day_completed')) {
    function cmn_school_confirm_booking_day_completed($school_user_id, $booking_id, $date, $actor_user_id = null, $method = 'portal') {
        $school_user_id = (int) $school_user_id;
        $booking_id = (int) $booking_id;
        $actor_user_id = $actor_user_id === null ? (int) get_current_user_id() : (int) $actor_user_id;
        $context = [
            'school_user_id' => $school_user_id,
            'booking_id' => $booking_id,
        ];

        $ability = $actor_user_id > 0 && $actor_user_id === $school_user_id
