if (!function_exists('cmn_get_school_partner_dashboard_data')) {
    function cmn_get_school_partner_dashboard_data($school_user_id) {
        $auth_check = function_exists('cmn_require_login') ? cmn_require_login() : (is_user_logged_in() ? true : new WP_Error('cmn_auth_required', 'Not authorised', ['status' => 401]));
        if (is_wp_error($auth_check)) {
            return $auth_check;
        }

        $current_user_id = (int) get_current_user_id();
        $school_user_id = (int) $school_user_id;
        if ($school_user_id < 1) {
            $school_user_id = $current_user_id;
        }

        $resolved_role = function_exists('cmn_role_from_user') ? cmn_role_from_user($current_user_id) : 'guest';
        if ($resolved_role !== 'school' || $current_user_id < 1 || $school_user_id !== $current_user_id) {
            if (function_exists('cmn_log_permission_denied_event')) {
                cmn_log_permission_denied_event($current_user_id, 'school_partner_dashboard.view', [
                    'school_user_id' => $school_user_id,
                    'entity_type' => 'school',
                    'entity_id' => $school_user_id,
                ], $resolved_role);
            }
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }

        if (function_exists('cmn_require_ability')) {
            $permission = cmn_require_ability('school_partner.view_self', [
                'school_user_id' => $school_user_id,
                'entity_type' => 'school',
                'entity_id' => $school_user_id,
            ]);
            if (is_wp_error($permission)) {
                return $permission;
            }
        }

        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if (!$plugin instanceof CMN_One_Plugin || !is_callable([$plugin, 'get_school_partner_dashboard_data'])) {
            return new WP_Error('cmn_school_partner_service_unavailable', 'Partner savings service is unavailable.');
        }

        return $plugin->get_school_partner_dashboard_data($school_user_id);
    }
}

