if (!function_exists('cmn_rewards_compute_tier')) {
    function cmn_rewards_compute_tier($shifts_completed, $config_row) {
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if ($plugin instanceof CMN_One_Plugin && is_callable([$plugin, 'rewards_compute_tier'])) {
            return (string) $plugin->rewards_compute_tier((int) $shifts_completed, is_array($config_row) ? $config_row : []);
        }

        $thresholds = [
            'standard' => 0,
            'bronze' => max(0, (int) ((is_array($config_row) ? ($config_row['bronze_threshold'] ?? 30) : 30))),
            'silver' => max(0, (int) ((is_array($config_row) ? ($config_row['silver_threshold'] ?? 60) : 60))),
            'gold' => max(0, (int) ((is_array($config_row) ? ($config_row['gold_threshold'] ?? 90) : 90))),
            'elite' => max(0, (int) ((is_array($config_row) ? ($config_row['elite_threshold'] ?? 120) : 120))),
        ];
        $thresholds['silver'] = max($thresholds['bronze'], $thresholds['silver']);
        $thresholds['gold'] = max($thresholds['silver'], $thresholds['gold']);
        $thresholds['elite'] = max($thresholds['gold'], $thresholds['elite']);
        $shift_total = max(0, (int) $shifts_completed);
        $tier = 'standard';
        foreach (['standard', 'bronze', 'silver', 'gold', 'elite'] as $candidate_tier) {
            if ($shift_total >= (int) ($thresholds[$candidate_tier] ?? 0)) {
                $tier = $candidate_tier;
            }
        }
        return $tier;
    }
}

