if (!function_exists('cmn_rewards_block_multiplier')) {
    function cmn_rewards_block_multiplier($block_index, $elite_block_index = 4) {
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if ($plugin instanceof CMN_One_Plugin && is_callable([$plugin, 'rewards_block_multiplier'])) {
            return (float) $plugin->rewards_block_multiplier((int) $block_index, (int) $elite_block_index);
        }
        $block_index = max(0, (int) $block_index);
        $elite_block_index = max(1, (int) $elite_block_index);
        if ($block_index <= 0) {
            return 1.00;
        }
        if ($block_index <= 1) {
            return 1.10;
        }
        if ($block_index === 2) {
            return 1.20;
        }
        if ($block_index === 3) {
            return 1.30;
        }
        if ($block_index >= $elite_block_index) {
            return 1.50;
        }
        return 1.50;
    }
}

