if (!function_exists('cmn_referrals_record_signup')) {
    function cmn_referrals_record_signup($referred_user_id, $referral_code) {
        $referred_user_id = (int) $referred_user_id;
        $referral_code = (string) $referral_code;
        if ($referred_user_id < 1) {
            return new WP_Error('cmn_referrals_invalid_referred_user', 'Referred candidate user is required.');
        }

        $current_user_id = (int) get_current_user_id();
        if ($current_user_id > 0) {
            if ($current_user_id === $referred_user_id) {
                if (function_exists('cmn_require_ability')) {
                    $permission = cmn_require_ability('rewards.view_self', ['candidate_user_id' => $referred_user_id]);
                    if (is_wp_error($permission)) {
                        return $permission;
                    }
                }
            } else {
                if (function_exists('cmn_require_ability')) {
                    $permission = cmn_require_ability('rewards.mutate_any', ['candidate_user_id' => $referred_user_id]);
                    if (is_wp_error($permission)) {
                        return $permission;
                    }
                } elseif (function_exists('cmn_can') && !cmn_can($current_user_id, 'rewards.mutate_any', ['candidate_user_id' => $referred_user_id])) {
                    return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
                }
            }
        }

        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if (!$plugin instanceof CMN_One_Plugin || !is_callable([$plugin, 'referrals_record_signup'])) {
            return new WP_Error('cmn_referrals_service_unavailable', 'Referral service is unavailable.');
        }
        return $plugin->referrals_record_signup($referred_user_id, $referral_code);
    }
}

