if (!function_exists('cmn_conduct_open_appeal')) {
    function cmn_conduct_open_appeal($candidate_user_id, $booking_id, $message) {
        $candidate_user_id = (int) $candidate_user_id;
        $booking_id = (int) $booking_id;
        $current_user_id = (int) get_current_user_id();

        if (function_exists('cmn_require_ability')) {
            $permission = cmn_require_ability('rewards.view_self', [
                'candidate_user_id' => $candidate_user_id,
                'booking_id' => $booking_id,
            ]);
            if (is_wp_error($permission)) {
                return $permission;
            }
        } elseif (!is_user_logged_in()) {
            return new WP_Error('cmn_auth_required', 'Not authorised', ['status' => 401]);
        }

        if ($current_user_id < 1 || $current_user_id !== $candidate_user_id) {
            if (function_exists('cmn_log_permission_denied_event')) {
                $resolved_role = function_exists('cmn_role_from_user') ? (string) cmn_role_from_user($current_user_id) : 'candidate';
                cmn_log_permission_denied_event($current_user_id, 'rewards.view_self', [
                    'candidate_user_id' => $candidate_user_id,
                    'booking_id' => $booking_id,
                ], $resolved_role);
            }
            return new WP_Error('cmn_not_authorized', 'Not authorised', ['status' => 403]);
        }

        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if (!$plugin instanceof CMN_One_Plugin || !is_callable([$plugin, 'conduct_open_appeal'])) {
            return new WP_Error('cmn_conduct_service_unavailable', 'Candidate conduct service is unavailable.');
        }
        return $plugin->conduct_open_appeal($candidate_user_id, $booking_id, (string) $message);
    }
}

