if (!function_exists('cmn_wp_timezone')) {
    function cmn_wp_timezone() {
        return function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC');
    }
}

if (!function_exists('cmn_now')) {
    function cmn_now() {
        $tz = cmn_wp_timezone();
        $real_now = new DateTimeImmutable('now', $tz);
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if (!$plugin instanceof CMN_One_Plugin || !is_callable([$plugin, 'get_training_now_override'])) {
            return $real_now;
        }
        try {
            $override = $plugin->get_training_now_override((int) get_current_user_id());
            if ($override instanceof DateTimeImmutable) {
                return $override->setTimezone($tz);
            }
            if ($override instanceof DateTimeInterface) {
                return DateTimeImmutable::createFromInterface($override)->setTimezone($tz);
            }
        } catch (Throwable $e) {
            return $real_now;
        }
        return $real_now;
    }
}

if (!function_exists('cmn_today_ymd')) {
    function cmn_today_ymd() {
        return cmn_now()->format('Y-m-d');
    }
}

if (!function_exists('cmn_payroll_resolve_reference_datetime')) {
    function cmn_payroll_resolve_reference_datetime($date = 'now') {
        $tz = function_exists('cmn_wp_timezone') ? cmn_wp_timezone() : (function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC'));
        try {
            if ($date instanceof DateTimeInterface) {
                $reference = DateTimeImmutable::createFromInterface($date)->setTimezone($tz);
            } elseif ($date === null || trim((string) $date) === '' || (string) $date === 'now') {
                $reference = function_exists('cmn_now') ? cmn_now() : new DateTimeImmutable('now', $tz);
            } elseif (is_numeric($date) && (!is_string($date) || preg_match('/^\d{9,}$/', (string) $date))) {
                $reference = (new DateTimeImmutable('@' . (int) $date))->setTimezone($tz);
            } else {
                $reference = new DateTimeImmutable((string) $date, $tz);
            }
        } catch (Throwable $e) {
            $reference = function_exists('cmn_now') ? cmn_now() : new DateTimeImmutable('now', $tz);
        }

        return $reference->setTimezone($tz);
    }
}

if (!function_exists('cmn_payroll_get_period_for_date')) {
    /*
     * Prompt 27 acceptance tests:
     * 1) Monday input resolves to previous Friday start and upcoming Thursday end.
     * 2) Friday input resolves to same-day period_start.
     * 3) pay_date always resolves to Friday.
     */
    function cmn_payroll_get_period_for_date($date = 'now') {
        $tz = function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC');
        $reference = function_exists('cmn_payroll_resolve_reference_datetime')
            ? cmn_payroll_resolve_reference_datetime($date)
            : new DateTimeImmutable('now', $tz);
        $reference = $reference->setTimezone($tz);

        $iso_day = (int) $reference->format('N');
        $delta = $iso_day - 5; // Friday start.
        if ($delta < 0) {
            $delta += 7;
        }

        $period_start = $reference->modify('-' . $delta . ' days')->setTime(0, 0, 0);
        $period_end = $period_start->modify('+6 days');
        $pay_date = $period_end->modify('+1 day');

        $start_label = function_exists('wp_date')
            ? wp_date('d M', $period_start->getTimestamp(), $tz)
            : date_i18n('d M', $period_start->getTimestamp(), false);
        $end_label = function_exists('wp_date')
            ? wp_date('d M', $period_end->getTimestamp(), $tz)
            : date_i18n('d M', $period_end->getTimestamp(), false);

        return [
            'period_start' => $period_start->format('Y-m-d'),
            'period_end' => $period_end->format('Y-m-d'),
            'pay_date' => $pay_date->format('Y-m-d'),
            'label' => 'Fri ' . $start_label . ' – Thu ' . $end_label,
        ];
    }
}

if (!function_exists('cmn_payroll_get_current_period')) {
    function cmn_payroll_get_current_period() {
        $reference = function_exists('cmn_now') ? cmn_now() : 'now';
        return (array) cmn_payroll_get_period_for_date($reference);
    }
}

if (!function_exists('cmn_payroll_get_previous_period')) {
    function cmn_payroll_get_previous_period() {
        $current = (array) cmn_payroll_get_current_period();
        $period_start = sanitize_text_field((string) ($current['period_start'] ?? ''));
        if ($period_start === '') {
            return (array) cmn_payroll_get_period_for_date('-7 days');
        }

        $reference = function_exists('cmn_payroll_resolve_reference_datetime')
            ? cmn_payroll_resolve_reference_datetime($period_start)
            : new DateTimeImmutable($period_start, function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC'));
        return (array) cmn_payroll_get_period_for_date($reference->modify('-1 day'));
    }
}

if (!function_exists('cmn_payroll_period_id')) {
    /*
     * Prompt 27 acceptance tests:
     * 1) Period ID remains stable for identical start/end inputs.
     * 2) ID format is "YYYY-MM-DD__YYYY-MM-DD".
     */
    function cmn_payroll_period_id($period_start, $period_end) {
        $period_start = sanitize_text_field((string) $period_start);
        $period_end = sanitize_text_field((string) $period_end);
        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $period_start) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $period_end)) {
            return '';
        }
        return $period_start . '__' . $period_end;
    }
}

