if (!function_exists('cmn_candidate_rewards_resolve_tier')) {
    function cmn_candidate_rewards_resolve_tier($academic_year_shift_total) {
        $plugin = $GLOBALS['cmn_one_plugin'] ?? null;
        if ($plugin instanceof CMN_One_Plugin && is_callable([$plugin, 'cmn_candidate_rewards_resolve_tier'])) {
            try {
                return (array) $plugin->cmn_candidate_rewards_resolve_tier($academic_year_shift_total);
            } catch (Throwable $e) {
                // Fall through to static fallback map if instance resolution fails.
            }
        }

        $shift_total = max(0, (int) $academic_year_shift_total);
        $thresholds = [
            'standard' => 0,
            'bronze' => 30,
            'silver' => 60,
            'gold' => 90,
            'elite' => 120,
        ];
        $multipliers = [
            'standard' => 1.00,
            'bronze' => 1.10,
            'silver' => 1.20,
            'gold' => 1.30,
            'elite' => 1.50,
        ];
        $resolved_tier = 'standard';
        foreach (['standard', 'bronze', 'silver', 'gold', 'elite'] as $tier) {
            if ($shift_total >= (int) ($thresholds[$tier] ?? 0)) {
                $resolved_tier = $tier;
            }
        }
        return [
            'tier' => $resolved_tier,
            'multiplier' => round((float) ($multipliers[$resolved_tier] ?? 1.00), 2),
            'threshold' => (int) ($thresholds[$resolved_tier] ?? 0),
            'academic_year_shift_total' => $shift_total,
        ];
    }
}

